@dataclasses.dataclass(frozen=True)
class _RegularFileIdentity:
    """One regular file generation bound to its exact bytes."""

    device: int
    inode: int
    size: int
    sha256: str


@dataclasses.dataclass(frozen=True)
class _HandoffArtifact:
    """One generation-bound handoff stored outside its checkout."""

    path: Path
    machine: str
    slot: str
    generation: int
    contents: bytes
    sha256: str
    recorded_at: str
    source: str
    source_path: Path | None
    source_identity: _RegularFileIdentity | None
    provenance_complete: bool
    storage_identity: _RegularFileIdentity


@dataclasses.dataclass(frozen=True)
class _HandoffRead:
    """Latest read evidence, including whether its source was authenticated."""

    sha256: str
    retirement_enqueued: bool
    sequence: int
    recorded_at: str
    source: str | None
    source_path: Path | None
    source_identity: _RegularFileIdentity | None

    @property
    def provenance_complete(self) -> bool:
        return (
            self.source is not None
            and self.source_path is not None
            and self.source_identity is not None
        )


@dataclasses.dataclass(frozen=True)
class _OwnerConsent:
    """A live owner's release of its slot, established from its own handoff.

    Every field is durable evidence the coordinator can cite: the exact
    generation-bound sidecar, the owner-authenticated publication intent that
    names the writer, and the coordinator read that acknowledged those bytes.
    """

    handoff_path: Path
    sha256: str
    intent_sequence: int
    read_sequence: int
    writer: ProcessIdentity


@dataclasses.dataclass(frozen=True)
class _OwnerRelease:
    """One ``owner-released`` event: a live owner gave its slot generation back.

    The event binds the release to everything the owner could see when it gave
    the slot back: the exact owner process generation, the heartbeat stamp it
    stopped renewing, and the generation-bound handoff sidecar it left for the
    coordinator. A later change to any of them voids the release.
    """

    sequence: int
    recorded_at: str
    slot: str
    generation: int
    agent: str
    owner: ProcessIdentity
    heartbeat_at: str
    handoff_path: Path
    sha256: str
    intent_sequence: int


@dataclasses.dataclass(frozen=True)
class _RetirementCandidate:
    """One exact handoff read whose current slot awaits safe retirement."""

    machine: str
    slot: str
    generation: int
    sha256: str
    event_sequence: int
    enqueued_at: str
    last_attempt_sequence: int | None
    artifact_path: str | None
    artifact_source: str | None
    blocked_reason: str | None
    # Present only for a generation its owner released; omitted from to_obj()
    # otherwise so that queue output for never-released slots is unchanged.
    owner_release: Mapping[str, object] | None = None

    def to_obj(self) -> dict[str, object]:
        value = dataclasses.asdict(self)
        if value["owner_release"] is None:
            del value["owner_release"]
        return value


@dataclasses.dataclass(frozen=True)
class _ValidationRemovalArtifact:
    """One required artifact named by a validation-removal proof."""

    role: str
    path: str
    identity: _RegularFileIdentity


@dataclasses.dataclass(frozen=True)
class _ValidationRemovalProof:
    """Immutable snapshot rechecked at a validation checkout's deletion boundary."""

    manifest_path: str
    manifest_identity: _RegularFileIdentity
    slot: str
    generation: int
    checkout: str
    artifacts: tuple[_ValidationRemovalArtifact, ...]


def _utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds")


def _short_hostname() -> str:
    name = socket.gethostname().split(".", 1)[0]
    _validate_name(name, "machine")
    return name


def _validate_name(value: str, label: str) -> str:
    if not NAME_RE.fullmatch(value):
        raise Refusal(
            f"invalid {label} {value!r}; use 1-64 letters, digits, '.', '_', or '-'"
        )
    return value


def _validate_remote(value: str) -> str:
    if (
        not REMOTE_RE.fullmatch(value)
        or value.startswith("-")
        or value.endswith("/")
        or ".." in value
    ):
        raise Refusal(f"invalid remote name {value!r}")
    return value


def _require_coordinator_authorized(args: argparse.Namespace, action: str) -> None:
    if getattr(args, "coordinator_authorized", False):
        return
    if action == "worktree creation":
        raise Refusal(
            "worktree creation requires a coordinator assignment. state: REFUSED -- "
            "no worktree or lifecycle record was changed. remedy: ask the coordinator "
            "to assign the slot; an assigned agent may rerun with "
            "--coordinator-authorized and its own --owner-pid"
        )
    raise Refusal(
        f"{action} is coordinator-owned. state: REFUSED -- no worktree or lifecycle "
        "record was changed. remedy: ask the coordinator to perform the operation; a "
        "coordinator-delegated wrapper may rerun it with --coordinator-authorized"
    )


def _require_slot_type(args: argparse.Namespace, action: str) -> str:
    value = getattr(args, "slot_type", None)
    if isinstance(value, str) and value in SLOT_TYPES:
        return value
    raise Refusal(
        f"{action} must record whether this is an agent or validate slot. state: REFUSED "
        "-- no worktree or lifecycle record was changed. remedy: rerun with "
        "--slot-type agent for authored work, or --slot-type validate for a disposable "
        "validation checkout whose evidence lives outside the slot"
    )


def _validate_ref(value: str, label: str) -> str:
    if not value or value.startswith("-") or any(ch.isspace() for ch in value):
        raise Refusal(f"invalid {label} {value!r}")
    if ".." in value or value.endswith("/") or value.endswith("."):
        raise Refusal(f"invalid {label} {value!r}")
    return value


def _validate_full_ref(value: str, label: str) -> str:
    _validate_ref(value, label)
    forbidden = set(" ~^:?*[\\")
    parts = value.split("/")
    if (
        not value.startswith("refs/")
        or len(parts) < 3
        or any(not part or part.startswith(".") or part.endswith(".lock") for part in parts)
        or "@{" in value
        or any(ord(character) < 32 or ord(character) == 127 for character in value)
        or any(character in forbidden for character in value)
    ):
        raise Refusal(f"invalid full {label} {value!r}")
    return value


def _validate_git_ref_name(value: str, label: str) -> str:
    """Accept a full ref name exactly when Git's ref-name rules accept it.

    These are the rules of git check-ref-format for a name under refs/, so
    a two-component name such as refs/stash is accepted. Git places no rule
    on bytes at or above 0x80, so names need not be UTF-8; such a name is
    carried as os.fsdecode gives it (undecodable bytes become lone
    surrogates), which os.fsencode, and therefore every Git command line,
    turns back into the same bytes. A string that does not round-trip that
    way names no ref Git could have reported.
    """

    try:
        canonical = os.fsdecode(os.fsencode(value)) == value
    except UnicodeError:
        canonical = False
    parts = value.split("/")
    if (
        not canonical
        or not value.startswith("refs/")
        or len(parts) < 2
        or any(not part or part.startswith(".") or part.endswith(".lock") for part in parts)
        or ".." in value
        or "@{" in value
        or value.endswith(".")
        or any(ord(character) < 0x20 or ord(character) == 0x7F for character in value)
        or any(character in " ~^:?*[\\" for character in value)
    ):
        raise Refusal(f"invalid full {label} {_display_ref(value)!r}")
    return value


def _display_ref(value: str) -> str:
    """Show a ref name with bytes that are not printable UTF-8 escaped."""

    try:
        raw = os.fsencode(value)
    except UnicodeError:
        return ascii(value)[1:-1]
    return "".join(
        character if character.isprintable() else repr(character)[1:-1]
        for character in raw.decode("utf-8", errors="backslashreplace")
    )


def _validate_layout(value: str) -> str:
    if value not in {"nested", "flat"}:
        raise Refusal(f"invalid layout {value!r}; expected 'nested' or 'flat'")
    return value


def _control_directory_for(worktrees: Path, layout: str) -> Path:
    if worktrees.name == "slots":
        return worktrees.parent
    return worktrees if layout == "nested" else worktrees.parent


def _validate_cache_glob(value: str) -> str:
    if not value or value != value.strip() or "\x00" in value:
        raise Refusal("cache globs must be non-empty relative paths without surrounding space")
    candidate = Path(value)
    if candidate.is_absolute() or ".." in candidate.parts:
        raise Refusal(f"cache glob must stay inside each checkout: {value!r}")
    normalized = candidate.as_posix()
    if not normalized or normalized == ".":
        raise Refusal("cache glob must not name the checkout root")
    parts = Path(normalized).parts
    if any("**" in part and part != "**" for part in parts):
        raise Refusal(
            "cache glob recursive wildcards ('**') must occupy a complete path component"
        )
    if any(part == ".git" for part in parts):
        raise Refusal("cache globs must never name Git administrative data")
    if any(character in parts[0] for character in "*?["):
        raise Refusal(
            "cache glob's first path component must be literal so it cannot match source broadly"
        )
    return normalized


@functools.lru_cache(maxsize=None)
def _glob_pattern_parts(pattern: str) -> tuple[str, ...]:
    """Split one cache glob into components once rather than once per path."""

    return tuple(part for part in pattern.split("/") if part)


@functools.lru_cache(maxsize=None)
def _glob_parts_are_literal(pattern_parts: tuple[str, ...]) -> bool:
    return not any(character in part for part in pattern_parts for character in "*?[")


def _glob_parts_match(
    pattern_parts: tuple[str, ...], path_parts: tuple[str, ...]
) -> bool:
    if _glob_parts_are_literal(pattern_parts):
        return pattern_parts == path_parts

    def matches(pattern_index: int, path_index: int) -> bool:
        if pattern_index == len(pattern_parts):
            return path_index == len(path_parts)
        part = pattern_parts[pattern_index]
        if part == "**":
            return matches(pattern_index + 1, path_index) or (
                path_index < len(path_parts) and matches(pattern_index, path_index + 1)
            )
        return (
            path_index < len(path_parts)
            and fnmatch.fnmatchcase(path_parts[path_index], part)
            and matches(pattern_index + 1, path_index + 1)
        )

    return matches(0, 0)


def _glob_matches_path(pattern: str, path: str) -> bool:
    """Match one slash-delimited path without allowing '*' to cross a slash."""

    return _glob_parts_match(
        _glob_pattern_parts(pattern),
        tuple(part for part in path.split("/") if part),
    )


def _cache_glob_contains_path(pattern: str, path: str) -> bool:
    """Whether any prefix of ``path`` is the cache directory named by ``pattern``.

    This decides one path against one cache glob. ``tracked_cache_paths``
    calls it for the globs ``_CacheGlobIndex`` says can contain a path and
    for the other globs whose call reaches ``fnmatch``; it leaves out the
    rest, which return False with no effect.
    Two properties keep it cheap without changing which paths it accepts:
    only a prefix whose component count equals the pattern's own can match
    unless a ``**`` component absorbs a variable number, and a pattern whose
    components are all literal is decided by comparing the components directly
    instead of by a per-component wildcard match.
    """

    pattern_parts = _glob_pattern_parts(pattern)
    if not pattern_parts:
        return False
    path_parts = tuple(part for part in path.split("/") if part)
    if "**" in pattern_parts:
        return any(
            _glob_parts_match(pattern_parts, path_parts[:length])
            for length in range(1, len(path_parts) + 1)
        )
    if len(pattern_parts) > len(path_parts):
        return False
    return _glob_parts_match(pattern_parts, path_parts[: len(pattern_parts)])


_CacheGlobPlan = tuple[tuple[str, ...], tuple[tuple[str, tuple[str, ...]], ...]]
"""Which cache globs ``tracked_cache_paths`` tests against a path, in order.

The first element is the run of skipped globs whose tests reach ``fnmatch``
before the first glob that can contain the path; then comes each glob that can
contain the path, paired with the run of skipped globs whose tests reach
``fnmatch`` after it, up to the next such glob.
"""


def _cache_glob_is_unanchored(first: str) -> bool:
    return first == "**" or any(character in first for character in "*?[")


class _CacheGlobIndex:
    """For a set of cache globs, which globs ``tracked_cache_paths`` must test
    against a path.

    ``_cache_glob_contains_path`` matches a pattern's first component against
    the path's first component, so a pattern whose first component is literal
    can contain only paths whose first component is exactly that string; for
    any other path it returns False. A pattern whose first component is ``**``
    or has a wildcard can contain any path: validation refuses that form, but a
    caller that has not validated its globs still gets those patterns tested.
    A pattern with no components contains no path and is left out. The globs
    kept for a path keep their order in ``cache_globs``, so a caller that stops
    at the first accepting pattern makes the calls it would make trying every
    pattern in turn, minus calls that return False.

    A call that returns False is not always free of side effects. For a
    pattern with a wildcard or ``**`` the matcher compares the first components
    with ``fnmatch.fnmatchcase``, which compiles the pattern's first component
    into a bounded least-recently-used cache, through ``re``'s own caches, or
    refreshes it there. A later, deeply recursive ``**`` match needs more stack
    if it meets a string that is not in that cache, and the compile itself
    needs stack, so what the caches hold, and where a compile happens, can
    decide whether a glob raises RecursionError. Such a call happens when the
    path has a component, the pattern is not all literal, and the pattern has
    ``**`` or no more components than the path. Those calls are not left out:
    each plan lists them, in order, as runs between the globs that can contain
    the path, so the caller still makes them, from the same place. Only calls
    that cannot reach ``fnmatch`` are left out.
    """

    def __init__(self, cache_globs: tuple[str, ...]) -> None:
        self._globs = tuple(
            (pattern, parts)
            for pattern in cache_globs
            if (parts := _glob_pattern_parts(pattern))
        )
        reaching = [
            parts
            for _, parts in self._globs
            if not _cache_glob_is_unanchored(parts[0])
            and not _glob_parts_are_literal(parts)
        ]
        # Paths with more components than any skipped pattern without '**'
        # make the same skipped calls, so they share a plan.
        self._length_limit = max(
            (len(parts) for parts in reaching if "**" not in parts), default=0
        )
        # How many distinct first components the runs can pass to fnmatch.
        self.skipped_components = len({parts[0] for parts in reaching})
        self._plans: dict[tuple[str, int], _CacheGlobPlan] = {}

    def plan(self, path: str) -> _CacheGlobPlan:
        first = path.partition("/")[0] or _first_path_component(path)
        if not first:
            length = 0
        elif self._length_limit:
            length = min(
                sum(1 for part in path.split("/") if part), self._length_limit + 1
            )
        else:
            length = 1
        key = (first, length)
        plan = self._plans.get(key)
        if plan is None:
            plan = self._plans[key] = self._build(first, length)
        return plan

    def _build(self, first: str, length: int) -> _CacheGlobPlan:
        runs: list[list[str]] = [[]]
        kept: list[str] = []
        for pattern, parts in self._globs:
            head = parts[0]
            if head == first or _cache_glob_is_unanchored(head):
                kept.append(pattern)
                runs.append([])
            elif (
                length
                and ("**" in parts or len(parts) <= length)
                and not _glob_parts_are_literal(parts)
            ):
                runs[-1].append(pattern)
        return (
            tuple(runs[0]),
            tuple((pattern, tuple(run)) for pattern, run in zip(kept, runs[1:])),
        )


@functools.lru_cache(maxsize=None)
def _cache_glob_index(cache_globs: tuple[str, ...]) -> _CacheGlobIndex:
    return _CacheGlobIndex(cache_globs)


def _fnmatch_cache_size() -> int:
    """How many patterns ``fnmatch`` keeps compiled, or 0 if that is unknown."""

    cache_info = getattr(getattr(fnmatch, "_compile_pattern", None), "cache_info", None)
    size = getattr(cache_info(), "maxsize", None) if callable(cache_info) else None
    return size if isinstance(size, int) else 0


def _cache_globs_to_test(
    plan: _CacheGlobPlan, last_run: list[tuple[str, ...]]
) -> Iterator[str]:
    """Yield the globs a plan says to test against a path, in order.

    ``tracked_cache_paths`` resumes this generator only after the test of the
    pattern it yielded returned False. A run's tests all return False, and each
    passes ``fnmatch`` only its pattern's first component. ``last_run`` holds
    the run made last when no test has used ``fnmatch`` since; the caller
    shares it between paths only when ``fnmatch`` can keep every first
    component the runs can pass it. Then making that run again would find
    each component compiled and leave ``fnmatch``'s cache, and ``re``'s, as
    they were, so it is not made again, which keeps the paths no glob can
    contain cheap.
    """

    first_run, kept = plan
    if first_run and first_run != last_run[0]:
        yield from first_run
        last_run[0] = first_run
    for pattern, run in kept:
        last_run[0] = ()
        yield pattern
        if run:
            yield from run
            last_run[0] = run


def _first_path_component(path: str) -> str:
    """The first component ``_cache_glob_contains_path`` sees in ``path``.

    The matcher skips empty components, so a leading or repeated separator
    does not change which component comes first; a path with no components
    yields the empty string, which no glob is indexed under.
    """

    return next((part for part in path.split("/") if part), "")


def _validate_hook(value: str) -> str:
    if not value.strip() or "\x00" in value:
        raise Refusal("post-provision hooks must be non-empty shell commands")
    return value


def _validate_salvage_push_remote(value: str) -> str:
    if not value or value != value.strip() or "\x00" in value:
        raise Refusal("salvage push remotes must be non-empty remote URLs")
    return value


def _string_tuple(
    value: object,
    label: str,
    validator: Callable[[str], str],
    *,
    unique: bool = True,
) -> tuple[str, ...]:
    result: list[str] = []
    for index, item in enumerate(_as_list(value, label)):
        raw = _as_str(item, f"{label}[{index}]")
        validated = validator(raw)
        if unique and validated in result:
            raise StateError(f"{label} contains duplicate entry {validated!r}")
        result.append(validated)
    return tuple(result)


def _cache_glob_groups(value: object, label: str) -> tuple[tuple[str, tuple[str, ...]], ...]:
    raw = _as_mapping(value, label)
    result: list[tuple[str, tuple[str, ...]]] = []
    for name in sorted(raw):
        _validate_name(name, f"{label} repository name")
        globs = _string_tuple(raw[name], f"{label}.{name}", _validate_cache_glob)
        if not globs:
            raise StateError(f"{label}.{name} must contain at least one cache glob")
        result.append((name, globs))
    return tuple(result)


def _cache_glob_assignments(
    values: Sequence[str], label: str
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    grouped: dict[str, list[str]] = {}
    for raw in values:
        name, separator, pattern = raw.partition("=")
        if not separator:
            raise Refusal(f"{label} must use NAME=PATH-GLOB: {raw!r}")
        _validate_name(name, f"{label} repository name")
        validated = _validate_cache_glob(pattern)
        entries = grouped.setdefault(name, [])
        if validated in entries:
            raise Refusal(f"duplicate {label} for {name}: {validated!r}")
        entries.append(validated)
    return tuple((name, tuple(grouped[name])) for name in sorted(grouped))


def _cache_globs_for(config: Config, checkout_name: str | None) -> tuple[str, ...]:
    selected = list(config.cache_globs)
    if checkout_name is not None:
        selected.extend(dict(config.repo_cache_globs).get(checkout_name, ()))
    return tuple(dict.fromkeys(selected))


def _as_mapping(value: object, label: str) -> Mapping[str, object]:
    if not isinstance(value, dict):
        raise StateError(f"{label} must be a JSON object")
    for key in value:
        if not isinstance(key, str):
            raise StateError(f"{label} contains a non-string key")
    return value


def _as_list(value: object, label: str) -> list[object]:
    if not isinstance(value, list):
        raise StateError(f"{label} must be a JSON array")
    return value


def _as_str(value: object, label: str) -> str:
    if not isinstance(value, str):
        raise StateError(f"{label} must be a string")
    return value


def _as_int(value: object, label: str, *, minimum: int = 0) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or value < minimum:
        raise StateError(f"{label} must be an integer >= {minimum}")
    return value


def _exact_keys(
    value: Mapping[str, object],
    required: AbstractSet[str],
    optional: AbstractSet[str],
    label: str,
) -> None:
    keys = set(value)
    missing = sorted(required - keys)
    unknown = sorted(keys - required - optional)
    if missing or unknown:
        details: list[str] = []
        if missing:
            details.append(f"missing {', '.join(missing)}")
        if unknown:
            details.append(f"unknown {', '.join(unknown)}")
        raise StateError(f"{label} has invalid fields: {'; '.join(details)}")


def _read_json(path: Path, label: str) -> object:
    _refuse_symlink(path, label)
    try:
        with path.open("r", encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError as exc:
        raise StateError(f"missing {label}: {path}") from exc
    except json.JSONDecodeError as exc:
        raise StateError(f"{label} is malformed JSON: {exc}") from exc
    except OSError as exc:
        raise StateError(f"cannot read {label} {path}: {exc}") from exc


def _read_config_document(path: Path, label: str = "configuration") -> tuple[Mapping[str, object], str]:
    """Read a configuration file (YAML subset or JSON); return the mapping and its format.

    The one reader for every configuration consumer, so a JSON and a YAML
    configuration behave identically. Duplicate keys are refused in both.
    """

    _refuse_symlink(path, label)
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError as exc:
        raise StateError(f"missing {label}: {path}") from exc
    except (OSError, UnicodeError) as exc:
        raise StateError(f"cannot read {label} {path}: {exc}") from exc
    try:
        value, fmt = yamlconfig.load_document(text)
    except yamlconfig.YamlError as exc:
        where = f"{path}:{exc.line}" if exc.line is not None else str(path)
        raise StateError(f"{label} is malformed: {where}: {exc.reason}") from exc
    if not isinstance(value, dict):
        raise StateError(f"{label} must be a mapping: {path}")
    return {str(key): item for key, item in value.items()}, fmt


def _read_config(path: Path, label: str = "configuration") -> Mapping[str, object]:
    return _read_config_document(path, label)[0]


def _config_key_order(path: tuple[str, ...], keys: Iterable[str]) -> list[str]:
    tables: dict[tuple[str, ...], Sequence[str]] = {
        (): tuple(CONFIG_KEY_DOCS),
        ("sandbox",): sandbox.SETTING_KEYS,
        ("sandbox", "limits"): sandbox.LIMIT_KEYS,
        ("image",): tuple(slotimage.IMAGE_DOCS),
    }
    known = tables.get(path)
    names = list(keys)
    if known is None:
        return names
    return [key for key in known if key in names] + sorted(key for key in names if key not in known)


def config_comments() -> dict[tuple[str, ...], str]:
    """Every documented configuration key path and the comment written above it."""

    comments: dict[tuple[str, ...], str] = {(key,): text for key, text in CONFIG_KEY_DOCS.items()}
    comments.update({("sandbox", key): text for key, text in sandbox.SETTING_DOCS.items()})
    comments.update({("sandbox", "limits", key): text for key, text in sandbox.LIMIT_DOCS.items()})
    comments.update({("image", key): text for key, text in slotimage.IMAGE_DOCS.items()})
    return comments


def render_config(payload: Mapping[str, object], fmt: str) -> str:
    """Serialize a configuration: canonical literate YAML, or indented JSON."""

    if fmt == "json":
        return json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    if fmt != "yaml":
        raise ValueError(f"unknown configuration format {fmt!r}")
    absent = [key for key in CONFIG_KEY_DOCS if key not in payload and key in OPTIONAL_CONFIG_KEYS]
    footer = ""
    if absent:
        footer = "Optional keys not set here (absent keeps their documented meaning): " + ", ".join(absent) + "."
    return yamlconfig.emit(
        payload,
        header=CONFIG_HEADER.format(name=CONFIG_NAME),
        comments=config_comments(),
        order=_config_key_order,
        footer=footer,
    )


def _write_config(path: Path, payload: Mapping[str, object], fmt: str | None = None) -> None:
    """Replace the configuration durably, keeping the previous bytes in ``<name>.bak``.

    ``fmt`` None keeps an existing file's format (JSON stays JSON) and writes
    literate YAML for a new file.
    """

    previous: bytes | None = None
    if path.exists() or path.is_symlink():
        _refuse_symlink(path, "configuration")
        try:
            previous = path.read_bytes()
        except OSError as exc:
            raise Refusal(f"cannot read configuration {path}: {exc}") from exc
    if fmt is None:
        fmt = "yaml" if previous is None else yamlconfig.detect_format(previous.decode("utf-8", "replace"))
    text = render_config(payload, fmt)
    if previous is not None:
        if previous == text.encode("utf-8"):
            return
        backup = path.with_name(path.name + ".bak")
        _refuse_symlink(backup, "configuration backup")
        for stale in backup.parent.glob(f"{backup.name}.tmp.*"):
            with contextlib.suppress(FileNotFoundError):
                stale.unlink()
        _atomic_write_bytes(backup, previous)
    _atomic_write_bytes(path, text.encode("utf-8"))


def _read_bounded_regular_file(path: Path, label: str, limit: int) -> bytes:
    """Read one regular file without following a replacement symlink."""

    # O_NONBLOCK is load-bearing even though regular files ignore it: if an
    # attacker swaps the path to a FIFO between enumeration and open(), open
    # must return so fstat() can reject the non-regular descriptor.
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    bound = "1 MiB" if limit == 1024 * 1024 else f"{limit}-byte"
    try:
        descriptor = os.open(path, flags)
        try:
            metadata = os.fstat(descriptor)
            if not stat.S_ISREG(metadata.st_mode):
                raise Refusal(f"{label} is not a regular file: {path}")
            if metadata.st_size > limit:
                raise Refusal(f"{label} exceeds the {bound} safety bound: {path}")
            chunks: list[bytes] = []
            remaining = limit + 1
            while remaining:
                chunk = os.read(descriptor, min(remaining, 64 * 1024))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            contents = b"".join(chunks)
        finally:
            os.close(descriptor)
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    if len(contents) > limit:
        raise Refusal(f"{label} exceeds the {bound} safety bound: {path}")
    return contents


def _read_regular_file_identity(
    path: Path, label: str, limit: int
) -> tuple[bytes, _RegularFileIdentity]:
    """Read one bounded regular file and bind the bytes to its open inode."""

    bound = "1 MiB" if limit == 1024 * 1024 else f"{limit}-byte"
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise Refusal(f"{label} is not a regular file: {path}")
        if before.st_size > limit:
            raise Refusal(f"{label} exceeds the {bound} safety bound: {path}")
        chunks: list[bytes] = []
        remaining = limit + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 64 * 1024))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        contents = b"".join(chunks)
        after = os.fstat(descriptor)
        try:
            path_after = path.stat(follow_symlinks=False)
        except OSError as exc:
            raise Refusal(f"cannot recheck {label} path {path}: {exc}") from exc
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    finally:
        os.close(descriptor)
    if len(contents) > limit:
        raise Refusal(f"{label} exceeds the {bound} safety bound: {path}")
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_mode",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(getattr(before, field) != getattr(after, field) for field in stable_fields):
        raise Refusal(f"{label} changed while it was read: {path}")
    if any(
        getattr(after, field) != getattr(path_after, field)
        for field in stable_fields
    ):
        raise Refusal(f"{label} path changed while it was read: {path}")
    if len(contents) != after.st_size:
        raise Refusal(f"{label} size changed while it was read: {path}")
    return contents, _RegularFileIdentity(
        device=after.st_dev,
        inode=after.st_ino,
        size=after.st_size,
        sha256=hashlib.sha256(contents).hexdigest(),
    )


def _strict_json_object(contents: bytes, label: str) -> Mapping[str, object]:
    """Decode a JSON object while refusing duplicate keys at every depth."""

    def unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
        value: dict[str, object] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate key {key!r}")
            value[key] = item
        return value

    try:
        value = json.loads(contents, object_pairs_hook=unique_object)
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError, RecursionError) as exc:
        raise Refusal(f"{label} is malformed JSON: {exc}") from exc
    return _as_mapping(value, label)


def _refuse_symlink(path: Path, label: str) -> None:
    try:
        if path.is_symlink():
            raise StateError(f"{label} must not be a symlink: {path}")
    except OSError as exc:
        raise StateError(f"cannot inspect {label} {path}: {exc}") from exc


def _relative_inside_reference(
    root: Path, raw: str, label: str
) -> tuple[str, Path]:
    """Validate a stored relative identity without inspecting its storage."""

    candidate = Path(raw)
    if candidate.is_absolute() or not candidate.parts or ".." in candidate.parts:
        raise Refusal(f"{label} must be a relative path inside {root}: {raw!r}")
    lexical = Path(os.path.normpath(str(candidate)))
    if lexical == Path("."):
        raise Refusal(f"{label} must not be the project root")
    return lexical.as_posix(), root / lexical


def _relative_inside(root: Path, raw: str, label: str) -> tuple[str, Path]:
    lexical, absolute = _relative_inside_reference(root, raw, label)
    _ensure_no_symlink_components(root, absolute, label)
    return lexical, absolute


def _ensure_no_symlink_components(root: Path, path: Path, label: str) -> None:
    try:
        relative = path.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"{label} escapes the project root: {path}") from exc
    current = root
    for part in relative.parts:
        current = current / part
        try:
            if current.is_symlink():
                raise Refusal(f"{label} crosses a symlink: {current}")
        except OSError as exc:
            raise Refusal(f"cannot inspect {label} path {current}: {exc}") from exc


def _canonical_managed_file_path(
    config: Config,
    raw: str,
    label: str,
    *,
    allow_frozen: bool = False,
) -> tuple[str, Path]:
    """Resolve one exact managed file spelling without accepting aliases."""

    candidate = Path(raw)
    if candidate.is_absolute():
        if not allow_frozen or raw != os.path.normpath(raw) or ".." in candidate.parts:
            raise Refusal(f"{label} is not a canonical managed path: {raw!r}")
        frozen_root = _frozen_validation_directory(config)
        if not _path_is_within(candidate, frozen_root):
            raise Refusal(f"{label} is outside the managed validation roots: {raw!r}")
        _ensure_no_symlink_components(config.root.parent, candidate, label)
        return raw, candidate
    relative, path = _relative_inside(config.root, raw, label)
    if relative != raw:
        raise Refusal(
            f"{label} must use its canonical project-relative spelling: {relative!r}"
        )
    return relative, path


def _managed_file_reference(config: Config, path: Path) -> str:
    """Render an already-bounded managed path in its one accepted spelling."""

    try:
        return path.relative_to(config.root).as_posix()
    except ValueError:
        frozen_root = _frozen_validation_directory(config)
        if not path.is_absolute() or not _path_is_within(path, frozen_root):
            raise Refusal(f"validation proof path is outside the managed roots: {path}")
        return str(path)


def _regular_file_identity_to_obj(identity: _RegularFileIdentity) -> dict[str, object]:
    return {
        "identity": [identity.device, identity.inode],
        "size": identity.size,
        "sha256": identity.sha256,
    }


def _regular_file_identity_from_obj(
    value: Mapping[str, object], label: str
) -> _RegularFileIdentity:
    identity = _as_list(value.get("identity"), f"{label}.identity")
    if len(identity) != 2:
        raise StateError(f"{label}.identity must contain device and inode")
    digest = _as_str(value.get("sha256"), f"{label}.sha256")
    if not DIGEST_RE.fullmatch(digest):
        raise StateError(f"{label}.sha256 must be 64 lowercase hexadecimal digits")
    return _RegularFileIdentity(
        device=_as_int(identity[0], f"{label}.identity[0]", minimum=0),
        inode=_as_int(identity[1], f"{label}.identity[1]", minimum=1),
        size=_as_int(value.get("size"), f"{label}.size", minimum=0),
        sha256=digest,
    )


def _validation_removal_artifact_to_obj(
    artifact: _ValidationRemovalArtifact,
) -> dict[str, object]:
    return {
        "role": artifact.role,
        "path": artifact.path,
        **_regular_file_identity_to_obj(artifact.identity),
    }


def _validation_removal_manifest_to_obj(
    proof: _ValidationRemovalProof,
) -> dict[str, object]:
    return {
        "schema": _VALIDATION_REMOVAL_PROOF_SCHEMA,
        "kind": "validation-removal-proof",
        "slot": proof.slot,
        "generation": proof.generation,
        "checkout": proof.checkout,
        "artifacts": [
            _validation_removal_artifact_to_obj(artifact)
            for artifact in proof.artifacts
        ],
    }


def _validation_removal_proof_to_obj(
    proof: _ValidationRemovalProof,
) -> dict[str, object]:
    return {
        "manifest": {
            "path": proof.manifest_path,
            **_regular_file_identity_to_obj(proof.manifest_identity),
        },
        **_validation_removal_manifest_to_obj(proof),
    }


def _validation_removal_artifacts_from_obj(
    value: object, label: str
) -> tuple[_ValidationRemovalArtifact, ...]:
    artifacts: list[_ValidationRemovalArtifact] = []
    for index, item in enumerate(_as_list(value, label)):
        row_label = f"{label}[{index}]"
        raw = _as_mapping(item, row_label)
        _exact_keys(
            raw,
            {"role", "path", "identity", "size", "sha256"},
            set(),
            row_label,
        )
        role = _as_str(raw["role"], f"{row_label}.role")
        artifacts.append(
            _ValidationRemovalArtifact(
                role=role,
                path=_as_str(raw["path"], f"{row_label}.path"),
                identity=_regular_file_identity_from_obj(raw, row_label),
            )
        )
    roles = [artifact.role for artifact in artifacts]
    if len(roles) != len(set(roles)):
        raise StateError("validation removal proof repeats an artifact role")
    if set(roles) != _VALIDATION_REMOVAL_ARTIFACT_ROLES:
        raise StateError(
            "validation removal proof must name exactly run-record, service-result, "
            "producer-schema, and scorecard-handoff artifacts"
        )
    paths = [artifact.path for artifact in artifacts]
    if len(paths) != len(set(paths)):
        raise StateError("validation removal proof repeats an artifact path")
    return tuple(artifacts)


def _validation_removal_manifest_fields(
    value: Mapping[str, object], label: str
) -> tuple[str, int, str, tuple[_ValidationRemovalArtifact, ...]]:
    _exact_keys(
        value,
        {"schema", "kind", "slot", "generation", "checkout", "artifacts"},
        set(),
        label,
    )
    if _as_int(value["schema"], f"{label}.schema") != _VALIDATION_REMOVAL_PROOF_SCHEMA:
        raise StateError("unsupported validation removal proof schema")
    if _as_str(value["kind"], f"{label}.kind") != "validation-removal-proof":
        raise StateError("validation removal proof has the wrong kind")
    slot = _validate_name(_as_str(value["slot"], f"{label}.slot"), "slot")
    generation = _as_int(value["generation"], f"{label}.generation", minimum=1)
    checkout = _as_str(value["checkout"], f"{label}.checkout")
    artifacts = _validation_removal_artifacts_from_obj(
        value["artifacts"], f"{label}.artifacts"
    )
    return slot, generation, checkout, artifacts


def _validation_removal_proof_from_obj(
    value: object, label: str = "validation removal proof"
) -> _ValidationRemovalProof:
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {
            "manifest",
            "schema",
            "kind",
            "slot",
            "generation",
            "checkout",
            "artifacts",
        },
        set(),
        label,
    )
    manifest = _as_mapping(raw["manifest"], f"{label}.manifest")
    _exact_keys(
        manifest,
        {"path", "identity", "size", "sha256"},
        set(),
        f"{label}.manifest",
    )
    manifest_payload = {
        key: raw[key]
        for key in ("schema", "kind", "slot", "generation", "checkout", "artifacts")
    }
    slot, generation, checkout, artifacts = _validation_removal_manifest_fields(
        manifest_payload, label
    )
    return _ValidationRemovalProof(
        manifest_path=_as_str(manifest["path"], f"{label}.manifest.path"),
        manifest_identity=_regular_file_identity_from_obj(
            manifest, f"{label}.manifest"
        ),
        slot=slot,
        generation=generation,
        checkout=checkout,
        artifacts=artifacts,
    )


def _assert_regular_file_identity(
    expected: _RegularFileIdentity,
    observed: _RegularFileIdentity,
    label: str,
) -> None:
    if (observed.device, observed.inode) != (expected.device, expected.inode):
        raise Refusal(f"{label} regular-file identity changed")
    if observed.size != expected.size:
        raise Refusal(f"{label} size changed")
    if observed.sha256 != expected.sha256:
        raise Refusal(f"{label} changed bytes")


def _validation_proof_manifest_path(config: Config, raw: str) -> tuple[str, Path]:
    relative, path = _canonical_managed_file_path(
        config, raw, "validation removal proof manifest"
    )
    proof_root = Path("ignored/validate/removal-proofs")
    relative_path = Path(relative)
    if (
        relative_path.suffix != ".json"
        or not _path_is_within(relative_path, proof_root)
        or relative_path == proof_root
    ):
        raise Refusal(
            "validation removal proof manifest must be a JSON file under "
            "ignored/validate/removal-proofs"
        )
    return relative, path


def _validation_run_record_argument(config: Config, raw: str) -> tuple[str, Path]:
    relative, path = _canonical_managed_file_path(
        config, raw, "completed validation run-record"
    )
    if (
        Path(relative).parent != Path("ignored/validate/runs")
        or path.suffix != ".json"
        or path.name.endswith(_VALIDATION_SERVICE_RESULT_SUFFIX)
    ):
        raise Refusal(
            "completed validation run-record must be one canonical "
            "ignored/validate/runs/*.json handle, not a service-result sidecar"
        )
    return relative, path


def _proof_artifact_path(
    config: Config,
    artifact: _ValidationRemovalArtifact,
    *,
    canonical_slot: Path,
    active_slot: Path,
) -> Path:
    candidate = Path(artifact.path)
    canonical = candidate if candidate.is_absolute() else config.root / candidate
    if _path_is_within(canonical, canonical_slot):
        relative = canonical.relative_to(canonical_slot)
        active = active_slot / relative
        _ensure_no_symlink_components(active_slot, active, artifact.role)
        return active
    _relative, external = _canonical_managed_file_path(
        config, artifact.path, artifact.role
    )
    return external


def _validate_proof_artifact_paths(
    config: Config,
    artifacts: Sequence[_ValidationRemovalArtifact],
    *,
    canonical_slot: Path,
    canonical_checkout: Path,
) -> tuple[tuple[_ValidationRemovalArtifact, Path], ...]:
    resolved: list[tuple[_ValidationRemovalArtifact, Path]] = []
    for artifact in artifacts:
        allow_frozen = artifact.role == "producer-schema"
        relative, path = _canonical_managed_file_path(
            config,
            artifact.path,
            f"validation removal {artifact.role}",
            allow_frozen=allow_frozen,
        )
        del relative
        inside_checkout = _path_is_within(path, canonical_checkout)
        if artifact.role == "producer-schema":
            if not inside_checkout or path == canonical_checkout:
                raise Refusal(
                    "validation removal producer-schema must be inside the exact checkout"
                )
        elif _path_is_within(path, canonical_slot):
            raise Refusal(
                f"validation removal {artifact.role} must remain outside the target"
            )
        if artifact.role == "scorecard-handoff" and path.name != "handoff.json":
            raise Refusal(
                "validation removal scorecard-handoff must name the exact "
                "handoff.json regular file"
            )
        resolved.append((artifact, path))
    return tuple(resolved)


def _validation_removal_artifact(
    artifacts: Sequence[_ValidationRemovalArtifact], role: str
) -> _ValidationRemovalArtifact:
    return next(artifact for artifact in artifacts if artifact.role == role)


def _validation_removal_record_path(
    config: Config, artifact: _ValidationRemovalArtifact
) -> tuple[str, Path]:
    relative, path = _canonical_managed_file_path(
        config, artifact.path, "validation removal run-record"
    )
    if (
        Path(relative).parent != Path("ignored/validate/runs")
        or path.suffix != ".json"
        or path.name.endswith(_VALIDATION_SERVICE_RESULT_SUFFIX)
    ):
        raise Refusal(
            "validation removal run-record must be one canonical "
            "ignored/validate/runs/*.json handle, not a service-result sidecar"
        )
    return relative, path


def _validation_removal_record_fields(
    config: Config,
    record_path: Path,
    record: Mapping[str, object],
    *,
    canonical_checkout: Path,
    expected_head: str,
    expected_slot: str,
    expected_generation: int | None,
) -> tuple[str, int, dict[str, Path]]:
    schema = record.get("service_result_schema")
    if (
        not isinstance(schema, int)
        or isinstance(schema, bool)
        or schema not in {1, 2, 3, 4, 5}
    ):
        raise Refusal(
            "validation removal run-record has no supported service-result identity"
        )
    historical = schema in {1, 2, 3}
    expected_state = "unknown" if historical else "completed"
    if record.get("state") != expected_state:
        raise Refusal(
            "validation removal run-record state does not match its service-result "
            "schema"
        )
    if not _validation_record_has_typed_admission(record):
        raise Refusal(
            "validation removal run-record has no canonical producer admission"
        )
    if expected_generation is not None and (
        record.get("wrkslots_slot") != expected_slot
        or type(record.get("wrkslots_generation")) is not int
        or record.get("wrkslots_generation") != expected_generation
    ):
        raise Refusal(
            "validation removal run-record does not name the exact slot generation"
        )
    unit = record.get("unit")
    if not isinstance(unit, str) or _VALIDATION_UNIT_RE.fullmatch(unit) is None:
        raise Refusal(
            "validation removal run-record has no canonical validate-*.service unit"
        )
    unit_name = unit.removesuffix(".service")
    if record_path.name != f"{unit_name}.json":
        raise Refusal(
            "validation removal run-record path does not match its exact unit"
        )
    if record.get("checkout") != str(canonical_checkout):
        raise Refusal(
            "validation removal run-record does not name the exact checkout"
        )
    if record.get("target") != expected_head:
        raise Refusal(
            "validation removal run-record target does not match the checkout HEAD"
        )
    expected_source = (
        "historical-validation-service-result"
        if historical
        else "validation-service-result"
    )
    if record.get("result_source") != expected_source:
        raise Refusal(
            "validation removal run-record has no supported service-result identity"
        )
    if schema == 1:
        if "scorecard_writeback" in record:
            raise Refusal(
                "validation removal historical schema-1 run-record must not derive "
                "scorecard writeback"
            )
    elif record.get("scorecard_writeback") != {"status": "completed"}:
        raise Refusal(
            "validation removal run-record has no completed scorecard writeback"
        )
    scorecard_directory = (
        config.root
        / "ignored"
        / "validate"
        / "scorecard-writebacks"
        / unit_name
    )
    if record.get("scorecard_handoff") != str(scorecard_directory):
        raise Refusal(
            "validation removal run-record does not name its canonical scorecard handoff"
        )
    return unit_name, schema, {
        "run-record": record_path,
        "service-result": record_path.with_name(
            f"{record_path.stem}{_VALIDATION_SERVICE_RESULT_SUFFIX}"
        ),
        "producer-schema": canonical_checkout / _VALIDATION_SERVICE_RESULT_SCHEMA_PATH,
        "scorecard-handoff": scorecard_directory / "handoff.json",
    }


def _validation_service_result_schema(
    contents: bytes, schema: int
) -> tuple[str, ...]:
    producer_schema = _strict_json_object(
        contents, "validation removal producer-schema"
    )
    schema_fields = _VALIDATION_SERVICE_RESULT_FIELDS[schema]
    expected_schema_keys = {"schema_version", "fields", "outcomes"}
    if schema >= 2:
        expected_schema_keys.add("scorecard_writeback")
    outcome_exit_field = "exit_code" if schema == 1 else "validation_exit_code"
    expected_outcomes = {
        "PASSED": {
            outcome_exit_field: 0,
            "state": "completed",
            "result": "success",
        },
        "FAILED": {
            outcome_exit_field: 1,
            "state": "completed",
            "result": "failure",
        },
        "COULD_NOT_RUN": {
            outcome_exit_field: 75,
            "state": "completed",
            "result": "no-result",
        },
    }
    if (
        set(producer_schema) != expected_schema_keys
        or type(producer_schema.get("schema_version")) is not int
        or producer_schema.get("schema_version") != schema
        or producer_schema.get("fields") != list(schema_fields)
        or not _json_equal(producer_schema.get("outcomes"), expected_outcomes)
        or (
            schema >= 2
            and not _json_equal(
                producer_schema.get("scorecard_writeback"),
                _VALIDATION_SCORECARD_WRITEBACK_SCHEMA,
            )
        )
    ):
        raise Refusal(
            "validation removal producer-schema does not match the run-record schema"
        )
    return schema_fields


def _validation_scorecard_writeback(
    value: object, label: str
) -> Mapping[str, object] | None:
    if value is None:
        return None
    if not isinstance(value, dict):
        raise Refusal(f"{label} must be an object or null")
    if value.get("status") == "completed" and set(value) == {"status"}:
        return value
    error = value.get("error")
    if (
        value.get("status") == "failed"
        and set(value) == {"status", "error"}
        and isinstance(error, str)
        and bool(error.strip())
    ):
        return value
    raise Refusal(
        f"{label} must be null, completed, or failed with a nonempty error"
    )


def _validation_optional_count(value: object, label: str) -> int | None:
    if value is None:
        return None
    return _as_int(value, label, minimum=0)


def _validation_service_result_projection(
    contents: bytes,
    *,
    schema: int,
    schema_fields: Sequence[str],
    expected_commit: object,
) -> Mapping[str, object]:
    service_result = _strict_json_object(
        contents, "validation removal service-result"
    )
    if set(service_result) != set(schema_fields):
        raise Refusal(
            "validation removal service-result fields do not match the producer schema"
        )
    if (
        type(service_result.get("schema_version")) is not int
        or service_result.get("schema_version") != schema
    ):
        raise Refusal(
            "validation removal service-result schema differs from the run-record"
        )
    if service_result.get("commit") != expected_commit:
        raise Refusal(
            "validation removal service-result commit differs from the run-record"
        )
    profile = service_result.get("profile")
    if not isinstance(profile, str) or not profile.strip():
        raise Refusal("validation removal service-result profile must be nonempty text")
    status = service_result.get("final_validate_status")
    if not isinstance(status, str) or status not in _VALIDATION_RESULT_OUTCOMES:
        raise Refusal(
            "validation removal service-result final status is unsupported"
        )
    result, expected_exit = _VALIDATION_RESULT_OUTCOMES[status]
    writeback: Mapping[str, object] | None = None
    if schema >= 2:
        writeback = _validation_scorecard_writeback(
            service_result.get("scorecard_writeback"),
            "validation removal service-result scorecard_writeback",
        )
        if status == "PASSED" and writeback is not None:
            if writeback.get("status") == "failed":
                expected_exit = 75
    exit_code = _as_int(
        service_result.get("exit_code"),
        "validation removal service-result exit_code",
    )
    if exit_code != expected_exit:
        raise Refusal(
            "validation removal service-result exit_code disagrees with its outcome"
        )
    executed_nodes = _as_int(
        service_result.get("executed_nodes"),
        "validation removal service-result executed_nodes",
        minimum=0,
    )
    executed_tests = _validation_optional_count(
        service_result.get("executed_tests"),
        "validation removal service-result executed_tests",
    )
    historical = schema in {1, 2, 3}
    projection: dict[str, object] = {
        "state": "unknown" if historical else "completed",
        "result": "unknown" if historical else result,
        "result_source": (
            "historical-validation-service-result"
            if historical
            else "validation-service-result"
        ),
        "final_validate_status": status,
        "exit_code": exit_code,
        "executed_nodes": executed_nodes,
        "executed_tests": executed_tests,
    }
    if historical:
        projection["passed_tests"] = None
        projection["detail"] = _historical_validation_result_detail(schema)
    if schema >= 2:
        projection["scorecard_writeback"] = writeback
    if schema >= 3:
        selection_mode = service_result.get("selection_mode")
        if selection_mode is not None and (
            not isinstance(selection_mode, str) or not selection_mode.strip()
        ):
            raise Refusal(
                "validation removal service-result selection_mode must be nonempty "
                "text or null"
            )
        projection["selection_mode"] = selection_mode
    if schema >= 4:
        passed_tests = _validation_optional_count(
            service_result.get("passed_tests"),
            "validation removal service-result passed_tests",
        )
        if (executed_tests is None) != (passed_tests is None):
            raise Refusal(
                "validation removal service-result test counts are incomplete"
            )
        if (
            executed_tests is not None
            and passed_tests is not None
            and passed_tests > executed_tests
        ):
            raise Refusal(
                "validation removal service-result passed_tests exceeds executed_tests"
            )
        if status == "PASSED" and (
            passed_tests is None or passed_tests != executed_tests
        ):
            raise Refusal(
                "validation removal service-result PASSED counts disagree"
            )
        projection["passed_tests"] = passed_tests
    if schema == 5:
        detail = service_result.get("detail")
        if detail is not None:
            if (
                not isinstance(detail, list)
                or not detail
                or any(
                    not isinstance(line, str) or not line.strip()
                    for line in detail
                )
                or status != "COULD_NOT_RUN"
            ):
                raise Refusal(
                    "validation removal service-result detail violates its schema"
                )
            projection["detail"] = "\n".join(detail)
        elif status == "COULD_NOT_RUN":
            projection["detail"] = (
                "validation reported COULD_NOT_RUN without detail"
            )
        else:
            projection["detail"] = None
    return projection


def _validation_scorecard_file_rows(
    value: object, label: str
) -> tuple[tuple[str, int, str], ...]:
    raw_rows = _as_list(value, label)
    if len(raw_rows) != len(_VALIDATION_SCORECARD_PATHS):
        raise Refusal(
            f"{label} must identify exactly SCORECARD.md and "
            "ci/compat-envelope/cells.json"
        )
    rows: dict[str, tuple[str, int, str]] = {}
    for index, value in enumerate(raw_rows):
        row_label = f"{label}[{index}]"
        row = _as_mapping(value, row_label)
        _exact_keys(row, {"path", "sha256", "size"}, set(), row_label)
        path = _as_str(row["path"], f"{row_label}.path")
        digest = _as_str(row["sha256"], f"{row_label}.sha256")
        size = _as_int(row["size"], f"{row_label}.size", minimum=0)
        if path not in _VALIDATION_SCORECARD_PATHS or path in rows:
            raise Refusal(f"{row_label} has an unknown or duplicate path")
        if re.fullmatch(r"[0-9a-f]{64}", digest) is None:
            raise Refusal(f"{row_label} has no lowercase SHA-256")
        rows[path] = (path, size, digest)
    if set(rows) != set(_VALIDATION_SCORECARD_PATHS):
        raise Refusal(
            f"{label} must identify exactly SCORECARD.md and "
            "ci/compat-envelope/cells.json"
        )
    return tuple(rows[path] for path in _VALIDATION_SCORECARD_PATHS)


def _validate_scorecard_handoff_file_set(path: Path) -> None:
    directory = path.parent
    if directory.is_symlink() or not directory.is_dir():
        raise Refusal(
            f"validation removal scorecard-handoff is not a regular directory: "
            f"{directory}"
        )
    try:
        observed = {
            item.relative_to(directory).as_posix()
            for item in directory.rglob("*")
            if item.is_file() or item.is_symlink()
        }
    except OSError as exc:
        raise Refusal(
            f"cannot inspect validation removal scorecard-handoff {directory}: {exc}"
        ) from exc
    expected = {"handoff.json", *_VALIDATION_SCORECARD_PATHS}
    if observed != expected:
        raise Refusal(
            "validation removal scorecard-handoff has an invalid file set: "
            f"{directory}"
        )


def _validate_validation_removal_payloads(
    config: Config,
    contents: Mapping[str, bytes],
    record: Mapping[str, object],
    *,
    unit_name: str,
    schema: int,
    scorecard_handoff_path: Path,
) -> None:
    schema_fields = _validation_service_result_schema(
        contents["producer-schema"], schema
    )
    projection = _validation_service_result_projection(
        contents["service-result"],
        schema=schema,
        schema_fields=schema_fields,
        expected_commit=record.get("target"),
    )
    if schema < 3 and "selection_mode" in record:
        raise Refusal(
            "validation removal historical run-record unexpectedly carries "
            "selection_mode"
        )
    for field, expected in projection.items():
        if not _json_equal(record.get(field), expected):
            raise Refusal(
                f"validation removal service-result {field} differs from the "
                "run-record"
            )

    scorecard = _strict_json_object(
        contents["scorecard-handoff"], "validation removal scorecard-handoff"
    )
    _exact_keys(
        scorecard,
        {"schema_version", "target", "unit", "writeback_completed", "files"},
        set(),
        "validation removal scorecard-handoff",
    )
    if (
        type(scorecard["schema_version"]) is not int
        or scorecard["schema_version"] != 1
        or scorecard["target"] != record.get("target")
        or scorecard["unit"] != unit_name
        or scorecard["writeback_completed"] is not True
    ):
        raise Refusal(
            "validation removal scorecard-handoff does not match the run-record unit"
        )
    _validate_scorecard_handoff_file_set(scorecard_handoff_path)
    record_files = _validation_scorecard_file_rows(
        record.get("scorecard_writeback_files"),
        "validation removal run-record scorecard_writeback_files",
    )
    handoff_files = _validation_scorecard_file_rows(
        scorecard["files"], "validation removal scorecard-handoff files"
    )
    if handoff_files != record_files:
        raise Refusal(
            "validation removal scorecard-handoff files differ from run-record"
        )
    for relative, size, digest in handoff_files:
        path = scorecard_handoff_path.parent / relative
        _ensure_no_symlink_components(config.root, path, "retained scorecard file")
        _payload, observed = _read_regular_file_identity(
            path,
            "retained scorecard file",
            _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
        )
        if observed.size != size:
            raise Refusal(
                f"retained scorecard file size differs from declared identity: {path}"
            )
        if observed.sha256 != digest:
            raise Refusal(f"retained scorecard file changed bytes: {path}")


def _verify_validation_removal_artifacts(
    config: Config,
    artifacts: Sequence[_ValidationRemovalArtifact],
    *,
    canonical_slot: Path,
    active_slot: Path,
    canonical_checkout: Path,
    expected_head: str,
    expected_slot: str,
    expected_generation: int | None,
    target_kind: str,
    repository: Path | None,
    expected_run_record: Path | None,
    active_slot_fd: int | None = None,
) -> None:
    run_artifact = _validation_removal_artifact(artifacts, "run-record")
    run_relative, run_path = _validation_removal_record_path(config, run_artifact)
    if (
        expected_run_record is not None
        and run_path != expected_run_record
    ):
        raise Refusal(
            "validation removal proof run-record differs from --completed-record"
        )
    _terminal_validation_record(
        config,
        run_relative,
        canonical_checkout,
        target_kind,
        expected_digest=run_artifact.identity.sha256,
        repository=repository,
        expected_target=expected_head,
        allow_historical_service_result=True,
    )
    run_contents, observed_run = _read_regular_file_identity(
        run_path,
        "validation removal run-record",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    _assert_regular_file_identity(
        run_artifact.identity, observed_run, "run-record"
    )
    record = _strict_json_object(run_contents, "validation removal run-record")
    unit_name, schema, expected_paths = _validation_removal_record_fields(
        config,
        run_path,
        record,
        canonical_checkout=canonical_checkout,
        expected_head=expected_head,
        expected_slot=expected_slot,
        expected_generation=expected_generation,
    )
    resolved = _validate_proof_artifact_paths(
        config,
        artifacts,
        canonical_slot=canonical_slot,
        canonical_checkout=canonical_checkout,
    )
    contents: dict[str, bytes] = {}
    active_paths: dict[str, Path] = {}
    identities: dict[tuple[int, int], str] = {}
    for artifact, canonical_path in resolved:
        expected_path = expected_paths[artifact.role]
        if canonical_path != expected_path:
            raise Refusal(
                f"validation removal {artifact.role} path does not match the "
                "run-record"
            )
        if artifact.role == "producer-schema" and active_slot_fd is not None:
            try:
                relative = canonical_path.relative_to(canonical_slot)
            except ValueError as exc:
                raise StateError(
                    "validation removal producer-schema is outside its canonical "
                    "checkout"
                ) from exc
            payload, observed = _read_regular_file_identity_beneath(
                active_slot_fd,
                relative,
                "validation removal producer-schema",
                _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
            )
            active_path = canonical_path
        else:
            active_path = _proof_artifact_path(
                config,
                artifact,
                canonical_slot=canonical_slot,
                active_slot=active_slot,
            )
            payload, observed = _read_regular_file_identity(
                active_path,
                f"validation removal {artifact.role}",
                _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
            )
        _assert_regular_file_identity(artifact.identity, observed, artifact.role)
        identity = (observed.device, observed.inode)
        duplicate_role = identities.get(identity)
        if duplicate_role is not None:
            raise Refusal(
                "validation removal artifacts share one regular-file identity: "
                f"{duplicate_role} and {artifact.role}"
            )
        identities[identity] = artifact.role
        contents[artifact.role] = payload
        active_paths[artifact.role] = active_path
    _validate_validation_removal_payloads(
        config,
        contents,
        record,
        unit_name=unit_name,
        schema=schema,
        scorecard_handoff_path=active_paths["scorecard-handoff"],
    )


def _load_validation_removal_proof(
    config: Config,
    raw_manifest: str,
    *,
    expected_slot: str,
    expected_generation: int | None,
    canonical_slot: Path,
    canonical_checkout: Path,
    expected_run_record: Path,
    expected_head: str,
    target_kind: str = "checkout",
    repository: Path | None = None,
) -> _ValidationRemovalProof:
    manifest_relative, manifest_path = _validation_proof_manifest_path(
        config, raw_manifest
    )
    if _path_is_within(manifest_path, canonical_slot):
        raise Refusal("validation removal proof manifest must remain outside the target")
    contents, manifest_identity = _read_regular_file_identity(
        manifest_path,
        "validation removal proof manifest",
        _VALIDATION_REMOVAL_PROOF_BYTES_LIMIT,
    )
    manifest = _strict_json_object(contents, "validation removal proof manifest")
    slot, generation, checkout, declared = _validation_removal_manifest_fields(
        manifest, "validation removal proof manifest"
    )
    if slot != expected_slot:
        raise Refusal(
            f"validation removal proof names slot {slot!r}, expected {expected_slot!r}"
        )
    if expected_generation is not None and generation != expected_generation:
        raise Refusal(
            f"validation removal proof names generation {generation}, expected "
            f"{expected_generation}"
        )
    expected_checkout = _managed_file_reference(config, canonical_checkout)
    if checkout != expected_checkout:
        raise Refusal(
            "validation removal proof does not name the exact checkout: "
            f"expected {expected_checkout!r}"
        )
    _verify_validation_removal_artifacts(
        config,
        declared,
        canonical_slot=canonical_slot,
        active_slot=canonical_slot,
        canonical_checkout=canonical_checkout,
        expected_head=expected_head,
        expected_slot=expected_slot,
        expected_generation=expected_generation,
        target_kind=target_kind,
        repository=repository,
        expected_run_record=expected_run_record,
    )
    return _ValidationRemovalProof(
        manifest_path=manifest_relative,
        manifest_identity=manifest_identity,
        slot=slot,
        generation=generation,
        checkout=checkout,
        artifacts=declared,
    )


def _recheck_validation_removal_proof(
    config: Config,
    proof: _ValidationRemovalProof,
    *,
    expected_slot: str,
    expected_generation: int | None,
    canonical_slot: Path,
    active_slot: Path,
    canonical_checkout: Path,
    expected_head: str,
    target_kind: str = "checkout",
    repository: Path | None = None,
    active_slot_fd: int | None = None,
) -> None:
    if proof.slot != expected_slot or (
        expected_generation is not None and proof.generation != expected_generation
    ):
        raise StateError("journaled validation removal proof has the wrong slot generation")
    if proof.checkout != _managed_file_reference(config, canonical_checkout):
        raise StateError("journaled validation removal proof names another checkout")
    manifest_relative, manifest_path = _validation_proof_manifest_path(
        config, proof.manifest_path
    )
    if manifest_relative != proof.manifest_path:
        raise StateError("journaled validation removal proof path is not canonical")
    contents, observed_manifest = _read_regular_file_identity(
        manifest_path,
        "validation removal proof manifest",
        _VALIDATION_REMOVAL_PROOF_BYTES_LIMIT,
    )
    _assert_regular_file_identity(
        proof.manifest_identity, observed_manifest, "validation removal proof manifest"
    )
    manifest = _strict_json_object(contents, "validation removal proof manifest")
    if dict(manifest) != _validation_removal_manifest_to_obj(proof):
        raise Refusal("validation removal proof manifest changed after authorization")
    _verify_validation_removal_artifacts(
        config,
        proof.artifacts,
        canonical_slot=canonical_slot,
        active_slot=active_slot,
        canonical_checkout=canonical_checkout,
        expected_head=expected_head,
        expected_slot=expected_slot,
        expected_generation=expected_generation,
        target_kind=target_kind,
        repository=repository,
        expected_run_record=None,
        active_slot_fd=active_slot_fd,
    )


def _ensure_no_mount_components(root: Path, path: Path, label: str) -> None:
    try:
        relative = path.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"{label} escapes its managed root: {path}") from exc
    current = root
    for part in relative.parts:
        current = current / part
        try:
            if os.path.ismount(current):
                raise Refusal(f"{label} crosses a mount point: {current}")
        except OSError as exc:
            raise Refusal(f"cannot inspect {label} mount path {current}: {exc}") from exc


def _mountinfo_path(value: str) -> Path:
    decoded = value
    for escaped, character in (
        ("\\040", " "),
        ("\\011", "\t"),
        ("\\012", "\n"),
        ("\\134", "\\"),
    ):
        decoded = decoded.replace(escaped, character)
    return Path(decoded)


def _assert_no_mountinfo_crossing(root: Path, path: Path, label: str) -> None:
    if not _path_is_within(path, root):
        raise Refusal(f"{label} escapes its managed root: {path}")
    mountinfo_path = Path("/proc/self/mountinfo")
    try:
        lines = mountinfo_path.read_text(
            encoding="utf-8", errors="surrogateescape"
        ).splitlines()
    except OSError as exc:
        raise Refusal(
            f"cannot prove {label} contains no mount points because {mountinfo_path} "
            f"is unreadable: {exc}"
        ) from exc
    for line in lines:
        left, separator, _right = line.partition(" - ")
        if not separator:
            continue
        fields = left.split()
        if len(fields) < 5:
            continue
        mount_point = _mountinfo_path(fields[4])
        if (
            mount_point.is_absolute()
            and mount_point != root
            and _path_is_within(mount_point, root)
            and (
                _path_is_within(path, mount_point)
                or _path_is_within(mount_point, path)
            )
        ):
            raise Refusal(f"{label} crosses or contains a mount point: {mount_point}")


def _path_is_within(candidate: Path, parent: Path) -> bool:
    """Whether ``candidate`` is ``parent`` or lies lexically below it.

    The answer is exactly whether ``candidate.relative_to(parent)`` succeeds,
    but for the common case of two ordinary absolute paths it compares strings:
    a slot-use census asks this for every path in every mount table it walks,
    and `relative_to` built and compared so many intermediate `Path` objects
    that it was measured, 2026-09-24, at 103 s of a 119 s `recover
    --abort-create`.  The separator keeps component boundaries, so ``/a/bc`` is
    not within ``/a/b``.  Relative paths and POSIX's distinct leading ``//``
    keep pathlib's own rules.
    """

    child = str(candidate)
    base = str(parent)
    if child[:1] != "/" or base[:1] != "/" or child[:2] == "//" or base[:2] == "//":
        try:
            candidate.relative_to(parent)
            return True
        except ValueError:
            return False
    return base == "/" or child == base or child.startswith(base + "/")


def _fd_mount_id(fd: int, label: str) -> int:
    path = Path("/proc/self/fdinfo") / str(fd)
    try:
        contents = path.read_text(encoding="ascii")
    except OSError as exc:
        raise Refusal(f"cannot determine mount identity for {label}: {exc}") from exc
    for line in contents.splitlines():
        key, separator, raw = line.partition(":")
        if key == "mnt_id" and separator:
            try:
                value = int(raw.strip())
            except ValueError as exc:
                raise Refusal(f"invalid mount identity for {label}: {raw!r}") from exc
            if value > 0:
                return value
    raise Refusal(f"cannot determine mount identity for {label}: mnt_id is absent")


def _open_directory_identity(path: Path, label: str) -> tuple[int, int, int]:
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise Refusal(f"cannot safely open {label} {path}: {exc}") from exc
    try:
        metadata = os.fstat(fd)
        return metadata.st_dev, metadata.st_ino, _fd_mount_id(fd, str(path))
    finally:
        os.close(fd)


class _FileHandle(ctypes.Structure):
    _fields_ = (
        ("handle_bytes", ctypes.c_uint),
        ("handle_type", ctypes.c_int),
        ("handle", ctypes.c_ubyte * _FILE_HANDLE_BYTES_LIMIT),
    )


_PrivateCleanupIdentity = tuple[int, int, int] | tuple[int, int, int, str]


def _fd_file_handle(fd: int, label: str) -> tuple[int, str]:
    """Return the filesystem's stable handle for one already-open object."""

    handle = _FileHandle()
    handle.handle_bytes = _FILE_HANDLE_BYTES_LIMIT
    mount_id = ctypes.c_int()
    try:
        name_to_handle_at = ctypes.CDLL(None, use_errno=True).name_to_handle_at
    except AttributeError as exc:
        raise Refusal(f"cannot determine stable directory identity for {label}") from exc
    ctypes.set_errno(0)
    result = name_to_handle_at(
        _AT_FDCWD,
        os.fsencode(f"/proc/self/fd/{fd}"),
        ctypes.byref(handle),
        ctypes.byref(mount_id),
        _AT_SYMLINK_FOLLOW,
    )
    if result != 0:
        error = ctypes.get_errno()
        raise Refusal(
            f"cannot determine stable directory identity for {label}: "
            f"{os.strerror(error)}"
        )
    if not 0 < handle.handle_bytes <= _FILE_HANDLE_BYTES_LIMIT:
        raise Refusal(f"invalid stable directory identity for {label}")
    return handle.handle_type, bytes(handle.handle[: handle.handle_bytes]).hex()


def _fd_private_cleanup_identity(fd: int, label: str) -> tuple[int, int, int, str]:
    """Identify a directory independently of the caller's mount namespace."""

    before = os.fstat(fd)
    handle_type, file_handle = _fd_file_handle(fd, label)
    after = os.fstat(fd)
    if (before.st_dev, before.st_ino) != (after.st_dev, after.st_ino):
        raise Refusal(f"directory identity changed while inspecting {label}")
    return before.st_dev, before.st_ino, handle_type, file_handle


def _private_cleanup_identity_from_obj(
    value: object, label: str
) -> _PrivateCleanupIdentity:
    values = _as_list(value, label)
    if len(values) == 3:
        return (
            _as_int(values[0], f"{label}[0]", minimum=1),
            _as_int(values[1], f"{label}[1]", minimum=1),
            _as_int(values[2], f"{label}[2]", minimum=1),
        )
    if len(values) != 4:
        raise StateError(
            f"{label} must contain dev, ino, file-handle type, and file-handle bytes"
        )
    file_handle = _as_str(values[3], f"{label}[3]")
    if (
        not file_handle
        or len(file_handle) > _FILE_HANDLE_BYTES_LIMIT * 2
        or len(file_handle) % 2
        or re.fullmatch(r"[0-9a-f]+", file_handle) is None
    ):
        raise StateError(f"{label}[3] must be bounded lowercase hexadecimal bytes")
    return (
        _as_int(values[0], f"{label}[0]", minimum=1),
        _as_int(values[1], f"{label}[1]", minimum=1),
        _as_int(values[2], f"{label}[2]", minimum=0),
        file_handle,
    )


def _config_payload(
    worktrees_dir: str,
    machine: str,
    default_remote: str,
    default_landed_ref: str,
    heartbeat_ttl_seconds: int,
    liveness_command: str,
    liveness_batch_command: str | None = None,
    max_active_slots: int | None = None,
    layout: str = "nested",
    cache_globs: Sequence[str] = (),
    repo_cache_globs: Sequence[tuple[str, Sequence[str]]] = (),
    post_provision_hooks: Sequence[str] = (),
    disk_advisory_bytes: int | None = None,
    disk_provisioning_floor_bytes: int | None = None,
    disk_emergency_bytes: int | None = None,
    slot_representation: str = "worktree",
    image: Mapping[str, object] | None = None,
    sandbox_section: Mapping[str, object] | None = None,
    salvage_push_remotes: Sequence[str] = (),
) -> dict[str, object]:
    payload: dict[str, object] = {
        "schema": SCHEMA,
        "worktrees_dir": worktrees_dir,
        "machine": machine,
        "default_remote": default_remote,
        "default_landed_ref": default_landed_ref,
        "heartbeat_ttl_seconds": heartbeat_ttl_seconds,
        "liveness_command": liveness_command,
    }
    if liveness_batch_command is not None:
        payload["liveness_batch_command"] = liveness_batch_command
    # Absent means "no cap", so an unset cap must not appear in the payload at
    # all; writing an explicit null would make init non-idempotent against every
    # configuration written before the field existed.
    if max_active_slots is not None:
        payload["max_active_slots"] = max_active_slots
    if layout != "nested":
        payload["layout"] = layout
    if cache_globs:
        payload["cache_globs"] = list(cache_globs)
    if repo_cache_globs:
        payload["repo_cache_globs"] = {
            name: list(patterns) for name, patterns in repo_cache_globs
        }
    if post_provision_hooks:
        payload["post_provision_hooks"] = list(post_provision_hooks)
    if salvage_push_remotes:
        payload["salvage_push_remotes"] = list(salvage_push_remotes)
    if disk_advisory_bytes is not None:
        payload["disk_advisory_bytes"] = disk_advisory_bytes
        payload["disk_provisioning_floor_bytes"] = disk_provisioning_floor_bytes
        payload["disk_emergency_bytes"] = disk_emergency_bytes
    if slot_representation != "worktree":
        payload["slot_representation"] = slot_representation
    if image:
        payload["image"] = dict(image)
    if sandbox_section is not None:
        payload["sandbox"] = dict(sandbox_section)
    return payload


def _canonical_config_payload(value: Mapping[str, object]) -> dict[str, object]:
    canonical = dict(value)
    if canonical.get("layout") == "nested":
        canonical.pop("layout")
    if canonical.get("cache_globs") == []:
        canonical.pop("cache_globs")
    if canonical.get("repo_cache_globs") == {}:
        canonical.pop("repo_cache_globs")
    if canonical.get("post_provision_hooks") == []:
        canonical.pop("post_provision_hooks")
    if canonical.get("salvage_push_remotes") == []:
        canonical.pop("salvage_push_remotes")
    if canonical.get("slot_representation") == "worktree":
        canonical.pop("slot_representation")
    return canonical


def _repaired_config(
    existing: dict[str, object], payload: dict[str, object]
) -> tuple[dict[str, object], list[str]]:
    """Bring a configuration written by an older build up to this schema.

    Repair is deliberately narrow. It ADDS fields this build requires and that
    the file does not have, and it bumps ``schema``. It never rewrites a field
    that is present with a different value, because a configuration is a
    description of where live state already is: silently changing
    ``worktrees_dir`` or ``machine`` would not fix a stale file, it would point
    the tool at a different registry and orphan every slot recorded in the old
    one. Every conflicting field is refused, and all of them are listed at once,
    so a repair can never be a disguised relocation and one fix per run is not
    the operator's only option.

    Returns the repaired mapping and a human-readable list of what changed, so
    the operator sees the migration rather than trusting it.
    """
    repaired = dict(existing)
    changes: list[str] = []
    conflicts: list[str] = []
    for key, want in payload.items():
        if key not in repaired:
            if key == "layout" and want == "flat":
                conflicts.append(
                    "layout: absent means nested; repair will not reinterpret existing "
                    "storage as flat"
                )
                continue
            repaired[key] = want
            changes.append(f"added {key}={want!r}")
            continue
        have = repaired[key]
        if have == want:
            continue
        if key in _CONFIG_REPAIR_UPDATABLE:
            # `schema` is what repair exists to advance. `max_active_slots` is a
            # policy knob, not a pointer to state: changing it re-tunes future
            # allocation and cannot orphan a slot that already exists. Both are
            # still reported, so an update is never silent.
            repaired[key] = want
            changes.append(f"{key} {have!r} -> {want!r}")
            continue
        conflicts.append(f"{key}: file has {have!r}, command line says {want!r}")
    unknown = sorted(set(repaired) - set(payload) - OPTIONAL_CONFIG_KEYS)
    if unknown:
        conflicts.append(
            "unknown field(s) this build does not understand: " + ", ".join(unknown)
        )
    if conflicts:
        raise Refusal(
            "cannot repair configuration without changing a field that already "
            "has a value; resolve these by hand and rerun:\n  "
            + "\n  ".join(conflicts)
        )
    if not changes:
        changes.append("no field needed repair")
    return repaired, changes


def _config_is_authoritative_candidate(root: Path, config_path: Path) -> bool:
    if config_path.is_symlink():
        return True
    try:
        raw = _read_config(config_path)
    except StateError:
        return True
    worktrees_value = raw.get("worktrees_dir")
    layout_value = raw.get("layout", "nested")
    if not isinstance(worktrees_value, str) or layout_value not in {"nested", "flat"}:
        return True
    candidate = Path(worktrees_value)
    if candidate.is_absolute() or not candidate.parts or ".." in candidate.parts:
        return True
    worktrees = root / Path(os.path.normpath(str(candidate)))
    control = worktrees if layout_value == "nested" else worktrees.parent
    return (
        (control / "wrkslots").is_symlink()
        or any(control.glob("ACTIVE.*.json"))
        or any(control.glob("ARCHIVED.*.json"))
        or any(control.glob("ACTIVE.*.journal"))
        or any(control.glob("CREATE.*.journal"))
        or any(control.glob("FINISH.*.journal"))
        or any(control.glob("VALIDATE-BATCH-SEAL.*.journal"))
        or any(control.glob("EVENTS.*"))
    )


def _discover_root(explicit: str | None) -> Path:
    if explicit is not None:
        candidate = Path(explicit).absolute()
        if candidate.is_symlink() or not candidate.is_dir():
            raise Refusal(f"project root must be an existing real directory: {candidate}")
        return candidate.resolve(strict=True)
    current = Path.cwd().resolve(strict=True)
    fallback: Path | None = None
    for candidate in (current, *current.parents):
        config_path = candidate / CONFIG_NAME
        if config_path.exists() or config_path.is_symlink():
            fallback = candidate
            if _config_is_authoritative_candidate(candidate, config_path):
                return candidate
    if fallback is not None:
        return fallback
    raise Refusal(f"no {CONFIG_NAME} found; run 'wrkslots init' from the project root")


def _load_config(explicit_root: str | None, machine_override: str | None) -> Config:
    root = _discover_root(explicit_root)
    path = root / CONFIG_NAME
    raw = _read_config(path)
    try:
        _exact_keys(raw, set(REQUIRED_CONFIG_KEYS), OPTIONAL_CONFIG_KEYS, "configuration")
    except StateError as exc:
        # A configuration written by an older build is missing fields this build
        # requires. Without a repair path every command, including read-only
        # status, is dead with no way back; say where the way back is.
        raise StateError(
            f"{exc} in {path}. Migrate it with `wrkslots init --repair` "
            f"(it refuses to change any field that already has a conflicting "
            f"value)."
        ) from exc
    if _as_int(raw["schema"], "configuration.schema") != SCHEMA:
        raise StateError(
            f"unsupported configuration schema in {path}: found "
            f"{raw['schema']!r}, this build speaks {SCHEMA}. Migrate it with "
            f"`wrkslots init --repair` (it refuses to change any field that "
            f"already has a conflicting value)."
        )
    machine = machine_override or os.environ.get("WRKSLOTS_MACHINE")
    if machine is None:
        machine = _as_str(raw["machine"], "configuration.machine")
    _validate_name(machine, "machine")
    relative, worktrees = _relative_inside(
        root, _as_str(raw["worktrees_dir"], "configuration.worktrees_dir"), "worktrees_dir"
    )
    del relative
    if not worktrees.is_dir() or worktrees.is_symlink():
        raise StateError(f"configured worktrees directory is missing or unsafe: {worktrees}")
    layout = _validate_layout(
        _as_str(raw.get("layout", "nested"), "configuration.layout")
    )
    control = _control_directory_for(worktrees, layout)
    if not control.is_dir() or control.is_symlink():
        raise StateError(f"configured control directory is missing or unsafe: {control}")
    remote = _validate_remote(
        _as_str(raw["default_remote"], "configuration.default_remote")
    )
    landed_ref = _validate_full_ref(
        _as_str(raw["default_landed_ref"], "configuration.default_landed_ref"),
        "default landed ref",
    )
    liveness_relative, liveness_command = _relative_inside(
        root,
        _as_str(raw["liveness_command"], "configuration.liveness_command"),
        "liveness command",
    )
    del liveness_relative
    if (
        not liveness_command.is_file()
        or liveness_command.is_symlink()
        or (
            liveness_command.suffix != ".py"
            and not os.access(liveness_command, os.X_OK)
        )
    ):
        raise StateError(
            f"configured liveness command is missing, not runnable, or unsafe: {liveness_command}"
        )
    liveness_batch_command: Path | None = None
    if "liveness_batch_command" in raw:
        _batch_relative, liveness_batch_command = _relative_inside(
            root,
            _as_str(
                raw["liveness_batch_command"],
                "configuration.liveness_batch_command",
            ),
            "batch liveness command",
        )
        if (
            not liveness_batch_command.is_file()
            or liveness_batch_command.is_symlink()
            or (
                liveness_batch_command.suffix != ".py"
                and not os.access(liveness_batch_command, os.X_OK)
            )
        ):
            raise StateError(
                "configured batch liveness command is missing, not runnable, or "
                f"unsafe: {liveness_batch_command}"
            )
    cap = raw.get("max_active_slots")
    cache_globs = (
        ()
        if "cache_globs" not in raw
        else _string_tuple(
            raw["cache_globs"], "configuration.cache_globs", _validate_cache_glob
        )
    )
    repo_cache_globs = (
        ()
        if "repo_cache_globs" not in raw
        else _cache_glob_groups(
            raw["repo_cache_globs"], "configuration.repo_cache_globs"
        )
    )
    post_provision_hooks = (
        ()
        if "post_provision_hooks" not in raw
        else _string_tuple(
            raw["post_provision_hooks"],
            "configuration.post_provision_hooks",
            _validate_hook,
            unique=False,
        )
    )
    salvage_push_remotes = (
        ()
        if "salvage_push_remotes" not in raw
        else _string_tuple(
            raw["salvage_push_remotes"],
            "configuration.salvage_push_remotes",
            _validate_salvage_push_remote,
        )
    )
    disk_keys = (
        "disk_advisory_bytes",
        "disk_provisioning_floor_bytes",
        "disk_emergency_bytes",
    )
    present_disk_keys = [key for key in disk_keys if key in raw]
    if present_disk_keys and len(present_disk_keys) != len(disk_keys):
        raise StateError(
            "configuration disk thresholds must supply advisory, provisioning floor, "
            "and emergency bytes together"
        )
    disk_values: tuple[int | None, int | None, int | None]
    if present_disk_keys:
        advisory = _as_int(raw[disk_keys[0]], f"configuration.{disk_keys[0]}", minimum=1)
        provisioning = _as_int(
            raw[disk_keys[1]], f"configuration.{disk_keys[1]}", minimum=1
        )
        emergency = _as_int(raw[disk_keys[2]], f"configuration.{disk_keys[2]}", minimum=1)
        if not emergency < provisioning < advisory:
            raise StateError(
                "configuration disk thresholds must satisfy "
                "emergency < provisioning floor < advisory"
            )
        disk_values = advisory, provisioning, emergency
    else:
        disk_values = None, None, None
    config = Config(
        root=root,
        config_path=path,
        worktrees=worktrees,
        control=control,
        machine=machine,
        default_remote=remote,
        default_landed_ref=landed_ref,
        heartbeat_ttl_seconds=_as_int(
            raw["heartbeat_ttl_seconds"],
            "configuration.heartbeat_ttl_seconds",
            minimum=1,
        ),
        liveness_command=liveness_command,
        liveness_batch_command=liveness_batch_command,
        max_active_slots=(
            None
            if cap is None
            else _as_int(cap, "configuration.max_active_slots", minimum=0)
        ),
        layout=layout,
        cache_globs=cache_globs,
        repo_cache_globs=repo_cache_globs,
        post_provision_hooks=post_provision_hooks,
        salvage_push_remotes=salvage_push_remotes,
        disk_advisory_bytes=disk_values[0],
        disk_provisioning_floor_bytes=disk_values[1],
        disk_emergency_bytes=disk_values[2],
        slot_representation=_parse_slot_representation(raw),
        image_settings=_parse_image_settings(raw),
        sandbox_settings=_parse_sandbox_settings(raw),
    )
    _activate_representation(config)
    return config


def _parse_slot_representation(raw: Mapping[str, object]) -> str:
    value = raw.get("slot_representation", "worktree")
    if value not in SLOT_REPRESENTATIONS:
        raise StateError(
            f"configuration.slot_representation must be one of "
            f"{', '.join(SLOT_REPRESENTATIONS)}, not {value!r}"
        )
    return str(value)


def _parse_image_settings(raw: Mapping[str, object]) -> slotimage.ImageSettings:
    value = raw.get("image")
    if value is None:
        return slotimage.ImageSettings()
    section = _as_mapping(value, "configuration.image")
    _exact_keys(
        section,
        set(),
        frozenset({"ceiling_bytes", "state_ceiling_bytes", "backend"}),
        "configuration.image",
    )
    defaults = slotimage.ImageSettings()
    backend = section.get("backend", defaults.backend)
    if backend not in slotimage.BACKENDS:
        raise StateError(
            f"configuration.image.backend must be one of {', '.join(slotimage.BACKENDS)}"
        )
    return slotimage.ImageSettings(
        ceiling_bytes=_as_int(
            section.get("ceiling_bytes", defaults.ceiling_bytes),
            "configuration.image.ceiling_bytes",
            minimum=GIB,
        ),
        state_ceiling_bytes=_as_int(
            section.get("state_ceiling_bytes", defaults.state_ceiling_bytes),
            "configuration.image.state_ceiling_bytes",
            minimum=GIB,
        ),
        backend=str(backend),
    )


def _parse_sandbox_settings(raw: Mapping[str, object]) -> sandbox.SandboxSettings:
    value = raw.get("sandbox")
    if value is None:
        return sandbox.SandboxSettings()
    try:
        return sandbox.settings_from_obj(_as_mapping(value, "configuration.sandbox"))
    except sandbox.SandboxError as exc:
        raise StateError(str(exc)) from exc


#: Mount points and sources that are this project's own slot-image mounts. The
#: process-use census ignores exactly these mount lines: a slot's own storage is
#: not evidence that anything is using the slot.
_OWNED_REPRESENTATION_MOUNTS: frozenset[tuple[Path, str]] = frozenset()


def _activate_representation(config: Config) -> None:
    """Mount any image-backed slot whose image is not mounted, then note owned mounts.

    Runs whenever a configuration is loaded, so that after a reboot (or a crash
    between unmount and remount during relocation) every image-backed slot is
    back at its recorded location before any lifecycle logic inspects it.
    """

    global _OWNED_REPRESENTATION_MOUNTS
    slotimage.register_layout(
        config.control, lambda slot_type, slot: _slot_directory(config, slot, slot_type)
    )
    if not slotimage.images_root(config.control).exists():
        _OWNED_REPRESENTATION_MOUNTS = frozenset()
        return
    try:
        for action in slotimage.ensure_all_mounted(config.control):
            print(f"wrkslots: {action}", file=sys.stderr)
    except slotimage.ImageError as exc:
        print(f"wrkslots: WARNING: slot image not mounted: {exc}", file=sys.stderr)
    _OWNED_REPRESENTATION_MOUNTS = slotimage.owned_mounts(config.control)


def _owned_mount_line(line: str) -> bool:
    if not _OWNED_REPRESENTATION_MOUNTS:
        return False
    left, separator, right = line.partition(" - ")
    if not separator:
        return False
    left_fields = left.split()
    right_fields = right.split()
    if len(left_fields) < 5 or len(right_fields) < 2:
        return False
    key = (_mountinfo_path(left_fields[4]), str(_mountinfo_path(right_fields[1])))
    return key in _OWNED_REPRESENTATION_MOUNTS


#: Control-directory entries that hold slot storage rather than being slots:
#: the disk images, the box's per-slot private state, and the default local
#: salvage bundles. In the nested layout they sit beside the slot directories.
_REPRESENTATION_DIRECTORIES = (
    slotimage.IMAGES_DIRECTORY,
    "slot-state",
    "box-state",
    _LOCAL_SALVAGE_DIRECTORY,
)


def _is_representation_directory(config: Config, entry: Path) -> bool:
    return entry.parent == config.control and entry.name in _REPRESENTATION_DIRECTORIES


def _slot_image_at(config: Config, path: Path) -> slotimage.SlotImage | None:
    if not slotimage.images_root(config.control).exists():
        return None
    try:
        return slotimage.image_for_location(config.control, path)
    except slotimage.ImageError as exc:
        raise Refusal(f"cannot read slot image records: {exc}") from exc


def _refresh_owned_mounts(config: Config) -> None:
    global _OWNED_REPRESENTATION_MOUNTS
    _OWNED_REPRESENTATION_MOUNTS = slotimage.owned_mounts(config.control)


def _rename_slot_path(config: Config, source: Path, destination: Path) -> None:
    """Rename a slot directory, relocating its image mount when it has one.

    A mount point cannot be renamed. For an image-backed slot the image is
    unmounted, the empty mount point renamed, and the image mounted again at
    the destination. Failures surface as OSError so every caller's existing
    rename error handling still applies.
    """

    image = _slot_image_at(config, source)
    if image is None:
        os.rename(source, destination)
        return
    try:
        slotimage.relocate(image, destination)
    except slotimage.ImageError as exc:
        raise OSError(errno.EBUSY, f"cannot relocate slot image: {exc}") from exc
    finally:
        _refresh_owned_mounts(config)


def _remove_slot_directory(config: Config, path: Path) -> None:
    """Remove an emptied slot directory: rmdir, or destroy its image.

    Raises OSError with the same meaning as rmdir when the slot still holds
    content, so callers keep their refusal wording.
    """

    image = _slot_image_at(config, path)
    if image is None:
        path.rmdir()
        return
    try:
        slotimage.destroy(image)
    except slotimage.ImageError as exc:
        raise OSError(errno.ENOTEMPTY, str(exc)) from exc
    finally:
        _refresh_owned_mounts(config)


def _provision_slot_image(
    config: Config, slot: str, slot_type: str, slot_path: Path
) -> slotimage.SlotImage:
    try:
        image = slotimage.provision(
            config.control, slot_type, slot, slot_path, config.image_settings
        )
    except slotimage.ImageError as exc:
        raise Refusal(
            f"cannot provision the disk image for slot {slot}: {exc}",
            remedy=(
                "check `sudo -n true` or fuse2fs availability, or create this slot as "
                "plain worktrees with `create --representation worktree`"
            ),
        ) from exc
    _refresh_owned_mounts(config)
    return image


def _slot_representation_of(config: Config, slot: str, slot_type: str) -> str:
    try:
        image = slotimage.load(config.control, slot_type, slot)
    except slotimage.ImageError as exc:
        raise Refusal(str(exc)) from exc
    return "worktree" if image is None else "image"


def _init_representation(
    args: argparse.Namespace, config_path: Path
) -> tuple[str, dict[str, object] | None]:
    """Choose the representation and image section init should write.

    A new project defaults to images. An existing configuration keeps what it
    has (absent means worktree) so rerunning init after an upgrade neither
    conflicts with nor silently converts a live project.
    """

    existing: Mapping[str, object] | None = None
    if config_path.exists() and not config_path.is_symlink():
        try:
            existing = _read_config(config_path)
        except StateError:
            existing = None
    if args.slot_representation is not None:
        representation = str(args.slot_representation)
    elif existing is not None:
        representation = str(existing.get("slot_representation", "worktree"))
    else:
        # WRKSLOTS_INIT_REPRESENTATION changes the default for a NEW project
        # only (for example a test suite that exercises plain worktrees).
        representation = os.environ.get("WRKSLOTS_INIT_REPRESENTATION", "image")
        if representation not in SLOT_REPRESENTATIONS:
            raise Refusal(
                "WRKSLOTS_INIT_REPRESENTATION must be worktree or image, "
                f"not {representation!r}"
            )
    image_section: dict[str, object] | None = None
    if existing is not None and isinstance(existing.get("image"), dict):
        raw_image = existing.get("image")
        assert isinstance(raw_image, dict)
        image_section = {str(key): value for key, value in raw_image.items()}
    if args.image_ceiling_gib is not None or args.image_backend is not None:
        image_section = dict(image_section or {})
        if args.image_ceiling_gib is not None:
            if args.image_ceiling_gib < 1:
                raise Refusal("--image-ceiling-gib must be at least 1")
            image_section["ceiling_bytes"] = args.image_ceiling_gib * GIB
        if args.image_backend is not None:
            image_section["backend"] = args.image_backend
    return representation, image_section


def _init_sandbox_section(config_path: Path) -> dict[str, object] | None:
    """The sandbox section init writes: every default for a new project.

    An existing configuration keeps exactly what it has (possibly nothing), so
    rerunning init never conflicts; `wrkslots sandbox write-defaults` fills in
    missing keys explicitly.
    """

    if not config_path.exists() and not config_path.is_symlink():
        return sandbox.default_config_obj()
    try:
        loaded = _read_config(config_path)
    except StateError:
        return None
    section = loaded.get("sandbox")
    if isinstance(section, dict):
        return {str(key): value for key, value in section.items()}
    return None


def _init_salvage_push_remotes(
    args: argparse.Namespace, config_path: Path
) -> tuple[str, ...]:
    """The salvage push allow list init writes.

    Explicit --salvage-push-remote flags replace the list. Without them an
    existing configuration keeps what it has, so rerunning init never drops an
    allowance; a new project allows no remote.
    """

    if args.salvage_push_remote:
        remotes = tuple(
            _validate_salvage_push_remote(value) for value in args.salvage_push_remote
        )
        if len(remotes) != len(set(remotes)):
            raise Refusal("salvage push remotes must not contain duplicates")
        return remotes
    if not config_path.exists() or config_path.is_symlink():
        return ()
    try:
        loaded = _read_config(config_path)
    except StateError:
        return ()
    existing = loaded.get("salvage_push_remotes")
    if isinstance(existing, list) and all(isinstance(item, str) for item in existing):
        return tuple(str(item) for item in existing)
    return ()


def _requested_representation(config: Config, args: argparse.Namespace) -> str:
    requested = getattr(args, "representation", None)
    if requested in (None, "config"):
        return config.slot_representation
    if requested not in SLOT_REPRESENTATIONS:
        raise Refusal(f"--representation must be config, worktree, or image, not {requested!r}")
    return str(requested)


def _is_owned_image_root(path: Path) -> bool:
    target = Path(os.path.abspath(path))
    return any(mount_point == target for mount_point, _source in _OWNED_REPRESENTATION_MOUNTS)


def _load_new_slot_config(args: argparse.Namespace, operation: str) -> Config:
    """Load the shard for an operation that creates a new active row.

    A checked-in configuration can outlive the host on which it was written.
    Silently using that stale default makes a locally owned slot look foreign
    immediately after allocation. Deliberate CLI/environment overrides retain
    their existing cross-shard semantics; only an implicit config-file default
    must agree with the current host.
    """

    machine_was_implicit = (
        args.machine is None and os.environ.get("WRKSLOTS_MACHINE") is None
    )
    config = _load_config(args.project_root, args.machine)
    if machine_was_implicit:
        local_machine = _short_hostname()
        if config.machine != local_machine:
            raise Refusal(
                f"refusing {operation}: configured machine shard {config.machine!r} "
                f"differs from current host {local_machine!r}, and no machine override "
                f"was supplied. Pass global '--machine {local_machine}' before the "
                "subcommand, or inspect the existing shards and deliberately repair or "
                "reinitialize the configuration before allocating a slot"
            )
    return config


def _active_path(config: Config, machine: str | None = None) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    return config.control / f"ACTIVE.{selected}.json"


def _landed_ref_for_remote(config: Config, remote: str) -> str:
    prefix = f"refs/remotes/{config.default_remote}/"
    if not config.default_landed_ref.startswith(prefix):
        raise StateError(f"configured landed ref must be under {prefix}")
    return f"refs/remotes/{remote}/{config.default_landed_ref.removeprefix(prefix)}"


def _archive_path(config: Config, machine: str | None = None) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    return config.control / f"ARCHIVED.{selected}.json"


def _journal_path(config: Config, machine: str | None = None) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    return config.control / f"ACTIVE.{selected}.journal"


def _create_journal_path(
    config: Config, slot: str, machine: str | None = None
) -> Path:
    """Return the collision-free journal path for one create target."""

    selected = machine or config.machine
    _validate_name(selected, "machine")
    _validate_name(slot, "slot")
    return config.control / (
        f"CREATE.{len(selected)}.{selected}.{len(slot)}.{slot}.journal"
    )


def _finish_journal_path(
    config: Config, slot: str, machine: str | None = None
) -> Path:
    """Return the collision-free journal path for one finish target."""

    selected = machine or config.machine
    _validate_name(selected, "machine")
    _validate_name(slot, "slot")
    return config.control / (
        f"FINISH.{len(selected)}.{selected}.{len(slot)}.{slot}.journal"
    )


def _validate_batch_seal_journal_path(
    config: Config, machine: str | None = None
) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    return config.control / f"VALIDATE-BATCH-SEAL.{selected}.journal"


def _hold_path(config: Config, slot: str, machine: str | None = None) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    _validate_name(slot, "slot")
    return config.control / f"HOLD.{len(selected)}.{selected}.{slot}.json"


def _handoff_sidecar_path(
    config: Config,
    slot: str,
    generation: int,
    machine: str | None = None,
) -> Path:
    """Return a collision-free handoff path outside every managed checkout."""

    selected = machine or config.machine
    _validate_name(selected, "machine")
    _validate_name(slot, "slot")
    if generation <= 0:
        raise StateError("handoff sidecar generation must be positive")
    return config.control / (
        f"HANDOFF.{len(selected)}.{selected}.{len(slot)}.{slot}.{generation}.json"
    )


def _load_hold_snapshot(
    config: Config, slot: str, machine: str | None = None
) -> dict[str, object] | None:
    selected = machine or config.machine
    path = _hold_path(config, slot, selected)
    if not path.exists() and not path.is_symlink():
        return None
    raw = _as_mapping(_read_json(path, "slot hold"), "slot hold")
    _exact_keys(raw, {"schema", "machine", "slot", "held_at", "reason"}, set(), "slot hold")
    if _as_int(raw["schema"], "slot hold.schema") != HOLD_SCHEMA:
        raise StateError(f"unsupported slot hold schema in {path}")
    if _as_str(raw["machine"], "slot hold.machine") != selected:
        raise StateError(f"slot hold machine does not match its filename: {path}")
    if _as_str(raw["slot"], "slot hold.slot") != slot:
        raise StateError(f"slot hold name does not match its filename: {path}")
    _parse_timestamp(_as_str(raw["held_at"], "slot hold.held_at"), "slot hold.held_at")
    if not _as_str(raw["reason"], "slot hold.reason").strip():
        raise StateError(f"slot hold has an empty reason: {path}")
    return dict(raw)


@dataclasses.dataclass(frozen=True)
class _HoldResult:
    value: dict[str, object] | None
    error: str | None = None


def _holds_from_events(
    events: Sequence[Mapping[str, object]],
    machine: str,
    slots: AbstractSet[str],
) -> dict[str, dict[str, object]]:
    """Replay one machine's hold events once for all requested slots."""

    holds: dict[str, dict[str, object]] = {}
    for event in events:
        payload = _as_mapping(event["payload"], "append-only event.payload")
        kind = event.get("kind")
        if kind == "state-imported":
            for item in _as_list(payload.get("holds", []), "imported holds"):
                candidate = dict(_as_mapping(item, "imported hold"))
                slot = candidate.get("slot")
                if isinstance(slot, str) and slot in slots:
                    holds[slot] = candidate
        else:
            slot = payload.get("slot")
            if not isinstance(slot, str) or slot not in slots:
                continue
            if kind == "slot-held":
                holds[slot] = {
                    "schema": HOLD_SCHEMA,
                    "machine": machine,
                    "slot": slot,
                    "held_at": event["recorded_at"],
                    "reason": payload.get("reason"),
                }
            elif kind == "slot-hold-released":
                holds.pop(slot, None)
    return holds


def _load_record_holds(
    config: Config, states: Sequence[ActiveState]
) -> dict[tuple[str, str], _HoldResult]:
    """Load every active record's hold while replaying each machine log once."""

    results: dict[tuple[str, str], _HoldResult] = {}
    for state in states:
        slots = {record.slot for record in state.slots}
        try:
            events = _load_events(config, state.machine)
            if events:
                holds = _holds_from_events(events, state.machine, slots)
                for slot in slots:
                    results[(state.machine, slot)] = _HoldResult(holds.get(slot))
                continue
        except Refusal as exc:
            for slot in slots:
                results[(state.machine, slot)] = _HoldResult(None, str(exc))
            continue
        for slot in slots:
            try:
                hold = _load_hold_snapshot(config, slot, state.machine)
            except Refusal as exc:
                results[(state.machine, slot)] = _HoldResult(None, str(exc))
            else:
                results[(state.machine, slot)] = _HoldResult(hold)
    return results


def _load_hold(
    config: Config,
    slot: str,
    machine: str | None = None,
    *,
    events: Sequence[Mapping[str, object]] | None = None,
) -> dict[str, object] | None:
    selected = machine or config.machine
    selected_events = _load_events(config, selected) if events is None else events
    if not selected_events:
        return _load_hold_snapshot(config, slot, selected)
    return _holds_from_events(selected_events, selected, {slot}).get(slot)


def _assert_not_held(config: Config, record: ActiveRecord) -> None:
    hold = _load_hold(config, record.slot, record.machine)
    if hold is not None:
        raise Refusal(
            f"slot {record.slot} is held: {_as_str(hold['reason'], 'slot hold.reason')}; "
            f"run 'wrkslots unhold {record.slot}' only when the hold is no longer needed"
        )


def _assert_absent_validate_rows_not_held(config: Config, records: Sequence[ActiveRecord]) -> None:
    slots = {record.slot for record in records}
    events = _load_events(config, config.machine)
    if not events:
        for record in records:
            hold_snapshot = _load_hold_snapshot(config, record.slot, record.machine)
            if hold_snapshot is not None:
                raise Refusal(
                    f"slot {record.slot} is held: "
                    f"{_as_str(hold_snapshot['reason'], 'slot hold.reason')}; run 'wrkslots "
                    f"unhold {record.slot}' only when the hold is no longer needed"
                )
        return
    holds: dict[str, Mapping[str, object]] = {}
    for event in events:
        payload = _as_mapping(event["payload"], "append-only event.payload")
        kind = event.get("kind")
        if kind == "state-imported":
            for item in _as_list(payload.get("holds", []), "imported holds"):
                hold = _as_mapping(item, "imported hold")
                slot = hold.get("slot")
                if isinstance(slot, str) and slot in slots:
                    holds[slot] = hold
        else:
            slot = payload.get("slot")
            if not isinstance(slot, str) or slot not in slots:
                continue
            if kind == "slot-held":
                holds[slot] = {
                    "reason": payload.get("reason"),
                }
            elif kind == "slot-hold-released":
                holds.pop(slot, None)
    for record in records:
        selected_hold = holds.get(record.slot)
        if selected_hold is not None:
            raise Refusal(
                f"slot {record.slot} is held: "
                f"{_as_str(selected_hold.get('reason'), 'slot hold.reason')}; run 'wrkslots "
                f"unhold {record.slot}' only when the hold is no longer needed"
            )


def _lock_path(subject: Path) -> Path:
    if subject.name == "ACTIVE":
        return subject.parent / "ACTIVE.global.lock"
    return subject.with_name(f"{subject.name}.lock")


@contextlib.contextmanager
def _locked(subject: Path, *, exclusive: bool, wait_seconds: float) -> Iterator[None]:
    path = _lock_path(subject)
    if path.parent.is_symlink() or not path.parent.is_dir():
        raise Refusal(f"unsafe lock parent: {path.parent}")
    try:
        fd = os.open(
            path,
            os.O_RDWR | os.O_CREAT | os.O_CLOEXEC | os.O_NOFOLLOW,
            0o600,
        )
    except OSError as exc:
        raise Refusal(f"cannot open state lock {path}: {exc}") from exc
    try:
        mode = os.fstat(fd).st_mode
    except OSError as exc:
        os.close(fd)
        raise Refusal(f"cannot inspect state lock {path}: {exc}") from exc
    if not stat.S_ISREG(mode):
        os.close(fd)
        raise Refusal(f"state lock is not a regular file: {path}")
    operation = fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH
    deadline = time.monotonic() + wait_seconds
    try:
        while True:
            try:
                fcntl.flock(fd, operation | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise _LockBusy(
                        f"state lock is busy for {subject}; retry after the current command exits"
                    ) from exc
                time.sleep(min(0.05, max(0.0, deadline - time.monotonic())))
        yield
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        finally:
            os.close(fd)


# A caller that already holds the configuration lock -- an exclusive flock on the project root
# directory -- and runs a wrkslots mutation would otherwise make that mutation refuse itself:
# wrkslots opens its own descriptor, which is a second open file description, so its flock
# conflicts with the caller's, and every such mutation refused as "configuration lock is busy".
# Removal and recovery cannot simply inherit the caller's descriptor either, because a launcher
# may re-run them in a host-context service that is not the caller's descendant.
#
# The caller therefore names, in this variable, the descriptor number it holds the flock on in
# ITS OWN descriptor table, and must be the process the command names with --coordinator-pid.
# wrkslots adopts the lock only after proving all of the following, and refuses otherwise; it
# never falls through to a second acquire:
#   * the coordinator is authenticated exactly as removal authenticates it (an ancestor of this
#     process, or the generation the host-context handoff bound);
#   * a pidfd opened on that PID names that authenticated generation: the generation is read
#     AFTER the pidfd is opened, and a pidfd cannot be redirected by PID reuse;
#   * pidfd_getfd(2) duplicates the named descriptor into this process. The duplicate shares the
#     coordinator's open file description, so every later check reads the one object the lock
#     belongs to, and nothing the coordinator does to its descriptor table afterwards can make
#     two checks describe two different files;
#   * the duplicate is the very directory the lock is taken on (device and inode);
#   * /proc/self/fdinfo of the duplicate shows an exclusive flock on that inode. fdinfo lists
#     only the locks owned by that open file description, so this is the kernel saying that the
#     coordinator's descriptor holds the lock -- not merely that someone does;
#   * a non-blocking exclusive flock through a new descriptor still fails.
# Every entry re-proves it. The duplicate is held for the whole locked section and then closed,
# never unlocked: flock(LOCK_UN) on it would release the coordinator's lock too. While it is
# held, the open file description -- and with it the lock -- outlives the coordinator closing
# its own descriptor or exiting, so the section stays excluded to its end.
#
# The coordinator, which is authenticated and therefore trusted, must keep one promise: while a
# command it lent the descriptor to may still run, it releases the lock only by closing its
# descriptor, never with flock(LOCK_UN). An explicit unlock acts on the shared open file
# description, so no descriptor this process holds could keep the lock.
#
# pidfd_getfd needs ptrace-attach permission over the coordinator: the same user, a dumpable
# process, and no Yama restriction that forbids attaching to a non-descendant. Without it the
# duplicate fails and the command refuses.
HELD_CONFIG_LOCK_FD_ENV = "WRKSLOTS_HELD_CONFIG_LOCK_FD"
_FDINFO_FLOCK_LINE = re.compile(
    r"^lock:\s+\d+:\s+FLOCK\s+ADVISORY\s+(?P<mode>READ|WRITE)\s+\S+\s+"
    r"[0-9a-f]+:[0-9a-f]+:(?P<inode>\d+)\s"
)
# pidfd_getfd(2) has no wrapper in the os module. Its number is 438 on both architectures listed
# here; other architectures number it differently, so they refuse rather than guess.
_PIDFD_GETFD_SYSCALL = {"x86_64": 438, "aarch64": 438}


@dataclasses.dataclass
class _HeldConfigLockClaim:
    """The caller's lock delegation for one command, and its coordinator once authenticated."""

    raw: str
    coordinator_pid: int | None
    coordinator: ProcessIdentity | None = None


_held_config_lock_claim: _HeldConfigLockClaim | None = None


def _take_held_config_lock_variable() -> str | None:
    """Remove the delegation from the environment so no process this command starts sees it."""

    global _held_config_lock_claim
    _held_config_lock_claim = None
    return os.environ.pop(HELD_CONFIG_LOCK_FD_ENV, None)


def _bind_held_config_lock(raw: str | None, args: argparse.Namespace) -> None:
    global _held_config_lock_claim
    if raw is None:
        _held_config_lock_claim = None
        return
    coordinator_pid = getattr(args, "coordinator_pid", None)
    _held_config_lock_claim = _HeldConfigLockClaim(
        raw, coordinator_pid if isinstance(coordinator_pid, int) else None
    )


def _directory_identity_for_lock(lock_path: Path) -> os.stat_result:
    try:
        fd = os.open(
            lock_path,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
        )
    except OSError as exc:
        raise Refusal(f"cannot open configuration lock {lock_path}: {exc}") from exc
    try:
        return os.fstat(fd)
    except OSError as exc:
        raise Refusal(f"cannot inspect configuration lock {lock_path}: {exc}") from exc
    finally:
        os.close(fd)


def _pidfd_getfd(pidfd: int, target_fd: int) -> int:
    """Duplicate ``target_fd`` of the process ``pidfd`` names, as a close-on-exec descriptor.

    The duplicate refers to the same open file description as the original, as dup(2) would.
    Raises OSError with the kernel's errno.
    """

    number = _PIDFD_GETFD_SYSCALL.get(os.uname().machine)
    if number is None:
        raise OSError(
            errno.ENOSYS,
            f"pidfd_getfd has no known system call number on {os.uname().machine}",
        )
    syscall = ctypes.CDLL(None, use_errno=True).syscall
    syscall.restype = ctypes.c_long
    ctypes.set_errno(0)
    result = syscall(
        ctypes.c_long(number), ctypes.c_int(pidfd), ctypes.c_int(target_fd), ctypes.c_uint(0)
    )
    if result < 0:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error))
    return int(result)


def _adopt_held_config_lock(claim: _HeldConfigLockClaim, lock_path: Path) -> int:
    """Prove the coordinator holds the lock and return a duplicate of its lock descriptor.

    The caller holds the returned descriptor for the locked section, then closes it without
    unlocking.
    """

    raw = claim.raw

    def refuse(reason: str) -> NoReturn:
        raise Refusal(
            f"{HELD_CONFIG_LOCK_FD_ENV}={raw!r} does not prove the caller holds the "
            f"configuration lock for {lock_path}: {reason}",
            remedy=(
                f"name in {HELD_CONFIG_LOCK_FD_ENV} the descriptor that holds the exclusive "
                f"flock on {lock_path} in the --coordinator-pid process, or unset it so "
                "wrkslots takes the lock itself"
            ),
        )

    if not (raw.isascii() and raw.isdigit()):
        refuse("it is not a descriptor number")
    fd = int(raw)
    if fd < 3:
        refuse("standard input, output and error are never a lock descriptor")
    pid = claim.coordinator_pid
    if pid is None:
        refuse("the descriptor is read from the --coordinator-pid process, and this command names none")
    if claim.coordinator is None:
        try:
            claim.coordinator = _capture_remove_processes(pid)[0]
        except Refusal as exc:
            refuse(f"coordinator PID {pid} is not authenticated: {exc}")
    coordinator = claim.coordinator
    expected = _directory_identity_for_lock(lock_path)
    try:
        pidfd = os.pidfd_open(pid)
    except OSError as exc:
        refuse(f"coordinator PID {pid} is gone ({exc.strerror})")
    try:
        # The pidfd names whichever process held the PID when it was opened. Reading the
        # generation afterwards proves that was the authenticated one; from here on PID reuse
        # cannot lend this command another process's descriptor.
        try:
            current = _read_process_identity(pid)
        except Refusal as exc:
            refuse(f"coordinator PID {pid} is gone: {exc}")
        if current != coordinator:
            refuse(f"coordinator PID {pid} is no longer the authenticated process generation")
        try:
            held = _pidfd_getfd(pidfd, fd)
        except OSError as exc:
            if exc.errno == errno.EBADF:
                refuse(f"descriptor {fd} is not open in coordinator PID {pid} ({exc.strerror})")
            if exc.errno == errno.ESRCH:
                refuse(f"coordinator PID {pid} exited before its descriptor was read")
            refuse(
                f"cannot duplicate descriptor {fd} of coordinator PID {pid} ({exc.strerror}); "
                "this needs ptrace-attach permission over the coordinator"
            )
    finally:
        os.close(pidfd)
    try:
        try:
            observed = os.fstat(held)
        except OSError as exc:
            refuse(f"cannot inspect descriptor {fd} of coordinator PID {pid} ({exc.strerror})")
        if not stat.S_ISDIR(observed.st_mode) or (observed.st_dev, observed.st_ino) != (
            expected.st_dev,
            expected.st_ino,
        ):
            refuse(
                f"descriptor {fd} of coordinator PID {pid} is device {observed.st_dev} inode "
                f"{observed.st_ino}, not the configuration lock directory (device "
                f"{expected.st_dev} inode {expected.st_ino})"
            )
        try:
            fdinfo = Path(f"/proc/self/fdinfo/{held}").read_text(encoding="ascii")
        except (OSError, UnicodeDecodeError) as exc:
            refuse(
                f"cannot read the lock state of descriptor {fd} of coordinator PID {pid}: {exc}"
            )
        # The device is NOT compared here: fdinfo prints the superblock device, which differs
        # from st_dev on filesystems with per-subvolume anonymous devices such as btrfs
        # (measured: fdinfo 00:2f against st_dev 0:50 for one /tmp directory). The inode is
        # matched as a sanity check; fdinfo already restricts itself to this description's locks.
        modes: set[str] = set()
        for line in fdinfo.splitlines():
            match = _FDINFO_FLOCK_LINE.match(line)
            if match is not None and int(match["inode"]) == expected.st_ino:
                modes.add(match["mode"])
        if "WRITE" not in modes:
            refuse(
                f"descriptor {fd} of coordinator PID {pid} holds no exclusive flock"
                + (" (only a shared one)" if "READ" in modes else "")
            )
        probe_fd = os.open(
            lock_path,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
        )
        try:
            try:
                fcntl.flock(probe_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                return held
            fcntl.flock(probe_fd, fcntl.LOCK_UN)
        finally:
            os.close(probe_fd)
        refuse("the lock was free when probed, so the coordinator no longer holds it")
    except BaseException:
        # Close only: an unlock would act on the coordinator's open file description.
        os.close(held)
        raise


@contextlib.contextmanager
def _locked_config(path: Path, wait_seconds: float) -> Iterator[None]:
    lock_path = path.parent
    claim = _held_config_lock_claim
    if claim is not None:
        held = _adopt_held_config_lock(claim, lock_path)
        try:
            yield
        finally:
            # Close, never unlock: the duplicate shares the coordinator's open file description,
            # so flock(LOCK_UN) here would release the coordinator's lock as well.
            os.close(held)
        return
    try:
        fd = os.open(
            lock_path,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
        )
    except OSError as exc:
        raise Refusal(f"cannot open configuration lock {lock_path}: {exc}") from exc
    try:
        mode = os.fstat(fd).st_mode
    except OSError as exc:
        os.close(fd)
        raise Refusal(f"cannot inspect configuration lock {lock_path}: {exc}") from exc
    if not stat.S_ISDIR(mode):
        os.close(fd)
        raise Refusal(f"configuration lock is not a directory: {lock_path}")
    deadline = time.monotonic() + wait_seconds
    try:
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise _LockBusy(
                        f"configuration lock is busy for {lock_path}; retry after the "
                        "other wrkslots mutation exits"
                    ) from exc
                time.sleep(min(0.05, max(0.0, deadline - time.monotonic())))
        yield
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        finally:
            os.close(fd)


def _remaining_lock_wait(deadline: float) -> float:
    return max(0.0, deadline - time.monotonic())


@contextlib.contextmanager
def _mutation_locks(
    config: Config,
    wait_seconds: float,
    *,
    deadline: float | None = None,
) -> Iterator[None]:
    effective_deadline = (
        time.monotonic() + wait_seconds if deadline is None else deadline
    )
    with _locked_config(config.config_path, _remaining_lock_wait(effective_deadline)):
        current = _load_config(str(config.root), config.machine)
        if current != config:
            raise Refusal(
                "configuration changed while this command was starting; rerun so it "
                "uses one coherent policy"
            )
        global_subject = config.control / "ACTIVE"
        with _locked(
            global_subject,
            exclusive=True,
            wait_seconds=_remaining_lock_wait(effective_deadline),
        ):
            with _locked(
                _active_path(config),
                exclusive=True,
                wait_seconds=_remaining_lock_wait(effective_deadline),
            ):
                yield


def _fsync_directory(directory: Path) -> None:
    fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _atomic_write_json(path: Path, payload: object) -> None:
    text = json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    _atomic_write_bytes(path, text.encode("utf-8"))


def _atomic_write_bytes(path: Path, contents: bytes) -> None:
    _refuse_symlink(path, "state file")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise Refusal(f"cannot prepare state directory {path.parent}: {exc}") from exc
    prefix = f"{path.name}.tmp."
    leftovers = sorted(path.parent.glob(f"{prefix}*"))
    if leftovers:
        raise StateError(
            f"partial state update exists for {path.name}: {leftovers[0]}; "
            "inspect it and use 'wrkslots recover'"
        )
    temp = path.parent / f"{prefix}{os.getpid()}.{uuid.uuid4().hex}"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC
    try:
        fd = os.open(temp, flags, 0o644)
    except OSError as exc:
        raise Refusal(f"cannot create temporary state file {temp}: {exc}") from exc
    try:
        with os.fdopen(fd, "wb", closefd=True) as handle:
            handle.write(contents)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
        _fsync_directory(path.parent)
    except OSError as exc:
        with contextlib.suppress(FileNotFoundError):
            temp.unlink()
        raise Refusal(f"cannot durably replace state file {path}: {exc}") from exc
    except BaseException:
        with contextlib.suppress(FileNotFoundError):
            temp.unlink()
        raise


def _verify_noreplace_handoff_move(
    source: Path,
    destination: Path,
    expected_contents: bytes,
    expected_identity: _RegularFileIdentity,
    label: str,
) -> None:
    """Verify a moved inode, restoring a raced destination without unlinking it."""

    failure: Refusal | StateError | None = None
    try:
        contents, identity = _read_regular_file_identity(
            destination, label, HANDOFF_SIDECAR_BYTES_LIMIT
        )
        if contents != expected_contents or identity != expected_identity:
            failure = StateError(
                f"{label} identity or content changed at its no-replace boundary"
            )
    except (Refusal, StateError) as exc:
        failure = exc
    if failure is not None:
        if (
            not source.exists()
            and not source.is_symlink()
            and (destination.exists() or destination.is_symlink())
        ):
            try:
                _rename_noreplace(
                    destination,
                    source,
                    f"restore raced {label}",
                )
                _fsync_directory(source.parent)
            except Refusal as restore:
                raise StateError(
                    f"{failure}; raced path also could not be restored: {restore}"
                ) from restore
        raise StateError(
            f"{failure}; preserved the raced artifact at {source} for recovery"
        ) from failure
    if source.exists() or source.is_symlink():
        raise StateError(
            f"{label} source pathname was recreated during publication; "
            f"preserved both {source} and {destination}"
        )


def _atomic_write_handoff_noreplace(path: Path, payload: object) -> None:
    """Durably publish a new sidecar without replacing any pathname occupant."""

    _refuse_symlink(path, "handoff sidecar")
    if path.exists():
        raise Refusal(f"handoff sidecar already exists and is immutable: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    prefix = f"{path.name}.tmp."
    leftovers = sorted(path.parent.glob(f"{prefix}*"))
    if leftovers:
        raise StateError(
            f"partial handoff sidecar publication exists: {leftovers[0]}; "
            "inspect it and use 'wrkslots recover'"
        )
    temp = path.parent / f"{prefix}{os.getpid()}.{uuid.uuid4().hex}"
    intended_contents = (
        json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    ).encode("utf-8")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC
    try:
        descriptor = os.open(temp, flags, 0o644)
        with os.fdopen(descriptor, "wb", closefd=True) as handle:
            handle.write(intended_contents)
            handle.flush()
            os.fsync(handle.fileno())
        _fsync_directory(path.parent)
        _interrupt_for_test("after-handoff-temp-write-before-snapshot")
        temp_contents, temp_identity = _read_regular_file_identity(
            temp, "handoff sidecar publication temp", HANDOFF_SIDECAR_BYTES_LIMIT
        )
        if temp_contents != intended_contents:
            raise StateError(
                f"handoff sidecar publication temp differs from its durable intent; "
                f"preserved it for recovery: {temp}"
            )
        _interrupt_for_test("before-handoff-sidecar-publish")
        _rename_noreplace(temp, path, "publish handoff sidecar")
        _fsync_directory(path.parent)
        _verify_noreplace_handoff_move(
            temp,
            path,
            temp_contents,
            temp_identity,
            "published handoff sidecar",
        )
    except Refusal:
        # The complete temp file is recovery evidence. Never unlink its pathname
        # after caller-controlled code had an opportunity to replace it.
        raise
    except OSError as exc:
        raise Refusal(f"cannot durably publish handoff sidecar {path}: {exc}") from exc


def _json_equal(left: object, right: object) -> bool:
    return json.dumps(
        left, sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ) == json.dumps(right, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def _recover_config_write(path: Path, payload: object) -> None:
    leftovers = sorted(path.parent.glob(f"{path.name}.tmp.*"))
    if not leftovers:
        return
    if path.exists() or path.is_symlink():
        existing = _read_config(path)
        if dict(existing) != payload:
            raise StateError(
                f"configuration temp file exists beside a different durable configuration: {leftovers[0]}"
            )
        for leftover in leftovers:
            leftover.unlink()
        _fsync_directory(path.parent)
        return
    matching: list[Path] = []
    for leftover in leftovers:
        try:
            candidate: object = _read_config(leftover, "configuration temp file")
        except StateError:
            leftover.unlink()
            continue
        if candidate != payload:
            raise StateError(
                f"configuration temp file records different init input: {leftover}"
            )
        matching.append(leftover)
    if len(matching) > 1:
        raise StateError("multiple complete configuration temp files require inspection")
    if matching:
        os.replace(matching[0], path)
        _fsync_directory(path.parent)
    else:
        _fsync_directory(path.parent)


def _remove_control_file(path: Path) -> None:
    _refuse_symlink(path, "control file")
    try:
        path.unlink()
        _fsync_directory(path.parent)
    except OSError as exc:
        raise Refusal(f"cannot remove control file {path}: {exc}") from exc


def _rename_noreplace(source: Path, destination: Path, label: str) -> None:
    """Atomically move one path without ever replacing the destination."""

    try:
        renameat2 = ctypes.CDLL(None, use_errno=True).renameat2
    except AttributeError as exc:
        raise Refusal(
            f"cannot {label}: atomic no-replace rename is unavailable"
        ) from exc
    renameat2.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    ctypes.set_errno(0)
    result = renameat2(
        _AT_FDCWD,
        os.fsencode(source),
        _AT_FDCWD,
        os.fsencode(destination),
        1,  # RENAME_NOREPLACE
    )
    if result == 0:
        return
    error = ctypes.get_errno()
    if error == errno.EEXIST:
        raise Refusal(
            f"cannot {label}: destination already exists; preserved both paths: "
            f"{source} and {destination}"
        )
    if error in (errno.ENOSYS, errno.EINVAL, errno.EOPNOTSUPP):
        raise Refusal(
            f"cannot {label}: filesystem lacks atomic no-replace rename support"
        )
    raise Refusal(
        f"cannot {label}: {os.strerror(error)}: {source} -> {destination}"
    )


def _identity_to_obj(owner: ProcessIdentity | None) -> object:
    if owner is None:
        return None
    return {
        "pid": owner.pid,
        "start_ticks": owner.start_ticks,
        "boot_id": owner.boot_id,
        "host_id": owner.host_id,
        "cgroup_path": owner.cgroup_path,
    }


def _identity_from_obj(value: object, label: str) -> ProcessIdentity | None:
    if value is None:
        return None
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {"pid", "start_ticks", "boot_id", "host_id", "cgroup_path"},
        set(),
        label,
    )
    identity = ProcessIdentity(
        pid=_as_int(raw["pid"], f"{label}.pid", minimum=1),
        start_ticks=_as_int(raw["start_ticks"], f"{label}.start_ticks", minimum=1),
        boot_id=_as_str(raw["boot_id"], f"{label}.boot_id"),
        host_id=_as_str(raw["host_id"], f"{label}.host_id"),
        cgroup_path=_as_str(raw["cgroup_path"], f"{label}.cgroup_path"),
    )
    if (
        not identity.boot_id
        or not identity.host_id
        or not identity.cgroup_path.startswith("/")
    ):
        raise StateError(f"{label} has an invalid boot, machine, or cgroup identity")
    return identity


def _handoff_to_obj(handoff: Handoff | None) -> object:
    if handoff is None:
        return None
    return {
        "recorded_at": handoff.recorded_at,
        "validation": list(handoff.validation),
        "limitations": list(handoff.limitations),
        "continuation": handoff.continuation,
    }


def _handoff_from_obj(value: object, label: str) -> Handoff | None:
    if value is None:
        return None
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {"recorded_at", "validation", "limitations", "continuation"},
        set(),
        label,
    )
    recorded_at = _as_str(raw["recorded_at"], f"{label}.recorded_at")
    _parse_timestamp(recorded_at, f"{label}.recorded_at")
    validation = tuple(
        _as_str(item, f"{label}.validation[{index}]")
        for index, item in enumerate(_as_list(raw["validation"], f"{label}.validation"))
    )
    limitations = tuple(
        _as_str(item, f"{label}.limitations[{index}]")
        for index, item in enumerate(_as_list(raw["limitations"], f"{label}.limitations"))
    )
    continuation = _as_str(raw["continuation"], f"{label}.continuation")
    if not validation or not continuation:
        raise StateError(f"{label} requires validation evidence and an exact continuation")
    return Handoff(recorded_at, validation, limitations, continuation)


def _handoff_artifact_to_obj(artifact: _HandoffArtifact) -> dict[str, object]:
    try:
        contents = artifact.contents.decode("utf-8")
    except UnicodeError as exc:
        raise StateError("handoff artifact contains invalid UTF-8") from exc
    if (
        not artifact.provenance_complete
        or artifact.source_path is None
        or artifact.source_identity is None
    ):
        raise StateError(
            "legacy handoff sidecar must be provenance-upgraded before it is written"
        )
    return {
        "schema": HANDOFF_SIDECAR_SCHEMA,
        "machine": artifact.machine,
        "slot": artifact.slot,
        "generation": artifact.generation,
        "recorded_at": artifact.recorded_at,
        "source": artifact.source,
        "source_path": str(artifact.source_path),
        "source_identity": _regular_file_identity_to_obj(artifact.source_identity),
        "contents_utf8": contents,
        "sha256": artifact.sha256,
    }


def _handoff_artifact_from_obj(
    config: Config,
    record: ActiveRecord,
    value: object,
    path: Path,
    storage_identity: _RegularFileIdentity,
) -> _HandoffArtifact:
    label = f"handoff sidecar {path}"
    raw = _as_mapping(value, label)
    schema = _as_int(raw.get("schema"), f"{label}.schema")
    fields = {
        "schema",
        "machine",
        "slot",
        "generation",
        "recorded_at",
        "source",
        "source_identity",
        "contents_utf8",
        "sha256",
    }
    if schema == HANDOFF_SIDECAR_SCHEMA:
        fields.add("source_path")
    elif schema != HANDOFF_SIDECAR_LEGACY_SCHEMA:
        raise StateError(f"unsupported handoff sidecar schema in {path}")
    _exact_keys(raw, fields, set(), label)
    machine = _as_str(raw["machine"], f"{label}.machine")
    slot = _as_str(raw["slot"], f"{label}.slot")
    generation = _as_int(raw["generation"], f"{label}.generation", minimum=1)
    if (machine, slot, generation) != (
        record.machine,
        record.slot,
        record.generation,
    ):
        raise StateError(f"handoff sidecar identity does not match slot generation: {path}")
    if path != _handoff_sidecar_path(config, slot, generation, machine):
        raise StateError(f"handoff sidecar filename does not match its identity: {path}")
    recorded_at = _as_str(raw["recorded_at"], f"{label}.recorded_at")
    _parse_timestamp(recorded_at, f"{label}.recorded_at")
    source = _as_str(raw["source"], f"{label}.source")
    if source not in {"write-handoff", "legacy-slot-file"}:
        raise StateError(f"{label}.source is invalid")
    expected_legacy_path = (
        _slot_directory(config, record.slot, record.slot_type) / "HANDOFF.md"
    ).resolve(strict=False)
    provenance_complete = schema == HANDOFF_SIDECAR_SCHEMA
    if schema == HANDOFF_SIDECAR_LEGACY_SCHEMA:
        source_path: Path | None = (
            expected_legacy_path if source == "legacy-slot-file" else None
        )
    else:
        source_path = Path(_as_str(raw["source_path"], f"{label}.source_path"))
        if not source_path.is_absolute() or ".." in source_path.parts:
            raise StateError(f"{label}.source_path must be a normalized absolute path")
    source_identity = (
        None
        if raw["source_identity"] is None
        else _regular_file_identity_from_obj(
            _as_mapping(raw["source_identity"], f"{label}.source_identity"),
            f"{label}.source_identity",
        )
    )
    if schema == HANDOFF_SIDECAR_SCHEMA and source_identity is None:
        raise StateError(f"{label} lacks source file identity")
    if (
        schema == HANDOFF_SIDECAR_LEGACY_SCHEMA
        and source == "legacy-slot-file"
        and source_identity is None
    ):
        raise StateError(f"{label} lacks its historical legacy file identity")
    if source == "legacy-slot-file" and source_path != expected_legacy_path:
        raise StateError(f"{label} legacy source path does not match its slot")
    contents_text = _as_str(raw["contents_utf8"], f"{label}.contents_utf8")
    contents = contents_text.encode("utf-8")
    if len(contents) > HANDOFF_BYTES_LIMIT:
        raise StateError(f"{label} exceeds the 1 MiB safety bound")
    digest = _as_str(raw["sha256"], f"{label}.sha256")
    if not DIGEST_RE.fullmatch(digest) or hashlib.sha256(contents).hexdigest() != digest:
        raise StateError(f"{label} digest does not match its content")
    if source_identity is not None and source_identity.sha256 != digest:
        raise StateError(f"{label} source digest does not match its content")
    return _HandoffArtifact(
        path=path,
        machine=machine,
        slot=slot,
        generation=generation,
        contents=contents,
        sha256=digest,
        recorded_at=recorded_at,
        source=source,
        source_path=source_path,
        source_identity=source_identity,
        provenance_complete=provenance_complete,
        storage_identity=storage_identity,
    )


def _load_handoff_sidecar(
    config: Config, record: ActiveRecord
) -> _HandoffArtifact | None:
    path = _handoff_sidecar_path(
        config, record.slot, record.generation, record.machine
    )
    if not path.exists() and not path.is_symlink():
        return None
    contents, storage_identity = _read_regular_file_identity(
        path, "handoff sidecar", HANDOFF_SIDECAR_BYTES_LIMIT
    )
    return _handoff_artifact_from_obj(
        config,
        record,
        _strict_json_object(contents, "handoff sidecar"),
        path,
        storage_identity,
    )


def _canonical_handoff_source(
    path: Path,
    contents: bytes,
    identity: _RegularFileIdentity,
    label: str,
) -> Path:
    try:
        canonical = path.resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"cannot resolve {label} {path}: {exc}") from exc
    canonical_contents, canonical_identity = _read_regular_file_identity(
        canonical, label, HANDOFF_BYTES_LIMIT
    )
    if canonical_contents != contents or canonical_identity != identity:
        raise Refusal(f"{label} changed while its canonical path was resolved: {path}")
    return canonical


def _ancestor_git_marker(path: Path, label: str) -> Path | None:
    """Find an ancestor .git marker without following or trusting it."""

    for directory in (path.parent, *path.parent.parents):
        marker = directory / ".git"
        try:
            metadata = marker.lstat()
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: "
                f"cannot inspect ancestor marker {marker}: {exc}"
            ) from exc
        if stat.S_ISLNK(metadata.st_mode):
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: "
                f"ancestor marker is a symlink: {marker}"
            )
        if stat.S_ISREG(metadata.st_mode):
            _read_regular_file_identity(marker, "Git marker", 64 * 1024)
        elif not stat.S_ISDIR(metadata.st_mode):
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: "
                f"ancestor marker is not a regular file or directory: {marker}"
            )
        return marker
    return None


def _git_worktree_root_for_handoff_source(path: Path, label: str) -> Path | None:
    """Return the containing Git worktree, refusing an indeterminate probe."""

    marker_before = _ancestor_git_marker(path, label)
    result = _GitVcs._run(
        path.parent,
        (
            "-c",
            "core.fsmonitor=false",
            "rev-parse",
            "--path-format=absolute",
            "--show-toplevel",
        ),
        check=False,
        env_overrides={"GIT_OPTIONAL_LOCKS": "0"},
    )
    stdout = result.stdout.strip()
    stderr = result.stderr.strip()
    if result.returncode == 0:
        if stderr or not stdout or "\n" in stdout or "\r" in stdout:
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: "
                "Git returned an invalid worktree root"
            )
        root = Path(stdout)
        try:
            resolved = root.resolve(strict=True)
        except OSError as exc:
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: {exc}"
            ) from exc
        if not root.is_absolute() or root != resolved or not root.is_dir():
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: "
                f"Git returned an unsafe worktree root {root}"
            )
        return root
    if (
        result.returncode == 128
        and not stdout
        and stderr.startswith("fatal: not a git repository")
    ):
        marker_after = _ancestor_git_marker(path, label)
        marker = marker_after or marker_before
        if marker is not None:
            raise Refusal(
                f"cannot determine Git provenance for {label} {path}: Git rejected "
                f"ancestor marker {marker}; preserve the input and repair Git metadata"
            )
        return None
    detail = stderr or stdout or f"Git exited {result.returncode} without diagnostics"
    raise Refusal(f"cannot determine Git provenance for {label} {path}: {detail}")


def _assert_external_handoff_source(path: Path) -> None:
    root = _git_worktree_root_for_handoff_source(path, "handoff input")
    if root is not None:
        raise Refusal(
            f"handoff input is inside Git working tree {root}: {path}; copy intentionally "
            "authored handoff bytes to an external regular file and retry"
        )


def _assert_legacy_handoff_is_not_tracked(path: Path) -> None:
    root = _git_worktree_root_for_handoff_source(path, "legacy HANDOFF.md")
    if root is None:
        return
    try:
        relative = path.resolve(strict=True).relative_to(root)
    except (OSError, ValueError) as exc:
        raise Refusal(
            f"cannot determine Git provenance for legacy HANDOFF.md {path}: {exc}"
        ) from exc
    result = _GitVcs._run(
        root,
        (
            "-c",
            "core.fsmonitor=false",
            "ls-files",
            "--error-unmatch",
            "--",
            relative.as_posix(),
        ),
        check=False,
        env_overrides={"GIT_OPTIONAL_LOCKS": "0"},
    )
    if result.returncode == 0:
        raise Refusal(
            "slot HANDOFF.md is tracked by Git and cannot prove a slot-specific "
            f"handoff: {path}"
        )
    if result.returncode != 1:
        detail = result.stderr.strip() or result.stdout.strip()
        raise Refusal(
            f"cannot determine whether legacy HANDOFF.md is tracked by Git: {path}"
            + (f": {detail}" if detail else "")
        )


def _legacy_handoff_artifact(
    config: Config, record: ActiveRecord, slot_path: Path
) -> _HandoffArtifact | None:
    path = slot_path / "HANDOFF.md"
    if not path.exists() and not path.is_symlink():
        return None
    contents, identity = _read_regular_file_identity(
        path, f"slot {record.slot} HANDOFF.md", HANDOFF_BYTES_LIMIT
    )
    try:
        contents.decode("utf-8")
    except UnicodeError as exc:
        raise Refusal(
            f"slot {record.slot} HANDOFF.md cannot be read as UTF-8: {exc}"
        ) from exc
    actual_source_path = _canonical_handoff_source(
        path, contents, identity, f"slot {record.slot} HANDOFF.md"
    )
    _assert_legacy_handoff_is_not_tracked(actual_source_path)
    source_path = (
        _slot_directory(config, record.slot, record.slot_type) / "HANDOFF.md"
    ).resolve(strict=False)
    return _HandoffArtifact(
        path=path,
        machine=record.machine,
        slot=record.slot,
        generation=record.generation,
        contents=contents,
        sha256=identity.sha256,
        recorded_at=_utc_now(),
        source="legacy-slot-file",
        source_path=source_path,
        source_identity=identity,
        provenance_complete=True,
        storage_identity=identity,
    )


def _resolve_handoff_artifact(
    config: Config,
    record: ActiveRecord,
    slot_path: Path,
    *,
    events: Sequence[Mapping[str, object]] | None = None,
) -> _HandoffArtifact | None:
    selected_events = (
        _load_events(config, record.machine) if events is None else events
    )
    sidecar = _load_handoff_sidecar(config, record)
    if sidecar is not None and not sidecar.provenance_complete:
        raise Refusal(
            f"slot {record.slot} handoff sidecar schema 1 lacks auditable source "
            "provenance and is permanently manual-only; preserve it for inspection "
            "rather than replacing or using it as removal authority"
        )
    publication = _handoff_write_publication(record, selected_events)
    if sidecar is None and publication is not None:
        state = "completed" if publication[2] else "outstanding"
        remedy = (
            "restore the exact completed sidecar"
            if publication[2]
            else "have the exact owner retry write-handoff or recover its authenticated temp"
        )
        raise Refusal(
            f"slot {record.slot} has a {state} owner-authenticated handoff write intent "
            f"but no canonical sidecar; preserve the slot and {remedy}"
        )
    if sidecar is not None:
        if sidecar.source == "legacy-slot-file" and publication is not None:
            state = "completed" if publication[2] else "outstanding"
            raise Refusal(
                f"slot {record.slot} has a {state} owner-authenticated write intent; "
                "a legacy projection cannot supersede it"
            )
        _assert_handoff_sidecar_publication(
            config, record, sidecar, events=selected_events
        )
    legacy = _legacy_handoff_artifact(config, record, slot_path)
    if sidecar is not None and legacy is not None:
        if sidecar.contents != legacy.contents or sidecar.sha256 != legacy.sha256:
            raise Refusal(
                f"slot {record.slot} contains an unread HANDOFF.md: its handoff sidecar "
                "disagrees with the legacy file; "
                "preserve both files and reconcile their exact contents"
            )
        if sidecar.source == "legacy-slot-file" and (
            sidecar.source_path != legacy.source_path
            or sidecar.source_identity != legacy.source_identity
        ):
            raise Refusal(
                f"slot {record.slot} contains an unread HANDOFF.md: its legacy file "
                "identity changed even though its bytes are unchanged; preserve both "
                "files for manual recovery; published sidecars are immutable"
            )
        return sidecar
    if sidecar is not None:
        return sidecar
    return legacy


def _import_source_to_obj(source: _ImportSource | None) -> object:
    if source is None:
        return None
    return {
        "format": source.format,
        "path": source.path,
        "file_sha256": source.file_sha256,
        "row_sha256": source.row_sha256,
        "status": source.status,
        "row": dict(source.row),
    }


def _import_source_from_obj(value: object, label: str) -> _ImportSource | None:
    if value is None:
        return None
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {"format", "path", "file_sha256", "row_sha256", "status", "row"},
        set(),
        label,
    )
    source_format = _as_str(raw["format"], f"{label}.format")
    if source_format != "worktree-state-v3":
        raise StateError(f"{label}.format is unsupported: {source_format!r}")
    path = _as_str(raw["path"], f"{label}.path")
    if Path(path).is_absolute() or not Path(path).parts or ".." in Path(path).parts:
        raise StateError(f"{label}.path must be project-relative")
    file_sha256 = _as_str(raw["file_sha256"], f"{label}.file_sha256")
    row_sha256 = _as_str(raw["row_sha256"], f"{label}.row_sha256")
    if not re.fullmatch(r"[0-9a-f]{64}", file_sha256) or not re.fullmatch(
        r"[0-9a-f]{64}", row_sha256
    ):
        raise StateError(f"{label} digests must be lowercase SHA-256 values")
    status = _as_str(raw["status"], f"{label}.status")
    if status not in HISTORICAL_ACTIVE_STATUSES:
        raise StateError(f"{label}.status is not an active historical state")
    row = dict(_as_mapping(raw["row"], f"{label}.row"))
    if _event_digest(row) != row_sha256:
        raise StateError(f"{label}.row digest does not match its content")
    if row.get("status") != status:
        raise StateError(f"{label}.status does not match its source row")
    return _ImportSource(source_format, path, file_sha256, row_sha256, status, row)


def _checkout_to_obj(checkout: Checkout) -> dict[str, object]:
    return {
        "name": checkout.name,
        "path": checkout.path,
        "repository": checkout.repository,
        "branch": checkout.branch,
        "start_point": checkout.start_point,
        "remote": checkout.remote,
        "remote_url_sha256": checkout.remote_url_sha256,
        "landed_ref": checkout.landed_ref,
        "head": checkout.head,
        "containing_remote_refs": list(checkout.containing_remote_refs),
        "vcs": checkout.vcs,
    }


def _checkout_from_obj(value: object, label: str) -> Checkout:
    raw = _as_mapping(value, label)
    fields = {
        "name",
        "path",
        "repository",
        "branch",
        "start_point",
        "remote",
        "remote_url_sha256",
        "landed_ref",
        "head",
        "containing_remote_refs",
        "vcs",
    }
    _exact_keys(raw, fields, set(), label)
    checkout = Checkout(
        name=_as_str(raw["name"], f"{label}.name"),
        path=_as_str(raw["path"], f"{label}.path"),
        repository=_as_str(raw["repository"], f"{label}.repository"),
        branch=_as_str(raw["branch"], f"{label}.branch"),
        start_point=_as_str(raw["start_point"], f"{label}.start_point"),
        remote=_as_str(raw["remote"], f"{label}.remote"),
        remote_url_sha256=_as_str(
            raw["remote_url_sha256"], f"{label}.remote_url_sha256"
        ),
        landed_ref=_as_str(raw["landed_ref"], f"{label}.landed_ref"),
        head=_as_str(raw["head"], f"{label}.head"),
        containing_remote_refs=tuple(
            _as_str(item, f"{label}.containing_remote_refs[{index}]")
            for index, item in enumerate(
                _as_list(
                    raw["containing_remote_refs"],
                    f"{label}.containing_remote_refs",
                )
            )
        ),
        vcs=_as_str(raw["vcs"], f"{label}.vcs"),
    )
    _validate_name(checkout.name, "checkout name")
    _validate_remote(checkout.remote)
    if not re.fullmatch(r"[0-9a-f]{64}", checkout.remote_url_sha256):
        raise StateError(f"{label}.remote_url_sha256 must be a lowercase SHA-256")
    _validate_ref(checkout.branch, "branch")
    if not SHA_RE.fullmatch(checkout.start_point):
        raise StateError(f"{label}.start_point must be a full lowercase Git commit")
    _validate_full_ref(checkout.landed_ref, "landed ref")
    if checkout.vcs != "git":
        raise StateError(f"unsupported VCS in {label}: {checkout.vcs!r}")
    if not SHA_RE.fullmatch(checkout.head):
        raise StateError(f"{label}.head must be a full lowercase Git commit")
    if any(
        not ref.startswith(f"refs/remotes/{checkout.remote}/")
        for ref in checkout.containing_remote_refs
    ):
        raise StateError(f"{label}.containing_remote_refs names an unauthorized ref")
    return checkout


def _task_scope_to_obj(scope: TaskScopeIdentity | None) -> dict[str, object] | None:
    if scope is None:
        return None
    return {
        "unit": scope.unit,
        "invocation_id": scope.invocation_id,
        "cgroup_path": scope.cgroup_path,
        "boot_id": scope.boot_id,
        "leader_pid": scope.leader_pid,
        "leader_start_ticks": scope.leader_start_ticks,
        "verification": scope.verification,
    }


def _task_scope_from_obj(value: object, label: str) -> TaskScopeIdentity:
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {
            "unit",
            "invocation_id",
            "cgroup_path",
            "boot_id",
            "leader_pid",
            "leader_start_ticks",
            "verification",
        },
        set(),
        label,
    )
    scope = TaskScopeIdentity(
        unit=_as_str(raw["unit"], f"{label}.unit"),
        invocation_id=_as_str(raw["invocation_id"], f"{label}.invocation_id"),
        cgroup_path=_as_str(raw["cgroup_path"], f"{label}.cgroup_path"),
        boot_id=_as_str(raw["boot_id"], f"{label}.boot_id"),
        leader_pid=_as_int(raw["leader_pid"], f"{label}.leader_pid", minimum=1),
        leader_start_ticks=_as_int(
            raw["leader_start_ticks"], f"{label}.leader_start_ticks", minimum=1
        ),
        verification=_as_str(raw["verification"], f"{label}.verification"),
    )
    if (
        not scope.unit.endswith(".scope")
        or "/" in scope.unit
        or any(
            character.isspace()
            or unicodedata.category(character) in {"Cc", "Cf"}
            for character in scope.unit
        )
    ):
        raise StateError(f"{label}.unit is not a task-scoped systemd unit")
    if re.fullmatch(r"[0-9a-f]{32}", scope.invocation_id) is None:
        raise StateError(
            f"{label}.invocation_id is not a canonical systemd invocation ID"
        )
    if (
        not scope.cgroup_path.startswith("/")
        or not scope.cgroup_path.endswith(f"/{scope.unit}")
        or "/../" in scope.cgroup_path
        or re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
            scope.boot_id,
        )
        is None
    ):
        raise StateError(f"{label} has an invalid cgroup path or boot ID")
    if scope.verification != "systemd-runtime-invocation-symlink-v1":
        raise StateError(f"{label}.verification is unsupported")
    return scope


def _assert_task_scope_matches_owner(
    scope: TaskScopeIdentity | None,
    owner: ProcessIdentity | None,
    label: str,
) -> None:
    if scope is None:
        return
    if owner is None:
        raise StateError(f"{label} has no bound owner process")
    if (
        scope.leader_pid,
        scope.leader_start_ticks,
        scope.boot_id,
        scope.cgroup_path,
    ) != (
        owner.pid,
        owner.start_ticks,
        owner.boot_id,
        owner.cgroup_path,
    ):
        raise StateError(f"{label} does not match its bound owner process")


def _systemd_invocation_directory() -> Path:
    return Path("/run/user") / str(os.getuid()) / "systemd" / "units"


def _systemd_user_manager_cgroup() -> str:
    uid = os.getuid()
    return f"/user.slice/user-{uid}.slice/user@{uid}.service"


def _verify_task_scope_invocation(scope: TaskScopeIdentity) -> None:
    # The invocation link comes from this user's manager, so a same-named unit
    # under another manager or the system manager must not borrow its identity.
    manager = _systemd_user_manager_cgroup()
    if not scope.cgroup_path.startswith(f"{manager}/"):
        raise Refusal(
            f"task scope cgroup {scope.cgroup_path} is not under the systemd user "
            f"manager {manager} whose invocation link is verified"
        )
    # The manager places a scope only inside slices, so a same-named cgroup made
    # inside a delegated service subtree cannot borrow the real scope's link.
    parents = scope.cgroup_path.removeprefix(f"{manager}/").split("/")[:-1]
    if any(not parent.endswith(".slice") for parent in parents):
        raise Refusal(
            f"task scope cgroup {scope.cgroup_path} is not a scope placed by the systemd "
            f"user manager {manager}: every component between them must be a slice"
        )
    path = _systemd_invocation_directory() / f"invocation:{scope.unit}"
    flags = os.O_PATH | os.O_CLOEXEC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
        try:
            opened = os.fstat(descriptor)
            if not stat.S_ISLNK(opened.st_mode):
                raise Refusal(
                    f"task scope invocation is not a systemd runtime symlink: {path}"
                )
            # Linux readlinkat(2) with an empty path reads the symlink pinned by
            # O_PATH|O_NOFOLLOW. A pathname read can be fooled by B -> A -> B
            # replacement while two surrounding lstat calls observe B twice.
            target = os.readlink("", dir_fd=descriptor)
        finally:
            os.close(descriptor)
        after = path.lstat()
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(
            f"cannot verify task scope invocation through systemd runtime link {path}: {exc}"
        ) from exc
    if (
        not stat.S_ISLNK(after.st_mode)
        or (opened.st_dev, opened.st_ino) != (after.st_dev, after.st_ino)
        or re.fullmatch(r"[0-9a-f]{32}", target) is None
        or target != scope.invocation_id
    ):
        raise Refusal(
            f"task scope invocation does not match the stable systemd runtime link {path}"
        )


_CREATE_SCOPE_REMEDY = (
    "the create journal is preserved and no ACTIVE row was published; run "
    "'wrkslots recover --coordinator-pid PID --slot SLOT --abort-create' to remove its "
    "unchanged provisional worktrees, then create the slot again from a live task scope"
)
_IMPORT_SCOPE_REMEDY = (
    "the import journal is preserved and no ACTIVE row was published; run "
    "'wrkslots recover --coordinator-pid PID --abort-import' to discard it, then "
    "import the slot again from a live task scope"
)


def _verify_task_scope_before_publication(
    scope: TaskScopeIdentity, remedy: str
) -> None:
    try:
        _verify_task_scope_invocation(scope)
    except Refusal as exc:
        raise Refusal(str(exc), remedy=remedy) from exc


def _task_scope_arguments(args: argparse.Namespace) -> tuple[str, str] | None:
    unit = getattr(args, "task_scope_unit", None)
    invocation_id = getattr(args, "task_scope_invocation_id", None)
    if (unit is None) != (invocation_id is None):
        raise Refusal(
            "--task-scope-unit and --task-scope-invocation-id must be supplied together"
    )
    if unit is None:
        return None
    assert invocation_id is not None
    return unit, invocation_id


def _task_scope_from_args(
    args: argparse.Namespace, owner: ProcessIdentity | None
) -> TaskScopeIdentity | None:
    selected = _task_scope_arguments(args)
    if selected is None:
        return None
    if owner is None:
        raise Refusal("task scope identity requires a live --owner-pid")
    unit, invocation_id = selected
    scope = _task_scope_from_obj(
        {
            "unit": unit,
            "invocation_id": invocation_id,
            "cgroup_path": owner.cgroup_path,
            "boot_id": owner.boot_id,
            "leader_pid": owner.pid,
            "leader_start_ticks": owner.start_ticks,
            "verification": "systemd-runtime-invocation-symlink-v1",
        },
        "task scope",
    )
    _verify_task_scope_invocation(scope)
    return scope


def _record_to_obj(record: ActiveRecord) -> dict[str, object]:
    value: dict[str, object] = {
        "slot": record.slot,
        "agent": record.agent,
        "task": record.task,
        "purpose": record.purpose,
        "slot_type": record.slot_type,
        "machine": record.machine,
        "generation": record.generation,
        "created_at": record.created_at,
        "heartbeat_at": record.heartbeat_at,
        "heartbeat_ttl_seconds": record.heartbeat_ttl_seconds,
        "owner": _identity_to_obj(record.owner),
        "coordinator_lease": _identity_to_obj(record.coordinator_lease),
        "coordinator_recovery_note": record.coordinator_recovery_note,
        "handoff": _handoff_to_obj(record.handoff),
        "checkouts": [_checkout_to_obj(item) for item in record.checkouts],
    }
    if record.layout is not None:
        value["layout"] = record.layout
    if record.import_source is not None:
        value["import_source"] = _import_source_to_obj(record.import_source)
    if record.task_scope is not None:
        value["task_scope"] = _task_scope_to_obj(record.task_scope)
    return value


def _record_from_obj(value: object, label: str) -> ActiveRecord:
    raw = _as_mapping(value, label)
    required_fields = {
        "slot",
        "agent",
        "task",
        "purpose",
        "machine",
        "generation",
        "created_at",
        "heartbeat_at",
        "heartbeat_ttl_seconds",
        "owner",
        "coordinator_lease",
        "coordinator_recovery_note",
        "handoff",
        "checkouts",
    }
    _exact_keys(
        raw,
        required_fields,
        {"slot_type", "layout", "import_source", "task_scope"},
        label,
    )
    checkouts = tuple(
        _checkout_from_obj(item, f"{label}.checkouts[{index}]")
        for index, item in enumerate(_as_list(raw["checkouts"], f"{label}.checkouts"))
    )
    coordinator_lease = _identity_from_obj(
        raw["coordinator_lease"], f"{label}.coordinator_lease"
    )
    if coordinator_lease is None:
        raise StateError(f"{label} has no coordinator lease")
    record = ActiveRecord(
        slot=_as_str(raw["slot"], f"{label}.slot"),
        agent=_as_str(raw["agent"], f"{label}.agent"),
        task=_as_str(raw["task"], f"{label}.task"),
        purpose=_as_str(raw["purpose"], f"{label}.purpose"),
        slot_type=_as_str(raw.get("slot_type", "agent"), f"{label}.slot_type"),
        machine=_as_str(raw["machine"], f"{label}.machine"),
        generation=_as_int(raw["generation"], f"{label}.generation", minimum=1),
        created_at=_as_str(raw["created_at"], f"{label}.created_at"),
        heartbeat_at=_as_str(raw["heartbeat_at"], f"{label}.heartbeat_at"),
        heartbeat_ttl_seconds=_as_int(
            raw["heartbeat_ttl_seconds"], f"{label}.heartbeat_ttl_seconds", minimum=1
        ),
        owner=_identity_from_obj(raw["owner"], f"{label}.owner"),
        coordinator_lease=coordinator_lease,
        coordinator_recovery_note=(
            None
            if raw["coordinator_recovery_note"] is None
            else _as_str(
                raw["coordinator_recovery_note"],
                f"{label}.coordinator_recovery_note",
            )
        ),
        handoff=_handoff_from_obj(raw["handoff"], f"{label}.handoff"),
        checkouts=checkouts,
        layout=(
            None
            if "layout" not in raw
            else _validate_layout(_as_str(raw["layout"], f"{label}.layout"))
        ),
        import_source=_import_source_from_obj(
            raw.get("import_source"), f"{label}.import_source"
        ),
        task_scope=(
            None
            if "task_scope" not in raw
            else _task_scope_from_obj(raw["task_scope"], f"{label}.task_scope")
        ),
    )
    _validate_name(record.slot, "slot")
    _validate_name(record.agent, "agent")
    _validate_name(record.machine, "machine")
    if not record.task or not record.purpose:
        raise StateError(f"{label} has an empty task or purpose")
    if record.slot_type not in SLOT_TYPES:
        raise StateError(
            f"{label}.slot_type must be one of {', '.join(SLOT_TYPES)}"
        )
    _parse_timestamp(record.created_at, f"{label}.created_at")
    _parse_timestamp(record.heartbeat_at, f"{label}.heartbeat_at")
    if not record.checkouts and record.import_source is None:
        raise StateError(f"{label} has no checkouts")
    if not record.checkouts and record.layout != "nested":
        raise StateError(
            f"{label} has no checkouts but is not a historical nested slot"
        )
    if record.coordinator_recovery_note is not None and record.owner is not None:
        raise StateError(f"{label} has coordinator recovery evidence for a bound owner")
    _assert_task_scope_matches_owner(record.task_scope, record.owner, f"{label}.task_scope")
    names = [item.name for item in record.checkouts]
    if len(names) != len(set(names)):
        raise StateError(f"{label} has duplicate checkout names")
    if record.import_source is not None:
        _assert_import_source_matches_record(record, label)
    return record


def _assert_import_source_matches_record(record: ActiveRecord, label: str) -> None:
    source = record.import_source
    assert source is not None
    if record.slot_type != "agent" or record.layout != "nested" or record.owner is None:
        raise StateError(
            f"{label} historical import must be a nested agent slot with an exact owner"
        )
    row = source.row
    expected_task, expected_purpose = _historical_task_and_purpose(
        row, f"{label}.import_source.row", record.agent
    )
    if expected_task != record.task or expected_purpose != record.purpose:
        raise StateError(f"{label} differs from its historical task or purpose")
    if row.get("allocated") != record.created_at:
        raise StateError(f"{label} differs from its historical allocation time")
    sidecar = _as_mapping(
        row.get("owner_sidecar"), f"{label}.import_source.row.owner_sidecar"
    )
    expected_owner = (
        sidecar.get("supervisor_pid"),
        sidecar.get("start_ticks"),
        sidecar.get("boot_id"),
        sidecar.get("cgroup_path"),
    )
    actual_owner = (
        record.owner.pid,
        record.owner.start_ticks,
        record.owner.boot_id,
        record.owner.cgroup_path,
    )
    if expected_owner != actual_owner:
        raise StateError(f"{label} owner differs from its historical owner_sidecar")
    if sidecar.get("slot") != record.slot or sidecar.get("agent") != record.agent:
        raise StateError(f"{label} identity differs from its historical owner_sidecar")
    for checkout in record.checkouts:
        if row.get(f"{checkout.name}_path") != checkout.path:
            raise StateError(
                f"{label} checkout {checkout.name} differs from its historical path"
            )


def _active_from_obj(
    config: Config,
    value: object,
    selected: str,
    label: str,
    *,
    require_repository: bool = True,
) -> ActiveState:
    raw = _as_mapping(value, label)
    _exact_keys(raw, {"schema", "machine", "revision", "slots"}, set(), "active state")
    if _as_int(raw["schema"], "active state.schema") != SCHEMA:
        raise StateError(f"unsupported active state schema in {label}")
    actual_machine = _as_str(raw["machine"], "active state.machine")
    if actual_machine != selected:
        raise StateError(
            f"active state machine mismatch: filename says {selected}, content says {actual_machine}"
        )
    slots = tuple(
        _record_from_obj(item, f"active state.slots[{index}]")
        for index, item in enumerate(_as_list(raw["slots"], "active state.slots"))
    )
    slot_names = [item.slot for item in slots]
    agents = [
        item.agent
        for item in slots
        if item.slot_type == "agent" and item.import_source is None
    ]
    if len(slot_names) != len(set(slot_names)):
        raise StateError(f"duplicate slot in {label}")
    if len(agents) != len(set(agents)):
        raise StateError(f"one agent owns more than one active slot in {label}")
    for record in slots:
        if record.machine != selected:
            raise StateError(
                f"slot {record.slot} says machine {record.machine}, expected shard {selected}"
            )
        _assert_record_paths(
            config, record, require_repository=require_repository
        )
    return ActiveState(
        machine=actual_machine,
        revision=_as_int(raw["revision"], "active state.revision"),
        slots=slots,
    )


def _load_active_snapshot(
    config: Config,
    machine: str | None = None,
    *,
    require_repository: bool = True,
) -> ActiveState:
    selected = machine or config.machine
    path = _active_path(config, selected)
    value = _read_json(path, "active state")
    if require_repository:
        return _active_from_obj(config, value, selected, str(path))
    return _active_from_obj(
        config, value, selected, str(path), require_repository=False
    )


def _active_to_obj(state: ActiveState) -> dict[str, object]:
    return {
        "schema": SCHEMA,
        "machine": state.machine,
        "revision": state.revision,
        "slots": [_record_to_obj(item) for item in sorted(state.slots, key=lambda x: x.slot)],
    }


def _archive_from_obj(
    config: Config, value: object, selected: str, label_prefix: str
) -> ArchiveState:
    raw = _as_mapping(value, label_prefix)
    _exact_keys(raw, {"schema", "machine", "revision", "records"}, set(), "archive state")
    if _as_int(raw["schema"], "archive state.schema") != SCHEMA:
        raise StateError(f"unsupported archive state schema in {label_prefix}")
    actual_machine = _as_str(raw["machine"], "archive state.machine")
    if actual_machine != selected:
        raise StateError(
            f"archive state machine mismatch: filename says {selected}, content says {actual_machine}"
        )
    records: list[dict[str, object]] = []
    archive_ids: set[str] = set()
    archived_slots: set[str] = set()
    for index, item in enumerate(_as_list(raw["records"], "archive state.records")):
        mapping = _as_mapping(item, f"archive state.records[{index}]")
        label = f"archive state.records[{index}]"
        fields = {
            "archive_id",
            "slot",
            "agent",
            "task",
            "purpose",
            "machine",
            "generation",
            "created_at",
            "finished_at",
            "mode",
            "actor",
            "physical_storage",
            "validation",
            "limitations",
            "continuation",
            "checkouts",
        }
        _exact_keys(
            mapping,
            fields,
            {"slot_type", "salvage", "layout", "import_source"},
            label,
        )
        archive_id = _as_str(mapping["archive_id"], f"{label}.archive_id")
        if archive_id in archive_ids:
            raise StateError(f"duplicate archive_id in {label_prefix}: {archive_id}")
        archive_ids.add(archive_id)
        slot = _validate_name(_as_str(mapping["slot"], f"{label}.slot"), "archived slot")
        if slot in archived_slots:
            raise StateError(f"duplicate archived slot in {label_prefix}: {slot}")
        archived_slots.add(slot)
        agent = _validate_name(
            _as_str(mapping["agent"], f"{label}.agent"), "archived agent"
        )
        if not _as_str(mapping["task"], f"{label}.task") or not _as_str(
            mapping["purpose"], f"{label}.purpose"
        ):
            raise StateError(f"{label} has an empty task or purpose")
        slot_type = _as_str(mapping.get("slot_type", "agent"), f"{label}.slot_type")
        if slot_type not in SLOT_TYPES:
            raise StateError(f"{label}.slot_type must be one of {', '.join(SLOT_TYPES)}")
        record_layout = (
            config.layout
            if "layout" not in mapping
            else _validate_layout(_as_str(mapping["layout"], f"{label}.layout"))
        )
        import_source = _import_source_from_obj(
            mapping.get("import_source"), f"{label}.import_source"
        )
        for salvage_index, salvage in enumerate(
            _as_list(mapping.get("salvage", []), f"{label}.salvage")
        ):
            _as_mapping(salvage, f"{label}.salvage[{salvage_index}]")
        record_machine = _as_str(mapping["machine"], f"{label}.machine")
        if record_machine != selected:
            raise StateError(
                f"archived slot {slot} says machine {record_machine}, expected {selected}"
            )
        generation = _as_int(mapping["generation"], f"{label}.generation", minimum=1)
        _parse_timestamp(_as_str(mapping["created_at"], f"{label}.created_at"), label)
        finished_at = _as_str(mapping["finished_at"], f"{label}.finished_at")
        _parse_timestamp(finished_at, label)
        expected_archive_id = f"{selected}:{slot}:{generation}:{finished_at}"
        if archive_id != expected_archive_id:
            raise StateError(f"{label}.archive_id does not match its record")
        mode = _as_str(mapping["mode"], f"{label}.mode")
        if mode != "remove":
            raise StateError(f"{label}.mode is invalid: {mode!r}")
        actor = _as_str(mapping["actor"], f"{label}.actor")
        if actor != "coordinator":
            raise StateError(f"{label}.actor does not match its operation")
        if _as_str(mapping["physical_storage"], f"{label}.physical_storage") != "removed":
            raise StateError(f"{label} does not record removed physical storage")
        validation = _as_list(mapping["validation"], f"{label}.validation")
        if not validation:
            raise StateError(f"{label} has no validation evidence")
        for evidence_index, evidence in enumerate(validation):
            _as_str(evidence, f"{label}.validation[{evidence_index}]")
        for limitation_index, limitation in enumerate(
            _as_list(mapping["limitations"], f"{label}.limitations")
        ):
            _as_str(limitation, f"{label}.limitations[{limitation_index}]")
        if not _as_str(mapping["continuation"], f"{label}.continuation"):
            raise StateError(f"{label} has no continuation")
        checkouts = tuple(
            _checkout_from_obj(value, f"{label}.checkouts[{checkout_index}]")
            for checkout_index, value in enumerate(
                _as_list(mapping["checkouts"], f"{label}.checkouts")
            )
        )
        if len({checkout.name for checkout in checkouts}) != len(checkouts):
            raise StateError(f"{label} has duplicate checkout names")
        if not checkouts and (import_source is None or record_layout != "nested"):
            raise StateError(f"{label} has no checkouts")
        if record_layout == "flat" and len(checkouts) != 1:
            raise StateError(f"{label} has multiple checkouts under flat layout")
        if import_source is not None:
            source_row = import_source.row
            source_owner = _as_mapping(
                source_row.get("owner_sidecar"),
                f"{label}.import_source.row.owner_sidecar",
            )
            source_task, source_purpose = _historical_task_and_purpose(
                source_row, f"{label}.import_source.row", agent
            )
            if (
                record_layout != "nested"
                or source_task != mapping["task"]
                or source_purpose != mapping["purpose"]
                or source_row.get("allocated") != mapping["created_at"]
                or source_owner.get("slot") != slot
                or source_owner.get("agent") != agent
            ):
                raise StateError(f"{label} differs from its historical source row")
        for checkout in checkouts:
            slot_path = _slot_directory(config, slot, slot_type)
            destination = (
                slot_path if record_layout == "flat" else slot_path / checkout.name
            )
            expected = destination.relative_to(config.root).as_posix()
            if checkout.path != expected:
                raise StateError(
                    f"{label} checkout {checkout.name} path escaped its archived slot"
                )
            if checkout.landed_ref != _landed_ref_for_remote(config, checkout.remote):
                raise StateError(
                    f"{label} checkout {checkout.name} differs from configured authority"
                )
        records.append(dict(mapping))
    return ArchiveState(
        machine=actual_machine,
        revision=_as_int(raw["revision"], "archive state.revision"),
        records=tuple(records),
    )


def _load_archive_snapshot(config: Config, machine: str | None = None) -> ArchiveState:
    selected = machine or config.machine
    path = _archive_path(config, selected)
    return _archive_from_obj(
        config, _read_json(path, "archive state"), selected, str(path)
    )


def _ensure_state_shard(config: Config) -> None:
    active = _active_path(config)
    archive = _archive_path(config)
    derived = _states_from_events(config, config.machine)
    if derived is not None:
        active_state, archive_state = derived
        _atomic_write_json(active, _active_to_obj(active_state))
        _atomic_write_json(archive, _archive_to_obj(archive_state))
        return
    active_exists = active.exists() or active.is_symlink()
    archive_exists = archive.exists() or archive.is_symlink()
    if active_exists != archive_exists:
        if active_exists:
            active_state = _load_active(config)
            if active_state.revision != 0 or active_state.slots:
                raise StateError(
                    f"partial machine state for {config.machine}: non-empty ACTIVE has no ARCHIVED"
                )
            _atomic_write_json(
                archive, _archive_to_obj(ArchiveState(config.machine, 0, ()))
            )
        else:
            archive_state = _load_archive(config)
            if archive_state.revision != 0 or archive_state.records:
                raise StateError(
                    f"partial machine state for {config.machine}: non-empty ARCHIVED has no ACTIVE"
                )
            _atomic_write_json(
                active, _active_to_obj(ActiveState(config.machine, 0, ()))
            )
        _ensure_event_log(config)
        return
    if active_exists:
        _load_active(config)
        _load_archive(config)
        _ensure_event_log(config)
        return
    _atomic_write_json(active, _active_to_obj(ActiveState(config.machine, 0, ())))
    _atomic_write_json(archive, _archive_to_obj(ArchiveState(config.machine, 0, ())))
    _ensure_event_log(config)


def _archive_to_obj(state: ArchiveState) -> dict[str, object]:
    return {
        "schema": SCHEMA,
        "machine": state.machine,
        "revision": state.revision,
        "records": list(state.records),
    }


def _event_directory(config: Config, machine: str | None = None) -> Path:
    selected = machine or config.machine
    _validate_name(selected, "machine")
    return config.control / f"EVENTS.{selected}"


def _event_digest(value: Mapping[str, object]) -> str:
    encoded = json.dumps(
        dict(value), sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _event_file_names(directory: Path) -> tuple[str, ...]:
    """Return the complete event file names in chain order.

    Names are listed and sorted as strings.  Sorting one Path per entry cost
    about 140 ms per load on a 16,000-event log on a loaded host, and one
    command loads the log several times; for entries of one directory the
    string order is the order the Paths had.
    """

    if not directory.exists():
        return ()
    if directory.is_symlink() or not directory.is_dir():
        raise StateError(f"append-only event log is not a real directory: {directory}")
    names = os.listdir(directory)
    complete_pattern = re.compile(r"[0-9]{20}\.json")
    partial_pattern = re.compile(r"[0-9]{20}\.json\.tmp\..+")
    unexpected = sorted(
        name
        for name in names
        if complete_pattern.fullmatch(name) is None
        and partial_pattern.fullmatch(name) is None
    )
    if unexpected:
        raise StateError(
            f"append-only event log contains an unexpected entry: {directory / unexpected[0]}; "
            "preserve it and run 'wrkslots doctor' before changing slot state"
        )
    return tuple(sorted(name for name in names if complete_pattern.fullmatch(name)))


def _event_files(directory: Path) -> list[Path]:
    return [directory / name for name in _event_file_names(directory)]


def _event_from_path(
    path: Path,
    machine: str,
    expected_sequence: int,
    previous: str,
    *,
    require_filename: bool = True,
) -> dict[str, object]:
    if require_filename and path.name != f"{expected_sequence:020d}.json":
        raise StateError(
            f"append-only event log has a sequence gap at {path}; "
            "preserve the log and run 'wrkslots doctor'"
        )
    raw = dict(_as_mapping(_read_json(path, "append-only event"), "append-only event"))
    _exact_keys(
        raw,
        {
            "schema",
            "machine",
            "sequence",
            "previous_sha256",
            "recorded_at",
            "kind",
            "payload",
            "sha256",
        },
        set(),
        "append-only event",
    )
    if _as_int(raw["schema"], "append-only event.schema") != EVENT_SCHEMA:
        raise StateError(f"unsupported append-only event schema in {path}")
    if _as_str(raw["machine"], "append-only event.machine") != machine:
        raise StateError(f"append-only event belongs to another machine: {path}")
    if _as_int(raw["sequence"], "append-only event.sequence") != expected_sequence:
        raise StateError(f"append-only event sequence does not match its filename: {path}")
    if _as_str(raw["previous_sha256"], "append-only event.previous_sha256") != previous:
        raise StateError(f"append-only event hash chain is broken at {path}")
    _parse_timestamp(
        _as_str(raw["recorded_at"], "append-only event.recorded_at"),
        "append-only event.recorded_at",
    )
    _as_str(raw["kind"], "append-only event.kind")
    _as_mapping(raw["payload"], "append-only event.payload")
    recorded_digest = _as_str(raw["sha256"], "append-only event.sha256")
    core = {key: value for key, value in raw.items() if key != "sha256"}
    if recorded_digest != _event_digest(core):
        raise StateError(f"append-only event digest does not match its content: {path}")
    return raw


# One validate-batch removal loads the whole append-only log about thirty times
# per slot.  A 2026-09-25 production log held 12,107 events (38 MB), so every
# load re-read, re-parsed and re-hashed the complete chain for 0.85 seconds and
# the batch's evidence deadline expired before the first slot finished.  For
# the duration of one command, keep each validated event keyed by the file's
# exact lstat identity and the chain position that validated it.  An event whose
# change time is recent is never kept: a rewrite inside the same timestamp tick
# could otherwise leave the identity unchanged.  Any later rewrite or rename
# moves the change time, so a kept event can never hide a change.  The window
# assumes the kernel stamps change times from this host's realtime clock, as a
# local filesystem does; a clock stepped backwards only stops events being kept.
# Loaded events are shared, never mutated, and consumers copy what they retain.
#
# The kept events alone still left every repeated load listing the directory
# and walking the memo file by file; a read-only classify-create-journals loads
# the log seven times.  So the complete verified chain is kept as well, keyed by
# its directory and machine, with every file name and the identity each file
# was verified with.  A load answers from the kept chain only when the
# directory lists exactly those names and every file still has exactly that
# identity.  That is the per-file test applied to every position at once, so
# every file is still lstat'ed on every load, and an earlier event rewritten or
# replaced between two loads is read and verified again exactly as before.  A
# chain is kept only when every one of its events was kept or reused under the
# per-file rule, so it inherits the change-time window.  Every writer forgets
# the chain before it changes the directory.
_EVENT_MEMO_STABLE_NS = 2_000_000_000
_EVENT_MEMO_ENTRIES_LIMIT = 1 << 17
_REPLAY_MEMO_ENTRIES_LIMIT = 8

_EventFileIdentity = tuple[int, int, int, int, int]


@dataclasses.dataclass(frozen=True)
class _VerifiedEventChain:
    """One complete verified chain and the file identities it was verified with."""

    names: tuple[str, ...]
    identities: tuple[_EventFileIdentity, ...]
    events: tuple[dict[str, object], ...]


@dataclasses.dataclass
class _EventMemo:
    """Validated events and replay prefixes reused within one command."""

    files: dict[
        tuple[str, str],
        tuple[tuple[int, int, int, int, int], int, str, dict[str, object]],
    ] = dataclasses.field(default_factory=dict)
    replays: dict[tuple[Config, str, bool], tuple[int, str, _ReplayFold]] = (
        dataclasses.field(default_factory=dict)
    )
    chains: dict[tuple[str, str], _VerifiedEventChain] = dataclasses.field(
        default_factory=dict
    )


_ACTIVE_EVENT_MEMO: list[_EventMemo] = []


@contextlib.contextmanager
def _event_memo_scope() -> Iterator[_EventMemo]:
    if _ACTIVE_EVENT_MEMO:
        yield _ACTIVE_EVENT_MEMO[-1]
        return
    memo = _EventMemo()
    _ACTIVE_EVENT_MEMO.append(memo)
    try:
        yield memo
    finally:
        _ACTIVE_EVENT_MEMO.remove(memo)


def _event_memo_clock_ns() -> int:
    return time.time_ns()


def _event_file_identity(path: str | Path) -> tuple[int, int, int, int, int] | None:
    try:
        status = os.lstat(path)
    except OSError:
        return None
    if not stat.S_ISREG(status.st_mode):
        return None
    return (
        status.st_dev,
        status.st_ino,
        status.st_size,
        status.st_mtime_ns,
        status.st_ctime_ns,
    )


def _load_event_paths(
    paths: Sequence[Path], machine: str
) -> tuple[dict[str, object], ...]:
    return _verify_event_paths(paths, machine)[0]


def _verify_event_paths(
    paths: Sequence[Path], machine: str
) -> tuple[tuple[dict[str, object], ...], tuple[_EventFileIdentity | None, ...]]:
    """Verify one chain and return each event's reusable file identity.

    An identity is returned only for an event the per-file memo reused or kept
    during this load, never for one outside a memo scope.
    """

    events: list[dict[str, object]] = []
    trusted: list[_EventFileIdentity | None] = []
    previous = "0" * 64
    if not _ACTIVE_EVENT_MEMO:
        for expected_sequence, path in enumerate(paths, start=1):
            raw = _event_from_path(path, machine, expected_sequence, previous)
            previous = _as_str(raw["sha256"], "append-only event.sha256")
            events.append(raw)
            trusted.append(None)
        return tuple(events), tuple(trusted)
    memo = _ACTIVE_EVENT_MEMO[-1].files
    observed_ns = _event_memo_clock_ns()
    for expected_sequence, path in enumerate(paths, start=1):
        key = (str(path), machine)
        identity = _event_file_identity(path)
        cached = memo.get(key)
        kept: _EventFileIdentity | None = None
        if (
            identity is not None
            and cached is not None
            and cached[:3] == (identity, expected_sequence, previous)
        ):
            raw = cached[3]
            kept = identity
        else:
            raw = _event_from_path(path, machine, expected_sequence, previous)
            if (
                identity is not None
                and identity[4] + _EVENT_MEMO_STABLE_NS <= observed_ns
                and _event_file_identity(path) == identity
            ):
                if len(memo) >= _EVENT_MEMO_ENTRIES_LIMIT:
                    memo.clear()
                memo[key] = (identity, expected_sequence, previous, raw)
                kept = identity
        previous = _as_str(raw["sha256"], "append-only event.sha256")
        events.append(raw)
        trusted.append(kept)
    return tuple(events), tuple(trusted)


def _forget_event_chain(directory: Path, machine: str) -> None:
    """Drop the kept chain of a log that is about to change."""

    if _ACTIVE_EVENT_MEMO:
        _ACTIVE_EVENT_MEMO[-1].chains.pop((str(directory), machine), None)


def _load_events(config: Config, machine: str | None = None) -> tuple[dict[str, object], ...]:
    selected = machine or config.machine
    directory = _event_directory(config, selected)
    names = _event_file_names(directory)
    if not _ACTIVE_EVENT_MEMO:
        return _load_event_paths([directory / name for name in names], selected)
    chains = _ACTIVE_EVENT_MEMO[-1].chains
    key = (str(directory), selected)
    chain = chains.get(key)
    if chain is not None:
        prefix = os.path.join(directory, "")
        if chain.names == names and all(
            _event_file_identity(prefix + name) == identity
            for name, identity in zip(names, chain.identities)
        ):
            return chain.events
        del chains[key]
    events, trusted = _verify_event_paths(
        [directory / name for name in names], selected
    )
    identities = tuple(identity for identity in trusted if identity is not None)
    if len(identities) == len(names):
        chains[key] = _VerifiedEventChain(names, identities, events)
    return events


@dataclasses.dataclass
class _EventWriter:
    directory: Path
    machine: str
    sequence: int
    previous_sha256: str

    def append(self, kind: str, payload: Mapping[str, object]) -> dict[str, object]:
        self.sequence += 1
        core: dict[str, object] = {
            "schema": EVENT_SCHEMA,
            "machine": self.machine,
            "sequence": self.sequence,
            "previous_sha256": self.previous_sha256,
            "recorded_at": _utc_now(),
            "kind": kind,
            "payload": dict(payload),
        }
        event = {**core, "sha256": _event_digest(core)}
        path = self.directory / f"{self.sequence:020d}.json"
        if path.exists() or path.is_symlink():
            raise StateError(f"append-only event already exists and will not be replaced: {path}")
        _forget_event_chain(self.directory, self.machine)
        _atomic_write_json(path, event)
        self.previous_sha256 = _as_str(event["sha256"], "append-only event.sha256")
        return event


def _event_writer(config: Config, machine: str) -> _EventWriter:
    directory = _event_directory(config, machine)
    if directory.exists() and (directory.is_symlink() or not directory.is_dir()):
        raise StateError(f"append-only event log is not a real directory: {directory}")
    created = not directory.exists()
    directory.mkdir(mode=0o755, parents=True, exist_ok=True)
    if created:
        _fsync_directory(directory.parent)
    events = _load_events(config, machine)
    return _EventWriter(
        directory=directory,
        machine=machine,
        sequence=len(events),
        previous_sha256=(
            "0" * 64 if not events else _as_str(events[-1]["sha256"], "append-only event.sha256")
        ),
    )


def _write_event_file(
    config: Config, machine: str, kind: str, payload: Mapping[str, object]
) -> dict[str, object]:
    return _event_writer(config, machine).append(kind, payload)


def _ensure_event_log(
    config: Config,
    machine: str | None = None,
    *,
    require_repository: bool = True,
) -> None:
    selected = machine or config.machine
    if _event_files(_event_directory(config, selected)):
        return
    active = _load_active_snapshot(
        config, selected, require_repository=require_repository
    )
    archive = _load_archive_snapshot(config, selected)
    holds = [
        hold
        for record in active.slots
        if (hold := _load_hold_snapshot(config, record.slot, selected)) is not None
    ]
    _write_event_file(
        config,
        selected,
        "state-imported",
        {
            "active": _active_to_obj(active),
            "archive": _archive_to_obj(archive),
            "holds": holds,
        },
    )


def _absent_validate_recovery_event_evidence(
    value: object, label: str
) -> tuple[str, str]:
    """Parse the machine-readable identity carried by a recovery event."""

    evidence = _as_mapping(value, label)
    _exact_keys(
        evidence,
        {"archive_id", "source_record_sha256", "validation_outcome"},
        set(),
        label,
    )
    archive_id = _as_str(evidence["archive_id"], f"{label}.archive_id")
    source_digest = _as_str(
        evidence["source_record_sha256"], f"{label}.source_record_sha256"
    )
    if not DIGEST_RE.fullmatch(source_digest):
        raise StateError(f"{label}.source_record_sha256 is not a SHA-256 digest")
    if evidence["validation_outcome"] != "unknown":
        raise StateError(f"{label}.validation_outcome must be unknown")
    return archive_id, source_digest


def _absent_agent_recovery_event_evidence(
    value: object, label: str
) -> tuple[str, str]:
    evidence = _as_mapping(value, label)
    _exact_keys(
        evidence,
        {"archive_id", "source_record_sha256", "physical_storage"},
        set(),
        label,
    )
    archive_id = _as_str(evidence["archive_id"], f"{label}.archive_id")
    source_digest = _as_str(
        evidence["source_record_sha256"], f"{label}.source_record_sha256"
    )
    if not DIGEST_RE.fullmatch(source_digest):
        raise StateError(f"{label}.source_record_sha256 is not a SHA-256 digest")
    if evidence["physical_storage"] != "externally-absent":
        raise StateError(f"{label}.physical_storage must be externally-absent")
    return archive_id, source_digest


@dataclasses.dataclass
class _ReplayFold:
    """Derived registry state after one verified prefix of the event log."""

    active_revision: int | None = None
    active_records: dict[str, ActiveRecord] = dataclasses.field(default_factory=dict)
    active_agents: dict[str, str] = dataclasses.field(default_factory=dict)
    archive_revision: int | None = None
    archive_records: list[dict[str, object]] = dataclasses.field(default_factory=list)
    archive_ids: set[str] = dataclasses.field(default_factory=set)
    archived_slots: set[str] = dataclasses.field(default_factory=set)
    absent_validate_recoveries: set[tuple[str, int, str]] = dataclasses.field(
        default_factory=set
    )
    absent_agent_recoveries: set[tuple[str, int, str]] = dataclasses.field(
        default_factory=set
    )
    # First record for each distinct input of _assert_record_paths, in log order.
    path_checks: dict[tuple[object, ...], ActiveRecord] = dataclasses.field(
        default_factory=dict
    )

    def copy(self) -> _ReplayFold:
        return _ReplayFold(
            self.active_revision,
            dict(self.active_records),
            dict(self.active_agents),
            self.archive_revision,
            list(self.archive_records),
            set(self.archive_ids),
            set(self.archived_slots),
            set(self.absent_validate_recoveries),
            set(self.absent_agent_recoveries),
            dict(self.path_checks),
        )


def _record_path_check_key(record: ActiveRecord) -> tuple[object, ...]:
    """Return every record field that _assert_record_paths reads."""

    return (
        record.slot,
        record.slot_type,
        record.layout,
        tuple(
            (
                checkout.name,
                checkout.path,
                checkout.repository,
                checkout.remote,
                checkout.landed_ref,
            )
            for checkout in record.checkouts
        ),
    )


def _resume_replay(
    config: Config,
    key: tuple[Config, str, bool],
    events: Sequence[Mapping[str, object]],
) -> tuple[int, _ReplayFold]:
    """Return how many events a remembered fold already covers, and its copy.

    Replaying a verified prefix is a pure function of its events and the
    configuration except for _assert_record_paths, which also inspects the
    filesystem.  The prefix is identified by its hash-chain tip, and that check
    is rerun for the prefix's records before the fold is trusted.

    Every replayed record gets the reference-only check, with or without
    require_repository; the existence check that require_repository adds is
    applied by _states_from_events to the records that are still active once
    the whole log is folded, on a resumed replay exactly as on a cold one.
    """

    cached = _ACTIVE_EVENT_MEMO[-1].replays.get(key) if _ACTIVE_EVENT_MEMO else None
    if cached is None:
        return 0, _ReplayFold()
    count, tip, fold = cached
    if count > len(events) or events[count - 1].get("sha256") != tip:
        return 0, _ReplayFold()
    # The reference-only _assert_record_paths is lexical except for
    # _stored_repository_reference, whose result depends only on the
    # repository string.  Recheck each distinct repository in log order so a
    # failure is the one a full replay would reach first.
    for repository in dict.fromkeys(
        checkout.repository
        for record in fold.path_checks.values()
        for checkout in record.checkouts
    ):
        _stored_repository_reference(config, repository)
    return count, fold.copy()


def _remember_replay(
    key: tuple[Config, str, bool],
    events: Sequence[Mapping[str, object]],
    fold: _ReplayFold,
) -> None:
    if not _ACTIVE_EVENT_MEMO:
        return
    replays = _ACTIVE_EVENT_MEMO[-1].replays
    replays.pop(key, None)
    if len(replays) >= _REPLAY_MEMO_ENTRIES_LIMIT:
        replays.pop(next(iter(replays)))
    replays[key] = (
        len(events),
        _as_str(events[-1]["sha256"], "append-only event.sha256"),
        fold,
    )


def _states_from_events(
    config: Config,
    machine: str,
    *,
    require_repository: bool = True,
) -> tuple[ActiveState, ArchiveState] | None:
    events = _load_events(config, machine)
    if not events:
        return None
    memo_key = (config, machine, require_repository)
    start, fold = _resume_replay(config, memo_key, events)
    active_revision = fold.active_revision
    active_records = fold.active_records
    active_agents = fold.active_agents
    archive_revision = fold.archive_revision
    archive_records = fold.archive_records
    archive_ids = fold.archive_ids
    archived_slots = fold.archived_slots
    absent_validate_recoveries = fold.absent_validate_recoveries
    absent_agent_recoveries = fold.absent_agent_recoveries
    path_checks = fold.path_checks
    for event in events[start:]:
        payload = _as_mapping(event["payload"], "append-only event.payload")
        kind = _as_str(event["kind"], "append-only event.kind")
        if kind == "state-imported":
            if active_revision is not None or archive_revision is not None:
                raise StateError("append-only event log imports state more than once")
            # Reference-only, like every replayed record: an imported row that a
            # later event replaces or removes is history, and the rows still
            # active after the fold get the existence check below.
            active = _active_from_obj(
                config,
                payload.get("active"),
                machine,
                "append-only imported active state",
                require_repository=False,
            )
            archive = _archive_from_obj(
                config,
                payload.get("archive"),
                machine,
                "append-only imported archive state",
            )
            for record in active.slots:
                path_checks.setdefault(_record_path_check_key(record), record)
            active_revision = active.revision
            active_records = {record.slot: record for record in active.slots}
            active_agents = {
                record.agent: record.slot
                for record in active.slots
                if record.slot_type == "agent" and record.import_source is None
            }
            archive_revision = archive.revision
            archive_records = [dict(record) for record in archive.records]
            archive_ids = {
                _as_str(record.get("archive_id"), "archive record archive_id")
                for record in archive.records
            }
            archived_slots = {
                _as_str(record.get("slot"), "archive record slot")
                for record in archive.records
            }
        elif kind == "active-state-recorded":
            if active_revision is None:
                raise StateError("append-only event records active state before its import")
            _exact_keys(
                payload,
                {
                    "action",
                    "slot",
                    "previous_revision",
                    "revision",
                    "previous_record_sha256",
                    "record",
                    "evidence",
                },
                set(),
                "append-only active-record event",
            )
            slot = _as_str(payload["slot"], "append-only active-record event.slot")
            _validate_name(slot, "slot")
            action = _as_str(
                payload["action"], "append-only active-record event.action"
            )
            previous_revision = _as_int(
                payload["previous_revision"],
                "append-only active-record event.previous_revision",
                minimum=0,
            )
            revision = _as_int(
                payload["revision"],
                "append-only active-record event.revision",
                minimum=1,
            )
            if previous_revision != active_revision or revision != active_revision + 1:
                raise StateError(
                    "append-only active-record event revision does not continue "
                    f"the derived state for slot {slot}"
                )
            current = active_records.get(slot)
            previous_digest = (
                None if current is None else _event_digest(_record_to_obj(current))
            )
            if payload["previous_record_sha256"] != previous_digest:
                raise StateError(
                    "append-only active-record event does not match the prior record "
                    f"for slot {slot}"
                )
            raw_record = payload["record"]
            if action == "absent-validation-row-recovered":
                if current is None or raw_record is not None:
                    raise StateError(
                        "absent-validation-row recovery event must remove one active row"
                    )
                archive_id, source_digest = _absent_validate_recovery_event_evidence(
                    payload["evidence"], "append-only active recovery event.evidence"
                )
                if source_digest != previous_digest:
                    raise StateError(
                        "append-only active recovery evidence does not match its source record"
                    )
                expected_prefix = f"{machine}:{slot}:{current.generation}:"
                if not archive_id.startswith(expected_prefix):
                    raise StateError(
                        "append-only active recovery evidence has a mismatched archive identity"
                    )
            elif action == "absent-agent-row-recovered":
                if current is None or current.slot_type != "agent" or raw_record is not None:
                    raise StateError(
                        "absent-agent-row recovery event must remove one active agent row"
                    )
                archive_id, source_digest = _absent_agent_recovery_event_evidence(
                    payload["evidence"], "append-only active agent recovery evidence"
                )
                if source_digest != previous_digest:
                    raise StateError(
                        "append-only active agent recovery evidence does not match its source record"
                    )
                if not archive_id.startswith(f"{machine}:{slot}:{current.generation}:"):
                    raise StateError(
                        "append-only active agent recovery evidence has a mismatched archive identity"
                    )
            if raw_record is None:
                if current is None:
                    raise StateError(
                        f"append-only active-record event removes absent slot {slot}"
                    )
                active_records.pop(slot)
                if current.slot_type == "agent" and current.import_source is None:
                    active_agents.pop(current.agent, None)
            else:
                record = _record_from_obj(
                    raw_record, "append-only active-record event.record"
                )
                if record.slot != slot or record.machine != machine:
                    raise StateError(
                        "append-only active-record event record identity does not "
                        f"match slot {slot} on machine {machine}"
                    )
                path_key = _record_path_check_key(record)
                if path_key not in path_checks:
                    _assert_record_paths(config, record, require_repository=False)
                    path_checks[path_key] = record
                if current is not None and current.slot_type == "agent" and current.import_source is None:
                    active_agents.pop(current.agent, None)
                if record.slot_type == "agent" and record.import_source is None:
                    conflict = active_agents.get(record.agent)
                    if conflict is not None and conflict != slot:
                        raise StateError(
                            "append-only active-record event gives one agent more than one slot"
                        )
                    active_agents[record.agent] = slot
                active_records[slot] = record
            active_revision = revision
        elif kind == "archive-state-recorded":
            if archive_revision is None:
                raise StateError("append-only event records archive state before its import")
            _exact_keys(
                payload,
                {
                    "action",
                    "slot",
                    "previous_revision",
                    "revision",
                    "record",
                    "evidence",
                },
                set(),
                "append-only archive-record event",
            )
            previous_revision = _as_int(
                payload["previous_revision"],
                "append-only archive-record event.previous_revision",
                minimum=0,
            )
            revision = _as_int(
                payload["revision"],
                "append-only archive-record event.revision",
                minimum=1,
            )
            if previous_revision != archive_revision or revision != archive_revision + 1:
                raise StateError(
                    "append-only archive-record event revision does not continue "
                    "the derived archive"
                )
            archive_record = dict(
                _as_mapping(payload["record"], "append-only archive-record event.record")
            )
            action = _as_str(
                payload["action"], "append-only archive-record event.action"
            )
            slot = _as_str(payload["slot"], "append-only archive-record event.slot")
            if archive_record.get("slot") != slot:
                raise StateError(
                    "append-only archive-record event record identity does not "
                    f"match slot {slot}"
                )
            parsed = _archive_from_obj(
                config,
                {
                    "schema": SCHEMA,
                    "machine": machine,
                    "revision": 1,
                    "records": [archive_record],
                },
                machine,
                "append-only derived archive state",
            )
            parsed_record = dict(parsed.records[0])
            archive_id = _as_str(
                parsed_record.get("archive_id"), "append-only archive record archive_id"
            )
            if action == "absent-validation-row-recovered":
                evidence_archive_id, source_digest = (
                    _absent_validate_recovery_event_evidence(
                        payload["evidence"],
                        "append-only archive recovery event.evidence",
                    )
                )
                generation = _as_int(
                    parsed_record.get("generation"),
                    "append-only archive recovery record.generation",
                    minimum=1,
                )
                if (
                    parsed_record.get("machine") != machine
                    or parsed_record.get("slot_type") != "validate"
                    or parsed_record.get("physical_storage") != "removed"
                    or evidence_archive_id != archive_id
                ):
                    raise StateError(
                        "append-only archive recovery evidence does not match its record"
                    )
                absent_validate_recoveries.add((slot, generation, source_digest))
            elif action == "absent-agent-row-recovered":
                evidence_archive_id, source_digest = _absent_agent_recovery_event_evidence(
                    payload["evidence"], "append-only archive agent recovery evidence"
                )
                generation = _as_int(
                    parsed_record.get("generation"),
                    "append-only archive agent recovery record.generation",
                    minimum=1,
                )
                if (
                    parsed_record.get("machine") != machine
                    or parsed_record.get("slot_type") != "agent"
                    or parsed_record.get("physical_storage") != "removed"
                    or evidence_archive_id != archive_id
                ):
                    raise StateError(
                        "append-only archive agent recovery evidence does not match its record"
                    )
                absent_agent_recoveries.add((slot, generation, source_digest))
            if archive_id in archive_ids:
                raise StateError(f"duplicate archive_id in append-only events: {archive_id}")
            if slot in archived_slots:
                raise StateError(f"duplicate archived slot in append-only events: {slot}")
            archive_ids.add(archive_id)
            archived_slots.add(slot)
            archive_records.append(parsed_record)
            archive_revision = revision
    if active_revision is None or archive_revision is None:
        raise StateError("append-only event log has no complete imported state")
    if require_repository:
        # Only the derived rows must name storage that exists now.  A record a
        # later event superseded, such as the row a repository-relocated event
        # rewrote or the row of a slot since archived, names where a
        # repository WAS; requiring that path today strands the whole registry
        # once the old directory is gone, which relocate-repository explicitly
        # allows.  Checked before the fold is remembered, so a refused replay
        # leaves the memo as it was.
        for record in active_records.values():
            _assert_record_paths(config, record, require_repository=True)
    _remember_replay(
        memo_key,
        events,
        _ReplayFold(
            active_revision,
            active_records,
            active_agents,
            archive_revision,
            archive_records,
            archive_ids,
            archived_slots,
            absent_validate_recoveries,
            absent_agent_recoveries,
            path_checks,
        ),
    )
    return (
        ActiveState(machine, active_revision, tuple(active_records.values())),
        ArchiveState(
            machine,
            archive_revision,
            tuple(archive_records),
            frozenset(absent_validate_recoveries),
            frozenset(absent_agent_recoveries),
        ),
    )


def _load_active(
    config: Config,
    machine: str | None = None,
    *,
    require_repository: bool = True,
) -> ActiveState:
    selected = machine or config.machine
    states = _states_from_events(
        config, selected, require_repository=require_repository
    )
    return (
        _load_active_snapshot(
            config, selected, require_repository=require_repository
        )
        if states is None
        else states[0]
    )


def _load_archive(
    config: Config,
    machine: str | None = None,
    *,
    require_repository: bool = True,
) -> ArchiveState:
    selected = machine or config.machine
    states = _states_from_events(
        config, selected, require_repository=require_repository
    )
    return _load_archive_snapshot(config, selected) if states is None else states[1]


def _write_active_state(
    config: Config,
    state: ActiveState,
    *,
    action: str,
    slot: str,
    evidence: Mapping[str, object] | None = None,
    require_repository: bool = True,
) -> None:
    _ensure_event_log(
        config, state.machine, require_repository=require_repository
    )
    previous = _load_active(
        config, state.machine, require_repository=require_repository
    )
    if state.revision != previous.revision + 1:
        raise StateError(
            "active state revision must advance exactly once before it is recorded"
        )
    previous_by_slot = {item.slot: item for item in previous.slots}
    current_by_slot = {item.slot: item for item in state.slots}
    changed = {
        name
        for name in previous_by_slot.keys() | current_by_slot.keys()
        if previous_by_slot.get(name) != current_by_slot.get(name)
    }
    previous_record = previous_by_slot.get(slot)
    current_record = current_by_slot.get(slot)
    if changed not in ({slot}, set()) or (
        not changed and (previous_record is None or current_record is None)
    ):
        raise StateError(
            "active state mutation must affect only its named slot; "
            f"expected {slot!r}, changed {sorted(changed)!r}"
        )
    _write_event_file(
        config,
        state.machine,
        "active-state-recorded",
        {
            "action": action,
            "slot": slot,
            "previous_revision": previous.revision,
            "revision": state.revision,
            "previous_record_sha256": (
                None
                if previous_record is None
                else _event_digest(_record_to_obj(previous_record))
            ),
            "record": (
                None if current_record is None else _record_to_obj(current_record)
            ),
            "evidence": dict(evidence or {}),
        },
    )
    _atomic_write_json(_active_path(config, state.machine), _active_to_obj(state))


def _write_active_rows_removed(
    config: Config,
    state: ActiveState,
    slots: Sequence[str],
    *,
    evidence_by_slot: Mapping[str, Mapping[str, object]] | None = None,
    event_writer: _EventWriter | None = None,
) -> ActiveState:
    names = tuple(_validate_name(slot, "slot") for slot in slots)
    if not names or len(names) != len(set(names)):
        raise StateError("active-row batch removal requires unique slots")
    current = {record.slot: record for record in state.slots}
    missing = [slot for slot in names if slot not in current]
    if missing:
        raise StateError(f"cannot batch-remove missing slot {missing[0]}")
    _ensure_event_log(config, state.machine)
    previous = _load_active(config, state.machine)
    if previous != state:
        raise StateError("active state changed before batch removal")
    writer = event_writer or _event_writer(config, state.machine)
    revision = state.revision
    for index, slot in enumerate(names, start=1):
        previous_revision = revision
        revision += 1
        writer.append(
            "active-state-recorded",
            {
                "action": "absent-validation-row-recovered",
                "slot": slot,
                "previous_revision": previous_revision,
                "revision": revision,
                "previous_record_sha256": _record_sha256(current[slot]),
                "record": None,
                "evidence": dict((evidence_by_slot or {}).get(slot, {})),
            },
        )
        _interrupt_for_test(f"after-absent-validate-active-row-{index}")
    removed = set(names)
    updated = ActiveState(
        state.machine,
        revision,
        tuple(record for record in state.slots if record.slot not in removed),
    )
    _interrupt_for_test("after-absent-validate-active-event")
    _atomic_write_json(_active_path(config, state.machine), _active_to_obj(updated))
    return updated


def _write_archive_state(
    config: Config,
    state: ArchiveState,
    *,
    action: str,
    slot: str,
    evidence: Mapping[str, object] | None = None,
    require_repository: bool = True,
) -> None:
    _ensure_event_log(
        config, state.machine, require_repository=require_repository
    )
    previous = _load_archive(
        config, state.machine, require_repository=require_repository
    )
    if state.revision != previous.revision + 1:
        raise StateError(
            "archive state revision must advance exactly once before it is recorded"
        )
    if (
        len(state.records) != len(previous.records) + 1
        or tuple(state.records[:-1]) != previous.records
    ):
        raise StateError("archive mutation must append exactly one record")
    record = dict(state.records[-1])
    if record.get("slot") != slot:
        raise StateError("archive mutation record does not match its named slot")
    _write_event_file(
        config,
        state.machine,
        "archive-state-recorded",
        {
            "action": action,
            "slot": slot,
            "previous_revision": previous.revision,
            "revision": state.revision,
            "record": record,
            "evidence": dict(evidence or {}),
        },
    )
    _atomic_write_json(_archive_path(config, state.machine), _archive_to_obj(state))


def _write_journal(
    config: Config,
    payload: Mapping[str, object],
    *,
    event_writer: _EventWriter | None = None,
    journal_path: Path | None = None,
) -> None:
    _ensure_event_log(config)
    writer = event_writer or _event_writer(config, config.machine)
    selected_path = journal_path or _journal_path(config)
    writer.append(
        "operation-progress-recorded",
        {
            "slot": payload.get("slot"),
            "operation": payload.get("kind"),
            "journal_path": selected_path.name,
            "journal": dict(payload),
        },
    )
    _atomic_write_json(selected_path, dict(payload))


def _clear_journal(
    config: Config,
    payload: Mapping[str, object],
    *,
    event_writer: _EventWriter | None = None,
    journal_path: Path | None = None,
) -> None:
    _ensure_event_log(config)
    writer = event_writer or _event_writer(config, config.machine)
    selected_path = journal_path or _journal_path(config)
    writer.append(
        "operation-completed",
        {
            "slot": payload.get("slot"),
            "operation": payload.get("kind"),
            "journal_path": selected_path.name,
        },
    )
    _interrupt_for_test("after-operation-completed")
    if selected_path.exists() or selected_path.is_symlink():
        _remove_control_file(selected_path)


def _operation_event_journal_path(
    config: Config,
    machine: str,
    payload: Mapping[str, object],
    *,
    journal: Mapping[str, object] | None = None,
) -> Path:
    raw_name = payload.get("journal_path")
    if raw_name is None:
        return _journal_path(config, machine)
    name = _as_str(raw_name, "append-only operation journal_path")
    if Path(name).name != name:
        raise StateError("append-only operation journal_path is not a filename")
    operation = _as_str(payload.get("operation"), "append-only operation kind")
    slot = _validate_name(
        _as_str(payload.get("slot"), "append-only operation slot"), "slot"
    )
    if operation == "create" and name.startswith("CREATE."):
        expected = _create_journal_path(config, slot, machine)
    elif operation == "finish" and name.startswith("FINISH."):
        expected = _finish_journal_path(config, slot, machine)
    else:
        expected = _journal_path(config, machine)
    selected = config.control / name
    if selected != expected:
        raise StateError(
            "append-only operation journal_path does not match its operation identity"
        )
    if journal is not None and (
        journal.get("kind") != operation
        or journal.get("slot") != slot
        or journal.get("machine") != machine
    ):
        raise StateError(
            "append-only operation event does not match its embedded journal"
        )
    return selected


def _pending_operations_from_events(
    config: Config, machine: str
) -> Mapping[Path, Mapping[str, object]]:
    pending: dict[Path, Mapping[str, object]] = {}
    for event in _load_events(config, machine):
        kind = _as_str(event["kind"], "append-only event.kind")
        payload = _as_mapping(event["payload"], "append-only event.payload")
        if kind == "operation-progress-recorded":
            journal_value = _as_mapping(
                payload.get("journal"), "append-only operation journal"
            )
            path = _operation_event_journal_path(
                config, machine, payload, journal=journal_value
            )
            identity = (journal_value.get("kind"), journal_value.get("slot"))
            for existing_path, existing in pending.items():
                if existing_path != path and (
                    existing.get("kind"), existing.get("slot")
                ) == identity:
                    raise StateError(
                        "append-only history has the same pending operation under "
                        "multiple journal paths"
                    )
            pending[path] = journal_value
        elif kind == "operation-completed":
            path = _operation_event_journal_path(config, machine, payload)
            current = pending.get(path)
            if current is None:
                continue
            if (
                payload.get("slot") == current.get("slot")
                and payload.get("operation") == current.get("kind")
            ):
                del pending[path]
            else:
                raise StateError(
                    "append-only completion does not match its pending operation"
                )
    return pending


def _recorded_handoff_digest(
    config: Config,
    record: ActiveRecord,
    *,
    events: Sequence[Mapping[str, object]] | None = None,
) -> str | None:
    digest: str | None = None
    selected_events = (
        _load_events(config, record.machine) if events is None else events
    )
    for event in selected_events:
        if event.get("kind") != "handoff-read":
            continue
        payload = _as_mapping(event["payload"], "handoff-read event payload")
        if payload.get("slot") == record.slot and payload.get("generation") == record.generation:
            digest = _as_str(payload.get("sha256"), "handoff-read event sha256")
    return digest


def _latest_handoff_read(
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
) -> _HandoffRead | None:
    latest: _HandoffRead | None = None
    for event in events:
        if event.get("kind") != "handoff-read":
            continue
        payload = _as_mapping(event["payload"], "handoff-read event payload")
        if payload.get("slot") != record.slot or payload.get("generation") != record.generation:
            continue
        digest = _as_str(payload.get("sha256"), "handoff-read event sha256")
        if not DIGEST_RE.fullmatch(digest):
            raise StateError("handoff-read event sha256 is not a SHA-256 digest")
        enqueued_value = payload.get("retirement_enqueued", False)
        if not isinstance(enqueued_value, bool):
            raise StateError("handoff-read event retirement_enqueued must be boolean")
        values = (
            payload.get("source"),
            payload.get("source_path"),
            payload.get("source_identity"),
        )
        if all(value is None for value in values):
            source = None
            source_path = None
            source_identity = None
        elif any(value is None for value in values):
            raise StateError("handoff-read event has incomplete source provenance")
        else:
            source = _as_str(values[0], "handoff-read event source")
            if source not in {"write-handoff", "legacy-slot-file"}:
                raise StateError("handoff-read event source is invalid")
            source_path = Path(_as_str(values[1], "handoff-read event source_path"))
            if not source_path.is_absolute() or ".." in source_path.parts:
                raise StateError(
                    "handoff-read event source_path must be a normalized absolute path"
                )
            source_identity = _regular_file_identity_from_obj(
                _as_mapping(values[2], "handoff-read event source_identity"),
                "handoff-read event source_identity",
            )
            if source_identity.sha256 != digest:
                raise StateError("handoff-read source digest does not match its content")
        latest = _HandoffRead(
            sha256=digest,
            retirement_enqueued=enqueued_value,
            sequence=_as_int(event["sequence"], "handoff-read event sequence", minimum=1),
            recorded_at=_as_str(event["recorded_at"], "handoff-read event recorded_at"),
            source=source,
            source_path=source_path,
            source_identity=source_identity,
        )
    return latest


def _handoff_read_matches_artifact(
    read: _HandoffRead, artifact: _HandoffArtifact
) -> bool:
    return (
        read.provenance_complete
        and artifact.provenance_complete
        and read.sha256 == artifact.sha256
        and read.source == artifact.source
        and read.source_path == artifact.source_path
        and read.source_identity == artifact.source_identity
    )


def _owner_before_handoff_write_intent(
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
    intent_sequence: int,
) -> ProcessIdentity | None:
    """Return this generation's owner immediately before one intent event."""

    owner: ProcessIdentity | None = None
    for event in events:
        sequence = _as_int(event["sequence"], "append-only event sequence", minimum=1)
        if sequence >= intent_sequence:
            break
        kind = event.get("kind")
        payload = _as_mapping(event["payload"], f"{kind} event payload")
        if kind == "state-imported":
            imported = _as_mapping(
                payload.get("active"), "append-only imported active state"
            )
            owner = None
            for index, value in enumerate(
                _as_list(imported.get("slots"), "append-only imported active state.slots")
            ):
                candidate = _record_from_obj(
                    value, f"append-only imported active state.slots[{index}]"
                )
                if (
                    candidate.machine == record.machine
                    and candidate.slot == record.slot
                    and candidate.generation == record.generation
                ):
                    owner = candidate.owner
                    break
        elif kind == "active-state-recorded" and payload.get("slot") == record.slot:
            raw_record = payload.get("record")
            if raw_record is None:
                owner = None
                continue
            candidate = _record_from_obj(
                raw_record, "append-only active-record event.record"
            )
            owner = (
                candidate.owner
                if candidate.machine == record.machine
                and candidate.slot == record.slot
                and candidate.generation == record.generation
                else None
            )
    return owner


def _handoff_write_publication(
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
) -> tuple[int, Mapping[str, object], bool] | None:
    intents: dict[int, Mapping[str, object]] = {}
    completed: set[int] = set()
    for event in events:
        kind = event.get("kind")
        payload = _as_mapping(event["payload"], f"{kind} event payload")
        if kind == "handoff-write-intended":
            if payload.get("slot") != record.slot or payload.get("generation") != record.generation:
                continue
            artifact = _as_mapping(payload.get("artifact"), "handoff write intent artifact")
            if (
                artifact.get("schema") != HANDOFF_SIDECAR_SCHEMA
                or artifact.get("machine") != record.machine
                or artifact.get("slot") != record.slot
                or artifact.get("generation") != record.generation
                or artifact.get("source") != "write-handoff"
            ):
                raise StateError("handoff write intent has an invalid artifact identity")
            writer = _identity_from_obj(
                payload.get("writer"), "handoff write intent writer"
            )
            if writer is None:
                raise StateError("handoff write intent lacks an owner identity")
            intent_sequence = _as_int(
                event["sequence"], "handoff write intent sequence", minimum=1
            )
            owner_at_intent = _owner_before_handoff_write_intent(
                record, events, intent_sequence
            )
            if owner_at_intent is None or writer != owner_at_intent:
                raise StateError(
                    "handoff write intent writer does not match the recorded slot owner"
                )
            intents[intent_sequence] = artifact
        elif kind == "handoff-write-completed":
            if payload.get("slot") != record.slot or payload.get("generation") != record.generation:
                continue
            sequence = _as_int(
                payload.get("intent_sequence"),
                "handoff write completion intent_sequence",
                minimum=1,
            )
            intended_artifact = intents.get(sequence)
            if intended_artifact is None:
                raise StateError("handoff write completion references an unknown intent")
            digest = _as_str(
                payload.get("artifact_sha256"),
                "handoff write completion artifact_sha256",
            )
            if digest != _event_digest(intended_artifact):
                raise StateError("handoff write completion digest does not match its intent")
            completed.add(sequence)
    if not intents:
        return None
    sequence = max(intents)
    return sequence, intents[sequence], sequence in completed


def _legacy_projection_read(
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
    artifact: _HandoffArtifact,
) -> tuple[Mapping[str, object], bool] | None:
    selected: tuple[Mapping[str, object], bool] | None = None
    expected_contents = artifact.contents.decode("utf-8")
    assert artifact.source_path is not None
    assert artifact.source_identity is not None
    for event in events:
        if event.get("kind") != "handoff-read":
            continue
        payload = _as_mapping(event["payload"], "handoff-read event payload")
        if payload.get("slot") != record.slot or payload.get("generation") != record.generation:
            continue
        if (
            payload.get("sha256") == artifact.sha256
            and payload.get("contents_utf8") == expected_contents
            and payload.get("source") == "legacy-slot-file"
            and payload.get("source_path") == str(artifact.source_path)
            and payload.get("source_identity")
            == _regular_file_identity_to_obj(artifact.source_identity)
        ):
            enqueued = payload.get("retirement_enqueued", False)
            if not isinstance(enqueued, bool):
                raise StateError("handoff-read event retirement_enqueued must be boolean")
            selected = payload, enqueued
    return selected


def _assert_handoff_sidecar_publication(
    config: Config,
    record: ActiveRecord,
    artifact: _HandoffArtifact,
    *,
    allow_outstanding_write: bool = False,
    events: Sequence[Mapping[str, object]] | None = None,
) -> tuple[str, int | None, Mapping[str, object] | None]:
    if not artifact.provenance_complete:
        raise Refusal("handoff sidecar lacks complete source provenance")
    selected_events = (
        _load_events(config, record.machine) if events is None else events
    )
    artifact_obj = _handoff_artifact_to_obj(artifact)
    if artifact.source == "write-handoff":
        publication = _handoff_write_publication(record, selected_events)
        if publication is None or not _json_equal(publication[1], artifact_obj):
            raise Refusal(
                f"slot {record.slot} handoff sidecar has no matching owner-authenticated "
                "publication intent; preserve it for manual review"
            )
        if not publication[2] and not allow_outstanding_write:
            raise Refusal(
                f"slot {record.slot} handoff publication is incomplete; preserve the "
                "sidecar and have its exact owner retry write-handoff"
            )
        return "write-handoff", publication[0], None
    publication = _handoff_write_publication(record, selected_events)
    if publication is not None:
        state = "completed" if publication[2] else "outstanding"
        raise Refusal(
            f"slot {record.slot} has a {state} owner-authenticated write intent; "
            "legacy sidecar recovery cannot supersede it"
        )
    legacy = _legacy_projection_read(record, selected_events, artifact)
    if legacy is None:
        raise Refusal(
            f"slot {record.slot} projected legacy sidecar has no matching "
            "provenance-bearing read; preserve it for manual review"
        )
    return "legacy-slot-file", None, legacy[0]


def _complete_handoff_write_publication(
    config: Config,
    record: ActiveRecord,
    intent_sequence: int,
    artifact: _HandoffArtifact,
) -> None:
    publication = _handoff_write_publication(
        record, _load_events(config, record.machine)
    )
    if publication is None or publication[0] != intent_sequence:
        raise StateError("handoff write intent changed before completion")
    if not _json_equal(publication[1], _handoff_artifact_to_obj(artifact)):
        raise StateError("handoff write completion does not match its intent")
    if publication[2]:
        return
    _write_event_file(
        config,
        record.machine,
        "handoff-write-completed",
        {
            "slot": record.slot,
            "generation": record.generation,
            "intent_sequence": intent_sequence,
            "artifact_sha256": _event_digest(publication[1]),
        },
    )


def _complete_legacy_projection(
    config: Config,
    record: ActiveRecord,
    artifact: _HandoffArtifact,
    read_payload: Mapping[str, object],
) -> None:
    latest = _latest_handoff_read(record, _load_events(config, record.machine))
    if latest is not None and latest.retirement_enqueued and _handoff_read_matches_artifact(
        latest, artifact
    ):
        return
    _write_event_file(
        config,
        record.machine,
        "handoff-read",
        {**dict(read_payload), "retirement_enqueued": True},
    )


def _retirement_candidates(
    config: Config,
    state: ActiveState,
    events: Sequence[Mapping[str, object]],
) -> tuple[_RetirementCandidate, ...]:
    last_attempts: dict[tuple[str, int, str, int], int] = {}
    for event in events:
        if event.get("kind") != "retirement-attempted":
            continue
        payload = _as_mapping(event["payload"], "retirement-attempted event payload")
        slot = _as_str(payload.get("slot"), "retirement-attempted event slot")
        generation = _as_int(
            payload.get("generation"), "retirement-attempted event generation", minimum=1
        )
        digest = _as_str(payload.get("sha256"), "retirement-attempted event sha256")
        if not DIGEST_RE.fullmatch(digest):
            raise StateError("retirement-attempted event sha256 is not a SHA-256 digest")
        read_sequence = _as_int(
            payload.get("handoff_read_sequence"),
            "retirement-attempted event handoff_read_sequence",
            minimum=1,
        )
        _as_str(payload.get("reason"), "retirement-attempted event reason")
        key = (slot, generation, digest, read_sequence)
        last_attempts[key] = _as_int(
            event["sequence"], "retirement-attempted event sequence", minimum=1
        )
    candidates: list[_RetirementCandidate] = []
    releases = _latest_owner_releases(
        events,
        {
            (record.slot, record.generation)
            for record in state.slots
            if record.slot_type == "agent"
        },
    )
    for record in state.slots:
        if record.slot_type != "agent":
            continue
        latest = _latest_handoff_read(record, events)
        if (
            latest is None
            or latest.retirement_enqueued is not True
            or not latest.provenance_complete
        ):
            continue
        digest = latest.sha256
        sequence = latest.sequence
        recorded_at = latest.recorded_at
        artifact_path: str | None = None
        artifact_source: str | None = None
        blocked_reason: str | None = None
        try:
            artifact = _resolve_handoff_artifact(
                config,
                record,
                _slot_directory(config, record.slot, record.slot_type),
                events=events,
            )
            if artifact is None:
                blocked_reason = "the exact handoff artifact is missing"
            elif not _handoff_read_matches_artifact(latest, artifact):
                blocked_reason = (
                    "the current handoff provenance differs from the enqueued read"
                )
            else:
                artifact_path = str(artifact.path)
                artifact_source = artifact.source
        except StateError:
            raise
        except Refusal as exc:
            blocked_reason = str(exc)
        release, release_void = _owner_release_state(config, record, events, releases)
        candidates.append(
            _RetirementCandidate(
                machine=record.machine,
                slot=record.slot,
                generation=record.generation,
                sha256=digest,
                event_sequence=sequence,
                enqueued_at=recorded_at,
                last_attempt_sequence=last_attempts.get(
                    (record.slot, record.generation, digest, sequence)
                ),
                artifact_path=artifact_path,
                artifact_source=artifact_source,
                blocked_reason=blocked_reason,
                owner_release=(
                    None
                    if release is None
                    else _owner_release_obj(release, release_void)
                ),
            )
        )
    return tuple(
        sorted(
            candidates,
            key=lambda item: (
                item.last_attempt_sequence is not None,
                item.last_attempt_sequence or item.event_sequence,
                item.event_sequence,
                item.slot,
            ),
        )
    )


def _retired_handoff_temp_path(
    target: Path, identity: _RegularFileIdentity
) -> Path:
    key = hashlib.sha256(target.name.encode("utf-8")).hexdigest()[:16]
    return target.parent / (
        f"HANDOFF-DUPLICATE.{key}.{identity.device:x}.{identity.inode:x}."
        f"{identity.sha256}.json"
    )


def _retired_legacy_handoff_path(
    config: Config,
    record: ActiveRecord,
    identity: _RegularFileIdentity,
) -> Path:
    key = hashlib.sha256(
        f"{record.machine}\0{record.slot}\0{record.generation}".encode("utf-8")
    ).hexdigest()[:16]
    return config.control / (
        f"HANDOFF-LEGACY-RETIRED.{key}.{identity.device:x}.{identity.inode:x}."
        f"{identity.sha256}.md"
    )


def _validate_retired_legacy_handoff(
    path: Path,
    identity: _RegularFileIdentity,
) -> None:
    contents, observed = _read_regular_file_identity(
        path, "retired legacy HANDOFF.md", HANDOFF_BYTES_LIMIT
    )
    if observed != identity or hashlib.sha256(contents).hexdigest() != identity.sha256:
        raise StateError(
            f"retired legacy HANDOFF.md identity changed; preserve it for recovery: {path}"
        )


def _record_legacy_handoff_quarantine(
    config: Config,
    record: ActiveRecord,
    retired: Path,
    identity: _RegularFileIdentity,
) -> None:
    payload = {
        "slot": record.slot,
        "generation": record.generation,
        "sha256": identity.sha256,
        "retired_path": retired.name,
        "source_identity": _regular_file_identity_to_obj(identity),
    }
    matches = []
    for event in _load_events(config, record.machine):
        if event.get("kind") != "handoff-removed":
            continue
        candidate = _as_mapping(event["payload"], "handoff-removed event payload")
        if (
            candidate.get("slot") == record.slot
            and candidate.get("generation") == record.generation
        ):
            matches.append(candidate)
    if not matches:
        _write_event_file(config, record.machine, "handoff-removed", payload)
        return
    if len(matches) != 1 or not _json_equal(matches[0], payload):
        raise StateError(
            f"handoff removal history disagrees with retired legacy artifact for "
            f"slot {record.slot}"
        )


def _retired_handoff_prefix(sidecar_path: Path) -> str:
    name_digest = hashlib.sha256(sidecar_path.name.encode("utf-8")).hexdigest()[:16]
    return f"HANDOFF-RETIRED.{name_digest}."


def _retired_handoff_path(sidecar: _HandoffArtifact) -> Path:
    identity = sidecar.storage_identity
    return sidecar.path.parent / (
        f"{_retired_handoff_prefix(sidecar.path)}{identity.device:x}.{identity.inode:x}."
        f"{sidecar.sha256}.{identity.sha256}.json"
    )


def _remove_handoff_sidecar_after_archive(
    config: Config, record: ActiveRecord
) -> None:
    """Move an archived sidecar to durable identity-bound retired storage."""

    sidecar_path = _handoff_sidecar_path(
        config, record.slot, record.generation, record.machine
    )
    prefix = _retired_handoff_prefix(sidecar_path)
    retired_paths = sorted(config.control.glob(f"{prefix}*"))
    if len(retired_paths) > 1:
        raise StateError(
            f"multiple retired handoff sidecars exist for slot {record.slot}"
        )
    digest = _recorded_handoff_digest(config, record)
    if retired_paths:
        retired = retired_paths[0]
        if sidecar_path.exists() or sidecar_path.is_symlink():
            raise StateError(
                f"handoff sidecar was replaced during archived cleanup for slot "
                f"{record.slot}; preserve both {sidecar_path} and {retired}"
            )
        match = re.fullmatch(
            rf"{re.escape(prefix)}([0-9a-f]+)\.([0-9a-f]+)\."
            r"([0-9a-f]{64})\.([0-9a-f]{64})\.json",
            retired.name,
        )
        if match is None:
            raise StateError(f"invalid retired handoff sidecar: {retired}")
        contents, identity = _read_regular_file_identity(
            retired, "retired handoff sidecar", HANDOFF_SIDECAR_BYTES_LIMIT
        )
        if (
            identity.device != int(match.group(1), 16)
            or identity.inode != int(match.group(2), 16)
            or digest != match.group(3)
            or identity.sha256 != match.group(4)
        ):
            raise StateError(
                f"retired handoff sidecar identity changed: {retired}"
            )
        artifact = _handoff_artifact_from_obj(
            config,
            record,
            _strict_json_object(contents, "retired handoff sidecar"),
            sidecar_path,
            identity,
        )
        if digest != artifact.sha256:
            raise Refusal(
                f"retired handoff sidecar does not match the exact read for slot "
                f"{record.slot}; preserve it and run 'wrkslots recover'"
            )
        return

    sidecar = _load_handoff_sidecar(config, record)
    if sidecar is None:
        return
    if digest != sidecar.sha256:
        raise Refusal(
            f"handoff sidecar changed before archived cleanup for slot {record.slot}; "
            "preserve it and run 'wrkslots recover'"
        )
    identity = sidecar.storage_identity
    retired = _retired_handoff_path(sidecar)
    if retired.exists() or retired.is_symlink():
        raise StateError(
            f"retired handoff destination already exists for slot {record.slot}: {retired}"
        )
    _interrupt_for_test("before-handoff-sidecar-retire")
    try:
        _rename_noreplace(
            sidecar_path,
            retired,
            f"retire handoff sidecar for slot {record.slot}",
        )
        _fsync_directory(config.control)
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(
            f"cannot quarantine handoff sidecar {sidecar_path}: {exc}"
        ) from exc
    _interrupt_for_test("after-handoff-sidecar-quarantine")
    _interrupt_for_test("before-handoff-retired-sidecar-finalize")
    contents, retired_identity = _read_regular_file_identity(
        retired, "retired handoff sidecar", HANDOFF_SIDECAR_BYTES_LIMIT
    )
    retired_artifact = _handoff_artifact_from_obj(
        config,
        record,
        _strict_json_object(contents, "retired handoff sidecar"),
        sidecar_path,
        retired_identity,
    )
    if (
        retired_identity != identity
        or retired_artifact.sha256 != digest
    ):
        raise StateError(
            f"retired handoff sidecar identity changed at its archive boundary for slot "
            f"{record.slot}; preserved it for inspection"
        )
    if sidecar_path.exists() or sidecar_path.is_symlink():
        raise StateError(
            f"handoff sidecar pathname was replaced during cleanup for slot "
            f"{record.slot}; preserved both identities for recovery"
        )


def _empty_state_repair_payload(
    path: Path, label: str, machine: str, rows_field: str
) -> dict[str, object] | None:
    raw = _as_mapping(_read_json(path, label), label)
    _exact_keys(raw, {"schema", "machine", "revision", rows_field}, set(), label)
    schema = _as_int(raw["schema"], f"{label}.schema")
    if schema == SCHEMA:
        return None
    if schema != 1:
        raise StateError(f"unsupported {label} schema in {path}")
    actual_machine = _as_str(raw["machine"], f"{label}.machine")
    if actual_machine != machine:
        raise StateError(
            f"{label} machine mismatch: filename says {machine}, content says "
            f"{actual_machine}"
        )
    revision = _as_int(raw["revision"], f"{label}.revision")
    rows = _as_list(raw[rows_field], f"{label}.{rows_field}")
    if revision != 0 or rows:
        raise StateError(
            f"cannot repair non-empty {label} written with schema 1 in {path}"
        )
    return {
        "schema": SCHEMA,
        "machine": machine,
        "revision": 0,
        rows_field: [],
    }


def _repair_empty_state_from_schema_one(config: Config) -> None:
    active_path = _active_path(config)
    archive_path = _archive_path(config)
    active_payload = (
        _empty_state_repair_payload(
            active_path, "active state", config.machine, "slots"
        )
        if active_path.exists() or active_path.is_symlink()
        else None
    )
    archive_payload = (
        _empty_state_repair_payload(
            archive_path, "archive state", config.machine, "records"
        )
        if archive_path.exists() or archive_path.is_symlink()
        else None
    )

    # Validate both durable files before rewriting either one. A malformed
    # current file must not leave the pair half-repaired.
    if active_payload is None and (active_path.exists() or active_path.is_symlink()):
        _load_active(config)
    if archive_payload is None and (
        archive_path.exists() or archive_path.is_symlink()
    ):
        _load_archive(config)

    for path, payload in (
        (active_path, active_payload),
        (archive_path, archive_payload),
    ):
        if payload is None:
            continue
        _atomic_write_json(path, payload)
        print(f"REPAIRED {path}: schema 1 -> {SCHEMA}")


def _atomic_replace_symlink(path: Path, target: Path) -> None:
    temporary = path.parent / f".{path.name}.tmp.{os.getpid()}.{uuid.uuid4().hex}"
    try:
        temporary.symlink_to(target)
        os.replace(temporary, path)
        _fsync_directory(path.parent)
    finally:
        if temporary.is_symlink():
            temporary.unlink()


def _state_files(config: Config) -> list[tuple[str, Path]]:
    result: list[tuple[str, Path]] = []
    pattern = re.compile(r"^ACTIVE\.(?P<machine>[A-Za-z0-9][A-Za-z0-9._-]{0,63})\.json$")
    for path in sorted(config.control.glob("ACTIVE.*.json")):
        match = pattern.fullmatch(path.name)
        if match is None:
            raise StateError(f"unexpected active-state filename: {path}")
        result.append((match.group("machine"), path))
    return result


def _archive_files(config: Config) -> list[tuple[str, Path]]:
    result: list[tuple[str, Path]] = []
    pattern = re.compile(
        r"^ARCHIVED\.(?P<machine>[A-Za-z0-9][A-Za-z0-9._-]{0,63})\.json$"
    )
    for path in sorted(config.control.glob("ARCHIVED.*.json")):
        match = pattern.fullmatch(path.name)
        if match is None:
            raise StateError(f"unexpected archive-state filename: {path}")
        result.append((match.group("machine"), path))
    return result


def _state_machines(config: Config) -> tuple[str, ...]:
    active = {machine for machine, _path in _state_files(config)}
    archive = {machine for machine, _path in _archive_files(config)}
    events: set[str] = set()
    pattern = re.compile(r"^EVENTS\.(?P<machine>[A-Za-z0-9][A-Za-z0-9._-]{0,63})$")
    for path in sorted(config.control.glob("EVENTS.*")):
        match = pattern.fullmatch(path.name)
        if match is None:
            raise StateError(f"unexpected append-only event directory name: {path}")
        if path.is_symlink() or not path.is_dir():
            raise StateError(f"append-only event log is not a real directory: {path}")
        events.add(match.group("machine"))
    missing_pairs = (active ^ archive) - events
    if missing_pairs:
        raise StateError(
            "ACTIVE and ARCHIVED machine shards differ without append-only history: "
            f"active={sorted(active)} archived={sorted(archive)} events={sorted(events)}"
        )
    return tuple(sorted(active | archive | events))


def _load_all_active(
    config: Config, *, require_repository: bool = True
) -> list[ActiveState]:
    states = [
        _load_active(config, machine, require_repository=require_repository)
        for machine in _state_machines(config)
    ]
    global_slots: dict[str, str] = {}
    global_agents: dict[str, str] = {}
    for state in states:
        for record in state.slots:
            previous_slot = global_slots.setdefault(record.slot, state.machine)
            if previous_slot != state.machine:
                raise StateError(
                    f"slot {record.slot!r} is active in both {previous_slot} and {state.machine}"
                )
            if record.slot_type == "agent" and record.import_source is None:
                previous_agent = global_agents.setdefault(record.agent, record.slot)
                if previous_agent != record.slot:
                    raise StateError(
                        f"agent {record.agent!r} owns both {previous_agent} and {record.slot}"
                    )
    return states


def _load_all_archives(
    config: Config, *, require_repository: bool = True
) -> list[ArchiveState]:
    archives = [
        _load_archive(config, machine, require_repository=require_repository)
        for machine in _state_machines(config)
    ]
    slots: dict[str, str] = {}
    for archive in archives:
        for record in archive.records:
            slot = _as_str(record.get("slot"), "archive slot")
            previous = slots.setdefault(slot, archive.machine)
            if previous != archive.machine:
                raise StateError(
                    f"slot {slot!r} is archived in both {previous} and {archive.machine}"
                )
    return archives


def _validate_global_state(
    config: Config,
    *,
    require_repository: bool = True,
) -> tuple[list[ActiveState], list[ArchiveState]]:
    states = _load_all_active(config, require_repository=require_repository)
    archives = _load_all_archives(config, require_repository=require_repository)
    active_slots = {
        record.slot: state.machine for state in states for record in state.slots
    }
    for archive in archives:
        for record in archive.records:
            slot = _as_str(record.get("slot"), "archive slot")
            if slot in active_slots:
                raise StateError(
                    f"slot {slot!r} is active on {active_slots[slot]} and archived on {archive.machine}"
                )
    return states, archives


def _validate_global_state_for_finish_recovery(
    config: Config, journal: Mapping[str, object]
) -> tuple[list[ActiveState], list[ArchiveState]]:
    states = _load_all_active(config, require_repository=False)
    archives = _load_all_archives(config, require_repository=False)
    recorded = _record_from_obj(journal.get("record"), "finish journal.record")
    expected_entry = _archive_entry(journal, recorded)
    active = {
        record.slot: (state.machine, record)
        for state in states
        for record in state.slots
    }
    for archive in archives:
        for archived in archive.records:
            slot = _as_str(archived.get("slot"), "archive slot")
            current = active.get(slot)
            if current is None:
                continue
            active_machine, active_record = current
            if (
                slot == recorded.slot
                and active_machine == config.machine
                and archive.machine == config.machine
                and _record_to_obj(active_record) == _record_to_obj(recorded)
                and _json_equal(archived, expected_entry)
            ):
                continue
            raise StateError(
                f"slot {slot!r} is active on {active_machine} and archived on {archive.machine}"
            )
    return states, archives


def _validate_global_state_for_absent_agent_recovery(
    config: Config, journal: Mapping[str, object]
) -> tuple[list[ActiveState], list[ArchiveState]]:
    """Allow only this journal's exact archive-before-ACTIVE overlap."""

    states = _load_all_active(config)
    archives = _load_all_archives(config)
    item, recorded, _branches, _receipts, expected_entry = _absent_agent_journal_inputs(
        config, journal
    )
    active = {
        record.slot: (state.machine, record)
        for state in states
        for record in state.slots
    }
    for archive in archives:
        for archived in archive.records:
            slot = _as_str(archived.get("slot"), "archive slot")
            current = active.get(slot)
            if current is None:
                continue
            active_machine, active_record = current
            if (
                slot == item.slot
                and active_machine == config.machine
                and archive.machine == config.machine
                and _record_to_obj(active_record) == _record_to_obj(recorded)
                and _json_equal(archived, expected_entry)
            ):
                continue
            raise StateError(
                f"slot {slot!r} is active on {active_machine} and archived on {archive.machine}"
            )
    return states, archives


def _registry_storage_inconsistencies(
    config: Config,
    states: Sequence[ActiveState],
    *,
    tolerate_unavailable_repositories: bool = False,
    additional_repositories: Sequence[Path] = (),
    vcs: _GitVcs | None = None,
    verify_row_identity: bool = True,
) -> tuple[StorageInconsistency, ...]:
    """Describe storage drift without weakening authoritative state validation.

    Callers must load ``states`` through ``_validate_global_state`` first. That
    keeps malformed events, invalid schemas or hashes, duplicate identities,
    and ambiguous repository paths fail-closed. This function handles only the
    later question of whether that readable authority still agrees with disk
    and Git worktree registration.
    """

    findings: list[StorageInconsistency] = []

    def note(
        kind: str,
        scope: str,
        detail: str,
        remedy: str,
        *,
        slot: str | None = None,
        slot_type: str | None = None,
        machine: str | None = None,
        checkout: str | None = None,
    ) -> None:
        findings.append(
            StorageInconsistency(
                kind=kind,
                scope=scope,
                slot=slot,
                slot_type=slot_type,
                machine=machine,
                checkout=checkout,
                detail=detail,
                remedy=remedy,
            )
        )

    records = [record for state in states for record in state.slots]
    record_by_slot_identity = {
        (record.slot_type, record.slot): record for record in records
    }
    expected = {
        slot_type: {record.slot for record in records if record.slot_type == slot_type}
        for slot_type in SLOT_TYPES
    }
    vcs = _GitVcs() if vcs is None else vcs
    listed_by_repository: dict[Path, set[Path]] = {}
    common_by_repository: dict[Path, Path] = {}
    listed_by_common: dict[Path, set[Path]] = {}
    recorded_by_common: dict[Path, set[Path]] = {}
    source_by_common: dict[Path, Path] = {}

    for record in sorted(records, key=lambda item: (item.machine, item.slot)):
        slot_path = _slot_directory(config, record.slot, record.slot_type)
        slot_present = slot_path.exists() or slot_path.is_symlink()
        slot_safe = slot_path.is_dir() and not slot_path.is_symlink()
        slot_inspectable = slot_safe
        if not slot_safe:
            kind = "unsafe-slot-directory" if slot_present else "row-without-directory"
            detail = (
                f"active row points at an unsafe slot path {slot_path}"
                if slot_present
                else f"active row but no slot directory at {slot_path}"
            )
            note(
                kind,
                "row",
                detail,
                "preserve the active row; restore its exact slot directory or use the "
                "supported recovery command after proving the storage is intentionally absent",
                slot=record.slot,
                slot_type=record.slot_type,
                machine=record.machine,
            )
        elif _record_layout(config, record) == "nested":
            try:
                actual = {entry.name for entry in slot_path.iterdir()}
            except OSError as exc:
                slot_inspectable = False
                note(
                    "slot-unreadable",
                    "row",
                    f"cannot inspect {slot_path}: {exc}",
                    "make the recorded slot directory readable, then rerun 'wrkslots status'",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                )
            else:
                wanted = {checkout.name for checkout in record.checkouts}
                allowed = set(wanted)
                if record.slot_type == "agent":
                    allowed.add("HANDOFF.md")
                for name in sorted(wanted - actual):
                    note(
                        "missing-checkout",
                        "row",
                        f"record names checkout {name!r} but it is not in {slot_path}",
                        "preserve the row and repair or recover the named checkout before mutation",
                        slot=record.slot,
                        slot_type=record.slot_type,
                        machine=record.machine,
                        checkout=name,
                    )
                for name in sorted(actual - allowed):
                    note(
                        "unexpected-entry",
                        "row",
                        f"slot holds {name!r}, which its record does not name",
                        "inspect and register or relocate the unexpected entry; do not delete it "
                        "to make the registry look consistent",
                        slot=record.slot,
                        slot_type=record.slot_type,
                        machine=record.machine,
                        checkout=name,
                    )

        for checkout in record.checkouts:
            path = _stored_path_reference(config, checkout.path, "checkout path")
            try:
                _relative, repository = _stored_repository_path(
                    config, checkout.repository
                )
                if repository not in listed_by_repository:
                    common_by_repository[repository] = vcs.common_directory(repository)
                    listed_by_repository[repository] = vcs.listed_worktrees(repository)
            except Refusal as exc:
                if not tolerate_unavailable_repositories:
                    raise
                note(
                    "repository-evidence-unavailable",
                    "row",
                    f"cannot inspect repository for checkout {checkout.name}: {exc}",
                    "restore the recorded source repository, or record where it moved with "
                    "'wrkslots relocate-repository', then rerun 'wrkslots status'; no mutation "
                    "may rely on unavailable Git evidence",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                    checkout=checkout.name,
                )
                continue
            common = common_by_repository[repository]
            source_by_common.setdefault(common, repository)
            listed_by_common.setdefault(common, set()).update(
                listed_by_repository[repository]
            )
            recorded_by_common.setdefault(common, set()).add(path.absolute())
            if not slot_inspectable:
                continue
            registered = path.absolute() in listed_by_repository[repository]
            present = path.exists() or path.is_symlink()
            if not present:
                if registered:
                    note(
                        "git-registration-without-directory",
                        "row",
                        f"Git still registers absent checkout path {path}",
                        "inspect 'git worktree list --porcelain' and repair or remove the stale "
                        "registration through Git before reusing this path",
                        slot=record.slot,
                        slot_type=record.slot_type,
                        machine=record.machine,
                        checkout=checkout.name,
                    )
                continue
            if path.is_symlink() or not path.is_dir():
                note(
                    "unsafe-checkout-path",
                    "row",
                    f"recorded checkout path is not a real directory: {path}",
                    "preserve and inspect the recorded path; replace no filesystem object "
                    "until its ownership is established",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                    checkout=checkout.name,
                )
                continue
            if not registered:
                note(
                    "checkout-without-git-registration",
                    "row",
                    f"checkout exists but Git does not register it at {path}",
                    "inspect 'git worktree list --porcelain' and repair the exact worktree "
                    "registration before mutation",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                    checkout=checkout.name,
                )
                continue
            if not verify_row_identity:
                continue
            try:
                checkout_root, checkout_common, _head = vcs.worktree_identity(path)
            except Refusal as exc:
                note(
                    "git-worktree-unreadable",
                    "row",
                    f"cannot verify recorded checkout {path}: {exc}",
                    "preserve the checkout and repair its Git metadata before mutation",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                    checkout=checkout.name,
                )
                continue
            if checkout_root != path.absolute() or checkout_common != common_by_repository[repository]:
                note(
                    "git-worktree-mismatch",
                    "row",
                    f"checkout {path} does not identify the recorded repository worktree",
                    "preserve the checkout and repair the exact Git worktree registration "
                    "before mutation",
                    slot=record.slot,
                    slot_type=record.slot_type,
                    machine=record.machine,
                    checkout=checkout.name,
                )

    for repository in additional_repositories:
        if repository not in listed_by_repository:
            common_by_repository[repository] = vcs.common_directory(repository)
            listed_by_repository[repository] = vcs.listed_worktrees(repository)
        common = common_by_repository[repository]
        source_by_common.setdefault(common, repository)
        listed_by_common.setdefault(common, set()).update(
            listed_by_repository[repository]
        )

    slot_roots = sorted(
        _slot_roots(config).items(), key=lambda item: len(item[1].parts), reverse=True
    )
    for common, registered_paths in sorted(listed_by_common.items()):
        source = source_by_common[common]
        for registered_path in sorted(
            registered_paths - recorded_by_common.get(common, set())
        ):
            managed = next(
                (
                    (slot_type, root)
                    for slot_type, root in slot_roots
                    if _path_is_within(registered_path, root)
                ),
                None,
            )
            if managed is None:
                continue
            slot_type, root = managed
            relative = registered_path.relative_to(root)
            slot = relative.parts[0] if relative.parts else None
            matched_record = (
                record_by_slot_identity.get((slot_type, slot))
                if slot is not None
                else None
            )
            note(
                "git-registration-without-row",
                "row" if matched_record is not None else "directory",
                f"source repository {source} (Git common directory {common}) registers "
                f"{registered_path} inside the managed {slot_type} root, but no active "
                "checkout row for that repository names it",
                (
                    f"inspect 'git -C {source} worktree list --porcelain'; for a present "
                    "ownerless validation checkout preserve and inspect it; destructive "
                    "recovery is disabled because the checkout and Git administration "
                    "cannot both be fenced against same-UID replacement; use "
                    "import-existing only for a demonstrably live owner, and repair a "
                    "missing stale registration before reusing any overlapping path"
                    if slot_type == "validate"
                    else f"inspect 'git -C {source} worktree list --porcelain'; restore and "
                    "register the live slot or remove the stale Git registration before "
                    "reusing any overlapping path"
                ),
                slot=slot,
                slot_type=slot_type,
                machine=None if matched_record is None else matched_record.machine,
            )

    for slot_type, root in _slot_roots(config).items():
        if not root.exists() and not root.is_symlink():
            continue
        if root.is_symlink() or not root.is_dir():
            note(
                "unsafe-slots-directory",
                "directory",
                f"managed {slot_type} slots directory is unsafe: {root}",
                "restore the configured managed directory as a real directory before mutation",
                slot_type=slot_type,
            )
            continue
        try:
            actual = {
                entry.name
                for entry in root.iterdir()
                if (entry.is_dir() or entry.is_symlink())
                and not entry.name.startswith("EVENTS.")
                and entry != config.control / "wrkslots"
                and not _is_representation_directory(config, entry)
                and not (
                    slot_type == "agent"
                    and entry == _validate_slots_directory(config)
                )
            }
        except OSError as exc:
            note(
                "slots-directory-unreadable",
                "directory",
                f"cannot enumerate {root}: {exc}",
                "make the configured managed directory readable, then rerun 'wrkslots status'",
                slot_type=slot_type,
            )
            continue
        for slot in sorted(actual - expected[slot_type]):
            remedy = (
                f"inspect the directory, then run 'wrkslots register {slot} --help' to "
                "record a live agent slot"
                if slot_type == "agent"
                else "inspect the retained validation directory, then run "
                "'wrkslots import-existing --help'"
            )
            note(
                "directory-without-row",
                "directory",
                f"{root / slot} exists but no active {slot_type} row claims it",
                remedy,
                slot=slot,
                slot_type=slot_type,
            )

    return tuple(
        sorted(
            findings,
            key=lambda item: (
                item.machine or "",
                item.slot_type or "",
                item.slot or "",
                item.checkout or "",
                item.kind,
            ),
        )
    )


def _validate_journal_shape(
    config: Config, path: Path, raw: Mapping[str, object]
) -> None:
    """Validate durable journal structure without inspecting or mutating its targets."""

    if _as_int(raw.get("schema"), "recovery journal.schema") != SCHEMA:
        raise StateError("unsupported recovery journal schema")
    machine = _as_str(raw.get("machine"), "recovery journal.machine")
    kind = _as_str(raw.get("kind"), "recovery journal.kind")
    slot = _validate_name(
        _as_str(raw.get("slot"), "recovery journal.slot"), "slot"
    )
    expected_paths = {_journal_path(config, machine)}
    if kind == "create":
        expected_paths.add(_create_journal_path(config, slot, machine))
    elif kind == "finish":
        expected_paths.add(_finish_journal_path(config, slot, machine))
    if path not in expected_paths:
        raise StateError(
            "recovery journal filename does not match its machine, operation, and slot"
        )
    if kind == "create":
        _exact_keys(
            raw, _CREATE_JOURNAL_REQUIRED, _CREATE_JOURNAL_OPTIONAL, "create journal"
        )
        _validate_name(_as_str(raw["agent"], "create journal.agent"), "agent")
        if not _as_str(raw["task"], "create journal.task") or not _as_str(
            raw["purpose"], "create journal.purpose"
        ):
            raise StateError("create journal has an empty task or purpose")
        _parse_timestamp(
            _as_str(raw["created_at"], "create journal.created_at"),
            "create journal.created_at",
        )
        _parse_timestamp(
            _as_str(raw["heartbeat_at"], "create journal.heartbeat_at"),
            "create journal.heartbeat_at",
        )
        _as_int(
            raw["heartbeat_ttl_seconds"],
            "create journal.heartbeat_ttl_seconds",
            minimum=1,
        )
        owner = _identity_from_obj(raw["owner"], "create journal.owner")
        task_scope = (
            None
            if "task_scope" not in raw
            else _task_scope_from_obj(raw["task_scope"], "create journal.task_scope")
        )
        _assert_task_scope_matches_owner(task_scope, owner, "create journal.task_scope")
        if (
            _identity_from_obj(
                raw["coordinator_lease"], "create journal.coordinator_lease"
            )
            is None
        ):
            raise StateError("create journal has no coordinator lease")
        planned = _as_list(raw["planned"], "create journal.planned")
        created = _as_list(raw["created"], "create journal.created")
        if not planned:
            raise StateError("create journal contains no planned checkouts")
        for index, item in enumerate(planned):
            _planned_from_obj(item, f"create journal.planned[{index}]")
        for index, item in enumerate(created):
            _checkout_from_obj(item, f"create journal.created[{index}]")
        slot_type = _as_str(raw.get("slot_type", "agent"), "create journal.slot_type")
        if slot_type not in SLOT_TYPES:
            raise StateError("create journal has an invalid slot type")
        _as_int(raw.get("hook_progress", 0), "create journal.hook_progress")
        hooks = _as_list(
            raw.get("post_provision_hooks", []),
            "create journal.post_provision_hooks",
        )
        for index, hook in enumerate(hooks):
            _validate_hook(
                _as_str(hook, f"create journal.post_provision_hooks[{index}]")
            )
        failure = raw.get("hook_failure")
        if failure is not None:
            _as_mapping(failure, "create journal.hook_failure")
        if "failure_policy" in raw:
            _as_str(raw["failure_policy"], "create journal.failure_policy")
        if "operation_id" in raw and not re.fullmatch(
            r"[0-9a-f]{32}",
            _as_str(raw["operation_id"], "create journal.operation_id"),
        ):
            raise StateError("create journal has an invalid operation_id")
    elif kind == "import-existing":
        _exact_keys(raw, _IMPORT_JOURNAL_REQUIRED, set(), "import journal")
        record = _record_from_obj(raw["record"], "import journal.record")
        if record.machine != machine or record.slot != slot:
            raise StateError("import journal record does not match its shard or slot")
    elif kind == "finish":
        _exact_keys(
            raw, _FINISH_JOURNAL_REQUIRED, _FINISH_JOURNAL_OPTIONAL, "finish journal"
        )
        record = _record_from_obj(raw["record"], "finish journal.record")
        if record.machine != machine or record.slot != slot:
            raise StateError("finish journal record does not match its shard or slot")
        if path == _finish_journal_path(config, slot, machine) and (
            record.slot_type != "validate"
            or raw.get("validate_complete") is not True
            or "validation_removal_proof" in raw
        ):
            raise StateError(
                "scoped finish journal is not a direct completed-validation removal"
            )
        mode = _as_str(raw["mode"], "finish journal.mode")
        actor = _as_str(raw["actor"], "finish journal.actor")
        if mode != "remove" or actor != "coordinator":
            raise StateError("finish journal actor does not match its operation")
        finished_at = _as_str(raw["finished_at"], "finish journal.finished_at")
        _parse_timestamp(finished_at, "finish journal.finished_at")
        expected_archive_id = f"{machine}:{record.slot}:{record.generation}:{finished_at}"
        if _as_str(raw["archive_id"], "finish journal.archive_id") != expected_archive_id:
            raise StateError("finish journal archive_id does not match its record")
        phase = _as_str(raw["phase"], "finish journal.phase")
        if phase not in {"prepared", "fenced", "removed"}:
            raise StateError(f"unknown finish journal phase {phase!r}")
        _as_str(raw["fenced"], "finish journal.fenced")
        for index, item in enumerate(_as_list(raw["removed"], "finish journal.removed")):
            _as_str(item, f"finish journal.removed[{index}]")
        for index, item in enumerate(
            _as_list(raw.get("salvage", []), "finish journal.salvage")
        ):
            _as_mapping(item, f"finish journal.salvage[{index}]")
        if "validate_complete" in raw and not isinstance(
            raw["validate_complete"], bool
        ):
            raise StateError("finish journal.validate_complete must be boolean")
        if "nested_git_evidence" in raw:
            _nested_git_evidence_from_obj(
                raw["nested_git_evidence"], "finish journal.nested_git_evidence"
            )
            if record.slot_type != "agent":
                raise StateError(
                    "finish journal records nested Git evidence for a non-agent slot"
                )
        if "original_mode" in raw:
            original_mode = _as_int(
                raw["original_mode"], "finish journal.original_mode"
            )
            if original_mode > 0o7777:
                raise StateError("finish journal.original_mode exceeds permission bits")
        if "private_census_identity" in raw:
            identity = _private_cleanup_identity_from_obj(
                raw["private_census_identity"],
                "finish journal.private_census_identity",
            )
            del identity
            if "original_mode" not in raw:
                raise StateError(
                    "finish journal private census identity has no original mode"
                )
        if "validation_removal_proof" in raw:
            proof = _validation_removal_proof_from_obj(
                raw["validation_removal_proof"],
                "finish journal.validation_removal_proof",
            )
            if (
                record.slot_type != "validate"
                or len(record.checkouts) != 1
                or proof.slot != record.slot
                or proof.generation != record.generation
                or "private_census_identity" not in raw
            ):
                raise StateError(
                    "finish journal validation removal proof does not match one "
                    "privately sealed validation checkout"
                )
    elif kind == "legacy-validate-remove":
        _exact_keys(
            raw,
            _LEGACY_VALIDATE_JOURNAL_REQUIRED,
            set(),
            "legacy validate removal journal",
        )
        for field in (
            "phase",
            "checkout",
            "repository",
            "completed_record",
            "completed_record_sha256",
            "head",
        ):
            _as_str(raw[field], f"legacy validate removal journal.{field}")
        if _identity_from_obj(raw["actor"], "legacy validate removal journal.actor") is None:
            raise StateError("legacy validate removal journal has no actor")
        if not isinstance(raw["coordinator_authorized"], bool):
            raise StateError(
                "legacy validate removal journal.coordinator_authorized must be boolean"
            )
    elif kind == "ownerless-validate-remove":
        _exact_keys(
            raw,
            _OWNERLESS_VALIDATE_JOURNAL_REQUIRED,
            _OWNERLESS_VALIDATE_JOURNAL_OPTIONAL,
            "ownerless validation journal",
        )
        phase = _as_str(raw["phase"], "ownerless validation journal.phase")
        if phase not in _OWNERLESS_VALIDATION_PHASES:
            raise StateError(f"unknown ownerless validation phase {phase!r}")
        _as_str(raw["fenced"], "ownerless validation journal.fenced")
        _validation_authorization_from_obj(raw["authorization"])
        if "exclusion" in raw:
            _ownerless_validation_paths(
                dataclasses.replace(config, machine=machine), raw
            )
    elif kind == "ownerless-agent-remove":
        _ownerless_agent_journal_inputs(dataclasses.replace(config, machine=machine), raw)
    elif kind == "ownerless-agent-cache-relocate":
        _ownerless_agent_cache_journal_inputs(
            dataclasses.replace(config, machine=machine), raw
        )
    elif kind == "recover-absent-validate-rows":
        _exact_keys(
            raw,
            _ABSENT_VALIDATE_JOURNAL_REQUIRED,
            set(),
            "absent-validation-row journal",
        )
        _absent_validate_batch_items(dataclasses.replace(config, machine=machine), raw)
    elif kind == "recover-absent-agent-row":
        _absent_agent_journal_inputs(dataclasses.replace(config, machine=machine), raw)
    else:
        raise StateError(f"unsupported recovery journal kind {kind!r}")


def _completed_create_record(
    config: Config, raw: Mapping[str, object]
) -> ActiveRecord:
    """Reconstruct the only ACTIVE row that can discharge a completed create."""

    machine = _as_str(raw["machine"], "create journal.machine")
    slot = _validate_name(_as_str(raw["slot"], "create journal.slot"), "slot")
    agent = _validate_name(_as_str(raw["agent"], "create journal.agent"), "agent")
    slot_type = _as_str(raw.get("slot_type", "agent"), "create journal.slot_type")
    if slot_type not in SLOT_TYPES:
        raise StateError("create journal has an invalid slot type")
    planned = tuple(
        _planned_from_obj(item, f"create journal.planned[{index}]")
        for index, item in enumerate(
            _as_list(raw["planned"], "create journal.planned")
        )
    )
    created = tuple(
        _checkout_from_obj(item, f"create journal.created[{index}]")
        for index, item in enumerate(
            _as_list(raw["created"], "create journal.created")
        )
    )
    if len(created) != len(planned):
        raise StateError("completed create journal has an incomplete checkout plan")
    for item, checkout in zip(planned, created, strict=True):
        if (
            checkout.name,
            checkout.path,
            checkout.repository,
            checkout.branch,
            checkout.start_point,
            checkout.remote,
            checkout.remote_url_sha256,
            checkout.landed_ref,
            checkout.head,
        ) != (
            item.name,
            item.destination,
            item.repository,
            item.branch,
            item.start_point,
            item.remote,
            item.remote_url_sha256,
            item.landed_ref,
            item.start_point,
        ):
            raise StateError("completed create journal differs from its checkout plan")
    hooks = _string_tuple(
        raw.get("post_provision_hooks", []),
        "create journal.post_provision_hooks",
        _validate_hook,
        unique=False,
    )
    if hooks != config.post_provision_hooks:
        raise StateError("create journal post-provision hooks differ from configuration")
    if (
        _as_int(raw.get("hook_progress", 0), "create journal.hook_progress")
        != len(planned) * len(hooks)
        or raw.get("hook_failure") is not None
    ):
        raise StateError("completed create journal has unfinished post-provision hooks")
    heartbeat_ttl_seconds = _as_int(
        raw["heartbeat_ttl_seconds"],
        "create journal.heartbeat_ttl_seconds",
        minimum=1,
    )
    if heartbeat_ttl_seconds != config.heartbeat_ttl_seconds:
        raise StateError("create journal heartbeat TTL differs from configuration")
    owner = _identity_from_obj(raw["owner"], "create journal.owner")
    task_scope = (
        None
        if "task_scope" not in raw
        else _task_scope_from_obj(raw["task_scope"], "create journal.task_scope")
    )
    _assert_task_scope_matches_owner(task_scope, owner, "create journal.task_scope")
    coordinator = _identity_from_obj(
        raw["coordinator_lease"], "create journal.coordinator_lease"
    )
    if coordinator is None:
        raise StateError("create journal has no coordinator lease")
    created_at = _as_str(raw["created_at"], "create journal.created_at")
    heartbeat_at = _as_str(raw["heartbeat_at"], "create journal.heartbeat_at")
    _parse_timestamp(created_at, "create journal.created_at")
    _parse_timestamp(heartbeat_at, "create journal.heartbeat_at")
    task = _as_str(raw["task"], "create journal.task")
    purpose = _as_str(raw["purpose"], "create journal.purpose")
    if not task or not purpose:
        raise StateError("create journal has an empty task or purpose")
    return ActiveRecord(
        slot=slot,
        agent=agent,
        task=task,
        purpose=purpose,
        slot_type=slot_type,
        machine=machine,
        generation=1,
        created_at=created_at,
        heartbeat_at=heartbeat_at,
        heartbeat_ttl_seconds=heartbeat_ttl_seconds,
        owner=owner,
        coordinator_lease=coordinator,
        coordinator_recovery_note=None,
        handoff=None,
        checkouts=created,
        task_scope=task_scope,
    )


def _scoped_operation_journal_opens(
    journal: Mapping[str, object], operation: str
) -> bool:
    """Return whether progress is the first write of a scoped operation."""

    if operation == "finish":
        return journal.get("phase") == "prepared"
    return journal.get("created") == [] and journal.get("hook_progress") == 0


def _scoped_operation_identity(
    journal: Mapping[str, object], operation: str
) -> str | None:
    """Return the value one scoped operation keeps and every new one replaces.

    Each finish chooses its ``fenced`` name with a fresh uuid4 and keeps it for
    every phase, including a rollback's.  Each create records a fresh uuid4
    ``operation_id``; create journals written before that field existed have
    none.  ``archive_id`` cannot serve: it embeds a one-second timestamp, so a
    retry within the same second repeats it.
    """

    value = journal.get("fenced" if operation == "finish" else "operation_id")
    return value if isinstance(value, str) else None


def _scoped_operation_journal_completed(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    operation: str,
) -> bool:
    """Verify event-first provenance for one scoped journal path.

    The path names only the machine and slot, so one path can carry several
    operations: a rolled-back finish completes while its ACTIVE row remains,
    and the retry writes the same path again.  Each completion closes an
    episode, and progress after it opens the next one only at the operation's
    first phase and with an operation identity that no earlier episode on the
    path used.  Every later progress in an episode carries the identity it
    opened with, and no progress may carry a completed episode's identity, so
    a replayed write of a completed operation is refused wherever it lands.
    The bytes must equal the latest progress, and completion is that of the
    latest episode.
    """

    label = f"scoped {operation} journal"
    machine = _as_str(raw["machine"], f"{operation} journal.machine")
    slot = _validate_name(
        _as_str(raw["slot"], f"{operation} journal.slot"), "slot"
    )
    recorded: Mapping[str, object] | None = None
    completed = False
    current: str | None = None
    retired: set[str] = set()
    for event in _load_events(config, machine):
        event_kind = _as_str(event["kind"], "append-only event.kind")
        if event_kind not in {"operation-progress-recorded", "operation-completed"}:
            continue
        payload = _as_mapping(event["payload"], "append-only event.payload")
        journal = (
            _as_mapping(payload.get("journal"), "append-only operation journal")
            if event_kind == "operation-progress-recorded"
            else None
        )
        event_path = _operation_event_journal_path(
            config, machine, payload, journal=journal
        )
        if event_path != path:
            continue
        if event_kind == "operation-progress-recorded":
            assert journal is not None
            identity = _scoped_operation_identity(journal, operation)
            if completed and (
                not _scoped_operation_journal_opens(journal, operation)
                or identity is None
            ):
                raise StateError(
                    f"{label} path was reused after completion without a new "
                    "operation"
                )
            if identity in retired:
                raise StateError(
                    f"{label} path was reopened with the identity of a completed "
                    "operation"
                )
            if recorded is None or completed:
                current = identity
            elif identity != current:
                raise StateError(
                    f"{label} progress changed its operation identity"
                )
            recorded = journal
            completed = False
            continue
        if recorded is None:
            raise StateError(f"scoped {operation} completion has no preceding progress evidence")
        if current is not None:
            retired.add(current)
        completed = True
    if recorded is None:
        raise StateError(f"{label} has no matching append-only progress evidence")
    if not _json_equal(raw, recorded):
        raise StateError(f"{label} differs from append-only progress evidence")
    return completed


def _scoped_create_journal_completed(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    states: Sequence[ActiveState] | None = None,
) -> bool:
    """Verify event-first provenance and return whether publication completed."""

    machine = _as_str(raw["machine"], "create journal.machine")
    slot = _validate_name(_as_str(raw["slot"], "create journal.slot"), "slot")
    if path != _create_journal_path(config, slot, machine):
        raise StateError("scoped create journal filename does not match its target")
    completed = _scoped_operation_journal_completed(config, path, raw, "create")
    if completed:
        expected = _completed_create_record(config, raw)
        selected_states = (
            tuple(states)
            if states is not None
            else tuple(_load_all_active(config, require_repository=False))
        )
        matches = [
            record
            for state in selected_states
            if state.machine == expected.machine
            for record in state.slots
            if record.slot == expected.slot
        ]
        if len(matches) != 1 or _record_to_obj(matches[0]) != _record_to_obj(expected):
            raise StateError(
                "completed scoped create journal has no exact durable ACTIVE row"
            )
    return completed


def _validate_journal_provenance(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    states: Sequence[ActiveState] | None = None,
) -> bool:
    """Validate journal bytes against their required durable provenance."""

    _validate_journal_shape(config, path, raw)
    machine = _as_str(raw.get("machine"), "recovery journal.machine")
    if path == _journal_path(config, machine):
        pending = _pending_journal_for_path(config, path)
        if pending is not None and not _json_equal(raw, pending):
            raise StateError(
                "standalone recovery journal differs from append-only operation evidence"
            )
        return False
    if raw.get("kind") == "create":
        return _scoped_create_journal_completed(config, path, raw, states)
    if raw.get("kind") == "finish":
        machine = _as_str(raw["machine"], "finish journal.machine")
        slot = _validate_name(_as_str(raw["slot"], "finish journal.slot"), "slot")
        if path != _finish_journal_path(config, slot, machine):
            raise StateError("scoped finish journal filename does not match its target")
        return _scoped_operation_journal_completed(config, path, raw, "finish")
    raise StateError("only create and finish journals may use a scoped journal path")


def _read_stable_physical_journal(
    config: Config,
    path: Path,
    states: Sequence[ActiveState] | None = None,
) -> tuple[Mapping[str, object], _RegularFileIdentity, bool]:
    if not path.exists() and not path.is_symlink():
        raise StateError(
            f"recovery journal {path} is missing while append-only history still names it"
        )
    contents, identity = _read_regular_file_identity(
        path, "recovery journal", 1024 * 1024
    )
    raw = _strict_json_object(contents, "recovery journal")
    completed = _validate_journal_provenance(config, path, raw, states)
    return raw, identity, completed


def _create_journal_items(
    config: Config,
    raw: Mapping[str, object],
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    *,
    completed: bool,
) -> tuple[
    str,
    str,
    str,
    str,
    Path,
    tuple[PlannedCheckout, ...],
    tuple[Checkout, ...],
    tuple[Checkout, ...],
    tuple[str, ...],
]:
    machine = _as_str(raw["machine"], "create journal.machine")
    slot = _validate_name(_as_str(raw["slot"], "create journal.slot"), "slot")
    agent = _validate_name(_as_str(raw["agent"], "create journal.agent"), "agent")
    slot_type = _as_str(raw.get("slot_type", "agent"), "create journal.slot_type")
    if slot_type not in SLOT_TYPES:
        raise StateError("create journal has an invalid slot type")
    if not completed and any(
        record.slot == slot for state in states for record in state.slots
    ):
        raise StateError(
            f"create journal for slot {slot!r} has already reached ACTIVE publication"
        )
    if any(
        record.get("slot") == slot
        for archive in archives
        for record in archive.records
    ):
        raise StateError(f"create journal for slot {slot!r} conflicts with an archive")
    planned = tuple(
        _planned_from_obj(item, f"create journal.planned[{index}]")
        for index, item in enumerate(
            _as_list(raw["planned"], "create journal.planned")
        )
    )
    created = tuple(
        _checkout_from_obj(item, f"create journal.created[{index}]")
        for index, item in enumerate(
            _as_list(raw["created"], "create journal.created")
        )
    )
    if not planned or len({item.name for item in planned}) != len(planned):
        raise StateError("create journal has an empty or duplicate checkout plan")
    if len({item.name for item in created}) != len(created):
        raise StateError("create journal has duplicate completed checkouts")
    if [item.name for item in created] != [
        item.name for item in planned[: len(created)]
    ]:
        raise StateError("create journal's completed checkouts are not a planned prefix")
    hooks = _string_tuple(
        raw.get("post_provision_hooks", []),
        "create journal.post_provision_hooks",
        _validate_hook,
        unique=False,
    )
    if hooks != config.post_provision_hooks:
        raise StateError("create journal post-provision hooks differ from configuration")
    if raw.get("failure_policy") != "leave-for-inspection":
        raise StateError("create journal has an unsupported hook failure policy")
    progress = _as_int(raw.get("hook_progress", 0), "create journal.hook_progress")
    if progress > len(created) * len(hooks):
        raise StateError("create journal ran hooks for an unrecorded checkout")
    failure_raw = raw.get("hook_failure")
    if failure_raw is not None:
        failure = _as_mapping(failure_raw, "create journal.hook_failure")
        _exact_keys(
            failure,
            {"checkout", "hook_index", "command", "status"},
            {"returncode", "detail"},
            "create journal.hook_failure",
        )
        if (
            not hooks
            or progress >= len(planned) * len(hooks)
            or len(created) != len(planned)
        ):
            raise StateError("create journal hook failure is inconsistent with progress")
        hook_index = progress % len(hooks)
        failure_status = _as_str(
            failure["status"], "create journal.hook_failure.status"
        )
        if (
            _as_str(
                failure["checkout"], "create journal.hook_failure.checkout"
            )
            != planned[progress // len(hooks)].name
            or _as_int(
                failure["hook_index"], "create journal.hook_failure.hook_index"
            )
            != hook_index
            or _as_str(
                failure["command"], "create journal.hook_failure.command"
            )
            != hooks[hook_index]
            or failure_status not in {"running", "failed", "failed-to-start"}
        ):
            raise StateError("create journal hook failure does not match its progress")
        if failure_status == "running":
            if "returncode" in failure or "detail" in failure:
                raise StateError(
                    "running create hook records impossible completion details"
                )
        elif failure_status == "failed":
            returncode = failure.get("returncode")
            if (
                not isinstance(returncode, int)
                or isinstance(returncode, bool)
                or returncode == 0
                or "detail" in failure
            ):
                raise StateError("failed create hook has invalid completion details")
        elif (
            "returncode" in failure
            or not _as_str(
                failure.get("detail"), "create journal.hook_failure.detail"
            ).strip()
        ):
            raise StateError(
                "failed-to-start create hook has invalid completion details"
            )
    slot_path = _slot_directory(config, slot, slot_type)
    created_by_name = {item.name: item for item in created}
    observed: list[Checkout] = []
    dirty: list[str] = []
    expected_entries: set[str] = set()
    vcs = _GitVcs()
    for item in planned:
        expected_path, destination = _checkout_path(config, slot, item.name, slot_type)
        if item.destination != expected_path:
            raise StateError(
                f"create journal destination for {item.name} does not match slot {slot}"
            )
        _stored_repository, repository = _stored_repository_path(
            config, item.repository
        )
        if item.landed_ref != _landed_ref_for_remote(config, item.remote):
            raise StateError(
                f"create journal target for {item.name} differs from configured authority"
            )
        if vcs.remote_url_sha256(repository, item.remote) != item.remote_url_sha256:
            raise Refusal(f"create journal remote changed for {item.name}")
        recorded = created_by_name.get(item.name)
        if recorded is None:
            if destination.exists() or destination.is_symlink():
                raise StateError(f"create journal has an unrecorded path at {destination}")
            if destination.absolute() in vcs.listed_worktrees(repository):
                raise StateError(
                    f"create journal has an unrecorded Git worktree at {destination}"
                )
            if vcs.branch_exists(repository, item.branch):
                raise StateError(
                    f"create journal has an unrecorded branch {item.branch!r}"
                )
            continue
        expected = (
            item.destination,
            item.repository,
            item.branch,
            item.start_point,
            item.remote,
            item.remote_url_sha256,
            item.landed_ref,
            item.start_point,
        )
        actual = (
            recorded.path,
            recorded.repository,
            recorded.branch,
            recorded.start_point,
            recorded.remote,
            recorded.remote_url_sha256,
            recorded.landed_ref,
            recorded.head,
        )
        if actual != expected:
            raise StateError(
                f"create journal's completed checkout {item.name} differs from its plan"
            )
        if destination.is_symlink() or not destination.is_dir():
            raise StateError(f"create journal checkout is missing or unsafe: {destination}")
        observed_head = vcs.verify_existing_worktree(repository, destination)
        observed_branch = vcs.branch(destination)
        if observed_branch != recorded.branch:
            raise StateError(
                f"create journal checkout {item.name} changed its registered branch"
            )
        observed.append(
            dataclasses.replace(
                recorded,
                head=observed_head,
                containing_remote_refs=(),
            )
        )
        if vcs.status(
            destination, _cache_globs_for(config, item.name), refresh_index=False
        ):
            dirty.append(item.name)
        expected_entries.add(item.name)
    if slot_path.exists() or slot_path.is_symlink():
        if slot_path.is_symlink() or not slot_path.is_dir():
            raise StateError(f"create journal slot path is unsafe: {slot_path}")
        if config.layout == "nested" and {
            entry.name for entry in slot_path.iterdir()
        } != expected_entries:
            raise StateError(f"create journal slot {slot!r} contains unrecorded paths")
    elif created:
        raise StateError(f"create journal has checkouts below missing slot {slot!r}")
    for state in states:
        for record in state.slots:
            if completed and state.machine == machine and record.slot == slot:
                continue
            active_path = _slot_directory(config, record.slot, record.slot_type)
            if _path_is_within(slot_path, active_path) or _path_is_within(
                active_path, slot_path
            ):
                raise StateError(
                    f"create journal slot {slot!r} overlaps active slot "
                    f"{state.machine}/{record.slot}"
                )
    return (
        machine,
        slot,
        agent,
        slot_type,
        slot_path,
        planned,
        created,
        tuple(observed),
        tuple(dirty),
    )


def _classify_create_journal(
    config: Config,
    path: Path,
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
) -> _CreateJournalClassification:
    raw, identity, completed = _read_stable_physical_journal(
        config, path, states
    )
    if raw.get("kind") != "create":
        raise Refusal(
            f"interrupted {raw.get('kind')!r} mutation {path.name} cannot coexist "
            "with an operation that permits only verified disjoint create journals"
        )
    owner = _identity_from_obj(raw["owner"], "create journal.owner")
    coordinator = _identity_from_obj(
        raw["coordinator_lease"], "create journal.coordinator_lease"
    )
    owner_state, owner_detail = _process_state(owner)
    coordinator_state, coordinator_detail = _process_state(coordinator)
    if not completed:
        if "indeterminate" in {owner_state, coordinator_state}:
            raise Refusal(
                f"create journal for slot {raw.get('slot')!r} process state is "
                f"indeterminate: owner={owner_state} ({owner_detail}); "
                f"coordinator={coordinator_state} ({coordinator_detail})"
            )
        if owner_state != coordinator_state or owner_state not in {"live", "dead"}:
            raise Refusal(
                f"create journal for slot {raw.get('slot')!r} has disagreeing process "
                f"state: owner={owner_state} ({owner_detail}); "
                f"coordinator={coordinator_state} ({coordinator_detail})"
            )
    machine, slot, agent, slot_type, slot_path, planned, created, observed, dirty = (
        _create_journal_items(
            config, raw, states, archives, completed=completed
        )
    )
    rebound_owner_state, _rebound_owner_detail = _process_state(owner)
    rebound_coordinator_state, _rebound_coordinator_detail = _process_state(coordinator)
    if not completed and (
        rebound_owner_state != owner_state
        or rebound_coordinator_state != coordinator_state
    ):
        raise Refusal(f"create journal for slot {slot!r} changed liveness while read")
    rebound, rebound_identity = _read_regular_file_identity(
        path, "recovery journal", 1024 * 1024
    )
    if (
        rebound_identity != identity
        or _strict_json_object(rebound, "recovery journal") != raw
    ):
        raise Refusal(f"create journal changed while it was classified: {path}")
    return _CreateJournalClassification(
        path,
        identity,
        machine,
        slot,
        agent,
        slot_type,
        slot_path,
        planned,
        created,
        observed,
        dirty,
        owner_state,
        owner_detail,
        coordinator_state,
        coordinator_detail,
        "completed-create" if completed else f"{owner_state}-incomplete-create",
    )


def _classify_create_journals(
    config: Config,
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    *,
    excluded_paths: AbstractSet[Path] = frozenset(),
) -> tuple[_CreateJournalClassification, ...]:
    rows = tuple(
        _classify_create_journal(config, path, states, archives)
        for path in _outstanding_journals(config)
        if path not in excluded_paths
    )
    seen_slots: set[tuple[str, str]] = set()
    seen_agents: set[str] = set()
    for row in rows:
        key = (row.machine, row.slot)
        if key in seen_slots:
            raise StateError(
                f"multiple interrupted creates claim {row.machine}/{row.slot}"
            )
        seen_slots.add(key)
        if row.slot_type == "agent" and row.agent in seen_agents:
            raise StateError(f"multiple interrupted creates claim agent {row.agent!r}")
        if row.slot_type == "agent":
            seen_agents.add(row.agent)
    return rows


def _assert_create_journal_classifications_stable(
    config: Config,
    rows: Sequence[_CreateJournalClassification],
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    *,
    excluded_paths: AbstractSet[Path] = frozenset(),
) -> None:
    outstanding = tuple(
        path for path in _outstanding_journals(config) if path not in excluded_paths
    )
    if tuple(row.path for row in rows) != outstanding:
        raise Refusal("recovery journal set changed while it was classified")
    for row in rows:
        contents, identity = _read_regular_file_identity(
            row.path, "recovery journal", 1024 * 1024
        )
        if identity != row.file_identity:
            raise Refusal(f"create journal changed while it was classified: {row.path}")
        raw = _strict_json_object(contents, "recovery journal")
        completed = _validate_journal_provenance(config, row.path, raw, states)
        if completed != (row.state == "completed-create"):
            raise Refusal(
                f"create journal completion changed while it was classified: {row.path}"
            )
        if not completed:
            owner = _identity_from_obj(raw["owner"], "create journal.owner")
            coordinator = _identity_from_obj(
                raw["coordinator_lease"], "create journal.coordinator_lease"
            )
            if (
                _process_state(owner)[0] != row.owner_state
                or _process_state(coordinator)[0] != row.coordinator_state
            ):
                raise Refusal(
                    f"create journal liveness changed while it was classified: {row.path}"
                )
        (
            _machine,
            _slot,
            _agent,
            _slot_type,
            _slot_path,
            _planned,
            _created,
            observed,
            dirty,
        ) = _create_journal_items(
            config, raw, states, archives, completed=completed
        )
        if observed != row.observed or dirty != row.dirty_checkouts:
            raise Refusal(
                f"create journal checkout state changed while it was classified: {row.path}"
            )


def _assert_interrupted_creates_unrelated(
    config: Config,
    rows: Sequence[_CreateJournalClassification],
    *,
    slot: str,
    agent: str,
    slot_type: str,
    plan: Sequence[PlannedCheckout] = (),
) -> None:
    target = _slot_directory(config, slot, slot_type)
    for row in rows:
        if row.slot == slot:
            raise Refusal(
                f"interrupted create already targets slot {slot!r}; recover that exact slot"
            )
        if slot_type == row.slot_type == "agent" and row.agent == agent:
            raise Refusal(
                f"interrupted create already belongs to agent {agent!r}; recover it first"
            )
        if _path_is_within(target, row.slot_path) or _path_is_within(
            row.slot_path, target
        ):
            raise Refusal(
                f"requested slot path {target} overlaps interrupted create "
                f"{row.machine}/{row.slot}"
            )
        for requested in plan:
            requested_repository = _stored_repository_path(
                config, requested.repository
            )[1]
            requested_path = _stored_path(
                config, requested.destination, "checkout destination"
            )
            for existing in row.planned:
                existing_repository = _stored_repository_path(
                    config, existing.repository
                )[1]
                existing_path = _stored_path(
                    config, existing.destination, "create journal checkout destination"
                )
                if _path_is_within(requested_path, existing_path) or _path_is_within(
                    existing_path, requested_path
                ):
                    raise Refusal(
                        f"checkout destination {requested_path} overlaps interrupted "
                        f"create {row.machine}/{row.slot}/{existing.name}"
                    )
                if (
                    requested_repository == existing_repository
                    and requested.branch == existing.branch
                ):
                    raise Refusal(
                        f"branch {requested.branch!r} is claimed by interrupted create "
                        f"{row.machine}/{row.slot}"
                    )


def _assert_interrupted_creates_unrelated_to_record(
    config: Config,
    rows: Sequence[_CreateJournalClassification],
    record: ActiveRecord,
) -> None:
    """Require every classified create to be disjoint from one active record."""

    _assert_interrupted_creates_unrelated(
        config,
        rows,
        slot=record.slot,
        agent=record.agent,
        slot_type=record.slot_type,
        plan=tuple(
            PlannedCheckout(
                name=item.name,
                destination=item.path,
                repository=item.repository,
                branch=item.branch,
                start_point=item.start_point,
                remote=item.remote,
                remote_url_sha256=item.remote_url_sha256,
                landed_ref=item.landed_ref,
            )
            for item in record.checkouts
        ),
    )


def _classify_disjoint_create_journals_for_record(
    config: Config,
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    record: ActiveRecord,
    *,
    excluded_paths: AbstractSet[Path] = frozenset(),
) -> tuple[_CreateJournalClassification, ...]:
    rows = _classify_create_journals(
        config, states, archives, excluded_paths=excluded_paths
    )
    _assert_interrupted_creates_unrelated_to_record(config, rows, record)
    return rows


def _recheck_disjoint_create_journals_for_record(
    config: Config,
    rows: Sequence[_CreateJournalClassification],
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    record: ActiveRecord,
    *,
    excluded_paths: AbstractSet[Path] = frozenset(),
) -> None:
    _assert_create_journal_classifications_stable(
        config, rows, states, archives, excluded_paths=excluded_paths
    )
    _assert_interrupted_creates_unrelated_to_record(config, rows, record)


def _journal_inconsistencies(
    config: Config, journals: Sequence[Path]
) -> tuple[StorageInconsistency, ...]:
    """Report unreadable standalone journals without withholding readable rows."""

    findings: list[StorageInconsistency] = []
    for path in journals:
        legacy_name = re.fullmatch(
            r"ACTIVE\.([A-Za-z0-9][A-Za-z0-9._-]{0,63})\.journal", path.name
        )
        machine: str | None = None if legacy_name is None else legacy_name.group(1)
        try:
            if path.exists() or path.is_symlink():
                raw = _as_mapping(
                    _read_json(path, "recovery journal"), "recovery journal"
                )
            else:
                pending_only = _pending_journal_for_path(config, path)
                if pending_only is None:
                    raise StateError(
                        "journal has neither standalone nor append-only evidence"
                    )
                raw = pending_only
            machine = _as_str(raw.get("machine"), "recovery journal.machine")
            _validate_journal_provenance(config, path, raw)
        except (Refusal, StateError) as exc:
            findings.append(
                StorageInconsistency(
                    kind="journal-unreadable",
                    scope="journal",
                    slot=None,
                    slot_type=None,
                    machine=machine,
                    checkout=None,
                    detail=f"cannot trust outstanding journal {path}: {exc}",
                    remedy="preserve the journal and append-only events; repair their exact "
                    "disagreement before any lifecycle mutation",
                )
            )
            continue
    return tuple(findings)


def _assert_record_storage_consistent(
    config: Config,
    record: ActiveRecord,
    *,
    vcs: _GitVcs | None = None,
) -> None:
    """Require the storage named by one authoritative record to be intact."""

    _assert_slot_contents(config, record)
    verifier = vcs or _GitVcs()
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path")
        _relative, repository = _stored_repository_path(config, checkout.repository)
        verifier.verify_existing_worktree(repository, path)


def _assert_record_registered(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
) -> None:
    """Check a row that a command does not name, without per-checkout Git probes.

    The outcome only decides whether the row is named in an advisory warning,
    so this reads the slot directory and each repository's worktree list, which
    a memoizing verifier lists once per repository. It omits the worktree-root,
    common-directory and HEAD probes, three Git processes per checkout, that
    kept the mutation locks held for tens of seconds on a large registry.
    ``wrkslots audit`` still runs those probes for every row.
    """

    _assert_slot_contents(config, record)
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path")
        _relative, repository = _stored_repository_path(config, checkout.repository)
        if path.is_symlink() or not path.is_dir():
            raise Refusal(f"checkout path is missing or not a real directory: {path}")
        if path.absolute() not in vcs.listed_worktrees(repository):
            raise Refusal(f"Git does not list {path} as a worktree of {repository}")


def _target_storage_refusal(
    message: str,
    remedy: str | None,
    record: ActiveRecord,
    *,
    before_any_change: bool,
) -> StateError:
    if before_any_change:
        return _TargetStorageDrift(message, record=record, remedy=remedy)
    return StateError(message, remedy=remedy)


def _assert_target_record_storage_consistent(
    config: Config,
    states: Sequence[ActiveState],
    record: ActiveRecord,
    *,
    before_any_change: bool = False,
) -> None:
    """Refuse physical or Git drift attributable to one requested record.

    ``before_any_change`` marks the check that ``remove`` makes before its
    first change to the slot; only that check reports the drift as
    ``_TargetStorageDrift``.
    """

    authoritative_state = next(
        (
            state
            for state in states
            if state.machine == record.machine and record in state.slots
        ),
        None,
    )
    if authoritative_state is None:
        raise StateError(
            f"slot {record.machine}/{record.slot} is not in the validated active state"
        )
    findings = _registry_storage_inconsistencies(
        config,
        (dataclasses.replace(authoritative_state, slots=(record,)),),
    )
    for finding in findings:
        if (
            finding.slot == record.slot
            and finding.slot_type == record.slot_type
            and finding.machine in {None, record.machine}
        ):
            raise _target_storage_refusal(
                finding.detail,
                finding.remedy,
                record,
                before_any_change=before_any_change,
            )
    _assert_no_cross_repository_target_registrations(
        config, states, record, before_any_change=before_any_change
    )


def _assert_no_cross_repository_target_registrations(
    config: Config,
    states: Sequence[ActiveState],
    record: ActiveRecord,
    *,
    before_any_change: bool = False,
) -> None:
    """Reject any available repository registration entering the target slot."""

    vcs = _GitVcs()
    target_slot = _slot_directory(config, record.slot, record.slot_type).absolute()
    expected_common_by_path: dict[Path, Path] = {}
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path").absolute()
        _relative, repository = _stored_repository_path(config, checkout.repository)
        expected_common_by_path[path] = vcs.common_directory(repository)

    repository_paths: set[Path] = set()
    for state in states:
        for active_record in state.slots:
            for checkout in active_record.checkouts:
                try:
                    _relative, repository = _stored_repository_path(
                        config, checkout.repository
                    )
                except Refusal:
                    continue
                repository_paths.add(repository)
    inspected_common: set[Path] = set()
    for repository in sorted(repository_paths):
        try:
            common = vcs.common_directory(repository)
            if common in inspected_common:
                continue
            registered_paths = vcs.listed_worktrees(repository)
        except Refusal:
            # Availability outside the selected record is intentionally not a
            # precondition for removing the selected target.
            continue
        inspected_common.add(common)
        for registered_path in registered_paths:
            registered = registered_path.absolute()
            if not _path_is_within(registered, target_slot):
                continue
            if expected_common_by_path.get(registered) == common:
                continue
            raise _target_storage_refusal(
                f"source repository {repository} (Git common directory {common}) "
                f"registers unexpected path {registered} inside target slot "
                f"{record.slot}",
                "inspect every recorded repository's 'git worktree list "
                "--porcelain' output and remove the unexpected target-slot "
                "registration before retrying removal",
                record,
                before_any_change=before_any_change,
            )


@dataclasses.dataclass(frozen=True)
class RegistryStorageFindings:
    """Registry and disk disagreements, separated by whose problem they are.

    Both are real defects and neither is discarded. They are carried apart
    because a command operating on one slot needs different responses to them:
    an entry naming its own slot must stop it, and an entry belonging to some
    other slot must be reported to the operator instead of stopping it.
    """

    #: ``slot_type:slot`` for a directory with no active row.
    unexpected: tuple[str, ...] = ()
    #: ``slot_type:slot`` for an active row whose storage is missing or
    #: inconsistent, excluding the slot the command named -- that one raises.
    stale: tuple[str, ...] = ()
    #: ``slot_type:slot`` for a Git-registered path inside the managed root with
    #: no active row, excluding the slot the command named -- that one raises.
    registrations: tuple[str, ...] = ()


@dataclasses.dataclass(frozen=True)
class _RemoteAuthority:
    """Exact remote destination selected before any network operation."""

    url: str
    sha256: str


def _assert_registry_storage_consistent(
    config: Config,
    states: Sequence[ActiveState],
    allowed_unregistered_slot: tuple[str, str] | None = None,
    *,
    allow_unregistered_migration_slots: bool = False,
    target_slot: str | None = None,
    scope_to_target: bool = False,
) -> RegistryStorageFindings:
    scope_to_target = scope_to_target or target_slot is not None
    records = [record for state in states for record in state.slots]
    expected_slots = {
        slot_type: {record.slot for record in records if record.slot_type == slot_type}
        for slot_type in SLOT_TYPES
    }
    # ⚠️ ONE ROW'S DEFECT MUST NOT REFUSE ANOTHER SLOT'S COMMAND. This loop
    # raised on the FIRST inconsistent record it reached, so a command naming
    # slot X died on a defect in unrelated slot Y and the message named Y. The
    # failure surfaced inside the new agent's operation while the cause belonged
    # to a slot it had never touched, so the agent investigated its own state and
    # found nothing wrong. Two lanes did exactly that.
    #
    # Measured 2026-09-03 on devbig014: 47 of 92 registered rows fail this check
    # and 11 call sites gate on it. A precondition that half the population fails
    # is not gating work, it is stopping arbitrary work -- nobody clears 47 rows
    # incidentally. `wrkslots adopt demos-calib` reported `lander-3`, which is not
    # special and was merely first in iteration order; repairing that one
    # directory would have cleared the message and left the other 46 behind.
    #
    # THE CHECK IS NOT REMOVED AND NOTHING IS SWEPT. Those 47 rows ARE a
    # lifecycle defect: they outlived their directories and nothing retired them.
    # A defect in the slot the command NAMES still refuses, and now refuses
    # naming that slot rather than an unrelated one, so a genuinely inconsistent
    # operation is still refused. A defect anywhere else is collected and
    # reported BY NAME by the caller, and the command proceeds.
    #
    # Scoping loses no reporting. `wrkslots audit` already names this exact
    # condition per slot in its `reasons` field -- verified 2026-09-03, audit
    # exits 0 and reports it for every one of the 47 -- and the caller here adds
    # a named warning on top. What scoping removes is only the REFUSAL of an
    # unrelated command, which told the operator nothing actionable because it
    # named one arbitrary slot and hid the rest.
    #
    # This generalises the direction `_assert_target_record_storage_consistent`
    # already took for `read-handoff`: scope the refusal to the requested record.
    #
    # Slot names are unique across both slot types -- `_active_from_obj` refuses
    # a duplicate -- so matching the target by name alone is unambiguous and needs
    # no slot type from the caller's arguments.
    #
    # ⚠️ WITH NO TARGET SCOPE THIS STILL RAISES, DELIBERATELY. Ownerless
    # validation recovery supplies an explicit scope because its exact path is
    # checked independently below; a bare recovery command still raises.
    #
    # Callers hold the mutation locks here, so the Git work must not grow with
    # the number of rows the command does not name. One memoizing verifier lists
    # each repository's worktrees once, and a row outside the scope gets only the
    # checks that decide whether the warning names it.
    stale: list[str] = []
    vcs = _AuditGitVcs()
    for record in records:
        try:
            if scope_to_target and record.slot != target_slot:
                _assert_record_registered(config, record, vcs)
            else:
                _assert_record_storage_consistent(config, record, vcs=vcs)
        except Refusal:
            if not scope_to_target or record.slot == target_slot:
                raise
            stale.append(f"{record.slot_type}:{record.slot}")
    unexpected: list[str] = []
    for slot_type, root in _slot_roots(config).items():
        if not root.exists():
            continue
        if root.is_symlink() or not root.is_dir():
            raise StateError(f"managed {slot_type} slots directory is unsafe: {root}")
        actual_slots = {
            entry.name
            for entry in root.iterdir()
            if (entry.is_dir() or entry.is_symlink())
            and not entry.name.startswith("EVENTS.")
            and entry != config.control / "wrkslots"
            and not _is_representation_directory(config, entry)
            and not (
                slot_type == "agent"
                and entry == _validate_slots_directory(config)
            )
        }
        unexpected.extend(
            f"{slot_type}:{slot}" for slot in sorted(actual_slots - expected_slots[slot_type])
        )
    # Only registration findings are used, and they depend on the worktree lists
    # alone, so the per-checkout identity probes are skipped.
    registration_findings = tuple(
        item
        for item in _registry_storage_inconsistencies(
            config, states, vcs=vcs, verify_row_identity=False
        )
        if item.kind == "git-registration-without-row"
    )
    # ⚠️ THE SAME SCOPING THE `stale` LOOP ABOVE ALREADY APPLIES, AND IT WAS
    # MISSING HERE. That earlier fix scoped one of this function's three checks
    # and left two global, so the defect it describes survived in a second
    # shape: a Git-registered path inside the managed root with no row refused
    # every mutating command for every lane. Measured 2026-09-04 on devbig014,
    # one such directory -- `lander-2-pr2799-final` -- refused `adopt`, `hold`
    # and `finish` for FIVE unrelated agents, each of which read a message
    # naming a slot it had never touched, investigated its own state, found
    # nothing wrong, and correctly declined to repair another lane's worktree.
    # Nobody saw it as one row refusing for everyone.
    #
    # A PARTIAL SCOPING IS THE HAZARD, not the presence of a check. Scoping one
    # of three left the message still arriving, still naming a foreign slot, and
    # still unactionable -- while the comment above read as though the class had
    # been dealt with.
    #
    # NOTHING IS SWEPT AND NOTHING IS WEAKENED. A registration overlapping the
    # slot the command NAMES still refuses, and still names that slot. A
    # registration that cannot be attributed to any slot still refuses, because
    # an unattributable finding cannot be proven unrelated. Everything else is
    # collected and reported BY NAME by the caller.
    retained_registrations: list[str] = []
    for finding in registration_findings:
        key = (
            f"{finding.slot_type}:{finding.slot}"
            if finding.slot_type is not None and finding.slot is not None
            else None
        )
        is_migration_directory = key is not None and key in unexpected
        is_allowed_target = (
            key is not None
            and allowed_unregistered_slot is not None
            and key == f"{allowed_unregistered_slot[0]}:{allowed_unregistered_slot[1]}"
        )
        if is_migration_directory and (
            allow_unregistered_migration_slots or is_allowed_target
        ):
            continue
        if (
            scope_to_target
            and finding.slot is not None
            and finding.slot != target_slot
        ):
            retained_registrations.append(key or finding.detail)
            continue
        raise StateError(finding.detail, remedy=finding.remedy)
    if allowed_unregistered_slot is not None:
        allowed_slot_type, allowed_slot = allowed_unregistered_slot
        unexpected = [
            value
            for value in unexpected
            if value != f"{allowed_slot_type}:{allowed_slot}"
        ]
    # The third check, scoped for the same reason. A bare directory with no row
    # is a real lifecycle defect, but only the one occupying the path THIS
    # command names can affect it; the rest are returned and named by the
    # caller. With no target slot every entry still refuses, as above.
    blocking_unexpected = (
        [value for value in unexpected if value.split(":", 1)[1] == target_slot]
        if scope_to_target
        else list(unexpected)
    )
    if blocking_unexpected and not allow_unregistered_migration_slots:
        slot_type, slot = blocking_unexpected[0].split(":", 1)
        if slot_type == "agent":
            remedy = (
                "run 'wrkslots audit --format json', then "
                f"'wrkslots register {slot} --help' and register the live checkout "
                "with --agent, --task, --purpose, --owner-pid, --coordinator-pid, "
                "--verified-live, and --repo. Put --allow-existing-unregistered-worktrees "
                "before unrelated commands only during deliberate migration; do not delete "
                "the directory to repair bookkeeping"
            )
        else:
            remedy = (
                "run 'wrkslots audit --format json', then import the retained validation "
                "state with 'wrkslots import-existing --help'"
            )
        raise StateError(
            "managed worktrees directory has a directory without an active row: "
            f"{blocking_unexpected[0]}. state: REFUSED -- no registered slot or "
            "unregistered directory was changed",
            remedy=remedy,
        )
    return RegistryStorageFindings(
        tuple(unexpected),
        tuple(sorted(stale)),
        tuple(sorted(set(retained_registrations))),
    )


def _assert_command_registry_storage(
    config: Config,
    states: Sequence[ActiveState],
    args: argparse.Namespace,
    *,
    allowed_unregistered_slot: tuple[str, str] | None = None,
    migration_operation: bool = False,
    target_slot: str | None = None,
    scope_to_target: bool = False,
) -> None:
    allow = bool(
        migration_operation
        or getattr(args, "allow_existing_unregistered_worktrees", False)
    )
    # The slot this command names. Every gated command except `recover` takes
    # one, and slot names are unique across both slot types, so the name alone
    # identifies the row whose defect must still stop this command.
    argument_slot = getattr(args, "slot", None)
    if target_slot is None and isinstance(argument_slot, str) and argument_slot:
        target_slot = argument_slot
    findings = _assert_registry_storage_consistent(
        config,
        states,
        allowed_unregistered_slot=allowed_unregistered_slot,
        allow_unregistered_migration_slots=allow,
        target_slot=target_slot,
        scope_to_target=scope_to_target or target_slot is not None,
    )
    unexpected = findings.unexpected
    if findings.stale:
        # ⚠️ NAMED, NOT COUNTED. This defect survived because the old refusal
        # printed ONE slot -- whichever came first -- so a reader repaired that
        # directory and believed it fixed. Listing every affected row is what
        # makes the real scale visible from the message itself.
        shown = ", ".join(findings.stale[:12])
        more = f" (+{len(findings.stale) - 12} more)" if len(findings.stale) > 12 else ""
        print(
            f"WARNING: {len(findings.stale)} registered slot(s) have missing or "
            "inconsistent storage. state: RETAINED -- this command targets different "
            "storage, changed none of these rows, and did not inspect them: "
            f"{shown}{more}. remedy: these rows outlived their directories; retire each "
            "one through its own lifecycle command rather than deleting rows in bulk, "
            "because a row is also what protects a slot holding an unread HANDOFF.md",
            file=sys.stderr,
        )
    if unexpected:
        # ⚠️ NOT GATED ON `allow` ANY MORE. It used to be, because without the
        # flag this condition always raised, so the warning was unreachable.
        # Now that a directory belonging to another slot is retained instead of
        # refusing, gating the warning would make the scoping SILENT -- which is
        # worse than the refusal it replaces.
        shown = ", ".join(sorted(unexpected)[:12])
        more = f" (+{len(unexpected) - 12} more)" if len(unexpected) > 12 else ""
        print(
            f"WARNING: {len(unexpected)} existing unregistered worktree directories "
            "remain outside wrkslots records. state: RETAINED -- this command will not "
            f"inspect, select, or remove them: {shown}{more}. remedy: run "
            "'wrkslots audit --format json' and import each live slot from verified "
            "process evidence",
            file=sys.stderr,
        )
    if findings.registrations:
        shown = ", ".join(findings.registrations[:12])
        more = (
            f" (+{len(findings.registrations) - 12} more)"
            if len(findings.registrations) > 12
            else ""
        )
        print(
            f"WARNING: {len(findings.registrations)} Git-registered path(s) inside the "
            "managed root have no active row. state: RETAINED -- this command named a "
            "different target, changed none of them, and did not inspect them: "
            f"{shown}{more}. remedy: run 'wrkslots audit --format json', then restore "
            "and register each live slot, or retire the stale Git registration through "
            "its own lifecycle command; do not delete a directory to repair bookkeeping, "
            "because the directory may hold the only reference to unpushed work",
            file=sys.stderr,
        )


def _global_rows(
    states: Sequence[ActiveState], archives: Sequence[ArchiveState]
) -> dict[tuple[str, str, str], object]:
    rows: dict[tuple[str, str, str], object] = {}
    for state in states:
        for record in state.slots:
            rows[("active", state.machine, record.slot)] = _record_to_obj(record)
    for archive in archives:
        for archive_record in archive.records:
            slot = _as_str(archive_record.get("slot"), "archive slot")
            rows[("archive", archive.machine, slot)] = dict(archive_record)
    return rows


def _assert_only_slot_changed(
    before: Mapping[tuple[str, str, str], object],
    after: Mapping[tuple[str, str, str], object],
    slot: str,
) -> None:
    before_unrelated = {key: value for key, value in before.items() if key[2] != slot}
    after_unrelated = {key: value for key, value in after.items() if key[2] != slot}
    if before_unrelated != after_unrelated:
        raise StateError(f"mutation of slot {slot!r} changed an unrelated registry row")


def _find_record(state: ActiveState, slot: str) -> ActiveRecord:
    for record in state.slots:
        if record.slot == slot:
            return record
    raise Refusal(f"slot {slot!r} is not active on machine {state.machine}")


def _replace_record(state: ActiveState, record: ActiveRecord) -> ActiveState:
    found = False
    slots: list[ActiveRecord] = []
    for current in state.slots:
        if current.slot == record.slot:
            slots.append(record)
            found = True
        else:
            slots.append(current)
    if not found:
        raise StateError(f"cannot replace missing slot {record.slot}")
    return ActiveState(state.machine, state.revision + 1, tuple(slots))


def _delete_record(state: ActiveState, slot: str) -> ActiveState:
    slots = tuple(record for record in state.slots if record.slot != slot)
    if len(slots) == len(state.slots):
        raise StateError(f"cannot remove missing slot {slot}")
    return ActiveState(state.machine, state.revision + 1, slots)


def _append_record(state: ActiveState, record: ActiveRecord) -> ActiveState:
    if any(item.slot == record.slot for item in state.slots):
        raise Refusal(f"slot {record.slot!r} is already active")
    if record.slot_type == "agent" and record.import_source is None and any(
        item.slot_type == "agent"
        and item.import_source is None
        and item.agent == record.agent
        for item in state.slots
    ):
        raise Refusal(f"agent {record.agent!r} already owns an active slot")
    return ActiveState(state.machine, state.revision + 1, (*state.slots, record))


def _with_proxy(command: Sequence[str], env: Mapping[str, str]) -> list[str]:
    """Use the host's network wrapper when installed, without a direct retry."""

    wrapper = shutil.which("with-proxy", path=env.get("PATH"))
    return [str(Path(wrapper).absolute()), *command] if wrapper is not None else list(command)


# Git and its transports print these when no connection to the remote was made.
_REMOTE_TRANSPORT_UNAVAILABLE = re.compile(
    r"CONNECT tunnel failed, response \d{3}"
    r"|Received HTTP code \d{3} from proxy after CONNECT"
    r"|Could not resolve (?:host|proxy|hostname)\b"
    r"|Failed to connect to \S+ port \d+"
    r"|Connection refused"
    r"|Connection timed out"
    r"|Network is unreachable",
    re.IGNORECASE,
)
# Any of these means the remote, or something claiming to be it, answered, or
# the caller or the remote was refused on identity. A command that prints one is
# not an outage. Git relays server messages over HTTP and during a pack transfer
# with a ``remote:`` prefix, so such text that merely mentions a connection
# failure also vetoes. Over SSH the server's stderr arrives unprefixed, so the
# forms a server prints there are listed on their own.
_REMOTE_AUTHORITY_FAILURE = re.compile(
    r"^remote:"
    r"|remote error:"
    r"|Authentication failed"
    r"|Proxy Authentication Required"
    r"|(?:response|HTTP code) 407\b"
    r"|could not read (?:Username|Password)"
    r"|Invalid username or password"
    r"|Permission denied \("
    r"|Host key verification failed"
    r"|REMOTE HOST IDENTIFICATION HAS CHANGED"
    r"|certificate"
    r"|The requested URL returned error"
    r"|Repository not found"
    r"|does not appear to be a git repository",
    re.IGNORECASE | re.MULTILINE,
)


def _remote_transport_unavailable(output: str) -> bool:
    """Return whether failed Git network output shows only an absent connection."""

    return bool(
        _REMOTE_TRANSPORT_UNAVAILABLE.search(output)
        and not _REMOTE_AUTHORITY_FAILURE.search(output)
    )


def _control_character(value: str) -> str | None:
    """Return the first control or line-separator character in ``value``, if any.

    That is a C0 or C1 control, DEL, or U+2028/U+2029: every character Python's
    str.splitlines() splits at, and every character urllib.parse.urlsplit()
    removes or strips. Git treats none of them specially in a path, so a path
    holding one can mean one thing to Git and another to Python.
    """

    for character in value:
        code = ord(character)
        if code < 0x20 or 0x7F <= code <= 0x9F or code in (0x2028, 0x2029):
            return character
    return None


def _refuse_control_characters(value: str, label: str) -> None:
    """Refuse ``value`` if it holds a character _control_character finds."""

    character = _control_character(value)
    if character is not None:
        raise Refusal(
            f"{label} holds the control character {character!r}, which Git and this "
            "check would read differently, so where it leads cannot be proven: "
            f"{value!r}"
        )


# Git's is_url(): a scheme of URL characters, its first alphanumeric, then
# "://". Anything else is a local path or the host:path spelling.
_GIT_URL_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9+.-]*://")


def _git_url_decode(text: str) -> bytes:
    """Decode percent escapes in ``text`` exactly as Git's url_decode() does.

    Git decodes a % followed by two hexadecimal digits only when the byte they
    name is not zero; %00 and any malformed escape stay as written. Python's
    unquote decodes %00 to a NUL byte, which names a different path, and one no
    path operation accepts.
    """

    raw = text.encode("utf-8", "surrogateescape")
    decoded = bytearray()
    index = 0
    while index < len(raw):
        escape = raw[index + 1 : index + 3]
        if (
            raw[index] == ord("%")
            and len(escape) == 2
            and all(byte in b"0123456789abcdefABCDEF" for byte in escape)
            and int(escape, 16) != 0
        ):
            decoded.append(int(escape, 16))
            index += 3
            continue
        decoded.append(raw[index])
        index += 1
    return bytes(decoded)


def _remote_url_local_text(url: str) -> str | None:
    """Return the local path Git uses for remote ``url``, or None for a remote transport.

    Follows Git's parse_connect_url(): only a URL whose scheme is exactly
    "file" names a local path; Git decodes the whole URL first, ignores the
    host, and uses everything from the first slash after "file://", "?" and
    "#" included. Of the hosts Git ignores this accepts only none and
    "localhost", and refuses any other, since naming one suggests a meaning
    Git does not give it. A string that is no URL is Git's host:path spelling
    when a colon precedes any slash, and otherwise a local path.
    """

    if _GIT_URL_RE.match(url):
        if not url.startswith("file://"):
            return None
        remainder = _git_url_decode(url).removeprefix(b"file://")
        if remainder.startswith(b"localhost/"):
            remainder = remainder.removeprefix(b"localhost")
        if not remainder.startswith(b"/"):
            raise Refusal(f"ambiguous file remote URL cannot be proven safe: {url!r}")
        try:
            return remainder.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise Refusal("file remote URL path is not valid UTF-8") from exc
    colon = url.find(":")
    slash = url.find("/")
    if colon >= 0 and (slash < 0 or colon < slash):
        return None
    return url


def _local_remote_url_path(repository: Path, url: str) -> Path | None:
    """Return a conservative local path for a Git remote URL, if it has one.

    A URL with a control character, or a leading space, refuses: Git keeps
    them where Python path and URL handling would split at or strip them, so
    the path checked might not be the path Git uses. The path itself is the one
    Git derives (_remote_url_local_text).
    """

    _refuse_control_characters(url, "remote URL")
    if url[:1].isspace():
        raise Refusal(f"remote URL begins with white space: {url!r}")
    text = _remote_url_local_text(url)
    if text is None:
        return None
    candidate = Path(text)
    if not candidate.is_absolute():
        candidate = repository / candidate
    return candidate


def _github_credential_helper_args(env: Mapping[str, str]) -> tuple[str, ...]:
    """Return an explicit GitHub credential helper without loading global Git config."""

    configured = env.get("FLEET_REAL_GH")
    candidate = configured or shutil.which("gh", path=env.get("PATH"))
    if candidate is None:
        return ()
    path = Path(candidate)
    try:
        resolved = path.resolve(strict=True)
    except OSError as exc:
        if configured is not None:
            raise Refusal(f"configured GitHub CLI is unavailable: {path}: {exc}") from exc
        return ()
    if not resolved.is_file() or not os.access(resolved, os.X_OK):
        if configured is not None:
            raise Refusal(f"configured GitHub CLI is not executable: {resolved}")
        return ()
    return (
        "-c",
        "credential.helper=",
        "-c",
        f"credential.helper=!{shlex.quote(str(resolved))} auth git-credential",
    )


def _git_failure_detail(result: subprocess.CompletedProcess[str]) -> str:
    """Name a Git probe's exit status and diagnostic, for a refusal that cannot classify it."""

    status = (
        f"signal {-result.returncode}"
        if result.returncode < 0
        else f"exit {result.returncode}"
    )
    detail = (result.stderr or result.stdout).strip()
    return f" ({status})" + (f": {detail}" if detail else "")


def _git_bytes_failure_detail(result: subprocess.CompletedProcess[bytes]) -> str:
    """_git_failure_detail for a command run with _GitVcs._run_bytes."""

    return _git_failure_detail(
        subprocess.CompletedProcess(
            result.args,
            result.returncode,
            "",
            result.stderr.decode("utf-8", errors="backslashreplace"),
        )
    )


def _display_git_path(path: bytes) -> str:
    """Show a path name Git reported, escaping bytes that are not printable UTF-8."""

    return "".join(
        character if character.isprintable() else repr(character)[1:-1]
        for character in path.decode("utf-8", errors="backslashreplace")
    )


def _git_config_quoted(value: str, what: str) -> bytes:
    """Return ``value`` as a double-quoted Git config value.

    Git config reads a backslash and a double quote inside quotes only as
    escapes, so both are escaped. A control character cannot be written
    without changing what Git reads back, so it refuses instead.
    """

    if any(ord(character) < 0x20 or ord(character) == 0x7F for character in value):
        raise Refusal(f"{what} contains a control character; it cannot be written to a Git config")
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    return b'"' + escaped.encode("utf-8") + b'"'


@dataclasses.dataclass
class _ItemDeadline:
    """The pre-deletion budget of one remove-agent-batch item.

    See _AGENT_REMOVE_BATCH_ITEM_SECONDS.  ``state`` is ``active`` while the
    budget bounds work, ``paused`` across a stretch that must not be
    interrupted, and ``ended`` once deletion may begin.
    """

    seconds: float
    started_at: float
    state: str = "active"
    seconds_before_deletion: float | None = None

    @property
    def expires_at(self) -> float:
        return self.started_at + self.seconds


# Set only while one remove-agent-batch item holds the registry lock.
_ITEM_DEADLINE: contextvars.ContextVar[_ItemDeadline | None] = contextvars.ContextVar(
    "wrkslots_agent_batch_item_deadline", default=None
)


@dataclasses.dataclass(frozen=True)
class _RemoteContainmentEvidence:
    """Remote branches seen to contain one commit, and when (time.monotonic()).

    ``refusal`` is the refusal the question ended in instead, if it did; it is
    raised again rather than asking the remote a second time.
    """

    refs: tuple[str, ...]
    observed_at: float
    refusal: Refusal | None = None


# Set only while one agent-slot removal runs (see
# _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS).  Maps (object directory,
# remote URL, commit, shallow) to the containment answer that removal obtained before
# it took the registry lock, so the checks made under the lock reuse it
# instead of contacting the remote.  An empty answer is reused too: it leads
# only to a salvage push or a local archive, which keep the work either way.
# So is a refusal, which removal reports exactly as if it were asked again (a
# transport outage still gets its redirect-free confirmation under the lock).
_REMOTE_CONTAINMENT_MEMO: contextvars.ContextVar[
    dict[tuple[str, str, str, bool], _RemoteContainmentEvidence] | None
] = contextvars.ContextVar("wrkslots_remote_containment_memo", default=None)


# Set only while one agent-slot removal runs: the (archive ref and commit,
# sha256, size) of each local salvage bundle it has already restored into a fresh
# bare clone and checked with a full fsck. Removal rechecks a bundle several
# times before it deletes the slot; a recheck of the very same bytes (the
# sha256 and size are always recomputed) need not clone and fsck them again.
_VERIFIED_SALVAGE_BUNDLES: contextvars.ContextVar[
    set[tuple[str, str, int]] | None
] = contextvars.ContextVar("wrkslots_verified_salvage_bundles", default=None)


@dataclasses.dataclass(frozen=True)
class _SalvageFactsEvidence:
    """Facts _salvage_candidate derived for one clean checkout, and how to recheck them.

    ``fingerprint`` is _salvage_fingerprint of the checkout, read before and
    again after those facts were derived and found equal both times;
    ``observed_at`` is when (time.monotonic()).
    """

    facts: _SalvageCandidate
    fingerprint: tuple[object, ...]
    observed_at: float


# Set only while one agent-slot removal runs.  Removal derives the salvage
# facts of every checkout and initialized submodule (_salvage_candidate) once
# before the registry lock (_prefetch_remote_containment) and three more times
# under it: to salvage, and twice to show nothing changed since.  Each
# derivation runs about twenty Git commands per repository; with a dozen
# nested submodules that alone used up most of a remove-agent-batch item's
# budget.  A clean checkout's facts are kept here, keyed by everything the
# derivation is given, and reused only when a fresh _salvage_fingerprint (HEAD,
# branch, configuration, index, status, unfinished operations and history
# state, about eight Git commands) equals the one read when they were derived,
# and for at most _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS.  A dirty
# checkout is always derived again: its status lines do not change when the
# content of an already modified file does, and its salvage commit must hold
# that content.
_SALVAGE_FACTS_MEMO: contextvars.ContextVar[
    dict[tuple[object, ...], _SalvageFactsEvidence] | None
] = contextvars.ContextVar("wrkslots_salvage_facts_memo", default=None)


@dataclasses.dataclass(frozen=True)
class _SubmoduleInventoryEvidence:
    """What _submodule_salvage_checkouts returned for one checkout, and how to recheck it.

    ``inventory`` is the initialized-submodule listing it was derived from,
    and ``sources`` the device and inode of each source submodule directory.
    """

    result: tuple[tuple[Checkout, Path], ...]
    inventory: tuple[str, ...]
    sources: tuple[tuple[int, int], ...]
    observed_at: float


# Set only while one agent-slot removal runs: the submodule checkouts of each
# checkout (_submodule_salvage_checkouts), reused when the listing of
# initialized submodules and the source directories are unchanged.  What the
# reuse skips (each submodule's HEAD, remote URL and the source's remote) is
# read again by the salvage-facts check of that submodule that always follows.
_SUBMODULE_INVENTORY_MEMO: contextvars.ContextVar[
    dict[tuple[object, ...], _SubmoduleInventoryEvidence] | None
] = contextvars.ContextVar("wrkslots_submodule_inventory_memo", default=None)


@contextlib.contextmanager
def _remote_containment_scope() -> Iterator[None]:
    """Keep remote containment answers, salvage facts and bundle verifications for one removal."""

    token = _REMOTE_CONTAINMENT_MEMO.set({})
    bundles = _VERIFIED_SALVAGE_BUNDLES.set(set())
    facts = _SALVAGE_FACTS_MEMO.set({})
    inventories = _SUBMODULE_INVENTORY_MEMO.set({})
    try:
        yield
    finally:
        _SUBMODULE_INVENTORY_MEMO.reset(inventories)
        _SALVAGE_FACTS_MEMO.reset(facts)
        _VERIFIED_SALVAGE_BUNDLES.reset(bundles)
        _REMOTE_CONTAINMENT_MEMO.reset(token)


def _item_budget_refusal(what: str) -> Refusal:
    deadline = _ITEM_DEADLINE.get()
    seconds = _AGENT_REMOVE_BATCH_ITEM_SECONDS if deadline is None else deadline.seconds
    return Refusal(
        f"this remove-agent-batch item used its {seconds:g}-second budget for work "
        f"before deletion at {what}; nothing in the slot was deleted and the slot "
        "was kept; retry it later, or remove it alone with 'wrkslots remove "
        "--no-lock-budget', which has no such budget"
    )


def _item_seconds_left(what: str) -> float | None:
    """Return the item budget left for ``what``, or None when no budget applies.

    Raises Refusal when the budget of the current remove-agent-batch item is
    already spent.
    """

    deadline = _ITEM_DEADLINE.get()
    if deadline is None or deadline.state != "active":
        return None
    remaining = deadline.expires_at - time.monotonic()
    if remaining <= 0:
        raise _item_budget_refusal(what)
    return remaining


def _pause_item_deadline() -> None:
    """Stop bounding work until _resume_item_deadline; the clock keeps running."""

    deadline = _ITEM_DEADLINE.get()
    if deadline is not None and deadline.state == "active":
        deadline.state = "paused"


def _resume_item_deadline() -> None:
    deadline = _ITEM_DEADLINE.get()
    if deadline is not None and deadline.state == "paused":
        deadline.state = "active"


def _end_item_deadline() -> None:
    """Refuse if the budget is spent, then stop bounding the item: deletion follows."""

    deadline = _ITEM_DEADLINE.get()
    if deadline is None or deadline.state == "ended":
        return
    if deadline.state == "active":
        _item_seconds_left("the first deletion")
    deadline.seconds_before_deletion = time.monotonic() - deadline.started_at
    deadline.state = "ended"


def _stop_process_group(
    process: subprocess.Popen[str] | subprocess.Popen[bytes],
) -> None:
    """Terminate, then kill, the process group of ``process``, and reap it."""

    try:
        os.killpg(process.pid, signal.SIGTERM)
    except OSError:
        pass
    try:
        process.communicate(timeout=_AGENT_REMOVE_BATCH_TERM_GRACE_SECONDS)
        return
    except subprocess.TimeoutExpired:
        pass
    # Only an unreaped leader keeps its process-group ID from being reused.
    if process.poll() is None:
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except OSError:
            pass
    try:
        process.communicate(timeout=_AGENT_REMOVE_BATCH_REAP_SECONDS)
    except subprocess.TimeoutExpired:
        # A descendant that left the process group still holds the pipes.
        for stream in (process.stdin, process.stdout, process.stderr):
            if stream is not None:
                with contextlib.suppress(OSError):
                    stream.close()
        with contextlib.suppress(subprocess.TimeoutExpired):
            process.wait(timeout=0)


def _run_within_item_budget(
    command: Sequence[str],
    *,
    seconds: float,
    what: str,
    env: Mapping[str, str] | None = None,
    input_text: str | None = None,
    timeout_refusal: Refusal | None = None,
    errors: str | None = None,
) -> subprocess.CompletedProcess[str]:
    """Run ``command`` as subprocess.run would, for at most ``seconds``.

    The command runs in its own session so that both signals reach every
    process it starts.  When the time runs out it receives SIGTERM first,
    because Git removes its lock files when SIGTERM stops it and leaves them
    when SIGKILL does, then SIGKILL after a grace period, and the item is
    refused, with ``timeout_refusal`` when the bound is not the item budget.
    ``errors`` is the text decoding error handler, as for subprocess.run.
    An OSError from starting the command propagates.
    """

    process = subprocess.Popen(
        list(command),
        stdin=subprocess.PIPE if input_text is not None else None,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        errors=errors,
        env=None if env is None else dict(env),
        start_new_session=True,
    )
    stdout, stderr = _communicate_within(
        process, input_text, seconds=seconds, what=what, timeout_refusal=timeout_refusal
    )
    return subprocess.CompletedProcess(list(command), process.returncode, stdout, stderr)


def _run_bytes_within_item_budget(
    command: Sequence[str],
    *,
    seconds: float,
    what: str,
    env: Mapping[str, str],
    input_bytes: bytes | None,
    timeout_refusal: Refusal | None,
) -> subprocess.CompletedProcess[bytes]:
    """_run_within_item_budget for a command whose input and output are bytes."""

    process = subprocess.Popen(
        list(command),
        stdin=subprocess.PIPE if input_bytes is not None else None,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=dict(env),
        start_new_session=True,
    )
    stdout, stderr = _communicate_within(
        process, input_bytes, seconds=seconds, what=what, timeout_refusal=timeout_refusal
    )
    return subprocess.CompletedProcess(list(command), process.returncode, stdout, stderr)


_Stream = TypeVar("_Stream", str, bytes)


def _communicate_within(
    process: subprocess.Popen[_Stream],
    data: _Stream | None,
    *,
    seconds: float,
    what: str,
    timeout_refusal: Refusal | None,
) -> tuple[_Stream, _Stream]:
    """Communicate with ``process`` for at most ``seconds``, as
    _run_within_item_budget describes."""

    try:
        stdout, stderr = process.communicate(data, timeout=max(0.0, seconds))
    except subprocess.TimeoutExpired:
        _stop_process_group(process)
        if timeout_refusal is not None:
            raise timeout_refusal from None
        raise _item_budget_refusal(what) from None
    except BaseException:
        _stop_process_group(process)
        raise
    return stdout, stderr


@contextlib.contextmanager
def _agent_batch_item_deadline(
    agent_batch: _AgentRemoveBatchContext | None,
) -> Iterator[None]:
    """Bound the pre-deletion work of one remove-agent-batch item.

    Entered once the item holds the registry lock.  Outside a batch it does
    nothing.
    """

    if agent_batch is None:
        yield
        return
    deadline = _ItemDeadline(agent_batch.item_seconds, time.monotonic())
    token = _ITEM_DEADLINE.set(deadline)
    try:
        yield
    finally:
        _ITEM_DEADLINE.reset(token)
        agent_batch.last_seconds_before_deletion = deadline.seconds_before_deletion


@dataclasses.dataclass(frozen=True)
class _WorktreeModule:
    """A submodule repository Git keeps in a linked worktree's administrative directory.

    ``name`` is its path relative to ``administration``, such as
    ``modules/lib`` or ``modules/lib/modules/nested``. ``shared`` is the
    repository at the same relative path in the superproject's common
    directory, which outlives the worktree, or None. A commit is unpublished
    when HEAD, a ref outside refs/remotes/, or a reflog names it, wherever it
    is stored, or this repository stores it in its own object directory and
    nothing names it, and no remote-tracking ref of this repository or of
    ``shared`` reaches it. ``tips``, in name order, are the unpublished
    commits HEAD or such a ref names and those no other unpublished commit
    has as a parent, so their history holds every unpublished commit:
    removing the registration would delete this repository, and with it the
    only local copy of those commits. Recovery keeps the repository instead
    (_retain_worktree_modules), but where no Git command finds it, so it
    salvages those commits first. ``blocking`` describes state the
    repository holds that salvaging commits cannot preserve.

    ``directories`` is, when examined where recovery set the repositories
    aside (_GitVcs.worktree_modules_set_aside), the path relative to
    ``path``, device and inode of ``path`` and of each directory below it,
    read before it was examined (_tree_directory_identities), so recovery can
    show that the directories it keeps are the ones examined
    (_refuse_unexamined_retained_repositories); otherwise empty.
    """

    name: str
    path: Path
    administration: Path
    shared: Path | None
    head: str | None
    tips: tuple[str, ...]
    blocking: tuple[str, ...]
    directories: tuple[tuple[str, int, int], ...] = ()


def _tree_directory_identities(root: Path) -> tuple[tuple[str, int, int], ...]:
    """Return the path relative to ``root``, device and inode of ``root`` and of each directory below it.

    Sorted by path; ``root`` itself is ".". Symbolic links are not
    followed, and an entry found as a directory that is no longer one when
    read refuses. For _WorktreeModule.directories.
    """

    found: list[tuple[str, int, int]] = []
    pending = [Path(".")]
    examined = 0
    while pending:
        relative = pending.pop()
        path = root / relative
        try:
            metadata = os.lstat(path)
        except OSError as exc:
            raise Refusal(f"cannot inspect {path}: {exc}; nothing was removed") from exc
        if not stat.S_ISDIR(metadata.st_mode):
            raise Refusal(
                f"{path} is no longer a directory while the submodule repositories "
                "are examined; nothing was removed. remedy: inspect it, then rerun"
            )
        found.append((relative.as_posix(), metadata.st_dev, metadata.st_ino))
        try:
            with os.scandir(path) as listing:
                for entry in listing:
                    examined += 1
                    if examined > _RETAINED_MODULES_ENTRY_LIMIT:
                        raise Refusal(
                            f"{root} holds more than {_RETAINED_MODULES_ENTRY_LIMIT} "
                            "entries; they cannot all be examined, and nothing was "
                            "removed"
                        )
                    if entry.is_dir(follow_symlinks=False):
                        pending.append(relative / entry.name)
        except OSError as exc:
            raise Refusal(f"cannot list {path}: {exc}; nothing was removed") from exc
    return tuple(sorted(found))


def _worktree_module_directories(
    administration: Path, *, set_aside: bool = False
) -> tuple[tuple[str, Path], ...]:
    """List the submodule repositories under ``administration``/modules, by relative name.

    Git clones each submodule of a linked worktree into
    <administrative directory>/modules/<submodule name>/, and a nested
    submodule into .../modules/<name>/modules/<nested name>/. A submodule name
    may hold slashes, so a directory without a HEAD file is one level of a
    name and is walked. A symlink, a file, or an incomplete repository found
    there refuses: what it holds cannot be examined.

    With ``set_aside`` the walk reads the directory recovery moved modules/
    to (_GitVcs.worktree_modules_set_aside); names stay relative to
    modules/. Without it, finding that directory refuses: it holds
    repositories a stopped recovery moved aside, which the walk of modules/
    would miss.
    """

    aside = administration / _WORKTREE_MODULES_ASIDE
    if set_aside:
        root = aside
    else:
        if aside.exists() or aside.is_symlink():
            raise Refusal(
                f"{aside} holds submodule repositories a recovery moved aside before "
                "it stopped, so they cannot be examined where Git keeps them. "
                "remedy: rerun `wrkslots recover`, which moves them back first; if "
                f"no recovery is pending, rename it to {administration / 'modules'}"
            )
        root = administration / "modules"
        if _is_worktree_modules_placeholder(root):
            raise Refusal(
                f"{root} is the file a recovery puts there while it removes the "
                "submodule repositories, so that recovery stopped before it finished. "
                "remedy: rerun `wrkslots recover`, which removes it first"
            )
    if not root.exists() and not root.is_symlink():
        return ()
    return _module_repositories_below(root)


def _module_repositories_below(root: Path) -> tuple[tuple[str, Path], ...]:
    """List the submodule repositories under ``root``, named "modules/" + their path below it.

    The walk _worktree_module_directories describes: a directory without a
    HEAD file is one level of a name, and a symlink, a file, or an
    incomplete repository refuses.
    """

    found: list[tuple[str, Path]] = []
    examined = 0
    pending: list[tuple[Path, int]] = [(root, 1)]
    while pending:
        directory, depth = pending.pop()
        if depth > _WORKTREE_MODULE_DEPTH_LIMIT:
            raise Refusal(
                f"submodule repositories under {root} nest deeper than "
                f"{_WORKTREE_MODULE_DEPTH_LIMIT} levels; they cannot all be examined"
            )
        if directory.is_symlink() or not directory.is_dir():
            raise Refusal(f"submodule directory Git kept for a worktree is unsafe: {directory}")
        try:
            entries = sorted(directory.iterdir())
        except OSError as exc:
            raise Refusal(f"cannot list submodule directory {directory}: {exc}") from exc
        for entry in entries:
            examined += 1
            if examined > _WORKTREE_MODULE_ENTRY_LIMIT:
                raise Refusal(
                    f"{root} holds more than {_WORKTREE_MODULE_ENTRY_LIMIT} submodule "
                    "directories; they cannot all be examined"
                )
            if entry.is_symlink() or not entry.is_dir():
                raise Refusal(
                    f"submodule directory {directory} holds {entry}, which is not a "
                    "directory; what it holds cannot be examined"
                )
            head = entry / "HEAD"
            if not head.exists() and not head.is_symlink():
                pending.append((entry, depth + 1))
                continue
            if head.is_symlink() or not head.is_file() or any(
                (entry / part).is_symlink() or not (entry / part).is_dir()
                for part in ("objects", "refs")
            ):
                raise Refusal(
                    f"submodule repository {entry} has no regular HEAD file, objects "
                    "directory, and refs directory; it cannot be examined"
                )
            name = "modules/" + entry.relative_to(root).as_posix()
            try:
                os.fsencode(name).decode("utf-8")
            except UnicodeDecodeError:
                raise Refusal(f"submodule repository name is not UTF-8: {entry}") from None
            found.append((name, entry))
            nested = entry / "modules"
            if nested.exists() or nested.is_symlink():
                pending.append((nested, depth + 1))
    return tuple(sorted(found))


def _repository_ref_locks(repository: Path) -> list[str]:
    """Describe each lock Git holds on a ref or other state of ``repository``.

    Git changes HEAD, a ref, packed-refs, or a reftable table list by
    creating <name>.lock and renaming it into place when the change is
    committed. A transaction prepared but not yet committed holds such a
    lock, and the commit it is about to name is in no ref a census reads,
    so salvage would not preserve it. So every *.lock at the top of the repository (other than index.lock,
    which _GitVcs._worktree_module reports by itself) and every one under
    refs/, logs/, and reftable/ is reported; a lock a stopped command left
    reads the same, since nothing tells the two apart.
    """

    found: list[str] = []
    examined = 0
    pending: list[tuple[Path, int]] = [(repository, 0)]
    while pending:
        directory, depth = pending.pop()
        try:
            with os.scandir(directory) as listing:
                entries = sorted(listing, key=lambda entry: entry.name)
        except OSError as exc:
            raise Refusal(f"cannot list {directory}: {exc}") from exc
        for entry in entries:
            examined += 1
            if examined > _MODULE_LOCK_CENSUS_ENTRY_LIMIT:
                raise Refusal(
                    f"{repository} holds more than {_MODULE_LOCK_CENSUS_ENTRY_LIMIT} ref "
                    "entries; they cannot all be examined"
                )
            if depth == 0 and entry.name == "index.lock":
                continue
            if entry.name.endswith(".lock"):
                found.append(
                    f"Git lock {entry.path} exists: a Git command is changing what "
                    f"{repository} names, or one stopped without removing its lock"
                )
                continue
            try:
                directory_entry = entry.is_dir(follow_symlinks=False)
            except OSError as exc:
                raise Refusal(f"cannot inspect {entry.path}: {exc}") from exc
            if not directory_entry or (
                depth == 0 and entry.name not in ("refs", "logs", "reftable")
            ):
                continue
            if depth + 1 > _MODULE_LOCK_CENSUS_DEPTH_LIMIT:
                raise Refusal(
                    f"directories under {directory} nest deeper than "
                    f"{_MODULE_LOCK_CENSUS_DEPTH_LIMIT} levels; they cannot all be examined"
                )
            pending.append((Path(entry.path), depth + 1))
    return found


def _is_recovery_placeholder(path: Path, content: bytes) -> bool:
    """Whether ``path`` is a regular file of exactly ``content``, as _place_recovery_placeholder makes."""

    try:
        metadata = os.lstat(path)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise Refusal(f"cannot inspect {path}: {exc}") from exc
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_size != len(content):
        return False
    return _read_bounded_regular_file(path, "recovery placeholder", len(content)) == content


def _is_worktree_modules_placeholder(root: Path) -> bool:
    """Whether ``root`` is the regular file _place_worktree_modules_placeholder makes."""

    return _is_recovery_placeholder(root, _WORKTREE_MODULES_PLACEHOLDER)


def _place_recovery_placeholder(
    path: Path,
    content: bytes,
    reappeared: str,
    *,
    purpose: str = "a placeholder for removal",
) -> tuple[int, int]:
    """Make ``path`` a regular file of ``content``, so no directory can be made below it.

    Created exclusively, so finding anything there refuses with
    ``reappeared``. ``purpose`` names the file in a refusal. Returns the
    file's device and inode.
    """

    try:
        descriptor = os.open(
            path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
            0o444,
        )
    except FileExistsError:
        raise Refusal(reappeared) from None
    except OSError as exc:
        raise Refusal(f"cannot make {path} {purpose}: {exc}") from exc
    try:
        if os.write(descriptor, content) != len(content):
            raise Refusal(f"cannot write {purpose} {path}")
        os.fsync(descriptor)
        metadata = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    _fsync_directory(path.parent)
    return (metadata.st_dev, metadata.st_ino)


def _place_worktree_modules_placeholder(administration: Path) -> tuple[int, int]:
    """Make the regular file that keeps ``administration``/modules from being a directory.

    Created exclusively, so finding anything there refuses: a Git command
    still running wrote below modules/ after the repositories were moved
    aside. Returns the file's device and inode.
    """

    root = administration / "modules"
    return _place_recovery_placeholder(
        root,
        _WORKTREE_MODULES_PLACEHOLDER,
        f"{root} reappeared once the submodule repositories were moved aside "
        f"to {administration / _WORKTREE_MODULES_ASIDE}: a Git command still "
        "running wrote there. Both are kept and nothing was removed. remedy: "
        "stop that command, merge what it wrote into the set-aside "
        "repositories, rename them back to modules/, then rerun",
    )


@dataclasses.dataclass(frozen=True)
class _RetainedModules:
    """Where absent-agent recovery keeps one checkout's submodule repositories, and whose they are.

    ``path`` is <common>/wrkslots-retained-modules/<slot>+<generation>+<digest>+<name>
    for the administrative directory <common>/worktrees/<name> of a
    checkout of the ACTIVE row ``slot`` at ``generation`` on ``machine``,
    whose record digests to ``record_sha256`` (_record_sha256); <digest> is
    its first 16 hexadecimal digits. The repositories go to modules/ below
    it, as deep below the common Git directory as <administrative
    directory>/modules is. A slot name holds no "+", so two rows never
    share a name; and Git reuses an administrative directory's name once
    the registration that had it is removed, as wrkslots reuses a slot's
    name once its row is gone, which the digest tells apart. The file
    _WORKTREE_MODULES_RETAINED_OWNER in ``path`` names the same row and
    directory (owner); recovery moves nothing out of a directory whose file
    names any other (_restore_worktree_modules_retained).
    """

    path: Path
    machine: str
    slot: str
    generation: int
    record_sha256: str
    administration: str

    def owner(self) -> dict[str, object]:
        """The fields of the owner file that name this row and administrative directory."""

        return {
            "administration": self.administration,
            "generation": self.generation,
            "machine": self.machine,
            "record_sha256": self.record_sha256,
            "schema": 1,
            "slot": self.slot,
        }


def _worktree_modules_retained(
    administration: Path, record: ActiveRecord
) -> _RetainedModules:
    """Return where absent-agent recovery keeps the submodule repositories of ``administration``.

    ``administration`` is the administrative directory of a checkout of
    ``record``; see _RetainedModules.
    """

    if administration.parent.name != "worktrees":
        raise Refusal(
            f"{administration} is not in the worktrees/ directory of a common Git "
            "directory, so recovery cannot tell where to keep its submodule "
            "repositories; nothing was removed"
        )
    slot = _validate_name(record.slot, "slot")
    if record.generation < 1:
        raise Refusal(
            f"row {slot} has generation {record.generation}, so recovery cannot "
            "name where to keep its submodule repositories; nothing was removed"
        )
    digest = _record_sha256(record)
    name = f"{slot}+{record.generation}+{digest[:16]}+{administration.name}"
    if len(os.fsencode(name)) > _FILE_NAME_BYTES_LIMIT:
        raise Refusal(
            f"{name!r}, where recovery would keep the submodule repositories of "
            f"{administration}, is longer than a file name can be; nothing was "
            "removed. remedy: recover this row by hand"
        )
    return _RetainedModules(
        path=administration.parent.parent / _WORKTREE_MODULES_RETAINED / name,
        machine=record.machine,
        slot=slot,
        generation=record.generation,
        record_sha256=digest,
        administration=administration.name,
    )


def _file_kind(mode: int) -> str:
    """Name the kind of file ``mode`` describes, as the owner file of retained repositories records it."""

    if stat.S_ISLNK(mode):
        return "symlink"
    if stat.S_ISDIR(mode):
        return "directory"
    if stat.S_ISREG(mode):
        return "file"
    return "other"


def _administration_entries(administration: Path) -> list[list[str]]:
    """List each path below ``administration`` with its kind, sorted.

    Each path is relative to ``administration``; the walk does not follow
    a symbolic link. The set-aside path and Git's index lock are left out:
    recovery moves the one and holds the other, so neither tells whether
    Git's removal of the registration began.
    """

    entries: list[list[str]] = []
    pending: list[tuple[Path, str]] = [(administration, "")]
    while pending:
        directory, prefix = pending.pop()
        try:
            with os.scandir(directory) as listing:
                for entry in listing:
                    if not prefix and entry.name in (_WORKTREE_MODULES_ASIDE, "index.lock"):
                        continue
                    if len(entries) >= _WORKTREE_MODULES_RETAINED_ENTRY_LIMIT:
                        raise Refusal(
                            f"{administration} holds more than "
                            f"{_WORKTREE_MODULES_RETAINED_ENTRY_LIMIT} entries; nothing "
                            "was removed"
                        )
                    kind = _file_kind(entry.stat(follow_symlinks=False).st_mode)
                    name = prefix + entry.name
                    entries.append([name, kind])
                    if kind == "directory":
                        pending.append((Path(entry.path), name + "/"))
        except OSError as exc:
            raise Refusal(f"cannot list {directory}: {exc}; nothing was removed") from exc
    return sorted(entries)


def _retained_modules_owner_bytes(
    retained: _RetainedModules, entries: Sequence[Sequence[str]]
) -> bytes:
    """The owner file of ``retained``: the row and directory it names, and ``entries``.

    ``entries`` is _administration_entries of the administrative directory
    when the repositories are moved: while each is still there, Git has not
    begun deleting the directory, and the registration is as recovery
    examined it.
    """

    payload: dict[str, object] = {
        **retained.owner(),
        "administration_entries": [list(entry) for entry in entries],
    }
    return (
        json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    ).encode("ascii")


def _read_retained_modules_owner(path: Path) -> dict[str, object] | None:
    """Read the owner file ``path``; None when it does not hold a JSON object.

    Recovery writes it whole and synchronizes it before anything is moved
    beside it, so only a recovery stopped while writing it leaves one that
    does not parse, with nothing beside it.
    """

    content = _read_bounded_regular_file(
        path, "retained submodule repository owner file", _WORKTREE_MODULES_RETAINED_OWNER_BYTES_LIMIT
    )
    try:
        value = json.loads(content.decode("ascii"))
    except (UnicodeDecodeError, ValueError):
        return None
    if not isinstance(value, dict):
        return None
    return {str(key): item for key, item in value.items()}


def _make_retained_modules_directory(
    administration: Path, retained: _RetainedModules
) -> None:
    """Make ``retained``.path, holding only its owner file, for the repositories of ``administration``.

    The directory must not exist yet. The owner file is created
    exclusively and synchronized before this returns.
    """

    owner_bytes = _retained_modules_owner_bytes(
        retained, _administration_entries(administration)
    )
    if len(owner_bytes) > _WORKTREE_MODULES_RETAINED_OWNER_BYTES_LIMIT:
        raise Refusal(
            f"the entries of {administration} do not fit in the file that names "
            "whose submodule repositories recovery keeps; nothing was removed"
        )
    store = retained.path.parent
    try:
        store.mkdir(exist_ok=True)
        _fsync_directory(store.parent)
    except OSError as exc:
        raise Refusal(
            f"cannot make {store} to keep submodule repositories in: {exc}; nothing "
            "was removed"
        ) from exc
    _refuse_unless_real_directory(store, "submodule repository store")
    try:
        retained.path.mkdir()
        _fsync_directory(store)
    except FileExistsError:
        raise Refusal(
            f"{retained.path} already exists: a recovery of this row kept submodule "
            "repositories there before it stopped, or something else made it; "
            "nothing was removed. remedy: rerun `wrkslots recover`, which moves "
            "them back first"
        ) from None
    except OSError as exc:
        raise Refusal(f"cannot make {retained.path}: {exc}; nothing was removed") from exc
    _interrupt_for_test("after-absent-agent-modules-retained-directory")
    owner = retained.path / _WORKTREE_MODULES_RETAINED_OWNER
    _place_recovery_placeholder(
        owner,
        owner_bytes,
        f"{owner} appeared in the directory recovery just made; nothing was removed. "
        "remedy: inspect it, then rerun",
        purpose="the file that names whose submodule repositories it keeps",
    )
    _interrupt_for_test("after-absent-agent-modules-retained-owner")


def _refuse_unless_real_directory(path: Path, label: str) -> None:
    """Refuse unless ``path`` is a directory that is not a symbolic link."""

    try:
        metadata = os.lstat(path)
    except OSError as exc:
        raise Refusal(f"cannot inspect {label} {path}: {exc}") from exc
    if not stat.S_ISDIR(metadata.st_mode):
        raise Refusal(
            f"{label} {path} is not a directory; nothing was removed. remedy: "
            "inspect it, then rerun"
        )


def _retain_worktree_modules(
    administration: Path, retained: _RetainedModules
) -> _DirectoryIdentity:
    """Move the set-aside submodule repositories of ``administration`` to ``retained``.path/modules.

    ``retained``.path must not exist yet; it is made here, with its owner
    file (_make_retained_modules_directory). The repositories move by one
    rename within the common Git directory, so nothing in them is copied,
    changed, or deleted, and a handle a process holds inside them follows
    them. Then a regular file is put at the set-aside path, created
    exclusively, so a Git command still running that names a repository
    by that path cannot make one anew there for the removal of the
    registration to delete. Returns the device and inode of the directory
    at the set-aside path, read just before it is moved, for
    _refuse_unretainable_retained_storage: read after the move, it would
    be that of whatever is at the retained path by then, and a directory
    put there in the meantime would be taken for the one moved.
    """

    aside = administration / _WORKTREE_MODULES_ASIDE
    _make_retained_modules_directory(administration, retained)
    kept = retained.path / "modules"
    try:
        metadata = os.lstat(aside)
        if not stat.S_ISDIR(metadata.st_mode):
            raise Refusal(
                f"{aside} is not a directory once examined; nothing was "
                "removed. remedy: inspect it, then rerun"
            )
        os.rename(aside, kept)
        _fsync_directory(retained.path)
        _fsync_directory(administration)
    except OSError as exc:
        raise Refusal(f"cannot move {aside} to {kept}: {exc}; nothing was removed") from exc
    _interrupt_for_test("after-absent-agent-modules-retained")
    _place_recovery_placeholder(
        aside,
        _WORKTREE_MODULES_ASIDE_PLACEHOLDER,
        f"{aside} reappeared once the submodule repositories were moved from "
        f"there to {kept}: a Git command still running wrote there. Both are "
        "kept and nothing was removed. remedy: stop that command, merge what it "
        f"wrote into {kept}, rename that back to "
        f"{administration / 'modules'}, then rerun",
    )
    _interrupt_for_test("after-absent-agent-modules-aside-placeholder")
    return (metadata.st_dev, metadata.st_ino)


def _restore_worktree_modules_retained(
    administration: Path, retained: _RetainedModules
) -> bool:
    """Move submodule repositories at ``retained``.path/modules back to the set-aside path.

    For a recovery that stopped once _retain_worktree_modules began, while
    Git still registers the checkout of ``administration``. Removes the
    placeholder at the set-aside path first, then the owner file, and
    ``retained``.path itself once nothing else is in it (so also when the
    stop came before anything was moved there). Returns whether anything
    changed.

    Refuses, moving nothing, when that directory holds anything recovery
    does not put there, when its owner file names another row or
    administrative directory, or does not name one while repositories are
    there, or when an entry of ``administration`` that the owner file lists
    is gone or changed kind. That last means Git began deleting the
    administrative directory and stopped partway: Git may no longer
    register it, or remove it whole once it notices that the checkout is
    gone, so the repositories stay where they are kept.
    """

    path = retained.path
    try:
        metadata = os.lstat(path)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise Refusal(f"cannot inspect {path}: {exc}") from exc
    if not stat.S_ISDIR(metadata.st_mode):
        raise Refusal(
            f"{path} is not a directory recovery made to keep submodule "
            "repositories in; nothing was moved. remedy: inspect it, then rerun"
        )
    _refuse_unless_real_directory(path.parent, "submodule repository store")
    try:
        names = sorted(os.listdir(path))
    except OSError as exc:
        raise Refusal(f"cannot list {path}: {exc}; nothing was moved") from exc
    stray = [name for name in names if name not in (_WORKTREE_MODULES_RETAINED_OWNER, "modules")]
    if stray:
        raise Refusal(
            f"{path} holds {path / stray[0]}, which recovery does not put there; "
            "nothing was moved. remedy: inspect it, then rerun"
        )
    owner_file = path / _WORKTREE_MODULES_RETAINED_OWNER
    kept = path / "modules"
    owner = (
        _read_retained_modules_owner(owner_file)
        if _WORKTREE_MODULES_RETAINED_OWNER in names
        else None
    )
    if owner is None and "modules" in names:
        raise Refusal(
            f"{kept} holds submodule repositories, but {owner_file} does not name "
            "the row and administrative directory whose they are; nothing was "
            "moved. remedy: inspect them, then rerun"
        )
    if owner is not None and {
        key: owner.get(key) for key in retained.owner()
    } != retained.owner():
        raise Refusal(
            f"{path} keeps the submodule repositories of another row or "
            f"administrative directory than slot {retained.slot} generation "
            f"{retained.generation}'s {administration} ({owner_file} names slot "
            f"{owner.get('slot')!r} generation {owner.get('generation')!r} and "
            f"directory {owner.get('administration')!r}); nothing was moved. "
            "remedy: inspect it, then rerun"
        )
    if "modules" in names:
        assert owner is not None
        if kept.is_symlink() or not kept.is_dir():
            raise Refusal(
                f"{kept} is not a directory recovery moved there; nothing was moved. "
                "remedy: inspect it, then rerun"
            )
        recorded = owner.get("administration_entries")
        if not isinstance(recorded, list) or not all(
            isinstance(entry, list)
            and len(entry) == 2
            and all(isinstance(part, str) for part in entry)
            for entry in recorded
        ):
            raise Refusal(
                f"{owner_file} does not list the entries of {administration}; "
                "nothing was moved. remedy: inspect it, then rerun"
            )
        for name, kind in recorded:
            if name.startswith("/") or any(
                part in ("", ".", "..") for part in name.split("/")
            ):
                raise Refusal(
                    f"{owner_file} lists {name!r}, which is not a path below "
                    f"{administration}; nothing was moved. remedy: inspect it, then "
                    "rerun"
                )
            try:
                found = _file_kind(os.lstat(administration / name).st_mode)
            except FileNotFoundError:
                found = None
            except OSError as exc:
                raise Refusal(
                    f"cannot inspect {administration / name}: {exc}; nothing was moved"
                ) from exc
            if found != kind:
                raise Refusal(
                    f"Git's removal of the registration in {administration} stopped "
                    f"partway: {administration / name} is gone or changed since the "
                    f"submodule repositories were moved to {kept}. They stay there, "
                    "and nothing was moved. remedy: once nothing left in "
                    f"{administration} is wanted, remove that directory by hand, "
                    "then rerun"
                )
        aside = administration / _WORKTREE_MODULES_ASIDE
        root = administration / "modules"
        placeholder = _is_recovery_placeholder(aside, _WORKTREE_MODULES_ASIDE_PLACEHOLDER)
        # Each path recovery moved them from holds its placeholder or nothing.
        occupied = [
            occupant
            for occupant, placed in (
                (aside, placeholder),
                (root, _is_worktree_modules_placeholder(root)),
            )
            if not placed and (occupant.exists() or occupant.is_symlink())
        ]
        if occupied:
            raise Refusal(
                f"both {occupied[0]} and {kept}, where a stopped recovery moved the "
                "submodule repositories of that administrative directory, exist; "
                "nothing was moved. remedy: merge the two by hand so that "
                f"{root} holds every submodule repository, remove the other, then "
                "rerun"
            )
        try:
            if placeholder:
                aside.unlink()
            # Fails rather than replace a nonempty directory made since the unlink.
            os.rename(kept, aside)
            _fsync_directory(administration)
            _fsync_directory(path)
        except OSError as exc:
            raise Refusal(f"cannot move {kept} back to {aside}: {exc}") from exc
    try:
        if _WORKTREE_MODULES_RETAINED_OWNER in names:
            owner_file.unlink()
        path.rmdir()
        _fsync_directory(path.parent)
    except OSError as exc:
        raise Refusal(
            f"cannot remove {path}, which recovery made to keep submodule "
            f"repositories in and which holds nothing it put there now: {exc}. "
            "remedy: inspect it, remove it once nothing in it is wanted, then rerun"
        ) from exc
    return True


def _restore_worktree_modules_set_aside(
    administration: Path, retained: _RetainedModules
) -> bool:
    """Move back submodule repositories _GitVcs.worktree_modules_set_aside moved.

    ``retained`` is where that recovery keeps them once it has examined
    them. With no administrative directory left, the registration is
    removed and they stay there for good: nothing changes. Otherwise any
    repositories there are moved back to the set-aside path first, unless
    Git began removing the administrative directory, when they stay
    (_restore_worktree_modules_retained); then the placeholder at modules/
    is removed and the set-aside repositories are moved back to modules/.
    Returns whether anything changed. Refuses, moving nothing further, when
    a path holds something recovery did not put there, or when two paths
    both hold repositories: which holds wanted work is not something
    recovery can decide.
    """

    try:
        os.lstat(administration)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise Refusal(f"cannot inspect {administration}: {exc}") from exc
    changed = _restore_worktree_modules_retained(administration, retained)
    aside = administration / _WORKTREE_MODULES_ASIDE
    root = administration / "modules"
    placeholder = _is_worktree_modules_placeholder(root)
    if not aside.exists() and not aside.is_symlink():
        if not placeholder:
            return changed
        # Stopped after making the placeholder with no modules/ to move.
        try:
            root.unlink()
            _fsync_directory(administration)
        except OSError as exc:
            raise Refusal(f"cannot remove the placeholder {root}: {exc}") from exc
        return True
    if aside.is_symlink() or not aside.is_dir():
        raise Refusal(
            f"{aside} is not a directory recovery moved aside; nothing was removed. "
            "remedy: inspect it, remove it by hand if it holds nothing wanted, then "
            "rerun"
        )
    if not placeholder and (root.exists() or root.is_symlink()):
        raise Refusal(
            f"both {root} and {aside}, where a stopped recovery moved the submodule "
            "repositories, exist; nothing was removed. remedy: merge the two by hand "
            "so that modules/ holds every submodule repository, then rerun"
        )
    try:
        if placeholder:
            root.unlink()
        # Fails rather than replace a nonempty modules/ made since the unlink.
        os.rename(aside, root)
        _fsync_directory(administration)
    except OSError as exc:
        raise Refusal(f"cannot move {aside} back to {root}: {exc}") from exc
    return True


@dataclasses.dataclass(frozen=True)
class _MountEntry:
    """One mount, as a line of a /proc/<pid>/mountinfo file shows it (proc(5)).

    ``mount_id`` and ``parent_id`` are the mount's identifier and that of
    the mount it is mounted on; ``point`` is the mount point, decoded;
    ``root`` the directory of the mounted file system shown there, still
    escaped, which for some file systems is not a path; ``fstype`` the file
    system type, with any subtype ("fuse.sshfs"); and ``options`` the super
    options, still escaped.
    """

    mount_id: int
    parent_id: int
    point: Path
    root: bytes
    fstype: str
    options: bytes


_MOUNTINFO_ESCAPE = re.compile(rb"\\([0-3][0-7]{2})")
_MOUNTINFO_STRAY_BACKSLASH = re.compile(rb"\\(?![0-3][0-7]{2})")


def _mountinfo_unescape(raw: bytes) -> bytes:
    """Decode the backslash and three octal digits the kernel writes for some bytes of a mount table field."""

    return _MOUNTINFO_ESCAPE.sub(lambda match: bytes((int(match.group(1), 8),)), raw)


def _mount_entries(table: bytes, label: str) -> tuple[_MountEntry, ...]:
    """Return each mount ``table``, a /proc/<pid>/mountinfo file, lists, in its order.

    proc(5): each mount is one line, ended by a newline, of fields
    separated by one space. The fourth is the root of the mount and the
    fifth its mount point; optional fields run from the seventh to a field
    that is a lone "-", and the file system type, the source, and the super
    options follow it. The kernel writes a space, tab, newline, or
    backslash in a path as a backslash and three octal digits, and every
    other byte as it is, so the table is split only at newline and space
    bytes, and a line of any other form refuses. A later line for the same
    mount point is a mount on top of an earlier one.
    """

    if not table.endswith(b"\n"):
        raise Refusal(f"{label} is empty or does not end with a newline")
    entries: list[_MountEntry] = []
    for line in table[:-1].split(b"\n"):
        fields = line.split(b" ")
        try:
            separator = fields.index(b"-", 6)
        except ValueError:
            raise Refusal(f"{label} has a line without its field separator") from None
        if len(fields) < separator + 4:
            raise Refusal(f"{label} has a line with fewer fields than a mount has")
        # Only the source, after the separator, may be empty.
        if b"" in fields[:separator]:
            raise Refusal(f"{label} has a line with an empty field before its separator")
        raw = fields[4]
        if not raw.startswith(b"/") or _MOUNTINFO_STRAY_BACKSLASH.search(raw):
            raise Refusal(f"{label} has a malformed mount point {raw!r}")
        if not fields[0].isdigit() or not fields[1].isdigit():
            raise Refusal(f"{label} has a line with a malformed mount identifier")
        entries.append(
            _MountEntry(
                mount_id=int(fields[0]),
                parent_id=int(fields[1]),
                point=Path(os.fsdecode(_mountinfo_unescape(raw))),
                root=fields[3],
                fstype=os.fsdecode(fields[separator + 1]),
                options=b" ".join(fields[separator + 3 :]),
            )
        )
    return tuple(entries)


def _mount_points(table: bytes, label: str) -> tuple[Path, ...]:
    """Return the mount point of each mount ``table``, a /proc/<pid>/mountinfo file, lists (_mount_entries)."""

    return tuple(entry.point for entry in _mount_entries(table, label))


def _refuse_mounts_below_administration(administration: Path) -> None:
    """Refuse when the administrative directory ``administration``, or anything below it, is a mount point.

    Removing a registration deletes everything below the administrative
    directory, walking into a directory that is a mount point and deleting
    what the mounted file system holds before failing to remove the
    mount point itself; a bind mount there can hold anything, even the
    objects of the submodule repositories recovery retains. A bind mount of
    a directory on the same file system has the same device, so only the
    mount table shows it. The table names each mount point by its resolved
    path, so ``administration`` is resolved before they are compared. A
    mount made after this check is not seen.
    """

    resolved = Path(os.path.realpath(administration))
    table = _read_bounded_regular_file(
        _SELF_MOUNTINFO, "mount table", _MOUNTINFO_FILE_BYTES_LIMIT
    )
    for point in _mount_points(table, f"mount table {_SELF_MOUNTINFO}"):
        if _path_is_within(point, resolved):
            where = (
                f"the Git administrative directory {administration} is a mount point"
                if point == resolved
                else f"mount point {point} lies below the Git administrative "
                f"directory {administration}"
            )
            raise Refusal(
                f"{where}; removing its registration would delete what the mount "
                "holds. nothing was removed. remedy: unmount it, then rerun"
            )


_DirectoryIdentity = tuple[int, int]


def _directory_identities(
    roots: Sequence[Path], label: str
) -> dict[_DirectoryIdentity, Path]:
    """Map the device and inode of each directory at or below ``roots`` to a path naming it.

    Each directory is identified as a path lookup finds it, so a mount
    point is the root of the file system mounted there, which is what
    deleting through that path reaches. A root that does not exist, or is
    not a directory, adds nothing. ``label`` names the
    directories in a refusal. More entries than
    _RETAINED_MODULES_ENTRY_LIMIT, or one that cannot be read, refuses.
    """

    identities: dict[_DirectoryIdentity, Path] = {}
    pending: list[Path] = []

    def add(path: Path, metadata: os.stat_result) -> None:
        identity = (metadata.st_dev, metadata.st_ino)
        if identity not in identities:
            identities[identity] = path
            pending.append(path)

    for root in roots:
        try:
            metadata = os.stat(root, follow_symlinks=False)
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise Refusal(f"cannot inspect {root} among {label}: {exc}") from exc
        if stat.S_ISDIR(metadata.st_mode):
            add(root, metadata)
    examined = 0
    while pending:
        directory = pending.pop()
        try:
            with os.scandir(directory) as listing:
                for entry in listing:
                    examined += 1
                    if examined > _RETAINED_MODULES_ENTRY_LIMIT:
                        raise Refusal(
                            f"{label} hold more than {_RETAINED_MODULES_ENTRY_LIMIT} "
                            "entries; they cannot all be examined, and nothing was "
                            "removed"
                        )
                    if entry.is_dir(follow_symlinks=False):
                        add(Path(entry.path), entry.stat(follow_symlinks=False))
        except OSError as exc:
            raise Refusal(
                f"cannot list {directory} among {label}: {exc}; nothing was removed"
            ) from exc
    return identities


# File system types that show other directories' contents, merged, as an
# overlay mount does, without saying which: recovery cannot check what
# they read, so a place on one refuses (_refuse_aliases_below).
_UNION_FILE_SYSTEM_TYPES = frozenset(
    {
        "aufs",
        "unionfs",
        "fuse-overlayfs",
        "fuse.fuse-overlayfs",
        "fuse.mergerfs",
        "fuse.bindfs",
        "fuse.unionfs",
        "fuse.unionfs-fuse",
        "fuse.mhddfs",
    }
)


def _read_self_mount_entries() -> tuple[_MountEntry, ...]:
    """Read /proc/self/mountinfo (_mount_entries)."""

    table = _read_bounded_regular_file(
        _SELF_MOUNTINFO, "mount table", _MOUNTINFO_FILE_BYTES_LIMIT
    )
    return _mount_entries(table, f"mount table {_SELF_MOUNTINFO}")


def _procfs_points(entries: Sequence[_MountEntry]) -> tuple[Path, ...]:
    """Return where a proc file system is mounted among ``entries``."""

    return tuple(entry.point for entry in entries if entry.fstype == "proc")


class _MountLookup:
    """Which mount of one mount table path lookup reaches at each path.

    Path lookup starts above every mount whose parent the table does not
    list (or that is its own parent): the mount at "/" of a process whose
    root is a mount point, or, for a process whose root is not one, each
    mount on the unlisted mount that holds that root.  At each leading part
    of a path it moves to the last mount listed on the current one at that
    point, as many times as mounts are stacked there.  Following mounts by
    parent, rather than taking the deepest mount point, sees that a mount
    made over a directory above an earlier mount hides that one.

    Each path is a node of a tree of path components, and the mount reached
    at each node is kept, so finding the mount of every entry of a table
    costs one step per path component and per stacked mount, however many
    entries share a prefix.
    """

    def __init__(self, entries: Sequence[_MountEntry]) -> None:
        self._entries = tuple(entries)
        known = {entry.mount_id for entry in entries}
        self._nodes: dict[tuple[int, str], int] = {}
        # Mounts listed on each mount (None: on the unlisted mount above
        # the table) at each path node, in table order.
        self._on: dict[tuple[int | None, int], list[_MountEntry]] = {}
        # The mount reached after each path node; None is the unlisted one.
        self._reached: dict[int, _MountEntry | None] = {}
        for entry in entries:
            parent = (
                None
                if entry.parent_id not in known or entry.parent_id == entry.mount_id
                else entry.parent_id
            )
            self._on.setdefault((parent, self._chain(entry.point)[-1]), []).append(entry)

    def _chain(self, path: Path) -> list[int]:
        chain = [0]
        for name in path.parts[1:]:
            chain.append(self._nodes.setdefault((chain[-1], name), len(self._nodes) + 1))
        return chain

    def _stacked(self, current: _MountEntry | None, node: int) -> _MountEntry | None:
        visited: set[int] = set()
        while True:
            owner = None if current is None else current.mount_id
            above = [
                entry for entry in self._on.get((owner, node), ()) if entry.mount_id != owner
            ]
            if not above:
                return current
            current = above[-1]
            if current.mount_id in visited:
                raise Refusal("the mount table stacks mounts on each other in a cycle")
            visited.add(current.mount_id)

    def reach(self, path: Path) -> _MountEntry | None:
        """The mount holding absolute, resolved ``path``, or None when no
        listed mount holds it."""

        if not path.is_absolute():
            raise Refusal(f"cannot find the mount holding relative path {path}")
        chain = self._chain(path)
        start = len(chain)
        while start and chain[start - 1] not in self._reached:
            start -= 1
        current = self._reached[chain[start - 1]] if start else None
        for node in chain[start:]:
            current = self._stacked(current, node)
            self._reached[node] = current
        return current

    def shows(self, entry: _MountEntry) -> bool:
        """Whether ``entry`` is the mount path lookup reaches at its point.

        A mount made later over its point, or over a directory above it,
        hides it.
        """

        return self.reach(entry.point) is entry


def _visible_mount(entries: Sequence[_MountEntry], path: Path) -> _MountEntry | None:
    """Return the mount of ``entries`` that holds the absolute, resolved
    ``path``, or None (see ``_MountLookup``)."""

    return _MountLookup(entries).reach(path)


def _process_dependent_prefix(
    path: str, procfs: Sequence[Path], *, _links: int = 0
) -> str | None:
    """Return the first leading part of ``path`` that leads into a proc file system, or None.

    A path into a proc file system names a different place for each
    process that resolves it: /proc/self, and /dev/fd and /dev/stdin, links
    into /proc/self/fd, are the resolving process's own. So does a path
    through one, whatever it resolves to for this process. Each leading
    part of ``path``, as written, is compared normalized and resolved, and
    each symbolic link among them is followed a step at a time, since the
    links in /proc/self/fd resolve past the proc file system. More than 40
    links (Linux's MAXSYMLINKS), or one that cannot be read, counts as
    leading there.
    """

    if _links > 40:
        return path
    parts = path.split("/")
    for count in range(1, len(parts) + 1):
        prefix = "/".join(parts[:count]) or "/"
        for candidate in dict.fromkeys((os.path.normpath(prefix), os.path.realpath(prefix))):
            if any(_path_is_within(Path(candidate), point) for point in procfs):
                return prefix
        if os.path.islink(prefix):
            try:
                target = os.readlink(prefix)
            except OSError:
                return prefix
            followed = os.path.join(os.path.realpath(os.path.dirname(prefix)), target)
            if _process_dependent_prefix(followed, procfs, _links=_links + 1) is not None:
                return prefix
    return None


def _refuse_aliases_below(
    root: Path,
    doomed: Callable[[], Mapping[_DirectoryIdentity, Path]],
    refuse: Callable[[str], NoReturn],
    *,
    links: bool,
) -> None:
    """Refuse when ``root``, or a directory below it, is a directory in ``doomed`` under another name.

    ``root`` is a resolved path. A bind mount gives a directory a second
    path that shares nothing with its first, so comparing paths, resolved
    or not, cannot show that deleting the directory through the first
    takes what the second shows; only their device and inode can.
    ``doomed`` maps those of each directory recovery deletes
    (_directory_identities) and is called only once ``root`` is found to
    exist. A mount point below ``root`` refuses as well: a file mounted
    there has the identity of a hard link to it, which does outlive the
    deletion of its other names, so only the mount table shows that this
    one would not. With ``links``, a symbolic link at or below ``root``
    refuses too, since Git follows one wherever it names. ``refuse`` is
    given what was found, and raises. More entries than
    _RETAINED_MODULES_ENTRY_LIMIT, or one that cannot be read, refuses.

    The mount holding ``root`` is examined too, since its directories have
    identities of their own whatever they show. A place in a proc file
    system refuses: it names another place for each process. So does one
    on a union file system (_UNION_FILE_SYSTEM_TYPES), whose layers the
    mount table does not show, and one on an overlay mount: the mount
    table names its layers by the paths they had when it was mounted, and
    a layer directory renamed since, into ``doomed`` or anywhere, is still
    the one the overlay shows, with nothing to show which directory that
    is now.
    """

    def check(path: Path, metadata: os.stat_result) -> None:
        aliased = doomed().get((metadata.st_dev, metadata.st_ino))
        if aliased is None:
            return
        if os.path.normpath(path) == os.path.normpath(aliased):
            # The directory itself, by the name recovery deletes it by.
            refuse(f"{path} is a directory recovery deletes")
        refuse(
            f"{path} is {aliased} under another name, as a bind mount makes "
            "it, and recovery deletes that"
        )

    entries = _read_self_mount_entries()
    for point in _procfs_points(entries):
        if _path_is_within(root, point):
            refuse(
                f"{root} lies in the proc file system mounted at {point}, where a "
                "path names a different place for each process that reads it"
            )
    if links and root.is_symlink():
        refuse(f"{root} is a symbolic link")
    try:
        metadata = os.stat(root, follow_symlinks=False)
    except FileNotFoundError:
        return
    except OSError as exc:
        raise Refusal(f"cannot inspect {root}: {exc}; nothing was removed") from exc
    if not stat.S_ISDIR(metadata.st_mode):
        return
    check(root, metadata)
    examined = 0
    pending = [root]
    while pending:
        directory = pending.pop()
        try:
            with os.scandir(directory) as listing:
                for entry in listing:
                    examined += 1
                    if examined > _RETAINED_MODULES_ENTRY_LIMIT:
                        raise Refusal(
                            f"{root} holds more than {_RETAINED_MODULES_ENTRY_LIMIT} "
                            "entries; they cannot all be examined, and nothing was "
                            "removed"
                        )
                    if links and entry.is_symlink():
                        refuse(f"{entry.path} is a symbolic link")
                    if entry.is_dir(follow_symlinks=False):
                        path = Path(entry.path)
                        check(path, entry.stat(follow_symlinks=False))
                        pending.append(path)
        except OSError as exc:
            raise Refusal(f"cannot list {directory}: {exc}; nothing was removed") from exc
    for mount in entries:
        if mount.point != root and _path_is_within(mount.point, root):
            refuse(
                f"mount point {mount.point} lies below it, and what is mounted there "
                "may be what recovery deletes, under another name"
            )
    holding = _visible_mount(entries, root)
    if holding is None:
        return
    if holding.fstype in _UNION_FILE_SYSTEM_TYPES:
        refuse(
            f"it is on a {holding.fstype} file system mounted at {holding.point}, "
            "which shows other directories' contents without saying which"
        )
    if holding.fstype == "overlay":
        # The mount table names an overlay's layers by the paths they had
        # when it was mounted; the kernel holds the directories themselves,
        # which a rename since can have put anywhere, and nothing shows
        # their device and inode.
        refuse(
            f"it is on the overlay mount at {holding.point}, which shows the "
            "contents of its layer directories; the mount table names them only "
            "by the paths they had when it was mounted, so which directories "
            "they are now cannot be shown"
        )


def _refuse_unretainable_module_storage(
    administration: Path,
    tree: Path,
    retained: _RetainedModules,
    repositories: Sequence[Path],
) -> None:
    """Refuse unless retaining the submodule repositories in ``tree`` keeps every object they read.

    ``tree`` holds them now: <administrative directory>/modules, or where
    recovery moved that aside (_GitVcs.worktree_modules_set_aside); and
    ``repositories`` are those below it (_module_repositories_below).
    Recovery moves the tree to ``retained``.path/modules and then lets Git
    delete the administrative directory, so:

    - A symbolic link anywhere in the tree refuses: once moved, a relative
      one names another place, and either kind can name a place in the
      administrative directory.
    - Each objects/info/alternates entry of those repositories, and each
      entry of an object directory those name, as deep as Git follows them,
      must name from where they are retained the place it names from
      <administrative directory>/modules: the same place in the moved tree,
      or the same place outside it. Git resolves an entry, a relative one
      appended to its object directory, as realpath(3) does
      (link_alt_odb_entry): a ".." after a symbolic link climbs from where
      the link points, not back to the directory holding the link. A Git
      that only normalized the path would read the place lexical
      normalization names. Both places are compared and checked, from
      where Git keeps the repository and from where it is retained.
    - A place outside the tree refuses when it lies, as named or resolved,
      in the worktrees/ directory of the common Git directory: Git deletes
      an administrative directory with its registration, whichever
      checkout's it is. It refuses too when it, or a directory below it, is
      a directory of worktrees/ under another name, as a bind mount of one
      outside worktrees/ makes it, or when a symbolic link lies anywhere
      below it, since Git follows that wherever it names
      (_refuse_aliases_below). The tree is among those directories too,
      though recovery moves it rather than deleting it: reached through a
      bind of the administrative directory, or of a directory above it, a
      place in the tree is a path the move leaves empty.
    - An entry that leads into a proc file system, as written or through
      a symbolic link, refuses (_process_dependent_prefix): it names a
      different place for each process, so what a Git command already
      running in the repository reads there cannot be checked.
    """

    common = Path(os.path.realpath(administration.parent.parent))
    worktrees = common / "worktrees"
    if (
        Path(os.path.realpath(administration)) != worktrees / administration.name
        or retained.path.parent.parent != administration.parent.parent
    ):
        raise Refusal(
            f"{administration} is not a directory of {worktrees}, so where its "
            "submodule repositories would be retained cannot be compared with "
            "where they are; nothing was removed"
        )
    original_root = worktrees / administration.name / "modules"
    final_root = common / _WORKTREE_MODULES_RETAINED / retained.path.name / "modules"
    _refuse_unless_real_directory(tree, "submodule repository tree")
    examined = 0
    directories = [tree]
    while directories:
        directory = directories.pop()
        try:
            with os.scandir(directory) as listing:
                for entry in listing:
                    examined += 1
                    if examined > _RETAINED_MODULES_ENTRY_LIMIT:
                        raise Refusal(
                            f"{tree} holds more than {_RETAINED_MODULES_ENTRY_LIMIT} "
                            "entries; they cannot all be examined, and nothing was "
                            "removed"
                        )
                    if entry.is_symlink():
                        raise Refusal(
                            f"{entry.path} is a symbolic link in the submodule "
                            "repositories recovery would retain: moved, a relative "
                            "link names another place, and either kind can name a "
                            f"place in {administration}, which Git deletes. nothing "
                            "was removed. remedy: replace the link with what it "
                            "names, then rerun"
                        )
                    if entry.is_dir(follow_symlinks=False):
                        directories.append(Path(entry.path))
        except OSError as exc:
            raise Refusal(f"cannot list {directory}: {exc}; nothing was removed") from exc

    def moved(original: str) -> str | None:
        candidate = Path(original)
        if not _path_is_within(candidate, original_root):
            return None
        return str(final_root / candidate.relative_to(original_root))

    found_doomed: list[Mapping[_DirectoryIdentity, Path]] = []

    def doomed() -> Mapping[_DirectoryIdentity, Path]:
        # Read once, and only for a row whose repositories borrow from
        # outside the tree.
        if not found_doomed:
            found_doomed.append(
                _directory_identities([worktrees], f"the directories of {worktrees}")
            )
        return found_doomed[0]

    # (object directory to read, its path from modules/, its path once retained, depth)
    pending: list[tuple[Path, str, str, int]] = []
    for repository in repositories:
        relative = repository.relative_to(tree)
        pending.append(
            (
                repository / "objects",
                str(original_root / relative / "objects"),
                str(final_root / relative / "objects"),
                0,
            )
        )
    seen: set[tuple[str, str]] = set()
    procfs: list[Path] = []
    while pending:
        objects, original, final, depth = pending.pop()
        if (original, final) in seen:
            continue
        seen.add((original, final))
        alternates = objects / "info" / "alternates"
        if not alternates.exists() and not alternates.is_symlink():
            continue
        label = f"submodule repository alternates file {alternates}"
        if depth >= _ALTERNATES_DEPTH_LIMIT:
            raise Refusal(
                f"{label} borrows objects more than {_ALTERNATES_DEPTH_LIMIT} "
                "alternates deep; nothing was removed"
            )
        try:
            # Git separates entries at LF only (link_alt_odb_entries).
            lines = _read_bounded_regular_file(
                alternates, label, _WORKTREE_GITDIR_BYTES_LIMIT
            ).decode("utf-8").split("\n")
        except UnicodeDecodeError as exc:
            raise Refusal(f"{label} is not UTF-8; nothing was removed") from exc
        for line in lines:
            if not line or line.startswith("#"):
                continue
            if line.startswith('"'):
                raise Refusal(
                    f"{label} quotes a path, which is not checked; nothing was removed"
                )
            _refuse_control_characters(line, label)
            if os.path.isabs(line):
                joined = joined_final = line
            else:
                joined = os.path.join(original, line)
                joined_final = os.path.join(final, line)
            remedy = (
                "nothing was removed. remedy: run `git repack -a -d` in that "
                "repository so that it holds every object it borrows, remove the "
                "entry, then rerun"
            )
            if not procfs:
                procfs.extend(_procfs_points(_read_self_mount_entries()))
            for written in dict.fromkeys((joined, joined_final)):
                dependent = _process_dependent_prefix(written, procfs)
                if dependent is not None:
                    raise Refusal(
                        f"{label} names {written}, which leads through {dependent} "
                        "into a proc file system, where a path names a different "
                        "place for each process that reads it: what a Git command "
                        "already running in the repository reads there cannot be "
                        f"checked; {remedy}"
                    )
            # The place lexical normalization names, then the place Git
            # resolves following symbolic links in order. In the tree,
            # which holds no symbolic link, a path recovery has not made
            # yet, or one behind the placeholder file, is resolved
            # lexically, as it reads once the tree is there.
            for named, named_final in dict.fromkeys(
                (
                    (os.path.normpath(joined), os.path.normpath(joined_final)),
                    (os.path.realpath(joined), os.path.realpath(joined_final)),
                )
            ):
                inside = moved(named)
                if inside is not None:
                    if inside != named_final:
                        raise Refusal(
                            f"{label} names {named} from where Git keeps the "
                            f"repository, but {named_final}, not where that is moved, "
                            f"once it is retained; {remedy}"
                        )
                    pending.append(
                        (
                            tree / Path(named).relative_to(original_root),
                            named,
                            named_final,
                            depth + 1,
                        )
                    )
                    continue
                if named_final != named:
                    raise Refusal(
                        f"{label} names {named} from where Git keeps the repository, "
                        f"but {named_final} once it is retained; {remedy}"
                    )
                resolved = os.path.realpath(named)
                for candidate in dict.fromkeys((named, resolved)):
                    if _path_is_within(Path(candidate), worktrees):
                        raise Refusal(
                            f"{label} borrows objects from {candidate}, in "
                            f"{worktrees}, where Git deletes each administrative "
                            f"directory with its registration; {remedy}"
                        )

                def refuse(found: str, store: str = resolved, why: str = label) -> NoReturn:
                    raise Refusal(
                        f"{why} borrows objects from {store}, where {found}: Git would "
                        "read objects there that recovery cannot show outlive the "
                        f"removal of a registration in {worktrees}; {remedy}"
                    )

                _refuse_aliases_below(Path(resolved), doomed, refuse, links=True)
                pending.append((Path(resolved), resolved, resolved, depth + 1))


def _retained_place(administration: Path, retained: _RetainedModules) -> Path:
    """Where, resolved, ``retained``.path must be: below the resolved common Git directory."""

    return (
        Path(os.path.realpath(administration.parent.parent))
        / _WORKTREE_MODULES_RETAINED
        / retained.path.name
    )


def _refuse_moved_retained(
    administration: Path, retained: _RetainedModules, found: str
) -> NoReturn:
    """Refuse because the kept repositories were moved (_refuse_unretainable_retained_storage)."""

    raise Refusal(
        f"{found}; the submodule repositories kept at {retained.path / 'modules'} "
        f"would be deleted with the registration of {administration}. nothing was "
        "removed. remedy: put them back at "
        f"{_retained_place(administration, retained) / 'modules'}, then rerun"
    )


def _refuse_moved_retained_directory(
    administration: Path,
    retained: _RetainedModules,
    kept_identity: _DirectoryIdentity,
) -> None:
    """Refuse when the kept repositories are no longer where they were moved (_refuse_unretainable_retained_storage)."""

    kept = retained.path / "modules"
    store = retained.path.parent
    expected = _retained_place(administration, retained)

    def refuse(found: str) -> NoReturn:
        _refuse_moved_retained(administration, retained, found)

    for path, label in (
        (store, "submodule repository store"),
        (retained.path, "directory the submodule repositories are kept in"),
        (kept, "kept submodule repository tree"),
    ):
        try:
            metadata = os.lstat(path)
        except OSError as exc:
            refuse(f"the {label} {path} cannot be inspected: {exc}")
        if stat.S_ISLNK(metadata.st_mode):
            refuse(f"the {label} {path} became a symbolic link")
        if not stat.S_ISDIR(metadata.st_mode):
            refuse(f"the {label} {path} is no longer a directory")
        if path == kept and (metadata.st_dev, metadata.st_ino) != kept_identity:
            refuse(f"{kept} is no longer the directory they were moved to")
    for path, place in ((retained.path, expected), (kept, expected / "modules")):
        if Path(os.path.realpath(path)) != place:
            refuse(f"{path} resolves to {os.path.realpath(path)}, not {place}")


def _refuse_unexamined_retained_repositories(
    administration: Path,
    retained: _RetainedModules,
    modules: Sequence[_WorktreeModule],
) -> None:
    """Refuse unless each directory of every examined submodule repository is where recovery keeps it.

    ``modules`` are the repositories as last examined where recovery set
    them aside (_WorktreeModule.directories). Each directory recorded
    there must be, at the same path below ``retained``.path, the same
    directory, not a symbolic link: the move to ``retained``.path keeps
    every directory below it. One moved or replaced since it was examined
    may have been carried into ``administration``, where Git deletes it,
    with whatever a process holding it open wrote there since; a
    replacement in its place, even an exact copy, preserves none of that.
    A directory made since is kept, and so is anything written into a
    kept directory. Something done after this check is not seen.
    """

    kept = retained.path / "modules"

    def refuse(found: str) -> NoReturn:
        raise Refusal(
            f"{found}; nothing was removed. remedy: find the directory examined "
            f"there (it may be in {administration}, which Git deletes with the "
            f"registration) and put it back at its place below {kept}, then rerun"
        )

    for module in modules:
        base = retained.path / module.name
        if not module.directories:
            raise StateError(
                f"submodule repository {module.path} was not examined where recovery "
                "set it aside"
            )
        for relative, device, inode in module.directories:
            path = base / relative
            examined = module.path / relative
            try:
                metadata = os.lstat(path)
            except FileNotFoundError:
                refuse(f"{path}, examined at {examined}, is gone")
            except OSError as exc:
                refuse(f"{path}, examined at {examined}, cannot be inspected: {exc}")
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or (metadata.st_dev, metadata.st_ino) != (device, inode)
            ):
                refuse(
                    f"{path} is not the directory examined at {examined}: it was "
                    "moved or replaced since"
                )


def _refuse_aliased_retained_directory(
    administration: Path, retained: _RetainedModules
) -> None:
    """Refuse when the place the kept repositories resolve to is a directory of ``administration`` under another name (_refuse_unretainable_retained_storage)."""

    expected = _retained_place(administration, retained)
    resolved_administration = Path(os.path.realpath(administration))
    found_doomed: list[Mapping[_DirectoryIdentity, Path]] = []

    def doomed() -> Mapping[_DirectoryIdentity, Path]:
        if not found_doomed:
            found_doomed.append(
                _directory_identities(
                    [resolved_administration], f"the directories of {administration}"
                )
            )
        return found_doomed[0]

    def aliased(found: str) -> NoReturn:
        _refuse_moved_retained(administration, retained, f"in {expected}, {found}")

    _refuse_aliases_below(expected, doomed, aliased, links=True)


def _refuse_unretainable_retained_storage(
    administration: Path,
    retained: _RetainedModules,
    kept_identity: _DirectoryIdentity | None,
) -> None:
    """Check again, once the submodule repositories are kept, what keeping them depends on.

    Runs after _retain_worktree_modules moved them to ``retained``.path,
    immediately before Git removes the registration of ``administration``.
    A mount below the administrative directory
    (_refuse_mounts_below_administration), a mount at or below
    ``retained``.path, or a symbolic link, alternates entry, bind alias or
    mount that _refuse_unretainable_module_storage refuses, if made since
    the census, could have Git delete objects the kept repositories read,
    or ones a process still holding a handle in them writes. Each refuses,
    and the repositories stay where they are kept. Something made after
    this check is not seen.

    ``kept_identity`` is the device and inode _retain_worktree_modules
    returned for the directory it moved, or None when nothing was moved.
    Once something was, the retained directory itself is checked too, since
    a rename made since then can carry it into the administrative directory:
    the store, ``retained``.path and its modules/ must each be a directory,
    not a symbolic link, the last still the directory moved; resolved, they
    must name the place below the resolved common Git directory that
    ``retained`` names; and, checked after everything else here, neither
    that place nor anything below it may be a directory of the
    administrative directory under another name
    (_refuse_aliases_below), as a bind mount, or a rename of the retained
    directory or one above it into the administrative directory with a
    bind mount or symbolic link left where it was, makes it. Within one
    mount a directory has one parent, and no mount may lie below the
    administrative directory, so a retained directory below it, or one it
    lies below, is a directory among those.
    """

    _refuse_mounts_below_administration(administration)
    if kept_identity is not None:
        _refuse_moved_retained_directory(administration, retained, kept_identity)
    resolved = Path(os.path.realpath(retained.path))
    table = _read_bounded_regular_file(
        _SELF_MOUNTINFO, "mount table", _MOUNTINFO_FILE_BYTES_LIMIT
    )
    for point in _mount_points(table, f"mount table {_SELF_MOUNTINFO}"):
        if _path_is_within(point, resolved):
            raise Refusal(
                f"mount point {point} lies at or below {retained.path}, where the "
                "submodule repositories are kept; it can show storage that Git "
                f"deletes with the registration of {administration}. nothing was "
                "removed. remedy: unmount it, then rerun"
            )
    kept = retained.path / "modules"
    if kept.exists() or kept.is_symlink():
        repositories = [path for _name, path in _module_repositories_below(kept)]
        if repositories:
            _refuse_unretainable_module_storage(
                administration, kept, retained, repositories
            )
    if kept_identity is not None:
        # Last, so a mount or link the checks above name refuses as that.
        _refuse_aliased_retained_directory(administration, retained)


_PACK_INDEX_V2_MAGIC = b"\xfftOc"
_PACK_HASH_BYTES = 20


def _refuse_unusable_pack_indexes(objects: Path, label: str) -> None:
    """Refuse unless Git can list every object of every pack in the object directory ``objects``.

    Git finds a pack through its index: it skips a pack that has none
    without a word, and lists nothing of one whose index it cannot use,
    with only a warning, still exiting 0. So each <name>.pack in
    objects/pack must have a <name>.idx, a regular file of index version 1
    or 2 whose fan-out table never decreases, whose size fits the number of
    objects that table gives, and whose trailing SHA-1 checksum matches its
    content; it must name the pack's trailing checksum, and that number of
    objects must be the one the pack's header gives. Only the pack's header
    and trailer are read, not the objects in it. A repository using
    SHA-256 object names refuses, as everywhere in this census (SHA_RE).
    """

    pack_directory = objects / "pack"
    try:
        names = sorted(os.listdir(pack_directory))
    except FileNotFoundError:
        return
    except OSError as exc:
        raise Refusal(f"cannot list {pack_directory} of {label}: {exc}") from exc
    for name in names:
        if not name.endswith(".pack"):
            continue
        pack = pack_directory / name
        index = pack_directory / f"{name.removesuffix('.pack')}.idx"

        def refuse(why: str, pack: Path = pack) -> NoReturn:
            raise Refusal(
                f"pack {pack} of {label} {why}, so Git would leave the objects in it "
                "out of the census without failing; nothing was removed. remedy: "
                "run `git index-pack` on it, or remove it if what it holds is not "
                "wanted, then rerun"
            )

        try:
            # A FIFO would block an open; nothing but a regular file is read.
            if not stat.S_ISREG(os.stat(pack).st_mode):
                refuse("is not a regular file")
            with open(pack, "rb") as stream:
                pack_metadata = os.fstat(stream.fileno())
                if not stat.S_ISREG(pack_metadata.st_mode):
                    refuse("is not a regular file")
                size = pack_metadata.st_size
                if size < 12 + _PACK_HASH_BYTES:
                    refuse("is too small to be a pack")
                header = stream.read(12)
                stream.seek(size - _PACK_HASH_BYTES)
                trailer = stream.read(_PACK_HASH_BYTES)
        except OSError as exc:
            refuse(f"cannot be read: {exc}")
        if (
            header[:4] != b"PACK"
            or int.from_bytes(header[4:8], "big") not in (2, 3)
            or len(trailer) != _PACK_HASH_BYTES
        ):
            refuse("does not begin with a version 2 or 3 pack header")
        held = int.from_bytes(header[8:12], "big")
        try:
            if not stat.S_ISREG(os.stat(index).st_mode):
                refuse(f"has an index {index.name} that is not a regular file")
            stream_index = open(index, "rb")
        except FileNotFoundError:
            refuse(f"has no index {index.name}")
        except OSError as exc:
            refuse(f"has an index {index.name} that cannot be read: {exc}")
        with stream_index:
            metadata = os.fstat(stream_index.fileno())
            if not stat.S_ISREG(metadata.st_mode):
                refuse(f"has an index {index.name} that is not a regular file")
            index_size = metadata.st_size
            digest = hashlib.sha1(usedforsecurity=False)
            start = stream_index.read(8 + 1024)
            version2 = start[:4] == _PACK_INDEX_V2_MAGIC
            if version2:
                if int.from_bytes(start[4:8], "big") != 2:
                    refuse(f"has an index {index.name} of an unknown version")
                fanout_bytes = start[8 : 8 + 1024]
            else:
                fanout_bytes = start[:1024]
            if len(fanout_bytes) != 1024:
                refuse(f"has an index {index.name} too small to be one")
            fanout = [
                int.from_bytes(fanout_bytes[offset : offset + 4], "big")
                for offset in range(0, 1024, 4)
            ]
            if any(later < earlier for earlier, later in itertools.pairwise(fanout)):
                refuse(f"has an index {index.name} whose fan-out table decreases")
            count = fanout[-1]
            if version2:
                least = 8 + 1024 + count * (_PACK_HASH_BYTES + 8) + 2 * _PACK_HASH_BYTES
                extra = index_size - least
                fits = extra >= 0 and extra % 8 == 0 and extra // 8 <= count
            else:
                fits = index_size == 1024 + count * (_PACK_HASH_BYTES + 4) + 2 * _PACK_HASH_BYTES
            if not fits:
                refuse(
                    f"has an index {index.name} whose size does not fit the {count} "
                    "objects it lists"
                )
            digest.update(start)
            remaining = index_size - len(start) - _PACK_HASH_BYTES
            tail = start[-_PACK_HASH_BYTES:]
            try:
                while remaining > 0:
                    chunk = stream_index.read(min(remaining, 1 << 20))
                    if not chunk:
                        break
                    digest.update(chunk)
                    remaining -= len(chunk)
                    tail = (tail + chunk)[-_PACK_HASH_BYTES:]
                checksum = stream_index.read(_PACK_HASH_BYTES)
            except OSError as exc:
                refuse(f"has an index {index.name} that cannot be read: {exc}")
            if remaining != 0 or digest.digest() != checksum:
                refuse(f"has an index {index.name} whose checksum does not match it")
            if tail != trailer:
                refuse(f"has an index {index.name} made for another pack")
            if count != held:
                refuse(
                    f"has an index {index.name} listing {count} objects, but holds {held}"
                )


def _alternate_object_directories(objects: Path, label: str) -> tuple[Path, ...]:
    """Return, resolved, each object directory Git borrows from for the object directory ``objects``.

    Read from objects/info/alternates and from those of the directories it
    names, as deep as _ALTERNATES_DEPTH_LIMIT, as Git reads them
    (link_alt_odb_entries): entries are separated at LF, a relative one is
    appended to the directory whose file names it, and each is resolved as
    realpath(3) does. A quoted entry, or one naming no directory, refuses.
    """

    found: dict[Path, None] = {}
    pending: list[tuple[Path, int]] = [(objects, 0)]
    while pending:
        directory, depth = pending.pop()
        alternates = directory / "info" / "alternates"
        if not alternates.exists() and not alternates.is_symlink():
            continue
        where = f"alternates file {alternates} of {label}"
        if depth >= _ALTERNATES_DEPTH_LIMIT:
            raise Refusal(
                f"{where} borrows objects more than {_ALTERNATES_DEPTH_LIMIT} "
                "alternates deep; nothing was removed"
            )
        try:
            lines = _read_bounded_regular_file(
                alternates, where, _WORKTREE_GITDIR_BYTES_LIMIT
            ).decode("utf-8").split("\n")
        except UnicodeDecodeError as exc:
            raise Refusal(f"{where} is not UTF-8; nothing was removed") from exc
        for line in lines:
            if not line or line.startswith("#"):
                continue
            if line.startswith('"'):
                raise Refusal(f"{where} quotes a path, which is not checked; nothing was removed")
            _refuse_control_characters(line, where)
            borrowed = Path(os.path.realpath(os.path.join(directory, line)))
            if not borrowed.is_dir():
                raise Refusal(
                    f"{where} names {line}, which is not a directory; nothing was removed"
                )
            if borrowed != Path(os.path.realpath(objects)) and borrowed not in found:
                found[borrowed] = None
                pending.append((borrowed, depth + 1))
    return tuple(found)


class _GitVcs:
    """The small Git boundary used by slot operations."""

    @staticmethod
    def _run(
        repository: Path,
        args: Sequence[str],
        *,
        check: bool = True,
        input_text: str | None = None,
        env_overrides: Mapping[str, str] | None = None,
        timeout_seconds: float | None = None,
        timeout_refusal: str | None = None,
        config: Sequence[tuple[str, str]] = (),
    ) -> subprocess.CompletedProcess[str]:
        """Run Git with a controlled environment.

        ``timeout_seconds`` bounds this one command; when it expires first,
        the command is stopped and Refusal(``timeout_refusal``) is raised.
        ``config`` holds Git settings, as (key, value) pairs, for this one
        command; they are passed on Git's command line.
        """

        command, env, what = _GitVcs._invocation(
            repository, args, env_overrides, config=config
        )
        seconds, expired = _GitVcs._bound(what, timeout_seconds, timeout_refusal)
        try:
            if seconds is None:
                completed = subprocess.run(
                    command,
                    text=True,
                    capture_output=True,
                    check=False,
                    env=env,
                    input=input_text,
                )
            else:
                completed = _run_within_item_budget(
                    command,
                    seconds=seconds,
                    what=what,
                    env=env,
                    input_text=input_text,
                    timeout_refusal=expired,
                )
        except OSError as exc:
            raise Refusal(f"cannot execute Git: {exc}") from exc
        if check and completed.returncode != 0:
            network_operation = _GitVcs._network_operation(args)
            detail = (
                "\n".join(
                    text.strip()
                    for text in (completed.stderr, completed.stdout)
                    if text.strip()
                )
                if network_operation
                else (completed.stderr or completed.stdout).strip()
            )
            message = f"Git refused in {repository}: git {' '.join(args)}" + (
                f": {detail}" if detail else ""
            )
            if network_operation and _remote_transport_unavailable(
                completed.stderr + "\n" + completed.stdout
            ):
                raise _RemoteTransportUnavailable(message)
            raise Refusal(message)
        return completed

    @staticmethod
    def _network_operation(args: Sequence[str]) -> bool:
        """Return whether ``args`` is a Git command that talks to a remote."""

        return bool(args and args[0] in {"fetch", "push", "ls-remote"})

    @staticmethod
    def _invocation(
        repository: Path,
        args: Sequence[str],
        env_overrides: Mapping[str, str] | None,
        *,
        config: Sequence[tuple[str, str]] = (),
    ) -> tuple[list[str], dict[str, str], str]:
        """Return the command line, environment, and description of one Git command.

        Each ``config`` pair becomes a ``-c key=value`` option before the
        subcommand, so a setting reaches Git without a GIT_CONFIG_* variable.
        """

        settings: list[str] = []
        for key, value in config:
            # Git splits the option at its first "=".
            if not key or "=" in key or any(
                character in key + value for character in "\n\0"
            ):
                raise StateError(f"malformed Git setting for one command: {key!r}")
            settings.extend(("-c", f"{key}={value}"))
        env = {
            key: value
            for key, value in os.environ.items()
            if not key.startswith("GIT_")
        }
        env["LC_ALL"] = "C"
        env["GIT_CONFIG_NOSYSTEM"] = "1"
        env["GIT_CONFIG_GLOBAL"] = "/dev/null"
        env["GIT_CONFIG_SYSTEM"] = "/dev/null"
        env["GIT_NO_REPLACE_OBJECTS"] = "1"
        expected_network_config = (
            env_overrides.get(_NETWORK_CONFIG_SHA256_ENV)
            if env_overrides is not None
            else None
        )
        if env_overrides:
            env.update(env_overrides)
        env.pop(_NETWORK_CONFIG_SHA256_ENV, None)
        network_operation = _GitVcs._network_operation(args)
        if expected_network_config is not None:
            observed_network_config = hashlib.sha256(
                _read_bounded_regular_file(
                    repository / "config",
                    "isolated network Git config",
                    _NETWORK_CONFIG_BYTES_LIMIT,
                )
            ).hexdigest()
            if observed_network_config != expected_network_config:
                raise Refusal(
                    "isolated network Git config changed before execution; preserve the "
                    "checkout and retry"
                )
        command = [
            "git",
            "--no-replace-objects",
            "-c",
            "core.useReplaceRefs=false",
            *settings,
            *(_github_credential_helper_args(env) if network_operation else ()),
            "-C",
            str(repository),
            *args,
        ]
        if network_operation:
            command = _with_proxy(command, env)
        return command, env, f"git {' '.join(args[:3])} in {repository}"

    @staticmethod
    def _bound(
        what: str, timeout_seconds: float | None, timeout_refusal: str | None
    ) -> tuple[float | None, Refusal | None]:
        """Return the seconds one Git command may run, and the refusal when they expire.

        None seconds means unbounded. The item budget, when one applies, bounds
        every command; ``timeout_seconds`` bounds this one when it is smaller,
        and expiring then raises Refusal(``timeout_refusal``).
        """

        if (timeout_seconds is None) != (timeout_refusal is None):
            raise StateError("a Git timeout needs both its bound and its refusal")
        seconds = _item_seconds_left(what)
        if timeout_seconds is not None and (seconds is None or timeout_seconds < seconds):
            return timeout_seconds, Refusal(str(timeout_refusal))
        return seconds, None

    @staticmethod
    def _run_bytes(
        repository: Path,
        args: Sequence[str],
        *,
        input_bytes: bytes | None = None,
        env_overrides: Mapping[str, str] | None = None,
        timeout_seconds: float,
        timeout_refusal: str,
        config: Sequence[tuple[str, str]] = (),
    ) -> subprocess.CompletedProcess[bytes]:
        """Run Git as _run does, passing input and output as bytes, unchecked.

        Path names Git reports or reads are bytes, and need be neither UTF-8
        nor free of carriage returns. The command is always bounded.
        ``config`` is as for _run.
        """

        command, env, what = _GitVcs._invocation(
            repository, args, env_overrides, config=config
        )
        seconds, expired = _GitVcs._bound(what, timeout_seconds, timeout_refusal)
        if seconds is None:
            raise StateError("a bytes Git command needs a bound")
        try:
            return _run_bytes_within_item_budget(
                command,
                seconds=seconds,
                what=what,
                env=env,
                input_bytes=input_bytes,
                timeout_refusal=expired,
            )
        except OSError as exc:
            raise Refusal(f"cannot execute Git: {exc}") from exc

    def repository_root(self, repository: Path) -> Path:
        result = self._run(repository, ["rev-parse", "--show-toplevel"])
        root = Path(result.stdout.strip()).absolute()
        if root.is_symlink() or not root.is_dir():
            raise Refusal(f"Git reported an unsafe repository root: {root}")
        return root

    def common_directory(self, repository: Path) -> Path:
        result = self._run(repository, ["rev-parse", "--path-format=absolute", "--git-common-dir"])
        common = Path(result.stdout.strip()).absolute()
        if common.is_symlink() or not common.is_dir():
            raise Refusal(f"Git reported an unsafe common directory: {common}")
        return common

    def linked_worktree_git_directory(self, checkout: Path) -> tuple[Path, Path]:
        """Return the exact common and per-worktree Git directories."""

        common = self.common_directory(checkout)
        result = self._run(
            checkout,
            ["rev-parse", "--path-format=absolute", "--git-dir"],
        )
        lines = result.stdout.splitlines()
        if len(lines) != 1:
            raise Refusal(
                f"Git did not report one linked-worktree directory for {checkout}"
            )
        git_directory = Path(lines[0]).absolute()
        if (
            git_directory.parent != common / "worktrees"
            or not git_directory.name
            or git_directory.is_symlink()
            or not git_directory.is_dir()
        ):
            raise Refusal(
                f"Git reported an unsafe linked-worktree directory: {git_directory}"
            )
        return common, git_directory

    def worktree_identity(self, checkout: Path) -> tuple[Path, Path, str]:
        """Answer repository_root, common_directory and head in ONE Git process.

        The registry audit asks all three of a checkout back to back, so on a
        251-row registry the separate spellings cost 753 Git processes at about
        24 ms each -- 18.7 of the audit's 19.1 seconds, measured 2026-09-17 by
        cProfile.  Nothing here is weakened to buy that: the same three values
        are read and every refusal below is the one the separate method raises.
        `git rev-parse` reports the requested options in argument order, and a
        failure on any of them is still a non-zero exit that `_run` turns into
        the same Refusal.
        """

        result = self._run(
            checkout,
            [
                "rev-parse",
                "--path-format=absolute",
                "--show-toplevel",
                "--git-common-dir",
                "--verify",
                "HEAD^{commit}",
            ],
        )
        lines = result.stdout.splitlines()
        if len(lines) != 3:
            raise Refusal(
                f"Git did not report one worktree identity for {checkout}: "
                f"expected three lines, got {len(lines)}"
            )
        root = Path(lines[0].strip()).absolute()
        if root.is_symlink() or not root.is_dir():
            raise Refusal(f"Git reported an unsafe repository root: {root}")
        common = Path(lines[1].strip()).absolute()
        if common.is_symlink() or not common.is_dir():
            raise Refusal(f"Git reported an unsafe common directory: {common}")
        sha = lines[2].strip()
        if not SHA_RE.fullmatch(sha):
            raise Refusal(f"checkout HEAD is not a full commit: {checkout}")
        return root, common, sha

    def commit_present(self, repository: Path, commit: str) -> bool:
        """Return whether the object store of ``repository`` holds commit ``commit``."""

        if not SHA_RE.fullmatch(commit):
            raise Refusal(f"cannot look up invalid commit {commit!r}")
        result = self._run(
            repository,
            ["cat-file", "--batch-check=%(objectname) %(objecttype)"],
            input_text=f"{commit}\n",
        )
        observed = result.stdout.strip()
        if observed == f"{commit} commit":
            return True
        if observed == f"{commit} missing":
            return False
        raise Refusal(f"Git reported {commit} as something other than a commit: {observed!r}")

    def verify_ref(self, repository: Path, ref: str, label: str) -> str:
        _validate_ref(ref, label)
        result = self._run(repository, ["rev-parse", "--verify", f"{ref}^{{commit}}"])
        sha = result.stdout.strip()
        if not SHA_RE.fullmatch(sha):
            raise Refusal(f"{label} did not resolve to one full commit: {ref}")
        return sha

    def local_branch_head(self, repository: Path, branch_ref: str) -> str | None:
        """Read one stable commit-valued local branch ref without changing it."""

        _validate_full_ref(branch_ref, "local branch ref")
        if not branch_ref.startswith("refs/heads/"):
            raise Refusal(f"local branch ref is outside refs/heads: {branch_ref!r}")
        symbolic = self._run(
            repository,
            ["symbolic-ref", "--quiet", branch_ref],
            check=False,
        )
        if symbolic.returncode == 0:
            raise Refusal(
                f"local branch ref {branch_ref!r} is symbolic; recovery requires a "
                "direct branch ref or proven absence"
            )
        if symbolic.returncode != 1 or symbolic.stdout or symbolic.stderr:
            raise Refusal(
                f"cannot classify whether local branch {branch_ref!r} is symbolic in "
                f"{repository}"
            )
        existence = self._run(
            repository,
            ["show-ref", "--exists", branch_ref],
            check=False,
        )
        # `show-ref --exists` has a purpose-built status contract: 0 means the
        # ref exists, 2 means it is missing, and 1 means another lookup error.
        # Git writes its fixed "reference does not exist" diagnostic on the
        # normal status-2 path, so stderr cannot distinguish absence here.
        if existence.returncode == 2 and not existence.stdout:
            return None
        if (
            existence.returncode != 0
            or existence.stdout
            or existence.stderr
        ):
            raise Refusal(
                f"cannot classify local branch existence for {branch_ref!r} in "
                f"{repository}"
            )

        def read_ref() -> str:
            result = self._run(
                repository,
                ["show-ref", "--verify", "--hash", "--", branch_ref],
                check=False,
            )
            lines = result.stdout.splitlines()
            if (
                result.returncode != 0
                or result.stderr
                or len(lines) != 1
                or SHA_RE.fullmatch(lines[0]) is None
            ):
                raise Refusal(
                    f"cannot read exact local branch state for {branch_ref!r} in "
                    f"{repository}"
                )
            return lines[0]

        first = read_ref()
        if self.verify_ref(repository, first, "local branch object") != first:
            raise Refusal(f"local branch {branch_ref!r} does not name one commit")
        second = read_ref()
        if second != first:
            raise Refusal(
                f"local branch {branch_ref!r} changed while its state was read"
            )
        return first

    def check_branch_name(self, repository: Path, branch: str) -> None:
        _validate_ref(branch, "branch")
        result = self._run(repository, ["check-ref-format", "--branch", branch], check=False)
        if result.returncode == 0:
            return
        # Git dies (exit 128) for an invalid name and for a real failure alike; only its
        # message, stable under LC_ALL=C, tells them apart.
        if result.returncode == 128 and "is not a valid branch name" in result.stderr:
            raise Refusal(f"invalid Git branch name {branch!r}")
        raise Refusal(f"cannot check Git branch name {branch!r}" + _git_failure_detail(result))

    def branch_exists(self, repository: Path, branch: str) -> bool:
        result = self._run(
            repository, ["show-ref", "--verify", "--quiet", f"refs/heads/{branch}"], check=False
        )
        if result.returncode not in (0, 1):
            raise Refusal(
                f"cannot determine whether branch {branch!r} exists in {repository}"
                + _git_failure_detail(result)
            )
        return result.returncode == 0

    def add_worktree(
        self, repository: Path, destination: Path, branch: str, start_point: str
    ) -> str:
        self.check_branch_name(repository, branch)
        if self.branch_exists(repository, branch):
            raise Refusal(f"local branch already exists: {branch}")
        self.verify_ref(repository, start_point, "start point")
        self._run(
            repository,
            ["worktree", "add", "-b", branch, str(destination), start_point],
        )
        return self.head(destination)

    def listed_worktrees(self, repository: Path) -> set[Path]:
        result = self._run(repository, ["worktree", "list", "--porcelain"])
        paths: set[Path] = set()
        for line in result.stdout.splitlines():
            if line.startswith("worktree "):
                paths.add(Path(line.removeprefix("worktree ")).absolute())
        return paths

    def worktree_registration(
        self, repository: Path, checkout: Path
    ) -> tuple[str, str | None] | None:
        """Return the exact administrative HEAD and branch for one registered path."""

        result = self._run(repository, ["worktree", "list", "--porcelain", "-z"])
        fields = result.stdout.split("\x00")
        if fields and fields[-1] == "":
            fields.pop()
        records: list[dict[str, str | None]] = []
        current: dict[str, str | None] | None = None
        for field in fields:
            key, separator, value = field.partition(" ")
            if key == "worktree":
                if current is not None:
                    records.append(current)
                current = {"worktree": value}
                continue
            if current is None:
                raise Refusal("Git worktree inventory starts without a worktree path")
            if key in current:
                raise Refusal(f"Git worktree inventory repeats field {key!r}")
            current[key] = value if separator else None
        if current is not None:
            records.append(current)
        target = checkout.absolute()
        matches = [
            record
            for record in records
            if Path(str(record.get("worktree"))).absolute() == target
        ]
        if len(matches) > 1:
            raise Refusal(f"Git reports duplicate worktree registrations for {target}")
        if not matches:
            return None
        record = matches[0]
        head = record.get("HEAD")
        if not isinstance(head, str) or not SHA_RE.fullmatch(head):
            raise Refusal(f"Git worktree registration for {target} has no full HEAD")
        branch = record.get("branch")
        return head, branch

    def worktree_administrative_directory(
        self, repository: Path, checkout: Path
    ) -> Path | None:
        """Return the directory where Git administers the linked worktree ``checkout``.

        Git keeps each linked worktree's HEAD and index in
        <common>/worktrees/<id>/, whose gitdir file names the worktree's .git
        path; that directory outlives a deleted checkout. None means no gitdir
        file names ``checkout``.
        """

        root = self.common_directory(repository) / "worktrees"
        if not root.exists() and not root.is_symlink():
            return None
        if root.is_symlink() or not root.is_dir():
            raise Refusal(f"Git worktree administration is unsafe: {root}")
        target = checkout.absolute() / ".git"
        matches: list[Path] = []
        for entry in sorted(root.iterdir()):
            gitdir = entry / "gitdir"
            if entry.is_symlink() or not entry.is_dir():
                continue
            if not gitdir.exists() and not gitdir.is_symlink():
                continue
            try:
                named = _read_bounded_regular_file(
                    gitdir, "Git worktree gitdir file", _WORKTREE_GITDIR_BYTES_LIMIT
                ).decode("utf-8")
            except UnicodeDecodeError as exc:
                raise Refusal(f"Git worktree gitdir file is not UTF-8: {gitdir}") from exc
            path = Path(named.rstrip())
            if not path.is_absolute():
                path = entry / path
            if Path(os.path.normpath(path)) == target:
                matches.append(entry)
        if len(matches) > 1:
            raise Refusal(
                f"Git administers {checkout} from more than one directory: "
                + ", ".join(str(match) for match in matches)
            )
        return matches[0] if matches else None

    def worktree_staged_paths(
        self,
        repository: Path,
        checkout: Path,
        head: str,
        remote: str,
        authority: _RemoteAuthority,
    ) -> tuple[Path | None, tuple[str, ...]]:
        """Return the index Git kept for ``checkout`` and the paths it stages beyond ``head``.

        A path is listed when its staged content differs from ``head`` or it
        is unmerged, shown with bytes that are not printable UTF-8 escaped
        (Git stores path names as bytes, which need not be UTF-8). The index
        is read in a temporary repository whose only configuration is
        _NETWORK_CONFIG, so no hook or filter of the source repository runs,
        and nothing is written. The comparison is stopped, and refused, after
        _ABSENT_AGENT_HISTORY_SECONDS.
        """

        if not SHA_RE.fullmatch(head):
            raise Refusal(f"cannot compare a worktree index with invalid commit {head!r}")
        administration = self.worktree_administrative_directory(repository, checkout)
        if administration is None:
            raise Refusal(
                f"Git registers {checkout} but no administrative directory names it"
            )
        index = administration / "index"
        if not index.exists() and not index.is_symlink():
            return None, ()
        if index.is_symlink() or not index.is_file():
            raise Refusal(f"Git worktree index is unsafe: {index}")
        with self._isolated_remote(repository, remote, authority) as (
            isolated,
            object_env,
        ):
            result = self._run_bytes(
                isolated,
                [
                    "diff-index",
                    "--cached",
                    "--exit-code",
                    "--name-only",
                    "-z",
                    "--no-renames",
                    "--ignore-submodules=none",
                    head,
                    "--",
                ],
                env_overrides={**object_env, "GIT_INDEX_FILE": str(index)},
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=(
                    f"Git did not compare the index Git kept for {checkout} with {head} "
                    f"within {_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was "
                    "stopped and nothing was removed. remedy: rerun when the host is "
                    "less loaded"
                ),
            )
        paths = tuple(
            _display_git_path(name)
            for name in dict.fromkeys(name for name in result.stdout.split(b"\0") if name)
        )
        if result.returncode == 0 and not paths:
            return index, ()
        if result.returncode == 1 and paths:
            return index, paths
        raise Refusal(
            f"cannot compare the index Git kept for {checkout} with {head}"
            + _git_bytes_failure_detail(result)
        )

    def worktree_private_roots_beyond(
        self,
        repository: Path,
        checkout: Path,
        head: str,
        remote: str,
        authority: _RemoteAuthority,
    ) -> tuple[str, ...]:
        """Describe what Git keeps only for ``checkout`` that ``head``'s history does not hold.

        That is each per-worktree ref (_WORKTREE_PRIVATE_REF_PREFIXES) not
        naming a commit in ``head``'s history, each unfinished-operation file
        (_GIT_OPERATION_STATE_NAMES) in its administrative directory, and each
        resolve-undo entry of its index whose object never appeared at that
        path in ``head``'s history (see _resolve_undo_beyond). Ancestry is
        decided in a temporary repository whose only configuration is
        _NETWORK_CONFIG. Reflogs, ORIG_HEAD, and FETCH_HEAD are not reported:
        they record past positions, not unfinished work.
        """

        if not SHA_RE.fullmatch(head):
            raise Refusal(f"cannot compare worktree refs with invalid commit {head!r}")
        administration = self.worktree_administrative_directory(repository, checkout)
        if administration is None:
            raise Refusal(
                f"Git registers {checkout} but no administrative directory names it"
            )
        index = administration / "index"
        has_index = index.exists() or index.is_symlink()
        if has_index and (index.is_symlink() or not index.is_file()):
            raise Refusal(f"Git worktree index is unsafe: {index}")
        found = [
            str(administration / name)
            for name in _GIT_OPERATION_STATE_NAMES
            if (administration / name).exists() or (administration / name).is_symlink()
        ]
        # Bytes, because a ref name need not be UTF-8; it is only shown.
        listed = self._run_bytes(
            repository,
            [
                "for-each-ref",
                "--format=%(refname)%00%(objectname)%00%(objecttype)",
                *_WORKTREE_PRIVATE_REF_PREFIXES,
            ],
            env_overrides={"GIT_DIR": str(administration)},
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=(
                f"Git did not list the per-worktree refs Git kept for {checkout} within "
                f"{_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped and "
                "nothing was removed. remedy: rerun when the host is less loaded"
            ),
        )
        if listed.returncode != 0:
            raise Refusal(
                f"cannot list the per-worktree refs Git kept for {checkout}"
                + _git_bytes_failure_detail(listed)
            )
        refs: list[tuple[str, str, str]] = []
        for line in listed.stdout.split(b"\n"):
            if not line:
                continue
            fields = [
                _display_git_path(field) for field in line.split(b"\0")
            ]
            if (
                len(fields) != 3
                or not fields[0].startswith(_WORKTREE_PRIVATE_REF_PREFIXES)
                or not SHA_RE.fullmatch(fields[1])
            ):
                raise Refusal(f"Git returned a malformed worktree ref inventory for {checkout}")
            refs.append((fields[0], fields[1], fields[2]))
        if refs or has_index:
            with self._isolated_remote(repository, remote, authority) as (
                isolated,
                object_env,
            ):
                for ref, target, kind in refs:
                    if kind != "commit":
                        found.append(f"{ref} -> {target} ({kind})")
                        continue
                    result = self._run(
                        isolated,
                        ["merge-base", "--is-ancestor", target, head],
                        check=False,
                        env_overrides=object_env,
                    )
                    if result.returncode == 1:
                        found.append(f"{ref} -> {target}")
                    elif result.returncode != 0:
                        raise Refusal(
                            f"cannot compare worktree ref {ref} with {head}"
                            + _git_failure_detail(result)
                        )
                if has_index:
                    found.extend(
                        self._resolve_undo_beyond(
                            isolated, object_env, index, head, checkout
                        )
                    )
        return tuple(found)

    def _resolve_undo_beyond(
        self,
        isolated: Path,
        object_env: Mapping[str, str],
        index: Path,
        head: str,
        checkout: Path,
    ) -> list[str]:
        """Describe each resolve-undo entry of ``index`` that ``head``'s history lacks.

        Resolving a conflict records the conflicting versions in the index's
        resolve-undo extension, which survives later commits, and Git keeps
        those objects from garbage collection only while that index exists.
        An entry is described unless its object appears at the same path in
        some commit of ``head``'s history (every side of a merge, without
        rename detection), so an entry whose content exists nowhere else
        refuses; content moved by a rename refuses too. Path names stay bytes
        from Git's output to the pathspecs passed back to it, so a name that
        is not UTF-8 or that holds a carriage return or newline is compared
        exactly. Each Git command is stopped, and refused, after
        _ABSENT_AGENT_HISTORY_SECONDS.
        """

        timeout_refusal = (
            f"Git did not read the resolve-undo record of the index Git kept for "
            f"{checkout}, or the history of {head} it is compared with, within "
            f"{_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped and "
            "nothing was removed. remedy: rerun when the host is less loaded"
        )
        listed = self._run_bytes(
            isolated,
            ["ls-files", "--resolve-undo", "-z"],
            env_overrides={**object_env, "GIT_INDEX_FILE": str(index)},
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=timeout_refusal,
        )
        if listed.returncode != 0:
            raise Refusal(
                f"cannot read the resolve-undo record of the index Git kept for {checkout}"
                + _git_bytes_failure_detail(listed)
            )
        unreadable = Refusal(
            f"Git returned a resolve-undo record for {checkout} that cannot be checked"
        )
        entries: list[tuple[bytes, str, str]] = []
        for record in listed.stdout.split(b"\0"):
            if not record:
                continue
            meta, separator, path = record.partition(b"\t")
            try:
                fields = meta.decode("ascii").split(" ")
            except UnicodeDecodeError:
                raise unreadable from None
            if (
                not separator
                or not path
                or len(fields) != 3
                or not SHA_RE.fullmatch(fields[1])
                or fields[2] not in ("1", "2", "3")
            ):
                raise unreadable
            entries.append((path, fields[2], fields[1]))
        if not entries:
            return []
        # Pathspecs go on the command line, never through --stdin, which reads
        # one per line and drops a line's trailing carriage return.
        batches: list[list[bytes]] = []
        batch_bytes = 0
        for path in sorted({path for path, _stage, _object in entries}):
            if batches and batch_bytes + len(path) + 1 <= _ABSENT_AGENT_PATHSPEC_BYTES_LIMIT:
                batches[-1].append(path)
                batch_bytes += len(path) + 1
            else:
                batches.append([path])
                batch_bytes = len(path) + 1
        seen: dict[bytes, set[str]] = {}
        malformed = Refusal(
            f"Git returned history for the resolve-undo record of {checkout} that "
            "cannot be checked"
        )
        for batch in batches:
            history = self._run_bytes(
                isolated,
                [
                    "log",
                    "--full-history",
                    "-m",
                    "--root",
                    "--no-renames",
                    "--no-ext-diff",
                    "--no-abbrev",
                    "--raw",
                    "-z",
                    "--format=",
                    head,
                    "--",
                    *(os.fsdecode(path) for path in batch),
                ],
                env_overrides={**object_env, "GIT_LITERAL_PATHSPECS": "1"},
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=timeout_refusal,
            )
            if history.returncode != 0:
                raise Refusal(
                    f"cannot read the history of {head} for the resolve-undo record of "
                    f"{checkout}" + _git_bytes_failure_detail(history)
                )
            tokens = iter(history.stdout.split(b"\0"))
            for token in tokens:
                if not token:
                    continue
                path = next(tokens, b"")
                try:
                    fields = token.decode("ascii").split(" ")
                except UnicodeDecodeError:
                    raise malformed from None
                if (
                    not token.startswith(b":")
                    or len(fields) != 5
                    or not SHA_RE.fullmatch(fields[2])
                    or not SHA_RE.fullmatch(fields[3])
                    or not path
                ):
                    raise malformed
                seen.setdefault(path, set()).update(fields[2:4])
        return [
            f"resolve-undo {_display_git_path(path)} stage {stage} -> {obj}"
            for path, stage, obj in entries
            if obj not in seen.get(path, set())
        ]

    def worktree_modules(
        self, repository: Path, checkout: Path, *, set_aside: bool = False
    ) -> tuple[_WorktreeModule, ...]:
        """Examine each submodule repository Git keeps in ``checkout``'s administrative directory.

        Removing the registration would delete <administrative
        directory>/modules/, where Git cloned every submodule of the checkout;
        recovery keeps it, but where no Git command finds it. A commit there
        that no remote-tracking ref reaches, in that repository or in the
        superproject's shared repository of the same name, exists nowhere
        else (see _WorktreeModule). With ``set_aside`` it examines them where
        worktree_modules_set_aside moved them, and records which directories
        it examined (_WorktreeModule.directories).
        """

        administration = self.worktree_administrative_directory(repository, checkout)
        if administration is None:
            raise Refusal(
                f"Git registers {checkout} but no administrative directory names it"
            )
        directories = _worktree_module_directories(administration, set_aside=set_aside)
        if not directories:
            return ()
        common = self.common_directory(repository)
        examined = tuple(path for _name, path in directories)
        modules: list[_WorktreeModule] = []
        for name, path in directories:
            # Read before the repository is examined, so a directory moved
            # or replaced since is not taken for one examined.
            identities = _tree_directory_identities(path) if set_aside else ()
            module = self._worktree_module(
                common, administration, name, path, examined=examined
            )
            modules.append(dataclasses.replace(module, directories=identities))
        return tuple(modules)

    def _repository_refs(
        self, work: Path, git_directory: Path, label: str
    ) -> tuple[tuple[str, str], ...]:
        """Return (ref, object name) for each ref of a repository, reading no object.

        ``work`` is an empty directory given to Git as the work tree, because
        a submodule repository's core.worktree names a checkout that may be
        absent. Git reads this repository's own configuration here, so no
        object is read: asking for an object's type could make Git fetch a
        missing object through the transport a promisor remote configures.
        GIT_NO_LAZY_FETCH forbids that fetch as well. Object types are read
        later, in an isolated repository (see _worktree_module).
        """

        listed = self._run_bytes(
            work,
            ["for-each-ref", "--format=%(refname)%00%(objectname)"],
            env_overrides={
                "GIT_DIR": str(git_directory),
                "GIT_WORK_TREE": str(work),
                "GIT_NO_LAZY_FETCH": "1",
            },
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=(
                f"Git did not list the refs of {label} within "
                f"{_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped and "
                "nothing was removed. remedy: rerun when the host is less loaded"
            ),
        )
        if listed.returncode != 0:
            raise Refusal(
                f"cannot list the refs of {label}" + _git_bytes_failure_detail(listed)
            )
        if listed.stderr.strip():
            # Git leaves out, with only a warning, a ref it cannot read or
            # whose object is missing; an inventory without it is incomplete.
            raise Refusal(
                f"Git reported a problem while listing the refs of {label}"
                + _git_bytes_failure_detail(listed)
            )
        refs: list[tuple[str, str]] = []
        for line in listed.stdout.split(b"\n"):
            if not line:
                continue
            fields = [_display_git_path(field) for field in line.split(b"\0")]
            if (
                len(fields) != 2
                or not fields[0].startswith("refs/")
                or not SHA_RE.fullmatch(fields[1])
            ):
                raise Refusal(f"Git returned a malformed ref inventory for {label}")
            refs.append((fields[0], fields[1]))
        return tuple(refs)

    def _repository_reflog_commits(
        self, work: Path, git_directory: Path, label: str
    ) -> tuple[tuple[str, ...], tuple[str, ...]]:
        """Return each commit a reflog of a repository names, and what blocks.

        The commits are the old and new values of every entry that Git can
        read. ``work`` is as for _repository_refs. Git reads the reflogs
        through the repository's own ref backend and reads each named object
        to find its commit, so GIT_NO_LAZY_FETCH forbids fetching a missing
        one. Git leaves out, with only a warning, an entry naming an object
        it cannot read, so anything it reports is returned as a reason that
        blocks the row: a commit no census can read cannot be shown to be
        published or salvaged. It is a reason rather than a refusal so that
        the census still reports, by name, a ref that names the same
        missing commit.
        """

        listed = self._run_bytes(
            work,
            ["rev-list", "--reflog", "--no-walk=unsorted", "--stdin"],
            input_bytes=b"",
            env_overrides={
                "GIT_DIR": str(git_directory),
                "GIT_WORK_TREE": str(work),
                "GIT_NO_LAZY_FETCH": "1",
                "GIT_NO_REPLACE_OBJECTS": "1",
            },
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=(
                f"Git did not list the reflogs of {label} within "
                f"{_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped and "
                "nothing was removed. remedy: rerun when the host is less loaded"
            ),
        )
        blocking: tuple[str, ...] = ()
        if listed.returncode != 0 or listed.stderr.strip():
            blocking = (
                f"cannot list every commit the reflogs of {label} name"
                + _git_bytes_failure_detail(listed)
                + "; remedy: inspect them with `git reflog`; "
                "`git reflog expire --stale-fix --all` drops entries naming "
                "commits that are gone",
            )
        commits = listed.stdout.decode("ascii", "replace").splitlines()
        if not all(SHA_RE.fullmatch(commit) for commit in commits):
            raise Refusal(f"Git returned a malformed reflog inventory for {label}")
        return tuple(commits), blocking

    def _repository_head(
        self, work: Path, git_directory: Path, label: str
    ) -> tuple[str | None, str | None, tuple[str, ...]]:
        """Read a repository's HEAD and operation refs through Git's ref backend.

        Returns (the ref HEAD names, or None when HEAD is detached; the commit
        a detached HEAD names, or None; each of _GIT_OPERATION_REF_NAMES that
        exists). Run as _repository_refs is, so no object is read or
        fetched. Git's backend is asked rather than the files read: a
        reftable repository keeps a placeholder in its HEAD file and its
        HEAD, CHERRY_PICK_HEAD, and REVERT_HEAD in its ref database, and the
        files backend accepts a HEAD file ending in a carriage return. Each
        operation ref is asked for by its exact name (show-ref --exists),
        never resolved the way rev-parse does, which would take a branch
        named CHERRY_PICK_HEAD for an unfinished cherry-pick. Any answer
        other than a name or a clean "does not exist" refuses, so a Git too
        old for --exists refuses too, and so does a detached HEAD that names
        nothing.
        """

        env = {
            "GIT_DIR": str(git_directory),
            "GIT_WORK_TREE": str(work),
            "GIT_NO_LAZY_FETCH": "1",
        }
        timeout_refusal = (
            f"Git did not read the HEAD of {label} within "
            f"{_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped and "
            "nothing was removed. remedy: rerun when the host is less loaded"
        )

        def resolve(name: str) -> str | None:
            resolved = self._run_bytes(
                work,
                ["rev-parse", "--quiet", "--verify", "--end-of-options", name],
                env_overrides=env,
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=timeout_refusal,
            )
            if resolved.returncode == 1 and not resolved.stdout and not resolved.stderr:
                return None
            value = resolved.stdout.decode("ascii", "replace").removesuffix("\n")
            if resolved.returncode != 0 or resolved.stderr or not SHA_RE.fullmatch(value):
                raise Refusal(
                    f"cannot resolve {name} of {label}" + _git_bytes_failure_detail(resolved)
                )
            return value

        symbolic = self._run_bytes(
            work,
            ["symbolic-ref", "--quiet", "HEAD"],
            env_overrides=env,
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=timeout_refusal,
        )
        target: str | None = None
        detached: str | None = None
        if symbolic.returncode == 0 and not symbolic.stderr:
            lines = symbolic.stdout.split(b"\n")
            if len(lines) != 2 or lines[1] or not lines[0].startswith(b"refs/"):
                raise Refusal(f"Git returned a malformed HEAD for {label}")
            target = _display_git_path(lines[0])
        elif symbolic.returncode == 1 and not symbolic.stdout and not symbolic.stderr:
            detached = resolve("HEAD")
            if detached is None:
                raise Refusal(f"the detached HEAD of {label} names no commit")
        else:
            raise Refusal(f"cannot read HEAD of {label}" + _git_bytes_failure_detail(symbolic))

        def exists(name: str) -> bool:
            # Exit 2 with exactly this one line is Git's "no such ref" for
            # --exists; Git runs with LC_ALL=C, so the line is not translated.
            probed = self._run_bytes(
                work,
                ["show-ref", "--exists", "--end-of-options", name],
                env_overrides=env,
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=timeout_refusal,
            )
            if probed.returncode == 2 and not probed.stdout and (
                probed.stderr == b"error: reference does not exist\n"
            ):
                return False
            if probed.stdout or probed.stderr or probed.returncode != 0:
                raise Refusal(
                    f"cannot tell whether {name} exists in {label}"
                    + _git_bytes_failure_detail(probed)
                )
            return True

        operations = tuple(name for name in _GIT_OPERATION_REF_NAMES if exists(name))
        return target, detached, operations

    def _isolated_object_kinds(
        self,
        isolated: Path,
        object_env: Mapping[str, str],
        objects: Iterable[str],
        label: str,
        timeout_refusal: str,
    ) -> dict[str, tuple[str, str | None, str | None]]:
        """Map each object to (type, peeled object, peeled type), read in ``isolated``.

        The isolated repository has no promisor remote and no configuration
        of the repository examined, so a missing object reads as "missing"
        and nothing is fetched. The peeled fields name what a tag finally
        points to, and are None for any other object.
        """

        queried = sorted(set(objects))
        if not queried:
            return {}

        def census(lines: Sequence[str]) -> list[tuple[str, str]]:
            checked = self._run_bytes(
                isolated,
                ["cat-file", "--batch-check=%(objectname) %(objecttype)"],
                input_bytes="".join(f"{line}\n" for line in lines).encode("ascii"),
                env_overrides={**object_env, "GIT_NO_LAZY_FETCH": "1"},
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=timeout_refusal,
            )
            if checked.returncode != 0:
                raise Refusal(
                    f"cannot read the objects of {label}" + _git_bytes_failure_detail(checked)
                )
            output = checked.stdout.decode("ascii", "replace").splitlines()
            if len(output) != len(lines):
                raise Refusal(f"Git returned a malformed object census for {label}")
            result: list[tuple[str, str]] = []
            for line in output:
                fields = line.split(" ")
                if len(fields) != 2 or not fields[1]:
                    raise Refusal(f"Git returned a malformed object census for {label}")
                result.append((fields[0], fields[1]))
            return result

        kinds: dict[str, tuple[str, str | None, str | None]] = {}
        for value, (name, kind) in zip(queried, census(queried), strict=True):
            if name != value:
                raise Refusal(f"Git returned a malformed object census for {label}")
            kinds[value] = (kind, None, None)
        tags = [value for value in queried if kinds[value][0] == "tag"]
        for value, (name, kind) in zip(
            tags, census([f"{value}^{{}}" for value in tags]), strict=True
        ):
            if kind == "missing":
                kinds[value] = ("tag", None, "missing")
            elif not SHA_RE.fullmatch(name):
                raise Refusal(f"Git returned a malformed object census for {label}")
            else:
                kinds[value] = ("tag", name, kind)
        return kinds

    def _own_commits(self, objects: Path, label: str, timeout_refusal: str) -> list[str]:
        """Return every commit stored in the object directory ``objects`` itself.

        Loose and packed alike, whether a ref, a reflog, or nothing names
        it; but not one read through its objects/info/alternates
        (_readable_commits lists those too). Git lists the objects of an
        alternate with a repository's own, so it is asked in a temporary
        object directory holding a link to each loose-object and pack
        directory of ``objects``, and no alternates file. An entry of those
        directories that is not a directory refuses, and so does a pack Git
        would leave out (_refuse_unusable_pack_indexes) or anything Git
        reports while listing (_list_commits).
        """

        _refuse_unusable_pack_indexes(objects, label)
        with tempfile.TemporaryDirectory(prefix="wrkslots-own-objects-") as temporary:
            own = Path(temporary) / "objects"
            own.mkdir()
            try:
                with os.scandir(objects) as listing:
                    for entry in listing:
                        if entry.name != "pack" and not re.fullmatch(
                            r"[0-9a-f]{2}", entry.name
                        ):
                            continue
                        if entry.is_symlink() or not entry.is_dir(follow_symlinks=False):
                            raise Refusal(
                                f"{entry.path} in {label} is not a directory; nothing "
                                "was removed"
                            )
                        (own / entry.name).symlink_to(entry.path, target_is_directory=True)
            except OSError as exc:
                raise Refusal(f"cannot list {objects} of {label}: {exc}") from exc
            with self._isolated_repository(own) as (isolated, object_env):
                return self._list_commits(isolated, object_env, label, timeout_refusal)

    def _readable_commits(
        self, objects: Path, label: str, timeout_refusal: str
    ) -> list[str]:
        """Return every commit Git reads through the object directory ``objects``.

        Those it stores itself (_own_commits) and those of each object
        directory it borrows from (_alternate_object_directories), named by
        anything or by nothing. A pack in any of them that Git would leave
        out refuses (_refuse_unusable_pack_indexes), and so does anything Git
        reports while listing (_list_commits).
        """

        for directory in (objects, *_alternate_object_directories(objects, label)):
            _refuse_unusable_pack_indexes(directory, label)
        with self._isolated_repository(objects) as (isolated, object_env):
            return self._list_commits(isolated, object_env, label, timeout_refusal)

    def _list_commits(
        self,
        isolated: Path,
        object_env: Mapping[str, str],
        label: str,
        timeout_refusal: str,
    ) -> list[str]:
        """List each commit the isolated repository ``isolated`` reads.

        Git leaves out, with only a warning and exit status 0, objects it
        cannot read, such as those of a pack whose index it cannot use; so
        anything it reports refuses.
        """

        listed = self._run_bytes(
            isolated,
            [
                "cat-file",
                "--batch-all-objects",
                "--unordered",
                "--batch-check=%(objecttype) %(objectname)",
            ],
            env_overrides={**object_env, "GIT_NO_LAZY_FETCH": "1"},
            timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
            timeout_refusal=timeout_refusal,
        )
        if listed.returncode != 0:
            raise Refusal(
                f"cannot list the objects of {label}" + _git_bytes_failure_detail(listed)
            )
        if listed.stderr.strip():
            raise Refusal(
                f"Git reported a problem while listing the objects of {label}, so "
                "the list may be incomplete" + _git_bytes_failure_detail(listed)
            )
        commits: list[str] = []
        for line in listed.stdout.decode("ascii", "replace").splitlines():
            kind, _space, value = line.partition(" ")
            if not SHA_RE.fullmatch(value):
                raise Refusal(f"Git returned a malformed object list for {label}")
            if kind == "commit":
                commits.append(value)
        return commits

    def _borrowed_unpublished(
        self,
        objects: Path,
        stored: AbstractSet[str],
        covered: Sequence[str],
        walk_alternates: Sequence[Path],
        label: str,
        timeout_refusal: str,
        examined: Sequence[Path] = (),
    ) -> list[str]:
        """Return why commits read only through alternates of the object directory ``objects`` block salvage.

        A commit Git reads through objects/info/alternates is stored in an
        object directory other repositories may share. When no ref or reflog
        of this repository names it, nothing tells whether it is this
        repository's own work. Such a commit, one not in ``stored`` (the
        commits ``objects`` stores itself, already compared), that is
        reachable from none of ``covered`` (the commits of the remote-tracking
        refs and the tips salvage keeps) can be shown neither published nor
        salvaged, so it blocks. ``walk_alternates`` are added for that walk
        only, where the commits of the shared repository's remote-tracking
        refs are read. Returns one reason, or none.

        ``examined`` are the object directories of the other submodule
        repositories this census examines. A commit one of them stores
        itself (_own_commits) does not block: the census of that repository
        shows it published or salvages it, as it does every commit a
        repository stores.
        """

        alternates = _alternate_object_directories(objects, label)
        if not alternates:
            return []
        censused = {Path(os.path.realpath(directory)) for directory in examined}
        elsewhere: set[str] = set()
        for directory in alternates:
            if directory in censused:
                elsewhere.update(
                    self._own_commits(
                        directory,
                        f"object directory {directory}, which {label} borrows from",
                        timeout_refusal,
                    )
                )
        borrowed = [
            commit
            for commit in self._readable_commits(objects, label, timeout_refusal)
            if commit not in stored and commit not in elsewhere
        ]
        if not borrowed:
            return []
        with self._isolated_repository(objects, alternates=walk_alternates) as (
            isolated,
            object_env,
        ):
            walked = self._run_bytes(
                isolated,
                ["rev-list", "--stdin"],
                input_bytes="".join(
                    [
                        *(f"{commit}\n" for commit in borrowed),
                        *(f"^{commit}\n" for commit in dict.fromkeys(covered)),
                    ]
                ).encode("ascii"),
                env_overrides={**object_env, "GIT_NO_LAZY_FETCH": "1"},
                timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                timeout_refusal=timeout_refusal,
                # GIT_GRAFT_FILE=/dev/null (_ISOLATED_HISTORY_ENV) otherwise
                # draws a deprecation hint, and anything Git reports refuses.
                config=(("advice.graftFileDeprecated", "false"),),
            )
        if walked.returncode != 0 or walked.stderr.strip():
            raise Refusal(
                f"cannot compare the commits {label} reads through its alternates "
                "with its remote-tracking refs" + _git_bytes_failure_detail(walked)
                + "; nothing was removed"
            )
        uncovered = walked.stdout.decode("ascii", "replace").splitlines()
        if not all(SHA_RE.fullmatch(commit) for commit in uncovered):
            raise Refusal(f"Git returned a malformed commit walk for {label}")
        if not uncovered:
            return []
        return [
            f"{len(uncovered)} commits it reads through objects/info/alternates, "
            f"such as {uncovered[0]}, are reachable from no remote-tracking ref and "
            "named by no ref or reflog of it, so recovery cannot tell whether they "
            "are its own work to salvage. remedy: fetch any that are its work to a "
            "remote-tracking ref, or run `git repack -a -d` in it and remove the "
            "alternates entry so that it holds what it reads itself"
        ]

    def _worktree_module(
        self,
        common: Path,
        administration: Path,
        name: str,
        path: Path,
        *,
        examined: Sequence[Path] = (),
    ) -> _WorktreeModule:
        """Examine the submodule repository ``path``, named ``name``, of ``administration``.

        ``examined`` are the repositories the same census examines, this one
        among them (see _borrowed_unpublished).
        """

        label = f"submodule repository {path}"
        blocking = [
            f"unfinished operation {path / state}"
            for state in _GIT_OPERATION_STATE_NAMES
            if (path / state).exists() or (path / state).is_symlink()
        ]
        if (path / "commondir").exists() or (path / "commondir").is_symlink():
            blocking.append(f"{path / 'commondir'} names objects kept elsewhere")
        lock = path / "index.lock"
        if lock.exists() or lock.is_symlink():
            # Git creates the lock before it writes the index and renames it
            # over the index when done, so a lock found here belongs to a Git
            # command still staging or committing, or to one that stopped
            # without finishing; either may hold work no census can see.
            blocking.append(
                f"Git index lock {lock} exists: a Git command is using {label}, or "
                "one stopped without removing its lock"
            )
        blocking.extend(_repository_ref_locks(path))
        if (path / "shallow").exists() or (path / "shallow").is_symlink():
            # A shallow clone lacks the history below its boundary, so no
            # bundle of it is complete and no ancestry walk of it is sound.
            return _WorktreeModule(
                name=name,
                path=path,
                administration=administration,
                shared=None,
                head=None,
                tips=(),
                blocking=(
                    *blocking,
                    f"{path / 'shallow'} marks a shallow clone, whose history cannot "
                    "be checked or bundled completely",
                ),
            )
        linked = path / "worktrees"
        if linked.exists() or linked.is_symlink():
            if linked.is_symlink() or not linked.is_dir() or any(linked.iterdir()):
                blocking.append(f"other worktrees use this repository ({linked})")
        candidate = common / name
        shared: Path | None = (
            None
            if (
                candidate == path
                or candidate.is_symlink()
                or not (candidate / "HEAD").is_file()
                or (candidate / "HEAD").is_symlink()
                or (candidate / "objects").is_symlink()
                or not (candidate / "objects").is_dir()
            )
            else candidate
        )
        # Only a guard: Git is asked what HEAD names (see _repository_head),
        # but a HEAD that is a link or is oversized refuses before Git runs.
        _read_bounded_regular_file(
            path / "HEAD", "submodule HEAD", _WORKTREE_MODULE_HEAD_BYTES_LIMIT
        )
        with tempfile.TemporaryDirectory(prefix="wrkslots-module-") as temporary:
            work = Path(temporary)
            refs = self._repository_refs(work, path, label)
            logged, reflog_blocking = self._repository_reflog_commits(work, path, label)
            blocking.extend(reflog_blocking)
            head_target, detached_head, operations = self._repository_head(
                work, path, label
            )
            blocking.extend(
                f"unfinished operation {operation} in {label}"
                for operation in operations
                if not (path / operation).exists() and not (path / operation).is_symlink()
            )
            shared_refs = (
                ()
                if shared is None
                else self._repository_refs(work, shared, f"shared repository {shared}")
            )

        timeout_refusal = (
            f"Git did not compare the commits of {label} with its remote-tracking refs "
            f"within {_ABSENT_AGENT_HISTORY_SECONDS:g} seconds; the command was stopped "
            "and nothing was removed. remedy: rerun when the host is less loaded"
        )
        tips: list[str] = []
        with self._isolated_repository(
            path / "objects",
            alternates=() if shared is None else (shared / "objects",),
        ) as (isolated, object_env):
            kinds = self._isolated_object_kinds(
                isolated,
                object_env,
                (target for _ref, target in (*refs, *shared_refs)),
                label,
                timeout_refusal,
            )

            def commit_of(entry: tuple[str, str]) -> str | None:
                kind, peeled, peeled_kind = kinds[entry[1]]
                if kind == "commit":
                    return entry[1]
                if kind == "tag" and peeled_kind == "commit":
                    return peeled
                return None

            published = {
                commit
                for entry in (*refs, *shared_refs)
                if entry[0].startswith("refs/remotes/")
                and (commit := commit_of(entry)) is not None
            }
            candidates: dict[str, None] = {}
            for entry in refs:
                if entry[0].startswith("refs/remotes/"):
                    continue
                commit = commit_of(entry)
                if commit is not None:
                    candidates[commit] = None
                else:
                    # A ref naming a tree, a blob, a tag of either, or a missing
                    # object preserves no commit, and salvage keeps only
                    # commits. The same ref in the shared repository proves
                    # nothing: that repository may read the object from this
                    # one through objects/info/alternates.
                    blocking.append(
                        f"ref {entry[0]} names {kinds[entry[1]][0]} {entry[1]}"
                    )
            head: str | None = None
            if detached_head is not None:
                head = detached_head
                candidates[head] = None
            else:
                # An unborn branch is absent from refs and preserves nothing.
                head = next(
                    (commit_of(entry) for entry in refs if entry[0] == head_target), None
                )
            queried = sorted({*candidates, *published})
            types: dict[str, str] = {}
            if queried:
                checked = self._run_bytes(
                    isolated,
                    ["cat-file", "--batch-check=%(objectname) %(objecttype)"],
                    input_bytes="".join(f"{value}\n" for value in queried).encode("ascii"),
                    env_overrides=object_env,
                    timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                    timeout_refusal=timeout_refusal,
                )
                if checked.returncode != 0:
                    raise Refusal(
                        f"cannot read the objects of {label}"
                        + _git_bytes_failure_detail(checked)
                    )
                lines = checked.stdout.decode("ascii", "replace").splitlines()
                if len(lines) != len(queried):
                    raise Refusal(f"Git returned a malformed object census for {label}")
                for value, line in zip(queried, lines, strict=True):
                    fields = line.split(" ")
                    if len(fields) != 2 or fields[0] != value:
                        raise Refusal(f"Git returned a malformed object census for {label}")
                    types[value] = fields[1]
            for commit in candidates:
                if types.get(commit) != "commit":
                    blocking.append(
                        f"commit {commit} named by HEAD or a ref is unreadable "
                        f"({types.get(commit, 'missing')})"
                    )
            readable = [commit for commit in candidates if types.get(commit) == "commit"]
            # A commit no ref names, kept only by a reflog or by nothing at
            # all, is as unpublished as one a branch names: every commit
            # this repository stores itself, and every one its reflogs name
            # wherever it is stored, is compared too.
            stored = self._own_commits(path / "objects", label, timeout_refusal)
            if readable or stored or logged:
                walked = self._run_bytes(
                    isolated,
                    ["rev-list", "--parents", "--stdin"],
                    input_bytes="".join(
                        [
                            *(
                                f"{commit}\n"
                                for commit in dict.fromkeys((*readable, *stored, *logged))
                            ),
                            *(
                                f"^{commit}\n"
                                for commit in sorted(published)
                                if types.get(commit) == "commit"
                            ),
                        ]
                    ).encode("ascii"),
                    env_overrides=object_env,
                    timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                    timeout_refusal=timeout_refusal,
                )
                if walked.returncode != 0:
                    raise Refusal(
                        f"cannot compare the commits of {label} with its remote-tracking "
                        "refs" + _git_bytes_failure_detail(walked) + "; a commit it "
                        "stores whose history is incomplete cannot be salvaged, even "
                        "one no ref names. nothing was removed. remedy: inspect it "
                        "with `git fsck`; once nothing that no ref or reflog names is "
                        "wanted, `git gc --prune=now` removes it, then rerun"
                    )
                unpublished: set[str] = set()
                parents: set[str] = set()
                for line in walked.stdout.decode("ascii", "replace").splitlines():
                    commit, *above = line.split(" ")
                    if not SHA_RE.fullmatch(commit) or not all(
                        SHA_RE.fullmatch(value) for value in above
                    ):
                        raise Refusal(f"Git returned a malformed commit walk for {label}")
                    unpublished.add(commit)
                    parents.update(above)
                # Each unpublished commit HEAD or a ref names, and each that
                # no other unpublished commit has as a parent: salvaging
                # those keeps every unpublished commit with its history.
                tips = sorted(
                    {commit for commit in readable if commit in unpublished}
                    | (unpublished - parents)
                )
            blocking.extend(
                self._borrowed_unpublished(
                    path / "objects",
                    frozenset(stored),
                    (
                        *(commit for commit in sorted(published) if types.get(commit) == "commit"),
                        *tips,
                    ),
                    () if shared is None else (shared / "objects",),
                    label,
                    timeout_refusal,
                    tuple(
                        repository / "objects"
                        for repository in examined
                        if repository != path
                    ),
                )
            )
            index = path / "index"
            if index.exists() or index.is_symlink():
                if index.is_symlink() or not index.is_file():
                    blocking.append(f"index {index} is not a regular file")
                elif head is None or types.get(head) != "commit":
                    blocking.append(f"index {index} has no readable HEAD commit to compare")
                else:
                    staged = self._run_bytes(
                        isolated,
                        [
                            "diff-index",
                            "--cached",
                            "--exit-code",
                            "--name-only",
                            "-z",
                            "--no-renames",
                            "--ignore-submodules=none",
                            head,
                            "--",
                        ],
                        env_overrides={**object_env, "GIT_INDEX_FILE": str(index)},
                        timeout_seconds=_ABSENT_AGENT_HISTORY_SECONDS,
                        timeout_refusal=timeout_refusal,
                    )
                    paths = [
                        _display_git_path(value)
                        for value in staged.stdout.split(b"\0")
                        if value
                    ]
                    if staged.returncode == 1 and paths:
                        shown = ", ".join(paths[:5]) + (
                            f", and {len(paths) - 5} more" if len(paths) > 5 else ""
                        )
                        blocking.append(
                            f"index {index} stages content HEAD {head} does not "
                            f"contain ({shown})"
                        )
                    elif staged.returncode != 0 or paths:
                        raise Refusal(
                            f"cannot compare the index of {label} with {head}"
                            + _git_bytes_failure_detail(staged)
                        )
                    blocking.extend(
                        self._resolve_undo_beyond(
                            isolated, object_env, index, head, path
                        )
                    )
        return _WorktreeModule(
            name=name,
            path=path,
            administration=administration,
            shared=shared,
            head=head,
            tips=tuple(tips),
            blocking=tuple(blocking),
        )

    @contextlib.contextmanager
    def worktree_index_locked(self, repository: Path, checkout: Path) -> Iterator[Path]:
        """Hold Git's own lock on the index of linked worktree ``checkout``.

        Git creates <administrative directory>/index.lock exclusively before it
        writes that index, so while the lock exists no Git command can stage
        content or commit there. `git worktree remove` deletes the lock with
        the administrative directory; otherwise it is released on exit. Yields
        the administrative directory.
        """

        administration = self.worktree_administrative_directory(repository, checkout)
        if administration is None:
            raise Refusal(
                f"Git registers {checkout} but no administrative directory names it"
            )
        lock = administration / "index.lock"
        try:
            descriptor = os.open(
                lock,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                0o600,
            )
        except FileExistsError as exc:
            raise Refusal(
                f"Git index lock {lock} already exists: a Git command is using the "
                f"index of {checkout}, or one stopped without removing its lock. "
                "remedy: once no Git command uses that worktree, delete the lock and "
                "rerun"
            ) from exc
        except OSError as exc:
            raise Refusal(f"cannot lock the Git index of {checkout}: {exc}") from exc
        try:
            created = os.fstat(descriptor)
        except OSError as exc:
            os.close(descriptor)
            lock.unlink(missing_ok=True)
            raise Refusal(f"cannot lock the Git index of {checkout}: {exc}") from exc
        os.close(descriptor)
        try:
            yield administration
        finally:
            try:
                observed = os.lstat(lock)
            except FileNotFoundError:
                pass
            else:
                if (observed.st_dev, observed.st_ino) == (created.st_dev, created.st_ino):
                    lock.unlink()

    @contextlib.contextmanager
    def worktree_modules_set_aside(
        self, administration: Path, retained: _RetainedModules
    ) -> Iterator[Callable[[], _DirectoryIdentity | None]]:
        """Move ``administration``/modules aside while recovery examines it, then keep it at ``retained``.path.

        A Git command reaches a submodule repository of a linked worktree by
        its path under <administrative directory>/modules/: through the
        checkout's gitfile, or through a GIT_DIR naming it. Locking each
        submodule's index does not stop a writer that needs no index
        (commit-tree, then update-ref) or uses another one (GIT_INDEX_FILE),
        and either can commit after the census. Renaming the directory stops
        a Git command started later, which then finds no repository. A
        command already running would make modules/<name>/refs/... anew,
        since Git makes any missing leading directory when it writes a ref,
        a lock, or an object, and write a ref there that removal deletes
        unexamined; so immediately after the rename a regular file is put at
        modules/ (_place_worktree_modules_placeholder), created exclusively:
        no directory can then be made below that path, and finding anything
        already there refuses with both kept. The caller examines the
        repositories where they now are (worktree_modules with set_aside).

        Recovery never deletes them. The yielded callable confirms that the
        placeholder is still the file made, then moves them, by one rename,
        to ``retained``.path/modules (_retain_worktree_modules), outside the
        administrative directory, immediately before the registration is
        removed, and returns the moved directory's device and inode, or None
        when there was nothing to move; removing the registration then
        deletes only the administrative files.
        ``retained`` is _worktree_modules_retained, and its path must not
        exist yet. If the body raises before that move, they are moved back
        from the set-aside path, and the placeholder is removed. Once they
        are moved they stay where they are kept, whatever the body does
        next: Git may have begun removing the registration, and if it
        stopped partway it may no longer register the administrative
        directory, or remove it whole once it notices that the checkout is
        gone. Only a resumed recovery moves them back, and only when nothing
        the administrative directory held at the move is gone
        (_restore_worktree_modules_retained).

        A process that already holds a handle inside them (a working
        directory, a directory descriptor, in any thread, or in a child it
        forks later) follows each rename, and so does a Git transaction it
        prepared. A commit such a process makes after the census, or a ref
        it names one with, is therefore not salvaged to a remote or bundle,
        but it is not lost either: it stays in the repositories at
        ``retained``.path, where every later write of that process goes too.
        Nothing removes what is kept there.

        A recovery stopped at any point before the registration is removed
        moves them back when it resumes, before it checks anything
        (_restore_worktree_modules_set_aside). Until then every census of the
        checkout refuses (_worktree_module_directories).
        """

        root = administration / "modules"
        aside = administration / _WORKTREE_MODULES_ASIDE
        if aside.exists() or aside.is_symlink():
            raise Refusal(
                f"{aside} already exists: a recovery stopped with submodule "
                "repositories moved aside. remedy: rerun `wrkslots recover`"
            )
        if _is_worktree_modules_placeholder(root):
            raise Refusal(
                f"{root} is already a recovery's placeholder: a recovery stopped "
                "before it finished. remedy: rerun `wrkslots recover`"
            )
        if retained.path.exists() or retained.path.is_symlink():
            raise Refusal(
                f"{retained.path} already exists: a recovery of this row kept submodule "
                "repositories there before it stopped, or something else made it; "
                "nothing was moved. remedy: rerun `wrkslots recover`, which moves "
                "them back first"
            )
        if root.exists() or root.is_symlink():
            if root.is_symlink() or not root.is_dir():
                raise Refusal(
                    f"submodule directory Git kept for a worktree is unsafe: {root}"
                )
            try:
                os.rename(root, aside)
            except OSError as exc:
                raise Refusal(f"cannot move {root} aside for removal: {exc}") from exc
        moved = False
        try:
            placeholder = _place_worktree_modules_placeholder(administration)
            if (aside.exists() or aside.is_symlink()) and (
                aside.is_symlink() or not aside.is_dir()
            ):
                raise Refusal(
                    f"{aside} was replaced once the submodule repositories were "
                    "moved there; nothing was removed"
                )
            _interrupt_for_test("after-absent-agent-modules-set-aside")

            def retain_modules() -> _DirectoryIdentity | None:
                nonlocal moved
                try:
                    metadata = os.lstat(root)
                except OSError as exc:
                    raise Refusal(
                        f"the placeholder {root} disappeared before removal: {exc}; "
                        "nothing was removed"
                    ) from exc
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or (metadata.st_dev, metadata.st_ino) != placeholder
                    or not _is_worktree_modules_placeholder(root)
                ):
                    raise Refusal(
                        f"{root} was replaced while the submodule repositories were "
                        "aside; nothing was removed. remedy: merge what is there into "
                        f"{aside}, rename that back to modules/, then rerun"
                    )
                if not (aside.exists() or aside.is_symlink()):
                    return None
                kept_identity = _retain_worktree_modules(administration, retained)
                moved = True
                return kept_identity

            yield retain_modules
        finally:
            # Once they are moved to ``retained``.path they stay there: only
            # a resumed recovery, which first proves that Git has not begun
            # removing the registration, moves them back.
            if not moved:
                _restore_worktree_modules_set_aside(administration, retained)

    def verify_existing_worktree(self, repository: Path, checkout: Path) -> str:
        source_common = self.common_directory(repository)
        checkout_root = self.repository_root(checkout)
        if checkout_root != checkout.absolute():
            raise Refusal(
                f"checkout path is not its Git worktree root: {checkout} (root {checkout_root})"
            )
        if self.common_directory(checkout) != source_common:
            raise Refusal(f"checkout {checkout} does not belong to repository {repository}")
        if checkout.absolute() not in self.listed_worktrees(repository):
            raise Refusal(f"Git does not list {checkout} as a worktree of {repository}")
        return self.head(checkout)

    def head(self, checkout: Path) -> str:
        result = self._run(checkout, ["rev-parse", "--verify", "HEAD^{commit}"])
        sha = result.stdout.strip()
        if not SHA_RE.fullmatch(sha):
            raise Refusal(f"checkout HEAD is not a full commit: {checkout}")
        return sha

    def branch(self, checkout: Path) -> str:
        result = self._run(checkout, ["symbolic-ref", "--quiet", "--short", "HEAD"], check=False)
        # With --quiet, a detached HEAD is exactly exit 1 with no diagnostic. Anything else
        # (a fatal error, a signal, a vanished `.git`) is a Git failure, not a branch state.
        if result.returncode == 1 and not result.stdout and not result.stderr:
            raise Refusal(f"checkout must be on its registered branch, not detached: {checkout}")
        if result.returncode != 0:
            raise Refusal(
                f"cannot read the branch of checkout {checkout}: git symbolic-ref failed"
                + _git_failure_detail(result)
            )
        branch = result.stdout.strip()
        _validate_ref(branch, "branch")
        return branch

    def status(
        self,
        checkout: Path,
        cache_globs: Sequence[str] = (),
        *,
        include_ignored: bool = True,
        refresh_index: bool = True,
    ) -> str:
        pathspecs = ["."]
        for pattern in cache_globs:
            pathspecs.append(f":(exclude,glob){pattern}")
            pathspecs.append(f":(exclude,glob){pattern}/**")
        arguments = ["status", "--porcelain=v2", "--untracked-files=all"]
        if include_ignored:
            arguments.append("--ignored=matching")
        arguments.extend(("--", *pathspecs))
        result = self._run(
            checkout,
            arguments,
            env_overrides=(
                None if refresh_index else {"GIT_OPTIONAL_LOCKS": "0"}
            ),
        )
        return result.stdout

    def uncommitted_handoff_paths(
        self, checkout: Path, cache_globs: Sequence[str] = ()
    ) -> tuple[str, ...]:
        """Return non-ignored, uncommitted paths whose basename starts HANDOFF."""

        pathspecs = [":(glob)HANDOFF*", ":(glob)**/HANDOFF*"]
        for pattern in cache_globs:
            pathspecs.append(f":(exclude,glob){pattern}")
            pathspecs.append(f":(exclude,glob){pattern}/**")
        changed = self._run(
            checkout,
            ["diff", "--name-only", "-z", "HEAD", "--", *pathspecs],
        ).stdout
        untracked = self._run(
            checkout,
            [
                "ls-files",
                "--others",
                "--exclude-standard",
                "-z",
                "--",
                *pathspecs,
            ],
        ).stdout
        return tuple(
            sorted(
                path
                for output in (changed, untracked)
                for path in output.split("\x00")
                if path
            )
        )

    def tracked_cache_paths(
        self, checkout: Path, cache_globs: Sequence[str]
    ) -> tuple[str, ...]:
        if not cache_globs:
            return ()
        indexed = self._run(checkout, ["ls-files", "--recurse-submodules", "-z"])
        committed = self._run(
            checkout,
            ["ls-tree", "-r", "--name-only", "-z", "HEAD"],
        )
        # A listing holds tens of thousands of paths and nearly none are cache,
        # so testing every path against every glob made this the audit's
        # largest cost. Each path is tested against the globs that can contain
        # it and, in place, against the other globs whose test reaches fnmatch
        # and so compiles or refreshes a pattern there (see _CacheGlobIndex),
        # all in their original order. Every glob left out would have returned
        # False with no effect. When the same run of skipped tests was just
        # made, and fnmatch can hold everything such runs pass it, the run is
        # not repeated. The selection stays inline, as it was, so the matcher
        # runs at the same stack depth and a glob deep enough to approach the
        # recursion limit succeeds or fails exactly as before.
        index = _cache_glob_index(tuple(cache_globs))
        shared = index.skipped_components <= _fnmatch_cache_size()
        last_run: list[tuple[str, ...]] = [()]
        paths = [
            path
            for output in (indexed.stdout, committed.stdout)
            for path in output.split("\x00")
            if path
            and any(
                _cache_glob_contains_path(pattern, path)
                for pattern in _cache_globs_to_test(
                    index.plan(path), last_run if shared else [()]
                )
            )
        ]
        return tuple(dict.fromkeys(paths))

    def submodule_paths(self, checkout: Path) -> tuple[str, ...]:
        indexed = self._run(checkout, ["ls-files", "--stage", "-z"])
        committed = self._run(checkout, ["ls-tree", "-r", "-z", "HEAD"])
        paths: list[str] = []
        for output in (indexed.stdout, committed.stdout):
            for record in output.split("\x00"):
                if not record:
                    continue
                metadata, separator, path = record.partition("\t")
                if separator and metadata.startswith("160000 "):
                    paths.append(path)
        return tuple(dict.fromkeys(paths))

    def initialized_submodules(self, checkout: Path) -> tuple[str, ...]:
        result = self._run(
            checkout,
            [
                "submodule",
                "foreach",
                "--quiet",
                "--recursive",
                'printf "%s\\n" "$displaypath"',
            ],
        )
        paths = tuple(line for line in result.stdout.splitlines() if line)
        for path in paths:
            candidate = Path(path)
            if candidate.is_absolute() or ".." in candidate.parts:
                raise Refusal(
                    f"Git reported an unsafe initialized submodule path: {path!r}"
                )
        return tuple(dict.fromkeys(paths))

    def assert_ordinary_index(self, checkout: Path) -> None:
        assume = self._run(checkout, ["ls-files", "-v"])
        for line in assume.stdout.splitlines():
            if line and line[0].islower():
                raise Refusal(
                    f"checkout has assume-unchanged index state: {line[2:]}"
                )
        skip = self._run(checkout, ["ls-files", "-t"])
        for line in skip.stdout.splitlines():
            if line.startswith("S "):
                raise Refusal(f"checkout has skip-worktree index state: {line[2:]}")

    def assert_ordinary_history(
        self, checkout: Path, *, allow_shallow: bool = False
    ) -> Path | None:
        """Refuse grafts, replacement refs and, unless ``allow_shallow``, shallow history.

        Returns the shallow file when ``allow_shallow`` lets one pass, else
        None. A shallow repository's history stops at its boundary, so the
        caller must then neither bundle it nor push from it; it may only show
        that its HEAD is already published (see _shallow_history_refusal).
        """

        common = self.common_directory(checkout)
        grafts = common / "info" / "grafts"
        shallow = common / "shallow"
        if grafts.exists() or grafts.is_symlink():
            raise Refusal(f"checkout uses graft history: {grafts}")
        shallow_present = shallow.exists() or shallow.is_symlink()
        if shallow_present and (not allow_shallow or shallow.is_symlink()):
            raise Refusal(f"checkout uses shallow history: {shallow}")
        replacements = self._run(
            checkout,
            ["for-each-ref", "--format=%(refname)", "refs/replace/"],
        )
        if replacements.stdout.strip():
            raise Refusal(
                f"checkout contains replacement refs: {replacements.stdout.splitlines()[0]}"
            )
        return shallow if shallow_present else None

    def fetch_remote(
        self,
        checkout: Path,
        remote: str,
        landed_ref: str,
        authority: _RemoteAuthority,
    ) -> None:
        _validate_remote(remote)
        _validate_full_ref(landed_ref, "landed ref")
        prefix = f"refs/remotes/{remote}/"
        if not landed_ref.startswith(prefix):
            raise Refusal(f"landed ref must be under {prefix}: {landed_ref}")
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            advertised = self._ls_remote_inventory(
                isolated,
                authority.url,
                heads_only=True,
                env_overrides=object_env,
            )
            fetched: dict[str, str] = {}
            if advertised:
                self._run(
                    isolated,
                    [
                        "fetch",
                        "--no-tags",
                        "--no-write-fetch-head",
                        "--no-auto-maintenance",
                        "--force",
                        "--no-recurse-submodules",
                        "--stdin",
                        "--",
                        authority.url,
                    ],
                    input_text="".join(
                        f"+{ref}:{ref}\n" for ref in sorted(advertised)
                    ),
                    env_overrides=object_env,
                )
                transferred = self._direct_ref_inventory(
                    isolated,
                    "refs/heads/",
                    env_overrides=object_env,
                )
                if transferred != advertised:
                    raise Refusal(
                        "Git fetched a different head inventory than the metadata inventory"
                    )
            else:
                transferred = {}
            heads_prefix = "refs/heads/"
            for ref, head in transferred.items():
                if not ref.startswith(heads_prefix):
                    raise Refusal(f"Git fetched a non-head ref: {ref}")
                tracking = prefix + ref.removeprefix(heads_prefix)
                _validate_full_ref(tracking, "remote-tracking ref")
                fetched[tracking] = head
        existing = self._direct_ref_inventory(checkout, prefix)
        updates = ["start"]
        zero = "0" * 40
        for ref, new_head in sorted(fetched.items()):
            old_head = existing.get(ref, zero)
            if old_head != new_head:
                updates.append(f"update {ref} {new_head} {old_head}")
        for ref, old_head in sorted(existing.items()):
            if ref not in fetched:
                updates.append(f"delete {ref} {old_head}")
        if len(updates) > 1:
            updates.extend(("prepare", "commit", ""))
            self._run(checkout, ["update-ref", "--stdin"], input_text="\n".join(updates))

    def _direct_ref_inventory(
        self,
        repository: Path,
        prefix: str,
        *,
        env_overrides: Mapping[str, str] | None = None,
    ) -> dict[str, str]:
        result = self._run(
            repository,
            ["for-each-ref", "--format=%(refname)%00%(objectname)%00%(symref)", prefix],
            env_overrides=env_overrides,
        )
        refs: dict[str, str] = {}
        for line in result.stdout.splitlines():
            fields = line.split("\0")
            if len(fields) != 3:
                raise Refusal("Git returned a malformed remote-ref inventory")
            ref, head, symbolic = fields
            if symbolic:
                continue
            _validate_full_ref(ref, "remote-tracking ref")
            if not SHA_RE.fullmatch(head) or ref in refs:
                raise Refusal("Git returned an ambiguous remote-ref inventory")
            refs[ref] = head
        return refs

    def _parse_remote_ref_inventory(self, output: str, label: str) -> dict[str, str]:
        refs: dict[str, str] = {}
        for line in output.splitlines():
            fields = line.split()
            if len(fields) != 2:
                raise Refusal(f"Git returned a malformed {label} inventory")
            head, ref = fields
            _validate_full_ref(ref, label)
            if not SHA_RE.fullmatch(head) or ref in refs:
                raise Refusal(f"Git returned an ambiguous {label} inventory")
            refs[ref] = head
        return refs

    def _ls_remote_inventory(
        self,
        repository: Path,
        url: str,
        *,
        refs: Sequence[str] = (),
        heads_only: bool = False,
        env_overrides: Mapping[str, str] | None = None,
        timeout_seconds: float | None = None,
        config: Sequence[tuple[str, str]] = (),
    ) -> dict[str, str]:
        """List the remote's refs at ``url``; ``timeout_seconds`` bounds the listing.

        A listing still running at that bound is stopped and refused.
        ``config`` holds Git settings for the listing, as _run takes them.
        """

        environment = dict(env_overrides or {})
        # ls-remote needs no repository. /dev/null is an explicit, immutable
        # non-repository GIT_DIR, so a same-UID .git/config appearing below the
        # temporary working directory cannot redirect the literal URL.
        environment["GIT_DIR"] = "/dev/null"
        arguments = ["ls-remote", "--refs"]
        if heads_only:
            arguments.append("--heads")
        arguments.extend(("--", url, *refs))
        # Settings reach _run only when there are some, so a listing without
        # them calls _run exactly as before ``config`` existed.
        run = self._run
        if config:
            run = functools.partial(self._run, config=config)
        # An unbounded listing calls _run exactly as before the bound existed.
        if timeout_seconds is None:
            result = run(repository, arguments, env_overrides=environment)
        else:
            result = run(
                repository,
                arguments,
                env_overrides=environment,
                timeout_seconds=timeout_seconds,
                timeout_refusal=(
                    f"Git did not list the remote's refs within {timeout_seconds:g} "
                    "seconds; the listing was stopped and no ref of the source "
                    "repository was read or written. remedy: rerun when the remote "
                    "answers faster"
                ),
            )
        return self._parse_remote_ref_inventory(result.stdout, "remote-ref")

    def _ls_remote_any_refs(
        self,
        repository: Path,
        url: str,
        *,
        refs: Sequence[str] = (),
        env_overrides: Mapping[str, str],
    ) -> dict[str, str]:
        """List every ref the remote at ``url`` advertises, with any valid name.

        Unlike _ls_remote_inventory, a name is read as the bytes Git printed
        (each line is <object> TAB <name>) and is accepted whenever Git's
        ref-name rules accept it (_validate_git_ref_name), so a name such as
        refs/stash, or one that is not UTF-8 or holds a non-ASCII space, is
        listed rather than refused. The listing is stopped, and refused,
        after _ABSENT_AGENT_REMOTE_LIST_SECONDS.
        """

        arguments = ["ls-remote", "--refs", "--", url, *refs]
        result = self._run_bytes(
            repository,
            arguments,
            # ls-remote needs no repository; see _ls_remote_inventory.
            env_overrides={**env_overrides, "GIT_DIR": "/dev/null"},
            timeout_seconds=_ABSENT_AGENT_REMOTE_LIST_SECONDS,
            timeout_refusal=(
                f"Git did not list the remote's refs within "
                f"{_ABSENT_AGENT_REMOTE_LIST_SECONDS:g} seconds; the listing was "
                "stopped and no ref of the source repository was read or written. "
                "remedy: rerun when the remote answers faster"
            ),
        )
        if result.returncode != 0:
            raise Refusal(
                "Git could not list the remote's refs"
                + _git_bytes_failure_detail(result)
            )
        listed: dict[str, str] = {}
        for line in result.stdout.split(b"\n"):
            if not line:
                continue
            head, separator, name = line.partition(b"\t")
            ref = os.fsdecode(name)
            try:
                head_text = head.decode("ascii")
                _validate_git_ref_name(ref, "remote ref")
            except (UnicodeDecodeError, Refusal):
                raise Refusal(
                    "Git returned a malformed remote-ref inventory line "
                    f"{_display_git_path(line)!r}"
                ) from None
            if not separator or not SHA_RE.fullmatch(head_text) or ref in listed:
                raise Refusal("Git returned an ambiguous remote-ref inventory")
            listed[ref] = head_text
        return listed

    def _assert_no_push_urls(
        self,
        checkout: Path,
        remote: str,
        *,
        env_overrides: Mapping[str, str] | None = None,
    ) -> None:
        _validate_remote(remote)
        result = self._run(
            checkout,
            ["config", "--null", "--get-all", f"remote.{remote}.pushurl"],
            check=False,
            env_overrides=env_overrides,
        )
        if result.returncode not in (0, 1):
            raise Refusal(
                f"cannot determine whether remote {remote!r} has a push URL"
                + _git_failure_detail(result)
            )
        values = result.stdout.split("\0")
        if values and values[-1] == "":
            values.pop()
        if any(value for value in values):
            raise Refusal(
                f"remote {remote!r} has a configured push URL; remove every non-empty "
                f"remote.{remote}.pushurl before remote operations"
            )

    def _remote_url_with_push_authority(
        self,
        checkout: Path,
        remote: str,
        *,
        env_overrides: Mapping[str, str] | None = None,
    ) -> str:
        _validate_remote(remote)
        self._assert_no_push_urls(checkout, remote, env_overrides=env_overrides)
        result = self._run(
            checkout, ["remote", "get-url", "--all", remote], env_overrides=env_overrides
        )
        urls = result.stdout.splitlines()
        if len(urls) != 1 or not urls[0]:
            raise Refusal(
                f"remote {remote!r} must have exactly one non-empty fetch URL"
            )
        push_result = self._run(
            checkout,
            ["remote", "get-url", "--push", "--all", remote],
            env_overrides=env_overrides,
        )
        push_urls = push_result.stdout.splitlines()
        if push_urls != urls:
            raise Refusal(
                f"remote {remote!r} effective push URL differs from its single fetch URL; "
                "remove pushInsteadOf or other push-only redirection"
            )
        return urls[0]

    def remote_authority(
        self,
        checkout: Path,
        remote: str,
        *,
        env_overrides: Mapping[str, str] | None = None,
    ) -> _RemoteAuthority:
        """Return ``remote``'s single URL; ``env_overrides`` can name another GIT_DIR."""

        url = self._remote_url_with_push_authority(
            checkout, remote, env_overrides=env_overrides
        )
        if url.startswith("-"):
            raise Refusal(
                f"remote {remote!r} URL cannot begin with '-' for isolated transport"
            )
        return _RemoteAuthority(
            url=url,
            sha256=hashlib.sha256(url.encode("utf-8")).hexdigest(),
        )

    def assert_remote_distinct_from_repositories(
        self,
        repository: Path,
        authority: _RemoteAuthority,
        protected_repositories: Sequence[Path],
    ) -> None:
        """Refuse a local remote that aliases any source repository in the row."""

        candidate = _local_remote_url_path(repository, authority.url)
        if candidate is None:
            return
        if not _local_remote_url_is_absolute(authority.url):
            kind = "file remote" if _GIT_URL_RE.match(authority.url) else "local remote"
            raise Refusal(
                f"relative {kind} {authority.url!r} has no stable meaning in the "
                "isolated salvage transport; use a distinct absolute remote URL"
            )
        try:
            candidate = candidate.resolve(strict=True)
        except OSError as exc:
            raise Refusal(
                f"cannot prove local remote {authority.url!r} is distinct from source "
                f"repositories: {exc}"
            ) from exc
        result = self._run(
            candidate,
            ["rev-parse", "--path-format=absolute", "--git-common-dir"],
            check=False,
        )
        lines = result.stdout.splitlines()
        if result.returncode != 0 or result.stderr or len(lines) != 1:
            raise Refusal(
                f"cannot classify local remote {authority.url!r} as one distinct Git "
                "repository"
            )
        remote_common = Path(lines[0])
        if not remote_common.is_absolute():
            remote_common = candidate / remote_common
        try:
            remote_common = remote_common.resolve(strict=True)
            remote_stat = remote_common.stat()
            protected_common = tuple(
                self.common_directory(source).resolve(strict=True)
                for source in protected_repositories
            )
            protected_identities = {
                (common.stat().st_dev, common.stat().st_ino)
                for common in protected_common
            }
        except OSError as exc:
            raise Refusal(
                "cannot resolve remote/source Git common directories before salvage"
            ) from exc
        if (
            remote_common in protected_common
            or (remote_stat.st_dev, remote_stat.st_ino) in protected_identities
        ):
            raise Refusal(
                f"remote {authority.url!r} resolves to a source repository in this "
                "recovery; refusing before the salvage push so no local ref is mutated"
            )

    def assert_remote_authority(
        self, checkout: Path, remote: str, authority: _RemoteAuthority
    ) -> None:
        expected_digest = hashlib.sha256(authority.url.encode("utf-8")).hexdigest()
        if authority.sha256 != expected_digest:
            raise StateError("remote authority URL and digest disagree")
        observed = self.remote_authority(checkout, remote)
        if observed != authority:
            raise Refusal(
                f"remote {remote!r} changed after authority was captured; preserve the "
                "checkout and restore its recorded remote"
            )

    @contextlib.contextmanager
    def _isolated_remote(
        self,
        checkout: Path,
        remote: str,
        authority: _RemoteAuthority,
        *,
        own_objects: bool = False,
    ) -> Iterator[tuple[Path, Mapping[str, str]]]:
        """Yield a temporary bare repository for talking to ``remote``.

        Its objects are the checkout's object store, or, with ``own_objects``,
        a store of its own that starts empty and has no alternates.
        """

        self.assert_remote_authority(checkout, remote, authority)
        objects = self.common_directory(checkout) / "objects"
        with self._isolated_repository(objects, own_objects=own_objects) as repository:
            yield repository

    @contextlib.contextmanager
    def _isolated_repository(
        self,
        objects: Path,
        *,
        own_objects: bool = False,
        alternates: Sequence[Path] = (),
        parent: Path | None = None,
    ) -> Iterator[tuple[Path, Mapping[str, str]]]:
        """Yield a temporary bare repository whose only configuration is _NETWORK_CONFIG.

        Its objects are ``objects``, or, with ``own_objects``, a store of its
        own that starts empty and has no alternates. Each of ``alternates``
        is added as an alternate object directory, read-only. The temporary
        repository is made in ``parent`` when given, otherwise in the
        system temporary directory.
        """

        if objects.is_symlink() or not objects.is_dir():
            raise Refusal(f"Git object directory is absent or unsafe: {objects}")
        if own_objects and alternates:
            raise StateError("an isolated repository with its own objects has no alternates")
        for alternate in alternates:
            if alternate.is_symlink() or not alternate.is_dir():
                raise Refusal(f"Git object directory is absent or unsafe: {alternate}")
            if os.pathsep in str(alternate):
                raise Refusal(f"Git object directory cannot be an alternate: {alternate}")
        if parent is not None and (parent.is_symlink() or not parent.is_dir()):
            raise Refusal(f"temporary repository parent is absent or unsafe: {parent}")
        with tempfile.TemporaryDirectory(
            prefix="wrkslots-remote-", dir=None if parent is None else str(parent)
        ) as temporary:
            root = Path(temporary)
            isolated = root / "network.git"
            for directory in (
                isolated / "objects" / "info",
                isolated / "objects" / "pack",
                isolated / "refs" / "heads",
                isolated / "refs" / "tags",
            ):
                directory.mkdir(parents=True, exist_ok=False)
            (isolated / "HEAD").write_bytes(b"ref: refs/heads/main\n")
            (isolated / "config").write_bytes(_NETWORK_CONFIG)
            config_digest = hashlib.sha256(_NETWORK_CONFIG).hexdigest()
            yield isolated, {
                "GIT_OBJECT_DIRECTORY": str(isolated / "objects" if own_objects else objects),
                _NETWORK_CONFIG_SHA256_ENV: config_digest,
                **_ISOLATED_HISTORY_ENV,
                **(
                    {
                        "GIT_ALTERNATE_OBJECT_DIRECTORIES": os.pathsep.join(
                            str(alternate) for alternate in alternates
                        )
                    }
                    if alternates
                    else {}
                ),
            }

    def confirm_remote_unreachable(
        self,
        checkout: Path,
        remote: str,
        authority: _RemoteAuthority,
        *,
        network_authority: _RemoteAuthority | None = None,
    ) -> _RemoteTransportUnavailable:
        """Ask the recorded URL again, without redirects, and return the outage.

        An HTTP remote that redirects elsewhere reports the other host's
        connection failure as its own. Asked without following redirects, the
        same remote answers with its redirect instead, which refuses.
        ``network_authority``, when given, is the URL that was asked (see
        remote_heads_containing); ``authority`` is still the checkout's own.
        """

        target = authority if network_authority is None else network_authority
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            try:
                # On Git's command line: the network wrapper requires an
                # environment without GIT_CONFIG_* (see _ISOLATED_HISTORY_ENV).
                self._ls_remote_inventory(
                    isolated,
                    target.url,
                    heads_only=True,
                    env_overrides=object_env,
                    config=(("http.followRedirects", "false"),),
                )
            except _RemoteTransportUnavailable as exc:
                return exc
        raise Refusal(
            f"remote {remote!r} answered when asked again without redirects after its "
            "fetch failed; preserve the checkout and rerun remove"
        )

    def remote_url_sha256(self, checkout: Path, remote: str) -> str:
        return self.remote_authority(checkout, remote).sha256

    def assert_remote_url(self, checkout: Path, remote: str, authorized_url: str) -> str:
        observed = self.remote_authority(checkout, remote)
        if observed.url != authorized_url:
            raise Refusal(
                f"remote {remote!r} URL differs from trusted provisioning input"
            )
        return observed.sha256

    def operation_paths(self, checkout: Path) -> list[Path]:
        names = _GIT_OPERATION_STATE_NAMES
        arguments: list[str] = ["rev-parse"]
        for name in names:
            arguments.extend(("--git-path", name))
        result = self._run(checkout, arguments)
        paths = result.stdout.splitlines()
        if len(paths) != len(names):
            raise Refusal("Git returned an incomplete operation-path inventory")
        found: list[Path] = []
        for raw_path in paths:
            candidate = Path(raw_path)
            if not candidate.is_absolute():
                candidate = checkout / candidate
            if candidate.exists() or candidate.is_symlink():
                found.append(candidate)
        return found

    def remote_refs_containing(self, checkout: Path, remote: str, head: str) -> tuple[str, ...]:
        _validate_remote(remote)
        result = self._run(
            checkout,
            [
                "for-each-ref",
                "--format=%(refname)",
                "--contains",
                head,
                f"refs/remotes/{remote}/",
            ],
        )
        refs = tuple(line for line in result.stdout.splitlines() if line)
        return refs

    def remote_heads_containing(
        self,
        checkout: Path,
        remote: str,
        head: str,
        authority: _RemoteAuthority,
        *,
        network_authority: _RemoteAuthority | None = None,
        shallow: bool = False,
    ) -> tuple[str, ...]:
        """Return refs/remotes/``remote``/<branch> for each remote branch containing ``head``.

        ``shallow`` says the checkout's history stops at a shallow boundary.
        Git then reports a branch tip whose parents are missing as containing
        any commit at all (it notes the missing parents on stderr and exits
        0), so no branch is compared in the checkout's object store: every
        tip is fetched, commits only, into the empty store described below,
        where only commits the remote sent are walked.

        ``authority`` is the checkout's own recorded remote and is rechecked
        first, every time. The branches are listed at ``network_authority``
        when it is given (a submodule whose remote is its source repository's
        own Git directory; see _submodule_network_authority), otherwise at
        ``authority``.

        This is the cheap form of fetch_remote followed by
        remote_refs_containing, and it gives the same answer: one ls-remote
        lists the remote's branches; a branch whose tip is already a commit
        in the checkout's object store is compared there; only when none of
        those contains ``head`` are the remaining tips fetched, and then only
        their commits (--filter=tree:0 where the remote supports filtering),
        into an empty temporary object store inside the checkout's own Git
        directory, never the system temporary directory. No ref of the
        checkout, including refs/remotes/*, is read or written. The answer is
        kept for _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS while a removal
        runs (_remote_containment_scope) and returned again without
        contacting the remote.
        """

        _validate_remote(remote)
        if not SHA_RE.fullmatch(head):
            raise Refusal(f"cannot search the remote for invalid commit {head!r}")
        self.assert_remote_authority(checkout, remote, authority)
        target = authority if network_authority is None else network_authority
        expected_digest = hashlib.sha256(target.url.encode("utf-8")).hexdigest()
        if target.sha256 != expected_digest:
            raise StateError("remote authority URL and digest disagree")
        if target.url.startswith("-"):
            raise Refusal(
                f"remote {remote!r} URL cannot begin with '-' for isolated transport"
            )
        common = self.common_directory(checkout)
        objects = common / "objects"
        memo = _REMOTE_CONTAINMENT_MEMO.get()
        key = (str(objects.resolve()), target.url, head, shallow)
        if memo is not None:
            cached = memo.get(key)
            if (
                cached is not None
                and time.monotonic() - cached.observed_at
                <= _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS
            ):
                if cached.refusal is not None:
                    raise cached.refusal
                return cached.refs
        try:
            refs = self._remote_heads_containing_uncached(
                checkout, remote, head, target, common, shallow=shallow
            )
        except Refusal as exc:
            if memo is not None:
                memo[key] = _RemoteContainmentEvidence((), time.monotonic(), exc)
            raise
        if memo is not None:
            memo[key] = _RemoteContainmentEvidence(refs, time.monotonic())
        return refs

    def _remote_heads_containing_uncached(
        self,
        checkout: Path,
        remote: str,
        head: str,
        target: _RemoteAuthority,
        common: Path,
        *,
        shallow: bool = False,
    ) -> tuple[str, ...]:
        """Ask the remote at ``target``; see remote_heads_containing."""

        objects = common / "objects"
        heads_prefix = "refs/heads/"
        with self._isolated_repository(objects) as (isolated, object_env):
            advertised = self._ls_remote_inventory(
                isolated,
                target.url,
                heads_only=True,
                env_overrides=object_env,
                timeout_seconds=_REMOTE_CONTAINMENT_LIST_SECONDS,
            )
            for ref in advertised:
                if not ref.startswith(heads_prefix):
                    raise Refusal(f"Git listed a non-head ref as a branch: {ref}")
            present = (
                frozenset()
                if shallow
                else self._present_commits(
                    isolated, set(advertised.values()), object_env
                )
            )
            local = {ref: tip for ref, tip in advertised.items() if tip in present}
            containing = self._isolated_refs_containing(
                isolated, local, head, object_env
            )
        if not containing:
            missing = {
                ref: tip for ref, tip in advertised.items() if tip not in present
            }
            if missing:
                containing = self._fetched_commits_containing(
                    common,
                    self._private_git_directory(checkout),
                    target,
                    missing,
                    head,
                )
        prefix = f"refs/remotes/{remote}/"
        refs = tuple(
            sorted(prefix + ref.removeprefix(heads_prefix) for ref in containing)
        )
        for ref in refs:
            _validate_full_ref(ref, "remote-tracking ref")
        return refs

    def _private_git_directory(self, checkout: Path) -> Path:
        """Return ``checkout``'s own Git directory (a linked worktree's, not the shared one)."""

        result = self._run(checkout, ["rev-parse", "--path-format=absolute", "--git-dir"])
        directory = Path(result.stdout.strip()).absolute()
        if directory.is_symlink() or not directory.is_dir():
            raise Refusal(f"Git reported an unsafe Git directory: {directory}")
        return directory

    def _present_commits(
        self,
        isolated: Path,
        candidates: AbstractSet[str],
        object_env: Mapping[str, str],
    ) -> frozenset[str]:
        """Return those of ``candidates`` that are commits in the isolated object store."""

        if not candidates:
            return frozenset()
        result = self._run(
            isolated,
            ["cat-file", "--batch-check=%(objectname) %(objecttype)"],
            input_text="".join(f"{tip}\n" for tip in sorted(candidates)),
            env_overrides=object_env,
        )
        found: set[str] = set()
        for line in result.stdout.splitlines():
            fields = line.split()
            if len(fields) == 2 and fields[1] == "commit" and fields[0] in candidates:
                found.add(fields[0])
        return frozenset(found)

    def _isolated_refs_containing(
        self,
        isolated: Path,
        tips: Mapping[str, str],
        head: str,
        object_env: Mapping[str, str],
    ) -> list[str]:
        """Return the names in ``tips`` whose commit contains ``head``, in that store.

        Each tip is named by a temporary ref in the isolated repository only;
        ``head`` and every tip must already be commits in its object store.
        """

        if not tips:
            return []
        names = sorted(tips)
        check_root = "refs/wrkslots-check/"
        self._run(
            isolated,
            ["update-ref", "--stdin"],
            input_text="".join(
                f"update {check_root}{index} {tips[name]}\n"
                for index, name in enumerate(names)
            ),
            env_overrides=object_env,
        )
        result = self._run(
            isolated,
            ["for-each-ref", "--format=%(refname)", "--contains", head, check_root],
            env_overrides={**object_env, "GIT_NO_LAZY_FETCH": "1"},
        )
        containing: list[str] = []
        for line in result.stdout.splitlines():
            if not line:
                continue
            suffix = line.removeprefix(check_root)
            if suffix == line or not suffix.isdigit() or int(suffix) >= len(names):
                raise Refusal(f"Git returned an unexpected containment ref: {line}")
            containing.append(names[int(suffix)])
        return containing

    def _fetched_commits_containing(
        self,
        common: Path,
        git_directory: Path,
        authority: _RemoteAuthority,
        missing: Mapping[str, str],
        head: str,
    ) -> list[str]:
        """Fetch the commits of ``missing`` into an empty store; return those containing ``head``.

        Every commit walked was sent by the remote, as in
        _assert_remote_sends_history: the store starts empty, has no
        alternates, and GIT_NO_LAZY_FETCH makes a missing commit an error
        rather than another download. Trees and blobs are not requested.
        The temporary repository is made inside ``git_directory``, the
        checkout's own Git directory, which removal deletes with the slot,
        so even a remote that ignores the filter writes nothing to the
        system temporary directory.
        """

        names = sorted(missing)
        proof_root = "refs/wrkslots-proof/"
        proof_config = (
            _NETWORK_CONFIG
            + b'[remote "proof"]\n\turl = '
            + _git_config_quoted(authority.url, "remote URL")
            + b"\n"
        )
        # With own_objects the first argument names no store that is used;
        # it only has to be a real object directory, and a linked worktree's
        # own Git directory has none, so the shared one is named.
        with self._isolated_repository(
            common / "objects", own_objects=True, parent=git_directory
        ) as (isolated, object_env):
            (isolated / "config").write_bytes(proof_config)
            fetched = self._run_bytes(
                isolated,
                [
                    "fetch",
                    "--filter=tree:0",
                    "--no-tags",
                    "--no-write-fetch-head",
                    "--no-auto-maintenance",
                    "--force",
                    "--no-recurse-submodules",
                    "--stdin",
                    "--",
                    "proof",
                ],
                input_bytes="".join(
                    f"+{name}:{proof_root}{index}\n" for index, name in enumerate(names)
                ).encode("utf-8"),
                env_overrides={
                    **object_env,
                    _NETWORK_CONFIG_SHA256_ENV: hashlib.sha256(proof_config).hexdigest(),
                },
                timeout_seconds=_REMOTE_CONTAINMENT_FETCH_SECONDS,
                timeout_refusal=(
                    f"Git did not fetch the commits of {len(names)} remote branch(es) "
                    f"within {_REMOTE_CONTAINMENT_FETCH_SECONDS:g} seconds; the fetch "
                    "was stopped and no ref of the checkout was read or written. "
                    "remedy: rerun when the remote answers faster"
                ),
            )
            (isolated / "config").write_bytes(_NETWORK_CONFIG)
            if fetched.returncode != 0:
                raise Refusal(
                    f"Git could not fetch the commits of {len(names)} remote branch(es) "
                    f"into an empty object store{_git_bytes_failure_detail(fetched)}. "
                    "No ref of the checkout was read or written. remedy: rerun when "
                    "the remote answers"
                )
            self._refuse_shallow_fetch(isolated, len(names))
            expected = {
                f"{proof_root}{index}": missing[name] for index, name in enumerate(names)
            }
            if (
                self._direct_ref_inventory(
                    isolated, proof_root, env_overrides=object_env
                )
                != expected
            ):
                raise Refusal(
                    "Git fetched a different ref inventory than the remote advertised"
                )
            lazy_off = {**object_env, "GIT_NO_LAZY_FETCH": "1"}
            if head not in self._present_commits(isolated, {head}, lazy_off):
                return []
            result = self._run(
                isolated,
                ["for-each-ref", "--format=%(refname)", "--contains", head, proof_root],
                env_overrides=lazy_off,
            )
        containing: list[str] = []
        for line in result.stdout.splitlines():
            if not line:
                continue
            suffix = line.removeprefix(proof_root)
            if suffix == line or not suffix.isdigit() or int(suffix) >= len(names):
                raise Refusal(f"Git returned an unexpected containment ref: {line}")
            containing.append(names[int(suffix)])
        return containing

    def ref_exists(self, checkout: Path, ref: str) -> bool:
        _validate_full_ref(ref, "remote ref")
        result = self._run(
            checkout, ["show-ref", "--verify", "--quiet", ref], check=False
        )
        if result.returncode not in (0, 1):
            raise Refusal(
                f"cannot determine whether ref {ref} exists" + _git_failure_detail(result)
            )
        return result.returncode == 0

    def commit_paths(self, checkout: Path, commit: str) -> tuple[str, ...]:
        if not SHA_RE.fullmatch(commit):
            raise Refusal(f"cannot inspect paths for invalid commit {commit!r}")
        result = self._run(
            checkout,
            [
                "diff-tree",
                "--root",
                "--no-commit-id",
                "--name-only",
                "-r",
                "-m",
                "-z",
                commit,
            ],
        )
        return tuple(dict.fromkeys(path for path in result.stdout.split("\x00") if path))

    def is_ancestor(self, checkout: Path, ancestor: str, descendant: str) -> bool:
        self.verify_ref(checkout, descendant, "landed ref")
        result = self._run(
            checkout,
            ["merge-base", "--is-ancestor", ancestor, descendant],
            check=False,
        )
        if result.returncode not in (0, 1):
            raise Refusal(
                f"cannot compare checkout HEAD {ancestor} with landed ref {descendant}"
                + _git_failure_detail(result)
            )
        return result.returncode == 0

    def remove_worktree(
        self, repository: Path, checkout: Path, *, force: bool = False
    ) -> None:
        # Do not run `git submodule deinit` before removal. Submodule
        # registration lives in the repository's common config, so deinitializing
        # one linked worktree makes populated submodules in every peer appear
        # uninitialized. `git worktree remove --force` removes only this
        # worktree and its worktree-private nested repository administration.
        args = ["worktree", "remove"]
        if force:
            args.append("--force")
        args.extend(("--", str(checkout)))
        if not _is_owned_image_root(checkout):
            self._run(repository, args)
            return
        # A flat image-backed checkout's root is the image's mount point, which
        # cannot be removed. Git deletes the working tree's contents, fails only
        # on that final rmdir, and still deletes the administrative directory.
        # Accept exactly that outcome; the image itself is destroyed with the
        # slot directory afterwards.
        result = self._run(repository, args, check=False)
        if result.returncode == 0:
            return
        leftover = [
            entry.name
            for entry in checkout.iterdir()
            if entry.name not in slotimage.REPRESENTATION_RESIDUE
        ]
        if leftover or checkout.absolute() in self.listed_worktrees(repository):
            detail = (result.stderr or result.stdout).strip().splitlines()
            raise Refusal(
                f"git worktree remove failed for image-backed checkout {checkout}: "
                f"{detail[-1] if detail else 'no output'}"
            )

    def remote_ref_sha(
        self,
        checkout: Path,
        remote: str,
        ref: str,
        authority: _RemoteAuthority,
    ) -> str | None:
        _validate_remote(remote)
        _validate_full_ref(ref, "remote salvage ref")
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            return self._remote_ref_sha_at_url(
                isolated, authority.url, ref, env_overrides=object_env
            )

    def _remote_ref_sha_at_url(
        self,
        isolated: Path,
        url: str,
        ref: str,
        *,
        env_overrides: Mapping[str, str],
    ) -> str | None:
        refs = self._ls_remote_inventory(
            isolated,
            url,
            refs=(ref,),
            env_overrides=env_overrides,
        )
        if not refs:
            return None
        if set(refs) != {ref}:
            raise Refusal(f"remote returned ambiguous content for salvage ref {ref}")
        return refs[ref]

    def _fetch_refs_into_isolated(
        self,
        isolated: Path,
        url: str,
        advertised: Mapping[str, str],
        *,
        destination: str,
        haves: Sequence[str] = (),
        env_overrides: Mapping[str, str],
    ) -> list[str]:
        """Fetch exactly the advertised refs into the temporary repository.

        Returns the advertised names in name order; the remote ref at
        position n is stored as ``destination``<n>, so no Git command after
        the fetch reads or prints the remote's own name, which may be any
        name Git accepts (see _validate_git_ref_name). The refspecs reach Git
        on standard input as the name's exact bytes. The refs exist only in
        that temporary repository and are discarded with it; no ref of the
        source repository, including refs/remotes/*, is read or written.
        Objects land in the source repository's object store, as with every
        isolated fetch. Each advertised tip already present there, and each
        commit in ``haves``, is first named by a temporary have-ref, so Git
        negotiates from those commits instead of downloading the whole
        history of a remote with many refs. The fetch is stopped, and
        refused, after _ABSENT_AGENT_REMOTE_FETCH_SECONDS.

        The fetch asks for complete history (_GIT_COMPLETE_HISTORY_DEPTH), so
        the remote is always asked, even when every object is already local,
        and is refused when the remote reports that it is shallow: a shallow
        remote can advertise a ref without holding that ref's older history,
        so its refs cannot show that it holds a commit.
        """

        names = sorted(advertised)
        if not names:
            return names
        tips = sorted(set(advertised.values()) | set(haves))
        present = self._run(
            isolated,
            ["cat-file", "--batch-check=%(objectname) %(objecttype)"],
            input_text="".join(f"{tip}\n" for tip in tips),
            env_overrides=env_overrides,
        )
        wanted = set(tips)
        commits: list[str] = []
        for line in present.stdout.splitlines():
            fields = line.split()
            if len(fields) == 2 and fields[1] == "commit" and fields[0] in wanted:
                commits.append(fields[0])
        if commits:
            self._run(
                isolated,
                ["update-ref", "--stdin"],
                input_text="".join(
                    f"update refs/wrkslots-have/{index} {tip}\n"
                    for index, tip in enumerate(commits)
                ),
                env_overrides=env_overrides,
            )
        arguments = [
            "fetch",
            f"--depth={_GIT_COMPLETE_HISTORY_DEPTH}",
            "--no-tags",
            "--no-write-fetch-head",
            "--no-auto-maintenance",
            "--force",
            "--no-recurse-submodules",
            "--stdin",
            "--",
            url,
        ]
        fetched = self._run_bytes(
            isolated,
            arguments,
            input_bytes=b"".join(
                b"+" + os.fsencode(name) + f":{destination}{index}\n".encode("ascii")
                for index, name in enumerate(names)
            ),
            env_overrides=env_overrides,
            timeout_seconds=_ABSENT_AGENT_REMOTE_FETCH_SECONDS,
            timeout_refusal=(
                f"Git did not fetch {len(names)} remote ref(s) into a temporary "
                f"repository within {_ABSENT_AGENT_REMOTE_FETCH_SECONDS:g} seconds; "
                "the fetch was stopped and no ref of the source repository was read "
                "or written. remedy: rerun when the remote answers faster"
            ),
        )
        if fetched.returncode != 0:
            raise Refusal(
                f"Git could not fetch {len(names)} remote ref(s) into a temporary "
                f"repository{_git_bytes_failure_detail(fetched)}. No ref of the source "
                "repository was read or written. remedy: rerun when the remote "
                "answers"
            )
        self._refuse_shallow_fetch(isolated, len(names))
        expected = {
            f"{destination}{index}": advertised[name] for index, name in enumerate(names)
        }
        if (
            self._direct_ref_inventory(isolated, destination, env_overrides=env_overrides)
            != expected
        ):
            raise Refusal(
                "Git fetched a different ref inventory than the remote advertised"
            )
        return names

    @staticmethod
    def _refuse_shallow_fetch(isolated: Path, count: int) -> None:
        shallow = isolated / "shallow"
        if shallow.exists() or shallow.is_symlink():
            raise Refusal(
                "the remote is a shallow repository: it reported history boundaries "
                f"below the {count} ref(s) fetched, so it may lack commits "
                "those refs descend from and cannot show that it holds one. No ref of "
                "the source repository was read or written. remedy: give that remote "
                "complete history, for example with git fetch --unshallow there, then "
                "rerun"
            )

    def remote_refs_containing_commit(
        self,
        checkout: Path,
        remote: str,
        commit: str,
        authority: _RemoteAuthority,
    ) -> dict[str, str]:
        """Return each ref the remote advertises that contains ``commit``.

        The result maps the remote's own ref name to the object it advertised;
        an annotated tag's object is the tag, which contains a commit when the
        commit it tags does. Branches, rescue refs, and tags
        (_ABSENT_AGENT_PREFERRED_REF_PREFIXES) are searched first; the
        remote's other refs are fetched and searched only when none of those
        contains the commit. Every ref is read fresh from the remote and
        fetched only into a temporary repository, under
        _ABSENT_AGENT_FETCHED_REF_ROOT; see _fetch_refs_into_isolated, which
        also refuses a shallow remote. The listing is stopped, and refused,
        after _ABSENT_AGENT_REMOTE_LIST_SECONDS. The caller confirms the ref
        it chooses with remote_ref_contains_commit.
        """

        _validate_remote(remote)
        if not SHA_RE.fullmatch(commit):
            raise Refusal(f"cannot search the remote for invalid commit {commit!r}")
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            advertised = self._ls_remote_any_refs(
                isolated, authority.url, env_overrides=object_env
            )
            preferred = {
                ref: tip
                for ref, tip in advertised.items()
                if ref.startswith(_ABSENT_AGENT_PREFERRED_REF_PREFIXES)
            }
            others = {
                ref: tip for ref, tip in advertised.items() if ref not in preferred
            }
            containing: dict[str, str] = {}
            for tier, candidates in (("preferred", preferred), ("other", others)):
                if containing or not candidates:
                    continue
                destination = f"{_ABSENT_AGENT_FETCHED_REF_ROOT}{tier}/"
                names = self._fetch_refs_into_isolated(
                    isolated,
                    authority.url,
                    candidates,
                    destination=destination,
                    haves=(commit,),
                    env_overrides=object_env,
                )
                result = self._run(
                    isolated,
                    [
                        "for-each-ref",
                        "--format=%(refname)%00%(objectname)",
                        "--contains",
                        commit,
                        destination,
                    ],
                    env_overrides=object_env,
                )
                for line in result.stdout.splitlines():
                    fields = line.split("\0")
                    position = fields[0].removeprefix(destination)
                    if (
                        len(fields) != 2
                        or not fields[0].startswith(destination)
                        or not position.isdigit()
                        or position != str(int(position))
                        or int(position) >= len(names)
                        or candidates[names[int(position)]] != fields[1]
                    ):
                        raise Refusal(
                            "Git returned a containing ref the remote did not advertise"
                        )
                    containing[names[int(position)]] = fields[1]
        return containing

    def remote_ref_contains_commit(
        self,
        checkout: Path,
        remote: str,
        ref: str,
        commit: str,
        authority: _RemoteAuthority,
    ) -> str | None:
        """Return ``ref``'s fresh tip when it exists and contains ``commit``.

        The ref is fetched only into a temporary repository and the answer is
        `git merge-base --is-ancestor` there. None means the remote no longer
        has the ref or its tip no longer contains the commit. Listing and
        fetching are bounded, and a shallow remote is refused, as in
        remote_refs_containing_commit. That fetch also leaves the commit in
        the source object store, which a resumed recovery needs when the
        commit was pruned there. A tip that contains the commit is then
        confirmed by _assert_remote_sends_history, which does not use the
        source object store at all.
        """

        _validate_remote(remote)
        _validate_git_ref_name(ref, "remote containing ref")
        shown = _display_ref(ref)
        if not SHA_RE.fullmatch(commit):
            raise Refusal(f"cannot compare invalid commit {commit!r} with {shown}")
        destination = f"{_ABSENT_AGENT_FETCHED_REF_ROOT}checked/"
        fetched = f"{destination}0"
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            tip = self._ls_remote_any_refs(
                isolated, authority.url, refs=(ref,), env_overrides=object_env
            ).get(ref)
            if tip is None:
                return None
            self._fetch_refs_into_isolated(
                isolated,
                authority.url,
                {ref: tip},
                destination=destination,
                haves=(commit,),
                env_overrides=object_env,
            )
            result = self._run(
                isolated,
                ["merge-base", "--is-ancestor", commit, fetched],
                check=False,
                env_overrides=object_env,
            )
        if result.returncode not in (0, 1):
            raise Refusal(
                f"cannot compare commit {commit} with remote ref {shown}"
                + _git_failure_detail(result)
            )
        if result.returncode != 0:
            return None
        self._assert_remote_sends_history(checkout, remote, ref, tip, commit, authority)
        return tip

    def _assert_remote_sends_history(
        self,
        checkout: Path,
        remote: str,
        ref: str,
        tip: str,
        commit: str,
        authority: _RemoteAuthority,
    ) -> None:
        """Refuse unless the remote itself sends ``commit`` as an ancestor of ``ref``.

        A fetch into the source object store stops at history the source
        already holds, so a remote whose own grafts or replacement refs cut
        ``ref``'s history short can appear to contain a commit it lacks. Here
        ``ref`` is fetched alone, commits only (--filter=tree:0, when the
        remote supports filtering), into a temporary repository whose object
        store starts empty and has no alternates, so every commit Git then
        walks was sent by the remote. A filtered fetch needs a named remote,
        which Git records as a promisor for the trees it did not send (a
        remote given only as a local path name cannot be recorded, and the
        fetch then fails its connectivity check), so the fetch alone runs with
        the URL as remote ``proof`` in that repository's config. Restoring the
        config before anything else runs there, and GIT_NO_LAZY_FETCH, mean a
        missing commit is an error rather than a further download. The fetch
        is stopped, and refused, after _ABSENT_AGENT_REMOTE_FETCH_SECONDS.
        """

        proof = "refs/wrkslots-proof/0"
        shown = _display_ref(ref)
        proof_config = (
            _NETWORK_CONFIG
            + b'[remote "proof"]\n\turl = '
            + _git_config_quoted(authority.url, f"remote {remote!r} URL")
            + b"\n"
        )
        with self._isolated_remote(checkout, remote, authority, own_objects=True) as (
            isolated,
            object_env,
        ):
            (isolated / "config").write_bytes(proof_config)
            # Bytes, because Git's diagnostic may quote the remote's ref name,
            # which need not be UTF-8.
            fetched = self._run_bytes(
                isolated,
                [
                    "fetch",
                    "--filter=tree:0",
                    "--no-tags",
                    "--no-write-fetch-head",
                    "--no-auto-maintenance",
                    "--force",
                    "--no-recurse-submodules",
                    "--",
                    "proof",
                    f"+{ref}:{proof}",
                ],
                env_overrides={
                    **object_env,
                    _NETWORK_CONFIG_SHA256_ENV: hashlib.sha256(proof_config).hexdigest(),
                },
                timeout_seconds=_ABSENT_AGENT_REMOTE_FETCH_SECONDS,
                timeout_refusal=(
                    f"Git did not fetch the commits of remote ref {shown} into an empty "
                    f"repository within {_ABSENT_AGENT_REMOTE_FETCH_SECONDS:g} seconds; "
                    "the fetch was stopped and no ref of the source repository was read "
                    "or written. remedy: rerun when the remote answers faster"
                ),
            )
            (isolated / "config").write_bytes(_NETWORK_CONFIG)
            if fetched.returncode != 0:
                # Without filtering, Git checks that the fetched history is
                # complete, so a remote that lacks part of it fails here.
                raise Refusal(
                    f"Git could not fetch remote ref {shown} alone into an empty object "
                    f"store{_git_bytes_failure_detail(fetched)}; the remote may lack commits "
                    f"in that ref's history, so it does not show that it holds commit "
                    f"{commit}. No ref of the source repository was read or written. "
                    "remedy: rerun; if this persists, push the commit to a branch on "
                    "that remote, then rerun"
                )
            self._refuse_shallow_fetch(isolated, 1)
            if self._direct_ref_inventory(
                isolated, "refs/wrkslots-proof/", env_overrides=object_env
            ) != {proof: tip}:
                raise Refusal(
                    "Git fetched a different ref inventory than the remote advertised"
                )
            result = self._run(
                isolated,
                ["merge-base", "--is-ancestor", commit, proof],
                check=False,
                env_overrides={**object_env, "GIT_NO_LAZY_FETCH": "1"},
            )
        if result.returncode != 0:
            raise Refusal(
                f"remote ref {shown} at {tip} contains commit {commit} only through "
                "commits the remote did not send when that ref was fetched alone into "
                "an empty object store; the remote may hide them with grafts or "
                "replacement refs, or lack them (git merge-base --is-ancestor"
                f"{_git_failure_detail(result)}). No ref of the source repository was "
                "read or written. remedy: push the commit to a branch on that remote, "
                "then rerun"
            )

    def push_salvage(
        self,
        checkout: Path,
        remote: str,
        commit: str,
        ref: str,
        authority: _RemoteAuthority,
    ) -> None:
        _validate_remote(remote)
        _validate_full_ref(ref, "remote salvage ref")
        with self._isolated_remote(checkout, remote, authority) as (
            isolated,
            object_env,
        ):
            self._push_salvage_ref(isolated, object_env, authority.url, commit, ref)

    def _push_salvage_ref(
        self,
        isolated: Path,
        object_env: Mapping[str, str],
        url: str,
        commit: str,
        ref: str,
    ) -> None:
        """Create ``ref`` at ``commit`` on ``url`` from an isolated repository and read it back.

        An existing ``ref`` naming ``commit`` is accepted as already pushed;
        one naming anything else refuses.
        """

        _validate_full_ref(ref, "remote salvage ref")
        existing = self._remote_ref_sha_at_url(
            isolated, url, ref, env_overrides=object_env
        )
        if existing is not None:
            if existing != commit:
                raise Refusal(
                    f"remote salvage ref {ref} already names {existing}, not {commit}; "
                    "preserve the checkout and choose a different recorded destination"
                )
            return
        self._run(
            isolated,
            [
                "push",
                "--porcelain",
                f"--force-with-lease={ref}:",
                "--",
                url,
                f"{commit}:{ref}",
            ],
            env_overrides=object_env,
        )
        observed = self._remote_ref_sha_at_url(
            isolated, url, ref, env_overrides=object_env
        )
        if observed != commit:
            raise Refusal(
                f"salvage push did not leave {ref} at {commit}; remote reports "
                f"{observed or 'no ref'}. Preserve the checkout and retry"
            )

    def delete_branch_at(self, repository: Path, branch: str, expected_head: str) -> None:
        if not self.branch_exists(repository, branch):
            return
        actual = self.verify_ref(repository, f"refs/heads/{branch}", "created branch")
        if actual != expected_head:
            raise Refusal(
                f"created branch {branch} moved from {expected_head} to {actual}; "
                "preserve it instead of aborting provisioning"
            )
        self._run(repository, ["branch", "-D", "--", branch])

    def repair_worktree(self, repository: Path, checkout: Path) -> None:
        self._run(repository, ["worktree", "repair", str(checkout)])
        if checkout.absolute() not in self.listed_worktrees(repository):
            raise Refusal(f"Git did not repair worktree registration for {checkout}")

    def repair_nested_repository(self, checkout: Path) -> None:
        git_file = checkout / ".git"
        if git_file.is_symlink() or not git_file.is_file():
            raise Refusal(f"nested repository has no safe .git file: {git_file}")
        try:
            value = git_file.read_text(encoding="utf-8").strip()
        except (OSError, UnicodeError) as exc:
            raise Refusal(f"cannot read nested repository identity {git_file}: {exc}") from exc
        prefix = "gitdir: "
        if not value.startswith(prefix) or "\n" in value:
            raise Refusal(f"nested repository has an invalid .git file: {git_file}")
        raw = Path(value.removeprefix(prefix))
        admin = raw if raw.is_absolute() else checkout / raw
        try:
            admin = admin.resolve(strict=True)
        except OSError as exc:
            raise Refusal(f"nested repository Git directory is unavailable: {admin}: {exc}") from exc
        if admin.is_symlink() or not admin.is_dir():
            raise Refusal(f"nested repository Git directory is unsafe: {admin}")
        environment = {
            key: value
            for key, value in os.environ.items()
            if not key.startswith("GIT_")
        }
        environment.update(
            {
                "LC_ALL": "C",
                "GIT_CONFIG_NOSYSTEM": "1",
                "GIT_CONFIG_GLOBAL": "/dev/null",
                "GIT_CONFIG_SYSTEM": "/dev/null",
                "GIT_NO_REPLACE_OBJECTS": "1",
            }
        )
        repair_command = [
            "git",
            "--no-replace-objects",
            "-c",
            "core.useReplaceRefs=false",
            f"--git-dir={admin}",
            f"--work-tree={checkout}",
            "config",
            "core.worktree",
            str(checkout),
        ]
        what = f"git config core.worktree for {checkout}"
        seconds = _item_seconds_left(what)
        try:
            if seconds is None:
                completed = subprocess.run(
                    repair_command,
                    text=True,
                    capture_output=True,
                    check=False,
                    env=environment,
                )
            else:
                completed = _run_within_item_budget(
                    repair_command, seconds=seconds, what=what, env=environment
                )
        except OSError as exc:
            raise Refusal(f"cannot execute Git while repairing {checkout}: {exc}") from exc
        if completed.returncode != 0:
            detail = (completed.stderr or completed.stdout).strip()
            raise Refusal(
                f"Git refused nested repository repair for {checkout}"
                + (f": {detail}" if detail else "")
            )
        if self.repository_root(checkout) != checkout.absolute():
            raise Refusal(f"Git did not repair nested repository worktree {checkout}")


class _AuditGitVcs(_GitVcs):
    """One consistent set of reusable Git observations for an audit sweep."""

    def __init__(self) -> None:
        self._common_directories: dict[Path, Path] = {}
        self._repository_roots: dict[Path, Path] = {}
        self._worktree_lists: dict[Path, frozenset[Path]] = {}
        self._verified_worktrees: dict[tuple[Path, Path], str] = {}
        self._ordinary_histories: set[Path] = set()
        self._tracked_cache_paths: dict[
            tuple[Path, tuple[str, ...]], tuple[str, ...]
        ] = {}
        self._submodule_paths: dict[Path, tuple[str, ...]] = {}

    def common_directory(self, repository: Path) -> Path:
        key = repository.absolute()
        if key not in self._common_directories:
            self._common_directories[key] = super().common_directory(repository)
        return self._common_directories[key]

    def repository_root(self, repository: Path) -> Path:
        key = repository.absolute()
        if key not in self._repository_roots:
            self._repository_roots[key] = super().repository_root(repository)
        return self._repository_roots[key]

    def listed_worktrees(self, repository: Path) -> set[Path]:
        common = self.common_directory(repository)
        if common not in self._worktree_lists:
            self._worktree_lists[common] = frozenset(
                super().listed_worktrees(repository)
            )
        return set(self._worktree_lists[common])

    def verify_existing_worktree(self, repository: Path, checkout: Path) -> str:
        key = (repository.absolute(), checkout.absolute())
        if key not in self._verified_worktrees:
            self._verified_worktrees[key] = super().verify_existing_worktree(
                repository, checkout
            )
        return self._verified_worktrees[key]

    def assert_ordinary_history(
        self, checkout: Path, *, allow_shallow: bool = False
    ) -> Path | None:
        if allow_shallow:
            return super().assert_ordinary_history(checkout, allow_shallow=True)
        common = self.common_directory(checkout)
        if common not in self._ordinary_histories:
            super().assert_ordinary_history(checkout)
            self._ordinary_histories.add(common)
        return None

    def tracked_cache_paths(
        self, checkout: Path, cache_globs: Sequence[str]
    ) -> tuple[str, ...]:
        key = (checkout.absolute(), tuple(cache_globs))
        if key not in self._tracked_cache_paths:
            self._tracked_cache_paths[key] = super().tracked_cache_paths(
                checkout, cache_globs
            )
        return self._tracked_cache_paths[key]

    def submodule_paths(self, checkout: Path) -> tuple[str, ...]:
        key = checkout.absolute()
        if key not in self._submodule_paths:
            self._submodule_paths[key] = super().submodule_paths(checkout)
        return self._submodule_paths[key]


def _resolved_repository_path(
    config: Config,
    stored: str,
    unresolved: Path,
    allowed_root: Path,
    *,
    allow_managed: bool = False,
) -> tuple[str, Path]:
    _ensure_no_symlink_components(allowed_root, unresolved, "repository")
    try:
        absolute = unresolved.resolve(strict=True)
    except OSError as exc:
        raise Refusal(
            f"source repository {stored!r} does not exist or cannot be resolved: "
            f"{unresolved}",
            remedy="pass --repo NAME=PATH with an existing Git worktree path",
        ) from exc
    if not absolute.is_dir():
        raise Refusal(f"repository does not exist or is unsafe: {absolute}")
    if not allow_managed and _path_is_within(absolute, _managed_worktrees_root(config)):
        raise Refusal(
            f"source repository must be outside the managed worktrees directory: {absolute}"
        )
    return stored, absolute


def _names_sibling_repository(parts: tuple[str, ...]) -> bool:
    """Return whether relative components are ``../NAME`` or ``../NAME/PATH``."""

    return (
        len(parts) >= 2
        and parts[0] == ".."
        and all(part not in {".", ".."} for part in parts[1:])
    )


def _repository_path(
    config: Config, raw: str, *, allow_managed: bool = False
) -> tuple[str, Path]:
    candidate = Path(raw)
    if candidate.is_absolute():
        raise Refusal(
            f"repository path must be relative to {config.root}: {raw!r}; "
            "use a path inside the project root or ../NAME[/PATH] components inside one "
            "direct sibling"
        )
    parts = candidate.parts
    is_sibling = _names_sibling_repository(parts)
    if ".." in parts and not is_sibling:
        raise Refusal(
            f"repository path must stay inside {config.root} or one direct sibling, "
            f"with path components '../NAME' or '../NAME/PATH'; other parent traversal is "
            f"refused: {raw!r}"
        )
    normalized = Path(os.path.normpath(str(candidate)))
    if not normalized.parts:
        normalized = Path(".")
    if is_sibling:
        stored = normalized.as_posix()
        if config.root.parent / parts[1] == config.root:
            raise Refusal(
                f"repository path {raw!r} aliases the project root; use a path inside it "
                "instead"
            )
        unresolved = config.root.parent.joinpath(*parts[1:])
        allowed_root = config.root.parent
    else:
        stored = "." if normalized == Path(".") else normalized.as_posix()
        unresolved = config.root / normalized
        allowed_root = config.root
    return _resolved_repository_path(
        config, stored, unresolved, allowed_root, allow_managed=allow_managed
    )


def _stored_repository_reference(
    config: Config, raw: str
) -> tuple[str, Path, Path]:
    """Validate a stored repository identity without requiring it to exist."""

    candidate = Path(raw)
    if candidate.is_absolute():
        if raw != os.path.normpath(raw):
            raise Refusal(
                f"stored absolute repository path is not canonical: {raw!r}"
            )
        if (
            candidate in {config.root, config.root.parent}
            or not candidate.name
            or candidate.parent != config.root.parent
        ):
            raise Refusal(
                "stored absolute repository path must name one direct sibling of the project "
                f"root, not the project root or another external path: {raw!r}"
            )
        stored = (Path("..") / candidate.name).as_posix()
        unresolved = candidate
        allowed_root = config.root.parent
    else:
        parts = candidate.parts
        sibling = _names_sibling_repository(parts)
        if ".." in parts and not sibling:
            raise Refusal(
                f"stored repository path must stay inside {config.root} or one direct "
                f"sibling, with path components '../NAME' or '../NAME/PATH': {raw!r}"
            )
        normalized = Path(os.path.normpath(str(candidate)))
        if sibling:
            stored = normalized.as_posix()
            if config.root.parent / parts[1] == config.root:
                raise Refusal(
                    f"stored repository path {raw!r} aliases the project root; use a path "
                    "inside it instead"
                )
            unresolved = config.root.parent.joinpath(*parts[1:])
            allowed_root = config.root.parent
        else:
            stored = "." if normalized == Path(".") else normalized.as_posix()
            unresolved = config.root / normalized
            allowed_root = config.root
    _ensure_no_symlink_components(allowed_root, unresolved, "repository")
    if _path_is_within(unresolved, _managed_worktrees_root(config)):
        raise Refusal(
            f"source repository must be outside the managed worktrees directory: {unresolved}"
        )
    return stored, unresolved, allowed_root


def _stored_repository_path(config: Config, raw: str) -> tuple[str, Path]:
    stored, unresolved, allowed_root = _stored_repository_reference(config, raw)
    return _resolved_repository_path(
        config, stored, unresolved, allowed_root
    )


def _managed_worktrees_root(config: Config) -> Path:
    return config.worktrees.parent if config.worktrees.name == "slots" else config.worktrees


def _validate_slots_directory(config: Config) -> Path:
    return _managed_worktrees_root(config) / "validate"


def _slot_roots(config: Config) -> dict[str, Path]:
    return {
        "agent": config.worktrees,
        "validate": _validate_slots_directory(config),
    }


def _slot_directory(config: Config, slot: str, slot_type: str = "agent") -> Path:
    _validate_name(slot, "slot")
    if slot_type not in SLOT_TYPES:
        raise Refusal(f"slot type must be one of {', '.join(SLOT_TYPES)}")
    return _slot_roots(config)[slot_type] / slot


def _checkout_path(
    config: Config, slot: str, name: str, slot_type: str = "agent"
) -> tuple[str, Path]:
    return _checkout_path_for_layout(
        config, slot, name, slot_type, config.layout
    )


def _checkout_path_for_layout(
    config: Config,
    slot: str,
    name: str,
    slot_type: str,
    layout: str,
) -> tuple[str, Path]:
    _validate_name(slot, "slot")
    _validate_name(name, "checkout name")
    _validate_layout(layout)
    slot_path = _slot_directory(config, slot, slot_type)
    destination = slot_path if layout == "flat" else slot_path / name
    _ensure_no_symlink_components(config.root, destination, "checkout")
    relative = destination.relative_to(config.root).as_posix()
    return relative, destination


def _record_layout(config: Config, record: ActiveRecord) -> str:
    return config.layout if record.layout is None else record.layout


def _stored_path(config: Config, raw: str, label: str) -> Path:
    relative, absolute = _relative_inside(config.root, raw, label)
    del relative
    return absolute


def _stored_path_reference(config: Config, raw: str, label: str) -> Path:
    _relative, absolute = _relative_inside_reference(config.root, raw, label)
    return absolute


def _boot_id(proc_root: Path) -> str:
    try:
        value = (proc_root / "sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    except (OSError, UnicodeError) as exc:
        raise Refusal(f"cannot read the machine boot id: {exc}") from exc
    if not value:
        raise Refusal("machine boot id is empty")
    return value


def _host_id() -> str:
    candidates = (Path("/etc/machine-id"), Path("/var/lib/dbus/machine-id"))
    failures: list[str] = []
    for path in candidates:
        try:
            value = path.read_text(encoding="ascii").strip()
        except FileNotFoundError:
            continue
        except (OSError, UnicodeError) as exc:
            failures.append(f"{path}: {exc}")
            continue
        if value:
            return value
        failures.append(f"{path}: empty")
    detail = f" ({'; '.join(failures)})" if failures else ""
    raise Refusal(f"cannot establish the stable machine identity{detail}")


# The machine's own PID 1 and PID 2, recognised by cgroup rather than by number.
#
# ⚠️ THE NUMBER ALONE IS THE WRONG TEST, and this was measured rather than
# reasoned about: a first version of this guard refused PID 1 and 2 outright
# and broke the process-and-git stress suite, which runs its whole harness
# under `unshare --pid --fork --mount-proc` where the runner legitimately IS
# PID 1. Inside such a namespace PID 1 is an ordinary process sitting in an
# ordinary session scope, its identity is coherent with every other identity
# recorded in that namespace, and refusing it would forbid a supported way to
# run. So the guard asks what the process IS, not what it is numbered.
#
# Measured on one host: the machine's init is PID 1 in "/init.scope" with 131
# start ticks; the kernel thread daemon is PID 2 in "/". Inside the namespace
# above, PID 1 reports the caller's own session scope instead -- so the two
# cases are distinguishable, and only the first is refused.
#
# ⚠️ THIS IS A WRITE-TIME GUARD BECAUSE THE READ-TIME CHECKS ARE CORRECT AND
# CANNOT HELP. Liveness compares the recorded generation against the live one.
# If the recorded generation IS the machine's init, that comparison answers
# "alive" for as long as the machine is up, so the slot can never be reclaimed
# and nothing downstream can tell it from a real owner. 17 rows of a 252-slot
# registry were in exactly that state.
#
# A related population is NOT refused here, deliberately: 2 rows record PID 1
# with a real agent's start ticks and sandbox scope, which is a process that
# read /proc/1 from inside its own PID namespace and faithfully recorded
# itself. Those are namespace-local rather than wrong, and when compared from
# the host they resolve to "dead" rather than sticking -- so they are
# decidable, and refusing them is not this guard's job.
#
# Where the signature does not hold -- an init outside "/init.scope" -- this
# degrades to the previous behaviour of accepting the identity, never to a
# false refusal.
_MACHINE_LEVEL_PROCESSES = {
    1: ("the machine's init process", "/init.scope"),
    2: ("the kernel thread daemon", "/"),
}


def _read_process_identity(pid: int, *, proc_root: Path = Path("/proc")) -> ProcessIdentity:
    if pid <= 0:
        raise Refusal("owner PID must be positive")
    pid_dir = proc_root / str(pid)
    process_stat = _read_process_stat(pid_dir)
    if process_stat is None:
        raise Refusal(f"owner PID {pid} is not live")
    cgroup_path = _read_process_cgroup(pid_dir)
    machine_level = _MACHINE_LEVEL_PROCESSES.get(pid)
    if machine_level is not None and cgroup_path == machine_level[1]:
        raise Refusal(
            f"PID {pid} is {machine_level[0]}, which can never own, coordinate or act "
            "on a slot; recording it would store an identity that stays live until the "
            "machine reboots, so the slot could never be reclaimed and no later check "
            "could tell it from a real owner. remedy: pass the PID of the real process "
            "-- if the caller is PID 1 inside its own PID namespace this refusal does "
            "not apply to it, because such a process is not this machine's init"
        )
    return ProcessIdentity(
        pid=pid,
        start_ticks=process_stat.start_ticks,
        boot_id=_boot_id(proc_root),
        host_id=_host_id(),
        cgroup_path=cgroup_path,
    )


def _first_seen_names(names: list[str]) -> list[str]:
    """The distinct names, in first-seen order.

    Module scope rather than a closure so a test can reach it. The audit's
    published lists must not repeat a name: `rows` is built from four separate
    append sites, and the downstream contract refuses the entire census when
    a published list contains duplicates.
    """
    seen: set[str] = set()
    ordered: list[str] = []
    for name in names:
        if name in seen:
            continue
        seen.add(name)
        ordered.append(name)
    return ordered


def _owner_record_is_absent(record: ActiveRecord) -> bool:
    """Whether this row records no usable owner at all.

    ⚠️ A DEGENERATE OWNER IS AN ABSENT OWNER, NOT A REASON TO PRESERVE FOREVER.
    The machine's init can never have owned a slot, so a row naming it records
    an error rather than a fact. Treating that error as evidence produced a
    refusal that demanded proof of a historical owner while the row itself was
    the reason no such proof can exist.

    ⚠️ AND THAT PROOF DOES NOT EXIST, measured rather than assumed: across an
    entire 6,841-entry append-only event log, for every row in this state, a
    non-degenerate identity is NEVER recorded in an `owner` field, in any event,
    ever. The create journal itself recorded the machine's init for both `owner`
    and `coordinator_lease`, so the degeneracy was present at the instant of
    registration and no later observer saw the real process. A rule satisfiable
    only by data nobody wrote is not a rule, it is a permanent hold -- and it
    holds hardest on exactly the rows nothing can vouch for.

    ⚠️ KEYING REMOVAL ON A HISTORICAL AGENT IDENTITY IS THE ANTI-PATTERN ITSELF.
    Agents here die constantly, so a protocol that depends on one surviving into
    the future cannot hold. What protects work is not knowing who owned a slot;
    it is the guards that remain and are unchanged: an unread handoff, a live
    process using the checkout, and salvage before delete.
    """
    if record.owner is None:
        return True
    machine_level = _MACHINE_LEVEL_PROCESSES.get(record.owner.pid)
    return machine_level is not None and record.owner.cgroup_path == machine_level[1]


def _owner_cgroup_is_evidence(record: ActiveRecord | None) -> bool:
    """Whether a live process sharing the recorded owner cgroup says anything about this slot.

    A cgroup is a container, not an identity. When the recorded owner's exact
    process generation is PROVEN DEAD, a live process sitting in the same
    cgroup is by construction not that owner, so refusing on its presence
    reports cohabitation as ownership.

    ⚠️ MEASURED, on one host with 252 registered slots and 3,619 live
    processes: this comparison blocked 135 slots. Four had a live process in
    the recorded cgroup that actually touched the checkout -- and every one of
    those four is caught independently by the direct-use test, which looks at
    cwd, root, exe and open descriptors. The remaining 131 were vouched for by
    a process that touched nothing in them. Two coarse sandbox scopes supplied
    97 of the 135, one live process standing in for 50 slots and another for
    47, because such a scope outlives the agent that ran inside it.

    ⚠️ THIS DELIBERATELY RETIRES A GUARD, and the narrowing is the one already
    accepted elsewhere in this file rather than a new idea: the same "omit the
    recorded cgroup comparison once the exact generation is proven dead" rule
    was introduced for disposable checkouts and scoped out of ordinary agent
    slots at the time. The reasoning given then -- that unrelated live
    processes in a coarse shared cgroup must not strand a checkout
    indefinitely -- holds identically here; only the blast radius differed.
    What is NOT retired: the direct-use test, the handoff and hold guards, the
    registered-liveness authority, and the requirement that the recorded owner
    generation be proven dead in the first place. This function is reached
    only after that requirement is already satisfied.

    The residual risk, stated rather than dismissed: an orphaned child of the
    dead owner still working inside the slot through absolute paths while
    holding no descriptor would no longer be seen here. It would still have to
    evade the direct-use test to go unnoticed.
    """
    if record is None or record.owner is None:
        return False
    # ⚠️ A DEGENERATE RECORD'S CGROUP IS WORTHLESS FOR THE SAME REASON ITS PID
    # IS. A row naming the machine's init also names /init.scope, where a live
    # process always sits, so the comparison refuses forever on the strength of
    # the same error. This was the SECOND route blocking such rows, found only
    # because the wiring test still failed after the first was removed: the
    # generation gate and the cgroup gate read the same bad evidence and had to
    # be told about it separately.
    if _owner_record_is_absent(record):
        return False
    return _process_state(record.owner)[0] != "dead"


def _read_process_cgroup(pid_dir: Path) -> str:
    try:
        lines = (pid_dir / "cgroup").read_text(encoding="ascii").splitlines()
    except (OSError, UnicodeError) as exc:
        raise Refusal(f"cannot read process cgroup for PID {pid_dir.name}: {exc}") from exc
    paths = [line.split("::", 1)[1] for line in lines if "::" in line]
    if len(paths) != 1 or not paths[0].startswith("/"):
        raise Refusal(f"cannot establish one unified cgroup for PID {pid_dir.name}")
    return paths[0].rstrip("/") or "/"


@dataclasses.dataclass(frozen=True)
class _ProcStatFields:
    """The numeric tail of one Linux proc stat record; ``comm`` remains opaque."""

    pid: int
    state: str
    parent: int
    flags: int
    start_ticks: int


_PROC_STATES = frozenset(b"RSDZTWtXxKPI")


def _parse_proc_stat(raw: bytes) -> _ProcStatFields | None:
    """Parse fields needed by wrkslots without decoding the opaque ``comm`` bytes."""
    opening = raw.find(b" (")
    closing = raw.rfind(b") ")
    if opening <= 0 or closing < opening + 2:
        return None
    fields = raw[closing + 2 :].split()
    if len(fields) <= 19 or len(fields[0]) != 1 or fields[0][0] not in _PROC_STATES:
        return None
    try:
        process = int(raw[:opening])
        parent = int(fields[1])
        flags = int(fields[6])
        start_ticks = int(fields[19])
        state = fields[0].decode("ascii")
    except (UnicodeError, ValueError):
        return None
    if process <= 0 or parent < 0 or flags < 0 or start_ticks <= 0:
        return None
    return _ProcStatFields(process, state, parent, flags, start_ticks)


def _read_process_parent(
    pid: int, *, proc_root: Path = Path("/proc")
) -> int | None:
    try:
        raw = proc_root.joinpath(str(pid), "stat").read_bytes()
    except (FileNotFoundError, ProcessLookupError):
        return None
    except OSError as exc:
        raise Refusal(f"cannot read process ancestry for PID {pid}: {exc}") from exc
    parsed = _parse_proc_stat(raw)
    if parsed is None or parsed.pid != pid:
        raise Refusal(f"cannot parse process ancestry for PID {pid}")
    return parsed.parent if parsed.parent > 0 and parsed.parent != pid else None


def _assert_caller_process(identity: ProcessIdentity, label: str) -> None:
    current: int | None = os.getpid()
    seen: set[int] = set()
    for _ in range(256):
        if current is None or current in seen:
            break
        seen.add(current)
        try:
            candidate = _read_process_identity(current)
        except Refusal:
            candidate = None
        if candidate == identity:
            return
        current = _read_process_parent(current)
    raise Refusal(
        f"{label} PID {identity.pid} is not in the invoking process ancestry"
    )


def _capture_caller_process(pid: int, label: str) -> ProcessIdentity:
    identity = _read_process_identity(pid)
    _assert_caller_process(identity, label)
    return identity


def _pipe_write_holders(fd: int) -> tuple[ProcessIdentity, ...]:
    """Return exact same-UID processes holding a write end of this anonymous pipe."""
    try:
        descriptor = os.fstat(fd)
        target = os.readlink(f"/proc/self/fd/{fd}")
    except OSError as exc:
        raise Refusal(f"cannot inspect host-context removal proof FD {fd}: {exc}") from exc
    if not stat.S_ISFIFO(descriptor.st_mode) or re.fullmatch(r"pipe:\[[0-9]+\]", target) is None:
        raise Refusal("host-context removal proof is not an anonymous pipe")
    holders: dict[int, ProcessIdentity] = {}
    try:
        process_directories = tuple(Path("/proc").iterdir())
    except OSError as exc:
        raise Refusal(f"cannot enumerate host processes for removal proof: {exc}") from exc
    for process_directory in process_directories:
        if not process_directory.name.isdigit():
            continue
        try:
            if process_directory.stat().st_uid != os.geteuid():
                continue
            descriptors = tuple((process_directory / "fd").iterdir())
        except OSError:
            continue
        for candidate_fd in descriptors:
            try:
                if os.readlink(candidate_fd) != target:
                    continue
                flags_line = next(
                    line
                    for line in (process_directory / "fdinfo" / candidate_fd.name)
                    .read_text(encoding="ascii")
                    .splitlines()
                    if line.startswith("flags:")
                )
                flags = int(flags_line.split()[1], 8)
            except (OSError, UnicodeError, StopIteration, ValueError):
                continue
            if flags & os.O_ACCMODE not in (os.O_WRONLY, os.O_RDWR):
                continue
            pid = int(process_directory.name)
            try:
                holders[pid] = _read_process_identity(pid)
            except Refusal:
                continue
    return tuple(holders[pid] for pid in sorted(holders))


def _capture_remove_handoff_writer(
    fd: int, coordinator: ProcessIdentity
) -> ProcessIdentity:
    for writer in _pipe_write_holders(fd):
        try:
            _assert_process_descends_from(writer, coordinator, "removal proof writer")
        except Refusal:
            continue
        return writer
    raise Refusal(
        "host-context removal proof has no live writer descended from the coordinator"
    )


def _capture_remove_processes(
    coordinator_pid: int,
) -> tuple[ProcessIdentity, ProcessIdentity, ProcessIdentity | None, int | None]:
    """Capture the durable actor and the process running removal."""
    runner_raw = os.environ.get("WRKSLOTS_REMOVE_RUNNER_PID")
    start_raw = os.environ.get("WRKSLOTS_REMOVE_COORDINATOR_START_TICKS")
    proof_fd_raw = os.environ.get("WRKSLOTS_REMOVE_PROOF_FD")
    if runner_raw is None and start_raw is None and proof_fd_raw is None:
        coordinator = _capture_caller_process(coordinator_pid, "coordinator")
        return coordinator, coordinator, None, None
    if runner_raw is None or start_raw is None or proof_fd_raw is None:
        raise Refusal(
            "host-context removal requires runner PID, coordinator generation, and proof FD"
        )
    try:
        runner_pid = int(runner_raw)
        expected_start_ticks = int(start_raw)
        proof_fd = int(proof_fd_raw)
    except ValueError as exc:
        raise Refusal(
            "host-context removal process identities must be decimal integers"
        ) from exc
    if runner_pid <= 0 or expected_start_ticks < 0 or proof_fd < 0:
        raise Refusal("host-context removal process identities are invalid")
    coordinator = _read_process_identity(coordinator_pid)
    if coordinator.start_ticks != expected_start_ticks:
        raise Refusal(
            f"coordinator PID {coordinator_pid} generation changed before removal"
        )
    runner = _capture_caller_process(runner_pid, "removal runner")
    writer = _capture_remove_handoff_writer(proof_fd, coordinator)
    return coordinator, runner, writer, proof_fd


def _assert_remove_processes(
    coordinator: ProcessIdentity,
    runner: ProcessIdentity,
    writer: ProcessIdentity | None,
    proof_fd: int | None,
) -> None:
    """Recheck both identities after the removal mutation lock is held."""
    _assert_caller_process(runner, "removal runner")
    try:
        current = _read_process_identity(coordinator.pid)
    except Refusal as exc:
        raise Refusal(
            f"coordinator PID {coordinator.pid} exited before the locked removal boundary"
        ) from exc
    if current != coordinator:
        raise Refusal(
            f"coordinator PID {coordinator.pid} generation changed before the locked "
            "removal boundary"
        )
    if writer is not None:
        if proof_fd is None or writer not in _pipe_write_holders(proof_fd):
            raise Refusal(
                "removal proof writer no longer holds the handoff pipe at the locked "
                "removal boundary"
            )
        _assert_process_descends_from(writer, coordinator, "removal proof writer")


@dataclasses.dataclass(frozen=True)
class _RecoveryProcesses:
    """Original recovery actor plus the authenticated invoking handoff."""

    coordinator: ProcessIdentity
    runner: ProcessIdentity
    writer: ProcessIdentity | None
    proof_fd: int | None

    @classmethod
    def capture(cls, coordinator_pid: int) -> _RecoveryProcesses:
        return cls(*_capture_remove_processes(coordinator_pid))

    def assert_current(self, coordinator: ProcessIdentity) -> None:
        if coordinator != self.coordinator:
            raise Refusal("recovery coordinator differs from captured process authority")
        if (
            (self.writer is None) != (self.proof_fd is None)
            or (self.writer is None and self.runner != self.coordinator)
            or (
                self.proof_fd is not None
                and (type(self.proof_fd) is not int or self.proof_fd < 0)
            )
        ):
            raise Refusal("recovery process authority has inconsistent handoff evidence")
        _assert_remove_processes(
            self.coordinator, self.runner, self.writer, self.proof_fd
        )


def _assert_recovery_processes(
    coordinator: ProcessIdentity,
    processes: _RecoveryProcesses | None,
    label: str = "coordinator",
) -> None:
    if processes is None:
        # Standalone callers retain their ordinary direct-ancestry contract.
        _assert_caller_process(coordinator, label)
    else:
        processes.assert_current(coordinator)


def _capture_registration_owner(pid: int) -> ProcessIdentity:
    """Capture an owner now; registration verifies its authority before publication."""
    return _read_process_identity(pid)


def _assert_process_descends_from(
    process: ProcessIdentity, ancestor: ProcessIdentity, label: str
) -> None:
    current: int | None = process.pid
    seen: set[int] = set()
    first = True
    for _ in range(256):
        if current is None or current in seen:
            break
        seen.add(current)
        try:
            candidate = _read_process_identity(current)
        except Refusal:
            candidate = None
        if first and candidate != process:
            raise Refusal(f"{label} PID {process.pid} generation changed")
        first = False
        if candidate == ancestor:
            return
        current = _read_process_parent(current)
    raise Refusal(
        f"{label} PID {process.pid} does not descend from coordinator PID "
        f"{ancestor.pid}"
    )


def _assert_registration_owner_authorized(
    owner: ProcessIdentity,
    coordinator: ProcessIdentity,
    slot_path: Path,
) -> None:
    try:
        _assert_caller_process(owner, "owner")
        return
    except Refusal as caller_refusal:
        _assert_process_descends_from(owner, coordinator, "owner")
        uses = _process_uses_slot(Path("/proc") / str(owner.pid), slot_path)
        if not any(item.startswith("cwd=") for item in uses):
            raise Refusal(
                f"owner PID {owner.pid} is outside the invoking process ancestry and "
                f"does not have its working directory inside slot {slot_path}"
            ) from caller_refusal


def _assert_create_owner_authorized(
    owner: ProcessIdentity | None, coordinator: ProcessIdentity
) -> None:
    """Permit self-binding or allocation by the invoking coordinator.

    A delegated agent may run beside its coordinator, for example in another
    terminal pane. Its own ancestry proves the owner it can bind. Creating an
    unbound slot or assigning another owner still requires the coordinator to
    invoke the command, and that other owner must descend from the coordinator.
    """
    if owner is not None:
        try:
            _assert_caller_process(owner, "owner")
            return
        except Refusal:
            pass
    _assert_caller_process(coordinator, "coordinator")
    if owner is not None:
        _assert_process_descends_from(owner, coordinator, "owner")


def _assert_create_processes(
    owner: ProcessIdentity | None, coordinator: ProcessIdentity, *, stage: str
) -> None:
    for label, identity in (("owner", owner), ("coordinator", coordinator)):
        if identity is None:
            continue
        try:
            confirmed = _read_process_identity(identity.pid)
        except Refusal as exc:
            raise Refusal(f"{label} process changed {stage}: {exc}") from exc
        if confirmed != identity:
            raise Refusal(f"{label} process generation changed {stage}")
    _assert_create_owner_authorized(owner, coordinator)


def _liveness_environment(config: Config, record: ActiveRecord) -> dict[str, str]:
    """Return the exact one-subject environment shared by both protocols."""

    return {
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin",
        "WRKSLOTS_PROJECT_ROOT": str(config.root),
        "WRKSLOTS_SLOT": record.slot,
        "WRKSLOTS_SLOT_TYPE": record.slot_type,
        "WRKSLOTS_AGENT": record.agent,
        "WRKSLOTS_TASK": record.task,
        "WRKSLOTS_MACHINE": record.machine,
        "WRKSLOTS_GENERATION": str(record.generation),
        "WRKSLOTS_OWNER_PID": "" if record.owner is None else str(record.owner.pid),
        "WRKSLOTS_OWNER_START_TICKS": (
            "" if record.owner is None else str(record.owner.start_ticks)
        ),
        "WRKSLOTS_OWNER_BOOT_ID": "" if record.owner is None else record.owner.boot_id,
        "WRKSLOTS_OWNER_CGROUP": "" if record.owner is None else record.owner.cgroup_path,
    }


def _liveness_subject(config: Config, record: ActiveRecord) -> dict[str, object]:
    binding: dict[str, object] = {
        "agent": record.agent,
        "environment": _liveness_environment(config, record),
    }
    digest = hashlib.sha256(
        json.dumps(
            binding, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("utf-8")
    ).hexdigest()
    return {"subject_id": digest, **binding}


def _liveness_batch_request(
    config: Config, records: Sequence[ActiveRecord]
) -> dict[str, object]:
    subjects = [_liveness_subject(config, record) for record in records]
    request_body: dict[str, object] = {
        "schema": _LIVENESS_BATCH_REQUEST_SCHEMA,
        "subjects": subjects,
    }
    request_sha256 = hashlib.sha256(
        json.dumps(
            request_body, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("utf-8")
    ).hexdigest()
    return {**request_body, "request_sha256": request_sha256}


def _parse_liveness_batch_response(
    response_text: str,
    request: Mapping[str, object],
) -> dict[str, tuple[str, str]]:
    if len(response_text.encode("utf-8")) > _LIVENESS_BATCH_BYTES_LIMIT:
        raise Refusal("batch liveness response exceeded its byte limit")
    try:
        response = _strict_json_object(
            response_text.encode("utf-8"), "batch liveness response"
        )
    except Refusal as exc:
        raise Refusal(f"batch liveness response is not JSON: {exc}") from exc
    _exact_keys(
        response,
        {"schema", "request_sha256", "results"},
        set(),
        "batch liveness response",
    )
    if response["schema"] != _LIVENESS_BATCH_RESPONSE_SCHEMA:
        raise Refusal("batch liveness response has an unsupported schema")
    if response["request_sha256"] != request.get("request_sha256"):
        raise Refusal("batch liveness response is bound to another request")
    requested: dict[str, str] = {}
    for index, value in enumerate(_as_list(request.get("subjects"), "batch subjects")):
        subject = _as_mapping(value, f"batch subjects[{index}]")
        subject_id = _as_str(subject.get("subject_id"), f"batch subjects[{index}].subject_id")
        agent = _as_str(subject.get("agent"), f"batch subjects[{index}].agent")
        if subject_id in requested:
            raise StateError("batch liveness request contains duplicate subject identities")
        requested[subject_id] = agent
    parsed: dict[str, tuple[str, str]] = {}
    for index, value in enumerate(_as_list(response["results"], "batch liveness results")):
        result = _as_mapping(value, f"batch liveness results[{index}]")
        _exact_keys(
            result,
            {"subject_id", "agent", "state", "detail"},
            set(),
            f"batch liveness results[{index}]",
        )
        subject_id = _as_str(
            result["subject_id"], f"batch liveness results[{index}].subject_id"
        )
        if subject_id in parsed:
            raise Refusal(f"batch liveness response duplicates subject {subject_id}")
        expected_agent = requested.get(subject_id)
        if expected_agent is None:
            raise Refusal(f"batch liveness response contains unknown subject {subject_id}")
        agent = _as_str(result["agent"], f"batch liveness results[{index}].agent")
        if agent != expected_agent:
            raise Refusal(
                f"batch liveness response misbinds subject {subject_id} to agent {agent!r}"
            )
        state = _as_str(result["state"], f"batch liveness results[{index}].state")
        if state not in {"dead", "alive", "unverifiable"}:
            raise Refusal(
                f"batch liveness response has invalid state {state!r} for {agent}"
            )
        detail = _as_str(result["detail"], f"batch liveness results[{index}].detail")
        if not detail or len(detail) > 4096 or detail != " ".join(detail.split()):
            raise Refusal(
                f"batch liveness response detail is absent or not one bounded line for {agent}"
            )
        parsed[subject_id] = state, detail
    missing = sorted(set(requested) - set(parsed))
    if missing:
        raise Refusal(
            f"batch liveness response omitted {len(missing)} requested subject(s): {missing[0]}"
        )
    return parsed


def _liveness_batch_diagnostic(value: str) -> str:
    """Bound one untrusted diagnostic before it is shared by every subject.

    Limit the input inspected as well as the UTF-8 output. Nonprinting text,
    including terminal controls and Unicode direction controls, becomes spaces.
    The final byte bound includes the truncation marker.
    """

    limit = 4096
    marker = b" [truncated]"
    excerpt = value[:limit]
    printable = "".join(char if char.isprintable() else " " for char in excerpt)
    encoded = " ".join(printable.split()).encode("utf-8")
    if len(value) > limit or len(encoded) > limit:
        return (
            encoded[:limit - len(marker)].decode("utf-8", errors="ignore").rstrip()
            + marker.decode("ascii")
        )
    return encoded.decode("utf-8") or "no detail"


def _registered_liveness_states(
    config: Config, records: Sequence[ActiveRecord]
) -> dict[tuple[str, str, int], tuple[str, str]]:
    """Read liveness once when a typed batch authority is configured.

    A broken batch is one broken observation, not permission to fall back to a
    different protocol whose answers might disagree. Every requested subject
    therefore becomes unverifiable together.
    """

    if not records:
        return {}
    if config.liveness_batch_command is None:
        return {
            (record.machine, record.slot, record.generation):
            _registered_liveness_state(config, record)
            for record in records
        }
    request = _liveness_batch_request(config, records)
    command = (
        [sys.executable, str(config.liveness_batch_command)]
        if config.liveness_batch_command.suffix == ".py"
        else [str(config.liveness_batch_command)]
    )
    common_env = {
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin",
        "WRKSLOTS_PROJECT_ROOT": str(config.root),
        "WRKSLOTS_MACHINE": config.machine,
        "WRKSLOTS_LIVENESS_BATCH_SCHEMA": _LIVENESS_BATCH_REQUEST_SCHEMA,
    }
    try:
        returncode, stdout_bytes, stderr_bytes = _run_bounded_read_only_command(
            command,
            timeout_seconds=_ABSENT_PROCESS_CENSUS_SECONDS,
            stdout_limit=_LIVENESS_BATCH_BYTES_LIMIT,
            stderr_limit=64 * 1024,
            env_overrides=common_env,
            input_data=json.dumps(
                request, sort_keys=True, separators=(",", ":")
            ).encode("utf-8"),
        )
        stdout = stdout_bytes.decode("utf-8")
        stderr = stderr_bytes.decode("utf-8")
        if returncode != 0:
            detail = _liveness_batch_diagnostic(stderr or stdout)
            raise Refusal(
                f"batch liveness command exited {returncode}: {detail}"
            )
        parsed = _parse_liveness_batch_response(stdout, request)
    except (OSError, UnicodeError, subprocess.TimeoutExpired, Refusal, StateError) as exc:
        detail = _liveness_batch_diagnostic(
            f"registered batch liveness authority is unverifiable: {exc}"
        )
        return {
            (record.machine, record.slot, record.generation):
            ("unverifiable", detail)
            for record in records
        }
    result: dict[tuple[str, str, int], tuple[str, str]] = {}
    subjects = _as_list(request["subjects"], "batch subjects")
    for record, value in zip(records, subjects, strict=True):
        subject = _as_mapping(value, "batch subject")
        subject_id = _as_str(subject["subject_id"], "batch subject.subject_id")
        result[(record.machine, record.slot, record.generation)] = parsed[subject_id]
    return result


def _bound_alive_verdict(stdout: str, stderr: str, agent: str) -> str | None:
    """Return the one output line that binds exit status 1 to this agent.

    Exit status 1 is also what an uncaught Python exception produces, so the
    status alone cannot mean alive. The command's whole output must be one
    non-empty line whose only ``agent=`` token names the requested agent and
    whose only ``rc=`` token is ``rc=1``. Anything else is not an answer.
    """

    lines = [line for line in (stdout + "\n" + stderr).splitlines() if line.strip()]
    if len(lines) != 1:
        return None
    tokens = lines[0].split()
    if [token for token in tokens if token.startswith("agent=")] != [f"agent={agent}"]:
        return None
    if [token for token in tokens if token.startswith("rc=")] != ["rc=1"]:
        return None
    return _liveness_batch_diagnostic(lines[0])


def _liveness_output_diagnostic(stdout: str, stderr: str) -> str:
    """Keep each stream's first and last lines; a traceback's cause is its last."""

    parts = []
    for name, text in (("stderr", stderr), ("stdout", stdout)):
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        if len(lines) == 1:
            parts.append(f"{name}: {lines[0][:1536]}")
        elif lines:
            # Bound each end separately so a long first line cannot hide the last.
            parts.append(
                f"{name} ({len(lines)} lines): {lines[0][:512]} ... {lines[-1][-1024:]}"
            )
    return _liveness_batch_diagnostic("; ".join(parts)) if parts else "no output"


def _registered_liveness_state(config: Config, record: ActiveRecord) -> tuple[str, str]:
    """Ask the registered liveness command about ``record``'s owner.

    Returns ``dead``, ``alive`` or ``unverifiable`` with a detail line.  Within a
    remove-agent-batch item the command receives at most the item's remaining
    budget and raises Refusal when that runs out.
    """

    env = _liveness_environment(config, record)
    what = "the registered liveness command"
    seconds = _item_seconds_left(what)
    try:
        command = (
            [sys.executable, str(config.liveness_command), record.agent]
            if config.liveness_command.suffix == ".py"
            else [str(config.liveness_command), record.agent]
        )
        if seconds is None:
            completed = subprocess.run(
                command,
                text=True,
                errors="replace",
                capture_output=True,
                check=False,
                env=env,
            )
        else:
            completed = _run_within_item_budget(
                command, seconds=seconds, what=what, env=env, errors="replace"
            )
    except OSError as exc:
        return "unverifiable", f"registered liveness command could not run: {exc}"
    detail = (completed.stderr or completed.stdout).strip().splitlines()
    first = detail[0] if detail else "no detail"
    if completed.returncode == 0:
        return "dead", first
    if completed.returncode == 1:
        verdict = _bound_alive_verdict(completed.stdout, completed.stderr, record.agent)
        if verdict is not None:
            return "alive", verdict
        return "unverifiable", (
            "registered liveness command exited 1 without a single output line "
            f"binding agent={record.agent} to rc=1: "
            + _liveness_output_diagnostic(completed.stdout, completed.stderr)
        )
    if completed.returncode == 2:
        return "unverifiable", first
    return "unverifiable", (
        f"registered liveness command returned unexpected rc {completed.returncode}: {first}"
    )


def _assert_registered_liveness(config: Config, record: ActiveRecord) -> None:
    state, detail = _registered_liveness_state(config, record)
    if state == "dead":
        return
    _refuse_registered_liveness(state, detail)


def _refuse_registered_liveness(state: str, detail: str) -> NoReturn:
    if state == "alive":
        raise Refusal(
            f"registered liveness authority reports owner alive: {detail}. state: "
            "REFUSED -- no checkout was salvaged or removed. remedy: let the owner "
            "finish or stop, then rerun remove after the time-to-live expires"
        )
    raise Refusal(
        f"registered liveness authority is unverifiable: {detail}. state: REFUSED -- "
        "no checkout was salvaged or removed; unknown ownership is not a free slot. "
        "remedy: refresh or repair the configured liveness source, then rerun remove"
    )


def _processes_around_unit_enumeration(
    before: Sequence[_AbsentProcessObservation],
) -> tuple[tuple[_AbsentProcessObservation, ...], tuple[Mapping[str, str], ...]]:
    """Enumerate user-systemd units, then reconcile ``before`` with a new table.

    ``before`` is a process table read before this call.  The user-systemd
    enumeration takes about 1.5 seconds on a busy host.  A run can start and
    finish inside that window and leave a child in its control group: the
    unit then reads inactive and unqueued, and ``before`` has no child.  The
    table read after the enumeration does, so the returned processes are that
    later table.  A process generation in both tables also keeps its earlier
    control group, so a child that left a run's control group meanwhile is
    still attributed to the run.  A generation only in ``before`` has exited
    and is dropped.  Both reads refuse rather than return a partial
    population.

    The later table is itself read one PID at a time, after its PID list.  A
    run that starts after that list leaves no process in it while the first
    enumeration still reads its unit inactive and unqueued.  The units are
    therefore enumerated again after the later table, and both enumerations
    are returned: a unit active or queued in either one is evidence of a
    run.  Control-group members that the later table missed are read
    separately by ``_retained_unit_cgroup_members``.
    """

    units = _user_systemd_snapshot()
    after = _absent_validate_process_snapshot()
    refreshed = _user_systemd_snapshot()
    current = set(after)
    live = {(process.pid, process.start_ticks) for process in after}
    moved = tuple(
        process
        for process in before
        if (process.pid, process.start_ticks) in live and process not in current
    )
    return (*after, *moved), (*refreshed, *units)


_CGROUP_ROOT = Path("/sys/fs/cgroup")
_RETAINED_CGROUP_DIRECTORY_LIMIT = 65536


def _user_manager_cgroup(root: Path) -> Path:
    """Return this user's systemd manager control group under ``root``.

    The manager's units, including validation runs, are its descendants.
    This process's own control group names the manager when it runs under
    it; otherwise the conventional ``user.slice`` location is used.
    """

    manager = f"user@{os.getuid()}.service"
    try:
        lines = Path("/proc/self/cgroup").read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        raise Refusal(f"this process's control group is unreadable: {exc}") from exc
    for line in lines:
        hierarchy, _controllers, path = line.split(":", 2)
        if hierarchy != "0":
            continue
        parts = Path(path).parts[1:]
        if manager in parts:
            return root.joinpath(*parts[: parts.index(manager) + 1])
    return root / "user.slice" / f"user-{os.getuid()}.slice" / manager


def _assert_whole_cgroup2_hierarchy(root: Path) -> None:
    """Refuse unless the mounts visible at and below ``root`` show the whole
    cgroup v2 tree.

    A cgroup v2 mount can show a subtree (its mount-table root is then that
    subtree's path), in which control groups outside it are missing rather
    than empty.  A visible mount below ``root`` (a file system over a
    control group, or a file bind-mounted over its ``cgroup.procs``)
    replaces what the hierarchy shows there, so a member list can read
    empty.  The caller has proved this process is in the initial cgroup
    namespace, where mount roots are paths from the hierarchy root.
    """

    entries = _read_self_mount_entries()
    lookup = _MountLookup(entries)
    entry = lookup.reach(root)
    if entry is None or entry.point != root or entry.fstype != "cgroup2":
        raise Refusal(f"no cgroup v2 hierarchy is mounted at {root}")
    if entry.root != b"/":
        shown = os.fsdecode(_mountinfo_unescape(entry.root))
        raise Refusal(
            f"the cgroup v2 mount at {root} shows only {shown} of the hierarchy, so a "
            "retained run unit's control group can be outside it"
        )
    for below in entries:
        if below.point != root and _path_is_within(below.point, root) and lookup.shows(below):
            raise Refusal(
                f"a {below.fstype} mount at {below.point} covers part of the cgroup v2 "
                "hierarchy, so a retained run unit's control-group members can read empty"
            )


def _retained_unit_cgroup_members(
    units: AbstractSet[str], *, root: Path | None = None
) -> Mapping[str, int]:
    """Count the processes now in each retained run unit's control group.

    The process tables name a process only if it existed when its PID was
    listed.  A run that started after that, and whose unit finished before
    the second enumeration, can leave a child in its control group that no
    table holds.  This reads ``cgroup.procs`` of every control group named
    after one of ``units``, and of its descendants, below the user manager,
    after both enumerations.  A control group that disappears meanwhile has
    no member.  No cgroup v2 hierarchy, an unreadable directory or member
    list, or a hierarchy beyond the census bound refuses.

    A count of zero is evidence only where the whole hierarchy is visible,
    so with the default ``root`` the mount at ``/sys/fs/cgroup`` must be
    cgroup v2 with the hierarchy's root as its own (a mount of a subtree
    would hide every unit outside it), no visible mount may lie below it,
    and the user manager's control group must be visible under ``root``;
    any of them missing refuses.
    """

    if not units:
        return {}
    if root is None:
        root = _CGROUP_ROOT
        _assert_whole_cgroup2_hierarchy(root)
    if not (root / "cgroup.controllers").is_file():
        raise Refusal(f"no cgroup v2 hierarchy is mounted at {root}")
    manager = _user_manager_cgroup(root)
    members = dict.fromkeys(units, 0)
    if not manager.is_dir():
        raise Refusal(
            f"this user's service manager control group {manager} is not visible, "
            "so a retained run unit's control-group members cannot be read"
        )

    def unreadable(exc: OSError) -> None:
        if not isinstance(exc, FileNotFoundError):
            raise Refusal(f"user-manager control group is unreadable: {exc}") from exc

    visited = 0
    for directory, _children, _files in os.walk(manager, onerror=unreadable):
        visited += 1
        if visited > _RETAINED_CGROUP_DIRECTORY_LIMIT:
            raise Refusal("user-manager control groups exceed the census bound")
        named = [
            part for part in Path(directory).relative_to(manager).parts if part in members
        ]
        if not named:
            continue
        try:
            procs = (Path(directory) / "cgroup.procs").read_text(encoding="ascii")
        except FileNotFoundError:
            continue
        except (OSError, UnicodeDecodeError) as exc:
            raise Refusal(f"control group {directory} member list is unreadable: {exc}") from exc
        count = sum(1 for line in procs.splitlines() if line.strip())
        for name in named:
            members[name] += count
    return members


# The kernel's fixed inode numbers for its initial PID and cgroup namespaces
# (PROC_PID_INIT_INO and PROC_CGROUP_INIT_INO in include/linux/proc_ns.h).
# Every other namespace gets a dynamically allocated inode, so a match proves
# that this process sees the host's PIDs and control-group paths.  Reading
# /proc/1/ns/* to compare instead needs ptrace access to PID 1, which an
# unprivileged caller does not have (EACCES on the measured host).
_INITIAL_NAMESPACE_INODES = (("pid", 0xEFFFFFFC), ("cgroup", 0xEFFFFFFB))


def _namespace_inode(name: str) -> int:
    return os.stat(f"/proc/self/ns/{name}").st_ino


def _proc_superblock_options() -> tuple[str, ...]:
    """Return the superblock options of the procfs visible at ``/proc``."""

    entry = _visible_mount(_read_self_mount_entries(), Path("/proc"))
    if entry is None or entry.point != Path("/proc") or entry.fstype != "proc":
        raise Refusal("no process filesystem is mounted at /proc")
    return tuple(os.fsdecode(_mountinfo_unescape(entry.options)).split(","))


# A mount point at or below one process's directory in /proc.
_PROC_PROCESS_MOUNT = re.compile(r"/proc/[0-9]+(?:/.*)?", re.DOTALL)


def _assert_host_process_view() -> None:
    """Refuse unless ``/proc`` and control-group paths show the whole host.

    Matching machine and boot identities do not show that this process can
    see a host run.  In a child PID namespace the run and its children are
    absent from /proc; in a child cgroup namespace their control-group paths
    are rewritten relative to another root; procfs mounted with ``hidepid``
    hides processes; and a mount over ``/proc/<pid>``, or a path inside it,
    replaces that process's entries with another file system's.  Any of
    them makes an absent run look ``dead``.  A mount there that a later
    mount over ``/proc`` hides replaces nothing that path lookup reaches.
    """

    for name, initial in _INITIAL_NAMESPACE_INODES:
        try:
            inode = _namespace_inode(name)
        except OSError as exc:
            raise Refusal(f"cannot read this process's {name} namespace: {exc}") from exc
        if inode != initial:
            raise Refusal(
                f"this process is not in the host's initial {name} namespace (inode "
                f"{inode}), so its process table need not show the recorded runs"
            )
    try:
        own = os.readlink("/proc/self")
    except OSError as exc:
        raise Refusal(f"cannot resolve /proc/self: {exc}") from exc
    if own != str(os.getpid()):
        raise Refusal(
            "/proc is not the process filesystem of this process's PID namespace"
        )
    hidden = [
        option
        for option in _proc_superblock_options()
        if option.startswith("hidepid=") and option not in {"hidepid=0", "hidepid=off"}
    ]
    if hidden:
        raise Refusal(
            f"/proc is mounted with {hidden[-1]}, so its process table need not show "
            "the recorded runs"
        )
    entries = _read_self_mount_entries()
    lookup = _MountLookup(entries)
    for entry in entries:
        if _PROC_PROCESS_MOUNT.fullmatch(str(entry.point)) and lookup.shows(entry):
            raise Refusal(
                f"a {entry.fstype} mount at {entry.point} masks that process's "
                "entries in /proc, so its process table need not show the recorded runs"
            )


def _validation_run_host_evidence() -> tuple[
    tuple[_AbsentProcessObservation, ...], tuple[Mapping[str, str], ...]
]:
    """Read this host's live processes and user-systemd units, each strictly.

    This is the only host-wide evidence the validation-run authority reads;
    the retained run handles are project files.  It first proves that this
    process's view of processes and control groups is the host's; see
    ``_assert_host_process_view``.  The process table is read on both sides
    of the user-systemd enumeration; see ``_processes_around_unit_enumeration``.
    """

    return _host_evidence_around(_absent_validate_process_snapshot)


def _host_evidence_around(
    before: Callable[[], Sequence[_AbsentProcessObservation]],
) -> tuple[tuple[_AbsentProcessObservation, ...], tuple[Mapping[str, str], ...]]:
    """Prove a host process view, then read processes around the units.

    ``before`` reads the first process table; recovery passes its path
    census, which reads one.  Shared by the validation-run authority and by
    ``recover-absent-validate-rows`` and ``recover-absent-agent-rows``.
    """

    _assert_host_process_view()
    return _processes_around_unit_enumeration(before())


@dataclasses.dataclass(frozen=True)
class _RunEvidence:
    """Host and run evidence for absent or completed rows, read in order."""

    processes: tuple[_AbsentProcessObservation, ...]
    units: tuple[Mapping[str, str], ...]
    bindings: Mapping[str, tuple[_RetainedValidationHandle, ...]]
    members: Mapping[str, int]
    # Handles whose two reads, before and after the host evidence, differ,
    # or are equal where that does not rule out a rewrite, and handles that
    # changed while a recent handle's timestamp window was waited out: each
    # with how and when it changed (``_retained_handle_changes``).
    late: Mapping[str, tuple[tuple[_RetainedValidationHandle, str], ...]]
    # The process generations the handles record, read just before the host
    # evidence (``_recorded_generations_before``): those that ran, and those
    # whose reading refused, with the refusal.  Keyed by boot id, PID and
    # start ticks.
    running: frozenset[tuple[str, int, int]]
    unreadable: Mapping[tuple[str, int, int], str]


def _run_evidence(
    config: Config,
    rows: Sequence[tuple[ActiveRecord, tuple[Path, ...]]],
    host: Callable[
        [], tuple[tuple[_AbsentProcessObservation, ...], tuple[Mapping[str, str], ...]]
    ],
    *,
    first: Mapping[str, tuple[_RetainedValidationHandle, ...]] | None = None,
) -> _RunEvidence:
    """Read the retained run handles, the host, the handles again, then cgroups.

    A run registered while the host evidence was read has a handle that the
    first read missed, or one rewritten, replaced or removed since it, so
    the handles from both reads are judged and every difference between
    the two reads, down to the handle file's bytes and times, is recorded
    in ``late``.  A rewrite with the same bytes in the same file timestamp
    tick leaves every recorded field alike, so when a handle of the first
    read changed within ``_RETAINED_HANDLE_STABLE_NS`` of it, the window is
    waited out and the handles are read again before the host evidence
    (``_settle_retained_handles``), and a difference between the reads
    before and after the wait is recorded in ``late`` as well.  A handle
    that both reads find alike while either finds it that recent, or
    across a step back of this host's realtime clock, is recorded in
    ``late`` too (``_retained_handle_changes``).  Between the last handle
    read before the host evidence and that evidence, the process generation
    each of those handles records is read directly
    (``_recorded_generations_before``).  The
    current members of their units' control groups are read last (see
    ``_retained_unit_cgroup_members``).  ``first`` is a handle read the
    caller has already made and judged.  Every caller that judges rows from
    runs reads its evidence here and judges it with ``_judge_run_evidence``:
    the validation-run authority, ``recover-absent-validate-rows`` and
    ``recover-absent-agent-rows``.

    No read here tells a run whose handle is written before its unit is
    queued from a run that finished: both leave a handle that every read
    finds alike, with no unit, process or member, and waiting longer does
    not tell them apart.  A dead answer therefore relies on whatever writes
    a handle making its run visible here (its unit active or queued, another
    active or queued unit that names the checkout, or the process
    generation the handle records running) before the change time of any
    write is ``_RETAINED_HANDLE_STABLE_NS`` old, and keeping it visible
    without a break until its own unit is queued.  The user guide states
    that rule for handle writers.
    """

    if first is None:
        first = _retained_handles_for_absent_rows(config, rows)
    earlier = first
    if _settle_retained_handles(first):
        first = _retained_handles_for_absent_rows(config, rows)
    running, unreadable = _recorded_generations_before(first)
    processes, units = host()
    later = _retained_handles_for_absent_rows(config, rows)
    bindings = {
        slot: tuple(
            dict.fromkeys(
                (*earlier.get(slot, ()), *first.get(slot, ()), *later.get(slot, ()))
            )
        )
        for slot in {*earlier, *first, *later}
    }
    members = _retained_unit_cgroup_members(
        {handle.unit for handles in bindings.values() for handle in handles}
    )
    late: dict[str, tuple[tuple[_RetainedValidationHandle, str], ...]] = {}
    for slot in {*earlier, *first, *later}:
        changes = _retained_handle_changes(
            first.get(slot, ()),
            later.get(slot, ()),
            window=True,
            during="while the host evidence was read",
        )
        if earlier is not first:
            changes += _retained_handle_changes(
                earlier.get(slot, ()),
                first.get(slot, ()),
                window=False,
                during="while their timestamp window was waited out",
            )
        if changes:
            late[slot] = changes
    return _RunEvidence(processes, units, bindings, members, late, running, unreadable)


def _recorded_generations_before(
    bindings: Mapping[str, tuple[_RetainedValidationHandle, ...]],
) -> tuple[frozenset[tuple[str, int, int]], dict[tuple[str, int, int], str]]:
    """Read each current-boot process generation that ``bindings`` record.

    ``_run_evidence`` reads them after its last handle read before the host
    evidence and just before that evidence.  A recorded generation that runs
    then may queue its unit at any later time, after the second user-systemd
    enumeration included, and exit before the judgment reads it again.  The
    process tables need not show it while it runs: they list thread groups
    and skip terminal ones, so a recorded thread ID, or a thread group
    leader that has exited while another thread of its group runs, is in
    neither.  Its own ``/proc`` entry is read here instead, which shows
    both.  A recorded generation that does not run then cannot act after
    it, so a unit it queued was queued before both enumerations.

    Returns the generations that ran and, for each whose generation or boot
    could not be read, the refusal, so that one unreadable handle refuses
    only the rows it names.
    """

    running: set[tuple[str, int, int]] = set()
    unreadable: dict[tuple[str, int, int], str] = {}
    current_boot: str | None = None
    for handles in bindings.values():
        for handle in handles:
            if handle.pid is None:
                continue
            assert handle.start_ticks is not None and handle.boot_id is not None
            generation = (handle.boot_id, handle.pid, handle.start_ticks)
            if generation in running or generation in unreadable:
                continue
            try:
                if current_boot is None:
                    current_boot = _boot_id(Path("/proc"))
                if handle.boot_id != current_boot:
                    continue
                if (
                    _process_start_ticks(Path("/proc") / str(handle.pid))
                    == handle.start_ticks
                ):
                    running.add(generation)
            except Refusal as exc:
                unreadable[generation] = str(exc)
    return frozenset(running), unreadable


def _retained_handle_changes(
    before: Sequence[_RetainedValidationHandle],
    after: Sequence[_RetainedValidationHandle],
    *,
    window: bool,
    during: str,
) -> tuple[tuple[_RetainedValidationHandle, str], ...]:
    """Every difference between two reads of one row's handles, as ``late`` holds it.

    A handle only ``after`` holds appeared, one that differs changed, and
    one only ``before`` holds disappeared or stopped naming the row.  An
    equal handle may still have been rewritten alike: with ``window``, when
    either read found it within ``_RETAINED_HANDLE_STABLE_NS`` of its change
    time (the later read finds that only if the realtime clock went back),
    and always when the realtime clock may have stepped more than
    ``_RETAINED_HANDLE_CLOCK_STEP_NS`` against the monotonic clock during
    or between the two reads (``_realtime_clock_stepped_back``).
    ``during`` says when, and ends each description.
    """

    first = {handle.path: handle for handle in before}
    second = {handle.path: handle for handle in after}
    changes: list[tuple[_RetainedValidationHandle, str]] = []
    changes.extend(
        (handle, "appeared" if path not in first else "changed")
        for path, handle in second.items()
        if first.get(path) != handle
    )
    if window:
        changes.extend(
            (handle, "may have been rewritten alike within one file timestamp tick")
            for path, handle in second.items()
            if first.get(path) == handle and (first[path].recent or handle.recent)
        )
    changes.extend(
        (
            handle,
            "may have been rewritten alike while this host's realtime clock stepped back",
        )
        for path, handle in second.items()
        if first.get(path) == handle
        and _realtime_clock_stepped_back(first[path], handle)
    )
    changes.extend(
        (handle, "disappeared or stopped naming the row")
        for path, handle in first.items()
        if path not in second
    )
    return tuple((handle, f"{change} {during}") for handle, change in changes)


def _realtime_clock_stepped_back(
    before: _RetainedValidationHandle, after: _RetainedValidationHandle
) -> bool:
    """Whether the realtime clock may have fallen against the monotonic clock
    while the censuses that read ``before`` and ``after`` ran, or between them.

    The highest offset either census found is compared with the lowest
    either found, so a fall counts wherever it shows: within the earlier
    census, before or after its handle reads, between the censuses, or
    within the later one.  A rise counts too, and so does a reading that
    pauses left too loosely bounded to rule a fall out; each keeps a run
    alive rather than clearing its row.
    """

    if before.clock_offsets_ns is None or after.clock_offsets_ns is None:
        return False
    return (
        max(before.clock_offsets_ns[1], after.clock_offsets_ns[1])
        - min(before.clock_offsets_ns[0], after.clock_offsets_ns[0])
        > _RETAINED_HANDLE_CLOCK_STEP_NS
    )


def _settle_retained_handles(
    handles: Mapping[str, tuple[_RetainedValidationHandle, ...]],
) -> bool:
    """Wait until no handle in ``handles`` changed within the window.

    Return whether any handle was recent, so that the caller reads the
    handles again.  A validation run rewrites its handle when it finishes,
    just before its row is removed, so a recent handle is the common case
    and not a refusal.  The wait is at most ``_RETAINED_HANDLE_STABLE_NS``
    and ``_RETAINED_HANDLE_SETTLE_SLACK_NS``; a change time further ahead
    of this host's clock is not waited for, and the handles read again are
    still recent.  The wait does not show that a registration it saw has
    ended.  The reads before and after it compare each handle's device,
    inode, size, bytes, and modification and change times, so a rewrite
    during the wait that moves any of them is a change, as a rewrite after
    a read is where file timestamps are fine-grained once read.  A handle
    rewritten alike within its timestamp tick during the wait still reads
    as before, and one rewritten just before the first read leaves nothing
    to compare, so a writer that queues its unit only after the wait is
    covered by the rule for handle writers in ``_run_evidence``, not by the
    wait.
    """

    changes = [
        handle.file_generation[5]
        for values in handles.values()
        for handle in values
        if handle.recent and handle.file_generation is not None
    ]
    if not changes:
        return False
    wait_ns = max(changes) + _RETAINED_HANDLE_STABLE_NS - _retained_handle_clock_ns()
    if 0 < wait_ns <= _RETAINED_HANDLE_STABLE_NS + _RETAINED_HANDLE_SETTLE_SLACK_NS:
        time.sleep(wait_ns / 1_000_000_000 + 0.01)
    return True


def _judge_run_evidence(
    rows: Sequence[tuple[ActiveRecord, tuple[Path, ...]]],
    evidence: _RunEvidence,
    *,
    resolver: _UnitPathResolver | None = None,
) -> None:
    """Refuse when ``evidence`` shows that a run may still use one of ``rows``.

    Each retained handle's process generation, unit states and control-group
    members are judged, and every active or queued unit is compared with the
    rows' paths.  A handle that the later read found new or changed, or
    that it no longer found, was written or removed after both user-systemd
    enumerations had begun, so their unit states do not cover its run: a
    unit queued after the second enumeration, whose job has not started,
    shows no state, process or member.  Such a handle is a run that may
    still use the row.  Rerunning reads it before the units.  A handle's
    recorded process generation that ran just before the host evidence is a
    run too, even when it has exited since: it may have queued its unit
    after the second enumeration (``_assert_retained_handle_processes_dead``).
    """

    slots = {record.slot for record, _paths in rows}
    bindings = {slot: evidence.bindings.get(slot, ()) for slot in slots}
    _assert_retained_handle_processes_dead(bindings, evidence.running, evidence.unreadable)
    _assert_absent_validate_systemd_unrelated(
        rows,
        bindings,
        evidence.processes,
        snapshot=evidence.units,
        resolver=resolver,
        members=evidence.members,
    )
    for slot in sorted(slots):
        for handle, change in evidence.late.get(slot, ()):
            raise _ValidationRunMayUseRow(
                f"retained validation handle {handle.path} for row {slot} {change}, "
                f"so its unit {handle.unit} may have been queued after the user-systemd "
                "enumerations"
            )


def _validation_run_row_paths(
    config: Config,
    record: ActiveRecord,
    fenced_slots: Mapping[tuple[str, str, int], Path] | None = None,
) -> tuple[Path, ...]:
    """Return a validation row's recorded paths and their fenced counterparts.

    Removal renames the slot directory to ``.<slot>.fenced.<generation>.<hex>``
    beside it before deleting it, so finish recovery and a deferred private
    completion judge a row whose checkout is no longer at its recorded path.
    A queued job or run handle naming the fenced checkout uses the same
    files.  Every such sibling present on disk is included, and so is the
    fence a finish journal names (``fenced_slots``), which may not exist yet.
    """

    paths = _absent_validate_row_paths(config, record)
    slot_path = _slot_directory(config, record.slot, record.slot_type).absolute()
    prefix = f".{record.slot}.fenced.{record.generation}."
    fences: set[Path] = set()
    named = None if fenced_slots is None else fenced_slots.get(
        (record.machine, record.slot, record.generation)
    )
    if named is not None:
        fences.add(named.absolute())
    try:
        with os.scandir(slot_path.parent) as entries:
            fences.update(
                slot_path.parent / entry.name
                for entry in entries
                if entry.name.startswith(prefix)
            )
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise Refusal(
            f"cannot enumerate fenced paths of validation row {record.slot}: {exc}"
        ) from exc
    fenced: list[Path] = []
    for fence in sorted(fences):
        for path in paths:
            if path == slot_path or slot_path in path.parents:
                fenced.append(fence / path.relative_to(slot_path))
    return tuple(dict.fromkeys((*paths, *fenced)))


def _validation_run_liveness_states(
    config: Config,
    records: Sequence[ActiveRecord],
    *,
    fenced_slots: Mapping[tuple[str, str, int], Path] | None = None,
) -> dict[tuple[str, str, int], tuple[str, str]]:
    """Answer the liveness question for validation rows from their runs.

    A validation row's ``agent`` names a run, not a process that can be asked
    about: validation launchers register labels such as ``validate-<slot>``
    that no process carries, and a validation may outlive the agent that
    started it.  Asking the configured agent-liveness command about such a
    row has no answer.  On 2026-10-05 every one of 54 validation rows on one
    host was ``unverifiable``, so no completed validation checkout could be
    removed by anyone except its own still-running launcher.

    The run is the authority instead, exactly as for
    ``recover-absent-validate-rows``.  A row is ``dead`` only when every
    retained run handle that names its slot or checkout path, recorded or
    fenced (see ``_validation_run_row_paths``), has a dead exact process
    generation and an inactive, unqueued service unit with no live
    process in its control group, and no active or queued user-systemd unit
    names those paths.  Positive evidence of a run is ``alive``.  Unreadable
    handle, process or user-systemd evidence, a row registered on another
    machine, and a row whose coordinator lease or owner names another stable
    host identity are ``unverifiable``, because all of that evidence is local
    to this host.

    This replaces only the agent-name question.  Every caller still requires
    the exact recorded owner generation to be dead (or the caller to be that
    live owner), and removal still runs its full process/path census.
    """

    if not records:
        return {}
    keys = [(record.machine, record.slot, record.generation) for record in records]
    if any(record.slot_type != "validate" for record in records):
        raise StateError("validation-run liveness applies only to validation rows")
    result: dict[tuple[str, str, int], tuple[str, str]] = {}
    local: list[ActiveRecord] = []
    try:
        _host_id()
    except Refusal as exc:
        detail = _liveness_batch_diagnostic(
            f"validation-run evidence is unverifiable: {exc}"
        )
        return {key: ("unverifiable", detail) for key in keys}
    for record in records:
        key = (record.machine, record.slot, record.generation)
        if record.machine != config.machine:
            result[key] = (
                "unverifiable",
                f"validation row is registered on machine {record.machine}, and "
                f"run, process and user-systemd evidence is local to {config.machine}",
            )
        else:
            # An ownerless row has no owner host to compare, but its
            # coordinator lease names the host that registered it.  Checking
            # only the owner let ``--machine`` select a foreign shard's
            # ownerless row and judge it ``dead`` from this host's evidence.
            try:
                _assert_absent_validate_row_is_local(record)
            except Refusal as exc:
                result[key] = (
                    "unverifiable",
                    f"{exc}, and run, process and user-systemd evidence is local to "
                    f"this host",
                )
                continue
            local.append(record)
    if not local:
        return result
    try:
        rows = tuple(
            (record, _validation_run_row_paths(config, record, fenced_slots))
            for record in local
        )
        evidence = _run_evidence(config, rows, _validation_run_host_evidence)
    except Refusal as exc:
        detail = _liveness_batch_diagnostic(
            f"validation-run evidence is unverifiable: {exc}"
        )
        result.update(
            ((record.machine, record.slot, record.generation), ("unverifiable", detail))
            for record in local
        )
        return result
    resolver = _UnitPathResolver()
    for row in rows:
        record = row[0]
        key = (record.machine, record.slot, record.generation)
        try:
            _judge_run_evidence((row,), evidence, resolver=resolver)
        except _ValidationRunMayUseRow as exc:
            result[key] = (
                "alive",
                _liveness_batch_diagnostic(f"validation run may still use the row: {exc}"),
            )
            continue
        except Refusal as exc:
            # Unreadable evidence, such as the boot id or a recorded run
            # process's generation, shows no run.  Reporting it ``alive``
            # would send the operator to stop a unit that may not exist.
            result[key] = (
                "unverifiable",
                _liveness_batch_diagnostic(
                    f"validation-run evidence is unverifiable: {exc}"
                ),
            )
            continue
        result[key] = (
            "dead",
            f"{len(evidence.bindings.get(record.slot, ()))} retained run handle(s) "
            "name this row, each with an inactive, unqueued unit with no live "
            "process and any recorded process generation dead since before the host "
            "evidence was read; no active or queued user-systemd unit names its "
            "paths",
        )
    return result


def _owner_liveness_states(
    config: Config, records: Sequence[ActiveRecord]
) -> dict[tuple[str, str, int], tuple[str, str]]:
    """Ask each row's liveness authority: the run for validation rows,
    the registered liveness command for agent rows."""

    validation = [record for record in records if record.slot_type == "validate"]
    agents = [record for record in records if record.slot_type != "validate"]
    result = _registered_liveness_states(config, agents)
    result.update(_validation_run_liveness_states(config, validation))
    return result


def _assert_owner_liveness(
    config: Config,
    record: ActiveRecord,
    *,
    known: Mapping[tuple[str, str, int], tuple[str, str]] | None = None,
    fenced_slot: Path | None = None,
) -> None:
    """Require the row's liveness authority to report its owner dead.

    ``known`` carries validation-run answers that the caller already read
    under the same mutation lock, so a batch reads host evidence once.
    ``fenced_slot`` is the fence a finish journal names for this row.
    """

    if record.slot_type != "validate":
        _assert_registered_liveness(config, record)
        return
    key = (record.machine, record.slot, record.generation)
    answered = None if known is None else known.get(key)
    state, detail = (
        answered
        if answered is not None
        else _validation_run_liveness_states(
            config,
            (record,),
            fenced_slots=None if fenced_slot is None else {key: fenced_slot},
        )[key]
    )
    if state == "dead":
        return
    if state == "alive":
        raise Refusal(
            f"validation-run authority reports the run may still use slot "
            f"{record.slot}: {detail}. state: REFUSED -- no checkout was salvaged or "
            "removed. remedy: let the validation run finish or stop its unit, then "
            "rerun remove"
        )
    raise Refusal(
        f"validation-run authority is unverifiable for slot {record.slot}: {detail}. "
        "state: REFUSED -- no checkout was salvaged or removed; unknown use is not a "
        "free slot. remedy: repair the named run-handle, process or user-systemd "
        "evidence, then rerun remove"
    )


def _process_state(identity: ProcessIdentity | None) -> tuple[str, str]:
    if identity is None:
        return "indeterminate", "no owner process generation is recorded"
    try:
        host_id = _host_id()
    except Refusal as exc:
        return "indeterminate", str(exc)
    if host_id != identity.host_id:
        return (
            "indeterminate",
            "the recorded owner belongs to a different machine identity",
        )
    try:
        boot_id = _boot_id(Path("/proc"))
    except Refusal as exc:
        return "indeterminate", str(exc)
    if boot_id != identity.boot_id:
        return "dead", "the recorded machine boot ended"
    try:
        current = _read_process_identity(identity.pid)
    except Refusal as exc:
        message = str(exc)
        if "is not live" in message:
            return "dead", message
        return "indeterminate", message
    if current == identity:
        return "live", f"PID {identity.pid} generation is live"
    return "dead", f"PID {identity.pid} was reused; the recorded generation exited"


def _link_target(path: Path) -> Path | None:
    try:
        raw = os.readlink(path)
    except FileNotFoundError:
        return None
    except PermissionError as exc:
        raise Refusal(
            f"process use is indeterminate because {path} is unreadable: {exc}"
        ) from exc
    except OSError as exc:
        if exc.errno == errno.EINVAL:
            return None
        raise Refusal(f"process use is indeterminate because {path} failed: {exc}") from exc
    if raw.endswith(" (deleted)"):
        raw = raw[: -len(" (deleted)")]
    target = Path(raw)
    if not target.is_absolute():
        target = path.parent / target
    return Path(os.path.normpath(str(target)))


def _process_uses_slot(
    pid_dir: Path,
    slot_path: Path,
    *,
    mount_verdicts: _MountTableVerdicts | None = None,
) -> list[str]:
    uses: list[str] = []
    for name in ("cwd", "root", "exe"):
        target = _link_target(pid_dir / name)
        if target is not None and _path_is_within(target, slot_path):
            uses.append(f"{name}={target}")
    fd_dir = pid_dir / "fd"
    try:
        descriptors = list(fd_dir.iterdir())
    except FileNotFoundError:
        descriptors = []
    except PermissionError as exc:
        raise Refusal(
            f"process use is indeterminate because {fd_dir} is unreadable: {exc}"
        ) from exc
    except OSError as exc:
        raise Refusal(
            f"process use is indeterminate because {fd_dir} cannot be read: {exc}"
        ) from exc
    for descriptor in descriptors:
        target = _link_target(descriptor)
        if target is not None and _path_is_within(target, slot_path):
            uses.append(f"fd/{descriptor.name}={target}")
            break
    maps_path = pid_dir / "maps"
    try:
        maps = maps_path.read_text(encoding="utf-8", errors="surrogateescape")
    except FileNotFoundError:
        maps = ""
    except PermissionError as exc:
        raise Refusal(
            f"process use is indeterminate because {maps_path} is unreadable: {exc}"
        ) from exc
    except OSError as exc:
        raise Refusal(
            f"process use is indeterminate because {maps_path} cannot be read: {exc}"
        ) from exc
    slot_text = str(slot_path)
    for line in maps.splitlines():
        if slot_text in line:
            fields = line.split(maxsplit=5)
            if len(fields) == 6:
                mapped = Path(fields[5].removesuffix(" (deleted)"))
                if mapped.is_absolute() and _path_is_within(mapped, slot_path):
                    uses.append(f"map={mapped}")
                    break
    if mount_verdicts is None:
        uses.extend(_process_mounts_slot(pid_dir, slot_path))
    else:
        uses.extend(mount_verdicts.uses(pid_dir))
    return uses


def _parse_mountinfo_paths(
    text: str,
    label: str,
    cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
) -> tuple[tuple[Path, str], ...]:
    """Parse one process's mount table into the absolute paths it references.

    ``cache`` is keyed on the mount table TEXT, which is what the result depends
    on; ``label`` only names the PID in a refusal.  A census reads one table per
    mount namespace, and on a fleet host almost every process has its own
    namespace while mounting the same tables -- measured 2026-09-17, 3,363
    namespaces across 3,638 processes.  Re-parsing identical text once per
    namespace built about 700,000 `Path` objects whose construction and hashing,
    not the walk over them, was the census's largest single cost.

    Only a SUCCESSFUL parse is cached, so a malformed table still refuses once
    per process and still names the process it came from.
    """

    if cache is not None:
        cached = cache.get(text)
        if cached is not None:
            return cached
    references: list[tuple[Path, str]] = []
    for line in text.splitlines():
        if _owned_mount_line(line):
            continue
        left, separator, right = line.partition(" - ")
        if not separator:
            raise Refusal(f"{label} is malformed")
        left_fields = left.split()
        right_fields = right.split()
        if len(left_fields) < 5 or len(right_fields) < 2:
            raise Refusal(f"{label} is incomplete")
        for raw in (left_fields[3], left_fields[4], right_fields[1]):
            candidate = Path(
                raw.replace("\\040", " ")
                .replace("\\011", "\t")
                .replace("\\012", "\n")
                .replace("\\134", "\\")
                .removesuffix(" (deleted)")
            )
            if candidate.is_absolute():
                references.append((candidate, raw))
    parsed = tuple(references)
    if cache is not None:
        cache[text] = parsed
    return parsed


def _read_process_mountinfo(pid_dir: Path) -> str | None:
    """Return one process's mount table, or None once the process is gone."""

    mountinfo_path = pid_dir / "mountinfo"
    try:
        return mountinfo_path.read_text(encoding="utf-8", errors="surrogateescape")
    except FileNotFoundError:
        return None
    except OSError as exc:
        if exc.errno in (errno.ENOENT, errno.ESRCH, errno.EINVAL):
            return None
        raise Refusal(
            f"process use is indeterminate because {mountinfo_path} is unreadable: {exc}"
        ) from exc


def _mountinfo_uses_slot(mountinfo: str, slot_path: Path, label: str) -> tuple[str, ...]:
    for candidate, _raw in _parse_mountinfo_paths(mountinfo, label):
        if _path_is_within(candidate, slot_path):
            return (f"mount={candidate}",)
    return ()


def _process_mounts_slot(pid_dir: Path, slot_path: Path) -> list[str]:
    mountinfo = _read_process_mountinfo(pid_dir)
    if mountinfo is None:
        return []
    return list(
        _mountinfo_uses_slot(
            mountinfo, slot_path, f"process mount evidence for PID {pid_dir.name}"
        )
    )


class _MountTableVerdicts:
    """One census's memo of whether each mount table it reads references a slot.

    A census over thousands of processes used to parse and walk one mount table
    per mount namespace, and a fleet host has nearly one namespace per process
    listing a handful of distinct tables (measured 2026-09-17: 3,363 namespaces
    across 3,638 processes).  The verdict depends only on the table and the
    slot, so it is computed once per distinct table and keyed on a digest of
    the table's content, which holds a few bytes per table rather than the
    tables themselves.

    Every process's table is still read.  A shared mount namespace is not a
    shared table: the kernel lists only the mounts below a process's root, and
    neither a namespace identity nor a root's rendered path identifies that
    root -- a root the reader cannot reach, such as a chroot in a lazily
    unmounted tree, renders as ``/``.  Keying on content is sound for every
    process, including one whose namespace is unreadable.  Only a successful
    verdict is stored: a malformed table refuses for every process that lists
    it, naming that process.
    """

    def __init__(self, slot_path: Path) -> None:
        self.slot_path = slot_path
        self._by_table: dict[bytes, tuple[str, ...]] = {}

    def uses(self, pid_dir: Path) -> list[str]:
        """Return ``pid_dir``'s mount uses of the slot, as `_process_mounts_slot`."""

        mountinfo = _read_process_mountinfo(pid_dir)
        if mountinfo is None:
            return []
        digest = hashlib.sha256(
            mountinfo.encode("utf-8", errors="surrogateescape")
        ).digest()
        verdict = self._by_table.get(digest)
        if verdict is None:
            verdict = _mountinfo_uses_slot(
                mountinfo,
                self.slot_path,
                f"process mount evidence for PID {pid_dir.name}",
            )
            self._by_table[digest] = verdict
        return list(verdict)


def _mount_namespace(pid_dir: Path) -> str | None:
    path = pid_dir / "ns" / "mnt"
    try:
        return os.readlink(path)
    except FileNotFoundError:
        return None
    except PermissionError:
        return f"pid:{pid_dir.name}"
    except OSError as exc:
        if exc.errno in (errno.ENOENT, errno.ESRCH, errno.EINVAL):
            return None
        raise Refusal(
            f"mount namespace is indeterminate because {path} is unreadable: {exc}"
        ) from exc


def _read_process_status(
    pid_dir: Path, *, generation: _ProcessStat | None = None,
) -> str:
    def read() -> str:
        return (pid_dir / "status").read_bytes().decode(
            "ascii", errors="surrogateescape"
        )

    try:
        return read()
    except OSError as exc:
        if exc.errno != errno.ESRCH:
            raise
    # A held proc inode can become unreadable after reap. Reopen its pathname
    # once; another error remains an error, never proof of terminal state.
    status = read()
    if generation is not None:
        current = _read_process_stat(pid_dir)
        if current is not None and current.start_ticks != generation.start_ticks:
            raise _ProcessEvidenceChanged(
                f"process generation changed while reopening status for PID {pid_dir.name}"
            )
    return status


def _process_uids(pid_dir: Path) -> tuple[int, int, int, int] | None:
    try:
        status = _read_process_status(pid_dir)
    except FileNotFoundError:
        return None
    except (OSError, UnicodeError) as exc:
        raise Refusal(
            f"process ownership is indeterminate because {pid_dir / 'status'} is unreadable: {exc}"
        ) from exc
    # procfs terminates records with LF and escapes LF inside ``Name``.  Do not use
    # ``splitlines()``: a process may put CR/VT/FF in its opaque name, and Python
    # would then manufacture a field-looking line from inside that name.
    for line in status.split("\n"):
        if line.startswith("Uid:"):
            fields = line.split()
            if len(fields) != 5:
                break
            try:
                real, effective, saved, filesystem = (
                    int(field) for field in fields[1:]
                )
                return real, effective, saved, filesystem
            except ValueError:
                break
    raise Refusal(f"process ownership is indeterminate for {pid_dir.name}")


def _process_uid(pid_dir: Path) -> int | None:
    uids = _process_uids(pid_dir)
    return None if uids is None else uids[0]


def _process_filesystem_uid(pid_dir: Path) -> int | None:
    """Return the credential Linux uses for filesystem permission checks."""

    uids = _process_uids(pid_dir)
    return None if uids is None else uids[3]


def _unrelated_lsof_warnings(stderr: str, slot_path: Path) -> bool:
    return _first_related_lsof_warning(stderr, slot_path) is None


def _first_related_lsof_warning(stderr: str, slot_path: Path) -> str | None:
    """Return the first lsof diagnostic that may concern ``slot_path``.

    A diagnostic that names exactly one path concerns the slot when that path
    is inside the slot or contains it.  A diagnostic naming no path or several
    paths cannot be attributed and concerns every slot.
    """

    patterns = (
        re.compile(r"^lsof: WARNING: can't stat\(\) .* file system (?P<path>/.*)$"),
        re.compile(r"^lsof: WARNING: can't opendir\((?P<path>/.*)\): .*$"),
    )
    for line in stderr.splitlines():
        if not line.strip() or line.strip() == "Output information may be incomplete.":
            continue
        matches = [match for pattern in patterns if (match := pattern.fullmatch(line))]
        raw_paths = (
            [matches[0].group("path")]
            if matches
            else re.findall(r"/[^\s)]+", line)
        )
        if len(raw_paths) != 1:
            return line
        unreadable = Path(raw_paths[0].rstrip(":"))
        if _path_is_within(slot_path, unreadable) or _path_is_within(unreadable, slot_path):
            return line
    return None


_LSOF_DIAGNOSTIC_VALUE_LIMIT = 160
_LSOF_DIAGNOSTIC_TRUNCATION = "...<truncated>"


@dataclasses.dataclass(frozen=True)
class _LsofUseDiagnostic:
    pid: int
    command_excerpt: str | None
    descriptor_excerpt: str | None
    name_excerpt: str | None


@dataclasses.dataclass
class _LiveUseRecheckBudget:
    """One transaction-wide allowance for an exact process generation to exit."""

    remaining_seconds: float = _RECLAIM_LIVE_USE_RECHECK_SECONDS
    _deadline: float | None = dataclasses.field(init=False, default=None, repr=False)

    def __post_init__(self) -> None:
        if self.remaining_seconds < 0 or not self.remaining_seconds < float("inf"):
            raise ValueError("live-use recheck allowance must be finite and nonnegative")

    def wait_for_exit(
        self,
        pid: int,
        *,
        start_ticks: int | None,
        proc_root: Path = Path("/proc"),
        revalidate: Callable[[], bool] | None = None,
    ) -> bool:
        """Wait for only the reported generation; uncertainty never permits retry."""

        now = time.monotonic()
        if self._deadline is None:
            self._deadline = now + self.remaining_seconds
        deadline = self._deadline
        self.remaining_seconds = max(0.0, deadline - now)
        if self.remaining_seconds <= 0 or start_ticks is None:
            return False
        descriptor = -1
        try:
            try:
                descriptor = os.pidfd_open(pid)
            except ProcessLookupError:
                # A direct /proc observation already read the generation
                # before inspecting its paths.  An lsof report has no such
                # pre-observation binding, so it must survive the bracketed
                # recheck below before disappearance can permit a retry.
                return revalidate is None
            except OSError:
                return False
            if revalidate is not None and not revalidate():
                return False
            try:
                current = _read_process_stat(proc_root / str(pid))
            except Refusal:
                return False
            if current is None or current.start_ticks != start_ticks:
                return False
            with selectors.DefaultSelector() as watcher:
                watcher.register(descriptor, selectors.EVENT_READ)
                while True:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        return False
                    if watcher.select(remaining):
                        return True
        except OSError:
            return False
        finally:
            self.remaining_seconds = max(0.0, deadline - time.monotonic())
            if descriptor >= 0:
                os.close(descriptor)


def _lsof_diagnostic_excerpt(value: str) -> str:
    """Render one lsof field as bounded, terminal-safe JSON string text."""

    pieces: list[str] = []
    rendered_size = 2  # Opening and closing quotes.
    for character in value:
        escaped = json.dumps(character, ensure_ascii=True)[1:-1]
        if rendered_size + len(escaped) > _LSOF_DIAGNOSTIC_VALUE_LIMIT:
            while (
                pieces
                and rendered_size + len(_LSOF_DIAGNOSTIC_TRUNCATION)
                > _LSOF_DIAGNOSTIC_VALUE_LIMIT
            ):
                removed = pieces.pop()
                rendered_size -= len(removed)
            return (
                '"'
                + "".join(pieces)
                + _LSOF_DIAGNOSTIC_TRUNCATION
                + '"'
            )
        pieces.append(escaped)
        rendered_size += len(escaped)
    return '"' + "".join(pieces) + '"'


def _parse_lsof_use_diagnostic(
    output: str,
) -> tuple[_LsofUseDiagnostic | None, bool]:
    """Return the lowest reported PID's first file record and parse health.

    ``lsof -Fpcfn`` is a stateful stream: ``c`` belongs to the preceding
    process, while ``n`` belongs to the preceding file descriptor.  Keeping
    that association here avoids presenting a command from one process beside
    a path from another.  Each unique ``p`` set must contain its requested
    ``c`` before one or more complete ``f``/``n`` pairs.  Only bounded, escaped
    excerpts survive this parser.  Malformed records never become evidence of
    absence or eligibility for a transient-holder retry.
    """

    selected_pid: int | None = None
    selected_command: str | None = None
    selected_descriptor: str | None = None
    selected_name: str | None = None
    current_pid: int | None = None
    current_descriptor: str | None = None
    current_is_selected_record = False
    current_has_command = False
    current_has_complete_file = False
    current_file_needs_name = False
    current_files_started = False
    seen_pids: set[int] = set()
    malformed = False

    def finish_process_record() -> None:
        nonlocal malformed
        if current_pid is not None and (
            not current_has_command
            or not current_has_complete_file
            or current_file_needs_name
        ):
            malformed = True

    for line in output.splitlines():
        if not line:
            malformed = True
            current_descriptor = None
            current_is_selected_record = False
            continue
        field, value = line[0], line[1:]
        if field == "p":
            finish_process_record()
            current_descriptor = None
            current_is_selected_record = False
            current_has_command = False
            current_has_complete_file = False
            current_file_needs_name = False
            current_files_started = False
            if not re.fullmatch(r"[0-9]{1,20}", value):
                malformed = True
                current_pid = None
                continue
            try:
                pid = int(value)
            except ValueError:
                malformed = True
                current_pid = None
                continue
            if pid in seen_pids:
                malformed = True
            seen_pids.add(pid)
            current_pid = pid
            if selected_pid is None or pid < selected_pid:
                selected_pid = pid
                selected_command = None
                selected_descriptor = None
                selected_name = None
            continue
        if field == "c":
            if (
                current_pid is None
                or not value
                or current_has_command
                or current_files_started
            ):
                malformed = True
                continue
            current_has_command = True
            if current_pid == selected_pid and selected_command is None:
                selected_command = _lsof_diagnostic_excerpt(value)
            continue
        if field == "f":
            if current_file_needs_name:
                malformed = True
            current_is_selected_record = False
            if current_pid is None or not value:
                malformed = True
                current_descriptor = None
                current_file_needs_name = False
                continue
            if not current_has_command:
                malformed = True
            current_files_started = True
            current_descriptor = value
            current_file_needs_name = True
            if current_pid == selected_pid and selected_descriptor is None:
                selected_descriptor = _lsof_diagnostic_excerpt(value)
                current_is_selected_record = True
            continue
        if field == "n":
            if (
                current_pid is None
                or current_descriptor is None
                or not current_file_needs_name
                or not value
            ):
                malformed = True
                continue
            if current_is_selected_record and selected_name is None:
                selected_name = _lsof_diagnostic_excerpt(value)
            current_descriptor = None
            current_is_selected_record = False
            current_file_needs_name = False
            current_has_complete_file = True
            continue
        malformed = True
        current_descriptor = None
        current_is_selected_record = False
        current_file_needs_name = False

    finish_process_record()
    if selected_pid is None:
        return None, malformed
    return (
        _LsofUseDiagnostic(
            selected_pid,
            selected_command,
            selected_descriptor,
            selected_name,
        ),
        malformed,
    )


def _format_lsof_use_diagnostic(
    evidence: _LsofUseDiagnostic, *, malformed: bool
) -> str:
    details: list[str] = []
    if evidence.command_excerpt is not None:
        details.append(f"command={evidence.command_excerpt}")
    if evidence.descriptor_excerpt is not None:
        details.append(f"fd={evidence.descriptor_excerpt}")
    if evidence.name_excerpt is not None:
        details.append(f"file={evidence.name_excerpt}")
    if malformed:
        details.append("malformed lsof fields omitted")
    return f"; lsof {', '.join(details)}" if details else ""


@dataclasses.dataclass(frozen=True)
class _LiveUseObservation:
    pid: int
    start_ticks: int | None
    proc_root: Path
    refusal: Refusal
    revalidate: Callable[[], bool] | None = None


def _lsof_slot_use(
    executable: Path, slot_path: Path
) -> tuple[_LsofUseDiagnostic | None, bool, int]:
    lsof_command = [str(executable), "-nP", "-Fpcfn", "+D", str(slot_path)]
    what = f"lsof +D {slot_path}"
    seconds = _item_seconds_left(what)
    try:
        if seconds is None:
            completed = subprocess.run(
                lsof_command,
                text=True,
                capture_output=True,
                check=False,
            )
        else:
            completed = _run_within_item_budget(lsof_command, seconds=seconds, what=what)
    except OSError as exc:
        raise Refusal(
            f"process use is indeterminate because lsof failed: {exc}"
        ) from exc
    if not _unrelated_lsof_warnings(completed.stderr, slot_path):
        raise Refusal(
            "process use is indeterminate because lsof reported: "
            f"{completed.stderr.strip().splitlines()[0]}"
        )
    evidence, malformed = _parse_lsof_use_diagnostic(completed.stdout)
    if evidence is None:
        if malformed:
            raise Refusal(
                "process use is indeterminate because lsof returned malformed field output"
            )
        if completed.returncode not in (0, 1):
            raise Refusal(
                f"process use is indeterminate because lsof exited {completed.returncode}"
            )
    return evidence, malformed, completed.returncode


def _lsof_use_is_recheckable(
    evidence: _LsofUseDiagnostic,
    *,
    malformed: bool,
    returncode: int,
) -> bool:
    return (
        not malformed
        and returncode in (0, 1)
        and evidence.command_excerpt is not None
        and evidence.descriptor_excerpt is not None
        and evidence.name_excerpt is not None
    )


def _assert_slot_unused(
    slot_path: Path,
    record: ActiveRecord | None = None,
    *,
    use_lsof: bool = True,
    ignore_invoking_ancestry: bool = False,
    census: _ProcessPathCensus | None = None,
    fallback_census: _ProcessPathCensus | None = None,
    proc_root: Path = Path("/proc"),
    ignore_current_process: bool = True,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
    agent_batch: _AgentRemoveBatchContext | None = None,
    canonical_path: Path | None = None,
    after_fence: bool = False,
    before_image_fence: bool = False,
) -> None:
    while True:
        observation = _observe_slot_use_once(
            slot_path,
            record,
            use_lsof=use_lsof,
            ignore_invoking_ancestry=ignore_invoking_ancestry,
            census=census,
            fallback_census=fallback_census,
            proc_root=proc_root,
            ignore_current_process=ignore_current_process,
            capture_generation=live_use_recheck is not None,
            **_agent_batch_use_check(
                agent_batch,
                canonical_path,
                after_fence=after_fence,
                before_image_fence=before_image_fence,
            ),
        )
        if observation is None:
            return
        if live_use_recheck is not None and live_use_recheck.wait_for_exit(
            observation.pid,
            start_ticks=observation.start_ticks,
            proc_root=observation.proc_root,
            revalidate=observation.revalidate,
        ):
            continue
        raise observation.refusal


def _observe_slot_use_once(
    slot_path: Path,
    record: ActiveRecord | None = None,
    *,
    use_lsof: bool = True,
    ignore_invoking_ancestry: bool = False,
    census: _ProcessPathCensus | None = None,
    fallback_census: _ProcessPathCensus | None = None,
    proc_root: Path = Path("/proc"),
    ignore_current_process: bool = True,
    capture_generation: bool = False,
    agent_batch: _AgentRemoveBatchContext | None = None,
    canonical_path: Path | None = None,
    after_fence: bool = False,
    before_image_fence: bool = False,
) -> _LiveUseObservation | None:
    try:
        current_directory = Path.cwd().resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"cannot establish the current working directory: {exc}") from exc
    if _path_is_within(current_directory, slot_path):
        raise Refusal(
            f"the wrkslots process is running from inside slot {slot_path}; change directory and retry"
        )
    if agent_batch is not None:
        if (
            census is not None
            or fallback_census is not None
            or not use_lsof
            or ignore_invoking_ancestry
            or proc_root != Path("/proc")
            or not ignore_current_process
        ):
            raise StateError(
                "an agent removal batch replaces only the ordinary lsof process check"
            )
        if before_image_fence:
            return agent_batch.observe_image_before_fence(
                slot_path,
                record,
                canonical_path=slot_path if canonical_path is None else canonical_path,
                capture_generation=capture_generation,
            )
        if after_fence:
            if canonical_path is None:
                raise StateError(
                    "an agent removal batch check after the path fence must name "
                    "the canonical slot path"
                )
            return agent_batch.observe_fenced(
                slot_path,
                record,
                canonical_path=canonical_path,
                capture_generation=capture_generation,
            )
        return agent_batch.observe(
            slot_path,
            record,
            canonical_path=slot_path if canonical_path is None else canonical_path,
            capture_generation=capture_generation,
        )
    if census is not None:
        census.assert_slot_unused(
            slot_path,
            record,
            ignore_invoking_ancestry=ignore_invoking_ancestry,
            ignore_current_process=ignore_current_process,
        )
        return None
    lsof = next(
        (
            candidate
            for candidate in (Path("/usr/bin/lsof"), Path("/usr/sbin/lsof"))
            if candidate.is_file() and os.access(candidate, os.X_OK)
        ),
        None,
    )
    direct_use_proven_absent = False
    if lsof is not None and use_lsof:
        evidence, malformed_lsof, lsof_returncode = _lsof_slot_use(lsof, slot_path)
        if evidence is not None:
            refusal = Refusal(
                f"live process {evidence.pid} uses slot {slot_path}"
                f"{_format_lsof_use_diagnostic(evidence, malformed=malformed_lsof)}; "
                "stop it and retry"
            )
            if not _lsof_use_is_recheckable(
                evidence,
                malformed=malformed_lsof,
                returncode=lsof_returncode,
            ):
                raise refusal
            lsof_start_ticks: int | None = None
            lsof_revalidate: Callable[[], bool] | None = None
            if capture_generation:
                try:
                    generation = _read_process_stat(Path("/proc") / str(evidence.pid))
                except Refusal:
                    generation = None
                lsof_start_ticks = (
                    None if generation is None else generation.start_ticks
                )
                evidence_pid = evidence.pid

                def revalidate_lsof_use() -> bool:
                    try:
                        rechecked, rechecked_malformed, rechecked_returncode = (
                            _lsof_slot_use(lsof, slot_path)
                        )
                    except Refusal:
                        return False
                    return (
                        rechecked is not None
                        and rechecked.pid == evidence_pid
                        and _lsof_use_is_recheckable(
                            rechecked,
                            malformed=rechecked_malformed,
                            returncode=rechecked_returncode,
                        )
                    )

                lsof_revalidate = revalidate_lsof_use
            return _LiveUseObservation(
                evidence.pid,
                lsof_start_ticks,
                Path("/proc"),
                refusal,
                lsof_revalidate,
            )
        direct_use_proven_absent = True
    try:
        pid_dirs = [path for path in proc_root.iterdir() if path.name.isdigit()]
    except OSError as exc:
        raise Refusal(f"cannot inspect live processes: {exc}") from exc
    current_pid = os.getpid()
    invoking_ancestry: set[int] = set()
    if ignore_invoking_ancestry:
        ancestor: int | None = current_pid
        for _ in range(256):
            if ancestor is None or ancestor in invoking_ancestry:
                break
            invoking_ancestry.add(ancestor)
            ancestor = _read_process_parent(ancestor)
    mount_verdicts = _MountTableVerdicts(slot_path)
    indeterminate_use: Refusal | None = None
    reported_use: _LiveUseObservation | None = None
    reported_use_recheckable = True
    # Resolved once: it describes the record, not the process being inspected,
    # and asking per PID would read the owner's /proc entry thousands of times.
    owner_cgroup_is_evidence = _owner_cgroup_is_evidence(record)
    for pid_dir in sorted(pid_dirs, key=lambda item: int(item.name)):
        pid = int(pid_dir.name)
        if pid == current_pid or pid in invoking_ancestry:
            continue
        start_ticks: int | None = None
        if capture_generation:
            try:
                generation = _read_process_stat(pid_dir)
            except Refusal:
                generation = None
            start_ticks = None if generation is None else generation.start_ticks
        try:
            uids = _process_uids(pid_dir)
        except Refusal:
            if reported_use is None:
                raise
            reported_use_recheckable = False
            continue
        if uids is None:
            continue
        if owner_cgroup_is_evidence and record is not None and record.owner is not None:
            try:
                cgroup = _read_process_cgroup(pid_dir)
            except Refusal as exc:
                cgroup_refusal = Refusal(
                    f"recorded cgroup use is indeterminate for PID {pid}: {exc}"
                )
                if reported_use is None:
                    raise cgroup_refusal from exc
                reported_use_recheckable = False
                continue
            if cgroup == record.owner.cgroup_path:
                cgroup_refusal = Refusal(
                    f"live process {pid} remains in recorded owner cgroup {cgroup}"
                )
                if reported_use is None:
                    raise cgroup_refusal
                reported_use_recheckable = False
                continue
        filesystem_uid = uids[3]
        if (
            not use_lsof
            and fallback_census is not None
            and filesystem_uid != os.getuid()
        ):
            continue
        try:
            if direct_use_proven_absent:
                mount_namespace = _mount_namespace(pid_dir)
                if mount_namespace is None:
                    uses = []
                else:
                    uses = mount_verdicts.uses(pid_dir)
            else:
                uses = _process_uses_slot(
                    pid_dir, slot_path, mount_verdicts=mount_verdicts
                )
        except Refusal as exc:
            if indeterminate_use is None:
                indeterminate_use = exc
            continue
        if uses:
            refusal = Refusal(
                f"live process {pid} uses slot {slot_path}: {uses[0]}; stop it and retry"
            )
            if not capture_generation:
                raise refusal
            if start_ticks is None:
                reported_use_recheckable = False
            if reported_use is None:
                reported_use = _LiveUseObservation(
                    pid,
                    start_ticks,
                    proc_root,
                    refusal,
                )
    if reported_use is not None:
        if indeterminate_use is not None or not reported_use_recheckable:
            return dataclasses.replace(reported_use, start_ticks=None)
        return reported_use
    if indeterminate_use is not None:
        if not use_lsof and fallback_census is not None:
            raise indeterminate_use
        if not use_lsof:
            return _observe_slot_use_once(
                slot_path,
                record,
                use_lsof=True,
                ignore_invoking_ancestry=ignore_invoking_ancestry,
                proc_root=proc_root,
                ignore_current_process=ignore_current_process,
                capture_generation=capture_generation,
            )
        raise indeterminate_use
    return None


def _parse_timestamp(value: str, label: str) -> dt.datetime:
    try:
        parsed = dt.datetime.fromisoformat(value)
    except ValueError as exc:
        raise StateError(f"invalid timestamp in {label}: {value!r}") from exc
    if parsed.tzinfo is None:
        raise StateError(f"timestamp in {label} must include a time zone")
    return parsed


def _heartbeat_diagnosis(record: ActiveRecord) -> tuple[float, bool]:
    stamp = _parse_timestamp(record.heartbeat_at, f"slot {record.slot} heartbeat")
    age = max(0.0, (dt.datetime.now(dt.timezone.utc) - stamp).total_seconds())
    return age, age > record.heartbeat_ttl_seconds


def _assert_record_paths(
    config: Config,
    record: ActiveRecord,
    *,
    require_repository: bool = True,
) -> None:
    expected_slot = _slot_directory(config, record.slot, record.slot_type)
    if require_repository:
        _ensure_no_symlink_components(config.root, expected_slot, "slot")
    layout = _record_layout(config, record)
    if layout == "flat" and len(record.checkouts) != 1:
        raise StateError(f"slot {record.slot} has multiple checkouts under flat layout")
    for checkout in record.checkouts:
        if checkout.landed_ref != _landed_ref_for_remote(config, checkout.remote):
            raise StateError(
                f"slot {record.slot} checkout {checkout.name} differs from configured authority"
            )
        if require_repository:
            expected_relative, expected_absolute = _checkout_path_for_layout(
                config, record.slot, checkout.name, record.slot_type, layout
            )
        else:
            expected_absolute = (
                expected_slot if layout == "flat" else expected_slot / checkout.name
            )
            expected_relative = expected_absolute.relative_to(config.root).as_posix()
        if checkout.path != expected_relative:
            raise StateError(
                f"slot {record.slot} checkout {checkout.name} path does not match its slot: "
                f"{checkout.path!r} != {expected_relative!r}"
            )
        actual = (
            _stored_path(config, checkout.path, "checkout path")
            if require_repository
            else _stored_path_reference(config, checkout.path, "checkout path")
        )
        if actual != expected_absolute:
            raise StateError(f"slot {record.slot} checkout path identity changed")
        if require_repository:
            _stored_repository_path(config, checkout.repository)
        else:
            _stored_repository_reference(config, checkout.repository)


def _assert_checkout_identity_unchanged(
    config: Config, checkout: Checkout, vcs: _GitVcs
) -> None:
    path = _stored_path(config, checkout.path, "checkout path")
    _relative, repository = _stored_repository_path(config, checkout.repository)
    head = vcs.verify_existing_worktree(repository, path)
    branch = vcs.branch(path)
    remote_url_sha256 = vcs.remote_url_sha256(path, checkout.remote)
    if (
        head != checkout.head
        or branch != checkout.branch
        or remote_url_sha256 != checkout.remote_url_sha256
    ):
        raise Refusal(
            f"checkout {checkout.name} identity changed before state publication; "
            "preserve it for inspection"
        )


def _unpushed_evidence(
    checkout: Checkout, path: Path, head: str, vcs: _GitVcs
) -> dict[str, object]:
    same_named_ref = f"refs/remotes/{checkout.remote}/{checkout.branch}"
    exists = vcs.ref_exists(path, same_named_ref)
    command: str | None = None
    touched = vcs.commit_paths(path, head)
    if exists:
        command = shlex.join(
            [
                "git",
                "--literal-pathspecs",
                "-C",
                str(path),
                "diff",
                head,
                same_named_ref,
                "--",
                *touched,
            ]
        )
    return {
        "same_named_remote_ref": same_named_ref if exists else None,
        "touched_files": list(touched),
        "diagnostic_command": command,
    }


def _unpushed_refusal(checkout: Checkout, path: Path, head: str, vcs: _GitVcs) -> str:
    evidence = _unpushed_evidence(checkout, path, head, vcs)
    same_named_ref = evidence["same_named_remote_ref"]
    base = (
        f"checkout {checkout.name} HEAD {head} is not reachable from any "
        f"refs/remotes/{checkout.remote}/* ref"
    )
    if same_named_ref is None:
        return (
            f"{base}. A same-named remote ref does not exist; publish the branch before finishing"
        )
    command = _as_str(evidence["diagnostic_command"], "unpushed diagnostic command")
    return (
        f"{base}. Same-named remote ref {same_named_ref} exists, so there are two "
        "opposite readings: this commit is genuinely unpushed, or the remote branch "
        "was rebased and this local tip is stale. Do not force-push based on this "
        f"refusal. Run `{command}`; empty output means the touched content is already "
        "present at the remote tip"
    )


def _assert_cache_policy_untracked_path(
    config: Config,
    checkout_name: str,
    path: Path,
    vcs: _GitVcs,
    cache_globs: Sequence[str],
) -> None:
    if not cache_globs:
        return
    tracked = vcs.tracked_cache_paths(path, cache_globs)
    if tracked:
        raise Refusal(
            f"configured cache policy for checkout {checkout_name} overlaps tracked source "
            f"at {tracked[0]}; narrow cache_globs before cleanup or finish"
        )
    for submodule in vcs.submodule_paths(path):
        submodule_parts = Path(submodule).parts
        for pattern in cache_globs:
            pattern_parts = Path(pattern).parts
            wildcard_index = next(
                (
                    index
                    for index, part in enumerate(pattern_parts)
                    if any(character in part for character in "*?[")
                ),
                len(pattern_parts),
            )
            literal_prefix = pattern_parts[:wildcard_index]
            if wildcard_index == len(pattern_parts):
                overlaps = (
                    submodule_parts[: len(pattern_parts)] == pattern_parts
                    or pattern_parts[: len(submodule_parts)] == submodule_parts
                )
            else:
                overlaps = (
                    submodule_parts[: len(literal_prefix)] == literal_prefix
                    or literal_prefix[: len(submodule_parts)] == submodule_parts
                )
            if overlaps:
                raise Refusal(
                    f"configured cache policy for checkout {checkout_name} may cross "
                    f"Git submodule {submodule}; configure that repository separately"
                )


def _assert_cache_policy_untracked(
    config: Config, checkout: Checkout, vcs: _GitVcs
) -> None:
    path = _stored_path(config, checkout.path, "checkout path")
    _assert_cache_policy_untracked_path(
        config, checkout.name, path, vcs, _cache_globs_for(config, checkout.name)
    )


def _assert_checkout_safe(
    config: Config,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    refresh_remote: bool = True,
) -> Checkout:
    path = _stored_path(config, checkout.path, "checkout path")
    _relative, repository = _stored_repository_path(config, checkout.repository)
    head = vcs.verify_existing_worktree(repository, path)
    branch = vcs.branch(path)
    if branch != checkout.branch:
        raise Refusal(
            f"checkout {checkout.name} branch changed: expected {checkout.branch}, found {branch}"
        )
    operation_paths = vcs.operation_paths(path)
    if operation_paths:
        raise Refusal(
            f"checkout {checkout.name} has an unfinished Git operation: {operation_paths[0]}"
        )
    vcs.assert_ordinary_history(path)
    vcs.assert_ordinary_index(path)
    _assert_cache_policy_untracked_path(
        config,
        checkout.name,
        path,
        vcs,
        _cache_globs_for(config, checkout.name),
    )
    status = vcs.status(path, _cache_globs_for(config, checkout.name))
    if status:
        first = status.splitlines()[0]
        raise Refusal(
            f"checkout {checkout.name} is dirty or has untracked/ignored files ({first}); "
            "commit intended work and publish it before finishing; keep a handoff "
            "out of commits (use write-handoff)"
        )
    remote_authority = vcs.remote_authority(path, checkout.remote)
    if remote_authority.sha256 != checkout.remote_url_sha256:
        raise Refusal(
            f"checkout {checkout.name} remote {checkout.remote} URL changed; "
            "preserve the checkout for inspection"
        )
    if refresh_remote:
        vcs.fetch_remote(
            path, checkout.remote, checkout.landed_ref, remote_authority
        )
        vcs.assert_remote_authority(path, checkout.remote, remote_authority)
    remote_refs = vcs.remote_refs_containing(path, checkout.remote, head)
    if not remote_refs:
        raise Refusal(_unpushed_refusal(checkout, path, head, vcs))
    if not vcs.is_ancestor(path, head, checkout.landed_ref):
        raise Refusal(
            f"checkout {checkout.name} HEAD {head} is not an ancestor of configured landed ref "
            f"{checkout.landed_ref}; no PR label or status substitutes for ancestry"
        )
    return dataclasses.replace(
        checkout,
        head=head,
        containing_remote_refs=remote_refs,
    )


def _salvage_pathspecs(config: Config, checkout_name: str) -> list[str]:
    # A handoff is a private note to the next agent, not work: salvage never
    # stages one. Removal preserves handoffs before salvage runs (read-handoff
    # sidecar, or the retained copy beside the registry).
    pathspecs = [".", ":(exclude,glob)HANDOFF*", ":(exclude,glob)**/HANDOFF*"]
    for pattern in _cache_globs_for(config, checkout_name):
        pathspecs.append(f":(exclude,glob){pattern}")
        pathspecs.append(f":(exclude,glob){pattern}/**")
    return pathspecs


def _local_salvage_archive_root(config: Config, raw: str | None) -> Path | None:
    """Validate the operator-owned root for local salvage bundles.

    The root is either the explicit --salvage-archive-root or the default, the
    wrkslots control directory (bundles go under its wrkslots-salvage/).
    """
    if raw is None:
        return None
    root = Path(raw)
    if not root.is_absolute() or ".." in root.parts:
        raise Refusal("--salvage-archive-root must be an absolute path without '..'")
    root = Path(os.path.normpath(str(root)))
    if root == Path("/"):
        raise Refusal("--salvage-archive-root must not be the filesystem root")
    current = Path("/")
    for part in root.parts[1:]:
        current /= part
        try:
            metadata = current.stat(follow_symlinks=False)
        except OSError as exc:
            raise Refusal(
                f"--salvage-archive-root must already exist as a real directory: {root}: {exc}"
            ) from exc
        if stat.S_ISLNK(metadata.st_mode):
            raise Refusal(f"--salvage-archive-root crosses a symlink: {current}")
    if not root.is_dir():
        raise Refusal(f"--salvage-archive-root is not a directory: {root}")
    root_metadata = root.stat(follow_symlinks=False)
    if root_metadata.st_uid != os.getuid() or root_metadata.st_mode & 0o022:
        raise Refusal(
            "--salvage-archive-root must be owned by the current user and not group/world writable"
        )
    if root != config.control and (
        _path_is_within(root, config.root) or _path_is_within(config.root, root)
    ):
        raise Refusal(
            "--salvage-archive-root must be separate from the managed project tree"
        )
    return root


def _default_salvage_archive_root(config: Config) -> Path:
    """The control directory: local salvage bundles stay beside the registry."""
    try:
        root = _local_salvage_archive_root(config, str(config.control))
    except Refusal as exc:
        raise Refusal(
            f"cannot use the default local salvage archive root {config.control}: {exc}; "
            "pass --salvage-archive-root DIR, or list the remote in salvage_push_remotes"
        ) from exc
    assert root is not None
    return root


def _salvage_push_allowed(config: Config, authority: _RemoteAuthority) -> bool:
    """Whether salvage may push to this remote (configuration.salvage_push_remotes)."""
    return any(
        _same_repository_remote(allowed, authority.url)
        for allowed in config.salvage_push_remotes
    )


def _sha256_regular_file(path: Path, label: str) -> tuple[str, int]:
    """Hash a stable regular file without following a replacement symlink."""
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise Refusal(f"cannot open {label} {path}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise Refusal(f"{label} is not a regular file: {path}")
        digest = hashlib.sha256()
        size = 0
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            size += len(chunk)
        after = os.fstat(descriptor)
        path_after = path.stat(follow_symlinks=False)
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    finally:
        os.close(descriptor)
    stable = ("st_dev", "st_ino", "st_mode", "st_size", "st_mtime_ns", "st_ctime_ns")
    if any(getattr(before, field) != getattr(after, field) for field in stable) or any(
        getattr(after, field) != getattr(path_after, field) for field in stable
    ):
        raise Refusal(f"{label} changed while it was read: {path}")
    if size != after.st_size:
        raise Refusal(f"{label} size changed while it was read: {path}")
    return digest.hexdigest(), size


def _local_salvage_paths(
    archive_root: Path,
    machine: str,
    slot: str,
    generation: int | None,
    checkout: Checkout,
    commit: str,
) -> tuple[Path, Path, str]:
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "-", checkout.name).strip("-.") or "checkout"
    name_digest = hashlib.sha256(checkout.name.encode("utf-8")).hexdigest()[:12]
    # An ownerless worktree has no registry generation.
    epoch = "ownerless" if generation is None else str(generation)
    directory = (
        archive_root
        / _LOCAL_SALVAGE_DIRECTORY
        / machine
        / slot
        / epoch
        / f"{safe_name}-{name_digest}-{commit[:12]}"
    )
    ref = (
        f"refs/heads/{_LOCAL_SALVAGE_DIRECTORY}/{machine}/{slot}/"
        f"{epoch}/{safe_name}-{name_digest}"
    )
    _validate_full_ref(ref, "local salvage archive ref")
    return directory / "repository.bundle", directory / "receipt.json", ref


def _prepare_local_salvage_directory(root: Path, directory: Path) -> None:
    """Create private archive descendants and reject unsafe pre-existing ones."""
    relative = directory.relative_to(root)
    current = root
    for part in relative.parts:
        current /= part
        try:
            current.mkdir(mode=0o700)
        except FileExistsError:
            pass
        except OSError as exc:
            raise Refusal(f"cannot create local salvage archive directory {current}: {exc}") from exc
        metadata = current.stat(follow_symlinks=False)
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_mode & 0o022
        ):
            raise Refusal(
                f"local salvage archive directory is not private current-user storage: {current}"
            )


def _verify_local_salvage_bundle(
    bundle: Path,
    expected_sha256: str,
    expected_size: int,
    archive_ref: str,
    commit: str,
    vcs: _GitVcs,
) -> None:
    observed_digest, observed_size = _sha256_regular_file(bundle, "local salvage bundle")
    if (observed_digest, observed_size) != (expected_sha256, expected_size):
        raise Refusal(f"local salvage bundle changed after publication: {bundle}")
    verified = _VERIFIED_SALVAGE_BUNDLES.get()
    # The same bytes verify the same way wherever they are linked.
    key = (f"{archive_ref}\0{commit}", observed_digest, observed_size)
    if verified is not None and key in verified:
        return
    # Restored beside the bundle, never in the system temporary directory:
    # a bundle holds a checkout's complete history, which can be gigabytes.
    with tempfile.TemporaryDirectory(
        prefix=".wrkslots-archive-verify-", dir=str(bundle.parent)
    ) as temporary:
        root = Path(temporary)
        restored = root / "restored.git"
        vcs._run(root, ["clone", "--bare", "--", str(bundle), str(restored)])
        restored_commit = vcs._run(
            restored, ["rev-parse", "--verify", archive_ref]
        ).stdout.strip()
        if restored_commit != commit:
            raise Refusal(
                f"local salvage bundle ref {archive_ref} names {restored_commit}, not {commit}"
            )
        vcs._run(restored, ["cat-file", "-e", f"{commit}^{{tree}}"])
        vcs._run(restored, ["fsck", "--full", "--strict", "--no-dangling"])
    if verified is not None:
        verified.add(key)


def _local_salvage_receipt_payload(
    archive_root: Path,
    bundle: Path,
    archive_ref: str,
    machine: str,
    slot: str,
    generation: int | None,
    checkout: Checkout,
    facts: _SalvageCandidate,
    bundle_sha256: str,
    bundle_size: int,
) -> dict[str, object]:
    return {
        "schema": _LOCAL_SALVAGE_RECEIPT_SCHEMA,
        "kind": "wrkslots-local-salvage-archive",
        "machine": machine,
        "slot": slot,
        "generation": generation,
        "checkout": checkout.name,
        "repository": checkout.repository,
        "remote": checkout.remote,
        "remote_url_sha256": checkout.remote_url_sha256,
        "source_head": facts.head,
        "salvage_commit": facts.commit,
        "status_sha256": facts.status_digest,
        "archive_root": str(archive_root),
        "bundle": str(bundle.relative_to(archive_root)),
        "bundle_sha256": bundle_sha256,
        "bundle_bytes": bundle_size,
        "archive_ref": archive_ref,
        "verification": {
            "fresh_bare_clone": True,
            "exact_ref": True,
            "full_fsck": True,
            "complete_history": True,
        },
    }


def _ensure_local_salvage_bundle(
    config: Config,
    machine: str,
    slot: str,
    generation: int | None,
    checkout: Checkout,
    path: Path,
    facts: _SalvageCandidate,
    archive_root: Path,
    vcs: _GitVcs,
) -> tuple[Path, Path, Path, str]:
    """Create, unless it exists, and verify the self-contained bundle of ``facts.commit``.

    Returns the checked archive root, the bundle, its receipt path, and the
    archive ref. No receipt is written here; see _archive_salvage_locally.
    """
    checked_root = _local_salvage_archive_root(config, str(archive_root))
    assert checked_root is not None
    bundle, receipt_path, archive_ref = _local_salvage_paths(
        checked_root, machine, slot, generation, checkout, facts.commit
    )
    _prepare_local_salvage_directory(checked_root, bundle.parent)
    _ensure_no_symlink_components(checked_root, bundle.parent, "local salvage archive")

    if not bundle.exists():
        with tempfile.TemporaryDirectory(prefix="wrkslots-bundle-stage-") as temporary:
            stage_root = Path(temporary)
            stage = stage_root / "stage.git"
            temp_bundle = (
                bundle.parent
                / f".{bundle.name}.tmp.{os.getpid()}.{uuid.uuid4().hex}"
            )
            vcs._run(stage_root, ["init", "--bare", "--", str(stage)])
            objects = vcs.common_directory(path) / "objects"
            object_env = {"GIT_OBJECT_DIRECTORY": str(objects)}
            vcs._run(
                stage,
                ["update-ref", archive_ref, facts.commit],
                env_overrides=object_env,
            )
            try:
                vcs._run(
                    stage,
                    ["bundle", "create", str(temp_bundle), archive_ref],
                    env_overrides=object_env,
                )
                descriptor = os.open(temp_bundle, os.O_RDONLY | os.O_CLOEXEC)
                try:
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
                os.chmod(temp_bundle, 0o444)
                temp_digest, temp_size = _sha256_regular_file(
                    temp_bundle, "temporary local salvage bundle"
                )
                _verify_local_salvage_bundle(
                    temp_bundle, temp_digest, temp_size, archive_ref, facts.commit, vcs
                )
                try:
                    os.link(temp_bundle, bundle, follow_symlinks=False)
                    _fsync_directory(bundle.parent)
                except FileExistsError:
                    pass
            finally:
                with contextlib.suppress(FileNotFoundError):
                    temp_bundle.unlink()
    return checked_root, bundle, receipt_path, archive_ref


def _archive_salvage_locally(
    config: Config,
    machine: str,
    slot: str,
    generation: int | None,
    checkout: Checkout,
    path: Path,
    facts: _SalvageCandidate,
    archive_root: Path,
    remote_failure: Refusal | None,
    vcs: _GitVcs,
) -> dict[str, object]:
    """Create and read back a self-contained bundle instead of a remote push.

    ``remote_failure`` is None when the remote is not in salvage_push_remotes,
    so nothing was pushed; otherwise it is the refused push, or the initial
    fetch's transport failure, so remote salvage did not complete.
    """
    checked_root, bundle, receipt_path, archive_ref = _ensure_local_salvage_bundle(
        config, machine, slot, generation, checkout, path, facts, archive_root, vcs
    )

    bundle_digest, bundle_size = _sha256_regular_file(bundle, "local salvage bundle")
    _verify_local_salvage_bundle(
        bundle, bundle_digest, bundle_size, archive_ref, facts.commit, vcs
    )
    expected_receipt = _local_salvage_receipt_payload(
        checked_root,
        bundle,
        archive_ref,
        machine,
        slot,
        generation,
        checkout,
        facts,
        bundle_digest,
        bundle_size,
    )
    if receipt_path.exists() or receipt_path.is_symlink():
        contents = _read_bounded_regular_file(
            receipt_path,
            "local salvage archive receipt",
            _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
        )
        observed = _strict_json_object(contents, "local salvage archive receipt")
        if not _json_equal(observed, expected_receipt):
            raise Refusal(
                f"local salvage archive receipt disagrees with the current checkout: {receipt_path}"
            )
    else:
        _atomic_write_json(receipt_path, expected_receipt)
        contents = _read_bounded_regular_file(
            receipt_path,
            "local salvage archive receipt",
            _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
        )
        if not _json_equal(
            _strict_json_object(contents, "local salvage archive receipt"),
            expected_receipt,
        ):
            raise Refusal(f"local salvage archive receipt readback failed: {receipt_path}")
    receipt_sha256 = hashlib.sha256(contents).hexdigest()
    _interrupt_for_test("after-local-salvage-archive")
    reason = (
        f"remote {checkout.remote} is not in salvage_push_remotes"
        if remote_failure is None
        else "remote salvage did not complete"
    )
    print(
        f"WARNING: {reason} for checkout {checkout.name}; "
        f"using verified local archive {bundle}",
        file=sys.stderr,
    )
    return {
        "checkout": checkout.name,
        "source_head": facts.head,
        "salvage_commit": facts.commit,
        "status_sha256": facts.status_digest,
        "disposition": "archived-local",
        "remote_ref": None,
        "containing_remote_refs": [],
        "archive_root": str(checked_root),
        "archive_receipt": str(receipt_path),
        "archive_receipt_sha256": receipt_sha256,
        "archive_bundle": str(bundle),
        "archive_bundle_sha256": bundle_digest,
        "archive_bundle_bytes": bundle_size,
        "archive_ref": archive_ref,
        "complete_history": True,
        "remote_failure": None if remote_failure is None else str(remote_failure),
        "archive_reason": (
            "remote-not-allowed" if remote_failure is None else "remote-refused"
        ),
        "destination": str(bundle),
    }


def _assert_local_salvage_receipt(
    config: Config,
    machine: str,
    slot: str,
    generation: int | None,
    checkout: Checkout,
    facts: _SalvageCandidate,
    salvage: Mapping[str, object],
    vcs: _GitVcs,
) -> None:
    root = _local_salvage_archive_root(
        config,
        _as_str(salvage.get("archive_root"), "salvage receipt.archive_root"),
    )
    assert root is not None
    bundle, receipt_path, archive_ref = _local_salvage_paths(
        root, machine, slot, generation, checkout, facts.commit
    )
    if _as_str(
        salvage.get("archive_receipt"), "salvage receipt.archive_receipt"
    ) != str(receipt_path):
        raise Refusal("local salvage receipt path does not match its bound checkout")
    if _as_str(
        salvage.get("archive_bundle"), "salvage receipt.archive_bundle"
    ) != str(bundle):
        raise Refusal("local salvage bundle path does not match its bound checkout")
    if _as_str(salvage.get("archive_ref"), "salvage receipt.archive_ref") != archive_ref:
        raise Refusal("local salvage archive ref does not match its bound checkout")
    receipt_contents = _read_bounded_regular_file(
        receipt_path,
        "local salvage archive receipt",
        _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
    )
    receipt_digest = hashlib.sha256(receipt_contents).hexdigest()
    if receipt_digest != _as_str(
        salvage.get("archive_receipt_sha256"),
        "salvage receipt.archive_receipt_sha256",
    ):
        raise Refusal(f"local salvage archive receipt changed: {receipt_path}")
    bundle_digest = _as_str(
        salvage.get("archive_bundle_sha256"), "salvage receipt.archive_bundle_sha256"
    )
    bundle_size = _as_int(
        salvage.get("archive_bundle_bytes"),
        "salvage receipt.archive_bundle_bytes",
        minimum=1,
    )
    expected_receipt = _local_salvage_receipt_payload(
        root,
        bundle,
        archive_ref,
        machine,
        slot,
        generation,
        checkout,
        facts,
        bundle_digest,
        bundle_size,
    )
    observed_receipt = _strict_json_object(
        receipt_contents, "local salvage archive receipt"
    )
    if not _json_equal(observed_receipt, expected_receipt):
        raise Refusal(
            f"local salvage archive receipt no longer binds the current checkout: {receipt_path}"
        )
    if salvage.get("complete_history") is not True:
        raise StateError("local salvage receipt does not assert complete history")
    _verify_local_salvage_bundle(
        bundle, bundle_digest, bundle_size, archive_ref, facts.commit, vcs
    )


@dataclasses.dataclass(frozen=True)
class _SalvageCandidate:
    head: str
    status_digest: str
    commit: str
    dirty: bool
    remote_authority: _RemoteAuthority
    # Where publication is judged when that is not remote_authority: a
    # submodule whose remote is its source repository's own Git directory is
    # judged at that source's remote (see _submodule_network_authority).
    network_authority: _RemoteAuthority | None = None
    # The shallow file of a submodule repository that was let through
    # (_salvage_candidate's allow_shallow); see _shallow_history_refusal.
    shallow: Path | None = None

    @property
    def aliased(self) -> bool:
        """Whether publication is judged at a remote other than the checkout's own."""
        return (
            self.network_authority is not None
            and self.network_authority != self.remote_authority
        )


def _shallow_history_refusal(facts: _SalvageCandidate) -> Refusal:
    """The refusal for a shallow checkout whose HEAD is not already published, clean.

    A shallow repository holds no history below its boundary, so no bundle
    of it is complete and nothing can be pushed from it soundly. Its HEAD is
    preserved only when a remote branch already contains it and nothing in
    the checkout differs from it; anything else refuses, as every shallow
    checkout used to.
    """

    return Refusal(f"checkout uses shallow history: {facts.shallow}")


_EMPTY_STATUS_SHA256 = hashlib.sha256(b"").hexdigest()


def _repository_config_sha256(vcs: _GitVcs, repository: Path) -> str:
    """Digest of every configuration value Git applies in ``repository``, with its origin."""

    listed = vcs._run_bytes(
        repository,
        ["config", "--list", "--null", "--show-origin", "--show-scope"],
        timeout_seconds=_REMOTE_CONTAINMENT_LIST_SECONDS,
        timeout_refusal=(
            f"Git did not list the configuration of {repository} within "
            f"{_REMOTE_CONTAINMENT_LIST_SECONDS:g} seconds; nothing was removed"
        ),
    )
    if listed.returncode != 0:
        raise Refusal(
            f"cannot read the Git configuration of {repository}"
            + _git_bytes_failure_detail(listed)
        )
    fields = listed.stdout.split(b"\0")
    if fields and fields[-1] == b"":
        fields.pop()
    # Each value is three fields: scope, origin, and "key\nvalue".
    if len(fields) % 3:
        raise Refusal(f"Git returned a malformed configuration listing for {repository}")
    digest = hashlib.sha256()
    for scope, origin, entry in zip(fields[0::3], fields[1::3], fields[2::3]):
        # Command-scope values are this invocation's own -c settings and those
        # a Git wrapper adds per command (a request correlator, for one), not
        # state of the repository or of the files Git reads.
        if scope == b"command":
            continue
        digest.update(scope + b"\0" + origin + b"\0" + entry + b"\0")
    return digest.hexdigest()


def _path_state(path: Path) -> tuple[int, int, int, int, int] | None:
    """Device, inode, size, mtime and ctime (ns) of ``path`` itself, or None if absent."""

    try:
        observed = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise Refusal(f"cannot inspect {path}: {exc}") from exc
    return (
        observed.st_dev,
        observed.st_ino,
        observed.st_size,
        observed.st_mtime_ns,
        observed.st_ctime_ns,
    )


# The positions in a _salvage_fingerprint of the two entries that describe the
# local mirror a submodule's remote names, known only once its facts are.
_FINGERPRINT_MIRROR_FIELDS = (12, 13)


def _fingerprint_without_mirror(fingerprint: tuple[object, ...]) -> tuple[object, ...]:
    return tuple(
        value
        for index, value in enumerate(fingerprint)
        if index not in _FINGERPRINT_MIRROR_FIELDS
    )


def _salvage_fingerprint(
    config: Config,
    checkout: Checkout,
    path: Path,
    vcs: _GitVcs,
    *,
    source: Path | None,
    mirror: Path | None,
) -> tuple[object, ...]:
    """Read cheaply what _salvage_candidate's answer for a clean checkout depends on.

    That is the worktree root and Git directories, HEAD and the branch, every
    configuration value (remote URLs, push URLs and URL rewrites among them)
    of the checkout and, for a submodule, of its source repository and of the
    local mirror its remote names, the index file's identity and times
    (assume-unchanged and skip-worktree bits, staged content), the status
    _salvage_candidate digests, unfinished operations, and grafts, shallow
    boundaries and replacement refs. The status is read without refreshing
    the index, so reading it does not itself change the index.
    """

    # One rev-parse names the worktree root, both Git directories, the index,
    # each unfinished-operation path (_GitVcs.operation_paths), HEAD's commit
    # (_GitVcs.head) and the ref HEAD names, or "HEAD" when it is detached.
    names = _GIT_OPERATION_STATE_NAMES
    arguments = [
        "rev-parse",
        "--path-format=absolute",
        "--show-toplevel",
        "--git-dir",
        "--git-common-dir",
        "--git-path",
        "index",
    ]
    for name in names:
        arguments.extend(("--git-path", name))
    arguments.extend(("HEAD^{commit}", "--symbolic-full-name", "HEAD"))
    located = vcs._run(path, arguments).stdout.splitlines()
    if len(located) != 6 + len(names):
        raise Refusal(f"Git returned an incomplete location inventory for {path}")
    toplevel, git_directory, common, index = located[:4]
    operations = located[4 : 4 + len(names)]
    head, branch = located[4 + len(names) :]
    if not SHA_RE.fullmatch(head):
        raise Refusal(f"checkout HEAD is not a full commit: {path}")
    common_path = Path(common)
    replacements = vcs._run(
        path, ["for-each-ref", "--format=%(refname) %(objectname)", "refs/replace/"]
    ).stdout
    return (
        toplevel,
        git_directory,
        common,
        head,
        branch,
        tuple(_path_state(Path(operation)) for operation in operations),
        _path_state(common_path / "info" / "grafts"),
        _path_state(common_path / "shallow"),
        replacements,
        _path_state(Path(index)),
        _repository_config_sha256(vcs, path),
        None if source is None else _repository_config_sha256(vcs, source),
        # _FINGERPRINT_MIRROR_FIELDS: these two must stay at that position.
        None if mirror is None else _repository_config_sha256(vcs, mirror),
        None if mirror is None else _path_state(mirror),
        hashlib.sha256(
            vcs.status(
                path,
                _cache_globs_for(config, checkout.name),
                include_ignored=False,
                refresh_index=False,
            ).encode("utf-8")
        ).hexdigest(),
    )


def _salvage_fingerprint_or_none(
    config: Config,
    checkout: Checkout,
    path: Path,
    vcs: _GitVcs,
    *,
    source: Path | None,
    mirror: Path | None,
) -> tuple[object, ...] | None:
    """_salvage_fingerprint, or None when it cannot be read.

    The facts are then derived in full, and any refusal is the one that
    derivation gives.
    """

    try:
        return _salvage_fingerprint(
            config, checkout, path, vcs, source=source, mirror=mirror
        )
    except Refusal:
        return None


def _salvage_candidate(
    config: Config,
    record: ActiveRecord | None,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
    allow_detached: bool = False,
    verify_repository_membership: bool = True,
    ownerless_slot: str | None = None,
    ownerless_recorded_at: str | None = None,
    allow_shallow: bool = False,
) -> _SalvageCandidate:
    """Return HEAD, status digest, durable commit candidate, and dirty state.

    See _salvage_candidate_uncached. While an agent-slot removal runs
    (_SALVAGE_FACTS_MEMO), the facts of a clean checkout are derived once and
    returned again while _salvage_fingerprint shows the checkout unchanged.
    """

    memo = _SALVAGE_FACTS_MEMO.get()
    if memo is None or record is None or ownerless_slot is not None:
        return _salvage_candidate_uncached(
            config,
            record,
            checkout,
            vcs,
            path_override=path_override,
            allow_detached=allow_detached,
            verify_repository_membership=verify_repository_membership,
            ownerless_slot=ownerless_slot,
            ownerless_recorded_at=ownerless_recorded_at,
            allow_shallow=allow_shallow,
        )
    path = path_override or _stored_path(config, checkout.path, "checkout path")
    _relative, repository = _stored_repository_path(config, checkout.repository)
    # Only a submodule candidate is detached; its repository is the source
    # submodule, whose remote decides where publication is judged.
    source = repository if allow_detached else None
    key: tuple[object, ...] = (
        str(path.absolute()),
        repr(checkout),
        allow_detached,
        verify_repository_membership,
        allow_shallow,
        record.machine,
        record.slot,
        record.generation,
        record.heartbeat_at,
        tuple(_cache_globs_for(config, checkout.name)),
    )
    cached = memo.get(key)
    if cached is not None and (
        time.monotonic() - cached.observed_at
        <= _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS
    ):
        mirror = (
            _absolute_local_remote_directory(path, cached.facts.remote_authority)
            if cached.facts.aliased
            else None
        )
        if (
            _salvage_fingerprint_or_none(
                config, checkout, path, vcs, source=source, mirror=mirror
            )
            == cached.fingerprint
        ):
            return cached.facts
    memo.pop(key, None)
    before = _salvage_fingerprint_or_none(
        config, checkout, path, vcs, source=source, mirror=None
    )
    facts = _salvage_candidate_uncached(
        config,
        record,
        checkout,
        vcs,
        path_override=path,
        allow_detached=allow_detached,
        verify_repository_membership=verify_repository_membership,
        allow_shallow=allow_shallow,
    )
    if facts.dirty or facts.status_digest != _EMPTY_STATUS_SHA256:
        return facts
    mirror = (
        _absolute_local_remote_directory(path, facts.remote_authority)
        if facts.aliased
        else None
    )
    if before is None or (facts.aliased and mirror is None):
        return facts
    after = _salvage_fingerprint_or_none(
        config, checkout, path, vcs, source=source, mirror=mirror
    )
    # The mirror's two entries are read only afterwards, once the facts name it.
    if after is not None and _fingerprint_without_mirror(
        before
    ) == _fingerprint_without_mirror(after):
        memo[key] = _SalvageFactsEvidence(facts, after, time.monotonic())
    return facts


def _salvage_candidate_uncached(
    config: Config,
    record: ActiveRecord | None,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
    allow_detached: bool = False,
    verify_repository_membership: bool = True,
    ownerless_slot: str | None = None,
    ownerless_recorded_at: str | None = None,
    allow_shallow: bool = False,
) -> _SalvageCandidate:
    """Return HEAD, status digest, durable commit candidate, and dirty state.

    A temporary index captures tracked and ordinary untracked files outside the
    configured regenerable caches. Gitignored content is never uploaded. The
    temporary index never changes the checkout's branch or ordinary index, so a
    failed push leaves the author's tree untouched.

    ``allow_shallow`` lets a shallow repository through only when its status
    is empty, and records its shallow file in the result; the caller must
    then refuse unless a remote branch already contains HEAD
    (_shallow_history_refusal).
    """

    path = path_override or _stored_path(config, checkout.path, "checkout path")
    _relative, repository = _stored_repository_path(config, checkout.repository)
    if verify_repository_membership:
        head = vcs.verify_existing_worktree(repository, path)
    else:
        if vcs.repository_root(path) != path.absolute():
            raise Refusal(f"nested repository is not rooted at its recorded path: {path}")
        head = vcs.head(path)
    if allow_detached:
        branch_result = vcs._run(
            path, ["symbolic-ref", "--quiet", "--short", "HEAD"], check=False
        )
        if branch_result.returncode not in (0, 1):
            raise Refusal(
                f"cannot determine branch state for checkout {checkout.name}"
                + _git_failure_detail(branch_result)
            )
    else:
        branch = vcs.branch(path)
        if branch != checkout.branch:
            raise Refusal(
                f"checkout {checkout.name} branch changed: expected {checkout.branch}, "
                f"found {branch}; preserve it and update the recorded checkout before reclaim"
            )
    operations = vcs.operation_paths(path)
    if operations:
        raise Refusal(
            f"checkout {checkout.name} has an unfinished Git operation at {operations[0]}; "
            "complete or abort that Git operation before reclaim"
        )
    shallow = vcs.assert_ordinary_history(path, allow_shallow=allow_shallow)
    vcs.assert_ordinary_index(path)
    _assert_cache_policy_untracked_path(
        config,
        checkout.name,
        path,
        vcs,
        _cache_globs_for(config, checkout.name),
    )
    remote_authority = vcs.remote_authority(path, checkout.remote)
    if remote_authority.sha256 != checkout.remote_url_sha256:
        raise Refusal(
            f"checkout {checkout.name} remote {checkout.remote} URL changed; restore the "
            "recorded remote before reclaim so salvage cannot be sent elsewhere"
        )
    # Only a submodule candidate is detached (see _submodule_salvage_checkouts);
    # its repository is the source submodule, never the managed checkout.
    network_authority = (
        _submodule_network_authority(config, checkout, path, vcs, remote_authority)
        if allow_detached
        else None
    )
    status = vcs.status(
        path,
        _cache_globs_for(config, checkout.name),
        include_ignored=False,
    )
    status_digest = hashlib.sha256(status.encode("utf-8")).hexdigest()
    if not status:
        return _SalvageCandidate(
            head=head,
            status_digest=status_digest,
            commit=head,
            dirty=False,
            remote_authority=remote_authority,
            network_authority=network_authority,
            shallow=shallow,
        )
    if shallow is not None:
        # Changed files in a shallow checkout could be kept only in a salvage
        # commit on top of a history the repository does not hold.
        raise Refusal(f"checkout uses shallow history: {shallow}")

    with tempfile.TemporaryDirectory(prefix="wrkslots-salvage-") as temporary:
        index = str(Path(temporary) / "index")
        env = {"GIT_INDEX_FILE": index}
        vcs._run(path, ["read-tree", "HEAD"], env_overrides=env)
        pathspecs = _salvage_pathspecs(config, checkout.name)
        vcs._run(path, ["add", "-u", "--", *pathspecs], env_overrides=env)
        untracked = vcs._run(
            path,
            [
                "ls-files",
                "--others",
                "--exclude-standard",
                "-z",
                "--",
                *pathspecs,
            ],
            env_overrides=env,
        ).stdout
        if untracked:
            # Each listed name is one exact path. Read as a glob pathspec, an
            # untracked file named `*.md` would also stage the excluded
            # HANDOFF.md and cache paths, so the names are matched literally.
            vcs._run(
                path,
                ["add", "--pathspec-from-file=-", "--pathspec-file-nul"],
                input_text=untracked,
                env_overrides={**env, "GIT_LITERAL_PATHSPECS": "1"},
            )
        tree = vcs._run(path, ["write-tree"], env_overrides=env).stdout.strip()
        if not SHA_RE.fullmatch(tree):
            raise Refusal(f"salvage tree for checkout {checkout.name} is not a full Git object")
        head_tree = vcs._run(path, ["rev-parse", f"{head}^{{tree}}"]).stdout.strip()
        if tree == head_tree:
            # Only excluded paths (handoffs) differ from HEAD: nothing to salvage.
            return _SalvageCandidate(
                head=head,
                status_digest=status_digest,
                commit=head,
                dirty=False,
                remote_authority=remote_authority,
                network_authority=network_authority,
            )
        if record is None:
            if ownerless_slot is None or ownerless_recorded_at is None:
                raise StateError("ownerless salvage lacks its slot and recorded time")
            message = (
                f"Salvage ownerless worktree {ownerless_slot}/{checkout.name}\n\n"
                f"source-head: {head}\n"
            )
            recorded_at = ownerless_recorded_at
        else:
            # The registry task text stays in the local record: a salvage
            # commit may be published, so it carries no task description.
            message = (
                f"Salvage {record.slot}/{checkout.name} after recorded owner exit\n\n"
                f"source-head: {head}\n"
            )
            recorded_at = record.heartbeat_at
        identity = {
            "GIT_AUTHOR_NAME": "wrkslots salvage",
            "GIT_AUTHOR_EMAIL": "wrkslots@localhost",
            "GIT_AUTHOR_DATE": recorded_at,
            "GIT_COMMITTER_NAME": "wrkslots salvage",
            "GIT_COMMITTER_EMAIL": "wrkslots@localhost",
            "GIT_COMMITTER_DATE": recorded_at,
        }
        commit = vcs._run(
            path,
            ["commit-tree", tree, "-p", head],
            input_text=message,
            env_overrides=identity,
        ).stdout.strip()
    if not SHA_RE.fullmatch(commit):
        raise Refusal(f"salvage commit for checkout {checkout.name} is not a full Git object")
    return _SalvageCandidate(
        head=head,
        status_digest=status_digest,
        commit=commit,
        dirty=True,
        remote_authority=remote_authority,
        network_authority=network_authority,
    )


def _submodule_salvage_checkouts(
    config: Config,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
) -> tuple[tuple[Checkout, Path], ...]:
    """Return a salvage checkout for each initialized submodule of ``checkout``.

    While an agent-slot removal runs (_SUBMODULE_INVENTORY_MEMO), the answer
    is derived once and returned again while Git lists the same initialized
    submodules and every source submodule directory is the same directory.
    Each submodule's HEAD and remote URL, which the reuse does not reread, are
    reread by the salvage-facts check (_salvage_candidate) every caller makes
    of each returned checkout next, which refuses a remote URL that differs
    from the one recorded here.
    """

    checkout_path = path_override or _stored_path(
        config, checkout.path, "checkout path"
    )
    _repository_relative, source_repository = _stored_repository_path(
        config, checkout.repository
    )
    memo = _SUBMODULE_INVENTORY_MEMO.get()
    if memo is None:
        return _submodule_salvage_checkouts_uncached(
            config, checkout, vcs, checkout_path, source_repository
        )
    key: tuple[object, ...] = (
        repr(checkout),
        str(checkout_path.absolute()),
        str(source_repository),
        config.default_remote,
    )
    inventory = vcs.initialized_submodules(checkout_path)
    cached = memo.get(key)
    if (
        cached is not None
        and cached.inventory == inventory
        and time.monotonic() - cached.observed_at
        <= _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS
    ):
        try:
            sources = _submodule_source_identities(
                config, checkout_path, source_repository, inventory
            )
        except Refusal:
            sources = None
        if sources == cached.sources:
            return cached.result
    memo.pop(key, None)
    result = _submodule_salvage_checkouts_uncached(
        config, checkout, vcs, checkout_path, source_repository, inventory=inventory
    )
    if vcs.initialized_submodules(checkout_path) == inventory:
        memo[key] = _SubmoduleInventoryEvidence(
            result,
            inventory,
            _submodule_source_identities(
                config, checkout_path, source_repository, inventory
            ),
            time.monotonic(),
        )
    return result


def _submodule_source_identities(
    config: Config,
    checkout_path: Path,
    source_repository: Path,
    inventory: Sequence[str],
) -> tuple[tuple[int, int], ...]:
    """Device and inode of each source submodule directory named by ``inventory``.

    Refuses as _submodule_salvage_checkouts does for a symbolic link on
    either path or a source that is not a directory.
    """

    identities: list[tuple[int, int]] = []
    for relative_value in inventory:
        relative = Path(relative_value)
        managed = checkout_path / relative
        source = source_repository / relative
        _ensure_no_symlink_components(checkout_path, managed, "submodule checkout")
        _ensure_no_symlink_components(config.root, source, "source submodule")
        if not source.is_dir() or source.is_symlink():
            raise Refusal(
                f"source submodule is unavailable: {source}. Preserve the slot until "
                "its remote authority can be established"
            )
        try:
            identities.append(_directory_device_inode(source))
        except OSError as exc:
            raise Refusal(f"cannot inspect source submodule {source}: {exc}") from exc
    return tuple(identities)


def _submodule_salvage_checkouts_uncached(
    config: Config,
    checkout: Checkout,
    vcs: _GitVcs,
    checkout_path: Path,
    source_repository: Path,
    *,
    inventory: Sequence[str] | None = None,
) -> tuple[tuple[Checkout, Path], ...]:
    result: list[tuple[Checkout, Path]] = []
    for relative_value in (
        vcs.initialized_submodules(checkout_path) if inventory is None else inventory
    ):
        relative = Path(relative_value)
        managed = checkout_path / relative
        source = source_repository / relative
        _ensure_no_symlink_components(checkout_path, managed, "submodule checkout")
        _ensure_no_symlink_components(config.root, source, "source submodule")
        if not source.is_dir() or source.is_symlink():
            raise Refusal(
                f"source submodule is unavailable for {checkout.name}/{relative_value}: "
                f"{source}. Preserve the slot until its remote authority can be established"
            )
        if vcs.repository_root(source) != source.absolute():
            raise Refusal(f"source submodule is not a Git root: {source}")
        remote = config.default_remote
        managed_authority = vcs.remote_authority(managed, remote)
        head = vcs.head(managed)
        stored_path = (Path(checkout.path) / relative).as_posix()
        source_relative = source.relative_to(config.root).as_posix()
        submodule = Checkout(
            name=f"{checkout.name}/{relative_value}",
            path=stored_path,
            repository=source_relative,
            branch="",
            start_point=head,
            remote=remote,
            # The source checkout may change transport independently.
            # Salvage still uses and rechecks the slot's own URL.
            remote_url_sha256=managed_authority.sha256,
            landed_ref=_landed_ref_for_remote(config, remote),
            head=head,
        )
        # Refuses unless the slot's remote is the source's remote, or is the
        # source repository itself (the layout a linked worktree's submodule
        # update produces).
        _submodule_network_authority(config, submodule, managed, vcs, managed_authority)
        result.append((submodule, managed))
    return tuple(result)


def _submodule_network_authority(
    config: Config,
    submodule: Checkout,
    managed: Path,
    vcs: _GitVcs,
    managed_authority: _RemoteAuthority,
) -> _RemoteAuthority:
    """Return the remote at which a submodule checkout's publication is judged.

    ``submodule`` is a checkout made by _submodule_salvage_checkouts: its
    repository is the source submodule and ``managed`` is the slot's copy,
    whose remote is ``managed_authority``. Two layouts are accepted:

    * the slot's remote names the same repository as the source's remote
      (_same_repository_remote); it is judged at the slot's own remote;
    * the slot's remote is a local absolute path naming a local mirror of the
      source's remote: the source submodule's own Git directory, or another
      local repository whose own remote names the same repository as the
      source's remote. A linked worktree shares its superproject's
      configuration, so when that configuration names such a local module
      directory as submodule.<name>.url (as a superproject that keeps local
      module mirrors does), `git submodule update` in the slot clones from
      it and records that path as origin. Removing the slot deletes neither
      repository, but neither is where work is published, so the commit is
      judged at the source's own remote. That remote must lead elsewhere: a
      network remote, or an absolute local path to a repository other than
      the source, the mirror and the slot's copy. Salvage never pushes
      through this alias; unpublished work is archived locally (see
      _salvage_one_checkout).

    Anything else refuses, exactly as before.
    """

    _relative, source = _stored_repository_path(config, submodule.repository)
    source_authority = vcs.remote_authority(source, submodule.remote)
    if _same_repository_remote(source_authority.url, managed_authority.url):
        return managed_authority
    mirror = _absolute_local_remote_directory(managed, managed_authority)
    if mirror is not None and _mirrors_source_remote(
        vcs, submodule.remote, mirror, source, managed, source_authority
    ):
        return source_authority
    raise Refusal(
        f"submodule {submodule.name} remote {submodule.remote} differs "
        "from its configured source; preserve the slot for inspection"
    )


def _mirrors_source_remote(
    vcs: _GitVcs,
    remote: str,
    mirror: Path,
    source: Path,
    managed: Path,
    source_authority: _RemoteAuthority,
) -> bool:
    """Whether ``mirror`` is a local mirror of ``source``'s remote.

    See _submodule_network_authority.
    """

    try:
        mirror_identity = _directory_device_inode(mirror)
        source_identity = _directory_device_inode(
            vcs.common_directory(source).resolve(strict=True)
        )
        managed_identity = _directory_device_inode(
            vcs.common_directory(managed).resolve(strict=True)
        )
    except OSError:
        return False
    if mirror_identity == managed_identity:
        return False
    if mirror_identity != source_identity:
        try:
            mirror_authority = vcs.remote_authority(mirror, remote)
        except Refusal:
            return False
        if not _same_repository_remote(mirror_authority.url, source_authority.url):
            return False
    # The source's own remote must lead elsewhere.
    if _local_remote_url_path(source, source_authority.url) is None:
        return True
    onward = _absolute_local_remote_directory(source, source_authority)
    if onward is None:
        return False
    try:
        onward_identity = _directory_device_inode(onward)
    except OSError:
        return False
    return onward_identity not in (source_identity, managed_identity, mirror_identity)


def _directory_device_inode(directory: Path) -> tuple[int, int]:
    observed = directory.stat()
    return observed.st_dev, observed.st_ino


def _absolute_local_remote_directory(
    repository: Path, authority: _RemoteAuthority
) -> Path | None:
    """Return the resolved directory an absolute local remote URL names.

    None for a network remote, a relative local remote, or a path that does
    not resolve to an existing directory.
    """

    candidate = _local_remote_url_path(repository, authority.url)
    if candidate is None or not _local_remote_url_is_absolute(authority.url):
        return None
    try:
        resolved = candidate.resolve(strict=True)
    except OSError:
        return None
    return resolved if resolved.is_dir() else None


def _github_repository_identity(url: str) -> tuple[str, str] | None:
    patterns = (
        r"https://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?/?",
        r"git@github\.com:([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?",
        r"ssh://git@github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?/?",
    )
    for pattern in patterns:
        match = re.fullmatch(pattern, url)
        if match is not None:
            return match.group(1).lower(), match.group(2).lower()
    return None


def _github_url_spellings(url: str) -> tuple[str, ...]:
    """Return the GitHub URL spellings _github_repository_identity equates with ``url``.

    Empty when ``url`` is not a GitHub repository URL. Both the owner/repo
    case of ``url`` and lower case are spelled.
    """

    patterns = (
        r"https://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?/?",
        r"git@github\.com:([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?",
        r"ssh://git@github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?/?",
    )
    for pattern in patterns:
        match = re.fullmatch(pattern, url)
        if match is None:
            continue
        spellings: list[str] = []
        for owner, name in (
            (match.group(1), match.group(2)),
            (match.group(1).lower(), match.group(2).lower()),
        ):
            for suffix in ("", ".git"):
                spellings.extend(
                    (
                        f"https://github.com/{owner}/{name}{suffix}",
                        f"https://github.com/{owner}/{name}{suffix}/",
                        f"git@github.com:{owner}/{name}{suffix}",
                        f"ssh://git@github.com/{owner}/{name}{suffix}",
                        f"ssh://git@github.com/{owner}/{name}{suffix}/",
                    )
                )
        return tuple(dict.fromkeys(spellings))
    return ()


def _recorded_remote_names_same_repository(
    recorded_sha256: str, authority: _RemoteAuthority
) -> bool:
    """Whether a recorded remote URL digest names the repository ``authority`` names.

    True for the exact URL, or when the digest is that of another GitHub
    transport spelling of the same owner/repo (_same_repository_remote), as
    when a source repository's remote moved from git@github.com: to https://.
    Only the digest was recorded, so each spelling is hashed and compared.
    """

    if authority.sha256 == recorded_sha256:
        return True
    return any(
        hmac.compare_digest(
            hashlib.sha256(spelling.encode("utf-8")).hexdigest(), recorded_sha256
        )
        for spelling in _github_url_spellings(authority.url)
    )


def _same_repository_remote(left: str, right: str) -> bool:
    """Accept exact URLs, or known GitHub transports for the same owner/repo."""
    if left == right:
        return True
    left_identity = _github_repository_identity(left)
    return left_identity is not None and left_identity == _github_repository_identity(right)


def _salvage_one_checkout(
    config: Config,
    record: ActiveRecord,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
    allow_detached: bool = False,
    prepared: _SalvageCandidate | None = None,
    archive_root: Path | None = None,
) -> dict[str, object]:
    path = path_override or _stored_path(config, checkout.path, "checkout path")
    facts = (
        _salvage_candidate(
            config,
            record,
            checkout,
            vcs,
            path_override=path,
            allow_detached=allow_detached,
            verify_repository_membership=not allow_detached,
        )
        if prepared is None
        else prepared
    )
    try:
        containing = vcs.remote_heads_containing(
            path,
            checkout.remote,
            facts.head,
            facts.remote_authority,
            network_authority=facts.network_authority,
            shallow=facts.shallow is not None,
        )
    except _RemoteTransportUnavailable as exc:
        if archive_root is None or facts.shallow is not None:
            raise
        # With no connection there is no remote answer to publish to or to
        # trust, so archive locally. The outage must repeat when the recorded
        # URL is asked again without redirects, which also rechecks the
        # recorded remote binding. Every other fetch refusal, including
        # authentication, host identity, and inventory disagreement, still
        # refuses, and so does a remote that answers the second time.
        vcs.confirm_remote_unreachable(
            path,
            checkout.remote,
            facts.remote_authority,
            network_authority=facts.network_authority,
        )
        vcs.assert_remote_authority(path, checkout.remote, facts.remote_authority)
        return _archive_salvage_locally(
            config,
            record.machine,
            record.slot,
            record.generation,
            checkout,
            path,
            facts,
            archive_root,
            exc,
            vcs,
        )
    vcs.assert_remote_authority(path, checkout.remote, facts.remote_authority)
    if not facts.dirty and containing:
        return {
            "checkout": checkout.name,
            "source_head": facts.head,
            "salvage_commit": facts.commit,
            "status_sha256": facts.status_digest,
            "disposition": "already-published",
            "remote_ref": None,
            "containing_remote_refs": list(containing),
        }
    if facts.shallow is not None:
        raise _shallow_history_refusal(facts)
    # A submodule whose remote is its source repository is never pushed
    # through that alias (see _submodule_network_authority).
    if facts.aliased or not _salvage_push_allowed(config, facts.remote_authority):
        return _archive_salvage_locally(
            config,
            record.machine,
            record.slot,
            record.generation,
            checkout,
            path,
            facts,
            archive_root or _default_salvage_archive_root(config),
            None,
            vcs,
        )
    salvage_name = checkout.name.replace("/", "-")
    salvage_ref = (
        f"{SALVAGE_REF_ROOT}/{record.machine}/{record.slot}/"
        f"{salvage_name}-{record.generation}-{facts.commit[:12]}"
    )
    _validate_full_ref(salvage_ref, "salvage ref")
    try:
        vcs.push_salvage(
            path,
            checkout.remote,
            facts.commit,
            salvage_ref,
            facts.remote_authority,
        )
    except Refusal as exc:
        if archive_root is None:
            raise
        vcs.assert_remote_authority(path, checkout.remote, facts.remote_authority)
        return _archive_salvage_locally(
            config,
            record.machine,
            record.slot,
            record.generation,
            checkout,
            path,
            facts,
            archive_root,
            exc,
            vcs,
        )
    return {
        "checkout": checkout.name,
        "source_head": facts.head,
        "salvage_commit": facts.commit,
        "status_sha256": facts.status_digest,
        "disposition": "salvaged",
        "remote_ref": salvage_ref,
        "containing_remote_refs": [],
        "destination": f"{checkout.remote}:{salvage_ref}",
    }


def _salvage_agent_slot(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    *,
    archive_root: Path | None = None,
) -> tuple[dict[str, object], ...]:
    candidates: list[tuple[Checkout, Path, bool]] = []
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path")
        if vcs.remote_url_sha256(path, checkout.remote) != checkout.remote_url_sha256:
            raise Refusal(
                f"checkout {checkout.name} remote {checkout.remote} URL changed; restore the "
                "recorded remote before reclaim so salvage cannot be sent elsewhere"
            )
        candidates.append((checkout, path, False))
        for submodule, path in _submodule_salvage_checkouts(config, checkout, vcs):
            candidates.append((submodule, path, True))
    prepared = [
        (
            checkout,
            path,
            detached,
            _salvage_candidate(
                config,
                record,
                checkout,
                vcs,
                path_override=path,
                allow_detached=detached,
                verify_repository_membership=not detached,
                allow_shallow=detached,
            ),
        )
        for checkout, path, detached in candidates
    ]
    return tuple(
        _salvage_one_checkout(
            config,
            record,
            checkout,
            vcs,
            path_override=path,
            allow_detached=detached,
            prepared=facts,
            archive_root=archive_root,
        )
        for checkout, path, detached, facts in prepared
    )


def _salvage_ownerless_checkout(
    config: Config,
    slot: str,
    recorded_at: str,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
    allow_detached: bool = False,
    prepared: _SalvageCandidate | None = None,
) -> dict[str, object]:
    """Publish one ownerless checkout without asserting an owner, task, or handoff."""

    path = path_override or _stored_path(config, checkout.path, "ownerless checkout path")
    facts = (
        _salvage_candidate(
            config,
            None,
            checkout,
            vcs,
            path_override=path,
            allow_detached=allow_detached,
            verify_repository_membership=not allow_detached,
            ownerless_slot=slot,
            ownerless_recorded_at=recorded_at,
        )
        if prepared is None
        else prepared
    )
    containing = vcs.remote_heads_containing(
        path,
        checkout.remote,
        facts.head,
        facts.remote_authority,
        network_authority=facts.network_authority,
    )
    vcs.assert_remote_authority(path, checkout.remote, facts.remote_authority)
    if not facts.dirty and containing:
        return {
            "checkout": checkout.name,
            "source_head": facts.head,
            "salvage_commit": facts.commit,
            "status_sha256": facts.status_digest,
            "disposition": "already-published",
            "remote_ref": None,
            "containing_remote_refs": list(containing),
        }
    if facts.aliased or not _salvage_push_allowed(config, facts.remote_authority):
        return _archive_salvage_locally(
            config,
            config.machine,
            slot,
            None,
            checkout,
            path,
            facts,
            _default_salvage_archive_root(config),
            None,
            vcs,
        )
    salvage_name = checkout.name.replace("/", "-")
    ref = (
        f"{SALVAGE_REF_ROOT}/{config.machine}/{slot}/"
        f"{salvage_name}-{facts.commit[:12]}"
    )
    _validate_full_ref(ref, "ownerless worktree salvage ref")
    vcs.push_salvage(
        path, checkout.remote, facts.commit, ref, facts.remote_authority
    )
    return {
        "checkout": checkout.name,
        "source_head": facts.head,
        "salvage_commit": facts.commit,
        "status_sha256": facts.status_digest,
        "disposition": "salvaged",
        "remote_ref": ref,
        "containing_remote_refs": [],
        "destination": f"{checkout.remote}:{ref}",
    }


def _salvage_ownerless_worktree(
    config: Config,
    authorization: OwnerlessAgentAuthorization,
    checkout: Checkout,
    vcs: _GitVcs,
    *,
    path_override: Path | None = None,
) -> tuple[dict[str, object], ...]:
    path = path_override or _stored_path(config, checkout.path, "ownerless checkout path")
    if vcs.remote_url_sha256(path, checkout.remote) != checkout.remote_url_sha256:
        raise Refusal(
            f"checkout {checkout.name} remote {checkout.remote} changed during salvage"
        )
    candidates: list[tuple[Checkout, Path, bool]] = [(checkout, path, False)]
    for submodule, submodule_path in _submodule_salvage_checkouts(
        config, checkout, vcs, path_override=path
    ):
        candidates.append((submodule, submodule_path, True))
    slot = Path(authorization.path).name
    prepared = [
        (
            candidate,
            candidate_path,
            detached,
            _salvage_candidate(
                config,
                None,
                candidate,
                vcs,
                path_override=candidate_path,
                allow_detached=detached,
                verify_repository_membership=not detached,
                ownerless_slot=slot,
                ownerless_recorded_at=authorization.recorded_at,
            ),
        )
        for candidate, candidate_path, detached in candidates
    ]
    return tuple(
        _salvage_ownerless_checkout(
            config,
            slot,
            authorization.recorded_at,
            candidate,
            vcs,
            path_override=candidate_path,
            allow_detached=detached,
            prepared=facts,
        )
        for candidate, candidate_path, detached, facts in prepared
    )


def _assert_salvage_still_matches(
    config: Config,
    record: ActiveRecord,
    receipts: Sequence[Mapping[str, object]],
    vcs: _GitVcs,
    *,
    paths: Mapping[str, Path] | None = None,
    checkouts: Sequence[Checkout] | None = None,
) -> None:
    by_name = {
        _as_str(value.get("checkout"), "salvage receipt.checkout"): value
        for value in receipts
    }
    targets: list[tuple[Checkout, Path, bool]] = []
    selected_checkouts = record.checkouts if checkouts is None else checkouts
    for checkout in selected_checkouts:
        path = (
            _stored_path(config, checkout.path, "checkout path")
            if paths is None
            else paths[checkout.name]
        )
        if vcs.remote_url_sha256(path, checkout.remote) != checkout.remote_url_sha256:
            raise Refusal(
                f"checkout {checkout.name} remote {checkout.remote} URL changed after "
                "salvage; preserve it and rerun remove"
            )
        targets.append((checkout, path, False))
        targets.extend(
            (submodule, submodule_path, True)
            for submodule, submodule_path in _submodule_salvage_checkouts(
                config, checkout, vcs, path_override=path
            )
        )
    expected_names = {checkout.name for checkout, _path, _detached in targets}
    if (
        set(by_name) != expected_names
        if checkouts is None
        else not expected_names <= set(by_name)
    ):
        raise StateError("salvage receipts do not name every selected checkout exactly once")
    prepared = [
        (
            checkout,
            path,
            allow_detached,
            _salvage_candidate(
                config,
                record,
                checkout,
                vcs,
                path_override=path,
                allow_detached=allow_detached,
                verify_repository_membership=not allow_detached,
                allow_shallow=allow_detached,
            ),
        )
        for checkout, path, allow_detached in targets
    ]
    for checkout, path, _allow_detached, facts in prepared:
        receipt = by_name[checkout.name]
        expected = (
            _as_str(receipt.get("source_head"), "salvage receipt.source_head"),
            _as_str(receipt.get("status_sha256"), "salvage receipt.status_sha256"),
            _as_str(receipt.get("salvage_commit"), "salvage receipt.salvage_commit"),
        )
        if (facts.head, facts.status_digest, facts.commit) != expected:
            raise Refusal(
                f"checkout {checkout.name} changed after salvage; preserve it and rerun remove "
                "so the changed state is published before deletion"
            )
        disposition = _as_str(
            receipt.get("disposition"), "salvage receipt.disposition"
        )
        if facts.shallow is not None and disposition != "already-published":
            raise _shallow_history_refusal(facts)
        if disposition == "salvaged":
            remote_ref = _as_str(receipt.get("remote_ref"), "salvage receipt.remote_ref")
            if (
                vcs.remote_ref_sha(
                    path,
                    checkout.remote,
                    remote_ref,
                    facts.remote_authority,
                )
                != facts.commit
            ):
                raise Refusal(
                    f"remote salvage ref {remote_ref} no longer contains {facts.commit}; "
                    "preserve the checkout and restore the remote evidence before deletion"
                )
        elif disposition == "already-published":
            if not vcs.remote_heads_containing(
                path,
                checkout.remote,
                facts.head,
                facts.remote_authority,
                network_authority=facts.network_authority,
                shallow=facts.shallow is not None,
            ):
                raise Refusal(
                    f"checkout {checkout.name} is no longer present on its recorded remote; "
                    "preserve it and rerun remove to publish salvage"
                )
        elif disposition == "archived-local":
            _assert_local_salvage_receipt(
                config,
                record.machine,
                record.slot,
                record.generation,
                checkout,
                facts,
                receipt,
                vcs,
            )
        else:
            raise StateError(f"unknown salvage disposition {disposition!r}")


def _assert_slot_contents(config: Config, record: ActiveRecord) -> Path:
    return _assert_slot_contents_values(
        config,
        record.slot,
        record.slot_type,
        _record_layout(config, record),
        record.checkouts,
    )


class _SlotDirectoryAbsent(Refusal):
    """The registered slot path names nothing at all: lstat reports ENOENT.

    This is the same refusal, with the same text, that every caller of
    `_assert_slot_contents` has always received for a missing slot directory.
    The subclass only lets audit tell an ABSENT directory, which
    recover-absent-agent-rows and recover-absent-validate-rows exist to retire,
    from an UNSAFE one.  A symlink, a non-directory, or any path lstat cannot
    inspect (EACCES, ENOTDIR, ELOOP, ...) still raises a plain `Refusal`.
    """

    def __init__(self, slot_path: Path) -> None:
        super().__init__(f"slot directory is missing or unsafe: {slot_path}")
        self.slot_path = slot_path


def _path_is_absent(path: Path) -> bool:
    """Return True only when lstat proves nothing occupies ``path``."""

    try:
        os.lstat(path)
    except FileNotFoundError:
        return True
    except OSError:
        return False
    return False


def _assert_slot_contents_values(
    config: Config,
    slot: str,
    slot_type: str,
    layout: str,
    checkouts: Sequence[Checkout],
) -> Path:
    slot_path = _slot_directory(config, slot, slot_type)
    if not slot_path.is_dir() or slot_path.is_symlink():
        if _path_is_absent(slot_path):
            raise _SlotDirectoryAbsent(slot_path)
        raise Refusal(f"slot directory is missing or unsafe: {slot_path}")
    if layout == "flat":
        if len(checkouts) != 1:
            raise StateError(f"slot {slot} does not have exactly one checkout under flat layout")
        checkout = checkouts[0]
        expected_path, _destination = _checkout_path_for_layout(
            config, slot, checkout.name, slot_type, layout
        )
        if checkout.path != expected_path:
            raise StateError(
                f"slot {slot} checkout path does not equal the flat slot root"
            )
        return slot_path
    expected_names = {checkout.name for checkout in checkouts}
    allowed_names = set(expected_names)
    if slot_type == "agent":
        allowed_names.add("HANDOFF.md")
    try:
        actual = {entry.name for entry in slot_path.iterdir()}
    except OSError as exc:
        raise Refusal(f"cannot inspect slot directory {slot_path}: {exc}") from exc
    extras = sorted(actual - allowed_names)
    missing = sorted(expected_names - actual)
    if extras or missing:
        details: list[str] = []
        if extras:
            details.append(f"unexpected entries {', '.join(extras)}")
        if missing:
            details.append(f"missing checkouts {', '.join(missing)}")
        raise Refusal(f"slot directory does not match its record: {'; '.join(details)}")
    return slot_path


def _uncommitted_handoff_paths(
    config: Config,
    record: ActiveRecord,
    slot_path: Path,
    vcs: _GitVcs,
    *,
    checkouts: Sequence[Checkout] | None = None,
) -> tuple[str, ...]:
    legacy = (slot_path / "HANDOFF.md").absolute()
    unprotected: set[str] = set()
    selected_checkouts = record.checkouts if checkouts is None else checkouts
    for checkout in selected_checkouts:
        _moved, checkout_path = _checkout_at_slot(
            config, record, checkout, slot_path
        )
        repositories = [(checkout.name, checkout_path)]
        repositories.extend(
            (f"{checkout.name}/{submodule}", checkout_path / submodule)
            for submodule in vcs.initialized_submodules(checkout_path)
        )
        for checkout_name, repository in repositories:
            for relative in vcs.uncommitted_handoff_paths(
                repository, _cache_globs_for(config, checkout_name)
            ):
                candidate = (repository / relative).absolute()
                if record.slot_type == "agent" and candidate == legacy:
                    continue
                if not _path_is_within(candidate, slot_path):
                    raise StateError(
                        f"Git reported handoff path outside slot {record.slot}: {candidate}"
                    )
                if candidate.exists() or candidate.is_symlink():
                    unprotected.add(candidate.relative_to(slot_path).as_posix())
    return tuple(sorted(unprotected))


def _assert_no_uncommitted_handoffs(
    config: Config,
    record: ActiveRecord,
    slot_path: Path,
    vcs: _GitVcs,
    *,
    checkouts: Sequence[Checkout] | None = None,
) -> None:
    unprotected = _uncommitted_handoff_paths(
        config, record, slot_path, vcs, checkouts=checkouts
    )
    if unprotected:
        shown = ", ".join(unprotected)
        raise Refusal(
            f"slot {record.slot} contains uncommitted handoff path(s): {shown}. "
            "state: REFUSED -- the slot and every checkout were retained. remedy: "
            "preserve each handoff outside the checkout or move its contents into the "
            "generation-bound handoff before retrying removal; salvage never publishes "
            "handoffs"
        )


def _assert_handoff_read(
    config: Config,
    record: ActiveRecord,
    slot_path: Path,
    *,
    events: Sequence[Mapping[str, object]] | None = None,
) -> _HandoffRead | None:
    if record.slot_type != "agent":
        return None
    selected_events = (
        _load_events(config, record.machine) if events is None else events
    )
    latest = _latest_handoff_read(record, selected_events)
    artifact = _resolve_handoff_artifact(
        config, record, slot_path, events=selected_events
    )
    if artifact is None:
        if latest is not None:
            raise Refusal(
                f"slot {record.slot} handoff artifact disappeared after it was read. "
                "state: REFUSED -- no checkout was salvaged or removed. remedy: restore "
                "the exact generation-bound sidecar or legacy HANDOFF.md"
            )
        return None
    if latest is None or not _handoff_read_matches_artifact(latest, artifact):
        raise Refusal(
            f"slot {record.slot} contains an unread HANDOFF.md or handoff sidecar. "
            "state: REFUSED -- no checkout was salvaged or removed. remedy: run "
            f"'wrkslots read-handoff {record.slot} --coordinator-authorized "
            "--coordinator-pid <current-coordinator-pid>' and read its output, then "
            "retry remove"
        )
    return latest


OWNER_CONSENT_ACTION = "owner-consented-release-recorded"
OWNER_CONSENT_BASIS = "owner-consented-handoff"


def _handoff_write_intent_writer(
    events: Sequence[Mapping[str, object]], intent_sequence: int
) -> ProcessIdentity:
    for event in events:
        if event.get("kind") != "handoff-write-intended":
            continue
        if _as_int(event["sequence"], "handoff write intent sequence", minimum=1) != (
            intent_sequence
        ):
            continue
        payload = _as_mapping(event["payload"], "handoff write intent payload")
        writer = _identity_from_obj(payload.get("writer"), "handoff write intent writer")
        if writer is None:
            raise StateError("handoff write intent lacks an owner identity")
        return writer
    raise StateError(f"handoff write intent {intent_sequence} is absent from history")


def _stale_generation_owner_handoffs(
    record: ActiveRecord, events: Sequence[Mapping[str, object]]
) -> list[int]:
    """Earlier or later generations of this slot whose handoff the current owner wrote."""

    generations: set[int] = set()
    for event in events:
        if event.get("kind") != "handoff-write-intended":
            continue
        payload = _as_mapping(event["payload"], "handoff write intent payload")
        if payload.get("slot") != record.slot:
            continue
        generation = payload.get("generation")
        if not isinstance(generation, int) or generation == record.generation:
            continue
        writer = _identity_from_obj(payload.get("writer"), "handoff write intent writer")
        if writer is not None and writer == record.owner:
            generations.add(generation)
    return sorted(generations)


def _owner_consented_release(
    config: Config,
    record: ActiveRecord,
    owner_detail: str,
    *,
    events: Sequence[Mapping[str, object]],
    coordinator_authorized: bool,
    expired: bool,
    age: float,
) -> _OwnerConsent | None:
    """Decide whether a LIVE recorded owner released this agent slot itself.

    The ordinary rule is that an agent slot is removed only after its exact
    owner process generation is proven dead. That rule strands every slot whose
    owner keeps running after its work is done: a long-lived agent session that
    hands a slot back cannot make its own process exit to prove it.

    The owner's release is accepted as a substitute for its death only when
    every one of these holds, and each missing one is named in the refusal:

    (a) the removal is ``--coordinator-authorized``; the coordinator process
        itself has already been verified live by the caller;
    (b) the heartbeat time-to-live has expired, so the owner has stopped
        renewing the slot (``--validate-complete`` is not a substitute);
    (c) a handoff for THIS slot generation was published through
        ``write-handoff`` and its owner-authenticated intent names a writer
        identical to the recorded owner -- pid, start ticks, boot, host and
        cgroup -- so a reused PID, an earlier owner, or an earlier slot
        generation cannot stand in for it; and
    (d) the coordinator read exactly those bytes with ``read-handoff``.

    Returns ``None`` when no handoff by this owner exists at all, so that case
    keeps its original refusal text unchanged. A writerless legacy
    ``HANDOFF.md`` carries no identity and therefore never expresses consent.
    Every other remove guard still runs after this: slot contents, uncommitted
    handoffs, the handoff-read check, the direct process-use check, and salvage
    before deletion.
    """

    if record.slot_type != "agent" or record.owner is None:
        return None
    publication = _handoff_write_publication(record, events)
    prefix = (
        "remove requires a proven-dead recorded owner or an owner-consented handoff; "
        f"owner is live: {owner_detail}. owner-consented release of slot {record.slot} "
        f"generation {record.generation} is not established"
    )
    tail = "state: REFUSED -- no checkout was salvaged or removed."
    if publication is None:
        stale = _stale_generation_owner_handoffs(record, events)
        if not stale:
            return None
        raise Refusal(
            f"{prefix}: stale generation -- the recorded owner's handoff belongs to slot "
            f"generation(s) {', '.join(str(item) for item in stale)}, not current generation "
            f"{record.generation}, and consent does not carry across generations. {tail} "
            "remedy: have the current owner run 'wrkslots write-handoff "
            f"{record.slot} --expected-generation {record.generation} ...' for this "
            "generation, or wait for the owner process to exit"
        )
    intent_sequence, intended, completed = publication
    writer = _handoff_write_intent_writer(events, intent_sequence)
    if writer != record.owner:
        raise Refusal(
            f"{prefix}: handoff writer mismatch -- the handoff was written by PID "
            f"{writer.pid} start ticks {writer.start_ticks}, but the recorded owner is PID "
            f"{record.owner.pid} start ticks {record.owner.start_ticks}; a different process "
            f"generation cannot release another owner's slot. {tail} remedy: wait for the "
            "recorded owner to exit, or have the recorded owner write its own handoff"
        )
    missing: list[str] = []
    remedies: list[str] = []
    artifact = _load_handoff_sidecar(config, record) if completed else None
    if (
        artifact is None
        or artifact.source != "write-handoff"
        or artifact.generation != record.generation
        or not _json_equal(_handoff_artifact_to_obj(artifact), intended)
    ):
        missing.append(
            "handoff publication incomplete -- no canonical sidecar matches the owner's "
            "completed write-handoff intent"
        )
        remedies.append("have the exact owner retry write-handoff")
    if not coordinator_authorized:
        missing.append("coordinator authorization -- --coordinator-authorized was not given")
        remedies.append("rerun remove with --coordinator-authorized")
    if not expired:
        remaining = max(1, record.heartbeat_ttl_seconds - int(age))
        missing.append(
            f"expired heartbeat -- the heartbeat is {int(age)}s old and its "
            f"{record.heartbeat_ttl_seconds}s time-to-live has not expired"
        )
        remedies.append(f"wait at least {remaining}s without renewal")
    latest = _latest_handoff_read(record, events)
    if artifact is not None and (
        latest is None or not _handoff_read_matches_artifact(latest, artifact)
    ):
        missing.append(
            "coordinator read -- the owner's handoff has not been read with read-handoff"
        )
        remedies.append(
            f"run 'wrkslots read-handoff {record.slot} --coordinator-pid "
            "<current-coordinator-pid>' and read its output"
        )
    if missing:
        raise Refusal(
            f"{prefix}; missing: {'; '.join(missing)}. {tail} remedy: "
            f"{'; '.join(remedies)}, then retry remove"
        )
    assert artifact is not None and latest is not None
    return _OwnerConsent(
        handoff_path=artifact.path,
        sha256=artifact.sha256,
        intent_sequence=intent_sequence,
        read_sequence=latest.sequence,
        writer=writer,
    )


def _owner_consent_evidence(
    record: ActiveRecord,
    consent: _OwnerConsent,
    *,
    coordinator: ProcessIdentity,
    coordinator_authorized: bool,
    age: float,
    registered_liveness: tuple[str, str],
) -> dict[str, object]:
    return {
        "basis": OWNER_CONSENT_BASIS,
        "owner_state": "live",
        "generation": record.generation,
        "owner": _identity_to_obj(record.owner),
        "actor": _identity_to_obj(coordinator),
        "coordinator_authorized": coordinator_authorized,
        "heartbeat_age_seconds": int(age),
        "heartbeat_ttl_seconds": record.heartbeat_ttl_seconds,
        "registered_liveness": registered_liveness[0],
        "registered_liveness_detail": registered_liveness[1],
        "handoff": {
            "path": str(consent.handoff_path),
            "sha256": consent.sha256,
            "source": "write-handoff",
            "intent_sequence": consent.intent_sequence,
            "read_sequence": consent.read_sequence,
            "writer": _identity_to_obj(consent.writer),
        },
    }


def _owner_consent_was_recorded(
    record: ActiveRecord,
    consent: _OwnerConsent,
    events: Sequence[Mapping[str, object]],
) -> bool:
    """Whether remove durably recorded this exact consent before it began."""

    for event in events:
        if event.get("kind") != "active-state-recorded":
            continue
        payload = _as_mapping(event["payload"], "active-state-recorded payload")
        if payload.get("action") != OWNER_CONSENT_ACTION or payload.get("slot") != record.slot:
            continue
        evidence = _as_mapping(payload.get("evidence"), "owner consent evidence")
        handoff = evidence.get("handoff")
        if (
            evidence.get("basis") == OWNER_CONSENT_BASIS
            and evidence.get("generation") == record.generation
            and evidence.get("coordinator_authorized") is True
            and _json_equal(evidence.get("owner"), _identity_to_obj(record.owner))
            and isinstance(handoff, Mapping)
            and handoff.get("sha256") == consent.sha256
            and handoff.get("intent_sequence") == consent.intent_sequence
        ):
            return True
    return False


# Explicit owner release: the live owner gives one agent slot generation back.
#
# ENCODED AS ITS OWN EVENT KIND, NOT AS A RECORD FIELD. The active record
# schema is read with exact keys by every client that shares this registry, so
# a new record field would make an older client refuse the whole registry.
# Replay in older clients branches on the event kinds it knows and skips the
# rest; an ``owner-released`` event is therefore invisible to them. They keep
# their original, stricter behaviour for the released slot (removal waits for
# the owner's death), and a heartbeat they renew changes the bound heartbeat
# stamp, which voids the release instead of being silently overridden by it.
# The read-only wrkslotsd replay refuses event kinds it does not list, so it
# lists this one too; the writer in _cmd_release spells the kind as a literal
# so that the source contract test can compare the two lists.
OWNER_RELEASE_EVENT = "owner-released"
OWNER_RELEASE_ACTION = "owner-release-honored"
OWNER_RELEASE_BASIS = "owner-released"
_OWNER_RELEASE_KEYS = frozenset(
    {"slot", "generation", "agent", "owner", "heartbeat_at", "handoff"}
)
_OWNER_RELEASE_HANDOFF_KEYS = frozenset({"path", "sha256", "source", "intent_sequence"})


def _owner_release_from_event(event: Mapping[str, object]) -> _OwnerRelease:
    label = "owner-released event"
    payload = _as_mapping(event["payload"], f"{label} payload")
    _exact_keys(payload, _OWNER_RELEASE_KEYS, set(), f"{label} payload")
    handoff = _as_mapping(payload["handoff"], f"{label} handoff")
    _exact_keys(handoff, _OWNER_RELEASE_HANDOFF_KEYS, set(), f"{label} handoff")
    if handoff["source"] != "write-handoff":
        raise StateError(f"{label} handoff source must be write-handoff")
    digest = _as_str(handoff["sha256"], f"{label} handoff sha256")
    if not DIGEST_RE.fullmatch(digest):
        raise StateError(f"{label} handoff sha256 is not a SHA-256 digest")
    owner = _identity_from_obj(payload["owner"], f"{label} owner")
    if owner is None:
        raise StateError(f"{label} lacks an owner identity")
    slot = _as_str(payload["slot"], f"{label} slot")
    _validate_name(slot, "slot")
    agent = _as_str(payload["agent"], f"{label} agent")
    heartbeat_at = _as_str(payload["heartbeat_at"], f"{label} heartbeat_at")
    _parse_timestamp(heartbeat_at, f"{label} heartbeat_at")
    recorded_at = _as_str(event["recorded_at"], f"{label} recorded_at")
    return _OwnerRelease(
        sequence=_as_int(event["sequence"], f"{label} sequence", minimum=1),
        recorded_at=recorded_at,
        slot=slot,
        generation=_as_int(payload["generation"], f"{label} generation", minimum=1),
        agent=agent,
        owner=owner,
        heartbeat_at=heartbeat_at,
        handoff_path=Path(_as_str(handoff["path"], f"{label} handoff path")),
        sha256=digest,
        intent_sequence=_as_int(
            handoff["intent_sequence"], f"{label} handoff intent_sequence", minimum=1
        ),
    )


def _latest_owner_releases(
    events: Sequence[Mapping[str, object]],
    wanted: AbstractSet[tuple[str, int]] | None = None,
) -> dict[tuple[str, int], _OwnerRelease]:
    """The latest ``owner-released`` event of each (slot, generation), in one pass.

    Only the generations in ``wanted`` are parsed when it is given, so one
    slot's release history cannot affect a command about another slot.
    """

    latest: dict[tuple[str, int], _OwnerRelease] = {}
    for event in events:
        if event.get("kind") != OWNER_RELEASE_EVENT:
            continue
        if wanted is not None:
            payload = event.get("payload")
            if not isinstance(payload, Mapping) or (
                payload.get("slot"),
                payload.get("generation"),
            ) not in wanted:
                continue
        release = _owner_release_from_event(event)
        latest[(release.slot, release.generation)] = release
    return latest


def _owner_release_void_reason(
    config: Config,
    record: ActiveRecord,
    release: _OwnerRelease,
    events: Sequence[Mapping[str, object]],
) -> str | None:
    """Why a recorded release no longer describes this slot, or ``None`` if it does.

    A release is the exact owner's statement about the slot as it was at that
    moment. It stops applying the moment anything it was bound to changes:
    another owner process generation, a renewed heartbeat, another agent, or a
    handoff sidecar that is missing or no longer the released bytes.
    """

    if release.agent != record.agent:
        return f"the slot now belongs to agent {record.agent}, not {release.agent}"
    if record.owner != release.owner:
        return "the recorded owner process generation changed after the release"
    if record.heartbeat_at != release.heartbeat_at:
        return (
            f"the heartbeat was renewed after the release (released at heartbeat "
            f"{release.heartbeat_at}, now {record.heartbeat_at})"
        )
    publication = _handoff_write_publication(record, events)
    if publication is None or publication[0] != release.intent_sequence or not publication[2]:
        return "the handoff publication changed after the release"
    try:
        artifact = _load_handoff_sidecar(config, record)
    except Refusal as exc:
        return f"the released handoff sidecar cannot be read: {exc}"
    if artifact is None:
        return "the released handoff sidecar is missing"
    if (
        artifact.source != "write-handoff"
        or artifact.path != release.handoff_path
        or artifact.sha256 != release.sha256
        or not _json_equal(_handoff_artifact_to_obj(artifact), publication[1])
    ):
        return "the handoff sidecar no longer matches the released bytes"
    return None


def _owner_release_state(
    config: Config,
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
    releases: Mapping[tuple[str, int], _OwnerRelease] | None = None,
) -> tuple[_OwnerRelease | None, str | None]:
    """This generation's latest release and, if it no longer applies, why not."""

    if record.slot_type != "agent":
        return None, None
    selected = (
        _latest_owner_releases(events, {(record.slot, record.generation)})
        if releases is None
        else releases
    )
    release = selected.get((record.slot, record.generation))
    if release is None:
        return None, None
    return release, _owner_release_void_reason(config, record, release, events)


def _owner_release_in_effect(
    config: Config,
    record: ActiveRecord,
    events: Sequence[Mapping[str, object]],
) -> _OwnerRelease | None:
    release, void_reason = _owner_release_state(config, record, events)
    return release if release is not None and void_reason is None else None


def _owner_release_evidence(
    record: ActiveRecord,
    release: _OwnerRelease,
    *,
    coordinator: ProcessIdentity,
    coordinator_authorized: bool,
    owner_state: str,
    age: float,
    registered_liveness: tuple[str, str],
) -> dict[str, object]:
    return {
        "basis": OWNER_RELEASE_BASIS,
        "owner_state": owner_state,
        "generation": record.generation,
        "owner": _identity_to_obj(record.owner),
        "actor": _identity_to_obj(coordinator),
        "coordinator_authorized": coordinator_authorized,
        "heartbeat_age_seconds": int(age),
        "heartbeat_ttl_seconds": record.heartbeat_ttl_seconds,
        "registered_liveness": registered_liveness[0],
        "registered_liveness_detail": registered_liveness[1],
        "release": {
            "sequence": release.sequence,
            "recorded_at": release.recorded_at,
            "heartbeat_at": release.heartbeat_at,
        },
        "handoff": {
            "path": str(release.handoff_path),
            "sha256": release.sha256,
            "source": "write-handoff",
            "intent_sequence": release.intent_sequence,
        },
    }


def _owner_release_was_recorded(
    record: ActiveRecord,
    release: _OwnerRelease,
    events: Sequence[Mapping[str, object]],
) -> bool:
    """Whether remove durably recorded that it honoured this exact release."""

    for event in events:
        if event.get("kind") != "active-state-recorded":
            continue
        payload = _as_mapping(event["payload"], "active-state-recorded payload")
        if payload.get("action") != OWNER_RELEASE_ACTION or payload.get("slot") != record.slot:
            continue
        evidence = _as_mapping(payload.get("evidence"), "owner release evidence")
        recorded = evidence.get("release")
        handoff = evidence.get("handoff")
        if (
            evidence.get("basis") == OWNER_RELEASE_BASIS
            and evidence.get("generation") == record.generation
            and _json_equal(evidence.get("owner"), _identity_to_obj(record.owner))
            and isinstance(recorded, Mapping)
            and recorded.get("sequence") == release.sequence
            and isinstance(handoff, Mapping)
            and handoff.get("sha256") == release.sha256
            and handoff.get("intent_sequence") == release.intent_sequence
        ):
            return True
    return False


def _owner_release_summary(release: _OwnerRelease) -> str:
    return f"RELEASED by live owner at {release.recorded_at}"


def _owner_release_obj(
    release: _OwnerRelease, void_reason: str | None
) -> dict[str, object]:
    """The display form of one generation's latest release, in effect or void."""

    return {
        "state": "released" if void_reason is None else "void",
        "summary": (
            _owner_release_summary(release)
            if void_reason is None
            else f"release at {release.recorded_at} no longer applies: {void_reason}"
        ),
        "event_sequence": release.sequence,
        "recorded_at": release.recorded_at,
        "heartbeat_at": release.heartbeat_at,
        "owner": _identity_to_obj(release.owner),
        "handoff_sha256": release.sha256,
        "void_reason": void_reason,
    }


def _owner_release_states(
    config: Config, states: Sequence[ActiveState]
) -> dict[tuple[str, str], tuple[_OwnerRelease, str | None]]:
    """Every active agent generation that has a release, keyed by (machine, slot).

    Only generations that are active now are parsed, and a slot that was
    never released is absent, so display commands add nothing for it.
    """

    found: dict[tuple[str, str], tuple[_OwnerRelease, str | None]] = {}
    for state in states:
        wanted = {
            (record.slot, record.generation)
            for record in state.slots
            if record.slot_type == "agent"
        }
        if not wanted:
            continue
        events = _load_events(config, state.machine)
        releases = _latest_owner_releases(events, wanted)
        if not releases:
            continue
        for record in state.slots:
            release, void_reason = _owner_release_state(
                config, record, events, releases
            )
            if release is not None:
                found[(record.machine, record.slot)] = (release, void_reason)
    return found


def _handoff_preconditions(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    *,
    refresh_remote: bool = True,
) -> tuple[Path, tuple[Checkout, ...]]:
    _assert_record_paths(config, record)
    slot_path = _assert_slot_contents(config, record)
    final_checkouts = tuple(
        _assert_checkout_safe(
            config, item, vcs, refresh_remote=refresh_remote
        )
        for item in record.checkouts
    )
    return slot_path, final_checkouts


def _remove_preconditions(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    *,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
    owner_consented: bool = False,
    agent_batch: _AgentRemoveBatchContext | None = None,
) -> tuple[Path, tuple[Checkout, ...]]:
    if record.handoff is None:
        raise Refusal(
            f"slot {record.slot} has no owner-alive handoff; preserve it and record one before removal"
        )
    slot_path, final_checkouts = _handoff_preconditions(config, record, vcs)
    if final_checkouts != record.checkouts:
        raise Refusal(
            f"slot {record.slot} changed after its handoff was recorded; preserve it for inspection"
        )
    _assert_slot_unused(
        slot_path,
        _record_for_slot_use_check(
            record,
            validate_complete=False,
            allow_live_validate_owner=False,
            owner_consented=owner_consented,
        ),
        live_use_recheck=live_use_recheck,
        **_agent_batch_use_check(agent_batch, slot_path),
    )
    return slot_path, final_checkouts


def _reclaim_preconditions(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    finish: _FinishContext,
    *,
    check_use: bool = True,
) -> tuple[Path, tuple[Checkout, ...]]:
    """Recheck everything a reclaim depends on; return the slot path and current checkouts.

    ``check_use`` False omits only the direct-use check of the slot, for a
    caller that runs this whole check again, use check included, before the
    path fence under the same registry-lock hold (_begin_finish, whose
    _begin_or_resume_path_fence does).
    """

    _assert_record_paths(config, record)
    slot_path = _assert_slot_contents(config, record)
    _assert_no_uncommitted_handoffs(config, record, slot_path, vcs)
    _assert_handoff_read(config, record, slot_path)
    use_check_record = _record_for_slot_use_check(
        record,
        validate_complete=finish.validate_complete,
        allow_live_validate_owner=finish.allow_live_validate_owner,
        owner_consented=finish.owner_consented,
    )
    private_cleanup = finish.private_cleanup
    if private_cleanup is not None:
        if private_cleanup.target.path != slot_path:
            raise StateError("private cleanup context does not match its slot path")
        if (
            _private_cleanup_fence_identity(config, slot_path)
            != private_cleanup.target.identity
        ):
            raise Refusal(
                f"private cleanup path identity changed after its shared census: "
                f"{slot_path}"
            )
    elif check_use:
        _assert_slot_unused(
            slot_path,
            use_check_record,
            use_lsof=use_check_record is not None,
            ignore_invoking_ancestry=(
                finish.allow_live_validate_owner and record.slot_type == "validate"
            ),
            live_use_recheck=finish.live_use_recheck,
            **_agent_batch_use_check(finish.agent_batch, slot_path),
        )
    final: list[Checkout] = []
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path")
        _relative, repository = _stored_repository_path(config, checkout.repository)
        head = vcs.verify_existing_worktree(repository, path)
        branch = vcs.branch(path)
        if branch != checkout.branch:
            raise Refusal(
                f"checkout {checkout.name} branch changed: expected {checkout.branch}, "
                f"found {branch}; preserve it and update the record before reclaim"
            )
        if record.slot_type == "agent":
            operations = vcs.operation_paths(path)
            if operations:
                raise Refusal(
                    f"checkout {checkout.name} has an unfinished Git operation at "
                    f"{operations[0]}; complete or abort it before reclaim"
                )
            vcs.assert_ordinary_history(path)
            vcs.assert_ordinary_index(path)
        if vcs.remote_url_sha256(path, checkout.remote) != checkout.remote_url_sha256:
            raise Refusal(
                f"checkout {checkout.name} remote {checkout.remote} URL changed; "
                "restore the recorded remote before reclaim"
            )
        final.append(dataclasses.replace(checkout, head=head))
    if record.slot_type == "validate":
        if finish.salvage:
            raise StateError("validate slot unexpectedly records salvage evidence")
    elif finish.salvage:
        _assert_salvage_still_matches(config, record, finish.salvage, vcs)
    elif record.handoff is not None:
        return _remove_preconditions(
            config,
            record,
            vcs,
            live_use_recheck=finish.live_use_recheck,
            owner_consented=finish.owner_consented,
            agent_batch=finish.agent_batch,
        )
    else:
        raise StateError("agent slot reclaim has neither salvage nor an owner handoff")
    return slot_path, tuple(final)


def _record_for_slot_use_check(
    record: ActiveRecord,
    *,
    validate_complete: bool,
    allow_live_validate_owner: bool,
    owner_consented: bool = False,
) -> ActiveRecord | None:
    if record.slot_type != "validate":
        if owner_consented:
            # The recorded owner is LIVE and released the slot itself, so its
            # own process -- and any sibling in a shared session scope -- is
            # expected to remain in the recorded cgroup. That comparison would
            # refuse on the very consent being honoured. Only the cgroup
            # comparison is dropped: returning a record (not None) keeps the
            # direct cwd/root/exe/descriptor/mapping use test fully active.
            return dataclasses.replace(record, owner=None)
        return record
    if allow_live_validate_owner:
        return None
    if (
        validate_complete
        and record.owner is not None
        and _process_state(record.owner)[0] == "dead"
    ):
        return None
    return record


def _validate_batch_seal_journals(config: Config) -> list[Path]:
    return sorted(config.control.glob("VALIDATE-BATCH-SEAL.*.journal"))


def _validate_batch_seal_orphaned(config: Config, path: Path) -> tuple[bool, str]:
    """Whether the seal journal at ``path`` was left by a process proven dead.

    True only when the seal's actor ran on this machine identity and this
    boot, its pid is absent or now names another process generation
    (``_process_state``), and no finish journal is paired with the seal. A
    live or indeterminate actor, an actor from another machine or an earlier
    boot, an unreadable journal, or a paired finish all keep the seal binding.
    Such an orphan is what a validate-batch removal leaves when its process is
    killed before its ``finally`` retires the seal: nothing can still be using
    it (https://github.com/rrnewton/agent-utils/issues/236).
    """
    try:
        _raw, targets = _validate_batch_seal_journal(
            config, path, _read_json(path, "validation-batch seal journal")
        )
        identity = _identity_from_obj(
            _raw["actor"], "validation-batch seal journal.actor"
        )
        if identity is None:
            return False, "the seal records no actor"
        host_id = _host_id()
        boot_id = _boot_id(Path("/proc"))
        if identity.host_id != host_id:
            return False, "the seal's actor belongs to another machine identity"
        if identity.boot_id != boot_id:
            return False, "the seal's actor ran in an earlier boot"
        state, reason = _process_state(identity)
        if state != "dead":
            return False, f"the seal's actor is {state}: {reason}"
        if _validate_batch_seal_paired_finish(config, targets) is not None:
            return False, "a finish journal is paired with the seal"
    except (Refusal, StateError) as exc:
        return False, f"the seal cannot be judged: {exc}"
    return True, f"its actor PID {identity.pid} is dead: {reason}"


def _recover_orphaned_validate_batch_seal(config: Config) -> None:
    """Retire this machine's seal journal when its actor is proven dead.

    Called only under the mutation locks of ``create``. The recovery is the
    seal-only one ``wrkslots recover`` performs: it restores each sealed
    directory's mode, or resolves a target that is already gone. A failed
    recovery leaves the seal in place and does not stop the create, which
    already proceeds beside a seal whose paths it does not overlap.
    """
    path = _validate_batch_seal_journal_path(config)
    if not path.is_file():
        return
    orphaned, reason = _validate_batch_seal_orphaned(config, path)
    if not orphaned:
        return
    try:
        _recover_validate_batch_seal_journal(
            config,
            recovery_kind=_ValidateBatchSealRecoveryKind.SEAL_ONLY,
            emit=False,
        )
    except (Refusal, StateError) as exc:
        print(
            f"wrkslots: left the validation-batch seal {path.name} in place: {exc}",
            file=sys.stderr,
        )
        return
    print(
        f"wrkslots: recovered the validation-batch seal {path.name}; {reason}",
        file=sys.stderr,
    )


def _refuse_partial_state(
    config: Config,
    *,
    allow_validate_batch_seals: bool = False,
    allow_orphaned_validate_batch_seals: bool = False,
) -> None:
    leftovers = sorted(config.control.glob("ACTIVE.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ARCHIVED.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ACTIVE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("CREATE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("FINISH.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("HANDOFF.*.json.tmp.*"))
    leftovers += sorted(
        config.control.glob("VALIDATE-BATCH-SEAL.*.journal.tmp.*")
    )
    for event_directory in sorted(config.control.glob("EVENTS.*")):
        if event_directory.is_dir() and not event_directory.is_symlink():
            leftovers += sorted(event_directory.glob("*.json.tmp.*"))
    if leftovers:
        raise StateError(
            f"partial atomic update found: {leftovers[0]}; preserve it and use 'wrkslots recover'"
        )
    seal_journals = _validate_batch_seal_journals(config)
    if seal_journals and not allow_validate_batch_seals:
        if allow_orphaned_validate_batch_seals:
            # A seal its dead actor left is retired by the next create, under
            # its lock; it need not block a read-only classification first.
            seal_journals = [
                path
                for path in seal_journals
                if not _validate_batch_seal_orphaned(config, path)[0]
            ]
        if seal_journals:
            raise Refusal(
                f"interrupted validation-batch seal recorded in {seal_journals[0]}; "
                "run 'wrkslots recover' first"
            )


def _outstanding_journals(config: Config) -> list[Path]:
    paths = {path for path in config.control.glob("ACTIVE.*.journal")}
    paths.update(config.control.glob("CREATE.*.journal"))
    paths.update(config.control.glob("FINISH.*.journal"))
    for directory in config.control.glob("EVENTS.*"):
        if not directory.is_dir() or directory.is_symlink():
            continue
        machine = directory.name.removeprefix("EVENTS.")
        paths.update(_pending_operations_from_events(config, machine))
    return sorted(paths)


def _pending_journal_for_path(
    config: Config, path: Path
) -> Mapping[str, object] | None:
    matches: list[Mapping[str, object]] = []
    for directory in config.control.glob("EVENTS.*"):
        if not directory.is_dir() or directory.is_symlink():
            continue
        machine = directory.name.removeprefix("EVENTS.")
        pending = _pending_operations_from_events(config, machine).get(path)
        if pending is not None:
            matches.append(pending)
    if len(matches) > 1:
        raise StateError(
            f"multiple append-only histories claim pending journal {path}"
        )
    return matches[0] if matches else None


def _assert_no_journal(config: Config) -> None:
    journals = _outstanding_journals(config)
    if journals:
        raise Refusal(
            f"interrupted mutation recorded in {journals[0]}; run 'wrkslots recover' first"
        )


def _journal_path_for_slot(config: Config, slot: str) -> Path:
    """Select one legacy or scoped mutation journal by validated slot identity."""

    matches: list[Path] = []
    for path in _outstanding_journals(config):
        if path.exists() or path.is_symlink():
            raw = _as_mapping(
                _read_json(path, "recovery journal"), "recovery journal"
            )
        else:
            pending = _pending_journal_for_path(config, path)
            if pending is None:
                raise StateError(
                    f"journal has neither standalone nor append-only evidence: {path}"
                )
            raw = pending
        _validate_journal_shape(config, path, raw)
        if raw.get("kind") in {"create", "finish"} and raw.get("slot") == slot:
            matches.append(path)
    if not matches:
        raise Refusal(f"no interrupted mutation is recorded for slot {slot!r}")
    if len(matches) != 1:
        raise StateError(f"multiple interrupted mutations claim slot {slot!r}")
    return matches[0]


def _load_journal(
    config: Config, *, selected_path: Path | None = None
) -> tuple[Path, Mapping[str, object]]:
    journals = _outstanding_journals(config)
    if not journals:
        raise Refusal("no interrupted mutation is recorded")
    if selected_path is not None:
        if selected_path not in journals:
            raise Refusal(f"no interrupted mutation is recorded in {selected_path}")
        path = selected_path
    elif len(journals) != 1:
        raise StateError(
            "multiple interrupted mutations are present; select one exact slot "
            "with '--slot SLOT' or inspect every journal before continuing"
        )
    else:
        path = journals[0]
    if path.exists() or path.is_symlink():
        raw = _as_mapping(_read_json(path, "recovery journal"), "recovery journal")
    else:
        pending = _pending_journal_for_path(config, path)
        if pending is None:
            raise StateError(
                f"append-only log names no pending operation for missing journal {path}"
            )
        raw = pending
    _validate_journal_provenance(config, path, raw)
    return path, raw


def _interrupt_for_test(point: str) -> None:
    if os.environ.get("WRKSLOTS_TEST_INTERRUPT") == point:
        os._exit(86)


def _assignments(values: Sequence[str] | None, label: str) -> dict[str, str]:
    result: dict[str, str] = {}
    for raw in values or ():
        name, separator, value = raw.partition("=")
        if not separator or not value:
            raise Refusal(f"{label} must use NAME=VALUE, got {raw!r}")
        _validate_name(name, f"{label} name")
        if name in result:
            raise Refusal(f"duplicate {label} for {name!r}")
        result[name] = value
    return result


def _planned_to_obj(item: PlannedCheckout) -> dict[str, object]:
    return dataclasses.asdict(item)


def _planned_from_obj(value: object, label: str) -> PlannedCheckout:
    raw = _as_mapping(value, label)
    fields = {
        "name",
        "destination",
        "repository",
        "branch",
        "start_point",
        "remote",
        "remote_url_sha256",
        "landed_ref",
    }
    _exact_keys(raw, fields, set(), label)
    item = PlannedCheckout(
        name=_as_str(raw["name"], f"{label}.name"),
        destination=_as_str(raw["destination"], f"{label}.destination"),
        repository=_as_str(raw["repository"], f"{label}.repository"),
        branch=_as_str(raw["branch"], f"{label}.branch"),
        start_point=_as_str(raw["start_point"], f"{label}.start_point"),
        remote=_as_str(raw["remote"], f"{label}.remote"),
        remote_url_sha256=_as_str(
            raw["remote_url_sha256"], f"{label}.remote_url_sha256"
        ),
        landed_ref=_as_str(raw["landed_ref"], f"{label}.landed_ref"),
    )
    _validate_name(item.name, "checkout name")
    _validate_remote(item.remote)
    if not re.fullmatch(r"[0-9a-f]{64}", item.remote_url_sha256):
        raise StateError(f"{label}.remote_url_sha256 must be a lowercase SHA-256")
    _validate_ref(item.branch, "branch")
    if not SHA_RE.fullmatch(item.start_point):
        raise StateError(f"{label}.start_point must be a full lowercase Git commit")
    _validate_full_ref(item.landed_ref, "landed ref")
    return item


def _owner_from_arg(owner_pid: int | None) -> ProcessIdentity | None:
    return _read_process_identity(owner_pid) if owner_pid is not None else None


def _cmd_init(args: argparse.Namespace) -> int:
    candidate_root = Path(args.directory).absolute()
    if candidate_root.exists() and (
        not candidate_root.is_dir() or candidate_root.is_symlink()
    ):
        raise Refusal(f"project root must be a real directory: {candidate_root}")
    candidate_root.mkdir(parents=True, exist_ok=True)
    root = candidate_root.resolve(strict=True)
    machine = args.machine or _short_hostname()
    _validate_name(machine, "machine")
    remote = _validate_remote(args.default_remote)
    landed_ref = _validate_full_ref(args.default_landed_ref, "default landed ref")
    if not landed_ref.startswith(f"refs/remotes/{remote}/"):
        raise Refusal(
            "default landed ref must name a remote-tracking ref under "
            f"refs/remotes/{remote}/"
        )
    liveness_relative, liveness_command = _relative_inside(
        root, args.liveness_command, "liveness command"
    )
    if (
        not liveness_command.is_file()
        or liveness_command.is_symlink()
        or (
            liveness_command.suffix != ".py"
            and not os.access(liveness_command, os.X_OK)
        )
    ):
        raise Refusal(
            f"liveness command must be a runnable real file: {liveness_command}"
        )
    liveness_batch_relative: str | None = None
    if args.liveness_batch_command is not None:
        liveness_batch_relative, liveness_batch_command = _relative_inside(
            root, args.liveness_batch_command, "batch liveness command"
        )
        if (
            not liveness_batch_command.is_file()
            or liveness_batch_command.is_symlink()
            or (
                liveness_batch_command.suffix != ".py"
                and not os.access(liveness_batch_command, os.X_OK)
            )
        ):
            raise Refusal(
                "batch liveness command must be a runnable real file: "
                f"{liveness_batch_command}"
            )
    worktrees_relative, worktrees = _relative_inside(
        root, args.worktrees_dir, "worktrees directory"
    )
    layout = _validate_layout(args.layout)
    if args.heartbeat_ttl_seconds < 1:
        raise Refusal("heartbeat TTL must be at least one second")
    if args.max_active_slots is not None and args.max_active_slots < 0:
        raise Refusal("max active slots must be non-negative")
    cache_globs = tuple(_validate_cache_glob(value) for value in args.cache_glob or ())
    if len(cache_globs) != len(set(cache_globs)):
        raise Refusal("cache globs must not contain duplicates")
    repo_cache_globs = _cache_glob_assignments(
        args.repo_cache_glob or (), "repository cache glob"
    )
    post_provision_hooks = tuple(
        _validate_hook(value) for value in args.post_provision_hook or ()
    )
    disk_gib = (
        args.disk_advisory_gib,
        args.disk_provisioning_floor_gib,
        args.disk_emergency_gib,
    )
    if any(value is not None for value in disk_gib) and not all(
        value is not None for value in disk_gib
    ):
        raise Refusal(
            "disk policy requires --disk-advisory-gib, "
            "--disk-provisioning-floor-gib, and --disk-emergency-gib together"
        )
    if all(value is not None for value in disk_gib):
        advisory_gib, provisioning_gib, emergency_gib = disk_gib
        assert advisory_gib is not None
        assert provisioning_gib is not None
        assert emergency_gib is not None
        if min(advisory_gib, provisioning_gib, emergency_gib) < 1:
            raise Refusal("disk thresholds must each be at least 1 GiB")
        if not emergency_gib < provisioning_gib < advisory_gib:
            raise Refusal(
                "disk thresholds must satisfy emergency < provisioning floor < advisory"
            )
        disk_bytes = (
            advisory_gib * GIB,
            provisioning_gib * GIB,
            emergency_gib * GIB,
        )
    else:
        disk_bytes = (None, None, None)
    config_path = root / CONFIG_NAME
    representation, image_section = _init_representation(args, config_path)
    sandbox_section = _init_sandbox_section(config_path)
    if args.sandbox_isolation is not None:
        sandbox_section = dict(sandbox_section or sandbox.default_config_obj())
        sandbox_section["isolation"] = args.sandbox_isolation
    salvage_push_remotes = _init_salvage_push_remotes(args, config_path)
    payload = _config_payload(
        worktrees_relative,
        machine,
        remote,
        landed_ref,
        args.heartbeat_ttl_seconds,
        liveness_relative,
        liveness_batch_relative,
        args.max_active_slots,
        layout,
        cache_globs,
        repo_cache_globs,
        post_provision_hooks,
        disk_bytes[0],
        disk_bytes[1],
        disk_bytes[2],
        representation,
        image_section,
        sandbox_section,
        salvage_push_remotes=salvage_push_remotes,
    )
    with _locked_config(config_path, args.wait_lock):
        _recover_config_write(config_path, payload)
        if config_path.exists() or config_path.is_symlink():
            existing = _read_config(config_path)
            if _canonical_config_payload(existing) != payload:
                existing_worktrees = existing.get("worktrees_dir")
                if isinstance(existing_worktrees, str):
                    _relative, existing_worktrees_path = _relative_inside(
                        root, existing_worktrees, "existing worktrees directory"
                    )
                    existing_layout = existing.get("layout", "nested")
                    # `isinstance` FIRST: a membership test against a set of strings tells mypy
                    # nothing about the type, and this value comes off a decoded record as
                    # `object`. Nothing changes at runtime — a non-string was never in that set.
                    if isinstance(existing_layout, str) and existing_layout in {"nested", "flat"}:
                        existing_control = _control_directory_for(
                            existing_worktrees_path, existing_layout
                        )
                        journals = sorted(existing_control.glob("ACTIVE.*.journal"))
                        journals += sorted(existing_control.glob("CREATE.*.journal"))
                        journals += sorted(existing_control.glob("FINISH.*.journal"))
                        if journals:
                            raise Refusal(
                                f"cannot change configuration while recovery journal "
                                f"{journals[0]} exists; recover or explicitly abort it first"
                            )
                if not args.repair:
                    raise Refusal(
                        f"{config_path} already has different configuration; "
                        "do not move live state by rerunning init. If this "
                        "configuration was written by an older build and no "
                        "longer loads, migrate it with `init --repair`."
                    )
                repaired, changes = _repaired_config(dict(existing), payload)
                _write_config(config_path, repaired)
                for line in changes:
                    print(f"REPAIRED {config_path}: {line}")
            elif args.repair:
                print(f"UNCHANGED {config_path}: already current")
        else:
            _write_config(config_path, payload, args.config_format)
    if worktrees.exists() and (not worktrees.is_dir() or worktrees.is_symlink()):
        raise Refusal(f"worktrees directory is not a real directory: {worktrees}")
    worktrees.mkdir(parents=True, exist_ok=True)
    config = _load_config(str(root), machine)
    worktrees = config.worktrees
    control = config.control
    with _mutation_locks(config, args.wait_lock):
        _recover_partial_updates(config, True)
        _refuse_partial_state(config)
        if args.repair:
            _repair_empty_state_from_schema_one(config)
        active_path = _active_path(config)
        if active_path.exists() or active_path.is_symlink():
            _load_active(config)
        else:
            _atomic_write_json(active_path, _active_to_obj(ActiveState(machine, 0, ())))
        archive_path = _archive_path(config)
        if archive_path.exists() or archive_path.is_symlink():
            _load_archive(config)
        else:
            _atomic_write_json(
                archive_path, _archive_to_obj(ArchiveState(machine, 0, ()))
            )
        _ensure_event_log(config)
        link = control / "wrkslots"
        executable = Path(__file__).with_name("__main__.py").resolve()
        relative_target = Path(os.path.relpath(executable, start=control))
        if link.exists() or link.is_symlink():
            if not link.is_symlink():
                raise Refusal(f"control path exists and is not a symlink: {link}")
            existing_target = Path(os.readlink(link))
            previous_executable = executable.parent.with_suffix(".py")
            existing_executable = (link.parent / existing_target).resolve()
            if (
                args.repair
                and previous_executable.is_file()
                and not previous_executable.is_symlink()
                and existing_executable == previous_executable
            ):
                _atomic_replace_symlink(link, relative_target)
                print(f"REPAIRED {link}: {existing_target} -> {relative_target}")
            elif existing_target != relative_target:
                raise Refusal(
                    f"control symlink points elsewhere: {link} -> {existing_target}"
                )
        else:
            link.symlink_to(relative_target)
            _fsync_directory(control)
    print(f"initialized wrkslots in {root}")
    print(
        f"machine={machine} worktrees={config.worktrees.relative_to(root)} "
        f"layout={config.layout} "
        f"control={control.relative_to(root)}"
    )
    print(f"command={link} -> {relative_target}")
    return 0


def _create_plan(config: Config, args: argparse.Namespace, vcs: _GitVcs) -> tuple[PlannedCheckout, ...]:
    repositories = _assignments(args.repo, "repository")
    remotes = _assignments(args.remote, "remote")
    remote_urls = _assignments(args.remote_url, "trusted remote URL")
    branches = _assignments(args.branch, "branch")
    starts = _assignments(args.start, "start point")
    if not repositories:
        raise Refusal("create requires at least one --repo NAME=PATH")
    if config.layout == "flat" and len(repositories) != 1:
        raise Refusal("flat layout requires exactly one repository per slot")
    if args.slot_type == "validate" and not branches:
        branches = {
            name: f"wrkslots/validate/{config.machine}/{args.slot}/{name}"
            for name in repositories
        }
    if set(branches) != set(repositories):
        missing = sorted(set(repositories) - set(branches))
        extra = sorted(set(branches) - set(repositories))
        raise Refusal(
            "branches must exactly match repositories"
            + (f"; missing {', '.join(missing)}" if missing else "")
            + (f"; unknown {', '.join(extra)}" if extra else "")
        )
    for mapping, label in (
        (starts, "start point"),
        (remotes, "remote"),
        (remote_urls, "trusted remote URL"),
    ):
        unknown = sorted(set(mapping) - set(repositories))
        if unknown:
            raise Refusal(f"{label} supplied for unknown repository: {', '.join(unknown)}")
    planned: list[PlannedCheckout] = []
    common_directories: set[Path] = set()
    for name, raw_repository in repositories.items():
        repository_relative, repository = _repository_path(config, raw_repository)
        if vcs.repository_root(repository) != repository.absolute():
            raise Refusal(f"repository path is not its Git worktree root: {repository}")
        common = vcs.common_directory(repository)
        if common in common_directories:
            raise Refusal("the same Git repository was supplied more than once")
        common_directories.add(common)
        branch = branches[name]
        vcs.check_branch_name(repository, branch)
        if vcs.branch_exists(repository, branch):
            raise Refusal(f"local branch already exists: {branch}")
        remote = _validate_remote(remotes.get(name, config.default_remote))
        landed_ref = _landed_ref_for_remote(config, remote)
        if not landed_ref.startswith(f"refs/remotes/{remote}/"):
            raise Refusal(
                f"landed ref for {name} must be under refs/remotes/{remote}/"
            )
        authorized_url = remote_urls.get(name)
        remote_authority = vcs.remote_authority(repository, remote)
        if authorized_url is not None and remote_authority.url != authorized_url:
            raise Refusal(
                f"remote {remote!r} URL differs from trusted provisioning input"
            )
        remote_url_sha256 = remote_authority.sha256
        if args.slot_type != "validate" or name not in starts:
            vcs.fetch_remote(repository, remote, landed_ref, remote_authority)
        vcs.assert_remote_authority(repository, remote, remote_authority)
        start = vcs.verify_ref(
            repository, starts.get(name, landed_ref), "start point"
        )
        destination_relative, destination = _checkout_path(
            config, args.slot, name, args.slot_type
        )
        if destination.exists() or destination.is_symlink():
            raise Refusal(f"checkout destination already exists: {destination}")
        planned.append(
            PlannedCheckout(
                name=name,
                destination=destination_relative,
                repository=repository_relative,
                branch=branch,
                start_point=start,
                remote=remote,
                remote_url_sha256=remote_url_sha256,
                landed_ref=landed_ref,
            )
        )
    return tuple(sorted(planned, key=lambda item: item.name))


def _assert_active_slot_cap(config: Config, states: Sequence[ActiveState]) -> None:
    """Refuse a new allocation once this machine is at its configured cap.

    The cap counts rows in this machine's shard, which is the same population
    the allocation is about to join. It is enforced here, on the allocation
    path, rather than reported after the fact: a cap that only appears in a
    report is not a cap, and a breach discovered later cannot un-allocate the
    slot that caused it.
    """
    cap = config.max_active_slots
    if cap is None:
        return
    active = [
        record
        for state in states
        if state.machine == config.machine
        for record in state.slots
    ]
    if len(active) < cap:
        return
    raise Refusal(
        f"machine {config.machine} already holds {len(active)} active slot(s) "
        f"against max_active_slots={cap}; finish or remove a slot before "
        f"allocating another. Active: {', '.join(sorted(r.slot for r in active))}"
    )


def _free_bytes(path: Path) -> int:
    try:
        filesystem = os.statvfs(path)
    except OSError as exc:
        raise Refusal(f"cannot measure free space on {path}: {exc}") from exc
    return filesystem.f_bavail * filesystem.f_frsize


def _disk_status(config: Config) -> dict[str, object]:
    free = _free_bytes(_managed_worktrees_root(config))
    advisory = config.disk_advisory_bytes
    provisioning = config.disk_provisioning_floor_bytes
    emergency = config.disk_emergency_bytes
    if advisory is None or provisioning is None or emergency is None:
        state = "unconfigured"
    elif free < emergency:
        state = "emergency"
    elif free < provisioning:
        state = "provisioning-blocked"
    elif free < advisory:
        state = "advisory"
    else:
        state = "healthy"
    return {
        "free_bytes": free,
        "state": state,
        "advisory_bytes": advisory,
        "provisioning_floor_bytes": provisioning,
        "emergency_bytes": emergency,
    }


def _format_gib(value: int) -> str:
    return f"{value / GIB:.1f} GiB"


def _assert_create_disk_space(config: Config, override: bool) -> None:
    status = _disk_status(config)
    state = _as_str(status["state"], "disk state")
    free = _as_int(status["free_bytes"], "disk free bytes")
    remedy = "run 'wrkslots audit' and 'wrkslots clean-caches', then retry"
    if state == "emergency":
        threshold = _as_int(status["emergency_bytes"], "disk emergency bytes", minimum=1)
        raise Refusal(
            f"free space {_format_gib(free)} is below the emergency floor "
            f"{_format_gib(threshold)}; stop builds, publish durable work, and {remedy}. "
            "--override-disk-floor does not bypass the emergency floor"
        )
    if state == "provisioning-blocked" and not override:
        threshold = _as_int(
            status["provisioning_floor_bytes"],
            "disk provisioning floor bytes",
            minimum=1,
        )
        raise Refusal(
            f"free space {_format_gib(free)} is below the provisioning floor "
            f"{_format_gib(threshold)}; {remedy}. Use --override-disk-floor only "
            "after inspecting the pressure"
        )
    if state == "provisioning-blocked":
        print(
            f"WARNING: overriding disk provisioning floor with {_format_gib(free)} free; "
            f"{remedy}",
            file=sys.stderr,
        )
    elif state == "advisory":
        print(
            f"WARNING: disk free space is advisory at {_format_gib(free)}; {remedy}",
            file=sys.stderr,
        )


def _assert_agent_and_slot_free(
    config: Config,
    slot: str,
    agent: str,
    slot_type: str,
    *,
    enforce_cap: bool = True,
) -> None:
    if _is_representation_directory(config, _slot_directory(config, slot, slot_type)):
        raise Refusal(
            f"slot name {slot!r} is reserved for wrkslots storage in the control directory"
        )
    states = _load_all_active(config)
    for state in states:
        for record in state.slots:
            if record.slot == slot:
                raise Refusal(f"slot {slot!r} is already active on {state.machine}")
            if (
                slot_type == "agent"
                and record.slot_type == "agent"
                and record.import_source is None
                and record.agent == agent
            ):
                raise Refusal(
                    f"agent {agent!r} already owns slot {record.slot!r} on {state.machine}"
                )
    if enforce_cap:
        _assert_active_slot_cap(config, states)
    for archive in _load_all_archives(config):
        for archived_record in archive.records:
            if archived_record.get("slot") == slot:
                raise Refusal(
                    f"slot {slot!r} is archived on {archive.machine}; finished slots are never reused"
                )


def _assert_create_target_clear(
    config: Config,
    states: Sequence[ActiveState],
    slot: str,
    slot_type: str,
    plan: Sequence[PlannedCheckout],
    vcs: _GitVcs,
) -> None:
    """Refuse collisions relevant to one create without requiring unrelated storage health."""

    target_slot = _slot_directory(config, slot, slot_type)
    for state in states:
        for record in state.slots:
            active_slot = _slot_directory(config, record.slot, record.slot_type)
            if _path_is_within(target_slot, active_slot) or _path_is_within(
                active_slot, target_slot
            ):
                raise Refusal(
                    f"requested slot path {target_slot} overlaps active slot "
                    f"{record.machine}/{record.slot} at {active_slot}"
                )
            for checkout in record.checkouts:
                active_path = _stored_path(config, checkout.path, "checkout path")
                for item in plan:
                    destination = _stored_path(
                        config, item.destination, "checkout destination"
                    )
                    if _path_is_within(destination, active_path) or _path_is_within(
                        active_path, destination
                    ):
                        raise Refusal(
                            f"checkout destination {destination} overlaps active checkout "
                            f"{record.machine}/{record.slot}/{checkout.name} at {active_path}"
                        )

    repositories = {
        _stored_repository_path(config, checkout.repository)[1]
        for state in states
        for record in state.slots
        for checkout in record.checkouts
    }
    repositories.update(
        _stored_repository_path(config, item.repository)[1] for item in plan
    )
    registrations = {
        repository: vcs.listed_worktrees(repository) for repository in repositories
    }
    for repository, worktrees in registrations.items():
        for registered in worktrees:
            # The source worktree may contain the configured managed root (the
            # documented `--repo NAME=.` case). It owns the linked worktree;
            # it is not a stale target registration. Every other overlapping
            # registration remains a collision.
            if registered == repository.absolute():
                continue
            if _path_is_within(target_slot, registered) or _path_is_within(
                registered, target_slot
            ):
                raise Refusal(
                    f"requested slot path {target_slot} overlaps Git-registered worktree "
                    f"{registered} in repository {repository}; inspect "
                    "'git worktree list --porcelain' and repair or remove that exact "
                    "stale registration before retrying"
                )


def _format_storage_inconsistency(item: StorageInconsistency) -> str:
    identity = "/".join(
        value
        for value in (item.machine, item.slot_type, item.slot, item.checkout)
        if value is not None
    )
    return f"kind={item.kind} target={identity or '-'}: {item.detail}"


def _warn_retained_storage_inconsistencies(
    findings: Sequence[StorageInconsistency],
) -> None:
    if not findings:
        return
    print(
        f"WARNING: registry/storage state remains INCONSISTENT "
        f"({len(findings)} finding(s)); this create target is distinct and none of "
        "the reported state was changed",
        file=sys.stderr,
    )
    for item in findings:
        print(f"INCONSISTENT {_format_storage_inconsistency(item)}", file=sys.stderr)
        print(f"  REMEDY: {item.remedy}", file=sys.stderr)


def _create_journal_payload(
    config: Config,
    args: argparse.Namespace,
    owner: ProcessIdentity | None,
    task_scope: TaskScopeIdentity | None,
    coordinator_lease: ProcessIdentity,
    plan: Sequence[PlannedCheckout],
    created: Sequence[Checkout],
    *,
    created_at: str,
    heartbeat_at: str,
    hook_progress: int,
    operation_id: str,
) -> dict[str, object]:
    value: dict[str, object] = {
        "schema": SCHEMA,
        "kind": "create",
        "machine": config.machine,
        "slot": args.slot,
        "agent": args.agent,
        "task": args.task,
        "purpose": args.purpose,
        "slot_type": args.slot_type,
        "created_at": created_at,
        "heartbeat_at": heartbeat_at,
        "heartbeat_ttl_seconds": config.heartbeat_ttl_seconds,
        "owner": _identity_to_obj(owner),
        "coordinator_lease": _identity_to_obj(coordinator_lease),
        "planned": [_planned_to_obj(item) for item in plan],
        "created": [_checkout_to_obj(item) for item in created],
        "post_provision_hooks": list(config.post_provision_hooks),
        "hook_progress": hook_progress,
        "hook_failure": None,
        "failure_policy": "leave-for-inspection",
        "operation_id": operation_id,
    }
    if task_scope is not None:
        value["task_scope"] = _task_scope_to_obj(task_scope)
    return value


def _run_post_provision_hooks(
    config: Config,
    created: Sequence[Checkout],
    journal_path: Path,
    journal: dict[str, object],
    *,
    start: int = 0,
) -> int:
    hooks = config.post_provision_hooks
    total = len(created) * len(hooks)
    if start < 0 or start > total:
        raise StateError("create journal hook progress is out of range")
    for step in range(start, total):
        checkout = created[step // len(hooks)]
        hook_index = step % len(hooks)
        command = hooks[hook_index]
        path = _stored_path(config, checkout.path, "hook checkout path")
        attempt = {
            "checkout": checkout.name,
            "hook_index": hook_index,
            "command": command,
            "status": "running",
        }
        journal["hook_failure"] = attempt
        _write_journal(config, journal, journal_path=journal_path)
        env = os.environ.copy()
        env.update(
            {
                "WRKSLOTS_PROJECT_ROOT": str(config.root),
                "WRKSLOTS_SLOT": path.parent.name if config.layout == "nested" else path.name,
                "WRKSLOTS_CHECKOUT": str(path),
                "WRKSLOTS_CHECKOUT_NAME": checkout.name,
            }
        )
        print(
            f"post-provision hook {step + 1}/{total} checkout={checkout.name}: {command}",
            file=sys.stderr,
        )
        try:
            completed = subprocess.run(
                _with_proxy(["/bin/sh", "-c", command], env),
                cwd=path,
                env=env,
                text=True,
                capture_output=True,
                check=False,
            )
        except OSError as exc:
            attempt["status"] = "failed-to-start"
            attempt["detail"] = str(exc)
            journal["hook_failure"] = attempt
            _write_journal(config, journal, journal_path=journal_path)
            raise Refusal(
                f"post-provision hook {hook_index + 1} for checkout {checkout.name} "
                f"could not start: {exc}; slot was left for inspection with journal "
                f"{journal_path}. Fix the cause and run 'wrkslots recover'"
            ) from exc
        if completed.returncode != 0:
            attempt["status"] = "failed"
            attempt["returncode"] = completed.returncode
            journal["hook_failure"] = attempt
            _write_journal(config, journal, journal_path=journal_path)
            if completed.stdout:
                print("post-provision hook stdout:", file=sys.stderr)
                print(completed.stdout, end="" if completed.stdout.endswith("\n") else "\n", file=sys.stderr)
            if completed.stderr:
                print("post-provision hook stderr:", file=sys.stderr)
                print(completed.stderr, end="" if completed.stderr.endswith("\n") else "\n", file=sys.stderr)
            raise Refusal(
                f"post-provision hook {hook_index + 1} for checkout {checkout.name} "
                f"failed with rc {completed.returncode}; slot was left for inspection "
                f"with journal {journal_path}. Fix the cause and run 'wrkslots recover'"
            )
        journal["hook_progress"] = step + 1
        journal["hook_failure"] = None
        _write_journal(config, journal, journal_path=journal_path)
    return total


# A repository's own Git hook installer, run by 'create' after the slot is
# registered.  See _run_setup_hook_installers for which repositories qualify.
SETUP_HOOKS_SCRIPT = "scripts/setup-hooks.sh"
SETUP_HOOKS_TIMEOUT_SECONDS = 60.0
SETUP_HOOKS_TAIL_BYTES = 4096
SETUP_HOOKS_TAIL_LINES = 20
_SETUP_HOOKS_GIT_SECONDS = 30.0
_SETUP_HOOKS_TERM_GRACE_SECONDS = 2.0
# Ambient settings that would point the installer's Git at another repository.
_SETUP_HOOKS_CLEARED_ENV = (
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_INDEX_FILE",
    "GIT_COMMON_DIR",
    "GIT_OBJECT_DIRECTORY",
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE",
    "GIT_PREFIX",
)


@dataclasses.dataclass(frozen=True)
class SetupHookResult:
    """What happened to one repository's hook installer during 'create'.

    ``status`` is one of: ran (exit status 0), failed, timed-out,
    failed-to-start, not-executable, not-run-shared-git-config,
    not-run-hooks-already-configured, or inspection-failed.
    """

    path: str
    status: str
    returncode: int | None = None
    output_tail: str = ""
    detail: str = ""

    def to_obj(self) -> dict[str, object]:
        """Return this result as the JSON object 'create' reports for one repository."""
        return {
            "path": self.path,
            "script": SETUP_HOOKS_SCRIPT,
            "status": self.status,
            "returncode": self.returncode,
            "output_tail": self.output_tail,
            "detail": self.detail,
        }


def _setup_hooks_git_dirs(repository: Path) -> tuple[Path, Path]:
    """Return the absolute Git directory and common directory of ``repository``."""

    completed = _GitVcs._run(
        repository,
        ["rev-parse", "--path-format=absolute", "--git-dir", "--git-common-dir"],
        timeout_seconds=_SETUP_HOOKS_GIT_SECONDS,
        timeout_refusal=f"git rev-parse in {repository} did not finish",
    )
    lines = completed.stdout.splitlines()
    if len(lines) != 2 or not all(lines):
        raise StateError(f"git rev-parse in {repository} printed {completed.stdout!r}")
    return Path(lines[0]).resolve(), Path(lines[1]).resolve()


def _setup_hooks_configured_path(repository: Path) -> str | None:
    """Return ``repository``'s own core.hooksPath, or None when it sets none.

    Only the repository's local configuration counts: a global or system
    setting says nothing about whether this slot's repository was set up.
    """

    completed = _GitVcs._run(
        repository,
        ["config", "--local", "--get", "core.hooksPath"],
        check=False,
        timeout_seconds=_SETUP_HOOKS_GIT_SECONDS,
        timeout_refusal=f"git config in {repository} did not finish",
    )
    if completed.returncode == 1:
        return None
    if completed.returncode != 0:
        raise StateError(
            f"git config --local --get core.hooksPath in {repository} exited "
            f"{completed.returncode}: {completed.stderr.strip()}"
        )
    return completed.stdout.strip()


def _setup_hooks_repositories(checkout: Path) -> list[Path]:
    """Return ``checkout`` and every initialized submodule below it, recursively."""

    completed = _GitVcs._run(
        checkout,
        [
            "submodule",
            "foreach",
            "--quiet",
            "--recursive",
            'printf "%s\\0" "$displaypath"',
        ],
        timeout_seconds=_SETUP_HOOKS_GIT_SECONDS,
        timeout_refusal=f"git submodule foreach in {checkout} did not finish",
    )
    return [checkout] + [
        checkout / name for name in completed.stdout.split("\0") if name
    ]


def _output_tail(stream: IO[bytes]) -> str:
    """Return at most the last SETUP_HOOKS_TAIL_LINES lines of ``stream``."""

    stream.seek(0, os.SEEK_END)
    size = stream.tell()
    stream.seek(max(0, size - SETUP_HOOKS_TAIL_BYTES))
    text = stream.read().decode("utf-8", errors="replace")
    lines = text.splitlines()
    if size > SETUP_HOOKS_TAIL_BYTES and lines:
        lines = lines[1:]  # the first line was probably cut
    return "\n".join(lines[-SETUP_HOOKS_TAIL_LINES:])


def _run_one_setup_hook_installer(repository: Path) -> SetupHookResult:
    """Run ``repository``'s installer once, bounded, with its output captured."""

    env = {
        key: value
        for key, value in os.environ.items()
        if key not in _SETUP_HOOKS_CLEARED_ENV
    }
    script = repository / SETUP_HOOKS_SCRIPT
    # The output goes to a file rather than a pipe, so a descendant that keeps
    # running after the installer exits cannot hold 'create' open.  The slot is
    # already registered, so failing to make that file is a result, not a raise.
    try:
        output_file = tempfile.TemporaryFile()
    except OSError as exc:
        return SetupHookResult(
            str(repository), "failed-to-start", detail=f"cannot create its output file: {exc}"
        )
    with output_file as output:
        try:
            process = subprocess.Popen(
                [str(script)],
                cwd=repository,
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=output,
                stderr=subprocess.STDOUT,
                start_new_session=True,
            )
        except OSError as exc:
            return SetupHookResult(str(repository), "failed-to-start", detail=str(exc))
        try:
            returncode = process.wait(timeout=SETUP_HOOKS_TIMEOUT_SECONDS)
        except subprocess.TimeoutExpired:
            with contextlib.suppress(OSError):
                os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=_SETUP_HOOKS_TERM_GRACE_SECONDS)
            except subprocess.TimeoutExpired:
                with contextlib.suppress(OSError):
                    os.killpg(process.pid, signal.SIGKILL)
                process.wait()
            return SetupHookResult(
                str(repository),
                "timed-out",
                returncode=process.returncode,
                output_tail=_output_tail(output),
                detail=f"stopped after {SETUP_HOOKS_TIMEOUT_SECONDS:g} s",
            )
        return SetupHookResult(
            str(repository),
            "ran" if returncode == 0 else "failed",
            returncode=returncode,
            output_tail=_output_tail(output),
        )


def _run_setup_hook_installers(
    config: Config, checkouts: Sequence[Checkout]
) -> tuple[int, list[SetupHookResult]]:
    """Run each new repository's own scripts/setup-hooks.sh; never raise.

    A repository qualifies when its Git configuration is private to this slot:
    its common Git directory lies inside the per-worktree Git directory of the
    checkout 'create' just added.  That is true of a submodule initialized in
    the new checkout, whose Git directory lives under
    <common>/worktrees/<checkout>/modules/, and false of the checkout itself,
    whose configuration is shared by every worktree of the repository, so a
    hook setting made once in the primary checkout already applies there and
    re-running the installer would rewrite state other slots use.  The script
    must be a regular, executable file; it runs from the repository root, with
    stdin closed, ambient GIT_DIR-style variables removed, and a bound of
    SETUP_HOOKS_TIMEOUT_SECONDS.  The slot is already registered, so a failure
    is reported, never raised.

    Returns the number of repositories inspected and one result for each
    repository that has the script.
    """

    checked = 0
    results: list[SetupHookResult] = []
    for checkout in checkouts:
        try:
            checkout_path = _stored_path(config, checkout.path, "checkout path")
        except (Refusal, StateError, OSError, ValueError) as exc:
            results.append(SetupHookResult(checkout.path, "inspection-failed", detail=str(exc)))
            continue
        try:
            slot_git_dir, _ = _setup_hooks_git_dirs(checkout_path)
            repositories = _setup_hooks_repositories(checkout_path)
        except (Refusal, StateError, OSError, ValueError) as exc:
            results.append(
                SetupHookResult(str(checkout_path), "inspection-failed", detail=str(exc))
            )
            continue
        for repository in repositories:
            checked += 1
            script = repository / SETUP_HOOKS_SCRIPT
            try:
                mode = script.lstat().st_mode
            except FileNotFoundError:
                continue
            except OSError as exc:
                results.append(
                    SetupHookResult(str(repository), "inspection-failed", detail=str(exc))
                )
                continue
            if not stat.S_ISREG(mode) or not mode & stat.S_IXUSR:
                results.append(
                    SetupHookResult(
                        str(repository),
                        "not-executable",
                        detail=f"{SETUP_HOOKS_SCRIPT} is not a regular executable file",
                    )
                )
                continue
            try:
                _, common_dir = _setup_hooks_git_dirs(repository)
            except (Refusal, StateError, OSError, ValueError) as exc:
                results.append(
                    SetupHookResult(str(repository), "inspection-failed", detail=str(exc))
                )
                continue
            if not common_dir.is_relative_to(slot_git_dir):
                results.append(
                    SetupHookResult(
                        str(repository),
                        "not-run-shared-git-config",
                        detail=f"its Git configuration {common_dir} is shared beyond this slot",
                    )
                )
                continue
            # A post-provision hook may already have installed hooks here (for
            # example a project's own hook dispatcher); the
            # installer would replace that setting, so it is left alone.
            try:
                configured = _setup_hooks_configured_path(repository)
            except (Refusal, StateError, OSError, ValueError) as exc:
                results.append(
                    SetupHookResult(str(repository), "inspection-failed", detail=str(exc))
                )
                continue
            if configured is not None:
                results.append(
                    SetupHookResult(
                        str(repository),
                        "not-run-hooks-already-configured",
                        detail=f"core.hooksPath is already {configured}",
                    )
                )
                continue
            results.append(_run_one_setup_hook_installer(repository))
    return checked, results


def _print_setup_hook_results(
    checked: int, results: Sequence[SetupHookResult], *, stream: TextIO
) -> None:
    """Print one 'hooks:' line per result, or the stated skip when nothing ran."""

    for result in results:
        where = f"{SETUP_HOOKS_SCRIPT} in {result.path}"
        if result.status == "ran":
            print(f"hooks: ran {where} (rc 0)", file=stream)
            continue
        if result.status in ("not-run-shared-git-config", "not-run-hooks-already-configured"):
            print(f"hooks: not run: {where}; {result.detail}", file=stream)
            continue
        if result.status == "failed":
            outcome = f"failed (rc {result.returncode})"
        elif result.status == "timed-out":
            outcome = f"timed out ({result.detail})"
        elif result.status == "failed-to-start":
            outcome = f"could not start: {result.detail}"
        elif result.status == "not-executable":
            outcome = f"not run: {result.detail}"
        else:
            outcome = f"not inspected: {result.detail}"
        print(
            f"hooks: WARNING {where} {outcome}; the slot was created without "
            "these Git hooks",
            file=stream,
        )
        if result.output_tail:
            print("hooks: output tail:", file=stream)
            for line in result.output_tail.splitlines():
                print(f"hooks: | {line}", file=stream)
    if all(result.status == "not-run-shared-git-config" for result in results):
        # A repository whose hooks were already configured is not in this set:
        # its "not run" line says its hooks are in place.
        print(
            f"hooks: skipped; no repository private to this slot has an executable "
            f"{SETUP_HOOKS_SCRIPT} ({checked} checked)",
            file=stream,
        )


def _cmd_create(args: argparse.Namespace) -> int:
    _require_coordinator_authorized(args, "worktree creation")
    args.slot_type = _require_slot_type(args, "worktree creation")
    config = _load_new_slot_config(args, "worktree creation")
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    if not args.task or not args.purpose:
        raise Refusal("task and purpose must be non-empty")
    owner = (
        _capture_registration_owner(args.owner_pid)
        if args.owner_pid is not None
        else None
    )
    task_scope = _task_scope_from_args(args, owner)
    coordinator_lease = _read_process_identity(args.coordinator_pid)
    _assert_create_owner_authorized(owner, coordinator_lease)
    vcs = _GitVcs()
    with _mutation_locks(config, args.wait_lock):
        _assert_create_processes(
            owner, coordinator_lease, stage="before create mutation"
        )
        # A validation cleanup seal protects only the exact slot paths recorded
        # in that seal. It may remain after its worker exits unexpectedly, and
        # must not turn an unrelated cleanup failure into a global admission
        # outage. The disjointness check below still rejects reuse or overlap
        # with every sealed path before this create writes anything.
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        _recover_orphaned_validate_batch_seal(config)
        states, archives = _validate_global_state(config)
        paired_finish_path = _validate_batch_paired_finish_path(config)
        cleanup_exclusions = (
            frozenset({paired_finish_path})
            if paired_finish_path is not None
            else frozenset()
        )
        interrupted_creates = _classify_create_journals(
            config,
            states,
            archives,
            excluded_paths=cleanup_exclusions,
        )
        _assert_interrupted_creates_unrelated(
            config,
            interrupted_creates,
            slot=args.slot,
            agent=args.agent,
            slot_type=args.slot_type,
        )
        before = _global_rows(states, archives)
        _ensure_state_shard(config)
        state = _load_active(config)
        _assert_agent_and_slot_free(config, args.slot, args.agent, args.slot_type)
        _assert_create_disk_space(config, args.override_disk_floor)
        slot_path = _slot_directory(config, args.slot, args.slot_type)
        if slot_path.exists() or slot_path.is_symlink():
            raise Refusal(f"slot path already exists: {slot_path}")
        plan = _create_plan(config, args, vcs)
        _assert_validate_batch_seals_disjoint_from_create(
            config,
            slot=args.slot,
            slot_type=args.slot_type,
            plan=plan,
        )
        _assert_interrupted_creates_unrelated(
            config,
            interrupted_creates,
            slot=args.slot,
            agent=args.agent,
            slot_type=args.slot_type,
            plan=plan,
        )
        plan_repositories = tuple(
            _stored_repository_path(config, item.repository)[1] for item in plan
        )
        storage_inconsistencies = _registry_storage_inconsistencies(
            config, states, additional_repositories=plan_repositories
        )
        _assert_create_target_clear(
            config, states, args.slot, args.slot_type, plan, vcs
        )
        interrupted_creates = _classify_create_journals(
            config,
            states,
            archives,
            excluded_paths=cleanup_exclusions,
        )
        if _validate_batch_paired_finish_path(config) != paired_finish_path:
            raise Refusal(
                "private validation finish changed while create was prepared"
            )
        _assert_interrupted_creates_unrelated(
            config,
            interrupted_creates,
            slot=args.slot,
            agent=args.agent,
            slot_type=args.slot_type,
            plan=plan,
        )
        _warn_retained_storage_inconsistencies(storage_inconsistencies)
        slot_path.parent.mkdir(parents=True, exist_ok=True)
        created_at = _utc_now()
        heartbeat_at = created_at
        operation_id = uuid.uuid4().hex
        journal_path = _create_journal_path(config, args.slot)
        created: list[Checkout] = []
        _write_journal(
            config,
            _create_journal_payload(
                config,
                args,
                owner,
                task_scope,
                coordinator_lease,
                plan,
                created,
                created_at=created_at,
                heartbeat_at=heartbeat_at,
                hook_progress=0,
                operation_id=operation_id,
            ),
            journal_path=journal_path,
        )
        representation = _requested_representation(config, args)
        if representation == "image":
            # The slot directory becomes the mount point of a fresh image; for
            # the flat layout `git worktree add` then fills the empty image root.
            _provision_slot_image(config, args.slot, args.slot_type, slot_path)
            _fsync_directory(slot_path.parent)
        elif config.layout == "nested":
            slot_path.mkdir(mode=0o755)
            _fsync_directory(slot_path.parent)
        for item in plan:
            _relative, repository = _stored_repository_path(config, item.repository)
            destination = _stored_path(config, item.destination, "checkout destination")
            head = vcs.add_worktree(repository, destination, item.branch, item.start_point)
            checkout = Checkout(
                name=item.name,
                path=item.destination,
                repository=item.repository,
                branch=item.branch,
                start_point=item.start_point,
                remote=item.remote,
                remote_url_sha256=item.remote_url_sha256,
                landed_ref=item.landed_ref,
                head=head,
            )
            created.append(checkout)
            _write_journal(
                config,
                _create_journal_payload(
                    config,
                    args,
                    owner,
                    task_scope,
                    coordinator_lease,
                    plan,
                    created,
                    created_at=created_at,
                    heartbeat_at=heartbeat_at,
                    hook_progress=0,
                    operation_id=operation_id,
                ),
                journal_path=journal_path,
            )
            _interrupt_for_test("after-create-worktree")
        hook_journal = _create_journal_payload(
            config,
            args,
            owner,
            task_scope,
            coordinator_lease,
            plan,
            created,
            created_at=created_at,
            heartbeat_at=heartbeat_at,
            hook_progress=0,
            operation_id=operation_id,
        )
        hook_progress = _run_post_provision_hooks(
            config, created, journal_path, hook_journal
        )
        for checkout in created:
            _assert_checkout_identity_unchanged(config, checkout, vcs)
        _assert_create_processes(
            owner,
            coordinator_lease,
            stage="during create; recovery journal is preserved",
        )
        heartbeat_at = _utc_now()
        _write_journal(
            config,
            _create_journal_payload(
                config,
                args,
                owner,
                task_scope,
                coordinator_lease,
                plan,
                created,
                created_at=created_at,
                heartbeat_at=heartbeat_at,
                hook_progress=hook_progress,
                operation_id=operation_id,
            ),
            journal_path=journal_path,
        )
        if task_scope is not None:
            _verify_task_scope_before_publication(task_scope, _CREATE_SCOPE_REMEDY)
        record = ActiveRecord(
            slot=args.slot,
            agent=args.agent,
            task=args.task,
            purpose=args.purpose,
            slot_type=args.slot_type,
            machine=config.machine,
            generation=1,
            created_at=created_at,
            heartbeat_at=heartbeat_at,
            heartbeat_ttl_seconds=config.heartbeat_ttl_seconds,
            owner=owner,
            coordinator_lease=coordinator_lease,
            coordinator_recovery_note=None,
            handoff=None,
            checkouts=tuple(created),
            task_scope=task_scope,
        )
        state = _append_record(state, record)
        _write_active_state(
            config,
            state,
            action="slot-created",
            slot=record.slot,
            evidence={
                "slot_type": record.slot_type,
                "coordinator_authorized": True,
                "coordinator": _identity_to_obj(coordinator_lease),
            },
        )
        _interrupt_for_test("after-active-write")
        _clear_journal(
            config,
            _as_mapping(_read_json(journal_path, "create journal"), "create journal"),
            journal_path=journal_path,
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    # The slot is registered and every checkout is materialized, including the
    # post-provision hooks' submodules; installers run outside the lock and
    # cannot undo or fail the creation.
    hooks_checked, hook_results = _run_setup_hook_installers(config, record.checkouts)
    if args.format == "json":
        _print_setup_hook_results(hooks_checked, hook_results, stream=sys.stderr)
        print(
            json.dumps(
                {
                    "slot": record.slot,
                    "slot_type": record.slot_type,
                    "setup_hooks": {
                        "script": SETUP_HOOKS_SCRIPT,
                        "timeout_seconds": SETUP_HOOKS_TIMEOUT_SECONDS,
                        "repositories_checked": hooks_checked,
                        "results": [result.to_obj() for result in hook_results],
                    },
                    "agent": record.agent,
                    "generation": record.generation,
                    "owner_process": "unbound" if owner is None else "bound",
                    "retained_storage_inconsistencies": [
                        item.to_obj() for item in storage_inconsistencies
                    ],
                    "checkouts": [
                        {
                            "name": checkout.name,
                            "path": str(
                                _stored_path(config, checkout.path, "checkout path")
                            ),
                            "head": checkout.head,
                        }
                        for checkout in record.checkouts
                    ],
                },
                indent=2,
                sort_keys=True,
            )
        )
    else:
        print(
            f"created slot={record.slot} agent={record.agent} generation={record.generation} "
            f"checkouts={len(record.checkouts)} "
            f"retained_storage_inconsistencies={len(storage_inconsistencies)}"
        )
        for checkout in record.checkouts:
            print(
                f"checkout={checkout.name} "
                f"path={_stored_path(config, checkout.path, 'checkout path')} "
                f"head={checkout.head}"
            )
        if owner is None:
            print("owner_process=unbound; run 'wrkslots adopt' before heartbeat or finish")
        _print_setup_hook_results(hooks_checked, hook_results, stream=sys.stdout)
    return 0


def _cmd_classify_create_journals(args: argparse.Namespace) -> int:
    """Classify existing create journals without locks, authorization, or writes."""

    config = _load_config(args.project_root, args.machine)
    slot_type = _require_slot_type(args, "create-journal classification")
    slot = _validate_name(args.slot, "slot")
    agent = _validate_name(args.agent, "agent")
    _refuse_partial_state(config, allow_orphaned_validate_batch_seals=True)
    before_states, before_archives = _validate_global_state(config)
    before_rows = _global_rows(before_states, before_archives)
    before_paths = tuple(_outstanding_journals(config))
    rows = _classify_create_journals(config, before_states, before_archives)
    _assert_interrupted_creates_unrelated(
        config, rows, slot=slot, agent=agent, slot_type=slot_type
    )
    after_states, after_archives = _validate_global_state(config)
    if before_rows != _global_rows(after_states, after_archives):
        raise Refusal("active registry changed while create journals were classified")
    if before_paths != tuple(row.path for row in rows):
        raise Refusal("recovery journal set changed before it was classified")
    _assert_create_journal_classifications_stable(
        config, rows, after_states, after_archives
    )
    payload = {
        "blocking": False,
        "journals": [row.to_obj() for row in rows],
        "requested": {
            "agent": agent,
            "slot": slot,
            "slot_path": str(_slot_directory(config, slot, slot_type)),
            "slot_type": slot_type,
        },
        "schema": 2,
    }
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        live_incomplete = sum(
            row.state == "live-incomplete-create" for row in rows
        )
        completed = sum(row.state == "completed-create" for row in rows)
        dead_incomplete = sum(
            row.state == "dead-incomplete-create" for row in rows
        )
        print(
            f"NONBLOCKING: journals={len(rows)} "
            f"live-incomplete-create={live_incomplete} "
            f"completed-create={completed} "
            f"dead-incomplete-create={dead_incomplete}; all are unrelated to requested "
            f"{slot_type} slot {slot}"
        )
        for row in rows:
            dirty = ",".join(row.dirty_checkouts) or "none"
            print(
                f"JOURNAL: state={row.state} machine={row.machine} slot={row.slot} "
                f"agent={row.agent} dirty_checkouts={dirty} journal={row.path}"
            )
    return 0


def _historical_source_row(
    config: Config, args: argparse.Namespace
) -> tuple[_ImportSource, Mapping[str, object], ProcessIdentity, str, str, str, str]:
    source_relative, source_path = _relative_inside(
        config.root, args.from_state_file, "historical state file"
    )
    _refuse_symlink(source_path, "historical state file")
    try:
        source_bytes = source_path.read_bytes()
        source_value: object = json.loads(source_bytes.decode("utf-8"))
    except FileNotFoundError as exc:
        raise Refusal(
            f"historical state file is missing: {source_path}. state: REFUSED -- "
            "no import journal or active row was written. remedy: restore the exact "
            "source file and rerun import-existing"
        ) from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise Refusal(
            f"cannot read historical state file {source_path}: {exc}. state: REFUSED -- "
            "no import journal or active row was written. remedy: preserve and repair "
            "the source file, then rerun import-existing"
        ) from exc
    source = _as_mapping(source_value, "historical state file")
    _exact_keys(
        source,
        {"version", "updated", "slots", "lease_history"},
        set(),
        "historical state file",
    )
    if _as_int(source["version"], "historical state file.version") != 3:
        raise Refusal(
            "historical state file has an unsupported version. state: REFUSED -- "
            "no import journal or active row was written. remedy: use a version 3 "
            "worktree-state.json source or add a separately reviewed converter"
        )
    _parse_timestamp(
        _as_str(source["updated"], "historical state file.updated"),
        "historical state file.updated",
    )
    slots = _as_mapping(source["slots"], "historical state file.slots")
    if args.slot not in slots:
        raise Refusal(
            f"historical state file has no row for slot {args.slot}. state: REFUSED -- "
            "no import journal or active row was written. remedy: select a slot named "
            "by the source file rather than reconstructing one from disk"
        )
    row = _as_mapping(slots[args.slot], f"historical slot {args.slot}")
    status = _as_str(row.get("status"), f"historical slot {args.slot}.status")
    if status == "released":
        raise Refusal(
            f"historical slot {args.slot} is recorded released. state: REFUSED -- "
            "no active row was written because import-existing only admits storage "
            "that still exists. remedy: retain this source row as history; if its path "
            "exists, investigate the registry disagreement before importing anything"
        )
    if status not in HISTORICAL_ACTIVE_STATUSES:
        raise Refusal(
            f"historical slot {args.slot} has unsupported status {status!r}. state: "
            "REFUSED -- no import journal or active row was written. remedy: preserve "
            "the row and add explicit handling for that status before retrying"
        )
    sidecar_value = row.get("owner_sidecar")
    if sidecar_value is None:
        raise Refusal(
            f"historical slot {args.slot} has no owner_sidecar. state: REFUSED -- no "
            "import journal or active row was written because owner death would remain "
            "unknowable. remedy: leave the slot unregistered and include it in the "
            "migration remainder unless a source with exact PID, start ticks, boot ID, "
            "and cgroup is found"
        )
    sidecar = _as_mapping(sidecar_value, f"historical slot {args.slot}.owner_sidecar")
    _exact_keys(
        sidecar,
        {
            "schema_version",
            "slot",
            "agent",
            "task",
            "recorded_at",
            "source",
            "supervisor_pid",
            "boot_id",
            "start_ticks",
            "cgroup_path",
            "generation",
        },
        {"tmux_pane_id", "lease"},
        f"historical slot {args.slot}.owner_sidecar",
    )
    if _as_int(sidecar["schema_version"], "historical owner schema") != 1:
        raise Refusal(
            f"historical slot {args.slot} has an unsupported owner_sidecar schema. "
            "state: REFUSED -- no import journal or active row was written. remedy: "
            "preserve the row and add explicit handling for that schema before retrying"
        )
    _parse_timestamp(
        _as_str(sidecar["recorded_at"], "historical owner recorded_at"),
        "historical owner recorded_at",
    )
    if not _as_str(sidecar["source"], "historical owner source"):
        raise Refusal(
            f"historical slot {args.slot} owner_sidecar has no source. state: REFUSED -- "
            "no import journal or active row was written. remedy: preserve and repair "
            "the source row before retrying"
        )
    sidecar_slot = _as_str(sidecar["slot"], "historical owner slot")
    if sidecar_slot != args.slot:
        raise Refusal(
            f"historical owner_sidecar names slot {sidecar_slot}, not {args.slot}. state: "
            "REFUSED -- no import journal or active row was written. remedy: repair the "
            "source inconsistency before retrying"
        )
    if args.source_host_id is None:
        raise Refusal(
            "historical owner_sidecar has no stable host identity. state: REFUSED -- no "
            "import journal or active row was written. remedy: on the host that produced "
            "the source registry, pass --source-host-id with its /etc/machine-id value"
        )
    current_host_id = _host_id()
    if args.source_host_id != current_host_id:
        raise Refusal(
            f"--source-host-id does not match this host. state: REFUSED -- no import "
            "journal or active row was written because a foreign process record cannot "
            "prove local owner death. remedy: run the import on the source host or leave "
            "the row in the migration remainder"
        )
    owner = _identity_from_obj(
        {
            "pid": sidecar["supervisor_pid"],
            "start_ticks": sidecar["start_ticks"],
            "boot_id": sidecar["boot_id"],
            "host_id": current_host_id,
            "cgroup_path": sidecar["cgroup_path"],
        },
        f"historical slot {args.slot}.owner",
    )
    assert owner is not None
    owner_state, owner_detail = _process_state(owner)
    if owner_state == "live":
        raise Refusal(
            f"historical slot {args.slot} still has its recorded owner alive: "
            f"{owner_detail}. state: REFUSED -- no import journal or active row was "
            "written. remedy: have that owner use ordinary import-existing with "
            "--verified-live and --owner-pid, or wait for this exact process generation "
            "to exit before retrying the historical import"
        )
    if owner_state != "dead":
        raise Refusal(
            f"historical slot {args.slot} owner death is indeterminate: {owner_detail}. "
            "state: REFUSED -- no import journal or active row was written; unavailable "
            "process evidence is not proof of death. remedy: restore process evidence on "
            "the source host or leave the row in the migration remainder"
        )
    expected_generation = f"{owner.boot_id}:{owner.pid}:{owner.start_ticks}"
    if sidecar.get("generation") is not None and sidecar.get("generation") != expected_generation:
        raise Refusal(
            f"historical slot {args.slot} owner generation disagrees with its process "
            "fields. state: REFUSED -- no import journal or active row was written. "
            "remedy: preserve and repair the source row before retrying"
    )
    agent = _validate_name(_as_str(sidecar["agent"], "historical owner agent"), "agent")
    try:
        task, purpose = _historical_task_and_purpose(
            row, f"historical slot {args.slot}", agent
        )
    except StateError as exc:
        raise Refusal(
            f"historical slot {args.slot} has invalid task or purpose evidence: "
            f"{exc}. state: "
            "REFUSED -- no import journal or active row was written. remedy: repair the "
            "source inconsistency before retrying"
        ) from exc
    created_at = _as_str(row.get("allocated"), f"historical slot {args.slot}.allocated")
    _parse_timestamp(created_at, f"historical slot {args.slot}.allocated")
    import_source = _ImportSource(
        format="worktree-state-v3",
        path=source_relative,
        file_sha256=hashlib.sha256(source_bytes).hexdigest(),
        row_sha256=_event_digest(row),
        status=status,
        row=dict(row),
    )
    return import_source, row, owner, agent, task, purpose, created_at


def _historical_task_and_purpose(
    row: Mapping[str, object], label: str, agent: str
) -> tuple[str, str]:
    sidecar = _as_mapping(row.get("owner_sidecar"), f"{label}.owner_sidecar")
    agents = [
        _as_mapping(item, f"{label}.agents[{index}]")
        for index, item in enumerate(_as_list(row.get("agents"), f"{label}.agents"))
    ]
    writable = [
        item
        for item in agents
        if item.get("name") == agent and item.get("read_only") is False
    ]
    if not writable:
        raise StateError(f"{label} does not list owner {agent} as a writable agent")
    task_values: list[str] = []
    for task_label, value in (
        (f"{label}.task", row.get("task")),
        (f"{label}.owner_sidecar.task", sidecar.get("task")),
    ):
        if value is None:
            task_values.append("")
            continue
        task_values.append(_as_str(value, task_label))
    writable_tasks = {
        _as_str(item.get("task"), f"{label}.writable_agent[{index}].task")
        for index, item in enumerate(writable)
        if item.get("task") is not None
    }
    writable_tasks.discard("")
    if len(writable_tasks) > 1:
        raise StateError(f"{label} records conflicting writable-agent task values")
    row_task, owner_task = task_values
    task = (
        row_task
        or owner_task
        or next(iter(writable_tasks), HISTORICAL_TASK_NOT_RECORDED)
    )
    raw_purpose = row.get("purpose")
    purpose = (
        HISTORICAL_PURPOSE_NOT_RECORDED
        if raw_purpose is None
        else _as_str(raw_purpose, f"{label}.purpose")
    )
    if not purpose:
        purpose = HISTORICAL_PURPOSE_NOT_RECORDED
    return task, purpose


def _historical_checkouts(
    config: Config,
    args: argparse.Namespace,
    row: Mapping[str, object],
    vcs: _GitVcs,
) -> tuple[Checkout, ...]:
    repositories = _assignments(args.repo, "repository")
    remotes = _assignments(args.remote, "remote")
    remote_urls = _assignments(args.remote_url, "trusted remote URL")
    source_paths: dict[str, tuple[str, Path]] = {}
    for key, value in row.items():
        if not key.endswith("_path"):
            continue
        name = _validate_name(key.removesuffix("_path"), "historical checkout name")
        raw_path = _as_str(value, f"historical slot {args.slot}.{key}")
        if raw_path == "-":
            continue
        relative, destination = _relative_inside(
            config.root, raw_path, f"historical checkout {name} path"
        )
        expected, expected_path = _checkout_path_for_layout(
            config, args.slot, name, args.slot_type, "nested"
        )
        if relative != expected or destination != expected_path:
            raise Refusal(
                f"historical checkout {name} path {raw_path!r} is not the nested path "
                f"{expected!r} for slot {args.slot}. state: REFUSED -- no import journal "
                "or active row was written. remedy: repair the source row or move the "
                "checkout through a separately reviewed operation before retrying"
            )
        source_paths[name] = (relative, destination)
    if not source_paths:
        raise Refusal(
            f"historical slot {args.slot} has no NAME_path fields. state: REFUSED -- "
            "no import journal or active row was written. remedy: preserve and repair "
            "the source row before retrying"
        )
    unknown_repositories = sorted(set(repositories) - set(source_paths))
    if unknown_repositories:
        raise Refusal(
            "repository supplied for checkout absent from the historical row: "
            + ", ".join(unknown_repositories)
        )
    for mapping, label in (
        (remotes, "remote"),
        (remote_urls, "trusted remote URL"),
    ):
        unknown = sorted(set(mapping) - set(repositories))
        if unknown:
            raise Refusal(f"{label} supplied for unknown repository: {', '.join(unknown)}")
    present_without_repository = sorted(
        name
        for name, (_relative, destination) in source_paths.items()
        if (destination.exists() or destination.is_symlink()) and name not in repositories
    )
    if present_without_repository:
        rendered = " ".join(
            f"--repo {name}=<source-repository>" for name in present_without_repository
        )
        raise Refusal(
            "historical slot contains checkout paths with no repository mapping: "
            f"{', '.join(present_without_repository)}. state: REFUSED -- no import "
            "journal or active row was written. remedy: rerun with {rendered}"
        )
    checkouts: list[Checkout] = []
    for name, raw_repository in sorted(repositories.items()):
        relative, destination = source_paths[name]
        repository_relative, repository = _repository_path(config, raw_repository)
        if not destination.exists() and not destination.is_symlink():
            if destination.absolute() in vcs.listed_worktrees(repository):
                raise Refusal(
                    f"historical checkout {name} is missing but Git still registers "
                    f"{destination}. state: REFUSED -- no import journal or active row "
                    "was written. remedy: repair the Git worktree registration before retrying"
                )
            continue
        if destination.is_symlink() or not destination.is_dir():
            raise Refusal(
                f"historical checkout is unsafe: {destination}. state: REFUSED -- no "
                "import journal or active row was written. remedy: preserve and inspect "
                "the path before retrying"
            )
        head = vcs.verify_existing_worktree(repository, destination)
        branch = vcs.branch(destination)
        remote = _validate_remote(remotes.get(name, config.default_remote))
        authorized_url = remote_urls.get(name)
        remote_url_sha256 = (
            vcs.remote_url_sha256(destination, remote)
            if authorized_url is None
            else vcs.assert_remote_url(destination, remote, authorized_url)
        )
        checkouts.append(
            Checkout(
                name=name,
                path=relative,
                repository=repository_relative,
                branch=branch,
                start_point=head,
                remote=remote,
                remote_url_sha256=remote_url_sha256,
                landed_ref=_landed_ref_for_remote(config, remote),
                head=head,
            )
        )
    return tuple(checkouts)


def _historical_import_inputs(
    config: Config, args: argparse.Namespace, vcs: _GitVcs
) -> _HistoricalImport:
    if args.slot_type != "agent":
        raise Refusal(
            "--from-state-file describes historical agent slots only. state: REFUSED -- "
            "no import journal or active row was written. remedy: use ordinary "
            "import-existing for a live validate slot"
        )
    if args.owner_pid is not None or args.verified_live:
        raise Refusal(
            "--owner-pid and --verified-live describe current ownership, not a historical "
            "source row. state: REFUSED -- no import journal or active row was written. "
            "remedy: drop them when using --from-state-file"
        )
    if any(value is not None for value in (args.agent, args.task, args.purpose)):
        raise Refusal(
            "--agent, --task, and --purpose are owned by the historical source row. "
            "state: REFUSED -- no import journal or active row was written. remedy: drop "
            "those flags or repair the source row before retrying"
        )
    source, row, owner, agent, task, purpose, created_at = _historical_source_row(
        config, args
    )
    checkouts = _historical_checkouts(config, args, row, vcs)
    try:
        _assert_slot_contents_values(
            config, args.slot, args.slot_type, "nested", checkouts
        )
    except Refusal as exc:
        raise Refusal(
            f"historical slot {args.slot} does not match the source row: {exc}. state: "
            "REFUSED -- no import journal or active row was written. remedy: preserve "
            "the source and slot, reconcile their paths and contents, then rerun the dry run"
        ) from exc
    return _HistoricalImport(
        agent=agent,
        task=task,
        purpose=purpose,
        created_at=created_at,
        owner=owner,
        checkouts=checkouts,
        source=source,
    )


def _existing_checkouts(
    config: Config, args: argparse.Namespace, vcs: _GitVcs
) -> tuple[Checkout, ...]:
    repositories = _assignments(args.repo, "repository")
    remotes = _assignments(args.remote, "remote")
    remote_urls = _assignments(args.remote_url, "trusted remote URL")
    if not repositories:
        raise Refusal("at least one --repo NAME=PATH is required")
    if config.layout == "flat" and len(repositories) != 1:
        raise Refusal("flat layout requires exactly one repository per slot")
    for mapping, label in (
        (remotes, "remote"),
        (remote_urls, "trusted remote URL"),
    ):
        unknown = sorted(set(mapping) - set(repositories))
        if unknown:
            raise Refusal(f"{label} supplied for unknown repository: {', '.join(unknown)}")
    checkouts: list[Checkout] = []
    for name, raw_repository in repositories.items():
        repository_relative, repository = _repository_path(config, raw_repository)
        destination_relative, destination = _checkout_path(
            config, args.slot, name, args.slot_type
        )
        if not destination.is_dir() or destination.is_symlink():
            raise Refusal(f"existing checkout is missing or unsafe: {destination}")
        head = vcs.verify_existing_worktree(repository, destination)
        branch = vcs.branch(destination)
        remote = _validate_remote(remotes.get(name, config.default_remote))
        authorized_url = remote_urls.get(name)
        remote_url_sha256 = (
            vcs.remote_url_sha256(destination, remote)
            if authorized_url is None
            else vcs.assert_remote_url(destination, remote, authorized_url)
        )
        landed_ref = _landed_ref_for_remote(config, remote)
        if not landed_ref.startswith(f"refs/remotes/{remote}/"):
            raise Refusal(
                f"landed ref for {name} must be under refs/remotes/{remote}/"
            )
        checkouts.append(
            Checkout(
                name=name,
                path=destination_relative,
                repository=repository_relative,
                branch=branch,
                start_point=head,
                remote=remote,
                remote_url_sha256=remote_url_sha256,
                landed_ref=landed_ref,
                head=head,
            )
        )
    return tuple(sorted(checkouts, key=lambda item: item.name))


def _register_existing(
    config: Config,
    args: argparse.Namespace,
    owner: ProcessIdentity,
    coordinator_lease: ProcessIdentity,
) -> ActiveRecord:
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    if not args.task or not args.purpose:
        raise Refusal("task and purpose must be non-empty")
    if not args.verified_live:
        raise Refusal("registration requires --verified-live and a live --owner-pid")
    task_scope = _task_scope_from_args(args, owner)
    vcs = _GitVcs()
    checkouts = _existing_checkouts(config, args, vcs)
    slot_path = _assert_slot_contents(
        config,
        ActiveRecord(
            slot=args.slot,
            agent=args.agent,
            task=args.task,
            purpose=args.purpose,
            slot_type=args.slot_type,
            machine=config.machine,
            generation=1,
            created_at=_utc_now(),
            heartbeat_at=_utc_now(),
            heartbeat_ttl_seconds=config.heartbeat_ttl_seconds,
            owner=owner,
            coordinator_lease=coordinator_lease,
            coordinator_recovery_note=None,
            handoff=None,
            checkouts=checkouts,
        ),
    )
    for checkout in checkouts:
        _assert_checkout_identity_unchanged(config, checkout, vcs)
    confirmed_owner = _read_process_identity(owner.pid)
    if confirmed_owner != owner:
        raise Refusal("owner process generation changed during registration")
    confirmed_coordinator = _read_process_identity(coordinator_lease.pid)
    if confirmed_coordinator != coordinator_lease:
        raise Refusal("coordinator process generation changed during registration")
    _assert_caller_process(confirmed_coordinator, "coordinator")
    _assert_registration_owner_authorized(
        confirmed_owner, confirmed_coordinator, slot_path
    )
    if task_scope is not None:
        _verify_task_scope_invocation(task_scope)
    now = _utc_now()
    return ActiveRecord(
        slot=args.slot,
        agent=args.agent,
        task=args.task,
        purpose=args.purpose,
        slot_type=args.slot_type,
        machine=config.machine,
        generation=1,
        created_at=now,
        heartbeat_at=now,
        heartbeat_ttl_seconds=config.heartbeat_ttl_seconds,
        owner=owner,
        coordinator_lease=coordinator_lease,
        coordinator_recovery_note=None,
        handoff=None,
        checkouts=checkouts,
        task_scope=task_scope,
    )


def _cmd_register(
    args: argparse.Namespace, *, allow_unregistered_migration_slots: bool = False
) -> int:
    _require_coordinator_authorized(args, "worktree registration")
    args.slot_type = _require_slot_type(args, "worktree registration")
    config = _load_new_slot_config(args, "worktree registration")
    owner = _capture_registration_owner(args.owner_pid)
    coordinator_lease = _capture_caller_process(
        args.coordinator_pid, "coordinator"
    )
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, archives = _validate_global_state(config)
        _assert_command_registry_storage(
            config,
            states,
            args,
            allowed_unregistered_slot=(args.slot_type, args.slot),
            migration_operation=allow_unregistered_migration_slots,
        )
        before = _global_rows(states, archives)
        _ensure_state_shard(config)
        state = _load_active(config)
        _assert_agent_and_slot_free(config, args.slot, args.agent, args.slot_type)
        record = _register_existing(
            config, args, owner, coordinator_lease
        )
        _write_active_state(
            config,
            _append_record(state, record),
            action="slot-registered",
            slot=record.slot,
            evidence={
                "slot_type": record.slot_type,
                "coordinator_authorized": True,
                "coordinator": _identity_to_obj(coordinator_lease),
            },
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"registered slot={record.slot} agent={record.agent} generation=1 "
        f"checkouts={len(record.checkouts)}"
    )
    return 0


def _import_journal_payload(record: ActiveRecord) -> dict[str, object]:
    return {
        "schema": SCHEMA,
        "kind": "import-existing",
        "machine": record.machine,
        "slot": record.slot,
        "record": _record_to_obj(record),
    }


def _verify_import_record(
    config: Config, record: ActiveRecord, vcs: _GitVcs
) -> None:
    _assert_record_paths(config, record)
    _assert_slot_contents(config, record)
    for checkout in record.checkouts:
        _assert_checkout_identity_unchanged(config, checkout, vcs)


def _publish_import(
    config: Config,
    state: ActiveState,
    record: ActiveRecord,
    *,
    coordinator_authorized: bool,
) -> None:
    journal = _import_journal_payload(record)
    _write_journal(config, journal)
    _interrupt_for_test("after-import-journal")
    _verify_import_record(config, record, _GitVcs())
    if record.task_scope is not None:
        _verify_task_scope_before_publication(record.task_scope, _IMPORT_SCOPE_REMEDY)
    _write_active_state(
        config,
        _append_record(state, record),
        action="slot-imported",
        slot=record.slot,
        evidence={
            "slot_type": record.slot_type,
            "coordinator_authorized": coordinator_authorized,
            "coordinator": _identity_to_obj(record.coordinator_lease),
            "import_source": _import_source_to_obj(record.import_source),
        },
    )
    _interrupt_for_test("after-import-active-write")
    _clear_journal(config, journal)


def _cmd_import_existing(args: argparse.Namespace) -> int:
    args.slot_type = _require_slot_type(args, "worktree import")
    config = (
        _load_new_slot_config(args, "worktree import --apply")
        if args.apply
        else _load_config(args.project_root, args.machine)
    )
    vcs = _GitVcs()
    _validate_name(args.slot, "slot")
    task_scope_arguments = _task_scope_arguments(args)
    if args.from_state_file is not None and task_scope_arguments is not None:
        raise Refusal(
            "task scope identity is available only for a live import, not "
            "--from-state-file"
        )
    historical = (
        None
        if args.from_state_file is None
        else _historical_import_inputs(config, args, vcs)
    )
    if historical is None:
        if args.source_host_id is not None:
            raise Refusal(
                "--source-host-id applies only with --from-state-file. state: REFUSED -- "
                "no import journal or active row was written. remedy: drop the flag or "
                "supply the historical state file it describes"
            )
        if any(value is None for value in (args.agent, args.task, args.purpose)):
            raise Refusal(
                "live import requires --agent, --task, and --purpose. state: REFUSED -- "
                "no import journal or active row was written. remedy: supply all three, "
                "or use --from-state-file to take them from a historical row"
            )
        assert args.agent is not None
        assert args.task is not None
        assert args.purpose is not None
        checkouts = _existing_checkouts(config, args, vcs)
        agent = args.agent
        task = args.task
        purpose = args.purpose
        source = None
    else:
        checkouts = historical.checkouts
        agent = historical.agent
        task = historical.task
        purpose = historical.purpose
        source = historical.source
    print(
        f"verified existing slot={args.slot} checkouts={len(checkouts)} "
        f"machine={config.machine}"
    )
    if source is not None:
        print(
            f"  source={source.path} status={source.status} "
            f"row_sha256={source.row_sha256}"
        )
    for checkout in checkouts:
        print(
            f"  {checkout.name}: path={checkout.path} branch={checkout.branch} head={checkout.head}"
        )
    if not args.apply:
        if historical is None:
            print(
                "dry-run: no state changed; add --apply --verified-live --owner-pid PID "
                "--coordinator-pid PID --coordinator-authorized to register"
            )
        else:
            print(
                "dry-run: no state changed; add --apply --coordinator-pid PID "
                "--coordinator-authorized to record the exact historical row and begin "
                "a fresh heartbeat time-to-live"
            )
        return 0
    _require_coordinator_authorized(args, "worktree import --apply")
    if args.coordinator_pid is None:
        raise Refusal(
            "--apply requires --coordinator-pid. state: REFUSED -- no import journal "
            "or active row was written. remedy: pass the live invoking coordinator PID"
        )
    if historical is None and (args.owner_pid is None or not args.verified_live):
        raise Refusal(
            "live --apply requires --verified-live and --owner-pid. state: REFUSED -- "
            "no import journal or active row was written. remedy: supply both for the "
            "current owner, or use --from-state-file for a recorded historical owner"
        )
    if historical is None:
        assert args.owner_pid is not None
    coordinator_lease = _capture_caller_process(
        args.coordinator_pid, "coordinator"
    )
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, archives = _validate_global_state(config)
        _assert_command_registry_storage(
            config,
            states,
            args,
            allowed_unregistered_slot=(args.slot_type, args.slot),
            migration_operation=True,
        )
        before = _global_rows(states, archives)
        _ensure_state_shard(config)
        state = _load_active(config)
        if historical is not None:
            current_historical = _historical_import_inputs(config, args, vcs)
            if current_historical != historical:
                raise Refusal(
                    "historical source row or checkout identity changed while import was "
                    "starting. state: REFUSED -- no import journal or active row was "
                    "written. remedy: inspect the new source and rerun the dry run before "
                    "applying it"
                )
            historical = current_historical
        _assert_agent_and_slot_free(
            config, args.slot, agent, args.slot_type, enforce_cap=False
        )
        if historical is None:
            owner = _capture_registration_owner(args.owner_pid)
            record = _register_existing(config, args, owner, coordinator_lease)
        else:
            now = _utc_now()
            record = ActiveRecord(
                slot=args.slot,
                agent=historical.agent,
                task=historical.task,
                purpose=historical.purpose,
                slot_type=args.slot_type,
                machine=config.machine,
                generation=1,
                created_at=historical.created_at,
                heartbeat_at=now,
                heartbeat_ttl_seconds=config.heartbeat_ttl_seconds,
                owner=historical.owner,
                coordinator_lease=coordinator_lease,
                coordinator_recovery_note=None,
                handoff=None,
                checkouts=historical.checkouts,
                layout="nested",
                import_source=historical.source,
            )
            _verify_import_record(config, record, vcs)
        confirmed_coordinator = _read_process_identity(coordinator_lease.pid)
        if confirmed_coordinator != coordinator_lease:
            raise Refusal(
                "coordinator process generation changed during import. state: REFUSED -- "
                "no import journal or active row was written. remedy: rerun with the "
                "current invoking coordinator PID"
            )
        _assert_caller_process(confirmed_coordinator, "coordinator")
        _publish_import(
            config,
            state,
            record,
            coordinator_authorized=True,
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"registered slot={record.slot} agent={record.agent} generation=1 "
        f"checkouts={len(record.checkouts)}"
    )
    return 0


def _expected_generation(record: ActiveRecord, expected: int) -> None:
    if record.generation != expected:
        raise Refusal(
            f"stale generation for slot {record.slot}: expected {expected}, "
            f"current {record.generation}"
        )


def _assert_owner_auth(
    record: ActiveRecord,
    agent: str,
    supplied: ProcessIdentity,
    expected_generation: int,
) -> ProcessIdentity:
    _expected_generation(record, expected_generation)
    if record.agent != agent:
        raise Refusal(
            f"ownership mismatch for slot {record.slot}: expected {record.agent}, got {agent}"
        )
    if record.owner is None:
        raise Refusal(f"slot {record.slot} has no bound owner process; adopt it first")
    if supplied != record.owner:
        state, detail = _process_state(record.owner)
        raise Refusal(
            f"owner process generation mismatch for slot {record.slot}; "
            f"recorded owner is {state}: {detail}"
        )
    _assert_caller_process(supplied, "owner")
    return supplied


def _cmd_adopt(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    owner = _capture_caller_process(args.owner_pid, "owner")
    task_scope = _task_scope_from_args(args, owner)
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, archives = _validate_global_state(config)
        _assert_command_registry_storage(config, states, args)
        before = _global_rows(states, archives)
        state = _load_active(config)
        record = _find_record(state, args.slot)
        _expected_generation(record, args.expected_generation)
        if record.agent != args.agent:
            raise Refusal(
                f"ownership mismatch for slot {args.slot}: expected {record.agent}, got {args.agent}"
            )
        if record.owner == owner and (
            task_scope is None or record.task_scope == task_scope
        ):
            print(
                f"already adopted slot={record.slot} agent={record.agent} "
                f"generation={record.generation}"
            )
            return 0
        if record.owner is not None and record.owner != owner:
            state_name, detail = _process_state(record.owner)
            raise Refusal(
                f"slot {record.slot} already has a {state_name} historical owner: {detail}; "
                "ordinary adopt cannot replace it"
            )
        confirmed_owner = _read_process_identity(owner.pid)
        if confirmed_owner != owner:
            raise Refusal("owner process generation changed during adopt")
        _assert_caller_process(confirmed_owner, "owner")
        if task_scope is not None:
            _verify_task_scope_invocation(task_scope)
        now = _utc_now()
        adopted = dataclasses.replace(
            record,
            owner=owner,
            heartbeat_at=now,
            task_scope=task_scope if task_scope is not None else record.task_scope,
        )
        _write_active_state(
            config,
            _replace_record(state, adopted),
            action="owner-bound",
            slot=adopted.slot,
            evidence={"owner": _identity_to_obj(owner)},
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"adopted slot={adopted.slot} agent={adopted.agent} generation={adopted.generation} "
        f"owner_pid={owner.pid}"
    )
    return 0


def _cmd_recover_unbound_owner(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    if not args.recovery_note.strip():
        raise Refusal("coordinator recovery requires a non-empty --recovery-note")
    validation = tuple(args.validation or ())
    limitations = tuple(args.limitation or ())
    if not validation or any(not item.strip() for item in validation):
        raise Refusal("coordinator recovery requires non-empty --validation evidence")
    coordinator = _capture_caller_process(args.coordinator_pid, "coordinator")
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, archives = _validate_global_state(config)
        _assert_command_registry_storage(config, states, args)
        before = _global_rows(states, archives)
        state = _load_active(config)
        record = _find_record(state, args.slot)
        _expected_generation(record, args.expected_generation)
        _assert_caller_process(coordinator, "coordinator")
        if record.owner is not None:
            raise Refusal(
                f"slot {record.slot} has a historical owner; coordinator recovery cannot replace it"
            )
        _assert_owner_liveness(config, record)
        _slot_path, final_checkouts = _handoff_preconditions(
            config, record, _GitVcs()
        )
        continuation = (
            f"wrkslots remove {record.slot} --coordinator-pid "
            f"<current-coordinator-pid> --expected-generation {record.generation}"
        )
        updated = dataclasses.replace(
            record,
            checkouts=final_checkouts,
            coordinator_recovery_note=args.recovery_note,
            handoff=Handoff(
                recorded_at=_utc_now(),
                validation=validation,
                limitations=limitations,
                continuation=continuation,
            ),
        )
        _write_active_state(
            config,
            _replace_record(state, updated),
            action="owner-recovery-recorded",
            slot=updated.slot,
            evidence={"note": args.recovery_note},
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"recorded coordinator recovery evidence slot={updated.slot} "
        f"generation={updated.generation}"
    )
    return 0


def _cmd_relocate_repository(args: argparse.Namespace) -> int:
    """Point the active rows that name a moved source repository at its new path.

    A checkout's recorded repository path is its Git evidence, so this refuses
    unless the new path is provably the same repository. Every present checkout
    recorded under the old path must be a linked worktree of the new path: its
    Git directory lies in the new path's common directory and the new path
    lists it. Each present checkout's recorded branch, and every affected
    checkout's recorded commits and remote URL, must be there too. A row whose
    storage is gone has no Git directory of its own, so at least one present
    checkout from the same old path must vouch for the move. Every affected row
    on this machine moves together, absent rows first, so an interrupted apply
    can be rerun while its witnesses still name the old path.
    """

    config = _load_config(args.project_root, args.machine)
    if config.machine != _short_hostname():
        raise Refusal("repository relocation must run on the rows' machine")
    tail = "state: REFUSED -- no registry row was changed."
    source, _source_path, _source_root = _stored_repository_reference(
        config, args.source
    )
    target, target_path = _repository_path(config, args.target)
    if target == source:
        raise Refusal(f"repository {source!r} is already the recorded path. {tail}")
    coordinator: ProcessIdentity | None = None
    if args.apply:
        _require_coordinator_authorized(args, "repository relocation")
        if args.coordinator_pid is None:
            raise Refusal("--apply requires --coordinator-pid")
        coordinator = _capture_caller_process(args.coordinator_pid, "coordinator")
    vcs = _GitVcs()
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, archives = _validate_global_state(config, require_repository=False)
        before = _global_rows(states, archives)
        state = _load_active(config, require_repository=False)
        affected = [
            (record, checkout)
            for record in state.slots
            for checkout in record.checkouts
            if _stored_repository_reference(config, checkout.repository)[0] == source
        ]
        if not affected:
            raise Refusal(
                f"no active row on {config.machine} names repository {source!r}. {tail}"
            )
        try:
            _stored, old_path = _stored_repository_path(config, source)
            still_present = vcs.repository_root(old_path) == old_path
        except Refusal:
            still_present = False
        if still_present:
            raise Refusal(
                f"recorded repository {source!r} is still a Git repository; relocation "
                f"applies only to a repository that moved away. {tail}"
            )
        try:
            target_root = vcs.repository_root(target_path)
            common = vcs.common_directory(target_path)
        except Refusal as exc:
            raise Refusal(
                f"new repository path {target!r} is not a Git repository: {exc}. {tail}"
            ) from exc
        if target_root != target_path:
            raise Refusal(
                f"new repository path {target!r} is not a Git repository: it lies inside "
                f"the Git worktree {target_root}. {tail}"
            )
        listed = vcs.listed_worktrees(target_path)
        remote_digests: dict[str, str] = {}
        witnesses: list[str] = []
        planned: list[tuple[ActiveRecord, Checkout, bool, bool]] = []
        for record, checkout in affected:
            label = f"{record.slot}/{checkout.name}"
            path = _stored_path_reference(config, checkout.path, "checkout path")
            present = path.exists() or path.is_symlink()
            if present:
                if path.is_symlink() or not path.is_dir():
                    raise Refusal(
                        f"checkout {label} is not a real directory: {path}. {tail}"
                    )
                try:
                    checkout_common, _git_directory = vcs.linked_worktree_git_directory(
                        path
                    )
                except Refusal:
                    checkout_common = None
                if checkout_common != common or path.absolute() not in listed:
                    raise Refusal(
                        f"checkout {label} is not a linked worktree of {target_path}: its "
                        f"Git directory is not in {common}, so the new path is a different "
                        f"repository. {tail} remedy: if it is the same repository, run "
                        f"'git -C {target_path} worktree repair {path}' and rerun"
                    )
                if not vcs.branch_exists(target_path, checkout.branch):
                    raise Refusal(
                        f"checkout {label} branch {checkout.branch!r} is not in "
                        f"{target_path}, so the new path is a different repository. {tail}"
                    )
                witnesses.append(label)
            commits = [checkout.head]
            if SHA_RE.fullmatch(checkout.start_point):
                commits.append(checkout.start_point)
            for commit in commits:
                if not vcs.commit_present(target_path, commit):
                    raise Refusal(
                        f"checkout {label} commit {commit} is not in {target_path}, so the "
                        f"new path is a different repository. {tail}"
                    )
            if checkout.remote not in remote_digests:
                remote_digests[checkout.remote] = vcs.remote_authority(
                    target_path, checkout.remote
                ).sha256
            if remote_digests[checkout.remote] != checkout.remote_url_sha256:
                raise Refusal(
                    f"checkout {label} remote {checkout.remote!r} URL differs in "
                    f"{target_path}. {tail}"
                )
            branch_present = present or vcs.branch_exists(target_path, checkout.branch)
            planned.append((record, checkout, present, branch_present))
        if not witnesses:
            raise Refusal(
                f"no checkout recorded under {source!r} is present, so nothing proves that "
                f"{target!r} is the same repository. {tail}"
            )
        print(
            f"REPOSITORY machine={config.machine} from={source} to={target} "
            f"common_directory={common} witnesses={','.join(witnesses)}"
        )
        # A row whose checkouts are all absent moves first; see the docstring.
        order = sorted(
            {record.slot: record for record, _checkout, _present, _branch in planned}.values(),
            key=lambda record: any(
                present
                for item, _checkout, present, _branch in planned
                if item.slot == record.slot
            ),
        )
        evidence_base = {
            "from": source,
            "to": target,
            "common_directory": str(common),
            "witnesses": witnesses,
        }
        current = state
        for original in order:
            moved = {
                checkout.name
                for record, checkout, _present, _branch in planned
                if record.slot == original.slot
            }
            updated = dataclasses.replace(
                original,
                checkouts=tuple(
                    dataclasses.replace(checkout, repository=target)
                    if checkout.name in moved
                    else checkout
                    for checkout in original.checkouts
                ),
            )
            _assert_record_paths(config, updated, require_repository=False)
            outcome = "would-relocate"
            if coordinator is not None:
                _assert_caller_process(coordinator, "coordinator")
                if _find_record(current, original.slot) != original:
                    raise StateError(f"slot {original.slot} changed during relocation")
                current = _replace_record(current, updated)
                _write_active_state(
                    config,
                    current,
                    action="repository-relocated",
                    slot=updated.slot,
                    evidence={**evidence_base, "checkouts": sorted(moved)},
                    require_repository=False,
                )
                outcome = "relocated"
            for record, checkout, present, branch_present in planned:
                if record.slot != original.slot:
                    continue
                print(
                    f"ROW machine={record.machine} slot={record.slot} "
                    f"generation={record.generation} checkout={checkout.name} "
                    f"storage={'present' if present else 'absent'} "
                    f"branch={'present' if branch_present else 'absent'} "
                    f"outcome={outcome} record_sha256={_record_sha256(updated)}"
                )
        if coordinator is None:
            print(
                "plan only: no registry row was changed; rerun with --apply "
                "--coordinator-authorized --coordinator-pid PID to record it"
            )
            return 0
        relocated = {record.slot: record for record in current.slots}
        expected = dict(before)
        for slot in {record.slot for record, _checkout, _present, _branch in planned}:
            expected[("active", config.machine, slot)] = _record_to_obj(relocated[slot])
        after_states, after_archives = _validate_global_state(
            config, require_repository=False
        )
        if _global_rows(after_states, after_archives) != expected:
            raise StateError("repository relocation changed an unrelated registry row")
    return 0


def _cmd_heartbeat(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    owner = _capture_caller_process(args.owner_pid, "owner")
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        states, archives = _validate_global_state(config)
        state = _load_active(config)
        record = _find_record(state, args.slot)
        _assert_owner_auth(record, args.agent, owner, args.expected_generation)
        _assert_validate_batch_seals_disjoint_from_record(
            config, record, action="heartbeat"
        )
        _assert_validate_cleanup_journals_disjoint_from_record(
            config,
            states,
            archives,
            record,
            action="heartbeat",
        )
        _assert_command_registry_storage(config, states, args)
        release = _owner_release_in_effect(
            config, record, _load_events(config, record.machine)
        )
        if release is not None:
            raise Refusal(
                f"slot {record.slot} generation {record.generation} was released by its "
                f"owner at {release.recorded_at} (event {release.sequence}), which "
                "stopped this generation's heartbeat. state: REFUSED -- the heartbeat was "
                "not renewed and the slot stays released for removal. remedy: stop using "
                "this slot and leave it; if more work is needed, create a new slot with "
                "'wrkslots create'"
            )
        before = _global_rows(states, archives)
        updated = dataclasses.replace(record, heartbeat_at=_utc_now())
        _write_active_state(
            config,
            _replace_record(state, updated),
            action="ttl-renewed",
            slot=updated.slot,
            evidence={"heartbeat_at": updated.heartbeat_at},
        )
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"heartbeat slot={updated.slot} generation={updated.generation} at={updated.heartbeat_at}"
    )
    return 0


def _cmd_release(args: argparse.Namespace) -> int:
    """Give one agent slot generation back while its owner process keeps running.

    Only the exact recorded owner process generation (or a process it started)
    can release, and only after it published a handoff with ``write-handoff``.
    The release is one appended event: it deletes nothing and runs no process
    census, so it returns promptly. The coordinator later removes the slot with
    the ordinary ``remove`` or ``retire-pending``, where every guard that
    protects work still runs; the release substitutes only for the owner's death
    and the heartbeat time-to-live.
    """

    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    owner = _capture_caller_process(args.owner_pid, "owner")
    tail = "state: REFUSED -- the slot was not released and its owner still holds it."
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        states, archives = _validate_global_state(config)
        state = _load_active(config)
        record = _find_record(state, args.slot)
        _assert_owner_auth(record, args.agent, owner, args.expected_generation)
        if record.slot_type != "agent":
            raise Refusal(
                f"release applies only to agent slots; slot {record.slot} is a "
                f"{record.slot_type} slot. {tail} remedy: remove a validation slot with "
                f"'wrkslots remove {record.slot} --validate-complete --coordinator-pid "
                f"<pid> --expected-generation {record.generation}' once its run completed"
            )
        _assert_validate_batch_seals_disjoint_from_record(
            config, record, action="release"
        )
        _assert_validate_cleanup_journals_disjoint_from_record(
            config,
            states,
            archives,
            record,
            action="release",
        )
        _assert_command_registry_storage(config, states, args)
        events = _load_events(config, record.machine)
        hold = _load_hold(config, record.slot, record.machine, events=events)
        if hold is not None:
            raise Refusal(
                f"slot {record.slot} is held: "
                f"{_as_str(hold['reason'], 'slot hold.reason')}. A hold keeps a slot on "
                f"purpose, so it cannot be released while held. {tail} remedy: ask "
                f"whoever placed the hold to run 'wrkslots unhold {record.slot}' once it is "
                "no longer needed, then retry release"
            )
        slot_path = _slot_directory(config, record.slot, record.slot_type)
        write_handoff = (
            f"'wrkslots write-handoff {record.slot} --agent {record.agent} --owner-pid "
            f"<owner-pid> --expected-generation {record.generation} --from-file <notes>'"
        )
        try:
            artifact = _resolve_handoff_artifact(
                config, record, slot_path, events=events
            )
        except Refusal as exc:
            raise Refusal(
                f"cannot release slot {record.slot}: {exc}. {tail}"
            ) from exc
        publication = _handoff_write_publication(record, events)
        if artifact is None or publication is None:
            found = (
                "has no handoff sidecar"
                if artifact is None
                else "has only a legacy HANDOFF.md, which names no writer"
            )
            raise Refusal(
                f"slot {record.slot} generation {record.generation} {found}; release "
                "requires a handoff published with write-handoff so the coordinator can "
                f"read what is left in the slot before removing it. {tail} remedy: write "
                f"your notes to a file outside the slot, run {write_handoff}, then retry "
                "release"
            )
        intent_sequence, intended, completed = publication
        if (
            artifact.source != "write-handoff"
            or not completed
            or not _json_equal(_handoff_artifact_to_obj(artifact), intended)
        ):
            raise Refusal(
                f"slot {record.slot} handoff publication is incomplete: the sidecar does "
                f"not match the completed write-handoff intent {intent_sequence}. {tail} "
                f"remedy: rerun the same {write_handoff} command with the same file, then "
                "retry release"
            )
        latest_read = _latest_handoff_read(record, events)
        handoff_read = latest_read is not None and _handoff_read_matches_artifact(
            latest_read, artifact
        )
        previous, void_reason = _owner_release_state(config, record, events)
        if (
            previous is not None
            and void_reason is None
            and previous.sha256 == artifact.sha256
        ):
            release = previous
            outcome = "already released"
        else:
            _ensure_event_log(config, record.machine)
            event = _write_event_file(
                config,
                record.machine,
                "owner-released",
                {
                    "slot": record.slot,
                    "generation": record.generation,
                    "agent": record.agent,
                    "owner": _identity_to_obj(record.owner),
                    "heartbeat_at": record.heartbeat_at,
                    "handoff": {
                        "path": str(artifact.path),
                        "sha256": artifact.sha256,
                        "source": "write-handoff",
                        "intent_sequence": intent_sequence,
                    },
                },
            )
            release = _owner_release_from_event(event)
            outcome = "released"
    print(
        f"{outcome} slot={record.slot} generation={record.generation} "
        f"sha256={release.sha256} at={release.recorded_at} event={release.sequence}"
    )
    print(
        "heartbeat: stopped for this generation; 'wrkslots heartbeat' now refuses for it"
    )
    print(
        "removal: no longer waits for the owner to exit or for the heartbeat "
        "time-to-live; the handoff read, the unused-slot check, salvage and holds "
        "still apply"
    )
    if handoff_read:
        print(
            f"next: coordinator runs 'wrkslots remove {record.slot} --coordinator-pid "
            f"<pid> --expected-generation {record.generation}' or 'wrkslots "
            "retire-pending --limit <n> --coordinator-pid <pid>'"
        )
    else:
        print(
            f"next: coordinator runs 'wrkslots read-handoff {record.slot} "
            f"--coordinator-pid <pid>', then 'wrkslots remove {record.slot} "
            f"--coordinator-pid <pid> --expected-generation {record.generation}' or "
            "'wrkslots retire-pending --limit <n> --coordinator-pid <pid>'"
        )
    print(
        "note: leave the slot now; remove refuses while any process, yours included, "
        "has its working directory, an open file or a mapping inside it"
    )
    return 0


def _cmd_hold(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    reason = args.reason.strip()
    if not reason:
        raise Refusal("hold requires a non-empty --reason")
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, _archives = _validate_global_state(config)
        _assert_command_registry_storage(config, states, args)
        record = _find_record(_load_active(config), args.slot)
        path = _hold_path(config, record.slot, record.machine)
        existing = _load_hold(config, record.slot, record.machine)
        if existing is not None:
            if _as_str(existing["reason"], "slot hold.reason") != reason:
                raise Refusal(
                    f"slot {record.slot} is already held for a different reason: "
                    f"{existing['reason']}"
                )
            print(f"already held slot={record.slot} reason={reason}")
            return 0
        _ensure_event_log(config, record.machine)
        _write_event_file(
            config,
            record.machine,
            "slot-held",
            {"slot": record.slot, "generation": record.generation, "reason": reason},
        )
        _atomic_write_json(
            path,
            {
                "schema": HOLD_SCHEMA,
                "machine": record.machine,
                "slot": record.slot,
                "held_at": _utc_now(),
                "reason": reason,
            },
        )
    print(f"held slot={record.slot} reason={reason}")
    return 0


def _cmd_unhold(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, _archives = _validate_global_state(config)
        _assert_command_registry_storage(config, states, args)
        record = _find_record(_load_active(config), args.slot)
        path = _hold_path(config, record.slot, record.machine)
        if _load_hold(config, record.slot, record.machine) is None:
            raise Refusal(f"slot {record.slot} is not held")
        _ensure_event_log(config, record.machine)
        _write_event_file(
            config,
            record.machine,
            "slot-hold-released",
            {"slot": record.slot, "generation": record.generation},
        )
        _remove_control_file(path)
    print(f"released hold slot={record.slot}")
    return 0


def _same_handoff_snapshot(
    left: _HandoffArtifact, right: _HandoffArtifact
) -> bool:
    return (
        left.path,
        left.machine,
        left.slot,
        left.generation,
        left.contents,
        left.sha256,
        left.source,
        left.source_path,
        left.source_identity,
        left.provenance_complete,
        left.storage_identity,
    ) == (
        right.path,
        right.machine,
        right.slot,
        right.generation,
        right.contents,
        right.sha256,
        right.source,
        right.source_path,
        right.source_identity,
        right.provenance_complete,
        right.storage_identity,
    )


def _write_and_flush_handoff(path: Path, rendered: str) -> None:
    try:
        sys.stdout.write(f"--- {path} ---\n")
        sys.stdout.write(rendered)
        if not rendered.endswith("\n"):
            sys.stdout.write("\n")
        sys.stdout.write(f"--- end {path} ---\n")
        sys.stdout.flush()
    except (OSError, ValueError) as exc:
        raise Refusal(
            "handoff output could not be flushed; no read or retirement queue event "
            f"was recorded: {exc}"
        ) from exc


def _cmd_read_handoff(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    reader = _capture_caller_process(args.coordinator_pid, "coordinator")
    _assert_caller_process(reader, "coordinator")
    if bool(args.adopt_legacy_change):
        raise Refusal(
            "--adopt-legacy-change is unavailable because handoff sidecars are "
            "immutable once published; preserve both artifacts for manual review"
        )
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, _archives = _validate_global_state(config, require_repository=False)
        state = _load_active(config, require_repository=False)
        record = _find_record(state, args.slot)
        if record.slot_type != "agent":
            raise Refusal(
                f"slot {record.slot} has type validate and cannot carry an agent handoff. "
                "state: REFUSED -- no event was recorded. remedy: inspect its run evidence "
                "under the project's validation evidence directory"
            )
        _assert_target_record_storage_consistent(config, states, record)
        slot_path = _slot_directory(config, record.slot, record.slot_type)
        artifact: _HandoffArtifact | None
        if args.expected_generation is not None:
            raise Refusal(
                "--expected-generation applies only with the unavailable "
                "--adopt-legacy-change compatibility flag"
            )
        try:
            artifact = _resolve_handoff_artifact(config, record, slot_path)
        except Refusal as exc:
            raise Refusal(
                f"{exc}. state: REFUSED -- no read was recorded; preserve both the "
                "slot and any handoff sidecar"
            ) from exc
        if artifact is None:
            raise Refusal(
                f"slot {record.slot} has no handoff sidecar or legacy HANDOFF.md. "
                "state: REFUSED -- no read was recorded. remedy: continue the reclaim "
                "checks; absence of a handoff is not evidence that the owner is dead"
            )
        try:
            rendered = artifact.contents.decode("utf-8")
        except UnicodeError as exc:
            raise Refusal(
                f"slot {record.slot} handoff cannot be read as UTF-8: {exc}. state: "
                "REFUSED -- no read was recorded. remedy: preserve and repair the handoff file"
            ) from exc
        legacy_path = slot_path / "HANDOFF.md"
        display_path = legacy_path if artifact.source == "legacy-slot-file" else artifact.path
        record_snapshot = _record_to_obj(record)
        latest_snapshot = _latest_handoff_read(record, _load_events(config, record.machine))

    _write_and_flush_handoff(display_path, rendered)

    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, _archives = _validate_global_state(config, require_repository=False)
        current_record = _find_record(
            _load_active(config, require_repository=False), args.slot
        )
        if _record_to_obj(current_record) != record_snapshot:
            raise Refusal(
                f"slot {args.slot} changed while its handoff was displayed; no read or "
                "retirement queue event was recorded"
            )
        _assert_target_record_storage_consistent(config, states, current_record)
        current_slot_path = _slot_directory(
            config, current_record.slot, current_record.slot_type
        )
        current_latest = _latest_handoff_read(
            current_record, _load_events(config, current_record.machine)
        )
        if current_latest != latest_snapshot:
            raise Refusal(
                f"slot {args.slot} handoff read history changed while its contents were "
                "displayed; no superseding read was recorded"
            )
        current_sidecar = _load_handoff_sidecar(config, current_record)
        current_artifact = _resolve_handoff_artifact(
            config, current_record, current_slot_path
        )
        if current_artifact is None or not _same_handoff_snapshot(
            current_artifact, artifact
        ):
            raise Refusal(
                f"slot {args.slot} handoff changed while it was displayed; no read "
                "or retirement queue event was recorded"
            )
        _assert_caller_process(reader, "coordinator")
        if (
            not current_artifact.provenance_complete
            or current_artifact.source_path is None
            or current_artifact.source_identity is None
        ):
            raise StateError("cannot record a handoff read without source provenance")
        latest_matches = bool(
            current_latest is not None
            and _handoff_read_matches_artifact(current_latest, current_artifact)
        )
        already_queued = bool(
            latest_matches
            and current_latest is not None
            and current_latest.retirement_enqueued is True
        )
        sidecar_path = _handoff_sidecar_path(
            config,
            current_record.slot,
            current_record.generation,
            current_record.machine,
        )
        projection_needed = (
            current_artifact.source == "legacy-slot-file"
            and current_sidecar is None
        )
        event_payload = {
            "slot": current_record.slot,
            "generation": current_record.generation,
            "sha256": current_artifact.sha256,
            "contents_utf8": rendered,
            "source": current_artifact.source,
            "source_path": str(current_artifact.source_path),
            "source_identity": _regular_file_identity_to_obj(
                current_artifact.source_identity
            ),
            "reader": _identity_to_obj(reader),
            "coordinator_authorized": bool(args.coordinator_authorized),
        }
        if projection_needed and not latest_matches:
            _ensure_event_log(config, current_record.machine, require_repository=False)
            _write_event_file(
                config,
                current_record.machine,
                "handoff-read",
                {**event_payload, "retirement_enqueued": False},
            )
            _interrupt_for_test("after-handoff-read-event")
        if projection_needed:
            projected = dataclasses.replace(current_artifact, path=sidecar_path)
            _atomic_write_handoff_noreplace(
                sidecar_path, _handoff_artifact_to_obj(projected)
            )
            _interrupt_for_test("after-handoff-sidecar-write")
            published = _load_handoff_sidecar(config, current_record)
            if published is None or _handoff_artifact_to_obj(
                published
            ) != _handoff_artifact_to_obj(projected):
                raise StateError(
                    "handoff sidecar changed after its no-replace publication"
                )
        if not already_queued:
            _ensure_event_log(config, current_record.machine, require_repository=False)
            _write_event_file(
                config,
                current_record.machine,
                "handoff-read",
                {**event_payload, "retirement_enqueued": True},
            )
            _interrupt_for_test("after-handoff-read-enqueued")
        digest = current_artifact.sha256
        record = current_record
    print(f"recorded HANDOFF.md read slot={record.slot} sha256={digest}")
    return 0


def _cmd_write_handoff(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    owner = _capture_caller_process(args.owner_pid, "owner")
    requested_source = Path(args.from_file).absolute()
    contents, _source_identity = _read_regular_file_identity(
        requested_source, "handoff input", HANDOFF_BYTES_LIMIT
    )
    try:
        contents.decode("utf-8")
    except UnicodeError as exc:
        raise Refusal(f"handoff input is not UTF-8: {requested_source}: {exc}") from exc
    source = _canonical_handoff_source(
        requested_source, contents, _source_identity, "handoff input"
    )
    _assert_external_handoff_source(source)
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        _assert_no_journal(config)
        states, _archives = _validate_global_state(config, require_repository=False)
        record = _find_record(
            _load_active(config, require_repository=False), args.slot
        )
        if record.slot_type != "agent":
            raise Refusal("validation slots cannot carry agent handoffs")
        _assert_owner_auth(record, args.agent, owner, args.expected_generation)
        if record.handoff is not None:
            raise Refusal(
                f"slot {record.slot} already has a recorded finish; its handoff is immutable"
            )
        _assert_target_record_storage_consistent(config, states, record)
        existing = _load_handoff_sidecar(config, record)
        legacy = _legacy_handoff_artifact(
            config,
            record,
            _slot_directory(config, record.slot, record.slot_type),
        )
        if legacy is not None and legacy.contents != contents:
            raise Refusal(
                f"slot {record.slot} legacy HANDOFF.md disagrees with the proposed sidecar; "
                "preserve both versions and reconcile them before writing"
            )
        sidecar_path = _handoff_sidecar_path(
            config, record.slot, record.generation, record.machine
        )
        artifact = _HandoffArtifact(
            path=sidecar_path,
            machine=record.machine,
            slot=record.slot,
            generation=record.generation,
            contents=contents,
            sha256=hashlib.sha256(contents).hexdigest(),
            recorded_at=_utc_now(),
            source="write-handoff",
            source_path=source,
            source_identity=_source_identity,
            provenance_complete=True,
            storage_identity=_source_identity,
        )
        if existing is not None and not existing.provenance_complete:
            raise Refusal(
                f"slot {record.slot} handoff sidecar schema 1 lacks auditable source "
                "provenance and is permanently manual-only; preserve it for inspection"
            )
        _ensure_event_log(config, record.machine, require_repository=False)
        publication = _handoff_write_publication(
            record, _load_events(config, record.machine)
        )
        intent_sequence: int
        intended: Mapping[str, object]
        if existing is None:
            if publication is None:
                intended = _handoff_artifact_to_obj(artifact)
                intent = _write_event_file(
                    config,
                    record.machine,
                    "handoff-write-intended",
                    {
                        "slot": record.slot,
                        "generation": record.generation,
                        "artifact": intended,
                        "writer": _identity_to_obj(owner),
                    },
                )
                intent_sequence = _as_int(
                    intent["sequence"], "handoff write intent sequence", minimum=1
                )
                _interrupt_for_test("after-handoff-write-intent")
            else:
                intent_sequence, intended, completed = publication
                if completed:
                    raise Refusal(
                        f"slot {record.slot} completed handoff sidecar disappeared; "
                        "preserve the slot and repair its exact artifact"
                    )
                recorded_at = _as_str(
                    intended.get("recorded_at"), "handoff write intent recorded_at"
                )
                _parse_timestamp(recorded_at, "handoff write intent recorded_at")
                artifact = dataclasses.replace(artifact, recorded_at=recorded_at)
                if not _json_equal(intended, _handoff_artifact_to_obj(artifact)):
                    raise Refusal(
                        f"slot {record.slot} has an outstanding handoff intent for "
                        "different bytes or source provenance; preserve it for recovery"
                    )
            _atomic_write_handoff_noreplace(
                sidecar_path, _handoff_artifact_to_obj(artifact)
            )
            _interrupt_for_test("after-handoff-sidecar-write")
            written = _load_handoff_sidecar(config, record)
            if written is None:
                raise StateError("handoff sidecar disappeared after its atomic write")
            if _handoff_artifact_to_obj(written) != _handoff_artifact_to_obj(artifact):
                raise StateError(
                    "handoff sidecar differs from the owner's exact published artifact; "
                    "preserve it and the external source for recovery"
                )
            artifact = written
            _complete_handoff_write_publication(
                config, record, intent_sequence, artifact
            )
        else:
            if (
                existing.contents != artifact.contents
                or existing.sha256 != artifact.sha256
                or existing.source != artifact.source
                or existing.source_path != artifact.source_path
                or existing.source_identity != artifact.source_identity
            ):
                raise Refusal(
                    f"slot {record.slot} already has an immutable handoff sidecar with "
                    "different contents or source provenance; preserve both versions for "
                    "manual review"
                )
            artifact = existing
            if publication is None or not _json_equal(
                publication[1], _handoff_artifact_to_obj(artifact)
            ):
                raise Refusal(
                    f"slot {record.slot} existing handoff sidecar has no matching "
                    "owner-authenticated publication intent; preserve it for manual review"
                )
            intent_sequence = publication[0]
            _complete_handoff_write_publication(
                config, record, intent_sequence, artifact
            )
        if (
            not artifact.provenance_complete
            or artifact.source_path is None
            or artifact.source_identity is None
        ):
            raise StateError("cannot record a handoff write without source provenance")
        _ensure_event_log(config, record.machine, require_repository=False)
        _write_event_file(
            config,
            record.machine,
            "handoff-written",
            {
                "slot": record.slot,
                "generation": record.generation,
                "sha256": artifact.sha256,
                "path": sidecar_path.name,
                "source": artifact.source,
                "source_path": str(artifact.source_path),
                "source_identity": _regular_file_identity_to_obj(
                    artifact.source_identity
                ),
                "writer": _identity_to_obj(owner),
            },
        )
    print(
        f"wrote handoff slot={record.slot} generation={record.generation} "
        f"sha256={artifact.sha256} path={sidecar_path}"
    )
    return 0


def _current_retirement_candidates(
    config: Config, wait_seconds: float, *, deadline: float | None = None
) -> tuple[_RetirementCandidate, ...]:
    effective_wait = (
        wait_seconds if deadline is None else _remaining_lock_wait(deadline)
    )
    with _locked(config.control / "ACTIVE", exclusive=False, wait_seconds=effective_wait):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        state = _load_active(config, require_repository=False)
        events = _load_events(config, state.machine)
        return _retirement_candidates(config, state, events)


def _emit_retirement_queue(
    candidates: Sequence[_RetirementCandidate], output_format: str
) -> None:
    payload = {
        "schema": RETIREMENT_QUEUE_SCHEMA,
        "pending": [candidate.to_obj() for candidate in candidates],
    }
    if output_format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
        return
    print(f"pending={len(candidates)}")
    for candidate in candidates:
        state = "BLOCKED" if candidate.blocked_reason is not None else "PENDING"
        suffix = (
            f" reason={candidate.blocked_reason}"
            if candidate.blocked_reason is not None
            else ""
        )
        if candidate.owner_release is not None:
            suffix += f" owner={candidate.owner_release['summary']}"
        print(
            f"{state}: {candidate.machine}/{candidate.slot} "
            f"generation={candidate.generation} sha256={candidate.sha256}{suffix}"
        )


def _cmd_retirement_queue(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _emit_retirement_queue(
        _current_retirement_candidates(config, args.wait_lock), args.format
    )
    return 0


def _retirement_outcome_after_refusal(
    config: Config,
    candidate: _RetirementCandidate,
    refusal: Refusal,
    deadline: float,
) -> tuple[str, str]:
    if isinstance(refusal, _LockBusy):
        return "deferred", str(refusal)
    if isinstance(refusal, _RetirementDeferred):
        return "deferred", str(refusal)
    if isinstance(refusal, StateError):
        raise StateError(
            "retire-pending outcome=could-not-determine recovery_required=true: "
            f"{refusal}"
        ) from refusal
    try:
        with _mutation_locks(
            config,
            _remaining_lock_wait(deadline),
            deadline=deadline,
        ):
            _refuse_partial_state(config)
            journals = _outstanding_journals(config)
            if journals:
                raise StateError(
                    f"retirement attempt for {candidate.slot} left mutation journal "
                    f"{journals[0]}; run recover before classifying its outcome"
                )
            states, archives = _validate_global_state(
                config, require_repository=False
            )
            state = next(
                (item for item in states if item.machine == candidate.machine), None
            )
            if state is None:
                raise StateError(
                    f"retirement attempt for {candidate.slot} found no registry "
                    f"state for machine {candidate.machine}"
                )
            current = next(
                (item for item in state.slots if item.slot == candidate.slot), None
            )
            if current is not None:
                if current.generation != candidate.generation:
                    return "deferred", "slot generation changed after queue selection"
                _assert_target_record_storage_consistent(config, states, current)
                latest = _latest_handoff_read(
                    current, _load_events(config, current.machine)
                )
                if latest is None or (
                    latest.sha256,
                    latest.retirement_enqueued,
                    latest.sequence,
                ) != (candidate.sha256, True, candidate.event_sequence):
                    return "deferred", "retirement candidate was superseded"
                return "retained", str(refusal)
            matches = [
                row
                for archive in archives
                if archive.machine == candidate.machine
                for row in archive.records
                if row.get("slot") == candidate.slot
                and row.get("generation") == candidate.generation
                and row.get("slot_type") == "agent"
                and row.get("physical_storage") == "removed"
            ]
            if len(matches) != 1:
                raise StateError(
                    f"retirement attempt for {candidate.slot} has neither its exact "
                    "active row nor one exact removed archive row"
                )
            slot_path = _slot_directory(config, candidate.slot, "agent")
            sidecar = _handoff_sidecar_path(
                config,
                candidate.slot,
                candidate.generation,
                candidate.machine,
            )
            if (
                slot_path.exists()
                or slot_path.is_symlink()
                or sidecar.exists()
                or sidecar.is_symlink()
            ):
                raise StateError(
                    f"retirement attempt for {candidate.slot} reached its archive but "
                    "left physical storage or handoff sidecar state"
                )
            return "removed", "ordinary remove completed before reporting its refusal"
    except _LockBusy as exc:
        return "deferred", str(exc)
    except StateError as exc:
        raise StateError(
            "retire-pending outcome=could-not-determine recovery_required=true: "
            f"{exc}"
        ) from exc


def _confirm_unchanged_after_target_storage_drift(
    config: Config,
    candidate: _RetirementCandidate,
    drift: _TargetStorageDrift,
    deadline: float,
) -> None:
    """Confirm that a removal refused for its target's own storage changed nothing.

    ``remove`` checks the target's storage before its first change to the
    slot; only the queue's attempt event precedes that check.  Under the
    mutation locks again, the registry must show no partial update and no
    mutation journal, and must still hold the row exactly as that check read
    it (``drift.record``), every field alike.  Anything else, including a
    lock that cannot be taken or a registry file that cannot be read or
    decoded (bytes that are not UTF-8, or JSON nested too deeply to
    decode), raises StateError.
    """

    try:
        with _mutation_locks(
            config,
            _remaining_lock_wait(deadline),
            deadline=deadline,
        ):
            _refuse_partial_state(config)
            journals = _outstanding_journals(config)
            if journals:
                raise StateError(
                    f"retirement attempt for {candidate.slot} left mutation journal "
                    f"{journals[0]}; run recover before classifying its outcome"
                )
            states, _archives = _validate_global_state(
                config, require_repository=False
            )
            current = next(
                (
                    record
                    for state in states
                    if state.machine == candidate.machine
                    for record in state.slots
                    if record.slot == candidate.slot
                ),
                None,
            )
            if (
                current is None
                or current.generation != candidate.generation
                or _record_to_obj(current) != _record_to_obj(drift.record)
            ):
                raise StateError(
                    f"retirement attempt for {candidate.slot} no longer finds its "
                    "exact active row after its storage refusal"
                )
    except _LockBusy as exc:
        raise StateError(
            f"retirement attempt for {candidate.slot} could not be confirmed "
            f"unchanged after its storage refusal: {exc}"
        ) from exc
    except (OSError, ValueError, RecursionError) as exc:
        raise StateError(
            f"retirement attempt for {candidate.slot} could not be confirmed "
            f"unchanged after its storage refusal: cannot read the registry: "
            f"{type(exc).__name__}: {exc}"
        ) from exc


def _retirement_failure_reason(exc: BaseException) -> str:
    """A refusal's own text, or another failure's type and text.

    ``retire-pending`` catches every Exception where an attempt's outcome is
    decided, so that one failing attempt stops the batch without losing the
    report of the attempts before it.  Each such failure is reported as
    could-not-determine with recovery required, never as removed or
    retained.
    """

    return str(exc) if isinstance(exc, Refusal) else f"{type(exc).__name__}: {exc}"


def _cmd_retire_pending(args: argparse.Namespace) -> int:
    if args.limit <= 0 or args.limit > RETIRE_PENDING_LIMIT:
        raise Refusal(
            f"--limit must be between 1 and {RETIRE_PENDING_LIMIT}"
        )
    wait_seconds = min(
        args.wait_lock if args.wait_lock > 0 else RETIRE_PENDING_WAIT_LOCK_SECONDS,
        RETIRE_PENDING_MAX_WAIT_LOCK_SECONDS,
    )
    deadline = time.monotonic() + wait_seconds
    config = _load_config(args.project_root, args.machine)
    pending = _current_retirement_candidates(
        config, wait_seconds, deadline=deadline
    )
    selected = pending[: args.limit]
    removed: list[dict[str, object]] = []
    retained: list[dict[str, object]] = []
    deferred: list[dict[str, object]] = []
    could_not_determine: list[dict[str, object]] = []
    stopped_at: int | None = None
    for index, candidate in enumerate(selected):
        identity = {
            "machine": candidate.machine,
            "slot": candidate.slot,
            "generation": candidate.generation,
            "sha256": candidate.sha256,
        }
        remove_values = dict(vars(args))
        remove_values.update(
            wait_lock=_remaining_lock_wait(deadline),
            slot=candidate.slot,
            expected_generation=candidate.generation,
            validate_complete=False,
            validation_proof_manifest=None,
            completed_record=None,
            _wait_deadline=deadline,
            _retirement_candidate=candidate,
        )
        remove_args = argparse.Namespace(**remove_values)
        try:
            _cmd_remove(remove_args, emit=False)
        except _TargetStorageDrift as exc:
            # One target's own storage is broken; the registry is not. The
            # target needs recovery, and the batch goes on only when the
            # registry shows that this attempt changed nothing.
            reason = str(exc) + (f"; remedy: {exc.remedy}" if exc.remedy else "")
            try:
                _confirm_unchanged_after_target_storage_drift(
                    config, candidate, exc, deadline
                )
            except Exception as state_error:
                # Any refusal or failure here, including one revalidating
                # the configuration, leaves the attempt unconfirmed: the
                # batch stops and still reports what it did.
                could_not_determine.append(
                    {
                        **identity,
                        "outcome": "could-not-determine",
                        "reason": f"{reason}; {_retirement_failure_reason(state_error)}",
                        "recovery_required": True,
                    }
                )
                stopped_at = index
                break
            could_not_determine.append(
                {
                    **identity,
                    "outcome": "could-not-determine",
                    "reason": (
                        f"{reason}; the slot is unchanged, so the batch "
                        "continued with its next candidate"
                    ),
                    "recovery_required": True,
                }
            )
        except StateError as exc:
            could_not_determine.append(
                {
                    **identity,
                    "outcome": "could-not-determine",
                    "reason": str(exc),
                    "recovery_required": True,
                }
            )
            stopped_at = index
            break
        except Refusal as exc:
            try:
                outcome, reason = _retirement_outcome_after_refusal(
                    config, candidate, exc, deadline
                )
            except Exception as state_error:
                # Any refusal or failure while classifying the attempt
                # leaves it unclassified: the batch stops and still reports
                # what it did.
                could_not_determine.append(
                    {
                        **identity,
                        "outcome": "could-not-determine",
                        "reason": _retirement_failure_reason(state_error),
                        "recovery_required": True,
                    }
                )
                stopped_at = index
                break
            destination = (
                retained
                if outcome == "retained"
                else removed
                if outcome == "removed"
                else deferred
            )
            destination.append(
                {**identity, "outcome": outcome, "reason": reason}
            )
        except Exception as exc:
            # The removal stopped at an unknown point, as for a StateError.
            # This includes RecursionError, the RuntimeError that
            # Path.resolve raises for a symlink loop before Python 3.13,
            # StopIteration and MemoryError.
            could_not_determine.append(
                {
                    **identity,
                    "outcome": "could-not-determine",
                    "reason": _retirement_failure_reason(exc),
                    "recovery_required": True,
                }
            )
            stopped_at = index
            break
        else:
            removed.append(
                {
                    **identity,
                    "outcome": "removed",
                    "reason": "ordinary remove completed",
                }
            )
    if stopped_at is not None:
        deferred.extend(
            {
                "machine": candidate.machine,
                "slot": candidate.slot,
                "generation": candidate.generation,
                "sha256": candidate.sha256,
                "outcome": "deferred",
                "reason": "batch stopped after an indeterminate retirement outcome",
            }
            for candidate in selected[stopped_at + 1 :]
        )
    deferred.extend(
        [
            {
                **candidate.to_obj(),
                "outcome": "deferred",
                "reason": "batch limit",
            }
            for candidate in pending[args.limit :]
        ]
    )
    payload = {
        "schema": RETIREMENT_QUEUE_SCHEMA,
        "limit": args.limit,
        "removed": removed,
        "retained": retained,
        "deferred": deferred,
        "could_not_determine": could_not_determine,
        "recovery_required": bool(could_not_determine),
    }
    if args.format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
    else:
        print(
            f"removed={len(removed)} retained={len(retained)} "
            f"deferred={len(deferred)} could_not_determine={len(could_not_determine)}"
        )
        for item in removed:
            print(
                f"REMOVED: {item['machine']}/{item['slot']} "
                f"generation={item['generation']}"
            )
        for item in retained:
            print(
                f"RETAINED: {item['machine']}/{item['slot']} "
                f"generation={item['generation']} reason={item['reason']}"
            )
        for item in deferred:
            print(
                f"DEFERRED: {item['machine']}/{item['slot']} "
                f"generation={item['generation']} reason={item['reason']}"
            )
        for item in could_not_determine:
            print(
                f"COULD_NOT_DETERMINE: {item['machine']}/{item['slot']} "
                f"generation={item['generation']} recovery_required=true "
                f"reason={item['reason']}"
            )
    return 3 if could_not_determine else 0


class _CachePlanExhausted(Refusal):
    """Cache-glob planning spent its allowance; the subject's total is unknown."""


@dataclasses.dataclass
class _CachePlanBudget:
    """One audit subject's share of cache-glob expansion.

    One work unit is one directory listing, and ``seconds`` bounds the time
    spent walking directories. Planning precedes the cache census, so this
    allowance is separate from the census's own. Git observations are not
    charged: their cost follows each checkout's index, not its ignored trees.
    """

    work: _AuditWorkBudget
    seconds: float
    wall_seconds: float
    spent: float = 0.0

    def check(self, walking: float = 0.0) -> None:
        if self.spent + walking >= self.seconds:
            raise _CachePlanExhausted(
                "cache planning exhausted this subject's share of the fixed wall "
                f"allowance of {self.wall_seconds:g} seconds; no cache total can be "
                "published within this allowance"
            )
        if self.work.remaining <= 0:
            raise _CachePlanExhausted(
                "cache planning exhausted this subject's share of "
                f"{self.work.limit} directory listings; no cache total can be "
                "published within this allowance"
            )

    def debit(self, walking: float) -> None:
        self.check(walking)
        self.work.debit()


def _expand_cache_globs(
    root: Path,
    cache_globs: Sequence[str],
    budget: _CachePlanBudget | None = None,
) -> tuple[tuple[str, tuple[Path, ...]], ...]:
    """Expand validated cache globs below ``root`` in one directory walk.

    Each pattern yields the paths Python 3.12 ``Path.glob`` yields for it: a
    non-final component matches an entry that is a directory after following
    symlinks, a final component matches any entry, ``**`` matches the
    directory itself and every descendant reached without following a
    symlink, and an unreadable directory contributes nothing. Every directory
    is listed at most once for all patterns together, and each listing is
    debited from ``budget`` together with the time this walk has taken.

    The order matches ``Path.glob`` only for a pattern without ``**``, or with
    one ``**`` directly before the final component and only literal
    components before it. For other shapes the same paths may come in a
    different order, so a caller that stops at the first unsafe path may name
    a different one than ``Path.glob`` would. The time bound is cooperative:
    it is checked between listings, so a listing that blocks is not
    interrupted.
    """

    started = time.monotonic()
    try:
        return _expand_cache_globs_walk(root, cache_globs, budget, started)
    finally:
        if budget is not None:
            budget.spent += time.monotonic() - started


def _expand_cache_globs_walk(
    root: Path,
    cache_globs: Sequence[str],
    budget: _CachePlanBudget | None,
    started: float,
) -> tuple[tuple[str, tuple[Path, ...]], ...]:
    parts = tuple(_glob_pattern_parts(pattern) for pattern in cache_globs)
    # Ordered by (the sequence in which this walk reaches the directory that
    # yields the path, the entry's position in that directory's listing).
    # That is Path.glob's order only for the shapes the docstring names: a
    # wildcard before '**' makes Path.glob finish each match's subtree first.
    matches: tuple[list[tuple[tuple[int, int], Path]], ...] = tuple([] for _ in parts)

    def closure(positions: set[tuple[int, int]]) -> set[tuple[int, int]]:
        # '**' may match no component: also try whatever follows the run of it.
        closed = set(positions)
        for index, position in positions:
            pattern = parts[index]
            while position < len(pattern) and pattern[position] == "**":
                position += 1
                closed.add((index, position))
        return closed

    reached = 0
    pending = [(root, reached, closure({(index, 0) for index in range(len(parts))}))]
    while pending:
        directory, sequence, positions = pending.pop()
        for index, position in positions:
            if position == len(parts[index]):
                matches[index].append(((sequence, -1), directory))
        if all(position == len(parts[index]) for index, position in positions):
            continue
        if budget is not None:
            budget.debit(time.monotonic() - started)
        try:
            with os.scandir(directory) as listing:
                entries = list(listing)
        except OSError:
            continue
        children: list[tuple[Path, int, set[tuple[int, int]]]] = []
        for entry_index, entry in enumerate(entries):
            child = directory / entry.name
            advanced: set[tuple[int, int]] = set()
            for index, position in positions:
                pattern = parts[index]
                if position == len(pattern):
                    continue
                part = pattern[position]
                if part == "**":
                    try:
                        descend = entry.is_dir(follow_symlinks=False)
                    except OSError:
                        descend = False
                    if descend:
                        advanced.add((index, position))
                elif fnmatch.fnmatchcase(entry.name, part):
                    if position + 1 == len(pattern):
                        matches[index].append(((sequence, entry_index), child))
                        continue
                    try:
                        directory_entry = entry.is_dir()
                    except OSError:
                        directory_entry = False
                    if directory_entry:
                        advanced.add((index, position + 1))
            if advanced:
                reached += 1
                children.append((child, reached, closure(advanced)))
        # Depth first with siblings in listing order, as Path.walk visits them;
        # a directory's children are all reached when it is visited.
        pending.extend(reversed(children))
    return tuple(
        (pattern, tuple(path for _order, path in sorted(found, key=lambda item: item[0])))
        for pattern, found in zip(cache_globs, matches)
    )


def _cache_directories_for_path(
    config: Config,
    checkout_path: Path,
    checkout_name: str,
    vcs: _GitVcs,
    cache_globs: Sequence[str],
    source_repository: Path | None = None,
    *,
    budget: _CachePlanBudget | None = None,
) -> tuple[CacheDirectory, ...]:
    candidates: set[Path] = set()
    if budget is not None:
        # Do not start this checkout's Git observations after the allowance.
        budget.check()
    if not checkout_path.is_dir() or checkout_path.is_symlink():
        raise Refusal(f"checkout is missing or unsafe for cache inspection: {checkout_path}")
    checkout_identity = _open_directory_identity(checkout_path, "checkout")
    if source_repository is None:
        if vcs.repository_root(checkout_path) != checkout_path.absolute():
            raise Refusal(f"cache target is not a Git checkout root: {checkout_path}")
    else:
        vcs.verify_existing_worktree(source_repository, checkout_path)
    if checkout_identity != _open_directory_identity(checkout_path, "checkout"):
        raise Refusal(f"checkout changed during cache inspection: {checkout_path}")
    _assert_cache_policy_untracked_path(
        config, checkout_name, checkout_path, vcs, cache_globs
    )
    try:
        expanded = _expand_cache_globs(checkout_path, cache_globs, budget)
    except (OSError, ValueError) as exc:
        raise Refusal(f"cannot expand cache globs in {checkout_path}: {exc}") from exc
    for pattern, matches in expanded:
        try:
            for candidate in matches:
                absolute = candidate.absolute()
                if not _path_is_within(absolute, checkout_path) or absolute == checkout_path:
                    raise Refusal(
                        f"cache glob {pattern!r} escaped checkout {checkout_path}"
                    )
                _ensure_no_symlink_components(checkout_path, absolute, "cache path")
                _ensure_no_mount_components(checkout_path, absolute, "cache path")
                _assert_no_mountinfo_crossing(checkout_path, absolute, "cache path")
                if candidate.is_symlink():
                    raise Refusal(f"configured cache path is a symlink: {candidate}")
                if not candidate.exists():
                    continue
                if not candidate.is_dir():
                    # A match that is not a directory is not a cache, for
                    # example a test fixture's one-byte regular file named
                    # `target`. It is ordinary checkout content: it goes with
                    # the checkout, or with the cache directory that holds
                    # it. The escape, symlink, mount, and symlink-match
                    # refusals above still apply to it.
                    continue
                candidates.add(absolute)
        except (OSError, ValueError) as exc:
            raise Refusal(
                f"cannot expand cache glob {pattern!r} in {checkout_path}: {exc}"
            ) from exc
    selected: list[Path] = []
    for candidate in sorted(candidates, key=lambda value: (len(value.parts), str(value))):
        if any(_path_is_within(candidate, parent) for parent in selected):
            continue
        selected.append(candidate)
    if checkout_identity != _open_directory_identity(checkout_path, "checkout"):
        raise Refusal(f"checkout changed during cache inspection: {checkout_path}")
    return tuple(
        CacheDirectory(
            path=path,
            checkout_root=checkout_path,
            checkout_device=checkout_identity[0],
            checkout_inode=checkout_identity[1],
            checkout_mount_id=checkout_identity[2],
        )
        for path in selected
    )


def _cache_directories_for_checkout(
    config: Config,
    checkout: Checkout,
    *,
    vcs: _GitVcs | None = None,
    budget: _CachePlanBudget | None = None,
) -> tuple[CacheDirectory, ...]:
    checkout_path = _stored_path(config, checkout.path, "checkout path")
    selected_vcs = vcs or _GitVcs()
    _relative, repository = _stored_repository_path(config, checkout.repository)
    return _cache_directories_for_path(
        config,
        checkout_path,
        checkout.name,
        selected_vcs,
        _cache_globs_for(config, checkout.name),
        repository,
        budget=budget,
    )


def _unregistered_cache_roots(config: Config, slot: str) -> tuple[Path, ...]:
    slot_path = config.worktrees / slot
    if not slot_path.is_dir() or slot_path.is_symlink():
        raise Refusal(f"unregistered slot is missing or unsafe: {slot_path}")
    candidates = (slot_path,) if config.layout == "flat" else tuple(slot_path.iterdir())
    roots: list[Path] = []
    vcs = _GitVcs()
    for candidate in candidates:
        if not candidate.is_dir() or candidate.is_symlink():
            raise Refusal(
                f"unregistered slot {slot} contains a non-checkout entry: {candidate}"
            )
        if vcs.repository_root(candidate) != candidate.absolute():
            raise Refusal(
                f"unregistered slot {slot} entry is not a Git checkout root: {candidate}"
            )
        roots.append(candidate.absolute())
    if not roots:
        raise Refusal(f"unregistered slot {slot} contains no Git checkouts")
    return tuple(roots)


def _cache_directories(
    config: Config,
    checkouts: Sequence[Checkout],
    *,
    vcs: _GitVcs | None = None,
    budget: _CachePlanBudget | None = None,
) -> tuple[CacheDirectory, ...]:
    return tuple(
        path
        for checkout in checkouts
        for path in _cache_directories_for_checkout(
            config, checkout, vcs=vcs, budget=budget
        )
    )


def _cache_slot_directories(
    config: Config,
    cache_slot: CacheSlot,
    *,
    vcs: _GitVcs | None = None,
    budget: _CachePlanBudget | None = None,
) -> tuple[CacheDirectory, ...]:
    if budget is not None:
        budget.check()
    selected_vcs = vcs or _GitVcs()
    registered = _cache_directories(
        config, cache_slot.checkouts, vcs=selected_vcs, budget=budget
    )
    roots = (
        _unregistered_cache_roots(config, cache_slot.slot)
        if cache_slot.state == "unregistered"
        else ()
    )
    if roots and config.repo_cache_globs and not config.cache_globs:
        raise Refusal(
            f"unregistered slot {cache_slot.slot} has no trusted repository-name mapping; "
            "import it or configure a global cache_globs policy before cleanup"
        )
    unregistered: list[CacheDirectory] = []
    for index, root in enumerate(roots):
        label = f"unregistered-{index + 1}"
        unregistered.extend(
            _cache_directories_for_path(
                config,
                root,
                label,
                selected_vcs,
                config.cache_globs,
                budget=budget,
            )
        )
    return (*registered, *unregistered)


def _validated_cache_journal(
    config: Config,
    path: Path,
    states: Sequence[ActiveState] | None = None,
) -> _ValidatedCacheJournal:
    """Read and provenance-check a cache journal without inspecting its targets."""

    if path.exists() or path.is_symlink():
        contents, _file_identity = _read_regular_file_identity(
            path, "cache recovery journal", _JOURNAL_BYTES_LIMIT
        )
        raw = _strict_json_object(contents, "cache recovery journal")
    else:
        pending = _pending_journal_for_path(config, path)
        if pending is None:
            raise StateError(
                f"journal has neither standalone nor append-only evidence: {path}"
            )
        raw = pending
    _validate_journal_provenance(config, path, raw, states)
    machine = _as_str(raw.get("machine"), "cache recovery journal.machine")
    slot = _validate_name(
        _as_str(raw.get("slot"), "cache recovery journal.slot"), "slot"
    )
    kind = _as_str(raw.get("kind"), "cache recovery journal.kind")
    if kind not in {"create", "import-existing", "finish"}:
        raise StateError(f"unsupported cache recovery journal kind {kind!r}")
    return _ValidatedCacheJournal(path, raw, machine, slot)


def _cache_slot_for_validated_journal(
    config: Config,
    journal: _ValidatedCacheJournal,
) -> CacheSlot:
    """Inspect the checkout and Git targets of one already-validated journal."""

    raw = journal.raw
    selected_machine = journal.machine
    kind = _as_str(raw.get("kind"), "cache recovery journal.kind")
    slot = journal.slot
    if kind == "create":
        slot_type = _as_str(
            raw.get("slot_type", "agent"), "cache recovery journal.slot_type"
        )
        checkouts = tuple(
            _checkout_from_obj(item, f"cache recovery journal.created[{index}]")
            for index, item in enumerate(
                _as_list(raw.get("created"), "cache recovery journal.created")
            )
        )
    elif kind in {"import-existing", "finish"}:
        record = _record_from_obj(raw.get("record"), "cache recovery journal.record")
        slot_type = record.slot_type
        if record.slot != slot or record.machine != selected_machine:
            raise StateError(
                f"{kind} journal cache record does not match its shard or slot"
            )
        _assert_record_paths(config, record)
        removed = (
            {
                _as_str(item, f"cache recovery journal.removed[{index}]")
                for index, item in enumerate(
                    _as_list(raw.get("removed"), "cache recovery journal.removed")
                )
            }
            if kind == "finish"
            else set()
        )
        if not removed <= {checkout.name for checkout in record.checkouts}:
            raise StateError("finish journal cache record names an unknown removed checkout")
        checkouts = tuple(
            checkout for checkout in record.checkouts if checkout.name not in removed
        )
    else:
        raise StateError(f"unsupported cache recovery journal kind {kind!r}")
    journal_layout = (
        _record_layout(config, record)
        if kind in {"import-existing", "finish"}
        else config.layout
    )
    if journal_layout == "flat" and len(checkouts) > 1:
        raise StateError("flat-layout create journal records multiple checkouts")
    vcs = _GitVcs()
    present: list[Checkout] = []
    for checkout in checkouts:
        expected, destination = _checkout_path_for_layout(
            config, slot, checkout.name, slot_type, journal_layout
        )
        if checkout.path != expected:
            raise StateError(
                f"cache recovery journal checkout {checkout.name} escapes slot {slot}"
            )
        _relative, repository = _stored_repository_path(config, checkout.repository)
        if not destination.exists() and not destination.is_symlink():
            if destination.absolute() in vcs.listed_worktrees(repository):
                raise Refusal(
                    f"journaled checkout {checkout.name} is missing but Git still registers it"
                )
            continue
        if destination.is_symlink() or not destination.is_dir():
            raise Refusal(f"journaled checkout is unsafe for cache cleanup: {destination}")
        vcs.verify_existing_worktree(repository, destination)
        present.append(checkout)
    return CacheSlot(
        slot=slot,
        machine=selected_machine,
        checkouts=tuple(present),
        state=f"{kind}-journal",
    )


def _journal_cache_slot(
    config: Config,
    path: Path,
    states: Sequence[ActiveState] | None = None,
) -> CacheSlot:
    journal = _validated_cache_journal(config, path, states)
    return _cache_slot_for_validated_journal(config, journal)


def _all_journal_cache_slots(
    config: Config,
    requested: AbstractSet[str] | None = None,
    states: Sequence[ActiveState] | None = None,
) -> tuple[CacheSlot, ...]:
    journals = tuple(
        _validated_cache_journal(config, path, states)
        for path in _outstanding_journals(config)
    )
    seen: dict[str, str] = {}
    for journal in journals:
        previous = seen.get(journal.slot)
        if previous is not None:
            raise StateError(
                f"slot {journal.slot!r} has recovery journals on both "
                f"{previous} and {journal.machine}"
            )
        seen[journal.slot] = journal.machine
    # Journal parsing, shape/provenance validation, and duplicate detection
    # are global control-plane gates. Checkout, Git, and cache target
    # inspection is intentionally limited to the requested slots.
    return tuple(
        _cache_slot_for_validated_journal(config, journal)
        for journal in journals
        if not requested or journal.slot in requested
    )


def _open_parent_directory(
    root: Path,
    path: Path,
    label: str,
    *,
    expected_root_identity: tuple[int, int, int] | None = None,
) -> tuple[int, str, int]:
    try:
        relative = path.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"{label} escapes its managed root: {path}") from exc
    if not relative.parts:
        raise Refusal(f"{label} must not be the managed root")
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        current_fd = os.open(root, flags)
    except OSError as exc:
        raise Refusal(f"cannot open managed root {root}: {exc}") from exc
    try:
        root_metadata = os.fstat(current_fd)
        root_mount_id = _fd_mount_id(current_fd, str(root))
        if expected_root_identity is not None:
            actual_root_identity = (
                root_metadata.st_dev,
                root_metadata.st_ino,
                root_mount_id,
            )
            if actual_root_identity != expected_root_identity:
                raise Refusal(f"{label} checkout identity changed before cleanup: {root}")
        for part in relative.parts[:-1]:
            next_fd = os.open(part, flags, dir_fd=current_fd)
            if _fd_mount_id(next_fd, str(path)) != root_mount_id:
                os.close(next_fd)
                raise Refusal(f"{label} crossed a mount point while opening {path}")
            os.close(current_fd)
            current_fd = next_fd
        return current_fd, relative.parts[-1], root_mount_id
    except OSError as exc:
        os.close(current_fd)
        raise Refusal(f"cannot safely open {label} parent for {path}: {exc}") from exc
    except Refusal:
        os.close(current_fd)
        raise


def _assert_parent_entry_absent(
    parent_fd: int, parent: Path, path: Path, label: str
) -> None:
    """Check one absent sibling through an already identity-bound parent FD."""

    if path.parent != parent or not path.name:
        raise StateError(f"{label} is not a direct child of its bound parent: {path}")
    try:
        os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return
    except OSError as exc:
        raise Refusal(f"cannot inspect {label} {path}: {exc}") from exc
    raise Refusal(f"{label} reappeared before cleanup: {path}")


def _open_cache_directory(
    config: Config,
    cache: CacheDirectory,
    *,
    expected_absent_path: Path | None = None,
) -> tuple[int, int, str] | None:
    path = cache.path
    _ensure_no_symlink_components(cache.checkout_root, path, "cache path")
    _ensure_no_mount_components(cache.checkout_root, path, "cache path")
    _assert_no_mountinfo_crossing(cache.checkout_root, path, "cache path")
    parent_fd, name, checkout_mount_id = _open_parent_directory(
        cache.checkout_root,
        path,
        "cache path",
        expected_root_identity=(
            cache.checkout_device,
            cache.checkout_inode,
            cache.checkout_mount_id,
        ),
    )
    if expected_absent_path is not None:
        try:
            _assert_parent_entry_absent(
                parent_fd,
                cache.checkout_root,
                expected_absent_path,
                "canonical validation path",
            )
        except BaseException:
            os.close(parent_fd)
            raise
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        cache_fd = os.open(name, flags, dir_fd=parent_fd)
    except FileNotFoundError:
        os.close(parent_fd)
        return None
    except OSError as exc:
        os.close(parent_fd)
        raise Refusal(f"cannot safely open cache directory {path}: {exc}") from exc
    if _fd_mount_id(cache_fd, str(path)) != checkout_mount_id:
        os.close(cache_fd)
        os.close(parent_fd)
        raise Refusal(f"cache path crossed a mount point while opening {path}")
    return parent_fd, cache_fd, name


def _directory_names(
    directory_fd: int,
    path: Path,
    *,
    entry_limit: int | None = None,
    label: str = "cache directory",
) -> list[str]:
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        scan_fd = os.open(".", flags, dir_fd=directory_fd)
    except OSError as exc:
        raise Refusal(f"cannot open {label} {path} for enumeration: {exc}") from exc
    try:
        with os.scandir(scan_fd) as entries:
            names: list[str] = []
            for entry in entries:
                if entry_limit is not None and len(names) >= entry_limit:
                    raise Refusal(f"{label} exceeds its directory-entry bound")
                names.append(entry.name)
            return sorted(names)
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(f"cannot enumerate {label} {path}: {exc}") from exc
    finally:
        os.close(scan_fd)


def _allocated_open_directory(
    directory_fd: int,
    path: Path,
    device: int,
    mount_id: int,
    *,
    allow_git_metadata: bool = False,
    disposable_git: Mapping[Path, tuple[int, int]] | None = None,
    git_metadata_found: list[Path] | None = None,
) -> int:
    try:
        metadata = os.fstat(directory_fd)
        if metadata.st_dev != device:
            raise Refusal(f"cache path crossed onto another filesystem: {path}")
        if _fd_mount_id(directory_fd, str(path)) != mount_id:
            raise Refusal(f"cache path crossed a mount point: {path}")
        total = metadata.st_blocks * 512
        names = _directory_names(directory_fd, path)
        for name in names:
            if name == ".git" and not allow_git_metadata:
                if git_metadata_found is not None:
                    git_metadata_found.append(path / name)
                else:
                    _assert_judged_git_metadata(
                        directory_fd, path, name, disposable_git
                    )
            try:
                child = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise Refusal(f"cannot inspect cache entry {path / name}: {exc}") from exc
            if not stat.S_ISDIR(child.st_mode):
                total += child.st_blocks * 512
                continue
            flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
            try:
                child_fd = os.open(name, flags, dir_fd=directory_fd)
            except OSError as exc:
                raise Refusal(f"cache directory changed during inspection: {path / name}: {exc}") from exc
            try:
                opened = os.fstat(child_fd)
                if (opened.st_dev, opened.st_ino) != (child.st_dev, child.st_ino):
                    raise Refusal(f"cache directory changed during inspection: {path / name}")
                if _fd_mount_id(child_fd, str(path / name)) != mount_id:
                    raise Refusal(f"cache path crossed a mount point: {path / name}")
                total += _allocated_open_directory(
                    child_fd,
                    path / name,
                    device,
                    mount_id,
                    allow_git_metadata=allow_git_metadata,
                    disposable_git=disposable_git,
                    git_metadata_found=git_metadata_found,
                )
            finally:
                os.close(child_fd)
        return total
    except OSError as exc:
        raise Refusal(f"cannot measure cache directory {path}: {exc}") from exc


def _allocated_cache_bytes(config: Config, cache: CacheDirectory) -> int:
    path = cache.path
    opened = _open_cache_directory(config, cache)
    if opened is None:
        return 0
    parent_fd, cache_fd, _name = opened
    try:
        device = os.fstat(cache_fd).st_dev
        mount_id = _fd_mount_id(cache_fd, str(path))
        return _allocated_open_directory(cache_fd, path, device, mount_id)
    finally:
        os.close(cache_fd)
        os.close(parent_fd)


def _audit_cpu_seconds() -> float:
    own = resource.getrusage(resource.RUSAGE_SELF)
    children = resource.getrusage(resource.RUSAGE_CHILDREN)
    return own.ru_utime + own.ru_stime + children.ru_utime + children.ru_stime


@dataclasses.dataclass
class _AuditMetrics:
    """Typed phase measurements whose work counts are stable under host load."""

    phases: list[dict[str, object]] = dataclasses.field(default_factory=list)

    def start(self) -> tuple[float, float]:
        return time.monotonic(), _audit_cpu_seconds()

    def finish(
        self,
        name: str,
        started: tuple[float, float],
        work: Mapping[str, int],
    ) -> None:
        if any(value < 0 for value in work.values()):
            raise StateError(f"audit phase {name} has a negative work counter")
        wall_started, cpu_started = started
        self.phases.append(
            {
                "name": name,
                "wall_seconds": max(0.0, time.monotonic() - wall_started),
                "cpu_seconds": max(0.0, _audit_cpu_seconds() - cpu_started),
                "work": dict(sorted(work.items())),
            }
        )

    def to_obj(self) -> dict[str, object]:
        names = [str(item["name"]) for item in self.phases]
        if len(names) != len(set(names)):
            raise StateError("audit phase metrics contain duplicate names")
        return {"schema": _AUDIT_METRICS_SCHEMA, "phases": list(self.phases)}


@dataclasses.dataclass(frozen=True)
class _AuditCacheMeasurement:
    bytes: int | None
    status: str
    error: str | None = None


@dataclasses.dataclass
class _AuditWorkBudget:
    """One shared cache-census budget debited at the point work occurs."""

    limit: int
    consumed: int = 0
    on_debit: Callable[[int], None] | None = dataclasses.field(
        default=None, repr=False, compare=False
    )

    @property
    def remaining(self) -> int:
        return self.limit - self.consumed

    def debit(self) -> None:
        if self.remaining <= 0:
            raise StateError("cache census attempted work after exhausting its budget")
        consumed = self.consumed + 1
        if self.on_debit is not None:
            self.on_debit(consumed)
        self.consumed = consumed


class _LinuxDirent(ctypes.Structure):
    """glibc/Linux dirent layout used to retain an opaque telldir cursor."""

    _fields_ = (
        ("d_ino", ctypes.c_ulong),
        ("d_off", ctypes.c_long),
        ("d_reclen", ctypes.c_ushort),
        ("d_type", ctypes.c_ubyte),
        ("d_name", ctypes.c_char * 256),
    )


@contextlib.contextmanager
def _audit_directory_stream(
    directory_fd: int,
    cursor: int,
    label: str,
) -> Iterator[Callable[[], tuple[str, int] | None]]:
    """Open a seekable directory stream at one unchanged-directory cookie."""

    libc = ctypes.CDLL(None, use_errno=True)
    try:
        fdopendir = libc.fdopendir
        readdir = libc.readdir
        telldir = libc.telldir
        seekdir = libc.seekdir
        closedir = libc.closedir
    except AttributeError as exc:
        raise Refusal(f"cache census directory cursors are unavailable for {label}") from exc
    fdopendir.argtypes = [ctypes.c_int]
    fdopendir.restype = ctypes.c_void_p
    readdir.argtypes = [ctypes.c_void_p]
    readdir.restype = ctypes.POINTER(_LinuxDirent)
    telldir.argtypes = [ctypes.c_void_p]
    telldir.restype = ctypes.c_long
    seekdir.argtypes = [ctypes.c_void_p, ctypes.c_long]
    seekdir.restype = None
    closedir.argtypes = [ctypes.c_void_p]
    closedir.restype = ctypes.c_int
    duplicate = os.dup(directory_fd)
    stream = fdopendir(duplicate)
    if stream is None:
        error = ctypes.get_errno()
        os.close(duplicate)
        raise Refusal(f"cannot open cache census cursor for {label}: {os.strerror(error)}")
    if cursor:
        seekdir(stream, cursor)

    def next_entry() -> tuple[str, int] | None:
        ctypes.set_errno(0)
        entry = readdir(stream)
        if not entry:
            error = ctypes.get_errno()
            if error:
                raise Refusal(
                    f"cannot read cache census directory {label}: {os.strerror(error)}"
                )
            return None
        name = os.fsdecode(bytes(entry.contents.d_name).split(b"\0", 1)[0])
        next_cursor = int(telldir(stream))
        if next_cursor < 0:
            raise Refusal(f"cache census returned an invalid cursor for {label}")
        return name, next_cursor

    try:
        yield next_entry
    finally:
        if closedir(stream) != 0:
            error = ctypes.get_errno()
            raise Refusal(
                f"cannot close cache census directory {label}: {os.strerror(error)}"
            )


def _audit_cache_check_deadline(deadline: float | None) -> None:
    if deadline is not None and time.monotonic() >= deadline:
        raise _AuditCacheTimeout("cache census traversal exhausted the fixed wall allowance")


def _open_absolute_directory_nofollow(
    path: Path, label: str, *, deadline: float | None = None
) -> int:
    if not path.is_absolute() or ".." in path.parts:
        raise Refusal(f"{label} must be a canonical absolute directory")
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    _audit_cache_check_deadline(deadline)
    fd = os.open(Path("/"), flags)
    try:
        for component in path.parts[1:]:
            _audit_cache_check_deadline(deadline)
            child_fd = os.open(component, flags, dir_fd=fd)
            os.close(fd)
            fd = child_fd
        _audit_cache_check_deadline(deadline)
        raw_actual = os.readlink(f"/proc/self/fd/{fd}")
        if raw_actual.endswith(" (deleted)") or Path(raw_actual) != path:
            raise Refusal(f"{label} changed or crossed a symlink while binding")
    except BaseException:
        os.close(fd)
        raise
    return fd


def _open_or_create_absolute_directory_nofollow(path: Path, label: str) -> int:
    """Bind an absolute directory, creating missing components without aliases."""

    if not path.is_absolute() or ".." in path.parts:
        raise Refusal(f"{label} must be a canonical absolute directory")
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    fd = os.open(Path("/"), flags)
    try:
        for component in path.parts[1:]:
            try:
                child_fd = os.open(component, flags, dir_fd=fd)
            except FileNotFoundError:
                try:
                    os.mkdir(component, 0o700, dir_fd=fd)
                except FileExistsError:
                    # A concurrent creator is acceptable only if the no-follow
                    # open below proves that it created an ordinary directory.
                    pass
                child_fd = os.open(component, flags, dir_fd=fd)
            os.close(fd)
            fd = child_fd
        raw_actual = os.readlink(f"/proc/self/fd/{fd}")
        if raw_actual.endswith(" (deleted)") or Path(raw_actual) != path:
            raise Refusal(f"{label} changed or crossed a symlink while binding")
    except BaseException:
        os.close(fd)
        raise
    return fd


def _audit_cache_state_path(config: Config, explicit: str | None) -> Path:
    if explicit is not None:
        candidate = Path(explicit)
        if (
            not candidate.is_absolute()
            or ".." in candidate.parts
            or Path(os.path.normpath(str(candidate))) != candidate
        ):
            raise Refusal(
                "--cache-census-state must be a canonical absolute path without '..'"
            )
    else:
        cache_home = Path(
            os.environ.get("XDG_CACHE_HOME", str(Path.home() / ".cache"))
        ).expanduser()
        if not cache_home.is_absolute():
            raise Refusal("XDG_CACHE_HOME must be absolute for audit cache state")
        if _path_is_within(cache_home, config.root):
            raise Refusal("audit cache home must be outside the managed project tree")
        try:
            parent_fd = _open_or_create_absolute_directory_nofollow(
                cache_home, "audit cache home"
            )
        except (OSError, Refusal) as exc:
            raise Refusal(f"audit cache home is unavailable: {cache_home}: {exc}") from exc
        cache_parent = cache_home
        try:
            for component in ("wrkslots", "audit-cache"):
                try:
                    os.mkdir(component, 0o700, dir_fd=parent_fd)
                except FileExistsError:
                    pass
                child_fd = os.open(
                    component,
                    os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
                    dir_fd=parent_fd,
                )
                os.close(parent_fd)
                parent_fd = child_fd
                cache_parent /= component
            os.fsync(parent_fd)
        except OSError as exc:
            raise Refusal(
                f"cannot prepare symlink-free audit cache state directory: {exc}"
            ) from exc
        finally:
            os.close(parent_fd)
        project = hashlib.sha256(str(config.root).encode("utf-8")).hexdigest()
        candidate = cache_parent / f"{project}.json"
    if not candidate.is_absolute() or _path_is_within(candidate, config.root):
        raise Refusal("audit cache census state must be outside the managed project tree")
    try:
        resolved_parent = candidate.parent.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise Refusal(
            f"audit cache census state parent must already exist: {candidate.parent}: {exc}"
        ) from exc
    if resolved_parent != candidate.parent or _path_is_within(
        resolved_parent, config.root
    ):
        raise Refusal(
            "audit cache census state parent must be symlink-free and outside the "
            "managed project tree"
        )
    return candidate


def _open_audit_cache_state_parent(config: Config, path: Path) -> int:
    try:
        fd = _open_absolute_directory_nofollow(
            path.parent, "audit cache census state parent"
        )
    except (OSError, Refusal) as exc:
        raise Refusal(f"cannot bind audit cache census state parent: {exc}") from exc
    try:
        metadata = os.fstat(fd)
        if not stat.S_ISDIR(metadata.st_mode):
            raise Refusal("audit cache census state parent is not a directory")
        if _path_is_within(path.parent, config.root):
            raise Refusal(
                "audit cache census state parent entered the managed project tree"
            )
    except BaseException:
        os.close(fd)
        raise
    return fd


def _audit_cache_state_json_chunks(
    payload: Mapping[str, object],
) -> Iterator[bytes]:
    """Bound both canonical encoding work and the eventual on-disk encoding.

    State has a shallow fixed schema. A modest nesting ceiling also rejects
    cyclic or hostile decoded values before the recursive JSON encoder runs.
    The preliminary lower bound prevents one oversized string/container from
    being encoded before the exact byte limit is checked below.
    """

    lower_bound = 0

    def visit(value: object, depth: int) -> None:
        nonlocal lower_bound
        if depth > 32:
            raise Refusal("audit cache census state exceeds its nesting bound")
        if isinstance(value, str):
            lower_bound += len(value) + 2
        elif isinstance(value, Mapping):
            lower_bound += 2
            for name, child in value.items():
                if not isinstance(name, str):
                    raise Refusal("audit cache census state has a non-string member")
                visit(name, depth + 1)
                visit(child, depth + 1)
        elif isinstance(value, list):
            lower_bound += 2
            for child in value:
                visit(child, depth + 1)
        elif value is None or isinstance(value, (int, float)):
            lower_bound += 1
        else:
            raise Refusal("audit cache census state contains an unsupported value")
        if lower_bound > _AUDIT_CACHE_STATE_BYTES_LIMIT:
            raise Refusal(
                "audit cache census state exceeds its "
                f"{_AUDIT_CACHE_STATE_BYTES_LIMIT}-byte safety bound"
            )

    visit(payload, 0)
    encoder = json.JSONEncoder(
        sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False
    )
    encoded_bytes = 0
    try:
        for chunk in encoder.iterencode(payload):
            encoded = chunk.encode("ascii")
            encoded_bytes += len(encoded)
            if encoded_bytes > _AUDIT_CACHE_STATE_BYTES_LIMIT:
                raise Refusal(
                    "audit cache census state exceeds its "
                    f"{_AUDIT_CACHE_STATE_BYTES_LIMIT}-byte safety bound"
                )
            yield encoded
    except (TypeError, ValueError, RecursionError) as exc:
        raise Refusal("audit cache census state cannot be safely encoded") from exc


def _audit_cache_state_mac(
    key: bytes, payload: Mapping[str, object]
) -> str:
    digest = hmac.new(key, digestmod=hashlib.sha256)
    for chunk in _audit_cache_state_json_chunks(payload):
        digest.update(chunk)
    return digest.hexdigest()


def _read_audit_cache_state(
    path: Path,
    parent_fd: int,
    key: bytes,
    registry_revision: str,
) -> dict[str, object] | None:
    """Malformed regenerable progress must never abort the lifecycle report."""

    try:
        decoded = json.loads(
            _read_bounded_regular_file_at(
                parent_fd,
                path.name,
                "audit cache census",
                _AUDIT_CACHE_STATE_BYTES_LIMIT,
            ).decode("utf-8")
        )
        if not isinstance(decoded, Mapping):
            return None
        envelope = dict(decoded)
        mac = envelope.pop("hmac_sha256", None)
        if (
            isinstance(mac, str)
            and DIGEST_RE.fullmatch(mac) is not None
            and envelope.get("schema") == _AUDIT_CACHE_CENSUS_SCHEMA
            and envelope.get("registry_revision") == registry_revision
            and isinstance(envelope.get("roots"), dict)
            and (
                envelope.get("next_subject") is None
                or isinstance(envelope.get("next_subject"), str)
            )
            and set(envelope)
            == {"schema", "registry_revision", "roots", "next_subject"}
            and hmac.compare_digest(mac, _audit_cache_state_mac(key, envelope))
        ):
            return envelope
    except (OSError, Refusal, UnicodeError, ValueError, RecursionError):
        # ValueError includes JSONDecodeError and bounded integer conversion
        # failures; deeply nested JSON can instead fail with RecursionError.
        # Authentication encoding uses the same bounded rejection path.
        pass
    return None


def _read_bounded_regular_file_at(
    parent_fd: int, name: str, label: str, limit: int
) -> bytes:
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(name, flags, dir_fd=parent_fd)
    try:
        metadata = os.fstat(fd)
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_size > limit:
            raise Refusal(f"{label} is not one bounded regular file")
        chunks: list[bytes] = []
        remaining = limit + 1
        while remaining:
            chunk = os.read(fd, min(remaining, 64 * 1024))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
    finally:
        os.close(fd)
    contents = b"".join(chunks)
    if len(contents) > limit:
        raise Refusal(f"{label} exceeds its {limit}-byte safety bound")
    return contents


def _read_audit_cache_key(parent_fd: int, name: str) -> bytes:
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOFOLLOW
    fd = os.open(name, flags, dir_fd=parent_fd)
    try:
        metadata = os.fstat(fd)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.geteuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or metadata.st_size != _AUDIT_CACHE_KEY_BYTES
        ):
            raise Refusal(
                "audit cache census key must be one owner-bound 0600 regular file "
                f"of exactly {_AUDIT_CACHE_KEY_BYTES} bytes"
            )
        key = os.read(fd, _AUDIT_CACHE_KEY_BYTES + 1)
    finally:
        os.close(fd)
    if len(key) != _AUDIT_CACHE_KEY_BYTES:
        raise Refusal(
            f"audit cache census key must contain exactly {_AUDIT_CACHE_KEY_BYTES} bytes"
        )
    return key


def _publish_audit_cache_key_noreplace(
    parent_fd: int, candidate: str, key_name: str
) -> None:
    """Publish a complete key without replacing a concurrent creator's key."""

    try:
        renameat2 = ctypes.CDLL(None, use_errno=True).renameat2
    except AttributeError as exc:
        raise Refusal(
            "cannot publish audit cache census key: atomic no-replace rename "
            "is unavailable"
        ) from exc
    renameat2.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    ctypes.set_errno(0)
    if renameat2(
        parent_fd, os.fsencode(candidate), parent_fd, os.fsencode(key_name), 1
    ) == 0:
        return
    error = ctypes.get_errno()
    if error in (errno.ENOSYS, errno.EINVAL, errno.EOPNOTSUPP):
        raise Refusal(
            "cannot publish audit cache census key: filesystem lacks atomic "
            "no-replace rename support"
        )
    # EEXIST becomes FileExistsError so the loser reads the winner's key below.
    raise OSError(error, os.strerror(error), key_name)


def _audit_cache_state_key(
    path: Path,
    parent_fd: int,
) -> bytes:
    key_name = f"{path.name}.key"
    try:
        return _read_audit_cache_key(parent_fd, key_name)
    except FileNotFoundError:
        pass
    # One reserved candidate bounds crash debris without scanning storage. Its
    # lock is released by process death, so an interrupted partial write can be
    # safely rebuilt. Only a complete, synced candidate acquires the final name.
    candidate = f".{key_name}.pending"
    flags = os.O_RDWR | os.O_CREAT | os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOFOLLOW
    fd = os.open(candidate, flags, 0o600, dir_fd=parent_fd)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc:
            raise Refusal("audit cache census key creation is already in progress") from exc
        try:
            # A competing publisher may have renamed the very inode we opened.
            # Re-read final authority before ever truncating a candidate fd.
            return _read_audit_cache_key(parent_fd, key_name)
        except FileNotFoundError:
            pass
        metadata = os.fstat(fd)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != os.geteuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or not 0 <= metadata.st_size <= _AUDIT_CACHE_KEY_BYTES
        ):
            raise Refusal(
                "audit cache census key candidate must be one owner-bound 0600 "
                f"regular file of at most {_AUDIT_CACHE_KEY_BYTES} bytes"
            )
        named = os.stat(candidate, dir_fd=parent_fd, follow_symlinks=False)
        if (named.st_dev, named.st_ino) != (metadata.st_dev, metadata.st_ino):
            raise Refusal("audit cache census key candidate changed while binding")
        os.ftruncate(fd, 0)
        generated = os.urandom(_AUDIT_CACHE_KEY_BYTES)
        offset = 0
        while offset < len(generated):
            written = os.write(fd, generated[offset:])
            if written <= 0:
                raise OSError("short write while creating audit cache census key")
            offset += written
        os.fsync(fd)
        if _read_audit_cache_key(parent_fd, candidate) != generated:
            raise Refusal("audit cache census key candidate changed before publication")
        try:
            _publish_audit_cache_key_noreplace(parent_fd, candidate, key_name)
        except FileExistsError:
            # A different creator's complete key is the only authority.
            pass
        key = _read_audit_cache_key(parent_fd, key_name)
        os.fsync(parent_fd)
        return key
    finally:
        os.close(fd)


def _write_audit_cache_state(
    path: Path,
    payload: Mapping[str, object],
    key: bytes,
    parent_fd: int,
) -> None:
    envelope = {**payload, "hmac_sha256": _audit_cache_state_mac(key, payload)}
    encoded = bytearray()
    for chunk in _audit_cache_state_json_chunks(envelope):
        encoded.extend(chunk)
    # Use exactly the compact encoding that was size-checked. In particular,
    # indentation or a trailing newline must not make our own state unreadable.
    # Preflight finishes before any temporary file is created.
    temporary = f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC
    fd = os.open(temporary, flags, 0o600, dir_fd=parent_fd)
    try:
        with os.fdopen(fd, "wb", closefd=True) as handle:
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(
            temporary,
            path.name,
            src_dir_fd=parent_fd,
            dst_dir_fd=parent_fd,
        )
        os.fsync(parent_fd)
    except BaseException:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(temporary, dir_fd=parent_fd)
        raise


def _audit_registry_revision(states: Sequence[ActiveState]) -> str:
    identity = [
        {"machine": state.machine, "revision": state.revision}
        for state in sorted(states, key=lambda value: value.machine)
    ]
    return hashlib.sha256(
        json.dumps(identity, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _audit_cache_root_identity_unbounded(
    config: Config, cache: CacheDirectory
) -> tuple[int, int, int, int, int] | None:
    opened = _open_cache_directory(config, cache)
    if opened is None:
        return None
    parent_fd, cache_fd, _name = opened
    try:
        metadata = os.fstat(cache_fd)
        return (
            metadata.st_dev,
            metadata.st_ino,
            _fd_mount_id(cache_fd, str(cache.path)),
            metadata.st_mtime_ns,
            metadata.st_ctime_ns,
        )
    finally:
        os.close(cache_fd)
        os.close(parent_fd)


class _AuditCacheTimeout(Refusal):
    """The shared execution allowance expired, possibly during a syscall."""


def _run_audit_cache_worker(
    operation: str,
    work: Callable[[], Mapping[str, object]],
    *,
    deadline: float,
    result_limit: int,
) -> Mapping[str, object]:
    """Bound filesystem execution and its result transfer by one deadline.

    No inherited registry or state locks survive in the child. Its private pipe
    carries bounded JSON; a killed or late worker supplies no completion evidence.
    """

    expired = f"cache census {operation} exceeded the fixed wall allowance"
    if time.monotonic() >= deadline:
        raise _AuditCacheTimeout(expired)
    read_fd, write_fd = os.pipe2(os.O_CLOEXEC)
    pid: int | None = None
    pid_fd: int | None = None
    reaped = False
    try:
        pid = os.fork()
        if pid == 0:
            try:
                # Do not keep a parent's lifecycle lock alive if a filesystem
                # operation remains uninterruptible after cancellation.
                for name in os.listdir("/proc/self/fd"):
                    descriptor = int(name)
                    if descriptor != write_fd:
                        try:
                            os.close(descriptor)
                        except OSError as exc:
                            if exc.errno != errno.EBADF:
                                raise
                try:
                    # A descheduled child must not start late work either.
                    if time.monotonic() >= deadline:
                        os._exit(2)
                    payload: dict[str, object] = {"value": work()}
                except _AuditCacheTimeout:
                    os._exit(2)
                except BaseException as exc:
                    payload = {"error": str(exc)[:512]}
                # Traversal progress can be large. Coalesce encoder fragments
                # into bounded chunks; never allocate an unchecked whole result
                # or issue a syscall for every tiny JSON token.
                encoder = json.JSONEncoder(
                    ensure_ascii=True, allow_nan=False, separators=(",", ":")
                )
                buffer = bytearray()
                encoded_size = 0

                def flush() -> None:
                    offset = 0
                    while offset < len(buffer):
                        if time.monotonic() >= deadline:
                            os._exit(2)
                        written = os.write(write_fd, memoryview(buffer)[offset:])
                        if written <= 0:
                            os._exit(1)
                        offset += written
                    buffer.clear()

                for fragment in encoder.iterencode(payload):
                    if time.monotonic() >= deadline:
                        os._exit(2)
                    encoded = fragment.encode("ascii")
                    encoded_size += len(encoded)
                    if encoded_size > result_limit:
                        os._exit(3)
                    buffer.extend(encoded)
                    if len(buffer) >= 64 * 1024:
                        flush()
                flush()
                os._exit(0)
            except BaseException:
                os._exit(1)
        os.close(write_fd)
        write_fd = -1
        pid_fd = os.pidfd_open(pid)
        os.set_blocking(read_fd, False)
        received = bytearray()
        eof = exited = False
        with selectors.DefaultSelector() as selector:
            selector.register(read_fd, selectors.EVENT_READ, "result")
            selector.register(pid_fd, selectors.EVENT_READ, "exit")
            while not (eof and exited):
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise _AuditCacheTimeout(expired)
                for key, _events in selector.select(remaining):
                    if key.data == "exit":
                        exited = True
                        selector.unregister(pid_fd)
                    else:
                        chunk = os.read(read_fd, min(64 * 1024, result_limit + 1 - len(received)))
                        if not chunk:
                            eof = True
                            selector.unregister(read_fd)
                        received.extend(chunk)
                        if len(received) > result_limit:
                            raise Refusal(f"cache census {operation} result is oversized")
            _waited, status = os.waitpid(pid, 0)
            reaped = True
        if time.monotonic() >= deadline or status == 2 << 8:
            raise _AuditCacheTimeout(expired)
        if status == 3 << 8:
            raise Refusal(f"cache census {operation} result is oversized")
        if status != 0:
            raise Refusal(f"cache census {operation} worker failed")
        try:
            packet = json.loads(received)
        except (ValueError, RecursionError) as exc:
            raise Refusal(f"invalid cache census {operation} result") from exc
        if time.monotonic() >= deadline:
            raise _AuditCacheTimeout(expired)
        if not isinstance(packet, dict):
            raise Refusal(f"invalid cache census {operation} result")
        if set(packet) == {"error"} and isinstance(packet["error"], str):
            raise Refusal(packet["error"])
        if set(packet) != {"value"}:
            raise Refusal(f"invalid cache census {operation} result")
        return _as_mapping(packet["value"], f"cache census {operation} result")
    finally:
        try:
            if pid is not None and pid > 0 and not reaped:
                # The unreaped PID is still ours. Never signal a PID after reaping.
                with contextlib.suppress(ProcessLookupError):
                    os.kill(pid, signal.SIGKILL)
                if pid_fd is not None:
                    with selectors.DefaultSelector() as cleanup:
                        cleanup.register(pid_fd, selectors.EVENT_READ)
                        cleanup.select(_READ_ONLY_COMMAND_REAP_SECONDS)
                    os.waitpid(pid, os.WNOHANG)
                else:
                    # pidfd setup failure must also have bounded cancellation.
                    cleanup_deadline = time.perf_counter() + _READ_ONLY_COMMAND_REAP_SECONDS
                    while os.waitpid(pid, os.WNOHANG)[0] == 0:
                        if time.perf_counter() >= cleanup_deadline:
                            break
                        time.sleep(0.01)
        finally:
            for owned_fd in (read_fd, write_fd, pid_fd):
                if owned_fd is not None and owned_fd >= 0:
                    os.close(owned_fd)


def _audit_cache_root_identity(
    config: Config,
    cache: CacheDirectory,
    *,
    deadline: float | None = None,
) -> tuple[int, int, int, int, int] | None:
    if deadline is None:
        return _audit_cache_root_identity_unbounded(config, cache)
    packet = _run_audit_cache_worker(
        "root binding",
        lambda: {"identity": _audit_cache_root_identity_unbounded(config, cache)},
        deadline=deadline,
        result_limit=4096,
    )
    if set(packet) != {"identity"}:
        raise Refusal("invalid cache census root binding result")
    identity = packet["identity"]
    if identity is None:
        return None
    if (
        not isinstance(identity, list)
        or len(identity) != 5
        or any(type(value) is not int for value in identity)
    ):
        raise Refusal("invalid cache census root binding identity")
    return identity[0], identity[1], identity[2], identity[3], identity[4]


def _audit_cache_root_key(
    cache: CacheDirectory, identity: Sequence[int]
) -> str:
    value = {
        "path": str(cache.path),
        "checkout_root": str(cache.checkout_root),
        "identity": list(identity),
    }
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _new_audit_cache_root(
    cache: CacheDirectory, identity: Sequence[int]
) -> dict[str, object]:
    return {
        "path": str(cache.path),
        "identity": list(identity),
        "phase": "measure",
        "bytes": 0,
        "verify_bytes": 0,
        "pending": ["."],
        "current": None,
        "status": "partial",
        "entries_visited": 0,
        "directories_visited": 0,
        "entries_verified": 0,
        "directories_verified": 0,
        "verified_directories": [],
        "verified_entries": [],
        "finalize_index": 0,
        "finalize_entry_index": 0,
        "directories_finalized": 0,
        "entries_finalized": 0,
    }


def _audit_cache_relative(value: object, label: str) -> str:
    relative = _as_str(value, label)
    if relative == ".":
        return relative
    lexical = Path(relative)
    if (
        lexical.is_absolute()
        or not lexical.parts
        or ".." in lexical.parts
        or lexical.as_posix() != relative
    ):
        raise StateError(f"{label} is not canonical: {relative!r}")
    return relative


def _validated_audit_cache_root(
    value: Mapping[str, object],
    cache: CacheDirectory,
    identity: Sequence[int],
    *,
    deadline: float | None = None,
) -> dict[str, object]:
    """Accept persisted progress only when every structural invariant holds."""

    def check_deadline() -> None:
        if deadline is not None and time.monotonic() >= deadline:
            raise Refusal("cache census root validation exhausted the fixed wall allowance")

    check_deadline()
    required = {
        "path",
        "identity",
        "phase",
        "bytes",
        "verify_bytes",
        "pending",
        "current",
        "status",
        "entries_visited",
        "directories_visited",
        "entries_verified",
        "directories_verified",
        "verified_directories",
        "verified_entries",
        "finalize_index",
        "finalize_entry_index",
        "directories_finalized",
        "entries_finalized",
    }
    _exact_keys(value, required, set(), "audit cache root")
    if value["path"] != str(cache.path) or value["identity"] != list(identity):
        raise StateError("audit cache root identity changed")
    phase = _as_str(value["phase"], "audit cache root.phase")
    status = _as_str(value["status"], "audit cache root.status")
    if phase not in {"measure", "verify", "finalize"} or status not in {
        "partial",
        "complete",
    }:
        raise StateError("audit cache root phase or status is invalid")
    for field in (
        "bytes",
        "verify_bytes",
        "entries_visited",
        "directories_visited",
        "entries_verified",
        "directories_verified",
        "finalize_index",
        "finalize_entry_index",
        "directories_finalized",
        "entries_finalized",
    ):
        _as_int(value[field], f"audit cache root.{field}", minimum=0)
    pending: list[str] = []
    pending_paths: set[str] = set()
    for index, item in enumerate(
        _as_list(value["pending"], "audit cache root.pending")
    ):
        check_deadline()
        relative = _audit_cache_relative(item, f"audit cache root.pending[{index}]")
        if relative in pending_paths:
            raise StateError("audit cache root.pending contains duplicates")
        pending_paths.add(relative)
        pending.append(relative)
    current_raw = value["current"]
    current: dict[str, object] | None
    if current_raw is None:
        current = None
    else:
        current = dict(_as_mapping(current_raw, "audit cache root.current"))
        _exact_keys(
            current,
            {"path", "cursor", "identity"},
            set(),
            "audit cache root.current",
        )
        _audit_cache_relative(current["path"], "audit cache root.current.path")
        _as_int(current["cursor"], "audit cache root.current.cursor", minimum=0)
        current_identity = _as_list(
            current["identity"], "audit cache root.current.identity"
        )
        if len(current_identity) != 4:
            raise StateError("audit cache root.current.identity must contain four integers")
        for item in current_identity:
            _as_int(item, "audit cache root.current.identity item", minimum=0)
    if phase == "measure" and (
        _as_int(value["verify_bytes"], "audit cache root.verify_bytes") != 0
        or _as_int(value["entries_verified"], "audit cache root.entries_verified") != 0
        or _as_int(
            value["directories_verified"], "audit cache root.directories_verified"
        )
        != 0
        or _as_list(
            value["verified_directories"],
            "audit cache root.verified_directories",
        )
        or _as_list(
            value["verified_entries"],
            "audit cache root.verified_entries",
        )
        or _as_int(value["finalize_index"], "audit cache root.finalize_index") != 0
        or _as_int(
            value["finalize_entry_index"],
            "audit cache root.finalize_entry_index",
        )
        != 0
        or _as_int(
            value["directories_finalized"],
            "audit cache root.directories_finalized",
        )
        != 0
        or _as_int(
            value["entries_finalized"],
            "audit cache root.entries_finalized",
        )
        != 0
    ):
        raise StateError("measurement-phase cache state contains verification progress")
    if phase == "verify" and _as_int(
        value["directories_visited"], "audit cache root.directories_visited"
    ) < 1:
        raise StateError("verification cache state has no measured root directory")
    verified_directories: list[dict[str, object]] = []
    directory_paths: set[str] = set()
    for index, item in enumerate(
        _as_list(
            value["verified_directories"],
            "audit cache root.verified_directories",
        )
    ):
        check_deadline()
        entry = dict(
            _as_mapping(
                item,
                f"audit cache root.verified_directories[{index}]",
            )
        )
        _exact_keys(
            entry,
            {"path", "identity"},
            set(),
            f"audit cache root.verified_directories[{index}]",
        )
        relative = _audit_cache_relative(
            entry["path"],
            f"audit cache root.verified_directories[{index}].path",
        )
        if relative in directory_paths:
            raise StateError("audit cache verified directories contain duplicates")
        directory_paths.add(relative)
        directory_identity = _as_list(
            entry["identity"],
            f"audit cache root.verified_directories[{index}].identity",
        )
        if len(directory_identity) != 4:
            raise StateError(
                "audit cache verified directory identity must contain four integers"
            )
        for identity_item in directory_identity:
            _as_int(
                identity_item,
                "audit cache verified directory identity item",
                minimum=0,
            )
        verified_directories.append(entry)
    if len(verified_directories) != _as_int(
        value["directories_verified"],
        "audit cache root.directories_verified",
    ):
        raise StateError("audit cache verified directory count is inconsistent")
    verified_entries: list[dict[str, object]] = []
    entry_paths: set[str] = set()
    for index, item in enumerate(
        _as_list(value["verified_entries"], "audit cache root.verified_entries")
    ):
        check_deadline()
        entry = dict(
            _as_mapping(item, f"audit cache root.verified_entries[{index}]")
        )
        _exact_keys(
            entry,
            {"path", "identity"},
            set(),
            f"audit cache root.verified_entries[{index}]",
        )
        relative = _audit_cache_relative(
            entry["path"], f"audit cache root.verified_entries[{index}].path"
        )
        if relative in entry_paths:
            raise StateError("audit cache verified entries contain duplicates")
        entry_paths.add(relative)
        entry_identity = _as_list(
            entry["identity"],
            f"audit cache root.verified_entries[{index}].identity",
        )
        if len(entry_identity) != 7:
            raise StateError("audit cache verified entry identity must contain seven integers")
        for identity_item in entry_identity:
            _as_int(
                identity_item,
                "audit cache verified entry identity item",
                minimum=0,
            )
        verified_entries.append(entry)
    finalize_index = _as_int(
        value["finalize_index"], "audit cache root.finalize_index", minimum=0
    )
    if finalize_index > len(verified_directories):
        raise StateError("audit cache finalize index is out of range")
    finalize_entry_index = _as_int(
        value["finalize_entry_index"],
        "audit cache root.finalize_entry_index",
        minimum=0,
    )
    if finalize_entry_index > len(verified_entries):
        raise StateError("audit cache finalize entry index is out of range")
    if phase != "finalize" and (
        finalize_index != 0
        or finalize_entry_index != 0
        or _as_int(
            value["directories_finalized"],
            "audit cache root.directories_finalized",
        )
        != 0
        or _as_int(
            value["entries_finalized"], "audit cache root.entries_finalized"
        )
        != 0
    ):
        raise StateError("audit cache state finalized directories before finalization")
    directories_finalized = _as_int(
        value["directories_finalized"],
        "audit cache root.directories_finalized",
    )
    entries_finalized = _as_int(
        value["entries_finalized"], "audit cache root.entries_finalized"
    )
    if phase == "finalize" and (
        current is not None
        or pending
        or value["bytes"] != value["verify_bytes"]
        or not verified_directories
        or directories_finalized != finalize_index
        or entries_finalized != finalize_entry_index
    ):
        raise StateError("audit cache finalization state is inconsistent")
    if status == "complete" and (
        phase != "finalize"
        or current is not None
        or pending
        or value["bytes"] != value["verify_bytes"]
        or finalize_index != len(verified_directories)
        or directories_finalized != len(verified_directories)
        or finalize_entry_index != len(verified_entries)
        or entries_finalized != len(verified_entries)
        or not verified_directories
    ):
        raise StateError("completed cache state lacks a full matching verification")
    check_deadline()
    return {
        **value,
        "pending": pending,
        "current": current,
        "verified_directories": verified_directories,
        "verified_entries": verified_entries,
    }


def _open_audit_cache_child(
    parent_fd: int,
    component: str,
    cache: CacheDirectory,
    label: Path,
    *,
    deadline: float | None = None,
) -> tuple[int, os.stat_result, int]:
    """Open one child and close it on every failure before ownership transfer."""

    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    _audit_cache_check_deadline(deadline)
    child_fd = os.open(component, flags, dir_fd=parent_fd)
    try:
        _audit_cache_check_deadline(deadline)
        metadata = os.fstat(child_fd)
        _audit_cache_check_deadline(deadline)
        mount_id = _fd_mount_id(child_fd, str(label))
        if (
            metadata.st_dev != cache.checkout_device
            or mount_id != cache.checkout_mount_id
        ):
            raise Refusal(f"cache census crossed a filesystem boundary: {label}")
    except BaseException:
        os.close(child_fd)
        raise
    return child_fd, metadata, mount_id


def _open_audit_cache_relative(
    cache: CacheDirectory,
    root_identity: Sequence[int],
    relative: str,
    *,
    deadline: float | None = None,
) -> tuple[int, os.stat_result, int]:
    """Open a descendant through exact checkout and cache-root identities."""

    relative = _audit_cache_relative(relative, "cache census relative path")
    try:
        cache_parts = cache.path.relative_to(cache.checkout_root).parts
    except ValueError as exc:
        raise Refusal(f"cache census root escapes its checkout: {cache.path}") from exc
    if not cache_parts:
        raise Refusal("cache census root must be below its checkout")
    expected_root = tuple(root_identity)
    if len(expected_root) != 5:
        raise StateError("cache census root identity must contain five integers")
    try:
        current_fd = _open_absolute_directory_nofollow(
            cache.checkout_root, "cache census checkout", deadline=deadline
        )
    except _AuditCacheTimeout:
        raise
    except (OSError, Refusal) as exc:
        raise Refusal(
            f"cannot bind cache census checkout {cache.checkout_root}: {exc}"
        ) from exc
    try:
        _audit_cache_check_deadline(deadline)
        checkout_metadata = os.fstat(current_fd)
        _audit_cache_check_deadline(deadline)
        checkout_mount_id = _fd_mount_id(current_fd, str(cache.checkout_root))
        if (
            checkout_metadata.st_dev,
            checkout_metadata.st_ino,
            checkout_mount_id,
        ) != (
            cache.checkout_device,
            cache.checkout_inode,
            cache.checkout_mount_id,
        ):
            raise Refusal(
                f"cache census checkout identity changed: {cache.checkout_root}"
            )
        current_path = cache.checkout_root
        metadata = checkout_metadata
        mount_id = checkout_mount_id
        for component in cache_parts:
            current_path /= component
            child_fd, metadata, mount_id = _open_audit_cache_child(
                current_fd, component, cache, current_path, deadline=deadline
            )
            os.close(current_fd)
            current_fd = child_fd
        actual_root = (
            metadata.st_dev,
            metadata.st_ino,
            mount_id,
            metadata.st_mtime_ns,
            metadata.st_ctime_ns,
        )
        if actual_root != expected_root:
            raise Refusal(f"cache census root identity changed: {cache.path}")
        if relative != ".":
            for component in Path(relative).parts:
                current_path /= component
                child_fd, metadata, mount_id = _open_audit_cache_child(
                    current_fd, component, cache, current_path, deadline=deadline
                )
                os.close(current_fd)
                current_fd = child_fd
        return current_fd, metadata, mount_id
    except BaseException:
        os.close(current_fd)
        raise


_AUDIT_CACHE_PROGRESS_FIELDS = (
    "directories_visited",
    "entries_visited",
    "directories_verified",
    "entries_verified",
    "directories_finalized",
    "entries_finalized",
)


@dataclasses.dataclass
class _AuditSharedCacheProgress:
    """One child writer publishes aligned counters without kill-sensitive locks."""

    memory: mmap.mmap
    consumed_before: int
    metrics_before: Mapping[str, int]

    def _store(self, index: int, delta: int) -> None:
        if not 0 <= delta < 1 << 64:
            raise StateError("cache census progress delta is out of range")
        ctypes.c_uint64.from_buffer(self.memory, index * 8).value = delta

    def debit(self, consumed: int) -> None:
        self._store(0, consumed - self.consumed_before)

    def metric(self, field: str, value: int) -> None:
        self._store(
            _AUDIT_CACHE_PROGRESS_FIELDS.index(field) + 1,
            value - self.metrics_before[field],
        )

    def work_delta(self) -> int:
        return int(ctypes.c_uint64.from_buffer(self.memory, 0).value)

    def metric_values(self) -> dict[str, int]:
        return {
            field: self.metrics_before[field]
            + int(ctypes.c_uint64.from_buffer(self.memory, (index + 1) * 8).value)
            for index, field in enumerate(_AUDIT_CACHE_PROGRESS_FIELDS)
        }


class _AuditTrackedCacheRoot(dict[str, object]):
    """Publish completed observations before their child-local bookkeeping."""

    def __init__(
        self, root: Mapping[str, object], progress: _AuditSharedCacheProgress
    ) -> None:
        super().__init__(root)
        self.progress = progress

    def __setitem__(self, key: str, value: object) -> None:
        if key in _AUDIT_CACHE_PROGRESS_FIELDS:
            self.progress.metric(
                key, _as_int(value, f"cache census {key}", minimum=0)
            )
        super().__setitem__(key, value)


def _resume_audit_cache_root(
    cache: CacheDirectory,
    root_identity: Sequence[int],
    root: dict[str, object],
    *,
    budget: _AuditWorkBudget,
    deadline: float,
    finalize: bool = True,
) -> bool:
    """Isolate traversal while retaining work already done on every failure."""

    _audit_cache_check_deadline(deadline)
    if budget.remaining <= 0 or (not finalize and root.get("phase") == "finalize"):
        return False
    consumed_before = budget.consumed
    remaining_before = budget.remaining
    metrics_before = {
        field: _as_int(root[field], f"cache census {field}", minimum=0)
        for field in _AUDIT_CACHE_PROGRESS_FIELDS
    }
    root_keys = set(root)
    finalizing = finalize and root.get("phase") == "finalize"
    applied = False
    with mmap.mmap(-1, 8 * (1 + len(_AUDIT_CACHE_PROGRESS_FIELDS))) as memory:
        progress = _AuditSharedCacheProgress(memory, consumed_before, metrics_before)

        def work() -> Mapping[str, object]:
            child_root = _AuditTrackedCacheRoot(root, progress)
            child_budget = _AuditWorkBudget(
                budget.limit, consumed_before, on_debit=progress.debit
            )
            error: str | None = None
            try:
                complete = _resume_audit_cache_root_unbounded(
                    cache,
                    root_identity,
                    child_root,
                    budget=child_budget,
                    deadline=deadline,
                    finalize=finalize,
                )
            except _AuditCacheTimeout:
                raise
            except (OSError, Refusal, StateError) as exc:
                error = str(exc)[:4096]
                complete = False
                child_root["status"] = "partial"
            _audit_cache_check_deadline(deadline)
            return {
                "root": child_root,
                "complete": complete,
                "error": error,
                "work_consumed": child_budget.consumed,
            }

        try:
            packet = _run_audit_cache_worker(
                "traversal", work, deadline=deadline,
                result_limit=_AUDIT_CACHE_STATE_BYTES_LIMIT,
            )
            _exact_keys(
                packet,
                {"root", "complete", "error", "work_consumed"},
                set(),
                "cache census traversal result",
            )
            returned = dict(_as_mapping(packet["root"], "cache census traversal root"))
            if set(returned) != root_keys:
                raise StateError("cache census traversal returned unexpected root fields")
            phase = _as_str(returned["phase"], "cache census traversal root phase")
            status = _as_str(returned["status"], "cache census traversal root status")
            if (
                returned["path"] != str(cache.path)
                or returned["identity"] != list(root_identity)
                or phase not in {"measure", "verify", "finalize"}
                or status not in {"partial", "complete"}
                or type(packet["complete"]) is not bool
                or (status == "complete") != packet["complete"]
                or (packet["error"] is not None and not isinstance(packet["error"], str))
            ):
                raise StateError("cache census traversal returned inconsistent root identity or status")
            if _as_int(
                packet["work_consumed"], "cache census traversal work", minimum=0
            ) != consumed_before + progress.work_delta():
                raise StateError("cache census traversal work counters disagree")
            for field, value in progress.metric_values().items():
                if _as_int(returned[field], f"cache census {field}", minimum=0) != value:
                    raise StateError("cache census traversal observation counters disagree")
            _audit_cache_check_deadline(deadline)
            root.clear()
            root.update(returned)
            applied = True
            error_value = packet["error"]
            if isinstance(error_value, str):
                raise Refusal(error_value)
            return packet["complete"] is True
        finally:
            # This data survives SIGKILL and never depends on receiving the
            # potentially large resumable-root response from the child.
            delta = progress.work_delta()
            if delta > remaining_before:
                raise StateError("cache census traversal exceeded its shared work budget")
            budget.consumed = consumed_before + delta
            if budget.on_debit is not None:
                budget.on_debit(budget.consumed)
            root.update(progress.metric_values())
            if finalizing and not applied:
                # Keep the pre-call verified arrays staged. A later subject
                # sweep starts at zero, but current metrics still describe all
                # final observations completed before cancellation.
                root["finalize_index"] = root["directories_finalized"]
                root["finalize_entry_index"] = root["entries_finalized"]
                root["status"] = "partial"


def _resume_audit_cache_root_unbounded(
    cache: CacheDirectory,
    root_identity: Sequence[int],
    root: dict[str, object],
    *,
    budget: _AuditWorkBudget,
    deadline: float,
    finalize: bool = True,
) -> bool:
    """Advance one exact root without turning an incomplete count into zero."""

    while budget.remaining > 0 and time.monotonic() < deadline:
        phase = _as_str(root.get("phase"), "cache census phase")
        if phase not in {"measure", "verify", "finalize"}:
            raise StateError(f"cache census has invalid phase {phase!r}")
        if phase == "finalize":
            if not finalize:
                return False
            verified_directories = _as_list(
                root.get("verified_directories"),
                "cache census verified directories",
            )
            finalize_index = _as_int(
                root.get("finalize_index"),
                "cache census finalize index",
                minimum=0,
            )
            if finalize_index < len(verified_directories):
                verified_entry = _as_mapping(
                    verified_directories[finalize_index],
                    "cache census verified directory",
                )
                relative = _audit_cache_relative(
                    verified_entry.get("path"),
                    "cache census verified directory path",
                )
                expected_identity = tuple(
                    _as_int(
                        value,
                        "cache census verified directory identity",
                        minimum=0,
                    )
                    for value in _as_list(
                        verified_entry.get("identity"),
                        "cache census verified directory identity",
                    )
                )
                budget.debit()
                fd, metadata, _mount_id = _open_audit_cache_relative(
                    cache, root_identity, relative, deadline=deadline
                )
                os.close(fd)
                actual_identity = (
                    metadata.st_dev,
                    metadata.st_ino,
                    metadata.st_mtime_ns,
                    metadata.st_ctime_ns,
                )
                if expected_identity != actual_identity:
                    raise Refusal(
                        "cache census directory changed before final publication: "
                        f"{cache.path / relative}"
                    )
                root["finalize_index"] = finalize_index + 1
                root["directories_finalized"] = _as_int(
                    root.get("directories_finalized"),
                    "cache census directories finalized",
                    minimum=0,
                ) + 1
                if finalize_index + 1 == len(verified_directories) and not _as_list(
                    root.get("verified_entries"), "cache census verified entries"
                ):
                    root["status"] = "complete"
                    return True
                continue
            verified_entries = _as_list(
                root.get("verified_entries"), "cache census verified entries"
            )
            finalize_entry_index = _as_int(
                root.get("finalize_entry_index"),
                "cache census finalize entry index",
                minimum=0,
            )
            if finalize_entry_index >= len(verified_entries):
                if not verified_directories:
                    raise StateError("cache census finalization has no directories")
                root["status"] = "complete"
                return True
            verified_entry = _as_mapping(
                verified_entries[finalize_entry_index],
                "cache census verified entry",
            )
            relative = _audit_cache_relative(
                verified_entry.get("path"), "cache census verified entry path"
            )
            candidate = cache.path / relative
            parent_relative = Path(relative).parent.as_posix()
            if parent_relative == "":
                parent_relative = "."
            budget.debit()
            parent_fd, _parent_metadata, _mount_id = _open_audit_cache_relative(
                cache, root_identity, parent_relative, deadline=deadline
            )
            try:
                _audit_cache_check_deadline(deadline)
                metadata = os.stat(
                    Path(relative).name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise Refusal(
                    f"cache census entry changed before final publication: {candidate}: {exc}"
                ) from exc
            finally:
                os.close(parent_fd)
            expected_entry_identity = tuple(
                _as_int(value, "cache census verified entry identity", minimum=0)
                for value in _as_list(
                    verified_entry.get("identity"),
                    "cache census verified entry identity",
                )
            )
            actual_entry_identity = (
                metadata.st_dev,
                metadata.st_ino,
                metadata.st_mode,
                metadata.st_size,
                metadata.st_blocks,
                metadata.st_mtime_ns,
                metadata.st_ctime_ns,
            )
            if expected_entry_identity != actual_entry_identity:
                raise Refusal(
                    "cache census entry changed before final publication: "
                    f"{candidate}"
                )
            root["finalize_entry_index"] = finalize_entry_index + 1
            root["entries_finalized"] = _as_int(
                root.get("entries_finalized"),
                "cache census entries finalized",
                minimum=0,
            ) + 1
            if finalize_entry_index + 1 == len(verified_entries):
                root["status"] = "complete"
                return True
            continue
        bytes_field = "bytes" if phase == "measure" else "verify_bytes"
        entries_field = (
            "entries_visited" if phase == "measure" else "entries_verified"
        )
        directories_field = (
            "directories_visited"
            if phase == "measure"
            else "directories_verified"
        )
        current_raw = root.get("current")
        if current_raw is None:
            pending = _as_list(root.get("pending"), "cache census pending")
            if not pending:
                if phase == "measure":
                    root["phase"] = "verify"
                    root["verify_bytes"] = 0
                    root["entries_verified"] = 0
                    root["directories_verified"] = 0
                    root["verified_directories"] = []
                    root["verified_entries"] = []
                    root["finalize_index"] = 0
                    root["finalize_entry_index"] = 0
                    root["directories_finalized"] = 0
                    root["entries_finalized"] = 0
                    root["pending"] = ["."]
                    continue
                measured = _as_int(root.get("bytes"), "cache census bytes", minimum=0)
                verified = _as_int(
                    root.get("verify_bytes"),
                    "cache census verified bytes",
                    minimum=0,
                )
                if _as_int(
                    root.get("directories_verified"),
                    "cache census directories verified",
                    minimum=0,
                ) < 1:
                    raise StateError("cache census verification omitted its root directory")
                # The independent second pass is the freshest complete count.
                # Directory blocks may settle after creation and ordinary file
                # allocation may change between invocations; neither permits
                # publishing the older value.
                if measured != verified:
                    root["bytes"] = verified
                root["phase"] = "finalize"
                root["finalize_index"] = 0
                root["finalize_entry_index"] = 0
                root["directories_finalized"] = 0
                root["entries_finalized"] = 0
                continue
            relative = _audit_cache_relative(
                pending.pop(), "cache census pending path"
            )
            root["pending"] = pending
            fd, metadata, _mount_id = _open_audit_cache_relative(
                cache, root_identity, relative, deadline=deadline
            )
            os.close(fd)
            root[bytes_field] = _as_int(
                root.get(bytes_field), f"cache census {bytes_field}", minimum=0
            ) + metadata.st_blocks * 512
            root[directories_field] = _as_int(
                root.get(directories_field),
                f"cache census {directories_field}",
                minimum=0,
            ) + 1
            if phase == "verify":
                verified_directories = _as_list(
                    root.get("verified_directories"),
                    "cache census verified directories",
                )
                verified_directories.append(
                    {
                        "path": relative,
                        "identity": [
                            metadata.st_dev,
                            metadata.st_ino,
                            metadata.st_mtime_ns,
                            metadata.st_ctime_ns,
                        ],
                    }
                )
                root["verified_directories"] = verified_directories
            root["current"] = {
                "path": relative,
                "cursor": 0,
                "identity": [
                    metadata.st_dev,
                    metadata.st_ino,
                    metadata.st_mtime_ns,
                    metadata.st_ctime_ns,
                ],
            }
            current_raw = root["current"]
        current = dict(_as_mapping(current_raw, "cache census current"))
        relative = _as_str(current.get("path"), "cache census current.path")
        cursor = _as_int(current.get("cursor"), "cache census current.cursor")
        if cursor < 0:
            raise StateError("cache census current.cursor must be non-negative")
        expected_identity = tuple(
            _as_int(value, "cache census current identity")
            for value in _as_list(current.get("identity"), "cache census current.identity")
        )
        fd, metadata, _mount_id = _open_audit_cache_relative(
            cache, root_identity, relative, deadline=deadline
        )
        try:
            actual_identity = (
                metadata.st_dev,
                metadata.st_ino,
                metadata.st_mtime_ns,
                metadata.st_ctime_ns,
            )
            if actual_identity != expected_identity:
                raise Refusal(
                    f"cache census directory changed while resuming: {cache.path / relative}"
                )
            complete = False
            _audit_cache_check_deadline(deadline)
            with _audit_directory_stream(
                fd, cursor, str(cache.path / relative)
            ) as next_entry:
                while budget.remaining > 0 and time.monotonic() < deadline:
                    item = next_entry()
                    if item is None:
                        complete = True
                        break
                    name, cursor = item
                    current["cursor"] = cursor
                    budget.debit()
                    if name in {".", ".."}:
                        continue
                    if name == ".git":
                        raise Refusal(
                            f"cache directory contains nested Git metadata: "
                            f"{cache.path / relative / name}"
                        )
                    try:
                        _audit_cache_check_deadline(deadline)
                        child = os.stat(name, dir_fd=fd, follow_symlinks=False)
                    except FileNotFoundError:
                        continue
                    except OSError as exc:
                        raise Refusal(
                            f"cannot inspect cache entry "
                            f"{cache.path / relative / name}: {exc}"
                        ) from exc
                    root[entries_field] = _as_int(
                        root.get(entries_field),
                        f"cache census {entries_field}",
                        minimum=0,
                    ) + 1
                    child_relative = (
                        name if relative == "." else f"{relative}/{name}"
                    )
                    if stat.S_ISDIR(child.st_mode):
                        pending = _as_list(root.get("pending"), "cache census pending")
                        pending.append(child_relative)
                        root["pending"] = pending
                    else:
                        root[bytes_field] = _as_int(
                            root.get(bytes_field),
                            f"cache census {bytes_field}",
                            minimum=0,
                        ) + child.st_blocks * 512
                        if phase == "verify":
                            verified_entries = _as_list(
                                root.get("verified_entries"),
                                "cache census verified entries",
                            )
                            verified_entries.append(
                                {
                                    "path": child_relative,
                                    "identity": [
                                        child.st_dev,
                                        child.st_ino,
                                        child.st_mode,
                                        child.st_size,
                                        child.st_blocks,
                                        child.st_mtime_ns,
                                        child.st_ctime_ns,
                                    ],
                                }
                            )
                            root["verified_entries"] = verified_entries
            if not complete:
                root["current"] = dict(current)
                return False
            root["current"] = None
        finally:
            os.close(fd)
    return False


def _audit_cache_census_bound(
    config: Config,
    states: Sequence[ActiveState],
    planned: Mapping[str, Sequence[CacheDirectory]],
    errors: Mapping[str, str],
    *,
    state_path: Path,
    work_limit: int,
    wall_seconds: float,
    parent_fd: int,
    state_key: bytes,
) -> tuple[dict[str, _AuditCacheMeasurement], dict[str, int]]:
    registry_revision = _audit_registry_revision(states)
    stored: dict[str, object] = {
        "schema": _AUDIT_CACHE_CENSUS_SCHEMA,
        "registry_revision": registry_revision,
        "roots": {},
        "next_subject": None,
    }
    loaded = _read_audit_cache_state(
        state_path, parent_fd, state_key, registry_revision
    )
    if loaded is not None:
        stored = loaded
    previous_roots = dict(
        _as_mapping(stored.get("roots"), "audit cache census roots")
    )
    # Index authenticated progress for subjects whose turn may be deferred.
    # Retention is not validation or completion evidence: each selected root
    # must still bind and validate afresh before any of its contents are used.
    planned_paths = {str(cache.path) for caches in planned.values() for cache in caches}
    previous_keys_by_path: dict[str, list[str]] = {}
    roots: dict[str, object] = {}
    for key, value in previous_roots.items():
        if isinstance(value, Mapping):
            path = value.get("path")
            if isinstance(path, str) and path in planned_paths:
                roots[key] = value
                previous_keys_by_path.setdefault(path, []).append(key)
    deadline = time.monotonic() + wall_seconds
    budget = _AuditWorkBudget(work_limit)
    root_results: dict[str, _AuditCacheMeasurement] = {}
    root_keys: dict[str, list[str]] = {subject: [] for subject in planned}
    attempted_subjects: set[str] = set()
    root_items: dict[
        str,
        tuple[CacheDirectory, tuple[int, int, int, int, int], dict[str, object]],
    ] = {}
    subject_errors = dict(errors)
    directories = entries = verified = verified_entries = finalized = 0
    finalized_entries = 0

    ordered_subjects = sorted(planned)
    requested_next = stored.get("next_subject")
    if isinstance(requested_next, str) and requested_next in planned:
        start = ordered_subjects.index(requested_next)
        ordered_subjects = ordered_subjects[start:] + ordered_subjects[:start]

    binding_expired = (
        "cache census root binding exhausted the fixed wall allowance "
        f"of {wall_seconds:g} seconds; no cache total can be published "
        "within this allowance"
    )

    def bind_subject(subject: str) -> None:
        # Binding and structural validation belong to this subject's fair turn.
        # A costly peer must not consume every call before a cheap peer runs.
        caches = planned[subject]
        subject_keys = root_keys[subject]
        for cache in sorted(caches, key=lambda value: str(value.path)):
            if time.monotonic() >= deadline:
                subject_errors.setdefault(subject, binding_expired)
                break
            try:
                identity = _audit_cache_root_identity(config, cache, deadline=deadline)
            except (OSError, Refusal, StateError) as exc:
                subject_errors.setdefault(subject, str(exc))
                continue
            if time.monotonic() >= deadline:
                subject_errors.setdefault(subject, binding_expired)
                break
            for obsolete in previous_keys_by_path.pop(str(cache.path), ()):
                roots.pop(obsolete, None)
            if identity is None:
                continue
            key = _audit_cache_root_key(cache, identity)
            if key in root_items:
                subject_keys.append(key)
                continue
            root_raw = previous_roots.get(key)
            try:
                root = (
                    _validated_audit_cache_root(root_raw, cache, identity, deadline=deadline)
                    if isinstance(root_raw, Mapping)
                    else _new_audit_cache_root(cache, identity)
                )
            except StateError:
                root = _new_audit_cache_root(cache, identity)
            except Refusal as exc:
                subject_errors.setdefault(subject, str(exc))
                break
            if time.monotonic() >= deadline:
                subject_errors.setdefault(subject, binding_expired)
                break
            subject_keys.append(key)
            if root.get("phase") == "finalize" and root.get("status") != "complete":
                # The final identity sweep must occur wholly in the invocation
                # that publishes completion; never resume halfway through it.
                root["finalize_index"] = 0
                root["finalize_entry_index"] = 0
                root["directories_finalized"] = 0
                root["entries_finalized"] = 0
            if root.get("status") == "complete":
                # Persisted completion never establishes current deletion
                # evidence by itself. Re-run the complete recursive verifier,
                # including entry names and allocated blocks, on this
                # invocation before publishing the cached measurement.
                root["status"] = "partial"
                root["phase"] = "verify"
                root["verify_bytes"] = 0
                root["entries_verified"] = 0
                root["directories_verified"] = 0
                root["verified_directories"] = []
                root["verified_entries"] = []
                root["finalize_index"] = 0
                root["finalize_entry_index"] = 0
                root["directories_finalized"] = 0
                root["entries_finalized"] = 0
                root["pending"] = ["."]
                root["current"] = None
            roots[key] = root
            root_results[key] = _AuditCacheMeasurement(None, "partial")
            root_items[key] = (cache, identity, root)

    def advance(key: str, *, finalize: bool) -> None:
        nonlocal directories, entries, verified, verified_entries, finalized
        nonlocal finalized_entries
        cache, identity, root = root_items[key]
        before_dirs = _as_int(root.get("directories_visited"), "cache census directories")
        before_entries = _as_int(root.get("entries_visited"), "cache census entries")
        before_verified = _as_int(
            root.get("directories_verified"),
            "cache census directories verified",
        )
        before_verified_entries = _as_int(
            root.get("entries_verified"),
            "cache census entries verified",
        )
        before_finalized = _as_int(
            root.get("directories_finalized"),
            "cache census directories finalized",
        )
        before_finalized_entries = _as_int(
            root.get("entries_finalized"),
            "cache census entries finalized",
        )
        try:
            if root.get("status") != "complete":
                _resume_audit_cache_root(
                    cache,
                    identity,
                    root,
                    budget=budget,
                    deadline=deadline,
                    finalize=finalize,
                )
            if root.get("status") == "complete":
                root_results[key] = _AuditCacheMeasurement(
                    _as_int(root.get("bytes"), "cache census bytes"), "complete"
                )
            else:
                root_results[key] = _AuditCacheMeasurement(None, "partial")
        except _AuditCacheTimeout:
            if finalize:
                # Retain only the pre-call staged identities. The scheduler
                # restarts the entire subject's final sweep and distinguishes
                # an opportunistic interruption from a full fresh timeout.
                root["status"] = "partial"
                root_results[key] = _AuditCacheMeasurement(None, "partial")
            else:
                roots.pop(key, None)
                root_results[key] = _AuditCacheMeasurement(
                    None, "error",
                    "cache census traversal exhausted the fixed wall allowance "
                    f"of {wall_seconds:g} seconds; no cache total can be published "
                    "within this allowance",
                )
        except (OSError, Refusal, StateError) as exc:
            roots.pop(key, None)
            root_results[key] = _AuditCacheMeasurement(None, "error", str(exc))
        finally:
            # These deltas are evidence about work already performed. Preserve
            # them even when the root itself is refused and its progress is
            # deliberately discarded.
            directories += _as_int(
                root.get("directories_visited"), "cache census directories"
            ) - before_dirs
            entries += _as_int(
                root.get("entries_visited"), "cache census entries"
            ) - before_entries
            verified += _as_int(
                root.get("directories_verified"),
                "cache census directories verified",
            ) - before_verified
            verified_entries += _as_int(
                root.get("entries_verified"),
                "cache census entries verified",
            ) - before_verified_entries
            finalized += _as_int(
                root.get("directories_finalized"),
                "cache census directories finalized",
            ) - before_finalized
            finalized_entries += _as_int(
                root.get("entries_finalized"),
                "cache census entries finalized",
            ) - before_finalized_entries

    # Progress belongs to a lifecycle subject, which may contain several roots.
    # Stage every root before reserving one fresh, indivisible publication sweep.
    # No completed subset may force its peers back through verification forever.
    next_subject = ordered_subjects[0] if ordered_subjects else None
    for index, subject in enumerate(ordered_subjects):
        if budget.remaining <= 0 or time.monotonic() >= deadline:
            break
        next_subject = ordered_subjects[(index + 1) % len(ordered_subjects)]
        if subject in subject_errors or not planned[subject]:
            continue
        attempted_subjects.add(subject)
        bind_subject(subject)
        keys = root_keys[subject]
        if subject in subject_errors or not keys:
            continue
        for key in keys:
            if root_items[key][2]["phase"] != "finalize":
                advance(key, finalize=False)
            if root_results[key].error is not None:
                break
        if any(root_results[key].error is not None for key in keys):
            continue
        if any(root_items[key][2]["phase"] != "finalize" for key in keys):
            continue
        required_work = sum(
            len(_as_list(root_items[key][2][field], f"cache census {field}"))
            for key in keys
            for field in ("verified_directories", "verified_entries")
        )
        if required_work > work_limit:
            subject_errors[subject] = (
                f"fresh cache finalization requires {required_work} work units for "
                f"this subject, exceeding the fixed allowance of {work_limit}; "
                "no cache total can be published within this allowance"
            )
            continue
        if required_work > budget.remaining:
            # Reserve a full turn rather than retrying behind other subjects.
            next_subject = subject
            break
        full_attempt = budget.consumed == 0
        for key in keys:
            advance(key, finalize=True)
            if root_results[key].status != "complete":
                break
        completed = (
            all(root_results[key].status == "complete" for key in keys)
            and time.monotonic() < deadline
        )
        if not completed:
            # Even roots which passed are only staged until this subject's whole
            # sweep passes together. Their finalization is restarted next time.
            for key in keys:
                root_items[key][2]["status"] = "partial"
                if root_results[key].error is None:
                    root_results[key] = _AuditCacheMeasurement(None, "partial")
            if any(root_results[key].error is not None for key in keys):
                continue
            if full_attempt:
                subject_errors[subject] = (
                    "fresh cache finalization exceeded the fixed wall allowance "
                    f"of {wall_seconds:g} seconds; no cache total can be published "
                    "within this allowance"
                )
            else:
                next_subject = subject
                break
    stored = {
        "schema": _AUDIT_CACHE_CENSUS_SCHEMA,
        "registry_revision": registry_revision,
        "roots": roots,
        "next_subject": next_subject,
    }
    try:
        _write_audit_cache_state(state_path, stored, state_key, parent_fd)
    except (OSError, Refusal) as exc:
        state_error = f"cannot persist audit cache census: {exc}"
        for subject, caches in planned.items():
            if caches:
                subject_errors.setdefault(subject, state_error)
    results: dict[str, _AuditCacheMeasurement] = {}
    for subject in planned:
        error = subject_errors.get(subject)
        if error is not None:
            results[subject] = _AuditCacheMeasurement(None, "error", error)
            continue
        if planned[subject] and subject not in attempted_subjects:
            results[subject] = _AuditCacheMeasurement(None, "partial")
            continue
        measurements = [root_results[key] for key in root_keys[subject]]
        root_error = next((item.error for item in measurements if item.error), None)
        if root_error is not None:
            results[subject] = _AuditCacheMeasurement(None, "error", root_error)
        elif any(item.status != "complete" for item in measurements):
            results[subject] = _AuditCacheMeasurement(None, "partial")
        else:
            results[subject] = _AuditCacheMeasurement(
                sum(item.bytes or 0 for item in measurements), "complete"
            )
    return results, {
        "cache_roots": sum(len(caches) for caches in planned.values()),
        "directories_visited": directories,
        "directories_verified": verified,
        "directories_finalized": finalized,
        "entries_visited": entries,
        "entries_verified": verified_entries,
        "entries_finalized": finalized_entries,
        "subjects": len(planned),
        "work_consumed": budget.consumed,
        "work_limit": work_limit,
        "work_remaining": budget.remaining,
    }


def _unavailable_audit_cache_census(
    planned: Mapping[str, Sequence[CacheDirectory]],
    errors: Mapping[str, str],
    *,
    work_limit: int,
    detail: str | None,
) -> tuple[dict[str, _AuditCacheMeasurement], dict[str, int]]:
    results: dict[str, _AuditCacheMeasurement] = {}
    for subject, caches in planned.items():
        error = errors.get(subject) or (detail if caches else None)
        if error is not None:
            results[subject] = _AuditCacheMeasurement(None, "error", error)
        else:
            results[subject] = _AuditCacheMeasurement(0, "complete")
    return results, {
        "cache_roots": sum(len(caches) for caches in planned.values()),
        "directories_visited": 0,
        "directories_verified": 0,
        "directories_finalized": 0,
        "entries_visited": 0,
        "entries_verified": 0,
        "entries_finalized": 0,
        "subjects": len(planned),
        "work_consumed": 0,
        "work_limit": work_limit,
        "work_remaining": work_limit,
    }


def _audit_cache_census(
    config: Config,
    states: Sequence[ActiveState],
    planned: Mapping[str, Sequence[CacheDirectory]],
    errors: Mapping[str, str],
    *,
    state_path: Path | None,
    work_limit: int,
    wall_seconds: float,
    storage_error: str | None = None,
) -> tuple[dict[str, _AuditCacheMeasurement], dict[str, int]]:
    if storage_error is not None or not any(planned.values()):
        return _unavailable_audit_cache_census(
            planned, errors, work_limit=work_limit, detail=storage_error
        )
    if state_path is None:
        raise StateError("cache census storage is absent despite planned cache work")
    parent_fd: int | None = None
    try:
        try:
            parent_fd = _open_audit_cache_state_parent(config, state_path)
            state_key = _audit_cache_state_key(state_path, parent_fd)
        except (OSError, Refusal) as exc:
            detail = f"cannot establish authenticated audit cache census state: {exc}"
            return _unavailable_audit_cache_census(
                planned, errors, work_limit=work_limit, detail=detail
            )
        assert parent_fd is not None
        return _audit_cache_census_bound(
            config,
            states,
            planned,
            errors,
            state_path=state_path,
            work_limit=work_limit,
            wall_seconds=wall_seconds,
            parent_fd=parent_fd,
            state_key=state_key,
        )
    finally:
        if parent_fd is not None:
            os.close(parent_fd)


def _clear_open_directory(
    directory_fd: int,
    path: Path,
    device: int,
    mount_id: int,
    *,
    allow_git_metadata: bool = False,
    disposable_git: Mapping[Path, tuple[int, int]] | None = None,
) -> int:
    metadata = os.fstat(directory_fd)
    if metadata.st_dev != device:
        raise Refusal(f"cache path crossed onto another filesystem: {path}")
    if _fd_mount_id(directory_fd, str(path)) != mount_id:
        raise Refusal(f"cache path crossed a mount point: {path}")
    writable = stat.S_IWUSR | stat.S_IXUSR
    if metadata.st_uid == os.geteuid() and metadata.st_mode & writable != writable:
        # Build scripts and Go's module cache leave read-only directories
        # (mode 0555) whose entries cannot be unlinked until the owner restores
        # write permission. The descriptor is the one already identity-checked
        # above, so this changes only the directory being emptied.
        try:
            os.fchmod(directory_fd, stat.S_IMODE(metadata.st_mode) | writable)
        except OSError as exc:
            raise Refusal(f"cannot make cache directory writable: {path}: {exc}") from exc
    total = metadata.st_blocks * 512
    names = _directory_names(directory_fd, path)
    for name in names:
        if name == ".git" and not allow_git_metadata:
            _assert_judged_git_metadata(directory_fd, path, name, disposable_git)
        try:
            child = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise Refusal(f"cannot inspect cache entry {path / name}: {exc}") from exc
        if stat.S_ISDIR(child.st_mode):
            flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
            try:
                child_fd = os.open(name, flags, dir_fd=directory_fd)
            except OSError as exc:
                raise Refusal(f"cache directory changed during cleanup: {path / name}: {exc}") from exc
            try:
                opened = os.fstat(child_fd)
                if (opened.st_dev, opened.st_ino) != (child.st_dev, child.st_ino):
                    raise Refusal(f"cache directory changed during cleanup: {path / name}")
                if _fd_mount_id(child_fd, str(path / name)) != mount_id:
                    raise Refusal(f"cache path crossed a mount point: {path / name}")
                total += _clear_open_directory(
                    child_fd,
                    path / name,
                    device,
                    mount_id,
                    allow_git_metadata=allow_git_metadata,
                    disposable_git=disposable_git,
                )
            finally:
                os.close(child_fd)
            try:
                current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            if (
                not stat.S_ISDIR(current.st_mode)
                or (current.st_dev, current.st_ino) != (child.st_dev, child.st_ino)
            ):
                raise Refusal(f"cache directory changed during cleanup: {path / name}")
            try:
                os.rmdir(name, dir_fd=directory_fd)
            except OSError as exc:
                raise Refusal(f"cannot remove cache directory {path / name}: {exc}") from exc
        else:
            try:
                os.unlink(name, dir_fd=directory_fd)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise Refusal(f"cannot remove cache entry {path / name}: {exc}") from exc
            total += child.st_blocks * 512
    if _directory_names(directory_fd, path):
        raise Refusal(f"cache directory changed while it was being cleaned: {path}")
    return total


def _remove_cache_directory(
    config: Config,
    cache: CacheDirectory,
    *,
    allow_git_metadata: bool = False,
    disposable_git: Mapping[Path, tuple[int, int]] | None = None,
    expected_identity: tuple[int, int, int] | None = None,
    expected_stable_identity: _PrivateCleanupIdentity | None = None,
    expected_absent_path: Path | None = None,
) -> int:
    path = cache.path
    opened = _open_cache_directory(
        config, cache, expected_absent_path=expected_absent_path
    )
    if opened is None:
        if expected_identity is not None or expected_stable_identity is not None:
            raise Refusal(f"cache directory disappeared before cleanup: {path}")
        return 0
    parent_fd, cache_fd, name = opened
    try:
        original, _mount_id, size = _clear_bound_cache_directory(
            cache_fd,
            path,
            allow_git_metadata=allow_git_metadata,
            disposable_git=disposable_git,
            expected_identity=expected_identity,
            expected_stable_identity=expected_stable_identity,
        )
        if expected_absent_path is not None:
            _assert_parent_entry_absent(
                parent_fd,
                cache.checkout_root,
                expected_absent_path,
                "canonical validation path",
            )
        try:
            current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return size
        if (
            not stat.S_ISDIR(current.st_mode)
            or (current.st_dev, current.st_ino) != (original.st_dev, original.st_ino)
        ):
            raise Refusal(f"cache directory changed before final removal: {path}")
        try:
            os.rmdir(name, dir_fd=parent_fd)
            os.fsync(parent_fd)
        except OSError as exc:
            raise Refusal(f"cannot remove configured cache directory {path}: {exc}") from exc
        return size
    finally:
        os.close(cache_fd)
        os.close(parent_fd)


def _clear_bound_cache_directory(
    directory_fd: int,
    path: Path,
    *,
    allow_git_metadata: bool,
    expected_identity: tuple[int, int, int] | None,
    expected_stable_identity: _PrivateCleanupIdentity | None,
    disposable_git: Mapping[Path, tuple[int, int]] | None = None,
) -> tuple[os.stat_result, int, int]:
    """Validate and empty an already-open cache directory without reopening it."""

    original = os.fstat(directory_fd)
    mount_id = _fd_mount_id(directory_fd, str(path))
    if expected_identity is not None and expected_identity != (
        original.st_dev,
        original.st_ino,
        mount_id,
    ):
        raise Refusal(f"cache directory identity changed before cleanup: {path}")
    if (
        expected_stable_identity is not None
        and _fd_private_cleanup_identity(directory_fd, str(path))
        != expected_stable_identity
    ):
        raise Refusal(
            f"cache directory stable file-handle identity changed before cleanup: {path}"
        )
    # Complete a read-only traversal before deletion begins. The destructive
    # traversal repeats every identity check so replacements still fail closed.
    _allocated_open_directory(
        directory_fd,
        path,
        original.st_dev,
        mount_id,
        allow_git_metadata=allow_git_metadata,
        disposable_git=disposable_git,
    )
    size = _clear_open_directory(
        directory_fd,
        path,
        original.st_dev,
        mount_id,
        allow_git_metadata=allow_git_metadata,
        disposable_git=disposable_git,
    )
    return original, mount_id, size


# Nested Git repositories inside an agent slot's configured caches.
#
# A cache traversal refuses every entry named ``.git`` unless the caller
# allows all of them (a completed validation) or has judged that exact entry
# disposable here first.  Judgment happens only on the destructive step of an
# otherwise authorized agent removal, before any cache is deleted, and asks Git
# itself: no path name is ever treated as evidence.
_NESTED_GIT_COMMAND_SECONDS = 120.0
# One allowance of time spent inside the Git commands a single removal runs to
# judge and re-judge nested repositories, so a slot full of clones cannot hold
# the lock for hours: 120 s per command, 900 s in total.  Deleting caches and
# every other step between commands is not charged.
_NESTED_GIT_REMOVAL_SECONDS = 900.0
_NESTED_GIT_IGNORED_SAMPLE = 20
_NESTED_GIT_OPERATION_MARKERS = (
    ("MERGE_HEAD", "a merge"),
    ("CHERRY_PICK_HEAD", "a cherry-pick"),
    ("REVERT_HEAD", "a revert"),
    ("rebase-merge", "a rebase"),
    ("rebase-apply", "a rebase or am"),
    ("BISECT_LOG", "a bisect"),
    ("BISECT_START", "a bisect"),
    ("sequencer", "a sequencer operation"),
)
_NESTED_GIT_EVIDENCE_KEYS = frozenset(
    {"checkout", "path", "head", "remote_ref", "ignored_entries", "ignored_sample"}
)
# Recorded beside the judged repositories in the slot-removed event: what the
# judgment did not cover, so the evidence is not read as more than it is.
_NESTED_GIT_SCOPE = (
    "Only directories named .git were judged. Everything else in the cache was "
    "deleted as ordinary cache files without inspection, including a bare Git "
    "repository under any other name and a filesystem image with repositories "
    "inside it. A judged repository was deleted with material no ref, reflog or "
    "commit reaches: dangling blobs and trees, hooks, .git/info files other than "
    "exclude, and Git LFS objects."
)
# Remote settings that route a transfer through a program this check cannot
# inspect, so a remote-tracking ref may not reflect what the remote's URL holds.
_NESTED_GIT_REMOTE_PROGRAMS = (
    ("vcs", "a remote helper"),
    ("uploadpack", "an upload-pack program"),
    ("receivepack", "a receive-pack program"),
)


@dataclasses.dataclass
class _NestedGitBudget:
    """One removal-wide allowance of time spent inside nested-judgment Git commands.

    Only time inside those commands is charged, so a removal that deletes a
    large cache between two judgments does not spend the allowance deleting.
    """

    total_seconds: float = _NESTED_GIT_REMOVAL_SECONDS
    spent_seconds: float = dataclasses.field(init=False, default=0.0)

    def command_seconds(self) -> float:
        """Return the bound for the next Git command, or zero once the allowance is spent."""

        return max(
            0.0,
            min(_NESTED_GIT_COMMAND_SECONDS, self.total_seconds - self.spent_seconds),
        )

    def charge(self, seconds: float) -> None:
        """Charge the wall time one Git command took."""

        self.spent_seconds += max(0.0, seconds)


@dataclasses.dataclass(frozen=True)
class _DisposableNestedRepository:
    """One nested repository holding no commit or change that exists only there."""

    path: Path
    identity: tuple[int, int]
    head: str | None
    remote_ref: str | None
    ignored_entries: int
    ignored_sample: tuple[str, ...]


def _assert_judged_git_metadata(
    directory_fd: int,
    path: Path,
    name: str,
    disposable_git: Mapping[Path, tuple[int, int]] | None,
) -> None:
    """Refuse a cache's ``.git`` entry unless it is the exact one judged disposable."""

    entry = path / name
    expected = None if disposable_git is None else disposable_git.get(entry)
    if expected is None:
        raise Refusal(f"cache directory contains nested Git metadata: {entry}")
    try:
        observed = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except OSError as exc:
        raise Refusal(
            f"cannot inspect nested Git metadata judged disposable: {entry}: {exc}"
        ) from exc
    if not stat.S_ISDIR(observed.st_mode) or (
        observed.st_dev,
        observed.st_ino,
    ) != expected:
        raise Refusal(
            f"nested Git repository changed after it was judged disposable: {entry}"
        )


def _nested_git_metadata_paths(config: Config, cache: CacheDirectory) -> list[Path]:
    """List every ``.git`` entry a removal of ``cache`` would reach, read-only."""

    opened = _open_cache_directory(config, cache)
    if opened is None:
        return []
    parent_fd, cache_fd, _name = opened
    try:
        found: list[Path] = []
        _allocated_open_directory(
            cache_fd,
            cache.path,
            os.fstat(cache_fd).st_dev,
            _fd_mount_id(cache_fd, str(cache.path)),
            git_metadata_found=found,
        )
        return found
    finally:
        os.close(cache_fd)
        os.close(parent_fd)


def _local_remote_path(url: str, base: Path) -> Path | None:
    """Return the filesystem path a local remote URL names, or None for a network URL."""

    if url.startswith("file://"):
        rest = url[len("file://") :]
        _authority, separator, remainder = rest.partition("/")
        return Path("/" + urllib.parse.unquote(remainder)) if separator else Path("/")
    if "://" in url:
        return None
    colon = url.find(":")
    slash = url.find("/")
    if colon != -1 and (slash == -1 or colon < slash):
        return None
    return Path(url) if os.path.isabs(url) else base / url


def _nested_remote_exclusion(
    url: str, work_tree: Path, resolved_roots: Sequence[Path], *, label: str = "URL"
) -> str | None:
    """Say why one remote URL proves nothing, or return None when it counts.

    A network URL counts.  A local path counts only when it exists and lies
    outside every root this removal deletes.  Nothing here raises: a path that
    cannot be resolved (a symbolic-link loop, a name too long, a permission
    error) is itself the reason the remote does not count.  ``label`` names
    which of the remote's URLs this is (its URL, its push URL, or one of them
    as the invoking user's Git configuration rewrites it).
    """

    if "::" in url:
        return f"its {label} names a remote helper, whose source this check cannot locate"
    try:
        local = _local_remote_path(url, work_tree)
        if local is None:
            return None
        target = local.resolve(strict=False)
        # Checked first: while the slot is fenced its canonical paths no
        # longer exist, and "inside this removal" is the more exact reason.
        if any(target == root or target.is_relative_to(root) for root in resolved_roots):
            return f"its {label} is a local path inside this removal"
        if not target.exists():
            return f"its {label} is a local path that does not exist"
    except (OSError, RuntimeError, ValueError) as exc:
        return (
            f"its {label} is a local path that cannot be resolved "
            f"({type(exc).__name__}: {exc})"
        )
    return None


def _qualified_fetch_destination(
    destination: str, *, expand_patterns: bool
) -> str | None:
    """Spell one fetch refspec destination as the ref Git writes, or None if it writes none.

    For a destination without a wildcard Git does what remote.c get_local_ref
    does: a name under refs/ is kept, heads/, tags/ and remotes/ gain refs/,
    and any other name becomes refs/heads/<name>, so ``remotes/origin/main``
    writes refs/remotes/origin/main.  Git ignores a wildcard destination
    outside refs/ as a "funny ref"; ``expand_patterns`` expands it the same
    way anyway, which over-approximates what it could write.
    """

    if not destination:
        return None
    if destination.startswith("refs/"):
        return destination
    if "*" in destination and not expand_patterns:
        return None
    if destination.startswith(("heads/", "tags/", "remotes/")):
        return "refs/" + destination
    return "refs/heads/" + destination


def _refspec_destinations(
    refspecs: Sequence[str], *, over_approximate: bool = False
) -> list[str]:
    """Return the local refs that positive fetch refspecs write, fully qualified.

    With ``over_approximate`` a wildcard destination outside refs/ is expanded
    too, for remotes whose every possible write must be accounted for.
    """

    destinations: list[str] = []
    for refspec in refspecs:
        body = refspec[1:] if refspec.startswith("+") else refspec
        if body.startswith("^"):
            continue
        _source, separator, destination = body.partition(":")
        if not separator:
            continue
        qualified = _qualified_fetch_destination(
            destination, expand_patterns=over_approximate
        )
        if qualified is not None:
            destinations.append(qualified)
    return destinations


def _refspec_destination_matches(destination: str, refname: str) -> bool:
    """Match ``refname`` against one refspec destination the way ``git fetch`` does."""

    if "*" not in destination:
        return refname == destination
    prefix, _star, suffix = destination.partition("*")
    return (
        len(refname) >= len(prefix) + len(suffix)
        and refname.startswith(prefix)
        and refname.endswith(suffix)
    )


def _judge_nested_git_repository(
    dotgit: Path,
    removed_roots: Sequence[Path],
    *,
    display: Path | None = None,
    budget: _NestedGitBudget | None = None,
) -> _DisposableNestedRepository:
    """Judge one nested repository; every failure, of any exception type, refuses.

    A removal rolls its path fence back only on a Refusal, so an OSError or
    RuntimeError escaping judgment would leave the slot fenced and the finish
    journal in place.  Converting here keeps every judgment failure on the
    rollback path.
    """

    try:
        return _judge_nested_git_repository_unchecked(
            dotgit,
            removed_roots,
            display=display,
            budget=_NestedGitBudget() if budget is None else budget,
        )
    except Refusal:
        raise
    except Exception as exc:
        raise Refusal(
            f"cache directory contains nested Git metadata: {display or dotgit}: "
            f"not provably disposable: judgment failed: {type(exc).__name__}: {exc}"
        ) from exc


def _judge_nested_git_repository_unchecked(
    dotgit: Path,
    removed_roots: Sequence[Path],
    *,
    display: Path | None,
    budget: _NestedGitBudget,
) -> _DisposableNestedRepository:
    """Prove that the repository at ``dotgit`` holds nothing that exists only here.

    The proof requires a well-formed, non-linked, non-bare repository whose
    ``.git`` is a directory with no linked worktrees, no submodule
    repositories and no legacy .git/remotes or .git/branches files, that
    borrows no objects through alternates and whose config sets no include,
    content filter, core.worktree or url.* rewrite; an index
    with no gitlink and no entry hidden by assume-unchanged or skip-worktree;
    a worktree with no uncommitted or untracked non-ignored change, no ignore
    rule in .git/info/exclude and no .gitignore that ignores itself; no stash
    and no operation in progress; and every commit object in the repository,
    whether named by HEAD, a branch, a tag, a pseudo-ref, a reflog entry or
    nothing at all (a dropped stash, a deleted branch), reachable from a
    counted remote-tracking ref.  A ref counts only when it is not a symbolic
    ref and a fetch refspec of a counted remote, and of no uncounted one, maps
    to it; an uncounted remote's destinations are qualified the way Git
    qualifies them and cover every namespace, so neither ``remotes/origin/main``
    nor ``refs/*:refs/*`` lets it write a counted ref unnoticed.  A remote
    counts only when it has a URL, its name has no '/', it routes no transfer
    through a remote helper, upload-pack or receive-pack program, and every URL
    and push URL, as configured and as the invoking user's Git configuration
    rewrites them (insteadOf, pushInsteadOf), is a network URL or an existing
    local path outside ``removed_roots``: ``git push`` sends commits to the
    push URL and then updates the remote-tracking ref as if they had reached
    the URL, and a clone of a sibling deleted by the same removal, or of a
    path that no longer exists, proves nothing.  Git runs with no global or
    system configuration, no grafts, replace refs or commit-graph, no optional
    locks, no fsmonitor, no transport, and a bound on every command drawn from
    ``budget``; only the commands that read remote settings and report
    effective URLs (``git config`` and ``git remote get-url``) see the
    invoking user's configuration, and neither runs a program.  Anything else refuses and names the condition that failed,
    reporting the entry as ``display`` (its canonical path while the slot is
    fenced).
    """

    def refuse(condition: str) -> Refusal:
        return Refusal(
            f"cache directory contains nested Git metadata: {display or dotgit}: "
            f"not provably disposable: {condition}"
        )

    try:
        metadata = os.lstat(dotgit)
    except OSError as exc:
        raise refuse(f"cannot inspect .git: {exc}") from exc
    if stat.S_ISLNK(metadata.st_mode):
        raise refuse(".git is a symbolic link, not a repository directory")
    if stat.S_ISREG(metadata.st_mode):
        raise refuse(
            ".git is a file, not a repository directory "
            "(a linked worktree or submodule pointer)"
        )
    if not stat.S_ISDIR(metadata.st_mode):
        raise refuse(".git is not a directory")
    work_tree = dotgit.parent
    env = {key: value for key, value in os.environ.items() if not key.startswith("GIT_")}
    env.update(
        {
            "LC_ALL": "C",
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": "/dev/null",
            "GIT_CONFIG_SYSTEM": "/dev/null",
            # Grafts rewrite parentage, so a graft could make a local-only
            # commit look like an ancestor of a remote-tracking ref.
            "GIT_GRAFT_FILE": "/dev/null",
            "GIT_NO_REPLACE_OBJECTS": "1",
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_TERMINAL_PROMPT": "0",
            "GIT_NO_LAZY_FETCH": "1",
            "GIT_ATTR_NOSYSTEM": "1",
        }
    )
    # Remote settings and effective URLs are read under the invoking user's
    # global and system configuration, the configuration a push or fetch in
    # this repository would have used, so a remote defined or rewritten there
    # is judged by where its transfers actually went.
    user_env = {
        key: value
        for key, value in os.environ.items()
        if not key.startswith("GIT_") or key.startswith("GIT_CONFIG_")
    }
    user_env.update(
        {
            "LC_ALL": "C",
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_TERMINAL_PROMPT": "0",
            "GIT_NO_LAZY_FETCH": "1",
        }
    )

    def run(
        args: Sequence[str],
        *,
        work: bool = False,
        stdin: bytes | None = None,
        user_config: bool = False,
    ) -> subprocess.CompletedProcess[bytes]:
        seconds = budget.command_seconds()
        if seconds <= 0:
            raise refuse(
                f"nested Git judgment spent its {budget.total_seconds:g}-second "
                f"allowance for this removal before git {' '.join(args)}"
            )
        item_what = f"git {' '.join(args[:3])} in {dotgit}"
        item_seconds = _item_seconds_left(item_what)
        limited_by_item = item_seconds is not None and item_seconds < seconds
        if item_seconds is not None and limited_by_item:
            seconds = item_seconds
        command = [
            "git",
            "--no-pager",
            "--no-replace-objects",
            "-c",
            "core.useReplaceRefs=false",
            "-c",
            "core.commitGraph=false",
            "-c",
            "advice.graftFileDeprecated=false",
            "-c",
            "core.fsmonitor=false",
            "-c",
            "core.untrackedCache=false",
            "-c",
            "core.excludesFile=/dev/null",
            "-c",
            "core.ignoreStat=false",
            "-c",
            "protocol.allow=never",
            f"--git-dir={dotgit}",
            *((f"--work-tree={work_tree}",) if work else ()),
            *args,
        ]
        started = time.monotonic()
        try:
            return subprocess.run(
                command,
                input=stdin,
                capture_output=True,
                check=False,
                env=user_env if user_config else env,
                cwd="/",
                timeout=seconds,
            )
        except subprocess.TimeoutExpired as exc:
            if limited_by_item:
                raise _item_budget_refusal(item_what) from exc
            raise refuse(
                f"git {' '.join(args)} did not finish within {seconds:g} seconds"
            ) from exc
        except OSError as exc:
            raise refuse(f"cannot execute Git: {exc}") from exc
        finally:
            budget.charge(time.monotonic() - started)

    def detail(completed: subprocess.CompletedProcess[bytes]) -> str:
        text = (completed.stderr or completed.stdout).decode(errors="replace").strip()
        return text.splitlines()[0][:300] if text else f"exit {completed.returncode}"

    def output(args: Sequence[str], *, work: bool = False, stdin: bytes | None = None) -> str:
        completed = run(args, work=work, stdin=stdin)
        if completed.returncode != 0:
            raise refuse(f"git {' '.join(args)} failed: {detail(completed)}")
        return completed.stdout.decode(errors="surrogateescape")

    def read_optional(relative: str) -> bytes | None:
        try:
            return (dotgit / relative).read_bytes()
        except FileNotFoundError:
            return None
        except OSError as exc:
            raise refuse(f"cannot inspect .git/{relative}: {exc}") from exc

    # (a) A well-formed repository whose Git directory is this .git itself.
    located = run(["rev-parse", "--path-format=absolute", "--git-dir", "--git-common-dir"])
    if located.returncode != 0:
        raise refuse(f"not a well-formed Git repository: {detail(located)}")
    for reported in located.stdout.decode(errors="surrogateescape").splitlines():
        try:
            same = os.path.samefile(reported, dotgit)
        except OSError:
            same = False
        if not same:
            raise refuse(
                f"Git reports repository directory {reported}, not this .git directory"
            )
    for config_name in ("config", "config.worktree"):
        config_path = dotgit / config_name
        if config_name != "config" and not config_path.exists():
            continue
        names = output(["config", "--file", str(config_path), "--null", "--list", "--name-only"])
        for key in sorted({item for item in names.split("\0") if item}):
            lowered = key.lower()
            if lowered.startswith(("include.", "includeif.")):
                raise refuse(
                    f"repository config sets {key}, which could load configuration "
                    "this check does not inspect"
                )
            if lowered.startswith("filter."):
                raise refuse(
                    f"repository config defines content filter {key}, which Git "
                    "status could execute"
                )
            if lowered == "core.worktree":
                raise refuse(
                    "repository config sets core.worktree, so its worktree may lie "
                    "outside this cache"
                )
            if lowered.startswith("url."):
                raise refuse(
                    f"repository config sets {key}, which rewrites remote URLs, so a "
                    "remote's configured URL may not be where its refs came from"
                )
        bare = run(["config", "--file", str(config_path), "--type=bool", "--get", "core.bare"])
        if bare.returncode == 0 and bare.stdout.strip() == b"true":
            raise refuse(
                ".git is configured as a bare repository (core.bare=true), so Git "
                "cannot report the files around it"
            )
        if bare.returncode not in {0, 1}:
            raise refuse(f"cannot read core.bare: {detail(bare)}")
    for subdirectory, what in (
        ("worktrees", "registered linked worktrees"),
        ("modules", "submodule repositories under .git/modules"),
        # Fetch and push still read remotes from these legacy files, which the
        # remote configuration below does not include.
        ("remotes", "remotes defined in legacy .git/remotes files, which this check does not read"),
        ("branches", "remotes defined in legacy .git/branches files, which this check does not read"),
    ):
        try:
            held = sorted(os.listdir(dotgit / subdirectory))
        except FileNotFoundError:
            held = []
        except OSError as exc:
            raise refuse(f"cannot inspect .git/{subdirectory}: {exc}") from exc
        if held:
            raise refuse(f"repository has {what}: {', '.join(held[:5])}")
    for alternates in ("objects/info/alternates", "objects/info/http-alternates"):
        borrowed = read_optional(alternates)
        if borrowed is not None and borrowed.strip():
            raise refuse(
                f"repository borrows objects through .git/{alternates}, so its own "
                "commits cannot be told apart from another repository's"
            )
    # (b) Nothing uncommitted, stashed, hidden, or in progress.
    for marker, operation in _NESTED_GIT_OPERATION_MARKERS:
        if os.path.lexists(dotgit / marker):
            raise refuse(f"{operation} is in progress (.git/{marker} exists)")
    stash = run(["rev-parse", "-q", "--verify", "refs/stash"])
    if stash.returncode == 0:
        raise refuse("stash entries exist (refs/stash)")
    if stash.returncode != 1:
        raise refuse(f"cannot read refs/stash: {detail(stash)}")
    hidden: list[str] = []
    gitlinks: list[str] = []
    for item in output(["ls-files", "-v", "-s", "-z"], work=True).split("\0"):
        if not item:
            continue
        tag, _space, entry = item.partition(" ")
        mode = entry.split(" ", 1)[0]
        path = entry.partition("\t")[2]
        if tag.islower() or tag == "S":
            hidden.append(f"{tag} {path}")
        if mode == "160000":
            gitlinks.append(path)
    if gitlinks:
        # Checked before status, which would otherwise run Git inside the
        # submodule under a configuration this check never inspected.
        raise refuse(
            f"index records {len(gitlinks)} submodule gitlink(s), whose checkouts "
            f"this check does not judge; first: {gitlinks[0]!r}"
        )
    if hidden:
        raise refuse(
            f"index marks {len(hidden)} path(s) assume-unchanged or skip-worktree, "
            f"which hides changes from status; first: {hidden[0]!r}"
        )
    exclude = read_optional("info/exclude")
    exclude_rules = [
        line
        for line in (b"" if exclude is None else exclude)
        .decode(errors="surrogateescape")
        .splitlines()
        if line.strip() and not line.startswith("#")
    ]
    if exclude_rules:
        raise refuse(
            f".git/info/exclude ignores {exclude_rules[0]!r}, a local rule no commit "
            "records, so files it hides from status may be work"
        )
    status = output(
        [
            "status",
            "--porcelain=v1",
            "-z",
            "--untracked-files=all",
            "--ignored=matching",
            "--ignore-submodules=none",
            "--no-renames",
        ],
        work=True,
    )
    changes: list[str] = []
    ignored: list[str] = []
    for item in status.split("\0"):
        if item.startswith("!! "):
            ignored.append(item[3:])
        elif item:
            changes.append(item)
    if changes:
        raise refuse(
            f"worktree has {len(changes)} uncommitted or untracked change(s), "
            f"first: {changes[0]!r}"
        )
    self_hidden = [
        item for item in ignored if item.rstrip("/").rsplit("/", 1)[-1] == ".gitignore"
    ]
    if self_hidden:
        raise refuse(
            f"{self_hidden[0]!r} is ignored by its own rules, which no commit "
            "records, so files it hides from status may be work"
        )
    # (c) Every commit object is reachable from a counted remote-tracking ref.
    head_probe = run(["rev-parse", "-q", "--verify", "HEAD^{commit}"])
    head: str | None = None
    if head_probe.returncode == 0:
        head = head_probe.stdout.decode().strip()
    else:
        symbolic = run(["symbolic-ref", "-q", "HEAD"])
        target = symbolic.stdout.decode(errors="surrogateescape").strip()
        unborn = (
            symbolic.returncode == 0
            and bool(target)
            and run(["rev-parse", "-q", "--verify", target]).returncode == 1
        )
        if not unborn:
            raise refuse("HEAD does not name a commit")
    listed_remotes = run(
        [
            "config",
            "--null",
            "--get-regexp",
            r"^remote\..*\.(url|pushurl|fetch|vcs|uploadpack|receivepack)$",
        ],
        user_config=True,
    )
    if listed_remotes.returncode not in {0, 1}:
        raise refuse(f"cannot read remote configuration: {detail(listed_remotes)}")
    remote_settings: dict[str, dict[str, list[str]]] = {}
    for item in listed_remotes.stdout.decode(errors="surrogateescape").split("\0"):
        key, _newline, value = item.partition("\n")
        if not key.startswith("remote."):
            continue
        name, _dot, variable = key[len("remote.") :].rpartition(".")
        remote_settings.setdefault(name, {}).setdefault(variable, []).append(value)
    remote_names = sorted(remote_settings)
    for remote_name in remote_names:
        if "/" in remote_name:
            raise refuse(
                f"remote {remote_name!r} has a name containing '/', so its "
                "remote-tracking refs can be mistaken for another remote's"
            )
    try:
        resolved_roots = [root.resolve(strict=False) for root in removed_roots]
    except (OSError, RuntimeError) as exc:
        raise refuse(f"cannot resolve the paths this removal deletes: {exc}") from exc

    def remote_exclusion(remote_name: str, settings: Mapping[str, list[str]]) -> str | None:
        urls = settings.get("url", [])
        if not urls:
            return "it has no URL"
        for variable, program in _NESTED_GIT_REMOTE_PROGRAMS:
            if any(settings.get(variable, [])):
                return (
                    f"it sets remote.{remote_name}.{variable}, so {program} this "
                    "check cannot inspect carried its transfers"
                )
        configured = [("URL", url) for url in urls] + [
            ("push URL", url) for url in settings.get("pushurl", [])
        ]
        seen = {url for _label, url in configured}
        for kind, flags in (("URL", ()), ("push URL", ("--push",))):
            effective = run(
                ["remote", "get-url", *flags, "--all", remote_name], user_config=True
            )
            if effective.returncode != 0:
                return f"Git cannot report its effective {kind}: {detail(effective)}"
            for url in effective.stdout.decode(errors="surrogateescape").splitlines():
                if url not in seen:
                    seen.add(url)
                    configured.append((f"effective {kind} {url!r}", url))
        for label, url in configured:
            reason = _nested_remote_exclusion(url, work_tree, resolved_roots, label=label)
            if reason is not None:
                return reason
        return None

    uncounted: dict[str, str] = {}
    counted_destinations: list[str] = []
    uncounted_destinations: list[str] = []
    for remote_name in remote_names:
        settings = remote_settings[remote_name]
        reason = remote_exclusion(remote_name, settings)
        refspecs = settings.get("fetch", [])
        if reason is None:
            counted_destinations.extend(
                destination
                for destination in _refspec_destinations(refspecs)
                if destination.startswith("refs/remotes/")
            )
        else:
            uncounted[remote_name] = reason
            # Every ref an uncounted remote could write, in any namespace:
            # refs/*:refs/* writes refs/remotes/origin/main as surely as
            # remotes/origin/main does.
            uncounted_destinations.extend(
                _refspec_destinations(refspecs, over_approximate=True)
            )
    counted_refs: dict[str, str] = {}
    local_tips: list[tuple[str, str]] = []
    for line in output(
        ["for-each-ref", "--format=%(objectname) %(refname) %(symref)"]
    ).splitlines():
        sha, refname, symref = line.split(" ", 2)
        # A symbolic ref proves nothing by itself: refs/remotes/origin/HEAD
        # can point at a ref an uncounted remote wrote, or at a local branch.
        # Its target, when that is a ref, is listed and judged on its own.
        if (
            not symref
            and any(
                _refspec_destination_matches(destination, refname)
                for destination in counted_destinations
            )
            and not any(
                _refspec_destination_matches(destination, refname)
                for destination in uncounted_destinations
            )
        ):
            counted_refs[refname] = sha
        else:
            local_tips.append((refname, sha))
    negatives = "".join(f"^{sha}\n" for sha in sorted(set(counted_refs.values())))
    commit_objects = output(
        [
            "cat-file",
            "--batch-all-objects",
            "--unordered",
            "--batch-check=%(objectname)",
            "--filter=object:type=commit",
        ]
    )

    def uncontained(flags: Sequence[str], positives: str) -> int:
        counted = output(
            ["rev-list", "--count", *flags, "--stdin"],
            stdin=(positives + negatives).encode(),
        )
        return int(counted.strip() or "0")

    total = uncontained(["--all", "--reflog"], commit_objects)
    if total:
        note = f"{total} commit(s) exist only in this repository" + (
            "; uncounted remote(s): "
            + ", ".join(f"{name} ({reason})" for name, reason in uncounted.items())
            if uncounted
            else ""
        )

        def named(label: str, sha: str) -> Refusal:
            return refuse(
                f"{label} names commit {sha}, which no counted refs/remotes/* ref "
                f"contains ({note})"
            )

        if head is not None and uncontained([], f"{head}\n"):
            raise named("HEAD", head)
        if uncontained([], "".join(f"{sha}\n" for _refname, sha in local_tips)):
            for refname, sha in local_tips:
                if uncontained([], f"{sha}\n"):
                    raise named(refname, sha)
        if uncontained(["--reflog"], ""):
            first = output(
                ["rev-list", "-n", "1", "--reflog", "--stdin"], stdin=negatives.encode()
            ).strip()
            raise refuse(
                f"a reflog entry reaches commit {first}, which no counted "
                f"refs/remotes/* ref contains ({note})"
            )
        first = output(
            ["rev-list", "-n", "1", "--stdin"],
            stdin=(commit_objects + negatives).encode(),
        ).strip()
        raise refuse(
            f"commit {first} is named by no ref, HEAD or reflog entry (for example "
            "a dropped stash or a deleted branch) and no counted refs/remotes/* ref "
            f"contains it ({note})"
        )
    remote_ref: str | None = None
    if head is not None:
        containing = output(
            [
                "for-each-ref",
                "--format=%(refname) %(symref)",
                "--contains",
                head,
                "refs/remotes/",
            ]
        ).splitlines()
        direct = [
            line.split(" ", 1)[0]
            for line in containing
            if line.endswith(" ") and line.split(" ", 1)[0] in counted_refs
        ]
        if not direct:
            raise refuse(f"no counted refs/remotes/* ref reports containing HEAD {head}")
        remote_ref = direct[0]
    return _DisposableNestedRepository(
        dotgit,
        (metadata.st_dev, metadata.st_ino),
        head,
        remote_ref,
        len(ignored),
        tuple(
            item.encode(errors="surrogateescape").decode(errors="backslashreplace")
            for item in ignored[:_NESTED_GIT_IGNORED_SAMPLE]
        ),
    )


def _judge_cache_nested_repositories(
    config: Config,
    cache: CacheDirectory,
    *,
    fenced_slot: Path,
    canonical_slot: Path,
    budget: _NestedGitBudget,
) -> tuple[_DisposableNestedRepository, ...]:
    """Judge every nested repository a removal of ``cache`` would reach, in order."""

    try:
        judged: list[_DisposableNestedRepository] = []
        for dotgit in _nested_git_metadata_paths(config, cache):
            judged.append(
                _judge_nested_git_repository(
                    dotgit,
                    (canonical_slot, fenced_slot),
                    display=canonical_slot / dotgit.relative_to(fenced_slot),
                    budget=budget,
                )
            )
        return tuple(judged)
    except Refusal:
        raise
    except Exception as exc:
        raise Refusal(
            f"cannot judge nested Git metadata in cache {cache.path}: "
            f"{type(exc).__name__}: {exc}"
        ) from exc


def _nested_git_evidence_item(
    checkout: str,
    repository: _DisposableNestedRepository,
    *,
    fenced_slot: Path,
    canonical_slot: Path,
) -> dict[str, object]:
    """Describe one repository judged disposable by its canonical path."""

    return {
        "checkout": checkout,
        "path": str(canonical_slot / repository.path.relative_to(fenced_slot)),
        "head": repository.head,
        "remote_ref": repository.remote_ref,
        "ignored_entries": repository.ignored_entries,
        "ignored_sample": list(repository.ignored_sample),
    }


def _nested_git_evidence_from_obj(value: object, label: str) -> list[dict[str, object]]:
    """Parse journaled nested-repository evidence, refusing any other shape."""

    parsed: list[dict[str, object]] = []
    for index, raw in enumerate(_as_list(value, label)):
        item_label = f"{label}[{index}]"
        item = _as_mapping(raw, item_label)
        _exact_keys(item, _NESTED_GIT_EVIDENCE_KEYS, set(), item_label)
        _as_str(item["checkout"], f"{item_label}.checkout")
        _as_str(item["path"], f"{item_label}.path")
        for key in ("head", "remote_ref"):
            if item[key] is not None:
                _as_str(item[key], f"{item_label}.{key}")
        _as_int(item["ignored_entries"], f"{item_label}.ignored_entries")
        for sample_index, sample in enumerate(
            _as_list(item["ignored_sample"], f"{item_label}.ignored_sample")
        ):
            _as_str(sample, f"{item_label}.ignored_sample[{sample_index}]")
        parsed.append(dict(item))
    return parsed


def _cache_slot_holds(
    config: Config, cache_slots: Mapping[str, CacheSlot]
) -> dict[str, dict[str, object] | None]:
    """Resolve every cache slot's hold while replaying each machine log once.

    Loading the hold slot by slot replayed the whole append-only log for each
    slot, so a report's journal reads grew with slots times log size.
    """

    by_machine: dict[str, set[str]] = {}
    for slot, cache_slot in cache_slots.items():
        by_machine.setdefault(cache_slot.machine or config.machine, set()).add(slot)
    holds: dict[str, dict[str, object] | None] = {}
    for machine, slots in sorted(by_machine.items()):
        events = _load_events(config, machine)
        if events:
            replayed = _holds_from_events(events, machine, slots)
            holds.update((slot, replayed.get(slot)) for slot in slots)
        else:
            holds.update(
                (slot, _load_hold_snapshot(config, slot, machine)) for slot in slots
            )
    return holds


_CACHEDIR_TAG_SIGNATURE = b"Signature: 8a477f597d28d172789f06886806bc55"
"""The first bytes of a ``CACHEDIR.TAG`` file (https://bford.info/cachedir/)."""


def _is_regular_file(path: Path) -> bool:
    try:
        return stat.S_ISREG(os.lstat(path).st_mode)
    except OSError:
        return False


def _has_build_cache_marker(path: Path) -> bool:
    """Whether a tool has marked ``path`` as its build cache.

    A ``CACHEDIR.TAG`` with the standard signature marks a cache for any
    tool. Cargo writes one only when it creates a build directory itself, so
    a build directory that another tool created first never receives one;
    Cargo writes ``.rustc_info.json`` to its build directory on every run, and
    that file marks such a directory too.
    """

    if _is_regular_file(path / ".rustc_info.json"):
        return True
    tag = path / "CACHEDIR.TAG"
    if not _is_regular_file(tag):
        return False
    try:
        with open(tag, "rb") as handle:
            return handle.read(len(_CACHEDIR_TAG_SIGNATURE)) == _CACHEDIR_TAG_SIGNATURE
    except OSError:
        return False


def _cache_is_within_unpacked_cargo_package(cache: CacheDirectory) -> bool:
    """Whether ``cache`` lies inside source that Cargo unpacked.

    Cargo writes ``.cargo-ok`` at the root of every crate it unpacks into a
    Cargo home's ``registry/src`` and every Git dependency it checks out into
    ``git/checkouts``, and it does not unpack that package again while the
    file exists. Deleting a directory inside such a package, such as the
    ``cc`` crate's ``src/target`` source module, therefore leaves a package
    that Cargo neither repairs nor reports. The file is found whatever the
    directories above it are called.
    """

    path = cache.path
    while True:
        if _is_regular_file(path / ".cargo-ok"):
            return True
        if path == cache.checkout_root or path.parent == path:
            return False
        path = path.parent


def _cache_glob_names_path_literally(config: Config, cache: CacheDirectory) -> bool:
    """Whether a cache glob without wildcards names ``cache`` exactly."""

    relative = cache.path.relative_to(cache.checkout_root).as_posix()
    patterns = (
        *config.cache_globs,
        *(pattern for _name, group in config.repo_cache_globs for pattern in group),
    )
    return any(
        _glob_parts_are_literal(_glob_pattern_parts(pattern))
        and _glob_matches_path(pattern, relative)
        for pattern in patterns
    )


def _clean_caches_skip_reason(config: Config, cache: CacheDirectory) -> str | None:
    """Why ``clean-caches`` keeps a directory its cache globs selected, if it does.

    Selection, with every refusal it raises, is shared with retirement and
    is unchanged; this only narrows what ``clean-caches`` deletes. A glob
    with a wildcard finds directories by name, and a name is not evidence of
    a cache: a crate's ``src/target`` module, a test fixture, or a directory
    of worktrees can carry it. Such a match is deleted only when a build
    tool has marked it. A glob without wildcards names one path the project
    configured, and keeps its plain meaning. Nothing inside an unpacked
    Cargo package is deleted.
    """

    if _cache_is_within_unpacked_cargo_package(cache):
        return "inside an unpacked Cargo package (.cargo-ok)"
    if not _cache_glob_names_path_literally(config, cache) and not _has_build_cache_marker(
        cache.path
    ):
        return "matched by a wildcard glob, and no build tool marked it as a cache"
    return None


def _cmd_clean_caches(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    if not config.cache_globs and not config.repo_cache_globs:
        raise Refusal("no cache globs are configured")
    only = tuple(args.only or ())
    for slot in only:
        _validate_name(slot, "slot")
    with contextlib.ExitStack() as locks:
        locks.enter_context(_mutation_locks(config, args.wait_lock))
        _refuse_partial_state(config)
        states, _archives = _validate_global_state(config)
        requested = set(only)
        cache_slots = {
            record.slot: CacheSlot(record.slot, record.machine, record.checkouts)
            for state in states
            for record in state.slots
            if not requested or record.slot in requested
        }
        registered_slots = {
            record.slot for candidate in states for record in candidate.slots
        }
        journal_slots = _all_journal_cache_slots(
            config, requested if requested else None, states
        )
        registered_slots.update(slot.slot for slot in journal_slots)
        for journal_slot in journal_slots:
            if not requested or journal_slot.slot in requested:
                cache_slots[journal_slot.slot] = journal_slot
        malformed_slots: dict[str, str] = {}
        entries = (
            (config.worktrees / slot for slot in sorted(requested - set(cache_slots)))
            if requested
            else sorted(config.worktrees.iterdir(), key=lambda path: path.name)
        )
        for entry in entries:
            if (
                not entry.exists()
                or not entry.is_dir()
                or entry.is_symlink()
                or entry.name.startswith("EVENTS.")
                or entry == _validate_slots_directory(config)
                or _is_representation_directory(config, entry)
                or entry.name in registered_slots
            ):
                continue
            try:
                _validate_name(entry.name, "unregistered slot")
            except Refusal as exc:
                if args.yes:
                    raise Refusal(
                        f"cannot bulk-clean malformed unregistered directory {entry}: {exc}"
                    ) from exc
                malformed_slots[entry.name] = str(exc)
                continue
            cache_slots[entry.name] = CacheSlot(
                entry.name,
                config.machine,
                (),
                "unregistered",
            )
        unknown = sorted(set(only) - set(cache_slots))
        if unknown:
            raise Refusal(f"unknown slot(s) for cache cleanup: {', '.join(unknown)}")
        selected = set(cache_slots) if args.yes else set(only)
        rows: list[dict[str, object]] = [
            {
                "slot": slot,
                "machine": None,
                "cache_bytes": 0,
                "action": "BLOCKED",
                "paths": [],
                "skipped": [],
                "hold_reason": None,
                "registered": False,
                "state": "unregistered",
                "cache_error": error,
                "policy_note": None,
            }
            for slot, error in sorted(malformed_slots.items())
        ]
        plans: dict[str, tuple[CacheDirectory, ...]] = {}
        holds = _cache_slot_holds(config, cache_slots)
        if not selected:
            # A report deletes nothing, and every deletion reacquires these
            # locks and replans its slots. Measuring hundreds of cache trees
            # must not block every other slot mutation for the whole walk.
            locks.close()
        for slot in sorted(cache_slots):
            cache_slot = cache_slots[slot]
            hold = holds[slot]
            directories: tuple[CacheDirectory, ...]
            cache_error: str | None = None
            policy_note = (
                "repository-specific cache globs were not applied because this slot has no "
                "trusted repository-name mapping"
                if cache_slot.state == "unregistered" and config.repo_cache_globs
                else None
            )
            skipped: list[dict[str, str]] = []
            if hold is not None:
                directories = ()
                cache_bytes = 0
                action = "HELD"
            else:
                try:
                    measured = tuple(
                        (cache, _allocated_cache_bytes(config, cache))
                        for cache in _cache_slot_directories(config, cache_slot)
                    )
                    # Every selected directory was measured, so its refusals
                    # (nested Git metadata, for one) have already applied.
                    kept: list[tuple[CacheDirectory, int]] = []
                    for cache, size in measured:
                        reason = _clean_caches_skip_reason(config, cache)
                        if reason is None:
                            kept.append((cache, size))
                        else:
                            skipped.append({"path": str(cache.path), "reason": reason})
                    directories = tuple(cache for cache, _size in kept)
                    cache_bytes = sum(size for _cache, size in kept)
                except (Refusal, OSError) as exc:
                    if slot in selected:
                        raise Refusal(
                            f"cannot clean selected slot {slot}: {exc}"
                        ) from exc
                    directories = ()
                    skipped = []
                    cache_bytes = 0
                    cache_error = str(exc)
                    action = "BLOCKED"
                else:
                    if slot in selected:
                        action = "REMOVED"
                        plans[slot] = directories
                    else:
                        action = "REPORT"
            rows.append(
                {
                    "slot": slot,
                    "machine": cache_slot.machine,
                    "cache_bytes": cache_bytes,
                    "action": action,
                    "paths": [str(cache.path) for cache in directories],
                    "skipped": skipped,
                    "hold_reason": None if hold is None else hold["reason"],
                    "registered": cache_slot.state == "active",
                    "state": cache_slot.state,
                    "cache_error": cache_error,
                    "policy_note": policy_note,
                }
            )
        removed_bytes = 0
        for row in rows:
            slot = _as_str(row["slot"], "cache row slot")
            for cache in plans.get(slot, ()):
                removed_bytes += _remove_cache_directory(config, cache)
    payload = {
        "schema": SCHEMA,
        "cache_globs": list(config.cache_globs),
        "repo_cache_globs": {
            name: list(patterns) for name, patterns in config.repo_cache_globs
        },
        "removed_bytes": removed_bytes,
        "slots": rows,
    }
    if args.format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
    else:
        mode = "delete" if selected else "report-only"
        print(
            f"cache_mode={mode} slots={len(rows)} removed={_format_gib(removed_bytes)}"
        )
        for row in rows:
            print(
                f"{row['action']}: {row['slot']} cache={_format_gib(_as_int(row['cache_bytes'], 'cache bytes'))}"
                + (
                    f" reason={row['hold_reason']}"
                    if row["hold_reason"] is not None
                    else ""
                )
                + (
                    f" error={row['cache_error']}"
                    if row["cache_error"] is not None
                    else ""
                )
                + (
                    f" note={row['policy_note']}"
                    if row["policy_note"] is not None
                    else ""
                )
            )
    return 0


def _absent_slot_recovery_reason(
    record: ActiveRecord, slot_path: Path, record_sha256: str
) -> str:
    """Name the exact read-only plan that retires a row whose directory is absent."""

    if record.slot_type == "agent":
        plan = (
            "wrkslots recover-absent-agent-rows --row "
            f"{record.slot}={record.generation}={record_sha256}"
        )
    else:
        row = {
            "generation": record.generation,
            "machine": record.machine,
            "record_sha256": record_sha256,
            "slot": record.slot,
        }
        plan = (
            "wrkslots recover-absent-validate-rows --input FILE', where FILE holds "
            f"'{json.dumps({'schema': 1, 'rows': [row]}, sort_keys=True)}"
        )
    return (
        f"slot directory is absent: {slot_path}; nothing occupies the path, so this "
        f"row is retired by recovery, not removal: on machine {record.machine}, run "
        f"'{plan}' for the read-only plan, then repeat it with '--apply "
        "--coordinator-authorized --coordinator-pid <coordinator-pid>'"
    )


def _audit_record(
    config: Config,
    record: ActiveRecord,
    *,
    events: Sequence[Mapping[str, object]],
    vcs: _GitVcs | None = None,
    process_census: _ProcessPathCensus | None = None,
    process_census_error: str | None = None,
    registered_liveness: tuple[str, str] | None = None,
    cache_measurement: _AuditCacheMeasurement | None = None,
) -> tuple[dict[str, object], bool]:
    selected_vcs = vcs or _GitVcs()
    owner_state, owner_detail = _process_state(record.owner)
    liveness_state, liveness_detail = (
        registered_liveness
        if registered_liveness is not None
        else _owner_liveness_states(config, (record,))[
            (record.machine, record.slot, record.generation)
        ]
    )
    heartbeat_age, heartbeat_expired = _heartbeat_diagnosis(record)
    agent_running = not (
        liveness_state == "dead"
        and owner_state == "dead"
    )
    hold = _load_hold(config, record.slot, record.machine, events=events)
    release, release_void = _owner_release_state(config, record, events)
    # Remove honours a release exactly when this is true; audit must agree
    # with it so that DELETABLE never names a slot remove would refuse and a
    # released slot is not reported as waiting for its owner's exit.
    release_honoured = (
        release is not None
        and release_void is None
        and owner_state in ("live", "dead")
        and not _owner_record_is_absent(record)
    )
    release_fields: dict[str, object] = (
        {} if release is None else {"owner_release": _owner_release_obj(release, release_void)}
    )
    if cache_measurement is None:
        cache_bytes: int | None = 0
        cache_error: str | None = None
        cache_status = "complete"
        try:
            cache_bytes = sum(
                _allocated_cache_bytes(config, cache)
                for cache in _cache_directories(
                    config, record.checkouts, vcs=selected_vcs
                )
            )
        except Refusal as exc:
            cache_bytes = None
            cache_error = str(exc)
            cache_status = "error"
    else:
        cache_bytes = cache_measurement.bytes
        cache_error = cache_measurement.error
        cache_status = cache_measurement.status
    if hold is not None:
        return (
            {
                "slot": record.slot,
                "machine": record.machine,
                "agent": record.agent,
                "slot_type": record.slot_type,
                "generation": record.generation,
                "record_sha256": _event_digest(_record_to_obj(record)),
                "verdict": "HELD",
                "reasons": [_as_str(hold["reason"], "slot hold.reason")],
                "owner_state": owner_state,
                "liveness_state": liveness_state,
                "heartbeat_age_seconds": int(heartbeat_age),
                "heartbeat_expired": heartbeat_expired,
                "cache_bytes": cache_bytes,
                "cache_error": cache_error,
                "cache_status": cache_status,
                **release_fields,
            },
            agent_running,
        )
    reasons: list[str] = []
    process_census_unknown = False
    if not release_honoured:
        if not heartbeat_expired:
            reasons.append(
                f"heartbeat age {int(heartbeat_age)}s has not exceeded the "
                f"{record.heartbeat_ttl_seconds}s time-to-live"
            )
        if liveness_state != "dead":
            reasons.append(f"liveness is {liveness_state}: {liveness_detail}")
        if record.owner is None:
            reasons.append("no owner process generation is recorded, so death is unknown")
        elif owner_state != "dead":
            reasons.append(f"recorded owner is {owner_state}: {owner_detail}")
    slot_path = _slot_directory(config, record.slot, record.slot_type)
    record_sha256 = _event_digest(_record_to_obj(record))
    # ABSENT is not UNSAFE.  Only `_SlotDirectoryAbsent` -- lstat found nothing
    # at the exact slot path, after `_assert_record_paths` refused any symlink
    # on the way to it and proved every checkout is that path or a child of
    # it -- selects the recovery classification.  Every other directory
    # refusal still lands in `reasons` below and keeps the row BLOCKED.
    slot_absent = False
    try:
        _assert_record_paths(config, record)
        try:
            _assert_slot_contents(config, record)
        except _SlotDirectoryAbsent:
            slot_absent = True
        # Recovery refuses an unread handoff exactly as removal does.
        _assert_handoff_read(config, record, slot_path, events=events)
        for checkout in () if slot_absent else record.checkouts:
            path = _stored_path(config, checkout.path, "checkout path")
            repository = _stored_repository_path(config, checkout.repository)[1]
            selected_vcs.verify_existing_worktree(repository, path)
            if selected_vcs.branch(path) != checkout.branch:
                raise Refusal(f"checkout {checkout.name} branch changed")
            if record.slot_type == "agent":
                operations = selected_vcs.operation_paths(path)
                if operations:
                    raise Refusal(
                        f"checkout {checkout.name} has an unfinished Git operation: "
                        f"{operations[0]}"
                    )
                selected_vcs.assert_ordinary_history(path)
                selected_vcs.assert_ordinary_index(path)
                _assert_cache_policy_untracked(config, checkout, selected_vcs)
                # Removal salvages initialized submodules before deleting an
                # agent slot.  Audit must therefore establish the same local
                # remote authority first; otherwise it can advertise
                # DELETABLE only for remove to refuse before salvage.
                _submodule_salvage_checkouts(config, checkout, selected_vcs)
            if (
                selected_vcs.remote_url_sha256(path, checkout.remote)
                != checkout.remote_url_sha256
            ):
                raise Refusal(f"checkout {checkout.name} remote URL changed")
    except Refusal as exc:
        reasons.append(str(exc))
    if slot_absent and release_honoured and owner_state != "dead":
        # An honoured release lets REMOVE proceed past a live owner, but the
        # recover-absent commands bind the exact recorded owner generation and
        # refuse while it lives.  RECOVERABLE must never name a command that
        # would refuse on this ground, so a live releasing owner keeps the
        # absent row BLOCKED until that generation exits.
        reasons.append(
            f"recorded owner is {owner_state}: {owner_detail}; the recover-absent "
            "commands require the recorded owner generation to be dead"
        )
    if (
        release_honoured
        or (
            heartbeat_expired
            and liveness_state == "dead"
            and owner_state == "dead"
        )
    ) and not reasons:
        if process_census_error is not None:
            reasons.append(process_census_error)
            process_census_unknown = True
        else:
            try:
                _assert_slot_unused(
                    slot_path,
                    _record_for_slot_use_check(
                        record,
                        validate_complete=record.slot_type == "validate",
                        allow_live_validate_owner=False,
                        owner_consented=release_honoured,
                    ),
                    census=process_census,
                )
            except Refusal as exc:
                reasons.append(str(exc))
                agent_running = True
    if slot_absent:
        # The cache census found no checkout to inspect for the same reason:
        # every checkout path is the absent slot directory or lies inside it,
        # so there are no cache bytes, and that refusal is not a second blocker.
        cache_bytes = 0
        cache_error = None
        cache_status = "complete"
        reasons.append(_absent_slot_recovery_reason(record, slot_path, record_sha256))
    if cache_error is not None:
        reasons.append(f"cache inspection failed: {cache_error}")
    elif cache_status == "partial":
        # A bounded census may not yet have reached a nested path that the
        # complete historical traversal would have refused.  Its null byte
        # count is therefore informationally honest but is not deletion
        # evidence.  Keep the row out of DELETABLE until the same resumable
        # census reaches and verifies every entry.
        reasons.append("cache inspection incomplete: bounded census is partial")
    return (
        {
            "slot": record.slot,
            "machine": record.machine,
            "agent": record.agent,
            "slot_type": record.slot_type,
            "generation": record.generation,
            "record_sha256": record_sha256,
            # RECOVERABLE is DELETABLE's counterpart for absent storage: every
            # proof audit makes for removal passed except the directory's
            # existence, and the only reason is the recovery command.  The
            # named command re-proves its own preconditions before acting.
            "verdict": (
                "UNKNOWN"
                if process_census_unknown
                else (
                    ("RECOVERABLE" if len(reasons) == 1 else "BLOCKED")
                    if slot_absent
                    else ("DELETABLE" if not reasons else "BLOCKED")
                )
            ),
            "reasons": reasons,
            "owner_state": owner_state,
            "liveness_state": liveness_state,
            "heartbeat_age_seconds": int(heartbeat_age),
            "heartbeat_expired": heartbeat_expired,
            "cache_bytes": cache_bytes,
            "cache_error": cache_error,
            "cache_status": cache_status,
            **release_fields,
        },
        agent_running,
    )


def _audit_validate_batch_seal_evidence(
    config: Config,
) -> tuple[
    tuple[tuple[str, str, int, Path], ...],
    tuple[tuple[str | None, str, str], ...],
]:
    """Parse seal targets for audit without letting one bad journal hide all rows."""

    targets: list[tuple[str, str, int, Path]] = []
    errors: list[tuple[str | None, str, str]] = []
    for path in _validate_batch_seal_journals(config):
        match = re.fullmatch(
            r"VALIDATE-BATCH-SEAL\.([A-Za-z0-9][A-Za-z0-9._-]{0,63})\.journal",
            path.name,
        )
        machine = None if match is None else match.group(1)
        try:
            raw, parsed = _validate_batch_seal_journal(
                config,
                path,
                _read_json(path, "validation-batch seal journal"),
            )
        except (Refusal, StateError) as exc:
            errors.append((machine, path.name, str(exc)))
            continue
        parsed_machine = _as_str(raw["machine"], "validation-batch seal journal.machine")
        targets.extend(
            (parsed_machine, slot, generation, target.path)
            for slot, generation, target in parsed
        )
    return tuple(targets), tuple(errors)


def _cmd_audit(args: argparse.Namespace) -> int:
    if args.cache_work_limit < 1:
        raise Refusal("--cache-work-limit must be positive")
    if not (math.isfinite(args.cache_wall_seconds) and args.cache_wall_seconds > 0):
        raise Refusal("--cache-wall-seconds must be finite and positive")
    config = _load_config(args.project_root, args.machine)
    metrics = _AuditMetrics()
    with _locked(config.control / "ACTIVE", exclusive=False, wait_seconds=args.wait_lock):
        registry_started = metrics.start()
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        states, _archives = _validate_global_state(config)
        records = [record for state in states for record in state.slots]
        event_logs = {
            state.machine: _load_events(config, state.machine) for state in states
        }
        seal_targets, seal_errors = _audit_validate_batch_seal_evidence(config)
        seal_by_slot = {
            (machine, slot): (generation, path)
            for machine, slot, generation, path in seal_targets
        }
        represented_seals: set[tuple[str, str, int]] = set()
        journal_slots = {
            slot.slot: slot for slot in _all_journal_cache_slots(config, states=states)
        }
        metrics.finish(
            "registry",
            registry_started,
            {
                "active_rows": len(records),
                "event_records": sum(len(events) for events in event_logs.values()),
                "machine_shards": len(states),
                "recovery_journals": len(journal_slots),
                "validation_seals": len(seal_targets),
            },
        )
        liveness_started = metrics.start()
        # Validation rows are answered by their runs, agent rows by the
        # registered command; see _validation_run_liveness_states.
        registered_liveness = _owner_liveness_states(config, records)
        agent_subjects = sum(record.slot_type != "validate" for record in records)
        metrics.finish(
            "liveness",
            liveness_started,
            {
                "batch_invocations": int(
                    bool(agent_subjects) and config.liveness_batch_command is not None
                ),
                "legacy_invocations": (
                    0 if config.liveness_batch_command is not None else agent_subjects
                ),
                "subjects": agent_subjects,
                "validation_run_subjects": len(records) - agent_subjects,
            },
        )
        census_started = metrics.start()
        process_census: _ProcessPathCensus | None = None
        process_census_error: str | None = None
        if records:
            try:
                process_census = _capture_process_path_census(
                    [_slot_directory(config, record.slot, record.slot_type) for record in records]
                )
            except Refusal as exc:
                process_census_error = f"process/path census failed: {exc}"
        metrics.finish(
            "process-census",
            census_started,
            {
                "census_attempted": int(bool(records)),
                "slot_paths": len(records),
            },
        )
        on_disk: set[tuple[str, str]] = set()
        for slot_type, root in _slot_roots(config).items():
            if not root.exists():
                continue
            try:
                on_disk.update(
                    (slot_type, entry.name)
                    for entry in root.iterdir()
                    if entry.is_dir()
                    and not entry.is_symlink()
                    and not entry.name.startswith("EVENTS.")
                    and not _is_representation_directory(config, entry)
                    and not (
                        slot_type == "agent"
                        and entry == _validate_slots_directory(config)
                    )
                )
            except OSError as exc:
                raise Refusal(f"cannot enumerate worktree slots in {root}: {exc}") from exc
        registered = {(record.slot_type, record.slot) for record in records}
        rows: list[dict[str, object]] = []
        running_agent_count = 0
        audit_vcs = _AuditGitVcs()
        cache_planned: dict[str, tuple[CacheDirectory, ...]] = {}
        cache_errors: dict[str, str] = {}
        record_cache_subjects: dict[tuple[str, str, int], str] = {}
        unregistered_cache_subjects: dict[tuple[str, str], str] = {}
        plan_targets: list[tuple[str, Sequence[Checkout] | CacheSlot]] = []
        for record in records:
            subject = f"record:{record.machine}:{record.slot}:{record.generation}"
            record_cache_subjects[(record.machine, record.slot, record.generation)] = subject
            plan_targets.append((subject, record.checkouts))
        for slot_type, slot in sorted(on_disk - registered):
            subject = f"unregistered:{slot_type}:{slot}"
            unregistered_cache_subjects[(slot_type, slot)] = subject
            if slot_type != "agent":
                cache_planned[subject] = ()
                continue
            journal_slot = journal_slots.get(slot)
            plan_targets.append(
                (
                    subject,
                    journal_slot
                    if journal_slot is not None
                    else CacheSlot(slot, config.machine, (), "unregistered"),
                )
            )
        # Recursive cache globs can reach arbitrarily large ignored trees. Each
        # subject may use an equal share of what earlier subjects left, so an
        # expensive subject exhausts only its own planning, never a cheap peer's.
        plan_started = metrics.start()
        plan_seconds = args.cache_wall_seconds
        plan_work = _AuditWorkBudget(args.cache_work_limit)
        plan_exhausted = 0
        for position, (subject, target) in enumerate(plan_targets):
            remaining_subjects = len(plan_targets) - position
            share = _CachePlanBudget(
                _AuditWorkBudget(plan_work.remaining // remaining_subjects),
                plan_seconds / remaining_subjects,
                args.cache_wall_seconds,
            )
            try:
                cache_planned[subject] = (
                    _cache_slot_directories(config, target, vcs=audit_vcs, budget=share)
                    if isinstance(target, CacheSlot)
                    else _cache_directories(config, target, vcs=audit_vcs, budget=share)
                )
            except Refusal as exc:
                cache_planned[subject] = ()
                cache_errors[subject] = str(exc)
                plan_exhausted += isinstance(exc, _CachePlanExhausted)
            plan_work.consumed += share.work.consumed
            plan_seconds = max(0.0, plan_seconds - share.spent)
        metrics.finish(
            "cache-planning",
            plan_started,
            {
                "directories_listed": plan_work.consumed,
                "exhausted_subjects": plan_exhausted,
                "subjects": len(plan_targets),
            },
        )
        cache_started = metrics.start()
        cache_state_path = None
        cache_storage_error = None
        if any(cache_planned.values()):
            try:
                cache_state_path = _audit_cache_state_path(config, args.cache_census_state)
            except (OSError, Refusal) as exc:
                if args.cache_census_state is not None:
                    # Explicit path errors are CLI refusals. An unavailable
                    # default cache is only unavailable accounting evidence.
                    raise
                cache_storage_error = f"default audit cache storage is unavailable: {exc}"
        cache_measurements, cache_work = _audit_cache_census(
            config,
            states,
            cache_planned,
            cache_errors,
            state_path=cache_state_path,
            work_limit=args.cache_work_limit,
            wall_seconds=args.cache_wall_seconds,
            storage_error=cache_storage_error,
        )
        metrics.finish("cache-census", cache_started, cache_work)
        records_started = metrics.start()
        for record in records:
            row, running = _audit_record(
                config,
                record,
                events=event_logs[record.machine],
                vcs=audit_vcs,
                process_census=process_census,
                process_census_error=process_census_error,
                registered_liveness=registered_liveness[
                    (record.machine, record.slot, record.generation)
                ],
                cache_measurement=cache_measurements[
                    record_cache_subjects[
                        (record.machine, record.slot, record.generation)
                    ]
                ],
            )
            journal_slot = journal_slots.get(record.slot)
            if journal_slot is not None:
                reasons = row["reasons"]
                assert isinstance(reasons, list)
                reasons.insert(
                    0,
                    f"interrupted {journal_slot.state.replace('-', ' ')} requires "
                    "wrkslots recover",
                )
                row["verdict"] = "BLOCKED"
            sealed = seal_by_slot.get((record.machine, record.slot))
            if sealed is not None:
                sealed_generation, _sealed_path = sealed
                reasons = row["reasons"]
                assert isinstance(reasons, list)
                if sealed_generation == record.generation:
                    reasons.insert(
                        0,
                        "interrupted validation-batch seal requires wrkslots recover",
                    )
                    row["verdict"] = "BLOCKED"
                else:
                    reasons.insert(
                        0,
                        "validation-batch seal cannot be attributed to the active "
                        f"generation: sealed={sealed_generation} "
                        f"active={record.generation}",
                    )
                    row["verdict"] = "UNKNOWN"
                represented_seals.add(
                    (record.machine, record.slot, sealed_generation)
                )
            rows.append(row)
            running_agent_count += int(running)
        metrics.finish(
            "registered-rows",
            records_started,
            {"rows": len(records)},
        )
        storage_started = metrics.start()
        for slot_type, slot in sorted(on_disk - registered):
            journal_slot = journal_slots.get(slot)
            sealed = seal_by_slot.get((config.machine, slot))
            cache_measurement = cache_measurements[
                unregistered_cache_subjects[(slot_type, slot)]
            ]
            rows.append(
                {
                    "slot": slot,
                    "slot_type": slot_type,
                    "machine": (
                        journal_slot.machine
                        if journal_slot is not None
                        else (config.machine if sealed is not None else None)
                    ),
                    "agent": None,
                    "generation": None if sealed is None else sealed[0],
                    "record_sha256": None,
                    "verdict": "BLOCKED",
                    "reasons": [
                        (
                            f"interrupted {journal_slot.state.replace('-', ' ')} requires "
                            "wrkslots recover"
                            if journal_slot is not None
                            else (
                                "interrupted validation-batch seal requires wrkslots recover"
                                if sealed is not None
                                else (
                                    "validation directory has no active registry row; preserve "
                                    "and inspect it, and use import-existing only for a "
                                    "demonstrably live owner; destructive ownerless Git "
                                    "worktree recovery is disabled"
                                    if slot_type == "validate"
                                    else "directory has no active registry row; inspect or "
                                    "import it"
                                )
                            )
                        )
                    ],
                    "owner_state": (
                        journal_slot.state
                        if journal_slot is not None
                        else (
                            "validation-batch-seal"
                            if sealed is not None
                            else "unregistered"
                        )
                    ),
                    "liveness_state": "unverifiable",
                    "cache_bytes": cache_measurement.bytes,
                    "cache_error": cache_measurement.error,
                    "cache_status": cache_measurement.status,
                }
            )
            if sealed is not None:
                represented_seals.add((config.machine, slot, sealed[0]))
        for journal_slot in sorted(journal_slots.values(), key=lambda item: item.slot):
            if any(
                slot == journal_slot.slot
                for _slot_type, slot in registered | on_disk
            ):
                continue
            rows.append(
                {
                    "slot": journal_slot.slot,
                    "slot_type": None,
                    "machine": journal_slot.machine,
                    "agent": None,
                    "generation": None,
                    "record_sha256": None,
                    "verdict": "BLOCKED",
                    "reasons": [
                        f"interrupted {journal_slot.state.replace('-', ' ')} requires "
                        "wrkslots recover"
                    ],
                    "owner_state": journal_slot.state,
                    "liveness_state": "unverifiable",
                    "cache_bytes": 0,
                    "cache_error": None,
                    "cache_status": "complete",
                }
            )
        for machine, slot, generation, sealed_path in seal_targets:
            if (machine, slot, generation) in represented_seals:
                continue
            rows.append(
                {
                    "slot": slot,
                    "slot_type": "validate",
                    "machine": machine,
                    "agent": None,
                    "generation": generation,
                    "record_sha256": None,
                    "verdict": "BLOCKED",
                    "reasons": [
                        "interrupted validation-batch seal requires wrkslots recover; "
                        f"recorded path={sealed_path}"
                    ],
                    "owner_state": "validation-batch-seal",
                    "liveness_state": "unverifiable",
                    "cache_bytes": 0,
                    "cache_error": None,
                    "cache_status": "complete",
                }
            )
        for seal_error_machine, journal_name, error in seal_errors:
            rows.append(
                {
                    "slot": journal_name,
                    "slot_type": "validate",
                    "machine": seal_error_machine,
                    "agent": None,
                    "generation": None,
                    "record_sha256": None,
                    "verdict": "UNKNOWN",
                    "reasons": [
                        f"validation-batch seal evidence is unreadable: {error}"
                    ],
                    "owner_state": "validation-batch-seal",
                    "liveness_state": "unverifiable",
                    "cache_bytes": 0,
                    "cache_error": None,
                    "cache_status": "complete",
                }
            )
        worktree_count = len(on_disk)
        disk = _disk_status(config)
        metrics.finish(
            "storage",
            storage_started,
            {
                "on_disk_rows": len(on_disk),
                "output_rows": len(rows),
                "unregistered_rows": len(on_disk - registered),
            },
        )
    sorted_rows = sorted(rows, key=lambda row: str(row["slot"]))
    attention = [
        row
        for row in sorted_rows
        if row["verdict"] in ("DELETABLE", "RECOVERABLE")
        or row["owner_state"] == "unregistered"
        or any(
            str(reason).startswith("interrupted ")
            for reason in _as_list(row["reasons"], "audit row.reasons")
        )
    ]
    unknown = [
        row
        for row in sorted_rows
        if row["verdict"] == "UNKNOWN"
        or (
                row["verdict"] == "BLOCKED"
                and row.get("heartbeat_expired") is True
                and (
                row["owner_state"] not in ("live", "dead")
                    or row["liveness_state"] not in ("alive", "dead")
                    or row["cache_error"] is not None
                    or row.get("cache_status") == "partial"
                    or any(
                    token in str(reason).lower()
                    for reason in _as_list(row["reasons"], "audit row.reasons")
                    for token in ("cannot", "failed", "unavailable", "unknown")
                )
            )
        )
    ]
    # ⚠️ DEDUPLICATE BOTH LISTS, NOT JUST ONE, AND DEDUPLICATE BY THE PUBLISHED
    # KEY. `rows` is assembled from FOUR separate append sites, so one slot can
    # legitimately produce more than one row -- a registry row plus an on-disk
    # worktree row is the ordinary case, which is why `owner_state ==
    # "unregistered"` is itself an attention condition.
    #
    # The previous code built `attention_ids` precisely because duplicates are
    # possible, used it to dedupe `unknown` against `attention`, and never
    # deduped `attention` against itself. The downstream contract then refused
    # the whole census -- "audit.attention_slots contains duplicates" -- so the
    # audit could not publish a number at all, and a tick that reports nothing
    # is indistinguishable from one that found nothing.
    #
    # ⚠️ THIS IS A DEADLOCK RATHER THAN A WRONG NUMBER, which is why it is worth
    # the comment. Nothing downstream can clear the condition: the duplicate is
    # produced inside this function every time two routes describe one slot, so
    # no later participant can complete the operation from the record. The
    # refusal was correct and unclearable at the same time.
    #
    # Deduplicating by (slot, machine) alone would not have been enough either:
    # the PUBLISHED lists carry the slot name only, so two machines registering
    # one name would still emit a duplicate the key could not see. Both lists
    # are therefore reduced on the value that is actually published, preserving
    # first-seen order so the report stays stable between runs.
    attention_names = _first_seen_names([str(row["slot"]) for row in attention])
    attention_name_set = set(attention_names)
    unknown_names = [
        name
        for name in _first_seen_names([str(row["slot"]) for row in unknown])
        if name not in attention_name_set
    ]
    if attention_names:
        gate_state = "actionable"
        summary = f"{len(attention_names)} worktree slot(s) need coordinator attention"
    elif unknown_names:
        gate_state = "unknown"
        summary = (
            f"could not determine reclaim state for {len(unknown_names)} worktree "
            "slot(s)"
        )
    else:
        gate_state = "ok"
        summary = "no worktree slot currently needs coordinator attention"
    payload = {
        "schema": SCHEMA,
        "worktree_count": worktree_count,
        "running_agent_count": running_agent_count,
        "leak": worktree_count > running_agent_count,
        "attention_count": len(attention_names),
        "attention_slots": attention_names,
        "unknown_count": len(unknown_names),
        "unknown_slots": unknown_names,
        "state": gate_state,
        "summary": summary,
        "remote_refs_refreshed": False,
        "disk": disk,
        "slots": sorted_rows,
        "metrics": metrics.to_obj(),
    }
    if args.format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
    else:
        print(
            f"worktrees={worktree_count} running_agents={running_agent_count} "
            f"leak={'yes' if payload['leak'] else 'no'} disk={disk['state']} "
            f"free={_format_gib(_as_int(disk['free_bytes'], 'disk free bytes'))}"
        )
        for row in sorted_rows:
            reasons = row["reasons"]
            assert isinstance(reasons, list)
            detail = "; ".join(str(reason) for reason in reasons) or "all removal proofs pass"
            if row["cache_error"] is not None:
                detail += f"; cache inspection: {row['cache_error']}"
            release_value = row.get("owner_release")
            if release_value is not None:
                release_obj = _as_mapping(release_value, "audit owner_release")
                detail += f"; {release_obj['summary']}"
            print(f"{row['verdict']}: {row['slot']}: {detail}")
        if args.gate:
            print(f"state={gate_state}")
            print(f"summary={summary}")
            if attention_names:
                print(
                    "ACTION: run 'wrkslots audit --format json' for exact evidence; "
                    "use 'wrkslots recover' for interrupted operations, import live "
                    "unregistered slots, run 'wrkslots remove' only for a slot "
                    "reported DELETABLE, and retire a slot reported RECOVERABLE "
                    "with the recover-absent command its reason names"
                )
            elif unknown_names:
                print(
                    "ACTION: restore the unavailable liveness or process evidence and "
                    "rerun 'wrkslots audit --gate'; do not remove an UNKNOWN slot"
                )
    if not args.gate:
        return 0
    if attention_names:
        return 1
    return 2 if unknown_names else 0


def _cmd_unpushed(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    if args.slot is not None:
        _validate_name(args.slot, "slot")
    with _locked(config.control / "ACTIVE", exclusive=False, wait_seconds=args.wait_lock):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        states, _archives = _validate_global_state(config)
        _assert_command_registry_storage(config, states, args)
        records = [
            record
            for state in states
            if state.machine == config.machine
            for record in state.slots
            if args.slot is None or record.slot == args.slot
        ]
        rows: list[dict[str, object]] = []
        vcs = _GitVcs()
        for record in records:
            for checkout in record.checkouts:
                path = _stored_path(config, checkout.path, "checkout path")
                head = vcs.verify_existing_worktree(
                    _stored_repository_path(config, checkout.repository)[1], path
                )
                branch = vcs.branch(path)
                if branch != checkout.branch:
                    raise Refusal(
                        f"checkout {checkout.name} branch changed: expected "
                        f"{checkout.branch}, found {branch}; preserve it for inspection"
                    )
                remote_authority = vcs.remote_authority(path, checkout.remote)
                if remote_authority.sha256 != checkout.remote_url_sha256:
                    raise Refusal(
                        f"checkout {checkout.name} remote {checkout.remote} URL changed"
                    )
                vcs.fetch_remote(
                    path, checkout.remote, checkout.landed_ref, remote_authority
                )
                vcs.assert_remote_authority(path, checkout.remote, remote_authority)
                containing = vcs.remote_refs_containing(path, checkout.remote, head)
                evidence = _unpushed_evidence(checkout, path, head, vcs)
                rows.append(
                    {
                        "slot": record.slot,
                        "checkout": checkout.name,
                        "head": head,
                        "state": "PUBLISHED" if containing else "UNPUSHED-OR-STALE",
                        "containing_remote_refs": list(containing),
                        "same_named_remote_ref": evidence["same_named_remote_ref"],
                        "touched_files": evidence["touched_files"],
                        "diagnostic_command": (
                            None if containing else evidence["diagnostic_command"]
                        ),
                    }
                )
    payload = {"schema": SCHEMA, "slots": rows}
    if args.format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
    else:
        for row in rows:
            print(f"{row['state']}: {row['slot']}/{row['checkout']} HEAD={row['head']}")
            if row["state"] == "UNPUSHED-OR-STALE":
                if row["same_named_remote_ref"] is None:
                    print("  no same-named remote ref exists; publish the branch")
                else:
                    print(
                        f"  same-named remote ref={row['same_named_remote_ref']}; two readings: "
                        "genuinely unpushed or stale after remote rebase"
                    )
                    print(
                        f"  compare={row['diagnostic_command']} (empty output means content present)"
                    )
    return 0


def _status_record(
    config: Config,
    record: ActiveRecord,
    *,
    hold_result: _HoldResult,
    tolerate_hold_error: bool = False,
    storage_inconsistencies: Sequence[StorageInconsistency] = (),
    owner_release: tuple[_OwnerRelease, str | None] | None = None,
) -> dict[str, object]:
    process_state, process_detail = _process_state(record.owner)
    age, expired = _heartbeat_diagnosis(record)
    value = _record_to_obj(record)
    if owner_release is not None:
        value["owner_release"] = _owner_release_obj(*owner_release)
    value["owner_state"] = process_state
    value["owner_detail"] = process_detail
    value["heartbeat_age_seconds"] = int(age)
    value["heartbeat_expired"] = expired
    hold = hold_result.value
    hold_error = hold_result.error
    if hold_error is not None and not tolerate_hold_error:
        raise Refusal(hold_error)
    value["held"] = hold is not None
    value["hold_reason"] = None if hold is None else hold["reason"]
    value["hold_error"] = hold_error
    value["storage_inconsistencies"] = [
        item.to_obj() for item in storage_inconsistencies
    ]
    return value


def _slot_findings(
    config: Config,
    states: Sequence[ActiveState],
    hold_results: Mapping[tuple[str, str], _HoldResult],
) -> list[dict[str, object]]:
    """Every storage and operational diagnosis, without authorizing mutation."""

    findings = [
        item.to_obj()
        for item in _registry_storage_inconsistencies(
            config, states, tolerate_unavailable_repositories=True
        )
    ]

    def note(kind: str, slot: str | None, machine: str | None, detail: str) -> None:
        findings.append(
            {
                "kind": kind,
                "scope": "operational",
                "slot": slot,
                "slot_type": None,
                "machine": machine,
                "checkout": None,
                "detail": detail,
                "remedy": "inspect the named condition; diagnosis alone authorizes no mutation",
            }
        )

    releases = _owner_release_states(config, states)
    for state in states:
        for record in state.slots:
            hold_result = hold_results[(record.machine, record.slot)]
            if hold_result.error is not None:
                note("invalid-hold", record.slot, state.machine, hold_result.error)
            process_state, process_detail = _process_state(record.owner)
            if process_state == "dead":
                note(
                    "dead-owner", record.slot, state.machine,
                    f"recorded owner is not running ({process_detail}); the slot "
                    "is held by a row whose owner has exited",
                )
            released = releases.get((record.machine, record.slot))
            if released is not None:
                release, void_reason = released
                if void_reason is None:
                    note(
                        "owner-released", record.slot, state.machine,
                        f"{_owner_release_summary(release)} (event "
                        f"{release.sequence}, generation {release.generation}); "
                        "remove no longer waits for the owner's exit or the "
                        "heartbeat time-to-live, and still requires the handoff "
                        "read and an unused slot",
                    )
                else:
                    note(
                        "owner-release-void", record.slot, state.machine,
                        f"release at {release.recorded_at} (event "
                        f"{release.sequence}) no longer applies: {void_reason}",
                    )

    for path in _outstanding_journals(config):
        note("unfinished-journal", None, None, f"recovery required: {path.name}")

    # `status` refuses outright on a partial atomic update. Diagnosis reports
    # it instead, because an operator looking at a wedged registry needs to see
    # the interrupted write alongside everything else, not in place of it.
    leftovers = sorted(config.control.glob("ACTIVE.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ARCHIVED.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ACTIVE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("CREATE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("FINISH.*.journal.tmp.*"))
    for event_directory in sorted(config.control.glob("EVENTS.*")):
        if event_directory.is_dir() and not event_directory.is_symlink():
            leftovers += sorted(event_directory.glob("*.json.tmp.*"))
    for path in leftovers:
        note(
            "partial-atomic-update", None, None,
            f"interrupted write left {path.name}; preserve it and run "
            "'wrkslots recover'",
        )

    cap = config.max_active_slots
    mine = [r for s in states if s.machine == config.machine for r in s.slots]
    if cap is not None and len(mine) > cap:
        note(
            "cap-breach", None, config.machine,
            f"{len(mine)} active slot(s) against max_active_slots={cap} "
            f"(excess {len(mine) - cap})",
        )
    return findings


def _cmd_doctor(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    with _locked(
        config.control / "ACTIVE", exclusive=False, wait_seconds=args.wait_lock
    ):
        all_states, _archives = _validate_global_state(
            config, require_repository=False
        )
        states = (
            all_states
            if args.all_machines
            else [state for state in all_states if state.machine == config.machine]
        )
        hold_results = _load_record_holds(config, all_states)
        all_findings = _slot_findings(config, all_states, hold_results)
        doctor_releases = _owner_release_states(config, states)
        findings = (
            all_findings
            if args.all_machines
            else [
                item
                for item in all_findings
                if item["machine"] is None or item["machine"] == config.machine
            ]
        )
        rows = [
            _status_record(
                config,
                record,
                hold_result=hold_results[(record.machine, record.slot)],
                tolerate_hold_error=True,
                owner_release=doctor_releases.get((record.machine, record.slot)),
            )
            for state in states
            for record in state.slots
        ]
    cap = config.max_active_slots
    if args.format == "json":
        print(
            json.dumps(
                {
                    "schema": SCHEMA,
                    "project_root": str(config.root),
                    "worktrees_dir": str(config.worktrees),
                    "control_dir": str(config.control),
                    "layout": config.layout,
                    "machines": [state.machine for state in states],
                    "event_counts": {
                        state.machine: len(_load_events(config, state.machine))
                        for state in states
                    },
                    "active": rows,
                    "max_active_slots": cap,
                    "findings": findings,
                },
                indent=2,
                sort_keys=True,
            )
        )
    else:
        print(
            f"project={config.root} worktrees={config.worktrees} control={config.control} "
            f"layout={config.layout} "
            f"active={len(rows)} cap={'none' if cap is None else cap} "
            f"findings={len(findings)}"
        )
        counts: dict[str, int] = {}
        for item in findings:
            kind = str(item["kind"])
            counts[kind] = counts.get(kind, 0) + 1
        for kind in sorted(counts):
            print(f"  {counts[kind]:4d}  {kind}")
        for item in findings:
            where = item["slot"] or "-"
            print(f"{item['kind']}: {where}: {item['detail']}")
    # Diagnosis never authorizes anything, so it does not fail the caller for
    # finding problems; a non-zero exit here would push callers toward `|| true`
    # and lose the real refusals too.
    return 0


def _cmd_status(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    with _locked(
        config.control / "ACTIVE", exclusive=False, wait_seconds=args.wait_lock
    ):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        all_states, _archives = _validate_global_state(
            config, require_repository=False
        )
        storage_inconsistencies = _registry_storage_inconsistencies(
            config, all_states, tolerate_unavailable_repositories=True
        )
        states = (
            all_states
            if args.all_machines
            else [state for state in all_states if state.machine == config.machine]
        )
        hold_results = _load_record_holds(config, states)
        status_releases = _owner_release_states(config, states)
        ordinary_journals = _outstanding_journals(config)
        seal_journals = _validate_batch_seal_journals(config)
        journals = [
            path.name for path in (*ordinary_journals, *seal_journals)
        ]
        storage_inconsistencies = (
            *storage_inconsistencies,
            *_journal_inconsistencies(
                config, ordinary_journals
            ),
        )
        records = [
            _status_record(
                config,
                record,
                hold_result=hold_results[(record.machine, record.slot)],
                storage_inconsistencies=tuple(
                    item
                    for item in storage_inconsistencies
                    if item.machine == record.machine and item.slot == record.slot
                ),
                owner_release=status_releases.get((record.machine, record.slot)),
            )
            for state in states
            for record in state.slots
            if args.slot is None or record.slot == args.slot
        ]
    if args.format == "json":
        print(
            json.dumps(
                {
                    "schema": SCHEMA,
                    "project_root": str(config.root),
                    "worktrees_dir": str(config.worktrees),
                    "control_dir": str(config.control),
                    "layout": config.layout,
                    "machines": [state.machine for state in states],
                    "active": records,
                    "journals": journals,
                    "registry_storage_state": (
                        "inconsistent" if storage_inconsistencies else "consistent"
                    ),
                    "registry_storage_inconsistencies": [
                        item.to_obj() for item in storage_inconsistencies
                    ],
                },
                indent=2,
                sort_keys=True,
            )
        )
        return 0
    print(
        f"project={config.root} worktrees={config.worktrees} control={config.control} "
        f"layout={config.layout} "
        f"active={len(records)} journals={len(journals)} "
        f"events={sum(len(_load_events(config, state.machine)) for state in states)} "
        f"registry_storage={'INCONSISTENT' if storage_inconsistencies else 'CONSISTENT'} "
        f"inconsistencies={len(storage_inconsistencies)}"
    )
    if journals:
        for journal in journals:
            print(f"RECOVERY REQUIRED: {journal}")
    for value in records:
        owner_state = _as_str(value["owner_state"], "status owner_state")
        expired = value["heartbeat_expired"] is True
        row_inconsistencies = _as_list(
            value["storage_inconsistencies"], "status storage_inconsistencies"
        )
        print(
            f"{value['machine']}/{value['slot']}: type={value['slot_type']} "
            f"agent={value['agent']} task={value['task']} "
            f"generation={value['generation']} owner={owner_state} "
            f"heartbeat_age={value['heartbeat_age_seconds']}s expired={'yes' if expired else 'no'} "
            f"held={'yes' if value['held'] is True else 'no'} "
            f"inconsistencies={len(row_inconsistencies)}"
        )
        release_value = value.get("owner_release")
        if release_value is not None:
            release_obj = _as_mapping(release_value, "status owner_release")
            print(
                f"  {release_obj['summary']} "
                f"(event {release_obj['event_sequence']})"
            )
    for item in storage_inconsistencies:
        print(f"INCONSISTENT {_format_storage_inconsistency(item)}")
        print(f"  REMEDY: {item.remedy}")
    return 0


def _finish_journal_payload(
    config: Config,
    record: ActiveRecord,
    *,
    finished_at: str,
    removed: Sequence[str],
    phase: str,
    finish: _FinishContext,
) -> dict[str, object]:
    archive_id = f"{config.machine}:{record.slot}:{record.generation}:{finished_at}"
    slot_path = _slot_directory(config, record.slot, record.slot_type)
    slot_parent = slot_path.parent
    if finish.private_cleanup is None:
        try:
            original_mode = stat.S_IMODE(
                slot_path.stat(follow_symlinks=False).st_mode
            )
        except OSError as exc:
            raise Refusal(
                f"cannot inspect slot permissions before fencing: {slot_path}: {exc}"
            ) from exc
    else:
        if finish.private_cleanup.target.path != slot_path:
            raise StateError("private cleanup context does not match its slot path")
        original_mode = finish.private_cleanup.target.original_mode
    fenced = (
        slot_parent
        / f".{record.slot}.fenced.{record.generation}.{uuid.uuid4().hex}"
    )
    payload: dict[str, object] = {
        "schema": SCHEMA,
        "kind": "finish",
        "machine": config.machine,
        "slot": record.slot,
        "mode": finish.mode,
        "actor": finish.actor,
        "finished_at": finished_at,
        "archive_id": archive_id,
        "phase": phase,
        "fenced": fenced.relative_to(config.root).as_posix(),
        "original_mode": original_mode,
        "removed": list(removed),
        "salvage": [dict(item) for item in finish.salvage],
        "validate_complete": finish.validate_complete,
        "record": _record_to_obj(record),
    }
    if finish.private_cleanup is not None:
        payload["private_census_identity"] = list(
            finish.private_cleanup.target.identity
        )
    if finish.validation_removal_proof is not None:
        payload["validation_removal_proof"] = _validation_removal_proof_to_obj(
            finish.validation_removal_proof
        )
    return payload


def _archive_entry(
    journal: Mapping[str, object], record: ActiveRecord
) -> dict[str, object]:
    if record.handoff is None:
        raise StateError("cannot archive a slot without durable reclaim evidence")
    value: dict[str, object] = {
        "archive_id": _as_str(journal["archive_id"], "journal.archive_id"),
        "slot": record.slot,
        "agent": record.agent,
        "task": record.task,
        "purpose": record.purpose,
        "slot_type": record.slot_type,
        "machine": record.machine,
        "generation": record.generation,
        "created_at": record.created_at,
        "finished_at": _as_str(journal["finished_at"], "journal.finished_at"),
        "mode": _as_str(journal["mode"], "journal.mode"),
        "actor": _as_str(journal["actor"], "journal.actor"),
        "physical_storage": "removed",
        "validation": list(record.handoff.validation),
        "limitations": list(record.handoff.limitations),
        "continuation": record.handoff.continuation,
        "salvage": [
            dict(_as_mapping(item, "finish journal.salvage entry"))
            for item in _as_list(journal.get("salvage", []), "finish journal.salvage")
        ],
        "checkouts": [_checkout_to_obj(item) for item in record.checkouts],
    }
    if record.layout is not None:
        value["layout"] = record.layout
    if record.import_source is not None:
        value["import_source"] = _import_source_to_obj(record.import_source)
    return value


def _append_archive_once(
    config: Config,
    archive: ArchiveState,
    entry: dict[str, object],
    *,
    action: str = "slot-archived",
    evidence: Mapping[str, object] | None = None,
    require_repository: bool = True,
) -> ArchiveState:
    archive_id = _as_str(entry["archive_id"], "archive entry archive_id")
    for existing in archive.records:
        if existing.get("archive_id") == archive_id:
            if not _json_equal(existing, entry):
                raise StateError(
                    f"archive_id {archive_id!r} already exists with different content"
                )
            _atomic_write_json(_archive_path(config), _archive_to_obj(archive))
            return archive
    updated = ArchiveState(
        machine=archive.machine,
        revision=archive.revision + 1,
        records=(*archive.records, entry),
        absent_validate_recoveries=archive.absent_validate_recoveries,
        absent_agent_recoveries=archive.absent_agent_recoveries,
    )
    _write_archive_state(
        config,
        updated,
        action=action,
        slot=_as_str(entry["slot"], "archive entry slot"),
        evidence={"archive_id": archive_id} if evidence is None else evidence,
        require_repository=require_repository,
    )
    return updated


def _finish_fenced_slot(
    config: Config, record: ActiveRecord, journal: Mapping[str, object]
) -> Path:
    relative, fenced = _relative_inside(
        config.root,
        _as_str(journal["fenced"], "finish journal.fenced"),
        "finish journal fenced path",
    )
    del relative
    prefix = f".{record.slot}.fenced.{record.generation}."
    slot_parent = _slot_directory(config, record.slot, record.slot_type).parent
    if (
        fenced.parent != slot_parent
        or not fenced.name.startswith(prefix)
        or len(fenced.name) != len(prefix) + 32
        or not re.fullmatch(r"[0-9a-f]{32}", fenced.name.removeprefix(prefix))
    ):
        raise StateError("finish journal fenced path does not match its slot generation")
    return fenced


def _checkout_at_slot(
    config: Config, record: ActiveRecord, checkout: Checkout, slot_path: Path
) -> tuple[Checkout, Path]:
    path = (
        slot_path
        if _record_layout(config, record) == "flat"
        else slot_path / checkout.name
    )
    relative = path.relative_to(config.root).as_posix()
    return dataclasses.replace(checkout, path=relative), path


def _single_validation_checkout(
    config: Config, record: ActiveRecord, slot_path: Path
) -> tuple[Path, Path]:
    """Return canonical and relocated paths for a proof-bound validation checkout."""

    if record.slot_type != "validate" or len(record.checkouts) != 1:
        raise Refusal(
            "validation removal proof requires one exact checkout in a validate slot"
        )
    checkout = record.checkouts[0]
    canonical = _stored_path(config, checkout.path, "validation checkout path")
    _moved, active = _checkout_at_slot(config, record, checkout, slot_path)
    return canonical, active


def _repair_checkout_at_slot(
    config: Config,
    record: ActiveRecord,
    checkout: Checkout,
    slot_path: Path,
    vcs: _GitVcs,
) -> Path:
    moved, path = _checkout_at_slot(config, record, checkout, slot_path)
    _repair_registration_at_slot(config, record, checkout, slot_path, vcs)
    current = _assert_checkout_safe(config, moved, vcs)
    if dataclasses.replace(current, path=checkout.path) != checkout:
        raise Refusal(
            f"fenced checkout {checkout.name} changed after finish was prepared; preserve it for inspection"
        )
    return path


def _declared_initialized_submodules(checkout: Path) -> tuple[Path, ...]:
    found: list[Path] = []

    def visit(repository: Path) -> None:
        modules = repository / ".gitmodules"
        if not modules.exists() and not modules.is_symlink():
            return
        if modules.is_symlink() or not modules.is_file():
            raise Refusal(f"nested repository has an unsafe .gitmodules file: {modules}")
        parser = configparser.RawConfigParser(interpolation=None, strict=True)
        try:
            with modules.open("r", encoding="utf-8") as handle:
                parser.read_file(handle)
        except (OSError, UnicodeError, configparser.Error) as exc:
            raise Refusal(f"cannot read nested repository declarations {modules}: {exc}") from exc
        for section in parser.sections():
            if not section.startswith('submodule "') or not parser.has_option(section, "path"):
                continue
            raw = parser.get(section, "path")
            relative = Path(raw)
            if relative.is_absolute() or not relative.parts or ".." in relative.parts:
                raise Refusal(f"unsafe submodule path {raw!r} in {modules}")
            nested = repository / relative
            _ensure_no_symlink_components(repository, nested, "nested repository")
            if not nested.exists() and not nested.is_symlink():
                continue
            if nested.is_symlink() or not nested.is_dir():
                raise Refusal(f"nested repository path is unsafe: {nested}")
            git_file = nested / ".git"
            if not git_file.exists() and not git_file.is_symlink():
                continue
            found.append(nested)
            visit(nested)

    visit(checkout)
    return tuple(found)


def _repair_nested_repositories(checkout: Path, vcs: _GitVcs) -> None:
    for nested in _declared_initialized_submodules(checkout):
        vcs.repair_nested_repository(nested)


def _repair_registration_at_slot(
    config: Config,
    record: ActiveRecord,
    checkout: Checkout,
    slot_path: Path,
    vcs: _GitVcs,
) -> Path:
    _moved, path = _checkout_at_slot(config, record, checkout, slot_path)
    _relative, repository = _stored_repository_path(config, checkout.repository)
    vcs.repair_worktree(repository, path)
    _repair_nested_repositories(path, vcs)
    return path


def _remove_fenced_directory(config: Config, fenced_slot: Path) -> None:
    if fenced_slot.exists():
        try:
            _remove_slot_directory(config, fenced_slot)
        except OSError as exc:
            raise Refusal(
                f"fenced slot directory is not empty after Git removal: {fenced_slot}: {exc}"
            ) from exc
    _fsync_directory(fenced_slot.parent)


def _assert_cleanup_fence_root_trusted(
    config: Config, fenced_slot: Path, *, managed_root: Path | None = None
) -> None:
    """Require a path namespace that another ordinary UID cannot rewrite."""

    root = config.root if managed_root is None else managed_root
    try:
        relative_parent = fenced_slot.parent.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"cleanup fence escapes its managed root: {fenced_slot}") from exc
    current = root
    for component in (None, *relative_parent.parts):
        if component is not None:
            current /= component
        try:
            metadata = current.stat(follow_symlinks=False)
        except OSError as exc:
            raise Refusal(f"cannot inspect cleanup fence root {current}: {exc}") from exc
        mode = stat.S_IMODE(metadata.st_mode)
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or current.is_symlink()
            or metadata.st_uid != os.getuid()
            or mode & 0o022
        ):
            raise Refusal(
                f"cleanup fence root is not an owner-controlled directory: {current}; "
                "the owner must own it and group/other write bits must be clear"
            )


def _seal_cleanup_path_private(
    config: Config,
    fenced_slot: Path,
    *,
    before_seal: Callable[[int, _PrivateCleanupIdentity], None] | None = None,
    managed_root: Path | None = None,
) -> tuple[int, _PrivateCleanupIdentity]:
    """Seal one cleanup path and return its prior mode and stable identity."""

    _assert_cleanup_fence_root_trusted(
        config, fenced_slot, managed_root=managed_root
    )
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        descriptor = os.open(fenced_slot, flags)
    except OSError as exc:
        raise Refusal(f"cannot safely open cleanup fence {fenced_slot}: {exc}") from exc
    original_mode: int | None = None
    mode_changed = False
    try:
        try:
            metadata = os.fstat(descriptor)
            if not stat.S_ISDIR(metadata.st_mode) or metadata.st_uid != os.getuid():
                raise Refusal(
                    f"cleanup fence is not an owner-controlled directory: {fenced_slot}"
                )
            original_mode = stat.S_IMODE(metadata.st_mode)
            identity = _fd_private_cleanup_identity(descriptor, str(fenced_slot))
            if before_seal is not None:
                before_seal(original_mode, identity)
            os.fchmod(descriptor, 0o700)
            mode_changed = True
            metadata = os.fstat(descriptor)
            if stat.S_IMODE(metadata.st_mode) != 0o700:
                raise Refusal(f"cleanup fence did not become private: {fenced_slot}")
            path_metadata = fenced_slot.stat(follow_symlinks=False)
            if (path_metadata.st_dev, path_metadata.st_ino) != (
                metadata.st_dev,
                metadata.st_ino,
            ):
                raise Refusal(
                    f"cleanup fence identity changed while sealing it: {fenced_slot}"
                )
            os.fsync(descriptor)
            if identity[:2] != (metadata.st_dev, metadata.st_ino):
                raise Refusal(
                    f"cleanup fence identity changed after sealing it: {fenced_slot}"
                )
        except BaseException as exc:
            if mode_changed and original_mode is not None:
                try:
                    os.fchmod(descriptor, original_mode)
                    os.fsync(descriptor)
                except OSError as restore_exc:
                    raise Refusal(
                        f"cannot restore cleanup fence permissions after sealing failed at "
                        f"{fenced_slot}: {restore_exc}"
                    ) from exc
            raise
    except OSError as exc:
        raise Refusal(f"cannot seal cleanup fence {fenced_slot}: {exc}") from exc
    finally:
        os.close(descriptor)
    assert original_mode is not None
    return original_mode, identity


def _private_cleanup_path_identity(
    config: Config,
    path: Path,
    *,
    allowed_modes: AbstractSet[int],
    managed_root: Path | None = None,
) -> tuple[int, int, int, str]:
    """Prove an owned path's mode and return its stable directory identity."""

    _assert_cleanup_fence_root_trusted(
        config, path, managed_root=managed_root
    )
    try:
        metadata = path.stat(follow_symlinks=False)
    except OSError as exc:
        raise Refusal(f"cannot inspect private cleanup path {path}: {exc}") from exc
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or path.is_symlink()
        or metadata.st_uid != os.getuid()
        or stat.S_IMODE(metadata.st_mode) not in allowed_modes
    ):
        expected = " or ".join(f"{mode:o}" for mode in sorted(allowed_modes))
        raise Refusal(
            f"cleanup path is no longer an owned directory with mode {expected}: {path}"
        )
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise Refusal(f"cannot safely open private cleanup path {path}: {exc}") from exc
    try:
        identity = _fd_private_cleanup_identity(descriptor, str(path))
    finally:
        os.close(descriptor)
    if identity[:2] != (metadata.st_dev, metadata.st_ino):
        raise Refusal(f"cleanup path identity changed during inspection: {path}")
    return identity


def _private_cleanup_fence_identity(
    config: Config,
    fenced_slot: Path,
    *,
    managed_root: Path | None = None,
) -> tuple[int, int, int, str]:
    """Prove the private fence invariant and return its stable directory identity."""

    return _private_cleanup_path_identity(
        config,
        fenced_slot,
        allowed_modes={0o700},
        managed_root=managed_root,
    )


def _upgrade_legacy_private_cleanup_identity(
    config: Config,
    record: ActiveRecord,
    path: Path,
    original_mode: int,
    expected: _PrivateCleanupIdentity,
    *,
    recovery_kind: _ValidateBatchSealRecoveryKind,
) -> tuple[int, int, int, str]:
    """Enroll a pre-file-handle journal only after revalidating its whole checkout."""

    if len(expected) != 3:
        raise StateError("only a legacy mount-id identity can be upgraded")
    observed = _private_cleanup_path_identity(
        config, path, allowed_modes={0o700, original_mode}
    )
    if observed[:2] != expected[:2]:
        raise Refusal(f"legacy private cleanup path identity changed: {path}")

    canonical = _slot_directory(config, record.slot, record.slot_type)
    vcs = _GitVcs()
    if recovery_kind is _ValidateBatchSealRecoveryKind.PAIRED_FINISH:
        if path == canonical:
            slot_path, final_checkouts = _handoff_preconditions(
                config, record, vcs, refresh_remote=False
            )
            if slot_path != path or tuple(
                checkout.head for checkout in final_checkouts
            ) != tuple(checkout.head for checkout in record.checkouts):
                raise Refusal(
                    f"legacy private cleanup path no longer matches its recorded "
                    f"checkout: {path}"
                )
        else:
            expected_fenced = path.parent == canonical.parent and path.name.startswith(
                f".{record.slot}.fenced.{record.generation}."
            )
            if not expected_fenced:
                raise Refusal(
                    f"legacy private cleanup path is not the recorded slot: {path}"
                )
            for checkout in record.checkouts:
                moved, _moved_path = _checkout_at_slot(
                    config, record, checkout, path
                )
                current = _assert_checkout_safe(
                    config, moved, vcs, refresh_remote=False
                )
                if current.head != moved.head:
                    raise Refusal(
                        f"legacy private cleanup path no longer matches checkout "
                        f"{checkout.name}: {path}"
                    )
        return observed

    if path == canonical:
        if _assert_slot_contents(config, record) != path:
            raise StateError("legacy private cleanup path resolved to another slot")
    else:
        expected_fenced = path.parent == canonical.parent and path.name.startswith(
            f".{record.slot}.fenced.{record.generation}."
        )
        if not expected_fenced:
            raise Refusal(f"legacy private cleanup path is not the recorded slot: {path}")
    for checkout in record.checkouts:
        moved, moved_path = _checkout_at_slot(config, record, checkout, path)
        _relative, repository = _stored_repository_path(config, moved.repository)
        head = vcs.verify_existing_worktree(repository, moved_path)
        branch = vcs.branch(moved_path)
        remote_url_sha256 = vcs.remote_url_sha256(moved_path, moved.remote)
        if (
            head != moved.head
            or branch != moved.branch
            or remote_url_sha256 != moved.remote_url_sha256
        ):
            raise Refusal(
                f"legacy private cleanup path no longer matches checkout "
                f"{checkout.name}: {path}"
            )
    return observed


def _restore_finish_original_mode(
    original: Path, journal: Mapping[str, object]
) -> None:
    raw_mode = journal.get("original_mode")
    if raw_mode is None:
        return
    mode = _as_int(raw_mode, "finish journal.original_mode")
    if mode > 0o7777:
        raise StateError("finish journal.original_mode exceeds permission bits")
    try:
        os.chmod(original, mode, follow_symlinks=False)
    except OSError as exc:
        raise Refusal(f"cannot restore slot permissions at {original}: {exc}") from exc


def _finish_private_census_identity(
    journal: Mapping[str, object],
) -> _PrivateCleanupIdentity | None:
    raw = journal.get("private_census_identity")
    if raw is None:
        return None
    return _private_cleanup_identity_from_obj(
        raw, "finish journal.private_census_identity"
    )


def _restore_private_cleanup_path(
    path: Path,
    original_mode: int,
    expected_identity: _PrivateCleanupIdentity,
    *,
    allow_missing: bool = True,
) -> None:
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError:
        if allow_missing:
            return
        raise Refusal(f"private cleanup path disappeared before mode restoration: {path}")
    except OSError as exc:
        raise Refusal(f"cannot open private cleanup path {path}: {exc}") from exc
    try:
        identity = _fd_private_cleanup_identity(descriptor, str(path))
        if identity != expected_identity:
            raise Refusal(
                f"private cleanup path identity changed before mode restoration: {path}"
            )
        os.fchmod(descriptor, original_mode)
        os.fsync(descriptor)
    except OSError as exc:
        raise Refusal(f"cannot restore cleanup path permissions at {path}: {exc}") from exc
    finally:
        os.close(descriptor)


def _reestablish_private_cleanup_fence(
    config: Config,
    path: Path,
    original_mode: int,
    expected_identity: _PrivateCleanupIdentity,
    *,
    managed_root: Path | None = None,
) -> None:
    """Verify an interrupted target and re-seal an exactly restored mode."""

    _assert_cleanup_fence_root_trusted(config, path, managed_root=managed_root)
    try:
        metadata = path.stat(follow_symlinks=False)
    except OSError as exc:
        raise Refusal(f"cannot inspect interrupted cleanup fence {path}: {exc}") from exc
    if not stat.S_ISDIR(metadata.st_mode) or path.is_symlink():
        raise Refusal(f"interrupted cleanup fence is not a real directory: {path}")
    mode = stat.S_IMODE(metadata.st_mode)
    if mode == 0o700:
        if (
            _private_cleanup_fence_identity(
                config, path, managed_root=managed_root
            )
            != expected_identity
        ):
            raise Refusal(f"interrupted cleanup fence identity changed: {path}")
        return
    if mode != original_mode:
        raise Refusal(
            f"interrupted cleanup fence mode changed at {path}: expected "
            f"{original_mode:o} or 700, found {mode:o}"
        )

    def verify_before_seal(
        observed_mode: int, observed_identity: _PrivateCleanupIdentity
    ) -> None:
        if observed_mode != original_mode or observed_identity != expected_identity:
            raise Refusal(f"interrupted cleanup fence identity changed: {path}")

    sealed_mode, sealed_identity = _seal_cleanup_path_private(
        config,
        path,
        before_seal=verify_before_seal,
        managed_root=managed_root,
    )
    if sealed_mode != original_mode or sealed_identity != expected_identity:
        raise StateError(f"interrupted cleanup fence changed while resealing: {path}")


def _private_cleanup_target_to_obj(
    config: Config,
    slot: str,
    generation: int,
    target: _PrivateCleanupTarget,
) -> dict[str, object]:
    return {
        "slot": slot,
        "generation": generation,
        "path": target.path.relative_to(config.root).as_posix(),
        "original_mode": target.original_mode,
        "identity": list(target.identity),
    }


def _private_cleanup_target_from_obj(
    config: Config, value: object, label: str
) -> tuple[str, int, _PrivateCleanupTarget]:
    raw = _as_mapping(value, label)
    _exact_keys(
        raw,
        {"slot", "generation", "path", "original_mode", "identity"},
        set(),
        label,
    )
    slot = _validate_name(_as_str(raw["slot"], f"{label}.slot"), "slot")
    generation = _as_int(raw["generation"], f"{label}.generation", minimum=1)
    _relative, path = _relative_inside(
        config.root, _as_str(raw["path"], f"{label}.path"), f"{label}.path"
    )
    expected = _slot_directory(config, slot, "validate")
    if path != expected:
        raise StateError(f"{label}.path does not match validation slot {slot}")
    original_mode = _as_int(raw["original_mode"], f"{label}.original_mode")
    if original_mode > 0o7777:
        raise StateError(f"{label}.original_mode exceeds permission bits")
    identity_values = _as_list(raw["identity"], f"{label}.identity")
    identity = _private_cleanup_identity_from_obj(identity_values, f"{label}.identity")
    return slot, generation, _PrivateCleanupTarget(path, original_mode, identity)


def _validate_batch_seal_journal(
    config: Config, path: Path, value: object
) -> tuple[Mapping[str, object], tuple[tuple[str, int, _PrivateCleanupTarget], ...]]:
    raw = _as_mapping(value, "validation-batch seal journal")
    _exact_keys(
        raw,
        {"schema", "kind", "machine", "created_at", "actor", "targets"},
        set(),
        "validation-batch seal journal",
    )
    if _as_int(raw["schema"], "validation-batch seal journal.schema") != (
        _VALIDATE_BATCH_SEAL_SCHEMA
    ):
        raise StateError("unsupported validation-batch seal journal schema")
    if raw["kind"] != "validate-batch-seal":
        raise StateError("validation-batch seal journal has the wrong operation kind")
    machine = _validate_name(
        _as_str(raw["machine"], "validation-batch seal journal.machine"),
        "machine",
    )
    if path != _validate_batch_seal_journal_path(config, machine):
        raise StateError("validation-batch seal journal filename does not match its machine")
    _parse_timestamp(
        _as_str(raw["created_at"], "validation-batch seal journal.created_at"),
        "validation-batch seal journal.created_at",
    )
    if _identity_from_obj(raw["actor"], "validation-batch seal journal.actor") is None:
        raise StateError("validation-batch seal journal has no actor")
    targets = tuple(
        _private_cleanup_target_from_obj(
            config, item, f"validation-batch seal journal.targets[{index}]"
        )
        for index, item in enumerate(
            _as_list(raw["targets"], "validation-batch seal journal.targets")
        )
    )
    if len(targets) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise StateError("validation-batch seal journal exceeds the batch limit")
    if len({slot for slot, _generation, _target in targets}) != len(targets):
        raise StateError("validation-batch seal journal repeats a slot")
    return raw, targets


def _load_validate_batch_seal_journal(
    config: Config,
) -> tuple[Path, Mapping[str, object], tuple[tuple[str, int, _PrivateCleanupTarget], ...]] | None:
    paths = _validate_batch_seal_journals(config)
    if not paths:
        return None
    if len(paths) != 1:
        raise StateError(
            "multiple validation-batch seal journals are present; recover each machine "
            "before continuing"
        )
    path = paths[0]
    raw, targets = _validate_batch_seal_journal(
        config, path, _read_json(path, "validation-batch seal journal")
    )
    if path != _validate_batch_seal_journal_path(config):
        raise Refusal(
            f"validation-batch seal journal belongs to {raw['machine']}; rerun with "
            f"--machine {raw['machine']}"
        )
    return path, raw, targets


def _write_validate_batch_seal_journal(
    config: Config, payload: Mapping[str, object]
) -> None:
    path = _validate_batch_seal_journal_path(config)
    _validate_batch_seal_journal(config, path, payload)
    _atomic_write_json(path, dict(payload))


def _write_owned_validate_batch_seal_journal(
    config: Config,
    payload: Mapping[str, object],
    owned: list[_RegularFileIdentity],
) -> None:
    """Write this invocation's seal and remember the exact file published.

    The previous identity is kept until the new payload is on disk, so a
    replacement that fails still leaves this invocation owning the seal it
    wrote before. A failure after the payload was published, including one
    reading it back, adopts that file only if it holds exactly the payload
    written here.
    """

    path = _validate_batch_seal_journal_path(config)
    label = "validation-batch seal journal"
    try:
        _write_validate_batch_seal_journal(config, payload)
        owned[:] = [_read_regular_file_identity(path, label, 1024 * 1024)[1]]
    except BaseException:
        try:
            contents, identity = _read_regular_file_identity(path, label, 1024 * 1024)
            published = _json_equal(json.loads(contents), dict(payload))
        except (ValueError, Refusal):
            published = False
        if published:
            owned[:] = [identity]
        raise


def _validate_batch_seal_is_owned(
    config: Config, owned: Sequence[_RegularFileIdentity]
) -> bool:
    """Return whether the current seal is exactly the file last written by us."""

    path = _validate_batch_seal_journal_path(config)
    if not owned or (not path.exists() and not path.is_symlink()):
        return False
    _contents, identity = _read_regular_file_identity(
        path, "validation-batch seal journal", 1024 * 1024
    )
    return identity == owned[-1]


def _assert_validate_batch_seals_disjoint_from_create(
    config: Config,
    *,
    slot: str,
    slot_type: str,
    plan: Sequence[PlannedCheckout],
) -> None:
    """Permit progress beside a seal without reusing any fenced identity."""

    requested_slot_path = _slot_directory(config, slot, slot_type)
    requested_checkout_paths = tuple(
        _stored_path(config, item.destination, "checkout destination")
        for item in plan
    )
    for path in _validate_batch_seal_journals(config):
        _raw, targets = _validate_batch_seal_journal(
            config,
            path,
            _read_json(path, "validation-batch seal journal"),
        )
        for sealed_slot, sealed_generation, target in targets:
            if sealed_slot == slot or _path_is_within(
                requested_slot_path, target.path
            ) or _path_is_within(target.path, requested_slot_path):
                raise Refusal(
                    f"requested slot {slot!r} overlaps validation cleanup seal "
                    f"{path.name} target {sealed_slot!r} generation "
                    f"{sealed_generation}"
                )
            for requested_path in requested_checkout_paths:
                if _path_is_within(requested_path, target.path) or _path_is_within(
                    target.path, requested_path
                ):
                    raise Refusal(
                        f"checkout destination {requested_path} overlaps validation "
                        f"cleanup seal {path.name} target {sealed_slot!r} generation "
                        f"{sealed_generation}"
                    )


def _assert_validate_batch_seals_disjoint_from_record(
    config: Config,
    record: ActiveRecord,
    *,
    action: str,
) -> None:
    """Permit a slot-local mutation only beside disjoint validation seals."""

    requested = _slot_directory(config, record.slot, record.slot_type)
    for path in _validate_batch_seal_journals(config):
        _raw, targets = _validate_batch_seal_journal(
            config,
            path,
            _read_json(path, "validation-batch seal journal"),
        )
        for sealed_slot, sealed_generation, target in targets:
            if sealed_slot == record.slot or _path_is_within(
                requested, target.path
            ) or _path_is_within(target.path, requested):
                raise Refusal(
                    f"{action} target {record.slot!r} overlaps validation cleanup "
                    f"seal {path.name} target {sealed_slot!r} generation "
                    f"{sealed_generation}"
                )


def _assert_validate_cleanup_journals_disjoint_from_record(
    config: Config,
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
    record: ActiveRecord,
    *,
    action: str,
) -> None:
    """Allow a slot-local action beside only an exact disjoint cleanup."""

    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        _assert_no_journal(config)
        return
    _seal_path, _seal_raw, targets = loaded
    paired = _validate_batch_seal_paired_finish(config, targets)
    excluded = (
        frozenset({_journal_path_for_slot(config, paired.slot)})
        if paired is not None
        else frozenset()
    )
    create_rows = _classify_disjoint_create_journals_for_record(
        config,
        states,
        archives,
        record,
        excluded_paths=excluded,
    )
    _recheck_disjoint_create_journals_for_record(
        config,
        create_rows,
        states,
        archives,
        record,
        excluded_paths=excluded,
    )
    if paired is not None:
        paired_path = _slot_directory(config, paired.slot, paired.slot_type)
        record_path = _slot_directory(config, record.slot, record.slot_type)
        if paired.slot == record.slot or _path_is_within(
            paired_path, record_path
        ) or _path_is_within(record_path, paired_path):
            raise Refusal(
                f"{action} target {record.slot!r} overlaps private validation "
                f"finish for {paired.slot!r}"
            )


def _assert_validate_batch_seal_target(
    config: Config,
    record: ActiveRecord,
    original_mode: int,
    identity: _PrivateCleanupIdentity,
) -> None:
    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        raise StateError("private batch removal has no durable seal journal")
    _path, _raw, targets = loaded
    expected_path = _slot_directory(config, record.slot, record.slot_type)
    if not any(
        slot == record.slot
        and generation == record.generation
        and target.path == expected_path
        and target.original_mode == original_mode
        and target.identity == identity
        for slot, generation, target in targets
    ):
        raise StateError(
            f"durable seal journal does not match target {record.slot} generation "
            f"{record.generation}"
        )


def _upgrade_legacy_validate_batch_seal_targets(
    config: Config,
    raw: Mapping[str, object],
    targets: Sequence[tuple[str, int, _PrivateCleanupTarget]],
    records: Mapping[str, ActiveRecord],
    paired_finish: ActiveRecord | None,
) -> tuple[Mapping[str, object], tuple[tuple[str, int, _PrivateCleanupTarget], ...]]:
    """Replace recoverable mount-id identities before restoring any target."""

    upgraded: list[tuple[str, int, _PrivateCleanupTarget]] = []
    changed = False
    for slot, generation, target in targets:
        record = records.get(slot)
        if (
            len(target.identity) == 3
            and record is not None
            and record.generation == generation
            and record.slot_type == "validate"
            and target.path.exists()
            and not target.path.is_symlink()
        ):
            stable = _upgrade_legacy_private_cleanup_identity(
                config,
                record,
                target.path,
                target.original_mode,
                target.identity,
                recovery_kind=(
                    _ValidateBatchSealRecoveryKind.PAIRED_FINISH
                    if paired_finish is not None
                    and paired_finish.slot == slot
                    and paired_finish.generation == generation
                    else _ValidateBatchSealRecoveryKind.SEAL_ONLY
                ),
            )
            target = dataclasses.replace(target, identity=stable)
            changed = True
        upgraded.append((slot, generation, target))
    if not changed:
        return raw, tuple(upgraded)
    updated = dict(raw)
    updated["targets"] = [
        _private_cleanup_target_to_obj(config, slot, generation, target)
        for slot, generation, target in upgraded
    ]
    _write_validate_batch_seal_journal(config, updated)
    return updated, tuple(upgraded)


def _upgrade_legacy_finish_seal_identity(
    config: Config,
    raw: Mapping[str, object],
    record: ActiveRecord,
    *,
    journal_path: Path,
) -> Mapping[str, object]:
    """Upgrade a paired finish/seal identity before destructive recovery resumes."""

    paired_finish = _assert_validate_batch_seal_recovery_kind(
        config, _ValidateBatchSealRecoveryKind.PAIRED_FINISH
    )
    assert paired_finish is not None
    if _record_to_obj(paired_finish) != _record_to_obj(record):
        raise StateError("paired finish journal record changed during recovery")

    finish_identity = _finish_private_census_identity(raw)
    if finish_identity is None:
        return raw
    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        return raw
    _seal_path, seal_raw, targets = loaded
    canonical = _slot_directory(config, record.slot, record.slot_type)
    matching = [
        (index, target)
        for index, (slot, generation, target) in enumerate(targets)
        if slot == record.slot
        and generation == record.generation
        and target.path == canonical
        and target.original_mode
        == _as_int(raw.get("original_mode"), "finish journal.original_mode")
    ]
    if len(matching) != 1:
        return raw
    target_index, seal_target = matching[0]
    seal_identity = seal_target.identity
    if len(finish_identity) == 4 and len(seal_identity) == 4:
        return raw
    if len(finish_identity) == 3 and len(seal_identity) == 3:
        if finish_identity != seal_identity:
            raise Refusal("legacy finish and validation-batch seal identities disagree")

    fenced = _finish_fenced_slot(config, record, raw)
    present = [
        candidate
        for candidate in (canonical, fenced)
        if candidate.exists() or candidate.is_symlink()
    ]
    if len(present) != 1:
        return raw
    subject = present[0]
    legacy = finish_identity if len(finish_identity) == 3 else seal_identity
    assert len(legacy) == 3
    stable = _upgrade_legacy_private_cleanup_identity(
        config,
        record,
        subject,
        seal_target.original_mode,
        legacy,
        recovery_kind=_ValidateBatchSealRecoveryKind.PAIRED_FINISH,
    )
    for identity in (finish_identity, seal_identity):
        if len(identity) == 4 and identity != stable:
            raise Refusal(
                f"private cleanup path identity changed during legacy upgrade: {subject}"
            )

    upgraded_targets = list(targets)
    upgraded_targets[target_index] = (
        record.slot,
        record.generation,
        dataclasses.replace(seal_target, identity=stable),
    )
    updated_seal = dict(seal_raw)
    updated_seal["targets"] = [
        _private_cleanup_target_to_obj(config, slot, generation, target)
        for slot, generation, target in upgraded_targets
    ]
    _write_validate_batch_seal_journal(config, updated_seal)

    updated_finish = dict(raw)
    updated_finish["private_census_identity"] = list(stable)
    _write_journal(config, updated_finish, journal_path=journal_path)
    return updated_finish


def _finish_journal_record_is_archived(
    config: Config,
    journal: Mapping[str, object],
    record: ActiveRecord,
    states: Sequence[ActiveState],
    archives: Sequence[ArchiveState],
) -> bool:
    """Bind a finish journal to its exact durable ACTIVE or archive record."""

    current = next(
        (
            active
            for state in states
            for active in state.slots
            if active.slot == record.slot
        ),
        None,
    )
    if current is not None:
        if (
            current.machine != config.machine
            or _record_to_obj(current) != _record_to_obj(record)
        ):
            raise StateError("finish journal record does not exactly match ACTIVE")
        return False

    archive_id = _as_str(journal["archive_id"], "finish journal.archive_id")
    matches = [
        archived
        for archive in archives
        if archive.machine == config.machine
        for archived in archive.records
        if archived.get("archive_id") == archive_id
    ]
    if not matches:
        raise StateError(
            "finish journal has neither its active record nor a durable archive entry"
        )
    if len(matches) != 1:
        raise StateError("finish journal archive_id is not unique")
    if not _json_equal(matches[0], _archive_entry(journal, record)):
        raise StateError("durable archive entry differs from the finish journal")
    return True


def _validate_batch_seal_paired_finish(
    config: Config,
    targets: Sequence[tuple[str, int, _PrivateCleanupTarget]],
) -> ActiveRecord | None:
    """Classify the only mutation state allowed beside a private seal.

    A single finish can pair with one exact sealed slot.  Every other durable
    mutation must be a stable create proven disjoint from every still-sealed
    path.  Merely counting journals would make an unrelated create either look
    like the paired finish or strand the private directory forever.
    """

    finish_paths: list[Path] = []
    paired: ActiveRecord | None = None
    paired_raw: Mapping[str, object] | None = None
    for journal_path in _outstanding_journals(config):
        _loaded_path, journal = _load_journal(
            config, selected_path=journal_path
        )
        kind = _as_str(journal.get("kind"), "journal.kind")
        if kind != "finish":
            continue
        finish_paths.append(journal_path)
        record = _record_from_obj(journal.get("record"), "finish journal.record")
        identity = _finish_private_census_identity(journal)
        original_mode = _as_int(
            journal.get("original_mode"), "finish journal.original_mode"
        )
        matches = [
            target
            for slot, generation, target in targets
            if record.machine == config.machine
            and record.slot_type == "validate"
            and record.slot == slot
            and record.generation == generation
            and journal.get("validate_complete") is True
            and not _as_list(journal.get("salvage", []), "finish journal.salvage")
            and target.path == _slot_directory(config, slot, "validate")
            and target.original_mode == original_mode
            and identity is not None
            and (
                identity == target.identity
                or (
                    len(identity) != len(target.identity)
                    and (len(identity) == 3 or len(target.identity) == 3)
                    and identity[:2] == target.identity[:2]
                )
            )
        ]
        if len(matches) != 1:
            raise StateError(
                "finish journal does not exactly pair with one validation-batch "
                "seal target"
            )
        if paired is not None:
            raise StateError(
                "validation-batch seal has multiple paired finish journals"
            )
        paired = record
        paired_raw = journal

    excluded = frozenset(finish_paths)
    if paired_raw is None:
        states, archives = _validate_global_state(
            config, require_repository=False
        )
    else:
        states, archives = _validate_global_state_for_finish_recovery(
            config, paired_raw
        )
        assert paired is not None
        _finish_journal_record_is_archived(
            config, paired_raw, paired, states, archives
        )
    create_rows = _classify_create_journals(
        config, states, archives, excluded_paths=excluded
    )
    active_records = {
        (state.machine, record.slot): record
        for state in states
        for record in state.slots
    }
    for sealed_slot, sealed_generation, target in targets:
        active = active_records.get((config.machine, sealed_slot))
        if active is not None and active.generation == sealed_generation:
            _assert_interrupted_creates_unrelated_to_record(
                config, create_rows, active
            )
        for row in create_rows:
            if row.slot == sealed_slot or _path_is_within(
                row.slot_path, target.path
            ) or _path_is_within(target.path, row.slot_path):
                raise Refusal(
                    f"interrupted create {row.machine}/{row.slot} overlaps sealed "
                    f"validation slot {sealed_slot!r}"
                )
    _assert_create_journal_classifications_stable(
        config, create_rows, states, archives, excluded_paths=excluded
    )
    return paired


def _validate_batch_paired_finish_path(config: Config) -> Path | None:
    """Return the exact finish paired with the current seal, if one exists."""

    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        return None
    _seal_path, _seal_raw, targets = loaded
    paired = _validate_batch_seal_paired_finish(config, targets)
    if paired is None:
        return None
    return _journal_path_for_slot(config, paired.slot)


def _assert_validate_batch_seal_recovery_kind(
    config: Config, recovery_kind: _ValidateBatchSealRecoveryKind
) -> ActiveRecord | None:
    """Require the named recovery boundary to match typed durable state."""

    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        if recovery_kind is _ValidateBatchSealRecoveryKind.PAIRED_FINISH:
            raise StateError(
                "paired-finish validation-batch recovery has no seal journal"
            )
        return None
    _path, _raw, targets = loaded
    paired = _validate_batch_seal_paired_finish(config, targets)
    if recovery_kind is _ValidateBatchSealRecoveryKind.SEAL_ONLY:
        if paired is not None:
            raise StateError(
                "seal-only validation-batch recovery cannot run with a paired "
                "mutation journal"
            )
        return None
    if paired is None:
        raise StateError(
            "paired-finish validation-batch recovery requires one mutation journal "
            "that exactly matches a sealed target"
        )
    return paired


def _recover_validate_batch_seal_journal(
    config: Config,
    *,
    recovery_kind: _ValidateBatchSealRecoveryKind,
    emit: bool = True,
    retain_evidence: bool = False,
) -> bool:
    loaded = _load_validate_batch_seal_journal(config)
    if loaded is None:
        return False
    path, raw, targets = loaded
    states, archives = _validate_global_state(config, require_repository=False)
    paired_finish = _assert_validate_batch_seal_recovery_kind(config, recovery_kind)
    records = {record.slot: record for state in states for record in state.slots}
    raw, targets = _upgrade_legacy_validate_batch_seal_targets(
        config, raw, targets, records, paired_finish
    )
    unresolved: list[dict[str, object]] = []
    errors: list[str] = []
    restored = 0
    absent_rows: list[str] = []
    # A seal only changes a target directory's mode. When that directory is
    # gone there is nothing left to restore, so in a seal-only recovery whose
    # recorded coordinator (the seal's actor, which authorized the removal) is
    # proven dead an absent target is resolved and its ACTIVE
    # row is left exactly as it is, for recover-absent-validate-rows, which
    # re-proves storage, Git and process state before it retires the row.
    # Refusing here deadlocked the two: that command refuses while any seal
    # journal exists, and this one kept the journal for the absent target.
    actor_state, actor_reason = _process_state(
        _identity_from_obj(raw["actor"], "validation-batch seal journal.actor")
    )
    for slot, generation, target in targets:
        current = records.get(slot)
        path_present = target.path.exists() or target.path.is_symlink()
        if current is None:
            archived = any(
                archived.get("slot") == slot
                and archived.get("generation") == generation
                for archive in archives
                for archived in archive.records
            )
            if archived and not path_present:
                continue
            errors.append(
                f"sealed target {slot} has no exact active row and cannot be restored"
            )
            unresolved.append(
                _private_cleanup_target_to_obj(config, slot, generation, target)
            )
            continue
        if current.generation != generation or current.slot_type != "validate":
            errors.append(
                f"sealed target {slot} no longer has validation generation {generation}"
            )
            unresolved.append(
                _private_cleanup_target_to_obj(config, slot, generation, target)
            )
            continue
        if not path_present:
            if paired_finish is None and actor_state == "dead":
                absent_rows.append(slot)
                continue
            errors.append(
                f"sealed target {slot} is absent while its ACTIVE row remains "
                f"(the seal's coordinator is {actor_state}: {actor_reason})"
            )
            unresolved.append(
                _private_cleanup_target_to_obj(config, slot, generation, target)
            )
            continue
        try:
            _restore_private_cleanup_path(
                target.path,
                target.original_mode,
                target.identity,
                allow_missing=False,
            )
        except (Refusal, StateError) as exc:
            errors.append(str(exc))
            unresolved.append(
                _private_cleanup_target_to_obj(config, slot, generation, target)
            )
        else:
            restored += 1
    if unresolved:
        if not retain_evidence:
            updated = dict(raw)
            updated["targets"] = unresolved
            _write_validate_batch_seal_journal(config, updated)
        raise Refusal(
            f"validation-batch seal recovery retained {len(unresolved)} target(s): "
            f"{errors[0]}"
        )
    if retain_evidence:
        if emit:
            print(
                f"restored validation-batch seals: restored={restored}; "
                "durable evidence retained for finish retry"
            )
        return True
    _remove_control_file(path)
    if emit:
        print(
            f"recovered validation-batch seals: restored={restored} "
            f"resolved={len(targets)}"
        )
        for slot in absent_rows:
            print(
                f"sealed target {slot} was already absent, so it had no mode to "
                "restore; its ACTIVE row remains for 'wrkslots "
                "recover-absent-validate-rows'"
            )
    return True


def _rollback_path_fence(
    config: Config,
    record: ActiveRecord,
    journal: dict[str, object],
    vcs: _GitVcs,
    *,
    journal_path: Path,
) -> None:
    # A rollback interrupted partway would leave the removal for 'wrkslots
    # recover', so a remove-agent-batch item budget does not bound it.
    _pause_item_deadline()
    removed = {
        _as_str(item, "journal.removed item")
        for item in _as_list(journal["removed"], "journal.removed")
    }
    if removed:
        raise Refusal("cannot roll back a path fence after a checkout was removed")
    original = _slot_directory(config, record.slot, record.slot_type)
    fenced = _finish_fenced_slot(config, record, journal)
    if original.exists() or original.is_symlink():
        raise Refusal(f"canonical slot reappeared before path-fence rollback: {original}")
    if not fenced.is_dir() or fenced.is_symlink():
        raise Refusal(f"fenced slot is missing or unsafe during rollback: {fenced}")
    try:
        _rename_slot_path(config, fenced, original)
        private_identity = _finish_private_census_identity(journal)
        if private_identity is None:
            _restore_finish_original_mode(original, journal)
        else:
            original_mode = _as_int(
                journal.get("original_mode"), "finish journal.original_mode"
            )
            _restore_private_cleanup_path(
                original, original_mode, private_identity, allow_missing=False
            )
        _fsync_directory(original.parent)
    except OSError as exc:
        raise Refusal(f"cannot restore path fence {fenced} to {original}: {exc}") from exc
    journal["phase"] = "prepared"
    _write_journal(config, journal, journal_path=journal_path)
    for checkout in record.checkouts:
        # Rollback preserves the checkout; it does not authorize deletion. Repair
        # Git's path registration without requiring the content to still match the
        # pre-fence snapshot, because a changed checkout is exactly what must be
        # returned to its canonical path for inspection.
        _repair_registration_at_slot(config, record, checkout, original, vcs)
    _remove_fenced_directory(config, fenced)
    _clear_journal(config, journal, journal_path=journal_path)


def _begin_or_resume_path_fence(
    config: Config,
    record: ActiveRecord,
    journal: dict[str, object],
    vcs: _GitVcs,
    finish: _FinishContext,
    *,
    journal_path: Path,
) -> tuple[dict[str, object], Path]:
    original = _slot_directory(config, record.slot, record.slot_type)
    fenced = _finish_fenced_slot(config, record, journal)
    original_present = original.exists() or original.is_symlink()
    fenced_present = fenced.exists() or fenced.is_symlink()
    newly_fenced = False
    if original_present and fenced_present:
        raise Refusal(f"both canonical and fenced slot paths exist for {record.slot}")
    if original_present:
        if finish.private_cleanup is not None:
            _assert_cleanup_fence_root_trusted(config, fenced)
        removed = _as_list(journal["removed"], "journal.removed")
        if removed:
            raise StateError("finish journal records removals while the canonical slot still exists")
        _slot_path, current_checkouts = _reclaim_preconditions(
            config,
            record,
            vcs,
            finish,
        )
        if current_checkouts != record.checkouts:
            raise Refusal(
                f"slot {record.slot} changed after reclaim was prepared; preserve it and "
                "rerun remove so the changed state is recorded"
            )
        if (
            finish.agent_batch is not None
            and original in finish.agent_batch.image_targets
        ):
            # The fence below mounts the image again, possibly from another
            # device, and the identity scan after it cannot match a process
            # still in the old mount; lsof finds one now, by device and inode.
            _assert_slot_unused(
                original,
                _record_for_slot_use_check(
                    record,
                    validate_complete=finish.validate_complete,
                    allow_live_validate_owner=finish.allow_live_validate_owner,
                    owner_consented=finish.owner_consented,
                ),
                live_use_recheck=finish.live_use_recheck,
                **_agent_batch_use_check(
                    finish.agent_batch, original, before_image_fence=True
                ),
            )
        # A bounded scan above may finish in its termination grace after the
        # remove-agent-batch item budget ran out; nothing is fenced then.
        _item_seconds_left("the path fence")
        try:
            _rename_slot_path(config, original, fenced)
            _fsync_directory(original.parent)
        except OSError as exc:
            raise Refusal(f"cannot establish path fence {original} -> {fenced}: {exc}") from exc
        _interrupt_for_test("after-path-fence-before-journal")
        fenced_present = True
        newly_fenced = True
    # From here until _finish_remove_paths enters the block that rolls the
    # fence back, a refusal would leave the removal for 'wrkslots recover', so
    # a remove-agent-batch item budget does not interrupt the Git
    # registration repair below.
    _pause_item_deadline()
    if not fenced_present:
        return journal, fenced
    if fenced.is_symlink() or not fenced.is_dir():
        raise Refusal(f"fenced slot is missing or unsafe: {fenced}")
    if original.exists() or original.is_symlink():
        raise Refusal(f"canonical slot still exists after path fence: {original}")
    if finish.private_cleanup is not None:
        _seal_cleanup_path_private(config, fenced)
    for checkout in record.checkouts:
        _moved, path = _checkout_at_slot(config, record, checkout, fenced)
        if path.exists() or path.is_symlink():
            _repair_registration_at_slot(config, record, checkout, fenced, vcs)
    journal["phase"] = "fenced"
    _write_journal(config, journal, journal_path=journal_path)
    if newly_fenced:
        _interrupt_for_test("after-path-fence")
    return journal, fenced


def _finish_remove_paths(
    config: Config,
    record: ActiveRecord,
    journal: dict[str, object],
    vcs: _GitVcs,
    finish: _FinishContext,
    *,
    journal_path: Path,
) -> dict[str, object]:
    if (
        finish.validation_removal_proof is not None
        and finish.private_cleanup is None
    ):
        raise StateError("validation removal proof requires a private cleanup fence")
    removed_values = _as_list(journal["removed"], "journal.removed")
    removed = {_as_str(item, "journal.removed item") for item in removed_values}
    all_names = {item.name for item in record.checkouts}
    if not removed <= all_names:
        raise StateError("finish journal names a checkout that is not in the active record")
    # A remove-agent-batch item whose budget is spent stops before its fence.
    _item_seconds_left("the path fence")
    journal, fenced_slot = _begin_or_resume_path_fence(
        config,
        record,
        journal,
        vcs,
        finish,
        journal_path=journal_path,
    )
    # A resumed removal keeps what an interrupted one already journaled.
    finish.nested_git_evidence[:] = _nested_git_evidence_from_obj(
        journal.get("nested_git_evidence", []), "finish journal.nested_git_evidence"
    )
    private_fence_identity = (
        None
        if finish.private_cleanup is None
        else finish.private_cleanup.target.identity
    )
    if finish.private_cleanup is not None:
        observed_identity = _private_cleanup_fence_identity(config, fenced_slot)
        if observed_identity != private_fence_identity:
            raise Refusal(
                f"private cleanup fence identity changed after its shared census: "
                f"{fenced_slot}"
            )
    use_check_record = _record_for_slot_use_check(
        record,
        validate_complete=finish.validate_complete,
        allow_live_validate_owner=finish.allow_live_validate_owner,
        owner_consented=finish.owner_consented,
    )
    if private_fence_identity is not None:
        assert finish.private_cleanup is not None
        fresh_census = finish.private_cleanup.fresh_census
        if fresh_census is None:
            # Interrupted-operation recovery still establishes this snapshot
            # while holding the recovery lock. Ordinary removal supplies the
            # post-fence census captured outside mutation locks.
            finish.private_cleanup.same_uid_census_performed = True
            fresh_census = _capture_same_uid_process_path_census(
                (fenced_slot,),
                budget=finish.private_cleanup.census_budget,
            )
        fresh_census.assert_slot_unused(
            fenced_slot,
            use_check_record,
            ignore_invoking_ancestry=(
                finish.allow_live_validate_owner
                and record.slot_type == "validate"
            ),
        )
        # Do not begin destructive work after the batch evidence deadline.
        finish.private_cleanup.census_budget.remaining_seconds()
    present: list[Checkout] = []
    missing_after_remove: list[Checkout] = []
    for checkout in record.checkouts:
        if checkout.name in removed:
            continue
        _moved, path = _checkout_at_slot(config, record, checkout, fenced_slot)
        if path.is_symlink():
            raise Refusal(f"interrupted fenced checkout became a symlink: {path}")
        if path.exists():
            present.append(checkout)
            continue
        _relative, repository = _stored_repository_path(config, checkout.repository)
        canonical = _stored_path(config, checkout.path, "checkout path")
        listed = vcs.listed_worktrees(repository)
        if path.absolute() in listed or canonical.absolute() in listed:
            raise Refusal(
                f"interrupted checkout {checkout.name} is missing but Git still registers it"
            )
        missing_after_remove.append(checkout)
    if missing_after_remove:
        if record.slot_type == "validate":
            for checkout in missing_after_remove:
                _relative, repository = _stored_repository_path(config, checkout.repository)
                vcs.delete_branch_at(repository, checkout.branch, checkout.head)
        removed.update(item.name for item in missing_after_remove)
        journal["removed"] = sorted(removed)
        _write_journal(config, journal, journal_path=journal_path)
    remaining = tuple(present)
    if remaining:
        if not fenced_slot.is_dir() or fenced_slot.is_symlink():
            raise Refusal(f"fenced slot is missing or unsafe: {fenced_slot}")
        if _record_layout(config, record) == "nested":
            try:
                actual = {entry.name for entry in fenced_slot.iterdir()}
            except OSError as exc:
                raise Refusal(f"cannot inspect fenced slot {fenced_slot}: {exc}") from exc
            expected = {item.name for item in remaining}
            if record.slot_type == "agent" and (fenced_slot / "HANDOFF.md").is_file():
                expected.add("HANDOFF.md")
            if actual != expected:
                raise Refusal(
                    f"fenced slot contents changed: expected {sorted(expected)}, "
                    f"found {sorted(actual)}"
                )
        elif len(remaining) != 1:
            raise StateError("flat-layout removal has more than one remaining checkout")
        deleted_nested: list[dict[str, object]] = []
        deleting_nested: list[dict[str, object]] = []
        try:
            # A refusal from here on rolls the fence back, so a
            # remove-agent-batch item budget bounds this work again.
            _resume_item_deadline()
            moved_checkouts: list[Checkout] = []
            moved_paths: dict[str, Path] = {}
            salvage = finish.salvage
            for checkout in remaining:
                moved, moved_path = _checkout_at_slot(
                    config, record, checkout, fenced_slot
                )
                if record.slot_type == "validate" or salvage:
                    _repair_registration_at_slot(
                        config, record, checkout, fenced_slot, vcs
                    )
                    head = vcs.verify_existing_worktree(
                        _stored_repository_path(config, checkout.repository)[1], moved_path
                    )
                    if head != checkout.head or vcs.branch(moved_path) != checkout.branch:
                        raise Refusal(
                            f"fenced checkout {checkout.name} changed after reclaim was "
                            "prepared; preserve it and rerun remove"
                        )
                else:
                    _repair_checkout_at_slot(
                        config, record, checkout, fenced_slot, vcs
                    )
                moved_checkouts.append(moved)
                moved_paths[checkout.name] = moved_path
            _assert_no_uncommitted_handoffs(
                config, record, fenced_slot, vcs, checkouts=remaining
            )
            _assert_handoff_read(config, record, fenced_slot)
            if record.slot_type == "agent" and salvage:
                _assert_salvage_still_matches(
                    config,
                    record,
                    salvage,
                    vcs,
                    paths=moved_paths,
                    checkouts=remaining,
                )
            if private_fence_identity is None:
                _assert_slot_unused(
                    fenced_slot,
                    use_check_record,
                    use_lsof=use_check_record is not None,
                    ignore_invoking_ancestry=(
                        finish.allow_live_validate_owner
                        and record.slot_type == "validate"
                    ),
                    live_use_recheck=finish.live_use_recheck,
                    **_agent_batch_use_check(
                        finish.agent_batch,
                        _slot_directory(config, record.slot, record.slot_type),
                        after_fence=True,
                    ),
                )
            if finish.validation_removal_proof is not None:
                canonical_checkout, _active_checkout = _single_validation_checkout(
                    config, record, fenced_slot
                )
                _recheck_validation_removal_proof(
                    config,
                    finish.validation_removal_proof,
                    expected_slot=record.slot,
                    expected_generation=record.generation,
                    canonical_slot=_slot_directory(
                        config, record.slot, record.slot_type
                    ),
                    active_slot=fenced_slot,
                    canonical_checkout=canonical_checkout,
                    expected_head=record.checkouts[0].head,
                )
                _interrupt_for_test("after-validation-removal-proof-recheck")
            disposable_git: dict[Path, tuple[int, int]] = {}
            nested_by_cache: dict[Path, tuple[_DisposableNestedRepository, ...]] = {}
            nested_evidence: dict[Path, dict[str, object]] = {}
            nested_budget = _NestedGitBudget()
            canonical_slot = _slot_directory(config, record.slot, record.slot_type)
            if record.slot_type == "agent":
                # Every guard above has passed.  Judge each nested repository
                # in every cache before the first deletion, so a refusal
                # leaves all of them in place.
                for checkout in moved_checkouts:
                    for cache in _cache_directories_for_checkout(config, checkout):
                        judged = _judge_cache_nested_repositories(
                            config,
                            cache,
                            fenced_slot=fenced_slot,
                            canonical_slot=canonical_slot,
                            budget=nested_budget,
                        )
                        if not judged:
                            continue
                        nested_by_cache[cache.path] = judged
                        for nested in judged:
                            disposable_git[nested.path] = nested.identity
                            nested_evidence[nested.path] = _nested_git_evidence_item(
                                checkout.name,
                                nested,
                                fenced_slot=fenced_slot,
                                canonical_slot=canonical_slot,
                            )
            if nested_evidence:
                # Journal what is about to be deleted before deleting any of
                # it, so an interrupted removal still records it on recovery.
                judged_paths = {item["path"] for item in nested_evidence.values()}
                merged = [
                    item
                    for item in finish.nested_git_evidence
                    if item["path"] not in judged_paths
                ] + list(nested_evidence.values())
                journal["nested_git_evidence"] = merged
                _write_journal(config, journal, journal_path=journal_path)
                finish.nested_git_evidence[:] = merged
                _interrupt_for_test("after-nested-git-evidence-journaled")
                if private_fence_identity is None:
                    # Judgment can take minutes; confirm nothing began using
                    # the fenced slot meanwhile.
                    _assert_slot_unused(
                        fenced_slot,
                        use_check_record,
                        use_lsof=use_check_record is not None,
                        ignore_invoking_ancestry=(
                            finish.allow_live_validate_owner
                            and record.slot_type == "validate"
                        ),
                        live_use_recheck=finish.live_use_recheck,
                        **_agent_batch_use_check(
                            finish.agent_batch, canonical_slot, after_fence=True
                        ),
                    )
                # Judge every cache again, after the use check and before the
                # first deletion, so neither a change nor an exhausted budget
                # can refuse once a cache is partly gone.  Deleting is not
                # charged to the budget.
                for checkout in moved_checkouts:
                    for cache in _cache_directories_for_checkout(config, checkout):
                        judged_here = nested_by_cache.get(cache.path, ())
                        rejudged = _judge_cache_nested_repositories(
                            config,
                            cache,
                            fenced_slot=fenced_slot,
                            canonical_slot=canonical_slot,
                            budget=nested_budget,
                        )
                        if rejudged != judged_here:
                            raise Refusal(
                                "nested Git repositories in cache "
                                f"{canonical_slot / cache.path.relative_to(fenced_slot)} "
                                "changed after they were judged disposable; preserve "
                                "the slot and rerun remove"
                            )
                _interrupt_for_test("after-nested-git-rejudged")
            # The last point at which a remove-agent-batch item refuses for
            # its budget.  Deleting runs to completion: stopping partway would
            # leave a partly deleted slot.
            _end_item_deadline()
            for checkout in moved_checkouts:
                for cache in _cache_directories_for_checkout(config, checkout):
                    judged_here = nested_by_cache.get(cache.path, ())
                    deleting_nested[:] = [
                        nested_evidence[nested.path] for nested in judged_here
                    ]
                    _remove_cache_directory(
                        config,
                        cache,
                        allow_git_metadata=(
                            record.slot_type == "validate" and finish.validate_complete
                        ),
                        disposable_git=disposable_git or None,
                    )
                    deleted_nested.extend(deleting_nested)
                    deleting_nested.clear()
        except Refusal as exc:

            def described(items: Sequence[Mapping[str, object]]) -> str:
                return ", ".join(
                    f"{item['path']} head={item['head']} "
                    f"contained-by={item['remote_ref']}"
                    for item in items
                )

            already = (
                "; before this refusal the removal deleted disposable nested Git "
                f"repositories: {described(deleted_nested)}"
                if deleted_nested
                else ""
            ) + (
                "; the refusal interrupted deleting a cache holding disposable "
                "nested Git repositories, which may be partly deleted: "
                f"{described(deleting_nested)}"
                if deleting_nested
                else ""
            )
            if already:
                already += (
                    "; each listed head is in the listed remote-tracking ref, and "
                    "every other commit of those repositories was in one of their "
                    "counted remote-tracking refs, so fetching from the remote that "
                    "ref names (its URL was in the deleted repository's "
                    "configuration) and checking out the listed head restores the "
                    "head's commits, but not uncommitted files, hooks or "
                    "unreferenced objects"
                )
            if not removed:
                try:
                    _rollback_path_fence(
                        config,
                        record,
                        journal,
                        vcs,
                        journal_path=journal_path,
                    )
                except Refusal as rollback:
                    raise Refusal(
                        f"{exc}{already}; path-fence rollback failed: {rollback}; "
                        "run 'wrkslots recover'"
                    ) from rollback
                if already:
                    already += (
                        "; keep this message: the path fence was rolled back, "
                        "which cleared the journal that listed these repositories"
                    )
            if already:
                raise Refusal(f"{exc}{already}") from exc
            raise
    elif fenced_slot.exists():
        remaining_entries = {entry.name for entry in fenced_slot.iterdir()}
        allowed = {"HANDOFF.md"} if record.slot_type == "agent" else set()
        unexpected = sorted(remaining_entries - allowed)
        if unexpected:
            raise Refusal(
                f"finished fenced slot contains unexpected entry: {unexpected[0]}"
            )
        if private_fence_identity is None:
            # The branch above checks the fenced slot for use before deleting
            # it; a slot with no checkout left is checked here, so a removal
            # resumed by 'wrkslots recover' checks it too.  Under the lock an
            # agent removal batch, a batch of one included, checks use before
            # the fence by path only; a use through an alias that only device
            # and inode identify, begun after its lsof scan, is found here.  A
            # refusal rolls the fence back.
            try:
                _resume_item_deadline()
                _assert_slot_unused(
                    fenced_slot,
                    use_check_record,
                    use_lsof=use_check_record is not None,
                    ignore_invoking_ancestry=(
                        finish.allow_live_validate_owner
                        and record.slot_type == "validate"
                    ),
                    live_use_recheck=finish.live_use_recheck,
                    **_agent_batch_use_check(
                        finish.agent_batch,
                        _slot_directory(config, record.slot, record.slot_type),
                        after_fence=True,
                    ),
                )
                _end_item_deadline()
            except Refusal as exc:
                if not removed:
                    try:
                        _rollback_path_fence(
                            config,
                            record,
                            journal,
                            vcs,
                            journal_path=journal_path,
                        )
                    except Refusal as rollback:
                        raise Refusal(
                            f"{exc}; path-fence rollback failed: {rollback}; "
                            "run 'wrkslots recover'"
                        ) from rollback
                raise
    for checkout in remaining:
        if private_fence_identity is not None and (
            _private_cleanup_fence_identity(config, fenced_slot)
            != private_fence_identity
        ):
            raise Refusal(
                f"private cleanup fence identity changed before deletion: {fenced_slot}"
            )
        _relative, repository = _stored_repository_path(config, checkout.repository)
        _moved, path = _checkout_at_slot(config, record, checkout, fenced_slot)
        vcs.remove_worktree(
            repository,
            path,
            force=record.slot_type == "validate" or bool(journal.get("salvage")),
        )
        _interrupt_for_test("after-remove-before-journal")
        if record.slot_type == "validate":
            vcs.delete_branch_at(repository, checkout.branch, checkout.head)
        removed.add(checkout.name)
        journal["removed"] = sorted(removed)
        _write_journal(config, journal, journal_path=journal_path)
        _interrupt_for_test("after-remove-worktree")
    if _record_layout(config, record) == "nested" and record.slot_type == "agent":
        handoff = fenced_slot / "HANDOFF.md"
        latest = _latest_handoff_read(
            record, _load_events(config, record.machine)
        )
        expected_source_path = (
            _slot_directory(config, record.slot, record.slot_type) / "HANDOFF.md"
        ).resolve(strict=False)
        expected_identity = (
            latest.source_identity
            if latest is not None
            and latest.provenance_complete
            and latest.source == "legacy-slot-file"
            and latest.source_path == expected_source_path
            else None
        )
        retired = (
            None
            if expected_identity is None
            else _retired_legacy_handoff_path(config, record, expected_identity)
        )
        handoff_present = handoff.exists() or handoff.is_symlink()
        retired_present = bool(
            retired is not None and (retired.exists() or retired.is_symlink())
        )
        if handoff_present:
            if handoff.is_symlink() or not handoff.is_file():
                raise Refusal(
                    f"fenced HANDOFF.md became unsafe: {handoff}; preserve the fenced slot "
                    "and run 'wrkslots recover'"
                )
            contents, identity = _read_regular_file_identity(
                handoff,
                "fenced HANDOFF.md before removal",
                HANDOFF_BYTES_LIMIT,
            )
            digest = hashlib.sha256(contents).hexdigest()
            if (
                expected_identity is None
                or latest is None
                or latest.sha256 != digest
                or expected_identity != identity
                or retired is None
            ):
                raise Refusal(
                    f"fenced HANDOFF.md changed after its exact provenance-bearing read: "
                    f"{handoff}; preserve the slot and rerun coordinator-authorized "
                    "'wrkslots read-handoff' before recovery"
                )
            if retired_present:
                raise StateError(
                    f"both fenced and retired legacy HANDOFF.md paths exist for "
                    f"slot {record.slot}; preserve both for recovery"
                )
            _interrupt_for_test("before-legacy-handoff-quarantine")
            _rename_noreplace(
                handoff,
                retired,
                f"quarantine legacy HANDOFF.md for slot {record.slot}",
            )
            _fsync_directory(fenced_slot)
            _fsync_directory(config.control)
            try:
                _validate_retired_legacy_handoff(retired, identity)
            except (Refusal, StateError) as exc:
                if not handoff.exists() and not handoff.is_symlink():
                    try:
                        _rename_noreplace(
                            retired,
                            handoff,
                            f"restore raced legacy HANDOFF.md for slot {record.slot}",
                        )
                        _fsync_directory(fenced_slot)
                        _fsync_directory(config.control)
                    except Refusal as restore:
                        raise StateError(
                            f"{exc}; raced replacement also could not be restored: {restore}"
                        ) from restore
                raise Refusal(
                    f"legacy HANDOFF.md pathname changed at its quarantine boundary; "
                    f"the replacement was preserved at {handoff}"
                ) from exc
            _interrupt_for_test("after-legacy-handoff-quarantine")
            if handoff.exists() or handoff.is_symlink():
                raise Refusal(
                    f"legacy HANDOFF.md pathname was recreated during quarantine for "
                    f"slot {record.slot}; preserved both {handoff} and {retired}"
                )
            _record_legacy_handoff_quarantine(
                config, record, retired, identity
            )
        elif retired_present:
            assert retired is not None
            assert expected_identity is not None
            _validate_retired_legacy_handoff(retired, expected_identity)
            _record_legacy_handoff_quarantine(
                config, record, retired, expected_identity
            )
        elif expected_identity is not None:
            raise Refusal(
                f"legacy HANDOFF.md disappeared without its exact retired quarantine: "
                f"{handoff}; preserve the fenced slot and run 'wrkslots recover'"
            )
    _remove_fenced_directory(config, fenced_slot)
    _interrupt_for_test("after-remove-fenced-directory")
    journal["phase"] = "removed"
    _write_journal(config, journal, journal_path=journal_path)
    return journal


def _assert_physical_slot_removed(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    journal: Mapping[str, object],
) -> None:
    slot_path = _slot_directory(config, record.slot, record.slot_type)
    fenced_slot = _finish_fenced_slot(config, record, journal)
    if slot_path.exists() or slot_path.is_symlink():
        raise Refusal(
            f"cannot archive slot {record.slot}: physical slot still exists at {slot_path}"
        )
    if fenced_slot.exists() or fenced_slot.is_symlink():
        raise Refusal(
            f"cannot archive slot {record.slot}: fenced storage still exists at {fenced_slot}"
        )
    for checkout in record.checkouts:
        path = _stored_path(config, checkout.path, "checkout path")
        if path.exists() or path.is_symlink():
            raise Refusal(
                f"cannot archive slot {record.slot}: checkout still exists at {path}"
            )
        _relative, repository = _stored_repository_path(config, checkout.repository)
        _moved, fenced_path = _checkout_at_slot(
            config, record, checkout, fenced_slot
        )
        listed = vcs.listed_worktrees(repository)
        if path.absolute() in listed or fenced_path.absolute() in listed:
            raise Refusal(
                f"cannot archive slot {record.slot}: Git still registers checkout {checkout.name}"
            )


def _finish_state_update(
    config: Config,
    state: ActiveState,
    record: ActiveRecord,
    journal: Mapping[str, object],
    *,
    journal_path: Path,
) -> None:
    nested_git_evidence = _nested_git_evidence_from_obj(
        journal.get("nested_git_evidence", []), "finish journal.nested_git_evidence"
    )
    current_slots = {item.slot: item for item in state.slots}
    current = current_slots.get(record.slot)
    if current is not None and _record_to_obj(current) != _record_to_obj(record):
        raise StateError("active record changed during an interrupted finish")
    _assert_physical_slot_removed(config, record, _GitVcs(), journal)
    archive = _load_archive(config, require_repository=False)
    entry = _archive_entry(journal, record)
    _append_archive_once(
        config, archive, entry, require_repository=False
    )
    _interrupt_for_test("after-archive-before-active")
    if current is not None:
        updated_state = _delete_record(state, record.slot)
        _write_active_state(
            config,
            updated_state,
            action="slot-removed",
            slot=record.slot,
            evidence={
                "archive_id": entry["archive_id"],
                **(
                    {
                        "disposable_nested_repositories": nested_git_evidence,
                        "nested_git_scope": _NESTED_GIT_SCOPE,
                    }
                    if nested_git_evidence
                    else {}
                ),
            },
            require_repository=False,
        )
    _remove_handoff_sidecar_after_archive(config, record)
    _clear_journal(config, journal, journal_path=journal_path)


def _begin_finish(
    config: Config,
    state: ActiveState,
    record: ActiveRecord,
    finish: _FinishContext,
    *,
    journal_path: Path,
    defer_private_census: bool = False,
) -> _PreparedPrivateFinish | None:
    vcs = _GitVcs()
    _load_archive(config, require_repository=False)
    _assert_not_held(config, record)
    # The path fence below always runs _reclaim_preconditions again, use
    # check included, before it renames the slot (_begin_or_resume_path_fence),
    # within this registry-lock hold; a /proc scan here, seconds earlier,
    # would decide nothing that one does not.
    _slot_path, final_checkouts = _reclaim_preconditions(
        config,
        record,
        vcs,
        finish,
        check_use=False,
    )
    final_record = dataclasses.replace(record, checkouts=final_checkouts)
    state = _replace_record(state, final_record)
    _write_active_state(
        config,
        state,
        action="checkout-evidence-refreshed",
        slot=record.slot,
        require_repository=False,
    )
    boundary_states, _boundary_archives = _validate_global_state(
        config, require_repository=False
    )
    boundary_state = next(
        (item for item in boundary_states if item.machine == config.machine), None
    )
    if boundary_state is None:
        raise StateError(
            f"slot {final_record.slot} lost its machine {config.machine} from the "
            "registry before its destructive boundary"
        )
    boundary_record = _find_record(boundary_state, final_record.slot)
    if _record_to_obj(boundary_record) != _record_to_obj(final_record):
        raise StateError(
            f"slot {final_record.slot} changed before its destructive boundary"
        )
    _assert_target_record_storage_consistent(
        config, boundary_states, boundary_record
    )
    finished_at = _utc_now()
    journal = _finish_journal_payload(
        config,
        final_record,
        finished_at=finished_at,
        removed=(),
        phase="prepared",
        finish=finish,
    )
    _write_journal(config, journal, journal_path=journal_path)
    _interrupt_for_test("after-finish-journal")
    if defer_private_census:
        if finish.private_cleanup is None:
            raise StateError("only a private cleanup can defer its fresh census")
        try:
            journal, _fenced_slot = _begin_or_resume_path_fence(
                config,
                final_record,
                journal,
                vcs,
                finish,
                journal_path=journal_path,
            )
        except Refusal:
            canonical = _slot_directory(
                config, final_record.slot, final_record.slot_type
            )
            fenced = _finish_fenced_slot(config, final_record, journal)
            if (
                canonical.is_dir()
                and not canonical.is_symlink()
                and not fenced.exists()
                and not fenced.is_symlink()
                and not _as_list(journal["removed"], "journal.removed")
            ):
                _clear_journal(config, journal, journal_path=journal_path)
            raise
        return _PreparedPrivateFinish(final_record, journal, journal_path)
    try:
        journal = _finish_remove_paths(
            config,
            final_record,
            journal,
            vcs,
            finish,
            journal_path=journal_path,
        )
    except Refusal:
        canonical = _slot_directory(config, final_record.slot, final_record.slot_type)
        fenced = _finish_fenced_slot(config, final_record, journal)
        if (
            canonical.is_dir()
            and not canonical.is_symlink()
            and not fenced.exists()
            and not fenced.is_symlink()
            and not _as_list(journal["removed"], "journal.removed")
        ):
            _clear_journal(config, journal, journal_path=journal_path)
        raise
    _finish_state_update(
        config,
        state,
        final_record,
        journal,
        journal_path=journal_path,
    )
    return None


def _load_prepared_private_finish(
    config: Config, prepared: _PreparedPrivateFinish
) -> Mapping[str, object]:
    """Reload one deferred finish without accepting journal substitution."""

    path, journal = _load_journal(config, selected_path=prepared.journal_path)
    if path != prepared.journal_path or not _json_equal(journal, prepared.journal):
        raise Refusal(
            f"private finish journal changed during its out-of-lock census: {path}"
        )
    paired = _assert_validate_batch_seal_recovery_kind(
        config, _ValidateBatchSealRecoveryKind.PAIRED_FINISH
    )
    if paired is None or _record_to_obj(paired) != _record_to_obj(prepared.record):
        raise StateError("private finish no longer pairs with its exact seal target")
    return journal


def _rollback_prepared_private_finish(
    config: Config, prepared: _PreparedPrivateFinish, refusal: Refusal
) -> None:
    """Return a census-refused private target to its canonical pathname."""

    try:
        journal = dict(_load_prepared_private_finish(config, prepared))
        _rollback_path_fence(
            config,
            prepared.record,
            journal,
            _GitVcs(),
            journal_path=prepared.journal_path,
        )
    except (Refusal, StateError) as rollback:
        raise Refusal(
            f"{refusal}; deferred path-fence rollback failed: {rollback}; "
            "run 'wrkslots recover'"
        ) from rollback


def _complete_prepared_private_finish(
    config: Config,
    prepared: _PreparedPrivateFinish,
    finish: _FinishContext,
    *,
    coordinator: ProcessIdentity,
    runner: ProcessIdentity,
    handoff_writer: ProcessIdentity | None,
    proof_fd: int | None,
) -> None:
    """Revalidate and complete the short destructive phase under mutation locks."""

    raw = _load_prepared_private_finish(config, prepared)
    states, archives = _validate_global_state_for_finish_recovery(config, raw)
    before = _global_rows(states, archives)
    state = next(item for item in states if item.machine == config.machine)
    current = _find_record(state, prepared.record.slot)
    if _record_to_obj(current) != _record_to_obj(prepared.record):
        raise Refusal(
            f"slot {prepared.record.slot} changed during its out-of-lock census"
        )
    _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
    _assert_not_held(config, current)
    owner_state, owner_detail = _process_state(current.owner)
    live_validate_owner = bool(
        finish.validate_complete
        and owner_state == "live"
        and current.owner == coordinator
    )
    if live_validate_owner:
        if handoff_writer is None:
            _assert_caller_process(coordinator, "validate owner")
    else:
        _assert_owner_liveness(
            config,
            current,
            fenced_slot=(
                _finish_fenced_slot(config, current, raw)
                if current.slot_type == "validate"
                else None
            ),
        )
    if (
        owner_state != "dead"
        and not live_validate_owner
        and not _owner_record_is_absent(current)
    ):
        raise Refusal(
            "remove requires a proven-dead recorded owner after its final census; "
            f"owner is {owner_state}: {owner_detail}"
        )
    private_cleanup = finish.private_cleanup
    if private_cleanup is None or private_cleanup.fresh_census is None:
        raise StateError("deferred private finish has no fresh same-UID census")
    _assert_validate_batch_seal_target(
        config,
        current,
        private_cleanup.target.original_mode,
        private_cleanup.target.identity,
    )
    fenced_slot = _finish_fenced_slot(config, current, raw)
    if (
        _private_cleanup_fence_identity(config, fenced_slot)
        != private_cleanup.target.identity
    ):
        raise Refusal(
            f"private cleanup fence identity changed after its fresh census: "
            f"{fenced_slot}"
        )
    resumed_finish = dataclasses.replace(
        finish, allow_live_validate_owner=live_validate_owner
    )
    journal = _finish_remove_paths(
        config,
        current,
        dict(raw),
        _GitVcs(),
        resumed_finish,
        journal_path=prepared.journal_path,
    )
    _finish_state_update(
        config,
        state,
        current,
        journal,
        journal_path=prepared.journal_path,
    )
    after_states, after_archives = _validate_global_state(
        config, require_repository=False
    )
    _assert_only_slot_changed(
        before,
        _global_rows(after_states, after_archives),
        current.slot,
    )


def _cmd_finish(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    _validate_name(args.agent, "agent")
    owner = _capture_caller_process(args.owner_pid, "owner")
    validation = tuple(args.validation or ())
    limitations = tuple(args.limitation or ())
    if not validation or any(not item.strip() for item in validation):
        raise Refusal("finish requires at least one non-empty --validation entry")
    if any(not item.strip() for item in limitations):
        raise Refusal("finish limitations must be non-empty")
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        states, archives = _validate_global_state(config)
        state = _load_active(config)
        record = _find_record(state, args.slot)
        _assert_owner_auth(record, args.agent, owner, args.expected_generation)
        _assert_validate_batch_seals_disjoint_from_record(
            config, record, action="finish"
        )
        _assert_validate_cleanup_journals_disjoint_from_record(
            config,
            states,
            archives,
            record,
            action="finish",
        )
        _assert_command_registry_storage(config, states, args)
        before = _global_rows(states, archives)
        if record.handoff is not None:
            raise Refusal(f"slot {record.slot} already has a recorded handoff")
        _slot_path, final_checkouts = _handoff_preconditions(
            config, record, _GitVcs()
        )
        continuation = (
            f"wrkslots remove {record.slot} --coordinator-pid "
            f"<current-coordinator-pid> --expected-generation {record.generation}"
        )
        updated = dataclasses.replace(
            record,
            checkouts=final_checkouts,
            handoff=Handoff(
                recorded_at=_utc_now(),
                validation=validation,
                limitations=limitations,
                continuation=continuation,
            ),
        )
        _write_active_state(
            config,
            _replace_record(state, updated),
            action="handoff-recorded",
            slot=updated.slot,
            evidence={"validation": list(validation)},
        )
        _interrupt_for_test("after-handoff-write")
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    print(
        f"recorded handoff slot={record.slot} generation={record.generation}; "
        "physical storage retained"
    )
    print(f"continuation={continuation}")
    return 0


def _cmd_remove(
    args: argparse.Namespace,
    *,
    private_cleanup: _PrivateCleanupContext | None = None,
    validation_removal_proof: _ValidationRemovalProof | None = None,
    emit: bool = True,
    agent_batch: _AgentRemoveBatchContext | None = None,
) -> int:
    with _remote_containment_scope():
        return _cmd_remove_in_scope(
            args,
            private_cleanup=private_cleanup,
            validation_removal_proof=validation_removal_proof,
            emit=emit,
            agent_batch=agent_batch,
        )


def _prefetch_remote_containment(
    config: Config, slot: str, salvage_archive_root: Path | None = None
) -> None:
    """Do removal's slow salvage work for ``slot`` before the registry lock is taken.

    See _REMOTE_CONTAINMENT_EVIDENCE_MAX_AGE_SECONDS. A lock-free read selects
    the slot, as _single_remove_agent_batch's does, and nothing is done unless
    its owner is already gone (dead or never recorded, heartbeat expired, no
    hold, handoff read). Then, in the order removal itself uses, every
    checkout and initialized submodule is first checked locally
    (_salvage_candidate), so a local defect still refuses before any network
    contact; only if all pass is the remote asked, for each, whether its HEAD
    is published. The answer (or the refusal) is only an entry in
    _REMOTE_CONTAINMENT_MEMO, which the removal under the lock may reuse for a
    commit, object store and remote URL it has re-derived itself. A checkout
    that removal would archive locally has its self-contained bundle made and
    verified here too; removal under the lock finds it, rechecks its bytes,
    and writes the receipt. Every refusal here is dropped: the removal under
    the lock asks the same questions and reports them there.
    """

    try:
        state = _load_active(config, require_repository=False)
        record = next((item for item in state.slots if item.slot == slot), None)
        if record is None or record.slot_type != "agent" or not record.checkouts:
            return
        owner_gone = (
            _owner_record_is_absent(record) or _process_state(record.owner)[0] == "dead"
        ) and _heartbeat_diagnosis(record)[1]
        if not owner_gone:
            return
        _assert_not_held(config, record)
        _assert_handoff_read(
            config, record, _slot_directory(config, slot, record.slot_type)
        )
        archive_root = salvage_archive_root or _default_salvage_archive_root(config)
        vcs = _GitVcs()
        prepared: list[tuple[Checkout, Path, _SalvageCandidate]] = []
        for checkout in record.checkouts:
            path = _stored_path(config, checkout.path, "checkout path")
            candidates: list[tuple[Checkout, Path, bool]] = [(checkout, path, False)]
            candidates.extend(
                (submodule, submodule_path, True)
                for submodule, submodule_path in _submodule_salvage_checkouts(
                    config, checkout, vcs
                )
            )
            for candidate, candidate_path, detached in candidates:
                prepared.append(
                    (
                        candidate,
                        candidate_path,
                        _salvage_candidate(
                            config,
                            record,
                            candidate,
                            vcs,
                            path_override=candidate_path,
                            allow_detached=detached,
                            verify_repository_membership=not detached,
                            allow_shallow=detached,
                        ),
                    )
                )
    except Refusal:
        return
    for candidate, candidate_path, facts in prepared:
        try:
            published = vcs.remote_heads_containing(
                candidate_path,
                candidate.remote,
                facts.head,
                facts.remote_authority,
                network_authority=facts.network_authority,
                shallow=facts.shallow is not None,
            )
            if published and not facts.dirty:
                continue
            if facts.shallow is not None:
                # Refused under the lock (_shallow_history_refusal).
                continue
            if not facts.aliased and _salvage_push_allowed(
                config, facts.remote_authority
            ):
                # A push is decided, and made, under the lock as before.
                continue
            _checked_root, bundle, _receipt, archive_ref = _ensure_local_salvage_bundle(
                config,
                record.machine,
                record.slot,
                record.generation,
                candidate,
                candidate_path,
                facts,
                archive_root,
                vcs,
            )
            # A bundle an earlier, refused removal left is restored and fully
            # checked here, once; under the lock its bytes are only rehashed
            # (_VERIFIED_SALVAGE_BUNDLES). One just made was checked already.
            digest, size = _sha256_regular_file(bundle, "local salvage bundle")
            _verify_local_salvage_bundle(
                bundle, digest, size, archive_ref, facts.commit, vcs
            )
        except Refusal:
            continue


def _cmd_remove_in_scope(
    args: argparse.Namespace,
    *,
    private_cleanup: _PrivateCleanupContext | None,
    validation_removal_proof: _ValidationRemovalProof | None,
    emit: bool,
    agent_batch: _AgentRemoveBatchContext | None,
) -> int:
    config = _load_config(args.project_root, args.machine)
    _validate_name(args.slot, "slot")
    if agent_batch is not None and (
        private_cleanup is not None
        or validation_removal_proof is not None
        or bool(args.validate_complete)
    ):
        raise StateError("an agent removal batch cannot carry validation cleanup")
    salvage_archive_root = _local_salvage_archive_root(
        config, getattr(args, "salvage_archive_root", None)
    )
    proof_manifest = getattr(args, "validation_proof_manifest", None)
    completed_record = getattr(args, "completed_record", None)
    if (proof_manifest is None) != (completed_record is None):
        raise Refusal(
            "--validation-proof-manifest and --completed-record must be supplied "
            "together for registered validation removal"
        )
    if (
        private_cleanup is None
        and (proof_manifest is not None or bool(args.validate_complete))
    ):
        batch_args = argparse.Namespace(**vars(args))
        batch_args.command = "remove-validate-batch"
        batch_args.slots = [f"{args.slot}={args.expected_generation}"]
        batch_args.validation_proof_manifests = (
            [] if proof_manifest is None else [proof_manifest]
        )
        batch_args.completed_records = (
            [] if completed_record is None else [completed_record]
        )
        batch_args.format = "json"
        payload = _remove_validate_batch(
            batch_args,
            single_validate_complete=(
                bool(args.validate_complete) and proof_manifest is None
            ),
        )
        retained = _as_list(payload["retained"], "validation removal result.retained")
        if retained:
            row = _as_mapping(retained[0], "validation removal result.retained[0]")
            raise Refusal(
                _as_str(row["reason"], "validation removal result.retained[0].reason")
            )
        removed = _as_list(payload["removed"], "validation removal result.removed")
        if len(removed) != 1:
            raise StateError("single validation proof removal produced no exact result")
        if emit:
            print(
                f"removed and archived slot={args.slot} "
                f"generation={args.expected_generation}"
            )
        return 0
    if proof_manifest is not None:
        raise StateError("validation proof manifest was supplied twice")
    coordinator, runner, handoff_writer, proof_fd = _capture_remove_processes(
        args.coordinator_pid
    )
    single_item = (
        agent_batch is None
        and private_cleanup is None
        and not bool(args.validate_complete)
        and not getattr(args, "no_lock_budget", False)
    )
    # A refusal of the lsof scan is reported at the first use check under the
    # lock, where the ordinary check would refuse, so a retire-pending batch
    # records its attempt first and moves on to its next candidate.
    single_refusal: Refusal | None = None
    if single_item:
        try:
            agent_batch = _single_remove_agent_batch(config, args.slot)
        except Refusal as exc:
            single_refusal = exc
    live_use_recheck = (
        private_cleanup.live_use_recheck
        if private_cleanup is not None
        else _LiveUseRecheckBudget()
    )
    scoped_validation_finish = bool(args.validate_complete) and (
        private_cleanup is None or private_cleanup.scoped_finish
    )
    if private_cleanup is None and not bool(args.validate_complete):
        # Network work happens here, before the registry lock, not under it.
        _prefetch_remote_containment(config, args.slot, salvage_archive_root)
    wait_deadline = getattr(args, "_wait_deadline", None)
    lock_scope = (
        _mutation_locks(config, args.wait_lock)
        if wait_deadline is None
        else _mutation_locks(config, args.wait_lock, deadline=wait_deadline)
    )
    prepared_private_finish: _PreparedPrivateFinish | None = None
    finish_context: _FinishContext | None = None
    with lock_scope, _agent_batch_item_deadline(agent_batch):
        _refuse_partial_state(
            config,
            allow_validate_batch_seals=private_cleanup is not None,
        )
        if not scoped_validation_finish:
            _assert_no_journal(config)
        states, archives = _validate_global_state(
            config, require_repository=False
        )
        before = _global_rows(states, archives)
        state = _load_active(config, require_repository=False)
        record = _find_record(state, args.slot)
        _expected_generation(record, args.expected_generation)
        retirement_candidate = getattr(args, "_retirement_candidate", None)
        if retirement_candidate is not None:
            if not isinstance(retirement_candidate, _RetirementCandidate):
                raise StateError("retirement queue candidate has an invalid type")
            expected_identity = (
                retirement_candidate.machine,
                retirement_candidate.slot,
                retirement_candidate.generation,
            )
            if expected_identity != (record.machine, record.slot, record.generation):
                raise _RetirementDeferred(
                    "retirement candidate generation changed before its guarded attempt"
                )
            latest = _latest_handoff_read(
                record, _load_events(config, record.machine)
            )
            if latest is None or (
                latest.sha256,
                latest.retirement_enqueued,
                latest.sequence,
            ) != (
                retirement_candidate.sha256,
                True,
                retirement_candidate.event_sequence,
            ):
                raise _RetirementDeferred(
                    "retirement candidate was superseded before its guarded attempt"
                )
            _write_event_file(
                config,
                record.machine,
                "retirement-attempted",
                {
                    "slot": record.slot,
                    "generation": record.generation,
                    "sha256": retirement_candidate.sha256,
                    "handoff_read_sequence": retirement_candidate.event_sequence,
                    "reason": "selected by bounded retirement queue",
                },
            )
            _interrupt_for_test("after-retirement-attempt")
        if private_cleanup is not None:
            _assert_validate_batch_seal_target(
                config,
                record,
                private_cleanup.target.original_mode,
                private_cleanup.target.identity,
            )
        _assert_target_record_storage_consistent(
            config, states, record, before_any_change=True
        )
        _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
        if args.validate_complete and record.slot_type != "validate":
            raise Refusal(
                "--validate-complete applies only to a slot created with --slot-type validate. "
                "state: REFUSED -- no checkout was salvaged or removed. remedy: omit the flag "
                "and satisfy the ordinary agent-slot reclaim conditions"
            )
        if salvage_archive_root is not None and record.slot_type != "agent":
            raise Refusal(
                "--salvage-archive-root applies only to agent slots that require Git salvage"
            )
        if agent_batch is not None and record.slot_type != "agent":
            raise Refusal(
                "remove-agent-batch accepts only agent slots; use remove-validate-batch "
                "for validation slots"
            )
        create_rows: tuple[_CreateJournalClassification, ...] = ()
        if scoped_validation_finish:
            create_rows = _classify_disjoint_create_journals_for_record(
                config, states, archives, record
            )
        _assert_not_held(config, record)
        age, expired = _heartbeat_diagnosis(record)
        owner_state, detail = _process_state(record.owner)
        live_validate_owner = bool(
            args.validate_complete
            and owner_state == "live"
            and record.owner == coordinator
        )
        owner_consent: _OwnerConsent | None = None
        owner_release: _OwnerRelease | None = None
        owner_unrecorded = _owner_record_is_absent(record)
        # An explicit release by the exact owner process generation is the
        # owner's own decision to give this generation back, so it is honoured
        # by an explicit remove and by a retire-pending batch alike. It stands
        # in for the owner's death and the heartbeat time-to-live only; the
        # handoff read, the direct-use check, salvage and holds still apply.
        if (
            record.slot_type == "agent"
            and owner_state in ("live", "dead")
            and not args.validate_complete
            and not owner_unrecorded
        ):
            owner_release = _owner_release_in_effect(
                config, record, _load_events(config, record.machine)
            )
        # An explicit remove names one slot, so running it is the coordinator's
        # decision for that slot. A retire-pending batch selects slots itself
        # and a scheduler may pass --coordinator-authorized for it, so it may
        # use owner consent only when the caller opted in for the batch.
        # Otherwise a live owner keeps the original refusal and is retained.
        owner_consent_allowed = retirement_candidate is None or (
            getattr(args, "include_owner_consented", False) is True
        )
        if (
            owner_release is None
            and owner_consent_allowed
            and record.slot_type == "agent"
            and owner_state == "live"
            and not args.validate_complete
            and not _owner_record_is_absent(record)
        ):
            owner_consent = _owner_consented_release(
                config,
                record,
                detail,
                events=_load_events(config, record.machine),
                coordinator_authorized=bool(args.coordinator_authorized),
                expired=expired,
                age=age,
            )
        consent_liveness: tuple[str, str] | None = None
        if live_validate_owner:
            if handoff_writer is None:
                _assert_caller_process(coordinator, "validate owner")
        elif owner_consent is not None or owner_release is not None:
            # The registered liveness authority answers "is the owner still
            # running?", and for a consenting or releasing owner the answer may
            # be yes by construction. Record its answer as evidence; do not
            # gate on it.
            consent_liveness = _registered_liveness_state(config, record)
        else:
            _assert_owner_liveness(config, record)
        # A release stops this generation's heartbeat (heartbeat refuses while
        # it is in effect) and is bound to the heartbeat stamp, so any renewal
        # voids it. Waiting for the time-to-live would only re-prove what the
        # exact owner already declared.
        if not expired and not args.validate_complete and owner_release is None:
            remaining = max(1, record.heartbeat_ttl_seconds - int(age))
            raise Refusal(
                f"slot {record.slot} heartbeat is {int(age)}s old and its "
                f"{record.heartbeat_ttl_seconds}s time-to-live has not expired. state: "
                "REFUSED -- no checkout was salvaged or removed. remedy: wait at least "
                f"{remaining}s without renewal before retrying remove; if the owner is still "
                "working, have it run 'wrkslots heartbeat' instead"
            )
        # An absent or degenerate owner record no longer blocks removal. The
        # heartbeat has already expired above, and every guard that actually
        # protects work still runs below: the handoff read, the direct-use
        # check, and salvage before delete. See _owner_record_is_absent.
        if (
            owner_state != "dead"
            and not live_validate_owner
            and not owner_unrecorded
            and owner_consent is None
            and owner_release is None
        ):
            raise Refusal(
                f"remove requires a proven-dead recorded owner; owner is {owner_state}: {detail}. "
                "state: REFUSED -- no checkout was salvaged or removed. remedy: wait for the "
                "exact owner process to exit and for the time-to-live to remain expired; if "
                "process evidence is unavailable, repair that evidence rather than treating the "
                "slot as free"
            )
        slot_path = _assert_slot_contents(config, record)
        _assert_no_uncommitted_handoffs(config, record, slot_path, _GitVcs())
        _assert_handoff_read(config, record, slot_path)
        if private_cleanup is not None:
            if private_cleanup.target.path != slot_path:
                raise StateError("private cleanup context does not match its slot path")
            if (
                _private_cleanup_fence_identity(config, slot_path)
                != private_cleanup.target.identity
            ):
                raise Refusal(
                    f"private cleanup path identity changed after its shared census: "
                    f"{slot_path}"
                )
        if single_refusal is not None:
            raise single_refusal
        if single_item and agent_batch is not None:
            if (
                time.monotonic() - agent_batch.captured_at
                > _AGENT_REMOVE_BATCH_CENSUS_MAX_AGE_SECONDS
            ):
                # remove-agent-batch takes a new shared scan before an item
                # whose scan is older than this; a single removal cannot take
                # one under the lock, so it stops instead.
                raise Refusal(
                    f"the lsof scan of slot {args.slot} is more than "
                    f"{_AGENT_REMOVE_BATCH_CENSUS_MAX_AGE_SECONDS:.0f} seconds old "
                    "at its first use check under the registry lock; nothing was "
                    "salvaged or removed; retry"
                )
            # The batch's checks skip the invoking process, which opens the
            # slot while it removes it.  When lsof ran, before the lock, it had
            # not yet opened it, so a descriptor, mapping or directory lsof
            # reported for it was inherited and is a use, which the ordinary
            # lsof check refused as it refuses any other.
            agent_batch.census.assert_slot_unused(
                slot_path, None, ignore_current_process=False
            )
        _assert_slot_unused(
            slot_path,
            _record_for_slot_use_check(
                record,
                validate_complete=bool(args.validate_complete),
                allow_live_validate_owner=live_validate_owner,
                owner_consented=owner_consent is not None or owner_release is not None,
            ),
            use_lsof=not live_validate_owner,
            ignore_invoking_ancestry=live_validate_owner,
            census=None if private_cleanup is None else private_cleanup.shared_census,
            live_use_recheck=live_use_recheck,
            **_agent_batch_use_check(agent_batch, slot_path),
        )
        if scoped_validation_finish:
            boundary_states, boundary_archives = _validate_global_state(
                config, require_repository=False
            )
            boundary_state = next(
                item for item in boundary_states if item.machine == config.machine
            )
            boundary_record = _find_record(boundary_state, record.slot)
            if _record_to_obj(boundary_record) != _record_to_obj(record):
                raise Refusal(
                    f"slot {record.slot} changed while interrupted creates were classified"
                )
            _assert_target_record_storage_consistent(
                config, boundary_states, boundary_record
            )
            _recheck_disjoint_create_journals_for_record(
                config,
                create_rows,
                boundary_states,
                boundary_archives,
                boundary_record,
            )
        _ensure_event_log(
            config, record.machine, require_repository=False
        )
        if owner_consent is not None:
            # Record the basis BEFORE any salvage or deletion so the removal
            # is attributable from the append-only history alone, and so an
            # interrupted removal can re-derive the same consent on recovery.
            assert consent_liveness is not None
            state = _replace_record(state, record)
            _write_active_state(
                config,
                state,
                action=OWNER_CONSENT_ACTION,
                slot=record.slot,
                evidence=_owner_consent_evidence(
                    record,
                    owner_consent,
                    coordinator=coordinator,
                    coordinator_authorized=bool(args.coordinator_authorized),
                    age=age,
                    registered_liveness=consent_liveness,
                ),
                require_repository=False,
            )
        elif owner_release is not None:
            # Same reason as for consent: the basis is durable before any
            # salvage or deletion, and recovery resumes only this exact release.
            assert consent_liveness is not None
            state = _replace_record(state, record)
            _write_active_state(
                config,
                state,
                action=OWNER_RELEASE_ACTION,
                slot=record.slot,
                evidence=_owner_release_evidence(
                    record,
                    owner_release,
                    coordinator=coordinator,
                    coordinator_authorized=bool(args.coordinator_authorized),
                    owner_state=owner_state,
                    age=age,
                    registered_liveness=consent_liveness,
                ),
                require_repository=False,
            )
        _write_event_file(
            config,
            record.machine,
            "reclaim-started",
            {
                "slot": record.slot,
                "generation": record.generation,
                "actor": _identity_to_obj(coordinator),
                "runner": _identity_to_obj(runner),
                "handoff_writer": (
                    None
                    if handoff_writer is None
                    else _identity_to_obj(handoff_writer)
                ),
                "coordinator_authorized": bool(args.coordinator_authorized),
                "owner_state": owner_state,
                "registered_liveness": (
                    "dead" if consent_liveness is None else consent_liveness[0]
                ),
                "heartbeat_age_seconds": int(age),
                "heartbeat_ttl_seconds": record.heartbeat_ttl_seconds,
                "validate_complete": bool(args.validate_complete),
                "live_validate_owner": live_validate_owner,
                "salvage_archive_root": (
                    None if salvage_archive_root is None else str(salvage_archive_root)
                ),
            },
        )
        salvage: tuple[dict[str, object], ...]
        evidence: tuple[str, ...]
        if record.slot_type == "validate":
            salvage = ()
            evidence = (
                "slot type validate: authored work is excluded by construction, so salvage was not run",
            )
        elif not record.checkouts and record.import_source is not None:
            salvage = ()
            evidence = (
                "historical agent slot contains no checkout and its exact contents were "
                "verified before deletion, so there was no checkout to salvage",
            )
        else:
            salvage = _salvage_agent_slot(
                config, record, _GitVcs(), archive_root=salvage_archive_root
            )
            evidence = tuple(
                f"checkout {item['checkout']}: {item['disposition']} commit "
                f"{item['salvage_commit']}"
                + (
                    f" at {item['remote_ref']}"
                    if item.get("remote_ref") is not None
                    else (
                        f" in {item['archive_bundle']}"
                        if item["disposition"] == "archived-local"
                        else " on an existing remote ref"
                    )
                )
                for item in salvage
            )
        if record.handoff is None:
            continuation = (
                f"wrkslots remove {record.slot} --coordinator-pid <current-coordinator-pid> "
                f"--expected-generation {record.generation}"
            )
            record = dataclasses.replace(
                record,
                handoff=Handoff(
                    recorded_at=_utc_now(),
                    validation=evidence,
                    limitations=(),
                    continuation=continuation,
                ),
            )
            state = _replace_record(state, record)
            _write_active_state(
                config,
                state,
                action="reclaim-evidence-recorded",
                slot=record.slot,
                evidence={
                    "actor": _identity_to_obj(coordinator),
                    "coordinator_authorized": bool(args.coordinator_authorized),
                    "owner_state": owner_state,
                    "heartbeat_age_seconds": int(age),
                    "salvage": list(salvage),
                    **(
                        {}
                        if owner_consent is None
                        else {
                            "basis": OWNER_CONSENT_BASIS,
                            "handoff_sha256": owner_consent.sha256,
                        }
                    ),
                    **(
                        {}
                        if owner_release is None
                        else {
                            "basis": OWNER_RELEASE_BASIS,
                            "release_sequence": owner_release.sequence,
                            "handoff_sha256": owner_release.sha256,
                        }
                    ),
                },
                require_repository=False,
            )
        finish_context = _FinishContext(
            mode="remove",
            actor="coordinator",
            salvage=salvage,
            validate_complete=bool(args.validate_complete),
            allow_live_validate_owner=live_validate_owner,
            private_cleanup=private_cleanup,
            validation_removal_proof=validation_removal_proof,
            live_use_recheck=live_use_recheck,
            owner_consented=owner_consent is not None or owner_release is not None,
            agent_batch=agent_batch,
        )
        prepared_private_finish = _begin_finish(
            config,
            state,
            record,
            finish_context,
            journal_path=(
                _finish_journal_path(config, record.slot)
                if scoped_validation_finish
                else _journal_path(config)
            ),
            defer_private_census=private_cleanup is not None,
        )
        if prepared_private_finish is None:
            after_states, after_archives = _validate_global_state(
                config, require_repository=False
            )
        else:
            after_states, after_archives = _validate_global_state_for_finish_recovery(
                config, prepared_private_finish.journal
            )
        _assert_only_slot_changed(
            before,
            _global_rows(after_states, after_archives),
            args.slot,
        )
    if prepared_private_finish is not None:
        assert private_cleanup is not None
        assert finish_context is not None
        fenced_slot = _finish_fenced_slot(
            config,
            prepared_private_finish.record,
            prepared_private_finish.journal,
        )
        try:
            if (
                _private_cleanup_fence_identity(config, fenced_slot)
                != private_cleanup.target.identity
            ):
                raise Refusal(
                    f"private cleanup fence identity changed before its fresh census: "
                    f"{fenced_slot}"
                )
            private_cleanup.same_uid_census_performed = True
            private_cleanup.fresh_census = _capture_same_uid_process_path_census(
                (fenced_slot,), budget=private_cleanup.census_budget
            )
            private_cleanup.census_budget.remaining_seconds()
            if (
                _private_cleanup_fence_identity(config, fenced_slot)
                != private_cleanup.target.identity
            ):
                raise Refusal(
                    f"private cleanup fence identity changed during its fresh census: "
                    f"{fenced_slot}"
                )
            _interrupt_for_test("after-validate-batch-fresh-census")
        except Refusal as exc:
            rollback_scope = (
                _mutation_locks(config, args.wait_lock)
                if wait_deadline is None
                else _mutation_locks(config, args.wait_lock, deadline=wait_deadline)
            )
            with rollback_scope:
                _rollback_prepared_private_finish(
                    config, prepared_private_finish, exc
                )
            raise
        completion_scope = (
            _mutation_locks(config, args.wait_lock)
            if wait_deadline is None
            else _mutation_locks(config, args.wait_lock, deadline=wait_deadline)
        )
        with completion_scope:
            _refuse_partial_state(config, allow_validate_batch_seals=True)
            try:
                _complete_prepared_private_finish(
                    config,
                    prepared_private_finish,
                    finish_context,
                    coordinator=coordinator,
                    runner=runner,
                    handoff_writer=handoff_writer,
                    proof_fd=proof_fd,
                )
            except Refusal as exc:
                if prepared_private_finish.journal_path.exists():
                    _rollback_prepared_private_finish(
                        config, prepared_private_finish, exc
                    )
                raise
    if agent_batch is not None and finish_context is not None:
        agent_batch.nested_git_evidence[:] = [
            dict(item) for item in finish_context.nested_git_evidence
        ]
    if emit:
        print(f"removed and archived slot={record.slot} generation={record.generation}")
        if finish_context is not None:
            _print_nested_git_evidence(finish_context.nested_git_evidence)
    return 0


def _print_nested_git_evidence(evidence: Sequence[Mapping[str, object]]) -> None:
    for item in evidence:
        print(
            f"removed disposable nested Git repository {item['path']} "
            f"head={item['head']} contained-by={item['remote_ref']} "
            f"ignored-entries={item['ignored_entries']}"
        )


def _parse_validate_batch_slot(raw: str) -> tuple[str, int]:
    slot, separator, generation_text = raw.rpartition("=")
    if not separator:
        raise Refusal(f"invalid --slot {raw!r}; expected SLOT=GENERATION")
    _validate_name(slot, "slot")
    try:
        generation = int(generation_text)
    except ValueError as exc:
        raise Refusal(
            f"invalid generation in --slot {raw!r}; expected a positive integer"
        ) from exc
    if generation <= 0:
        raise Refusal(
            f"invalid generation in --slot {raw!r}; expected a positive integer"
        )
    return slot, generation


def _seal_validate_batch_targets(
    config: Config,
    coordinator: ProcessIdentity,
    runner: ProcessIdentity,
    handoff_writer: ProcessIdentity | None,
    proof_fd: int | None,
    requested: Sequence[tuple[str, int]],
    wait_seconds: float,
    retained: list[dict[str, object]],
    private_targets: dict[str, _PrivateCleanupTarget],
    proof_manifests: Mapping[str, str],
    completed_records: Mapping[str, Path],
    removal_proofs: dict[str, _ValidationRemovalProof],
    owned_seal: list[_RegularFileIdentity],
    *,
    single_validate_complete: bool = False,
) -> None:
    """Preflight and seal each eligible target while the mutation locks are held.

    ``owned_seal`` receives the exact seal file this invocation publishes.
    """

    with _mutation_locks(config, wait_seconds):
        _refuse_partial_state(config)
        states, archives = _validate_global_state(
            config, require_repository=False
        )
        if single_validate_complete:
            if len(requested) != 1:
                raise StateError(
                    "internal completed-validation cleanup requires one exact slot"
                )
            selected_slot, selected_generation = requested[0]
            selected_state = next(
                state for state in states if state.machine == config.machine
            )
            selected_record = _find_record(selected_state, selected_slot)
            _expected_generation(selected_record, selected_generation)
            create_rows = _classify_disjoint_create_journals_for_record(
                config, states, archives, selected_record
            )
        else:
            _assert_no_journal(config)
            selected_record = None
            create_rows = ()
        _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
        seal_journal: dict[str, object] = {
            "schema": _VALIDATE_BATCH_SEAL_SCHEMA,
            "kind": "validate-batch-seal",
            "machine": config.machine,
            "created_at": _utc_now(),
            "actor": _identity_to_obj(coordinator),
            "targets": [],
        }
        _write_owned_validate_batch_seal_journal(config, seal_journal, owned_seal)
        _interrupt_for_test("after-validate-batch-seal-journal")
        records = {record.slot: record for state in states for record in state.slots}
        run_liveness: dict[tuple[str, str, int], tuple[str, str]] | None = None
        for slot, generation in requested:
            try:
                record = records.get(slot)
                if record is None:
                    raise Refusal(
                        f"slot {slot!r} is not active on machine {config.machine}"
                    )
                _expected_generation(record, generation)
                if record.slot_type != "validate":
                    if single_validate_complete:
                        raise Refusal(
                            "--validate-complete applies only to a slot created with "
                            "--slot-type validate. state: REFUSED -- no checkout was "
                            "salvaged or removed. remedy: omit the flag and satisfy the "
                            "ordinary agent-slot reclaim conditions"
                        )
                    raise Refusal("batch validation cleanup accepts only validate slots")
                _assert_not_held(config, record)
                owner_state, owner_detail = _process_state(record.owner)
                live_validate_owner = bool(
                    single_validate_complete
                    and owner_state == "live"
                    and record.owner == coordinator
                )
                if live_validate_owner:
                    if handoff_writer is None:
                        _assert_caller_process(coordinator, "validate owner")
                else:
                    if run_liveness is None:
                        # One read of host evidence answers every requested
                        # validation row; the destructive phase asks again
                        # for each target immediately before it fences.
                        run_liveness = _validation_run_liveness_states(
                            config,
                            [
                                records[name]
                                for name in dict.fromkeys(
                                    name for name, _generation in requested
                                )
                                if name in records
                                and records[name].slot_type == "validate"
                            ],
                        )
                    _assert_owner_liveness(config, record, known=run_liveness)
                owner_unrecorded = _owner_record_is_absent(record)
                if owner_state != "dead" and not live_validate_owner:
                    if not (single_validate_complete and owner_unrecorded):
                        prefix = (
                            "remove requires"
                            if single_validate_complete
                            else "batch validation cleanup requires"
                        )
                        raise Refusal(
                            f"{prefix} a proven-dead recorded owner; owner is "
                            f"{owner_state}: {owner_detail}"
                        )
                slot_path = _assert_slot_contents(config, record)
                proof_manifest = proof_manifests.get(slot)
                if proof_manifest is not None:
                    canonical_checkout, _active_checkout = _single_validation_checkout(
                        config, record, slot_path
                    )
                    checkout = record.checkouts[0]
                    _repository_relative, repository = _stored_repository_path(
                        config, checkout.repository
                    )
                    removal_proofs[slot] = _load_validation_removal_proof(
                        config,
                        proof_manifest,
                        expected_slot=slot,
                        expected_generation=generation,
                        canonical_slot=slot_path,
                        canonical_checkout=canonical_checkout,
                        expected_run_record=completed_records[slot],
                        expected_head=checkout.head,
                        repository=repository,
                    )

                def record_before_seal(
                    original_mode: int,
                    identity: _PrivateCleanupIdentity,
                    *,
                    selected_slot: str = slot,
                    selected_generation: int = generation,
                    selected_path: Path = slot_path,
                ) -> None:
                    target = _PrivateCleanupTarget(
                        selected_path, original_mode, identity
                    )
                    entries = _as_list(
                        seal_journal["targets"],
                        "validation-batch seal journal.targets",
                    )
                    seal_journal["targets"] = [
                        *entries,
                        _private_cleanup_target_to_obj(
                            config, selected_slot, selected_generation, target
                        ),
                    ]
                    _write_owned_validate_batch_seal_journal(
                        config, seal_journal, owned_seal
                    )
                    _interrupt_for_test("after-validate-batch-seal-target-planned")

                original_mode, identity = _seal_cleanup_path_private(
                    config, slot_path, before_seal=record_before_seal
                )
                private_targets[slot] = _PrivateCleanupTarget(
                    path=slot_path,
                    original_mode=original_mode,
                    identity=identity,
                )
                _interrupt_for_test("after-validate-batch-seal-target")
            except (Refusal, StateError) as exc:
                retained.append(
                    {"slot": slot, "generation": generation, "reason": str(exc)}
                )
        if single_validate_complete and private_targets:
            assert selected_record is not None
            boundary_states, boundary_archives = _validate_global_state(
                config, require_repository=False
            )
            boundary_state = next(
                state for state in boundary_states if state.machine == config.machine
            )
            boundary_record = _find_record(boundary_state, selected_record.slot)
            if _record_to_obj(boundary_record) != _record_to_obj(selected_record):
                raise Refusal(
                    f"slot {selected_record.slot} changed while its private cleanup "
                    "fence was established"
                )
            _assert_target_record_storage_consistent(
                config, boundary_states, boundary_record
            )
            _recheck_disjoint_create_journals_for_record(
                config,
                create_rows,
                boundary_states,
                boundary_archives,
                boundary_record,
            )


def _validate_remove_batch_census_seconds(sealed_slots: int) -> float:
    """Return the census deadline for a validation batch of sealed slots.

    One slot, or none, gets the single-census bound.  Each further slot adds
    one same-UID census allowance.
    """

    return _VALIDATE_REMOVE_BATCH_CENSUS_SECONDS + (
        _VALIDATE_REMOVE_BATCH_ITEM_CENSUS_SECONDS * max(0, sealed_slots - 1)
    )


def _validate_remove_batch_census_stderr_bytes(sealed_slots: int) -> int:
    """Return the combined census stderr bound for a validation batch.

    One slot, or none, gets one allowance.  Each further slot adds one more.
    """

    return _VALIDATE_REMOVE_BATCH_CENSUS_STDERR_BYTES * max(1, sealed_slots)


def _remove_validate_batch(
    args: argparse.Namespace, *, single_validate_complete: bool = False
) -> dict[str, object]:
    requested = tuple(_parse_validate_batch_slot(raw) for raw in args.slots)
    if len(requested) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise Refusal(
            f"remove-validate-batch accepts at most {VALIDATE_REMOVE_BATCH_LIMIT} slots; "
            "run another bounded batch for the remainder"
        )
    if len({slot for slot, _generation in requested}) != len(requested):
        raise Refusal("remove-validate-batch received the same slot more than once")
    config = _load_config(args.project_root, args.machine)
    raw_proofs = tuple(getattr(args, "validation_proof_manifests", ()) or ())
    raw_records = tuple(getattr(args, "completed_records", ()) or ())
    if bool(raw_proofs) != bool(raw_records):
        raise Refusal(
            "remove-validate-batch requires --validation-proof-manifest and "
            "--completed-record together"
        )
    if raw_proofs and len(raw_proofs) != len(requested):
        raise Refusal(
            "remove-validate-batch requires one --validation-proof-manifest for "
            "each --slot when any proof is supplied"
        )
    if raw_records and len(raw_records) != len(requested):
        raise Refusal(
            "remove-validate-batch requires one --completed-record for each --slot "
            "when any proof is supplied"
        )
    canonical_proofs = tuple(
        _validation_proof_manifest_path(config, raw)[0] for raw in raw_proofs
    )
    if len(canonical_proofs) != len(set(canonical_proofs)):
        raise Refusal(
            "remove-validate-batch received the same validation proof manifest more "
            "than once"
        )
    canonical_records = tuple(
        _validation_run_record_argument(config, raw)[1] for raw in raw_records
    )
    if len(canonical_records) != len(set(canonical_records)):
        raise Refusal(
            "remove-validate-batch received the same completed run-record more than "
            "once"
        )
    proof_manifests = (
        {
            slot: proof
            for (slot, _generation), proof in zip(
                requested, canonical_proofs, strict=True
            )
        }
        if canonical_proofs
        else {}
    )
    completed_records = (
        {
            slot: record
            for (slot, _generation), record in zip(
                requested, canonical_records, strict=True
            )
        }
        if canonical_records
        else {}
    )
    coordinator, runner, handoff_writer, proof_fd = _capture_remove_processes(
        args.coordinator_pid
    )
    retained: list[dict[str, object]] = []
    private_targets: dict[str, _PrivateCleanupTarget] = {}
    removal_proofs: dict[str, _ValidationRemovalProof] = {}
    removed: list[dict[str, object]] = []
    same_uid_census_count = 0
    live_use_recheck = _LiveUseRecheckBudget()
    owned_seal: list[_RegularFileIdentity] = []
    try:
        _seal_validate_batch_targets(
            config,
            coordinator,
            runner,
            handoff_writer,
            proof_fd,
            requested,
            args.wait_lock,
            retained,
            private_targets,
            proof_manifests,
            completed_records,
            removal_proofs,
            owned_seal,
            single_validate_complete=single_validate_complete,
        )
        # Lock acquisition and the exact seal/preflight establish which paths
        # the census must cover, but are not census work.  Starting this budget
        # before Phase A made a slow registry preflight consume most or all of
        # the bounded evidence window before the first observer ran.
        census_budget = _ReadOnlyCommandBudget.start(
            timeout_seconds=_validate_remove_batch_census_seconds(
                len(private_targets)
            ),
            stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
            stderr_limit=_validate_remove_batch_census_stderr_bytes(
                len(private_targets)
            ),
            input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
        private_paths = [
            private_target.path for private_target in private_targets.values()
        ]
        shared_census_count = int(bool(private_paths))
        shared_census_refusal: str | None = None
        if private_paths:
            try:
                privileged_census = _capture_process_path_census(
                    private_paths,
                    budget=census_budget,
                    include_owner_cgroups=False,
                )
                census_budget.remaining_seconds()
            except Refusal as exc:
                shared_census_refusal = str(exc)
                privileged_census = _ProcessPathCensus((), ())
                retained.extend(
                    {
                        "slot": slot,
                        "generation": generation,
                        "reason": shared_census_refusal,
                    }
                    for slot, generation in requested
                    if slot in private_targets
                )
            else:
                _interrupt_for_test("after-validate-batch-shared-census")
        else:
            privileged_census = _ProcessPathCensus((), ())
        for request_index, (slot, generation) in enumerate(requested):
            target = private_targets.get(slot)
            if target is None or shared_census_refusal is not None:
                continue
            try:
                census_budget.remaining_seconds()
            except Refusal as deadline:
                retained.extend(
                    {
                        "slot": remaining_slot,
                        "generation": remaining_generation,
                        "reason": str(deadline),
                    }
                    for remaining_slot, remaining_generation in requested[request_index:]
                    if remaining_slot in private_targets
                )
                break
            item_args = argparse.Namespace(**vars(args))
            item_args.command = "remove"
            item_args.slot = slot
            item_args.expected_generation = generation
            item_args.validate_complete = True
            item_args.validation_proof_manifest = None
            item_args.completed_record = None
            private_cleanup = _PrivateCleanupContext(
                target,
                privileged_census,
                census_budget,
                scoped_finish=single_validate_complete,
                live_use_recheck=live_use_recheck,
            )
            try:
                _cmd_remove(
                    item_args,
                    private_cleanup=private_cleanup,
                    validation_removal_proof=removal_proofs.get(slot),
                    emit=False,
                )
            except (Refusal, StateError) as exc:
                retained.append(
                    {"slot": slot, "generation": generation, "reason": str(exc)}
                )
                try:
                    census_budget.remaining_seconds()
                except Refusal as deadline:
                    retained.extend(
                        {
                            "slot": remaining_slot,
                            "generation": remaining_generation,
                            "reason": str(deadline),
                        }
                        for remaining_slot, remaining_generation in requested[
                            request_index + 1 :
                        ]
                        if remaining_slot in private_targets
                    )
                    break
            else:
                removed.append({"slot": slot, "generation": generation})
            finally:
                same_uid_census_count += int(
                    private_cleanup.same_uid_census_performed
                )
    finally:
        with _mutation_locks(config, args.wait_lock):
            # A refused invocation may find another operation's seal here; only
            # the exact file this invocation published is its to retire.
            loaded_seal = (
                _load_validate_batch_seal_journal(config)
                if _validate_batch_seal_is_owned(config, owned_seal)
                else None
            )
            has_finish = loaded_seal is not None and any(
                _as_str(
                    _load_journal(config, selected_path=journal_path)[1].get("kind"),
                    "journal.kind",
                )
                == "finish"
                for journal_path in _outstanding_journals(config)
            )
            if loaded_seal is not None and not has_finish:
                _recover_validate_batch_seal_journal(
                    config,
                    recovery_kind=_ValidateBatchSealRecoveryKind.SEAL_ONLY,
                    emit=False,
                )
    payload = {
        "schema": 1,
        "batch_limit": VALIDATE_REMOVE_BATCH_LIMIT,
        "process_censuses": shared_census_count,
        "shared_process_censuses": shared_census_count,
        "same_uid_process_censuses": same_uid_census_count,
        "requested": len(requested),
        "removed": removed,
        "retained": retained,
    }
    return payload


def _cmd_remove_validate_batch(args: argparse.Namespace) -> int:
    payload = _remove_validate_batch(args)
    removed = _as_list(payload["removed"], "removed")
    retained = _as_list(payload["retained"], "retained")
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        print(
            f"requested={payload['requested']} removed={len(removed)} "
            f"retained={len(retained)} "
            f"process_censuses={payload['process_censuses']}"
        )
        for value in retained:
            row = _as_mapping(value, "retained item")
            print(f"RETAINED: {row['slot']} reason={row['reason']}")
    # A retained item is a refusal of that item.  Success means every requested
    # slot was removed; a batch that removed nothing never reports success.
    return 0 if removed and not retained else 1


# ---------------------------------------------------------------------------
# remove-agent-batch
#
# The ordinary `remove` of one agent slot runs its process-use check four or
# five times inside one registry-lock hold: before salvage, twice before the
# path fence, after the fence, and again after nested Git repositories are
# judged.  Each check starts `lsof +D`, whose cost is the system-wide scan of
# every process's open descriptors rather than the slot's tree (about 10
# seconds on an idle 4,000-process host and 20 to 45 seconds under load), so
# one slot held the lock for minutes.  The batch runs one lsof scan for every
# target, outside any lock, and uses it only for the three checks before the
# path fence.  At each of those it (1) confirms the slot directory is still
# the directory the shared scan covered, (2) refuses on any shared-scan match
# or on an lsof warning that may concern the slot, and (3) runs a fresh
# in-process scan of /proc for path, mapping, mount, and owner-cgroup use,
# which costs about one second on the same host.  The fresh scan is what
# catches a process that began using the slot after the shared scan; the
# shared scan is what catches use through a hardlink or other inode alias
# that no path names.  Nothing is deleted before the fence.  The checks after
# the fence, which guard deletion, run no lsof when they can decide without
# it: one in-process /proc scan records the device and inode of every entry
# of the fenced tree and compares every process's cwd, root, exe, descriptors
# and mappings with it by path and by identity, which is what lsof compares
# (see _agent_batch_fenced_use).  When that scan cannot decide, because the
# tree spans devices, is on a filesystem the scan does not compare, or a
# process's evidence is unreadable in an unexpected way, the ordinary lsof
# check of the fenced path decides instead.  Each item's work before its
# first deletion is held to _AGENT_REMOVE_BATCH_ITEM_SECONDS, which bounds
# how long it keeps the registry lock from other clients.
# ---------------------------------------------------------------------------


@dataclasses.dataclass(frozen=True)
class _LsofUseRecord:
    """One complete ``p``/``c``/``f``/``n`` record from an ``lsof -F`` stream."""

    pid: int
    command: str
    descriptor: str
    name: str


def _parse_lsof_use_records(
    output: str,
) -> tuple[tuple[_LsofUseRecord, ...], bool]:
    """Return every complete file record and whether the stream was malformed.

    This applies the same stream rules as `_parse_lsof_use_diagnostic`: each
    unique ``p`` set carries one ``c`` before one or more complete ``f``/``n``
    pairs.  Unlike that parser it keeps every record, because a shared scan of
    several slots must attribute each record to the slot it names.
    """

    records: list[_LsofUseRecord] = []
    malformed = False
    seen: set[int] = set()
    pid: int | None = None
    command: str | None = None
    descriptor: str | None = None
    complete_file = False

    def finish_process() -> None:
        nonlocal malformed
        if pid is not None and (
            command is None or descriptor is not None or not complete_file
        ):
            malformed = True

    for line in output.splitlines():
        if not line:
            malformed = True
            descriptor = None
            continue
        field, value = line[0], line[1:]
        if field == "p":
            finish_process()
            command = None
            descriptor = None
            complete_file = False
            if not re.fullmatch(r"[0-9]{1,20}", value):
                malformed = True
                pid = None
                continue
            pid = int(value)
            if pid in seen:
                malformed = True
            seen.add(pid)
        elif field == "c":
            if pid is None or not value or command is not None or complete_file or descriptor is not None:
                malformed = True
                continue
            command = value
        elif field == "f":
            if pid is None or not value or command is None or descriptor is not None:
                malformed = True
            descriptor = value if pid is not None and value else None
        elif field == "n":
            if pid is None or command is None or descriptor is None or not value:
                malformed = True
                descriptor = None
                continue
            records.append(_LsofUseRecord(pid, command, descriptor, value))
            descriptor = None
            complete_file = True
        else:
            malformed = True
            descriptor = None
    finish_process()
    return tuple(records), malformed


def _lsof_executable() -> Path | None:
    return next(
        (
            candidate
            for candidate in (Path("/usr/bin/lsof"), Path("/usr/sbin/lsof"))
            if candidate.is_file() and os.access(candidate, os.X_OK)
        ),
        None,
    )


def _directory_identity(path: Path) -> tuple[int, int] | None:
    """Return a real directory's device and inode, or None for anything else."""

    try:
        observed = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise Refusal(f"cannot inspect slot directory {path}: {exc}") from exc
    if not stat.S_ISDIR(observed.st_mode):
        return None
    return observed.st_dev, observed.st_ino


@dataclasses.dataclass(frozen=True)
class _SharedAgentCensus:
    """One shared lsof scan: its records, and the targets it cannot vouch for.

    ``unobservable`` maps a target to the lsof diagnostic that concerns it.
    Such a target has no usable evidence from this scan; every other target's
    records are exactly what a single-target scan of it would have accepted.
    """

    census: _ProcessPathCensus
    unobservable: Mapping[Path, str]


def _capture_agent_remove_batch_census(
    targets: Sequence[Path],
) -> _SharedAgentCensus:
    """Run one ``lsof +D`` over every target and attribute each record.

    lsof runs as the invoking user, exactly as the ordinary check does, so it
    covers the same processes.  A record whose name is not below exactly one
    requested target is attributed to every target: an unattributable record
    must never make a slot look unused.  An lsof diagnostic is attributed the
    same way the ordinary check judges one against its single slot, so it
    makes only the targets it may concern unobservable.
    """

    empty = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    if not targets:
        return _SharedAgentCensus(empty, {})
    lsof = _lsof_executable()
    if lsof is None:
        raise Refusal(
            "remove-agent-batch needs lsof for its shared process census; "
            "use single-slot remove on this host"
        )
    command = [str(lsof), "-nP", "-Fpcfn"]
    for target in targets:
        command.extend(("+D", str(target)))
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            check=False,
            timeout=_AGENT_REMOVE_BATCH_LSOF_SECONDS,
        )
    except subprocess.TimeoutExpired as exc:
        raise Refusal(
            "process use is indeterminate because the shared lsof census exceeded "
            f"its {_AGENT_REMOVE_BATCH_LSOF_SECONDS:.0f} s bound"
        ) from exc
    except OSError as exc:
        raise Refusal(f"process use is indeterminate because lsof failed: {exc}") from exc
    stdout = completed.stdout.decode("utf-8", errors="surrogateescape")
    stderr = completed.stderr.decode("utf-8", errors="replace")
    unobservable = {
        target: line
        for target in targets
        if (line := _first_related_lsof_warning(stderr, target)) is not None
    }
    records, malformed = _parse_lsof_use_records(stdout)
    if malformed:
        raise Refusal(
            "process use is indeterminate because lsof returned malformed field output"
        )
    if completed.returncode not in (0, 1):
        raise Refusal(
            f"process use is indeterminate because lsof exited {completed.returncode}"
        )
    matches: list[tuple[int, str, str, str]] = []
    for item in records:
        name = item.name.removesuffix(" (deleted)")
        owners = (
            [target for target in targets if _path_is_within(Path(name), target)]
            if name.startswith("/")
            else []
        )
        detail = (
            f"command={_lsof_diagnostic_excerpt(item.command)} "
            f"fd={_lsof_diagnostic_excerpt(item.descriptor)} "
            f"file={_lsof_diagnostic_excerpt(item.name)}"
        )
        for target in owners if len(owners) == 1 else targets:
            matches.append((item.pid, str(target), "shared-lsof", detail))
    return _SharedAgentCensus(
        _ProcessPathCensus((), tuple(matches), owner_cgroup_complete=False),
        unobservable,
    )


def _readable_link_target(path: Path) -> str | None:
    """Return an absolute link target, or None when absent or unreadable.

    A link the invoking user may not read is also invisible to lsof run as
    that user, which is what the ordinary check relies on, so it is not
    evidence either way.  Other failures still refuse.
    """

    try:
        raw = os.readlink(path)
    except OSError as exc:
        if exc.errno in (
            errno.ENOENT, errno.ESRCH, errno.EINVAL, errno.EACCES, errno.EPERM,
        ):
            return None
        raise Refusal(f"process use is indeterminate because {path} failed: {exc}") from exc
    raw = raw.removesuffix(" (deleted)")
    if not raw.startswith("/"):
        return None
    return os.path.normpath(raw)


def _agent_batch_fresh_use(
    slot_path: Path,
    record: ActiveRecord | None,
    *,
    capture_generation: bool,
    proc_root: Path = Path("/proc"),
) -> _LiveUseObservation | None:
    """Scan /proc once for current use of ``slot_path`` without starting lsof.

    For every process it reads the owner cgroup when that is evidence for the
    record, every mount table (as the ordinary check does after lsof), and the
    cwd, root, exe, descriptor, and mapping paths it may read.  It stops at the
    first use found; the caller may wait for that exact process generation
    and then repeat the whole scan.
    """

    base = str(slot_path)
    prefix = base + "/"

    def within(target: str | None) -> bool:
        return target is not None and (target == base or target.startswith(prefix))

    try:
        pid_dirs = [path for path in proc_root.iterdir() if path.name.isdigit()]
    except OSError as exc:
        raise Refusal(f"cannot inspect live processes: {exc}") from exc
    current_pid = os.getpid()
    mount_verdicts = _MountTableVerdicts(slot_path)
    owner_cgroup = (
        record.owner.cgroup_path
        if record is not None
        and record.owner is not None
        and _owner_cgroup_is_evidence(record)
        else None
    )
    slot_bytes = base.encode("utf-8", errors="surrogateescape")
    for pid_dir in sorted(pid_dirs, key=lambda item: int(item.name)):
        pid = int(pid_dir.name)
        if pid == current_pid:
            continue
        start_ticks: int | None = None
        if capture_generation:
            try:
                generation = _read_process_stat(pid_dir)
            except Refusal:
                generation = None
            start_ticks = None if generation is None else generation.start_ticks
        if _process_uids(pid_dir) is None:
            continue
        uses: list[str] = []
        if owner_cgroup is not None:
            try:
                cgroup = _read_process_cgroup(pid_dir)
            except Refusal as exc:
                if not pid_dir.exists():
                    continue
                raise Refusal(
                    f"recorded cgroup use is indeterminate for PID {pid}: {exc}"
                ) from exc
            if cgroup == owner_cgroup:
                raise Refusal(
                    f"live process {pid} remains in recorded owner cgroup {cgroup}"
                )
        uses.extend(mount_verdicts.uses(pid_dir))
        if not uses:
            for name in ("cwd", "root", "exe"):
                target = _readable_link_target(pid_dir / name)
                if within(target):
                    uses.append(f"{name}={target}")
                    break
        if not uses:
            fd_dir = pid_dir / "fd"
            try:
                descriptors = os.listdir(fd_dir)
            except OSError as exc:
                if exc.errno not in (
                    errno.ENOENT, errno.ESRCH, errno.EACCES, errno.EPERM,
                ):
                    raise Refusal(
                        f"process use is indeterminate because {fd_dir} cannot be read: {exc}"
                    ) from exc
                descriptors = []
            for descriptor in descriptors:
                target = _readable_link_target(fd_dir / descriptor)
                if within(target):
                    uses.append(f"fd/{descriptor}={target}")
                    break
        if not uses:
            maps_path = pid_dir / "maps"
            try:
                maps = maps_path.read_bytes()
            except OSError as exc:
                if exc.errno not in (
                    errno.ENOENT, errno.ESRCH, errno.EACCES, errno.EPERM,
                ):
                    raise Refusal(
                        f"process use is indeterminate because {maps_path} cannot be read: {exc}"
                    ) from exc
                maps = b""
            if slot_bytes in maps:
                for line in maps.split(b"\n"):
                    if slot_bytes not in line:
                        continue
                    fields = line.split(maxsplit=5)
                    if len(fields) != 6:
                        continue
                    mapped = fields[5].decode(
                        "utf-8", errors="surrogateescape"
                    ).removesuffix(" (deleted)")
                    if within(os.path.normpath(mapped) if mapped.startswith("/") else None):
                        uses.append(f"map={mapped}")
                        break
        if uses:
            refusal = Refusal(
                f"live process {pid} uses slot {slot_path}: {uses[0]}; stop it and retry"
            )
            if not capture_generation:
                raise refusal
            return _LiveUseObservation(pid, start_ticks, proc_root, refusal)
    return None


_AT_STATX_DONT_SYNC = 0x4000
_STATX_TYPE = 0x1
_STATX_INO = 0x100
# A process or link that vanished, or one the invoking user may not inspect,
# is skipped, as lsof run as that user skips it.
_FENCED_SCAN_SKIPPED_ERRNOS = frozenset(
    {errno.ENOENT, errno.ESRCH, errno.EACCES, errno.EPERM}
)


class _StatxTimestamp(ctypes.Structure):
    _fields_ = (
        ("tv_sec", ctypes.c_int64),
        ("tv_nsec", ctypes.c_uint32),
        ("reserved", ctypes.c_int32),
    )


class _Statx(ctypes.Structure):
    """The kernel's ``struct statx``, which is 256 bytes on every architecture."""

    _fields_ = (
        ("stx_mask", ctypes.c_uint32),
        ("stx_blksize", ctypes.c_uint32),
        ("stx_attributes", ctypes.c_uint64),
        ("stx_nlink", ctypes.c_uint32),
        ("stx_uid", ctypes.c_uint32),
        ("stx_gid", ctypes.c_uint32),
        ("stx_mode", ctypes.c_uint16),
        ("spare0", ctypes.c_uint16),
        ("stx_ino", ctypes.c_uint64),
        ("stx_size", ctypes.c_uint64),
        ("stx_blocks", ctypes.c_uint64),
        ("stx_attributes_mask", ctypes.c_uint64),
        ("stx_atime", _StatxTimestamp),
        ("stx_btime", _StatxTimestamp),
        ("stx_ctime", _StatxTimestamp),
        ("stx_mtime", _StatxTimestamp),
        ("stx_rdev_major", ctypes.c_uint32),
        ("stx_rdev_minor", ctypes.c_uint32),
        ("stx_dev_major", ctypes.c_uint32),
        ("stx_dev_minor", ctypes.c_uint32),
        ("spare2", ctypes.c_uint64 * 14),
    )


@functools.lru_cache(maxsize=1)
def _statx_library() -> ctypes.CDLL | None:
    """Return the C library with its statx prototype set, or None without statx."""

    if ctypes.sizeof(_Statx) != 256:
        return None
    library = ctypes.CDLL(None, use_errno=True)
    try:
        # The library object keeps this function object, prototype included.
        function = library.statx
    except AttributeError:
        return None
    function.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_uint,
        ctypes.POINTER(_Statx),
    )
    function.restype = ctypes.c_int
    return library


def _cached_file_identity(path: str) -> tuple[int, int]:
    """Return the device and inode of the file ``path`` resolves to.

    It asks statx for cached attributes (AT_STATX_DONT_SYNC), so a network or
    FUSE filesystem answers without asking its server, which can take
    unbounded time; the device and inode never come from the server.  Where
    statx is unavailable it falls back to os.stat.  Raises OSError.
    """

    library = _statx_library()
    if library is not None:
        buffer = _Statx()
        ctypes.set_errno(0)
        result = library.statx(
            _AT_FDCWD,
            os.fsencode(path),
            _AT_STATX_DONT_SYNC,
            _STATX_TYPE | _STATX_INO,
            ctypes.byref(buffer),
        )
        if result == 0:
            return (
                os.makedev(buffer.stx_dev_major, buffer.stx_dev_minor),
                int(buffer.stx_ino),
            )
        error = ctypes.get_errno()
        if error != errno.ENOSYS:
            raise OSError(error, os.strerror(error), path)
    observed = os.stat(path)
    return observed.st_dev, observed.st_ino


class _ScanCancelled(Exception):
    """The caller of a bounded scan stopped waiting for it."""


@dataclasses.dataclass(frozen=True)
class _UndecidedFencedUse:
    """The post-fence /proc scan could not decide; lsof must."""

    reason: str


def _fenced_tree_inodes(
    fenced: Path, cancel: threading.Event
) -> tuple[int, frozenset[int]] | _UndecidedFencedUse:
    """Return the device and every inode number of the tree at ``fenced``.

    Any entry on another device (a mount or a nested filesystem volume), and
    any entry that cannot be read, leaves the scan undecided.
    """

    try:
        top = os.lstat(fenced)
    except OSError as exc:
        return _UndecidedFencedUse(f"cannot inspect {fenced}: {exc}")
    if not stat.S_ISDIR(top.st_mode):
        return _UndecidedFencedUse(f"{fenced} is not a directory")
    device = top.st_dev
    inodes = {top.st_ino}
    pending = [str(fenced)]
    while pending:
        if cancel.is_set():
            raise _ScanCancelled
        directory = pending.pop()
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    observed = entry.stat(follow_symlinks=False)
                    if observed.st_dev != device:
                        return _UndecidedFencedUse(
                            f"{entry.path} is on another device than {fenced}"
                        )
                    inodes.add(observed.st_ino)
                    if stat.S_ISDIR(observed.st_mode):
                        pending.append(entry.path)
        except OSError as exc:
            return _UndecidedFencedUse(f"cannot read {directory}: {exc}")
    return device, frozenset(inodes)


# Filesystems whose mappings in /proc/<pid>/maps name the same inode, with
# the same inode number, as stat does.  Their mapping device is the device
# stat reports, except on btrfs, where stat gives each volume a device of its
# own (see _agent_batch_fenced_use).  On any other filesystem, such as
# overlayfs, where a mapping can name an underlying inode, the post-fence scan
# leaves the decision to lsof.
_FENCED_SCAN_FILESYSTEMS = frozenset({"btrfs", "ext2", "ext3", "ext4", "tmpfs", "xfs"})


def _mount_device(path: Path) -> tuple[int, str] | None:
    """Return the device and type of the filesystem ``path`` is on.

    The device is the one /proc/<pid>/maps shows for a file on that
    filesystem.  Returns None when the mount cannot be identified.
    """

    try:
        _device, _inode, mount_id = _open_directory_identity(path, "fenced slot")
        mountinfo = Path("/proc/self/mountinfo").read_text(
            encoding="utf-8", errors="surrogateescape"
        )
    except (Refusal, OSError):
        return None
    for line in mountinfo.split("\n"):
        fields = line.split(" ")
        if len(fields) < 3 or fields[0] != str(mount_id):
            continue
        major, separator, minor = fields[2].partition(":")
        if not (separator and major.isdigit() and minor.isdigit()):
            return None
        try:
            filesystem = fields[fields.index("-", 6) + 1]
        except (ValueError, IndexError):
            return None
        return os.makedev(int(major), int(minor)), filesystem
    return None


def _unix_socket_inodes_within(paths: Sequence[Path]) -> frozenset[int] | _UndecidedFencedUse:
    """Return the inodes of this network namespace's sockets bound below ``paths``.

    /proc/net/unix keeps the path a socket was bound to, so a socket bound
    before the path fence still names the canonical slot path.
    """

    try:
        text = Path("/proc/net/unix").read_bytes().decode("utf-8", errors="surrogateescape")
    except OSError as exc:
        return _UndecidedFencedUse(f"cannot read /proc/net/unix: {exc}")
    inodes: set[int] = set()
    for line in text.split("\n")[1:]:
        fields = line.split(None, 7)
        if len(fields) < 8 or not fields[7].startswith("/"):
            continue
        bound = Path(os.path.normpath(fields[7]))
        if any(_path_is_within(bound, path) for path in paths):
            if not fields[6].isdigit():
                return _UndecidedFencedUse(f"malformed /proc/net/unix line: {line!r}")
            inodes.add(int(fields[6]))
    return frozenset(inodes)


def _agent_batch_fenced_use(
    fenced_path: Path,
    canonical_path: Path,
    record: ActiveRecord | None,
    *,
    capture_generation: bool,
    cancel: threading.Event | None = None,
    proc_root: Path = Path("/proc"),
) -> _LiveUseObservation | _UndecidedFencedUse | None:
    """Scan /proc once for use of a fenced agent slot, without starting lsof.

    It first records the device and inode of every entry of the fenced tree.
    For every process it may inspect, it then reads the owner cgroup when that
    is evidence for the record and every mount table, as
    `_agent_batch_fresh_use` does, and compares each of the process's cwd,
    root, exe and descriptors with the fenced tree by path and by device and
    inode, so a use through a hard link, or through a bind mount in another
    mount namespace, is found although no path names the slot.  A socket
    descriptor matches a socket bound below the slot's canonical or fenced
    path in this network namespace.  A mapping matches by path, or by inode
    on the filesystem's device.

    Returns the first use found (with ``capture_generation``) or raises it,
    returns None when there is none, and returns _UndecidedFencedUse when the
    scan cannot decide: when the tree spans devices or cannot be read, when
    the tree is on a filesystem outside _FENCED_SCAN_FILESYSTEMS, when a
    process's evidence fails with an unexpected error, or when a mapping on a
    filesystem that stat reports under another device (btrfs) has an inode
    number found in the tree.  An undecided scan stops at once; the caller
    falls back to lsof.
    """

    stop = threading.Event() if cancel is None else cancel
    tree = _fenced_tree_inodes(fenced_path, stop)
    if isinstance(tree, _UndecidedFencedUse):
        return tree
    tree_device, tree_inodes = tree
    sockets = _unix_socket_inodes_within((canonical_path, fenced_path))
    if isinstance(sockets, _UndecidedFencedUse):
        return sockets
    mount = _mount_device(fenced_path)
    if mount is None:
        return _UndecidedFencedUse(f"cannot identify the filesystem of {fenced_path}")
    mapping_device, filesystem = mount
    if filesystem not in _FENCED_SCAN_FILESYSTEMS:
        return _UndecidedFencedUse(
            f"{fenced_path} is on a {filesystem} filesystem, whose mappings this "
            "scan does not compare"
        )
    mapping_major = os.major(mapping_device)
    mapping_minor = os.minor(mapping_device)
    base = str(fenced_path)
    prefix = base + "/"

    def within(target: str) -> bool:
        return target == base or target.startswith(prefix)

    def in_tree(link: str) -> bool:
        device, inode = _cached_file_identity(link)
        return device == tree_device and inode in tree_inodes

    identity_match = ", which is an entry of the fenced slot by device and inode"

    try:
        pid_dirs = [path for path in proc_root.iterdir() if path.name.isdigit()]
    except OSError as exc:
        raise Refusal(f"cannot inspect live processes: {exc}") from exc
    current_pid = os.getpid()
    mount_verdicts = _MountTableVerdicts(fenced_path)
    owner_cgroup = (
        record.owner.cgroup_path
        if record is not None
        and record.owner is not None
        and _owner_cgroup_is_evidence(record)
        else None
    )
    for pid_dir in sorted(pid_dirs, key=lambda item: int(item.name)):
        if stop.is_set():
            raise _ScanCancelled
        pid = int(pid_dir.name)
        if pid == current_pid:
            continue
        start_ticks: int | None = None
        if capture_generation:
            try:
                generation = _read_process_stat(pid_dir)
            except Refusal:
                generation = None
            start_ticks = None if generation is None else generation.start_ticks
        if _process_uids(pid_dir) is None:
            continue
        if owner_cgroup is not None:
            try:
                cgroup = _read_process_cgroup(pid_dir)
            except Refusal as exc:
                if not pid_dir.exists():
                    continue
                raise Refusal(
                    f"recorded cgroup use is indeterminate for PID {pid}: {exc}"
                ) from exc
            if cgroup == owner_cgroup:
                raise Refusal(
                    f"live process {pid} remains in recorded owner cgroup {cgroup}"
                )
        uses = mount_verdicts.uses(pid_dir)
        current = pid_dir
        try:
            for name in ("cwd", "root", "exe"):
                if uses:
                    break
                current = pid_dir / name
                try:
                    raw = os.readlink(current)
                    target = raw.removesuffix(" (deleted)")
                    if target.startswith("/") and within(os.path.normpath(target)):
                        uses.append(f"{name}={target}")
                    elif in_tree(str(current)):
                        uses.append(f"{name}={raw}{identity_match}")
                except OSError as exc:
                    if exc.errno not in _FENCED_SCAN_SKIPPED_ERRNOS:
                        raise
            current = pid_dir / "fd"
            try:
                descriptors = [] if uses else os.listdir(current)
            except OSError as exc:
                if exc.errno not in _FENCED_SCAN_SKIPPED_ERRNOS:
                    raise
                descriptors = []
            for descriptor in descriptors:
                current = pid_dir / "fd" / descriptor
                try:
                    raw = os.readlink(current)
                except OSError as exc:
                    if exc.errno not in _FENCED_SCAN_SKIPPED_ERRNOS:
                        raise
                    continue
                if raw.startswith("socket:[") and raw.endswith("]"):
                    inode_text = raw[len("socket:["):-1]
                    if inode_text.isdigit() and int(inode_text) in sockets:
                        uses.append(f"fd/{descriptor}={raw} is bound below the slot")
                        break
                    continue
                if not raw.startswith("/"):
                    continue
                target = raw.removesuffix(" (deleted)")
                try:
                    if within(os.path.normpath(target)):
                        uses.append(f"fd/{descriptor}={raw}")
                        break
                    if in_tree(str(current)):
                        uses.append(f"fd/{descriptor}={raw}{identity_match}")
                        break
                except OSError as exc:
                    if exc.errno not in _FENCED_SCAN_SKIPPED_ERRNOS:
                        raise
            current = pid_dir / "maps"
            try:
                maps = b"" if uses else current.read_bytes()
            except OSError as exc:
                if exc.errno not in _FENCED_SCAN_SKIPPED_ERRNOS:
                    raise
                maps = b""
        except OSError as exc:
            return _UndecidedFencedUse(f"{current}: {exc}")
        seen: set[bytes] = set()
        for line in maps.split(b"\n") if maps else ():
            fields = line.split(maxsplit=5)
            if len(fields) < 5 or fields[4] == b"0":
                continue
            if len(fields) == 6:
                mapped = fields[5].decode("utf-8", errors="surrogateescape")
                target = mapped.removesuffix(" (deleted)")
                if target.startswith("/") and within(os.path.normpath(target)):
                    uses.append(f"map={mapped}")
                    break
            key = fields[3] + b" " + fields[4]
            if key in seen:
                continue
            seen.add(key)
            major, _separator, minor = fields[3].partition(b":")
            try:
                same_filesystem = (int(major, 16), int(minor, 16)) == (
                    mapping_major,
                    mapping_minor,
                )
                inode = int(fields[4])
            except ValueError:
                return _UndecidedFencedUse(f"malformed mapping in {pid_dir / 'maps'}")
            if not same_filesystem or inode not in tree_inodes:
                continue
            if mapping_device != tree_device:
                return _UndecidedFencedUse(
                    f"process {pid} maps inode {inode} on the fenced slot's filesystem, "
                    "whose volumes stat reports under their own devices"
                )
            uses.append(
                f"map={line.decode('utf-8', errors='surrogateescape')}{identity_match}"
            )
            break
        if uses:
            refusal = Refusal(
                f"live process {pid} uses slot {fenced_path}: {uses[0]}; stop it and retry"
            )
            if not capture_generation:
                raise refusal
            return _LiveUseObservation(pid, start_ticks, proc_root, refusal)
    return None


_ScanResult = TypeVar("_ScanResult")


def _run_bounded_scan(
    work: Callable[[threading.Event], _ScanResult],
    *,
    seconds: float,
    on_timeout: Callable[[], Refusal],
) -> _ScanResult:
    """Run ``work`` on a daemon thread and wait for it at most ``seconds``.

    The thread runs in a copy of the caller's context, so it sees the
    caller's remove-agent-batch item budget.  ``work`` receives an event that
    is set when the wait ends; a scan that checks it stops, and a scan
    blocked in a system call is abandoned and ends on its own.  Its exception
    is raised here.
    """

    cancel = threading.Event()
    results: list[_ScanResult] = []
    failures: list[BaseException] = []

    def target() -> None:
        try:
            results.append(work(cancel))
        except BaseException as exc:  # re-raised in the caller's thread
            failures.append(exc)

    thread = threading.Thread(
        target=contextvars.copy_context().run,
        args=(target,),
        name="wrkslots-bounded-scan",
        daemon=True,
    )
    thread.start()
    thread.join(max(0.0, seconds))
    if thread.is_alive():
        cancel.set()
        raise on_timeout()
    if failures:
        raise failures[0]
    return results[0]


def _run_item_scan(
    work: Callable[[threading.Event], _ScanResult],
    what: str,
    *,
    seconds: float | None = None,
    grace: float = 0.0,
) -> _ScanResult:
    """Run one process-use scan of a remove-agent-batch item within its bounds.

    The scan receives ``seconds`` (by default _AGENT_REMOVE_BATCH_SCAN_SECONDS),
    or the item budget that remains when that is less, plus ``grace``.  When
    the item budget is what runs out, the item is refused for its budget.
    """

    if seconds is None:
        seconds = _AGENT_REMOVE_BATCH_SCAN_SECONDS
    item_left = _item_seconds_left(what)
    limited_by_item = item_left is not None and item_left < seconds
    wait = (item_left if limited_by_item and item_left is not None else seconds) + grace

    def timed_out() -> Refusal:
        if limited_by_item:
            return _item_budget_refusal(what)
        return Refusal(
            f"process use is indeterminate because {what} exceeded its "
            f"{seconds:g}-second bound"
        )

    return _run_bounded_scan(work, seconds=wait, on_timeout=timed_out)


@dataclasses.dataclass
class _AgentRemoveBatchContext:
    """The process-use evidence and item budget of one agent removal batch.

    Before an item's path fence, ``observe`` serves its use checks at the
    unfenced slot path from the shared lsof scan and a fresh /proc scan.
    After the fence, ``observe_fenced`` serves the checks that guard deletion
    with one /proc scan that compares identities with the fenced tree, and
    runs the ordinary lsof check of the fenced path when that scan cannot
    decide.

    ``identities`` holds each target directory's device and inode from before
    the shared scan; only the checks before the fence compare them, since the
    fence of an image-backed slot can change them.  ``censused`` names the targets whose identity was
    unchanged across the scan that produced ``census`` and about which lsof
    reported nothing; ``unobservable`` holds the lsof diagnostic for each
    target it did report on.  ``nested_git_evidence`` is filled by each
    item's removal with the disposable nested repositories it deleted.
    ``item_seconds`` is the budget of each item's work before deletion (see
    _AGENT_REMOVE_BATCH_ITEM_SECONDS), and ``last_seconds_before_deletion``
    is how long the last item held the registry lock before it began
    deleting, or None when it did not reach deletion.

    ``image_targets`` names the image-backed targets.  The fence of such a
    slot mounts its image again, possibly from another device, so the
    identity scan after the fence cannot match a process still working in
    the old mount, for example through a detached bind alias in a mount
    namespace of its own, and would report the slot unused.  Immediately
    before the fence of such a target, ``observe_image_before_fence`` runs
    the ordinary lsof check, as 'remove --no-lock-budget' does there, held
    to the item budget; it finds such a process while the old mount is
    still the slot's.
    """

    identities: dict[Path, tuple[int, int]]
    image_targets: frozenset[Path] = frozenset()
    census: _ProcessPathCensus = dataclasses.field(
        default_factory=lambda: _ProcessPathCensus((), (), owner_cgroup_complete=False)
    )
    censused: frozenset[Path] = frozenset()
    unobservable: Mapping[Path, str] = dataclasses.field(default_factory=dict)
    captured_at: float = 0.0
    shared_census_count: int = 0
    shared_census_seconds: float = 0.0
    fresh_scan_count: int = 0
    fresh_scan_seconds: float = 0.0
    fenced_scan_count: int = 0
    fenced_scan_seconds: float = 0.0
    fenced_lsof_fallbacks: list[str] = dataclasses.field(default_factory=list)
    fenced_lsof_fallback_seconds: float = 0.0
    image_lsof_check_count: int = 0
    image_lsof_check_seconds: float = 0.0
    nested_git_evidence: list[dict[str, object]] = dataclasses.field(
        default_factory=list
    )
    item_seconds: float = dataclasses.field(
        default_factory=lambda: _AGENT_REMOVE_BATCH_ITEM_SECONDS
    )
    last_seconds_before_deletion: float | None = None

    def capture(self, targets: Sequence[Path]) -> None:
        """Replace the shared evidence with one new scan of ``targets``."""

        selected = [
            target
            for target in targets
            if _directory_identity(target) == self.identities[target]
        ]
        self.census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
        self.censused = frozenset()
        self.unobservable = {}
        started = time.monotonic()
        self.shared_census_count += 1
        try:
            shared = _capture_agent_remove_batch_census(selected)
        finally:
            self.shared_census_seconds += time.monotonic() - started
        self.census = shared.census
        self.unobservable = dict(shared.unobservable)
        self.censused = frozenset(
            target
            for target in selected
            if target not in shared.unobservable
            and _directory_identity(target) == self.identities[target]
        )
        self.captured_at = time.monotonic()
        _interrupt_for_test("after-agent-batch-shared-census")

    def observe_image_before_fence(
        self,
        check_path: Path,
        record: ActiveRecord | None,
        *,
        canonical_path: Path,
        capture_generation: bool,
    ) -> _LiveUseObservation | None:
        """Run the ordinary lsof check of an image-backed target just before its fence.

        See ``image_targets``.  It is bounded like the lsof check after the
        fence that ``observe_fenced`` falls back to.
        """

        if check_path != canonical_path or canonical_path not in self.image_targets:
            raise StateError(
                f"an agent removal batch checks only an image-backed slot's unfenced "
                f"path with lsof before its fence, not {check_path}"
            )
        started = time.monotonic()
        self.image_lsof_check_count += 1
        try:
            # lsof is itself held to the item budget and stopped when it runs
            # out; this wait bounds the in-process scan that follows it.
            return _run_item_scan(
                lambda _cancel: _observe_slot_use_once(
                    check_path, record, capture_generation=capture_generation
                ),
                "the lsof check of an image-backed slot before the path fence",
                seconds=_AGENT_REMOVE_BATCH_LSOF_SECONDS,
                grace=_AGENT_REMOVE_BATCH_TERM_GRACE_SECONDS
                + _AGENT_REMOVE_BATCH_REAP_SECONDS,
            )
        finally:
            self.image_lsof_check_seconds += time.monotonic() - started

    def observe(
        self,
        check_path: Path,
        record: ActiveRecord | None,
        *,
        canonical_path: Path,
        capture_generation: bool,
    ) -> _LiveUseObservation | None:
        if check_path != canonical_path:
            raise StateError(
                f"an agent removal batch checks only the unfenced slot path "
                f"{canonical_path}, not {check_path}"
            )
        diagnostic = self.unobservable.get(canonical_path)
        if diagnostic is not None:
            raise Refusal(
                f"process use is indeterminate because lsof reported: {diagnostic}"
            )
        if canonical_path not in self.censused:
            raise Refusal(
                f"slot {canonical_path} was not covered by this batch's shared "
                "process census"
            )
        if _directory_identity(check_path) != self.identities[canonical_path]:
            raise Refusal(
                f"slot directory {check_path} is not the directory this batch's "
                "shared process census covered"
            )
        self.census.assert_slot_unused(canonical_path, None)
        started = time.monotonic()
        self.fresh_scan_count += 1
        try:
            return _run_item_scan(
                lambda _cancel: _agent_batch_fresh_use(
                    check_path, record, capture_generation=capture_generation
                ),
                "the /proc scan before the path fence",
            )
        finally:
            self.fresh_scan_seconds += time.monotonic() - started

    def observe_fenced(
        self,
        check_path: Path,
        record: ActiveRecord | None,
        *,
        canonical_path: Path,
        capture_generation: bool,
    ) -> _LiveUseObservation | None:
        """Check a fenced slot for use, as the ordinary check after the fence does.

        A /proc scan compares every process's cwd, root, exe, descriptors and
        mappings with the fenced tree by path and by device and inode, which
        is what lsof compares; see _agent_batch_fenced_use.  When that scan
        cannot decide, the ordinary lsof check of the fenced path decides.

        Both read the fenced slot as it is when they run and use nothing
        gathered before the fence, so the fenced directory is not required to
        keep the device and inode ``identities`` recorded for it, and the
        ordinary check after the fence does not require it either.  An
        image-backed slot does not keep them: its fence unmounts the disk
        image and mounts it again at the fenced path, and the new mount can
        have another device number, for example another loop device.
        """

        if check_path == canonical_path:
            raise StateError(
                f"an agent removal batch check after the path fence must name the "
                f"fenced path, not the canonical slot path {canonical_path}"
            )
        if canonical_path not in self.identities:
            raise StateError(
                f"slot {canonical_path} is not a target of this agent removal batch"
            )
        if _directory_identity(check_path) is None:
            raise Refusal(f"fenced slot {check_path} is missing or is not a directory")
        started = time.monotonic()
        self.fenced_scan_count += 1
        try:
            verdict = _run_item_scan(
                lambda cancel: _agent_batch_fenced_use(
                    check_path,
                    canonical_path,
                    record,
                    capture_generation=capture_generation,
                    cancel=cancel,
                ),
                "the /proc scan after the path fence",
            )
        finally:
            self.fenced_scan_seconds += time.monotonic() - started
        if not isinstance(verdict, _UndecidedFencedUse):
            return verdict
        self.fenced_lsof_fallbacks.append(verdict.reason)
        started = time.monotonic()
        try:
            # lsof is itself held to the item budget and stopped when it runs
            # out; this wait bounds the in-process scan that follows it.
            return _run_item_scan(
                lambda _cancel: _observe_slot_use_once(
                    check_path, record, capture_generation=capture_generation
                ),
                "the lsof check after the path fence",
                seconds=_AGENT_REMOVE_BATCH_LSOF_SECONDS,
                grace=_AGENT_REMOVE_BATCH_TERM_GRACE_SECONDS
                + _AGENT_REMOVE_BATCH_REAP_SECONDS,
            )
        finally:
            self.fenced_lsof_fallback_seconds += time.monotonic() - started


class _AgentBatchUseCheck(TypedDict, total=False):
    agent_batch: _AgentRemoveBatchContext
    canonical_path: Path
    after_fence: bool
    before_image_fence: bool


def _agent_batch_use_check(
    agent_batch: _AgentRemoveBatchContext | None,
    canonical_path: Path | None,
    *,
    after_fence: bool = False,
    before_image_fence: bool = False,
) -> _AgentBatchUseCheck:
    """Keywords that route one slot-use check through an agent removal batch.

    Outside a batch this is empty, so every ordinary use check receives
    exactly the arguments it always has, and so does any replacement
    installed for it.  ``after_fence`` marks a check of the fenced path,
    whose ``canonical_path`` names the slot's unfenced path, and
    ``before_image_fence`` the lsof check of an image-backed slot made just
    before its fence.
    """

    if agent_batch is None:
        return {}
    keywords: _AgentBatchUseCheck = {"agent_batch": agent_batch}
    if canonical_path is not None:
        keywords["canonical_path"] = canonical_path
    if after_fence:
        keywords["after_fence"] = True
    if before_image_fence:
        keywords["before_image_fence"] = True
    return keywords


def _single_remove_agent_batch(
    config: Config, slot: str
) -> _AgentRemoveBatchContext | None:
    """Prepare ordinary remove of one agent slot as a remove-agent-batch of one.

    The registry lock is held for a whole removal, and every client that
    writes the registry waits for it.  Ordinary remove used to run ``lsof +D``
    over the slot under that lock four times, and the cost of each run grows
    with the number of files in the slot: on a 33 GB slot of 68,888 entries,
    at load average about 260, one run took 9 to 18 seconds.  A batch of one
    instead runs that single ``lsof +D`` here, before the lock is taken, and
    uses remove-agent-batch's checks under the lock: before the path fence, a
    fresh /proc scan and a check that the slot directory is the one lsof
    covered; after the fence, the /proc scan that compares identities with
    the fenced tree, which falls back to the ordinary lsof check only when it
    cannot decide.  The item budget (_AGENT_REMOVE_BATCH_ITEM_SECONDS) bounds
    the work before the first deletion, except the stretches it names.

    The lock-free read here only selects the path to scan; the removal
    decides everything again under the lock.  Returns None, so the ordinary
    checks run instead, for a slot that is not an active agent slot with a
    directory, for an image-backed slot, and on a host without lsof, where
    the ordinary check has its own fallback.  The fence of an image-backed
    slot mounts its image again, possibly from another device, so the scan
    after the fence could not match a process still using the old mount.
    """

    if _lsof_executable() is None:
        return None
    try:
        state = _load_active(config, require_repository=False)
    except Refusal:
        return None
    record = next((item for item in state.slots if item.slot == slot), None)
    if record is None or record.slot_type != "agent":
        return None
    slot_path = _slot_directory(config, slot, record.slot_type)
    identity = _directory_identity(slot_path)
    if identity is None:
        return None
    try:
        if _slot_image_at(config, slot_path) is not None:
            return None
    except Refusal:
        return None
    context = _AgentRemoveBatchContext({slot_path: identity})
    context.capture([slot_path])
    return context


def _removal_journal_candidate(config: Config, slot: str) -> Path | None:
    """Return a journal that a removal of this machine's ``slot`` may have left.

    Two files are read: this machine's registry journal and the slot's own
    finish journal.  A journal whose slot cannot be read counts.  This
    machine's append-only history is then replayed, because a mutation
    records its progress there before it writes the journal file: one
    interrupted between the two leaves a pending operation and no file.  A
    pending operation for ``slot``, or for no named slot, returns its
    journal path, which need not exist.  A history that cannot be replayed
    returns its event directory.  Ordinary remove still refuses every
    outstanding journal, of any kind and on any machine, under the registry
    lock.  This read takes no lock, so it also finds a journal that another
    client holds for an operation still in progress;
    _interrupted_removal_journal rechecks under the lock.

    The replay reads every event file.  Within one command the verified
    events are kept, so a later call only checks that each file is
    unchanged.
    """

    for path in (_journal_path(config), _finish_journal_path(config, slot)):
        if not path.exists() and not path.is_symlink():
            continue
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, ValueError):
            return path
        if not isinstance(value, dict) or value.get("slot") in (slot, None):
            return path
    try:
        pending = _pending_operations_from_events(config, config.machine)
    except (Refusal, OSError, UnicodeError, ValueError):
        return _event_directory(config, config.machine)
    for path, journal in sorted(pending.items()):
        if journal.get("slot") in (slot, None):
            return path
    return None


def _agent_row_still_active(config: Config, slot: str, generation: int) -> bool | None:
    """Return whether this machine's registry still holds ``slot`` at ``generation``.

    Returns None when the registry cannot be read.  remove-agent-batch uses
    this only to describe an item that an unexpected error interrupted.
    """

    try:
        state = _load_active(config, require_repository=False)
    except Exception:
        return None
    return any(
        record.slot == slot and record.generation == generation for record in state.slots
    )


def _interrupted_removal_journal(
    config: Config, slot: str, wait_seconds: float
) -> Path | None:
    """Return a journal that an interrupted removal of this machine's ``slot`` left.

    A removal that fails after writing its finish journal and cannot roll it
    back leaves that journal for 'wrkslots recover'.  A removal of an agent
    slot writes and retires its journal inside one registry-lock hold, so a
    journal that is still present while this call holds the lock was left by
    an interrupted operation, not by one in progress.  The lock is taken only
    when a lock-free read finds a candidate, so the common case waits for no
    lock.  A validation removal can keep its journal across a lock release
    while it runs its process census, so for a validation slot a journal found
    here can still belong to a removal in progress; remove-agent-batch refuses
    validation slots in any case.  Raises Refusal when the lock is not taken
    within ``wait_seconds``.
    """

    if _removal_journal_candidate(config, slot) is None:
        return None
    with _mutation_locks(config, wait_seconds):
        return _removal_journal_candidate(config, slot)


def _read_agent_batch_items(args: argparse.Namespace) -> tuple[tuple[str, int], ...]:
    raw: list[str] = list(getattr(args, "slots", None) or ())
    input_path = getattr(args, "input", None)
    if input_path is not None:
        try:
            text = Path(input_path).read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise Refusal(f"cannot read --input {input_path}: {exc}") from exc
        for line in text.splitlines():
            stripped = line.strip()
            if stripped and not stripped.startswith("#"):
                raw.append(stripped)
    if not raw:
        raise Refusal("remove-agent-batch needs at least one --slot or a non-empty --input")
    requested = tuple(_parse_validate_batch_slot(value) for value in raw)
    if len(requested) > AGENT_REMOVE_BATCH_LIMIT:
        raise Refusal(
            f"remove-agent-batch accepts at most {AGENT_REMOVE_BATCH_LIMIT} slots; "
            "run another bounded batch for the remainder"
        )
    if len({slot for slot, _generation in requested}) != len(requested):
        raise Refusal("remove-agent-batch received the same slot more than once")
    return requested


def _remove_agent_batch(args: argparse.Namespace) -> dict[str, object]:
    requested = _read_agent_batch_items(args)
    config = _load_config(args.project_root, args.machine)
    if getattr(args, "salvage_archive_root", None) is not None:
        _local_salvage_archive_root(config, args.salvage_archive_root)
    started = time.monotonic()
    removed: list[dict[str, object]] = []
    refused: list[dict[str, object]] = []
    recovery_required = False
    decided: set[str] = set()

    def refuse(slot: str, generation: int, reason: str, **extra: object) -> None:
        decided.add(slot)
        refused.append(
            {"slot": slot, "generation": generation, "reason": reason, **extra}
        )

    def recovery_reason(journal: Path) -> str:
        if journal == _event_directory(config, config.machine):
            return (
                f"the append-only history in {journal} cannot be replayed, so an "
                "interrupted removal cannot be ruled out; run 'wrkslots recover' "
                "before another removal"
            )
        return (
            f"an interrupted removal is recorded in {journal}; run 'wrkslots "
            "recover' before another removal"
        )

    def unconfirmed_reason(exc: Exception) -> str:
        return (
            "a removal journal for this slot exists, and whether an interrupted "
            f"removal left it could not be checked under the registry lock: {exc}"
        )

    unconfirmed_stop = (
        "batch stopped: a removal journal could not be checked under the registry "
        "lock; retry the remaining slots"
    )

    def stop_remaining(reason: str) -> None:
        for later_slot, later_generation in requested:
            if later_slot not in decided:
                refuse(later_slot, later_generation, reason)

    wait_seconds = (
        args.wait_lock if args.wait_lock > 0 else AGENT_REMOVE_BATCH_WAIT_LOCK_SECONDS
    )
    # Read-only preflight.  It selects the paths the shared scan must cover;
    # every item is decided again under the registry lock by ordinary remove.
    # Only a journal found by the lock-free read is rechecked under the lock.
    state = _load_active(config, require_repository=False)
    records = {record.slot: record for record in state.slots}
    eligible: list[tuple[str, int, Path]] = []
    identities: dict[Path, tuple[int, int]] = {}
    image_targets: set[Path] = set()
    for slot, generation in requested:
        try:
            interrupted = _interrupted_removal_journal(config, slot, wait_seconds)
        except Refusal as exc:
            refuse(slot, generation, unconfirmed_reason(exc))
            stop_remaining(unconfirmed_stop)
            eligible.clear()
            break
        if interrupted is not None:
            recovery_required = True
            refuse(slot, generation, recovery_reason(interrupted), recovery_required=True)
            stop_remaining(
                "batch stopped: an interrupted removal must be recovered first; run "
                "'wrkslots recover' and retry the remaining slots"
            )
            eligible.clear()
            break
        record = records.get(slot)
        if record is None:
            refuse(slot, generation, f"slot {slot!r} is not active on machine {config.machine}")
            continue
        if record.generation != generation:
            refuse(
                slot,
                generation,
                f"slot {slot} generation is {record.generation}, not {generation}",
            )
            continue
        if record.slot_type != "agent":
            refuse(
                slot,
                generation,
                "remove-agent-batch accepts only agent slots; use remove-validate-batch "
                "for validation slots",
            )
            continue
        slot_path = _slot_directory(config, slot, record.slot_type)
        identity = _directory_identity(slot_path)
        if identity is None:
            refuse(
                slot,
                generation,
                f"slot directory is missing or unsafe: {slot_path}; use "
                "recover-absent-agent-rows (or recover-absent-agent-row) for a row "
                "whose storage is absent",
            )
            continue
        try:
            image_backed = _slot_image_at(config, slot_path) is not None
        except Refusal as exc:
            refuse(slot, generation, str(exc))
            continue
        if image_backed:
            image_targets.add(slot_path)
        identities[slot_path] = identity
        eligible.append((slot, generation, slot_path))
    context = _AgentRemoveBatchContext(
        identities, image_targets=frozenset(image_targets)
    )
    remaining_targets = [slot_path for _slot, _generation, slot_path in eligible]
    error: str | None = None
    # The item being attempted, so that an unexpected error can name it.
    current: tuple[str, int, float] | None = None
    try:
        for index, (slot, generation, slot_path) in enumerate(eligible):
            if context.shared_census_count == 0 or (
                time.monotonic() - context.captured_at
                > _AGENT_REMOVE_BATCH_CENSUS_MAX_AGE_SECONDS
            ):
                try:
                    context.capture(remaining_targets[index:])
                except Refusal as exc:
                    stop_remaining(str(exc))
                    break
            if index:
                # Waiters poll the registry lock every 50 ms; leave them a window
                # between items so a batch never starves heartbeats.
                time.sleep(_AGENT_REMOVE_BATCH_YIELD_SECONDS)
            item_args = argparse.Namespace(**vars(args))
            item_args.command = "remove"
            item_args.slot = slot
            item_args.expected_generation = generation
            item_args.validate_complete = False
            item_args.validation_proof_manifest = None
            item_args.completed_record = None
            item_args.wait_lock = wait_seconds
            item_started = time.monotonic()
            current = (slot, generation, item_started)
            context.nested_git_evidence.clear()
            context.last_seconds_before_deletion = None
            try:
                _cmd_remove(item_args, emit=False, agent_batch=context)
            except Refusal as exc:
                seconds = round(time.monotonic() - item_started, 3)
                # StateError is a Refusal too.  Whether the batch can go on
                # depends only on whether the item left an interrupted removal,
                # not on the class of the exception: an invariant check raises
                # StateError before any journal exists, and a refusal after the
                # finish journal was written normally rolls the journal back.
                # When it cannot, the journal stays for 'wrkslots recover' and no
                # later item can proceed.
                try:
                    interrupted = _interrupted_removal_journal(config, slot, wait_seconds)
                except Refusal as check:
                    refuse(
                        slot,
                        generation,
                        f"{exc}; {unconfirmed_reason(check)}",
                        seconds=seconds,
                    )
                    stop_remaining(unconfirmed_stop)
                    break
                if interrupted is None:
                    refuse(slot, generation, str(exc), seconds=seconds)
                else:
                    recovery_required = True
                    refuse(
                        slot,
                        generation,
                        f"{exc}; {recovery_reason(interrupted)}",
                        seconds=seconds,
                        recovery_required=True,
                    )
                    stop_remaining(
                        "batch stopped: an earlier item left an interrupted removal; run "
                        "'wrkslots recover' and retry the remaining slots"
                    )
                    break
            else:
                decided.add(slot)
                before_deletion = context.last_seconds_before_deletion
                removed.append(
                    {
                        "slot": slot,
                        "generation": generation,
                        "seconds": round(time.monotonic() - item_started, 3),
                        "seconds_before_deletion": (
                            None if before_deletion is None else round(before_deletion, 3)
                        ),
                        "disposable_nested_repositories": list(context.nested_git_evidence),
                    }
                )
            current = None
            _interrupt_for_test("after-agent-batch-item")
    except Exception as exc:  # the report must survive any failure
        # Each item is atomic in the registry, so the removals already made
        # stand.  Report them, the item that failed, and the slots not yet
        # attempted, instead of losing the report with the traceback.
        error = f"{type(exc).__name__}: {exc}"
        print("wrkslots: remove-agent-batch stopped on an unexpected error:", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
        if current is not None and current[0] not in decided:
            failed_slot, failed_generation, failed_started = current
            reason = f"unexpected error: {error}"
            extra: dict[str, object] = {}
            try:
                interrupted = _interrupted_removal_journal(
                    config, failed_slot, wait_seconds
                )
            except Exception as check:
                reason += f"; {unconfirmed_reason(check)}"
            else:
                if interrupted is not None:
                    recovery_required = True
                    reason += f"; {recovery_reason(interrupted)}"
                    extra["recovery_required"] = True
                else:
                    still_active = _agent_row_still_active(
                        config, failed_slot, failed_generation
                    )
                    if still_active is None:
                        reason += (
                            "; the registry could not be read to tell whether the slot "
                            "is still active; read 'wrkslots status'"
                        )
                    elif still_active:
                        reason += (
                            f"; the slot is still active at generation {failed_generation} "
                            "and no interrupted removal is recorded"
                        )
                    else:
                        reason += (
                            f"; the slot is no longer active at generation "
                            f"{failed_generation}, so its removal may have completed "
                            "before the error; read 'wrkslots status'"
                        )
            refuse(
                failed_slot,
                failed_generation,
                reason,
                seconds=round(time.monotonic() - failed_started, 3),
                **extra,
            )
        stop_remaining("batch stopped after an unexpected error; retry the remaining slots")
    order = {slot: position for position, (slot, _generation) in enumerate(requested)}
    refused.sort(key=lambda item: order[_as_str(item["slot"], "refused slot")])
    return {
        "schema": 1,
        "batch_limit": AGENT_REMOVE_BATCH_LIMIT,
        "requested": len(requested),
        "removed": removed,
        "refused": refused,
        "recovery_required": recovery_required,
        "error": error,
        "shared_process_censuses": context.shared_census_count,
        "shared_process_census_seconds": round(context.shared_census_seconds, 3),
        "fresh_process_scans": context.fresh_scan_count,
        "fresh_process_scan_seconds": round(context.fresh_scan_seconds, 3),
        "fenced_process_scans": context.fenced_scan_count,
        "fenced_process_scan_seconds": round(context.fenced_scan_seconds, 3),
        "fenced_lsof_fallbacks": len(context.fenced_lsof_fallbacks),
        "fenced_lsof_fallback_reasons": list(context.fenced_lsof_fallbacks),
        "fenced_lsof_fallback_seconds": round(context.fenced_lsof_fallback_seconds, 3),
        "image_lsof_checks": context.image_lsof_check_count,
        "image_lsof_check_seconds": round(context.image_lsof_check_seconds, 3),
        "item_budget_seconds": context.item_seconds,
        "seconds": round(time.monotonic() - started, 3),
    }


def _cmd_remove_agent_batch(args: argparse.Namespace) -> int:
    payload = _remove_agent_batch(args)
    removed = _as_list(payload["removed"], "removed")
    refused = _as_list(payload["refused"], "refused")
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        print(
            f"requested={payload['requested']} removed={len(removed)} "
            f"refused={len(refused)} "
            f"shared_process_censuses={payload['shared_process_censuses']} "
            f"fresh_process_scans={payload['fresh_process_scans']} "
            f"fenced_process_scans={payload['fenced_process_scans']} "
            f"fenced_lsof_fallbacks={payload['fenced_lsof_fallbacks']} "
            f"item_budget_seconds={payload['item_budget_seconds']:g} "
            f"seconds={payload['seconds']}"
        )
        for value in removed:
            row = _as_mapping(value, "removed item")
            print(f"REMOVED: {row['slot']} generation={row['generation']}")
            _print_nested_git_evidence(
                [
                    _as_mapping(item, "removed nested repository")
                    for item in _as_list(
                        row["disposable_nested_repositories"],
                        "removed nested repositories",
                    )
                ]
            )
        for value in refused:
            row = _as_mapping(value, "refused item")
            print(
                f"REFUSED: {row['slot']} generation={row['generation']} "
                f"reason={row['reason']}"
            )
        if payload["error"] is not None:
            print(f"ERROR: {payload['error']}")
        if payload["recovery_required"]:
            print("RECOVERY REQUIRED: run 'wrkslots recover' before another removal")
    # Success means every requested slot was removed.  Any refusal, including
    # a batch that removed nothing, and any unexpected error is exit status 1.
    return 0 if removed and not refused and payload["error"] is None else 1


def _recover_partial_updates(config: Config, discard: bool) -> bool:
    leftovers = sorted(config.control.glob("ACTIVE.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ARCHIVED.*.json.tmp.*"))
    leftovers += sorted(config.control.glob("ACTIVE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("CREATE.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("FINISH.*.journal.tmp.*"))
    leftovers += sorted(config.control.glob("HANDOFF.*.json.tmp.*"))
    leftovers += sorted(
        config.control.glob("VALIDATE-BATCH-SEAL.*.journal.tmp.*")
    )
    for event_directory in sorted(config.control.glob("EVENTS.*")):
        if event_directory.is_dir() and not event_directory.is_symlink():
            leftovers += sorted(event_directory.glob("*.json.tmp.*"))
    if not leftovers:
        return False
    if not discard:
        raise StateError(
            f"partial atomic update found: {leftovers[0]}; inspect it, then rerun recover "
            "with --discard-partial to keep the last durable state"
        )
    for leftover in leftovers:
        if leftover.is_symlink() or not leftover.is_file():
            raise StateError(f"partial state path is not a regular file: {leftover}")
        marker = ".tmp."
        target_name, separator, _suffix = leftover.name.partition(marker)
        if not separator:
            raise StateError(f"unrecognized partial state filename: {leftover}")
        target = leftover.parent / target_name
        event_directory_match = re.fullmatch(
            r"EVENTS\.([A-Za-z0-9][A-Za-z0-9._-]{0,63})", leftover.parent.name
        )
        event_name_match = re.fullmatch(r"([0-9]{20})\.json", target.name)
        if event_directory_match is not None and event_name_match is not None:
            machine = event_directory_match.group(1)
            same_target = sorted(leftover.parent.glob(f"{target.name}.tmp.*"))
            if len(same_target) != 1:
                raise StateError(
                    f"cannot recover append-only event {target.name}: multiple temp files exist"
                )
            durable_paths = sorted(
                entry
                for entry in leftover.parent.iterdir()
                if re.fullmatch(r"[0-9]{20}\.json", entry.name)
            )
            durable_events = _load_event_paths(durable_paths, machine)
            if target.exists() or target.is_symlink():
                if target.is_symlink() or not target.is_file():
                    raise StateError(
                        f"cannot discard {leftover}: durable event is unsafe: {target}"
                    )
                leftover.unlink()
                _fsync_directory(leftover.parent)
                print(
                    f"discarded incomplete append-only event {leftover.name}; "
                    f"kept durable {target.name}"
                )
                continue
            expected_sequence = len(durable_events) + 1
            if int(event_name_match.group(1)) != expected_sequence:
                raise StateError(
                    f"cannot recover append-only event {target.name}: expected sequence "
                    f"{expected_sequence:020d}"
                )
            previous = (
                "0" * 64
                if not durable_events
                else _as_str(
                    durable_events[-1]["sha256"], "append-only event.sha256"
                )
            )
            _event_from_path(
                leftover,
                machine,
                expected_sequence,
                previous,
                require_filename=False,
            )
            _forget_event_chain(_event_directory(config, machine), machine)
            os.replace(leftover, target)
            _fsync_directory(target.parent)
            _load_events(config, machine)
            print(f"recovered append-only event {target.name} from {leftover.name}")
            continue
        active_match = re.fullmatch(
            r"ACTIVE\.([A-Za-z0-9][A-Za-z0-9._-]{0,63})\.json", target.name
        )
        archive_match = re.fullmatch(
            r"ARCHIVED\.([A-Za-z0-9][A-Za-z0-9._-]{0,63})\.json", target.name
        )
        scoped_create = re.fullmatch(r"CREATE\..+\.journal", target.name)
        handoff_sidecar = target.name.startswith("HANDOFF.") and target.name.endswith(
            ".json"
        )
        if not target.exists() and not target.is_symlink():
            matches = sorted(leftover.parent.glob(f"{target.name}.tmp.*"))
            if len(matches) != 1:
                raise StateError(
                    f"cannot recover initial state for {target.name}: multiple temp files exist"
                )
            raw = _as_mapping(_read_json(leftover, "initial state temp file"), "initial state temp file")
            machine_match = active_match or archive_match
            if machine_match is None and scoped_create is None and not handoff_sidecar:
                raise StateError(
                    f"cannot promote temp file without a durable target: {leftover}"
                )
            if handoff_sidecar:
                contents, identity = _read_regular_file_identity(
                    leftover, "handoff sidecar temp file", HANDOFF_SIDECAR_BYTES_LIMIT
                )
                raw = _as_mapping(
                    _strict_json_object(contents, "handoff sidecar temp file"),
                    "handoff sidecar temp file",
                )
                machine = _as_str(raw.get("machine"), "handoff temp machine")
                slot = _as_str(raw.get("slot"), "handoff temp slot")
                generation = _as_int(
                    raw.get("generation"), "handoff temp generation", minimum=1
                )
                state = _load_active(config, machine, require_repository=False)
                record = _find_record(state, slot)
                _expected_generation(record, generation)
                artifact = _handoff_artifact_from_obj(
                    config, record, raw, target, identity
                )
                authority_kind, intent_sequence, read_payload = (
                    _assert_handoff_sidecar_publication(
                        config,
                        record,
                        artifact,
                        allow_outstanding_write=True,
                    )
                )
                _interrupt_for_test("before-handoff-temp-recovery-publish")
                _rename_noreplace(
                    leftover, target, "recover handoff sidecar publication"
                )
                _fsync_directory(target.parent)
                _verify_noreplace_handoff_move(
                    leftover,
                    target,
                    contents,
                    identity,
                    "recovered handoff sidecar",
                )
                if authority_kind == "write-handoff":
                    assert intent_sequence is not None
                    _complete_handoff_write_publication(
                        config, record, intent_sequence, artifact
                    )
                else:
                    assert read_payload is not None
                    _complete_legacy_projection(
                        config, record, artifact, read_payload
                    )
                print(
                    f"recovered handoff sidecar {target.name} from {leftover.name}"
                )
                continue
            if scoped_create is not None:
                _validate_journal_shape(config, target, raw)
                os.replace(leftover, target)
                _fsync_directory(target.parent)
                print(
                    f"recovered scoped create journal {target.name} "
                    f"from {leftover.name}"
                )
                continue
            assert machine_match is not None
            if (
                _as_int(raw.get("schema"), "initial state schema") != SCHEMA
                or _as_str(raw.get("machine"), "initial state machine")
                != machine_match.group(1)
            ):
                raise StateError(f"initial state temp file is invalid: {leftover}")
            os.replace(leftover, target)
            _fsync_directory(target.parent)
            if active_match is not None:
                _load_active(config, active_match.group(1))
            else:
                assert archive_match is not None
                _load_archive(config, archive_match.group(1))
            print(f"recovered initial state {target.name} from {leftover.name}")
            continue
        if not target.is_file() or target.is_symlink():
            raise StateError(
                f"cannot discard {leftover}: last durable state is unsafe: {target}"
            )
        if active_match is not None:
            machine = active_match.group(1)
            state = _load_active(config, machine)
            if _load_events(config, machine):
                leftover.unlink()
                _fsync_directory(leftover.parent)
                _atomic_write_json(target, _active_to_obj(state))
                print(
                    f"discarded incomplete atomic update {leftover.name}; refreshed "
                    f"{target.name} from the append-only log"
                )
                continue
        elif archive_match is not None:
            machine = archive_match.group(1)
            archive_state = _load_archive(config, machine)
            if _load_events(config, machine):
                leftover.unlink()
                _fsync_directory(leftover.parent)
                _atomic_write_json(target, _archive_to_obj(archive_state))
                print(
                    f"discarded incomplete atomic update {leftover.name}; refreshed "
                    f"{target.name} from the append-only log"
                )
                continue
        elif target.name.endswith(".journal"):
            raise StateError(
                f"cannot automatically discard journal update {leftover}; "
                "preserve both files for explicit inspection"
            )
        elif handoff_sidecar:
            target_contents, target_identity = _read_regular_file_identity(
                target, "handoff sidecar", HANDOFF_SIDECAR_BYTES_LIMIT
            )
            target_raw = _as_mapping(
                _strict_json_object(target_contents, "handoff sidecar"),
                "handoff sidecar",
            )
            machine = _as_str(target_raw.get("machine"), "handoff sidecar machine")
            slot = _as_str(target_raw.get("slot"), "handoff sidecar slot")
            record = _find_record(
                _load_active(config, machine, require_repository=False), slot
            )
            target_artifact = _handoff_artifact_from_obj(
                config, record, target_raw, target, target_identity
            )
            temp_contents, temp_identity = _read_regular_file_identity(
                leftover, "handoff sidecar temp file", HANDOFF_SIDECAR_BYTES_LIMIT
            )
            temp_artifact = _handoff_artifact_from_obj(
                config,
                record,
                _strict_json_object(temp_contents, "handoff sidecar temp file"),
                target,
                temp_identity,
            )
            if _handoff_artifact_to_obj(temp_artifact) != _handoff_artifact_to_obj(
                target_artifact
            ):
                raise StateError(
                    f"handoff sidecar temp file disagrees with durable target; "
                    f"preserved both {leftover} and {target}"
                )
            authority_kind, intent_sequence, read_payload = (
                _assert_handoff_sidecar_publication(
                    config,
                    record,
                    target_artifact,
                    allow_outstanding_write=True,
                )
            )
            retired = _retired_handoff_temp_path(target, temp_identity)
            if retired.exists() or retired.is_symlink():
                raise StateError(
                    f"retired duplicate handoff temp already exists: {retired}"
                )
            _interrupt_for_test("before-handoff-temp-quarantine")
            _rename_noreplace(
                leftover, retired, "quarantine duplicate handoff temp file"
            )
            _fsync_directory(leftover.parent)
            try:
                retired_contents, retired_identity = _read_regular_file_identity(
                    retired,
                    "retired duplicate handoff temp file",
                    HANDOFF_SIDECAR_BYTES_LIMIT,
                )
                if retired_identity != temp_identity or retired_contents != temp_contents:
                    raise StateError(
                        "duplicate handoff temp identity changed at quarantine boundary"
                    )
            except (Refusal, StateError) as exc:
                if not leftover.exists() and not leftover.is_symlink():
                    try:
                        _rename_noreplace(
                            retired,
                            leftover,
                            "restore raced duplicate handoff temp file",
                        )
                        _fsync_directory(leftover.parent)
                    except Refusal as restore:
                        raise StateError(
                            f"{exc}; raced temp also could not be restored: {restore}"
                        ) from restore
                raise StateError(
                    f"handoff sidecar temp changed at quarantine boundary; "
                    f"preserved it at {leftover}"
                ) from exc
            current_contents, current_identity = _read_regular_file_identity(
                target, "handoff sidecar", HANDOFF_SIDECAR_BYTES_LIMIT
            )
            if current_identity != target_identity or current_contents != target_contents:
                raise StateError(
                    f"durable handoff sidecar changed during temp recovery; "
                    f"preserved both {target} and {retired}"
                )
            if authority_kind == "write-handoff":
                assert intent_sequence is not None
                _complete_handoff_write_publication(
                    config, record, intent_sequence, target_artifact
                )
            else:
                assert read_payload is not None
                _complete_legacy_projection(
                    config, record, target_artifact, read_payload
                )
            print(
                f"quarantined exact duplicate handoff temp {leftover.name}; "
                f"kept durable {target.name}"
            )
            continue
        else:
            raise StateError(f"unrecognized durable state target: {target}")
        leftover.unlink()
        _fsync_directory(leftover.parent)
        print(f"discarded incomplete atomic update {leftover.name}; kept {target.name}")
    return True


_EMPTY_SUBMODULE_ADMIN_DIRECTORY_LIMIT = 4096
_EMPTY_SUBMODULE_ADMIN_DEPTH_LIMIT = 64


@dataclasses.dataclass(frozen=True)
class _EmptySubmoduleAdministration:
    """Identity-bound proof that one worktree's module administration is empty."""

    common_directory: Path
    common_identity: tuple[int, int, int]
    git_directory: Path
    git_directory_identity: tuple[int, int, int]
    directories: tuple[tuple[tuple[str, ...], tuple[int, int, int]], ...]


def _submodule_admin_identity(
    directory_fd: int, path: Path, mount_id: int
) -> tuple[int, int, int]:
    try:
        metadata = os.fstat(directory_fd)
    except OSError as exc:
        raise Refusal(f"cannot inspect submodule administration {path}: {exc}") from exc
    identity = (
        metadata.st_dev,
        metadata.st_ino,
        _fd_mount_id(directory_fd, str(path)),
    )
    if identity[2] != mount_id:
        raise Refusal(f"submodule administration crosses a mount point: {path}")
    return identity


def _submodule_admin_names(directory_fd: int, path: Path) -> tuple[str, ...]:
    return tuple(
        _directory_names(
            directory_fd,
            path,
            entry_limit=_EMPTY_SUBMODULE_ADMIN_DIRECTORY_LIMIT,
            label="submodule administration",
        )
    )


def _open_submodule_administration(
    vcs: _GitVcs,
    checkout: Path,
    *,
    expected: _EmptySubmoduleAdministration | None = None,
) -> tuple[
    int,
    int,
    Path,
    Path,
    Path,
    tuple[int, int, int],
    tuple[int, int, int],
] | None:
    common, git_directory = vcs.linked_worktree_git_directory(checkout)
    common_identity = _open_directory_identity(common, "Git common directory")
    if expected is not None and (
        common != expected.common_directory
        or common_identity != expected.common_identity
        or git_directory != expected.git_directory
    ):
        raise Refusal(
            "linked-worktree Git administration changed before abort cleanup"
        )
    modules = git_directory / "modules"
    git_fd, name, mount_id = _open_parent_directory(
        common,
        modules,
        "submodule administration",
        expected_root_identity=common_identity,
    )
    try:
        git_identity = _submodule_admin_identity(git_fd, git_directory, mount_id)
        if expected is not None and git_identity != expected.git_directory_identity:
            raise Refusal(
                "linked-worktree Git administration changed before abort cleanup"
            )
        try:
            named = os.stat(name, dir_fd=git_fd, follow_symlinks=False)
        except FileNotFoundError:
            os.close(git_fd)
            return None
        if not stat.S_ISDIR(named.st_mode):
            kind = "symlink" if stat.S_ISLNK(named.st_mode) else "non-directory entry"
            raise Refusal(f"submodule administration is a {kind}: {modules}")
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
        modules_fd = os.open(name, flags, dir_fd=git_fd)
        try:
            modules_identity = _submodule_admin_identity(
                modules_fd, modules, mount_id
            )
            if modules_identity[:2] != (named.st_dev, named.st_ino):
                raise Refusal(
                    f"submodule administration changed during inspection: {modules}"
                )
            if (
                expected is not None
                and dict(expected.directories).get(()) != modules_identity
            ):
                raise Refusal(
                    "submodule administration changed between abort preflight and removal"
                )
        except BaseException:
            os.close(modules_fd)
            raise
        return (
            git_fd,
            modules_fd,
            modules,
            common,
            git_directory,
            common_identity,
            git_identity,
        )
    except OSError as exc:
        os.close(git_fd)
        raise Refusal(f"cannot open submodule administration {modules}: {exc}") from exc
    except BaseException:
        os.close(git_fd)
        raise


def _snapshot_empty_submodule_admin_tree(
    directory_fd: int,
    path: Path,
    relative: tuple[str, ...],
    mount_id: int,
    observed: list[tuple[tuple[str, ...], tuple[int, int, int]]],
) -> None:
    if len(relative) > _EMPTY_SUBMODULE_ADMIN_DEPTH_LIMIT:
        raise Refusal("submodule administration exceeds its directory-depth bound")
    if len(observed) >= _EMPTY_SUBMODULE_ADMIN_DIRECTORY_LIMIT:
        raise Refusal("submodule administration exceeds its directory-count bound")
    identity = _submodule_admin_identity(directory_fd, path, mount_id)
    observed.append((relative, identity))
    names = _submodule_admin_names(directory_fd, path)
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        for name in names:
            child_path = path / name
            child = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            if not stat.S_ISDIR(child.st_mode):
                kind = (
                    "symlink" if stat.S_ISLNK(child.st_mode) else "non-directory entry"
                )
                raise Refusal(
                    f"submodule administration contains a {kind}: {child_path}"
                )
            child_fd = os.open(name, flags, dir_fd=directory_fd)
            try:
                child_identity = _submodule_admin_identity(
                    child_fd, child_path, mount_id
                )
                if child_identity[:2] != (child.st_dev, child.st_ino):
                    raise Refusal(
                        f"submodule administration changed during inspection: "
                        f"{child_path}"
                    )
                _snapshot_empty_submodule_admin_tree(
                    child_fd,
                    child_path,
                    (*relative, name),
                    mount_id,
                    observed,
                )
            finally:
                os.close(child_fd)
            current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            if (
                not stat.S_ISDIR(current.st_mode)
                or (current.st_dev, current.st_ino) != child_identity[:2]
            ):
                raise Refusal(
                    f"submodule administration changed during inspection: {child_path}"
                )
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(
            f"submodule administration changed during inspection: {path}: {exc}"
        ) from exc
    if _submodule_admin_names(directory_fd, path) != names:
        raise Refusal(
            f"submodule administration changed during inspection: {path}"
        )


def _empty_submodule_administration(
    vcs: _GitVcs, checkout: Path
) -> _EmptySubmoduleAdministration | None:
    initialized = vcs.initialized_submodules(checkout)
    declared = _declared_initialized_submodules(checkout)
    if initialized or declared:
        first = (
            initialized[0]
            if initialized
            else str(declared[0].relative_to(checkout))
        )
        raise Refusal(
            f"cannot abort checkout with initialized submodule {first!r}; "
            "preserve it for inspection"
        )
    opened = _open_submodule_administration(vcs, checkout)
    if opened is None:
        return None
    (
        git_fd,
        modules_fd,
        modules,
        common,
        git_directory,
        common_identity,
        git_identity,
    ) = opened
    try:
        observed: list[tuple[tuple[str, ...], tuple[int, int, int]]] = []
        _snapshot_empty_submodule_admin_tree(
            modules_fd, modules, (), git_identity[2], observed
        )
        try:
            current = os.stat("modules", dir_fd=git_fd, follow_symlinks=False)
        except OSError as exc:
            raise Refusal(
                f"submodule administration changed during inspection: {modules}: {exc}"
            ) from exc
        if (current.st_dev, current.st_ino) != dict(observed)[()][:2]:
            raise Refusal(
                f"submodule administration changed during inspection: {modules}"
            )
        return _EmptySubmoduleAdministration(
            common_directory=common,
            common_identity=common_identity,
            git_directory=git_directory,
            git_directory_identity=git_identity,
            directories=tuple(observed),
        )
    finally:
        os.close(modules_fd)
        os.close(git_fd)


def _rmdir_verified_empty_admin_directory(
    parent_fd: int,
    directory_fd: int,
    name: str,
    path: Path,
    expected_identity: tuple[int, int, int],
) -> None:
    try:
        if (
            _submodule_admin_identity(
                directory_fd, path, expected_identity[2]
            )
            != expected_identity
            or _submodule_admin_names(directory_fd, path)
        ):
            raise Refusal(
                f"submodule administration changed or is not empty before removal: "
                f"{path}"
            )
        named = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            not stat.S_ISDIR(named.st_mode)
            or (named.st_dev, named.st_ino) != expected_identity[:2]
        ):
            raise Refusal(f"submodule administration changed before removal: {path}")
        os.rmdir(name, dir_fd=parent_fd)
        os.fsync(parent_fd)
        removed = os.fstat(directory_fd)
        if removed.st_nlink != 0:
            raise Refusal(f"submodule administration raced removal: {path}")
        try:
            os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return
        raise Refusal(f"submodule administration reappeared during removal: {path}")
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(
            f"cannot remove verified-empty submodule administration {path}: {exc}"
        ) from exc


def _prune_empty_submodule_admin_tree(
    directory_fd: int,
    path: Path,
    relative: tuple[str, ...],
    identities: Mapping[tuple[str, ...], tuple[int, int, int]],
) -> None:
    expected = identities.get(relative)
    if expected is None:
        raise Refusal(f"submodule administration acquired an unexpected directory: {path}")
    if _submodule_admin_identity(directory_fd, path, expected[2]) != expected:
        raise Refusal(f"submodule administration changed before removal: {path}")
    children = tuple(
        sorted(
            child[-1]
            for child in identities
            if len(child) == len(relative) + 1 and child[:-1] == relative
        )
    )
    if _submodule_admin_names(directory_fd, path) != children:
        raise Refusal(
            f"submodule administration changed before removal: {path}"
        )
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    try:
        for name in children:
            child_relative = (*relative, name)
            child_path = path / name
            child_expected = identities[child_relative]
            child_fd = os.open(name, flags, dir_fd=directory_fd)
            try:
                _prune_empty_submodule_admin_tree(
                    child_fd, child_path, child_relative, identities
                )
                _rmdir_verified_empty_admin_directory(
                    directory_fd,
                    child_fd,
                    name,
                    child_path,
                    child_expected,
                )
            finally:
                os.close(child_fd)
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(
            f"submodule administration changed before removal: {path}: {exc}"
        ) from exc


def _prune_empty_submodule_administration(
    vcs: _GitVcs,
    checkout: Path,
    expected: _EmptySubmoduleAdministration,
) -> None:
    current = _empty_submodule_administration(vcs, checkout)
    if current != expected:
        raise Refusal(
            "submodule administration changed between abort preflight and removal"
        )
    modules = expected.git_directory / "modules"
    _assert_slot_unused(modules)
    if _empty_submodule_administration(vcs, checkout) != expected:
        raise Refusal(
            "submodule administration changed during its live-use census"
        )
    _assert_slot_unused(modules)
    opened = _open_submodule_administration(vcs, checkout, expected=expected)
    if opened is None:
        raise Refusal(
            "submodule administration disappeared between preflight and removal"
        )
    (
        git_fd,
        modules_fd,
        opened_modules,
        _common,
        _git_directory,
        _common_identity,
        _git_identity,
    ) = opened
    if opened_modules != modules:
        raise Refusal("submodule administration path changed before removal")
    try:
        identities = dict(expected.directories)
        root_identity = identities.get(())
        if root_identity is None or len(identities) != len(expected.directories):
            raise StateError("submodule administration witness is malformed")
        _prune_empty_submodule_admin_tree(modules_fd, modules, (), identities)
        _rmdir_verified_empty_admin_directory(
            git_fd,
            modules_fd,
            "modules",
            modules,
            root_identity,
        )
    finally:
        os.close(modules_fd)
        os.close(git_fd)


def _abort_create(
    config: Config,
    journal_path: Path,
    slot: str,
    slot_type: str,
    plan: Sequence[PlannedCheckout],
    recorded_created: Sequence[Checkout],
) -> None:
    slot_path = _slot_directory(config, slot, slot_type)
    vcs = _GitVcs()
    recorded_by_name = {checkout.name: checkout for checkout in recorded_created}
    if config.layout == "nested" and slot_path.exists():
        if not slot_path.is_dir() or slot_path.is_symlink():
            raise Refusal(f"cannot abort unsafe slot path: {slot_path}")
        expected_entries = {
            item.name
            for item in plan
            if _stored_path(config, item.destination, "checkout destination").exists()
        }
        actual_entries = {entry.name for entry in slot_path.iterdir()}
        if actual_entries != expected_entries:
            raise Refusal(
                f"cannot abort slot with unexpected root contents: expected "
                f"{sorted(expected_entries)}, found {sorted(actual_entries)}"
            )
    preflight: list[
        tuple[
            PlannedCheckout,
            Path,
            Path,
            str,
            bool,
            Checkout | None,
            tuple[CacheDirectory, ...],
            _EmptySubmoduleAdministration | None,
        ]
    ] = []
    for item in plan:
        _relative, repository = _stored_repository_path(config, item.repository)
        destination = _stored_path(config, item.destination, "checkout destination")
        recorded = recorded_by_name.get(item.name)
        expected_head = item.start_point if recorded is None else recorded.head
        if destination.exists() or destination.is_symlink():
            if destination.is_symlink() or not destination.is_dir():
                raise Refusal(f"cannot abort unsafe checkout path: {destination}")
            head = vcs.verify_existing_worktree(repository, destination)
            branch = vcs.branch(destination)
            if head != expected_head or branch != item.branch:
                raise Refusal(
                    f"cannot abort changed checkout {item.name}: expected branch "
                    f"{item.branch} at {expected_head}, found {branch} at {head}"
                )
            operation_paths = vcs.operation_paths(destination)
            if operation_paths:
                raise Refusal(
                    f"cannot abort checkout {item.name} with an unfinished Git operation: "
                    f"{operation_paths[0]}"
                )
            vcs.assert_ordinary_history(destination)
            vcs.assert_ordinary_index(destination)
            checkout = recorded or Checkout(
                name=item.name,
                path=item.destination,
                repository=item.repository,
                branch=item.branch,
                start_point=item.start_point,
                remote=item.remote,
                remote_url_sha256=item.remote_url_sha256,
                landed_ref=item.landed_ref,
                head=expected_head,
            )
            _assert_cache_policy_untracked(config, checkout, vcs)
            status = vcs.status(
                destination, _cache_globs_for(config, checkout.name)
            )
            if status:
                first = status.splitlines()[0]
                raise Refusal(
                    f"cannot abort changed checkout {item.name}: source state is dirty "
                    f"({first}); preserve it for inspection"
                )
            present = True
            caches = _cache_directories_for_checkout(config, checkout)
            submodule_administration = _empty_submodule_administration(
                vcs, destination
            )
        elif destination.absolute() in vcs.listed_worktrees(repository):
            raise Refusal(
                f"cannot abort missing checkout still registered by Git: {destination}"
            )
        else:
            present = False
            checkout = None
            caches = ()
            submodule_administration = None
        if vcs.branch_exists(repository, item.branch):
            branch_head = vcs.verify_ref(
                repository, f"refs/heads/{item.branch}", "created branch"
            )
            if branch_head != expected_head:
                raise Refusal(
                    f"created branch {item.branch} moved from {expected_head} to "
                    f"{branch_head}; preserve it instead of aborting provisioning"
                )
        preflight.append(
            (
                item,
                repository,
                destination,
                expected_head,
                present,
                checkout,
                caches,
                submodule_administration,
            )
        )
    if slot_path.exists():
        _assert_slot_unused(slot_path)
    for (
        item,
        repository,
        destination,
        expected_head,
        present,
        checkout,
        caches,
        submodule_administration,
    ) in preflight:
        if present:
            assert checkout is not None
            head = vcs.verify_existing_worktree(repository, destination)
            branch = vcs.branch(destination)
            if head != expected_head or branch != item.branch:
                raise Refusal(
                    f"cannot abort changed checkout {item.name}: expected branch "
                    f"{item.branch} at {expected_head}, found {branch} at {head}"
                )
            operation_paths = vcs.operation_paths(destination)
            if operation_paths:
                raise Refusal(
                    f"cannot abort checkout {item.name} with an unfinished Git operation: "
                    f"{operation_paths[0]}"
                )
            vcs.assert_ordinary_history(destination)
            vcs.assert_ordinary_index(destination)
            _assert_cache_policy_untracked(config, checkout, vcs)
            status = vcs.status(
                destination, _cache_globs_for(config, checkout.name)
            )
            if status:
                first = status.splitlines()[0]
                raise Refusal(
                    f"cannot abort changed checkout {item.name}: source state is dirty "
                    f"({first}); preserve it for inspection"
                )
            current_submodule_administration = _empty_submodule_administration(
                vcs, destination
            )
            if current_submodule_administration != submodule_administration:
                raise Refusal(
                    "submodule administration changed between abort preflight and "
                    "removal"
                )
            for cache in caches:
                _remove_cache_directory(config, cache)
            if current_submodule_administration is not None:
                _prune_empty_submodule_administration(
                    vcs, destination, current_submodule_administration
                )
            vcs.remove_worktree(repository, destination)
            _fsync_directory(slot_path.parent)
    for (
        item,
        repository,
        _destination,
        expected_head,
        _present,
        _checkout,
        _caches,
        _submodule_administration,
    ) in preflight:
        vcs.delete_branch_at(repository, item.branch, expected_head)
    if slot_path.exists():
        try:
            _remove_slot_directory(config, slot_path)
        except OSError as exc:
            raise Refusal(f"cannot remove aborted slot directory {slot_path}: {exc}") from exc
        _fsync_directory(slot_path.parent)
    _clear_journal(
        config,
        _as_mapping(_read_json(journal_path, "create journal"), "create journal"),
        journal_path=journal_path,
    )
    print(f"aborted incomplete create slot={slot}; removed provisional worktrees and branches")


def _recover_create(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    state: ActiveState,
    recovery_actor: ProcessIdentity,
    *,
    retry_running_hook: bool,
    abort_create: bool,
) -> None:
    _exact_keys(
        raw, _CREATE_JOURNAL_REQUIRED, _CREATE_JOURNAL_OPTIONAL, "create journal"
    )
    machine = _as_str(raw["machine"], "create journal.machine")
    if machine != config.machine or path not in {
        _journal_path(config, machine),
        _create_journal_path(
            config, _as_str(raw["slot"], "create journal.slot"), machine
        ),
    }:
        raise StateError(
            f"create journal filename does not match machine {config.machine}"
        )
    slot = _as_str(raw["slot"], "create journal.slot")
    agent = _as_str(raw["agent"], "create journal.agent")
    _validate_name(slot, "slot")
    _validate_name(agent, "agent")
    slot_type = _as_str(raw.get("slot_type", "agent"), "create journal.slot_type")
    if slot_type not in SLOT_TYPES:
        raise StateError(
            f"create journal.slot_type must be one of {', '.join(SLOT_TYPES)}"
        )
    plan = tuple(
        _planned_from_obj(item, f"create journal.planned[{index}]")
        for index, item in enumerate(
            _as_list(raw["planned"], "create journal.planned")
        )
    )
    recorded_created = tuple(
        _checkout_from_obj(item, f"create journal.created[{index}]")
        for index, item in enumerate(
            _as_list(raw["created"], "create journal.created")
        )
    )
    journal_hooks = (
        ()
        if "post_provision_hooks" not in raw
        else _string_tuple(
            raw["post_provision_hooks"],
            "create journal.post_provision_hooks",
            _validate_hook,
            unique=False,
        )
    )
    if journal_hooks != config.post_provision_hooks:
        raise StateError("create journal post-provision hooks differ from configuration")
    hook_progress = _as_int(raw.get("hook_progress", 0), "create journal.hook_progress")
    total_hook_steps = len(plan) * len(journal_hooks)
    if hook_progress > total_hook_steps:
        raise StateError("create journal hook progress exceeds its hook plan")
    if "failure_policy" in raw and _as_str(
        raw["failure_policy"], "create journal.failure_policy"
    ) != "leave-for-inspection":
        raise StateError("create journal has an unsupported hook failure policy")
    hook_failure = raw.get("hook_failure")
    failure: Mapping[str, object] | None = None
    hook_failure_status: str | None = None
    if hook_failure is not None:
        failure = _as_mapping(hook_failure, "create journal.hook_failure")
        _exact_keys(
            failure,
            {"checkout", "hook_index", "command", "status"},
            {"returncode", "detail"},
            "create journal.hook_failure",
        )
        hook_failure_status = _as_str(
            failure["status"], "create journal.hook_failure.status"
        )
        if hook_failure_status not in {"running", "failed", "failed-to-start"}:
            raise StateError("create journal has an unknown hook failure status")
    if not plan:
        raise StateError("create journal contains no planned checkouts")
    if len({item.name for item in plan}) != len(plan):
        raise StateError("create journal has duplicate planned checkout names")
    if len({item.name for item in recorded_created}) != len(recorded_created):
        raise StateError("create journal has duplicate created checkout names")
    if [item.name for item in recorded_created] != [
        item.name for item in plan[: len(recorded_created)]
    ]:
        raise StateError("create journal's completed checkouts are not a planned prefix")
    if hook_progress > len(recorded_created) * len(journal_hooks):
        raise StateError("create journal ran hooks for a checkout not durably recorded")
    if failure is not None:
        if not journal_hooks or hook_progress >= total_hook_steps:
            raise StateError("create journal records a failed hook after hook completion")
        if len(recorded_created) != len(plan):
            raise StateError("create journal records a hook before every checkout was created")
        expected_checkout = plan[hook_progress // len(journal_hooks)].name
        expected_hook_index = hook_progress % len(journal_hooks)
        failure_checkout = _as_str(
            failure["checkout"], "create journal.hook_failure.checkout"
        )
        failure_hook_index = _as_int(
            failure["hook_index"], "create journal.hook_failure.hook_index"
        )
        failure_command = _as_str(
            failure["command"], "create journal.hook_failure.command"
        )
        if (
            failure_checkout != expected_checkout
            or failure_hook_index != expected_hook_index
            or failure_command != journal_hooks[expected_hook_index]
        ):
            raise StateError("create journal hook failure does not match its progress")
        if hook_failure_status == "running":
            if "returncode" in failure or "detail" in failure:
                raise StateError("running create hook records impossible completion details")
            if not retry_running_hook and not abort_create:
                raise Refusal(
                    "the create journal records a hook that was running when provisioning "
                    "stopped; it may already have completed. Inspect its effects, then rerun "
                    "recover with --retry-running-hook to authorize another execution"
                )
        elif hook_failure_status == "failed":
            returncode = failure.get("returncode")
            if (
                not isinstance(returncode, int)
                or isinstance(returncode, bool)
                or returncode == 0
                or "detail" in failure
            ):
                raise StateError("failed create hook has invalid completion details")
        elif (
            "returncode" in failure
            or not _as_str(
                failure.get("detail"), "create journal.hook_failure.detail"
            ).strip()
        ):
            raise StateError("failed-to-start create hook has invalid completion details")
    planned_by_name = {item.name: item for item in plan}
    for item in plan:
        expected_destination, _destination = _checkout_path(
            config, slot, item.name, slot_type
        )
        if item.destination != expected_destination:
            raise StateError(
                f"create journal destination for {item.name} does not match slot {slot}"
            )
        normalized_repository, _repository = _stored_repository_path(
            config, item.repository
        )
        if (
            not Path(item.repository).is_absolute()
            and item.repository != normalized_repository
        ):
            raise StateError(
                f"create journal repository for {item.name} is not canonical"
            )
        if item.landed_ref != _landed_ref_for_remote(config, item.remote):
            raise StateError(
                f"create journal target for {item.name} differs from configured authority"
            )
        if _GitVcs().remote_url_sha256(_repository, item.remote) != item.remote_url_sha256:
            raise Refusal(
                f"create journal remote {item.remote!r} URL changed for {item.name}"
            )
        if not SHA_RE.fullmatch(item.start_point):
            raise StateError(
                f"create journal start point for {item.name} is not an exact commit"
            )
    for checkout in recorded_created:
        planned = planned_by_name.get(checkout.name)
        if planned is None:
            raise StateError("create journal records an unplanned checkout")
        expected_fields = (
            planned.destination,
            planned.repository,
            planned.branch,
            planned.start_point,
            planned.remote,
            planned.remote_url_sha256,
            planned.landed_ref,
        )
        actual_fields = (
            checkout.path,
            checkout.repository,
            checkout.branch,
            checkout.start_point,
            checkout.remote,
            checkout.remote_url_sha256,
            checkout.landed_ref,
        )
        if actual_fields != expected_fields or checkout.head != planned.start_point:
            raise StateError(
                f"create journal's completed checkout {checkout.name} differs from its plan"
            )
    task = _as_str(raw["task"], "create journal.task")
    purpose = _as_str(raw["purpose"], "create journal.purpose")
    if not task or not purpose:
        raise StateError("create journal has an empty task or purpose")
    created_at = _as_str(raw["created_at"], "create journal.created_at")
    _parse_timestamp(created_at, "create journal.created_at")
    heartbeat_at = _as_str(raw["heartbeat_at"], "create journal.heartbeat_at")
    _parse_timestamp(heartbeat_at, "create journal.heartbeat_at")
    heartbeat_ttl_seconds = _as_int(
        raw["heartbeat_ttl_seconds"],
        "create journal.heartbeat_ttl_seconds",
        minimum=1,
    )
    if heartbeat_ttl_seconds != config.heartbeat_ttl_seconds:
        raise StateError("create journal heartbeat TTL differs from configuration")
    owner = _identity_from_obj(raw["owner"], "create journal.owner")
    task_scope = (
        None
        if "task_scope" not in raw
        else _task_scope_from_obj(raw["task_scope"], "create journal.task_scope")
    )
    _assert_task_scope_matches_owner(task_scope, owner, "create journal.task_scope")
    coordinator_lease = _identity_from_obj(
        raw["coordinator_lease"], "create journal.coordinator_lease"
    )
    if coordinator_lease is None:
        raise StateError("create journal has no coordinator lease")
    existing_record = next((item for item in state.slots if item.slot == slot), None)
    if existing_record is not None:
        if abort_create:
            raise Refusal(
                f"cannot abort create for slot {slot}: its ACTIVE row is already durable"
            )
        if hook_progress != total_hook_steps:
            raise StateError(
                "create journal reached ACTIVE publication before post-provision hooks completed"
            )
        expected_record = ActiveRecord(
            slot=slot,
            agent=agent,
            task=task,
            purpose=purpose,
            slot_type=slot_type,
            machine=config.machine,
            generation=1,
            created_at=created_at,
            heartbeat_at=heartbeat_at,
            heartbeat_ttl_seconds=heartbeat_ttl_seconds,
            owner=owner,
            coordinator_lease=coordinator_lease,
            coordinator_recovery_note=None,
            handoff=None,
            checkouts=recorded_created,
            task_scope=task_scope,
        )
        if len(recorded_created) != len(plan) or _record_to_obj(
            existing_record
        ) != _record_to_obj(expected_record):
            raise StateError("create journal does not exactly match its durable ACTIVE record")
        _assert_record_paths(config, existing_record)
        for checkout in existing_record.checkouts:
            _relative, repository = _stored_repository_path(config, checkout.repository)
            destination = _stored_path(config, checkout.path, "checkout path")
            head = _GitVcs().verify_existing_worktree(repository, destination)
            if head != checkout.head:
                raise Refusal(
                    f"create recovery found changed HEAD for {checkout.name}; preserve it for inspection"
                )
        _clear_journal(config, raw, journal_path=path)
        print(f"recovered create: active state was durable; cleared journal for {slot}")
        return
    if abort_create:
        _abort_create(config, path, slot, slot_type, plan, recorded_created)
        return
    if task_scope is not None:
        # Refuse before provisioning or hooks run for an owner whose scope has
        # ended: hooks that dirty a tree would also make --abort-create refuse.
        _verify_task_scope_before_publication(task_scope, _CREATE_SCOPE_REMEDY)
    _assert_agent_and_slot_free(config, slot, agent, slot_type)
    slot_path = _slot_directory(config, slot, slot_type)
    if slot_path.exists() and (not slot_path.is_dir() or slot_path.is_symlink()):
        raise Refusal(f"create recovery found an unsafe slot path: {slot_path}")
    if (
        not slot_path.exists()
        and config.layout == "nested"
        and _slot_representation_of(config, slot, slot_type) == "worktree"
    ):
        slot_path.mkdir(mode=0o755)
        _fsync_directory(slot_path.parent)
    vcs = _GitVcs()
    created: list[Checkout] = []
    for item in plan:
        destination = _stored_path(config, item.destination, "checkout destination")
        _relative, repository = _stored_repository_path(config, item.repository)
        if destination.exists() or destination.is_symlink():
            if destination.is_symlink() or not destination.is_dir():
                raise Refusal(f"create recovery found an unsafe destination: {destination}")
            head = vcs.verify_existing_worktree(repository, destination)
            branch = vcs.branch(destination)
            if branch != item.branch:
                raise Refusal(
                    f"create recovery branch mismatch for {item.name}: "
                    f"expected {item.branch}, found {branch}"
                )
            recorded = next(
                (value for value in recorded_created if value.name == item.name), None
            )
            expected_head = recorded.head if recorded is not None else item.start_point
            if head != expected_head:
                raise Refusal(
                    f"create recovery found changed HEAD for {item.name}; preserve it for inspection"
                )
        else:
            if vcs.branch_exists(repository, item.branch):
                raise Refusal(
                    f"create recovery found branch {item.branch} without its registered path; "
                    "preserve it for inspection"
                )
            head = vcs.add_worktree(repository, destination, item.branch, item.start_point)
        checkout = Checkout(
            name=item.name,
            path=item.destination,
            repository=item.repository,
            branch=item.branch,
            start_point=item.start_point,
            remote=item.remote,
            remote_url_sha256=item.remote_url_sha256,
            landed_ref=item.landed_ref,
            head=head,
        )
        created.append(checkout)
        updated_journal = dict(raw)
        updated_journal["created"] = [_checkout_to_obj(value) for value in created]
        _write_journal(config, updated_journal, journal_path=path)
    if config.layout == "nested":
        actual = {entry.name for entry in slot_path.iterdir()}
        expected = {item.name for item in plan}
        if actual != expected:
            raise Refusal(
                f"create recovery found unexpected slot contents: expected {sorted(expected)}, "
                f"found {sorted(actual)}"
            )
    updated_journal = dict(raw)
    updated_journal["created"] = [_checkout_to_obj(value) for value in created]
    updated_journal["post_provision_hooks"] = list(journal_hooks)
    updated_journal["hook_progress"] = hook_progress
    updated_journal["hook_failure"] = None
    updated_journal["failure_policy"] = "leave-for-inspection"
    _write_journal(config, updated_journal, journal_path=path)
    hook_progress = _run_post_provision_hooks(
        config,
        created,
        path,
        updated_journal,
        start=hook_progress,
    )
    if hook_progress != total_hook_steps:
        raise StateError("create recovery did not complete its post-provision hooks")
    for checkout in created:
        _assert_checkout_identity_unchanged(config, checkout, vcs)
    record = ActiveRecord(
        slot=slot,
        agent=agent,
        task=task,
        purpose=purpose,
        slot_type=slot_type,
        machine=config.machine,
        generation=1,
        created_at=created_at,
        heartbeat_at=heartbeat_at,
        heartbeat_ttl_seconds=heartbeat_ttl_seconds,
        owner=owner,
        coordinator_lease=coordinator_lease,
        coordinator_recovery_note=None,
        handoff=None,
        checkouts=tuple(created),
        task_scope=task_scope,
    )
    if record.task_scope is not None:
        _verify_task_scope_before_publication(record.task_scope, _CREATE_SCOPE_REMEDY)
    _write_active_state(
        config,
        _append_record(state, record),
        action="slot-created-by-recovery",
        slot=record.slot,
        evidence={
            "slot_type": record.slot_type,
            "original_coordinator": _identity_to_obj(coordinator_lease),
            "recovery_actor": _identity_to_obj(recovery_actor),
        },
    )
    _clear_journal(config, updated_journal, journal_path=path)
    print(f"recovered create: registered slot={slot} checkouts={len(created)}")


def _recover_import_existing(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    state: ActiveState,
    recovery_actor: ProcessIdentity,
    *,
    abort_import: bool = False,
) -> None:
    _exact_keys(
        raw,
        _IMPORT_JOURNAL_REQUIRED,
        set(),
        "import journal",
    )
    machine = _as_str(raw["machine"], "import journal.machine")
    if machine != config.machine or path != _journal_path(config, machine):
        raise StateError(
            f"import journal filename does not match machine {config.machine}"
        )
    slot = _validate_name(_as_str(raw["slot"], "import journal.slot"), "slot")
    record = _record_from_obj(raw["record"], "import journal.record")
    if record.slot != slot or record.machine != machine:
        raise StateError("import journal record does not match its shard or slot")
    existing = next((item for item in state.slots if item.slot == slot), None)
    if existing is not None:
        if _record_to_obj(existing) != _record_to_obj(record):
            raise StateError(
                f"import journal for slot {slot} does not match its durable ACTIVE row"
            )
        if abort_import:
            raise Refusal(
                f"cannot abort import for slot {slot}: its ACTIVE row is already durable"
            )
        _verify_import_record(config, existing, _GitVcs())
        _clear_journal(config, raw)
        print(f"recovered import: active state was durable; cleared journal for {slot}")
        return
    if abort_import:
        # An import only publishes a row for checkouts that already exist, so
        # discarding the unpublished journal leaves every file untouched.
        _clear_journal(config, raw)
        print(
            f"aborted interrupted import slot={slot}; no ACTIVE row was published "
            "and no files were changed"
        )
        return
    _assert_agent_and_slot_free(
        config, slot, record.agent, record.slot_type, enforce_cap=False
    )
    _verify_import_record(config, record, _GitVcs())
    if record.task_scope is not None:
        _verify_task_scope_before_publication(record.task_scope, _IMPORT_SCOPE_REMEDY)
    _write_active_state(
        config,
        _append_record(state, record),
        action="slot-imported-by-recovery",
        slot=slot,
        evidence={
            "slot_type": record.slot_type,
            "original_coordinator": _identity_to_obj(record.coordinator_lease),
            "recovery_actor": _identity_to_obj(recovery_actor),
            "import_source": _import_source_to_obj(record.import_source),
        },
    )
    _clear_journal(config, raw)
    print(f"recovered import: registered slot={slot} checkouts={len(record.checkouts)}")


def _recover_finish(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    state: ActiveState,
    coordinator: ProcessIdentity,
    *,
    processes: _RecoveryProcesses | None = None,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> None:
    _exact_keys(
        raw, _FINISH_JOURNAL_REQUIRED, _FINISH_JOURNAL_OPTIONAL, "finish journal"
    )
    record = _record_from_obj(raw["record"], "finish journal.record")
    if record.machine != config.machine:
        raise StateError("finish journal record belongs to a different machine")
    if path not in {
        _journal_path(config),
        _finish_journal_path(config, record.slot),
    }:
        raise StateError(f"finish journal filename does not match machine {config.machine}")
    journal_slot = _as_str(raw["slot"], "finish journal.slot")
    if journal_slot != record.slot:
        raise StateError("finish journal slot does not match its recorded active state")
    finished_at = _as_str(raw["finished_at"], "finish journal.finished_at")
    _parse_timestamp(finished_at, "finish journal.finished_at")
    expected_archive_id = (
        f"{config.machine}:{record.slot}:{record.generation}:{finished_at}"
    )
    if _as_str(raw["archive_id"], "finish journal.archive_id") != expected_archive_id:
        raise StateError("finish journal archive_id does not match its record")
    mode = _as_str(raw["mode"], "finish journal.mode")
    actor = _as_str(raw["actor"], "finish journal.actor")
    if mode != "remove" or actor != "coordinator":
        raise StateError("finish journal actor does not match its operation")
    removed_values = _as_list(raw["removed"], "finish journal.removed")
    removed_names = [
        _as_str(value, f"finish journal.removed[{index}]")
        for index, value in enumerate(removed_values)
    ]
    if len(removed_names) != len(set(removed_names)):
        raise StateError("finish journal contains duplicate removed checkout names")
    if not set(removed_names) <= {checkout.name for checkout in record.checkouts}:
        raise StateError("finish journal names an unknown removed checkout")
    salvage = tuple(
        _as_mapping(item, f"finish journal.salvage[{index}]")
        for index, item in enumerate(
            _as_list(raw.get("salvage", []), "finish journal.salvage")
        )
    )
    if record.slot_type == "validate" and salvage:
        raise StateError("validate finish journal must not contain salvage evidence")
    validate_complete = raw.get("validate_complete", False)
    if not isinstance(validate_complete, bool):
        raise StateError("finish journal.validate_complete must be boolean")
    original_mode: int | None = None
    if "original_mode" in raw:
        original_mode = _as_int(raw["original_mode"], "finish journal.original_mode")
        if original_mode > 0o7777:
            raise StateError("finish journal.original_mode exceeds permission bits")
    private_identity = _finish_private_census_identity(raw)
    if private_identity is not None and original_mode is None:
        raise StateError("private finish journal has no original directory mode")
    removal_proof = (
        None
        if raw.get("validation_removal_proof") is None
        else _validation_removal_proof_from_obj(
            raw["validation_removal_proof"],
            "finish journal.validation_removal_proof",
        )
    )
    if removal_proof is not None:
        if private_identity is None:
            raise StateError(
                "validation removal proof has no private cleanup identity"
            )
        canonical_slot = _slot_directory(config, record.slot, record.slot_type)
        canonical_checkout, _active_checkout = _single_validation_checkout(
            config, record, canonical_slot
        )
        if (
            removal_proof.slot != record.slot
            or removal_proof.generation != record.generation
            or removal_proof.checkout
            != _managed_file_reference(config, canonical_checkout)
        ):
            raise StateError(
                "finish journal validation removal proof names another slot generation"
            )
        _validation_proof_manifest_path(config, removal_proof.manifest_path)
        _validate_proof_artifact_paths(
            config,
            removal_proof.artifacts,
            canonical_slot=canonical_slot,
            canonical_checkout=canonical_checkout,
        )
    if validate_complete and record.slot_type != "validate":
        raise StateError("agent finish journal cannot claim validate completion")
    if record.slot_type == "agent" and salvage:
        names = {
            _as_str(item.get("checkout"), "finish journal.salvage checkout")
            for item in salvage
        }
        top_level = {checkout.name for checkout in record.checkouts}
        if not top_level <= names or any(
            not any(name == top or name.startswith(f"{top}/") for top in top_level)
            for name in names
        ):
            raise StateError(
                "finish journal salvage does not cover every checkout or names an "
                "unrelated nested repository"
            )
    archive = _load_archive(config, require_repository=False)
    already_archived = _finish_journal_record_is_archived(
        config, raw, record, (state,), (archive,)
    )
    if already_archived:
        _assert_physical_slot_removed(config, record, _GitVcs(), raw)
        _atomic_write_json(_archive_path(config), _archive_to_obj(archive))
        _remove_handoff_sidecar_after_archive(config, record)
        _clear_journal(config, raw, journal_path=path)
        print(f"recovered finish: cleared completed journal for {record.slot}")
        return
    current = next(item for item in state.slots if item.slot == record.slot)
    _assert_recovery_processes(coordinator, processes)
    _assert_not_held(config, current)
    age, expired = _heartbeat_diagnosis(current)
    owner_state, detail = _process_state(current.owner)
    live_validate_owner = bool(
        validate_complete
        and owner_state == "live"
        and current.owner == coordinator
    )
    owner_consent: _OwnerConsent | None = None
    owner_release: _OwnerRelease | None = None
    if (
        current.slot_type == "agent"
        and owner_state in ("live", "dead")
        and not validate_complete
        and not _owner_record_is_absent(current)
    ):
        # Resume a removal that began on an explicit owner release only if
        # remove durably recorded that exact release before it started, and
        # only while the release still matches current state.
        release_events = _load_events(config, current.machine)
        release_candidate = _owner_release_in_effect(config, current, release_events)
        if release_candidate is not None and _owner_release_was_recorded(
            current, release_candidate, release_events
        ):
            owner_release = release_candidate
    if (
        owner_release is None
        and current.slot_type == "agent"
        and owner_state == "live"
        and not validate_complete
        and not _owner_record_is_absent(current)
    ):
        # An interrupted owner-consented removal must be resumable while the
        # consenting owner is still running; otherwise its global journal
        # would block every mutation until that unrelated process exits.
        # Resume only the exact consent that remove durably recorded before
        # it began, and re-establish every condition from current state.
        recovery_events = _load_events(config, current.machine)
        candidate = _owner_consented_release(
            config,
            current,
            detail,
            events=recovery_events,
            coordinator_authorized=True,
            expired=expired,
            age=age,
        )
        if candidate is not None and _owner_consent_was_recorded(
            current, candidate, recovery_events
        ):
            owner_consent = candidate
    if live_validate_owner:
        _assert_recovery_processes(coordinator, processes, "validate owner")
    elif owner_consent is None and owner_release is None:
        _assert_owner_liveness(
            config,
            current,
            fenced_slot=(
                _finish_fenced_slot(config, record, raw)
                if current.slot_type == "validate"
                else None
            ),
        )
    if not expired and not validate_complete and owner_release is None:
        raise Refusal(
            f"slot {current.slot} time-to-live is no longer expired after renewal; "
            "preserve it and do not resume deletion"
        )
    owner_unrecorded = _owner_record_is_absent(current)
    if (
        owner_state != "dead"
        and not live_validate_owner
        and not owner_unrecorded
        and owner_consent is None
        and owner_release is None
    ):
        raise Refusal(f"recorded owner is {owner_state}: {detail}")
    owner_waived = owner_consent is not None or owner_release is not None
    journal = dict(raw)
    phase = _as_str(journal["phase"], "finish journal.phase")
    selected_live_use_recheck = live_use_recheck or _LiveUseRecheckBudget()
    if phase not in ("prepared", "fenced", "removed"):
        raise StateError(f"unknown finish journal phase {phase!r}")
    if phase in ("prepared", "fenced"):
        private_cleanup: _PrivateCleanupContext | None = None
        if private_identity is not None:
            assert original_mode is not None
            original = _slot_directory(config, record.slot, record.slot_type)
            fenced = _finish_fenced_slot(config, record, journal)
            present = [
                candidate
                for candidate in (original, fenced)
                if candidate.exists() or candidate.is_symlink()
            ]
            if len(present) > 1:
                raise Refusal(
                    f"private finish recovery requires at most one target path for "
                    f"{record.slot}; found {len(present)}"
                )
            if present:
                census_path = present[0]
                identity_verified = False
                recovery_budget = _ReadOnlyCommandBudget.start(
                    timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
                    stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
                    stderr_limit=64 * 1024,
                    input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
                )
                try:
                    _reestablish_private_cleanup_fence(
                        config, census_path, original_mode, private_identity
                    )
                    identity_verified = True
                    recovery_census = _capture_process_path_census(
                        (census_path,), budget=recovery_budget
                    )
                    recovery_census.assert_slot_unused(
                        census_path,
                        _record_for_slot_use_check(
                            record,
                            validate_complete=validate_complete,
                            allow_live_validate_owner=live_validate_owner,
                            owner_consented=owner_waived,
                        ),
                        ignore_invoking_ancestry=(
                            live_validate_owner and record.slot_type == "validate"
                        ),
                    )
                except Refusal as exc:
                    if identity_verified and census_path == fenced and not removed_names:
                        try:
                            _rollback_path_fence(
                                config,
                                record,
                                journal,
                                _GitVcs(),
                                journal_path=path,
                            )
                        except Refusal as rollback:
                            raise Refusal(
                                f"{exc}; path-fence rollback failed: {rollback}"
                            ) from rollback
                    raise
                private_cleanup = _PrivateCleanupContext(
                    _PrivateCleanupTarget(
                        census_path, original_mode, private_identity
                    ),
                    recovery_census,
                    recovery_budget,
                    live_use_recheck=selected_live_use_recheck,
                )
        recovery_finish = _FinishContext(
            mode=mode,
            actor=actor,
            salvage=salvage,
            validate_complete=validate_complete,
            allow_live_validate_owner=live_validate_owner,
            private_cleanup=private_cleanup,
            validation_removal_proof=removal_proof,
            live_use_recheck=selected_live_use_recheck,
            owner_consented=owner_waived,
        )
        journal = _finish_remove_paths(
            config,
            record,
            journal,
            _GitVcs(),
            recovery_finish,
            journal_path=path,
        )
    else:
        if set(removed_names) != {checkout.name for checkout in record.checkouts}:
            raise StateError("removed finish phase does not name every checkout")
        _assert_physical_slot_removed(config, record, _GitVcs(), journal)
    nested_git_evidence = _nested_git_evidence_from_obj(
        journal.get("nested_git_evidence", []), "finish journal.nested_git_evidence"
    )
    _finish_state_update(
        config,
        state,
        record,
        journal,
        journal_path=path,
    )
    print(f"recovered finish: archived and removed slot={record.slot}")
    _print_nested_git_evidence(nested_git_evidence)


def _restore_interrupted_private_finish_after_refusal(
    config: Config,
    raw: Mapping[str, object],
    refusal: Refusal,
) -> None:
    """Restore a still-canonical batch target after recovery safely refuses."""

    identity = _finish_private_census_identity(raw)
    if identity is None:
        return
    removed = _as_list(raw["removed"], "finish journal.removed")
    if removed:
        return
    record = _record_from_obj(raw["record"], "finish journal.record")
    original = _slot_directory(config, record.slot, record.slot_type)
    fenced = _finish_fenced_slot(config, record, raw)
    if not (original.exists() or original.is_symlink()) or (
        fenced.exists() or fenced.is_symlink()
    ):
        return
    original_mode = _as_int(
        raw.get("original_mode"), "finish journal.original_mode"
    )
    try:
        _restore_private_cleanup_path(
            original, original_mode, identity, allow_missing=False
        )
    except (Refusal, StateError) as restore:
        raise Refusal(
            f"{refusal}; cleanup path mode restoration also failed: {restore}"
        ) from restore


def _legacy_validate_recovery_inputs(
    config: Config, raw: Mapping[str, object]
) -> tuple[Path, Path, Path, str]:
    _exact_keys(
        raw,
        _LEGACY_VALIDATE_JOURNAL_REQUIRED,
        set(),
        "legacy validate removal journal",
    )
    if _as_int(raw["schema"], "legacy validate removal journal.schema") != SCHEMA:
        raise StateError("unsupported legacy validate removal journal schema")
    if _as_str(raw["kind"], "legacy validate removal journal.kind") != "legacy-validate-remove":
        raise StateError("legacy validate removal journal has the wrong operation kind")
    if _as_str(raw["machine"], "legacy validate removal journal.machine") != config.machine:
        raise StateError("legacy validate removal journal belongs to a different machine")
    slot = _validate_name(
        _as_str(raw["slot"], "legacy validate removal journal.slot"), "slot"
    )
    checkout_relative, checkout = _relative_inside(
        config.root,
        _as_str(raw["checkout"], "legacy validate removal journal.checkout"),
        "legacy validation checkout",
    )
    if (
        Path(checkout_relative).parent != Path("ignored")
        or checkout.name != slot
        or not slot.startswith("validate-fresh-")
    ):
        raise Refusal(
            "legacy validation cleanup accepts only an exact ignored/validate-fresh-* "
            "checkout. state: REFUSED -- no checkout was removed. remedy: pass the "
            "project-relative checkout recorded by the completed validation handle"
        )
    repository_relative, repository = _stored_repository_path(
        config,
        _as_str(raw["repository"], "legacy validate removal journal.repository"),
    )
    del repository_relative
    record_relative, record_path = _relative_inside(
        config.root,
        _as_str(raw["completed_record"], "legacy validate removal journal.completed_record"),
        "completed validation record",
    )
    if (
        Path(record_relative).parent != Path("ignored/validate/runs")
        or record_path.suffix != ".json"
    ):
        raise Refusal(
            "completed validation evidence must be an exact JSON record under "
            "ignored/validate/runs. state: REFUSED -- no checkout was removed. "
            "remedy: pass the durable run-record path used by validate-run"
        )
    expected_digest = _as_str(
        raw["completed_record_sha256"],
        "legacy validate removal journal.completed_record_sha256",
    )
    if not re.fullmatch(r"[0-9a-f]{64}", expected_digest):
        raise StateError("legacy validate removal journal has an invalid record digest")
    try:
        record_contents = record_path.read_bytes()
    except OSError as exc:
        raise Refusal(
            f"cannot read completed validation record {record_path}: {exc}. state: "
            "REFUSED -- no checkout was removed. remedy: restore the durable record "
            "byte-for-byte and rerun wrkslots recover"
        ) from exc
    observed_digest = hashlib.sha256(record_contents).hexdigest()
    if observed_digest != expected_digest:
        raise Refusal(
            f"completed validation record changed after cleanup was prepared: {record_path}. "
            "state: REFUSED -- no checkout was removed. remedy: preserve the checkout and "
            "inspect the record change before retrying"
        )
    try:
        record_value = json.loads(record_contents)
    except json.JSONDecodeError as exc:
        raise Refusal(f"completed validation record is not valid JSON: {record_path}: {exc}") from exc
    record = _as_mapping(record_value, "completed validation record")
    recorded_checkout = record.get("checkout")
    if not isinstance(recorded_checkout, str) or Path(recorded_checkout).resolve() != checkout:
        raise Refusal(
            "completed validation record does not name this exact checkout. state: "
            "REFUSED -- no checkout was removed. remedy: pass the matching run record "
            "or retain the checkout for inspection"
        )
    if record.get("temporary_checkout") is False:
        raise Refusal(
            "completed validation record says this was not a temporary checkout. state: "
            "REFUSED -- no checkout was removed. remedy: retain it; only validation-created "
            "temporary checkouts use this recovery path"
        )
    expected_exits = {"PASSED": 0, "FAILED": 1, "COULD_NOT_RUN": 75}
    final_status = record.get("final_validate_status")
    if (
        record.get("state") != "completed"
        # Narrows `final_status` for the index below, which reads it out of a decoded record and so
        # sees `object`. Placed before the membership test rather than after it because only the
        # isinstance narrows; the runtime answer is unchanged, since a non-string was never a key.
        or not isinstance(final_status, str)
        or final_status not in expected_exits
        or record.get("exit_code") != expected_exits[final_status]
    ):
        raise Refusal(
            "validation record does not contain an evidenced completed result. state: "
            "REFUSED -- no checkout was removed. remedy: let validate-run finish recording "
            "the result, or retain the checkout while the outcome is unknown"
        )
    head = _as_str(raw["head"], "legacy validate removal journal.head")
    if not SHA_RE.fullmatch(head):
        raise StateError("legacy validate removal journal has an invalid checkout HEAD")
    return checkout, repository, record_path, head


def _validation_handoff_artifact(path: Path) -> Path | None:
    """Return the first top-level handoff-shaped artifact, without following it."""

    try:
        candidates = sorted(
            (entry for entry in path.iterdir() if entry.name.startswith("HANDOFF")),
            key=lambda entry: entry.name,
        )
    except OSError as exc:
        raise Refusal(
            f"cannot inspect validation path for handoff artifacts: {path}: {exc}"
        ) from exc
    return candidates[0] if candidates else None


def _recover_legacy_validate_remove(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
) -> None:
    if path != _journal_path(config):
        raise StateError(
            f"legacy validate removal journal filename does not match machine {config.machine}"
        )
    _assert_caller_process(coordinator, "coordinator")
    checkout, repository, record_path, head = _legacy_validate_recovery_inputs(config, raw)
    phase = _as_str(raw["phase"], "legacy validate removal journal.phase")
    if phase not in ("prepared", "removed"):
        raise StateError(f"unknown legacy validate removal phase {phase!r}")
    vcs = _GitVcs()
    listed = vcs.listed_worktrees(repository)
    if checkout.exists() or checkout.is_symlink():
        if phase == "removed":
            raise Refusal(
                f"legacy validation checkout reappeared after removal was recorded: {checkout}. "
                "state: REFUSED -- no further deletion ran. remedy: preserve it and inspect "
                "the repository registration before retrying"
            )
        if checkout.is_symlink() or not checkout.is_dir():
            raise Refusal(f"legacy validation checkout became unsafe: {checkout}")
        _ensure_no_mount_components(config.root, checkout, "legacy validation checkout")
        _assert_no_mountinfo_crossing(checkout, checkout, "legacy validation checkout")
        handoff = _validation_handoff_artifact(checkout)
        if handoff is not None:
            raise Refusal(
                f"legacy validation checkout gained HANDOFF.md or another HANDOFF* "
                f"artifact: {handoff}; "
                "preserve it and do not resume deletion"
            )
        observed_head = vcs.verify_existing_worktree(repository, checkout)
        if observed_head != head:
            raise Refusal(
                f"legacy validation checkout HEAD changed from {head} to {observed_head}; "
                "preserve it and do not resume deletion"
            )
        _assert_slot_unused(checkout)
        raise Refusal(
            "legacy validation removal journal has no bounded validation removal proof. "
            "state: REFUSED -- the checkout was retained. remedy: preserve this legacy "
            "journal and use a supported ownerless validation recovery only after the "
            "journal conflict is resolved without deleting the checkout"
        )
    if checkout.absolute() in listed:
        raise Refusal(
            f"Git still registers removed legacy validation checkout {checkout}. state: "
            "REFUSED -- cleanup is incomplete. remedy: inspect the registration and rerun "
            "wrkslots recover; do not report the checkout removed"
        )
    if checkout.exists() or checkout.is_symlink():
        raise Refusal(
            f"legacy validation checkout still exists after Git removal: {checkout}. state: "
            "REFUSED -- cleanup is incomplete. remedy: preserve the directory and inspect "
            "why Git left it before rerunning recovery"
        )
    journal = dict(raw)
    if phase != "removed":
        journal["phase"] = "removed"
        _write_journal(config, journal)
    _write_event_file(
        config,
        config.machine,
        "legacy-validate-checkout-removed",
        {
            "slot": raw["slot"],
            "checkout": raw["checkout"],
            "repository": raw["repository"],
            "completed_record": raw["completed_record"],
            "completed_record_sha256": raw["completed_record_sha256"],
            "head": head,
            "recovery_actor": _identity_to_obj(coordinator),
        },
    )
    _clear_journal(config, journal)
    print(
        f"recovered completed legacy validation checkout={checkout} "
        f"record={record_path}"
    )


def _frozen_validation_directory(config: Config) -> Path:
    return config.root.parent / f".{config.root.name}-frozen-validate"


def _validation_recovery_target(
    config: Config, raw: str, target_kind: str
) -> tuple[str, Path, tuple[str, str] | None]:
    if target_kind == "frozen-checkout":
        supplied = Path(raw)
        if not supplied.is_absolute():
            raise Refusal(
                "frozen validation checkout is not an absolute path; pass the exact "
                "absolute checkout path and retry"
            )
        if ".." in supplied.parts:
            raise Refusal(
                "frozen validation checkout path contains '..'; pass its normalized exact "
                "absolute path and retry"
            )
        canonical = os.path.normpath(raw)
        if raw != canonical:
            raise Refusal(
                "frozen validation checkout must use its exact canonical absolute spelling; "
                f"pass {canonical!r} and retry"
            )
        target = Path(canonical)
        frozen_root = _frozen_validation_directory(config)
        allowed = (
            target.parent == frozen_root
            and target.name.startswith("validate-fresh-")
        )
        if not allowed:
            raise Refusal(
                "frozen checkout path is outside the exact sibling validation directory: "
                f"{target}; preserve it or move it under {frozen_root}/validate-fresh-* "
                "before retrying"
            )
        _validate_name(target.name, "validation recovery path name")
        _ensure_no_symlink_components(
            config.root.parent, target, "frozen validation recovery path"
        )
        return str(target), target, None

    relative, target = _relative_inside(config.root, raw, "validation recovery path")
    validate_root = _validate_slots_directory(config)
    if target_kind == "checkout":
        allowed = target.parent == validate_root or (
            target.parent == config.root / "ignored"
            and target.name.startswith("validate-fresh-")
        )
    elif target_kind == "cargo-home":
        allowed = target.name.startswith("validate-cargo-") and target.parent in {
            validate_root,
            config.root / "ignored" / "validate" / "cargo-homes",
        }
    else:
        raise StateError(f"unknown validation recovery target kind {target_kind!r}")
    if not allowed:
        raise Refusal(
            f"{target_kind} path is outside the exact validation directories: {target}"
        )
    _validate_name(target.name, "validation recovery path name")
    slot = ("validate", target.name) if target.parent == validate_root else None
    return relative, target, slot


# The producer parser and every local module it imports: the parser runs from a
# private copy of exactly these files. a consuming project's run_registry.py has imported
# reverie_node since 2026-09-20 (consumer commit 01991d70); without it every frozen
# handle was refused with ModuleNotFoundError, and frozen validation checkouts
# were never removed (94 GB across nine of them on 2026-10-11). Each file is
# copied to its tracked path under the private root: reverie_node.py imports
# bounded_capture from ../lib relative to itself, so a flat copy still failed
# with "No module named 'bounded_capture'" once reverie_node.py was present.
_FROZEN_VALIDATION_PARSER_FILES = (
    "ci-hub/validate/run_registry.py",
    "ci-hub/validate/service_result.py",
    "ci-hub/validate/final_validate_status.py",
    "ci-hub/validate/reverie_node.py",
    "ci-hub/lib/bounded_capture.py",
)
_FROZEN_VALIDATION_PARSER_ENTRY = "ci-hub/validate/run_registry.py"
_FROZEN_VALIDATION_PARSER_BOOTSTRAP = (
    "import runpy,sys\n"
    "script=sys.argv.pop(1)\n"
    "sys.path.insert(0,script.rsplit('/',1)[0])\n"
    "runpy.run_path(script,run_name='__main__')\n"
)
_FROZEN_TOOL_AUTHORITY_MODULE = "ci-hub/validate/immutable_tool_authority.py"
_FROZEN_TOOL_AUTHORITY_BOOTSTRAP = r'''
import dataclasses, fcntl, importlib.util, json, os, re, stat, sys
from pathlib import Path

spec = importlib.util.spec_from_file_location("pinned_tool_authority", sys.argv[1])
module = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = module
spec.loader.exec_module(module)
request = json.loads(sys.stdin.buffer.read(1024 * 1024 + 1))
environment = request["environment"]
expected = request["expected"]

# These bytes only locate a descriptor. The pinned verifier below remains the
# authority and rechecks the entire sealed protocol, content digest and state.
authority_path = Path(environment.get(module.TOOL_AUTHORITY_ENV, ""))
holder, _descriptor = module.proc_fd_identity(authority_path, role="tool authority")
descriptor = os.open(authority_path, os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK)
try:
    metadata = os.fstat(descriptor)
    seals = fcntl.F_SEAL_SEAL | fcntl.F_SEAL_SHRINK | fcntl.F_SEAL_GROW | fcntl.F_SEAL_WRITE
    if (not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 0
            or metadata.st_mode & 0o222 or not 0 < metadata.st_size <= 4096
            or fcntl.fcntl(descriptor, fcntl.F_GET_SEALS) & seals != seals):
        raise ValueError("tool descriptor locator is not bounded, anonymous and sealed")
    locator = json.loads(os.read(descriptor, 4097))
finally:
    os.close(descriptor)
if (not isinstance(locator, dict) or type(locator.get("holder_pid")) is not int
        or locator["holder_pid"] != holder or type(locator.get("root_fd")) is not int
        or locator["root_fd"] < 0):
    raise ValueError("tool descriptor locator has invalid holder or root identity")
tool_root = Path(f"/proc/{holder}/fd/{locator['root_fd']}")
verified = module.read_immutable_tool_authority(
    tool_root, Path(expected["state_root"]), environment
)
values = dataclasses.asdict(verified)
pins = {name: value for name, value in values.items() if name.endswith("_sha")}
product_fields = set(pins) - {"parent_sha", "agent_utils_sha"}
if (len(pins) != 3 or len(product_fields) != 1
        or not {"parent_sha", "agent_utils_sha"}.issubset(pins)
        or any(not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{40}", value) is None
               for value in pins.values())):
    raise ValueError("tool authority does not have exactly three unambiguous repository pins")
product_field = next(iter(product_fields))
if (pins["parent_sha"] != expected["authority_head"]
        or pins[product_field] != expected["consumer_head"]
        or pins["agent_utils_sha"] != expected["agent_head"]):
    raise ValueError("sealed tool pins differ from the loaded enclosing Git chain")
for name in ("root_dev", "root_ino", "state_dev", "state_ino"):
    if type(values.get(name)) is not int or values[name] != expected[name]:
        raise ValueError(f"sealed tool {name} differs from the loaded authority/state root")
if str(values["state_root"]) != expected["state_root"]:
    raise ValueError("sealed tool state root differs from the recovery project root")
print(json.dumps(expected, sort_keys=True, separators=(",", ":")))
'''


def _trusted_git_capture(
    repository: Path,
    arguments: Sequence[str],
    *,
    label: str,
    stdout_limit: int = 1024 * 1024,
) -> bytes:
    """Read one bounded Git fact through the already hardened executable boundary."""

    git = _root_owned_executable(Path("/usr/bin/git"), "Git")
    returncode, stdout, stderr = _run_bounded_read_only_command(
        (
            str(git.path),
            "--no-replace-objects",
            "-c",
            "core.attributesFile=/dev/null",
            "-C",
            str(repository),
            *arguments,
        ),
        timeout_seconds=15,
        stdout_limit=stdout_limit,
        stderr_limit=64 * 1024,
        env_overrides={
            "GIT_CONFIG_GLOBAL": "/dev/null",
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_OPTIONAL_LOCKS": "0",
        },
        trusted_executables=(git,),
    )
    if returncode != 0 or stderr:
        detail = stderr.decode("utf-8", errors="replace").strip()
        rendered = f": {detail}" if detail else ""
        raise Refusal(f"cannot authenticate {label}{rendered}")
    return stdout


def _trusted_git_text(
    repository: Path, arguments: Sequence[str], *, label: str
) -> str:
    raw = _trusted_git_capture(repository, arguments, label=label, stdout_limit=4096)
    try:
        value = raw.decode("ascii").strip()
    except UnicodeDecodeError as exc:
        raise Refusal(f"cannot authenticate {label}: Git returned non-ASCII data") from exc
    if not value or "\n" in value or "\r" in value:
        raise Refusal(f"cannot authenticate {label}: Git returned an invalid value")
    return value


def _trusted_git_directory(
    repository: Path, arguments: Sequence[str], *, label: str
) -> Path:
    """Return one canonical absolute directory reported by trusted Git."""

    raw = _trusted_git_text(repository, arguments, label=label)
    path = Path(raw)
    if not path.is_absolute():
        raise Refusal(f"cannot authenticate {label}: Git returned a relative path")
    try:
        resolved = path.resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"cannot authenticate {label}: {exc}") from exc
    if path != resolved or not path.is_dir():
        raise Refusal(
            f"cannot authenticate {label}: Git returned a non-canonical directory"
        )
    return path


def _trusted_git_toplevel(repository: Path, *, label: str) -> Path:
    return _trusted_git_directory(
        repository,
        ("rev-parse", "--path-format=absolute", "--show-toplevel"),
        label=label,
    )


def _trusted_git_superproject(repository: Path, *, label: str) -> Path:
    superproject = _trusted_git_directory(
        repository,
        (
            "rev-parse",
            "--path-format=absolute",
            "--show-superproject-working-tree",
        ),
        label=f"{label} superproject checkout",
    )
    if _trusted_git_toplevel(superproject, label=label) != superproject:
        raise Refusal(f"{label} superproject is not a Git worktree root")
    return superproject


def _trusted_git_head(repository: Path, label: str) -> str:
    head = _trusted_git_text(
        repository, ("rev-parse", "--verify", "HEAD^{commit}"), label=label
    )
    if re.fullmatch(r"[0-9a-f]{40,64}", head) is None:
        raise Refusal(f"cannot authenticate {label}: HEAD is not a canonical object ID")
    return head


def _trusted_gitlink(
    repository: Path, commit: str, relative: str, *, label: str
) -> str:
    raw = _trusted_git_capture(
        repository,
        ("ls-tree", "-z", commit, "--", relative),
        label=label,
        stdout_limit=4096,
    )
    match = re.fullmatch(
        rb"160000 commit ([0-9a-f]{40,64})\t" + re.escape(os.fsencode(relative)) + rb"\x00",
        raw,
    )
    if match is None:
        raise Refusal(f"cannot authenticate {label}: expected one exact Gitlink")
    return match.group(1).decode("ascii")


def _frozen_validation_authority_chain(config: Config) -> tuple[Path, Path, Path]:
    """Return the authenticated outer, consumer, and agent-utils checkouts."""

    loaded = Path(__file__).resolve(strict=True)
    agent_checkout = _trusted_git_toplevel(
        loaded.parent, label="loaded agent-utils checkout"
    )
    try:
        loaded.relative_to(agent_checkout)
    except ValueError as exc:
        raise Refusal("loaded wrkslots module is outside its authenticated checkout") from exc
    consumer = _trusted_git_superproject(
        agent_checkout, label="agent-utils"
    )
    authority = _trusted_git_superproject(
        consumer, label="consumer"
    )
    config_root = _trusted_git_toplevel(
        config.root,
        label="frozen validation recovery project root",
    )
    if config_root != config.root.resolve():
        raise Refusal("frozen validation recovery project root is not a Git worktree root")
    try:
        agent_relative = agent_checkout.relative_to(consumer).as_posix()
        consumer_relative = consumer.relative_to(authority).as_posix()
    except ValueError as exc:
        raise Refusal("authenticated submodule checkout is outside its superproject") from exc
    if agent_relative in {"", "."} or consumer_relative in {"", "."}:
        raise Refusal("authenticated submodule checkout has an invalid Gitlink path")
    return authority, consumer, agent_checkout


def _frozen_validation_authority_commit(config: Config) -> tuple[Path, str]:
    """Bind parser authority through both enclosing, pinned repository Gitlinks."""

    authority, consumer, agent_checkout = _frozen_validation_authority_chain(config)
    agent_relative = agent_checkout.relative_to(consumer).as_posix()
    consumer_relative = consumer.relative_to(authority).as_posix()

    agent_head = _trusted_git_head(agent_checkout, "agent-utils HEAD")
    consumer_head = _trusted_git_head(consumer, "enclosing consumer HEAD")
    if (
        _trusted_gitlink(
            consumer,
            consumer_head,
            agent_relative,
            label="enclosing consumer agent-utils Gitlink",
        )
        != agent_head
    ):
        raise Refusal(
            "loaded agent-utils HEAD differs from the enclosing checkout's pinned Gitlink"
        )
    authority_head = _trusted_git_head(authority, "outer authority HEAD")
    if (
        _trusted_gitlink(
            authority,
            authority_head,
            consumer_relative,
            label="outer authority consumer Gitlink",
        )
        != consumer_head
    ):
        raise Refusal(
            "enclosing checkout HEAD differs from the outer authority's pinned Gitlink"
        )
    authority_common = _trusted_git_directory(
        authority,
        ("rev-parse", "--path-format=absolute", "--git-common-dir"),
        label="outer authority common Git directory",
    )
    config_common = _trusted_git_directory(
        config.root,
        ("rev-parse", "--path-format=absolute", "--git-common-dir"),
        label="frozen validation recovery common Git directory",
    )
    if config_common != authority_common:
        try:
            _authenticate_frozen_tool_state_root(
                config, authority, consumer, agent_checkout,
                authority_head, consumer_head, agent_head,
            )
        except Refusal as exc:
            raise Refusal(
                "frozen validation recovery project root does not share the authenticated "
                "outer authority Git repository; sealed separate-clone authority refused: "
                f"{exc}"
            ) from exc
    return authority, authority_head


def _authenticate_frozen_tool_state_root(
    config: Config,
    authority: Path,
    consumer: Path,
    agent_checkout: Path,
    authority_head: str,
    consumer_head: str,
    agent_head: str,
) -> None:
    """Bind a separate state clone through the pinned sealed-tool verifier."""

    relative = _FROZEN_TOOL_AUTHORITY_MODULE
    _stored, module_path = _relative_inside(authority, relative, "tool authority module")

    def pinned_bytes() -> bytes:
        working = _read_bounded_regular_file(module_path, "tool authority module", 1024 * 1024)
        pinned = _trusted_git_capture(
            authority, ("cat-file", "blob", f"{authority_head}:{relative}"),
            label="pinned tool authority module",
        )
        if working != pinned:
            raise Refusal("tool authority module differs from authenticated HEAD")
        return pinned

    def directory_identity(path: Path) -> tuple[int, int]:
        metadata = path.lstat()
        if not stat.S_ISDIR(metadata.st_mode) or path.resolve(strict=True) != path:
            raise Refusal("tool authority and state must remain canonical directories")
        return metadata.st_dev, metadata.st_ino

    try:
        root_identity = directory_identity(authority)
        state_identity = directory_identity(config.root)
        payload = pinned_bytes()
        python = _root_owned_executable(Path("/usr/bin/python3").resolve(strict=True), "Python")
    except OSError as exc:
        raise Refusal(f"cannot inspect sealed tool authority: {exc}") from exc
    expected = {
        "authority_head": authority_head, "consumer_head": consumer_head,
        "agent_head": agent_head, "state_root": str(config.root),
        "root_dev": root_identity[0], "root_ino": root_identity[1],
        "state_dev": state_identity[0], "state_ino": state_identity[1],
    }
    # Pass only protocol metadata as data, never ambient interpreter/loader
    # settings. The pinned module selects and verifies its own exact names.
    environment = {
        name: value for name, value in os.environ.items()
        if re.fullmatch(r"[A-Z0-9_]+_TOOL_(AUTHORITY|ROOT|[A-Z0-9_]+_SHA|[A-Z0-9_]+_SHA256)", name)
    }
    request = json.dumps({"environment": environment, "expected": expected}).encode()
    with tempfile.TemporaryDirectory(prefix="wrkslots-tool-authority-") as raw_temp:
        directory = Path(raw_temp)
        directory.chmod(0o700)
        snapshot = directory / "immutable_tool_authority.py"
        descriptor = os.open(snapshot, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC, 0o600)
        try:
            view = memoryview(payload)
            while view:
                written = os.write(descriptor, view)
                view = view[written:]
            os.fchmod(descriptor, 0o400)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        directory.chmod(0o500)
        try:
            returncode, stdout, stderr = _run_bounded_read_only_command(
                (str(python.path), "-I", "-B", "-c", _FROZEN_TOOL_AUTHORITY_BOOTSTRAP, str(snapshot)),
                timeout_seconds=15, stdout_limit=16 * 1024, stderr_limit=16 * 1024,
                input_data=request, trusted_executables=(python,),
            )
        finally:
            directory.chmod(0o700)
    _recheck_trusted_executable(python)
    try:
        if directory_identity(authority) != root_identity or directory_identity(config.root) != state_identity:
            raise Refusal("tool authority or state root changed during inspection")
        if pinned_bytes() != payload:
            raise Refusal("pinned tool authority changed during inspection")
    except OSError as exc:
        raise Refusal(f"sealed tool authority changed during inspection: {exc}") from exc
    for checkout, head in ((authority, authority_head), (consumer, consumer_head), (agent_checkout, agent_head)):
        if _trusted_git_head(checkout, "sealed tool repository recheck") != head:
            raise Refusal("sealed tool repository HEAD changed during inspection")
    if returncode != 0 or stderr:
        detail = stderr.decode("utf-8", errors="replace").strip()
        raise Refusal(f"pinned sealed tool verifier refused the state-root binding: {detail}")
    try:
        result = json.loads(stdout)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise Refusal("pinned sealed tool verifier returned invalid JSON") from exc
    if result != expected:
        raise Refusal("pinned sealed tool verifier did not confirm the exact loaded authority")


def _authenticated_frozen_parser_blobs(
    config: Config,
    *,
    expected_authority: Path | None = None,
    expected_head: str | None = None,
    expected_blobs: Mapping[str, bytes] | None = None,
) -> tuple[Path, str, dict[str, bytes]]:
    authority, head = _frozen_validation_authority_commit(config)
    if expected_authority is not None and authority != expected_authority:
        raise Refusal("frozen validation parser authority changed during inspection")
    if expected_head is not None and head != expected_head:
        raise Refusal("frozen validation parser authority HEAD changed during inspection")
    blobs: dict[str, bytes] = {}
    for relative in _FROZEN_VALIDATION_PARSER_FILES:
        _stored, worktree_path = _relative_inside(
            authority, relative, "frozen validation parser module"
        )
        worktree_bytes = _read_bounded_regular_file(
            worktree_path, "frozen validation parser module", 1024 * 1024
        )
        head_bytes = _trusted_git_capture(
            authority,
            ("cat-file", "blob", f"{head}:{relative}"),
            label=f"frozen validation parser module {relative}",
        )
        if worktree_bytes != head_bytes:
            raise Refusal(
                f"frozen validation parser module differs from authenticated HEAD: {relative}"
            )
        if expected_blobs is not None and expected_blobs.get(relative) != head_bytes:
            raise Refusal(
                f"frozen validation parser module changed during inspection: {relative}"
            )
        blobs[relative] = head_bytes
    if expected_blobs is not None and set(expected_blobs) != set(blobs):
        raise Refusal("frozen validation parser module set changed during inspection")
    return authority, head, blobs


def _canonical_frozen_validation_record(
    config: Config, path: Path, contents: bytes
) -> tuple[Mapping[str, object], Mapping[str, object]]:
    """Ask the pinned producer parser to validate one frozen run handle."""

    authority, head, blobs = _authenticated_frozen_parser_blobs(config)
    try:
        python_path = Path("/usr/bin/python3").resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"Python is unavailable: {exc}") from exc
    python = _root_owned_executable(python_path, "Python")
    command_error: Refusal | None = None
    returncode = -1
    stdout = b""
    stderr = b""
    with tempfile.TemporaryDirectory(prefix="wrkslots-frozen-parser-") as raw_temp:
        parser_root = Path(raw_temp)
        parser_root.chmod(0o700)
        snapshot = parser_root / "record.json"
        parser_inputs = tuple(blobs.items()) + ((snapshot.name, contents),)
        directories = sorted(
            {parent for relative in blobs for parent in Path(relative).parents
             if parent != Path(".")},
            key=lambda directory: len(directory.parts),
        )
        for directory in directories:
            (parser_root / directory).mkdir(mode=0o700)
        for name, payload in parser_inputs:
            destination = parser_root / name
            descriptor = os.open(
                destination,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC,
                0o600,
            )
            try:
                view = memoryview(payload)
                while view:
                    written = os.write(descriptor, view)
                    view = view[written:]
                os.fchmod(descriptor, 0o400)
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
        for directory in (*directories, Path(".")):
            (parser_root / directory).chmod(0o500)
        try:
            returncode, stdout, stderr = _run_bounded_read_only_command(
                (
                    str(python.path),
                    "-I",
                    "-B",
                    "-c",
                    _FROZEN_VALIDATION_PARSER_BOOTSTRAP,
                    str(parser_root / _FROZEN_VALIDATION_PARSER_ENTRY),
                    "inspect",
                    "--path",
                    str(snapshot),
                ),
                timeout_seconds=15,
                stdout_limit=1024 * 1024,
                stderr_limit=64 * 1024,
                trusted_executables=(python,),
            )
        except Refusal as exc:
            command_error = exc
        finally:
            for directory in (Path("."), *directories):
                (parser_root / directory).chmod(0o700)

    _authenticated_frozen_parser_blobs(
        config,
        expected_authority=authority,
        expected_head=head,
        expected_blobs=blobs,
    )
    _recheck_trusted_executable(python)
    after = _read_bounded_regular_file(
        path, "terminal validation record", 16 * 1024 * 1024
    )
    if hashlib.sha256(after).digest() != hashlib.sha256(contents).digest():
        raise Refusal("terminal validation record changed while its producer parsed it")
    if command_error is not None:
        raise command_error
    if returncode != 0 or stderr:
        detail = stderr.decode("utf-8", errors="replace").strip()
        rendered = f": {detail}" if detail else ""
        raise Refusal(f"canonical frozen validation record parser refused the handle{rendered}")
    try:
        projected = json.loads(stdout)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise Refusal("canonical frozen validation record parser returned invalid JSON") from exc
    if not isinstance(projected, dict):
        raise Refusal("canonical frozen validation record parser returned a non-object")
    try:
        rebound = json.loads(after)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise Refusal("terminal validation record became invalid after parsing") from exc
    return projected, _as_mapping(rebound, "terminal validation record after parsing")


def _frozen_validation_record_binding(
    record: Mapping[str, object],
    target: Path,
    repository: Path | None,
    *,
    expected_target: str | None = None,
) -> str:
    """Bind the destructive target to fields retained only in the raw handle."""

    if record.get("checkout") != str(target):
        raise Refusal("terminal validation record does not name this exact checkout")
    if record.get("temporary_checkout") is not True:
        raise Refusal("terminal validation record says the checkout is not temporary")
    if repository is None or record.get("source_checkout") != str(repository):
        raise Refusal(
            "terminal validation record does not name the exact source checkout; "
            "preserve the checkout and pass the recorded source repository"
        )
    record_target = record.get("target")
    if not isinstance(record_target, str) or not SHA_RE.fullmatch(record_target):
        raise Refusal(
            "terminal validation record has no exact target commit; preserve the "
            "checkout and repair or replace the run handle"
        )
    if expected_target is not None and record_target != expected_target:
        raise Refusal(
            "terminal validation record target changed after authorization; preserve "
            "the checkout and restore the authorized record before retrying"
        )
    return record_target


def _terminal_validation_record(
    config: Config,
    raw: str,
    target: Path,
    target_kind: str,
    *,
    expected_digest: str | None = None,
    repository: Path | None = None,
    expected_target: str | None = None,
    allow_historical_service_result: bool = False,
    frozen_removal_proof_supplied: bool | None = None,
    frozen_result: _FrozenResultEvidence | None = None,
) -> tuple[str, str, str | None]:
    if frozen_result is not None and (
        target_kind != "frozen-checkout" or frozen_removal_proof_supplied is not False
    ):
        raise StateError(
            "durable frozen result authority applies only to frozen cleanup without a proof"
        )
    relative, path = _relative_inside(config.root, raw, "terminal validation record")
    if Path(relative).parent != Path("ignored/validate/runs") or path.suffix != ".json":
        raise Refusal("terminal validation record must be an ignored/validate/runs/*.json file")
    try:
        contents = _read_bounded_regular_file(
            path, "terminal validation record", 16 * 1024 * 1024
        )
        value = json.loads(contents)
    except (OSError, json.JSONDecodeError) as exc:
        raise Refusal(f"terminal validation record is unreadable: {path}: {exc}") from exc
    digest = hashlib.sha256(contents).hexdigest()
    if expected_digest is not None and digest != expected_digest:
        raise Refusal("terminal validation record changed after recovery was authorized")
    record = _as_mapping(value, "terminal validation record")
    field = (
        "checkout"
        if target_kind in {"checkout", "frozen-checkout"}
        else "cargo_home"
    )
    if target_kind != "frozen-checkout":
        recorded = record.get(field)
        if not isinstance(recorded, str) or recorded != str(target):
            raise Refusal(f"terminal validation record does not name this exact {field}")
        if target_kind == "checkout" and record.get("temporary_checkout") is False:
            raise Refusal("terminal validation record says the checkout is not temporary")
    record_target: str | None = None
    if target_kind == "frozen-checkout":
        if (
            frozen_removal_proof_supplied is False
            and frozen_result is None
            and not (
                type(record.get("service_result_schema")) is int
                and record.get("service_result_schema") in {1, 2, 3}
                and record.get("result_source") == "validation-service-result"
            )
        ):
            raise Refusal(
                "direct frozen validation recovery requires "
                "--validation-proof-manifest for current or historical-projection "
                "records; use the bounded batch command to classify a pre-proof "
                "historical checkout without removing it"
            )
        record_target = _frozen_validation_record_binding(
            record,
            target,
            repository,
            expected_target=expected_target,
        )
        if (
            record.get("schema_version") != 1
            or record.get("kind") != "frozen-validate"
            or record.get("producer") != "ci-hub/validate/run_registry.py"
            or record.get("admission") != "frozen-validate"
            or record.get("validation_kind") != "frozen-validate"
        ):
            raise Refusal(
                "terminal validation record is not an authoritative frozen-validation "
                "handle; preserve the checkout and pass its current frozen run handle"
            )
        projected, rebound = _canonical_frozen_validation_record(config, path, contents)
        _frozen_validation_record_binding(
            rebound,
            target,
            repository,
            expected_target=record_target,
        )
        if (
            projected.get("schema_version") != record.get("schema_version")
            or projected.get("kind") != "frozen-validate"
            or projected.get("state") != record.get("state")
            or projected.get("target") != record_target
            or projected.get("repo") != record.get("repo")
        ):
            raise Refusal(
                "canonical frozen validation record projection does not bind this handle"
            )
        if (
            frozen_result is not None
            and _durable_frozen_result(config, path, record, record_target)
            != frozen_result
        ):
            raise Refusal(
                "durable frozen validation result changed after removal was authorized"
            )
    if not _validation_record_is_terminal(
        record,
        target_kind=target_kind,
        allow_historical_service_result=allow_historical_service_result,
    ):
        raise Refusal(
            "validation record does not contain an evidenced terminal result; no path was "
            "removed. Let validate-run finish recording the result or preserve the path"
        )
    return relative, digest, record_target


def _validation_record_has_typed_admission(record: Mapping[str, object]) -> bool:
    """Return whether a current validation handle records a complete admission result."""

    kind = record.get("kind")
    frozen = kind == "frozen-validate"
    if (
        type(record.get("schema_version")) is not int
        or record.get("schema_version") != 1
        or not isinstance(kind, str)
        or kind not in {"validate", "reverie-validate", "frozen-validate"}
        or record.get("producer") != "ci-hub/validate/run_registry.py"
        or record.get("admission")
        != ("frozen-validate" if frozen else "ci-hub validate-lock")
        or record.get("temporary_checkout") is not True
        or (
            frozen
            and record.get("validation_kind") != "frozen-validate"
        )
    ):
        return False
    raw = record.get("admission_result")
    if not isinstance(raw, dict):
        return False
    state = raw.get("state")
    if state == "admitted":
        if not {"state", "recorded_at"} <= set(raw) or not set(raw) <= {
            "state",
            "recorded_at",
            "run_number",
        }:
            return False
        run_number = raw.get("run_number")
        if run_number is not None and (
            not isinstance(run_number, int)
            or isinstance(run_number, bool)
            or run_number <= 0
        ):
            return False
    elif state == "refused":
        if set(raw) != {"state", "recorded_at", "reason", "exit_code"}:
            return False
        reason = raw.get("reason")
        if not isinstance(reason, str) or reason not in {
            "stale-base",
            "validation-lock-refusal",
        }:
            return False
        exit_code = raw.get("exit_code")
        if (
            not isinstance(exit_code, int)
            or isinstance(exit_code, bool)
            or exit_code == 0
        ):
            return False
    else:
        return False
    recorded_at = raw.get("recorded_at")
    if not isinstance(recorded_at, str):
        return False
    try:
        _parse_timestamp(recorded_at, "validation admission result")
    except StateError:
        return False
    return True


def _validation_record_process_is_dead(record: Mapping[str, object]) -> bool:
    """Prove that the exact process generation recorded by a validation is gone."""

    raw = record.get("process_identity")
    if not isinstance(raw, dict) or set(raw) != {"pid", "start_ticks", "boot_id"}:
        return False
    pid = raw.get("pid")
    start_ticks = raw.get("start_ticks")
    boot_id = raw.get("boot_id")
    if (
        not isinstance(pid, int)
        or isinstance(pid, bool)
        or pid <= 0
        or not isinstance(start_ticks, int)
        or isinstance(start_ticks, bool)
        or start_ticks <= 0
        or not isinstance(boot_id, str)
        or not boot_id.strip()
    ):
        return False
    try:
        current_boot = _boot_id(Path("/proc"))
        process = _read_process_stat(Path("/proc") / str(pid))
    except Refusal:
        return False
    return current_boot != boot_id or process is None or process.start_ticks != start_ticks


def _current_validation_result_is_terminal(
    record: Mapping[str, object], *, schema: int, status: str
) -> bool:
    """Require every current result field that makes cleanup authoritative."""

    expected_results = {
        "PASSED": "success",
        "FAILED": "failure",
        "COULD_NOT_RUN": "no-result",
    }
    expected_result = expected_results.get(status)
    if expected_result is None or record.get("result") != expected_result:
        return False
    if record.get("result_source") != "validation-service-result":
        return False
    if "selection_mode" not in record:
        return False
    selection_mode = record.get("selection_mode")
    if selection_mode is not None and (
        not isinstance(selection_mode, str) or not selection_mode.strip()
    ):
        return False
    if (
        "executed_nodes" not in record
        or "scorecard_writeback" not in record
        or "executed_tests" not in record
        or "passed_tests" not in record
    ):
        return False
    writeback = record.get("scorecard_writeback")
    if writeback is not None:
        if not isinstance(writeback, dict):
            return False
        if writeback == {"status": "completed"}:
            pass
        elif schema == 6 and writeback == {"status": "delegated"}:
            # Schema 6 (consumer commit 25d2537a, 2026-10-05) names a write-back
            # the launcher owns; it means what null meant before it.
            pass
        elif (
            set(writeback) == {"status", "error"}
            and writeback.get("status") == "failed"
            and isinstance(writeback.get("error"), str)
            and bool(str(writeback["error"]).strip())
        ):
            pass
        else:
            return False
    executed_nodes = record.get("executed_nodes")
    if (
        not isinstance(executed_nodes, int)
        or isinstance(executed_nodes, bool)
        or executed_nodes < 0
    ):
        return False
    executed_tests = record.get("executed_tests")
    passed_tests = record.get("passed_tests")
    if executed_tests is not None and (
        not isinstance(executed_tests, int)
        or isinstance(executed_tests, bool)
        or executed_tests < 0
    ):
        return False
    if passed_tests is not None and (
        not isinstance(passed_tests, int)
        or isinstance(passed_tests, bool)
        or passed_tests < 0
    ):
        return False
    if (executed_tests is None) != (passed_tests is None):
        return False
    if (
        executed_tests is not None
        and passed_tests is not None
        and passed_tests > executed_tests
    ):
        return False
    if status == "PASSED" and (
        passed_tests is None or passed_tests != executed_tests
    ):
        return False
    if schema in {5, 6}:
        if "detail" not in record:
            return False
        detail = record.get("detail")
        if status == "COULD_NOT_RUN":
            if not isinstance(detail, str) or not detail.strip():
                return False
        elif detail is not None:
            return False
    elif "detail" in record:
        return False
    if (
        status == "PASSED"
        and isinstance(writeback, dict)
        and writeback.get("status") == "failed"
    ):
        expected_exit = 75
    else:
        expected_exit = {"PASSED": 0, "FAILED": 1, "COULD_NOT_RUN": 75}[status]
    exit_code = record.get("exit_code")
    return (
        isinstance(exit_code, int)
        and not isinstance(exit_code, bool)
        and exit_code == expected_exit
    )


def _historical_validation_result_is_terminal(
    record: Mapping[str, object], *, schema: int
) -> bool:
    """Recognize the exact non-authoritative projection of a finished sidecar."""

    status = record.get("final_validate_status")
    outcome = (
        _VALIDATION_RESULT_OUTCOMES.get(status)
        if isinstance(status, str)
        else None
    )
    if outcome is None:
        return False
    expected_exit = outcome[1]
    exit_code = record.get("exit_code")
    executed_nodes = record.get("executed_nodes")
    executed_tests = record.get("executed_tests")
    if (
        record.get("state") != "unknown"
        or record.get("result") != "unknown"
        or record.get("result_source") != "historical-validation-service-result"
        or record.get("detail") != _historical_validation_result_detail(schema)
        or record.get("passed_tests") is not None
        or type(exit_code) is not int
        or exit_code != expected_exit
        or type(executed_nodes) is not int
        or executed_nodes < 0
        or (
            executed_tests is not None
            and (type(executed_tests) is not int or executed_tests < 0)
        )
    ):
        return False
    if schema == 1:
        if "scorecard_writeback" in record:
            return False
    elif record.get("scorecard_writeback") != {"status": "completed"}:
        return False
    if schema == 3:
        if "selection_mode" not in record:
            return False
        selection_mode = record.get("selection_mode")
        return selection_mode is None or (
            isinstance(selection_mode, str) and bool(selection_mode.strip())
        )
    return "selection_mode" not in record


def _validation_record_is_terminal(
    record: Mapping[str, object],
    *,
    target_kind: str,
    allow_historical_service_result: bool = False,
) -> bool:
    """Return whether one retained validation handle proves execution has stopped.

    A current handle may retain an unknown validation verdict after its service
    result was lost.  Its exact process generation being gone still proves that
    disposable validation storage is no longer owned by that execution.  This
    cleanup fact does not promote the unknown verdict to passed or failed.
    """

    schema = record.get("service_result_schema")
    if record.get("result_source") == "validation-service-result" and schema is None:
        return False
    if (
        allow_historical_service_result
        and type(schema) is int
        and schema in {1, 2, 3}
    ):
        return _historical_validation_result_is_terminal(record, schema=schema)

    state = record.get("state")
    if not isinstance(state, str):
        return False
    if state in {"killed", "not-run", "refused"}:
        return True
    if state != "completed":
        return bool(
            target_kind in {"cargo-home", "frozen-checkout"}
            and state == "unknown"
            and record.get("result") == "unknown"
            and isinstance(record.get("detail"), str)
            and str(record["detail"]).strip()
            and _validation_record_has_typed_admission(record)
            and _validation_record_process_is_dead(record)
        )
    exits = {"PASSED": 0, "FAILED": 1, "COULD_NOT_RUN": 75}
    status = record.get("final_validate_status")
    expected_exit = exits.get(status) if isinstance(status, str) else None
    if schema is not None and (
        not isinstance(schema, int)
        or isinstance(schema, bool)
        or schema not in {1, 2, 3, 4, 5, 6}
    ):
        return False
    if schema in {1, 2}:
        expected_exit = None
    elif schema in {4, 5, 6} and isinstance(status, str):
        return _current_validation_result_is_terminal(
            record, schema=schema, status=status
        )
    elif schema == 3:
        writeback = record.get("scorecard_writeback")
        failed = bool(
            isinstance(writeback, dict)
            and set(writeback) == {"status", "error"}
            and writeback.get("status") == "failed"
            and isinstance(writeback.get("error"), str)
            and writeback["error"].strip()
        )
        complete = isinstance(writeback, dict) and writeback == {"status": "completed"}
        if writeback is not None and not failed and not complete:
            expected_exit = None
        elif status == "PASSED" and failed:
            expected_exit = 75
    return expected_exit is not None and record.get("exit_code") == expected_exit


class _FrozenNoProofDisposition(enum.Enum):
    BLOCKS_ENTRY = "blocks-entry"
    CURRENT_INCOMPLETE_RETAINED = "current-incomplete-retained"
    CURRENT_TERMINAL_REMOVABLE = "current-terminal-removable"
    HISTORICAL_NONBLOCKING = "historical-nonblocking"
    LEGACY_RECOVERY = "legacy-recovery"


@dataclasses.dataclass(frozen=True)
class _FrozenResultEvidence:
    """One durable frozen-validation result row file bound to its run-record target."""

    path: str
    identity: _RegularFileIdentity
    target: str


@dataclasses.dataclass(frozen=True)
class _FrozenNoProofClassification:
    disposition: _FrozenNoProofDisposition
    historical_schema: int | None = None
    frozen_result: _FrozenResultEvidence | None = None
    detail: str | None = None


def _frozen_result_evidence_to_obj(value: _FrozenResultEvidence) -> dict[str, object]:
    return {
        "path": value.path,
        "device": value.identity.device,
        "inode": value.identity.inode,
        "size": value.identity.size,
        "sha256": value.identity.sha256,
    }


def _frozen_result_evidence_from_obj(
    value: object, *, target: str | None
) -> _FrozenResultEvidence:
    raw = _as_mapping(value, "durable frozen validation result evidence")
    _exact_keys(
        raw,
        {"path", "device", "inode", "size", "sha256"},
        set(),
        "durable frozen validation result evidence",
    )
    sha256 = _as_str(raw["sha256"], "durable frozen validation result sha256")
    if target is None or re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
        raise StateError("durable frozen validation result evidence is incomplete")
    return _FrozenResultEvidence(
        path=_as_str(raw["path"], "durable frozen validation result path"),
        identity=_RegularFileIdentity(
            device=_as_int(raw["device"], "durable frozen validation result device"),
            inode=_as_int(raw["inode"], "durable frozen validation result inode"),
            size=_as_int(raw["size"], "durable frozen validation result size", minimum=1),
            sha256=sha256,
        ),
        target=target,
    )


def _current_frozen_service_result(record: Mapping[str, object]) -> bool:
    """Recognize a current service-result terminal result, not a lost verdict."""

    schema = record.get("service_result_schema")
    return bool(
        type(schema) is int
        and schema in {4, 5, 6}
        and record.get("result_source") == "validation-service-result"
        and record.get("state") == "completed"
        and _validation_record_is_terminal(record, target_kind="frozen-checkout")
    )


def _durable_frozen_result(
    config: Config,
    record_path: Path,
    record: Mapping[str, object],
    target: str,
) -> _FrozenResultEvidence:
    """Prove an inactive current frozen run recorded its result outside the clone.

    The producer writes ``ignored/validate/frozen/<unit>.jsonl`` for the same
    unit whose handle is ``ignored/validate/runs/<unit>.json`` and names it in
    the handle's ``result_record``.  When the run finishes it selects the row
    measured for the target commit in the recorded checkout no earlier than
    the run started, and marks it ``admission=frozen-validate`` and
    ``qualifying_receipt=false``.  The final row must carry exactly those
    facts and a verdict that agrees with the handle.  Together with a dead
    process generation and a current terminal service result, this is the
    removal authority for a frozen checkout whose own teardown did not
    finish; no removal-proof manifest producer exists for frozen runs.

    This proves only that the result is recorded.  It does not copy evidence
    out of the checkout (failed-node artifacts, orphaned receipts, scorecard
    handoffs): the validation cleanup sweep that calls the batch command owns
    those steps and runs them before the call.  A direct batch caller must
    preserve whatever it needs from the checkout first.
    """

    if _current_incomplete_frozen_result(record):
        raise Refusal(
            "current incomplete frozen validation is retained, never removed by its "
            "durable result"
        )
    if not _current_frozen_service_result(record):
        raise Refusal("frozen validation has no current service-result terminal result")
    if not _validation_record_process_is_dead(record):
        raise Refusal("frozen validation process state is live or uncertain")
    label = "durable frozen validation result"
    path = config.root / "ignored" / "validate" / "frozen" / f"{record_path.stem}.jsonl"
    _ensure_no_symlink_components(config.root, path, label)
    try:
        os.lstat(path)
    except FileNotFoundError:
        raise Refusal(f"{label} does not exist: {path}") from None
    except OSError as exc:
        raise Refusal(f"cannot inspect {label} {path}: {exc}") from exc
    if record.get("result_record") != str(path):
        raise Refusal(f"frozen validation run-record does not name this {label}")
    contents, identity = _read_regular_file_identity(
        path, label, _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT
    )
    rows = [line for line in contents.splitlines() if line.strip()]
    if not rows:
        raise Refusal(f"{label} is empty: {path}")
    final = _strict_json_object(rows[-1], f"{label} final row")
    if final.get("commit") != target:
        raise Refusal(f"{label} final row does not name the recorded target commit")
    checkout = record.get("checkout")
    if not isinstance(checkout, str) or final.get("cwd") != checkout:
        raise Refusal(f"{label} final row was not measured in the recorded checkout")
    if final.get("admission") != "frozen-validate":
        raise Refusal(f"{label} final row is not marked as a frozen-validate admission")
    if final.get("qualifying_receipt") is not False:
        raise Refusal(f"{label} final row does not disclaim a qualifying receipt")
    # The producer accepts its repository's full name or its short name.
    repo = record.get("repo")
    if (
        not isinstance(repo, str)
        or not repo.strip()
        or final.get("repo") not in {repo, repo.rsplit("/", 1)[-1]}
    ):
        raise Refusal(f"{label} final row names another repository")
    row_started = final.get("started_at")
    run_started = record.get("started_at")
    try:
        if not isinstance(row_started, str) or not isinstance(run_started, str):
            raise StateError("frozen validation start time is missing")
        predates = _parse_timestamp(
            row_started, f"{label} final row"
        ) < _parse_timestamp(run_started, "frozen validation run-record")
    except StateError as exc:
        raise Refusal(f"{label} final row has no comparable start time: {exc}") from exc
    if predates:
        raise Refusal(f"{label} final row predates the recorded run")
    expected_result = {
        "PASSED": "pass",
        "FAILED": "fail",
        "COULD_NOT_RUN": "no_result",
    }.get(str(record.get("final_validate_status")))
    row_result = final.get("result")
    row_exit = final.get("exit_code")
    measured = record.get("measured_result")
    if (
        expected_result is None
        or row_result != expected_result
        or type(row_exit) is not int
        or (row_result == "pass" and row_exit != 0)
        or (row_result == "fail" and row_exit == 0)
        or (measured is not None and measured != row_result)
    ):
        raise Refusal(f"{label} final row verdict disagrees with the run-record")
    return _FrozenResultEvidence(
        path.relative_to(config.root).as_posix(), identity, target
    )


def _current_incomplete_frozen_result(record: Mapping[str, object]) -> bool:
    """Recognize a narrow retained no-result, without inferring execution phase."""

    expected: dict[str, object] = {
        "service_result_schema": 5,
        "result_source": "validation-service-result",
        "state": "completed",
        "result": "no-result",
        "final_validate_status": "COULD_NOT_RUN",
        "exit_code": 75,
        "temporary_checkout": True,
        "materialized_target": False,
        "qualifying_receipt": False,
        "executed_nodes": 0,
        "executed_tests": None,
        "passed_tests": None,
        "selection_mode": None,
        "scorecard_writeback": None,
    }
    admission = record.get("admission_result")
    return (
        all(key in record and _json_equal(record[key], value) for key, value in expected.items())
        and "scorecard_handoff" not in record
        and "scorecard_writeback_files" not in record
        and _validation_record_has_typed_admission(record)
        and isinstance(admission, dict)
        and admission.get("state") == "admitted"
    )


@dataclasses.dataclass(frozen=True)
class _RetainedValidationGitState:
    head: str
    common: Path
    git_directory: Path
    index: Path
    index_identity: _RegularFileIdentity
    status: str
    directories: tuple[tuple[int, int, int], ...]


def _retained_validation_git_state(
    repository: Path, *, pristine: bool, cache_globs: Sequence[str] = ()
) -> _RetainedValidationGitState:
    """Observe a repository without refreshing its index or changing its files."""

    vcs = _GitVcs()
    if vcs.repository_root(repository) != repository.absolute():
        raise Refusal(f"retained validation repository is not its exact root: {repository}")
    operations = vcs.operation_paths(repository)
    if operations:
        raise Refusal(f"retained validation repository has an unfinished Git operation: {operations[0]}")
    vcs.assert_ordinary_history(repository)
    vcs.assert_ordinary_index(repository)
    head = vcs.head(repository)
    common = vcs.common_directory(repository)
    git_directory = Path(vcs._run(repository, [
        "rev-parse", "--path-format=absolute", "--git-dir",
    ]).stdout.strip())
    index = Path(vcs._run(repository, [
        "rev-parse", "--path-format=absolute", "--git-path", "index",
    ]).stdout.strip())
    _ensure_no_symlink_components(git_directory, index, "retained validation index")
    _contents, index_identity = _read_regular_file_identity(
        index, "retained validation index", _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT
    )
    # Local submodule-ignore and filesystem-monitor settings cannot hide an
    # authored path in the disposable clone. The surviving source may contain
    # work, including a HANDOFF and ignored investigation files; bind its
    # observations instead of imposing deletion-only cleanliness on it.
    pathspecs = ["."]
    for pattern in cache_globs:
        pathspecs.extend((f":(exclude,glob){pattern}", f":(exclude,glob){pattern}/**"))
    status = vcs._run(
        repository,
        ["-c", "core.fsmonitor=false", "-c", "core.untrackedCache=false",
         "status", "--porcelain=v2", "--untracked-files=all",
         "--ignored=matching", "--ignore-submodules=none", "--", *pathspecs],
        env_overrides={"GIT_OPTIONAL_LOCKS": "0"},
    ).stdout
    if pristine and status:
        raise Refusal(f"retained validation checkout is not pristine ({status.splitlines()[0]}); preserve it")
    return _RetainedValidationGitState(
        head, common, git_directory, index, index_identity, status,
        (
            _open_directory_identity(repository, "retained validation repository"),
            _open_directory_identity(common, "retained validation Git common directory"),
            _open_directory_identity(git_directory, "retained validation Git directory"),
        ),
    )


def _pristine_frozen_validation_state(
    checkout: Path, *, expected_head: str
) -> tuple[object, ...]:
    """Bind every initialized gitlink and refuse content hidden by a parent index."""

    vcs = _GitVcs()
    initialized = tuple(sorted(vcs.initialized_submodules(checkout)))
    declared = tuple(sorted(
        path.relative_to(checkout).as_posix()
        for path in _declared_initialized_submodules(checkout)
    ))
    if initialized != declared:
        raise Refusal("retained validation initialized submodule declarations disagree")
    remaining = set(initialized)
    states: list[object] = []
    for relative in (".", *initialized):
        repository = checkout / relative
        _ensure_no_symlink_components(checkout, repository, "retained validation submodule")
        _ensure_no_mount_components(checkout, repository, "retained validation submodule")
        state = _retained_validation_git_state(repository, pristine=True)
        if relative == "." and state.head != expected_head:
            raise Refusal("retained validation checkout HEAD differs from its recorded target")
        if not _path_is_within(state.common, checkout):
            raise Refusal("retained validation submodule Git storage escapes the standalone clone")
        states.append((relative, state))
        entries = vcs._run(repository, ["ls-tree", "-r", "-z", "HEAD"]).stdout
        for entry in entries.split("\x00"):
            if not entry.startswith("160000 "):
                continue
            metadata, separator, raw_path = entry.partition("\t")
            fields = metadata.split()
            path = Path(raw_path)
            if (not separator or len(fields) != 3 or not SHA_RE.fullmatch(fields[2])
                    or path.is_absolute() or ".." in path.parts):
                raise Refusal("retained validation contains an unsafe gitlink")
            child = repository / path
            child_relative = child.relative_to(checkout).as_posix()
            _ensure_no_symlink_components(checkout, child, "retained validation gitlink")
            if child_relative in initialized:
                if vcs.head(child) != fields[2]:
                    raise Refusal(f"retained validation submodule HEAD differs from its gitlink: {child_relative}")
                remaining.discard(child_relative)
            elif child.exists():
                if not child.is_dir() or any(child.iterdir()):
                    raise Refusal(f"uninitialized retained validation gitlink contains files: {child_relative}")
                states.append((child_relative, _open_directory_identity(child, "uninitialized gitlink")))
            else:
                states.append((child_relative, None))
    if remaining:
        raise Refusal("retained validation initialized submodule has no committed gitlink")
    return tuple(states)


def _current_incomplete_frozen_retention(
    config: Config,
    checkout: Path,
    record_path: Path,
    record_contents: bytes,
    record_identity: _RegularFileIdentity,
    repository: Path,
    *,
    batch_cleanup: _OwnerlessValidationBatchContext,
) -> _FrozenNoProofClassification:
    """Preserve one authenticated, pristine and inactive current no-result."""

    record = _strict_json_object(record_contents, "current frozen validation run-record")
    states, archives = _validate_global_state(config)
    before_registry = _global_rows(states, archives)
    if _outstanding_journals(config) or _validate_batch_seal_journals(config):
        raise Refusal("current frozen validation retention requires completed registry operations")
    for state in states:
        for active in state.slots:
            slot = _slot_directory(config, active.slot, active.slot_type)
            if _path_is_within(checkout, slot) or _path_is_within(slot, checkout):
                raise Refusal(f"validation path belongs to registered slot {active.slot}")
    if not _validation_record_process_is_dead(record):
        raise Refusal("current frozen validation process state is live or uncertain")
    relative = record_path.relative_to(config.root).as_posix()
    _relative, digest, target = _terminal_validation_record(
        config, relative, checkout, "frozen-checkout", repository=repository,
        expected_digest=record_identity.sha256,
    )
    if target is None:
        raise StateError("current frozen validation has no exact target")
    # Keeping the entire clone needs no remote copy and no source-tree
    # cleanliness. Exact source path/origin and stable local observations are
    # still required, independently of the source's current HEAD.
    _head, remote = _validation_checkout_facts(
        config, checkout, repository, expected_head=target,
        batch_cleanup=batch_cleanup, standalone=True,
        require_remote_containment=False,
    )
    vcs = _GitVcs()
    before_clone = _pristine_frozen_validation_state(checkout, expected_head=target)
    before_source = _retained_validation_git_state(
        repository, pristine=False, cache_globs=config.cache_globs
    )
    if vcs.common_directory(repository) == vcs.common_directory(checkout):
        raise Refusal("retained validation source shares Git storage with the clone")
    producer = checkout / _VALIDATION_SERVICE_RESULT_SCHEMA_PATH
    sidecar = record_path.with_name(f"{record_path.stem}{_VALIDATION_SERVICE_RESULT_SUFFIX}")
    _ensure_no_symlink_components(checkout, producer, "current frozen validation producer schema")
    evidence = [(record_path, record_contents, record_identity)]
    for path in (producer, sidecar):
        contents, identity = _read_regular_file_identity(
            path, "current frozen validation evidence", _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT
        )
        evidence.append((path, contents, identity))
    projection = _validation_service_result_projection(
        evidence[2][1], schema=5,
        schema_fields=_validation_service_result_schema(evidence[1][1], 5),
        expected_commit=target,
    )
    for field, value in projection.items():
        if field not in record or not _json_equal(record[field], value):
            raise Refusal(f"current frozen validation service-result {field} differs from the run-record")
    batch_cleanup.assert_unused(config, checkout, fresh_same_uid=True)
    for path, contents, identity in evidence:
        rebound, rebound_identity = _read_regular_file_identity(
            path, "current frozen validation evidence", _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT
        )
        _assert_regular_file_identity(identity, rebound_identity, "current frozen validation evidence")
        if rebound != contents:
            raise Refusal("current frozen validation evidence changed during classification")
    if (before_clone != _pristine_frozen_validation_state(checkout, expected_head=target)
            or before_source != _retained_validation_git_state(
                repository, pristine=False, cache_globs=config.cache_globs
            )
            or remote != vcs.remote_url_sha256(repository, config.default_remote)
            or remote != vcs.remote_url_sha256(checkout, config.default_remote)):
        raise Refusal("current frozen validation source or checkout changed during classification")
    _terminal_validation_record(
        config, relative, checkout, "frozen-checkout", expected_digest=digest,
        repository=repository, expected_target=target,
    )
    if not _validation_record_process_is_dead(record):
        raise Refusal("current frozen validation process state changed during classification")
    batch_cleanup.assert_unused(config, checkout, fresh_same_uid=False)
    states, archives = _validate_global_state(config)
    if (before_registry != _global_rows(states, archives)
            or _outstanding_journals(config) or _validate_batch_seal_journals(config)):
        raise Refusal("registry state changed during current frozen validation classification")
    return _FrozenNoProofClassification(_FrozenNoProofDisposition.CURRENT_INCOMPLETE_RETAINED)


def _current_terminal_frozen_removal(
    config: Config,
    checkout: Path,
    record_relative: str,
    record_path: Path,
    record_contents: bytes,
    record_identity: _RegularFileIdentity,
    record_digest: str,
    repository: Path,
    frozen_result: _FrozenResultEvidence,
    *,
    batch_cleanup: _OwnerlessValidationBatchContext,
) -> _FrozenNoProofClassification:
    """Authorize journaled removal of one inactive, result-recorded frozen clone.

    The decision follows exact checkout facts, a fresh same-UID census, and a
    second read of the run-record and durable result.  Removal itself still
    goes through the ordinary journaled recovery, which rebinds all of it.
    """

    target = frozen_result.target
    _validation_checkout_facts(
        config,
        checkout,
        repository,
        expected_head=target,
        batch_cleanup=batch_cleanup,
        fresh_same_uid=False,
        standalone=True,
        remote_observation_repository=repository,
        require_remote_containment=False,
    )
    batch_cleanup.assert_unused(config, checkout, fresh_same_uid=True)
    label = "current frozen validation run-record"
    rebound, rebound_identity = _read_regular_file_identity(
        record_path, label, _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT
    )
    _assert_regular_file_identity(record_identity, rebound_identity, label)
    if rebound != record_contents:
        raise Refusal(f"{label} changed during entry classification")
    _terminal_validation_record(
        config,
        record_relative,
        checkout,
        "frozen-checkout",
        expected_digest=record_digest,
        repository=repository,
        expected_target=target,
        frozen_removal_proof_supplied=False,
        frozen_result=frozen_result,
    )
    if _GitVcs().head(checkout) != target:
        raise Refusal(
            "current frozen validation checkout HEAD changed during entry classification"
        )
    return _FrozenNoProofClassification(
        _FrozenNoProofDisposition.CURRENT_TERMINAL_REMOVABLE,
        frozen_result=frozen_result,
    )


def _frozen_no_proof_disposition(
    config: Config,
    checkout: Path,
    raw_record: str,
    raw_repository: str,
    *,
    batch_cleanup: _OwnerlessValidationBatchContext,
) -> _FrozenNoProofClassification:
    """Prove one supported frozen run is inert without authorizing its deletion.

    Historical schema-2/3 producers did not retain the four-artifact removal
    proof required by current cleanup.  Such a checkout must remain on disk,
    but it need not prevent an unrelated validation from starting when every
    fact other than deletion authority is still readable and exact.  The
    distinct legacy result-source case keeps its existing recovery behavior;
    current incomplete results have a separate stricter preservation path;
    an inactive current terminal result with a durable frozen result row is
    handed to journaled removal; other current and malformed shapes block
    entry. This classification is read-only: it neither creates a proof nor
    qualifies the historical result.
    """

    record_relative, record_path = _validation_run_record_argument(
        config, raw_record
    )
    record_contents, record_identity = _read_regular_file_identity(
        record_path,
        "historical frozen validation run-record",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    record = _strict_json_object(
        record_contents, "historical frozen validation run-record"
    )
    _repository_relative, repository = _repository_path(
        config, raw_repository, allow_managed=True
    )
    schema = record.get("service_result_schema")
    result_source = record.get("result_source")
    if (
        type(schema) is int
        and schema in {1, 2, 3}
        and result_source == "validation-service-result"
    ):
        return _FrozenNoProofClassification(
            _FrozenNoProofDisposition.LEGACY_RECOVERY
        )
    if (
        type(schema) is not int
        or schema not in {2, 3}
        or result_source != "historical-validation-service-result"
    ):
        _record_relative, record_digest, record_target = _terminal_validation_record(
            config,
            record_relative,
            checkout,
            "frozen-checkout",
            repository=repository,
        )
        if _current_incomplete_frozen_result(record):
            return _current_incomplete_frozen_retention(
                config, checkout, record_path, record_contents, record_identity,
                repository, batch_cleanup=batch_cleanup,
            )
        if record_target is None:
            raise StateError("current frozen validation has no exact target")
        if record_digest != record_identity.sha256:
            raise Refusal(
                "current frozen validation run-record changed during entry classification"
            )
        try:
            frozen_result = _durable_frozen_result(
                config, record_path, record, record_target
            )
        except Refusal as exc:
            return _FrozenNoProofClassification(
                _FrozenNoProofDisposition.BLOCKS_ENTRY, detail=str(exc)
            )
        return _current_terminal_frozen_removal(
            config, checkout, record_relative, record_path, record_contents,
            record_identity, record_digest, repository, frozen_result,
            batch_cleanup=batch_cleanup,
        )
    if (
        record.get("kind") != "frozen-validate"
        or record.get("materialized_target") is not False
        or "scorecard_handoff" in record
        or "scorecard_writeback_files" in record
    ):
        raise Refusal(
            "historical frozen validation without a removal proof does not match "
            "the pre-proof non-materialized shape"
        )
    if not _validation_record_process_is_dead(record):
        raise Refusal(
            "historical frozen validation process state is live or uncertain"
        )

    _record_relative, record_digest, record_target = _terminal_validation_record(
        config,
        record_relative,
        checkout,
        "frozen-checkout",
        repository=repository,
        allow_historical_service_result=True,
    )
    if record_target is None:
        raise StateError("historical frozen validation has no exact target")
    _validation_checkout_facts(
        config,
        checkout,
        repository,
        expected_head=record_target,
        batch_cleanup=batch_cleanup,
        fresh_same_uid=False,
        standalone=True,
        remote_observation_repository=repository,
        require_remote_containment=False,
    )

    producer_path = checkout / _VALIDATION_SERVICE_RESULT_SCHEMA_PATH
    sidecar_path = record_path.with_name(
        f"{record_path.stem}{_VALIDATION_SERVICE_RESULT_SUFFIX}"
    )
    _ensure_no_symlink_components(
        checkout, producer_path, "historical frozen validation producer schema"
    )
    producer_contents, producer_identity = _read_regular_file_identity(
        producer_path,
        "historical frozen validation producer schema",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    sidecar_contents, sidecar_identity = _read_regular_file_identity(
        sidecar_path,
        "historical frozen validation service-result",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    schema_fields = _validation_service_result_schema(producer_contents, schema)
    projection = _validation_service_result_projection(
        sidecar_contents,
        schema=schema,
        schema_fields=schema_fields,
        expected_commit=record_target,
    )
    for field, expected in projection.items():
        if field not in record or not _json_equal(record[field], expected):
            raise Refusal(
                f"historical frozen validation service-result {field} differs "
                "from the run-record"
            )
    if projection.get("scorecard_writeback") != {"status": "completed"}:
        raise Refusal(
            "historical frozen validation has no completed scorecard writeback"
        )

    # The decision is made only after a fresh same-UID census and a second read
    # of every authority-bearing file.  Any changed or unreadable observation
    # remains an entry blocker; no destructive action follows this proof.
    batch_cleanup.assert_unused(config, checkout, fresh_same_uid=True)
    rebound_record, rebound_record_identity = _read_regular_file_identity(
        record_path,
        "historical frozen validation run-record",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    rebound_producer, rebound_producer_identity = _read_regular_file_identity(
        producer_path,
        "historical frozen validation producer schema",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    rebound_sidecar, rebound_sidecar_identity = _read_regular_file_identity(
        sidecar_path,
        "historical frozen validation service-result",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    _assert_regular_file_identity(
        record_identity,
        rebound_record_identity,
        "historical frozen validation run-record",
    )
    _assert_regular_file_identity(
        producer_identity,
        rebound_producer_identity,
        "historical frozen validation producer schema",
    )
    _assert_regular_file_identity(
        sidecar_identity,
        rebound_sidecar_identity,
        "historical frozen validation service-result",
    )
    if (
        rebound_record != record_contents
        or rebound_producer != producer_contents
        or rebound_sidecar != sidecar_contents
    ):
        raise Refusal(
            "historical frozen validation evidence changed during entry classification"
        )
    _terminal_validation_record(
        config,
        record_relative,
        checkout,
        "frozen-checkout",
        expected_digest=record_digest,
        repository=repository,
        expected_target=record_target,
        allow_historical_service_result=True,
    )
    if _GitVcs().head(checkout) != record_target:
        raise Refusal(
            "historical frozen validation checkout HEAD changed during entry "
            "classification"
        )
    return _FrozenNoProofClassification(
        _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING,
        historical_schema=schema,
    )


def _recordless_validation_evidence(
    config: Config, target: Path, target_kind: str, note: str | None
) -> Mapping[str, object]:
    if note is None or not note.strip():
        raise Refusal("recordless validation recovery requires a non-empty --recovery-note")
    field = (
        "checkout"
        if target_kind in {"checkout", "frozen-checkout"}
        else "cargo_home"
    )
    records = config.root / "ignored" / "validate" / "runs"
    if records.is_symlink() or (records.exists() and not records.is_dir()):
        raise Refusal(f"retained validation record directory is unsafe: {records}")
    for path in sorted(records.glob("*.json")) if records.is_dir() else ():
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise Refusal(f"cannot prove retained record is unrelated: {path}: {exc}") from exc
        if not isinstance(value, dict):
            raise Refusal(f"cannot prove retained record is unrelated: {path} is not an object")
        recorded = value.get(field)
        if isinstance(recorded, str) and Path(recorded).resolve() == target:
            raise Refusal(
                f"retained validation record {path} names this {field}; use --completed-record"
            )
    return {"kind": "coordinator-determination", "note": note.strip(), "no_retained_record": True}


def _ownerless_validation_blocking_status(
    status: str, cache_globs: Sequence[str]
) -> str:
    """Keep every porcelain record except ignored paths under explicit safe roots."""

    blocking: list[str] = []
    for record in status.splitlines():
        if record.startswith("! "):
            path = record[2:]
            if any(_cache_glob_contains_path(pattern, path) for pattern in cache_globs):
                continue
        blocking.append(record)
    return "\n".join(blocking)


def _validation_checkout_facts(
    config: Config,
    checkout: Path,
    repository: Path,
    *,
    expected_head: str | None = None,
    expected_remote: str | None = None,
    batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    fresh_same_uid: bool = False,
    standalone: bool = False,
    remote_observation_repository: Path | None = None,
    require_remote_containment: bool = True,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> tuple[str, str]:
    selected_live_use_recheck = (
        live_use_recheck
        if live_use_recheck is not None
        else (
            batch_cleanup.live_use_recheck
            if batch_cleanup is not None
            else None
        )
    )
    if repository == checkout or _path_is_within(repository, checkout):
        raise Refusal("repository must survive removal and cannot be inside the checkout")
    if checkout.is_symlink() or not checkout.is_dir():
        raise Refusal(f"validation checkout is absent or unsafe: {checkout}")
    _ensure_no_mount_components(checkout.parent, checkout, "validation checkout")
    _assert_no_mountinfo_crossing(checkout, checkout, "validation checkout")
    handoff = _validation_handoff_artifact(checkout)
    if handoff is not None:
        raise Refusal(
            "validation checkout contains HANDOFF.md or another HANDOFF* artifact; "
            f"preserve it: {handoff}"
        )
    vcs = _GitVcs()
    if standalone:
        if (
            vcs.repository_root(checkout) != checkout.absolute()
            or (checkout / ".git").is_symlink()
            or not (checkout / ".git").is_dir()
        ):
            raise Refusal(
                f"frozen validation checkout is not a standalone Git clone: {checkout}"
            )
        head = vcs.head(checkout)
    else:
        head = vcs.verify_existing_worktree(repository, checkout)
    if expected_head is not None and head != expected_head:
        raise Refusal(
            "validation checkout HEAD changed after recovery was authorized; preserve the "
            "checkout and restore the recorded target before retrying"
        )
    if not standalone and vcs.initialized_submodules(checkout):
        raise Refusal(
            "ownerless linked validation checkout has initialized submodules; preserve it"
        )
    vcs.assert_ordinary_history(checkout)
    vcs.assert_ordinary_index(checkout)
    _assert_cache_policy_untracked_path(
        config, "ownerless-validation", checkout, vcs, config.cache_globs
    )
    preserve_checkout_git_state = (
        remote_observation_repository is not None or not require_remote_containment
    )
    status = _ownerless_validation_blocking_status(
        vcs.status(
            checkout,
            config.cache_globs,
            refresh_index=not preserve_checkout_git_state,
        ),
        ("ignored", *config.cache_globs),
    )
    if status:
        raise Refusal(f"validation checkout is dirty ({status.splitlines()[0]}); preserve it")
    remote = config.default_remote
    landed_ref = _landed_ref_for_remote(config, remote)
    checkout_authority = vcs.remote_authority(checkout, remote)
    remote_digest = checkout_authority.sha256
    repository_remote_digest = (
        vcs.remote_url_sha256(repository, remote)
        if standalone or remote_observation_repository is not None
        else None
    )
    if standalone and repository_remote_digest != remote_digest:
        raise Refusal(
            "frozen validation checkout remote differs from its recorded source checkout; "
            "preserve both checkouts and repair their origin binding before retrying"
        )
    if expected_remote is not None and remote_digest != expected_remote:
        raise Refusal("validation checkout remote changed after recovery was authorized")
    remote_observer = checkout
    observer_authority = checkout_authority
    if remote_observation_repository is not None:
        remote_observer = remote_observation_repository
        if remote_observer == checkout or _path_is_within(remote_observer, checkout):
            raise StateError(
                "retained validation checkout cannot supply its own remote observation"
            )
        if vcs.repository_root(remote_observer) != remote_observer.absolute():
            raise Refusal(
                "validation source repository is not its Git checkout root; preserve the "
                "retained checkout and repair the recorded source repository"
            )
        observer_common = vcs.common_directory(remote_observer)
        retained_common = vcs.common_directory(checkout)
        if (
            observer_common == retained_common
            or _path_is_within(observer_common, checkout)
        ):
            raise Refusal(
                "validation source repository shares Git storage with the retained "
                "checkout and cannot provide a non-mutating remote observation"
            )
        observer_status = _ownerless_validation_blocking_status(
            vcs.status(remote_observer, config.cache_globs),
            ("ignored", *config.cache_globs),
        )
        if observer_status:
            raise Refusal(
                "validation source repository is dirty and cannot provide the remote "
                f"observation ({observer_status.splitlines()[0]})"
            )
        vcs.assert_ordinary_history(remote_observer)
        vcs.assert_ordinary_index(remote_observer)
        observer_authority = vcs.remote_authority(remote_observer, remote)
        if observer_authority.sha256 != remote_digest:
            raise Refusal(
                "validation source repository remote differs from the retained checkout"
            )
    # Remote containment is preservation evidence for deletion.  The historical
    # path that deliberately retains the checkout needs exact local binding,
    # not a remote copy of a commit that the checkout continues to preserve.
    if require_remote_containment:
        vcs.fetch_remote(remote_observer, remote, landed_ref, observer_authority)
        if vcs.remote_url_sha256(checkout, remote) != remote_digest:
            raise Refusal("validation checkout remote changed during recovery inspection")
        vcs.assert_remote_authority(remote_observer, remote, observer_authority)
        if not vcs.remote_refs_containing(remote_observer, remote, head):
            raise Refusal(
                f"validation checkout HEAD {head} is not contained by remote {remote}"
            )
    if batch_cleanup is None:
        if standalone:
            census = _capture_process_path_census(
                (checkout,), include_owner_cgroups=False
            )
            _assert_slot_unused(
                checkout,
                census=census,
                ignore_current_process=False,
            )
        else:
            _assert_slot_unused(
                checkout, live_use_recheck=selected_live_use_recheck
            )
    else:
        batch_cleanup.assert_unused(
            config, checkout, fresh_same_uid=fresh_same_uid
        )
    return head, remote_digest


def _validation_cargo_facts(
    path: Path,
    *,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> tuple[int, int, int]:
    if path.is_symlink() or not path.is_dir():
        raise Refusal(f"validation Cargo home is absent or unsafe: {path}")
    _ensure_no_mount_components(path.parent, path, "validation Cargo home")
    _assert_no_mountinfo_crossing(path, path, "validation Cargo home")
    if (path / ".git").exists() or (path / ".git").is_symlink():
        raise Refusal("validation Cargo home is a Git worktree root; preserve it")
    handoff = _validation_handoff_artifact(path)
    if handoff is not None:
        raise Refusal(
            "validation Cargo home contains HANDOFF.md or another HANDOFF* artifact; "
            f"preserve it: {handoff}"
        )
    _assert_slot_unused(path, live_use_recheck=live_use_recheck)
    return _open_directory_identity(path.parent, "validation Cargo-home parent")


def _validation_authorization_to_obj(
    value: ValidationRecoveryAuthorization,
) -> dict[str, object]:
    encoded: dict[str, object] = {
        "target_kind": value.target_kind,
        "path": value.path,
        "identity": list(value.identity),
        "actor": _identity_to_obj(value.actor),
        "evidence": dict(value.evidence),
        "no_authored_work": value.no_authored_work,
        "no_live_use": value.no_live_use,
        "repository": value.repository,
        "head": value.head,
        "remote_url_sha256": value.remote_url_sha256,
        "parent_identity": None if value.parent_identity is None else list(value.parent_identity),
    }
    if value.stable_identity is not None:
        encoded["stable_identity"] = list(value.stable_identity)
    if value.removal_proof is not None:
        encoded["removal_proof"] = _validation_removal_proof_to_obj(
            value.removal_proof
        )
        encoded["proof_original_mode"] = value.proof_original_mode
        encoded["proof_private_identity"] = (
            None
            if value.proof_private_identity is None
            else list(value.proof_private_identity)
        )
    return encoded


def _validation_authorization_from_obj(value: object) -> ValidationRecoveryAuthorization:
    raw = _as_mapping(value, "validation recovery authorization")
    required = {
        "target_kind",
        "path",
        "identity",
        "actor",
        "evidence",
        "no_authored_work",
        "no_live_use",
        "repository",
        "head",
        "remote_url_sha256",
        "parent_identity",
    }
    _exact_keys(
        raw,
        required,
        {
            "stable_identity",
            "removal_proof",
            "proof_original_mode",
            "proof_private_identity",
        },
        "validation recovery authorization",
    )
    actor = _identity_from_obj(raw["actor"], "validation recovery actor")
    if actor is None or raw["no_authored_work"] is not True or raw["no_live_use"] is not True:
        raise StateError("validation recovery authorization is incomplete")
    identity = tuple(_as_int(item, "validation path identity") for item in _as_list(raw["identity"], "validation path identity"))
    parent = None if raw["parent_identity"] is None else tuple(
        _as_int(item, "validation parent identity")
        for item in _as_list(raw["parent_identity"], "validation parent identity")
    )
    if len(identity) != 3 or (parent is not None and len(parent) != 3):
        raise StateError("validation recovery directory identity must have three fields")
    stable = (
        None
        if raw.get("stable_identity") is None
        else _private_cleanup_identity_from_obj(
            raw["stable_identity"], "validation stable path identity"
        )
    )
    removal_proof = (
        None
        if raw.get("removal_proof") is None
        else _validation_removal_proof_from_obj(
            raw["removal_proof"], "validation recovery removal proof"
        )
    )
    proof_mode_raw = raw.get("proof_original_mode")
    proof_original_mode = (
        None
        if proof_mode_raw is None
        else _as_int(
            proof_mode_raw,
            "validation recovery proof original mode",
            minimum=0,
        )
    )
    if proof_original_mode is not None and proof_original_mode > 0o7777:
        raise StateError("validation recovery proof original mode exceeds permission bits")
    proof_identity_raw = raw.get("proof_private_identity")
    proof_private_identity = (
        None
        if proof_identity_raw is None
        else _private_cleanup_identity_from_obj(
            proof_identity_raw,
            "validation recovery proof private identity",
        )
    )
    if removal_proof is None and (
        proof_original_mode is not None or proof_private_identity is not None
    ):
        raise StateError("validation recovery has a proof seal without a proof")
    if (proof_original_mode is None) != (proof_private_identity is None):
        raise StateError("validation recovery proof seal is incomplete")
    return ValidationRecoveryAuthorization(
        target_kind=_as_str(raw["target_kind"], "validation target kind"),
        path=_as_str(raw["path"], "validation path"),
        identity=identity,
        actor=actor,
        evidence=_as_mapping(raw["evidence"], "validation recovery evidence"),
        no_authored_work=True,
        no_live_use=True,
        repository=None if raw["repository"] is None else _as_str(raw["repository"], "validation repository"),
        head=None if raw["head"] is None else _as_str(raw["head"], "validation HEAD"),
        remote_url_sha256=None if raw["remote_url_sha256"] is None else _as_str(raw["remote_url_sha256"], "validation remote digest"),
        parent_identity=parent,
        stable_identity=stable,
        removal_proof=removal_proof,
        proof_original_mode=proof_original_mode,
        proof_private_identity=proof_private_identity,
    )


def _ownerless_validation_journal(
    config: Config,
    args: argparse.Namespace,
    coordinator: ProcessIdentity,
    states: Sequence[ActiveState],
    batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    *,
    require_remote_containment: bool = True,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> tuple[dict[str, object], tuple[str, str] | None]:
    frozen_checkout = getattr(args, "frozen_validate_checkout", None)
    target_kind = (
        "frozen-checkout"
        if frozen_checkout is not None
        else "checkout"
        if args.ownerless_validate_checkout is not None
        else "cargo-home"
    )
    raw_target = (
        frozen_checkout
        or args.ownerless_validate_checkout
        or args.ownerless_validate_cargo_home
    )
    assert raw_target is not None
    if target_kind == "frozen-checkout" and args.completed_record is None:
        raise Refusal(
            "frozen validation checkout recovery requires --completed-record; pass the "
            "terminal frozen run handle and retry"
        )
    relative, target, allowed = _validation_recovery_target(config, raw_target, target_kind)
    for state in states:
        for record in state.slots:
            slot_path = _slot_directory(config, record.slot, record.slot_type)
            if target == slot_path or _path_is_within(target, slot_path):
                raise Refusal(f"validation path belongs to registered slot {record.slot}")
    repository_relative: str | None = None
    repository: Path | None = None
    if target_kind in {"checkout", "frozen-checkout"}:
        if args.repository is None:
            raise Refusal("validation checkout recovery requires --repository")
        repository_relative, repository = _repository_path(
            config, args.repository, allow_managed=True
        )
    elif args.repository is not None:
        raise Refusal("--repository applies only to validation checkouts")

    proof_manifest = getattr(args, "validation_proof_manifest", None)
    # Only the bounded batch supplies this, after its own read-only
    # classification; the recover command line has no way to name it.
    frozen_result: _FrozenResultEvidence | None = getattr(args, "frozen_result", None)
    if frozen_result is not None and (
        target_kind != "frozen-checkout"
        or proof_manifest is not None
        or batch_cleanup is None
        or args.completed_record is None
    ):
        raise StateError(
            "durable frozen result authority applies only to batch frozen cleanup "
            "without a proof"
        )
    record_path: str | None = None
    record_target: str | None = None
    if args.completed_record is not None:
        record_path, digest, record_target = _terminal_validation_record(
            config,
            args.completed_record,
            target,
            target_kind,
            repository=repository,
            allow_historical_service_result=proof_manifest is not None,
            frozen_removal_proof_supplied=(
                proof_manifest is not None
                if target_kind == "frozen-checkout"
                else None
            ),
            frozen_result=frozen_result,
        )
        evidence: Mapping[str, object] = {
            "kind": "terminal-record",
            "path": record_path,
            "sha256": digest,
        }
        if record_target is not None:
            evidence = {**evidence, "target": record_target}
        if frozen_result is not None:
            evidence = {
                **evidence,
                "frozen_result": _frozen_result_evidence_to_obj(frozen_result),
            }
        if args.recovery_note is not None:
            raise Refusal("--completed-record cannot be combined with --recovery-note")
    else:
        evidence = _recordless_validation_evidence(
            config, target, target_kind, args.recovery_note
        )
    identity = _open_directory_identity(target, "validation recovery path")
    stable_identity: _PrivateCleanupIdentity | None = None
    head: str | None = None
    remote_digest: str | None = None
    parent_identity: tuple[int, int, int] | None = None
    if target_kind in {"checkout", "frozen-checkout"}:
        assert repository is not None
        if target_kind == "frozen-checkout":
            frozen_root = _frozen_validation_directory(config)
            stable_identity = _private_cleanup_path_identity(
                config,
                target,
                allowed_modes={0o700},
                managed_root=frozen_root,
            )
            parent_identity = _open_directory_identity(
                frozen_root, "frozen validation checkout parent"
            )
            if stable_identity[:2] != identity[:2] or identity[2] != parent_identity[2]:
                raise Refusal("frozen validation checkout identity or mount changed")
        head, remote_digest = _validation_checkout_facts(
            config,
            target,
            repository,
            expected_head=record_target,
            batch_cleanup=batch_cleanup,
            standalone=target_kind == "frozen-checkout",
            require_remote_containment=require_remote_containment,
            live_use_recheck=live_use_recheck,
        )
    else:
        if args.repository is not None:
            raise Refusal("--repository applies only to validation checkouts")
        parent_identity = _validation_cargo_facts(
            target, live_use_recheck=live_use_recheck
        )
    removal_proof: _ValidationRemovalProof | None = None
    if proof_manifest is not None:
        if target_kind == "cargo-home":
            raise Refusal(
                "--validation-proof-manifest applies only to validation checkouts"
            )
        if record_path is None:
            raise Refusal(
                "validation removal proof requires the matching --completed-record"
            )
        assert head is not None
        removal_proof = _load_validation_removal_proof(
            config,
            proof_manifest,
            expected_slot=target.name,
            expected_generation=None,
            canonical_slot=target,
            canonical_checkout=target,
            expected_run_record=config.root / record_path,
            expected_head=head,
            target_kind=target_kind,
            repository=repository,
        )
    if target_kind == "checkout":
        raise Refusal(_OWNERLESS_LINKED_VALIDATION_REFUSAL)
    authorization = ValidationRecoveryAuthorization(
        target_kind=target_kind,
        path=relative,
        identity=identity,
        actor=coordinator,
        evidence=evidence,
        no_authored_work=True,
        no_live_use=True,
        repository=repository_relative,
        head=head,
        remote_url_sha256=remote_digest,
        parent_identity=parent_identity,
        stable_identity=stable_identity,
        removal_proof=removal_proof,
    )
    fenced = target.with_name(f".{target.name}.ownerless-validate.{uuid.uuid4().hex}")
    fenced_value = (
        str(fenced)
        if target_kind == "frozen-checkout"
        else fenced.relative_to(config.root).as_posix()
    )
    return {
        "schema": SCHEMA,
        "kind": "ownerless-validate-remove",
        "machine": config.machine,
        "slot": target.name,
        "phase": "prepared",
        "fenced": fenced_value,
        "authorization": _validation_authorization_to_obj(authorization),
    }, allowed


def _ownerless_validation_paths(
    config: Config,
    raw: Mapping[str, object],
) -> tuple[ValidationRecoveryAuthorization, Path, Path, str]:
    """Decode the durable ownerless-validation path identity without touching it."""

    _exact_keys(
        raw,
        _OWNERLESS_VALIDATE_JOURNAL_REQUIRED,
        _OWNERLESS_VALIDATE_JOURNAL_OPTIONAL,
        "ownerless validation journal",
    )
    if (
        _as_int(raw["schema"], "ownerless validation journal.schema") != SCHEMA
        or raw["kind"] != "ownerless-validate-remove"
        or raw["machine"] != config.machine
    ):
        raise StateError("ownerless validation journal identity is invalid")
    authorization = _validation_authorization_from_obj(raw["authorization"])
    _relative, target, _allowed = _validation_recovery_target(
        config, authorization.path, authorization.target_kind
    )
    if _as_str(raw["slot"], "ownerless validation slot") != target.name:
        raise StateError("ownerless validation journal slot differs from its path")
    raw_fenced = _as_str(raw["fenced"], "fenced validation path")
    if authorization.target_kind == "frozen-checkout":
        fenced = Path(raw_fenced)
        if not fenced.is_absolute():
            raise StateError("fenced frozen validation path must be absolute")
        fenced = Path(os.path.normpath(raw_fenced))
        if fenced.parent != _frozen_validation_directory(config):
            raise StateError("fenced frozen validation path has the wrong parent")
        _ensure_no_symlink_components(
            config.root.parent, fenced, "fenced frozen validation path"
        )
    else:
        _relative, fenced = _relative_inside(config.root, raw_fenced, "fenced path")
    prefix = f".{target.name}.ownerless-validate."
    if (
        fenced.parent != target.parent
        or not fenced.name.startswith(prefix)
        or not re.fullmatch(rf"{re.escape(prefix)}[0-9a-f]{{32}}", fenced.name)
    ):
        raise StateError("fenced validation path does not match its target")
    phase = _as_str(raw["phase"], "ownerless validation journal.phase")
    if phase not in _OWNERLESS_VALIDATION_PHASES:
        raise StateError(f"unknown ownerless validation phase {phase!r}")
    if "exclusion" in raw:
        _ownerless_validation_exclusion_from_obj(config, fenced, raw["exclusion"])
    return authorization, target, fenced, phase


def _ownerless_validation_inputs(
    config: Config,
    raw: Mapping[str, object],
    *,
    recheck: bool,
    batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    fresh_same_uid: bool = False,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> tuple[
    ValidationRecoveryAuthorization,
    Path,
    Path,
    Path | None,
    Path | None,
]:
    authorization, target, fenced, phase = _ownerless_validation_paths(config, raw)
    removal_proof = authorization.removal_proof
    if removal_proof is not None:
        if authorization.target_kind == "cargo-home":
            raise StateError("validation Cargo-home authorization cannot carry a proof")
        if (
            removal_proof.slot != target.name
            or removal_proof.checkout != _managed_file_reference(config, target)
        ):
            raise StateError(
                "validation recovery proof names another checkout"
            )
        _validation_proof_manifest_path(config, removal_proof.manifest_path)
        _validate_proof_artifact_paths(
            config,
            removal_proof.artifacts,
            canonical_slot=target,
            canonical_checkout=target,
        )
    target_present = target.exists() or target.is_symlink()
    fenced_present = fenced.exists() or fenced.is_symlink()
    if target_present and fenced_present:
        raise Refusal("canonical and fenced validation paths both exist; preserve both")
    active = target if target_present else fenced if fenced_present else None
    if phase != "removed" and active is None:
        raise Refusal(
            f"validation path disappeared during {phase} cleanup; removal outcome is "
            "UNKNOWN, so preserve the journal and inspect the authorized identity"
        )
    if phase == "removed" and active is not None:
        for candidate in (target, fenced):
            if (
                not candidate.is_symlink()
                and candidate.is_dir()
                and _open_directory_identity(candidate, "replacement validation path")
                == authorization.identity
            ):
                raise Refusal("authorized validation path reappeared after removal was recorded")
        # A completed removal journal authorizes bookkeeping for one exact old
        # inode, not control of a later same-name object.  Ignore replacements
        # after proving none has the authorized identity, and never inspect or
        # mutate their repository-controlled contents.
        active = None
    if active is not None:
        if (
            active.is_symlink()
            or not active.is_dir()
            or _open_directory_identity(active, "validation path")
            != authorization.identity
        ):
            raise Refusal("validation path identity changed; preserve it")
        if authorization.target_kind == "frozen-checkout":
            if authorization.stable_identity is None:
                raise StateError(
                    "frozen validation authorization has no stable file-handle identity"
                )
            observed_stable = _private_cleanup_path_identity(
                config,
                active,
                allowed_modes={0o700},
                managed_root=_frozen_validation_directory(config),
            )
            if observed_stable != authorization.stable_identity:
                raise Refusal(
                    "frozen validation path file-handle identity changed; preserve every "
                    "candidate path and inspect the interrupted journal before retrying"
                )
        if authorization.proof_private_identity is not None:
            managed_root = (
                _frozen_validation_directory(config)
                if authorization.target_kind == "frozen-checkout"
                else None
            )
            assert authorization.proof_original_mode is not None
            allowed_modes = {0o700}
            if phase == "prepared" and active == target:
                allowed_modes.add(authorization.proof_original_mode)
            observed_private = _private_cleanup_path_identity(
                config,
                active,
                allowed_modes=allowed_modes,
                managed_root=managed_root,
            )
            if observed_private != authorization.proof_private_identity:
                raise Refusal(
                    "validation proof cleanup fence identity changed; preserve the "
                    "checkout"
                )
    if (
        removal_proof is not None
        and authorization.proof_private_identity is None
        and (phase != "prepared" or active != target)
    ):
        raise StateError(
            "validation removal proof reached a destructive phase without a private "
            "cleanup identity"
        )
    repository: Path | None = None
    if authorization.target_kind in {"checkout", "frozen-checkout"}:
        if (
            authorization.repository is None
            or authorization.head is None
            or authorization.remote_url_sha256 is None
        ):
            raise StateError("validation checkout authorization is incomplete")
        if authorization.target_kind == "checkout" and (
            authorization.parent_identity is not None
            or authorization.stable_identity is not None
        ):
            raise StateError("ordinary validation checkout has frozen-path identity")
        if authorization.target_kind == "frozen-checkout" and (
            authorization.parent_identity is None
            or authorization.stable_identity is None
        ):
            raise StateError("frozen validation checkout authorization is incomplete")
        if (
            authorization.target_kind == "frozen-checkout"
            and _open_directory_identity(
                _frozen_validation_directory(config),
                "frozen validation checkout parent",
            )
            != authorization.parent_identity
        ):
            raise Refusal(
                "frozen validation checkout parent identity changed; preserve the checkout "
                "and restore the original sibling directory before retrying"
            )
        _stored, repository = _repository_path(
            config, authorization.repository, allow_managed=True
        )
        if repository == target or _path_is_within(repository, target):
            raise StateError("validation repository is inside the removal target")
    elif authorization.target_kind == "cargo-home":
        if (
            authorization.repository is not None
            or authorization.head is not None
            or authorization.remote_url_sha256 is not None
            or authorization.parent_identity is None
            or authorization.stable_identity is not None
        ):
            raise StateError("validation Cargo-home authorization is incomplete")
    else:
        raise StateError(f"unknown validation target kind {authorization.target_kind!r}")
    evidence = authorization.evidence
    kind = _as_str(evidence.get("kind"), "validation recovery evidence.kind")
    if kind == "terminal-record":
        _exact_keys(
            evidence,
            {"kind", "path", "sha256"},
            (
                {"target", "frozen_result"}
                if authorization.target_kind == "frozen-checkout"
                else set()
            ),
            "terminal evidence",
        )
        frozen_result = (
            None
            if "frozen_result" not in evidence
            else _frozen_result_evidence_from_obj(
                evidence["frozen_result"], target=authorization.head
            )
        )
        if frozen_result is not None and removal_proof is not None:
            raise StateError(
                "frozen terminal evidence cannot combine a durable result and a proof"
            )
        if authorization.target_kind == "frozen-checkout":
            evidence_target = _as_str(
                evidence.get("target"), "terminal evidence.target"
            )
            if evidence_target != authorization.head:
                raise StateError(
                    "frozen terminal evidence target differs from authorized HEAD"
                )
        if removal_proof is not None:
            proof_run_record = next(
                artifact
                for artifact in removal_proof.artifacts
                if artifact.role == "run-record"
            )
            if proof_run_record.path != _as_str(
                evidence["path"], "terminal evidence.path"
            ):
                raise StateError(
                    "validation removal proof run-record differs from terminal evidence"
                )
        if recheck:
            _terminal_validation_record(
                config,
                _as_str(evidence["path"], "terminal evidence.path"),
                target,
                authorization.target_kind,
                expected_digest=_as_str(evidence["sha256"], "terminal evidence.sha256"),
                repository=repository,
                expected_target=authorization.head,
                allow_historical_service_result=removal_proof is not None,
                frozen_removal_proof_supplied=(
                    removal_proof is not None
                    if authorization.target_kind == "frozen-checkout"
                    else None
                ),
                frozen_result=frozen_result,
            )
    elif kind == "coordinator-determination":
        _exact_keys(
            evidence,
            {"kind", "note", "no_retained_record"},
            set(),
            "coordinator determination",
        )
        if evidence["no_retained_record"] is not True:
            raise StateError("coordinator determination lacks no-record evidence")
        if recheck:
            _recordless_validation_evidence(
                config,
                target,
                authorization.target_kind,
                _as_str(evidence["note"], "coordinator determination.note"),
            )
    else:
        raise StateError(f"unknown validation recovery evidence kind {kind!r}")
    if removal_proof is not None and kind != "terminal-record":
        raise StateError("validation removal proof requires terminal record evidence")
    if recheck and active is not None:
        if authorization.target_kind in {"checkout", "frozen-checkout"}:
            assert repository is not None
            if active == fenced and authorization.target_kind == "checkout":
                _GitVcs().repair_worktree(repository, fenced)
            _validation_checkout_facts(
                config,
                active,
                repository,
                expected_head=authorization.head,
                expected_remote=authorization.remote_url_sha256,
                batch_cleanup=batch_cleanup,
                fresh_same_uid=fresh_same_uid,
                standalone=authorization.target_kind == "frozen-checkout",
                live_use_recheck=live_use_recheck,
            )
        else:
            assert authorization.parent_identity is not None
            if _validation_cargo_facts(
                active, live_use_recheck=live_use_recheck
            ) != authorization.parent_identity:
                raise Refusal("validation Cargo-home parent identity changed")
        if removal_proof is not None and fresh_same_uid:
            assert authorization.head is not None
            _recheck_validation_removal_proof(
                config,
                removal_proof,
                expected_slot=target.name,
                expected_generation=None,
                canonical_slot=target,
                active_slot=active,
                canonical_checkout=target,
                expected_head=authorization.head,
                target_kind=authorization.target_kind,
                repository=repository,
            )
            _interrupt_for_test("after-ownerless-validation-proof-recheck")
    return authorization, target, fenced, active, repository


def _rollback_validation_fence(
    config: Config,
    target: Path,
    fenced: Path,
    authorization: ValidationRecoveryAuthorization,
    repository: Path | None,
    journal: Mapping[str, object],
) -> None:
    if target.exists() or target.is_symlink() or fenced.is_symlink() or not fenced.is_dir():
        raise Refusal("cannot safely roll back validation path fence; preserve both paths")
    _rename_slot_path(config, fenced, target)
    _fsync_directory(target.parent)
    rollback_journal = {**journal, "phase": "prepared"}
    _write_journal(config, rollback_journal)
    if authorization.removal_proof is not None:
        if (
            authorization.proof_original_mode is None
            or authorization.proof_private_identity is None
        ):
            raise StateError("validation proof cleanup fence is incomplete")
        _restore_private_cleanup_path(
            target,
            authorization.proof_original_mode,
            authorization.proof_private_identity,
            allow_missing=False,
        )
    if authorization.target_kind == "checkout":
        assert repository is not None
        _GitVcs().repair_worktree(repository, target)
    _clear_journal(config, rollback_journal)


def _directory_identity_obj(identity: tuple[int, int, int]) -> list[int]:
    return list(identity)


def _directory_identity_from_obj(value: object, label: str) -> tuple[int, int, int]:
    fields = _as_list(value, label)
    if len(fields) != 3:
        raise StateError(f"{label} must contain device, inode, and mount id")
    return (
        _as_int(fields[0], f"{label}[0]", minimum=1),
        _as_int(fields[1], f"{label}[1]", minimum=1),
        _as_int(fields[2], f"{label}[2]", minimum=1),
    )


def _ownerless_validation_exclusion_name(config: Config, fenced: Path) -> str:
    token = fenced.name.rsplit(".", 1)[-1]
    if re.fullmatch(r"[0-9a-f]{32}", token) is None:
        raise StateError("fenced validation path has no exclusion identity")
    context = hashlib.sha256(
        os.fsencode(str(config.root)) + b"\0" + os.fsencode(str(fenced))
    ).hexdigest()[:16]
    return f".wrkslots-ownerless-validation.{token}.{context}"


def _ownerless_validation_exclusion_to_obj(
    value: _OwnerlessValidationExclusionRecord,
) -> dict[str, object]:
    return {
        "schema": _OWNERLESS_VALIDATION_EXCLUSION_SCHEMA,
        "phase": value.phase,
        "root": str(value.root),
        "root_identity": _directory_identity_obj(value.root_identity),
        "guard": str(value.guard),
        "guard_identity": _directory_identity_obj(value.guard_identity),
        "source_alias": str(value.source_alias),
        "payload_identity": list(value.payload_identity),
    }


def _ownerless_validation_exclusion_from_obj(
    config: Config,
    fenced: Path,
    value: object,
) -> _OwnerlessValidationExclusionRecord:
    raw = _as_mapping(value, "ownerless validation exclusion")
    _exact_keys(
        raw,
        {
            "schema",
            "phase",
            "root",
            "root_identity",
            "guard",
            "guard_identity",
            "source_alias",
            "payload_identity",
        },
        set(),
        "ownerless validation exclusion",
    )
    if (
        _as_int(raw["schema"], "ownerless validation exclusion.schema")
        != _OWNERLESS_VALIDATION_EXCLUSION_SCHEMA
    ):
        raise StateError("ownerless validation exclusion schema is unsupported")
    phase = _as_str(raw["phase"], "ownerless validation exclusion.phase")
    if phase not in _OWNERLESS_VALIDATION_EXCLUSION_PHASES:
        raise StateError(f"unknown ownerless validation exclusion phase {phase!r}")
    root = Path(_as_str(raw["root"], "ownerless validation exclusion.root"))
    guard = Path(_as_str(raw["guard"], "ownerless validation exclusion.guard"))
    source_alias = Path(
        _as_str(raw["source_alias"], "ownerless validation exclusion.source_alias")
    )
    if (
        root not in _OWNERLESS_VALIDATION_EXCLUSION_ROOTS
        or not root.is_absolute()
        or guard != root / _ownerless_validation_exclusion_name(config, fenced)
        or not source_alias.is_absolute()
        or ".." in source_alias.parts
        or any("\n" in str(path) or "\0" in str(path) for path in (root, guard, source_alias))
    ):
        raise StateError("ownerless validation exclusion paths are not canonical")
    payload_identity_values = _as_list(
        raw["payload_identity"], "ownerless validation exclusion.payload_identity"
    )
    if len(payload_identity_values) != 2:
        raise StateError(
            "ownerless validation exclusion payload identity must contain device and inode"
        )
    return _OwnerlessValidationExclusionRecord(
        phase=phase,
        root=root,
        root_identity=_directory_identity_from_obj(
            raw["root_identity"], "ownerless validation exclusion.root_identity"
        ),
        guard=guard,
        guard_identity=_directory_identity_from_obj(
            raw["guard_identity"], "ownerless validation exclusion.guard_identity"
        ),
        source_alias=source_alias,
        payload_identity=(
            _as_int(
                payload_identity_values[0],
                "ownerless validation exclusion.payload_identity[0]",
                minimum=1,
            ),
            _as_int(
                payload_identity_values[1],
                "ownerless validation exclusion.payload_identity[1]",
                minimum=1,
            ),
        ),
    )


def _self_mountinfo_records() -> tuple[tuple[int, str, Path, Path, str, str], ...]:
    """Parse the fields needed to map one bind-mounted path onto another view."""

    try:
        lines = Path("/proc/self/mountinfo").read_text(
            encoding="utf-8", errors="surrogateescape"
        ).splitlines()
    except OSError as exc:
        raise Refusal(f"cannot read mount layout for validation exclusion: {exc}") from exc
    records: list[tuple[int, str, Path, Path, str, str]] = []
    for line in lines:
        left, separator, right = line.partition(" - ")
        fields = left.split()
        right_fields = right.split()
        if not separator or len(fields) < 5 or len(right_fields) < 2:
            raise Refusal("mount layout is malformed while preparing validation exclusion")
        try:
            mount_id = int(fields[0])
        except ValueError as exc:
            raise Refusal("mount layout has a non-numeric mount id") from exc
        root = _mountinfo_path(fields[3])
        mount_point = _mountinfo_path(fields[4])
        if not root.is_absolute() or not mount_point.is_absolute():
            raise Refusal("mount layout contains a relative path")
        records.append(
            (
                mount_id,
                fields[2],
                root,
                mount_point,
                right_fields[0],
                right_fields[1],
            )
        )
    return tuple(records)


def _mountinfo_record_for_path(
    path: Path,
    records: Sequence[tuple[int, str, Path, Path, str, str]],
    label: str,
) -> tuple[int, str, Path, Path, str, str]:
    matches = [record for record in records if _path_is_within(path, record[3])]
    if not matches:
        raise Refusal(f"cannot identify the mount containing {label}: {path}")
    depth = max(len(record[3].parts) for record in matches)
    closest = [record for record in matches if len(record[3].parts) == depth]
    if len(closest) != 1:
        raise Refusal(f"mount layout is ambiguous for {label}: {path}")
    return closest[0]


def _mount_alias_path(
    path: Path,
    destination_root: Path,
    records: Sequence[tuple[int, str, Path, Path, str, str]],
) -> Path:
    """Derive one path on a peer mount from mount roots and mount points."""

    source = _mountinfo_record_for_path(path.parent, records, "validation path")
    destination = _mountinfo_record_for_path(
        destination_root, records, "validation exclusion root"
    )
    if source[0] == destination[0]:
        return path
    if (source[1], source[4], source[5]) != (
        destination[1],
        destination[4],
        destination[5],
    ):
        raise Refusal("validation exclusion root is on another filesystem")
    source_inside_filesystem = source[2] / path.parent.relative_to(source[3])
    try:
        alias_parent_relative = source_inside_filesystem.relative_to(destination[2])
    except ValueError as exc:
        raise Refusal(
            "validation path is outside the filesystem view containing the exclusion root"
        ) from exc
    alias_parent = destination[3] / alias_parent_relative
    return alias_parent / path.name


def _path_alias_on_mount(
    path: Path,
    destination_root: Path,
    records: Sequence[tuple[int, str, Path, Path, str, str]],
) -> Path:
    """Map path onto destination_root and authenticate both parent spellings."""

    alias = _mount_alias_path(path, destination_root, records)
    alias_parent = alias.parent
    try:
        source_parent = path.parent.stat(follow_symlinks=False)
        alias_parent_metadata = alias_parent.stat(follow_symlinks=False)
    except OSError as exc:
        raise Refusal(f"cannot authenticate validation path mount alias: {exc}") from exc
    if (
        not stat.S_ISDIR(source_parent.st_mode)
        or not stat.S_ISDIR(alias_parent_metadata.st_mode)
        or (source_parent.st_dev, source_parent.st_ino)
        != (alias_parent_metadata.st_dev, alias_parent_metadata.st_ino)
    ):
        raise Refusal("validation path mount alias names another parent directory")
    return alias


def _trusted_validation_exclusion_root(
    fenced: Path,
) -> tuple[Path, tuple[int, int, int], Path]:
    """Select one root-owned sticky path with an unambiguous same-filesystem view."""

    records = _self_mountinfo_records()
    direct: list[tuple[Path, tuple[int, int, int], Path]] = []
    aliases: list[tuple[Path, tuple[int, int, int], Path]] = []
    source_mount = _mountinfo_record_for_path(fenced.parent, records, "validation path")
    for candidate in _OWNERLESS_VALIDATION_EXCLUSION_ROOTS:
        try:
            metadata = candidate.stat(follow_symlinks=False)
            resolved = candidate.resolve(strict=True)
            descriptor = os.open(
                candidate,
                os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            )
        except OSError:
            continue
        try:
            identity = (
                metadata.st_dev,
                metadata.st_ino,
                _fd_mount_id(descriptor, str(candidate)),
            )
        finally:
            os.close(descriptor)
        if (
            resolved != candidate
            or not stat.S_ISDIR(metadata.st_mode)
            or metadata.st_uid != 0
            or metadata.st_gid != 0
            or stat.S_IMODE(metadata.st_mode) != 0o1777
        ):
            continue
        try:
            source_alias = _path_alias_on_mount(fenced, candidate, records)
        except Refusal:
            continue
        destination_mount = _mountinfo_record_for_path(
            candidate, records, "validation exclusion root"
        )
        entry = (candidate, identity, source_alias)
        if destination_mount[0] == source_mount[0]:
            direct.append(entry)
        else:
            aliases.append(entry)
    selected = direct if direct else aliases
    if len(selected) != 1:
        raise Refusal(
            "validation exclusion requires exactly one trusted root-owned, same-filesystem "
            f"sticky parent; found {len(selected)}"
        )
    return selected[0]


def _root_validation_exclusion_command(
    program: Path,
    arguments: Sequence[str],
    label: str,
    *,
    allow_stdout: bool = False,
) -> bytes:
    budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=15,
        stdout_limit=64 * 1024,
        stderr_limit=64 * 1024,
    )
    returncode, stdout, stderr = _run_root_owned_command(
        program, arguments, budget=budget
    )
    if returncode != 0 or stderr or (stdout and not allow_stdout):
        detail = (stderr or stdout).decode("utf-8", errors="replace").strip().splitlines()
        suffix = f": {detail[0]}" if detail else f" (exit {returncode})"
        raise Refusal(f"verified root context could not {label}{suffix}")
    return stdout


def _assert_verified_root_context() -> None:
    stdout = _root_validation_exclusion_command(
        Path("/usr/bin/id"), ("-u",), "identify itself", allow_stdout=True
    )
    if stdout != b"0\n":
        raise Refusal("validation exclusion command did not run as uid 0")


def _root_validation_path_metadata(path: Path, label: str) -> os.stat_result:
    stdout = _root_validation_exclusion_command(
        Path("/usr/bin/stat"),
        ("--format=%d:%i:%f:%u:%g", "--", str(path)),
        f"inspect {label}",
        allow_stdout=True,
    )
    try:
        device, inode, raw_mode, uid, gid = stdout.decode("ascii").strip().split(":")
        values = (int(device), int(inode), int(raw_mode, 16), int(uid), int(gid))
    except (UnicodeError, ValueError) as exc:
        raise Refusal(f"verified root context returned malformed {label} metadata") from exc
    return os.stat_result((values[2], values[1], values[0], 0, values[3], values[4], 0, 0, 0, 0))


def _root_validation_directory_names(path: Path) -> list[str]:
    stdout = _root_validation_exclusion_command(
        Path("/usr/bin/find"),
        (str(path), "-mindepth", "1", "-maxdepth", "1", "-printf", "%f\\0"),
        "enumerate the validation exclusion guard",
        allow_stdout=True,
    )
    try:
        names = stdout.decode("utf-8", errors="strict").split("\0")
    except UnicodeError as exc:
        raise Refusal("validation exclusion guard contains a non-UTF-8 name") from exc
    if names and names[-1] == "":
        names.pop()
    if any(not name or "/" in name or "\0" in name for name in names):
        raise Refusal("validation exclusion guard contains a malformed name")
    return sorted(names)


def _restore_ownerless_validation_exclusion(
    config: Config,
    raw: Mapping[str, object],
) -> dict[str, object]:
    """Restore a crash-interrupted root-owned exclusion before ordinary recovery."""

    authorization, target, fenced, phase = _ownerless_validation_paths(config, raw)
    exclusion_value = raw.get("exclusion")
    if exclusion_value is None:
        # An unrecorded guard can exist only if the process died between root mkdir
        # and the durable identity write. Never infer authority over it from its name.
        for root in _OWNERLESS_VALIDATION_EXCLUSION_ROOTS:
            guard = root / _ownerless_validation_exclusion_name(config, fenced)
            if guard.exists() or guard.is_symlink():
                raise Refusal(
                    "unrecorded validation exclusion guard exists; preserve it for "
                    "inspection"
                )
        return dict(raw)
    exclusion = _ownerless_validation_exclusion_from_obj(
        config, fenced, exclusion_value
    )
    if phase != "removing":
        raise StateError(
            "validation exclusion record exists outside the removing phase"
        )
    expected_alias = _path_alias_on_mount(
        fenced, exclusion.root, _self_mountinfo_records()
    )
    if expected_alias != exclusion.source_alias:
        raise Refusal("validation exclusion mount alias changed since it was recorded")
    _assert_verified_root_context()
    try:
        root_fd = os.open(
            exclusion.root,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
        )
    except OSError as exc:
        raise Refusal(
            f"cannot open validation exclusion root {exclusion.root}: {exc}"
        ) from exc
    try:
        root_metadata = os.fstat(root_fd)
        root_identity = (
            root_metadata.st_dev,
            root_metadata.st_ino,
            _fd_mount_id(root_fd, str(exclusion.root)),
        )
        if (
            root_identity != exclusion.root_identity
            or root_metadata.st_uid != 0
            or root_metadata.st_gid != 0
            or stat.S_IMODE(root_metadata.st_mode) != 0o1777
        ):
            raise Refusal("validation exclusion root identity or permissions changed")
        try:
            guard_metadata = os.stat(
                exclusion.guard.name, dir_fd=root_fd, follow_symlinks=False
            )
        except FileNotFoundError:
            restored_candidates = [
                candidate
                for candidate in (target, fenced)
                if candidate.is_dir()
                and not candidate.is_symlink()
                and _open_directory_identity(candidate, "restored validation path")
                == authorization.identity
            ]
            if len(restored_candidates) != 1:
                raise Refusal(
                    "recorded validation exclusion guard disappeared before recovery"
                )
            restored = dict(raw)
            restored.pop("exclusion", None)
            _write_journal(config, restored)
            return restored
        except OSError as exc:
            raise Refusal(
                f"cannot inspect validation exclusion guard {exclusion.guard}: {exc}"
            ) from exc
        observed_guard_identity = (
            guard_metadata.st_dev,
            guard_metadata.st_ino,
            exclusion.root_identity[2],
        )
        if (
            observed_guard_identity != exclusion.guard_identity
            or not stat.S_ISDIR(guard_metadata.st_mode)
            or guard_metadata.st_uid != 0
            or guard_metadata.st_gid != 0
            or stat.S_IMODE(guard_metadata.st_mode) not in {0, 0o755}
        ):
            raise Refusal("validation exclusion guard identity or ownership changed")
        names = _root_validation_directory_names(exclusion.guard)
        target_present = target.exists() or target.is_symlink()
        fenced_present = fenced.exists() or fenced.is_symlink()
        if target_present and fenced_present:
            raise Refusal(
                "canonical and fenced validation paths both exist during exclusion "
                "recovery"
            )
        restored_path = target if target_present else fenced if fenced_present else None
        if names == [] and restored_path is not None:
            if (
                restored_path.is_symlink()
                or not restored_path.is_dir()
                or _open_directory_identity(restored_path, "restored validation path")
                != authorization.identity
            ):
                raise Refusal("restored validation path identity changed")
        elif names == [_OWNERLESS_VALIDATION_EXCLUSION_ENTRY]:
            payload = exclusion.guard / _OWNERLESS_VALIDATION_EXCLUSION_ENTRY
            payload_metadata = _root_validation_path_metadata(
                payload, "excluded validation checkout"
            )
            if (
                not stat.S_ISDIR(payload_metadata.st_mode)
                or (payload_metadata.st_dev, payload_metadata.st_ino)
                != exclusion.payload_identity
                or exclusion.payload_identity != authorization.identity[:2]
            ):
                raise Refusal(
                    "excluded validation checkout identity changed; preserve it"
                )
            if target_present:
                destination = fenced
                destination_alias = exclusion.source_alias
            elif fenced_present:
                destination = target
                destination_alias = _path_alias_on_mount(
                    target, exclusion.root, _self_mountinfo_records()
                )
            else:
                destination = fenced
                destination_alias = exclusion.source_alias
            _root_validation_exclusion_command(
                Path("/usr/bin/mv"),
                (
                    "--no-clobber",
                    "--no-target-directory",
                    "--",
                    str(payload),
                    str(destination_alias),
                ),
                "restore the excluded validation checkout",
            )
            if (
                not destination.is_dir()
                or destination.is_symlink()
                or _open_directory_identity(destination, "restored validation checkout")
                != authorization.identity
            ):
                raise Refusal(
                    "excluded validation checkout was not restored to its exact identity"
                )
        else:
            raise Refusal(
                "validation exclusion state is ambiguous; preserve every path"
            )
        _root_validation_exclusion_command(
            Path("/usr/bin/rmdir"),
            ("--", str(exclusion.guard)),
            "remove the empty validation exclusion guard",
        )
        try:
            os.stat(exclusion.guard.name, dir_fd=root_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise Refusal("validation exclusion guard remains after recovery")
        os.fsync(root_fd)
        restored = dict(raw)
        restored.pop("exclusion", None)
        _write_journal(config, restored)
        return restored
    finally:
        os.close(root_fd)


def _begin_ownerless_validation_exclusion(
    config: Config,
    target: Path,
    fenced: Path,
    authorization: ValidationRecoveryAuthorization,
    journal: dict[str, object],
) -> _OwnerlessValidationExclusion:
    """Move a validation tree behind a root-owned, non-searchable path guard."""

    if target.exists() or target.is_symlink():
        raise Refusal(f"canonical validation path reappeared before cleanup: {target}")
    if not fenced.is_dir() or fenced.is_symlink():
        raise Refusal(f"fenced validation path disappeared before exclusion: {fenced}")
    root, root_identity, source_alias = _trusted_validation_exclusion_root(fenced)
    guard = root / _ownerless_validation_exclusion_name(config, fenced)
    payload = guard / _OWNERLESS_VALIDATION_EXCLUSION_ENTRY
    assert authorization.parent_identity is not None
    source_parent_fd, source_name, _source_parent_mount_id = _open_parent_directory(
        fenced.parent,
        fenced,
        "fenced validation checkout",
        expected_root_identity=authorization.parent_identity,
    )
    root_fd: int | None = None
    guard_fd: int | None = None
    payload_fd: int | None = None
    try:
        _assert_verified_root_context()
        try:
            root_fd = os.open(
                root,
                os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            )
        except OSError as exc:
            raise Refusal(f"cannot open validation exclusion root {root}: {exc}") from exc
        opened_root = os.fstat(root_fd)
        if (
            (
                opened_root.st_dev,
                opened_root.st_ino,
                _fd_mount_id(root_fd, str(root)),
            )
            != root_identity
            or opened_root.st_uid != 0
            or opened_root.st_gid != 0
            or stat.S_IMODE(opened_root.st_mode) != 0o1777
        ):
            raise Refusal("validation exclusion root identity changed before use")
        try:
            os.stat(guard.name, dir_fd=root_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise Refusal(
                f"cannot inspect validation exclusion guard {guard}: {exc}"
            ) from exc
        else:
            raise Refusal(f"validation exclusion guard already exists: {guard}")
        payload_fd = os.open(
            source_name,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=source_parent_fd,
        )
        payload_metadata = os.fstat(payload_fd)
        payload_identity = (
            payload_metadata.st_dev,
            payload_metadata.st_ino,
            _fd_mount_id(payload_fd, str(fenced)),
        )
        if (
            not stat.S_ISDIR(payload_metadata.st_mode)
            or payload_identity != authorization.identity
        ):
            raise Refusal("validation checkout identity changed before exclusion")
        alias_metadata = source_alias.stat(follow_symlinks=False)
        if (
            not stat.S_ISDIR(alias_metadata.st_mode)
            or (alias_metadata.st_dev, alias_metadata.st_ino)
            != (payload_metadata.st_dev, payload_metadata.st_ino)
        ):
            raise Refusal("validation checkout mount alias names another inode")
        _root_validation_exclusion_command(
            Path("/usr/bin/mkdir"),
            ("--mode=0755", "--", str(guard)),
            "create the validation exclusion guard",
        )
        guard_fd = os.open(
            guard.name,
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=root_fd,
        )
        guard_metadata = os.fstat(guard_fd)
        guard_identity = (
            guard_metadata.st_dev,
            guard_metadata.st_ino,
            _fd_mount_id(guard_fd, str(guard)),
        )
        if (
            not stat.S_ISDIR(guard_metadata.st_mode)
            or guard_metadata.st_uid != 0
            or guard_metadata.st_gid != 0
            or stat.S_IMODE(guard_metadata.st_mode) != 0o755
            or guard_identity[2] != root_identity[2]
        ):
            raise Refusal("validation exclusion guard is not root-owned and private")
        exclusion_record = _OwnerlessValidationExclusionRecord(
            phase="guard-created",
            root=root,
            root_identity=root_identity,
            guard=guard,
            guard_identity=guard_identity,
            source_alias=source_alias,
            payload_identity=authorization.identity[:2],
        )
        journal["exclusion"] = _ownerless_validation_exclusion_to_obj(
            exclusion_record
        )
        _write_journal(config, journal)
        os.fsync(root_fd)
        _interrupt_for_test("after-ownerless-validate-exclusion-directory")
        _root_validation_exclusion_command(
            Path("/usr/bin/chmod"),
            ("000", "--", str(guard)),
            "seal the validation exclusion guard",
        )
        sealed = os.fstat(guard_fd)
        path_sealed = os.stat(guard.name, dir_fd=root_fd, follow_symlinks=False)
        if (
            (sealed.st_dev, sealed.st_ino) != guard_identity[:2]
            or (path_sealed.st_dev, path_sealed.st_ino) != guard_identity[:2]
            or sealed.st_uid != 0
            or sealed.st_gid != 0
            or stat.S_IMODE(sealed.st_mode) != 0
            or stat.S_IMODE(path_sealed.st_mode) != 0
        ):
            raise Refusal("validation exclusion guard did not become root-owned mode 000")
        _interrupt_for_test("after-ownerless-validate-exclusion-seal")
        _root_validation_exclusion_command(
            Path("/usr/bin/mv"),
            (
                "--no-clobber",
                "--no-target-directory",
                "--",
                str(source_alias),
                str(payload),
            ),
            "move the validation checkout behind its exclusion guard",
        )
        os.fsync(guard_fd)
        os.fsync(source_parent_fd)
        _interrupt_for_test("after-ownerless-validate-exclusion-move")
        moved_metadata = _root_validation_path_metadata(
            payload, "excluded validation checkout"
        )
        if (
            not stat.S_ISDIR(moved_metadata.st_mode)
            or (moved_metadata.st_dev, moved_metadata.st_ino)
            != authorization.identity[:2]
            or (os.fstat(payload_fd).st_dev, os.fstat(payload_fd).st_ino)
            != authorization.identity[:2]
        ):
            raise Refusal("validation checkout identity changed during exclusion")
        _assert_parent_entry_absent(
            source_parent_fd, fenced.parent, fenced, "fenced validation path"
        )
        try:
            source_alias.stat(follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise Refusal("validation checkout mount alias remains after exclusion move")
        if (
            authorization.stable_identity is not None
            and _fd_private_cleanup_identity(payload_fd, str(payload))
            != authorization.stable_identity
        ):
            raise Refusal(
                "validation checkout stable identity changed during exclusion"
            )
        exclusion_record = dataclasses.replace(
            exclusion_record, phase="payload-moved"
        )
        journal["exclusion"] = _ownerless_validation_exclusion_to_obj(
            exclusion_record
        )
        _write_journal(config, journal)
        return _OwnerlessValidationExclusion(
            root=root,
            guard=guard,
            payload=payload,
            source_alias=source_alias,
            root_fd=root_fd,
            source_parent_fd=source_parent_fd,
            guard_fd=guard_fd,
            payload_fd=payload_fd,
            record=exclusion_record,
        )
    except BaseException:
        if payload_fd is not None:
            os.close(payload_fd)
        if guard_fd is not None:
            os.close(guard_fd)
        if root_fd is not None:
            os.close(root_fd)
        os.close(source_parent_fd)
        raise


def _assert_current_process_only_holds_excluded_payload(
    exclusion: _OwnerlessValidationExclusion,
    target: Path,
    fenced: Path,
) -> tuple[int, str, str, str] | None:
    """Permit only the remover's exact payload descriptor in its own process."""

    paths = (exclusion.payload, exclusion.source_alias, fenced, target)
    targets = {path: str(path) for path in paths}
    base = Path("/proc/self")
    for name in ("cwd", "root", "exe"):
        try:
            raw = os.readlink(base / name)
        except FileNotFoundError:
            continue
        observed = Path(os.path.normpath(raw.removesuffix(" (deleted)")))
        if _matching_absent_validate_target(observed, targets) is not None:
            raise Refusal(
                f"cleanup process unexpectedly uses excluded validation path: {name}={raw}"
            )
    expected_seen = False
    expected_census_match: tuple[int, str, str, str] | None = None
    try:
        descriptors = tuple((base / "fd").iterdir())
    except OSError as exc:
        raise Refusal(f"cannot inspect cleanup process descriptors: {exc}") from exc
    for descriptor in descriptors:
        try:
            raw = os.readlink(descriptor)
        except FileNotFoundError:
            continue
        if descriptor.name == str(exclusion.payload_fd):
            metadata = os.fstat(exclusion.payload_fd)
            if (metadata.st_dev, metadata.st_ino) != exclusion.record.payload_identity:
                raise Refusal("cleanup process payload descriptor changed identity")
            expected_seen = True
            observed = Path(os.path.normpath(raw.removesuffix(" (deleted)")))
            matched = _matching_absent_validate_target(observed, targets)
            if matched is not None:
                _target, slot = matched
                expected_census_match = (os.getpid(), slot, "link", raw)
            continue
        observed = Path(os.path.normpath(raw.removesuffix(" (deleted)")))
        if _matching_absent_validate_target(observed, targets) is None:
            continue
        raise Refusal(
            "cleanup process has an unexpected descriptor into the excluded "
            f"validation path: fd/{descriptor.name}={raw}"
        )
    if not expected_seen:
        raise Refusal("cleanup process lost its excluded validation descriptor")
    try:
        maps = (base / "maps").read_text(encoding="utf-8", errors="surrogateescape")
    except OSError as exc:
        raise Refusal(f"cannot inspect cleanup process mappings: {exc}") from exc
    for line in maps.splitlines():
        fields = line.split(maxsplit=5)
        if len(fields) != 6 or not fields[5].startswith("/"):
            continue
        observed = Path(os.path.normpath(fields[5].removesuffix(" (deleted)")))
        if _matching_absent_validate_target(observed, targets) is not None:
            raise Refusal(
                "cleanup process maps a file from the excluded validation path"
            )
    return expected_census_match


def _assert_excluded_validation_unused(
    exclusion: _OwnerlessValidationExclusion,
    target: Path,
    fenced: Path,
    batch_cleanup: _OwnerlessValidationBatchContext | None,
) -> None:
    """Census after the namespace move while ordinary same-UID entry is denied."""

    if batch_cleanup is None:
        budget = _ReadOnlyCommandBudget.start(
            timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
            stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
            stderr_limit=64 * 1024,
            input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
    else:
        batch_cleanup.same_uid_census_count += 1
        budget = _ReadOnlyCommandBudget.start(
            timeout_seconds=batch_cleanup.census_budget.remaining_seconds(),
            stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
            stderr_limit=64 * 1024,
            input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
    expected_match = _assert_current_process_only_holds_excluded_payload(
        exclusion, target, fenced
    )
    census_paths = tuple(
        dict.fromkeys((exclusion.payload, exclusion.source_alias, fenced, target))
    )
    fresh = _capture_same_uid_process_path_census(census_paths, budget=budget)
    matches = list(fresh.matches)
    if expected_match is not None and expected_match in matches:
        matches.remove(expected_match)
    filtered = dataclasses.replace(fresh, matches=tuple(matches))
    for census_path in census_paths:
        filtered.assert_slot_unused(
            census_path,
            None,
            ignore_current_process=False,
        )
    _assert_current_process_only_holds_excluded_payload(exclusion, target, fenced)
    if batch_cleanup is not None:
        batch_cleanup.census_budget.remaining_seconds()


def _read_regular_file_identity_beneath(
    directory_fd: int,
    relative: Path,
    label: str,
    limit: int,
) -> tuple[bytes, _RegularFileIdentity]:
    """Read a bounded regular file beneath an already-open directory."""

    if relative.is_absolute() or not relative.parts or ".." in relative.parts:
        raise Refusal(f"{label} is not beneath the excluded validation checkout")
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    current_fd = os.dup(directory_fd)
    try:
        for component in relative.parts[:-1]:
            next_fd = os.open(component, flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd
        file_flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
        if hasattr(os, "O_NOFOLLOW"):
            file_flags |= os.O_NOFOLLOW
        descriptor = os.open(relative.parts[-1], file_flags, dir_fd=current_fd)
        try:
            before = os.fstat(descriptor)
            if not stat.S_ISREG(before.st_mode):
                raise Refusal(f"{label} is not a regular file")
            if before.st_size > limit:
                raise Refusal(f"{label} exceeds the {limit}-byte safety bound")
            chunks: list[bytes] = []
            remaining = limit + 1
            while remaining:
                chunk = os.read(descriptor, min(remaining, 64 * 1024))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            contents = b"".join(chunks)
            after = os.fstat(descriptor)
        finally:
            os.close(descriptor)
    except OSError as exc:
        raise Refusal(
            f"cannot read {label} below the excluded checkout: {exc}"
        ) from exc
    finally:
        os.close(current_fd)
    if len(contents) > limit or len(contents) != after.st_size:
        raise Refusal(f"{label} changed while it was read")
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_mode",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(getattr(before, field) != getattr(after, field) for field in stable_fields):
        raise Refusal(f"{label} changed while it was read")
    return contents, _RegularFileIdentity(
        device=after.st_dev,
        inode=after.st_ino,
        size=after.st_size,
        sha256=hashlib.sha256(contents).hexdigest(),
    )


def _recheck_excluded_validation_proof(
    config: Config,
    authorization: ValidationRecoveryAuthorization,
    canonical_slot: Path,
    repository: Path | None,
    payload_fd: int,
) -> None:
    """Rebind every proof artifact after excluding the checkout from new use."""

    proof = authorization.removal_proof
    evidence = authorization.evidence
    if proof is None and "frozen_result" in evidence:
        # A durable frozen result authorizes this removal in place of a proof,
        # so its run-record and result row are rebound after the final census
        # exactly as proof artifacts are.
        _terminal_validation_record(
            config,
            _as_str(evidence.get("path"), "terminal evidence.path"),
            canonical_slot,
            authorization.target_kind,
            expected_digest=_as_str(evidence.get("sha256"), "terminal evidence.sha256"),
            repository=repository,
            expected_target=authorization.head,
            frozen_removal_proof_supplied=False,
            frozen_result=_frozen_result_evidence_from_obj(
                evidence["frozen_result"], target=authorization.head
            ),
        )
        return
    if proof is None:
        return
    if authorization.head is None:
        raise StateError("validation checkout authorization has no exact HEAD")
    _recheck_validation_removal_proof(
        config,
        proof,
        expected_slot=canonical_slot.name,
        expected_generation=None,
        canonical_slot=canonical_slot,
        active_slot=canonical_slot,
        canonical_checkout=canonical_slot,
        expected_head=authorization.head,
        target_kind=authorization.target_kind,
        repository=repository,
        active_slot_fd=payload_fd,
    )


def _remove_excluded_validation_tree(
    config: Config,
    exclusion: _OwnerlessValidationExclusion,
    target: Path,
    fenced: Path,
    authorization: ValidationRecoveryAuthorization,
) -> int:
    """Delete the authorized payload through its FD, then remove the root guard."""

    _assert_excluded_validation_tree_bound(exclusion, target, fenced, authorization)
    _original, _mount_id, size = _clear_bound_cache_directory(
        exclusion.payload_fd,
        exclusion.payload,
        allow_git_metadata=True,
        expected_identity=authorization.identity,
        expected_stable_identity=authorization.stable_identity,
    )
    _assert_excluded_validation_tree_bound(exclusion, target, fenced, authorization)
    _root_validation_exclusion_command(
        Path("/usr/bin/rmdir"),
        ("--", str(exclusion.payload)),
        "remove the empty excluded validation checkout",
    )
    try:
        os.fsync(exclusion.guard_fd)
    except OSError as exc:
        raise Refusal(f"cannot sync emptied validation exclusion guard: {exc}") from exc
    _root_validation_exclusion_command(
        Path("/usr/bin/rmdir"),
        ("--", str(exclusion.guard)),
        "remove the empty validation exclusion guard",
    )
    try:
        os.stat(exclusion.guard.name, dir_fd=exclusion.root_fd, follow_symlinks=False)
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise Refusal(f"cannot recheck removed validation exclusion guard: {exc}") from exc
    else:
        raise Refusal("validation exclusion guard remains after removal")
    os.fsync(exclusion.root_fd)
    return size


def _assert_excluded_validation_tree_bound(
    exclusion: _OwnerlessValidationExclusion,
    target: Path,
    fenced: Path,
    authorization: ValidationRecoveryAuthorization,
) -> None:
    """Recheck all names and identities before destructive traversal starts."""

    root_metadata = os.fstat(exclusion.root_fd)
    root_identity = (
        root_metadata.st_dev,
        root_metadata.st_ino,
        _fd_mount_id(exclusion.root_fd, str(exclusion.root)),
    )
    if (
        root_identity != exclusion.record.root_identity
        or root_metadata.st_uid != 0
        or root_metadata.st_gid != 0
        or stat.S_IMODE(root_metadata.st_mode) != 0o1777
    ):
        raise Refusal("validation exclusion root identity or permissions changed")
    guard_metadata = os.fstat(exclusion.guard_fd)
    if (
        (
            guard_metadata.st_dev,
            guard_metadata.st_ino,
            _fd_mount_id(exclusion.guard_fd, str(exclusion.guard)),
        )
        != exclusion.record.guard_identity
        or guard_metadata.st_uid != 0
        or guard_metadata.st_gid != 0
        or stat.S_IMODE(guard_metadata.st_mode) != 0
    ):
        raise Refusal("validation exclusion guard became accessible before cleanup")
    try:
        current_guard = os.stat(
            exclusion.guard.name,
            dir_fd=exclusion.root_fd,
            follow_symlinks=False,
        )
    except OSError as exc:
        raise Refusal(
            f"validation exclusion guard disappeared before cleanup: {exc}"
        ) from exc
    if (
        current_guard.st_dev,
        current_guard.st_ino,
    ) != exclusion.record.guard_identity[:2]:
        raise Refusal("validation exclusion guard identity changed before cleanup")
    _assert_parent_entry_absent(
        exclusion.source_parent_fd,
        target.parent,
        target,
        "canonical validation path",
    )
    _assert_parent_entry_absent(
        exclusion.source_parent_fd,
        fenced.parent,
        fenced,
        "fenced validation path",
    )
    payload_metadata = os.fstat(exclusion.payload_fd)
    payload_identity = (
        payload_metadata.st_dev,
        payload_metadata.st_ino,
        _fd_mount_id(exclusion.payload_fd, str(exclusion.payload)),
    )
    if payload_identity != authorization.identity:
        raise Refusal("excluded validation checkout identity changed before cleanup")
    root_payload = _root_validation_path_metadata(
        exclusion.payload, "excluded validation checkout"
    )
    if (
        not stat.S_ISDIR(root_payload.st_mode)
        or (root_payload.st_dev, root_payload.st_ino)
        != exclusion.record.payload_identity
    ):
        raise Refusal("excluded validation checkout path changed before cleanup")
    try:
        exclusion.source_alias.stat(follow_symlinks=False)
    except FileNotFoundError:
        pass
    else:
        raise Refusal("validation checkout mount alias reappeared before cleanup")
    if (
        authorization.stable_identity is not None
        and _fd_private_cleanup_identity(exclusion.payload_fd, str(exclusion.payload))
        != authorization.stable_identity
    ):
        raise Refusal(
            "excluded validation checkout stable identity changed before cleanup"
        )


def _recover_ownerless_validation(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
    runner: ProcessIdentity,
    handoff_writer: ProcessIdentity | None,
    proof_fd: int | None,
    *,
    batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    emit: bool = True,
    live_use_recheck: _LiveUseRecheckBudget | None = None,
) -> None:
    if path != _journal_path(config):
        raise StateError("ownerless validation journal filename is invalid")
    _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
    selected_live_use_recheck = (
        live_use_recheck
        if live_use_recheck is not None
        else (
            batch_cleanup.live_use_recheck
            if batch_cleanup is not None
            else _LiveUseRecheckBudget()
        )
    )
    initial_authorization, _target, _fenced, initial_phase = _ownerless_validation_paths(
        config, raw
    )
    if (
        initial_authorization.target_kind == "checkout"
        and initial_phase != "removed"
    ):
        raise Refusal(_OWNERLESS_LINKED_VALIDATION_REFUSAL)
    if initial_authorization.target_kind != "checkout":
        raw = _restore_ownerless_validation_exclusion(config, raw)
    authorization, target, fenced, active, repository = _ownerless_validation_inputs(
        config,
        raw,
        recheck=False,
        batch_cleanup=batch_cleanup,
        live_use_recheck=selected_live_use_recheck,
    )
    journal = dict(raw)
    if active is not None:
        try:
            authorization, target, fenced, active, repository = (
                _ownerless_validation_inputs(
                    config,
                    journal,
                    recheck=True,
                    batch_cleanup=batch_cleanup,
                    live_use_recheck=selected_live_use_recheck,
                )
            )
        except Refusal:
            if active == fenced and not target.exists():
                _rollback_validation_fence(
                    config, target, fenced, authorization, repository, journal
                )
            raise
        if authorization.removal_proof is not None:
            managed_root = (
                _frozen_validation_directory(config)
                if authorization.target_kind == "frozen-checkout"
                else None
            )
            if authorization.proof_private_identity is None:
                if active != target:
                    raise StateError(
                        "validation proof cleanup reached a fenced path before its "
                        "private identity was recorded"
                    )
                sealed_authorization: list[ValidationRecoveryAuthorization] = []

                def record_proof_seal(
                    original_mode: int,
                    identity: _PrivateCleanupIdentity,
                ) -> None:
                    updated = dataclasses.replace(
                        authorization,
                        proof_original_mode=original_mode,
                        proof_private_identity=identity,
                    )
                    journal["authorization"] = _validation_authorization_to_obj(
                        updated
                    )
                    _write_journal(config, journal)
                    sealed_authorization.append(updated)
                    _interrupt_for_test(
                        "after-ownerless-validation-proof-seal-planned"
                    )

                original_mode, private_identity = _seal_cleanup_path_private(
                    config,
                    active,
                    before_seal=record_proof_seal,
                    managed_root=managed_root,
                )
                if not sealed_authorization:
                    raise StateError(
                        "validation proof cleanup did not record its private seal"
                    )
                authorization = sealed_authorization[0]
                if (
                    authorization.proof_original_mode != original_mode
                    or authorization.proof_private_identity != private_identity
                ):
                    raise StateError(
                        "validation proof cleanup seal changed after it was recorded"
                    )
            else:
                assert authorization.proof_original_mode is not None
                assert active is not None
                _reestablish_private_cleanup_fence(
                    config,
                    active,
                    authorization.proof_original_mode,
                    authorization.proof_private_identity,
                    managed_root=managed_root,
                )
            _interrupt_for_test("after-ownerless-validation-proof-seal")
        if active == target:
            _rename_slot_path(config, target, fenced)
            _fsync_directory(target.parent)
            _interrupt_for_test("after-ownerless-validate-path-fence-before-journal")
            if authorization.target_kind == "checkout":
                assert repository is not None
                _GitVcs().repair_worktree(repository, fenced)
            journal["phase"] = "fenced"
            _write_journal(config, journal)
            _interrupt_for_test("after-ownerless-validate-path-fence")
        try:
            authorization, target, fenced, active, repository = (
                _ownerless_validation_inputs(
                    config,
                    journal,
                    recheck=True,
                    batch_cleanup=batch_cleanup,
                    fresh_same_uid=(authorization.target_kind == "checkout"),
                    live_use_recheck=selected_live_use_recheck,
                )
            )
        except Refusal as exc:
            try:
                _rollback_validation_fence(
                    config, target, fenced, authorization, repository, journal
                )
            except Refusal as rollback:
                raise Refusal(f"{exc}; fence rollback failed: {rollback}") from rollback
            raise
        if active != fenced:
            raise StateError("validation cleanup did not establish its path fence")
        if (
            authorization.removal_proof is not None
            and authorization.target_kind != "checkout"
        ):
            assert authorization.head is not None
            _recheck_validation_removal_proof(
                config,
                authorization.removal_proof,
                expected_slot=target.name,
                expected_generation=None,
                canonical_slot=target,
                active_slot=fenced,
                canonical_checkout=target,
                expected_head=authorization.head,
                target_kind=authorization.target_kind,
                repository=repository,
            )
            _interrupt_for_test("after-ownerless-validation-proof-recheck")
        journal["phase"] = "removing"
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-validate-removing")
        if authorization.target_kind == "checkout":
            assert repository is not None
            _GitVcs().remove_worktree(repository, fenced, force=True)
        else:
            assert authorization.parent_identity is not None
            exclusion: _OwnerlessValidationExclusion | None = None
            destructive_started = False
            try:
                exclusion = _begin_ownerless_validation_exclusion(
                    config, target, fenced, authorization, journal
                )
                _assert_excluded_validation_unused(
                    exclusion, target, fenced, batch_cleanup
                )
                _recheck_excluded_validation_proof(
                    config,
                    authorization,
                    target,
                    repository,
                    exclusion.payload_fd,
                )
                _interrupt_for_test("after-ownerless-validate-final-check")
                _assert_excluded_validation_tree_bound(
                    exclusion, target, fenced, authorization
                )
                _assert_current_process_only_holds_excluded_payload(
                    exclusion, target, fenced
                )
                destructive_started = True
                _remove_excluded_validation_tree(
                    config, exclusion, target, fenced, authorization
                )
            except (Refusal, StateError) as exc:
                if exclusion is not None:
                    exclusion.close()
                    exclusion = None
                if not destructive_started:
                    try:
                        _restore_ownerless_validation_exclusion(config, journal)
                        _rollback_validation_fence(
                            config,
                            target,
                            fenced,
                            authorization,
                            repository,
                            journal,
                        )
                    except (Refusal, StateError) as rollback:
                        raise Refusal(
                            f"{exc}; exclusion rollback failed: {rollback}"
                        ) from rollback
                raise
            finally:
                if exclusion is not None:
                    exclusion.close()
            journal.pop("exclusion", None)
        journal["phase"] = "removed"
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-validate-remove")
    if initial_phase != "removed" and (
        target.exists() or target.is_symlink() or fenced.exists() or fenced.is_symlink()
    ):
        raise Refusal("validation path still exists after removal")
    if authorization.target_kind == "checkout" and initial_phase != "removed":
        assert repository is not None
        if target.absolute() in _GitVcs().listed_worktrees(repository) or fenced.absolute() in _GitVcs().listed_worktrees(repository):
            raise Refusal("Git still registers the removed validation checkout")
    authorization_payload = _validation_authorization_to_obj(authorization)
    recovery_identity = hashlib.sha256(
        json.dumps(
            {"slot": raw["slot"], "authorization": authorization_payload},
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    ).hexdigest()
    matching_events = 0
    for event in _load_events(config, config.machine):
        if event.get("kind") != "ownerless-validate-path-removed":
            continue
        payload = _as_mapping(
            event.get("payload"), "ownerless validation removal event payload"
        )
        event_identity = payload.get("recovery_id")
        same_authorization = (
            payload.get("slot") == raw["slot"]
            and payload.get("authorization") == authorization_payload
        )
        if event_identity == recovery_identity or same_authorization:
            if event_identity not in {None, recovery_identity} or not same_authorization:
                raise StateError(
                    "ownerless validation removal event identity conflicts with its "
                    "authorization"
                )
            matching_events += 1
    if matching_events > 1:
        raise StateError("duplicate ownerless validation removal events already exist")
    if matching_events == 0:
        _write_event_file(
            config,
            config.machine,
            "ownerless-validate-path-removed",
            {
                "slot": raw["slot"],
                "recovery_id": recovery_identity,
                "authorization": authorization_payload,
                "recovery_actor": _identity_to_obj(coordinator),
            },
        )
    _interrupt_for_test("after-ownerless-validate-removal-event")
    _clear_journal(config, journal)
    if emit:
        print(f"recovered ownerless validation {authorization.target_kind}={target}")


def _ownerless_agent_authorization_to_obj(
    value: OwnerlessAgentAuthorization,
) -> dict[str, object]:
    return {
        **dataclasses.asdict(value),
        "identity": list(value.identity),
        "actor": _identity_to_obj(value.actor),
    }


def _ownerless_agent_authorization_from_obj(
    value: object,
) -> OwnerlessAgentAuthorization:
    raw = _as_mapping(value, "ownerless agent authorization")
    _exact_keys(
        raw,
        _OWNERLESS_AGENT_AUTHORIZATION_REQUIRED,
        set(),
        "ownerless agent authorization",
    )
    identity = tuple(
        _as_int(item, "ownerless agent directory identity")
        for item in _as_list(raw["identity"], "ownerless agent directory identity")
    )
    if len(identity) != 3:
        raise StateError("ownerless agent directory identity must have three fields")
    actor = _identity_from_obj(raw["actor"], "ownerless agent recovery actor")
    if actor is None:
        raise StateError("ownerless agent recovery has no actor")
    head = _as_str(raw["head"], "ownerless agent HEAD")
    digest = _as_str(raw["remote_url_sha256"], "ownerless agent remote digest")
    if not SHA_RE.fullmatch(head) or not DIGEST_RE.fullmatch(digest):
        raise StateError("ownerless agent Git identity is invalid")
    handoff_raw = raw["handoff_sha256"]
    handoff_digest = (
        None
        if handoff_raw is None
        else _as_str(handoff_raw, "ownerless agent HANDOFF.md digest")
    )
    if handoff_digest is not None and not DIGEST_RE.fullmatch(handoff_digest):
        raise StateError("ownerless agent HANDOFF.md digest is invalid")
    recorded_at = _as_str(raw["recorded_at"], "ownerless agent recorded_at")
    _parse_timestamp(recorded_at, "ownerless agent recorded_at")
    return OwnerlessAgentAuthorization(
        path=_as_str(raw["path"], "ownerless agent path"),
        identity=identity,
        actor=actor,
        repository=_as_str(raw["repository"], "ownerless agent repository"),
        head=head,
        branch=_validate_ref(_as_str(raw["branch"], "ownerless agent branch"), "branch"),
        remote=_validate_remote(_as_str(raw["remote"], "ownerless agent remote")),
        remote_url_sha256=digest,
        handoff_sha256=handoff_digest,
        recorded_at=recorded_at,
    )


def _ownerless_agent_journal_authorization_from_obj(
    value: object,
) -> OwnerlessAgentAuthorization:
    """Read current authorization or the exact schema-2 shape predating handoffs."""

    raw = _as_mapping(value, "ownerless agent authorization")
    if set(raw) == _OWNERLESS_AGENT_AUTHORIZATION_PRE_HANDOFF_REQUIRED:
        raw = {**raw, "handoff_sha256": None}
    return _ownerless_agent_authorization_from_obj(raw)


def _ownerless_agent_target(config: Config, raw: str) -> tuple[str, Path]:
    relative, target = _relative_inside(config.root, raw, "ownerless agent worktree")
    root = _slot_roots(config)["agent"]
    if target.parent != root or target.name == "ignored":
        raise Refusal(
            f"ownerless agent worktree must be one direct child of {root}, excluding ignored"
        )
    _validate_name(target.name, "ownerless agent worktree name")
    return relative, target


def _assert_unregistered_path_systemd_unrelated(path: Path) -> None:
    for unit in _user_systemd_snapshot():
        active = unit["ActiveState"] not in {"inactive", "failed"}
        queued = unit["PendingJob"] == "yes"
        if (active or queued) and str(path) in "\n".join(unit.values()):
            raise Refusal(
                f"user-systemd unit {unit['Id']} names ownerless worktree path {path}"
            )


def _ownerless_agent_checkout(
    config: Config,
    authorization: OwnerlessAgentAuthorization,
    path: Path,
    repository: Path,
) -> Checkout:
    return Checkout(
        name="worktree",
        path=path.relative_to(config.root).as_posix(),
        repository=authorization.repository,
        branch=authorization.branch,
        start_point=authorization.head,
        remote=authorization.remote,
        remote_url_sha256=authorization.remote_url_sha256,
        landed_ref=_landed_ref_for_remote(config, authorization.remote),
        head=authorization.head,
    )


def _ownerless_agent_facts(
    config: Config,
    authorization: OwnerlessAgentAuthorization,
    path: Path,
    repository: Path,
    *,
    expected_identity: bool,
) -> Checkout:
    if path.is_symlink() or not path.is_dir():
        raise Refusal(f"ownerless agent worktree is absent or unsafe: {path}")
    _ensure_no_mount_components(path.parent, path, "ownerless agent worktree")
    _assert_no_mountinfo_crossing(path, path, "ownerless agent worktree")
    if expected_identity and _open_directory_identity(path, "ownerless agent worktree") != authorization.identity:
        raise Refusal("ownerless agent worktree identity changed")
    handoff = path / "HANDOFF.md"
    if handoff.is_symlink():
        raise Refusal(f"ownerless agent HANDOFF.md must not be a symlink: {handoff}")
    observed_handoff = (
        hashlib.sha256(
            _read_bounded_regular_file(
                handoff, "ownerless agent HANDOFF.md", 1024 * 1024
            )
        ).hexdigest()
        if handoff.exists()
        else None
    )
    if observed_handoff != authorization.handoff_sha256:
        if authorization.handoff_sha256 is None:
            raise Refusal(
                "ownerless agent worktree contains unread HANDOFF.md; read it and "
                f"rerun with --handoff-sha256 {observed_handoff}"
            )
        raise Refusal(
            "ownerless agent HANDOFF.md changed after it was read; preserve the worktree"
        )
    vcs = _GitVcs()
    head = vcs.verify_existing_worktree(repository, path)
    branch = vcs.branch(path)
    if head != authorization.head or branch != authorization.branch:
        raise Refusal("ownerless agent worktree HEAD or branch changed")
    vcs.assert_ordinary_history(path)
    vcs.assert_ordinary_index(path)
    if vcs.remote_url_sha256(path, authorization.remote) != authorization.remote_url_sha256:
        raise Refusal("ownerless agent worktree remote changed")
    checkout = _ownerless_agent_checkout(config, authorization, path, repository)
    # Salvage never stages a handoff, and only the bound root HANDOFF.md is
    # preserved beside the registry, so every other one must be moved first.
    unprotected: list[str] = []
    repositories = [(checkout.name, path)]
    repositories.extend(
        (f"{checkout.name}/{submodule}", path / submodule)
        for submodule in vcs.initialized_submodules(path)
    )
    for checkout_name, nested in repositories:
        for relative in vcs.uncommitted_handoff_paths(
            nested, _cache_globs_for(config, checkout_name)
        ):
            candidate = (nested / relative).absolute()
            if candidate != handoff.absolute() and (
                candidate.exists() or candidate.is_symlink()
            ):
                unprotected.append(candidate.relative_to(path.absolute()).as_posix())
    if unprotected:
        raise Refusal(
            "ownerless agent worktree contains uncommitted handoff path(s): "
            f"{', '.join(sorted(unprotected))}; salvage never publishes handoffs, so "
            "preserve each one outside the worktree before retrying"
        )
    _assert_slot_unused(path)
    _assert_unregistered_path_systemd_unrelated(path)
    return checkout


def _ownerless_handoff_copy_path(
    config: Config, authorization: OwnerlessAgentAuthorization
) -> Path | None:
    if authorization.handoff_sha256 is None:
        return None
    key = hashlib.sha256(
        f"{config.machine}\0{authorization.path}\0{authorization.recorded_at}".encode(
            "utf-8"
        )
    ).hexdigest()[:16]
    return config.control / (
        f"HANDOFF-OWNERLESS-RETIRED.{key}.{authorization.handoff_sha256}.md"
    )


def _preserve_ownerless_handoff(
    config: Config, authorization: OwnerlessAgentAuthorization, active: Path
) -> Path | None:
    """Keep the read HANDOFF.md beside the registry; salvage never stages it."""

    copy = _ownerless_handoff_copy_path(config, authorization)
    if copy is None:
        return None
    if not copy.exists() and not copy.is_symlink():
        contents = _read_bounded_regular_file(
            active / "HANDOFF.md", "ownerless agent HANDOFF.md", HANDOFF_BYTES_LIMIT
        )
        if hashlib.sha256(contents).hexdigest() != authorization.handoff_sha256:
            raise Refusal(
                "ownerless agent HANDOFF.md changed after it was read; preserve the worktree"
            )
        _atomic_write_bytes(copy, contents)
    preserved = _read_bounded_regular_file(
        copy, "preserved ownerless HANDOFF.md", HANDOFF_BYTES_LIMIT
    )
    if hashlib.sha256(preserved).hexdigest() != authorization.handoff_sha256:
        raise StateError(
            f"preserved ownerless HANDOFF.md changed; preserve it for recovery: {copy}"
        )
    return copy


def _ownerless_agent_journal_inputs(
    config: Config, raw: Mapping[str, object]
) -> tuple[OwnerlessAgentAuthorization, Path, Path, Path | None, Path, tuple[Mapping[str, object], ...]]:
    _exact_keys(raw, _OWNERLESS_AGENT_JOURNAL_REQUIRED, set(), "ownerless agent journal")
    if (
        _as_int(raw["schema"], "ownerless agent journal.schema") != SCHEMA
        or raw["kind"] != "ownerless-agent-remove"
        or raw["machine"] != config.machine
    ):
        raise StateError("ownerless agent journal identity is invalid")
    authorization = _ownerless_agent_journal_authorization_from_obj(
        raw["authorization"]
    )
    _relative, target = _ownerless_agent_target(config, authorization.path)
    if raw["slot"] != target.name:
        raise StateError("ownerless agent journal slot differs from its path")
    _relative, fenced = _relative_inside(
        config.root, _as_str(raw["fenced"], "ownerless agent fenced path"), "fenced path"
    )
    prefix = f".{target.name}.ownerless-agent."
    if (
        fenced.parent != target.parent
        or not re.fullmatch(rf"{re.escape(prefix)}[0-9a-f]{{32}}", fenced.name)
    ):
        raise StateError("ownerless agent fenced path does not match its target")
    phase = _as_str(raw["phase"], "ownerless agent journal.phase")
    if phase not in {"prepared", "preserved", "fenced", "removed"}:
        raise StateError(f"unknown ownerless agent phase {phase!r}")
    target_present = target.exists() or target.is_symlink()
    fenced_present = fenced.exists() or fenced.is_symlink()
    if target_present and fenced_present:
        raise Refusal("canonical and fenced ownerless agent paths both exist")
    active = target if target_present else fenced if fenced_present else None
    if phase == "removed" and active is not None:
        raise Refusal("ownerless agent worktree reappeared after removal was recorded")
    if active is not None and (
        active.is_symlink()
        or not active.is_dir()
        or _open_directory_identity(active, "ownerless agent worktree") != authorization.identity
    ):
        raise Refusal("ownerless agent worktree identity changed; preserve it")
    _stored, repository = _repository_path(
        config, authorization.repository, allow_managed=True
    )
    if repository == target or _path_is_within(repository, target):
        raise StateError("ownerless agent source repository is inside the removal target")
    salvage = tuple(
        _as_mapping(value, f"ownerless agent journal.salvage[{index}]")
        for index, value in enumerate(_as_list(raw["salvage"], "ownerless agent journal.salvage"))
    )
    return authorization, target, fenced, active, repository, salvage


def _assert_ownerless_agent_no_registry_collision(
    config: Config, target: Path, states: Sequence[ActiveState], archives: Sequence[ArchiveState]
) -> None:
    for state in states:
        for record in state.slots:
            if record.slot == target.name:
                raise Refusal(f"ownerless path name collides with active slot {record.slot}")
            for checkout in record.checkouts:
                recorded = _stored_path_reference(config, checkout.path, "recorded checkout path")
                if recorded == target or _path_is_within(recorded, target) or _path_is_within(target, recorded):
                    raise Refusal(f"ownerless path overlaps registered checkout {record.slot}/{checkout.name}")
    for archive in archives:
        for archive_record in archive.records:
            if archive_record.get("slot") == target.name:
                raise Refusal(f"ownerless path name collides with archived slot {target.name}")


def _assert_ownerless_salvage_still_matches(
    config: Config,
    authorization: OwnerlessAgentAuthorization,
    checkout: Checkout,
    receipts: Sequence[Mapping[str, object]],
    vcs: _GitVcs,
    path: Path,
) -> None:
    if vcs.remote_url_sha256(path, checkout.remote) != checkout.remote_url_sha256:
        raise Refusal("ownerless worktree remote changed after salvage; preserve it")
    candidates = [(checkout, path, False)]
    candidates.extend(
        (submodule, submodule_path, True)
        for submodule, submodule_path in _submodule_salvage_checkouts(
            config, checkout, vcs, path_override=path
        )
    )
    if len(candidates) != len(receipts):
        raise StateError("ownerless salvage receipts do not cover every checkout")
    slot = Path(authorization.path).name
    prepared = [
        (
            candidate,
            candidate_path,
            _salvage_candidate(
                config,
                None,
                candidate,
                vcs,
                path_override=candidate_path,
                allow_detached=detached,
                verify_repository_membership=not detached,
                ownerless_slot=slot,
                ownerless_recorded_at=authorization.recorded_at,
            ),
        )
        for candidate, candidate_path, detached in candidates
    ]
    for (candidate, candidate_path, facts), receipt in zip(prepared, receipts):
        if receipt.get("checkout") != candidate.name:
            raise StateError("ownerless salvage receipt order changed")
        if (facts.head, facts.status_digest, facts.commit) != (
            receipt.get("source_head"),
            receipt.get("status_sha256"),
            receipt.get("salvage_commit"),
        ):
            raise Refusal("ownerless worktree changed after salvage; preserve it")
        if receipt.get("disposition") == "salvaged":
            ref = _as_str(receipt.get("remote_ref"), "ownerless salvage ref")
            if (
                vcs.remote_ref_sha(
                    candidate_path,
                    candidate.remote,
                    ref,
                    facts.remote_authority,
                )
                != facts.commit
            ):
                raise Refusal(
                    f"remote salvage ref {ref} no longer preserves {facts.commit}"
                )
        elif receipt.get("disposition") == "already-published":
            if not vcs.remote_heads_containing(
                candidate_path,
                candidate.remote,
                facts.head,
                facts.remote_authority,
                network_authority=facts.network_authority,
            ):
                raise Refusal(f"ownerless checkout {candidate.name} is no longer published")
        elif receipt.get("disposition") == "archived-local":
            _assert_local_salvage_receipt(
                config, config.machine, slot, None, candidate, facts, receipt, vcs
            )
        else:
            raise StateError("ownerless salvage receipt has unknown disposition")


def _recover_ownerless_agent(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
) -> None:
    if path != _journal_path(config):
        raise StateError("ownerless agent journal filename is invalid")
    _assert_caller_process(coordinator, "coordinator")
    authorization, target, fenced, active, repository, salvage = (
        _ownerless_agent_journal_inputs(config, raw)
    )
    if authorization.actor.host_id != _host_id():
        raise Refusal("ownerless agent journal belongs to another host identity")
    journal = dict(raw)
    vcs = _GitVcs()
    if active is not None:
        if active == fenced:
            vcs.repair_worktree(repository, fenced)
            _repair_nested_repositories(fenced, vcs)
        checkout = _ownerless_agent_facts(
            config, authorization, active, repository, expected_identity=True
        )
        _preserve_ownerless_handoff(config, authorization, active)
        if not salvage:
            salvage = _salvage_ownerless_worktree(
                config, authorization, checkout, vcs, path_override=active
            )
            journal["salvage"] = [dict(value) for value in salvage]
            journal["phase"] = "preserved"
            _write_journal(config, journal)
            _interrupt_for_test("after-ownerless-agent-salvage")
        _assert_ownerless_salvage_still_matches(
            config, authorization, checkout, salvage, vcs, active
        )
        if active == target:
            _rename_slot_path(config, target, fenced)
            _fsync_directory(target.parent)
            if _open_directory_identity(fenced, "fenced ownerless agent worktree") != authorization.identity:
                _rename_slot_path(config, fenced, target)
                _fsync_directory(target.parent)
                raise Refusal("ownerless agent worktree identity changed during fencing")
            _interrupt_for_test("after-ownerless-agent-fence-before-journal")
            vcs.repair_worktree(repository, fenced)
            _repair_nested_repositories(fenced, vcs)
            journal["phase"] = "fenced"
            _write_journal(config, journal)
            _interrupt_for_test("after-ownerless-agent-fence")
            active = fenced
            checkout = dataclasses.replace(
                checkout, path=fenced.relative_to(config.root).as_posix()
            )
        _ownerless_agent_facts(
            config, authorization, active, repository, expected_identity=True
        )
        _assert_unregistered_path_systemd_unrelated(target)
        _assert_unregistered_path_systemd_unrelated(fenced)
        _assert_ownerless_salvage_still_matches(
            config, authorization, checkout, salvage, vcs, active
        )
        _preserve_ownerless_handoff(config, authorization, active)
        vcs.remove_worktree(repository, active, force=True)
        journal["phase"] = "removed"
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-agent-remove")
    if target.exists() or target.is_symlink() or fenced.exists() or fenced.is_symlink():
        raise Refusal("ownerless agent worktree still exists after removal")
    if target.absolute() in vcs.listed_worktrees(repository) or fenced.absolute() in vcs.listed_worktrees(repository):
        raise Refusal("Git still registers the removed ownerless agent worktree")
    preserved_handoff = _ownerless_handoff_copy_path(config, authorization)
    _write_event_file(
        config,
        config.machine,
        "ownerless-agent-worktree-removed",
        {
            "slot": raw["slot"],
            "authorization": _ownerless_agent_authorization_to_obj(authorization),
            "salvage": [dict(value) for value in salvage],
            "handoff_preserved": (
                None if preserved_handoff is None else str(preserved_handoff)
            ),
            "recovery_actor": _identity_to_obj(coordinator),
        },
    )
    _clear_journal(config, journal)
    print(f"recovered ownerless agent worktree={target}")


def _cmd_recover_ownerless_agent_worktree(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    if config.machine != _short_hostname():
        raise Refusal("ownerless agent recovery must run on the worktree's machine")
    if args.apply:
        _require_coordinator_authorized(args, "ownerless agent worktree recovery")
        if args.coordinator_pid is None:
            raise Refusal("--apply requires --coordinator-pid")
        coordinator = _capture_caller_process(args.coordinator_pid, "coordinator")
    else:
        coordinator = _read_process_identity(os.getpid())
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        journals = _outstanding_journals(config)
        if journals:
            path, raw = _load_journal(config)
            if raw.get("kind") != "ownerless-agent-remove":
                raise Refusal(f"another interrupted mutation is recorded in {path}")
            authorization, target, _fenced, _active, _repository, _salvage = (
                _ownerless_agent_journal_inputs(config, raw)
            )
            if authorization.path != _ownerless_agent_target(config, args.path)[0]:
                raise Refusal("requested ownerless path differs from the interrupted recovery")
            if not args.apply:
                print(f"WORKTREE path={target} outcome=planned detail=resume")
                return 0
            _recover_ownerless_agent(config, path, raw, coordinator)
            return 0
        states, archives = _validate_global_state(config)
        relative, target = _ownerless_agent_target(config, args.path)
        _assert_ownerless_agent_no_registry_collision(config, target, states, archives)
        repository_relative, repository = _repository_path(
            config, args.repository, allow_managed=True
        )
        if repository == target or _path_is_within(repository, target):
            raise Refusal("ownerless agent source repository is inside the removal target")
        head = _as_str(args.head, "ownerless agent HEAD")
        digest = _as_str(args.remote_url_sha256, "ownerless agent remote digest")
        if not SHA_RE.fullmatch(head) or not DIGEST_RE.fullmatch(digest):
            raise Refusal("--head and --remote-url-sha256 must be full lowercase digests")
        handoff_digest = args.handoff_sha256
        if handoff_digest is not None and not DIGEST_RE.fullmatch(handoff_digest):
            raise Refusal("--handoff-sha256 must be one lowercase SHA-256 digest")
        authorization = OwnerlessAgentAuthorization(
            path=relative,
            identity=_open_directory_identity(target, "ownerless agent worktree"),
            actor=coordinator,
            repository=repository_relative,
            head=head,
            branch=_validate_ref(args.branch, "branch"),
            remote=_validate_remote(args.remote),
            remote_url_sha256=digest,
            handoff_sha256=handoff_digest,
            recorded_at=_utc_now(),
        )
        _ownerless_agent_facts(
            config, authorization, target, repository, expected_identity=True
        )
        if not args.apply:
            print(f"WORKTREE path={target} outcome=planned detail=ownerless-agent")
            return 0
        journal = {
            "schema": SCHEMA,
            "kind": "ownerless-agent-remove",
            "machine": config.machine,
            "slot": target.name,
            "phase": "prepared",
            "fenced": (
                target.with_name(f".{target.name}.ownerless-agent.{uuid.uuid4().hex}")
                .relative_to(config.root)
                .as_posix()
            ),
            "authorization": _ownerless_agent_authorization_to_obj(authorization),
            "salvage": [],
        }
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-agent-journal")
        before = _global_rows(states, archives)
        _recover_ownerless_agent(config, _journal_path(config), journal, coordinator)
        after_states, after_archives = _validate_global_state(config)
        if _global_rows(after_states, after_archives) != before:
            raise StateError("ownerless agent recovery changed registered slot state")
    return 0


def _ownerless_agent_cache_paths(config: Config) -> tuple[Path, Path]:
    source = _slot_roots(config)["agent"] / "ignored"
    destination = config.root / "ignored" / "validate" / "cache" / "wrkslots-agent-ignored"
    return source, destination


def _assert_ownerless_agent_cache_tree(path: Path) -> tuple[int, int, int]:
    if path.is_symlink() or not path.is_dir():
        raise Refusal(f"ownerless agent cache path is absent or unsafe: {path}")
    _ensure_no_mount_components(path.parent, path, "ownerless agent cache path")
    _assert_no_mountinfo_crossing(path, path, "ownerless agent cache path")
    expected = path / "validate" / "cache" / "rust-script"
    if not expected.is_dir() or expected.is_symlink():
        raise Refusal(
            "ownerless agent cache must contain the exact validate/cache/rust-script tree"
        )
    def walk_error(error: OSError) -> None:
        raise Refusal(f"cannot enumerate ownerless agent cache: {error}")

    for root, directories, files in os.walk(
        path, topdown=True, onerror=walk_error, followlinks=False
    ):
        root_path = Path(root)
        for name in (*directories, *files):
            candidate = root_path / name
            if candidate.is_symlink():
                raise Refusal(f"ownerless agent cache contains a symlink: {candidate}")
            if name in {".git", "HANDOFF.md"}:
                raise Refusal(f"ownerless agent cache contains authored-work marker {candidate}")
            try:
                metadata = candidate.lstat()
            except OSError as exc:
                raise Refusal(f"cannot inspect ownerless agent cache entry {candidate}: {exc}") from exc
            if not (stat.S_ISDIR(metadata.st_mode) or stat.S_ISREG(metadata.st_mode)):
                raise Refusal(f"ownerless agent cache contains a special file: {candidate}")
        if root_path == path and (set(directories) != {"validate"} or files):
            raise Refusal("ownerless agent cache root contains an unexpected entry")
        if root_path == path / "validate" and (set(directories) != {"cache"} or files):
            raise Refusal("ownerless agent cache validate directory contains an unexpected entry")
        if root_path == path / "validate" / "cache" and (
            set(directories) != {"rust-script"} or files
        ):
            raise Refusal("ownerless agent cache cache directory contains an unexpected entry")
    _assert_slot_unused(path)
    _assert_unregistered_path_systemd_unrelated(path)
    return _open_directory_identity(path, "ownerless agent cache path")


def _ownerless_agent_cache_journal_inputs(
    config: Config, raw: Mapping[str, object]
) -> tuple[Path, Path, Path, Path | None, tuple[int, int, int]]:
    _exact_keys(
        raw,
        _OWNERLESS_AGENT_CACHE_JOURNAL_REQUIRED,
        set(),
        "ownerless agent cache journal",
    )
    if (
        _as_int(raw["schema"], "ownerless agent cache journal.schema") != SCHEMA
        or raw["kind"] != "ownerless-agent-cache-relocate"
        or raw["machine"] != config.machine
        or raw["slot"] != "ignored"
    ):
        raise StateError("ownerless agent cache journal identity is invalid")
    if _as_str(raw["host_id"], "ownerless agent cache host_id") != _host_id():
        raise Refusal("ownerless agent cache journal belongs to another host identity")
    expected_source, expected_destination = _ownerless_agent_cache_paths(config)
    _relative, source = _relative_inside(
        config.root, _as_str(raw["source"], "ownerless agent cache source"), "cache source"
    )
    _relative, destination = _relative_inside(
        config.root,
        _as_str(raw["destination"], "ownerless agent cache destination"),
        "cache destination",
    )
    _relative, fenced = _relative_inside(
        config.root, _as_str(raw["fenced"], "ownerless agent cache fence"), "cache fence"
    )
    if source != expected_source or destination != expected_destination:
        raise StateError("ownerless agent cache journal names a non-canonical path")
    prefix = ".ignored.ownerless-agent-cache."
    if fenced.parent != source.parent or not re.fullmatch(
        rf"{re.escape(prefix)}[0-9a-f]{{32}}", fenced.name
    ):
        raise StateError("ownerless agent cache fence is invalid")
    identity = tuple(
        _as_int(value, "ownerless agent cache identity")
        for value in _as_list(raw["identity"], "ownerless agent cache identity")
    )
    if len(identity) != 3:
        raise StateError("ownerless agent cache identity must have three fields")
    if _identity_from_obj(raw["actor"], "ownerless agent cache actor") is None:
        raise StateError("ownerless agent cache journal has no actor")
    phase = _as_str(raw["phase"], "ownerless agent cache phase")
    if phase not in {"prepared", "fenced", "relocated"}:
        raise StateError(f"unknown ownerless agent cache phase {phase!r}")
    present = [
        candidate
        for candidate in (source, fenced, destination)
        if candidate.exists() or candidate.is_symlink()
    ]
    if len(present) > 1:
        raise Refusal("more than one ownerless agent cache path exists; preserve all")
    active = present[0] if present else None
    if active is not None and (
        active.is_symlink()
        or not active.is_dir()
        or _open_directory_identity(active, "ownerless agent cache") != identity
    ):
        raise Refusal("ownerless agent cache identity changed; preserve it")
    if phase != "relocated" and active == destination:
        phase = "relocated"
    if phase == "relocated" and active != destination:
        raise Refusal("relocated ownerless agent cache is missing from its destination")
    return source, destination, fenced, active, identity


def _recover_ownerless_agent_cache(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
) -> None:
    if path != _journal_path(config):
        raise StateError("ownerless agent cache journal filename is invalid")
    _assert_caller_process(coordinator, "coordinator")
    source, destination, fenced, active, _identity = (
        _ownerless_agent_cache_journal_inputs(config, raw)
    )
    journal = dict(raw)
    if active in {source, fenced}:
        assert active is not None
        _assert_ownerless_agent_cache_tree(active)
        for candidate in (source, fenced, destination):
            _assert_unregistered_path_systemd_unrelated(candidate)
        if active == source:
            _rename_slot_path(config, source, fenced)
            _fsync_directory(source.parent)
            if _open_directory_identity(fenced, "fenced ownerless agent cache") != _identity:
                _rename_slot_path(config, fenced, source)
                _fsync_directory(source.parent)
                raise Refusal("ownerless agent cache identity changed during fencing")
            journal["phase"] = "fenced"
            _write_journal(config, journal)
            _interrupt_for_test("after-ownerless-agent-cache-fence")
        destination.parent.mkdir(parents=True, exist_ok=True)
        _ensure_no_symlink_components(
            config.root, destination.parent, "ownerless agent cache destination"
        )
        _fsync_directory(destination.parent)
        if destination.exists() or destination.is_symlink():
            raise Refusal(f"ownerless agent cache destination already exists: {destination}")
        try:
            _rename_slot_path(config, fenced, destination)
        except OSError as exc:
            if not source.exists() and fenced.is_dir() and not destination.exists():
                _rename_slot_path(config, fenced, source)
                _fsync_directory(source.parent)
            raise Refusal(f"cannot relocate exact ownerless agent cache tree: {exc}") from exc
        _fsync_directory(destination.parent)
        journal["phase"] = "relocated"
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-agent-cache-relocate")
    source, destination, fenced, active, _identity = (
        _ownerless_agent_cache_journal_inputs(config, journal)
    )
    if active != destination:
        raise StateError("ownerless agent cache relocation did not reach its destination")
    _assert_ownerless_agent_cache_tree(destination)
    _write_event_file(
        config,
        config.machine,
        "ownerless-agent-cache-relocated",
        {
            "slot": "ignored",
            "source": source.relative_to(config.root).as_posix(),
            "destination": destination.relative_to(config.root).as_posix(),
            "identity": list(_identity),
            "recovery_actor": _identity_to_obj(coordinator),
        },
    )
    _clear_journal(config, journal)
    print(f"relocated ownerless agent cache={source} destination={destination}")


def _cmd_recover_ownerless_agent_cache(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    if config.machine != _short_hostname():
        raise Refusal("ownerless agent cache recovery must run on the cache's machine")
    if args.apply:
        _require_coordinator_authorized(args, "ownerless agent cache recovery")
        if args.coordinator_pid is None:
            raise Refusal("--apply requires --coordinator-pid")
        coordinator = _capture_caller_process(args.coordinator_pid, "coordinator")
    else:
        coordinator = _read_process_identity(os.getpid())
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config)
        journals = _outstanding_journals(config)
        if journals:
            path, raw = _load_journal(config)
            if raw.get("kind") != "ownerless-agent-cache-relocate":
                raise Refusal(f"another interrupted mutation is recorded in {path}")
            if not args.apply:
                print("CACHE slot=ignored outcome=planned detail=resume")
                return 0
            _recover_ownerless_agent_cache(config, path, raw, coordinator)
            return 0
        states, archives = _validate_global_state(config)
        source, destination = _ownerless_agent_cache_paths(config)
        _assert_ownerless_agent_no_registry_collision(config, source, states, archives)
        if destination.exists() or destination.is_symlink():
            raise Refusal(f"ownerless agent cache destination already exists: {destination}")
        identity = _assert_ownerless_agent_cache_tree(source)
        if not args.apply:
            print(f"CACHE slot=ignored outcome=planned destination={destination}")
            return 0
        journal = {
            "schema": SCHEMA,
            "kind": "ownerless-agent-cache-relocate",
            "machine": config.machine,
            "host_id": _host_id(),
            "slot": "ignored",
            "phase": "prepared",
            "source": source.relative_to(config.root).as_posix(),
            "destination": destination.relative_to(config.root).as_posix(),
            "fenced": source.with_name(
                f".ignored.ownerless-agent-cache.{uuid.uuid4().hex}"
            ).relative_to(config.root).as_posix(),
            "identity": list(identity),
            "actor": _identity_to_obj(coordinator),
        }
        _write_journal(config, journal)
        _interrupt_for_test("after-ownerless-agent-cache-journal")
        before = _global_rows(states, archives)
        _recover_ownerless_agent_cache(config, _journal_path(config), journal, coordinator)
        after_states, after_archives = _validate_global_state(config)
        if _global_rows(after_states, after_archives) != before:
            raise StateError("ownerless agent cache recovery changed registered slot state")
    return 0


def _absent_agent_row_identity(raw: object, label: str) -> AbsentAgentRow:
    value = _as_mapping(raw, label)
    _exact_keys(
        value,
        {"machine", "slot", "generation", "record_sha256"},
        set(),
        label,
    )
    digest = _as_str(value["record_sha256"], f"{label}.record_sha256")
    if not DIGEST_RE.fullmatch(digest):
        raise Refusal(f"{label}.record_sha256 must be one lowercase SHA-256 digest")
    return AbsentAgentRow(
        machine=_validate_name(_as_str(value["machine"], f"{label}.machine"), "machine"),
        slot=_validate_name(_as_str(value["slot"], f"{label}.slot"), "slot"),
        generation=_as_int(value["generation"], f"{label}.generation", minimum=1),
        record_sha256=digest,
    )


def _validate_absent_agent_row(record: ActiveRecord, item: AbsentAgentRow) -> None:
    if record.slot_type != "agent":
        raise Refusal(f"slot {item.slot} is not an agent row")
    if record.machine != item.machine or record.generation != item.generation:
        raise Refusal(f"agent row {item.machine}/{item.slot} generation changed")
    observed = _record_sha256(record)
    if observed != item.record_sha256:
        raise Refusal(
            f"agent row {item.machine}/{item.slot} changed: expected "
            f"{item.record_sha256}, found {observed}"
        )


def _assert_absent_agent_storage(
    config: Config, record: ActiveRecord
) -> tuple[Path, ...]:
    _assert_record_paths(config, record)
    paths = _absent_validate_row_paths(config, record)
    for path in paths:
        if path.exists() or path.is_symlink():
            raise Refusal(f"agent row {record.slot} still has physical storage at {path}")
    root = _slot_roots(config)["agent"]
    try:
        siblings = tuple(root.iterdir()) if root.is_dir() else ()
    except OSError as exc:
        raise Refusal(f"cannot enumerate possible fenced agent paths: {exc}") from exc
    prefixes = (
        f".{record.slot}.fenced.{record.generation}.",
        f".{record.slot}.ownerless-agent.",
    )
    for sibling in siblings:
        if any(sibling.name.startswith(prefix) for prefix in prefixes):
            raise Refusal(f"agent row {record.slot} has a possible fenced path: {sibling}")
    return paths


# The kernel's fixed inode number for the initial PID namespace
# (PROC_PID_INIT_INO). Only a caller in that namespace sees every process on the
# machine, so only there does a missing /proc/<pid> prove that a process
# generation exited rather than that it runs outside the caller's view.
_INITIAL_PID_NAMESPACE_LINK = "pid:[4026531836]"


def _in_initial_pid_namespace() -> bool:
    try:
        return os.readlink("/proc/self/ns/pid") == _INITIAL_PID_NAMESPACE_LINK
    except OSError:
        return False


def _assert_absent_agent_registered_liveness(config: Config, record: ActiveRecord) -> None:
    """Refuse unless the liveness authority or the exact owner generation settles it.

    The registered liveness authority answers about an agent NAME. It may
    report "alive" because some other live process carries that name: a
    restarted session of the same agent, or a leaked helper process that
    inherited the name from a session that has since exited.

    ⚠️ FOR A ROW WHOSE STORAGE IS ALREADY ABSENT, THAT ANSWER IS NOT ABOUT THE
    ROW. There is no checkout left to protect; every owner operation on the row
    binds the exact recorded generation, so a later process with the same name
    cannot act through it; and this command pushes every recorded HEAD to a
    rescue ref and reads it back before changing anything. Requiring "dead"
    from the authority anyway made the row unrecoverable for as long as
    anything carried the name, while the one-slot-per-agent rule refused every
    new slot for that agent because of the very same row -- a deadlock.
    Measured: a row whose owner generation had exited 283,000 seconds earlier
    (a 3,600-second time-to-live) was held by two leaked helper processes that
    still carried the agent's name.

    Absent validation rows already decline to treat agent-name liveness as an
    ownership authority. This keeps the authority in force and overrides only
    its "alive" verdict, and only when the exact recorded owner generation (PID,
    start ticks and boot) is proven dead from the initial PID namespace. An
    "unverifiable" verdict, a live or indeterminate generation, a row with no
    usable owner, or a restricted process view still refuses. The process,
    cgroup, mount and user-service census that follows is unchanged.
    """

    state, detail = _registered_liveness_state(config, record)
    if state == "dead":
        return
    owner = record.owner
    if state == "alive" and owner is not None and not _owner_record_is_absent(record):
        owner_state, owner_detail = _process_state(owner)
        if owner_state == "dead" and _in_initial_pid_namespace():
            print(
                f"NOTE: registered liveness authority reports agent {record.agent} alive "
                f"({detail}), but the exact recorded owner generation of agent row "
                f"{record.slot} (PID {owner.pid}, start ticks {owner.start_ticks}, boot "
                f"{owner.boot_id}) is dead ({owner_detail}) and its storage is absent, so "
                "a live process carrying the same agent name cannot be using this row; "
                "continuing with the process, cgroup, mount and user-service census",
                file=sys.stderr,
            )
            return
    _refuse_registered_liveness(state, detail)


def _assert_absent_agent_liveness(
    config: Config, record: ActiveRecord, paths: Sequence[Path]
) -> None:
    _assert_absent_validate_row_is_local(record)
    _assert_absent_agent_registered_liveness(config, record)
    if record.owner is not None:
        owner_state, detail = _process_state(record.owner)
        if owner_state != "dead":
            raise Refusal(
                f"recorded owner for agent row {record.slot} is {owner_state}: {detail}"
            )
    rows = ((record, tuple(paths)),)
    # A validation run may use an agent checkout too, so retained run handles
    # naming its paths are judged as for a validation row.
    evidence = _run_evidence(
        config,
        rows,
        lambda: _host_evidence_around(
            lambda: _assert_absent_validate_processes_unrelated(rows)
        ),
    )
    # The refusal directly above already required a proven-dead owner, so this
    # comparison could only ever have fired on a process that is not the owner.
    if _owner_cgroup_is_evidence(record) and record.owner is not None:
        for process in evidence.processes:
            if _cgroup_matches(record.owner.cgroup_path, process.cgroup_path):
                raise Refusal(
                    f"live process {process.pid} remains in recorded owner cgroup "
                    f"{record.owner.cgroup_path} for agent row {record.slot}"
                )
    _judge_run_evidence(rows, evidence)


def _absent_agent_rescue_ref(
    record: ActiveRecord, checkout: Checkout, *, root: str | None = None
) -> str:
    name = checkout.name.replace("/", "-")
    ref = (
        f"{root or ABSENT_AGENT_RESCUE_REF_ROOT}/{record.machine}/{record.slot}/"
        f"{name}-{record.generation}-{checkout.head[:12]}"
    )
    _validate_full_ref(ref, "agent-row rescue ref")
    return ref


def _absent_agent_branch_witness_to_obj(
    witness: _AbsentAgentBranchWitness,
) -> dict[str, object]:
    return {
        "checkout": witness.checkout,
        "branch_ref": witness.branch_ref,
        "state": witness.state,
        "head": witness.head,
    }


def _absent_agent_branch_witness_from_obj(
    value: object, label: str
) -> _AbsentAgentBranchWitness:
    raw = _as_mapping(value, label)
    _exact_keys(raw, {"checkout", "branch_ref", "state", "head"}, set(), label)
    checkout = _as_str(raw["checkout"], f"{label}.checkout")
    if not checkout:
        raise StateError(f"{label}.checkout must not be empty")
    try:
        branch_ref = _validate_full_ref(
            _as_str(raw["branch_ref"], f"{label}.branch_ref"),
            f"{label}.branch_ref",
        )
    except Refusal as exc:
        raise StateError(f"{label}.branch_ref is invalid") from exc
    if not branch_ref.startswith("refs/heads/"):
        raise StateError(f"{label}.branch_ref must name refs/heads")
    state = _as_str(raw["state"], f"{label}.state")
    head_raw = raw["head"]
    if state == "absent":
        if head_raw is not None:
            raise StateError(f"{label}.head must be null when the branch is absent")
        head = None
    elif state == "present":
        head = _as_str(head_raw, f"{label}.head")
        if SHA_RE.fullmatch(head) is None:
            raise StateError(f"{label}.head must be one full object SHA")
    else:
        raise StateError(f"{label}.state must be 'absent' or 'present'")
    return _AbsentAgentBranchWitness(checkout, branch_ref, state, head)


def _absent_agent_branch_witnesses(
    config: Config, record: ActiveRecord, vcs: _GitVcs
) -> tuple[_AbsentAgentBranchWitness, ...]:
    witnesses: list[_AbsentAgentBranchWitness] = []
    for checkout in record.checkouts:
        _stored, repository = _stored_repository_path(config, checkout.repository)
        branch_ref = f"refs/heads/{checkout.branch}"
        head = vcs.local_branch_head(repository, branch_ref)
        witnesses.append(
            _AbsentAgentBranchWitness(
                checkout=checkout.name,
                branch_ref=branch_ref,
                state="absent" if head is None else "present",
                head=head,
            )
        )
    return tuple(witnesses)


def _assert_absent_agent_branch_witness(
    repository: Path,
    checkout: Checkout,
    witness: _AbsentAgentBranchWitness,
    vcs: _GitVcs,
) -> None:
    expected_ref = f"refs/heads/{checkout.branch}"
    if witness.checkout != checkout.name or witness.branch_ref != expected_ref:
        raise StateError(
            f"branch witness does not match absent checkout {checkout.name}"
        )
    observed = vcs.local_branch_head(repository, witness.branch_ref)
    if observed == witness.head:
        return
    expected = witness.head or "absent"
    actual = observed or "absent"
    raise Refusal(
        f"local branch {witness.branch_ref!r} for absent checkout {checkout.name} "
        f"changed from witnessed state {expected} to {actual}; recovery refuses "
        "and preserves the ACTIVE row and journal for inspection"
    )


def _assert_absent_agent_registration(
    checkout: Checkout,
    witness: _AbsentAgentBranchWitness,
    registration: tuple[str, str | None],
) -> None:
    head, branch = registration
    expected_head = witness.head if witness.state == "present" else _NULL_GIT_SHA
    expected_branch = f"refs/heads/{checkout.branch}"
    if head != expected_head or branch != expected_branch:
        raise Refusal(
            f"Git registration changed for absent checkout {checkout.name}: expected "
            f"HEAD {expected_head} on {expected_branch}, found HEAD {head} on "
            f"{branch or 'detached'}"
        )


def _assert_absent_agent_rescue_refs_disjoint(
    record: ActiveRecord,
    branch_witnesses: Sequence[_AbsentAgentBranchWitness],
) -> None:
    local_branches = {witness.branch_ref for witness in branch_witnesses}
    rescue_refs = {
        _absent_agent_rescue_ref(record, checkout) for checkout in record.checkouts
    }
    collisions = sorted(rescue_refs & local_branches)
    if collisions:
        raise Refusal(
            "planned rescue destination collides with a recorded local branch ref: "
            + ", ".join(collisions)
            + "; refusing before any salvage push or ref mutation"
        )


def _absent_agent_containing_ref_rank(checkout: Checkout, ref: str) -> tuple[int, str]:
    """Order remote refs that contain a recorded HEAD by how durable they are.

    The remote branch behind the checkout's landed ref comes first, then rescue
    refs, which exist to preserve commits, then tags, which are rarely moved,
    then the checkout's own branch, then every other branch by name, then any
    other ref (such as a hosting service's refs/pull/*) by name.
    """

    tracking = f"refs/remotes/{checkout.remote}/"
    landed = (
        "refs/heads/" + checkout.landed_ref.removeprefix(tracking)
        if checkout.landed_ref.startswith(tracking)
        else None
    )
    if ref == landed:
        return (0, ref)
    if ref.startswith("refs/rescue/"):
        return (1, ref)
    if ref.startswith("refs/tags/"):
        return (2, ref)
    if ref == f"refs/heads/{checkout.branch}":
        return (3, ref)
    if ref.startswith("refs/heads/"):
        return (4, ref)
    return (5, ref)


def _absent_agent_existing_containing_ref(
    vcs: _GitVcs,
    repository: Path,
    checkout: Checkout,
    authority: _RemoteAuthority,
) -> tuple[str, str] | None:
    """Return one existing remote ref that contains the recorded HEAD, and its tip.

    Both the search and the confirming `git merge-base --is-ancestor` read the
    remote fresh into temporary repositories, so neither creates nor changes a
    ref in the source repository, including refs/remotes/<remote>/*. The
    confirmation also fetches the chosen ref's commits alone into an empty
    object store, so the remote, not the source repository, must supply the
    recorded HEAD's history.
    """

    containing = vcs.remote_refs_containing_commit(
        repository, checkout.remote, checkout.head, authority
    )
    if not containing:
        return None
    ref = min(
        containing, key=lambda value: _absent_agent_containing_ref_rank(checkout, value)
    )
    tip = vcs.remote_ref_contains_commit(
        repository, checkout.remote, ref, checkout.head, authority
    )
    if tip is None:
        raise Refusal(
            f"remote ref {_display_ref(ref)} stopped containing the recorded HEAD "
            f"{checkout.head} of "
            f"absent checkout {checkout.name} while recovery was planning. state: "
            "REFUSED -- the ACTIVE row and Git registrations were retained. remedy: "
            "rerun the plan"
        )
    return ref, tip


def _absent_agent_module_env(module: Path, work: Path) -> dict[str, str]:
    """Environment for a Git command in a submodule repository whose checkout is absent.

    Its core.worktree names a directory that no longer exists, so Git is
    given ``work``, an existing empty directory, as the work tree.
    GIT_NO_LAZY_FETCH keeps a promisor remote that repository configures
    from fetching anything.
    """

    return {"GIT_DIR": str(module), "GIT_WORK_TREE": str(work), "GIT_NO_LAZY_FETCH": "1"}


def _assert_absent_agent_modules_preserved(
    vcs: _GitVcs,
    repository: Path,
    path: Path,
    checkout: Checkout,
    retained: str,
    salvaged: Mapping[str, AbstractSet[str]] | None,
    *,
    record: ActiveRecord,
    set_aside: bool = False,
) -> tuple[_WorktreeModule, ...]:
    """Refuse while a submodule repository Git kept for an absent checkout holds unsaved work.

    Removing the registration would delete every submodule repository under
    the administrative directory, and recovery keeps them only where no Git
    command finds them (see _GitVcs.worktree_modules). Content staged
    there, a resolve-undo entry, an unfinished operation, or anything else
    _WorktreeModule.blocking names refuses, because recovery salvages only
    commits. ``salvaged`` is None before salvage; afterwards it maps each
    submodule name to the commits salvage preserved, and a commit outside
    every remote-tracking ref that salvage did not preserve refuses. With
    ``set_aside`` it examines them where recovery moved them aside.

    Removing the registration deletes the administrative directory, so a
    mount point in it refuses, whether or not it holds submodule
    repositories (_refuse_mounts_below_administration). And recovery moves
    the repositories to where it keeps them for ``record``
    (_worktree_modules_retained) before Git deletes that directory, so an
    object store they borrow from that the move or the deletion would take
    from them refuses (_refuse_unretainable_module_storage).
    """

    administration = vcs.worktree_administrative_directory(repository, path)
    if administration is None:
        raise Refusal(
            f"Git registers {path} but no administrative directory names it. "
            f"state: REFUSED -- {retained} were retained"
        )
    _refuse_mounts_below_administration(administration)
    # Storage first: the census reads every object the repositories borrow,
    # and an alternates entry leading into proc or into the administrative
    # directory should refuse saying so, not as whatever Git reports while
    # reading through it.
    directories = _worktree_module_directories(administration, set_aside=set_aside)
    if directories:
        _refuse_unretainable_module_storage(
            administration,
            administration / (_WORKTREE_MODULES_ASIDE if set_aside else "modules"),
            _worktree_modules_retained(administration, record),
            [module for _name, module in directories],
        )
    modules = vcs.worktree_modules(repository, path, set_aside=set_aside)
    blocked = [
        f"{module.path}: {reason}" for module in modules for reason in module.blocking
    ]
    if blocked:
        shown = "; ".join(blocked[:5]) + (
            f"; and {len(blocked) - 5} more" if len(blocked) > 5 else ""
        )
        raise Refusal(
            f"absent checkout {checkout.name} still has submodule repository state "
            f"that recovery cannot salvage ({shown}); recovery would keep it only "
            "where no Git command finds it. state: REFUSED -- "
            f"{retained} were retained. remedy: "
            "commit and publish that content, or discard it if it is not wanted, "
            "then rerun"
        )
    if salvaged is not None:
        missing = [
            f"{module.path} commit {tip}"
            for module in modules
            for tip in module.tips
            if tip not in salvaged.get(module.name, frozenset())
        ]
        if missing:
            shown = ", ".join(missing[:5]) + (
                f", and {len(missing) - 5} more" if len(missing) > 5 else ""
            )
            raise Refusal(
                f"absent checkout {checkout.name} has submodule commits that no "
                f"remote-tracking ref holds and that recovery did not salvage ({shown}); "
                "recovery would keep them only where no Git command finds them. "
                f"state: REFUSED -- {retained} were retained. remedy: publish those "
                "commits, then rerun; "
                "a recovery journal written before they appeared cannot preserve them"
            )
    return modules


def _absent_agent_module_safe_name(name: str) -> str:
    safe = re.sub(r"[^A-Za-z0-9._-]+", "-", name).strip("-.") or "submodule"
    return f"{safe}-{hashlib.sha256(name.encode('utf-8')).hexdigest()[:12]}"


def _absent_agent_module_rescue_ref(
    record: ActiveRecord, checkout: Checkout, module: str, commit: str
) -> str:
    ref = (
        f"{ABSENT_AGENT_RESCUE_REF_ROOT}/{record.machine}/{record.slot}/"
        f"{checkout.name.replace('/', '-')}-{record.generation}-submodules/"
        f"{_absent_agent_module_safe_name(module)}/{commit}"
    )
    _validate_full_ref(ref, "submodule rescue ref")
    return ref


def _absent_agent_module_archive_paths(
    archive_root: Path,
    record: ActiveRecord,
    checkout: Checkout,
    module: str,
    tips: Sequence[str],
) -> tuple[Path, Path, tuple[tuple[str, str], ...]]:
    """Return the bundle, its receipt, and (commit, ref) for each commit it archives."""

    checkout_name = re.sub(r"[^A-Za-z0-9._-]+", "-", checkout.name).strip("-.") or (
        "checkout"
    )
    checkout_digest = hashlib.sha256(checkout.name.encode("utf-8")).hexdigest()[:12]
    tips_digest = hashlib.sha256("".join(tips).encode("ascii")).hexdigest()[:12]
    module_name = _absent_agent_module_safe_name(module)
    directory = (
        archive_root
        / _LOCAL_SALVAGE_DIRECTORY
        / record.machine
        / record.slot
        / str(record.generation)
        / f"{checkout_name}-{checkout_digest}-submodules"
        / f"{module_name}-{tips_digest}"
    )
    refs = tuple(
        (
            tip,
            _validate_full_ref(
                f"refs/heads/{_LOCAL_SALVAGE_DIRECTORY}/{record.machine}/{record.slot}/"
                f"{record.generation}/{checkout_name}-{checkout_digest}/{module_name}/{tip}",
                "local submodule salvage archive ref",
            ),
        )
        for tip in tips
    )
    return directory / "repository.bundle", directory / "receipt.json", refs


def _verify_absent_agent_module_bundle(
    bundle: Path,
    expected_sha256: str,
    expected_size: int,
    refs: Sequence[tuple[str, str]],
    vcs: _GitVcs,
) -> None:
    """Prove the bundle unchanged, self-contained, and naming each commit at its ref."""

    observed = _sha256_regular_file(bundle, "local submodule salvage bundle")
    if observed != (expected_sha256, expected_size):
        raise Refusal(f"local submodule salvage bundle changed after publication: {bundle}")
    # Restored beside the bundle, never in the system temporary directory.
    with tempfile.TemporaryDirectory(
        prefix=".wrkslots-archive-verify-", dir=str(bundle.parent)
    ) as temporary:
        root = Path(temporary)
        restored = root / "restored.git"
        vcs._run(root, ["clone", "--bare", "--", str(bundle), str(restored)])
        for commit, ref in refs:
            restored_commit = vcs._run(
                restored, ["rev-parse", "--verify", f"{ref}^{{commit}}"]
            ).stdout.strip()
            if restored_commit != commit:
                raise Refusal(
                    f"local submodule salvage bundle ref {ref} names {restored_commit}, "
                    f"not {commit}"
                )
        vcs._run(restored, ["fsck", "--full", "--strict", "--no-dangling"])


def _absent_agent_module_receipt_payload(
    archive_root: Path,
    bundle: Path,
    record: ActiveRecord,
    checkout: Checkout,
    submodule: str,
    submodule_repository: str,
    refs: Sequence[tuple[str, str]],
    bundle_sha256: str,
    bundle_size: int,
) -> dict[str, object]:
    return {
        "schema": _LOCAL_SALVAGE_RECEIPT_SCHEMA,
        "kind": "wrkslots-local-submodule-salvage-archive",
        "machine": record.machine,
        "slot": record.slot,
        "generation": record.generation,
        "checkout": checkout.name,
        "submodule": submodule,
        "submodule_repository": submodule_repository,
        "archive_root": str(archive_root),
        "bundle": str(bundle.relative_to(archive_root)),
        "bundle_sha256": bundle_sha256,
        "bundle_bytes": bundle_size,
        "archive_refs": [{"commit": commit, "ref": ref} for commit, ref in refs],
        "verification": {
            "fresh_bare_clone": True,
            "exact_refs": True,
            "full_fsck": True,
            "complete_history": True,
        },
    }


def _archive_absent_agent_module_locally(
    config: Config,
    record: ActiveRecord,
    checkout: Checkout,
    module: _WorktreeModule,
    archive_root: Path,
    remote_failure: Refusal | None,
    vcs: _GitVcs,
) -> dict[str, object]:
    """Bundle the complete history of each unpublished commit of ``module`` and read it back.

    ``remote_failure`` is None when the submodule's remote is not in
    salvage_push_remotes; otherwise it is the refused push.
    """

    checked_root = _local_salvage_archive_root(config, str(archive_root))
    assert checked_root is not None
    bundle, receipt_path, refs = _absent_agent_module_archive_paths(
        checked_root, record, checkout, module.name, module.tips
    )
    _prepare_local_salvage_directory(checked_root, bundle.parent)
    _ensure_no_symlink_components(checked_root, bundle.parent, "local salvage archive")
    if not bundle.exists() and not bundle.is_symlink():
        with tempfile.TemporaryDirectory(prefix="wrkslots-bundle-stage-") as temporary:
            stage_root = Path(temporary)
            stage = stage_root / "stage.git"
            temp_bundle = (
                bundle.parent / f".{bundle.name}.tmp.{os.getpid()}.{uuid.uuid4().hex}"
            )
            vcs._run(stage_root, ["init", "--bare", "--", str(stage)])
            object_env = {
                "GIT_OBJECT_DIRECTORY": str(module.path / "objects"),
                **_ISOLATED_HISTORY_ENV,
                **(
                    {"GIT_ALTERNATE_OBJECT_DIRECTORIES": str(module.shared / "objects")}
                    if module.shared is not None
                    else {}
                ),
            }
            for commit, ref in refs:
                vcs._run(stage, ["update-ref", ref, commit], env_overrides=object_env)
            try:
                vcs._run(
                    stage,
                    ["bundle", "create", str(temp_bundle), *(ref for _commit, ref in refs)],
                    env_overrides=object_env,
                )
                descriptor = os.open(temp_bundle, os.O_RDONLY | os.O_CLOEXEC)
                try:
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
                os.chmod(temp_bundle, 0o444)
                temp_digest, temp_size = _sha256_regular_file(
                    temp_bundle, "temporary local submodule salvage bundle"
                )
                _verify_absent_agent_module_bundle(
                    temp_bundle, temp_digest, temp_size, refs, vcs
                )
                try:
                    os.link(temp_bundle, bundle, follow_symlinks=False)
                    _fsync_directory(bundle.parent)
                except FileExistsError:
                    pass
            finally:
                with contextlib.suppress(FileNotFoundError):
                    temp_bundle.unlink()
    bundle_digest, bundle_size = _sha256_regular_file(
        bundle, "local submodule salvage bundle"
    )
    _verify_absent_agent_module_bundle(bundle, bundle_digest, bundle_size, refs, vcs)
    expected_receipt = _absent_agent_module_receipt_payload(
        checked_root,
        bundle,
        record,
        checkout,
        module.name,
        str(module.path),
        refs,
        bundle_digest,
        bundle_size,
    )
    if receipt_path.exists() or receipt_path.is_symlink():
        contents = _read_bounded_regular_file(
            receipt_path,
            "local submodule salvage archive receipt",
            _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
        )
        observed = _strict_json_object(contents, "local submodule salvage archive receipt")
        if not _json_equal(observed, expected_receipt):
            raise Refusal(
                "local submodule salvage archive receipt disagrees with the submodule "
                f"repository: {receipt_path}"
            )
    else:
        _atomic_write_json(receipt_path, expected_receipt)
        contents = _read_bounded_regular_file(
            receipt_path,
            "local submodule salvage archive receipt",
            _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
        )
        if not _json_equal(
            _strict_json_object(contents, "local submodule salvage archive receipt"),
            expected_receipt,
        ):
            raise Refusal(
                f"local submodule salvage archive receipt readback failed: {receipt_path}"
            )
    print(
        f"WARNING: submodule {module.name} of absent checkout {checkout.name}: "
        + (
            "its remote is not in salvage_push_remotes"
            if remote_failure is None
            else "remote salvage did not complete"
        )
        + f"; preserved {len(module.tips)} unpublished commit(s) in verified local "
        f"archive {bundle}",
        file=sys.stderr,
    )
    return {
        **_absent_agent_module_receipt_base(checkout, module),
        "disposition": _ABSENT_MODULE_ARCHIVED,
        "archive_root": str(checked_root),
        "archive_receipt": str(receipt_path),
        "archive_receipt_sha256": hashlib.sha256(contents).hexdigest(),
        "archive_bundle": str(bundle),
        "archive_bundle_sha256": bundle_digest,
        "archive_bundle_bytes": bundle_size,
        "archive_refs": [{"commit": commit, "ref": ref} for commit, ref in refs],
        "complete_history": True,
        "archive_reason": "remote-not-allowed" if remote_failure is None else "remote-refused",
        "remote_failure": None if remote_failure is None else str(remote_failure),
    }


def _absent_agent_module_receipt_base(
    checkout: Checkout, module: _WorktreeModule
) -> dict[str, object]:
    return {
        "checkout": checkout.name,
        "submodule": module.name,
        "submodule_repository": str(module.path),
        "shared_repository": None if module.shared is None else str(module.shared),
        "unpublished_commits": list(module.tips),
    }


def _absent_agent_module_authority(
    config: Config,
    vcs: _GitVcs,
    repository: Path,
    module: _WorktreeModule,
    repositories: Sequence[Path],
    doomed: Sequence[Path],
) -> _RemoteAuthority | None:
    """Return the submodule remote salvage may push to, or None to archive locally.

    That is the submodule repository's configuration.default_remote, when it
    has exactly one URL, no push URL, is listed in salvage_push_remotes, and
    is neither a source repository of the row nor a repository Git keeps for
    the checkout. A local remote named by a relative path is archived
    locally instead: Git would resolve it from wherever the push runs. A
    local remote that is, or keeps objects or refs in, an administrative
    directory in ``doomed``, or keeps either behind a symbolic link, refuses
    (_assert_local_remote_outlives).
    """

    with tempfile.TemporaryDirectory(prefix="wrkslots-module-") as temporary:
        work = Path(temporary)
        try:
            authority = vcs.remote_authority(
                work,
                config.default_remote,
                env_overrides=_absent_agent_module_env(module.path, work),
            )
        except Refusal:
            return None
    if not _salvage_push_allowed(config, authority):
        return None
    local = _local_remote_url_path(repository, authority.url)
    if local is not None and not _local_remote_url_is_absolute(authority.url):
        # Classified before the distinct-repository check, which would resolve
        # the path from the superproject and refuse instead of archiving.
        return None
    vcs.assert_remote_distinct_from_repositories(repository, authority, repositories)
    if local is not None:
        resolved = _assert_local_remote_outlives(
            local, (module.administration, *doomed), f"submodule repository {module.path}"
        )
        if module.shared is not None and (
            resolved == module.shared.resolve()
            or _path_is_within(resolved, module.shared.resolve())
        ):
            raise Refusal(
                f"the remote of submodule repository {module.path} is {module.shared}, "
                "which is not a separate repository to salvage into"
            )
    return authority


def _local_remote_url_is_absolute(url: str) -> bool:
    """Whether a local remote URL (see _local_remote_url_path) names an absolute path."""

    text = _remote_url_local_text(url)
    return text is not None and Path(text).is_absolute()


def _refuse_symlinks_below(root: Path, label: str) -> None:
    """Refuse a symbolic link at ``root`` or anywhere below it; ``root`` need not exist."""

    def refuse(link: str) -> NoReturn:
        raise Refusal(
            f"{label} keeps {link} as a symbolic link, which Git follows to storage "
            "it does not own, so it cannot be shown to outlive recovery. remedy: "
            "replace the link with what it names, or remove the remote from "
            "salvage_push_remotes so salvage archives locally"
        )

    if root.is_symlink():
        refuse(str(root))
    if not root.exists():
        return
    pending = [root]
    while pending:
        directory = pending.pop()
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    if entry.is_symlink():
                        refuse(entry.path)
                    if entry.is_dir(follow_symlinks=False):
                        pending.append(Path(entry.path))
        except OSError as exc:
            raise Refusal(f"cannot inspect {directory} for {label}: {exc}") from exc


def _refuse_process_dependent_storage(
    written: Path, procfs: Sequence[Path], label: str, what: str
) -> None:
    """Refuse when ``written``, a path Git reads for a local remote, leads into a proc file system.

    See _process_dependent_prefix. ``what`` says where the path came from.
    """

    leading = _process_dependent_prefix(str(written), procfs)
    if leading is not None:
        raise Refusal(
            f"{label} {what} {written}, which leads through {leading} into a proc "
            "file system, where a path names a different place for each process "
            "that resolves it, so where Git keeps the remote's objects and refs "
            "cannot be checked. remedy: point the remote at a repository named, "
            "and borrowing objects, by paths outside the proc file system, or "
            "remove it from salvage_push_remotes so salvage archives locally"
        )


def _local_repository_storage(path: Path, label: str) -> tuple[Path, ...]:
    """Return, resolved, each directory of objects or refs Git uses for local repository ``path``.

    Git looks for a local remote at ``path``, path/.git, path.git, and
    path.git/.git, follows a gitfile and a commondir file, and borrows
    objects through objects/info/alternates, up to five levels deep. Each
    candidate found is included, so the result can only overstate what Git
    uses. A symbolic link anywhere below an objects, refs, or reftable
    directory refuses, as does a linked packed-refs file: Git follows it, so
    a pack, a loose object, or a ref there may live in another directory
    entirely. Anything that cannot be read, or nests deeper, refuses.
    So does a candidate, gitfile target, commondir or alternates entry,
    as written and joined to where it is read, that leads into a proc file
    system (_refuse_process_dependent_storage): resolved by recovery, it
    names recovery's own place, not the one the Git command serving the
    remote finds.
    """

    procfs = _procfs_points(_read_self_mount_entries())
    git_directories: list[Path] = []
    for candidate in (
        path / ".git",
        path,
        Path(f"{path}.git") / ".git",
        Path(f"{path}.git"),
    ):
        _refuse_process_dependent_storage(candidate, procfs, label, "looks for a repository at")
        if candidate.is_file():
            try:
                text = _read_bounded_regular_file(
                    candidate, f"{label} gitfile", _WORKTREE_GITDIR_BYTES_LIMIT
                ).decode("utf-8")
            except UnicodeDecodeError as exc:
                raise Refusal(f"{label} gitfile {candidate} is not UTF-8") from exc
            # Git strips every trailing CR and LF (read_gitfile_gently); any
            # other control character left in the path refuses.
            line = text.rstrip("\r\n")
            if not line.startswith("gitdir: ") or line == "gitdir: ":
                raise Refusal(f"{label} gitfile {candidate} is malformed")
            _refuse_control_characters(
                line.removeprefix("gitdir: "), f"{label} gitfile {candidate}"
            )
            target = Path(line.removeprefix("gitdir: "))
            joined_target = target if target.is_absolute() else candidate.parent / target
            _refuse_process_dependent_storage(
                joined_target, procfs, label, f"gitfile {candidate} names"
            )
            git_directories.append(joined_target)
        elif candidate.is_dir():
            git_directories.append(candidate)
    stores: list[Path] = []
    pending: list[tuple[Path, int]] = []
    for git_directory in git_directories:
        stores.append(git_directory)
        pending.append((git_directory / "objects", 0))
        commondir = git_directory / "commondir"
        if commondir.exists() or commondir.is_symlink():
            try:
                text = _read_bounded_regular_file(
                    commondir, f"{label} commondir", _WORKTREE_GITDIR_BYTES_LIMIT
                ).decode("utf-8")
            except UnicodeDecodeError as exc:
                raise Refusal(f"{label} commondir {commondir} is not UTF-8") from exc
            # Git strips every trailing CR and LF (get_common_dir_noenv).
            common_text = text.rstrip("\r\n")
            if not common_text:
                raise Refusal(f"{label} commondir {commondir} is malformed")
            _refuse_control_characters(common_text, f"{label} commondir {commondir}")
            common = Path(common_text)
            common_directory = common if common.is_absolute() else git_directory / common
            _refuse_process_dependent_storage(
                common_directory, procfs, label, f"commondir {commondir} names"
            )
            stores.append(common_directory)
            pending.append((common_directory / "objects", 0))
    found: dict[Path, None] = {}
    while pending:
        objects, depth = pending.pop()
        resolved = objects.resolve()
        if resolved in found:
            continue
        found[resolved] = None
        alternates = resolved / "info" / "alternates"
        if not alternates.exists() and not alternates.is_symlink():
            continue
        if depth >= 5:
            raise Refusal(f"{label} borrows objects more than five alternates deep")
        try:
            # Git separates entries at LF only (link_alt_odb_entries); a CR, a
            # vertical tab or another line separator is part of a path.
            lines = _read_bounded_regular_file(
                alternates, f"{label} alternates", _WORKTREE_GITDIR_BYTES_LIMIT
            ).decode("utf-8").split("\n")
        except UnicodeDecodeError as exc:
            raise Refusal(f"{label} alternates file {alternates} is not UTF-8") from exc
        for line in lines:
            if not line or line.startswith("#"):
                continue
            if line.startswith('"'):
                raise Refusal(
                    f"{label} alternates file {alternates} quotes a path, which is not "
                    "checked"
                )
            _refuse_control_characters(line, f"{label} alternates file {alternates}")
            alternate = Path(line)
            joined_alternate = alternate if alternate.is_absolute() else resolved / alternate
            _refuse_process_dependent_storage(
                joined_alternate, procfs, label, f"alternates file {alternates} names"
            )
            pending.append((joined_alternate, depth + 1))
    storage: dict[Path, None] = {}
    for store in stores:
        resolved_store = store.resolve()
        storage[resolved_store] = None
        if (resolved_store / "packed-refs").is_symlink():
            _refuse_symlinks_below(resolved_store / "packed-refs", label)
        for name in ("refs", "reftable"):
            _refuse_symlinks_below(resolved_store / name, label)
    for objects in found:
        storage[objects] = None
        _refuse_symlinks_below(objects, label)
    return tuple(storage)


def _assert_local_remote_outlives(
    local: Path, doomed: Sequence[Path], label: str
) -> Path:
    """Refuse a local remote that is, or keeps objects or refs in, a directory in ``doomed``.

    A rescue ref on such a remote names a commit through a path recovery is
    about to remove with an administrative directory: it deletes that
    directory, after moving the submodule repositories in it to where it
    keeps them. A remote that keeps
    any of them behind a symbolic link refuses too (_local_repository_storage),
    and so does one where any of them, or a directory below one, is a
    directory at or below ``doomed`` under another name, as a bind mount
    makes it (_refuse_aliases_below).
    Returns the remote's resolved path. A remote whose path, as written,
    leads into a proc file system refuses before it is resolved
    (_refuse_process_dependent_storage), and so does one whose repository
    pointers do (_local_repository_storage).
    """

    _refuse_process_dependent_storage(
        local, _procfs_points(_read_self_mount_entries()), label, "has a local remote at"
    )
    try:
        resolved = local.resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"cannot resolve the local remote of {label}: {exc}") from exc
    kept = [directory.resolve() for directory in doomed]
    remedy = (
        "remedy: point the remote at a repository that keeps its own objects, or "
        "remove it from salvage_push_remotes so salvage archives locally"
    )
    storage = (resolved, *_local_repository_storage(resolved, label))
    for used in storage:
        for directory in kept:
            if used == directory or _path_is_within(used, directory):
                raise Refusal(
                    f"the local remote of {label} uses {used}, inside {directory}, "
                    "which recovery deletes; a rescue ref there would preserve nothing. "
                    f"{remedy}"
                )
    found_doomed: list[Mapping[_DirectoryIdentity, Path]] = []

    def doomed_directories() -> Mapping[_DirectoryIdentity, Path]:
        if not found_doomed:
            found_doomed.append(
                _directory_identities(kept, "the directories recovery deletes")
            )
        return found_doomed[0]

    for used in dict.fromkeys(storage):
        if any(other != used and _path_is_within(used, other) for other in storage):
            continue  # examined with the directory that holds it

        def refuse(found: str, used: Path = used) -> NoReturn:
            raise Refusal(
                f"the local remote of {label} uses {used}, where {found}; a rescue "
                f"ref there would preserve nothing. {remedy}"
            )

        _refuse_aliases_below(used, doomed_directories, refuse, links=False)
    return resolved


def _push_absent_agent_module(
    record: ActiveRecord,
    checkout: Checkout,
    module: _WorktreeModule,
    authority: _RemoteAuthority,
    vcs: _GitVcs,
) -> dict[str, object]:
    refs = [
        (tip, _absent_agent_module_rescue_ref(record, checkout, module.name, tip))
        for tip in module.tips
    ]
    with vcs._isolated_repository(
        module.path / "objects",
        alternates=() if module.shared is None else (module.shared / "objects",),
    ) as (isolated, object_env):
        for commit, ref in refs:
            vcs._push_salvage_ref(isolated, object_env, authority.url, commit, ref)
    return {
        **_absent_agent_module_receipt_base(checkout, module),
        "disposition": _ABSENT_MODULE_PUSHED,
        "remote_url_sha256": authority.sha256,
        "remote_refs": [{"commit": commit, "ref": ref} for commit, ref in refs],
    }


def _absent_agent_doomed_administrations(
    config: Config, record: ActiveRecord, removed: AbstractSet[str], vcs: _GitVcs
) -> dict[str, Path]:
    """Map each checkout still registered, outside ``removed``, to its administrative directory."""

    doomed: dict[str, Path] = {}
    for checkout in record.checkouts:
        if checkout.name in removed:
            continue
        _stored, repository = _stored_repository_path(config, checkout.repository)
        path = _stored_path(config, checkout.path, "agent checkout path").absolute()
        if vcs.worktree_registration(repository, path) is None:
            continue
        administration = vcs.worktree_administrative_directory(repository, path)
        if administration is None:
            raise Refusal(
                f"Git registers {path} but no administrative directory names it"
            )
        doomed[checkout.name] = administration
    return doomed


def _assert_private_salvage_directories(root: Path, directory: Path) -> None:
    """Refuse unless every directory from ``root`` down to ``directory`` is private and real."""

    try:
        relative = directory.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"local salvage archive {directory} is outside {root}") from exc
    current = root
    for part in relative.parts:
        current /= part
        try:
            metadata = current.stat(follow_symlinks=False)
        except OSError as exc:
            raise Refusal(f"cannot inspect local salvage archive {current}: {exc}") from exc
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or metadata.st_uid != os.getuid()
            or metadata.st_mode & 0o022
        ):
            raise Refusal(
                f"local salvage archive directory is not private current-user storage: "
                f"{current}"
            )


def _salvage_absent_agent_modules(
    config: Config, record: ActiveRecord, vcs: _GitVcs, *, apply: bool
) -> list[dict[str, object]]:
    """Preserve, or with ``apply`` False only plan, every unpublished submodule commit.

    Each submodule repository Git keeps for a still-registered checkout is
    examined (_assert_absent_agent_modules_preserved). Its commits outside
    every remote-tracking ref are pushed to rescue refs on its remote when
    salvage_push_remotes lists that remote, and otherwise, or when the push
    is refused, bundled with their complete history into the default local
    salvage archive and read back. A planned receipt names only the
    submodule and the commits that need salvage.
    """

    repositories = tuple(
        _stored_repository_path(config, checkout.repository)[1]
        for checkout in record.checkouts
    )
    doomed = _absent_agent_doomed_administrations(config, record, frozenset(), vcs)
    receipts: list[dict[str, object]] = []
    for checkout in record.checkouts:
        _stored, repository = _stored_repository_path(config, checkout.repository)
        path = _stored_path(config, checkout.path, "agent checkout path").absolute()
        if vcs.worktree_registration(repository, path) is None:
            continue
        modules = _assert_absent_agent_modules_preserved(
            vcs,
            repository,
            path,
            checkout,
            "the ACTIVE row and Git registrations",
            None,
            record=record,
        )
        for module in modules:
            if not module.tips:
                receipts.append(
                    {
                        **_absent_agent_module_receipt_base(checkout, module),
                        "disposition": _ABSENT_MODULE_PUBLISHED,
                    }
                )
                continue
            authority = _absent_agent_module_authority(
                config, vcs, repository, module, repositories, tuple(doomed.values())
            )
            if not apply:
                if authority is None:
                    _default_salvage_archive_root(config)
                receipts.append(
                    {
                        **_absent_agent_module_receipt_base(checkout, module),
                        "disposition": "planned-push"
                        if authority is not None
                        else "planned-local-archive",
                    }
                )
                continue
            failure: Refusal | None = None
            if authority is not None:
                try:
                    receipts.append(
                        _push_absent_agent_module(record, checkout, module, authority, vcs)
                    )
                    continue
                except Refusal as exc:
                    failure = exc
            receipts.append(
                _archive_absent_agent_module_locally(
                    config,
                    record,
                    checkout,
                    module,
                    _default_salvage_archive_root(config),
                    failure,
                    vcs,
                )
            )
    return receipts


def _absent_agent_module_salvaged(
    receipts: Sequence[Mapping[str, object]],
) -> dict[str, dict[str, frozenset[str]]]:
    """Map checkout -> submodule -> the commits its receipt preserved."""

    salvaged: dict[str, dict[str, frozenset[str]]] = {}
    for receipt in receipts:
        commits = (
            frozenset()
            if receipt["disposition"] == _ABSENT_MODULE_PUBLISHED
            else frozenset(
                _as_str(value, "submodule receipt commit")
                for value in _as_list(
                    receipt["unpublished_commits"], "submodule receipt.unpublished_commits"
                )
            )
        )
        salvaged.setdefault(str(receipt["checkout"]), {})[str(receipt["submodule"])] = commits
    return salvaged


_ABSENT_MODULE_RECEIPT_KEYS: Mapping[str, frozenset[str]] = {
    _ABSENT_MODULE_PUBLISHED: frozenset(),
    _ABSENT_MODULE_PUSHED: frozenset({"remote_url_sha256", "remote_refs"}),
    _ABSENT_MODULE_ARCHIVED: frozenset(
        {
            "archive_root",
            "archive_receipt",
            "archive_receipt_sha256",
            "archive_bundle",
            "archive_bundle_sha256",
            "archive_bundle_bytes",
            "archive_refs",
            "complete_history",
            "archive_reason",
            "remote_failure",
        }
    ),
}


def _absent_agent_module_commit_refs(
    receipt: Mapping[str, object], key: str, label: str
) -> tuple[tuple[str, str], ...]:
    pairs: list[tuple[str, str]] = []
    for index, value in enumerate(_as_list(receipt[key], f"{label}.{key}")):
        entry = _as_mapping(value, f"{label}.{key}[{index}]")
        _exact_keys(entry, {"commit", "ref"}, set(), f"{label}.{key}[{index}]")
        commit = _as_str(entry["commit"], f"{label}.{key}[{index}].commit")
        ref = _as_str(entry["ref"], f"{label}.{key}[{index}].ref")
        try:
            _validate_full_ref(ref, f"{label}.{key}[{index}].ref")
        except Refusal as exc:
            raise StateError(f"{label}.{key}[{index}].ref is invalid") from exc
        pairs.append((commit, ref))
    return tuple(pairs)


def _absent_agent_submodule_salvage_from_journal(
    raw: Mapping[str, object], record: ActiveRecord
) -> tuple[dict[str, object], ...]:
    """Validate the submodule receipts a recovery journal recorded before its first push."""

    if "submodule_salvage" not in raw:
        return ()
    entries = _as_list(raw["submodule_salvage"], "absent-agent-row journal.submodule_salvage")
    if not entries:
        raise StateError("absent-agent-row journal.submodule_salvage is empty")
    order = [checkout.name for checkout in record.checkouts]
    receipts: list[dict[str, object]] = []
    seen: list[tuple[int, str]] = []
    for index, value in enumerate(entries):
        label = f"absent-agent-row journal.submodule_salvage[{index}]"
        entry = dict(_as_mapping(value, label))
        disposition = _as_str(entry.get("disposition"), f"{label}.disposition")
        if disposition not in _ABSENT_MODULE_RECEIPT_KEYS:
            raise StateError(f"{label}.disposition {disposition!r} is unknown")
        _exact_keys(
            entry,
            {
                "checkout",
                "submodule",
                "submodule_repository",
                "shared_repository",
                "unpublished_commits",
                "disposition",
                *_ABSENT_MODULE_RECEIPT_KEYS[disposition],
            },
            set(),
            label,
        )
        checkout = _as_str(entry["checkout"], f"{label}.checkout")
        submodule = _as_str(entry["submodule"], f"{label}.submodule")
        _as_str(entry["submodule_repository"], f"{label}.submodule_repository")
        if entry["shared_repository"] is not None:
            _as_str(entry["shared_repository"], f"{label}.shared_repository")
        if checkout not in order or not submodule:
            raise StateError(f"{label} names no recorded checkout and submodule")
        commits = [
            _as_str(commit, f"{label}.unpublished_commits[{position}]")
            for position, commit in enumerate(
                _as_list(entry["unpublished_commits"], f"{label}.unpublished_commits")
            )
        ]
        if (
            any(SHA_RE.fullmatch(commit) is None for commit in commits)
            or commits != sorted(set(commits))
            or (disposition == _ABSENT_MODULE_PUBLISHED) != (not commits)
        ):
            raise StateError(f"{label}.unpublished_commits is invalid for {disposition}")
        if disposition == _ABSENT_MODULE_PUSHED:
            if DIGEST_RE.fullmatch(
                _as_str(entry["remote_url_sha256"], f"{label}.remote_url_sha256")
            ) is None or [
                commit
                for commit, _ref in _absent_agent_module_commit_refs(
                    entry, "remote_refs", label
                )
            ] != commits:
                raise StateError(f"{label} remote refs differ from its commits")
        elif disposition == _ABSENT_MODULE_ARCHIVED:
            for key in (
                "archive_root",
                "archive_receipt",
                "archive_bundle",
                "archive_reason",
            ):
                _as_str(entry[key], f"{label}.{key}")
            for key in ("archive_receipt_sha256", "archive_bundle_sha256"):
                if DIGEST_RE.fullmatch(_as_str(entry[key], f"{label}.{key}")) is None:
                    raise StateError(f"{label}.{key} must be one SHA-256 digest")
            _as_int(entry["archive_bundle_bytes"], f"{label}.archive_bundle_bytes", minimum=1)
            if entry["remote_failure"] is not None:
                _as_str(entry["remote_failure"], f"{label}.remote_failure")
            if entry["complete_history"] is not True or [
                commit
                for commit, _ref in _absent_agent_module_commit_refs(
                    entry, "archive_refs", label
                )
            ] != commits:
                raise StateError(f"{label} archive refs differ from its commits")
        position = (order.index(checkout), submodule)
        if seen and position <= seen[-1]:
            raise StateError(
                "absent-agent-row submodule receipts are not distinct and in checkout order"
            )
        seen.append(position)
        receipts.append(entry)
    return tuple(receipts)


def _assert_absent_agent_module_salvage_intact(
    config: Config,
    record: ActiveRecord,
    receipts: Sequence[Mapping[str, object]],
    removed: AbstractSet[str],
    vcs: _GitVcs,
) -> tuple[Callable[[], None], ...]:
    """Re-read every submodule salvage before any registration is removed.

    The journal's paths are not trusted. A submodule repository must be
    where Git keeps it for a still-registered checkout. A pushed commit must
    still be at its rescue ref on the URL that repository names, which must
    not be a relative local path, and a local remote must not keep objects or
    refs in an administrative directory recovery deletes, or behind a
    symbolic link. A bundle and its receipt must be at the paths wrkslots derives
    for them in the default archive root, below private directories that
    cross no symlink and lie outside every such administrative directory;
    the receipt must say exactly what the journal records, and the bundle
    must still hash to it, clone afresh, name each commit, and pass a full
    fsck.

    Returns, for each salvage, a check of what it rests on that reads only
    this host, to run again immediately before each registration is
    removed: a rename or bind mount made since could carry a bundle, its
    receipt, or a local remote's storage into an administrative directory.
    It checks again where a bundle and its receipt are and that each still
    hashes to what was verified, or that a local remote's storage still
    outlives the removal (_assert_local_remote_outlives) and its rescue
    refs still name the commits. A pushed commit's objects are taken to be
    on the remote while a rescue ref there names it, as Git keeps them; a
    remote reached through the network has nothing to check again here.
    """

    checkouts = {checkout.name: checkout for checkout in record.checkouts}
    doomed = _absent_agent_doomed_administrations(config, record, removed, vcs)
    doomed_paths = tuple(doomed.values())
    rechecks: list[Callable[[], None]] = []

    def doomed_finder() -> Callable[[], Mapping[_DirectoryIdentity, Path]]:
        found_doomed: list[Mapping[_DirectoryIdentity, Path]] = []

        def doomed_directories() -> Mapping[_DirectoryIdentity, Path]:
            # Every administrative directory of each repository involved: Git
            # deletes any of them with its registration, whichever row's it is.
            if not found_doomed:
                parents = sorted({path.parent for path in doomed_paths})
                found_doomed.append(
                    _directory_identities(
                        parents,
                        "the Git administrative directories of "
                        + ", ".join(str(path) for path in parents),
                    )
                )
            return found_doomed[0]

        return doomed_directories

    def check_archive_place(root: Path, bundle: Path, receipt_path: Path, label: str) -> None:
        _assert_private_salvage_directories(root, bundle.parent)
        for kept in (bundle, receipt_path):
            real = Path(os.path.realpath(kept))
            for directory in doomed_paths:
                resolved = directory.resolve()
                if real == resolved or _path_is_within(real, resolved):
                    raise Refusal(
                        f"local salvage archive {kept} for {label} lies in {directory}, "
                        "which recovery deletes; nothing was removed"
                    )

        def refuse_archive(found: str, kept: Path = bundle.parent, why: str = label) -> NoReturn:
            raise Refusal(
                f"local salvage archive {kept} for {why} cannot be shown to outlive "
                f"the removal of a registration: {found}. nothing was removed"
            )

        _refuse_aliases_below(
            Path(os.path.realpath(bundle.parent)),
            doomed_finder(),
            refuse_archive,
            links=True,
        )

    def check_pushed_refs(
        isolated: Path,
        object_env: Mapping[str, str],
        url: str,
        refs: Sequence[tuple[str, str]],
        label: str,
    ) -> None:
        for commit, ref in refs:
            if vcs._remote_ref_sha_at_url(isolated, url, ref, env_overrides=object_env) != commit:
                raise Refusal(f"remote rescue ref {ref} for {label} no longer names {commit}")

    for receipt in receipts:
        checkout = checkouts[str(receipt["checkout"])]
        submodule = _as_str(receipt["submodule"], "submodule name")
        recorded_repository = _as_str(receipt["submodule_repository"], "submodule path")
        label = f"submodule {submodule} of absent checkout {checkout.name}"
        administration = doomed.get(checkout.name)
        if administration is not None and Path(recorded_repository) != (
            administration / submodule
        ):
            raise Refusal(
                f"the recovery journal places {label} at {recorded_repository}, not "
                f"where Git keeps it ({administration / submodule}); nothing was removed"
            )
        if receipt["disposition"] == _ABSENT_MODULE_PUSHED:
            if administration is None:
                continue
            module_path = administration / submodule
            with tempfile.TemporaryDirectory(prefix="wrkslots-module-") as temporary:
                work = Path(temporary)
                authority = vcs.remote_authority(
                    work,
                    config.default_remote,
                    env_overrides=_absent_agent_module_env(module_path, work),
                )
                if authority.sha256 != receipt["remote_url_sha256"]:
                    raise Refusal(f"the remote of {label} changed after salvage")
                local = _local_remote_url_path(module_path, authority.url)
                if local is not None and not _local_remote_url_is_absolute(
                    authority.url
                ):
                    # Salvage archives rather than pushes to a relative local
                    # remote, and Git would resolve one from the temporary
                    # repository the check below reads through, not from where
                    # it is inspected here.
                    raise Refusal(
                        f"the recovery journal records commits of {label} pushed to "
                        f"{authority.url}, a relative local path, which salvage "
                        "never pushes to; nothing was removed"
                    )
                if local is not None:
                    _assert_local_remote_outlives(local, doomed_paths, label)
                pushed_refs = _absent_agent_module_commit_refs(receipt, "remote_refs", label)
                with vcs._isolated_repository(module_path / "objects") as (
                    isolated,
                    object_env,
                ):
                    check_pushed_refs(isolated, object_env, authority.url, pushed_refs, label)
            if local is not None:
                # mypy does not carry the narrowing above into a default value.
                remote_path: Path = local

                def recheck_pushed(
                    local: Path = remote_path,
                    url: str = authority.url,
                    refs: Sequence[tuple[str, str]] = pushed_refs,
                    label: str = label,
                ) -> None:
                    resolved = _assert_local_remote_outlives(local, doomed_paths, label)
                    # Only refs are read; the store this repository starts
                    # with, empty, is never used.
                    with vcs._isolated_repository(resolved, own_objects=True) as (
                        isolated,
                        object_env,
                    ):
                        check_pushed_refs(isolated, object_env, url, refs, label)

                rechecks.append(recheck_pushed)
        elif receipt["disposition"] == _ABSENT_MODULE_ARCHIVED:
            root = _default_salvage_archive_root(config)
            commits = [
                _as_str(value, "submodule receipt commit")
                for value in _as_list(
                    receipt["unpublished_commits"], "submodule receipt commits"
                )
            ]
            bundle, receipt_path, refs = _absent_agent_module_archive_paths(
                root, record, checkout, submodule, commits
            )
            if (
                receipt["archive_root"] != str(root)
                or receipt["archive_bundle"] != str(bundle)
                or receipt["archive_receipt"] != str(receipt_path)
                or _absent_agent_module_commit_refs(receipt, "archive_refs", label)
                != refs
            ):
                raise Refusal(
                    f"the recovery journal names a local salvage archive for {label} "
                    f"other than {bundle}, where wrkslots writes it; nothing was removed"
                )
            check_archive_place(root, bundle, receipt_path, label)
            contents = _read_bounded_regular_file(
                receipt_path,
                "local submodule salvage archive receipt",
                _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
            )
            if hashlib.sha256(contents).hexdigest() != receipt["archive_receipt_sha256"]:
                raise Refusal(f"local salvage archive receipt for {label} changed")
            bundle_sha256 = _as_str(receipt["archive_bundle_sha256"], "submodule bundle digest")
            bundle_size = _as_int(
                receipt["archive_bundle_bytes"], "submodule bundle size", minimum=1
            )
            if not _json_equal(
                _strict_json_object(contents, "local submodule salvage archive receipt"),
                _absent_agent_module_receipt_payload(
                    root,
                    bundle,
                    record,
                    checkout,
                    submodule,
                    recorded_repository,
                    refs,
                    bundle_sha256,
                    bundle_size,
                ),
            ):
                raise Refusal(
                    f"local salvage archive receipt {receipt_path} for {label} disagrees "
                    "with the recovery journal; nothing was removed"
                )
            _verify_absent_agent_module_bundle(bundle, bundle_sha256, bundle_size, refs, vcs)
            receipt_sha256 = _as_str(receipt["archive_receipt_sha256"], "receipt digest")

            def recheck_archive(
                root: Path = root,
                bundle: Path = bundle,
                receipt_path: Path = receipt_path,
                label: str = label,
                receipt_sha256: str = receipt_sha256,
                bundle_sha256: str = bundle_sha256,
                bundle_size: int = bundle_size,
            ) -> None:
                check_archive_place(root, bundle, receipt_path, label)
                contents = _read_bounded_regular_file(
                    receipt_path,
                    "local submodule salvage archive receipt",
                    _LOCAL_SALVAGE_RECEIPT_BYTES_LIMIT,
                )
                if hashlib.sha256(contents).hexdigest() != receipt_sha256:
                    raise Refusal(f"local salvage archive receipt for {label} changed")
                observed = _sha256_regular_file(bundle, "local submodule salvage bundle")
                if observed != (bundle_sha256, bundle_size):
                    raise Refusal(
                        f"local submodule salvage bundle changed after publication: {bundle}"
                    )

            rechecks.append(recheck_archive)
    return tuple(rechecks)


def _absent_agent_module_validation(receipt: Mapping[str, object]) -> str:
    commits = _as_list(receipt["unpublished_commits"], "submodule receipt commits")
    prefix = f"checkout {receipt['checkout']} submodule {receipt['submodule']}: "
    if receipt["disposition"] == _ABSENT_MODULE_PUBLISHED:
        return (
            prefix + "every commit the submodule repository Git kept for the checkout "
            "stored itself, or HEAD or a ref there named, was reachable from a "
            "remote-tracking ref there or in the shared submodule repository; nothing "
            "was salvaged"
        )
    if receipt["disposition"] == _ABSENT_MODULE_PUSHED:
        return (
            prefix + f"{len(commits)} commit(s) outside every remote-tracking ref were "
            "pushed to rescue refs on the submodule's remote and read back before the "
            "registration was removed"
        )
    return (
        prefix + f"{len(commits)} commit(s) outside every remote-tracking ref were "
        f"bundled with complete history into {receipt['archive_bundle']} (SHA-256 "
        f"{receipt['archive_bundle_sha256']}), which was cloned afresh and fsck-checked "
        "before the registration was removed"
    )


def _assert_absent_agent_index_unstaged(
    vcs: _GitVcs,
    repository: Path,
    path: Path,
    checkout: Checkout,
    authority: _RemoteAuthority,
    retained: str,
) -> None:
    """Refuse while the index Git kept for an absent checkout stages unpublished content.

    Removing the registration deletes that index. A rescue push or an existing
    remote ref preserves only the recorded HEAD, so content staged beyond it
    exists nowhere else.
    """

    index, staged = vcs.worktree_staged_paths(
        repository, path, checkout.head, checkout.remote, authority
    )
    if staged:
        shown = ", ".join(staged[:5]) + (
            f", and {len(staged) - 5} more" if len(staged) > 5 else ""
        )
        raise Refusal(
            f"absent checkout {checkout.name} still has an index at {index} that "
            f"stages content its recorded HEAD {checkout.head} does not contain "
            f"({shown}); removing the Git registration would delete it. state: "
            f"REFUSED -- {retained} were retained. remedy: commit that staged "
            "content and publish it, or reset that index to the recorded HEAD if "
            "it is not wanted, then rerun"
        )


def _assert_absent_agent_worktree_state_preserved(
    vcs: _GitVcs,
    repository: Path,
    path: Path,
    checkout: Checkout,
    authority: _RemoteAuthority,
    retained: str,
) -> None:
    """Refuse while Git keeps anything for an absent checkout beyond its recorded HEAD.

    Removing the registration deletes the checkout's administrative
    directory: its index (see _assert_absent_agent_index_unstaged) with its
    resolve-undo record, its per-worktree refs, and any unfinished merge,
    cherry-pick, revert, rebase, or bisect. Only the recorded HEAD's history
    is preserved, so a per-worktree ref or resolve-undo entry naming anything
    outside it, or an unfinished operation, refuses. Reflogs are discarded,
    as by every `git worktree remove`.
    """

    _assert_absent_agent_index_unstaged(
        vcs, repository, path, checkout, authority, retained
    )
    roots = vcs.worktree_private_roots_beyond(
        repository, path, checkout.head, checkout.remote, authority
    )
    if roots:
        shown = ", ".join(roots[:5]) + (
            f", and {len(roots) - 5} more" if len(roots) > 5 else ""
        )
        raise Refusal(
            f"absent checkout {checkout.name} still has Git state outside the history "
            f"of its recorded HEAD {checkout.head} ({shown}); removing the Git "
            f"registration would delete it. state: REFUSED -- {retained} were "
            "retained. remedy: publish each such ref's commit and delete the ref, "
            "or delete it if it is not wanted; finish or abandon the unfinished "
            "operation; publish a resolve-undo entry's content, or reset that "
            "index to the recorded HEAD if it is not wanted; then rerun"
        )


def _absent_agent_checkout_receipts(
    config: Config,
    record: ActiveRecord,
    vcs: _GitVcs,
    branch_witnesses: Sequence[_AbsentAgentBranchWitness],
    removed: AbstractSet[str] = frozenset(),
    *,
    preserved: AbstractSet[str] = frozenset(),
    containment: Mapping[str, tuple[str, str]] | None = None,
    module_salvage: Mapping[str, Mapping[str, AbstractSet[str]]] | None,
) -> tuple[dict[str, object], ...]:
    """Check every absent checkout and return its planned preservation receipt.

    ``containment`` is None while planning: a checkout whose remote is not in
    salvage_push_remotes is then accepted only when an existing remote ref
    already contains its recorded HEAD. A journal passes the containment it
    recorded, which is re-verified instead of searched for again.
    ``module_salvage`` is None before submodule salvage, and afterwards maps
    checkout -> submodule -> the commits salvage preserved (see
    _assert_absent_agent_modules_preserved).
    """

    if len(branch_witnesses) != len(record.checkouts):
        raise StateError("absent-agent branch witness count differs from checkout count")
    _assert_absent_agent_rescue_refs_disjoint(record, branch_witnesses)
    repositories = tuple(
        _stored_repository_path(config, checkout.repository)[1]
        for checkout in record.checkouts
    )
    found: dict[str, tuple[str, str]] = {}
    for checkout, witness in zip(record.checkouts, branch_witnesses, strict=True):
        _stored, repository = _stored_repository_path(config, checkout.repository)
        authority = vcs.remote_authority(repository, checkout.remote)
        if not _recorded_remote_names_same_repository(
            checkout.remote_url_sha256, authority
        ):
            raise Refusal(
                f"source repository remote changed for absent checkout {checkout.name}"
            )
        vcs.assert_remote_distinct_from_repositories(
            repository, authority, repositories
        )
        if checkout.name not in preserved and (
            vcs.verify_ref(repository, checkout.head, "recorded checkout HEAD")
            != checkout.head
        ):
            raise Refusal(f"recorded commit object is unavailable for {checkout.name}")
        recorded = None if containment is None else containment.get(checkout.name)
        if recorded is not None:
            if (
                vcs.remote_ref_contains_commit(
                    repository, checkout.remote, recorded[0], checkout.head, authority
                )
                is None
            ):
                raise Refusal(
                    f"existing remote ref {_display_ref(recorded[0])} no longer contains "
                    "the recorded "
                    f"HEAD {checkout.head} of absent checkout {checkout.name}. state: "
                    "REFUSED -- the ACTIVE row, the recovery journal, and the remaining "
                    "Git registrations were retained. remedy: restore a remote ref "
                    "containing that commit, then rerun recover"
                )
        elif not _salvage_push_allowed(config, authority):
            if containment is not None:
                raise Refusal(
                    f"absent checkout {checkout.name} remote {checkout.remote} is not in "
                    "salvage_push_remotes, and the recovery journal preserves the "
                    "recorded HEAD by pushing a rescue ref to it. state: REFUSED -- the "
                    "ACTIVE row, the recovery journal, and the remaining Git "
                    "registrations were retained. remedy: list the remote in "
                    "salvage_push_remotes only if salvage may publish to it"
                )
            existing = _absent_agent_existing_containing_ref(
                vcs, repository, checkout, authority
            )
            if existing is None:
                raise Refusal(
                    f"absent checkout {checkout.name} remote {checkout.remote} is not in "
                    "salvage_push_remotes, and no ref on that remote contains the "
                    f"recorded HEAD {checkout.head}; recovery preserves the recorded HEAD "
                    "only by finding it in such a ref or by pushing a rescue ref. state: REFUSED -- the ACTIVE row and Git "
                    "registrations were retained. remedy: publish the recorded HEAD to "
                    "that remote, or list the remote in salvage_push_remotes only if "
                    "salvage may publish to it"
                )
            found[checkout.name] = existing
        if checkout.name not in removed:
            _assert_absent_agent_branch_witness(repository, checkout, witness, vcs)
        path = _stored_path(config, checkout.path, "agent checkout path").absolute()
        registration = vcs.worktree_registration(repository, path)
        if checkout.name in removed:
            if registration is not None:
                raise Refusal(
                    f"Git registration reappeared for removed absent checkout {checkout.name}"
                )
        elif registration is not None:
            _assert_absent_agent_registration(checkout, witness, registration)
            # A rescue ref and an existing remote ref both preserve only the
            # recorded HEAD, so both dispositions need this. A resumed recovery
            # can find a preserved HEAD pruned from the local repository, when
            # nothing can be compared with it here; before removing this
            # registration, _recover_absent_agent_row fetches it back from the
            # remote ref that preserves it and makes this check under Git's
            # index lock.
            if checkout.name not in preserved or vcs.commit_present(
                repository, checkout.head
            ):
                _assert_absent_agent_worktree_state_preserved(
                    vcs,
                    repository,
                    path,
                    checkout,
                    authority,
                    "the ACTIVE row and Git registrations"
                    if containment is None
                    else "the ACTIVE row, the recovery journal, and the remaining "
                    "Git registrations",
                )
            _assert_absent_agent_modules_preserved(
                vcs,
                repository,
                path,
                checkout,
                "the ACTIVE row and Git registrations"
                if containment is None
                else "the ACTIVE row, the recovery journal, and the remaining "
                "Git registrations",
                None
                if module_salvage is None
                else module_salvage.get(checkout.name, {}),
                record=record,
            )
    return _absent_agent_planned_receipts(
        record,
        branch_witnesses,
        containment=found if containment is None else containment,
    )


def _absent_agent_planned_receipts(
    record: ActiveRecord,
    branch_witnesses: Sequence[_AbsentAgentBranchWitness],
    *,
    include_branch_witness: bool = True,
    rescue_root: str | None = None,
    containment: Mapping[str, tuple[str, str]] | None = None,
) -> tuple[dict[str, object], ...]:
    if len(branch_witnesses) != len(record.checkouts):
        raise StateError("absent-agent branch witness count differs from checkout count")
    if containment and not include_branch_witness:
        raise StateError("absent-agent remote containment requires branch witnesses")
    receipts: list[dict[str, object]] = []
    for checkout, witness in zip(record.checkouts, branch_witnesses, strict=True):
        existing = None if containment is None else containment.get(checkout.name)
        receipt: dict[str, object]
        if existing is None:
            receipt = {
                "checkout": checkout.name,
                "source_head": checkout.head,
                "salvage_commit": checkout.head,
                "status_sha256": None,
                "disposition": "salvaged",
                "remote_ref": _absent_agent_rescue_ref(
                    record, checkout, root=rescue_root
                ),
                "containing_remote_refs": [],
                "working_tree_contents": "unknown-storage-absent-before-recovery",
            }
        else:
            # Recovery pushes nothing for this checkout: remote_ref names the
            # existing remote ref that already contained the recorded HEAD, and
            # remote_ref_tip is the tip that ref had when recovery was planned.
            receipt = {
                "checkout": checkout.name,
                "source_head": checkout.head,
                "salvage_commit": checkout.head,
                "status_sha256": None,
                "disposition": _ABSENT_AGENT_ALREADY_ON_REMOTE,
                "remote_ref": existing[0],
                "remote_ref_tip": existing[1],
                "containing_remote_refs": [existing[0]],
                "working_tree_contents": "unknown-storage-absent-before-recovery",
            }
        if include_branch_witness:
            receipt["local_branch"] = _absent_agent_branch_witness_to_obj(witness)
            receipt["local_branch_rescue"] = (
                "not-applicable-absent"
                if witness.head is None
                else (
                    "same-commit-as-recorded-head"
                    if witness.head == checkout.head
                    else "no-separate-ref-left-untouched"
                )
            )
        receipts.append(receipt)
    return tuple(receipts)


def _absent_agent_branch_validation(receipt: Mapping[str, object]) -> str:
    checkout = _as_str(receipt.get("checkout"), "absent-agent receipt.checkout")
    witness = _absent_agent_branch_witness_from_obj(
        receipt.get("local_branch"), "absent-agent receipt.local_branch"
    )
    observed = witness.head or "absent"
    disposition = _as_str(
        receipt.get("local_branch_rescue"),
        "absent-agent receipt.local_branch_rescue",
    )
    already_on_remote = receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE
    remote_ref = receipt.get("remote_ref")
    existing_ref = (
        _display_ref(remote_ref) if isinstance(remote_ref, str) else remote_ref
    )
    if disposition == "not-applicable-absent" and witness.head is None:
        detail = (
            "had no tip; the recorded HEAD was already contained in existing remote "
            f"ref {existing_ref}"
            if already_on_remote
            else "had no tip to include in the recorded-HEAD rescue ref"
        )
    elif (
        disposition == "same-commit-as-recorded-head"
        and witness.head == receipt.get("source_head")
    ):
        detail = (
            "named the recorded HEAD, which existing remote ref "
            f"{existing_ref} already contained"
            if already_on_remote
            else "named the same commit as the recorded HEAD rescue ref"
        )
    elif disposition == "no-separate-ref-left-untouched" and witness.head is not None:
        detail = (
            "received no rescue ref; only the recorded HEAD "
            f"{receipt.get('source_head')} was checked against existing remote ref "
            f"{existing_ref}"
            if already_on_remote
            else "received no separate rescue ref; the recorded-HEAD rescue ref targets "
            f"{receipt.get('source_head')}"
        )
    else:
        raise StateError("absent-agent local branch rescue disposition is inconsistent")
    return (
        f"checkout {checkout}: recovery issued no source-repository command targeting "
        f"local branch {witness.branch_ref} for mutation; checks immediately before "
        f"and after registration reconciliation matched witnessed state {observed}, "
        f"then that witness expired when the removal marker became durable and asserts "
        f"no later branch state; {detail}"
    )


def _absent_agent_archive_entry(
    record: ActiveRecord,
    item: AbsentAgentRow,
    finished_at: str,
    receipts: Sequence[Mapping[str, object]],
    submodules: Sequence[Mapping[str, object]] = (),
) -> dict[str, object]:
    branch_receipts = ["local_branch" in receipt for receipt in receipts]
    if any(branch_receipts) and not all(branch_receipts):
        raise StateError("absent-agent receipts mix legacy and branch-witness shapes")
    has_branch_witnesses = bool(branch_receipts and branch_receipts[0])
    distinct_branch_tip = any(
        receipt.get("local_branch_rescue") == "no-separate-ref-left-untouched"
        for receipt in receipts
    )
    already_on_remote = any(
        receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE
        for receipt in receipts
    )
    if already_on_remote and not has_branch_witnesses:
        raise StateError("absent-agent remote containment requires branch witnesses")
    return {
        "archive_id": f"{record.machine}:{record.slot}:{record.generation}:{finished_at}",
        "slot": record.slot,
        "agent": record.agent,
        "task": record.task,
        "purpose": record.purpose,
        "slot_type": "agent",
        "machine": record.machine,
        "generation": record.generation,
        "created_at": record.created_at,
        "finished_at": finished_at,
        "mode": "remove",
        "actor": "coordinator",
        "physical_storage": "removed",
        "validation": [
            "registry reconciliation confirmed physical storage externally absent",
            f"source ACTIVE record SHA-256: {item.record_sha256}",
            *(
                (
                    f"checkout {receipt['checkout']}: recorded slot HEAD "
                    f"{receipt['source_head']} was already contained in existing remote "
                    f"ref {_display_ref(_as_str(receipt['remote_ref'], 'receipt.remote_ref'))} "
                    f"at tip {receipt['remote_ref_tip']}; "
                    "recovery pushed nothing and re-verified the containment with git "
                    "merge-base --is-ancestor against a freshly fetched copy of that ref"
                    if receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE
                    else f"checkout {receipt['checkout']}: recorded slot HEAD "
                    f"{receipt['source_head']} preserved at remote rescue ref "
                    f"{receipt['remote_ref']} and read back at {receipt['salvage_commit']}"
                    if has_branch_witnesses
                    else f"checkout {receipt['checkout']}: remote rescue ref "
                    f"{receipt['remote_ref']} read back at {receipt['salvage_commit']}"
                )
                for receipt in receipts
            ),
            *(
                _absent_agent_branch_validation(receipt)
                for receipt in receipts
                if has_branch_witnesses
            ),
            *(_absent_agent_module_validation(receipt) for receipt in submodules),
        ],
        "limitations": [
            "working-tree contents were absent before recovery; tracked and ordinary "
            "untracked content and HANDOFF could not be inspected or salvaged; ignored "
            "content could not be inspected and would not have been uploaded",
            *(
                [
                    "local branch witnesses cover only registration reconciliation; "
                    "no branch state after the durable removal marker is asserted"
                ]
                if has_branch_witnesses
                else []
            ),
            *(
                [
                    "local branch tips distinct from the recorded slot HEAD were left "
                    "untouched in source repositories; no separate rescue refs were "
                    "created to target those exact tips"
                ]
                if distinct_branch_tip
                else []
            ),
            *(
                [
                    "a recorded HEAD found in an existing remote ref stays preserved "
                    "only while that ref, which recovery neither created nor protects, "
                    "still contains it"
                ]
                if already_on_remote
                else []
            ),
            *(
                [
                    "submodule repositories Git kept for the checkouts under "
                    "<common>/worktrees/<id>/modules were moved intact, reflogs "
                    "included, to <common>/"
                    f"{_WORKTREE_MODULES_RETAINED}/{record.slot}+{record.generation}"
                    f"+{_record_sha256(record)[:16]}+<id>/modules before each "
                    "registration was removed, and "
                    "recovery never deletes them; at the final census every commit "
                    "their HEADs, refs and reflogs named and every commit they "
                    "stored themselves, whether named or not, was compared with "
                    "their remote-tracking refs and those of the shared repository, "
                    "and each reachable from none of those was salvaged; none they "
                    "read through objects/info/alternates was left both unreachable "
                    "from those and unsalvaged; a commit written "
                    "there later, by a process already holding a handle inside "
                    "them, is kept there but recorded nowhere; a commit found in a "
                    "remote-tracking ref stays preserved only while that remote "
                    "still holds it"
                ]
                if submodules
                else []
            ),
        ],
        "continuation": (
            "physical storage was already absent; inspect each checkout's verified "
            "remote ref, either a rescue ref this recovery pushed or an existing ref "
            "that already contained the recorded HEAD, and re-read every local branch "
            "ref because its historical witness has expired"
            if already_on_remote
            else "physical storage was already absent; inspect the verified recorded-HEAD "
            "rescue refs and re-read every local branch ref because its historical "
            "witness has expired"
            if has_branch_witnesses
            else "physical storage was already absent; inspect the verified rescue refs"
        ),
        "salvage": [
            *(dict(receipt) for receipt in receipts),
            *(dict(receipt) for receipt in submodules),
        ],
        "checkouts": [_checkout_to_obj(checkout) for checkout in record.checkouts],
        **({"layout": record.layout} if record.layout is not None else {}),
        **(
            {"import_source": _import_source_to_obj(record.import_source)}
            if record.import_source is not None
            else {}
        ),
    }


def _archive_matches_absent_agent_row(
    archive: ArchiveState, archived: Mapping[str, object], item: AbsentAgentRow
) -> bool:
    validation = archived.get("validation")
    return bool(
        archive.machine == item.machine
        and archived.get("slot") == item.slot
        and archived.get("machine") == item.machine
        and archived.get("generation") == item.generation
        and archived.get("slot_type") == "agent"
        and archived.get("physical_storage") == "removed"
        and isinstance(validation, list)
        and f"source ACTIVE record SHA-256: {item.record_sha256}" in validation
        and (item.slot, item.generation, item.record_sha256)
        in archive.absent_agent_recoveries
    )


def _absent_agent_event_evidence(
    item: AbsentAgentRow, archive_entry: Mapping[str, object]
) -> dict[str, object]:
    return {
        "archive_id": _as_str(archive_entry.get("archive_id"), "absent-agent archive_id"),
        "source_record_sha256": item.record_sha256,
        "physical_storage": "externally-absent",
    }


def _absent_agent_receipt_containment(
    receipts: Sequence[Mapping[str, object]],
) -> dict[str, tuple[str, str]]:
    """Return checkout name -> (existing remote ref, planned tip) for receipts
    whose recorded HEAD was already on the remote."""

    return {
        _as_str(receipt.get("checkout"), "absent-agent receipt.checkout"): (
            _as_str(receipt.get("remote_ref"), "absent-agent receipt.remote_ref"),
            _as_str(receipt.get("remote_ref_tip"), "absent-agent receipt.remote_ref_tip"),
        )
        for receipt in receipts
        if receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE
    }


def _absent_agent_containment_to_obj(
    containment: Mapping[str, tuple[str, str]],
) -> list[dict[str, object]]:
    return [
        {"checkout": name, "remote_ref": ref, "tip": tip}
        for name, (ref, tip) in containment.items()
    ]


def _absent_agent_containment_from_journal(
    raw: Mapping[str, object], record: ActiveRecord, legacy_branches: bool
) -> dict[str, tuple[str, str]]:
    if "remote_containment" not in raw:
        return {}
    if legacy_branches:
        raise StateError("absent-agent-row remote containment requires branch witnesses")
    entries = _as_list(
        raw["remote_containment"], "absent-agent-row journal.remote_containment"
    )
    if not entries:
        raise StateError("absent-agent-row journal.remote_containment is empty")
    order = [checkout.name for checkout in record.checkouts]
    containment: dict[str, tuple[str, str]] = {}
    for index, value in enumerate(entries):
        label = f"absent-agent-row journal.remote_containment[{index}]"
        entry = _as_mapping(value, label)
        _exact_keys(entry, {"checkout", "remote_ref", "tip"}, set(), label)
        name = _as_str(entry["checkout"], f"{label}.checkout")
        ref = _as_str(entry["remote_ref"], f"{label}.remote_ref")
        tip = _as_str(entry["tip"], f"{label}.tip")
        try:
            _validate_git_ref_name(ref, f"{label}.remote_ref")
        except Refusal as exc:
            raise StateError(f"{label}.remote_ref is invalid") from exc
        if SHA_RE.fullmatch(tip) is None:
            raise StateError(f"{label}.tip must be one full object SHA")
        if name not in order or name in containment:
            raise StateError(f"{label}.checkout must name one distinct recorded checkout")
        containment[name] = (ref, tip)
    if list(containment) != [name for name in order if name in containment]:
        raise StateError("absent-agent-row remote containment is not in checkout order")
    return containment


def _absent_agent_journal_inputs(
    config: Config, raw: Mapping[str, object]
) -> tuple[
    AbsentAgentRow,
    ActiveRecord,
    tuple[_AbsentAgentBranchWitness, ...],
    tuple[Mapping[str, object], ...],
    dict[str, object],
]:
    _exact_keys(
        raw,
        _ABSENT_AGENT_JOURNAL_REQUIRED,
        _ABSENT_AGENT_JOURNAL_OPTIONAL,
        "absent-agent-row journal",
    )
    if (
        _as_int(raw["schema"], "absent-agent-row journal.schema") != SCHEMA
        or raw["kind"] != "recover-absent-agent-row"
        or raw["machine"] != config.machine
    ):
        raise StateError("absent-agent-row journal identity is invalid")
    item = _absent_agent_row_identity(raw["input"], "absent-agent-row journal.input")
    if item.machine != config.machine or raw["slot"] != item.slot:
        raise StateError("absent-agent-row journal row identity is invalid")
    if not _as_str(raw["host_id"], "absent-agent-row journal.host_id"):
        raise StateError("absent-agent-row journal has no stable host identity")
    if _identity_from_obj(raw["actor"], "absent-agent-row journal.actor") is None:
        raise StateError("absent-agent-row journal has no actor")
    phase = _as_str(raw["phase"], "absent-agent-row journal.phase")
    if phase not in {"prepared", "preserved", "registrations-removed"}:
        raise StateError(f"unknown absent-agent-row phase {phase!r}")
    record = _record_from_obj(raw["record"], "absent-agent-row journal.record")
    _validate_absent_agent_row(record, item)
    legacy_branches = "branch_witnesses" not in raw
    branch_witnesses = (
        tuple(
            _AbsentAgentBranchWitness(
                checkout=checkout.name,
                branch_ref=f"refs/heads/{checkout.branch}",
                state="present",
                head=checkout.head,
            )
            for checkout in record.checkouts
        )
        if legacy_branches
        else tuple(
            _absent_agent_branch_witness_from_obj(
                value, f"absent-agent-row journal.branch_witnesses[{index}]"
            )
            for index, value in enumerate(
                _as_list(
                    raw["branch_witnesses"],
                    "absent-agent-row journal.branch_witnesses",
                )
            )
        )
    )
    if len(branch_witnesses) != len(record.checkouts):
        raise StateError(
            "absent-agent-row branch witness count differs from checkout count"
        )
    for checkout, witness in zip(record.checkouts, branch_witnesses, strict=True):
        if (
            witness.checkout != checkout.name
            or witness.branch_ref != f"refs/heads/{checkout.branch}"
        ):
            raise StateError(
                f"absent-agent-row branch witness differs from checkout {checkout.name}"
            )
    containment = _absent_agent_containment_from_journal(raw, record, legacy_branches)
    submodules = _absent_agent_submodule_salvage_from_journal(raw, record)
    receipts = tuple(
        _as_mapping(value, f"absent-agent-row journal.preserved[{index}]")
        for index, value in enumerate(_as_list(raw["preserved"], "absent-agent-row journal.preserved"))
    )
    removed = tuple(
        _as_str(value, f"absent-agent-row journal.removed[{index}]")
        for index, value in enumerate(_as_list(raw["removed"], "absent-agent-row journal.removed"))
    )
    names = {checkout.name for checkout in record.checkouts}
    if len(receipts) > len(record.checkouts) or len(removed) > len(record.checkouts):
        raise StateError("absent-agent-row journal progress exceeds its checkout count")
    if {str(value.get("checkout")) for value in receipts} - names or set(removed) - names:
        raise StateError("absent-agent-row journal names an unrelated checkout")
    archive_entry = dict(
        _as_mapping(raw["archive_entry"], "absent-agent-row journal.archive_entry")
    )
    finished_at = _as_str(archive_entry.get("finished_at"), "absent-agent archive.finished_at")
    _parse_timestamp(finished_at, "absent-agent archive.finished_at")
    # A journal written before rescue refs left refs/heads/ planned the legacy
    # destination and may already have pushed to it. Resume such a journal at
    # exactly the destination it recorded; never re-plan it to the new root.
    for rescue_root in (
        ABSENT_AGENT_RESCUE_REF_ROOT,
        LEGACY_ABSENT_AGENT_RESCUE_REF_ROOT,
    ):
        expected_receipts = _absent_agent_planned_receipts(
            record,
            branch_witnesses,
            include_branch_witness=not legacy_branches,
            rescue_root=rescue_root,
            containment=containment,
        )
        expected_archive = _absent_agent_archive_entry(
            record, item, finished_at, expected_receipts, submodules
        )
        if _json_equal(archive_entry, expected_archive):
            break
    else:
        raise StateError("absent-agent-row archive entry differs from its exact inputs")
    for index, receipt in enumerate(receipts):
        if not _json_equal(receipt, expected_receipts[index]):
            raise StateError("absent-agent-row preserved receipts are not a durable prefix")
    if tuple(removed) != tuple(checkout.name for checkout in record.checkouts[: len(removed)]):
        raise StateError("absent-agent-row removed registrations are not a durable prefix")
    if removed and (
        phase == "prepared" or len(receipts) != len(record.checkouts)
    ):
        raise StateError(
            "absent-agent-row removed registrations precede durable remote preservation"
        )
    if phase in {"preserved", "registrations-removed"} and len(receipts) != len(
        record.checkouts
    ):
        raise StateError("absent-agent-row journal phase precedes complete remote preservation")
    if phase == "registrations-removed" and len(removed) != len(record.checkouts):
        raise StateError("absent-agent-row journal phase precedes complete registration removal")
    return item, record, branch_witnesses, expected_receipts, archive_entry


def _assert_absent_agent_safe(
    config: Config,
    record: ActiveRecord,
    branch_witnesses: Sequence[_AbsentAgentBranchWitness] | None = None,
    removed: AbstractSet[str] = frozenset(),
    *,
    preserved: AbstractSet[str] = frozenset(),
    containment: Mapping[str, tuple[str, str]] | None = None,
    module_salvage: Mapping[str, Mapping[str, AbstractSet[str]]] | None,
) -> tuple[
    tuple[Path, ...],
    tuple[_AbsentAgentBranchWitness, ...],
    tuple[dict[str, object], ...],
]:
    _assert_absent_validate_rows_not_held(config, (record,))
    paths = _assert_absent_agent_storage(config, record)
    _assert_handoff_read(
        config,
        record,
        _slot_directory(config, record.slot, record.slot_type),
    )
    _assert_absent_agent_liveness(config, record, paths)
    vcs = _GitVcs()
    selected_witnesses = (
        tuple(branch_witnesses)
        if branch_witnesses is not None
        else _absent_agent_branch_witnesses(config, record, vcs)
    )
    receipts = _absent_agent_checkout_receipts(
        config,
        record,
        vcs,
        selected_witnesses,
        removed,
        preserved=preserved,
        containment=containment,
        module_salvage=module_salvage,
    )
    return paths, selected_witnesses, receipts


def _recover_absent_agent_row(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
) -> None:
    if path != _journal_path(config):
        raise StateError("absent-agent-row journal filename is invalid")
    if raw.get("host_id") != _host_id():
        raise Refusal("absent-agent-row journal belongs to another host identity")
    _assert_caller_process(coordinator, "coordinator")
    item, recorded, branch_witnesses, planned, archive_entry = (
        _absent_agent_journal_inputs(config, raw)
    )
    state = _load_active(config)
    current = next((row for row in state.slots if row.slot == item.slot), None)
    archive = _load_archive(config)
    archived = next(
        (row for row in archive.records if row.get("archive_id") == archive_entry["archive_id"]),
        None,
    )
    if current is None:
        if archived is None or not _json_equal(archived, archive_entry):
            raise StateError("absent agent row disappeared without its exact archive")
        _remove_handoff_sidecar_after_archive(config, recorded)
        _clear_journal(config, raw)
        print(f"recovered absent agent row={item.slot}")
        return
    if _record_to_obj(current) != _record_to_obj(recorded):
        raise StateError(f"agent row {item.slot} differs from its journal snapshot")
    removed_names = tuple(
        _as_str(value, f"absent-agent-row journal.removed[{index}]")
        for index, value in enumerate(
            _as_list(raw["removed"], "absent-agent-row journal.removed")
        )
    )
    preserved_count = len(
        _as_list(raw["preserved"], "absent-agent-row journal.preserved")
    )
    preserved_names = frozenset(
        checkout.name for checkout in recorded.checkouts[:preserved_count]
    )
    containment = _absent_agent_receipt_containment(planned)
    submodules = _absent_agent_submodule_salvage_from_journal(raw, recorded)
    module_salvage = _absent_agent_module_salvaged(submodules)
    vcs = _GitVcs()
    # A recovery stopped before it removed a checkout's registration may have
    # left that checkout's submodule repositories set aside, or where it keeps
    # them. Move them back first, so every check below, including that their
    # salvage is intact, examines them where Git keeps them; this refuses,
    # and leaves them where they are kept, if Git began removing the
    # registration (_restore_worktree_modules_retained). An administrative
    # directory Git no longer lists is not among these: its registration is
    # gone, and what recovery kept stays kept.
    for administration in _absent_agent_doomed_administrations(
        config, recorded, frozenset(removed_names), vcs
    ).values():
        _restore_worktree_modules_set_aside(
            administration, _worktree_modules_retained(administration, recorded)
        )
    _assert_absent_agent_safe(
        config,
        current,
        branch_witnesses,
        frozenset(removed_names),
        preserved=preserved_names,
        containment=containment,
        module_salvage=module_salvage,
    )
    journal = dict(raw)
    preserved = [
        dict(_as_mapping(value, f"preserved[{index}]"))
        for index, value in enumerate(_as_list(journal["preserved"], "preserved"))
    ]
    authorities: list[_RemoteAuthority] = []
    for checkout in recorded.checkouts:
        _stored, repository = _stored_repository_path(config, checkout.repository)
        authority = vcs.remote_authority(repository, checkout.remote)
        if not _recorded_remote_names_same_repository(
            checkout.remote_url_sha256, authority
        ):
            raise Refusal(
                f"source repository remote changed for absent checkout {checkout.name}"
            )
        authorities.append(authority)
    for checkout, receipt, authority in zip(
        recorded.checkouts[len(preserved) :],
        planned[len(preserved) :],
        authorities[len(preserved) :],
    ):
        _stored, repository = _stored_repository_path(config, checkout.repository)
        # An already-on-remote receipt pushes nothing: _assert_absent_agent_safe
        # above re-verified that its existing remote ref still contains the
        # recorded HEAD. Every other receipt pushes a rescue ref, and
        # _assert_absent_agent_safe refused unless salvage_push_remotes lists
        # that checkout's remote.
        if receipt.get("disposition") != _ABSENT_AGENT_ALREADY_ON_REMOTE:
            vcs.push_salvage(
                repository,
                checkout.remote,
                checkout.head,
                _as_str(receipt["remote_ref"], "agent-row rescue ref"),
                authority,
            )
        preserved.append(dict(receipt))
        journal["preserved"] = preserved
        _write_journal(config, journal)
        _interrupt_for_test("after-absent-agent-rescue-ref")
    for checkout, receipt, authority in zip(recorded.checkouts, planned, authorities):
        remote_ref = _as_str(receipt["remote_ref"], "agent-row rescue ref")
        _stored, repository = _stored_repository_path(config, checkout.repository)
        if receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE:
            if (
                vcs.remote_ref_contains_commit(
                    repository, checkout.remote, remote_ref, checkout.head, authority
                )
                is None
            ):
                raise Refusal(
                    f"existing remote ref {_display_ref(remote_ref)} for {checkout.name} "
                    "no longer "
                    "contains its HEAD"
                )
        elif (
            vcs.remote_ref_sha(
                repository, checkout.remote, remote_ref, authority
            )
            != checkout.head
        ):
            raise Refusal(f"remote rescue ref for {checkout.name} no longer preserves its HEAD")
    # Submodule salvage completed before the journal was written; re-read it
    # here, with the other remote checks, before any registration is removed.
    salvage_rechecks = _assert_absent_agent_module_salvage_intact(
        config, recorded, submodules, frozenset(removed_names), vcs
    )
    journal["phase"] = "preserved"
    _write_journal(config, journal)
    removed = list(removed_names)
    for checkout, witness, receipt, authority in zip(
        recorded.checkouts[len(removed) :],
        branch_witnesses[len(removed) :],
        planned[len(removed) :],
        authorities[len(removed) :],
        strict=True,
    ):
        _stored, repository = _stored_repository_path(config, checkout.repository)
        checkout_path = _stored_path(config, checkout.path, "agent checkout path").absolute()
        _assert_absent_agent_branch_witness(repository, checkout, witness, vcs)
        registration = vcs.worktree_registration(repository, checkout_path)
        if registration is not None:
            _assert_absent_agent_registration(checkout, witness, registration)
            retained = (
                "the ACTIVE row, the recovery journal, and this checkout's Git "
                "registration"
            )
            if receipt.get("disposition") == _ABSENT_AGENT_ALREADY_ON_REMOTE:
                # Nothing recovery pushed preserves this HEAD, so check the
                # existing ref again before this registration, not just before
                # the first one, is removed. Every remote operation precedes
                # the index lock below; every check under it is local.
                remote_ref = _as_str(receipt["remote_ref"], "agent-row containing ref")
                if (
                    vcs.remote_ref_contains_commit(
                        repository, checkout.remote, remote_ref, checkout.head, authority
                    )
                    is None
                ):
                    raise Refusal(
                        f"existing remote ref {_display_ref(remote_ref)} stopped "
                        "containing the "
                        f"recorded HEAD {checkout.head} of absent checkout "
                        f"{checkout.name} before its Git registration was removed. "
                        f"state: REFUSED -- {retained} were retained. remedy: restore "
                        "a remote ref containing that commit, then rerun recover"
                    )
            if not vcs.commit_present(repository, checkout.head):
                # A resumed recovery can find the preserved HEAD pruned from
                # the local repository. Fetch it back, as objects only, from
                # the remote ref that preserves it, so the checks below can
                # compare this worktree's index and refs with it.
                remote_ref = _as_str(receipt["remote_ref"], "agent-row preserving ref")
                if (
                    vcs.remote_ref_contains_commit(
                        repository, checkout.remote, remote_ref, checkout.head, authority
                    )
                    is None
                ):
                    raise Refusal(
                        f"the local repository no longer holds the recorded HEAD "
                        f"{checkout.head} of absent checkout {checkout.name}, and remote "
                        f"ref {_display_ref(remote_ref)} no longer contains it, so its Git "
                        f"registration cannot be checked. state: REFUSED -- {retained} "
                        "were retained. remedy: restore a remote ref containing that "
                        "commit, then rerun recover"
                    )
            # Holding Git's index lock keeps any Git command from staging or
            # committing in this worktree from these checks until the removal,
            # which deletes the lock with the administrative directory. The
            # submodule repositories kept there are moved aside first, so no
            # Git command can reach them by their path after they are
            # examined, and then out of the administrative directory, so
            # removing the registration deletes none of them
            # (_GitVcs.worktree_modules_set_aside).
            with vcs.worktree_index_locked(
                repository, checkout_path
            ) as administration, vcs.worktree_modules_set_aside(
                administration, keep := _worktree_modules_retained(administration, recorded)
            ) as retain_modules:
                registration = vcs.worktree_registration(repository, checkout_path)
                if registration is None:
                    raise Refusal(
                        f"Git registration for absent checkout {checkout.name} "
                        f"disappeared during recovery. state: REFUSED -- {retained} "
                        "were retained. remedy: rerun recover"
                    )
                _assert_absent_agent_registration(checkout, witness, registration)
                _assert_absent_agent_branch_witness(repository, checkout, witness, vcs)
                _assert_absent_agent_worktree_state_preserved(
                    vcs, repository, checkout_path, checkout, authority, retained
                )
                examined_modules = _assert_absent_agent_modules_preserved(
                    vcs,
                    repository,
                    checkout_path,
                    checkout,
                    retained,
                    module_salvage.get(checkout.name, {}),
                    record=recorded,
                    set_aside=True,
                )
                # Remote preservation can take long enough for the missing path
                # to reappear. Refuse before asking Git to remove the
                # registration so the ordinary `git worktree remove --force`
                # path does not knowingly delete newly materialized storage.
                _assert_absent_agent_storage(config, recorded)
                # A mount made since the census would have Git delete what
                # it holds; check before anything is moved. Once the
                # repositories are kept, check again, as late as anything
                # can be checked, the mounts and every storage check
                # retention depends on.
                _refuse_mounts_below_administration(administration)
                kept_identity = retain_modules()
                try:
                    _refuse_unretainable_retained_storage(
                        administration, keep, kept_identity
                    )
                    if kept_identity is not None:
                        _refuse_unexamined_retained_repositories(
                            administration, keep, examined_modules
                        )
                    # What each salvage rests on, checked again here: a
                    # rename or bind mount made since the salvages were
                    # read could carry it into this administrative
                    # directory. Every check here reads only this host.
                    for recheck in salvage_rechecks:
                        recheck()
                    vcs.remove_worktree(repository, checkout_path, force=True)
                except Refusal as exc:
                    # A check refused, or Git may have stopped partway
                    # through deleting the administrative directory; either
                    # way the repositories stay where they were moved
                    # (_GitVcs.worktree_modules_set_aside).
                    raise Refusal(
                        f"{exc}. The submodule repositories of absent checkout "
                        f"{checkout.name}, if it had any, stay at "
                        f"{keep.path / 'modules'}. remedy: rerun recover, which "
                        "moves them back while Git's registration is intact"
                    ) from exc
        if vcs.worktree_registration(repository, checkout_path) is not None:
            raise Refusal(f"Git still registers absent checkout {checkout.name}")
        _assert_absent_agent_branch_witness(repository, checkout, witness, vcs)
        removed.append(checkout.name)
        journal["removed"] = removed
        _write_journal(config, journal)
        _interrupt_for_test("after-absent-agent-registration-remove")
    journal["phase"] = "registrations-removed"
    _write_journal(config, journal)
    _assert_absent_agent_safe(
        config,
        current,
        branch_witnesses,
        frozenset(checkout.name for checkout in recorded.checkouts),
        preserved=frozenset(checkout.name for checkout in recorded.checkouts),
        containment=containment,
        module_salvage=module_salvage,
    )
    if archived is None:
        archive = _append_archive_once(
            config,
            archive,
            archive_entry,
            action="absent-agent-row-recovered",
            evidence=_absent_agent_event_evidence(item, archive_entry),
        )
        _interrupt_for_test("after-absent-agent-archive")
    elif not _json_equal(archived, archive_entry):
        raise StateError("durable absent-agent archive differs from its journal")
    state = _load_active(config)
    current = next((row for row in state.slots if row.slot == item.slot), None)
    if current is not None:
        _validate_absent_agent_row(current, item)
        _write_active_state(
            config,
            _delete_record(state, item.slot),
            action="absent-agent-row-recovered",
            slot=item.slot,
            evidence=_absent_agent_event_evidence(item, archive_entry),
        )
        _interrupt_for_test("after-absent-agent-active-delete")
    _remove_handoff_sidecar_after_archive(config, recorded)
    _clear_journal(config, journal)
    print(f"recovered absent agent row={item.slot}")


def _absent_agent_recovery_coordinator(
    config: Config, args: argparse.Namespace
) -> ProcessIdentity | None:
    """Check the host and, for --apply, capture the authorizing coordinator."""

    if config.machine != _short_hostname():
        raise Refusal("absent agent row recovery must run on the row's machine")
    if args.apply:
        _require_coordinator_authorized(args, "absent agent row recovery")
        if args.coordinator_pid is None:
            raise Refusal("--apply requires --coordinator-pid")
        return _capture_caller_process(args.coordinator_pid, "coordinator")
    return None


def _recover_absent_agent_row_item(
    config: Config,
    item: AbsentAgentRow,
    *,
    apply: bool,
    coordinator: ProcessIdentity | None,
    wait_seconds: float,
) -> str:
    """Plan or recover one exact absent agent row inside one registry-lock hold.

    Returns ``would-recover`` or ``would-resume`` for a plan, and
    ``already-recovered`` or ``recovered``; any refusal is raised.
    Everything it prints is the single-row command's output.
    """

    with _mutation_locks(config, wait_seconds):
        _refuse_partial_state(config)
        if _outstanding_journals(config):
            path, raw = _load_journal(config)
            if raw.get("kind") != "recover-absent-agent-row":
                raise Refusal(f"another interrupted mutation is recorded in {path}")
            journal_item, _record, _branches, _planned, _archive = (
                _absent_agent_journal_inputs(config, raw)
            )
            if journal_item != item:
                raise Refusal("requested agent row differs from the interrupted recovery")
            if not apply:
                print(f"ROW machine={item.machine} slot={item.slot} outcome=planned detail=resume")
                return "would-resume"
            assert coordinator is not None
            _recover_absent_agent_row(config, path, raw, coordinator)
            return "recovered"
        states, archives = _validate_global_state(config)
        before = _global_rows(states, archives)
        state = next(value for value in states if value.machine == config.machine)
        record = next((value for value in state.slots if value.slot == item.slot), None)
        if record is None:
            matching = [
                archived
                for archive in archives
                for archived in archive.records
                if archived.get("slot") == item.slot
            ]
            if len(matching) == 1 and any(
                _archive_matches_absent_agent_row(archive, matching[0], item)
                for archive in archives
                if archive.machine == item.machine
            ):
                print(
                    f"ROW machine={item.machine} slot={item.slot} "
                    f"generation={item.generation} outcome=already-recovered"
                )
                return "already-recovered"
            raise Refusal(
                f"agent row {item.machine}/{item.slot} is neither active nor an exact prior recovery"
            )
        _validate_absent_agent_row(record, item)
        _paths, branch_witnesses, receipts = _assert_absent_agent_safe(
            config, record, module_salvage=None
        )
        # Removing a registration takes the submodule repositories Git keeps
        # for that checkout out of Git's reach, so their unpublished commits
        # are salvaged before the journal exists: a salvage that refuses
        # leaves no journal to block other rows, and a rerun salvages again
        # idempotently.
        submodules = _salvage_absent_agent_modules(
            config, record, _GitVcs(), apply=apply
        )
        if not apply:
            rendered_witnesses = json.dumps(
                [
                    _absent_agent_branch_witness_to_obj(witness)
                    for witness in branch_witnesses
                ],
                sort_keys=True,
                separators=(",", ":"),
            )
            planned_containment = _absent_agent_receipt_containment(receipts)
            rendered_containment = (
                " remote_containment="
                + json.dumps(
                    _absent_agent_containment_to_obj(planned_containment),
                    sort_keys=True,
                    separators=(",", ":"),
                )
                if planned_containment
                else ""
            )
            planned_submodules = [
                {
                    "checkout": receipt["checkout"],
                    "submodule": receipt["submodule"],
                    "unpublished_commits": receipt["unpublished_commits"],
                    "disposition": receipt["disposition"],
                }
                for receipt in submodules
                if receipt["disposition"] != _ABSENT_MODULE_PUBLISHED
            ]
            rendered_submodules = (
                " submodule_salvage="
                + json.dumps(planned_submodules, sort_keys=True, separators=(",", ":"))
                if planned_submodules
                else ""
            )
            print(
                f"ROW machine={item.machine} slot={item.slot} generation={item.generation} "
                "outcome=planned detail=physical-storage-absent "
                f"branch_witnesses={rendered_witnesses}{rendered_containment}"
                f"{rendered_submodules}"
            )
            return "would-recover"
        assert coordinator is not None
        finished_at = _utc_now()
        journal = {
            "schema": SCHEMA,
            "kind": "recover-absent-agent-row",
            "machine": config.machine,
            "host_id": _host_id(),
            "slot": item.slot,
            "phase": "prepared",
            "actor": _identity_to_obj(coordinator),
            "input": dataclasses.asdict(item),
            "record": _record_to_obj(record),
            "branch_witnesses": [
                _absent_agent_branch_witness_to_obj(witness)
                for witness in branch_witnesses
            ],
            "preserved": [],
            "removed": [],
            "archive_entry": _absent_agent_archive_entry(
                record, item, finished_at, receipts, submodules
            ),
        }
        receipt_containment = _absent_agent_receipt_containment(receipts)
        if receipt_containment:
            journal["remote_containment"] = _absent_agent_containment_to_obj(
                receipt_containment
            )
        if submodules:
            journal["submodule_salvage"] = submodules
        _write_journal(config, journal)
        _interrupt_for_test("after-absent-agent-journal")
        _recover_absent_agent_row(config, _journal_path(config), journal, coordinator)
        after_states, after_archives = _validate_global_state(config)
        _assert_only_slot_changed(before, _global_rows(after_states, after_archives), item.slot)
    return "recovered"


def _cmd_recover_absent_agent_row(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    item = AbsentAgentRow(
        machine=config.machine,
        slot=_validate_name(args.slot, "slot"),
        generation=args.expected_generation,
        record_sha256=args.record_sha256,
    )
    if not DIGEST_RE.fullmatch(item.record_sha256):
        raise Refusal("--record-sha256 must be one lowercase SHA-256 digest")
    coordinator = _absent_agent_recovery_coordinator(config, args)
    _recover_absent_agent_row_item(
        config,
        item,
        apply=bool(args.apply),
        coordinator=coordinator,
        wait_seconds=args.wait_lock,
    )
    return 0


# recover-absent-agent-rows runs the single-row recovery above, unchanged, for
# each exact row: every row gets its own registry-lock hold, its own journal,
# and all three of its safety proofs.  Measured 2026-09-29 on a 4,000-process
# host at load average 42 to 55, one row's plan took 6 to 18 seconds and its
# apply 22 to 37 seconds, all inside the lock, whether run singly or in this
# batch; about 95 percent of an apply was the all-process and user-systemd
# censuses, which it runs three times as its time-of-check proof.  Sharing
# those censuses across rows would move that proof away from the destructive
# steps it guards, so the batch shares nothing.  It releases the lock between
# rows and reports every row.


def _parse_absent_agent_row(value: str, machine: str) -> AbsentAgentRow:
    parts = value.split("=")
    if len(parts) != 3:
        raise Refusal(f"absent agent row must be SLOT=GENERATION=SHA256: {value!r}")
    slot, generation_text, digest = parts
    slot = _validate_name(slot, "slot")
    try:
        generation = int(generation_text, 10)
    except ValueError as exc:
        raise Refusal(f"absent agent row generation is not an integer: {value!r}") from exc
    if generation < 1:
        raise Refusal(f"absent agent row generation must be positive: {value!r}")
    if not DIGEST_RE.fullmatch(digest):
        raise Refusal(
            f"absent agent row record SHA-256 must be one lowercase digest: {value!r}"
        )
    return AbsentAgentRow(
        machine=machine, slot=slot, generation=generation, record_sha256=digest
    )


def _read_absent_agent_rows(
    args: argparse.Namespace, machine: str
) -> tuple[AbsentAgentRow, ...]:
    raw: list[str] = list(getattr(args, "rows", None) or ())
    input_path = getattr(args, "input", None)
    if input_path is not None:
        try:
            text = Path(input_path).read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise Refusal(f"cannot read --input {input_path}: {exc}") from exc
        for line in text.splitlines():
            stripped = line.strip()
            if stripped and not stripped.startswith("#"):
                raw.append(stripped)
    if not raw:
        raise Refusal(
            "recover-absent-agent-rows needs at least one --row or a non-empty --input"
        )
    if len(raw) > ABSENT_AGENT_ROW_BATCH_LIMIT:
        raise Refusal(
            f"recover-absent-agent-rows accepts at most {ABSENT_AGENT_ROW_BATCH_LIMIT} "
            "rows; run another bounded batch for the remainder"
        )
    rows = tuple(_parse_absent_agent_row(value, machine) for value in raw)
    if len({row.slot for row in rows}) != len(rows):
        raise Refusal("recover-absent-agent-rows received the same slot more than once")
    return rows


def _interrupted_absent_agent_row_first(
    config: Config, requested: tuple[AbsentAgentRow, ...]
) -> tuple[AbsentAgentRow, ...]:
    """Order a row with an interrupted single-row recovery journal first.

    While that journal exists every other row refuses, so a rerun of an
    interrupted batch resumes it before the rest.  This read is only an
    ordering hint taken without the lock; each row is decided under it.
    """

    try:
        if not _outstanding_journals(config):
            return requested
        _path, raw = _load_journal(config)
    except Refusal:
        return requested
    if raw.get("kind") != "recover-absent-agent-row":
        return requested
    first = [row for row in requested if row.slot == raw.get("slot")]
    return (*first, *(row for row in requested if row.slot != raw.get("slot")))


def _recover_absent_agent_rows(args: argparse.Namespace) -> dict[str, object]:
    config = _load_config(args.project_root, args.machine)
    requested = _read_absent_agent_rows(args, config.machine)
    coordinator = _absent_agent_recovery_coordinator(config, args)
    apply = bool(args.apply)
    order = {row.slot: position for position, row in enumerate(requested)}
    wait_seconds = (
        args.wait_lock if args.wait_lock > 0 else AGENT_REMOVE_BATCH_WAIT_LOCK_SECONDS
    )
    started = time.monotonic()
    rows: list[dict[str, object]] = []
    recovery_required = False
    attempts = _interrupted_absent_agent_row_first(config, requested)
    for index, item in enumerate(attempts):
        if index:
            # Waiters poll the registry lock every 50 ms; leave them a window
            # between rows so a batch never starves heartbeats.
            time.sleep(_AGENT_REMOVE_BATCH_YIELD_SECONDS)
        output = io.StringIO()
        item_started = time.monotonic()
        row: dict[str, object] = {"slot": item.slot, "generation": item.generation}
        try:
            with contextlib.redirect_stdout(output):
                outcome = _recover_absent_agent_row_item(
                    config,
                    item,
                    apply=apply,
                    coordinator=coordinator,
                    wait_seconds=wait_seconds,
                )
        except StateError as exc:
            recovery_required = True
            row.update(outcome="refused", reason=str(exc), recovery_required=True)
        except Refusal as exc:
            row.update(outcome="refused", reason=str(exc))
        else:
            row["outcome"] = outcome
        row["seconds"] = round(time.monotonic() - item_started, 3)
        row["output"] = output.getvalue().splitlines()
        rows.append(row)
        _interrupt_for_test("after-absent-agent-rows-item")
        if recovery_required:
            for later in attempts[index + 1 :]:
                rows.append(
                    {
                        "slot": later.slot,
                        "generation": later.generation,
                        "outcome": "refused",
                        "reason": "batch stopped after a state error; run 'wrkslots recover' "
                        "and retry the remaining rows",
                        "seconds": 0.0,
                        "output": [],
                    }
                )
            break
    rows.sort(key=lambda row: order[_as_str(row["slot"], "absent agent row slot")])
    counts = {
        name: sum(1 for row in rows if row["outcome"] == name)
        for name in (
            "would-recover", "would-resume", "recovered", "already-recovered", "refused",
        )
    }
    return {
        "schema": 1,
        "batch_limit": ABSENT_AGENT_ROW_BATCH_LIMIT,
        "mode": "apply" if apply else "plan",
        "requested": len(requested),
        "counts": counts,
        "rows": rows,
        "recovery_required": recovery_required,
        "seconds": round(time.monotonic() - started, 3),
    }


def _cmd_recover_absent_agent_rows(args: argparse.Namespace) -> int:
    payload = _recover_absent_agent_rows(args)
    rows = [
        _as_mapping(value, "absent agent row result")
        for value in _as_list(payload["rows"], "rows")
    ]
    counts = _as_mapping(payload["counts"], "counts")
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        print(
            f"mode={payload['mode']} requested={payload['requested']} "
            f"would_recover={counts['would-recover']} "
            f"would_resume={counts['would-resume']} "
            f"recovered={counts['recovered']} "
            f"already_recovered={counts['already-recovered']} "
            f"refused={counts['refused']} seconds={payload['seconds']}"
        )
        for row in rows:
            label = _as_str(row["outcome"], "outcome").upper()
            line = f"{label}: {row['slot']} generation={row['generation']}"
            if row["outcome"] == "refused":
                line += f" reason={row['reason']}"
            print(line)
            for text in _as_list(row["output"], "output"):
                print(f"  {text}")
        if payload["recovery_required"]:
            print("RECOVERY REQUIRED: run 'wrkslots recover' before another recovery")
    # Success means every requested row reached the requested mode's outcome:
    # would recover or resume in a plan, recovered or already recovered by
    # --apply.  Any refusal is exit status 1; a refusal of the whole batch
    # raises (exit 3).
    return 1 if counts["refused"] else 0


def _record_sha256(record: ActiveRecord) -> str:
    return _event_digest(_record_to_obj(record))


def _read_absent_validate_rows_input(
    config: Config, raw_path: str
) -> tuple[str, tuple[AbsentValidateRow, ...]]:
    candidate = Path(raw_path)
    path = candidate if candidate.is_absolute() else config.root / candidate
    limit = 1024 * 1024
    contents = _read_bounded_regular_file(path, "absent-validation-row input", limit)
    try:
        raw = _as_mapping(json.loads(contents), "absent-validation-row input")
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise Refusal(f"absent-validation-row input is not valid JSON: {exc}") from exc
    _exact_keys(raw, {"schema", "rows"}, set(), "absent-validation-row input")
    if _as_int(raw["schema"], "absent-validation-row input.schema") != 1:
        raise Refusal("absent-validation-row input schema must be 1")
    raw_rows = _as_list(raw["rows"], "absent-validation-row input.rows")
    if not raw_rows:
        raise Refusal("absent-validation-row input must name at least one row")
    if len(raw_rows) > 1024:
        raise Refusal("absent-validation-row input names more than 1024 rows")
    rows: list[AbsentValidateRow] = []
    identities: set[tuple[str, str]] = set()
    for index, value in enumerate(raw_rows):
        label = f"absent-validation-row input.rows[{index}]"
        row = _as_mapping(value, label)
        _exact_keys(
            row,
            {"machine", "slot", "generation", "record_sha256"},
            set(),
            label,
        )
        machine = _validate_name(_as_str(row["machine"], f"{label}.machine"), "machine")
        slot = _validate_name(_as_str(row["slot"], f"{label}.slot"), "slot")
        generation = _as_int(row["generation"], f"{label}.generation", minimum=1)
        digest = _as_str(row["record_sha256"], f"{label}.record_sha256")
        if not DIGEST_RE.fullmatch(digest):
            raise Refusal(f"{label}.record_sha256 must be one lowercase SHA-256 digest")
        identity = (machine, slot)
        if identity in identities:
            raise Refusal(f"absent-validation-row input repeats {machine}/{slot}")
        identities.add(identity)
        rows.append(AbsentValidateRow(machine, slot, generation, digest))
    return hashlib.sha256(contents).hexdigest(), tuple(rows)


def _absent_validate_row_paths(config: Config, record: ActiveRecord) -> tuple[Path, ...]:
    paths = [_slot_directory(config, record.slot, record.slot_type)]
    paths.extend(
        _stored_path(config, checkout.path, "validation checkout path")
        for checkout in record.checkouts
    )
    return tuple(dict.fromkeys(path.absolute() for path in paths))


def _assert_absent_validate_rows_storage(
    config: Config, records: Sequence[ActiveRecord]
) -> tuple[tuple[ActiveRecord, tuple[Path, ...]], ...]:
    rows: list[tuple[ActiveRecord, tuple[Path, ...]]] = []
    for record in records:
        _assert_record_paths(config, record)
        paths = _absent_validate_row_paths(config, record)
        for path in paths:
            if path.exists() or path.is_symlink():
                raise Refusal(
                    f"validation row {record.slot} still has physical storage at {path}"
                )
        rows.append((record, paths))

    validate_root = _validate_slots_directory(config)
    try:
        siblings = tuple(validate_root.iterdir()) if validate_root.is_dir() else ()
    except OSError as exc:
        raise Refusal(f"cannot enumerate possible fenced validation paths: {exc}") from exc
    records_by_slot = {record.slot: record for record in records}
    for sibling in siblings:
        name = sibling.name
        matched_slot: str | None = None
        if name.startswith("."):
            for marker in (".fenced.", ".ownerless-validate."):
                offset = 1
                while (index := name.find(marker, offset)) >= 0:
                    slot = name[1:index]
                    candidate_record = records_by_slot.get(slot)
                    suffix = name[index + len(marker) :]
                    if candidate_record is not None and (
                        marker == ".ownerless-validate."
                        or suffix.startswith(f"{candidate_record.generation}.")
                    ):
                        matched_slot = slot
                        break
                    offset = index + 1
                if matched_slot is not None:
                    break
        if matched_slot is not None:
            raise Refusal(
                f"validation row {matched_slot} has a possible fenced path: {sibling}"
            )

    vcs = _GitVcs()
    repositories = {
        repository
        for record in records
        for checkout in record.checkouts
        for _stored, repository in (
            _stored_repository_path(config, checkout.repository),
        )
    }
    listed_by_repository = {
        repository: set(vcs.listed_worktrees(repository))
        for repository in repositories
    }
    for record in records:
        for checkout in record.checkouts:
            _stored, repository = _stored_repository_path(config, checkout.repository)
            path = _stored_path(
                config, checkout.path, "validation checkout path"
            ).absolute()
            if path in listed_by_repository[repository]:
                raise Refusal(
                    f"Git still registers absent validation checkout {checkout.name} "
                    f"at {path}"
                )
    return tuple(rows)


def _retained_handle_path(config: Config, value: str, label: str) -> str:
    """A handle's path field joined to the project root, as written.

    It is not normalized here: ``_UnitPathResolver`` resolves it as the
    kernel does, so a ``..`` after a symlink keeps the symlink's target.
    """

    if not value:
        raise Refusal(f"{label} is empty")
    return value if os.path.isabs(value) else os.path.join(str(config.root), value)


def _retained_handle_clock_ns() -> int:
    return time.time_ns()


def _retained_handle_monotonic_ns() -> int:
    return time.monotonic_ns()


def _retained_handle_clocks() -> tuple[int, int, int]:
    """This host's realtime clock, and the bounds of its offset from the monotonic clock.

    The realtime clock is read between two readings of the monotonic clock,
    so its offset from the monotonic clock at that moment is no lower than
    the realtime reading less the later monotonic reading and no higher
    than it less the earlier one.  A pause between the reads widens these
    bounds instead of moving them.  The same three readings also come from
    a pause together with a step back that the realtime read saw and that
    was undone by the next reading, so a reading's bounds are kept whole
    and no later, narrower reading replaces them
    (``_realtime_clock_stepped_back``).  All three are in nanoseconds.
    """

    before = _retained_handle_monotonic_ns()
    realtime = _retained_handle_clock_ns()
    after = _retained_handle_monotonic_ns()
    return realtime, realtime - after, realtime - before


def _retained_handles_for_absent_rows(
    config: Config, rows: Sequence[tuple[ActiveRecord, tuple[Path, ...]]]
) -> Mapping[str, tuple[_RetainedValidationHandle, ...]]:
    handles = config.root / "ignored" / "validate" / "runs"
    if handles.is_symlink() or (handles.exists() and not handles.is_dir()):
        raise Refusal(f"retained validation handle directory is unsafe: {handles}")
    # A handle names a row when its checkout or source checkout is one of
    # the row's paths or inside one, compared as unit words are: by
    # normalized and symlink-resolved spelling and by file identity, so a
    # symlink to the slot or a directory below it names the row too.
    deadline = time.monotonic() + _RETAINED_HANDLE_CENSUS_SECONDS
    # The census's own deadline bounds its path matching, and the reading
    # of the rows' identities, in place of the judgement's.
    resolver = _UnitPathResolver(
        _UnitResolutionBudget.start(
            deadline=deadline,
            expired="retained validation handle census exceeded its time bound",
        )
    )
    targets = [
        (record.slot, resolver.row(target)) for record, paths in rows for target in paths
    ]
    matched: dict[str, list[_RetainedValidationHandle]] = {
        record.slot: [] for record, _paths in rows
    }
    handle_paths: list[Path] = []
    total_bytes = 0
    if time.monotonic() >= deadline:
        raise Refusal("retained validation handle census exceeded its time bound")
    # The clocks are read before the first handle and after the last, so a
    # step of the realtime clock while the handles are read shows in the
    # offsets the handles carry (``_realtime_clock_stepped_back``).
    started = _retained_handle_clocks()
    found: list[
        tuple[
            set[str],
            Path,
            str,
            int | None,
            int | None,
            str | None,
            tuple[int, int, int, str, int, int],
        ]
    ] = []
    if handles.is_dir():
        try:
            with os.scandir(handles) as entries:
                for directory_entry in entries:
                    if time.monotonic() >= deadline:
                        raise Refusal(
                            "retained validation handle enumeration exceeded its time bound"
                        )
                    if not directory_entry.name.endswith(".json"):
                        continue
                    if len(handle_paths) >= _RETAINED_HANDLE_COUNT_LIMIT:
                        raise Refusal(
                            "retained validation handles exceed the file-count census bound"
                        )
                    metadata = directory_entry.stat(follow_symlinks=False)
                    path = handles / directory_entry.name
                    if not stat.S_ISREG(metadata.st_mode):
                        raise Refusal(f"retained validation handle is unsafe: {path}")
                    # Only the census as a whole is bounded.  A per-handle cap
                    # of 1 MiB refused every absent-row recovery on the host
                    # because one unrelated run record was 1,303,247 bytes,
                    # while all 2,546 records together were 12,705,397 bytes
                    # (2026-10-04).
                    total_bytes += metadata.st_size
                    if total_bytes > _RETAINED_HANDLE_BYTES_LIMIT:
                        raise Refusal(
                            "retained validation handles exceed the 64 MiB census bound"
                        )
                    handle_paths.append(path)
        except Refusal:
            raise
        except OSError as exc:
            raise Refusal(
                f"cannot enumerate retained validation handles: {exc}"
            ) from exc
    if time.monotonic() >= deadline:
        raise Refusal("retained validation handle enumeration exceeded its time bound")
    handle_paths.sort()
    if time.monotonic() >= deadline:
        raise Refusal("retained validation handle enumeration exceeded its time bound")
    total_bytes = 0
    for path in handle_paths:
        try:
            contents, read = _read_regular_file_identity(
                path, "retained validation handle", _RETAINED_HANDLE_BYTES_LIMIT
            )
            # The times come from the path after the read, so a rewrite
            # that leaves the bytes, inode and size alike still differs.
            after = path.stat(follow_symlinks=False)
            if (after.st_dev, after.st_ino) != (read.device, read.inode):
                raise Refusal(
                    f"retained validation handle was replaced while it was read: {path}"
                )
            file_generation = (
                read.device,
                read.inode,
                read.size,
                read.sha256,
                after.st_mtime_ns,
                after.st_ctime_ns,
            )
            total_bytes += len(contents)
            if total_bytes > _RETAINED_HANDLE_BYTES_LIMIT:
                raise Refusal("retained validation handles exceed the 64 MiB census bound")
            if time.monotonic() >= deadline:
                raise Refusal(
                    "retained validation handle census exceeded its time bound"
                )
            # A duplicated field has no single meaning, and a permissive
            # decoder keeps the last value: an appended ``"process_identity":
            # null`` would hide a live run process, and an appended
            # ``checkout`` would move the handle off its row.
            value = _strict_json_object(
                contents, f"cannot prove retained validation handle is unrelated: {path}"
            )
        except (OSError, UnicodeError) as exc:
            raise Refusal(
                f"cannot prove retained validation handle is unrelated: {path}: {exc}"
            ) from exc
        related: set[str] = set()
        for field in ("checkout", "source_checkout"):
            raw = value.get(field)
            if raw is None:
                continue
            if not isinstance(raw, str):
                raise Refusal(
                    f"cannot prove retained validation handle is unrelated: "
                    f"{path} has a non-string {field}"
                )
            target = _retained_handle_path(config, raw, f"{path}.{field}")
            related.update(
                slot for slot, identity in targets if resolver.path_names(target, identity)
            )
            # The resolver's budget ends at the census deadline, and is
            # charged as it resolves, so one field's resolution cannot run
            # far past it.
            if time.monotonic() >= deadline:
                raise Refusal("retained validation handle census exceeded its time bound")
        if not related:
            continue
        unit = value.get("unit")
        if (
            not isinstance(unit, str)
            or not re.fullmatch(r"[A-Za-z0-9:_.@-]+\.(?:service|scope)", unit)
            or path.name != f"{unit.removesuffix('.service').removesuffix('.scope')}.json"
        ):
            raise Refusal(
                f"retained validation handle {path} has no matching exact unit identity"
            )
        raw_identity = value.get("process_identity")
        pid: int | None = None
        start_ticks: int | None = None
        boot_id: str | None = None
        if raw_identity is not None:
            identity = _as_mapping(raw_identity, f"{path}.process_identity")
            _exact_keys(
                identity,
                {"pid", "start_ticks", "boot_id"},
                set(),
                f"{path}.process_identity",
            )
            pid = _as_int(identity["pid"], f"{path}.process_identity.pid", minimum=1)
            start_ticks = _as_int(
                identity["start_ticks"],
                f"{path}.process_identity.start_ticks",
                minimum=1,
            )
            boot_id = _as_str(identity["boot_id"], f"{path}.process_identity.boot_id")
            if not boot_id:
                raise Refusal(f"retained validation handle {path} has an empty boot identity")
        found.append((related, path, unit, pid, start_ticks, boot_id, file_generation))
    finished = _retained_handle_clocks()
    # A change time within the window of the earliest realtime value either
    # reading took is recent, so a step back during the census makes more
    # handles recent, not fewer.
    stable_before_ns = min(started[0], finished[0]) - _RETAINED_HANDLE_STABLE_NS
    clock_offsets_ns = (min(started[1], finished[1]), max(started[2], finished[2]))
    for related, path, unit, pid, start_ticks, boot_id, file_generation in found:
        handle = _RetainedValidationHandle(
            path,
            unit,
            pid,
            start_ticks,
            boot_id,
            file_generation,
            recent=file_generation[5] > stable_before_ns,
            clock_offsets_ns=clock_offsets_ns,
        )
        for slot in related:
            matched[slot].append(handle)
    if time.monotonic() >= deadline:
        raise Refusal("retained validation handle census exceeded its time bound")
    return {slot: tuple(values) for slot, values in matched.items()}


def _matching_absent_validate_target(
    observed: Path,
    targets: Mapping[Path, str],
    cache: dict[Path, tuple[Path, str] | None] | None = None,
) -> tuple[Path, str] | None:
    """Name the requested target that is ``observed`` or an ancestor of it.

    ``cache`` memoizes the ancestor walk for one census, whose ``targets`` do
    not change while it runs.  The mount census asks this of every reference in
    every mount namespace on the box, and on a fleet host that is a very lopsided
    population: measured 2026-09-17, 660,432 calls over 2,124 DISTINCT paths --
    311 repeats each, and 236,895 of the calls were the single path ``/``.  The
    walk itself is cheap; asking it 660,432 times cost 7.61 of the census's 12.0
    seconds, against a 22-second whole-operation bound that also has to pay for a
    second census.  The memo changes no answer: this is a pure function of
    ``observed`` and ``targets``.
    """

    if cache is not None:
        try:
            # Not `.get`: a stored `None` is a real answer -- this path is
            # dominated by references that match nothing -- so absence has to be
            # distinguished by the KeyError rather than by the value.
            return cache[observed]
        except KeyError:
            pass
    matched: tuple[Path, str] | None = None
    for candidate in (observed, *observed.parents):
        slot = targets.get(candidate)
        if slot is not None:
            matched = (candidate, slot)
            break
    if cache is not None:
        cache[observed] = matched
    return matched


def _cgroup_matches(recorded: str, observed: str) -> bool:
    prefix = recorded.rstrip("/") or "/"
    descendant_prefix = prefix if prefix == "/" else f"{prefix}/"
    return observed == prefix or observed.startswith(descendant_prefix)


@dataclasses.dataclass(frozen=True)
class _AbsentProcessObservation:
    pid: int
    start_ticks: int
    cgroup_path: str
    mount_namespace: str
    kernel_thread: bool = False


_PF_KTHREAD = 0x00200000


@dataclasses.dataclass(frozen=True)
class _ProcessStat:
    start_ticks: int
    flags: int


def _read_process_stat(pid_dir: Path) -> _ProcessStat | None:
    try:
        raw = (pid_dir / "stat").read_bytes()
    except (FileNotFoundError, ProcessLookupError):
        return None
    except OSError as exc:
        raise Refusal(
            f"process generation is indeterminate because {pid_dir / 'stat'} "
            f"is unreadable: {exc}"
        ) from exc
    parsed = _parse_proc_stat(raw)
    expected_pid = int(pid_dir.name) if pid_dir.name.isdigit() else None
    if parsed is None or (expected_pid is not None and parsed.pid != expected_pid):
        raise Refusal(f"process generation is invalid for PID {pid_dir.name}")
    return _ProcessStat(start_ticks=parsed.start_ticks, flags=parsed.flags)


def _process_start_ticks(pid_dir: Path) -> int | None:
    process_stat = _read_process_stat(pid_dir)
    return None if process_stat is None else process_stat.start_ticks


def _process_is_exiting_namespace_init(pid_dir: Path) -> bool:
    """Is this process a PID-namespace init being torn down, holding nothing?

    The kernel's exit path (do_exit) releases a task's files, its
    filesystem context and its namespaces (exit_files, exit_fs,
    exit_task_namespaces, exit_nsproxy_namespaces in 7.x) before exit_notify
    looks for a child reaper; an
    exiting namespace init then waits in zap_pid_ns_processes until every
    other process of its namespace is gone. Such a task can hold no
    checkout: it has no open files, no working directory or root, and no
    mount namespace, which is why its mount namespace reads as absent.
    Required, each from /proc: the wait channel is zap_pid_ns_processes;
    the innermost NSpid is 1; Threads is 1; and cwd, root and ns/mnt each read as ENOENT
    (released), not as a permission error. Anything else is not exempt.
    """
    try:
        wchan = (pid_dir / "wchan").read_text(encoding="ascii", errors="replace").strip()
        status = _read_process_status(pid_dir)
    except (OSError, UnicodeError, Refusal):
        return False
    if wchan != "zap_pid_ns_processes":
        return False
    nspid = [line.split()[1:] for line in status.split("\n") if line.startswith("NSpid:")]
    if not nspid or not nspid[0] or nspid[0][-1] != "1":
        return False
    # One thread: a multi-threaded init whose leader exits keeps running
    # threads that may still hold files; only a lone exiting task is proven.
    threads = [line.split()[1:] for line in status.split("\n") if line.startswith("Threads:")]
    if not threads or threads[0] != ["1"]:
        return False
    for released in ("cwd", "root", "ns/mnt"):
        try:
            os.readlink(pid_dir / released)
        except FileNotFoundError:
            continue
        except OSError:
            return False
        return False
    names = [line.split(":", 1)[1].strip() for line in status.split("\n")
             if line.startswith("Name:")]
    print(
        f"wrkslots: PID {pid_dir.name} ({names[0] if names else '?'}) is a PID-namespace "
        "init being torn down (wchan zap_pid_ns_processes; cwd, root and mount namespace "
        "already released), so it cannot hold a checkout; not counted as an occupant",
        file=sys.stderr,
    )
    return True


def _process_is_zombie(
    pid_dir: Path, *, generation: _ProcessStat | None = None,
) -> bool:
    try:
        status = _read_process_status(pid_dir, generation=generation)
    except FileNotFoundError as exc:
        if _read_process_stat(pid_dir) is None:
            return True
        raise Refusal(
            f"process state is indeterminate because {pid_dir / 'status'} "
            "is missing while its generation is still present"
        ) from exc
    except (OSError, UnicodeError) as exc:
        raise Refusal(
            f"process state is indeterminate because {pid_dir / 'status'} is unreadable: {exc}"
        ) from exc
    # See `_process_uids`: only the kernel's LF is a record boundary. Other
    # Unicode line separators may be opaque bytes from the process name.
    states = [line.split() for line in status.split("\n") if line.startswith("State:")]
    if not states:
        raise Refusal(f"process state is missing for PID {pid_dir.name}")
    # Include state tokens exposed by current and older supported Linux kernels.
    # Unknown or ambiguous evidence must never be interpreted as terminal.
    if (
        len(states) != 1 or len(states[0]) < 2 or states[0][0] != "State:"
        or states[0][1] not in {"R", "S", "D", "T", "t", "X", "Z", "P", "I", "K", "W", "x"}
    ):
        raise Refusal(f"process state is invalid for PID {pid_dir.name}")
    return states[0][1] in {"Z", "X"}


def _process_generation_is_terminal(pid_dir: Path, generation: _ProcessStat) -> bool:
    if not _process_is_zombie(pid_dir, generation=generation):
        return False
    current = _read_process_stat(pid_dir)
    if current is not None and current.start_ticks != generation.start_ticks:
        raise _ProcessEvidenceChanged(
            f"PID {pid_dir.name} generation changed during terminal-state observation"
        )
    return True


def _absent_validate_process_snapshot(
    proc_root: Path = Path("/proc"),
    *,
    include_owner_cgroups: bool = True,
) -> tuple[_AbsentProcessObservation, ...]:
    try:
        pid_dirs = sorted(
            (path for path in proc_root.iterdir() if path.name.isdigit()),
            key=lambda path: int(path.name),
        )
    except OSError as exc:
        raise Refusal(f"cannot enumerate live processes: {exc}") from exc
    observations: list[_AbsentProcessObservation] = []
    for pid_dir in pid_dirs:
        generation = _read_process_stat(pid_dir)
        if generation is None:
            continue
        if _process_generation_is_terminal(pid_dir, generation):
            continue
        try:
            if _process_uid(pid_dir) is None:
                continue
            cgroup = _read_process_cgroup(pid_dir) if include_owner_cgroups else ""
            mount_namespace = _mount_namespace(pid_dir)
        except Refusal:
            if _process_start_ticks(pid_dir) is None:
                continue
            raise
        if mount_namespace is None:
            if _process_is_zombie(pid_dir):
                continue
            if _process_start_ticks(pid_dir) is None:
                continue
            if _process_is_exiting_namespace_init(pid_dir):
                continue
            raise Refusal(f"mount namespace is indeterminate for live PID {pid_dir.name}")
        current_generation = _read_process_stat(pid_dir)
        if current_generation is None:
            continue
        if current_generation.start_ticks != generation.start_ticks:
            raise _ProcessEvidenceChanged(
                f"process generation changed while reading PID {pid_dir.name}"
            )
        observations.append(
            _AbsentProcessObservation(
                pid=int(pid_dir.name),
                start_ticks=generation.start_ticks,
                cgroup_path=cgroup,
                mount_namespace=mount_namespace,
                kernel_thread=bool(generation.flags & _PF_KTHREAD),
            )
        )
    return tuple(observations)


class _MountinfoCensusExceeded(Refusal):
    """The census's distinct-content byte bound refused a mount table.

    This is a refusal of the WHOLE census, not of one process: the refused
    table was never parsed, so no later read -- another representative of the
    same namespace whose table was charged before included -- may stand in for
    it.  Callers that fall back between representatives must re-raise it.
    """


class _MountinfoCensus(dict[str, tuple[tuple[Path, str], ...]]):
    """One census's parsed mount tables plus its distinct-content byte account.

    The mapping is the parse memo `_parse_mountinfo_paths` already used, keyed
    on the table text.  The account charges `_MOUNTINFO_CENSUS_BYTES_LIMIT` once
    per distinct table content, keyed on a SHA-256 digest of the bytes read, so
    the bound limits what the census keeps rather than how many processes list
    the same table.

    ⚠️ CHARGING IS NOT READING.  Every process whose table the census read
    before still has it read and parsed -- one per readable mount namespace and
    one for EVERY process whose namespace link is unreadable -- and only the
    byte charge is shared between identical tables.  A table whose content was
    already charged still yields that process's references, from the memo.

    The total charged is the sum of the sizes of the distinct tables observed,
    so whether a census exceeds the bound does not depend on the order in
    which processes are read, and one census starts with a fresh account
    rather than inheriting what an earlier census or batch item consumed.

    Exceeding the bound is final for the census: the refusal is a
    `_MountinfoCensusExceeded`, and every later charge -- of content charged
    before included -- repeats it, so no read after an unparsed table can be
    taken as complete evidence.
    """

    def __init__(self, limit: int | None = None) -> None:
        super().__init__()
        self.limit = _MOUNTINFO_CENSUS_BYTES_LIMIT if limit is None else limit
        self.charged_bytes = 0
        self.reads = 0
        self.read_bytes = 0
        self._charged: set[bytes] = set()
        self._exceeded: _MountinfoCensusExceeded | None = None

    @property
    def distinct_tables(self) -> int:
        return len(self._charged)

    def charge(self, pid: int, contents: bytes) -> None:
        if self._exceeded is not None:
            raise _MountinfoCensusExceeded(str(self._exceeded))
        self.reads += 1
        self.read_bytes += len(contents)
        digest = hashlib.sha256(contents).digest()
        if digest in self._charged:
            return
        if self.charged_bytes + len(contents) > self.limit:
            self._exceeded = _MountinfoCensusExceeded(
                f"mountinfo census exceeded its {self.limit}-byte bound on distinct "
                f"mount-table content: /proc/{pid}/mountinfo adds {len(contents)} new "
                f"bytes to the {self.charged_bytes} bytes already charged for "
                f"{self.distinct_tables} distinct table(s) over {self.reads - 1} "
                f"earlier read(s) of {self.read_bytes - len(contents)} bytes in this "
                "census; identical tables are charged once"
            )
            raise self._exceeded
        self._charged.add(digest)
        self.charged_bytes += len(contents)


def _mountinfo_path_references(
    pid: int,
    budget: _ReadOnlyCommandBudget,
    cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
) -> tuple[tuple[Path, str], ...]:
    """Return one process's mount references, charged to ``cache``'s census.

    ``budget`` supplies the operation deadline.  The byte bound belongs to the
    census, so it is charged to ``cache`` when that is a `_MountinfoCensus`;
    any other caller gets a census of its own for this one table.  Each file is
    read against the fixed `_MOUNTINFO_FILE_BYTES_LIMIT`, so a per-file refusal
    names that bound rather than whatever remained of a shared allowance.
    """

    census = cache if isinstance(cache, _MountinfoCensus) else _MountinfoCensus()
    path = Path("/proc") / str(pid) / "mountinfo"
    try:
        budget.remaining_seconds()
        contents = _read_bounded_regular_file(
            path,
            f"mount evidence for PID {pid}",
            _MOUNTINFO_FILE_BYTES_LIMIT,
        )
        census.charge(pid, contents)
        budget.remaining_seconds()
        text = contents.decode("utf-8", errors="surrogateescape")
    except (OSError, UnicodeError) as exc:
        raise Refusal(f"mount evidence is indeterminate for PID {pid}: {exc}") from exc
    return _parse_mountinfo_paths(text, f"mount evidence for PID {pid}", cache)


def _absent_validate_mount_match(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[int, str, str, str] | None:
    matches = _absent_validate_mount_matches(processes, targets, budget)
    return matches[0] if matches else None


def _absent_validate_mount_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[tuple[int, str, str, str], ...]:
    selected_budget = budget or _ReadOnlyCommandBudget.start(
        timeout_seconds=_ABSENT_PROCESS_CENSUS_SECONDS,
        stdout_limit=16 * 1024 * 1024,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    namespaces: dict[str, list[_AbsentProcessObservation]] = {}
    for process in processes:
        namespaces.setdefault(process.mount_namespace, []).append(process)
    matches: list[tuple[int, str, str, str]] = []
    # One memo for this census. Nearly every process on a fleet host has its own
    # mount namespace -- 3,363 namespaces across 3,638 processes, measured
    # 2026-09-17 -- and they mount the same handful of paths, so the references
    # repeat about 311 times each.
    match_cache: dict[Path, tuple[Path, str] | None] = {}
    # One census: a fresh distinct-content byte account for this observation
    # of every mount table, never one inherited from an earlier census.
    mountinfo_cache = _MountinfoCensus()
    for representatives in namespaces.values():
        selected: _AbsentProcessObservation | None = None
        references: tuple[tuple[Path, str], ...] = ()
        failures: list[tuple[_AbsentProcessObservation, Refusal]] = []
        for process in representatives:
            try:
                candidate_references = _mountinfo_path_references_with_retry(
                    process, selected_budget, mountinfo_cache
                )
            except _MountinfoCensusExceeded:
                # The refused table was never parsed.  Falling back to another
                # representative would let a table charged earlier stand in for
                # it, so the bound refuses the whole census.
                raise
            except Refusal as exc:
                failures.append((process, exc))
                continue
            current_start = _process_start_ticks(Path("/proc") / str(process.pid))
            if current_start != process.start_ticks:
                if any(
                    _matching_absent_validate_target(observed, targets, match_cache)
                    is not None
                    for observed, _detail in candidate_references
                ):
                    raise Refusal(
                        f"PID {process.pid} identity changed after mount matched a selected path; "
                        "the selected path may still be in use"
                    )
                continue
            selected = process
            references = candidate_references
            break
        if selected is None:
            # A representative that exited during the census is skipped, as
            # _preflight_process_observations skips one that exited before it:
            # its terminal generation can hold no mount reference.  A zombie
            # keeps its /proc directory and start ticks until it is reaped, so
            # matching start ticks alone took it for a live process; on a busy
            # host one such exit in every attempt refused the whole census as
            # "relevant process evidence changed".  A representative whose read
            # failed while it still runs refuses, as before.
            for process, failure in failures:
                if _process_observation_is_active(process):
                    raise failure
            continue
        for observed, detail in references:
            matched = _matching_absent_validate_target(observed, targets, match_cache)
            if matched is not None:
                _target, slot = matched
                matches.append((selected.pid, slot, "mount", detail))
    return tuple(matches)


def _mountinfo_path_references_with_retry(
    process: _AbsentProcessObservation,
    budget: _ReadOnlyCommandBudget,
    cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
) -> tuple[tuple[Path, str], ...]:
    """Retry one stable procfs EINVAL; persistent errors remain refusals."""

    for attempt in range(2):
        try:
            return _mountinfo_path_references(process.pid, budget, cache)
        except _MountinfoCensusExceeded:
            # The census bound is not a property of this process, so neither
            # its exit nor a retry can turn the refusal into evidence.
            raise
        except Refusal as exc:
            # A process that exits after the snapshot can retain its procfs
            # directory and start ticks until its parent reaps it.  Linux then
            # returns EINVAL for mountinfo, so generation equality alone does
            # not distinguish that ordinary race from unreadable live evidence.
            if not _process_observation_is_active(process):
                raise _ProcessEvidenceChanged(
                    f"PID {process.pid} exited during mountinfo census"
                ) from exc
            cause = exc.__cause__
            if not isinstance(cause, OSError) or cause.errno != errno.EINVAL:
                raise
            if attempt:
                raise
    raise AssertionError("unreachable mountinfo retry")


def _has_identity_user_namespace(
    uid_map_path: Path = Path("/proc/self/uid_map"),
) -> bool:
    """Accept executable ownership only in the full identity UID namespace."""

    try:
        rows = uid_map_path.read_text(encoding="ascii").splitlines()
    except (OSError, UnicodeError) as exc:
        raise Refusal(f"cannot read user-namespace UID mapping: {exc}") from exc
    mappings: list[tuple[int, int, int]] = []
    for row in rows:
        fields = row.split()
        if len(fields) != 3 or any(
            not field.isascii() or not field.isdecimal() for field in fields
        ):
            raise Refusal("user-namespace UID mapping is malformed")
        inside, outside, length = (int(field) for field in fields)
        if length <= 0 or inside + length > 1 << 32 or outside + length > 1 << 32:
            raise Refusal("user-namespace UID mapping is out of range")
        mappings.append((inside, outside, length))
    return mappings == [(0, 0, (1 << 32) - 1)]


@dataclasses.dataclass(frozen=True)
class _TrustedExecutablePath:
    path: Path
    identities: tuple[tuple[Path, int, int, int, int, int], ...]


def _trusted_path_identity(path: Path) -> tuple[Path, int, int, int, int, int]:
    try:
        metadata = path.lstat()
    except OSError as exc:
        raise Refusal(f"trusted executable path is unavailable {path}: {exc}") from exc
    return (
        path,
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
    )


def _root_owned_executable(path: Path, label: str) -> _TrustedExecutablePath:
    if not path.is_absolute() or path.parent != _TRUSTED_EXECUTABLE_DIRECTORY:
        raise Refusal(f"{label} must use its hard-coded canonical /usr/bin path: {path}")
    try:
        resolved = path.resolve(strict=True)
    except OSError as exc:
        raise Refusal(f"{label} is unavailable: {exc}") from exc
    if resolved != path or not _has_identity_user_namespace():
        raise Refusal(f"{label} is not a root-owned, non-writable executable: {resolved}")
    chain: list[tuple[Path, int, int, int, int, int]] = []
    candidate = resolved
    while True:
        identity = _trusted_path_identity(candidate)
        _path, _device, _inode, mode, uid, gid = identity
        expected_type = stat.S_ISREG(mode) if candidate == resolved else stat.S_ISDIR(mode)
        if (
            not expected_type
            or uid != 0
            or gid != 0
            or mode & 0o022
            or os.access(candidate, os.W_OK, effective_ids=True)
        ):
            raise Refusal(
                f"{label} has an untrusted executable path component: {candidate}"
            )
        chain.append(identity)
        if candidate == candidate.parent:
            break
        candidate = candidate.parent
    if not os.access(resolved, os.X_OK):
        raise Refusal(f"{label} is not executable: {resolved}")
    if resolved.resolve(strict=True) != resolved:
        raise Refusal(f"{label} executable path changed during validation: {resolved}")
    return _TrustedExecutablePath(resolved, tuple(chain))


def _recheck_trusted_executable(executable: _TrustedExecutablePath) -> None:
    try:
        if executable.path.resolve(strict=True) != executable.path:
            raise Refusal(
                f"trusted executable path changed before execution: {executable.path}"
            )
    except OSError as exc:
        raise Refusal(
            f"trusted executable path is unavailable before execution: "
            f"{executable.path}: {exc}"
        ) from exc
    for expected in executable.identities:
        observed = _trusted_path_identity(expected[0])
        if observed != expected:
            raise Refusal(
                f"trusted executable path identity changed before execution: {expected[0]}"
            )


@dataclasses.dataclass
class _ReadOnlyCommandBudget:
    """One deadline plus byte and direct-observation bounds for a census."""

    deadline: float
    stdout_remaining: int
    stderr_remaining: int
    input_remaining: int
    observations_remaining: int
    # The configured bound, kept so a deadline refusal can say how large the
    # bound was and how long the census actually ran.  Zero means unknown.
    timeout_seconds: float = 0.0

    @classmethod
    def start(
        cls,
        *,
        timeout_seconds: float,
        stdout_limit: int,
        stderr_limit: int,
        input_limit: int = 16 * 1024 * 1024,
        observation_limit: int = _PROCESS_CENSUS_OBSERVATION_LIMIT,
    ) -> "_ReadOnlyCommandBudget":
        return cls(
            deadline=time.monotonic() + timeout_seconds,
            stdout_remaining=stdout_limit,
            stderr_remaining=stderr_limit,
            input_remaining=input_limit,
            observations_remaining=observation_limit,
            timeout_seconds=timeout_seconds,
        )

    def remaining_seconds(self) -> float:
        now = time.monotonic()
        remaining = self.deadline - now
        if remaining <= 0:
            detail = ""
            if self.timeout_seconds > 0:
                elapsed = now - (self.deadline - self.timeout_seconds)
                detail = (
                    f" (bound {self.timeout_seconds:.1f} s, "
                    f"elapsed {elapsed:.1f} s)"
                )
            raise Refusal(
                "read-only census exceeded its operation-wide time bound" + detail
            )
        return remaining

    def reserve_input(self, size: int) -> None:
        if size > self.input_remaining:
            raise Refusal("read-only census exceeded its operation-wide input bound")
        self.input_remaining -= size

    def consume_output(self, stdout: bytes, stderr: bytes) -> None:
        self.stdout_remaining -= len(stdout)
        self.stderr_remaining -= len(stderr)
        if self.stdout_remaining < 0 or self.stderr_remaining < 0:
            raise Refusal("read-only census exceeded its operation-wide output bound")

    def consume_observation(self) -> None:
        if self.observations_remaining <= 0:
            raise Refusal(
                "read-only census exceeded its operation-wide observation bound"
            )
        self.observations_remaining -= 1


def _run_bounded_read_only_command(
    command: Sequence[str],
    *,
    timeout_seconds: float = 60.0,
    stdout_limit: int = 16 * 1024 * 1024,
    stderr_limit: int = 64 * 1024,
    input_limit: int = 1024 * 1024,
    env_overrides: Mapping[str, str] | None = None,
    input_data: bytes | None = None,
    trusted_executables: Sequence[_TrustedExecutablePath] = (),
) -> tuple[int, bytes, bytes]:
    if input_data is not None and len(input_data) > input_limit:
        raise Refusal(
            f"privileged read-only census input exceeds {input_limit} bytes"
        )
    environment = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C"}
    if env_overrides is not None:
        environment.update(env_overrides)
    for executable in trusted_executables:
        _recheck_trusted_executable(executable)
    deadline = time.monotonic() + timeout_seconds
    try:
        process = subprocess.Popen(
            list(command),
            stdin=subprocess.PIPE if input_data is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd="/",
            env=environment,
            start_new_session=True,
        )
    except OSError as exc:
        raise Refusal(f"cannot start privileged read-only census: {exc}") from exc
    selector: selectors.BaseSelector | None = None
    try:
        assert process.stdout is not None and process.stderr is not None
        stdout_buffer = bytearray()
        stderr_buffer = bytearray()
        streams = {
            process.stdout.fileno(): (
                process.stdout,
                stdout_buffer,
                stdout_limit,
                "stdout",
            ),
            process.stderr.fileno(): (
                process.stderr,
                stderr_buffer,
                stderr_limit,
                "stderr",
            ),
        }
        selector = selectors.DefaultSelector()
        for stream, _buffer, _limit, _label in streams.values():
            os.set_blocking(stream.fileno(), False)
            selector.register(stream, selectors.EVENT_READ)
        input_offset = 0
        if input_data is not None:
            assert process.stdin is not None
            os.set_blocking(process.stdin.fileno(), False)
            selector.register(process.stdin, selectors.EVENT_WRITE)
        while selector.get_map():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise Refusal(f"privileged read-only census exceeded {timeout_seconds:g}s")
            ready = selector.select(min(remaining, 1.0))
            for key, _mask in ready:
                if process.stdin is not None and key.fileobj is process.stdin:
                    assert input_data is not None
                    try:
                        written = os.write(
                            key.fd, input_data[input_offset : input_offset + 64 * 1024]
                        )
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        written = len(input_data) - input_offset
                    input_offset += written
                    if input_offset == len(input_data):
                        selector.unregister(process.stdin)
                        process.stdin.close()
                    continue
                stream, buffer, limit, label = streams[key.fd]
                try:
                    chunk = os.read(key.fd, 64 * 1024)
                except BlockingIOError:
                    continue
                if not chunk:
                    selector.unregister(stream)
                    continue
                buffer.extend(chunk)
                if len(buffer) > limit:
                    raise Refusal(f"privileged read-only census {label} exceeded {limit} bytes")
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise Refusal(f"privileged read-only census exceeded {timeout_seconds:g}s")
        returncode = process.wait(timeout=remaining)
        if time.monotonic() >= deadline:
            raise Refusal(f"privileged read-only census exceeded {timeout_seconds:g}s")
    except BaseException as exc:
        cleanup_error: str | None = None
        # The unreaped leader reserves its PID/PGID while descendants may hold
        # the pipes open. After wait() reaps it, that number may be reused: a
        # late-result refusal must not signal an unrelated process group.
        if process.returncode is None:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            except OSError as kill_error:
                cleanup_error = f"cannot kill census process group {process.pid}: {kill_error}"
        try:
            process.wait(timeout=_READ_ONLY_COMMAND_REAP_SECONDS)
        except subprocess.TimeoutExpired:
            # An uninterruptible kernel operation can outlive SIGKILL. Do not
            # wait forever or treat its incomplete output as a successful census.
            cleanup_error = (
                f"census PID {process.pid} was not reaped within "
                f"{_READ_ONLY_COMMAND_REAP_SECONDS:g}s after SIGKILL"
            )
        if cleanup_error is not None:
            if not isinstance(exc, (Refusal, subprocess.TimeoutExpired)):
                raise exc from Refusal(cleanup_error)
            raise Refusal(f"{exc}; {cleanup_error}") from exc
        if isinstance(exc, subprocess.TimeoutExpired):
            raise Refusal(f"privileged read-only census exceeded {timeout_seconds:g}s") from exc
        raise
    finally:
        if selector is not None:
            selector.close()
        if process.stdin is not None and not process.stdin.closed:
            process.stdin.close()
        if process.stdout is not None:
            process.stdout.close()
        if process.stderr is not None:
            process.stderr.close()
    return returncode, bytes(stdout_buffer), bytes(stderr_buffer)


def _run_root_owned_command(
    program: Path,
    arguments: Sequence[str],
    *,
    input_data: bytes | None = None,
    input_limit: int = 1024 * 1024,
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[int, bytes, bytes]:
    sudo = _root_owned_executable(Path("/usr/bin/sudo"), "sudo")
    executable = _root_owned_executable(program, program.name)
    command = [
        str(sudo.path),
        "-n",
        "-u",
        "root",
        "--",
        str(executable.path),
        *arguments,
    ]
    if sum(len(os.fsencode(argument)) + 1 for argument in command) > 64 * 1024:
        raise Refusal("privileged read-only census command exceeds the 64 KiB argv bound")
    selected_budget = budget or _ReadOnlyCommandBudget.start(
        timeout_seconds=60,
        stdout_limit=16 * 1024 * 1024,
        stderr_limit=64 * 1024,
    )
    selected_budget.reserve_input(0 if input_data is None else len(input_data))
    stdout_limit = selected_budget.stdout_remaining
    stderr_limit = selected_budget.stderr_remaining
    if stdout_limit <= 0 or stderr_limit <= 0:
        raise Refusal("read-only census exhausted its operation-wide output bound")
    result = _run_bounded_read_only_command(
        command,
        timeout_seconds=selected_budget.remaining_seconds(),
        stdout_limit=stdout_limit,
        stderr_limit=stderr_limit,
        input_limit=input_limit,
        input_data=input_data,
        trusted_executables=(sudo, executable),
    )
    selected_budget.consume_output(result[1], result[2])
    return result


def _run_same_uid_command(
    program: Path,
    arguments: Sequence[str],
    *,
    budget: _ReadOnlyCommandBudget,
    input_data: bytes | None = None,
) -> tuple[int, bytes, bytes]:
    """Run one bounded unprivileged census command from the shared batch budget."""

    executable = _root_owned_executable(program, program.name)
    command = [str(executable.path), *arguments]
    if sum(len(os.fsencode(argument)) + 1 for argument in command) > 64 * 1024:
        raise Refusal("same-UID read-only census command exceeds the 64 KiB argv bound")
    budget.reserve_input(0 if input_data is None else len(input_data))
    stdout_limit = budget.stdout_remaining
    stderr_limit = budget.stderr_remaining
    if stdout_limit <= 0 or stderr_limit <= 0:
        raise Refusal("same-UID census exhausted its operation-wide output bound")
    result = _run_bounded_read_only_command(
        command,
        timeout_seconds=budget.remaining_seconds(),
        stdout_limit=stdout_limit,
        stderr_limit=stderr_limit,
        input_data=input_data,
        trusted_executables=(executable,),
    )
    budget.remaining_seconds()
    budget.consume_output(result[1], result[2])
    return result


def _argument_batches(
    prefix: Sequence[str],
    items: Sequence[str],
    suffix: Sequence[str],
    *,
    budget: int = 48 * 1024,
) -> tuple[tuple[str, ...], ...]:
    fixed = sum(len(os.fsencode(argument)) + 1 for argument in (*prefix, *suffix))
    if fixed >= budget:
        raise Refusal("privileged read-only census fixed arguments exceed the argv bound")
    batches: list[tuple[str, ...]] = []
    current: list[str] = []
    used = fixed
    for item in items:
        size = len(os.fsencode(item)) + 1
        if fixed + size > budget:
            raise Refusal("one privileged read-only census argument exceeds the argv bound")
        if current and used + size > budget:
            batches.append((*prefix, *current, *suffix))
            current = []
            used = fixed
        current.append(item)
        used += size
    if current:
        batches.append((*prefix, *current, *suffix))
    return tuple(batches)


def _process_symlink_roots(
    processes: Sequence[_AbsentProcessObservation],
) -> tuple[str, ...]:
    roots: list[str] = []
    for process in processes:
        base = Path("/proc") / str(process.pid)
        roots.extend(str(base / name) for name in ("cwd", "root"))
        # Linux intentionally exposes no /proc/PID/exe target for kernel threads.
        # Omitting that one known-absent link avoids treating expected kernel state
        # as an incomplete census; every userspace process must still expose it.
        if not process.kernel_thread:
            roots.append(str(base / "exe"))
        roots.append(str(base / "fd"))
    return tuple(roots)


def _find_link_selection(targets: Mapping[Path, str]) -> tuple[str, ...]:
    """Build GNU find predicates that emit only links into selected trees.

    A full-host process census can contain millions of unrelated descriptors.
    Filtering their link targets in ``find`` keeps the bounded command channel
    proportional to relevant evidence while the parser below still validates
    every emitted record and the command runner still refuses an oversized
    relevant result.
    """

    tests: list[str] = []
    for target in sorted(targets, key=str):
        literal = str(target)
        for character in ("\\", "*", "?", "["):
            literal = literal.replace(character, f"\\{character}")
        patterns = (
            ("/*",)
            if target == Path("/")
            else (literal, f"{literal}/*", f"{literal} (deleted)")
        )
        for pattern in patterns:
            if tests:
                tests.append("-o")
            tests.extend(("-lname", pattern))
    return tuple(tests)


def _bounded_find_link_selection(
    targets: Mapping[Path, str],
    *,
    budget: int = _FIND_LINK_SELECTION_BYTES_LIMIT,
) -> tuple[str, ...]:
    """Return a bounded producer filter that contains every selected tree.

    GNU find has no file-backed form of ``-lname``. Repeating three predicates
    for every selected tree can therefore exhaust execve's argument space even
    though the procfs roots themselves are already batched. When that happens,
    replace the selected paths with lexical ancestors until their expression
    fits. This only widens the producer filter: each consumer still accepts
    evidence against the original mapping, so an unrelated sibling can consume
    the bounded output budget but can never become a live-use match.

    Keeping one expression for the entire operation also means every procfs
    root is scanned once against one process snapshot. Partitioning the target
    set would instead rescan mutable descriptors and could miss a link that
    moved between target partitions.
    """

    if budget < 1:
        raise Refusal("privileged find selection has no argv budget")
    selectors = frozenset(targets)
    while selectors:
        selection = _find_link_selection({path: "" for path in selectors})
        size = sum(len(os.fsencode(argument)) + 1 for argument in selection)
        if size <= budget:
            return selection
        parents = frozenset(path.parent for path in selectors)
        if parents == selectors:
            raise Refusal("privileged find selection cannot fit the argv bound")
        selectors = parents
    return ()


def _pid_from_proc_evidence(path: Path) -> int:
    parts = path.parts
    if len(parts) < 4 or parts[1] != "proc" or not parts[2].isdigit():
        raise Refusal(f"privileged process evidence names an unexpected path: {path}")
    return int(parts[2])


_FIND_MISSING_RE = re.compile(
    r"^/usr/bin/find: '/proc/(?P<pid>[0-9]+)(?:/[^']*)?': " r"No such file or directory$"
)
_GREP_MISSING_RE = re.compile(
    r"^/usr/bin/grep: /proc/(?P<pid>[0-9]+)/maps: No such file or directory$"
)
_FIND_PERMISSION_RE = re.compile(
    r"^/usr/bin/find: '/proc/(?P<pid>[0-9]+)(?:/[^']*)?': Permission denied$"
)
_GREP_PERMISSION_RE = re.compile(
    r"^/usr/bin/grep: /proc/(?P<pid>[0-9]+)/maps: Permission denied$"
)


def _process_generation_is_current(process: _AbsentProcessObservation) -> bool:
    return _process_start_ticks(Path("/proc") / str(process.pid)) == process.start_ticks


def _process_observation_is_active(process: _AbsentProcessObservation) -> bool:
    """Return whether the observed generation still names a non-zombie process."""

    pid_dir = Path("/proc") / str(process.pid)
    before = _read_process_stat(pid_dir)
    if before is None or before.start_ticks != process.start_ticks:
        return False
    if _process_is_zombie(pid_dir):
        return False
    after = _read_process_stat(pid_dir)
    return after is not None and after.start_ticks == process.start_ticks


def _preflight_process_observations(
    processes: Sequence[_AbsentProcessObservation],
    budget: _ReadOnlyCommandBudget,
) -> tuple[_AbsentProcessObservation, ...]:
    """Reject unstable identities and omit proven terminal generations."""

    retained: list[_AbsentProcessObservation] = []
    for process in processes:
        budget.remaining_seconds()
        # Retain vanished identities in the original tuple: every downstream
        # observer must still establish absence or reject stale/reused evidence.
        pid_dir = Path("/proc") / str(process.pid)
        if _read_process_stat(pid_dir) is None:
            retained.append(process)
            continue
        if _process_observation_is_active(process):
            retained.append(process)
            continue
        # Ordinary exit/zombie churn is positive terminal evidence. Once the
        # same generation is proven terminal it cannot retain path or mount
        # references, so do not send it to privileged readers. A merely
        # vanished identity is retained above because PID reuse can race those
        # readers and must still be detected downstream.
        current = _read_process_stat(pid_dir)
        if current is None:
            retained.append(process)
            continue
        if current.start_ticks != process.start_ticks:
            raise _ProcessEvidenceChanged(
                f"PID {process.pid} changed before process path census"
            )
        if _process_generation_is_terminal(pid_dir, current):
            continue
        raise _ProcessEvidenceChanged(
            f"PID {process.pid} liveness changed before process path census"
        )
    return tuple(retained)


def _allow_only_vanished_process_diagnostics(
    program: str,
    returncode: int,
    stderr: bytes,
    processes: Mapping[int, _AbsentProcessObservation],
) -> None:
    if returncode == 0 and not stderr:
        return
    if program == "grep" and returncode == 1 and not stderr:
        return
    expected_error = 1 if program == "find" else 2
    if returncode != expected_error:
        raise Refusal(f"privileged {program} census refused with exit {returncode}")
    if returncode == 0 or not stderr:
        raise Refusal(
            f"privileged {program} census returned exit {returncode} with "
            "inconsistent diagnostics"
        )
    try:
        lines = stderr.decode("ascii").splitlines()
    except UnicodeError as exc:
        raise Refusal(f"privileged {program} census diagnostics are undecodable") from exc
    pattern = _FIND_MISSING_RE if program == "find" else _GREP_MISSING_RE
    changed_diagnostic: str | None = None
    for line in lines:
        match = pattern.fullmatch(line)
        process = processes.get(int(match.group("pid"))) if match else None
        if process is None:
            raise Refusal(f"privileged {program} census produced diagnostics: {line}")
        if _process_observation_is_active(process):
            changed_diagnostic = line
    # Validate every diagnostic before classifying motion: an earlier vanished
    # FD must not hide a later permission, malformed, or unknown-path refusal.
    # The enclosing bounded retry discards this entire incomplete census.
    if changed_diagnostic is not None:
        raise _ProcessEvidenceChanged(
            f"privileged {program} census produced diagnostics: {changed_diagnostic}"
        )


def _same_uid_indeterminate_processes(
    program: str,
    returncode: int,
    stderr: bytes,
    processes: Mapping[int, _AbsentProcessObservation],
) -> tuple[_AbsentProcessObservation, ...]:
    """Return stable protected PIDs that require fresh privileged evidence."""

    if returncode == 0 and not stderr:
        return ()
    if program == "grep" and returncode == 1 and not stderr:
        return ()
    expected_error = 1 if program == "find" else 2
    if returncode != expected_error or not stderr:
        raise Refusal(
            f"same-UID {program} census returned inconsistent exit {returncode}"
        )
    try:
        lines = stderr.decode("ascii").splitlines()
    except UnicodeError as exc:
        raise Refusal(
            f"same-UID {program} census diagnostics are undecodable"
        ) from exc
    missing_pattern = _FIND_MISSING_RE if program == "find" else _GREP_MISSING_RE
    permission_pattern = (
        _FIND_PERMISSION_RE if program == "find" else _GREP_PERMISSION_RE
    )
    indeterminate: dict[int, _AbsentProcessObservation] = {}
    changed_diagnostic: str | None = None
    for line in lines:
        missing = missing_pattern.fullmatch(line)
        if missing is not None:
            process = processes.get(int(missing.group("pid")))
            if process is None:
                raise Refusal(
                    f"same-UID {program} census produced diagnostics: {line}"
                )
            if _process_observation_is_active(process):
                changed_diagnostic = line
            continue
        denied = permission_pattern.fullmatch(line)
        process = (
            None if denied is None else processes.get(int(denied.group("pid")))
        )
        if process is None:
            raise Refusal(f"same-UID {program} census produced diagnostics: {line}")
        if not _process_observation_is_active(process):
            continue
        indeterminate[process.pid] = process
    if changed_diagnostic is not None:
        raise _ProcessEvidenceChanged(
            f"same-UID {program} census produced diagnostics: {changed_diagnostic}"
        )
    return tuple(indeterminate.values())


def _parse_find_path_matches(
    output: bytes,
    processes: Mapping[int, _AbsentProcessObservation],
    targets: Mapping[Path, str],
    *,
    census: str,
) -> tuple[tuple[int, str, str, str], ...]:
    fields = output.split(b"\0")
    if fields and fields[-1] == b"":
        fields.pop()
    if len(fields) % 2:
        raise Refusal(f"{census} find census returned a truncated record")
    matches: list[tuple[int, str, str, str]] = []
    match_cache: dict[Path, tuple[Path, str] | None] = {}
    for index in range(0, len(fields), 2):
        evidence_path = Path(fields[index].decode("utf-8", errors="surrogateescape"))
        raw_target = fields[index + 1].decode("utf-8", errors="surrogateescape")
        pid = _pid_from_proc_evidence(evidence_path)
        process = processes.get(pid)
        if process is None:
            raise Refusal(f"{census} find census returned an unexpected PID: {pid}")
        observed = Path(os.path.normpath(raw_target.removesuffix(" (deleted)")))
        matched = _matching_absent_validate_target(observed, targets, match_cache)
        if matched is None:
            continue
        if not _process_generation_is_current(process):
            raise Refusal(
                f"PID {pid} identity changed after {census} find matched a selected path; "
                "the selected path may still be in use"
            )
        _target, slot = matched
        matches.append((pid, slot, "link", raw_target))
    return tuple(matches)


def _parse_maps_path_matches(
    output: bytes,
    processes: Mapping[int, _AbsentProcessObservation],
    targets: Mapping[Path, str],
    *,
    census: str,
) -> tuple[tuple[int, str, str, str], ...]:
    matches: list[tuple[int, str, str, str]] = []
    match_cache: dict[Path, tuple[Path, str] | None] = {}
    for raw_line in output.splitlines():
        raw_path, separator, raw_mapping = raw_line.partition(b":")
        if not separator:
            raise Refusal(f"{census} grep census returned an unframed maps record")
        try:
            evidence_path = Path(raw_path.decode("ascii"))
        except UnicodeError as exc:
            raise Refusal(f"{census} grep census is undecodable: {exc}") from exc
        mapping = raw_mapping.decode("utf-8", errors="surrogateescape")
        fields = mapping.split(maxsplit=5)
        if len(fields) != 6:
            raise Refusal(f"{census} grep census returned a malformed maps record")
        observed = Path(fields[5].removesuffix(" (deleted)"))
        if not observed.is_absolute():
            continue
        matched = _matching_absent_validate_target(observed, targets, match_cache)
        if matched is None:
            continue
        pid = _pid_from_proc_evidence(evidence_path)
        process = processes.get(pid)
        if process is None:
            raise Refusal(f"{census} grep census returned an unexpected PID: {pid}")
        if not _process_generation_is_current(process):
            raise Refusal(
                f"PID {pid} identity changed after {census} maps matched a selected path; "
                "the selected path may still be in use"
            )
        _target, slot = matched
        matches.append((pid, slot, "map", str(observed)))
    return tuple(matches)


def _absent_validate_find_match(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[int, str, str, str] | None:
    matches = _absent_validate_find_matches(processes, targets, budget)
    return matches[0] if matches else None


def _absent_validate_find_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[tuple[int, str, str, str], ...]:
    roots = _process_symlink_roots(processes)
    if not roots:
        return ()
    link_selection = _bounded_find_link_selection(targets)
    suffix = (
        "-ignore_readdir_race",
        "-maxdepth",
        "1",
        "-type",
        "l",
        "(",
        *link_selection,
        ")",
        "-printf",
        "%p\\0%l\\0",
    )
    observed_by_pid = {process.pid: process for process in processes}
    chunks: list[bytes] = []
    for arguments in _argument_batches(("-P",), roots, suffix):
        batch_pids = {
            _pid_from_proc_evidence(Path(argument))
            for argument in arguments[1 : len(arguments) - len(suffix)]
        }
        batch_processes = {
            pid: observed_by_pid[pid] for pid in batch_pids if pid in observed_by_pid
        }
        returncode, stdout, stderr = _run_root_owned_command(
            Path("/usr/bin/find"), arguments, budget=budget
        )
        _allow_only_vanished_process_diagnostics("find", returncode, stderr, batch_processes)
        chunks.append(stdout)
    return _parse_find_path_matches(
        b"".join(chunks), observed_by_pid, targets, census="privileged"
    )


def _absent_validate_maps_match(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[int, str, str, str] | None:
    matches = _absent_validate_maps_matches(processes, targets, budget)
    return matches[0] if matches else None


def _absent_validate_maps_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[tuple[int, str, str, str], ...]:
    files = [str(Path("/proc") / str(process.pid) / "maps") for process in processes]
    if not files:
        return ()
    patterns: list[str] = []
    for target in sorted(targets, key=str):
        text = str(target)
        if "\n" in text or "\0" in text:
            raise Refusal("validation paths containing line or NUL bytes cannot be probed")
        patterns.append(text)
    pattern_input = ("\n".join(patterns) + "\n").encode("utf-8")
    observed_by_pid = {process.pid: process for process in processes}
    chunks: list[bytes] = []
    for arguments in _argument_batches(("-F", "-H", "-f", "-", "--"), files, ()):
        batch_pids = {_pid_from_proc_evidence(Path(argument)) for argument in arguments[5:]}
        batch_processes = {
            pid: observed_by_pid[pid] for pid in batch_pids if pid in observed_by_pid
        }
        returncode, stdout, stderr = _run_root_owned_command(
            Path("/usr/bin/grep"), arguments, input_data=pattern_input, budget=budget
        )
        if returncode not in {0, 1, 2}:
            raise Refusal(f"privileged grep census refused with exit {returncode}")
        _allow_only_vanished_process_diagnostics("grep", returncode, stderr, batch_processes)
        chunks.append(stdout)
    return _parse_maps_path_matches(
        b"".join(chunks), observed_by_pid, targets, census="privileged"
    )


def _absent_validate_privileged_path_match(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget | None = None,
) -> tuple[int, str, str, str] | None:
    return _absent_validate_find_match(processes, targets, budget) or _absent_validate_maps_match(
        processes, targets, budget
    )


def _same_uid_process_observations(
    budget: _ReadOnlyCommandBudget,
    proc_root: Path = Path("/proc"),
) -> tuple[_AbsentProcessObservation, ...]:
    """Snapshot processes whose filesystem UID can traverse a private fence."""

    budget.remaining_seconds()
    try:
        pid_dirs = sorted(
            (path for path in proc_root.iterdir() if path.name.isdigit()),
            key=lambda path: int(path.name),
        )
    except OSError as exc:
        raise Refusal(f"cannot enumerate live processes: {exc}") from exc
    observations: list[_AbsentProcessObservation] = []
    for pid_dir in pid_dirs:
        budget.remaining_seconds()
        generation = _read_process_stat(pid_dir)
        if generation is None:
            continue
        if _process_generation_is_terminal(pid_dir, generation):
            continue
        filesystem_uid = _process_filesystem_uid(pid_dir)
        if filesystem_uid is None or filesystem_uid != os.getuid():
            continue
        try:
            # Validation-batch final checks pass record=None and need path and
            # mount evidence, never owner-cgroup membership. Avoid rereading an
            # unused cgroup file for every same-filesystem-UID PID and target.
            mount_namespace = _mount_namespace(pid_dir)
        except Refusal:
            if _process_start_ticks(pid_dir) is None:
                continue
            raise
        if mount_namespace is None:
            if _process_is_zombie(pid_dir) or _process_start_ticks(pid_dir) is None:
                continue
            if _process_is_exiting_namespace_init(pid_dir):
                continue
            raise Refusal(f"mount namespace is indeterminate for live PID {pid_dir.name}")
        current_generation = _read_process_stat(pid_dir)
        if current_generation is None:
            continue
        if current_generation.start_ticks != generation.start_ticks:
            raise _ProcessEvidenceChanged(
                f"process generation changed while reading PID {pid_dir.name}"
            )
        observations.append(
            _AbsentProcessObservation(
                pid=int(pid_dir.name),
                start_ticks=generation.start_ticks,
                cgroup_path="",
                mount_namespace=mount_namespace,
                kernel_thread=bool(generation.flags & _PF_KTHREAD),
            )
        )
    return tuple(observations)


def _same_uid_direct_path_processes(
    processes: Sequence[_AbsentProcessObservation],
    budget: _ReadOnlyCommandBudget,
) -> tuple[
    tuple[_AbsentProcessObservation, ...],
    tuple[_AbsentProcessObservation, ...],
]:
    """Separate directly readable proc entries from privileged-fallback work."""

    direct: list[_AbsentProcessObservation] = []
    indeterminate: list[_AbsentProcessObservation] = []
    for process in processes:
        budget.remaining_seconds()
        base = Path("/proc") / str(process.pid)
        try:
            os.readlink(base / "cwd")
            os.readlink(base / "root")
            if not process.kernel_thread:
                os.readlink(base / "exe")
            with os.scandir(base / "fd"):
                pass
        except PermissionError:
            if not _process_generation_is_current(process):
                raise _ProcessEvidenceChanged(
                    f"PID {process.pid} generation changed before same-UID path census"
                )
            indeterminate.append(process)
        except (FileNotFoundError, ProcessLookupError) as exc:
            # A short-lived, unrelated process can exit between the snapshot and
            # these link probes. Keep its identity in the privileged fallback so
            # every downstream observer still either proves it gone or rejects
            # stale/reused evidence, but do not discard the whole host snapshot
            # merely because this generation is positively no longer active.
            if _process_observation_is_active(process):
                raise _ProcessEvidenceChanged(
                    f"PID {process.pid} proc entries changed before same-UID path census"
                ) from exc
            indeterminate.append(process)
        except OSError as exc:
            if not _process_generation_is_current(process):
                raise _ProcessEvidenceChanged(
                    f"PID {process.pid} generation changed before same-UID path census"
                ) from exc
            raise Refusal(
                f"cannot inspect same-UID process {process.pid} path evidence: {exc}"
            ) from exc
        else:
            direct.append(process)
    return tuple(direct), tuple(indeterminate)


def _same_uid_batched_path_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget,
) -> tuple[
    tuple[tuple[int, str, str, str], ...],
    tuple[_AbsentProcessObservation, ...],
]:
    """Inspect readable links/maps in batches and identify protected procfs rows."""

    direct_processes, fallback_processes = _same_uid_direct_path_processes(
        processes, budget
    )
    observed_by_pid = {process.pid: process for process in direct_processes}
    matches: list[tuple[int, str, str, str]] = []
    indeterminate = {process.pid: process for process in fallback_processes}
    roots = _process_symlink_roots(direct_processes)
    link_tests = _bounded_find_link_selection(targets)
    find_suffix = (
        "-ignore_readdir_race",
        "-maxdepth",
        "1",
        "-type",
        "l",
        "(",
        *link_tests,
        ")",
        "-printf",
        "%p\\0%l\\0",
    )
    find_chunks: list[bytes] = []
    for arguments in _argument_batches(("-P",), roots, find_suffix):
        batch_pids = {
            _pid_from_proc_evidence(Path(argument))
            for argument in arguments[1 : len(arguments) - len(find_suffix)]
        }
        batch_processes = {
            pid: observed_by_pid[pid] for pid in batch_pids if pid in observed_by_pid
        }
        returncode, stdout, stderr = _run_same_uid_command(
            Path("/usr/bin/find"), arguments, budget=budget
        )
        for process in _same_uid_indeterminate_processes(
            "find", returncode, stderr, batch_processes
        ):
            indeterminate[process.pid] = process
        find_chunks.append(stdout)
    matches.extend(
        _parse_find_path_matches(
            b"".join(find_chunks), observed_by_pid, targets, census="same-UID"
        )
    )

    files = [
        str(Path("/proc") / str(process.pid) / "maps")
        for process in direct_processes
    ]
    patterns: list[str] = []
    for target in sorted(targets, key=str):
        text = str(target)
        if "\n" in text or "\0" in text:
            raise Refusal("validation paths containing line or NUL bytes cannot be probed")
        patterns.append(text)
    pattern_input = ("\n".join(patterns) + "\n").encode("utf-8")
    maps_chunks: list[bytes] = []
    for arguments in _argument_batches(("-F", "-H", "-f", "-", "--"), files, ()):
        batch_pids = {
            _pid_from_proc_evidence(Path(argument)) for argument in arguments[5:]
        }
        batch_processes = {
            pid: observed_by_pid[pid] for pid in batch_pids if pid in observed_by_pid
        }
        returncode, stdout, stderr = _run_same_uid_command(
            Path("/usr/bin/grep"),
            arguments,
            input_data=pattern_input,
            budget=budget,
        )
        for process in _same_uid_indeterminate_processes(
            "grep", returncode, stderr, batch_processes
        ):
            indeterminate[process.pid] = process
        maps_chunks.append(stdout)
    matches.extend(
        _parse_maps_path_matches(
            b"".join(maps_chunks), observed_by_pid, targets, census="same-UID"
        )
    )
    return tuple(matches), tuple(indeterminate.values())


def _capture_same_uid_process_path_census(
    slot_paths: Sequence[Path],
    *,
    budget: _ReadOnlyCommandBudget,
) -> _ProcessPathCensus:
    """Capture one fresh snapshot for paths reachable by this filesystem UID."""

    targets = {path: str(path) for path in slot_paths}
    if not targets:
        return _ProcessPathCensus((), (), owner_cgroup_complete=False)
    for attempt in range(3):
        budget.remaining_seconds()
        try:
            processes = _same_uid_process_observations(budget)
            processes = _preflight_process_observations(processes, budget)
            direct_matches, indeterminate = _same_uid_batched_path_matches(
                processes, targets, budget
            )
            privileged_matches = (
                *_absent_validate_find_matches(indeterminate, targets, budget),
                *_absent_validate_maps_matches(indeterminate, targets, budget),
            )
            # Reject volatile path motion before spending the shared mountinfo
            # input budget. An accepted attempt still completes every observer.
            matches = (
                *_absent_validate_mount_matches(processes, targets, budget),
                *direct_matches,
                *privileged_matches,
            )
        except _ProcessEvidenceChanged:
            if attempt < 2:
                continue
            raise Refusal(
                "same-UID process evidence changed during three liveness attempts"
            )
        return _ProcessPathCensus(
            processes, matches, owner_cgroup_complete=False
        )
    raise Refusal(
        "same-UID liveness proof is indeterminate because relevant process "
        "evidence changed during three attempts"
    )


@dataclasses.dataclass(frozen=True)
class _ProcessPathCensus:
    processes: tuple[_AbsentProcessObservation, ...]
    matches: tuple[tuple[int, str, str, str], ...]
    owner_cgroup_complete: bool = True

    def assert_slot_unused(
        self,
        slot_path: Path,
        record: ActiveRecord | None,
        *,
        ignore_invoking_ancestry: bool = False,
        ignore_current_process: bool = True,
    ) -> None:
        current_pid = os.getpid()
        ignored = {current_pid} if ignore_current_process else set()
        if ignore_invoking_ancestry:
            ancestor = _read_process_parent(current_pid)
            for _ in range(256):
                if ancestor is None or ancestor in ignored:
                    break
                ignored.add(ancestor)
                ancestor = _read_process_parent(ancestor)
        if (
            record is not None
            and record.owner is not None
            and not self.owner_cgroup_complete
            # Incomplete evidence is only a problem for evidence that is still
            # consulted. Without this the census would refuse for the absence
            # of a comparison it is no longer going to make.
            and _owner_cgroup_is_evidence(record)
        ):
            raise Refusal(
                "process census omitted owner-cgroup evidence required for this slot"
            )
        if _owner_cgroup_is_evidence(record) and record is not None and record.owner is not None:
            for process in self.processes:
                if process.pid in ignored:
                    continue
                if _cgroup_matches(record.owner.cgroup_path, process.cgroup_path):
                    raise Refusal(
                        f"live process {process.pid} remains in recorded owner cgroup "
                        f"{record.owner.cgroup_path}"
                    )
        label = str(slot_path)
        for pid, slot, kind, detail in self.matches:
            if slot == label and pid not in ignored:
                raise Refusal(
                    f"live process {pid} uses slot {slot_path}: {kind}={detail}; "
                    "stop it and retry"
                )


def _census_nul_records(output: bytes, width: int, label: str) -> list[list[str]]:
    fields = output.split(b"\0")
    if fields.pop() != b"" or len(fields) % width:
        raise Refusal(f"{label} returned a truncated record")
    decoded = [field.decode("utf-8", errors="surrogateescape") for field in fields]
    return [decoded[index:index + width] for index in range(0, len(decoded), width)]


def _selected_tree_inodes(
    targets: Mapping[Path, str], budget: _ReadOnlyCommandBudget,
) -> tuple[dict[tuple[int, int], tuple[tuple[str, str], ...]], bool]:
    """Stat each selected tree once; outside hardlinks retain the same identity.

    Names inside that already-bound tree are not needed for membership. Keeping
    only device/inode/type avoids repeating a long checkout prefix per file.
    """

    collected: dict[tuple[int, int], list[tuple[str, str]]] = {}
    has_sockets = False
    for target, slot in targets.items():
        rc, stdout, stderr = _run_same_uid_command(
            Path("/usr/bin/find"), ("-P", str(target), "-printf", "%D\\0%i\\0%y\\0"),
            budget=budget,
        )
        if rc or stderr:
            raise Refusal("selected-tree inode census is incomplete: " +
                          stderr.decode("utf-8", errors="replace").strip())
        for device, inode, kind in _census_nul_records(stdout, 3, "selected-tree find"):
            if kind not in {"b", "c", "d", "f", "l", "p", "s"}:
                raise Refusal("selected-tree find returned an invalid file type")
            has_sockets = has_sockets or kind == "s"
            if not device.isascii() or not device.isdecimal() or not inode.isascii() or not inode.isdecimal():
                raise Refusal("selected-tree find returned an invalid inode identity")
            identity = (int(device), int(inode))
            entries = collected.setdefault(identity, [])
            entry = (slot, f"{target} [device={device},inode={inode}]")
            if entry not in entries:
                entries.append(entry)
    return {identity: tuple(paths) for identity, paths in collected.items()}, has_sockets


def _batch_link_matches(
    processes: Sequence[_AbsentProcessObservation], targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[int, str, str, str], ...]:
    # Use the same literal link selection as the existing final same-UID pass.
    # Outside aliases are covered separately by followed device/inode stats.
    tests = _bounded_find_link_selection(targets)
    suffix = ("-ignore_readdir_race", "-maxdepth", "1", "-type", "l",
              "(", *tests, ")", "-printf", "%p\\0%l\\0")
    observed = {process.pid: process for process in processes}
    matches: list[tuple[int, str, str, str]] = []
    for arguments in _argument_batches(("-P",), _process_symlink_roots(processes), suffix):
        pids = {_pid_from_proc_evidence(Path(path))
                for path in arguments[1:len(arguments) - len(suffix)]}
        rc, stdout, stderr = _run_root_owned_command(Path("/usr/bin/find"), arguments, budget=budget)
        _allow_only_vanished_process_diagnostics(
            "find", rc, stderr, {pid: observed[pid] for pid in pids},
        )
        matches.extend(_parse_find_path_matches(stdout, observed, targets, census="privileged"))
    return tuple(matches)


def _direct_process_identity_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    inodes: Mapping[tuple[int, int], tuple[tuple[str, str], ...]],
    budget: _ReadOnlyCommandBudget,
    *,
    proc_root: Path = Path("/proc"),
) -> tuple[
    tuple[tuple[int, str, str, str], ...],
    tuple[tuple[int, str, str, str], ...],
    dict[int, set[int]],
    tuple[_AbsentProcessObservation, ...],
]:
    """Read same-UID link and inode evidence without a census output pipe.

    The privileged fallback used to print every descriptor on the host before
    Python discarded unrelated identities.  Agent workloads can hold enough
    descriptors for that irrelevant text to exhaust the shared output budget.
    Procfs applies the target process's filesystem credentials to these links,
    so directly readable same-UID processes can instead be compared in place.
    Protected and foreign-UID processes remain assigned to the complete root
    fallback below; no permission error is interpreted as evidence of absence.
    """

    link_matches: list[tuple[int, str, str, str]] = []
    inode_matches: list[tuple[int, str, str, str]] = []
    sockets: dict[int, set[int]] = {}
    fallback: list[_AbsentProcessObservation] = []
    match_cache: dict[Path, tuple[Path, str] | None] = {}

    for process in processes:
        budget.consume_observation()
        budget.remaining_seconds()
        pid_dir = proc_root / str(process.pid)
        try:
            filesystem_uid = _process_filesystem_uid(pid_dir)
        except Refusal:
            if not _process_generation_is_current(process):
                continue
            raise
        if filesystem_uid is None:
            if _process_generation_is_current(process):
                raise _ProcessEvidenceChanged(
                    f"PID {process.pid} status changed before direct inode census"
                )
            continue
        if filesystem_uid != os.getuid():
            fallback.append(process)
            continue

        process_link_matches: list[tuple[int, str, str, str]] = []
        process_inode_matches: list[tuple[int, str, str, str]] = []
        process_sockets: set[int] = set()
        needs_fallback = False
        vanished = False

        def observe(path: Path, *, transient: bool = False) -> bool:
            nonlocal vanished
            budget.consume_observation()
            budget.remaining_seconds()
            try:
                raw_target = os.readlink(path)
                metadata = path.stat()
            except FileNotFoundError:
                if transient:
                    return False
                if _process_generation_is_current(process):
                    raise _ProcessEvidenceChanged(
                        f"PID {process.pid} proc entries changed during direct inode census"
                    )
                vanished = True
                return False
            except PermissionError:
                return True
            except OSError as exc:
                # A disconnected cwd is the one stable procfs error for which
                # the historical lsof fallback is still authoritative.
                if path.name == "cwd" and exc.errno == errno.ENOTCONN:
                    return True
                if not _process_generation_is_current(process):
                    vanished = True
                    return False
                raise Refusal(
                    f"cannot inspect same-UID process {process.pid} inode "
                    f"evidence {path}: {exc}"
                ) from exc
            if stat.S_ISLNK(metadata.st_mode):
                if _process_generation_is_current(process):
                    raise _ProcessEvidenceChanged(
                        f"PID {process.pid} proc target changed during direct inode census"
                    )
                vanished = True
                return False
            observed_path = Path(
                os.path.normpath(raw_target.removesuffix(" (deleted)"))
            )
            matched = _matching_absent_validate_target(
                observed_path, targets, match_cache
            )
            if matched is not None:
                _target, slot = matched
                process_link_matches.append(
                    (process.pid, slot, "link", raw_target)
                )
            selected = inodes.get((metadata.st_dev, metadata.st_ino), ())
            for slot, selected_path in selected:
                process_inode_matches.append(
                    (process.pid, slot, "inode", f"{path}={selected_path}")
                )
            if stat.S_ISSOCK(metadata.st_mode):
                process_sockets.add(metadata.st_ino)
            return False

        for name in ("cwd", "root"):
            needs_fallback = observe(pid_dir / name)
            if vanished or needs_fallback:
                break
        if not vanished and not needs_fallback and not process.kernel_thread:
            needs_fallback = observe(pid_dir / "exe")
        if not vanished and not needs_fallback:
            try:
                budget.consume_observation()
                budget.remaining_seconds()
                with os.scandir(pid_dir / "fd") as descriptors:
                    for descriptor in descriptors:
                        if not descriptor.name.isdecimal():
                            raise Refusal(
                                f"PID {process.pid} descriptor census returned an "
                                f"unexpected entry: {descriptor.name!r}"
                            )
                        needs_fallback = observe(
                            Path(descriptor.path), transient=True
                        )
                        if needs_fallback:
                            break
            except FileNotFoundError:
                if _process_generation_is_current(process):
                    raise _ProcessEvidenceChanged(
                        f"PID {process.pid} fd directory changed during direct inode census"
                    )
                vanished = True
            except PermissionError:
                needs_fallback = True
            except OSError as exc:
                if not _process_generation_is_current(process):
                    vanished = True
                else:
                    raise Refusal(
                        f"cannot enumerate same-UID process {process.pid} descriptors: {exc}"
                    ) from exc

        if vanished or not _process_generation_is_current(process):
            if process_link_matches or process_inode_matches:
                # A child forked before the exit, outside the snapshot, can
                # still hold what this process was seen holding.
                raise Refusal(
                    f"PID {process.pid} identity changed after direct census "
                    "matched a selected path; the selected path may still be "
                    "in use"
                )
            # A socket inode alone names no path. A still-live socket bound
            # inside a target then has no holder in the namespace table that
            # lists it, which the Unix association hard-refuses. Recording
            # this exited holder would downgrade that to a retryable change.
            continue
        link_matches.extend(process_link_matches)
        inode_matches.extend(process_inode_matches)
        if needs_fallback:
            fallback.append(process)
            continue
        for inode in process_sockets:
            sockets.setdefault(inode, set()).add(process.pid)

    return tuple(link_matches), tuple(inode_matches), sockets, tuple(fallback)


def _bounded_inode_ranges(
    inodes: Mapping[tuple[int, int], object],
) -> tuple[tuple[int, int], ...]:
    """Cover every selected inode with finitely many producer predicates.

    Device identity is deliberately checked only by the consumer because GNU
    find has no device-number predicate. Merging the smallest gaps can emit
    unrelated candidates, but can never omit a selected inode.
    """

    values = sorted({inode for _device, inode in inodes})
    if any(inode <= 0 for inode in values):
        raise Refusal("selected-tree inode census returned an invalid inode identity")
    if not values:
        return ()
    gaps = [
        (values[index + 1] - values[index], index)
        for index in range(len(values) - 1)
        if values[index + 1] > values[index] + 1
    ]
    cuts = {
        index
        for _gap, index in sorted(gaps, key=lambda item: (-item[0], item[1]))[
            : _PROCESS_CENSUS_INODE_RANGE_LIMIT - 1
        ]
    }
    ranges: list[tuple[int, int]] = []
    first = values[0]
    for index, value in enumerate(values[:-1]):
        if index in cuts:
            ranges.append((first, value))
            first = values[index + 1]
    ranges.append((first, values[-1]))
    return tuple(ranges)


def _find_inode_selection(
    inodes: Mapping[tuple[int, int], object],
) -> tuple[str, ...]:
    """Select every socket and an over-approximation of selected inodes."""

    tests: list[str] = ["-type", "s"]
    for first, last in _bounded_inode_ranges(inodes):
        tests.append("-o")
        if first == last:
            tests.extend(("-inum", str(first)))
        else:
            tests.extend(
                (
                    "(",
                    "-inum",
                    f"+{first - 1}",
                    "-a",
                    "!",
                    "-inum",
                    f"+{last}",
                    ")",
                )
            )
    return tuple(tests)


def _privileged_inode_matches(
    processes: Sequence[_AbsentProcessObservation],
    inodes: Mapping[tuple[int, int], tuple[tuple[str, str], ...]],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[tuple[int, str, str, str], ...], dict[int, set[int]]]:
    """Follow proc links with stat, without reading fdinfo contents.

    cwd/root/exe are depth zero. Only the fd directory is enumerated: following
    cwd/root recursively would accidentally scan arbitrary process filesystems.
    """

    observed = {process.pid: process for process in processes}
    links: list[str] = []
    directories: list[str] = []
    for process in processes:
        base = Path("/proc") / str(process.pid)
        links.extend(str(base / name) for name in ("cwd", "root"))
        if not process.kernel_thread:
            links.append(str(base / "exe"))
        directories.append(str(base / "fd"))
    matches: list[tuple[int, str, str, str]] = []
    sockets: dict[int, set[int]] = {}
    fallback: set[int] = set()
    unreadable_cwds: set[str] = set()
    targets = {Path(slot): slot for paths in inodes.values() for slot, _name in paths}
    for roots, depths in ((links, ("-maxdepth", "0")),
                           (directories, ("-mindepth", "1", "-maxdepth", "1"))):
        suffix = (
            "-ignore_readdir_race",
            *depths,
            "(",
            *_find_inode_selection(inodes),
            ")",
            "-printf",
            "%p\\0%D\\0%i\\0%y\\0",
        )
        for arguments in _argument_batches(("-L",), roots, suffix):
            batch_pids = {_pid_from_proc_evidence(Path(path))
                          for path in arguments[1:len(arguments) - len(suffix)]}
            rc, stdout, stderr = _run_root_owned_command(
                Path("/usr/bin/find"), arguments, budget=budget,
            )
            try:
                _allow_only_vanished_process_diagnostics(
                    "find", rc, stderr, {pid: observed[pid] for pid in batch_pids},
                )
            except Refusal:
                # An observed disconnected cwd can defeat followed stat while
                # independent FD evidence remains complete. Only this exact
                # cwd error may use the historical oracle; unreadable FDs could
                # hide socket identities that a negative lsof result misses.
                if rc != 1 or not stderr or not targets:
                    raise
                for line in stderr.decode("ascii").splitlines():
                    diagnostic = re.fullmatch(
                        r"/usr/bin/find: '(/proc/([0-9]+)/cwd)': Transport endpoint is not connected", line,
                    )
                    if diagnostic is None or int(diagnostic[2]) not in batch_pids:
                        raise Refusal("proc inode find returned unattributed diagnostics")
                    pid = int(diagnostic[2])
                    if _process_generation_is_current(observed[pid]):
                        fallback.add(pid)
                        unreadable_cwds.add(diagnostic[1])
            for name, device, inode, kind in _census_nul_records(stdout, 4, "proc inode find"):
                pid = _pid_from_proc_evidence(Path(name))
                observation = observed.get(pid)
                if observation is None or pid not in batch_pids:
                    raise Refusal("proc inode find returned an unexpected PID")
                # GNU find reports U for anonymous descriptors whose stat mode
                # has no file-type bits. Still compare their device/inode.
                if not device.isascii() or not device.isdecimal() or not inode.isascii() or not inode.isdecimal() or kind not in {"b", "c", "d", "f", "l", "p", "s", "U"}:
                    raise Refusal("proc inode find returned an invalid inode identity")
                if kind == "l":
                    if name not in unreadable_cwds:
                        raise _ProcessEvidenceChanged(f"PID {pid} proc target changed during inode census")
                    continue
                identity = (int(device), int(inode))
                selected = inodes.get(identity, ())
                if selected or kind == "s":
                    if not _process_generation_is_current(observation):
                        raise _ProcessEvidenceChanged(f"PID {pid} generation changed during inode census")
                    for slot, path in selected:
                        matches.append((pid, slot, "inode", f"{name}={path}"))
                    if kind == "s":
                        sockets.setdefault(int(inode), set()).add(pid)
    if fallback:
        matches.extend(_batch_lsof_fallback(
            tuple(observed[pid] for pid in sorted(fallback)), targets, budget,
        ))
    return tuple(matches), sockets


def _merge_socket_holders(
    destination: dict[int, set[int]], source: Mapping[int, set[int]]
) -> None:
    for inode, pids in source.items():
        destination.setdefault(inode, set()).update(pids)


def _batch_inode_matches(
    processes: Sequence[_AbsentProcessObservation],
    targets: Mapping[Path, str],
    inodes: Mapping[tuple[int, int], tuple[tuple[str, str], ...]],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[tuple[int, str, str, str], ...], dict[int, set[int]]]:
    """Collect complete path/inode/socket evidence with bounded fallback output."""

    direct_links, direct_inodes, sockets, fallback = (
        _direct_process_identity_matches(processes, targets, inodes, budget)
    )
    privileged_links = _batch_link_matches(fallback, targets, budget)
    privileged_inodes, privileged_sockets = _privileged_inode_matches(
        fallback, inodes, budget
    )
    _merge_socket_holders(sockets, privileged_sockets)
    return (
        (*direct_links, *privileged_links, *direct_inodes, *privileged_inodes),
        sockets,
    )


_BATCH_MAPS_AWK = r'''
BEGIN {
    while ((r = getline item < "/dev/stdin") > 0) {
        if (substr(item, 1, 1) == "i") inodes[item] = 1;
        else paths[++count] = substr(item, 2);
    }
    if (r < 0) { print "maps selection input is unreadable" > "/dev/stderr"; exit 2; }
    close("/dev/stdin");
    for (file = 1; file < ARGC; file++) {
        path = ARGV[file];
        while ((r = getline row < path) > 0) {
            split(row, fields); selected = (("i" fields[5]) in inodes);
            for (i = 1; !selected && i <= count; i++) selected = index(row, paths[i]) != 0;
            if (selected) print path ":" row;
        }
        if (r < 0) { print path ": " ERRNO > "/dev/stderr"; failed = 1; }
        close(path);
    }
    exit failed;
}
'''


_BATCH_UNIX_AWK = r'''
BEGIN {
    while ((r = getline target < "/dev/stdin") > 0) targets[++count] = target;
    if (r < 0) { print "Unix socket selection input is unreadable" > "/dev/stderr"; exit 2; }
    close("/dev/stdin");
    file = ARGV[1]; rows = 0; truncated = 0;
    while ((r = getline row < file) > 0) {
        rows++;
        if (RT != "\n") truncated = 1;
        selected = (rows == 1);
        for (i = 1; !selected && i <= count; i++) selected = index(row, targets[i]) != 0;
        if (selected) print row;
    }
    if (r < 0) { print file ": " ERRNO > "/dev/stderr"; exit 2; }
    if (truncated) { print file ": missing final newline" > "/dev/stderr"; exit 2; }
    close(file);
}
'''


def _batch_maps_inode_matches(
    processes: Sequence[_AbsentProcessObservation], targets: Mapping[Path, str],
    inodes: Mapping[tuple[int, int], tuple[tuple[str, str], ...]],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[int, str, str, str], ...]:
    # A maps row retains device/inode even when its outside hardlink is the only
    # visible pathname, and even after the original descriptor has been closed.
    patterns = {"p" + str(target) for target in targets}
    # Prefix keys in both the input and awk lookup, with no numeric conversion:
    # inode strings above 2**53 must not collapse through floating-point keys.
    patterns.update(f"i{inode}" for _device, inode in inodes if inode)
    if any("\n" in value or "\0" in value for value in patterns):
        raise Refusal("validation paths containing line or NUL bytes cannot be probed")
    pattern_input = ("\n".join(sorted(patterns)) + "\n").encode("utf-8")
    observed = {process.pid: process for process in processes}
    files = [f"/proc/{process.pid}/maps" for process in processes]
    matches: list[tuple[int, str, str, str]] = []
    inode_numbers = {inode for _device, inode in inodes}
    unresolved: dict[str, bytes] = {}
    cache: dict[Path, tuple[Path, str] | None] = {}
    for arguments in _argument_batches(("--", _BATCH_MAPS_AWK), files, ()):
        batch_pids = {_pid_from_proc_evidence(Path(path)) for path in arguments[2:]}
        rc, stdout, stderr = _run_root_owned_command(
            Path("/usr/bin/gawk"),
            arguments,
            input_data=pattern_input,
            input_limit=_PROCESS_CENSUS_SELECTION_BYTES_LIMIT,
            budget=budget,
        )
        if rc or stderr:
            if rc != 1 or not stderr:
                raise Refusal(f"maps inode filter returned inconsistent exit {rc}")
            for diagnostic in stderr.decode("utf-8", errors="surrogateescape").splitlines():
                missing = re.fullmatch(r"/proc/([0-9]+)/maps: No such file or directory", diagnostic)
                if missing is None or int(missing[1]) not in batch_pids or _process_generation_is_current(observed[int(missing[1])]):
                    raise Refusal("maps inode filter produced diagnostics: " + diagnostic)
        for line in stdout.splitlines():
            raw_path, separator, mapping = line.partition(b":")
            if not separator:
                raise Refusal("inode maps census returned an unframed record")
            path = Path(raw_path.decode("ascii"))
            pid = _pid_from_proc_evidence(path)
            fields = mapping.decode("utf-8", errors="surrogateescape").split(maxsplit=5)
            if pid not in batch_pids or len(fields) not in (5, 6):
                raise Refusal("inode maps census returned a malformed record")
            try:
                major, minor = (int(part, 16) for part in fields[3].split(":"))
                identity = (os.makedev(major, minor), int(fields[4]))
            except (ValueError, OverflowError) as exc:
                raise Refusal("inode maps census returned an invalid identity") from exc
            selected = list(inodes.get(identity, ()))
            if not selected and identity[1] in inode_numbers:
                # Some filesystems expose a different device number in maps
                # than through stat. Never equate those devices or use inode
                # alone: ask the kernel-held mapping for its actual file stat.
                if not re.fullmatch(r"[0-9a-f]+-[0-9a-f]+", fields[0]):
                    raise Refusal("inode maps census returned an invalid address range")
                first, last = (int(value, 16) for value in fields[0].split("-"))
                if first >= last:
                    raise Refusal("inode maps census returned an invalid address range")
                unresolved[f"/proc/{pid}/map_files/{fields[0]}"] = line
            if len(fields) == 6:
                match = _matching_absent_validate_target(
                    Path(fields[5].removesuffix(" (deleted)")), targets, cache,
                )
                if match is not None:
                    selected.append((match[1], fields[5]))
            if selected:
                if not _process_generation_is_current(observed[pid]):
                    raise _ProcessEvidenceChanged(f"PID {pid} generation changed during maps census")
                for slot, name in selected:
                    matches.append((pid, slot, "map", f"{path}={name}"))
    if unresolved:
        matches.extend(_batch_map_file_matches(observed, unresolved, inodes, budget))
    return tuple(matches)



def _batch_map_file_matches(
    processes: Mapping[int, _AbsentProcessObservation], rows: Mapping[str, bytes],
    inodes: Mapping[tuple[int, int], tuple[tuple[str, str], ...]],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[int, str, str, str], ...]:
    """Resolve a maps/stat device mismatch through the kernel-held file."""

    suffix = ("-maxdepth", "0", "-printf", "%p\\0%D\\0%i\\0%y\\0")
    seen: set[str] = set()
    matches: list[tuple[int, str, str, str]] = []
    for arguments in _argument_batches(("-L",), tuple(rows), suffix):
        rc, stdout, stderr = _run_root_owned_command(Path("/usr/bin/find"), arguments, budget=budget)
        if rc or stderr:
            raise Refusal("map_files inode identity is unreadable: " + stderr.decode("utf-8", errors="replace").strip())
        for name, device, inode, kind in _census_nul_records(stdout, 4, "map_files find"):
            if name not in rows or name in seen or kind not in {"f", "c", "b"} or not device.isascii() or not device.isdecimal() or not inode.isascii() or not inode.isdecimal():
                raise Refusal("map_files inode identity is malformed or unavailable")
            seen.add(name)
            pid = _pid_from_proc_evidence(Path(name))
            if not _process_generation_is_current(processes[pid]):
                raise _ProcessEvidenceChanged(f"PID {pid} changed during map_files census")
            for slot, path in inodes.get((int(device), int(inode)), ()):
                matches.append((pid, slot, "map", f"{name}={path}"))
    if seen != set(rows):
        raise Refusal("map_files inode census omitted a requested mapping")
    # A mapping can be replaced at the same virtual address without PID reuse.
    # Require every original complete row after following the kernel map link.
    by_pid: dict[int, set[bytes]] = {}
    for name, row in rows.items():
        by_pid.setdefault(_pid_from_proc_evidence(Path(name)), set()).add(row)
    for pid, expected in by_pid.items():
        patterns = b"\n".join(row.partition(b":")[2] for row in sorted(expected)) + b"\n"
        rc, stdout, stderr = _run_root_owned_command(
            Path("/usr/bin/grep"), ("-F", "-H", "-x", "-f", "-", "--", f"/proc/{pid}/maps"),
            input_data=patterns, budget=budget,
        )
        if rc not in {0, 1} or stderr:
            raise Refusal("maps readback is unreadable after map_files census")
        if set(stdout.splitlines()) != expected or not _process_generation_is_current(processes[pid]):
            raise _ProcessEvidenceChanged(f"PID {pid} mappings changed during map_files census")
    return tuple(matches)


def _batch_lsof_fallback(
    processes: Sequence[_AbsentProcessObservation], targets: Mapping[Path, str],
    budget: _ReadOnlyCommandBudget,
) -> tuple[tuple[int, str, str, str], ...]:
    """Retain the original oracle only for the attributed disconnected cwd."""

    pids = {process.pid: process for process in processes}
    arguments = ["-nP", "-Fpcfn", "-a", "-p", ",".join(map(str, sorted(pids)))]
    for target in targets:
        arguments.extend(("+D", str(target)))
    rc, stdout, stderr = _run_same_uid_command(Path("/usr/bin/lsof"), arguments, budget=budget)
    for process in processes:
        if not _process_generation_is_current(process):
            raise _ProcessEvidenceChanged(f"PID {process.pid} changed during lsof fallback")
    diagnostics = stderr.decode("utf-8", errors="surrogateescape")
    if rc not in (0, 1) or any(not _unrelated_lsof_warnings(diagnostics, target) for target in targets):
        raise Refusal("disconnected cwd lsof fallback is incomplete")
    reported: set[int] = set()
    attributed: set[int] = set()
    current: int | None = None
    matches: list[tuple[int, str, str, str]] = []
    for line in stdout.decode("utf-8", errors="surrogateescape").splitlines():
        if line.startswith("p") and line[1:].isdigit():
            current = int(line[1:])
            if current not in pids:
                raise Refusal("disconnected cwd lsof fallback reported an unexpected PID")
            reported.add(current)
        elif line.startswith("n") and current is not None:
            name = line[1:].removesuffix(" (deleted)")
            matched = _matching_absent_validate_target(Path(name), targets)
            if matched is not None:
                attributed.add(current)
                matches.append((current, matched[1], "lsof", name))
    if reported != attributed:
        raise Refusal("disconnected cwd lsof fallback reported unattributed process use")
    return tuple(matches)


def _batch_network_namespaces(
    processes: Sequence[_AbsentProcessObservation], budget: _ReadOnlyCommandBudget,
) -> dict[int, str]:
    """Read exact namespace links with the same trusted full-host visibility."""

    observed = {process.pid: process for process in processes}
    roots = [f"/proc/{process.pid}/ns/net" for process in processes]
    suffix = ("-maxdepth", "0", "-printf", "%p\\0%l\\0")
    result: dict[int, str] = {}
    for arguments in _argument_batches(("-P",), roots, suffix):
        batch = {_pid_from_proc_evidence(Path(path)) for path in arguments[1:-len(suffix)]}
        rc, stdout, stderr = _run_root_owned_command(Path("/usr/bin/find"), arguments, budget=budget)
        _allow_only_vanished_process_diagnostics("find", rc, stderr, {pid: observed[pid] for pid in batch})
        for path, namespace in _census_nul_records(stdout, 2, "network namespace find"):
            pid = _pid_from_proc_evidence(Path(path))
            if pid not in batch or path != f"/proc/{pid}/ns/net" or pid in result:
                raise Refusal("network namespace census returned an unexpected path")
            if not _process_generation_is_current(observed[pid]):
                continue
            if not re.fullmatch(r"net:\[[0-9]+\]", namespace):
                raise Refusal(f"network namespace is unreadable or malformed for PID {pid}")
            result[pid] = namespace
    for process in processes:
        if process.pid not in result and _process_generation_is_current(process):
            raise Refusal(f"network namespace census omitted PID {process.pid}")
    return result


def _batch_unix_socket_matches(
    processes: Sequence[_AbsentProcessObservation], targets: Mapping[Path, str],
    holders: Mapping[int, set[int]], budget: _ReadOnlyCommandBudget,
    *, selected_has_sockets: bool = False,
) -> tuple[tuple[int, str, str, str], ...]:
    """Associate namespace-local Unix names with the sockets held by processes.

    A process can retain a socket after changing network namespaces, so consult
    every observed namespace, not just the holder's current namespace.
    """

    namespaces: dict[str, list[_AbsentProcessObservation]] = {}
    bindings = _batch_network_namespaces(processes, budget)
    for process in processes:
        if process.pid in bindings:
            namespaces.setdefault(bindings[process.pid], []).append(process)
    matches: list[tuple[int, str, str, str]] = []
    cache: dict[Path, tuple[Path, str] | None] = {}
    observed = {process.pid: process for process in processes}
    unresolved: set[int] = set()
    accounted: set[int] = set()
    selected_representatives: list[_AbsentProcessObservation] = []
    target_input = ("\n".join(map(str, targets)) + "\n").encode("utf-8")
    if any("\n" in str(target) or "\0" in str(target) for target in targets):
        raise Refusal("validation paths containing line or NUL bytes cannot be probed")
    for namespace, representatives in namespaces.items():
        contents: bytes | None = None
        for process in representatives:
            path = Path(f"/proc/{process.pid}/net/unix")
            try:
                if selected_has_sockets:
                    rc, contents, stderr = _run_root_owned_command(
                        Path("/usr/bin/cat"), ("--", str(path)), budget=budget
                    )
                else:
                    rc, contents, stderr = _run_root_owned_command(
                        Path("/usr/bin/gawk"),
                        ("--", _BATCH_UNIX_AWK, str(path)),
                        input_data=target_input,
                        input_limit=_PROCESS_CENSUS_SELECTION_BYTES_LIMIT,
                        budget=budget,
                    )
                if rc or stderr or len(contents) > _UNIX_SOCKET_TABLE_BYTES_LIMIT:
                    raise Refusal(f"Unix socket census is incomplete for PID {process.pid}")
                budget.remaining_seconds()
                if not _process_generation_is_current(process):
                    contents = None
                    continue
            except (OSError, Refusal) as exc:
                if not _process_generation_is_current(process):
                    contents = None
                    continue
                if isinstance(exc, Refusal):
                    raise
                raise Refusal(f"Unix socket census is unreadable for PID {process.pid}: {exc}") from exc
            selected_representatives.append(process)
            break
        if contents is None:
            raise _ProcessEvidenceChanged("network namespace representatives changed during socket census")
        lines = contents.decode("utf-8", errors="surrogateescape").split("\n")
        if lines[-1] != "":
            raise Refusal("Unix socket census returned a truncated record")
        lines.pop()
        if not lines or lines[0].split() != ["Num", "RefCount", "Protocol", "Flags", "Type", "St", "Inode", "Path"]:
            raise Refusal("Unix socket census returned a malformed header")
        for line in lines[1:]:
            # The kernel emits one delimiter after the inode. Keep every byte
            # after that delimiter: even a whitespace-only relative name is a
            # legal filesystem socket, distinct from an unnamed socket.
            fields = re.fullmatch(
                r"[0-9a-fA-F]+:[ \t]+(?:[0-9a-fA-F]+[ \t]+){5}([0-9]+)(?: (.*))?", line,
            )
            if fields is None:
                raise Refusal("Unix socket census returned a malformed record")
            inode = int(fields[1])
            accounted.add(inode)
            pathname = fields[2]
            if pathname is None:
                continue  # An unnamed socket has no bound filesystem path.
            name = Path(pathname)
            pids = holders.get(inode, set())
            if pathname.startswith("@"):
                # proc renders both abstract addresses and a filesystem-relative
                # '@name' this way. With selected socket nodes its identity is
                # unresolved; the prefix alone is never abstract proof.
                if selected_has_sockets:
                    unresolved.update(pids)
                continue
            if not name.is_absolute():
                # A namespace table also lists sockets held by other processes.
                # Only held descriptor identities belong to this census. Relative
                # bind paths cannot be reconstructed from the holder's later cwd.
                if selected_has_sockets:
                    unresolved.update(pids)
                continue
            matched = _matching_absent_validate_target(name, targets, cache)
            if matched is None:
                if selected_has_sockets:
                    # The bound name can be an outside hardlink of a socket node
                    # in a selected tree; its object identity remains unresolved.
                    unresolved.update(pids)
                continue
            if not pids:
                raise Refusal(f"Unix socket remains bound inside {matched[0]} without a stable observed holder")
            for pid in pids:
                if not _process_generation_is_current(observed[pid]):
                    raise _ProcessEvidenceChanged(f"PID {pid} changed during Unix socket census")
                matches.append((pid, matched[1], "socket", str(name)))
    after = _batch_network_namespaces(selected_representatives, budget)
    if after != {process.pid: bindings[process.pid] for process in selected_representatives}:
        raise _ProcessEvidenceChanged("network namespace representatives changed during socket census")
    if selected_has_sockets and set(holders) - accounted:
        # A socket can outlive the last process in its originating network
        # namespace. Its FD alone establishes neither its family nor its bound
        # name, so tables from current process namespaces cannot prove clear.
        raise Refusal("held socket identities are absent from observed Unix tables; selected socket-node use is unknown")
    if unresolved:
        # A positive match for this PID in one selected tree cannot establish
        # that an unresolved socket does not use another selected tree.
        raise Refusal("Unix socket census cannot attribute a relative bound pathname or alias")
    return tuple(matches)


def _capture_lsof_process_path_census(
    slot_paths: Sequence[Path], *, budget: _ReadOnlyCommandBudget,
) -> _ProcessPathCensus:
    """Preserve the batch's historical file/alias/socket proof without fdinfo.

    Keep the internal entrypoint used by batch recovery and its fresh same-UID
    guard. The general path-only census remains separate: inode and Unix socket
    evidence are required here before this batch can be declared unused.
    """

    targets = {path: str(path) for path in slot_paths}
    if not targets:
        return _ProcessPathCensus((), (), owner_cgroup_complete=False)
    before = {path: _open_directory_identity(path, "selected census tree") for path in targets}
    inodes, has_sockets = _selected_tree_inodes(targets, budget)
    if has_sockets:
        # A Unix bound-name string does not authenticate the held filesystem
        # object: that name can be unlinked/rebound while a hardlink survives in
        # another selected tree. Do not declare any member of this cohort unused
        # without kernel socket-object identity evidence.
        raise Refusal("selected tree contains a filesystem socket node; socket-object liveness is unproven")
    for attempt in range(3):
        budget.remaining_seconds()
        try:
            processes = _absent_validate_process_snapshot(include_owner_cgroups=False)
            mounts = _absent_validate_mount_matches(processes, targets, budget)
            identities, sockets = _batch_inode_matches(
                processes, targets, inodes, budget
            )
            maps = _batch_maps_inode_matches(processes, targets, inodes, budget)
            unix = _batch_unix_socket_matches(
                processes, targets, sockets, budget, selected_has_sockets=has_sockets,
            )
        except _ProcessEvidenceChanged:
            if attempt < 2:
                continue
            raise Refusal("batch process evidence changed during three liveness attempts")
        if before != {path: _open_directory_identity(path, "selected census tree") for path in targets}:
            raise Refusal("selected census tree identity changed during process census")
        budget.remaining_seconds()
        return _ProcessPathCensus(
            processes,
            (*mounts, *identities, *maps, *unix),
            owner_cgroup_complete=False,
        )
    raise Refusal("batch process census is indeterminate")


@dataclasses.dataclass(frozen=True)
class _PrivateCleanupTarget:
    """One validation slot sealed before its shared destructive census."""

    path: Path
    original_mode: int
    identity: _PrivateCleanupIdentity


@dataclasses.dataclass
class _PrivateCleanupContext:
    """Sealed target and batch-wide evidence budget for its final scan."""

    target: _PrivateCleanupTarget
    shared_census: _ProcessPathCensus
    census_budget: _ReadOnlyCommandBudget
    scoped_finish: bool = False
    fresh_census: _ProcessPathCensus | None = None
    same_uid_census_performed: bool = False
    live_use_recheck: _LiveUseRecheckBudget = dataclasses.field(
        default_factory=_LiveUseRecheckBudget
    )


@dataclasses.dataclass
class _OwnerlessValidationBatchContext:
    """Shared full-host evidence plus fresh checks for private ownerless paths."""

    canonical_by_identity: Mapping[_PrivateCleanupIdentity, Path]
    shared_census: _ProcessPathCensus
    census_budget: _ReadOnlyCommandBudget
    same_uid_census_count: int = 0
    live_use_recheck: _LiveUseRecheckBudget = dataclasses.field(
        default_factory=_LiveUseRecheckBudget
    )

    def assert_unused(
        self, config: Config, active: Path, *, fresh_same_uid: bool
    ) -> None:
        managed_root = (
            _frozen_validation_directory(config)
            if active.parent == _frozen_validation_directory(config)
            else None
        )
        identity = _private_cleanup_path_identity(
            config, active, allowed_modes={0o700}, managed_root=managed_root
        )
        canonical = self.canonical_by_identity.get(identity)
        if canonical is None:
            raise Refusal(
                f"private validation checkout identity was not in the shared census: {active}"
            )
        # Keep the ordinary explicit cwd guard for both the canonical and
        # renamed path without launching another process census.
        _assert_slot_unused(
            active,
            census=_ProcessPathCensus((), (), owner_cgroup_complete=False),
        )
        self.shared_census.assert_slot_unused(
            canonical, None, ignore_current_process=False
        )
        if not fresh_same_uid:
            return
        self.same_uid_census_count += 1
        fresh_budget = _ReadOnlyCommandBudget.start(
            timeout_seconds=self.census_budget.remaining_seconds(),
            stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
            stderr_limit=64 * 1024,
            input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
        fresh = _capture_same_uid_process_path_census(
            (active,), budget=fresh_budget
        )
        fresh.assert_slot_unused(active, None, ignore_current_process=False)
        self.census_budget.remaining_seconds()


@dataclasses.dataclass
class _OwnerlessValidationExclusion:
    """An ownerless validation tree hidden behind a root-owned directory."""

    root: Path
    guard: Path
    payload: Path
    source_alias: Path
    root_fd: int
    source_parent_fd: int
    guard_fd: int
    payload_fd: int
    record: _OwnerlessValidationExclusionRecord

    def close(self) -> None:
        for descriptor in (
            self.payload_fd,
            self.guard_fd,
            self.source_parent_fd,
            self.root_fd,
        ):
            with contextlib.suppress(OSError):
                os.close(descriptor)


@dataclasses.dataclass(frozen=True)
class _FinishContext:
    """Immutable policy and evidence carried through one finish operation."""

    mode: str
    actor: str
    salvage: tuple[Mapping[str, object], ...] = ()
    validate_complete: bool = False
    allow_live_validate_owner: bool = False
    private_cleanup: _PrivateCleanupContext | None = None
    validation_removal_proof: _ValidationRemovalProof | None = None
    live_use_recheck: _LiveUseRecheckBudget | None = None
    owner_consented: bool = False
    # Set only by remove-agent-batch.  It replaces the ordinary lsof run in the
    # use checks made before the path fence with the batch's shared lsof
    # evidence plus a fresh in-process scan.  The checks made after the fence,
    # which guard deletion, stay ordinary.  It is never written to the finish
    # journal: recovery of an interrupted item runs the ordinary checks.
    agent_batch: _AgentRemoveBatchContext | None = None
    # Filled by the cache-removal step from the finish journal: one entry per
    # nested repository judged disposable (checkout, canonical .git path, HEAD,
    # containing remote ref, and the ignored entries deleted with it).
    nested_git_evidence: list[dict[str, object]] = dataclasses.field(
        default_factory=list
    )


@dataclasses.dataclass(frozen=True)
class _PreparedPrivateFinish:
    """Durable path fence awaiting its final out-of-lock liveness census."""

    record: ActiveRecord
    journal: Mapping[str, object]
    journal_path: Path


def _capture_process_path_census(
    slot_paths: Sequence[Path],
    *,
    budget: _ReadOnlyCommandBudget | None = None,
    include_owner_cgroups: bool = True,
) -> _ProcessPathCensus:
    targets = {path: str(path) for path in slot_paths}
    if not targets:
        return _ProcessPathCensus(
            (), (), owner_cgroup_complete=include_owner_cgroups
        )
    selected_budget = budget or _ReadOnlyCommandBudget.start(
        timeout_seconds=_ABSENT_PROCESS_CENSUS_SECONDS,
        stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    for attempt in range(3):
        selected_budget.remaining_seconds()
        try:
            processes = (
                _absent_validate_process_snapshot()
                if include_owner_cgroups
                else _absent_validate_process_snapshot(
                    include_owner_cgroups=False
                )
            )
            processes = _preflight_process_observations(
                processes, selected_budget
            )
            path_matches = (
                *_absent_validate_find_matches(processes, targets, selected_budget),
                *_absent_validate_maps_matches(processes, targets, selected_budget),
            )
            # A failed path observation discards the whole attempt without
            # first rereading every mount table. Budgets never reset on retry.
            mount_matches = _absent_validate_mount_matches(
                processes, targets, selected_budget
            )
        except _ProcessEvidenceChanged:
            if attempt < 2:
                continue
            raise Refusal(
                "relevant process evidence changed during three liveness attempts"
            )
        return _ProcessPathCensus(
            processes,
            (*mount_matches, *path_matches),
            owner_cgroup_complete=include_owner_cgroups,
        )
    raise Refusal(
        "all-process liveness proof is indeterminate because relevant process "
        "evidence changed during three attempts"
    )


def _assert_absent_validate_processes_unrelated(
    rows: Sequence[tuple[ActiveRecord, tuple[Path, ...]]],
) -> tuple[_AbsentProcessObservation, ...]:
    targets = {path: record.slot for record, row_paths in rows for path in row_paths}
    budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=_ABSENT_PROCESS_CENSUS_SECONDS,
        stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    for attempt in range(3):
        try:
            processes = _absent_validate_process_snapshot()
            match = _absent_validate_mount_match(processes, targets, budget)
            if match is not None:
                pid, slot, kind, detail = match
                raise Refusal(
                    f"live process {pid} may still use validation row {slot}: " f"{kind}={detail}"
                )
            match = _absent_validate_privileged_path_match(processes, targets, budget)
        except _ProcessEvidenceChanged:
            if attempt < 2:
                continue
            raise Refusal(
                "relevant process evidence changed during three liveness attempts"
            )
        if match is not None:
            pid, slot, kind, detail = match
            observed = next((process for process in processes if process.pid == pid), None)
            if observed is None or (
                _process_start_ticks(Path("/proc") / str(pid)) != observed.start_ticks
            ):
                continue
            raise Refusal(
                f"live process {pid} may still use validation row {slot}: " f"{kind}={detail}"
            )
        return processes
    raise Refusal(
        "all-process liveness proof is indeterminate because relevant process "
        "evidence changed during three attempts"
    )


_USER_SYSTEMD_BUS_NAME = "org.freedesktop.systemd1"
_USER_SYSTEMD_MANAGER_PATH = "/org/freedesktop/systemd1"
_USER_SYSTEMD_MANAGER_INTERFACE = "org.freedesktop.systemd1.Manager"
_USER_SYSTEMD_UNIT_INTERFACE = "org.freedesktop.systemd1.Unit"
_USER_SYSTEMD_SERVICE_PROPERTIES = (
    ("ControlGroup", "s"),
    ("MainPID", "u"),
    ("WorkingDirectory", "s"),
    ("ExecStart", "a(sasbttttuii)"),
    ("ExecStartPre", "a(sasbttttuii)"),
    ("ExecStartPost", "a(sasbttttuii)"),
    ("ExecReload", "a(sasbttttuii)"),
    ("ExecStop", "a(sasbttttuii)"),
    ("ExecStopPost", "a(sasbttttuii)"),
    ("Environment", "as"),
    ("EnvironmentFiles", "a(sb)"),
    ("RootDirectory", "s"),
    ("RootImage", "s"),
    ("BindPaths", "a(ssbt)"),
    ("BindReadOnlyPaths", "a(ssbt)"),
    ("ReadWritePaths", "as"),
    ("ReadOnlyPaths", "as"),
    ("InaccessiblePaths", "as"),
    ("StandardInput", "s"),
    ("StandardOutput", "s"),
    ("StandardError", "s"),
)
_USER_SYSTEMD_SCOPE_PROPERTIES = (("ControlGroup", "s"),)
_USER_SYSTEMD_UNIT_PROPERTIES = (
    ("Id", "s"),
    ("LoadState", "s"),
    ("ActiveState", "s"),
    ("SubState", "s"),
    ("RequiresMountsFor", "as"),
)


def _run_user_busctl(
    arguments: Sequence[str],
    budget: _ReadOnlyCommandBudget,
    *,
    raw_listing: bool = False,
) -> bytes:
    """Run one trusted, bounded user-manager D-Bus query.

    A manager listing contains arbitrary descriptions that are not liveness
    evidence.  Its raw JSON has a separate finite input bound; after strict
    parsing, the caller charges only the typed unit-identity projection to the
    shared evidence-output budget.  Property replies are evidence and remain
    charged byte-for-byte.
    """

    busctl = _root_owned_executable(Path("/usr/bin/busctl"), "busctl")
    command = [str(busctl.path), "--user", "--json=short", *arguments]
    if sum(len(os.fsencode(argument)) + 1 for argument in command) > 64 * 1024:
        raise Refusal("user-systemd D-Bus command exceeds the 64 KiB argv bound")
    stdout_limit = (
        _USER_SYSTEMD_LISTING_BYTES_LIMIT
        if raw_listing
        else budget.stdout_remaining
    )
    stderr_limit = budget.stderr_remaining
    if stdout_limit <= 0 or stderr_limit <= 0:
        raise Refusal("user-systemd census exhausted its operation-wide output bound")
    returncode, stdout, stderr = _run_bounded_read_only_command(
        command,
        timeout_seconds=budget.remaining_seconds(),
        stdout_limit=stdout_limit,
        stderr_limit=stderr_limit,
        env_overrides=_user_bus_environment(),
        trusted_executables=(busctl,),
    )
    budget.remaining_seconds()
    if raw_listing:
        if len(stdout) > _USER_SYSTEMD_LISTING_BYTES_LIMIT:
            raise Refusal(
                "user-systemd unit listing exceeds its per-listing bound of "
                f"{_USER_SYSTEMD_LISTING_BYTES_LIMIT} bytes"
            )
        budget.reserve_input(len(stdout))
        budget.consume_output(b"", stderr)
    else:
        budget.consume_output(stdout, stderr)
    if returncode != 0:
        detail = (stderr or stdout).decode("utf-8", errors="replace").strip().splitlines()
        raise Refusal(
            "cannot enumerate user-systemd state"
            + (f": {detail[0]}" if detail else "")
        )
    if stderr:
        raise Refusal(
            "cannot enumerate user-systemd state: "
            + stderr.decode("utf-8", errors="replace").splitlines()[0]
        )
    return stdout


def _user_bus_environment() -> dict[str, str]:
    uid = os.getuid()
    expected = Path(f"/run/user/{uid}")
    runtime = os.environ.get("XDG_RUNTIME_DIR")
    if runtime != str(expected):
        raise Refusal(f"XDG_RUNTIME_DIR must be the current user's runtime directory {expected}")
    try:
        metadata = expected.lstat()
    except OSError as exc:
        raise Refusal(f"cannot inspect XDG_RUNTIME_DIR {expected}: {exc}") from exc
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_uid != uid
        or metadata.st_mode & 0o022
    ):
        raise Refusal(f"XDG_RUNTIME_DIR is not a private owned directory: {expected}")
    result = {"XDG_RUNTIME_DIR": str(expected)}
    address = os.environ.get("DBUS_SESSION_BUS_ADDRESS")
    if address is None:
        return result
    prefix = "unix:path="
    if not address.startswith(prefix) or any(token in address for token in (",", ";")):
        raise Refusal("DBUS_SESSION_BUS_ADDRESS is not one local unix:path endpoint")
    path = Path(address.removeprefix(prefix))
    if not path.is_absolute() or path.parent != expected:
        raise Refusal("DBUS_SESSION_BUS_ADDRESS is outside XDG_RUNTIME_DIR")
    try:
        socket_metadata = path.lstat()
    except OSError as exc:
        raise Refusal(f"cannot inspect DBUS_SESSION_BUS_ADDRESS socket {path}: {exc}") from exc
    if not stat.S_ISSOCK(socket_metadata.st_mode) or socket_metadata.st_uid != uid:
        raise Refusal("DBUS_SESSION_BUS_ADDRESS is not an owned unix socket")
    result["DBUS_SESSION_BUS_ADDRESS"] = address
    return result


def _user_busctl_json_document(contents: bytes, label: str) -> Mapping[str, object]:
    try:
        document = _strict_json_object(contents, label)
    except (Refusal, StateError) as exc:
        raise Refusal(f"{label} is not one strict JSON object: {exc}") from exc
    if set(document) != {"type", "data"}:
        raise Refusal(f"{label} has unexpected JSON fields")
    if not isinstance(document["type"], str):
        raise Refusal(f"{label} has a non-string D-Bus signature")
    return document


def _user_busctl_json_documents(
    stdout: bytes, expected: int, label: str
) -> tuple[Mapping[str, object], ...]:
    # `--json=short` emits exactly one physical line per return value and JSON
    # escapes every newline inside a D-Bus string.  Requiring its final newline
    # makes a complete-but-unframed prefix a refusal rather than evidence.
    if not stdout.endswith(b"\n"):
        raise Refusal(f"{label} is truncated or lacks its terminal newline")
    lines = stdout[:-1].split(b"\n")
    if len(lines) != expected or any(not line for line in lines):
        raise Refusal(
            f"{label} returned {len(lines)} JSON documents; expected {expected}"
        )
    return tuple(
        _user_busctl_json_document(line, f"{label} document {index}")
        for index, line in enumerate(lines, start=1)
    )


def _user_busctl_string(value: object, label: str) -> str:
    if not isinstance(value, str) or "\0" in value:
        raise Refusal(f"{label} is not one D-Bus string")
    return value


def _user_busctl_integer(value: object, bits: int, signed: bool, label: str) -> int:
    minimum = -(1 << (bits - 1)) if signed else 0
    maximum = (1 << (bits - 1)) - 1 if signed else (1 << bits) - 1
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or value < minimum
        or value > maximum
    ):
        kind = "signed" if signed else "unsigned"
        raise Refusal(f"{label} is not one {bits}-bit {kind} D-Bus integer")
    return value


def _user_busctl_typed_value(signature: str, value: object, label: str) -> object:
    """Validate the complete JSON shape for every property type we consume."""

    if signature == "s":
        return _user_busctl_string(value, label)
    if signature == "u":
        return _user_busctl_integer(value, 32, False, label)
    if not isinstance(value, list):
        raise Refusal(f"{label} is not a D-Bus array")
    if signature == "as":
        return [
            _user_busctl_string(item, f"{label}[{index}]")
            for index, item in enumerate(value)
        ]
    if signature == "a(sb)":
        result: list[list[object]] = []
        for index, item in enumerate(value):
            if not isinstance(item, list) or len(item) != 2:
                raise Refusal(f"{label}[{index}] is not one (string, boolean) tuple")
            name = _user_busctl_string(item[0], f"{label}[{index}][0]")
            if not isinstance(item[1], bool):
                raise Refusal(f"{label}[{index}][1] is not one D-Bus boolean")
            result.append([name, item[1]])
        return result
    if signature == "a(ssbt)":
        result = []
        for index, item in enumerate(value):
            if not isinstance(item, list) or len(item) != 4:
                raise Refusal(f"{label}[{index}] is not one (ssbt) tuple")
            source = _user_busctl_string(item[0], f"{label}[{index}][0]")
            target = _user_busctl_string(item[1], f"{label}[{index}][1]")
            if not isinstance(item[2], bool):
                raise Refusal(f"{label}[{index}][2] is not one D-Bus boolean")
            flags = _user_busctl_integer(
                item[3], 64, False, f"{label}[{index}][3]"
            )
            result.append([source, target, item[2], flags])
        return result
    if signature == "a(sasbttttuii)":
        result = []
        for index, item in enumerate(value):
            if not isinstance(item, list) or len(item) != 10:
                raise Refusal(f"{label}[{index}] is not one Exec command tuple")
            path = _user_busctl_string(item[0], f"{label}[{index}][0]")
            if not isinstance(item[1], list):
                raise Refusal(f"{label}[{index}][1] is not an argument array")
            arguments = [
                _user_busctl_string(argument, f"{label}[{index}][1][{offset}]")
                for offset, argument in enumerate(item[1])
            ]
            if not isinstance(item[2], bool):
                raise Refusal(f"{label}[{index}][2] is not one D-Bus boolean")
            times = [
                _user_busctl_integer(
                    item[offset], 64, False, f"{label}[{index}][{offset}]"
                )
                for offset in range(3, 7)
            ]
            pid = _user_busctl_integer(item[7], 32, False, f"{label}[{index}][7]")
            code = _user_busctl_integer(item[8], 32, True, f"{label}[{index}][8]")
            status = _user_busctl_integer(item[9], 32, True, f"{label}[{index}][9]")
            result.append([path, arguments, item[2], *times, pid, code, status])
        return result
    raise AssertionError(f"unsupported user-systemd D-Bus signature {signature}")


# Separates the strings of an array property (``ExecStart`` arguments,
# ``Environment`` assignments, ``ReadWritePaths`` entries) in the one string
# ``_user_systemd_properties`` returns for it.  An argument can hold a
# newline, so a newline cannot also mark where one ends; a D-Bus string
# never holds a NUL character.
_UNIT_PROPERTY_ELEMENT_SEPARATOR = "\0"


def _user_busctl_string_evidence(value: object) -> tuple[str, ...]:
    if isinstance(value, str):
        return (value,)
    if isinstance(value, list):
        return tuple(
            text for item in value for text in _user_busctl_string_evidence(item)
        )
    return ()


def _user_systemd_properties(
    object_path: str,
    interface: str,
    properties: Sequence[tuple[str, str]],
    budget: _ReadOnlyCommandBudget,
) -> dict[str, str]:
    stdout = _run_user_busctl(
        (
            "get-property",
            _USER_SYSTEMD_BUS_NAME,
            object_path,
            interface,
            *(name for name, _signature in properties),
        ),
        budget,
    )
    documents = _user_busctl_json_documents(
        stdout, len(properties), f"user-systemd {interface} properties"
    )
    result: dict[str, str] = {}
    for (name, signature), document in zip(properties, documents, strict=True):
        if document["type"] != signature:
            raise Refusal(
                f"user-systemd property {name} has signature {document['type']!r}; "
                f"expected {signature!r}"
            )
        value = _user_busctl_typed_value(
            signature, document["data"], f"user-systemd property {name}"
        )
        if isinstance(value, str):
            result[name] = value
        elif isinstance(value, int):
            result[name] = str(value)
        else:
            result[name] = _UNIT_PROPERTY_ELEMENT_SEPARATOR.join(
                _user_busctl_string_evidence(value)
            )
    return result


def _user_systemd_unit_name(value: object, label: str) -> str:
    unit = _user_busctl_string(value, label)
    if (
        not unit
        or len(os.fsencode(unit)) > 255
        or any(character.isspace() for character in unit)
    ):
        raise Refusal(f"{label} is not one bounded systemd unit name")
    return unit


def _user_systemd_object_path(value: object, label: str) -> str:
    path = _user_busctl_string(value, label)
    if re.fullmatch(r"/org/freedesktop/systemd1/unit/[A-Za-z0-9_]+", path) is None:
        raise Refusal(f"{label} is not one systemd unit object path")
    return path


def _user_systemd_state(value: object, label: str) -> str:
    state = _user_busctl_string(value, label)
    if re.fullmatch(r"[a-z][a-z0-9-]*", state) is None:
        raise Refusal(f"{label} is not one systemd state")
    return state


def _user_systemd_units(budget: _ReadOnlyCommandBudget) -> tuple[_UserSystemdUnit, ...]:
    stdout = _run_user_busctl(
        (
            "call",
            _USER_SYSTEMD_BUS_NAME,
            _USER_SYSTEMD_MANAGER_PATH,
            _USER_SYSTEMD_MANAGER_INTERFACE,
            "ListUnitsByPatterns",
            "asas",
            "0",
            "2",
            "*.service",
            "*.scope",
        ),
        budget,
        raw_listing=True,
    )
    document = _user_busctl_json_documents(
        stdout, 1, "user-systemd unit listing"
    )[0]
    if document["type"] != "a(ssssssouso)":
        raise Refusal(
            "user-systemd unit listing has signature "
            f"{document['type']!r}; expected 'a(ssssssouso)'"
        )
    data = document["data"]
    if not isinstance(data, list) or len(data) != 1 or not isinstance(data[0], list):
        raise Refusal("user-systemd unit listing has an invalid return-value shape")
    if len(data[0]) > _USER_SYSTEMD_UNIT_LIMIT:
        raise Refusal(
            f"user-systemd unit population exceeds {_USER_SYSTEMD_UNIT_LIMIT}"
        )
    result: list[_UserSystemdUnit] = []
    names: set[str] = set()
    object_paths: set[str] = set()
    for index, item in enumerate(data[0]):
        label = f"user-systemd unit listing row {index}"
        if not isinstance(item, list) or len(item) != 10:
            raise Refusal(f"{label} is not one ListUnits tuple")
        unit = _user_systemd_unit_name(item[0], f"{label} name")
        if not unit.endswith((".service", ".scope")):
            raise Refusal(f"{label} returned an unexpected unit type")
        _user_busctl_string(item[1], f"{label} description")
        load_state = _user_systemd_state(item[2], f"{label} load state")
        active_state = _user_systemd_state(item[3], f"{label} active state")
        sub_state = _user_systemd_state(item[4], f"{label} substate")
        following = _user_busctl_string(item[5], f"{label} following unit")
        if following:
            raise Refusal(f"{label} is an unresolved unit alias")
        object_path = _user_systemd_object_path(item[6], f"{label} object path")
        job_id = _user_busctl_integer(item[7], 32, False, f"{label} job id")
        job_type = _user_busctl_string(item[8], f"{label} job type")
        job_path = _user_busctl_string(item[9], f"{label} job path")
        if job_id == 0:
            if job_type or job_path != "/":
                raise Refusal(f"{label} has inconsistent absent-job fields")
        elif (
            re.fullmatch(r"[a-z][a-z0-9-]*", job_type) is None
            or job_path != f"/org/freedesktop/systemd1/job/{job_id}"
        ):
            raise Refusal(f"{label} has inconsistent live-job fields")
        if unit in names or object_path in object_paths:
            raise Refusal("user-systemd unit listing has duplicate identities")
        names.add(unit)
        object_paths.add(object_path)
        result.append(
            _UserSystemdUnit(
                unit,
                load_state,
                active_state,
                sub_state,
                object_path,
                job_id,
                job_type,
                job_path,
            )
        )
    projection = json.dumps(
        [
            [
                unit.unit,
                unit.load_state,
                unit.active_state,
                unit.sub_state,
                unit.object_path,
                unit.job_id,
                unit.job_type,
                unit.job_path,
            ]
            for unit in result
        ],
        ensure_ascii=True,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("ascii")
    budget.consume_output(projection, b"")
    return tuple(result)


def _user_systemd_jobs(
    budget: _ReadOnlyCommandBudget,
    units: Mapping[str, _UserSystemdUnit],
) -> dict[str, tuple[int, str, str]]:
    stdout = _run_user_busctl(
        (
            "call",
            _USER_SYSTEMD_BUS_NAME,
            _USER_SYSTEMD_MANAGER_PATH,
            _USER_SYSTEMD_MANAGER_INTERFACE,
            "ListJobs",
        ),
        budget,
    )
    document = _user_busctl_json_documents(stdout, 1, "user-systemd job listing")[0]
    if document["type"] != "a(usssoo)":
        raise Refusal(
            "user-systemd job listing has signature "
            f"{document['type']!r}; expected 'a(usssoo)'"
        )
    data = document["data"]
    if not isinstance(data, list) or len(data) != 1 or not isinstance(data[0], list):
        raise Refusal("user-systemd job listing has an invalid return-value shape")
    result: dict[str, tuple[int, str, str]] = {}
    ids: set[int] = set()
    for index, item in enumerate(data[0]):
        label = f"user-systemd job listing row {index}"
        if not isinstance(item, list) or len(item) != 6:
            raise Refusal(f"{label} is not one ListJobs tuple")
        job_id = _user_busctl_integer(item[0], 32, False, f"{label} job id")
        if job_id == 0 or job_id in ids:
            raise Refusal(f"{label} has a zero or duplicate job id")
        ids.add(job_id)
        unit = _user_systemd_unit_name(item[1], f"{label} unit")
        job_type = _user_systemd_state(item[2], f"{label} job type")
        _user_systemd_state(item[3], f"{label} job state")
        job_path = _user_busctl_string(item[4], f"{label} job path")
        if job_path != f"/org/freedesktop/systemd1/job/{job_id}":
            raise Refusal(f"{label} has a mismatched job object path")
        unit_path = _user_systemd_object_path(item[5], f"{label} unit object path")
        if not unit.endswith((".service", ".scope")):
            continue
        listed = units.get(unit)
        if listed is None or listed.object_path != unit_path or unit in result:
            raise Refusal(f"{label} does not match the enumerated unit set")
        result[unit] = (job_id, job_type, job_path)
    return result


def _user_systemd_snapshot() -> tuple[Mapping[str, str], ...]:
    budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=30,
        stdout_limit=1024 * 1024,
        stderr_limit=64 * 1024,
        input_limit=(
            _USER_SYSTEMD_LISTING_BYTES_LIMIT * _USER_SYSTEMD_SNAPSHOT_LISTING_READS
        ),
    )
    selected = _user_systemd_units(budget)
    property_names = {
        name
        for name, _signature in (
            *_USER_SYSTEMD_SERVICE_PROPERTIES,
            *_USER_SYSTEMD_UNIT_PROPERTIES,
        )
    }
    for attempt in range(_USER_SYSTEMD_SNAPSHOT_ATTEMPTS):
        selected_by_name = {unit.unit: unit for unit in selected}
        evidence: dict[str, dict[str, str]] = {}
        for unit in selected:
            live = unit.active_state not in {"inactive", "failed"} or unit.job_id != 0
            if unit.unit.endswith(".service"):
                properties = (
                    _USER_SYSTEMD_SERVICE_PROPERTIES
                    if live
                    else _USER_SYSTEMD_SCOPE_PROPERTIES
                )
                interface = "org.freedesktop.systemd1.Service"
            else:
                properties = _USER_SYSTEMD_SCOPE_PROPERTIES
                interface = "org.freedesktop.systemd1.Scope"
            evidence[unit.unit] = _user_systemd_properties(
                unit.object_path, interface, properties, budget
            )

        current: list[_UserSystemdUnit] = []
        for unit in selected:
            values = _user_systemd_properties(
                unit.object_path,
                _USER_SYSTEMD_UNIT_INTERFACE,
                _USER_SYSTEMD_UNIT_PROPERTIES,
                budget,
            )
            if values["Id"] != unit.unit:
                raise Refusal(
                    f"user-systemd object {unit.object_path} changed identity from "
                    f"{unit.unit!r} to {values['Id']!r}"
                )
            load_state = _user_systemd_state(
                values["LoadState"], f"user-systemd unit {unit.unit} load state"
            )
            active_state = _user_systemd_state(
                values["ActiveState"], f"user-systemd unit {unit.unit} active state"
            )
            sub_state = _user_systemd_state(
                values["SubState"], f"user-systemd unit {unit.unit} substate"
            )
            evidence[unit.unit]["RequiresMountsFor"] = values["RequiresMountsFor"]
            current.append(
                dataclasses.replace(
                    unit,
                    load_state=load_state,
                    active_state=active_state,
                    sub_state=sub_state,
                )
            )

        listed_after = _user_systemd_units(budget)
        listed_after_by_name = {unit.unit: unit for unit in listed_after}
        jobs = _user_systemd_jobs(budget, listed_after_by_name)
        current = [
            dataclasses.replace(
                unit,
                job_id=jobs.get(unit.unit, (0, "", "/"))[0],
                job_type=jobs.get(unit.unit, (0, "", "/"))[1],
                job_path=jobs.get(unit.unit, (0, "", "/"))[2],
            )
            for unit in current
        ]
        listed_jobs = {
            unit.unit: (unit.job_id, unit.job_type, unit.job_path)
            for unit in listed_after
            if unit.job_id != 0
        }
        current_by_name = {unit.unit: unit for unit in current}
        listed_with_jobs = tuple(
            dataclasses.replace(
                unit,
                job_id=jobs.get(unit.unit, (0, "", "/"))[0],
                job_type=jobs.get(unit.unit, (0, "", "/"))[1],
                job_path=jobs.get(unit.unit, (0, "", "/"))[2],
            )
            for unit in listed_after
        )
        listed_with_jobs_by_name = {unit.unit: unit for unit in listed_with_jobs}
        stable = (
            listed_jobs == jobs
            and selected_by_name == current_by_name
            and current_by_name == listed_with_jobs_by_name
        )
        if not stable:
            if attempt < _USER_SYSTEMD_SNAPSHOT_ATTEMPTS - 1:
                selected = listed_with_jobs
                continue
            raise Refusal(
                "user-systemd unit population, identity, state, or jobs changed during "
                "three bounded enumeration attempts"
            )

        result: list[dict[str, str]] = []
        for unit in listed_with_jobs:
            values = {name: "" for name in property_names}
            values.update(evidence[unit.unit])
            values.update(
                {
                    "Id": unit.unit,
                    "LoadState": unit.load_state,
                    "ActiveState": unit.active_state,
                    "SubState": unit.sub_state,
                    "PendingJob": "yes" if unit.job_id != 0 else "no",
                }
            )
            result.append(values)
        return tuple(result)
    raise AssertionError("bounded user-systemd retry loop did not return or refuse")


# Characters that separate the words of a unit property string.  Whitespace
# and quotes end shell words; ``=``, ``:`` and ``,`` separate an option or
# variable name from its value and the entries of a search list
# (``--checkout=PATH``, ``PATH=/a:/b``); ``;``, ``&``, ``|``, parentheses,
# redirections, braces and ``$`` delimit shell commands.  Every other
# character, including ``+``, ``.``, ``-``, ``_``, ``@`` and ``~``, is part
# of a path name, so ``slot01+other`` is one path and not ``slot01``.
#
# A path may itself contain any of these characters, so splitting alone
# would lose a path with a space in it.  Each element of a property (one
# argv element, environment assignment or path, which
# ``_user_systemd_properties`` separates with
# ``_UNIT_PROPERTY_ELEMENT_SEPARATOR``), each line of an element, and a
# property string as a whole are therefore also judged whole, as their
# shell words, split by these characters other than whitespace, and from
# just after each ``=``, and each separator a ``/`` or ``~`` follows, to
# the end, so an option or assignment value holding a separator is whole.
# A row path's own spellings are also found as text anywhere in a property
# (``_property_mentions``), which keeps a row path whole even where it
# holds a newline or ends just before a separator, and counts a path that
# goes on from it, even back out through ``..``, since that path needs the
# row to resolve.  Every reading only
# adds candidate paths, so a reading that splits a path apart can refuse a
# row falsely (``slot01:other`` names ``slot01``) but cannot hide one;
# ``:``, ``,`` and ``;`` delimit real paths in search lists, bind
# specifications (``SRC:DST``) and shell commands, so they stay separators.
# The element separator, NUL, is a separator too; no path holds it.
_UNIT_EVIDENCE_SEPARATORS = re.compile(r"[\s\x00\"'`=:,;&|()<>{}$]+")
_UNIT_ARGUMENT_SEPARATORS = re.compile(r"[\x00\"'`=:,;&|()<>{}$]+")
_UNIT_VALUE_STARTS = re.compile(r"=|[\s\x00\"'`:,;&|()<>{}$](?=[/~])")
# Characters that make a shell word worth reading again as shell text: a
# word holding whitespace, a quote, a backslash or a control operator came
# from a quoted command (``bash -c "cd '/x/y z' && make"``).
_UNIT_SHELL_TEXT = re.compile(r"[\s\"'\\;&|()<>]")
# How many times a shell word is read again as shell text.
_UNIT_SHELL_NESTING = 3
# How many characters the shell-word reader reads between checks of the
# judgement's time bound (``_BudgetedText``).  Both of its readings
# together read about 540,000 characters a second on the measurement host
# (2026-10-05), so a check falls about every 8 milliseconds.
_UNIT_SHELL_CHECK_CHARACTERS = 4096
# The work one judgement may spend reading the words of the user-systemd
# units and retained run handles and resolving them as paths
# (``_UnitResolutionBudget``): characters of words, readings and candidate
# paths produced, file lookups (``lstat``, ``stat`` and ``readlink``), and
# seconds.  Every reading of a property string is kept whole, so the
# characters grow with the square of a long property's length; a judgement
# that would exceed a bound refuses instead of reading on.
_UNIT_RESOLUTION_CHARACTER_LIMIT = 32 * 1024 * 1024
_UNIT_RESOLUTION_LOOKUP_LIMIT = 262_144
_UNIT_RESOLUTION_SECONDS = 20.0
# Prefixes systemd and unit files put before a path to change how it is used
# (``-/path`` and ``!/path`` mean the path may be missing).
_UNIT_PATH_PREFIXES = "-!@+"


@dataclasses.dataclass(frozen=True)
class _RowPathIdentity:
    """One validation-row path, as the strings and file it is."""

    path: Path
    spellings: tuple[str, ...]
    file: tuple[int, int] | None


def _row_path_identity(path: Path) -> _RowPathIdentity:
    """Return the lexical and symlink-resolved spellings of a row path and,
    when it exists, its device and inode.

    The path is resolved as written, so a ``..`` after a symlink leaves the
    symlink's target as the kernel does; its lexically normalized spelling
    is resolved too.
    """

    raw = str(path)
    lexical = os.path.normpath(raw)
    try:
        metadata = os.stat(raw)
    except (OSError, ValueError):
        file = None
    else:
        file = (metadata.st_dev, metadata.st_ino)
    return _RowPathIdentity(
        path,
        tuple(dict.fromkeys((lexical, os.path.realpath(raw), os.path.realpath(lexical)))),
        file,
    )


# A stat failure that every path below the failing one shares: the path is
# missing, a non-directory, a symlink loop, or too long for a system call.
_LOOKUP_ENDS_BELOW = frozenset({errno.ENOENT, errno.ENOTDIR, errno.ELOOP, errno.ENAMETOOLONG})


# An ``lstat`` failure that every path below the failing one shares, as for
# ``_LOOKUP_ENDS_BELOW``, or no permission to search a directory above it.
_LSTAT_ENDS_BELOW = _LOOKUP_ENDS_BELOW | {errno.EACCES}
# How many symbolic links one resolution may follow inside each other.  The
# kernel follows 40; a deeper nesting is refused rather than resolved.
_REALPATH_LINK_NESTING = 40


@dataclasses.dataclass
class _UnitResolutionBudget:
    """What is left of one judgement's unit-word and path-resolution work.

    ``characters`` and ``lookups`` count down as words are read and paths
    looked up; ``deadline`` is a ``time.monotonic`` time, and ``expired``
    the refusal once it passes.  Spending past any of them refuses, so a
    long or crafted property string costs a bounded amount of work and
    answers as unverifiable.
    """

    characters: int
    lookups: int
    deadline: float
    expired: str

    @classmethod
    def start(
        cls, *, deadline: float | None = None, expired: str | None = None
    ) -> _UnitResolutionBudget:
        """A full budget, ending ``_UNIT_RESOLUTION_SECONDS`` from now or at
        a caller's own ``deadline`` with its own ``expired`` refusal."""

        return cls(
            _UNIT_RESOLUTION_CHARACTER_LIMIT,
            _UNIT_RESOLUTION_LOOKUP_LIMIT,
            time.monotonic() + _UNIT_RESOLUTION_SECONDS if deadline is None else deadline,
            (
                "reading the words of the user-systemd units and retained run handles "
                f"exceeds the {_UNIT_RESOLUTION_SECONDS:g}-second bound of one judgement"
            )
            if expired is None
            else expired,
        )

    def spend(self, *, characters: int = 0, lookups: int = 0) -> None:
        self.characters -= characters
        self.lookups -= lookups
        if self.characters < 0:
            raise Refusal(
                "the words of the user-systemd units and retained run handles exceed "
                f"the {_UNIT_RESOLUTION_CHARACTER_LIMIT:,}-character bound of one judgement"
            )
        if self.lookups < 0:
            raise Refusal(
                "resolving the paths of the user-systemd units and retained run handles "
                f"exceeds the {_UNIT_RESOLUTION_LOOKUP_LIMIT:,}-lookup bound of one judgement"
            )
        if time.monotonic() >= self.deadline:
            raise Refusal(self.expired)


class _SymlinkLoop(Exception):
    """A symlink met again while it is being resolved; ``path`` is the
    unresolved text ``os.path.realpath`` returns for it."""

    def __init__(self, path: str) -> None:
        super().__init__(path)
        self.path = path


@dataclasses.dataclass
class _Traversal:
    """What one path resolution passes through on its way.

    ``paths`` holds the deepest spelling looked up before each ``..`` steps
    back out of it and the path of each symlink followed; every other part
    looked up is a prefix of one of those or of the resolution itself, so
    a row that any looked-up part lies in contains one of them.  ``files``
    holds the device and inode of every part looked up that is not a
    symlink.  The kernel needs each of them to exist for the path to
    resolve, so a unit that names a path through a row depends on the row.
    """

    paths: dict[str, None] = dataclasses.field(default_factory=dict)
    files: set[tuple[int, int]] = dataclasses.field(default_factory=set)


class _UnitPathResolver:
    """Resolve the words of user-systemd units to path identities.

    One resolver serves one judgement: it memoizes each property string's
    candidate paths, the resolution of each path, and the identity of each
    file it stats, so several rows can be compared with one unit
    enumeration without repeating the parsing or the file-system reads.  It
    must not outlive the judgement, because the files change.  Its work is
    bounded by ``budget`` (``_UnitResolutionBudget``), which a caller may
    share with a wider bound such as the handle census deadline.

    A path is resolved exactly as ``os.path.realpath`` resolves it
    (``_realpath``), without looking up a component below one whose lookup
    failed in a way every path below shares, and its ancestors are statted
    from ``/`` down with the same stop, so only ancestors that exist are
    kept.  What the resolution looks up on the way is kept with it
    (``_Traversal``).
    """

    def __init__(self, budget: _UnitResolutionBudget | None = None) -> None:
        self._budget = _UnitResolutionBudget.start() if budget is None else budget
        self._candidates: dict[tuple[str, str], tuple[str, ...]] = {}
        self._words: dict[str, tuple[tuple[str, ...], frozenset[tuple[int, int]]]] = {}
        self._files: dict[str, tuple[tuple[int, int] | None, bool]] = {}
        # What ``lstat`` found at each path: "link", "directory" (or a
        # failure that a path below need not share), or "end" (a
        # non-directory, or a failure every path below shares), and the
        # device and inode of a file that is not a symlink.
        self._kinds: dict[str, tuple[str, tuple[int, int] | None]] = {}
        self._targets: dict[str, str] = {}

    def row(self, path: Path) -> _RowPathIdentity:
        """``_row_path_identity(path)``, once the time bound is checked."""

        self._budget.spend()
        return _row_path_identity(path)

    def check_bound(self) -> None:
        """Refuse once the time bound has passed, so that an answer read
        from work that outran it, such as a row identity read or a property
        scan that crossed it, is not given."""

        self._budget.spend()

    def _kind(self, path: str) -> tuple[str, tuple[int, int] | None]:
        try:
            return self._kinds[path]
        except KeyError:
            pass
        # The memo keeps the path, so its characters are charged too.
        self._budget.spend(characters=len(path), lookups=1)
        identity: tuple[int, int] | None = None
        try:
            metadata = os.lstat(path)
        except OSError as exc:
            kind = "end" if exc.errno in _LSTAT_ENDS_BELOW else "directory"
        else:
            if stat.S_ISLNK(metadata.st_mode):
                kind = "link"
            else:
                kind = "directory" if stat.S_ISDIR(metadata.st_mode) else "end"
                identity = (metadata.st_dev, metadata.st_ino)
        self._kinds[path] = (kind, identity)
        return kind, identity

    def _target(self, path: str) -> str:
        try:
            return self._targets[path]
        except KeyError:
            pass
        self._budget.spend(characters=len(path), lookups=1)
        try:
            target = os.readlink(path)
        except OSError as exc:
            raise Refusal(
                "a path that a user-systemd unit or retained run handle names "
                f"cannot be resolved: {exc}"
            ) from exc
        self._budget.spend(characters=len(target))
        self._targets[path] = target
        return target

    def _realpath(self, path: str, traversal: _Traversal | None = None) -> str:
        """``os.path.realpath(path)`` of absolute ``path``.

        This is the walk of Python 3.12's ``posixpath.realpath``, which
        looks up each component as it is appended, follows symlinks, steps
        back over ``..`` by text and gives up on a symlink loop.  It keeps
        the path as components and walks the text by index, so neither a
        long path nor many ``..`` steps make it quadratic, and it does not
        look up a component below one that is missing, not a directory, a
        symlink loop, too long, or unsearchable: every such lookup fails,
        and ``realpath`` reads a failed lookup as a plain name.  The
        lookups and link targets are memoized for the judgement.  A link
        target that cannot be read, a path that cannot be looked up at all,
        or more than ``_REALPATH_LINK_NESTING`` nested links refuses.  So
        does a path holding a NUL or a character the file-system encoding
        cannot encode, wherever it stands, as ``realpath`` raises for one
        when it looks up the component holding it.

        ``traversal``, when given, gathers what the walk passes through on
        the way (``_Traversal``).
        """

        if not path.startswith("/"):
            raise Refusal(f"cannot resolve relative path {path!r}")
        try:
            if "\0" in path:
                raise ValueError("embedded null byte")
            os.fsencode(path)
        except ValueError as exc:
            raise Refusal(
                "a path that a user-systemd unit or retained run handle names "
                f"cannot be resolved: {exc}"
            ) from exc
        try:
            components, _prefixes, _end = self._join_real(
                [], [], None, path, {}, 0, traversal
            )
        except _SymlinkLoop as loop:
            return os.path.normpath(loop.path)
        except ValueError as exc:
            raise Refusal(
                "a path that a user-systemd unit or retained run handle names "
                f"cannot be resolved: {exc}"
            ) from exc
        return "/" + "/".join(components)

    def _join_real(
        self,
        components: list[str],
        prefixes: list[str],
        end: int | None,
        text: str,
        seen: dict[str, tuple[tuple[str, ...], tuple[str, ...], int | None] | None],
        nesting: int,
        traversal: _Traversal | None = None,
    ) -> tuple[list[str], list[str], int | None]:
        """Append ``text`` to the resolved path ``components``.

        ``prefixes`` holds the spelling of each leading part of
        ``components`` down to ``end``, the length at which a lookup ended
        every lookup below it (None when none has).  ``seen`` maps each
        symlink met in this resolution to what it resolved to, or to None
        while it is being resolved, as ``realpath``'s own memo does; a
        symlink met again was walked, and its walk recorded in
        ``traversal``, earlier in the same resolution.
        """

        if nesting > _REALPATH_LINK_NESTING:
            raise Refusal(
                "a path that a user-systemd unit or retained run handle names "
                f"nests more than {_REALPATH_LINK_NESTING} symbolic links"
            )
        position = 0
        if text.startswith("/"):
            components, prefixes, end = [], [], None
            position = 1
        length = len(text)
        while position < length:
            stop = text.find("/", position)
            if stop < 0:
                stop = length
            name = text[position:stop]
            position = stop + 1
            if not name or name == ".":
                continue
            if name == "..":
                if components:
                    if traversal is not None and prefixes:
                        # The deepest part looked up is left here, so it
                        # is kept; every part above it is a prefix of it.
                        self._record(traversal, prefixes[-1])
                    components.pop()
                    if len(prefixes) > len(components):
                        prefixes.pop()
                    if end is not None and len(components) < end:
                        end = None
                continue
            if end is not None:
                components.append(name)
                continue
            # A memoized lookup is free, so the time bound is checked here.
            self._budget.spend()
            joined = (prefixes[-1] if prefixes else "") + "/" + name
            kind, identity = self._kind(joined)
            if traversal is not None and identity is not None:
                traversal.files.add(identity)
            if kind != "link":
                components.append(name)
                prefixes.append(joined)
                if kind == "end":
                    end = len(components)
                continue
            if traversal is not None:
                # The symlink's own path is left for its target.
                self._record(traversal, joined)
            if joined in seen:
                known = seen[joined]
                if known is None:
                    raise _SymlinkLoop(os.path.join(joined, text[position:]))
                self._budget.spend(characters=len(known[0]) + len(known[1]))
                components, prefixes, end = list(known[0]), list(known[1]), known[2]
                continue
            seen[joined] = None
            try:
                components, prefixes, end = self._join_real(
                    components,
                    prefixes,
                    end,
                    self._target(joined),
                    seen,
                    nesting + 1,
                    traversal,
                )
            except _SymlinkLoop as loop:
                raise _SymlinkLoop(os.path.join(loop.path, text[position:])) from None
            # The copies are charged as one character per part.
            self._budget.spend(characters=len(components) + len(prefixes))
            seen[joined] = (tuple(components), tuple(prefixes), end)
        return components, prefixes, end

    def _record(self, traversal: _Traversal, path: str) -> None:
        """Keep ``path`` among the paths of ``traversal``, charging its
        characters the first time, since the answer keeps it."""

        if path not in traversal.paths:
            self._budget.spend(characters=len(path))
            traversal.paths[path] = None

    def _file(self, path: str) -> tuple[tuple[int, int] | None, bool]:
        """The identity of the file at ``path``, or None, and whether a path
        below it can still be looked up."""

        try:
            return self._files[path]
        except KeyError:
            pass
        self._budget.spend(characters=len(path), lookups=1)
        answer: tuple[tuple[int, int] | None, bool]
        try:
            metadata = os.stat(path)
        except ValueError:
            answer = (None, False)
        except OSError as exc:
            answer = (None, exc.errno not in _LOOKUP_ENDS_BELOW)
        else:
            answer = ((metadata.st_dev, metadata.st_ino), True)
        self._files[path] = answer
        return answer

    def _ancestor_files(self, path: str) -> set[tuple[int, int]]:
        """The files of absolute ``path`` and of each of its ancestors that
        exist, statted from ``/`` down."""

        files: set[tuple[int, int]] = set()
        end = 0
        while True:
            identity, below = self._file(path[:end] or "/")
            if identity is not None:
                files.add(identity)
            if not below or end >= len(path):
                return files
            end = path.find("/", end + 1)
            if end < 0:
                end = len(path)

    def _resolve(self, joined: str) -> tuple[tuple[str, ...], frozenset[tuple[int, int]]]:
        """Return a path's spellings and the files of it and its ancestors.

        The path is resolved as written, as the kernel resolves it: a
        ``..`` after a symlink leaves the symlink's target, which lexical
        normalization would remove along with the symlink.  The lexically
        normalized spelling, and its resolution, are kept as well, so a
        word names a row under either reading.

        The paths and files the resolutions pass through on the way are
        kept too (``_Traversal``): the kernel needs every part it looks up
        to exist, so ``<row>/../slot02`` depends on the row even though it
        ends outside it.
        """

        try:
            return self._words[joined]
        except KeyError:
            pass
        # The text is walked for its lexical spelling, its resolution as
        # written and the resolution of its lexical spelling.
        self._budget.spend(characters=3 * len(joined))
        lexical = os.path.normpath(joined)
        traversal = _Traversal()
        resolved = tuple(
            dict.fromkeys(
                self._realpath(spelling, traversal)
                for spelling in dict.fromkeys((joined, lexical))
            )
        )
        # A symlink's target can make a resolution longer than its text.
        self._budget.spend(characters=sum(len(spelling) for spelling in resolved))
        files: set[tuple[int, int]] = set(traversal.files)
        for current in resolved:
            files.update(self._ancestor_files(current))
        answer = (
            tuple(dict.fromkeys((lexical, *resolved, *traversal.paths))),
            frozenset(files),
        )
        self._words[joined] = answer
        return answer

    def names(self, unit: Mapping[str, str], row: _RowPathIdentity) -> bool:
        """Whether any word of ``unit`` is ``row`` or a path inside it.

        Relative words are resolved against the unit's working directory,
        which for a user unit without one is the user's home directory.  A
        word names the row when its lexical or symlink-resolved spelling,
        or a path its resolution passes through, is a row spelling or lies
        under one by whole path components, or when it, an existing
        ancestor or a file its resolution passes through is the row's own
        file (a bind mount or hard-linked directory reaches it under
        another name).
        """

        base = _unit_working_directory(unit)
        for value in unit.values():
            # A property read for an earlier row costs nothing again, so
            # the time bound is checked for each.
            self._budget.spend()
            if any(_property_mentions(value, spelling) for spelling in row.spellings):
                return True
            for joined in self._value_paths(base, value):
                if self.path_names(joined, row):
                    return True
        return False

    def _value_paths(self, base: str, value: str) -> tuple[str, ...]:
        """The absolute candidate paths of one property string, read once."""

        key = (base, value)
        try:
            return self._candidates[key]
        except KeyError:
            pass
        paths: list[str] = []
        for word in _unit_property_words(value, self._budget):
            for candidate in dict.fromkeys((word, word.lstrip(_UNIT_PATH_PREFIXES))):
                if not candidate:
                    continue
                if candidate == "~" or candidate.startswith("~/"):
                    candidate = os.path.expanduser(candidate)
                self._budget.spend(characters=len(base) + len(candidate))
                paths.append(
                    candidate if candidate.startswith("/") else os.path.join(base, candidate)
                )
        answer = tuple(dict.fromkeys(paths))
        self._candidates[key] = answer
        return answer

    def path_names(self, joined: str, row: _RowPathIdentity) -> bool:
        """Whether absolute path ``joined`` is ``row`` or a path inside it.

        Its lexical or symlink-resolved spelling, or a path its resolution
        passes through, is a row spelling or lies under one by whole path
        components, or it, an existing ancestor or a file its resolution
        passes through is the row's own file.
        """

        self._budget.spend()
        spellings, files = self._resolve(joined)
        if row.file is not None and row.file in files:
            return True
        return any(
            _spelling_is_within(spelling, root)
            for spelling in spellings
            for root in row.spellings
        )


class _BudgetedText:
    """Text that ``shlex`` reads, checking a judgement's time bound as it goes.

    ``shlex`` reads its input one character at a time, and a single word
    can be as long as the whole text, so the bound is checked every
    ``_UNIT_SHELL_CHECK_CHARACTERS`` characters read rather than between
    words.
    """

    def __init__(self, text: str, budget: _UnitResolutionBudget) -> None:
        self._text = text
        self._position = 0
        self._budget = budget
        self._unchecked = 0

    def _advance(self, end: int) -> str:
        start = self._position
        self._position = end
        self._unchecked += end - start
        if self._unchecked >= _UNIT_SHELL_CHECK_CHARACTERS:
            self._unchecked = 0
            self._budget.spend()
        return self._text[start:end]

    def read(self, size: int = -1) -> str:
        end = len(self._text) if size < 0 else min(len(self._text), self._position + size)
        return self._advance(end)

    def readline(self) -> str:
        end = self._text.find("\n", self._position)
        return self._advance(len(self._text) if end < 0 else end + 1)


def _shell_words(text: str, budget: _UnitResolutionBudget) -> tuple[str, ...]:
    """The shell words of ``text``, read plainly and with control operators.

    Plain reading joins an operator written against a word to it
    (``'/x/y z';`` is the word ``/x/y z;``); the second reading makes
    ``;``, ``&&``, ``|`` and the other control operators words of their
    own.  Text that does not parse, such as an unclosed quote, keeps the
    words read before the error.  ``budget``'s time bound is checked as
    the text is read (``_BudgetedText``).
    """

    words: list[str] = []
    for operators in (False, True):
        lexer = shlex.shlex(
            _BudgetedText(text, budget),  # type: ignore[arg-type]
            posix=True,
            punctuation_chars=operators,
        )
        lexer.whitespace_split = True
        lexer.commenters = ""
        try:
            for word in lexer:
                words.append(word)
        except ValueError:
            pass
    return tuple(dict.fromkeys(words))


def _unit_property_words(value: str, budget: _UnitResolutionBudget) -> tuple[str, ...]:
    """Every candidate path in one unit property string.

    The elements are the NUL-separated strings of an array property (see
    ``_UNIT_PROPERTY_ELEMENT_SEPARATOR``), each line of one, and a string
    without a NUL as a whole.  An element is judged whole, as each of its
    shell words, read again as shell text up to ``_UNIT_SHELL_NESTING``
    times when a word holds shell text, as the pieces of each of those
    split by every separator and by every separator except whitespace,
    and as the rest of each from just after every ``=``, and every
    separator that ``/`` or ``~`` follows, so ``--checkout=<path>`` and
    ``NAME=<path>`` keep a path that holds a separator.  Each rest runs to
    the end of the element, however long; ``budget`` is charged for every
    character read and produced before the work is done.
    """

    pieces = value.split(_UNIT_PROPERTY_ELEMENT_SEPARATOR)
    elements = dict.fromkeys(
        (*pieces, *(line for piece in pieces if "\n" in piece for line in piece.split("\n")))
    )
    budget.spend(characters=2 * len(value))
    words: list[str] = []
    for element in elements:
        readings = [element]
        level: tuple[str, ...] = (element,)
        for _ in range(_UNIT_SHELL_NESTING):
            # Each text is read by two lexers, and each yields words no
            # longer than the text.
            budget.spend(characters=4 * sum(len(text) for text in level))
            level = tuple(
                dict.fromkeys(
                    word
                    for text in level
                    for word in _shell_words(text, budget)
                    if word != text
                )
            )
            readings.extend(level)
            level = tuple(word for word in level if _UNIT_SHELL_TEXT.search(word))
            if not level:
                break
        for reading in dict.fromkeys(readings):
            # The reading and its two splits.
            budget.spend(characters=3 * len(reading))
            words.append(reading)
            words.extend(_UNIT_EVIDENCE_SEPARATORS.split(reading))
            words.extend(_UNIT_ARGUMENT_SEPARATORS.split(reading))
            for match in _UNIT_VALUE_STARTS.finditer(reading):
                budget.spend(characters=len(reading) - match.end())
                words.append(reading[match.end() :])
    return tuple(dict.fromkeys(words))


def _property_mentions(value: str, spelling: str) -> bool:
    """Whether a unit property string holds a row path spelling as a path.

    The spelling must begin the string or follow a separator (through any
    of the prefixes ``_UNIT_PATH_PREFIXES``), and end the string or precede
    ``/`` or a separator.  Found as text, a row path holding a separator,
    a newline or a quote is whole wherever it stands, as an option value,
    an assignment, a search-list entry or a quoted shell word.  A path that
    goes on from it, even one that leaves it again through ``..``
    (``<row>/../slot02``), names the row: the kernel looks the row up on
    the way, so the path stops resolving once the row is gone.
    """

    start = value.find(spelling)
    while start >= 0:
        end = start + len(spelling)
        lead = start
        while lead and value[lead - 1] in _UNIT_PATH_PREFIXES:
            lead -= 1
        opens = (
            lead == 0 or _UNIT_EVIDENCE_SEPARATORS.fullmatch(value[lead - 1]) is not None
        )
        closes = (
            end == len(value)
            or value[end] == "/"
            or _UNIT_EVIDENCE_SEPARATORS.fullmatch(value[end]) is not None
        )
        if opens and closes:
            return True
        start = value.find(spelling, start + 1)
    return False


def _spelling_is_within(path: str, root: str) -> bool:
    """Whether normalized ``path`` is ``root`` or under it by components."""

    return path == root or path.startswith(root.rstrip("/") + "/")


def _unit_working_directory(unit: Mapping[str, str]) -> str:
    """The directory a unit's relative paths are resolved against.

    The property is the manager's own string, read over D-Bus, so
    whitespace in it is part of the directory's name and is kept.
    """

    home = os.path.expanduser("~")
    raw = unit.get("WorkingDirectory", "").lstrip(_UNIT_PATH_PREFIXES)
    if raw in {"", "~"}:
        return home
    if raw.startswith("~/"):
        return os.path.join(home, raw[2:])
    return raw if raw.startswith("/") else os.path.join(home, raw)


def _assert_retained_handle_processes_dead(
    bindings: Mapping[str, tuple[_RetainedValidationHandle, ...]],
    running: AbstractSet[tuple[str, int, int]] = frozenset(),
    unreadable: Mapping[tuple[str, int, int], str] | None = None,
) -> None:
    """Refuse when a handle's recorded process generation runs, or ran
    just before the host evidence.

    The direct check reads each current-boot generation now.  It alone does
    not cover a process that hands its run to a unit: a process that queues
    its unit after the second user-systemd enumeration and then exits reads
    dead here while no enumeration shows the unit.  ``running`` holds the
    generations that ``_recorded_generations_before`` read running just
    before the host evidence, and each is a run that may still use the row,
    as is one that runs now.  ``unreadable`` holds the generations that
    could not be read then, which refuse as unverifiable: reading one dead
    now does not show that it was dead then.  A generation read running
    refuses first, as a run, for every handle of the rows, and is named
    live when it still runs.
    """

    for slot, handles in bindings.items():
        for handle in handles:
            if (handle.boot_id, handle.pid, handle.start_ticks) not in running:
                continue
            try:
                live = (
                    _process_start_ticks(Path("/proc") / str(handle.pid))
                    == handle.start_ticks
                )
            except Refusal:
                live = False
            if live:
                raise _ValidationRunMayUseRow(
                    f"retained validation handle {handle.path} has live exact process "
                    f"generation {handle.pid} for row {slot}"
                )
            raise _ValidationRunMayUseRow(
                f"retained validation handle {handle.path} records process "
                f"generation {handle.pid}, which ran just before the host evidence "
                f"was read, for row {slot}"
            )
    current_boot = _boot_id(Path("/proc"))
    for slot, handles in bindings.items():
        for handle in handles:
            if handle.pid is None:
                continue
            assert handle.start_ticks is not None and handle.boot_id is not None
            refusal = (unreadable or {}).get(
                (handle.boot_id, handle.pid, handle.start_ticks)
            )
            if refusal is not None:
                raise Refusal(refusal)
            if handle.boot_id != current_boot:
                continue
            if _process_start_ticks(Path("/proc") / str(handle.pid)) == handle.start_ticks:
                raise _ValidationRunMayUseRow(
                    f"retained validation handle {handle.path} has live exact process "
                    f"generation {handle.pid} for row {slot}"
                )


def _assert_absent_validate_systemd_unrelated(
    rows: Sequence[tuple[ActiveRecord, tuple[Path, ...]]],
    bindings: Mapping[str, tuple[_RetainedValidationHandle, ...]],
    processes: Sequence[_AbsentProcessObservation],
    *,
    snapshot: Sequence[Mapping[str, str]] | None = None,
    resolver: _UnitPathResolver | None = None,
    members: Mapping[str, int] | None = None,
) -> None:
    """Refuse when a retained run unit or any active user unit may use a row.

    ``snapshot`` lets one caller judge several rows against a single
    user-systemd enumeration; when absent, this reads a fresh one.  It may
    hold one unit more than once, from successive enumerations, and every
    entry is judged.  ``resolver`` lets the same caller share the path
    resolution of that enumeration's words across rows.  ``members`` counts
    the processes found in each retained unit's control group by a later
    read (``_retained_unit_cgroup_members``).
    """

    if snapshot is None:
        snapshot = _user_systemd_snapshot()
    by_name: dict[str, list[Mapping[str, str]]] = {}
    for unit in snapshot:
        by_name.setdefault(unit["Id"], []).append(unit)
    for slot, handles in bindings.items():
        for handle in handles:
            if any(
                handle.unit in Path(process.cgroup_path).parts for process in processes
            ):
                raise _ValidationRunMayUseRow(
                    f"retained validation unit {handle.unit} still has a live cgroup "
                    f"process for row {slot}"
                )
            count = 0 if members is None else members.get(handle.unit, 0)
            if count:
                raise _ValidationRunMayUseRow(
                    f"retained validation unit {handle.unit} control group now holds "
                    f"{count} process(es) for row {slot}"
                )
            for unit in by_name.get(handle.unit, ()):
                active = unit["ActiveState"] not in {"inactive", "failed"}
                queued = unit["PendingJob"] == "yes"
                if active or queued:
                    raise _ValidationRunMayUseRow(
                        f"retained validation unit {handle.unit} may still use row {slot}"
                    )
                control_group = unit["ControlGroup"].rstrip("/") or "/"
                if control_group != "/" and any(
                    _cgroup_matches(control_group, process.cgroup_path)
                    for process in processes
                ):
                    raise _ValidationRunMayUseRow(
                        f"retained validation unit {handle.unit} still has a live "
                        f"process for row {slot}"
                    )
    if resolver is None:
        resolver = _UnitPathResolver()
    targets = tuple((record, resolver.row(path)) for record, paths in rows for path in paths)
    for unit in snapshot:
        active = unit["ActiveState"] not in {"inactive", "failed"}
        queued = unit["PendingJob"] == "yes"
        if not active and not queued:
            continue
        for record, target in targets:
            if resolver.names(unit, target):
                raise _ValidationRunMayUseRow(
                    f"user-systemd unit {unit['Id']} names validation row "
                    f"{record.slot} path {target.path}"
                )
    # The last row identity read or property answer may itself have run past
    # the bound; a unit naming no row is an answer only within it.
    resolver.check_bound()


def _assert_absent_validate_owners_dead(records: Sequence[ActiveRecord]) -> None:
    current_host = _host_id()
    current_boot = _boot_id(Path("/proc"))
    for record in records:
        owner = record.owner
        if owner is None:
            raise Refusal(f"validation row {record.slot} has no exact owner process generation")
        if owner.host_id != current_host:
            raise Refusal(f"recorded owner host is indeterminate for validation row {record.slot}")
        if owner.boot_id != current_boot:
            continue
        ticks = _process_start_ticks(Path("/proc") / str(owner.pid))
        if ticks is None or ticks != owner.start_ticks:
            continue
        raise Refusal(
            f"recorded owner PID {owner.pid} generation is still live for validation "
            f"row {record.slot}"
        )


def _assert_absent_validate_rows_safe(config: Config, records: Sequence[ActiveRecord]) -> None:
    if not records:
        return
    _assert_absent_validate_rows_not_held(config, records)
    rows = _assert_absent_validate_rows_storage(config, records)
    _assert_absent_validate_owners_dead(records)
    bindings = _retained_handles_for_absent_rows(config, rows)
    _assert_retained_handle_processes_dead(bindings)
    evidence = _run_evidence(
        config,
        rows,
        lambda: _host_evidence_around(
            lambda: _assert_absent_validate_processes_unrelated(rows)
        ),
        first=bindings,
    )
    _judge_run_evidence(rows, evidence)


def _absent_validate_archive_entry(
    record: ActiveRecord,
    item: AbsentValidateRow,
    finished_at: str,
) -> dict[str, object]:
    value: dict[str, object] = {
        "archive_id": f"{record.machine}:{record.slot}:{record.generation}:{finished_at}",
        "slot": record.slot,
        "agent": record.agent,
        "task": record.task,
        "purpose": record.purpose,
        "slot_type": record.slot_type,
        "machine": record.machine,
        "generation": record.generation,
        "created_at": record.created_at,
        "finished_at": finished_at,
        "mode": "remove",
        "actor": "coordinator",
        # `physical_storage` is the archive-time disposition, not a claim that
        # this command performed the removal.  Keeping the established schema-2
        # shape lets older fail-closed readers consume the repaired archive.
        "physical_storage": "removed",
        "validation": [
            "registry reconciliation confirmed physical storage absent",
            f"source ACTIVE record SHA-256: {item.record_sha256}",
        ],
        "limitations": ["validation outcome unknown"],
        "continuation": "no storage remains; consult retained validation records by run identity",
        "salvage": [],
        "checkouts": [_checkout_to_obj(checkout) for checkout in record.checkouts],
    }
    if record.layout is not None:
        value["layout"] = record.layout
    if record.import_source is not None:
        value["import_source"] = _import_source_to_obj(record.import_source)
    return value


def _absent_validate_recovery_evidence(
    item: AbsentValidateRow, archived: Mapping[str, object]
) -> dict[str, object]:
    """Build the typed event evidence shared by archive and ACTIVE removal."""

    return {
        "archive_id": _as_str(
            archived.get("archive_id"), "absent-validation-row archive_id"
        ),
        "source_record_sha256": item.record_sha256,
        "validation_outcome": "unknown",
    }


def _archive_matches_absent_validate_row(
    archive: ArchiveState,
    archived: Mapping[str, object],
    item: AbsentValidateRow,
) -> bool:
    return bool(
        archive.machine == item.machine
        and
        archived.get("slot") == item.slot
        and archived.get("machine") == item.machine
        and archived.get("generation") == item.generation
        and archived.get("slot_type") == "validate"
        and archived.get("physical_storage") == "removed"
        and (item.slot, item.generation, item.record_sha256)
        in archive.absent_validate_recoveries
    )


def _append_absent_validate_archives(
    config: Config,
    state: ArchiveState,
    additions_to_write: Sequence[tuple[AbsentValidateRow, Mapping[str, object]]],
    writer: _EventWriter,
) -> ArchiveState:
    if not additions_to_write:
        return state
    records = [*state.records]
    revision = state.revision
    additions: list[tuple[AbsentValidateRow, dict[str, object], int, int]] = []
    for item, raw_entry in additions_to_write:
        entry = dict(raw_entry)
        slot = _as_str(entry.get("slot"), "absent-validation-row archive slot")
        if slot != item.slot:
            raise StateError("absent-validation-row archive entry has mismatched input")
        previous_revision = revision
        revision += 1
        records.append(entry)
        additions.append((item, entry, previous_revision, revision))
    updated = _archive_from_obj(
        config,
        {
            "schema": SCHEMA,
            "machine": state.machine,
            "revision": revision,
            "records": records,
        },
        state.machine,
        "absent-validation-row derived archive",
    )
    recovery_identities = set(state.absent_validate_recoveries)
    recovery_identities.update(
        (item.slot, item.generation, item.record_sha256)
        for item, _entry, _previous_revision, _next_revision in additions
    )
    updated = dataclasses.replace(
        updated,
        absent_validate_recoveries=frozenset(recovery_identities),
        absent_agent_recoveries=state.absent_agent_recoveries,
    )
    for item, entry, previous_revision, next_revision in additions:
        writer.append(
            "archive-state-recorded",
            {
                "action": "absent-validation-row-recovered",
                "slot": item.slot,
                "previous_revision": previous_revision,
                "revision": next_revision,
                "record": entry,
                "evidence": _absent_validate_recovery_evidence(item, entry),
            },
        )
        _interrupt_for_test("after-absent-validate-archive")
    return updated


def _validate_absent_validate_row(record: ActiveRecord, item: AbsentValidateRow) -> None:
    if record.slot_type != "validate":
        raise Refusal(f"slot {item.slot} is not a validation row")
    if record.machine != item.machine or record.generation != item.generation:
        raise Refusal(f"validation row {item.machine}/{item.slot} generation changed")
    digest = _record_sha256(record)
    if digest != item.record_sha256:
        raise Refusal(
            f"validation row {item.machine}/{item.slot} changed: expected "
            f"{item.record_sha256}, found {digest}"
        )


def _assert_absent_validate_row_is_local(record: ActiveRecord) -> None:
    recorded = {record.coordinator_lease.host_id}
    if record.owner is not None:
        recorded.add(record.owner.host_id)
    if "" in recorded or len(recorded) != 1:
        raise Refusal(
            f"validation row {record.machine}/{record.slot} has missing or mixed stable "
            "host identities"
        )
    expected = next(iter(recorded))
    current = _host_id()
    if expected != current:
        raise Refusal(
            f"validation row {record.machine}/{record.slot} belongs to stable host "
            f"{expected}, not current host {current}"
        )


def _absent_validate_rows_state(
    config: Config,
    items: Sequence[AbsentValidateRow],
    *,
    allow_exact_overlap: bool,
) -> tuple[list[ActiveState], list[ArchiveState]]:
    states = _load_all_active(config)
    archives = _load_all_archives(config)
    allowed = {(item.machine, item.slot): item for item in items}
    active = {record.slot: (state.machine, record) for state in states for record in state.slots}
    for archive in archives:
        for archived in archive.records:
            slot = _as_str(archived.get("slot"), "archive slot")
            current = active.get(slot)
            if current is None:
                continue
            active_machine, active_record = current
            item = allowed.get((active_machine, slot))
            if not (
                allow_exact_overlap
                and item is not None
                and archive.machine == active_machine
                and _archive_matches_absent_validate_row(archive, archived, item)
            ):
                raise StateError(
                    f"slot {slot!r} is active on {active_machine} and archived on "
                    f"{archive.machine}"
                )
            _validate_absent_validate_row(active_record, item)
    return states, archives


def _plan_absent_validate_rows(
    config: Config,
    items: Sequence[AbsentValidateRow],
) -> tuple[tuple[AbsentValidateRow, ActiveRecord, dict[str, object]], ...]:
    if any(item.machine != config.machine for item in items):
        raise Refusal(
            f"every input row must name selected machine {config.machine}; use --machine "
            "for another shard"
        )
    states, archives = _absent_validate_rows_state(config, items, allow_exact_overlap=False)
    active_by_identity = {
        (state.machine, record.slot): record for state in states for record in state.slots
    }
    archived_by_identity = {
        (archive.machine, _as_str(record.get("slot"), "archive slot")): (
            archive,
            record,
        )
        for archive in archives
        for record in archive.records
    }
    planned: list[tuple[AbsentValidateRow, ActiveRecord, dict[str, object]]] = []
    active_records: list[ActiveRecord] = []
    for item in items:
        identity = (item.machine, item.slot)
        record = active_by_identity.get(identity)
        archived_pair = archived_by_identity.get(identity)
        if record is None:
            if archived_pair is not None and _archive_matches_absent_validate_row(
                archived_pair[0], archived_pair[1], item
            ):
                continue
            raise Refusal(
                f"validation row {item.machine}/{item.slot} is neither active nor an "
                "exact prior absent-row recovery"
            )
        _validate_absent_validate_row(record, item)
        _assert_absent_validate_row_is_local(record)
        if archived_pair is not None:
            raise StateError(f"validation row {item.slot} is both active and archived")
        active_records.append(record)
        finished_at = _utc_now()
        planned.append((item, record, _absent_validate_archive_entry(record, item, finished_at)))
    _assert_absent_validate_rows_safe(config, active_records)
    return tuple(planned)


def _already_recovered_absent_validate_keys(
    archives: Sequence[ArchiveState], items: Sequence[AbsentValidateRow]
) -> set[tuple[str, str, int]]:
    """Return requested identities backed by an exact typed recovery event."""

    requested = {(item.machine, item.slot): item for item in items}
    recovered: set[tuple[str, str, int]] = set()
    for archive in archives:
        for archived in archive.records:
            slot = _as_str(archived.get("slot"), "archive slot")
            item = requested.get((archive.machine, slot))
            if item is not None and _archive_matches_absent_validate_row(
                archive, archived, item
            ):
                recovered.add((item.machine, item.slot, item.generation))
    return recovered


def _absent_validate_batch_journal(
    config: Config,
    input_sha256: str,
    planned: Sequence[tuple[AbsentValidateRow, ActiveRecord, Mapping[str, object]]],
    coordinator: ProcessIdentity,
) -> dict[str, object]:
    return {
        "schema": SCHEMA,
        "kind": "recover-absent-validate-rows",
        "machine": config.machine,
        "host_id": _host_id(),
        "slot": "absent-validate-rows",
        "input_sha256": input_sha256,
        "cursor": 0,
        "actor": _identity_to_obj(coordinator),
        "items": [
            {
                "input": dataclasses.asdict(item),
                "record": _record_to_obj(record),
                "archive_entry": dict(archive_entry),
            }
            for item, record, archive_entry in planned
        ],
    }


def _absent_validate_batch_items(
    config: Config, raw: Mapping[str, object]
) -> tuple[int, tuple[tuple[AbsentValidateRow, ActiveRecord, dict[str, object]], ...]]:
    _exact_keys(
        raw,
        _ABSENT_VALIDATE_JOURNAL_REQUIRED,
        set(),
        "absent-validation-row journal",
    )
    if (
        _as_int(raw["schema"], "absent-validation-row journal.schema") != SCHEMA
        or raw["kind"] != "recover-absent-validate-rows"
        or raw["machine"] != config.machine
        or raw["slot"] != "absent-validate-rows"
    ):
        raise StateError("absent-validation-row journal identity is invalid")
    input_digest = _as_str(raw["input_sha256"], "absent-validation-row journal.input_sha256")
    if not DIGEST_RE.fullmatch(input_digest):
        raise StateError("absent-validation-row journal input digest is invalid")
    actor = _identity_from_obj(raw["actor"], "absent-validation-row journal.actor")
    if actor is None:
        raise StateError("absent-validation-row journal has no actor")
    if not _as_str(raw["host_id"], "absent-validation-row journal.host_id"):
        raise StateError("absent-validation-row journal has no stable host identity")
    result: list[tuple[AbsentValidateRow, ActiveRecord, dict[str, object]]] = []
    for index, value in enumerate(_as_list(raw["items"], "absent-validation-row journal.items")):
        label = f"absent-validation-row journal.items[{index}]"
        entry = _as_mapping(value, label)
        _exact_keys(entry, {"input", "record", "archive_entry"}, set(), label)
        input_raw = _as_mapping(entry["input"], f"{label}.input")
        _exact_keys(
            input_raw,
            {"machine", "slot", "generation", "record_sha256"},
            set(),
            f"{label}.input",
        )
        item = AbsentValidateRow(
            machine=_validate_name(
                _as_str(input_raw["machine"], f"{label}.input.machine"), "machine"
            ),
            slot=_validate_name(_as_str(input_raw["slot"], f"{label}.input.slot"), "slot"),
            generation=_as_int(input_raw["generation"], f"{label}.input.generation", minimum=1),
            record_sha256=_as_str(input_raw["record_sha256"], f"{label}.input.record_sha256"),
        )
        if item.machine != config.machine or not DIGEST_RE.fullmatch(item.record_sha256):
            raise StateError(f"{label}.input identity is invalid")
        record = _record_from_obj(entry["record"], f"{label}.record")
        _validate_absent_validate_row(record, item)
        archive_entry = dict(_as_mapping(entry["archive_entry"], f"{label}.archive_entry"))
        finished_at = _as_str(
            archive_entry.get("finished_at"), f"{label}.archive_entry.finished_at"
        )
        _parse_timestamp(finished_at, f"{label}.archive_entry.finished_at")
        expected = _absent_validate_archive_entry(record, item, finished_at)
        if not _json_equal(archive_entry, expected):
            raise StateError(f"{label}.archive_entry differs from its exact input row")
        result.append((item, record, archive_entry))
    if not result:
        raise StateError("absent-validation-row journal has no items")
    if len({(item.machine, item.slot) for item, _record, _entry in result}) != len(result):
        raise StateError("absent-validation-row journal repeats a row")
    cursor = _as_int(raw["cursor"], "absent-validation-row journal.cursor", minimum=0)
    if cursor > len(result):
        raise StateError("absent-validation-row journal cursor exceeds its item count")
    return cursor, tuple(result)


def _recover_absent_validate_rows(
    config: Config,
    path: Path,
    raw: Mapping[str, object],
    coordinator: ProcessIdentity,
    *,
    safety_prechecked: bool = False,
) -> tuple[AbsentValidateRow, ...]:
    if path != _journal_path(config):
        raise StateError("absent-validation-row journal filename is invalid")
    local_machine = _short_hostname()
    if config.machine != local_machine:
        raise Refusal(
            f"absent validation rows belong to {config.machine}, but liveness evidence "
            f"is local to {local_machine}; run this command on {config.machine}"
        )
    journal_host = _as_str(raw.get("host_id"), "absent-validation-row journal.host_id")
    current_host = _host_id()
    if journal_host != current_host:
        raise Refusal(
            "absent-validation-row journal belongs to another host identity; "
            "resume it on the host that created it"
        )
    _assert_caller_process(coordinator, "coordinator")
    cursor, items = _absent_validate_batch_items(config, raw)
    journal = dict(raw)
    states, archives = _absent_validate_rows_state(
        config,
        tuple(item for item, _record, _entry in items),
        allow_exact_overlap=True,
    )
    active_state = next(state for state in states if state.machine == config.machine)
    archive_state = next(state for state in archives if state.machine == config.machine)
    active_by_slot = {record.slot: record for record in active_state.slots}
    archived_by_slot = {
        _as_str(entry.get("slot"), "archive slot"): (archive_state, entry)
        for entry in archive_state.records
    }
    current_records: list[ActiveRecord] = []
    archive_presence: list[bool] = []
    for index, (item, recorded, archive_entry) in enumerate(items):
        _assert_absent_validate_row_is_local(recorded)
        current = active_by_slot.get(item.slot)
        archived_pair = archived_by_slot.get(item.slot)
        archived = None if archived_pair is None else archived_pair[1]
        if current is not None:
            _validate_absent_validate_row(current, item)
            if _record_to_obj(current) != _record_to_obj(recorded):
                raise StateError(f"validation row {item.slot} differs from its journal snapshot")
        if archived_pair is not None and (
            not _json_equal(archived_pair[1], archive_entry)
            or not _archive_matches_absent_validate_row(
                archived_pair[0], archived_pair[1], item
            )
        ):
            raise StateError(
                f"archive entry for {item.slot} differs from its typed journal identity"
            )
        if current is None and archived is None:
            raise StateError(f"validation row {item.slot} disappeared without its archive entry")
        archive_presence.append(archived is not None)
        if current is not None:
            current_records.append(current)
    archived_prefix = next(
        (index for index, present in enumerate(archive_presence) if not present),
        len(archive_presence),
    )
    if any(archive_presence[archived_prefix:]):
        raise StateError("absent-validation-row archives do not form a durable prefix")
    if cursor > archived_prefix:
        raise StateError("absent-validation-row journal cursor passed its durable archive prefix")
    if archived_prefix < len(items) and len(current_records) != len(items):
        raise StateError(
            "absent-validation-row batch lost ACTIVE rows before all archives were durable"
        )
    presence = [item.slot in active_by_slot for item, _record, _entry in items]
    first_present = next(
        (index for index, present in enumerate(presence) if present), len(presence)
    )
    if any(not present for present in presence[first_present:]):
        raise StateError("absent-validation-row ACTIVE removals do not form a durable prefix")
    if not safety_prechecked and archived_prefix < len(items):
        _assert_absent_validate_rows_safe(config, current_records)
    before_states, before_archives = states, archives
    target_slots = {item.slot for item, _record, _entry in items}
    before = {
        key: value
        for key, value in _global_rows(before_states, before_archives).items()
        if key[2] not in target_slots
    }
    writer = _event_writer(config, config.machine)
    missing_archives = [
        (item, entry) for item, _record, entry in items[archived_prefix:]
    ]
    if missing_archives:
        archive_state = _append_absent_validate_archives(
            config, archive_state, missing_archives, writer
        )
        for item, _record, archive_entry in items[archived_prefix:]:
            archived_by_slot[item.slot] = (archive_state, archive_entry)
    if cursor != len(items):
        journal["cursor"] = len(items)
        _write_journal(config, journal, event_writer=writer)
        _interrupt_for_test("after-absent-validate-row")
    _atomic_write_json(_archive_path(config, archive_state.machine), _archive_to_obj(archive_state))
    remaining = [
        record
        for item, _recorded, _archive_entry in items
        if (record := active_by_slot.get(item.slot)) is not None
    ]
    if remaining:
        _assert_absent_validate_rows_safe(config, remaining)
        active_state = _write_active_rows_removed(
            config,
            active_state,
            tuple(record.slot for record in remaining),
            evidence_by_slot={
                item.slot: _absent_validate_recovery_evidence(item, entry)
                for item, _record, entry in items
            },
            event_writer=writer,
        )
        _interrupt_for_test("after-absent-validate-active-delete")
    # EVENTS is authoritative.  A crash can occur after either append-only
    # transition and before its compatibility snapshot; rematerialize both
    # views before declaring the journal complete.
    _atomic_write_json(_archive_path(config, archive_state.machine), _archive_to_obj(archive_state))
    _atomic_write_json(_active_path(config, active_state.machine), _active_to_obj(active_state))
    states, archives = _validate_global_state(config)
    active_by_identity = {
        (state.machine, record.slot): record for state in states for record in state.slots
    }
    archived_by_identity = {
        (archive.machine, _as_str(record.get("slot"), "archive slot")): (
            archive,
            record,
        )
        for archive in archives
        for record in archive.records
    }
    for item, _record, archive_entry in items:
        identity = (item.machine, item.slot)
        if active_by_identity.get(identity) is not None:
            raise StateError(f"absent-validation-row recovery retained {item.slot} in ACTIVE")
        found_archive = archived_by_identity.get(identity)
        if (
            found_archive is None
            or not _json_equal(found_archive[1], archive_entry)
            or not _archive_matches_absent_validate_row(
                found_archive[0], found_archive[1], item
            )
        ):
            raise StateError(f"absent-validation-row recovery lost archive {item.slot}")
    after = {
        key: value
        for key, value in _global_rows(states, archives).items()
        if key[2] not in target_slots
    }
    if after != before:
        raise StateError("absent-validation-row recovery changed an unrelated registry row")
    _clear_journal(config, journal, event_writer=writer)
    return tuple(item for item, _record, _entry in items)


def _emit_absent_validate_outcomes(
    rows: Sequence[tuple[AbsentValidateRow, str, str]], output_format: str
) -> None:
    output_rows: list[dict[str, object]] = [
        {
            "machine": item.machine,
            "slot": item.slot,
            "generation": item.generation,
            "outcome": outcome,
            "detail": detail,
        }
        for item, outcome, detail in rows
    ]
    payload: dict[str, object] = {
        "schema": 1,
        "rows": output_rows,
    }
    if output_format == "json":
        print(json.dumps(payload, indent=2, sort_keys=True))
        return
    for row in output_rows:
        print(
            f"ROW machine={row['machine']} slot={row['slot']} "
            f"generation={row['generation']} outcome={row['outcome']} "
            f"detail={json.dumps(row['detail'])}"
        )


def _cmd_recover_absent_validate_rows(args: argparse.Namespace) -> int:
    config = _load_config(args.project_root, args.machine)
    input_sha256, requested = _read_absent_validate_rows_input(config, args.input)
    already_recovered_keys: set[tuple[str, str, int]] = set()
    try:
        local_machine = _short_hostname()
        if config.machine != local_machine:
            raise Refusal(
                f"absent validation rows belong to {config.machine}, but liveness evidence "
                f"is local to {local_machine}; run this command on {config.machine}"
            )
        if args.apply:
            _require_coordinator_authorized(args, "absent validation row recovery")
            if args.coordinator_pid is None:
                raise Refusal("--apply requires --coordinator-pid")
            coordinator = _capture_caller_process(args.coordinator_pid, "coordinator")
        else:
            coordinator = None
        with _mutation_locks(config, args.wait_lock):
            _refuse_partial_state(config)
            journals = _outstanding_journals(config)
            if journals:
                if len(journals) != 1:
                    raise StateError("multiple interrupted mutations require inspection")
                path, raw = _load_journal(config)
                if raw.get("kind") != "recover-absent-validate-rows":
                    raise Refusal(
                        f"another interrupted mutation is recorded in {path}; "
                        "run wrkslots recover"
                    )
                if raw.get("input_sha256") != input_sha256:
                    raise Refusal("absent-validation-row input differs from the interrupted batch")
                _cursor, items = _absent_validate_batch_items(config, raw)
                journal_keys = {
                    (item.machine, item.slot, item.generation) for item, _record, _entry in items
                }
                already_recovered_keys = _already_recovered_absent_validate_keys(
                    _load_all_archives(config), requested
                )
                unaccounted = [
                    item
                    for item in requested
                    if (item.machine, item.slot, item.generation)
                    not in journal_keys | already_recovered_keys
                ]
                if unaccounted:
                    item = unaccounted[0]
                    raise Refusal(
                        f"validation row {item.machine}/{item.slot} is not in the "
                        "interrupted batch and has no exact prior recovery"
                    )
                if not args.apply:
                    _emit_absent_validate_outcomes(
                        [
                            (
                                item,
                                (
                                    "planned"
                                    if (item.machine, item.slot, item.generation) in journal_keys
                                    else "already-recovered"
                                ),
                                (
                                    "resume the recorded batch"
                                    if (item.machine, item.slot, item.generation) in journal_keys
                                    else "exact archive already exists"
                                ),
                            )
                            for item in requested
                        ],
                        args.format,
                    )
                    return 0
                assert coordinator is not None
                _recover_absent_validate_rows(config, path, raw, coordinator)
                _emit_absent_validate_outcomes(
                    [
                        (
                            item,
                            (
                                "recovered"
                                if (item.machine, item.slot, item.generation) in journal_keys
                                else "already-recovered"
                            ),
                            (
                                "archived with validation outcome unknown"
                                if (item.machine, item.slot, item.generation) in journal_keys
                                else "exact archive already existed"
                            ),
                        )
                        for item in requested
                    ],
                    args.format,
                )
                return 0
            states, archives = _validate_global_state(config)
            before = _global_rows(states, archives)
            already_recovered_keys = _already_recovered_absent_validate_keys(
                archives, requested
            )
            planned = _plan_absent_validate_rows(config, requested)
            planned_keys = {
                (item.machine, item.slot, item.generation) for item, _record, _entry in planned
            }
            if not args.apply:
                _emit_absent_validate_outcomes(
                    [
                        (
                            item,
                            (
                                "planned"
                                if (item.machine, item.slot, item.generation) in planned_keys
                                else "already-recovered"
                            ),
                            (
                                f"read-only plan input_sha256={input_sha256}"
                                if (item.machine, item.slot, item.generation) in planned_keys
                                else "exact archive already exists"
                            ),
                        )
                        for item in requested
                    ],
                    args.format,
                )
                return 0
            assert coordinator is not None
            if planned:
                journal = _absent_validate_batch_journal(config, input_sha256, planned, coordinator)
                _write_journal(config, journal)
                _interrupt_for_test("after-absent-validate-batch-journal")
                _recover_absent_validate_rows(
                    config,
                    _journal_path(config),
                    journal,
                    coordinator,
                    safety_prechecked=True,
                )
                after_states, after_archives = _validate_global_state(config)
                target_slots = {item.slot for item in requested}
                if {
                    key: value
                    for key, value in _global_rows(after_states, after_archives).items()
                    if key[2] not in target_slots
                } != {key: value for key, value in before.items() if key[2] not in target_slots}:
                    raise StateError("absent-validation-row recovery changed an unrelated row")
            _emit_absent_validate_outcomes(
                [
                    (
                        item,
                        (
                            "recovered"
                            if (item.machine, item.slot, item.generation) in planned_keys
                            else "already-recovered"
                        ),
                        (
                            "archived with validation outcome unknown"
                            if (item.machine, item.slot, item.generation) in planned_keys
                            else "exact archive already existed"
                        ),
                    )
                    for item in requested
                ],
                args.format,
            )
    except Refusal as exc:
        _emit_absent_validate_outcomes(
            [
                (
                    item,
                    (
                        "already-recovered"
                        if (item.machine, item.slot, item.generation)
                        in already_recovered_keys
                        else "refused"
                    ),
                    (
                        "exact archive already exists"
                        if (item.machine, item.slot, item.generation)
                        in already_recovered_keys
                        else str(exc)
                    ),
                )
                for item in requested
            ],
            args.format,
        )
        raise
    return 0


def _cmd_recover_ownerless_validate_batch(args: argparse.Namespace) -> int:
    ordinary_checkouts = tuple(args.checkouts or ())
    frozen_checkouts = tuple(args.frozen_validate_checkouts or ())
    if bool(ordinary_checkouts) == bool(frozen_checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch requires exactly one of --checkout or "
            "--frozen-validate-checkout; choose the matching validation storage kind and retry"
        )
    frozen = bool(frozen_checkouts)
    checkouts = frozen_checkouts if frozen else ordinary_checkouts
    records = tuple(args.completed_records)
    repositories = tuple(args.repositories)
    proof_manifests = tuple(
        getattr(args, "validation_proof_manifests", ()) or ()
    )
    if not (len(checkouts) == len(records) == len(repositories)):
        raise Refusal(
            "recover-ownerless-validate-batch requires the same number of "
            "--checkout, --completed-record, and --repository arguments"
        )
    if proof_manifests and len(proof_manifests) != len(checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch requires one "
            "--validation-proof-manifest for each checkout when any proof is supplied"
        )
    if len(checkouts) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise Refusal(
            "recover-ownerless-validate-batch accepts at most "
            f"{VALIDATE_REMOVE_BATCH_LIMIT} checkouts"
        )
    if len(set(checkouts)) != len(checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch received the same checkout more than once"
        )
    _require_coordinator_authorized(args, "ownerless validation cleanup")
    config = _load_config(args.project_root, args.machine)
    canonical_proofs = tuple(
        _validation_proof_manifest_path(config, raw)[0]
        for raw in proof_manifests
    )
    if len(canonical_proofs) != len(set(canonical_proofs)):
        raise Refusal(
            "recover-ownerless-validate-batch received the same validation proof "
            "manifest more than once"
        )
    aligned_proofs: tuple[str | None, ...] = (
        tuple(canonical_proofs)
        if canonical_proofs
        else tuple(None for _checkout in checkouts)
    )
    coordinator, runner, handoff_writer, proof_fd = _capture_remove_processes(
        args.coordinator_pid
    )
    retained: list[dict[str, object]] = []
    removed: list[dict[str, object]] = []
    prepared: list[
        tuple[str, str, str, str | None, Path, _PrivateCleanupIdentity]
    ] = []
    with _mutation_locks(config, args.wait_lock):
        _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        if _outstanding_journals(config) or _validate_batch_seal_journals(config):
            raise Refusal(
                "an interrupted mutation is already recorded; recover it before starting "
                "ownerless validation batch cleanup"
            )
        for checkout, record, repository, proof_manifest in zip(
            checkouts,
            records,
            repositories,
            aligned_proofs,
            strict=True,
        ):
            try:
                _relative, target, _allowed = _validation_recovery_target(
                    config,
                    checkout,
                    "frozen-checkout" if frozen else "checkout",
                )
                identity = _private_cleanup_path_identity(
                    config,
                    target,
                    allowed_modes={0o700},
                    managed_root=(
                        _frozen_validation_directory(config) if frozen else None
                    ),
                )
            except (Refusal, StateError) as exc:
                retained.append(
                    {
                        "blocks_entry": True,
                        "checkout": checkout,
                        "reason": str(exc),
                    }
                )
            else:
                prepared.append(
                    (
                        checkout,
                        record,
                        repository,
                        proof_manifest,
                        target,
                        identity,
                    )
                )
    identities = [identity for *_prefix, identity in prepared]
    if len(set(identities)) != len(identities):
        raise Refusal(
            "recover-ownerless-validate-batch resolved multiple checkouts to one directory"
        )
    census_budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
        stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    shared_census_count = int(bool(prepared))
    if prepared:
        try:
            shared_census = _capture_lsof_process_path_census(
                [target for *_prefix, target, _identity in prepared],
                budget=census_budget,
            )
            census_budget.remaining_seconds()
        except Refusal as exc:
            retained.extend(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                }
                for checkout, _record, _repository, _proof, _target, _identity in prepared
            )
            prepared = []
            shared_census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    else:
        shared_census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    batch_cleanup = _OwnerlessValidationBatchContext(
        {identity: target for *_prefix, target, identity in prepared},
        shared_census,
        census_budget,
    )
    for index, (
        checkout,
        record,
        repository,
        proof_manifest,
        target,
        _identity,
    ) in enumerate(prepared):
        try:
            census_budget.remaining_seconds()
            shared_census.assert_slot_unused(
                target, None, ignore_current_process=False
            )
            frozen_result: _FrozenResultEvidence | None = None
            if frozen and proof_manifest is None:
                classification = _frozen_no_proof_disposition(
                    config,
                    target,
                    record,
                    repository,
                    batch_cleanup=batch_cleanup,
                )
                if classification.disposition is _FrozenNoProofDisposition.CURRENT_INCOMPLETE_RETAINED:
                    retained.append({
                        "blocks_entry": False,
                        "checkout": checkout,
                        "reason": "current incomplete frozen validation is exact and inactive; the checkout and no-result remain retained",
                    })
                    continue
                if (
                    classification.disposition
                    is _FrozenNoProofDisposition.CURRENT_TERMINAL_REMOVABLE
                ):
                    frozen_result = classification.frozen_result
                    if frozen_result is None:
                        raise StateError(
                            "current terminal frozen validation lost its durable result"
                        )
                elif (
                    classification.disposition
                    is not _FrozenNoProofDisposition.LEGACY_RECOVERY
                ):
                    nonblocking = (
                        classification.disposition
                        is _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING
                    )
                    historical_schema = classification.historical_schema
                    if nonblocking and historical_schema is None:
                        raise StateError(
                            "historical frozen validation classification lost its schema"
                        )
                    retained.append(
                        {
                            "blocks_entry": not nonblocking,
                            "checkout": checkout,
                            "reason": (
                                f"historical schema {historical_schema} frozen validation has no "
                                "removal proof; the inactive checkout remains retained"
                                if nonblocking
                                else "frozen validation has no typed removal proof; "
                                "the checkout remains retained and blocks entry"
                                + (
                                    f": {classification.detail}"
                                    if classification.detail
                                    else ""
                                )
                            ),
                        }
                    )
                    continue
            item_args = argparse.Namespace(
                project_root=args.project_root,
                machine=args.machine,
                wait_lock=args.wait_lock,
                command="recover",
                coordinator_pid=args.coordinator_pid,
                coordinator_authorized=True,
                discard_partial=False,
                legacy_validate_checkout=checkout,
                ownerless_validate_checkout=None,
                ownerless_validate_cargo_home=None,
                frozen_validate_checkout=checkout if frozen else None,
                completed_record=record,
                repository=repository,
                validation_proof_manifest=proof_manifest,
                frozen_result=frozen_result,
                recovery_note=None,
                retry_running_hook=False,
                abort_create=False,
                abort_import=False,
            )
            if frozen:
                item_args.legacy_validate_checkout = None
                item_args.ownerless_validate_checkout = None
            _cmd_recover(
                item_args,
                ownerless_batch_cleanup=batch_cleanup,
                emit=False,
            )
        except (Refusal, StateError) as exc:
            retained.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                }
            )
            if _outstanding_journals(config) or _validate_batch_seal_journals(config):
                reason = (
                    "an interrupted mutation remains after the preceding refusal; "
                    "recover it before retrying this checkout"
                )
                retained.extend(
                    {
                        "blocks_entry": True,
                        "checkout": remaining[0],
                        "reason": reason,
                    }
                    for remaining in prepared[index + 1 :]
                )
                break
        else:
            removed.append({"checkout": checkout})
    payload = {
        "schema": 2,
        "batch_limit": VALIDATE_REMOVE_BATCH_LIMIT,
        "process_censuses": shared_census_count,
        "shared_process_censuses": shared_census_count,
        "same_uid_process_censuses": batch_cleanup.same_uid_census_count,
        "requested": len(checkouts),
        "removed": removed,
        "retained": retained,
    }
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        print(
            f"requested={len(checkouts)} removed={len(removed)} "
            f"retained={len(retained)} process_censuses={shared_census_count}"
        )
        for row in retained:
            print(
                f"RETAINED: {row['checkout']} "
                f"blocks_entry={str(row['blocks_entry']).lower()} "
                f"reason={row['reason']}"
            )
    return 0


def _cmd_classify_ownerless_validate_batch(args: argparse.Namespace) -> int:
    """Classify retained validation checkouts without locks or writes."""

    ordinary = tuple(args.checkouts or ())
    frozen_values = tuple(args.frozen_validate_checkouts or ())
    if bool(ordinary) == bool(frozen_values):
        raise Refusal(
            "classify-ownerless-validate-batch requires exactly one of --checkout or "
            "--frozen-validate-checkout"
        )
    frozen = bool(frozen_values)
    checkouts = frozen_values if frozen else ordinary
    records = tuple(args.completed_records)
    repositories = tuple(args.repositories)
    proofs = tuple(args.validation_proof_manifests or ())
    if not (len(checkouts) == len(records) == len(repositories)):
        raise Refusal(
            "classify-ownerless-validate-batch requires the same number of "
            "checkout, completed-record, and repository arguments"
        )
    if proofs and len(proofs) != len(checkouts):
        raise Refusal(
            "classify-ownerless-validate-batch requires one proof per checkout"
        )
    if len(checkouts) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise Refusal(
            "classify-ownerless-validate-batch accepts at most "
            f"{VALIDATE_REMOVE_BATCH_LIMIT} checkouts"
        )
    if len(set(checkouts)) != len(checkouts):
        raise Refusal(
            "classify-ownerless-validate-batch received a duplicate checkout"
        )
    config = _load_config(args.project_root, args.machine)
    canonical_proofs = tuple(
        _validation_proof_manifest_path(config, value)[0] for value in proofs
    )
    if len(canonical_proofs) != len(set(canonical_proofs)):
        raise Refusal("classify-ownerless-validate-batch received a duplicate proof")
    if canonical_proofs:
        aligned_proofs: tuple[str | None, ...] = canonical_proofs
    else:
        aligned_proofs = (None,) * len(checkouts)
    _refuse_partial_state(config, allow_validate_batch_seals=True)
    if _validate_batch_seal_journals(config):
        raise Refusal(
            "an interrupted validation-batch seal is recorded; recover it before admission"
        )
    before_states, before_archives = _validate_global_state(config)
    before_rows = _global_rows(before_states, before_archives)
    before_paths = tuple(_outstanding_journals(config))
    create_rows = _classify_create_journals(
        config, before_states, before_archives
    )
    prepared: list[
        tuple[str, str, str, str | None, Path, _PrivateCleanupIdentity]
    ] = []
    results: list[dict[str, object]] = []
    for checkout, record, repository, proof in zip(
        checkouts, records, repositories, aligned_proofs, strict=True
    ):
        try:
            _relative, target, _allowed = _validation_recovery_target(
                config,
                checkout,
                "frozen-checkout" if frozen else "checkout",
            )
            if any(
                _path_is_within(target, row.slot_path)
                or _path_is_within(row.slot_path, target)
                for row in create_rows
            ):
                raise Refusal("validation path overlaps an interrupted create")
            identity = _private_cleanup_path_identity(
                config,
                target,
                allowed_modes={0o700},
                managed_root=(
                    _frozen_validation_directory(config) if frozen else None
                ),
            )
        except (Refusal, StateError) as exc:
            results.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
            )
        else:
            prepared.append((checkout, record, repository, proof, target, identity))
    identities = [identity for *_prefix, identity in prepared]
    if len(set(identities)) != len(identities):
        raise Refusal(
            "classify-ownerless-validate-batch resolved multiple checkouts to one directory"
        )
    budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
        stdout_limit=_PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    census_count = int(bool(prepared))
    if prepared:
        try:
            census = _capture_lsof_process_path_census(
                [target for *_prefix, target, _identity in prepared], budget=budget
            )
            budget.remaining_seconds()
        except Refusal as exc:
            results.extend(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
                for checkout, _record, _repo, _proof, _target, _identity in prepared
            )
            prepared = []
            census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    else:
        census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    batch = _OwnerlessValidationBatchContext(
        {identity: target for *_prefix, target, identity in prepared},
        census,
        budget,
    )
    actor = _read_process_identity(os.getpid())
    for checkout, record, repository, proof, target, _identity in prepared:
        try:
            budget.remaining_seconds()
            census.assert_slot_unused(target, None, ignore_current_process=False)
            if frozen and proof is None:
                historical = _frozen_no_proof_disposition(
                    config,
                    target,
                    record,
                    repository,
                    batch_cleanup=batch,
                )
                if historical.disposition is _FrozenNoProofDisposition.CURRENT_INCOMPLETE_RETAINED:
                    results.append({
                        "blocks_entry": False,
                        "checkout": checkout,
                        "reason": "current incomplete frozen validation is exact and inactive; the checkout and no-result remain retained",
                        "state": "current-incomplete-retained",
                    })
                    continue
                if (
                    historical.disposition
                    is _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING
                ):
                    results.append(
                        {
                            "blocks_entry": False,
                            "checkout": checkout,
                            "reason": (
                                f"historical schema {historical.historical_schema} "
                                "validation is exact and inactive; it remains retained"
                            ),
                            "state": "historical-retained",
                        }
                    )
                    continue
                if historical.disposition is _FrozenNoProofDisposition.BLOCKS_ENTRY:
                    raise Refusal(
                        "frozen validation has no typed removal proof and cannot "
                        "be classified as historical"
                        + (f": {historical.detail}" if historical.detail else "")
                    )
            item_args = argparse.Namespace(
                ownerless_validate_checkout=None if frozen else checkout,
                ownerless_validate_cargo_home=None,
                frozen_validate_checkout=checkout if frozen else None,
                completed_record=record,
                repository=repository,
                validation_proof_manifest=proof,
                frozen_result=(
                    historical.frozen_result
                    if frozen and proof is None
                    else None
                ),
                recovery_note=None,
            )
            _ownerless_validation_journal(
                config,
                item_args,
                actor,
                before_states,
                batch_cleanup=batch,
                require_remote_containment=False,
            )
        except (Refusal, StateError) as exc:
            results.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
            )
        else:
            results.append(
                {
                    "blocks_entry": False,
                    "checkout": checkout,
                    "reason": (
                        "terminal validation is exact and unused; read-only "
                        "classification left it retained"
                    ),
                    "state": "terminal-retained",
                }
            )
    after_states, after_archives = _validate_global_state(config)
    if before_rows != _global_rows(after_states, after_archives):
        raise Refusal("active registry changed during validation classification")
    if before_paths != tuple(row.path for row in create_rows):
        raise Refusal("recovery journal set changed before validation classification")
    _assert_create_journal_classifications_stable(
        config, create_rows, after_states, after_archives
    )
    payload = {
        "classifications": results,
        "create_journals": [row.to_obj() for row in create_rows],
        "process_censuses": census_count,
        "requested": len(checkouts),
        "schema": 1,
    }
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        blocking = sum(result["blocks_entry"] is True for result in results)
        print(
            f"requested={len(checkouts)} blocking={blocking} "
            f"nonblocking={len(results) - blocking} process_censuses={census_count}"
        )
        for result in results:
            print(
                f"{result['state']}: {result['checkout']} "
                f"blocks_entry={str(result['blocks_entry']).lower()} "
                f"reason={result['reason']}"
            )
    return 0


def _cmd_recover(
    args: argparse.Namespace,
    *,
    ownerless_batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    emit: bool = True,
) -> int:
    config = _load_config(args.project_root, args.machine)
    coordinator, runner, handoff_writer, proof_fd = _capture_remove_processes(
        args.coordinator_pid
    )
    live_use_recheck = (
        ownerless_batch_cleanup.live_use_recheck
        if ownerless_batch_cleanup is not None
        else _LiveUseRecheckBudget()
    )
    processes = _RecoveryProcesses(coordinator, runner, handoff_writer, proof_fd)
    with _mutation_locks(config, args.wait_lock):
        _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
        recovered_partial = _recover_partial_updates(config, args.discard_partial)
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        if (
            recovered_partial
            and not _outstanding_journals(config)
            and not _validate_batch_seal_journals(config)
        ):
            _ensure_event_log(config)
            _write_event_file(
                config,
                config.machine,
                "partial-updates-recovered",
                {
                    "actor": _identity_to_obj(coordinator),
                    "coordinator_authorized": bool(args.coordinator_authorized),
                },
            )
            states, _archives = _validate_global_state(config)
            _assert_command_registry_storage(config, states, args)
            return 0
        legacy_requested = args.legacy_validate_checkout is not None
        if legacy_requested and any(
            value is not None
            for value in (
                args.ownerless_validate_checkout,
                args.ownerless_validate_cargo_home,
                args.frozen_validate_checkout,
            )
        ):
            raise Refusal("legacy and ownerless validation path flags cannot be combined")
        if legacy_requested:
            if args.completed_record is None or args.repository is None or args.recovery_note:
                raise Refusal(
                    "--legacy-validate-checkout requires --completed-record and --repository"
                )
            args.ownerless_validate_checkout = args.legacy_validate_checkout
        requested_ownerless = any(
            value is not None
            for value in (
                args.ownerless_validate_checkout,
                args.ownerless_validate_cargo_home,
                args.frozen_validate_checkout,
                args.completed_record,
                args.repository,
                args.recovery_note,
                getattr(args, "validation_proof_manifest", None),
            )
        )
        if getattr(args, "slot", None) is not None and requested_ownerless:
            raise Refusal(
                "--slot selects an interrupted mutation and cannot be combined "
                "with validation cleanup flags"
            )
        if requested_ownerless:
            _require_coordinator_authorized(args, "ownerless validation cleanup")
            if args.abort_import:
                raise Refusal(
                    "--abort-import applies only to an interrupted import-existing "
                    "journal and cannot be combined with validation cleanup flags"
                )
            if sum(
                value is not None
                for value in (
                    args.ownerless_validate_checkout,
                    args.ownerless_validate_cargo_home,
                    args.frozen_validate_checkout,
                )
            ) != 1:
                raise Refusal(
                    "ownerless validation cleanup requires exactly one target path"
                )
            if _outstanding_journals(config) or _validate_batch_seal_journals(
                config
            ):
                raise Refusal(
                    "an interrupted mutation is already recorded. state: REFUSED -- the new "
                    "validation cleanup did not start. remedy: rerun 'wrkslots recover "
                    "--coordinator-pid PID' without cleanup flags to finish the recorded "
                    "operation first"
                )
            states, archives = _validate_global_state(config)
            raw_target = (
                args.frozen_validate_checkout
                or args.ownerless_validate_checkout
                or args.ownerless_validate_cargo_home
            )
            target_kind = (
                "frozen-checkout"
                if args.frozen_validate_checkout
                else "checkout"
                if args.ownerless_validate_checkout
                else "cargo-home"
            )
            assert raw_target is not None
            if target_kind == "frozen-checkout" and (
                args.completed_record is None
                or args.repository is None
                or args.recovery_note is not None
            ):
                raise Refusal(
                    "--frozen-validate-checkout requires --completed-record and "
                    "--repository; provide the terminal run handle and its source checkout"
                )
            _relative, _target, allowed = _validation_recovery_target(
                config, raw_target, target_kind
            )
            _assert_command_registry_storage(
                config,
                states,
                args,
                allowed_unregistered_slot=allowed,
                target_slot=allowed[1] if allowed is not None else None,
                scope_to_target=True,
            )
            before = _global_rows(states, archives)
            journal, _allowed = _ownerless_validation_journal(
                config,
                args,
                coordinator,
                states,
                batch_cleanup=ownerless_batch_cleanup,
                live_use_recheck=live_use_recheck,
            )
            _write_journal(config, journal)
            if legacy_requested:
                _interrupt_for_test("after-legacy-validate-journal")
            _interrupt_for_test("after-ownerless-validate-journal")
            path = _journal_path(config)
            raw: Mapping[str, object] = journal
        else:
            seal_journals = _validate_batch_seal_journals(config)
            selected_slot = getattr(args, "slot", None)
            selected_path: Path | None
            if seal_journals:
                loaded_seal = _load_validate_batch_seal_journal(config)
                assert loaded_seal is not None
                _seal_path, _seal_raw, sealed_targets = loaded_seal
                paired_finish = _validate_batch_seal_paired_finish(
                    config,
                    sealed_targets,
                )
                if paired_finish is None:
                    sealed_slots = {slot for slot, _generation, _target in sealed_targets}
                    if selected_slot is not None and selected_slot not in sealed_slots:
                        raise Refusal(
                            "a private validation seal must be recovered before the "
                            f"unrelated mutation for slot {selected_slot!r}"
                        )
                    # ci-hub/bin/wrkslots always runs 'recover' in a host
                    # service that does not descend from the coordinator, so
                    # check the same handoff every other recovery checks.
                    # Without a handoff this is still direct ancestry.
                    _assert_recovery_processes(coordinator, processes)
                    _recover_validate_batch_seal_journal(
                        config,
                        recovery_kind=_ValidateBatchSealRecoveryKind.SEAL_ONLY,
                    )
                    return 0
                if selected_slot is not None and selected_slot != paired_finish.slot:
                    raise Refusal(
                        "a private validation finish must be recovered before the "
                        f"unrelated mutation for slot {selected_slot!r}; rerun with "
                        f"--slot {paired_finish.slot}"
                    )
                selected_path = _journal_path_for_slot(
                    config, paired_finish.slot
                )
            else:
                selected_path = (
                    _journal_path_for_slot(config, selected_slot)
                    if selected_slot is not None
                    else None
                )
            path, raw = _load_journal(config, selected_path=selected_path)
        kind_hint = _as_str(raw.get("kind"), "journal.kind")
        if args.abort_import and kind_hint != "import-existing":
            raise Refusal(
                f"--abort-import applies only to import-existing journals; the "
                f"recorded journal is {kind_hint!r}"
            )
        if kind_hint == "finish":
            recovery_states, recovery_archives = (
                _validate_global_state_for_finish_recovery(config, raw)
            )
            recovery_record = _record_from_obj(
                raw.get("record"), "finish journal.record"
            )
            excluded = frozenset({path})
            coexisting_creates = _classify_disjoint_create_journals_for_record(
                config,
                recovery_states,
                recovery_archives,
                recovery_record,
                excluded_paths=excluded,
            )
            _recheck_disjoint_create_journals_for_record(
                config,
                coexisting_creates,
                recovery_states,
                recovery_archives,
                recovery_record,
                excluded_paths=excluded,
            )
        _assert_recovery_processes(coordinator, processes)
        _ensure_event_log(config)
        _write_event_file(
            config,
            config.machine,
            "recovery-started",
            {
                "slot": raw.get("slot"),
                "operation": raw.get("kind"),
                "actor": _identity_to_obj(coordinator),
                "runner": _identity_to_obj(runner),
                "handoff_writer": (
                    _identity_to_obj(handoff_writer)
                    if handoff_writer is not None
                    else None
                ),
                "coordinator_authorized": bool(args.coordinator_authorized),
            },
        )
        if _as_int(raw.get("schema"), "journal.schema") != SCHEMA:
            raise StateError("unsupported recovery journal schema")
        machine = _as_str(raw.get("machine"), "journal.machine")
        if machine != config.machine:
            raise Refusal(
                f"journal belongs to machine {machine}; rerun with --machine {machine}"
            )
        kind = kind_hint
        seal_journals = _validate_batch_seal_journals(config)
        if seal_journals:
            if kind != "finish":
                raise StateError(
                    "validation-batch seal evidence coexists with a non-finish journal"
                )
            record = _record_from_obj(raw.get("record"), "finish journal.record")
            raw = _upgrade_legacy_finish_seal_identity(
                config, raw, record, journal_path=path
            )
            private_identity = _finish_private_census_identity(raw)
            if private_identity is None:
                raise StateError(
                    "validation-batch seal evidence coexists with a non-batch finish journal"
                )
            original_mode = _as_int(
                raw.get("original_mode"), "finish journal.original_mode"
            )
            _assert_validate_batch_seal_target(
                config, record, original_mode, private_identity
            )
        elif kind == "finish" and _finish_private_census_identity(raw) is not None:
            raise StateError(
                "private finish journal is missing its validation-batch seal evidence"
            )
        if kind == "finish":
            states, archives = _validate_global_state_for_finish_recovery(config, raw)
        elif kind == "recover-absent-validate-rows":
            _cursor, batch_items = _absent_validate_batch_items(config, raw)
            states, archives = _absent_validate_rows_state(
                config,
                tuple(item for item, _record, _entry in batch_items),
                allow_exact_overlap=True,
            )
        elif kind == "recover-absent-agent-row":
            states, archives = _validate_global_state_for_absent_agent_recovery(
                config, raw
            )
        else:
            states, archives = _validate_global_state(config)
        before = _global_rows(states, archives)
        state = _load_active(
            config, require_repository=kind != "finish"
        )
        if kind == "create":
            _assert_remove_processes(coordinator, runner, handoff_writer, proof_fd)
            _recover_create(
                config,
                path,
                raw,
                state,
                coordinator,
                retry_running_hook=args.retry_running_hook,
                abort_create=args.abort_create,
            )
        elif kind == "import-existing":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_import_existing(
                config,
                path,
                raw,
                state,
                coordinator,
                abort_import=args.abort_import,
            )
        elif kind == "finish":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            try:
                _recover_finish(
                    config,
                    path,
                    raw,
                    state,
                    coordinator,
                    processes=processes,
                    live_use_recheck=live_use_recheck,
                )
            except Refusal as exc:
                _restore_interrupted_private_finish_after_refusal(
                    config, raw, exc
                )
                if seal_journals:
                    _recover_validate_batch_seal_journal(
                        config,
                        recovery_kind=_ValidateBatchSealRecoveryKind.PAIRED_FINISH,
                        retain_evidence=True,
                    )
                raise
        elif kind == "legacy-validate-remove":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_legacy_validate_remove(config, path, raw, coordinator)
        elif kind == "ownerless-validate-remove":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_ownerless_validation(
                config,
                path,
                raw,
                coordinator,
                runner,
                handoff_writer,
                proof_fd,
                batch_cleanup=ownerless_batch_cleanup,
                emit=emit,
                live_use_recheck=live_use_recheck,
            )
        elif kind == "ownerless-agent-remove":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_ownerless_agent(config, path, raw, coordinator)
        elif kind == "ownerless-agent-cache-relocate":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_ownerless_agent_cache(config, path, raw, coordinator)
        elif kind == "recover-absent-validate-rows":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            try:
                recovered = _recover_absent_validate_rows(config, path, raw, coordinator)
            except Refusal as exc:
                _emit_absent_validate_outcomes(
                    [(item, "refused", str(exc)) for item, _record, _entry in batch_items],
                    "human",
                )
                raise
            _emit_absent_validate_outcomes(
                [
                    (
                        item,
                        "recovered",
                        "archived with validation outcome unknown",
                    )
                    for item in recovered
                ],
                "human",
            )
        elif kind == "recover-absent-agent-row":
            if args.retry_running_hook or args.abort_create:
                raise Refusal(
                    "--retry-running-hook and --abort-create apply only to create journals"
                )
            _recover_absent_agent_row(config, path, raw, coordinator)
        else:
            raise StateError(f"unknown recovery journal kind {kind!r}")
        if seal_journals:
            _recover_validate_batch_seal_journal(
                config,
                recovery_kind=_ValidateBatchSealRecoveryKind.SEAL_ONLY,
            )
        after_states, after_archives = _validate_global_state(
            config, require_repository=kind != "finish"
        )
        after = _global_rows(after_states, after_archives)
        if kind == "recover-absent-validate-rows":
            pass
        elif kind in {
            "legacy-validate-remove",
            "ownerless-validate-remove",
            "ownerless-agent-remove",
            "ownerless-agent-cache-relocate",
        }:
            if after != before:
                raise StateError("ownerless cleanup changed the registered slot state")
        else:
            slot = _as_str(raw.get("slot"), "journal.slot")
            _assert_only_slot_changed(before, after, slot)
    return 0


class _HelpFormatter(argparse.RawDescriptionHelpFormatter):
    def __init__(self, prog: str) -> None:
        super().__init__(prog, max_help_position=30, width=100)


def _add_repo_options(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--repo",
        action="append",
        metavar="NAME=PATH",
        help=(
            "relative source Git repository path inside the project root, or ../NAME[/PATH] "
            "path components inside one direct sibling; absolute paths, other parent traversal, "
            "and symlink components are refused. NAME labels the checkout and must match the "
            "other NAME=VALUE options (repeat once per checkout)"
        ),
    )
    parser.add_argument(
        "--remote",
        action="append",
        metavar="NAME=REMOTE",
        help=(
            "configured Git remote name for one checkout "
            "(default: the remote recorded by init)"
        ),
    )
    parser.add_argument(
        "--remote-url",
        action="append",
        metavar="NAME=URL",
        help=(
            "expected fetch URL for the selected remote; when omitted, record the "
            "configured URL (repeat once per applicable checkout)"
        ),
    )


def _add_task_scope_options(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--task-scope-unit",
        metavar="UNIT.scope",
        help=(
            "exact transient systemd scope containing --owner-pid; requires "
            "--task-scope-invocation-id; the owner cgroup must end in /UNIT.scope and "
            "the runtime invocation symlink must match before the row is written"
        ),
    )
    parser.add_argument(
        "--task-scope-invocation-id",
        metavar="HEX32",
        help=(
            "lowercase 32-hex systemd InvocationID for --task-scope-unit; both "
            "scope options must be supplied together and are verified through "
            "/run/user/$UID/systemd/units/invocation:UNIT.scope"
        ),
    )


_QUICKSTART = """\
wrkslots manages durable agent and validation worktree slots.

1. Initialize the project once. The running command is project-owned and is called with the agent
   name. It must return 0 for dead, 1 for alive, or 2 when it cannot determine the answer. init
   writes .wrkslots.yml as literate YAML with a comment above every key (older JSON projects
   still load; `wrkslots config convert --to yaml` converts them).

     wrkslots init . --worktrees-dir worktrees/slots --liveness-command tools/agent-liveness.py

2. Create a new linked worktree and branch from an existing source repository. The repository's
   configured origin is used by default; add --remote product=upstream to choose another remote,
   and add --remote-url product=URL when the caller must verify its fetch URL.

     wrkslots create slot01 \\
       --slot-type agent --coordinator-authorized \\
       --agent codex-1 --task task-123 --purpose "fix parser" \\
       --coordinator-pid "$COORDINATOR_PID" --owner-pid "$OWNER_PID" \\
       --repo product=product --branch product=codex/fix-parser

3. The exact recorded owner refreshes its heartbeat while working.

     wrkslots heartbeat slot01 \\
       --agent codex-1 --owner-pid "$OWNER_PID" --expected-generation 1

4. Before exiting, the owner may record a clean, published handoff. This retains the slot.

     wrkslots write-handoff slot01 \\
       --agent codex-1 --owner-pid "$OWNER_PID" --expected-generation 1 \\
       --from-file /path/to/HANDOFF.md

     wrkslots finish slot01 \\
       --agent codex-1 --owner-pid "$OWNER_PID" --expected-generation 1 \\
       --validation "make test: pass"

   An owner that is done with the slot but keeps running gives it back after writing the
   handoff. The release is bound to that owner process, the generation, the current heartbeat,
   and the handoff digest. It stops this generation's heartbeat, and removal then no longer waits
   for the owner to exit or for the time-to-live. Leave the slot first: removal still refuses
   while any process, the owner included, uses it.

     wrkslots release slot01 \\
       --agent codex-1 --owner-pid "$OWNER_PID" --expected-generation 1

5. Reading a handoff prints its exact contents and enqueues that generation without removing it.

     wrkslots read-handoff slot01 \\
       --coordinator-pid "$CURRENT_COORDINATOR_PID"

6. After the registered running command and exact process identity prove the owner dead, and the
   recorded time-to-live expires without renewal, any later coordinator may remove the slot. A
   slot its owner released needs only the handoff read from step 5.
   Agent slots preserve dirty and unpushed work first; validate slots skip salvage. Salvage never
   stages a HANDOFF* file, and it pushes only to remotes listed in salvage_push_remotes. Work on
   any other remote is kept in a self-contained Git bundle under <control>/wrkslots-salvage/ (or
   under --salvage-archive-root), and removal begins only after the bundle and receipt pass
   readback checks. If a push to an allowed remote refuses and an operator explicitly approves
   durable local custody, pass an existing absolute directory outside the project.

     wrkslots remove slot01 \\
       --coordinator-pid "$CURRENT_COORDINATOR_PID" --expected-generation 1

   Add `--salvage-archive-root "$HOME/temp/agent_checkouts"` to that remove command to enable
   this fallback for a refused push.

If a create or removal is interrupted, preserve all paths and run:

     wrkslots recover --coordinator-pid "$CURRENT_COORDINATOR_PID"

Box a command or agent to a slot (plain or image-backed alike): per-slot limits, a fresh /tmp,
the real $HOME read-only under a per-slot private layer, and only the slot, its Git directories,
the project's outputs (ai_docs, experiments), and shared harness state writable. `init` writes
every default into the configuration's sandbox section; inspect it with `sandbox show-config`.

     wrkslots run slot01 -- make test
     wrkslots run slot01 --isolation root -- HARNESS ...   # setuid helpers work inside
     wrkslots shell-command slot01 --format json            # for agent launchers
     wrkslots sandbox write-defaults                        # older projects: add missing keys

Box a (sub)coordinator that creates slots and launches subagents into them: the same view,
but every slot, the registry, and the slots' Git directories writable (--writable project: the
whole project root), with no slot. Image slots it creates are mounted on the host.

     wrkslots box --isolation root --cwd worktrees -- HARNESS ...
     wrkslots shell-command --box --cwd worktrees --format json   # for agent launchers

Use `wrkslots COMMAND --help` for the exact effects and inputs of one command.
"""


def _cmd_config_help(args: argparse.Namespace) -> int:
    parser = args.config_parser
    assert isinstance(parser, argparse.ArgumentParser)
    parser.print_help()
    return 0


def _cmd_config_convert(args: argparse.Namespace) -> int:
    # Loading validates the whole configuration first: an invalid file is not rewritten.
    config = _load_config(args.project_root, args.machine)
    with _locked_config(config.config_path, args.wait_lock):
        raw, current = _read_config_document(config.config_path)
        _write_config(config.config_path, raw, args.target)
    backup = config.config_path.with_name(config.config_path.name + ".bak")
    print(f"wrote {config.config_path} as {args.target} (was {current}); previous bytes in {backup}")
    return 0


def _cmd_quickstart(_args: argparse.Namespace) -> int:
    print(_QUICKSTART)
    return 0


def _load_userguide() -> str:
    return Path(__file__).with_name("USER_GUIDE.md").read_text(encoding="utf-8")


def _build_parser() -> argparse.ArgumentParser:
    description = """Create, track, hand off, recover, and remove Git worktree slots for coding agents.

Read-only: status, doctor, audit, import-existing without --apply, and
clean-caches without --only or --yes. unpushed refreshes remote-tracking refs
but does not mutate registry state.
Mutating: init, create, register, import-existing --apply, adopt,
recover-unbound-owner, relocate-repository --apply, heartbeat, hold, unhold,
clean-caches deletion, finish,
write-handoff, release, read-handoff, retire-pending, remove,
recover-absent-validate-rows --apply, and recover. Registry mutations take a state lock and append
hash-linked events. ACTIVE and ARCHIVED are compatibility views derived from those events.
Configuration: config convert (literate YAML or JSON .wrkslots.yml).
Storage and boxing: image (slot disk images), run and shell-command (box a command
or agent to a slot, for plain and image slots alike), box (a coordinator box: all slots
and the registry writable, no slot), sandbox (show or complete the
configuration's sandbox section), and limits (the machine-wide guard).
Each slot binds an agent identity, coordinator process generation, and one or more linked Git
worktrees to durable machine-sharded state. Removal fails closed unless the time-to-live,
registered running command, process evidence, Git state, salvage evidence, and recovery journal
all agree that deletion is safe.
"""
    epilog = """Lifecycle:
  wrkslots quickstart
  wrkslots init . --worktrees-dir worktrees/slots --liveness-command tools/agent-liveness.py
  wrkslots create slot01 --slot-type agent --coordinator-authorized \\
    --agent codex-1 --task task-123 --purpose "fix parser" \\
    --repo product=product --branch product=codex/fix-parser \\
    --coordinator-pid PID --owner-pid PID
  wrkslots heartbeat slot01 --agent codex-1 --owner-pid PID --expected-generation 1
  wrkslots finish slot01 --agent codex-1 --owner-pid PID --expected-generation 1 \\
    --validation "exact command and result"

finish proves clean index/tracked/untracked/ignored state outside configured regenerable cache
paths, no unfinished Git operation, remote durability, exact landed ancestry, and path identity,
then records the owner-alive handoff while retaining physical storage. Any later participant may
run remove. It proceeds only after the heartbeat TTL expires, the registered liveness command
returns rc 0, the exact owner process generation is dead, and independent process/cgroup/mount
checks prove the slot unused. rc 1, rc 2, and unavailable evidence all refuse. An owner that keeps
running may instead give the slot back with 'wrkslots release' after write-handoff; that replaces
only the owner-exit, liveness, and TTL conditions, never the handoff read or the use checks.

Any failed precondition leaves every worktree in place. If a process stops during create or
remove, later mutations refuse and 'wrkslots recover' resumes from the append-only history and
its journal compatibility view. Never edit EVENTS.*, ACTIVE.*, ARCHIVED.*, or a journal by hand.

Global options (--project-root, --machine, --wait-lock,
--allow-existing-unregistered-worktrees) precede the command.
Exit status: 0 success/no gate finding, 1 audit gate action, 2 command-line
usage or audit gate unknown, 3 fail-closed refusal.
"""
    parser = argparse.ArgumentParser(
        prog="wrkslots",
        description=description,
        epilog=epilog,
        formatter_class=_HelpFormatter,
    )
    parser.add_argument("--version", action="version", version=f"wrkslots {VERSION}")
    parser.add_argument(
        "--userguide",
        action="store_true",
        help="print the complete installed user guide and exit",
    )
    parser.add_argument(
        "--project-root",
        help=f"project root containing {CONFIG_NAME}; otherwise search upward",
    )
    parser.add_argument(
        "--machine",
        help=(
            "override the configured machine shard (or set WRKSLOTS_MACHINE); create, "
            "register, and import-existing --apply refuse an implicit configured shard "
            "that differs from the current host"
        ),
    )
    parser.add_argument(
        "--wait-lock",
        type=float,
        default=0.0,
        metavar="SECONDS",
        help="wait up to this many seconds for a state lock (default: fail immediately)",
    )
    parser.add_argument(
        "--allow-existing-unregistered-worktrees",
        action="store_true",
        help=(
            "permit operations on registered slots while retaining and warning about "
            "pre-existing worktree directories that have no wrkslots record; never treats "
            "those directories as free or authorizes their removal"
        ),
    )
    subparsers = parser.add_subparsers(dest="command", metavar="COMMAND")

    quickstart = subparsers.add_parser(
        "quickstart",
        help="print the normal end-to-end workflow",
        description="Print a concise tutorial for init, create, heartbeat, finish, remove, and recovery.",
        formatter_class=_HelpFormatter,
    )
    quickstart.set_defaults(handler=_cmd_quickstart)

    init = subparsers.add_parser(
        "init",
        help="initialize wrkslots for one project",
        description=(
            "Initialize wrkslots once at a project root. This creates the configuration, empty "
            "machine state, managed worktrees directory, and a project-local command symlink. "
            "It does not create a slot or alter a source repository."
        ),
        epilog=(
            "The running command is project-owned deletion authority. wrkslots invokes it as "
            "PATH AGENT with recorded identity in WRKSLOTS_* environment variables. Exit 0 means "
            "dead, 1 means alive, and 2 means unverifiable; every other result refuses removal."
        ),
        formatter_class=_HelpFormatter,
    )
    init.add_argument(
        "directory",
        nargs="?",
        default=".",
        help="project root to initialize (default: current directory)",
    )
    init.add_argument(
        "--worktrees-dir",
        default="worktrees/slots",
        metavar="PATH",
        help=(
            "managed agent-slot directory relative to the project root; validation slots use "
            "the sibling worktrees/validate directory (default: worktrees/slots)"
        ),
    )
    init.add_argument(
        "--default-remote",
        default="origin",
        metavar="REMOTE",
        help="configured Git remote name used when create omits --remote (default: origin)",
    )
    init.add_argument(
        "--default-landed-ref",
        default="refs/remotes/origin/main",
        metavar="REF",
        help="remote-tracking ref that a finished commit must reach (default: refs/remotes/origin/main)",
    )
    init.add_argument(
        "--heartbeat-ttl-seconds",
        type=int,
        default=3600,
        metavar="SECONDS",
        help=(
            "age after which an unrenewed heartbeat satisfies one reclaim condition; owner and "
            "liveness evidence must independently agree (default: 3600)"
        ),
    )
    init.add_argument(
        "--layout",
        choices=("nested", "flat"),
        default="nested",
        help="nested puts repositories under each slot; flat makes one checkout the slot root",
    )
    init.add_argument(
        "--liveness-command",
        required=True,
        metavar="PATH",
        help=(
            "executable path relative to the project root; called as PATH AGENT during removal "
            "and must return 0 dead, 1 alive, or 2 unverifiable"
        ),
    )
    init.add_argument(
        "--liveness-batch-command",
        metavar="PATH",
        help=(
            "optional executable path relative to the project root implementing the "
            "typed wrkslots batch-liveness protocol used by audit; removal continues "
            "to call --liveness-command for one exact subject"
        ),
    )
    init.add_argument(
        "--max-active-slots",
        type=int,
        default=None,
        help="refuse create/register beyond this many active slots on this machine "
        "(default: uncapped)",
    )
    init.add_argument(
        "--cache-glob",
        action="append",
        metavar="PATH-GLOB",
        help="checkout-relative regenerable directory glob applied to every repository",
    )
    init.add_argument(
        "--repo-cache-glob",
        action="append",
        metavar="NAME=PATH-GLOB",
        help="regenerable directory glob applied only to repository NAME (repeatable)",
    )
    init.add_argument(
        "--post-provision-hook",
        action="append",
        metavar="SHELL-COMMAND",
        help="ordered shell command run in every new checkout (repeatable)",
    )
    init.add_argument(
        "--salvage-push-remote",
        action="append",
        metavar="REMOTE-URL",
        help=(
            "remote URL that removal may push salvage commits to (repeatable); work on "
            "any other remote is kept in a verified local bundle. Rerunning init without "
            "this flag keeps the existing list (default for a new project: none)"
        ),
    )
    init.add_argument(
        "--config-format",
        choices=yamlconfig.FORMATS,
        default=None,
        help=(
            f"format of a NEW {CONFIG_NAME}: yaml (literate YAML with a comment above every "
            "key; the default) or json. An existing file keeps its format when init --repair "
            "rewrites it; convert it with `wrkslots config convert`"
        ),
    )
    init.add_argument(
        "--slot-representation",
        choices=SLOT_REPRESENTATIONS,
        default=None,
        help=(
            "storage for NEW slots: image (one sparse disk image per slot; the default for a "
            "new project) or worktree (plain directories). Rerunning init on an existing "
            "project keeps its current setting unless this flag is given; change it later "
            "with `wrkslots image set-default`. Existing slots are never converted by this"
        ),
    )
    init.add_argument(
        "--image-ceiling-gib",
        type=int,
        default=None,
        metavar="GIB",
        help=(
            "apparent size of each new slot image in GiB. Images are sparse: this is an upper "
            f"bound, not a reservation (default: {slotimage.DEFAULT_CEILING_BYTES // GIB})"
        ),
    )
    init.add_argument(
        "--image-backend",
        choices=slotimage.BACKENDS,
        default=None,
        help=(
            "how slot images are mounted: kernel (sudo -n mount -o loop), fuse (fuse2fs, no "
            "privilege), or auto (kernel when sudo -n works, else fuse; default)"
        ),
    )
    init.add_argument(
        "--sandbox-isolation",
        choices=sandbox.ISOLATIONS,
        default=None,
        help=(
            "configuration.sandbox.isolation for boxed commands and agents: userns (limits plus "
            "a confined file-system view in an unprivileged user namespace; the default for a "
            "new project), root (the same view built through sudo -n, for harness launchers "
            "that need a setuid step), or cgroup (per-slot limits only, no file-system view). "
            "To change it later, edit sandbox.isolation in the configuration; rerunning init "
            "with a different value refuses like any other configuration change"
        ),
    )
    init.add_argument("--disk-advisory-gib", type=int)
    init.add_argument("--disk-provisioning-floor-gib", type=int)
    init.add_argument("--disk-emergency-gib", type=int)
    init.add_argument(
        "--repair",
        action="store_true",
        help="migrate files written by an older build: repair compatible "
        "configuration, exact empty schema-1 machine state, and the previous "
        "repository command symlink; refuse conflicting or populated state",
    )
    init.set_defaults(handler=_cmd_init)

    status = subparsers.add_parser(
        "status",
        help="show active slots and safety diagnoses",
        description=(
            "Read durable state without mutating it. Reports ownership, heartbeat age, process "
            "evidence, Git state, journals, and cross-machine conflicts. A diagnosis never "
            "authorizes deletion."
        ),
        formatter_class=_HelpFormatter,
    )
    status.add_argument(
        "--all-machines",
        action="store_true",
        help="read every ACTIVE machine shard instead of only the selected machine",
    )
    status.add_argument("--slot", metavar="SLOT", help="limit output to this slot name")
    status.add_argument(
        "--format",
        choices=("human", "json"),
        default="human",
        help="output format (default: human)",
    )
    status.set_defaults(handler=_cmd_status)

    doctor = subparsers.add_parser(
        "doctor",
        description=(
            "read-only: list every registry/storage disagreement at once "
            "instead of refusing at the first; authorizes nothing"
        ),
        help="list every registry/storage disagreement at once (read-only)",
    )
    doctor.add_argument("--all-machines", action="store_true", help="read every ACTIVE shard")
    doctor.add_argument("--format", choices=("human", "json"), default="human")
    doctor.set_defaults(handler=_cmd_doctor)

    audit = subparsers.add_parser(
        "audit",
        description=(
            "lifecycle-read-only leak audit with per-slot deletion verdicts; may update "
            "only regenerable cache-accounting census state"
        ),
        help="show leak counts and DELETABLE/BLOCKED/HELD verdicts",
    )
    audit.add_argument("--format", choices=("human", "json"), default="human")
    audit.add_argument(
        "--cache-census-state",
        metavar="PATH",
        help=(
            "canonical absolute resumable cache-accounting state path beneath an "
            "existing symlink-free parent outside the managed project (default: a "
            "project-keyed file below XDG_CACHE_HOME or "
            "~/.cache); never stores lifecycle authority"
        ),
    )
    audit.add_argument(
        "--cache-work-limit",
        type=int,
        default=_AUDIT_CACHE_WORK_LIMIT,
        metavar="ENTRIES",
        help=(
            "maximum cache traversal work units per invocation, and separately the "
            "maximum directory listings for cache-glob planning; oversized subject "
            f"planning or finalization reports null/error (default: {_AUDIT_CACHE_WORK_LIMIT})"
        ),
    )
    audit.add_argument(
        "--cache-wall-seconds",
        type=float,
        default=_AUDIT_CACHE_WALL_SECONDS,
        metavar="SECONDS",
        help=(
            "cache binding/traversal wall budget in seconds, and separately the budget for "
            "walking directories to expand cache globs, excluding Git observations and "
            "state I/O; unfinished work is null/partial, "
            "a planning or full finalization timeout is null/error "
            f"(default: {_AUDIT_CACHE_WALL_SECONDS:g})"
        ),
    )
    audit.add_argument(
        "--gate",
        action="store_true",
        help=(
            "exit 1 when a DELETABLE slot, interrupted operation, or unregistered "
            "directory needs coordinator attention; exit 2 when an expired slot's "
            "evidence is unavailable; blocked live evidence is retained without a finding"
        ),
    )
    audit.set_defaults(handler=_cmd_audit)

    unpushed = subparsers.add_parser(
        "unpushed",
        description="report remote containment and two-readings evidence for every HEAD",
        help="diagnose unpublished or stale-after-rebase local tips",
    )
    unpushed.add_argument("--slot")
    unpushed.add_argument("--format", choices=("human", "json"), default="human")
    unpushed.set_defaults(handler=_cmd_unpushed)

    create = subparsers.add_parser(
        "create",
        help="create linked worktrees and register a slot",
        description=(
            "Create one new branch and linked Git worktree for each --repo, then durably register "
            "the slot, coordinator, and optional owner. Source repositories and configured "
            "remotes must already exist. create never reclaims or removes another slot."
        ),
        epilog=(
            "Each NAME must appear once in --repo and --branch. --start, --remote, --remote-url, "
            "and later Git evidence use the same NAME. The configured origin is used by default. "
            "When --remote-url is supplied, the selected remote must match it; otherwise its "
            "configured URL is recorded. Omit --owner-pid only when that owner will immediately "
            "run adopt. After the slot is registered, create runs scripts/setup-hooks.sh in each "
            "submodule initialized in the new checkouts whose Git configuration is private to "
            "the slot and sets no core.hooksPath yet, from that submodule's root, for at most "
            "60 seconds each; the outcome is "
            "printed as 'hooks:' lines (setup_hooks in --format json), and a failing installer "
            "is reported without failing or undoing the creation."
        ),
        formatter_class=_HelpFormatter,
    )
    create.add_argument("slot", help="new slot name, such as slot01")
    create.add_argument(
        "--slot-type",
        choices=SLOT_TYPES,
        required=True,
        help="agent preserves authored work before reclaim; validate never salvages",
    )
    create.add_argument(
        "--coordinator-authorized",
        action="store_true",
        required=True,
        help=(
            "confirm that the coordinator assigned this slot; an assigned agent may "
            "create it with its own --owner-pid"
        ),
    )
    create.add_argument("--agent", required=True, metavar="AGENT", help="registered agent name")
    create.add_argument(
        "--task", required=True, metavar="TASK", help="task or work-item identifier"
    )
    create.add_argument(
        "--purpose",
        required=True,
        metavar="TEXT",
        help="short human-readable reason for the slot",
    )
    create.add_argument(
        "--owner-pid",
        type=int,
        metavar="PID",
        help=(
            "live owner PID whose lifetime represents this one agent; do not use a "
            "shared multiplexing supervisor. The owner may be in this command's "
            "ancestry even when its assigned coordinator runs separately, or another "
            "child of the invoking coordinator; omit only when the coordinator creates "
            "the slot and the owner will immediately adopt"
        ),
    )
    create.add_argument(
        "--coordinator-pid",
        type=int,
        required=True,
        metavar="PID",
        help=(
            "live assigned coordinator PID; it must be an ancestor of this command "
            "unless the owner is in this command's ancestry"
        ),
    )
    _add_task_scope_options(create)
    _add_repo_options(create)
    create.add_argument(
        "--branch",
        action="append",
        metavar="NAME=BRANCH",
        help=(
            "new local branch for one checkout (required once per --repo for agent slots; "
            "validate slots generate private branches when omitted)"
        ),
    )
    create.add_argument(
        "--start",
        action="append",
        metavar="NAME=REF",
        help="start ref for one checkout (default: landed ref derived for its configured remote)",
    )
    create.add_argument(
        "--override-disk-floor",
        action="store_true",
        help="allow create below the provisioning floor, but never below the emergency floor",
    )
    create.add_argument(
        "--representation",
        choices=("config", *SLOT_REPRESENTATIONS),
        default="config",
        help=(
            "how this slot is stored: worktree (plain directories on the host), image (the "
            "slot directory is the mount point of one sparse ext4 disk image under "
            "<control>/slot-images/), or config (the configured slot_representation; "
            "default). The choice is recorded per slot and never changes lifecycle policy"
        ),
    )
    create.add_argument("--format", choices=("human", "json"), default="human")
    create.set_defaults(handler=_cmd_create)

    classify_create = subparsers.add_parser(
        "classify-create-journals",
        help="prove whether interrupted creates are unrelated to one new slot",
        description=(
            "Read and verify every outstanding create journal, its exact process "
            "generations, Git worktrees, and dirty state without taking a mutation lock "
            "or changing registry, journal, or checkout bytes. Missing, malformed, "
            "ambiguous, non-create, or overlapping state refuses."
        ),
        formatter_class=_HelpFormatter,
    )
    classify_create.add_argument("slot", help="prospective slot name")
    classify_create.add_argument("--slot-type", choices=SLOT_TYPES, required=True)
    classify_create.add_argument("--agent", required=True, metavar="AGENT")
    classify_create.add_argument(
        "--format", choices=("human", "json"), default="human"
    )
    classify_create.set_defaults(handler=_cmd_classify_create_journals)

    register = subparsers.add_parser(
        "register",
        help="register already-created live worktrees",
        description=(
            "Verify linked worktrees already present under the slot path and register their exact "
            "Git, coordinator, and owner identities. This command does not create or move paths. "
            "Use only while the owner is demonstrably live. The owner may be the invoking "
            "process or another child of the invoking coordinator whose working directory is "
            "inside the slot."
        ),
        formatter_class=_HelpFormatter,
    )
    register.add_argument("slot", help="existing managed slot name")
    register.add_argument(
        "--slot-type",
        choices=SLOT_TYPES,
        help="type recorded at registration; it controls whether reclaim must salvage",
    )
    register.add_argument(
        "--coordinator-authorized",
        action="store_true",
        help="confirm that the coordinator authorized this registration",
    )
    register.add_argument("--agent", required=True, metavar="AGENT", help="registered agent name")
    register.add_argument(
        "--task", required=True, metavar="TASK", help="task or work-item identifier"
    )
